// components/tabs.js — Phase 2 split (2026-05-02).
// All tab components. Loaded after ui.js. Read MINIAPP_PARITY.md §0.5 before
// editing — when adding a new tab, prefer this file over a per-tab file until
// it crosses ~4000 lines.
    // ─── Cultivation Tab ─────────────────────────────────────────────────────
    // ─── Breakthrough Modal (MA-29) ──────────────────────────────────────────
    // Translates a backend `reason` (gate/cooldown/error) into a user-facing
    // i18n string. Used both in modal banner and in toast on failure.
    // ⚠️ O ÚNICO leitor do portão nesta ficheiro. `ondaCultOn()` vive no
    // `ui.js` e é o dono da chave-mestra; aqui basta **um** ponto que o
    // chame e distribua o booleano — é o que a guarda do §19 conta, e é a
    // Lei 0 §2 aplicada a um ficheiro de 33.000 linhas: dois leitores da
    // mesma chave divergem sempre, e já divergiram nesta casa.
    function obraOn() {
      return typeof ondaCultOn === "function" && ondaCultOn();
    }

    function btReasonText(reason, extra) {
      switch (reason) {
        case "foundation_required":     return t("breakthrough_requirement_foundation");
        case "core_required":           return t("breakthrough_requirement_core");
        case "body_tempering_required": return t("breakthrough_requirement_body_tempering",
                                          { cur: extra?.current_level ?? 0, req: extra?.required_level ?? 3 });
        case "celestial_trial_required":return t("breakthrough_requirement_celestial_trial",
                                          { n: extra?.trial_num ?? 1 });
        case "tribulation_cooldown":    return t("breakthrough_tribulation_cooldown",
                                          { n: fmtDuration(extra?.cooldown_remaining_ms || 0) });
        case "not_eligible":            return t("breakthrough_ineligible");
        case "max_realm":               return t("breakthrough_max_realm");
        default:                        return reason || t("breakthrough_fail");
      }
    }

    function BreakthroughModal({ onClose, onResolved, onGateFoundation, onGateCore, onGateTrib, onGateCelestial }) {
      // phase: 'preview' (default) → 'charge' (1s) → 'flash' (0.4s) → 'reveal' (1.5s) → 'closed'
      // 'gated' shows the requirement banner with horizontal shake.
      const [phase, setPhase] = useState("preview");
      const [preview, setPreview] = useState(null);
      const [busy, setBusy] = useState(false);
      const [reveal, setReveal] = useState(null);
      const [errInfo, setErrInfo] = useState(null);

      useEffect(() => {
        let cancelled = false;
        (async () => {
          try {
            const res = await api("breakthrough/preview");
            if (!cancelled) setPreview(res);
          } catch (e) {
            if (!cancelled) setErrInfo({ reason: e.message });
          }
        })();
        return () => { cancelled = true; };
      }, []);

      async function attempt() {
        if (!preview || busy) return;
        setBusy(true);
        haptic("warning");
        try {
          const res = await api("breakthrough/attempt");
          if (!res.ok) {
            // v14.14a — auto-redirect to trial modal when engine gates on
            // foundation/core. Lei §1: jogador NUNCA preso sem caminho.
            if (res.reason === "foundation_required" && onGateFoundation) {
              haptic("warning");
              onGateFoundation();
              return;
            }
            if (res.reason === "core_required" && onGateCore) {
              haptic("warning");
              onGateCore();
              return;
            }
            // Hotfix "A Volta" 2026-07-07 (#6) — a Prova Celestial (R8) tinha o
            // MESMO dead-end que foundation/core já resolviam: banner estático
            // sem caminho (Lei §1). Redireciona para a tab Celestial.
            if (res.reason === "celestial_trial_required" && onGateCelestial) {
              haptic("warning");
              onGateCelestial();
              return;
            }
            // Sprint 8 — the engine paused for the Cerimónia-Semente. Fold the
            // disclosure into the preview so the footer flips to Consolidar/Forçar.
            if (res.reason === "ceremony_required") {
              haptic("warning");
              setPreview(p => p ? { ...p, ceremony: res.ceremony } : p);
              setBusy(false);
              return;
            }
            // Gate / cooldown / not_eligible.
            haptic("error");
            setErrInfo(res);
            setPhase("gated");
            setBusy(false);
            return;
          }
          if (res.type === "tribulation_pending") {
            // v15.1.x bug fix (2026-05-15): owner reported breakthrough
            // blocked the tribulation flow ("falta cultivacao"). Lei §1 —
            // when a tribulation is pending (created here OR by an earlier
            // tick), auto-open TribulationModal so the player has a path
            // forward without needing to leave the mini-app.
            haptic("warning");
            onResolved && onResolved(res);
            if (onGateTrib) {
              onGateTrib();
            } else {
              showToast(t("breakthrough_tribulation_pending"));
              onClose();
            }
            return;
          }
          // Success — run cinematic (charge → flash → reveal).
          setReveal(res);
          setPhase("charge");
          setTimeout(() => setPhase("flash"), 1000);
          setTimeout(() => setPhase("reveal"), 1400);
          setTimeout(() => {
            haptic("success");
            const msg = res.type === "realm_up"
              ? t("breakthrough_realm_up", { realm: res.new_realm_name })
              : t("breakthrough_sub_layer_up", { n: res.new_sub_layer });
            showToast(msg);
            onResolved && onResolved(res);
            onClose();
          }, 2900);
        } catch (e) {
          haptic("error");
          setErrInfo({ reason: e.message });
          setPhase("gated");
          setBusy(false);
        }
      }

      const blocked = preview && (preview.blockers?.length || preview.type === "none");
      const eligible = preview && preview.eligible && !blocked;
      const trialColor = reveal ? `var(--realm-${Math.min(reveal.new_realm || 0, 10)})` : "var(--gold2)";

      // Cinematic overlay (charge/flash/reveal). Sits above modal backdrop.
      function Cinematic() {
        if (phase === "preview" || phase === "gated") return null;
        const realmCol = trialColor;
        return (
          <div style={{
            position:"fixed", inset:0, zIndex:80,
            display:"grid", placeItems:"center",
            pointerEvents:"none",
            background: phase === "flash" ? "rgba(255,255,240,.94)" : "rgba(4,8,18,.85)",
            transition: phase === "flash" ? "background .3s" : "background .6s",
            animation: phase === "flash" ? "bt-shake-screen .35s linear" : "none",
          }}>
            {phase === "charge" && (
              <div style={{ position:"relative", width:160, height:160 }}>
                <div style={{
                  position:"absolute", inset:0, borderRadius:"50%",
                  background:`radial-gradient(circle, ${realmCol} 0%, rgba(255,255,255,.6) 60%, transparent 100%)`,
                  animation:"bt-charge 1s cubic-bezier(.4,0,.6,1) forwards",
                }} />
                {/* Qi convergence particles */}
                {Array.from({ length: 10 }).map((_, i) => {
                  const ox = (i % 2 ? 1 : -1) * (20 + (i % 5) * 8);
                  return (
                    <div key={i} style={{
                      position:"absolute", left:"50%", top:"100%",
                      width:6, height:6, borderRadius:"50%",
                      background: realmCol, boxShadow:`0 0 8px ${realmCol}`,
                      "--ox": `${ox}px`,
                      animation: `bt-particle-rise ${0.7 + (i % 4) * 0.1}s ease-out ${i * 0.05}s infinite`,
                    }} />
                  );
                })}
              </div>
            )}
            {phase === "reveal" && reveal && (
              <div style={{
                textAlign:"center", animation:"bt-reveal 1.5s cubic-bezier(.2,.8,.2,1) forwards",
              }}>
                <div style={{ fontSize:80, marginBottom:8, filter:`drop-shadow(0 0 22px ${realmCol})` }}>
                  {reveal.new_realm_emoji || "✦"}
                </div>
                <div style={{
                  fontFamily:"'Cinzel',serif", fontSize:28, fontWeight:700,
                  color:realmCol, letterSpacing:1.5,
                  textShadow:`0 0 24px ${realmCol}, 0 0 40px rgba(255,255,255,.3)`,
                }}>
                  {reveal.new_realm_name}
                </div>
                <div style={{ fontFamily:"'Cinzel',serif", fontSize:14, color:"var(--gold2)", marginTop:8, letterSpacing:1 }}>
                  {t("breakthrough_success")}
                </div>
                {/* Progressão Visível — the antes→depois panel: the "moment" made
                    visible (Poder de Combate / HP / Qi climbing in green). Only when
                    the server sent deltas (gated by progressao_visivel). */}
                {reveal.deltas && (
                  <div style={{ maxWidth:280, margin:"12px auto 0", textAlign:"left" }}>
                    <div style={{ fontSize:10, color:"var(--muted)", textTransform:"uppercase",
                                  letterSpacing:1, textAlign:"center", marginBottom:2 }}>
                      {t("vp_gains")}
                    </div>
                    <DeltaPanel deltas={reveal.deltas} />
                  </div>
                )}
              </div>
            )}
          </div>
        );
      }

      // Sprint 8 — resolve the Cerimónia-Semente (Consolidar / Forçar). Mirrors attempt()
      // but posts the choice; same cinematic on success. Forçar failure STILL advances
      // (Lei §1) — the toast just names the setback.
      async function resolveCeremony(choice) {
        if (!preview || busy) return;
        setBusy(true);
        haptic(choice === "forcar" ? "warning" : "light");
        try {
          const res = await api("breakthrough/ceremony", { choice });
          if (!res.ok) {
            haptic("error");
            setErrInfo(res);
            setPhase("gated");
            setBusy(false);
            return;
          }
          setReveal(res);
          setPhase("charge");
          setTimeout(() => setPhase("flash"), 1000);
          setTimeout(() => setPhase("reveal"), 1400);
          setTimeout(() => {
            const oc = res.ceremony_outcome || {};
            const msg = (choice === "forcar")
              ? (oc.success ? t("bt_done_forcar_win", { realm: res.new_realm_name })
                            : t("bt_done_forcar_setback", { realm: res.new_realm_name }))
              : t("bt_done_consolidar", { realm: res.new_realm_name });
            haptic(oc.success !== false ? "success" : "warning");
            showToast(msg);
            onResolved && onResolved(res);
            onClose();
          }, 2900);
        } catch (e) {
          haptic("error");
          setErrInfo({ reason: e.message });
          setPhase("gated");
          setBusy(false);
        }
      }

      // Backdrop click — only allowed on preview/gated phases (never mid-cinematic).
      const backdropClick = (phase === "preview" || phase === "gated") ? onClose : undefined;

      const realmFromName = preview ? `${preview.current_realm_emoji || ""} ${preview.current_realm_name || ""} ${preview.current_sub_layer}` : "";
      const realmToName = preview ? `${preview.next_realm_emoji || ""} ${preview.next_realm_name || ""} ${preview.next_sub_layer}` : "";

      // Hide the modal mid-cinematic so only the overlay shows.
      const modalOpen = phase === "preview" || phase === "gated";
      const cer = preview && preview.ceremony;
      const footer = preview ? (
        cer ? (
          // Sprint 8 — the Cerimónia-Semente choice. Consolidar (safe) is always
          // available; Forçar is disabled during a setback (Lei §1 — never stuck).
          <div style={{ display:"flex", gap:8 }}>
            <ActionBtn onClick={() => resolveCeremony("consolidar")} variant="primary"
                       style={{ flex:1 }} disabled={busy}>
              {t("bt_btn_consolidar")}
            </ActionBtn>
            <ActionBtn onClick={() => resolveCeremony("forcar")} variant="ghost"
                       style={{ flex:1 }} disabled={busy || !cer.force_available}>
              {t("bt_btn_forcar", { pct: Math.round((cer.force_chance || 0) * 100) })}
            </ActionBtn>
          </div>
        ) : (
          <div style={{ display:"flex", gap:8 }}>
            <ActionBtn onClick={onClose} variant="ghost" style={{ flex:1 }} disabled={busy}>
              {t("breakthrough_cancel")}
            </ActionBtn>
            <ActionBtn onClick={attempt} variant="primary"
                       style={{ flex:1.4 }}
                       disabled={!eligible || busy}>
              {t("breakthrough_attempt")}
            </ActionBtn>
          </div>
        )
      ) : null;

      return (
        <>
          {modalOpen && (
            <Modal
              onClose={backdropClick}
              allowBackdropClose={!!backdropClick}
              title={`⚡ ${t("breakthrough_modal_title")}`}
              accent="rgba(var(--gold2-rgb),.55)"
              maxWidth={360}
              cardStyle={{
                background:"linear-gradient(180deg,rgba(30,40,72,.95),rgba(var(--card-rgb),.99))",
                boxShadow:"0 20px 60px rgba(0,0,0,.7), 0 0 32px rgba(var(--gold2-rgb),.25)",
              }}
              shake={phase === "gated"}
              footer={footer}
            >
              {!preview && !errInfo && (
                <div style={{ padding:"22px 0", textAlign:"center", color:"var(--muted)", fontSize:12 }}>
                  <DotSpinner /><div style={{ marginTop:8 }}>{t("breakthrough_loading")}</div>
                </div>
              )}

              {preview && (
                <>
                  <div style={{
                    padding:"10px 12px",
                    background:"rgba(0,0,0,.3)", border:"1px dashed rgba(var(--gold2-rgb),.25)",
                    borderRadius:10, textAlign:"center",
                  }}>
                    <div style={{ fontSize:10, color:"var(--muted)", letterSpacing:1, textTransform:"uppercase" }}>
                      {preview.type === "realm_up" ? t("breakthrough_type_realm_up") : t("breakthrough_type_sub_layer")}
                    </div>
                    <div style={{ marginTop:6, fontSize:13, fontFamily:"'Cinzel',serif", color:"var(--gold2)" }}>
                      {t("breakthrough_from_to", { from: realmFromName, to: realmToName })}
                    </div>
                  </div>

                  <div style={{ marginTop:12, display:"grid", gap:6 }}>
                    <KVRow label={t("breakthrough_cb_cost")}
                           value={`${fmtNum(preview.cb_effective_threshold || preview.cb_threshold)} CB`} />
                    <KVRow label={t("breakthrough_qi_after")}
                           value={`${fmtNum(preview.qi_after)} / ${fmtNum(preview.qi_capacity_after)}`} />
                    <KVRow label={t("breakthrough_chance")}
                           value={`${preview.success_chance || 100}% (${t("breakthrough_chance_auto")})`} />
                    {preview.buff_active && (
                      <div style={{
                        marginTop:4, padding:"6px 10px", borderRadius:8,
                        background:"rgba(var(--jade-rgb),.1)", border:"1px solid rgba(var(--jade-rgb),.3)",
                        fontSize:11, color:"var(--jade)", textAlign:"center",
                      }}>{t("breakthrough_buff_active", { n: preview.buff_value?.toFixed(1) || "1.0" })}</div>
                    )}
                    {preview.needs_tribulation && (
                      <div style={{
                        marginTop:4, padding:"6px 10px", borderRadius:8,
                        background:"rgba(var(--warn-rgb),.12)", border:"1px solid rgba(var(--warn-rgb),.35)",
                        fontSize:11, color:"var(--warn)", textAlign:"center",
                      }}>{t("breakthrough_tribulation_warning")}</div>
                    )}
                  </div>

                  {preview.ceremony && (
                    <div style={{ marginTop:10, padding:"8px 10px", borderRadius:8,
                                  background:"rgba(var(--gold2-rgb),.08)", border:"1px solid rgba(var(--gold2-rgb),.3)",
                                  fontSize:11, color:"var(--text)", lineHeight:1.5 }}>
                      <div style={{ marginBottom:4 }}>{t("bt_ceremony_intro")}</div>
                      {preview.ceremony.body_gap > 0 && (
                        <div style={{ color:"var(--warn)" }}>{t("bt_ceremony_gap", { gap: preview.ceremony.body_gap })}</div>
                      )}
                      {preview.ceremony.has_insight && (
                        <div style={{ color:"var(--jade)" }}>{t("bt_ceremony_insight")}</div>
                      )}
                      {preview.ceremony.force_available
                        ? <div style={{ color:"var(--muted)", marginTop:2 }}>{t("bt_ceremony_force_odds", { pct: Math.round((preview.ceremony.force_chance || 0) * 100) })}</div>
                        : <div style={{ color:"var(--muted)", marginTop:2 }}>{t("bt_ceremony_setback", { mins: Math.max(1, Math.floor((preview.ceremony.setback_remaining || 0) / 60)) })}</div>}
                    </div>
                  )}

                  {(preview.blockers || []).map((b, i) => (
                    <div key={i} className="err-banner" style={{ marginTop:10 }}>
                      {btReasonText(b.key, b)}
                      {b.key === "celestial_trial_required" && onGateCelestial && (
                        <ActionBtn variant="primary" style={{ marginTop:8 }}
                                   onClick={() => { haptic("select"); onGateCelestial(); }}>
                          {t("bt_goto_celestial")}
                        </ActionBtn>
                      )}
                    </div>
                  ))}
                  {phase === "gated" && errInfo && (
                    <div className="err-banner" style={{ marginTop:10 }}>
                      {btReasonText(errInfo.reason, errInfo)}
                    </div>
                  )}
                </>
              )}

              {errInfo && !preview && (
                <div className="err-banner">
                  {btReasonText(errInfo.reason, errInfo)}
                </div>
              )}
            </Modal>
          )}
          <Cinematic />
        </>
      );
    }

    // Tiny KV row used inside BreakthroughModal — keeps preview compact.
    function KVRow({ label, value }) {
      return (
        <div style={{ display:"flex", justifyContent:"space-between", padding:"4px 2px", fontSize:12 }}>
          <span style={{ color:"var(--muted)" }}>{label}</span>
          <b style={{ color:"var(--gold2)" }}>{value}</b>
        </div>
      );
    }

    // ─── Foundation Trial Modal (v14.14a) ────────────────────────────────────
    // Surfaces handlers/cultivation.py:foundation_start_callback +
    // foundation_confirm_callback in the mini-app. Reaches the player when:
    //  - Auto-open: BreakthroughModal returned reason === "foundation_required"
    //    (Cultivation tab catches that and opens this modal).
    //  - Manual: trial-pending card on CultivationTab when foundation_locked.
    //
    // 3 phases: preview → cinematic (charge + flash + reveal) → done.
    // Quality colour glow mirrors the chat `foundation_art` rendering.
    function FoundationTrialModal({ onClose, onResolved }) {
      const [phase, setPhase] = useState("preview"); // preview|charge|flash|reveal|done
      const [data, setData] = useState(null);
      const [busy, setBusy] = useState(false);
      const [reveal, setReveal] = useState(null);
      const [errInfo, setErrInfo] = useState(null);

      useEffect(() => {
        let cancelled = false;
        (async () => {
          try {
            const res = await api("foundation/status");
            if (!cancelled) setData(res);
          } catch (e) {
            if (!cancelled) setErrInfo({ reason: e.message });
          }
        })();
        return () => { cancelled = true; };
      }, []);

      async function attempt() {
        if (!data || busy) return;
        setBusy(true);
        haptic("warning");
        try {
          const res = await api("foundation/attempt");
          if (!res.ok) {
            haptic("error");
            setErrInfo(res);
            setBusy(false);
            return;
          }
          setReveal(res);
          setPhase("charge");
          setTimeout(() => setPhase("flash"), 1000);
          setTimeout(() => setPhase("reveal"), 1400);
          setTimeout(() => {
            haptic("success");
            setPhase("done");
            setBusy(false);
            onResolved && onResolved(res);
          }, 2900);
        } catch (e) {
          haptic("error");
          setErrInfo({ reason: e.message });
          setBusy(false);
        }
      }

      // ── Quality colour palette mirrors chat foundation_art ──
      const QUALITY_COLOUR = {
        low:     "var(--realm-0)",
        medium:  "var(--realm-2)",
        high:    "#22d3ee",
        perfect: "var(--realm-10)",
        sacred:  "var(--gold3)",
      };
      const trialColour = reveal ? (QUALITY_COLOUR[reveal.quality] || "var(--gold2)") : "var(--gold2)";

      function Cinematic() {
        if (phase !== "charge" && phase !== "flash" && phase !== "reveal") return null;
        return (
          <div style={{
            position:"fixed", inset:0, zIndex:80,
            display:"grid", placeItems:"center", pointerEvents:"none",
            background: phase === "flash" ? "rgba(255,255,240,.94)" : "rgba(4,8,18,.85)",
            transition: phase === "flash" ? "background .3s" : "background .6s",
            animation: phase === "flash" ? "bt-shake-screen .35s linear" : "none",
          }}>
            {phase === "charge" && (
              <div style={{ position:"relative", width:160, height:160 }}>
                <div style={{
                  position:"absolute", inset:0, borderRadius:"50%",
                  background:`radial-gradient(circle, ${trialColour} 0%, rgba(255,255,255,.6) 60%, transparent 100%)`,
                  animation:"bt-charge 1s cubic-bezier(.4,0,.6,1) forwards",
                }} />
                {Array.from({ length: 10 }).map((_, i) => {
                  const ox = (i % 2 ? 1 : -1) * (20 + (i % 5) * 8);
                  return (
                    <div key={i} style={{
                      position:"absolute", left:"50%", top:"100%",
                      width:6, height:6, borderRadius:"50%",
                      background: trialColour, boxShadow:`0 0 8px ${trialColour}`,
                      "--ox": `${ox}px`,
                      animation: `bt-particle-rise ${0.7 + (i % 4) * 0.1}s ease-out ${i * 0.05}s infinite`,
                    }} />
                  );
                })}
              </div>
            )}
            {phase === "reveal" && reveal && (
              <div style={{ textAlign:"center", animation:"bt-reveal 1.5s cubic-bezier(.2,.8,.2,1) forwards" }}>
                <div style={{ fontSize:80, marginBottom:8, filter:`drop-shadow(0 0 22px ${trialColour})` }}>
                  {reveal.emoji || "🏯"}
                </div>
                <div style={{
                  fontFamily:"'Cinzel',serif", fontSize:28, fontWeight:700,
                  color:trialColour, letterSpacing:1.5,
                  textShadow:`0 0 24px ${trialColour}, 0 0 40px rgba(255,255,255,.3)`,
                }}>
                  {safeT(reveal.quality_label_key, null, reveal.quality)}
                </div>
                <div style={{ fontFamily:"'Cinzel',serif", fontSize:14, color:"var(--gold2)", marginTop:8, letterSpacing:1 }}>
                  {t("foundation_trial_title").replace(/\*/g, "")}
                </div>
              </div>
            )}
          </div>
        );
      }

      const isCine = phase === "charge" || phase === "flash" || phase === "reveal";
      const modalOpen = !isCine;
      const fp = data?.foundation_preview;

      const footer = phase === "done"
        ? (
            <ActionBtn onClick={onClose} variant="primary" style={{ width:"100%" }}>
              {t("foundation_close")}
            </ActionBtn>
          )
        : phase === "preview" && data && data.foundation_locked
        ? (
            <div style={{ display:"flex", gap:8 }}>
              <ActionBtn onClick={onClose} variant="ghost" style={{ flex:1 }} disabled={busy}>
                {t("foundation_cancel")}
              </ActionBtn>
              <ActionBtn onClick={attempt} variant="primary" style={{ flex:1.4 }} disabled={busy}>
                {t("btn_foundation_start").replace(/\*/g, "")}
              </ActionBtn>
            </div>
          )
        : null;

      return (
        <>
          {modalOpen && (
            <Modal
              onClose={(phase === "preview" || phase === "done") ? onClose : undefined}
              allowBackdropClose={phase === "preview" || phase === "done"}
              title={`🏯 ${t("foundation_modal_title")}`}
              accent="rgba(var(--gold2-rgb),.55)"
              maxWidth={380}
              cardStyle={{
                background:"linear-gradient(180deg,rgba(30,40,72,.95),rgba(var(--card-rgb),.99))",
                boxShadow:"0 20px 60px rgba(0,0,0,.7), 0 0 32px rgba(var(--gold2-rgb),.25)",
              }}
              footer={footer}
            >
              {!data && !errInfo && (
                <div style={{ padding:"22px 0", textAlign:"center", color:"var(--muted)", fontSize:12 }}>
                  <DotSpinner /><div style={{ marginTop:8 }}>{t("foundation_loading")}</div>
                </div>
              )}

              {data && !data.foundation_locked && phase !== "done" && (
                <div style={{ padding:"14px 4px", textAlign:"center", fontSize:13, color:"var(--muted)" }}>
                  {t("foundation_not_eligible")}
                </div>
              )}

              {data && data.foundation_locked && phase === "preview" && fp && (
                <>
                  <div style={{
                    padding:"10px 12px", marginBottom:10,
                    background:"rgba(0,0,0,.3)", border:"1px dashed rgba(var(--gold2-rgb),.25)",
                    borderRadius:10, fontSize:12, color:"var(--text)", lineHeight:1.5,
                  }}>
                    {t("foundation_trial_intro").replace(/\*/g, "")}
                  </div>

                  <div style={{
                    marginTop:8, fontSize:11, color:"var(--gold2)",
                    fontFamily:"'Cinzel',serif", letterSpacing:1, textTransform:"uppercase",
                  }}>
                    {t("foundation_chances_title").replace(/[\n📊*]/g, "").trim()}
                  </div>

                  <div style={{ marginTop:8, display:"grid", gap:6 }}>
                    <KVRow
                      label={`👻 ${t("soul")}`}
                      value={`${fp.current.soul}/${fp.thresholds.soul} ${fp.ready.soul ? "✅" : "❌"}`}
                    />
                    <KVRow
                      label={`👁️ ${t("perception")}`}
                      value={`${fp.current.perception}/${fp.thresholds.perception} ${fp.ready.perception ? "✅" : "❌"}`}
                    />
                    <KVRow
                      label={`🍀 ${t("luck")}`}
                      value={`${fp.current.luck} → ${fp.luck_chance_pct}%`}
                    />
                  </div>

                  {fp.luck_chance_pct < 100 && (
                    <div style={{
                      marginTop:10, padding:"6px 10px", borderRadius:8,
                      background:"rgba(var(--warn-rgb),.12)", border:"1px solid rgba(var(--warn-rgb),.35)",
                      fontSize:11, color:"var(--warn)", lineHeight:1.45,
                    }}>
                      {t("foundation_luck_tip").replace(/\*/g, "")}
                    </div>
                  )}

                  {errInfo && (
                    <div className="err-banner" style={{ marginTop:10 }}>
                      {errInfo.reason || t("foundation_fail")}
                    </div>
                  )}
                </>
              )}

              {phase === "done" && reveal && (
                <div style={{ textAlign:"center" }}>
                  <div style={{ fontSize:60, marginBottom:8, filter:`drop-shadow(0 0 18px ${trialColour})` }}>
                    {reveal.emoji || "🏯"}
                  </div>
                  <div style={{
                    fontFamily:"'Cinzel',serif", fontSize:20, fontWeight:700,
                    color:trialColour, letterSpacing:1.2, marginBottom:10,
                  }}>
                    {safeT(reveal.quality_label_key, null, reveal.quality)}
                  </div>
                  <div style={{
                    padding:"10px 12px",
                    background:"rgba(0,0,0,.3)", border:"1px solid rgba(var(--gold2-rgb),.2)",
                    borderRadius:10, fontSize:12, color:"var(--text)", lineHeight:1.55, textAlign:"left",
                  }}>
                    {(reveal.results || []).map((r, i) => {
                      const key = `foundation_trial_${r.trial}_${r.passed ? "pass" : "fail"}`;
                      return <div key={i}>{safeT(key, null, "").replace(/\*/g, "")}</div>;
                    })}
                    <div style={{ marginTop:10, fontWeight:700, color:trialColour }}>
                      {safeT(`foundation_result_${reveal.quality}`, null, "").replace(/\*/g, "")}
                    </div>
                  </div>
                </div>
              )}
            </Modal>
          )}
          <Cinematic />
        </>
      );
    }

    // ─── Core Formation Modal (v14.14a) ──────────────────────────────────────
    // Surfaces handlers/cultivation.py:core_formation_start_callback +
    // core_form_confirm_callback. Reaches the player when:
    //  - Auto-open: BreakthroughModal returned reason === "core_required".
    //  - Manual: trial-pending card on CultivationTab when core_locked.
    // Quality is determined by core_essence already accumulated — modal
    // surfaces predicted quality and lets the player decide between form-now
    // (permanent) or wait-for-more-essence.
    function CoreFormationModal({ onClose, onResolved }) {
      const [phase, setPhase] = useState("preview");
      const [data, setData] = useState(null);
      const [busy, setBusy] = useState(false);
      const [reveal, setReveal] = useState(null);
      const [errInfo, setErrInfo] = useState(null);

      useEffect(() => {
        let cancelled = false;
        (async () => {
          try {
            const res = await api("foundation/status");
            if (!cancelled) setData(res);
          } catch (e) {
            if (!cancelled) setErrInfo({ reason: e.message });
          }
        })();
        return () => { cancelled = true; };
      }, []);

      async function attempt() {
        if (!data || busy) return;
        setBusy(true);
        haptic("warning");
        try {
          const res = await api("core/attempt");
          if (!res.ok) {
            haptic("error");
            setErrInfo(res);
            setBusy(false);
            return;
          }
          setReveal(res);
          setPhase("charge");
          setTimeout(() => setPhase("flash"), 1000);
          setTimeout(() => setPhase("reveal"), 1400);
          setTimeout(() => {
            haptic("success");
            setPhase("done");
            setBusy(false);
            onResolved && onResolved(res);
          }, 2900);
        } catch (e) {
          haptic("error");
          setErrInfo({ reason: e.message });
          setBusy(false);
        }
      }

      const QUALITY_COLOUR = {
        flawed:   "var(--realm-0)",
        normal:   "var(--realm-1)",
        superior: "var(--realm-3)",
        perfect:  "var(--gold3)",
      };
      const trialColour = reveal ? (QUALITY_COLOUR[reveal.quality] || "var(--gold2)") : "var(--gold2)";

      function Cinematic() {
        if (phase !== "charge" && phase !== "flash" && phase !== "reveal") return null;
        return (
          <div style={{
            position:"fixed", inset:0, zIndex:80,
            display:"grid", placeItems:"center", pointerEvents:"none",
            background: phase === "flash" ? "rgba(255,255,240,.94)" : "rgba(4,8,18,.85)",
            transition: phase === "flash" ? "background .3s" : "background .6s",
            animation: phase === "flash" ? "bt-shake-screen .35s linear" : "none",
          }}>
            {phase === "charge" && (
              <div style={{ position:"relative", width:160, height:160 }}>
                <div style={{
                  position:"absolute", inset:0, borderRadius:"50%",
                  background:`radial-gradient(circle, ${trialColour} 0%, rgba(255,255,255,.6) 60%, transparent 100%)`,
                  animation:"bt-charge 1s cubic-bezier(.4,0,.6,1) forwards",
                }} />
              </div>
            )}
            {phase === "reveal" && reveal && (
              <div style={{ textAlign:"center", animation:"bt-reveal 1.5s cubic-bezier(.2,.8,.2,1) forwards" }}>
                <div style={{ fontSize:80, marginBottom:8, filter:`drop-shadow(0 0 22px ${trialColour})` }}>
                  {reveal.emoji || "🔮"}
                </div>
                <div style={{
                  fontFamily:"'Cinzel',serif", fontSize:28, fontWeight:700,
                  color:trialColour, letterSpacing:1.5,
                  textShadow:`0 0 24px ${trialColour}, 0 0 40px rgba(255,255,255,.3)`,
                }}>
                  {safeT(reveal.quality_label_key, null, reveal.quality)}
                </div>
                <div style={{ fontFamily:"'Cinzel',serif", fontSize:14, color:"var(--gold2)", marginTop:8, letterSpacing:1 }}>
                  {t("core_modal_title")}
                </div>
              </div>
            )}
          </div>
        );
      }

      const isCine = phase === "charge" || phase === "flash" || phase === "reveal";
      const modalOpen = !isCine;
      const cp = data?.core_preview;

      const footer = phase === "done"
        ? (
            <ActionBtn onClick={onClose} variant="primary" style={{ width:"100%" }}>
              {t("foundation_close")}
            </ActionBtn>
          )
        : phase === "preview" && data && data.core_locked
        ? (
            <div style={{ display:"flex", gap:8 }}>
              <ActionBtn onClick={onClose} variant="ghost" style={{ flex:1 }} disabled={busy}>
                {t("btn_core_wait").replace(/[⏳]/g, "").trim() || t("foundation_cancel")}
              </ActionBtn>
              <ActionBtn onClick={attempt} variant="primary" style={{ flex:1.4 }} disabled={busy}>
                {t("btn_core_form").replace(/\*/g, "")}
              </ActionBtn>
            </div>
          )
        : null;

      return (
        <>
          {modalOpen && (
            <Modal
              onClose={(phase === "preview" || phase === "done") ? onClose : undefined}
              allowBackdropClose={phase === "preview" || phase === "done"}
              title={`🔮 ${t("core_modal_title")}`}
              accent="rgba(var(--realm-3-rgb),.55)"
              maxWidth={380}
              cardStyle={{
                background:"linear-gradient(180deg,rgba(30,40,72,.95),rgba(var(--card-rgb),.99))",
                boxShadow:"0 20px 60px rgba(0,0,0,.7), 0 0 32px rgba(var(--realm-3-rgb),.25)",
              }}
              footer={footer}
            >
              {!data && !errInfo && (
                <div style={{ padding:"22px 0", textAlign:"center", color:"var(--muted)", fontSize:12 }}>
                  <DotSpinner /><div style={{ marginTop:8 }}>{t("foundation_loading")}</div>
                </div>
              )}

              {data && !data.core_locked && phase !== "done" && (
                <div style={{ padding:"14px 4px", textAlign:"center", fontSize:13, color:"var(--muted)" }}>
                  {t("core_not_eligible")}
                </div>
              )}

              {data && data.core_locked && phase === "preview" && cp && (
                <>
                  <div style={{
                    padding:"10px 12px", marginBottom:10,
                    background:"rgba(0,0,0,.3)", border:"1px dashed rgba(var(--realm-3-rgb),.25)",
                    borderRadius:10, fontSize:12, color:"var(--text)", lineHeight:1.5,
                  }}>
                    {t("core_intro_simple")}
                  </div>

                  <div style={{ display:"grid", gap:6, marginBottom:10 }}>
                    <KVRow label={`💠 ${t("core_essence_label")}`} value={`${cp.essence} / ${cp.essence_cap}`} />
                    <KVRow label={`🏯 ${t("foundation_label")}`} value={safeT(cp.foundation_label_key, null, cp.foundation)} />
                    <KVRow label={`⚖️ ${t("core_max_label")}`} value={safeT(cp.max_core_label_key, null, cp.max_core)} />
                    <KVRow
                      label={`🔮 ${t("core_predicted_label")}`}
                      value={`${cp.predicted_emoji || ""} ${safeT(cp.predicted_label_key, null, cp.predicted)}`}
                    />
                  </div>

                  {cp.was_capped && (
                    <div style={{
                      marginBottom:10, padding:"6px 10px", borderRadius:8,
                      background:"rgba(var(--warn-rgb),.12)", border:"1px solid rgba(var(--warn-rgb),.35)",
                      fontSize:11, color:"var(--warn)", lineHeight:1.45,
                    }}>
                      {t("core_capped_warning", {
                        foundation: safeT(cp.foundation_label_key, null, cp.foundation),
                        max_core: safeT(cp.max_core_label_key, null, cp.max_core),
                      }).replace(/\*/g, "")}
                    </div>
                  )}

                  <div style={{
                    padding:"6px 10px", borderRadius:8,
                    background:"rgba(var(--red-rgb),.10)", border:"1px solid rgba(var(--red-rgb),.30)",
                    fontSize:11, color:"var(--red)", lineHeight:1.45,
                  }}>
                    {t("core_permanent_warning")}
                  </div>

                  {errInfo && (
                    <div className="err-banner" style={{ marginTop:10 }}>
                      {errInfo.reason || t("foundation_fail")}
                    </div>
                  )}
                </>
              )}

              {phase === "done" && reveal && (
                <div style={{ textAlign:"center" }}>
                  <div style={{ fontSize:60, marginBottom:8, filter:`drop-shadow(0 0 18px ${trialColour})` }}>
                    {reveal.emoji || "🔮"}
                  </div>
                  <div style={{
                    fontFamily:"'Cinzel',serif", fontSize:20, fontWeight:700,
                    color:trialColour, letterSpacing:1.2, marginBottom:10,
                  }}>
                    {safeT(reveal.quality_label_key, null, reveal.quality)}
                  </div>
                  <div style={{
                    padding:"10px 12px",
                    background:"rgba(0,0,0,.3)", border:"1px solid rgba(var(--realm-3-rgb),.2)",
                    borderRadius:10, fontSize:12, color:"var(--text)", lineHeight:1.55, textAlign:"left",
                  }}>
                    <div>{safeT(`core_result_${reveal.quality}`, null, "").replace(/\*/g, "")}</div>
                    {reveal.was_capped && (
                      <div style={{ marginTop:8, color:"var(--warn)" }}>
                        {t("core_capped_warning", {
                          foundation: safeT(reveal.foundation_label_key, null, reveal.foundation),
                          max_core: safeT(reveal.max_core_label_key, null, reveal.max_allowed),
                        }).replace(/\*/g, "")}
                      </div>
                    )}
                  </div>
                </div>
              )}
            </Modal>
          )}
          <Cinematic />
        </>
      );
    }

    // ─── Recomeço Modal (v14.14b — D-1a Newbie Grace) ────────────────────────
    // Mirrors handlers/foundation.py:recomeco_command + recomeco_confirm_callback.
    // One-shot reroll for newbies (realm ≤2 OR ≤7 days). Uses uniform-weighted
    // pick on foundation_quality (40/35/20/5) + spirit_root (excludes Low).
    function RecomecoModal({ onClose, onResolved }) {
      const [phase, setPhase] = useState("preview"); // preview|cine|done
      const [data, setData] = useState(null);
      const [busy, setBusy] = useState(false);
      const [result, setResult] = useState(null);
      const [errInfo, setErrInfo] = useState(null);

      useEffect(() => {
        let cancelled = false;
        (async () => {
          try {
            const res = await api("foundation/recomeco/preview");
            if (!cancelled) setData(res);
          } catch (e) {
            if (!cancelled) setErrInfo({ reason: e.message });
          }
        })();
        return () => { cancelled = true; };
      }, []);

      async function confirm() {
        if (busy) return;
        setBusy(true);
        haptic("warning");
        try {
          const res = await api("foundation/recomeco/execute");
          if (!res.ok) {
            haptic("error");
            setErrInfo(res);
            setBusy(false);
            return;
          }
          setResult(res);
          setPhase("cine");
          setTimeout(() => {
            haptic("success");
            setPhase("done");
            setBusy(false);
            onResolved && onResolved(res);
          }, 1800);
        } catch (e) {
          haptic("error");
          setErrInfo({ reason: e.message });
          setBusy(false);
        }
      }

      const isCine = phase === "cine";
      const modalOpen = !isCine;
      const eligible = data && data.eligible;

      const footer = phase === "done"
        ? (
            <ActionBtn onClick={onClose} variant="primary" style={{ width:"100%" }}>
              {t("foundation_close")}
            </ActionBtn>
          )
        : phase === "preview" && eligible
        ? (
            <div style={{ display:"flex", gap:8 }}>
              <ActionBtn onClick={onClose} variant="ghost" style={{ flex:1 }} disabled={busy}>
                {t("recomeco_btn_cancel").replace(/[❌]/g, "").trim()}
              </ActionBtn>
              <ActionBtn onClick={confirm} variant="primary" style={{ flex:1.6 }} disabled={busy}>
                {t("recomeco_btn_confirm").replace(/[🌱]/g, "").trim()}
              </ActionBtn>
            </div>
          )
        : phase === "preview" && data
        ? (
            <ActionBtn onClick={onClose} variant="ghost" style={{ width:"100%" }}>
              {t("foundation_close")}
            </ActionBtn>
          )
        : null;

      return (
        <>
          {modalOpen && (
            <Modal
              onClose={(phase === "preview" || phase === "done") ? onClose : undefined}
              allowBackdropClose={phase === "preview" || phase === "done"}
              title={`🌱 ${t("recomeco_modal_title")}`}
              accent="rgba(34,211,238,.5)"
              maxWidth={380}
              cardStyle={{
                background:"linear-gradient(180deg,rgba(20,40,60,.95),rgba(8,18,30,.99))",
                boxShadow:"0 20px 60px rgba(0,0,0,.7), 0 0 32px rgba(34,211,238,.18)",
              }}
              footer={footer}
            >
              {!data && !errInfo && (
                <div style={{ padding:"22px 0", textAlign:"center", color:"var(--muted)", fontSize:12 }}>
                  <DotSpinner /><div style={{ marginTop:8 }}>{t("foundation_loading")}</div>
                </div>
              )}

              {data && !eligible && phase === "preview" && (
                <div style={{
                  padding:"10px 12px", marginBottom:10,
                  background:"rgba(var(--warn-rgb),.1)", border:"1px solid rgba(var(--warn-rgb),.3)",
                  borderRadius:10, fontSize:12, color:"var(--warn)", lineHeight:1.5,
                }}>
                  {data.reason === "recomeco_err_already_used"
                    ? t("recomeco_err_already_used").replace(/\*/g, "")
                    : t("recomeco_err_realm_too_high", {
                        realm: data.realm,
                        days: data.max_age_days,
                      }).replace(/\*/g, "")}
                </div>
              )}

              {data && eligible && phase === "preview" && (
                <>
                  <div style={{
                    padding:"10px 12px", marginBottom:10,
                    background:"rgba(0,0,0,.3)", border:"1px dashed rgba(34,211,238,.25)",
                    borderRadius:10, fontSize:12, color:"var(--text)", lineHeight:1.55,
                  }}>
                    {t("recomeco_intro_short")}
                  </div>

                  <div style={{ display:"grid", gap:6, marginBottom:10 }}>
                    <KVRow
                      label={`🏯 ${t("foundation_label")}`}
                      value={data.foundation_quality
                        ? safeT(`foundation_quality_${data.foundation_quality}`, null, data.foundation_quality)
                        : t("recomeco_foundation_none").replace(/[—()]/g, "").trim()}
                    />
                    <KVRow
                      label={`🌱 ${t("recomeco_root_label")}`}
                      value={`${data.spirit_root_emoji || ""} ${data.spirit_root || "—"}`}
                    />
                  </div>

                  <div style={{
                    padding:"6px 10px", borderRadius:8,
                    background:"rgba(var(--red-rgb),.10)", border:"1px solid rgba(var(--red-rgb),.30)",
                    fontSize:11, color:"var(--red)", lineHeight:1.45,
                  }}>
                    {t("recomeco_one_shot_warning")}
                  </div>

                  {errInfo && (
                    <div className="err-banner" style={{ marginTop:10 }}>
                      {errInfo.reason || t("foundation_fail")}
                    </div>
                  )}
                </>
              )}

              {phase === "done" && result && (
                <div>
                  <div style={{ textAlign:"center", marginBottom:14 }}>
                    <div style={{ fontSize:54, marginBottom:6,
                                  filter:"drop-shadow(0 0 18px rgba(34,211,238,.55))" }}>🌱</div>
                    <div style={{ fontFamily:"'Cinzel',serif", fontSize:18, fontWeight:700,
                                  color:"var(--gold2)", letterSpacing:1.2 }}>
                      {t("recomeco_done_title")}
                    </div>
                  </div>
                  <div style={{ display:"grid", gap:8 }}>
                    <div style={{
                      padding:"8px 10px", borderRadius:8,
                      background:"rgba(0,0,0,.25)", border:"1px solid rgba(34,211,238,.2)",
                      fontSize:12, color:"var(--text)",
                    }}>
                      <div style={{ fontSize:10, color:"var(--muted)", marginBottom:3, textTransform:"uppercase", letterSpacing:.5 }}>
                        {t("foundation_label")}
                      </div>
                      <span style={{ color:"var(--muted)" }}>
                        {result.old_foundation_label_key
                          ? safeT(result.old_foundation_label_key, null, result.old_foundation || "—")
                          : "—"}
                      </span>
                      <span style={{ margin:"0 8px", color:"var(--gold2)" }}>→</span>
                      <b style={{ color:"var(--jade)" }}>
                        {safeT(result.new_foundation_label_key, null, result.new_foundation)}
                      </b>
                    </div>
                    <div style={{
                      padding:"8px 10px", borderRadius:8,
                      background:"rgba(0,0,0,.25)", border:"1px solid rgba(34,211,238,.2)",
                      fontSize:12, color:"var(--text)",
                    }}>
                      <div style={{ fontSize:10, color:"var(--muted)", marginBottom:3, textTransform:"uppercase", letterSpacing:.5 }}>
                        {t("recomeco_root_label")}
                      </div>
                      <span style={{ color:"var(--muted)" }}>
                        {result.old_spirit_root_emoji} {result.old_spirit_root}
                      </span>
                      <span style={{ margin:"0 8px", color:"var(--gold2)" }}>→</span>
                      <b style={{ color:"var(--jade)" }}>
                        {result.new_spirit_root_emoji} {result.new_spirit_root}
                      </b>
                    </div>
                  </div>
                </div>
              )}
            </Modal>
          )}
          {isCine && (
            <div style={{
              position:"fixed", inset:0, zIndex:80,
              display:"grid", placeItems:"center", pointerEvents:"none",
              background:"rgba(8,18,30,.92)",
            }}>
              <div style={{ position:"relative", width:160, height:160 }}>
                <div style={{
                  position:"absolute", inset:0, borderRadius:"50%",
                  background:"radial-gradient(circle, #22d3ee 0%, rgba(255,255,255,.6) 60%, transparent 100%)",
                  animation:"bt-charge 1s cubic-bezier(.4,0,.6,1) forwards",
                }} />
              </div>
            </div>
          )}
        </>
      );
    }

    // ─── Quebrar Fundação Modal (v14.14b — D-1b Mid-game Ritual) ──────────────
    // Mirrors handlers/foundation.py:quebrar_fundacao_command + break_begin +
    // break_answer_callback. Multi-step: intro → Q1 → Q2 → Q3 → confirm cost →
    // server execute → cinematic shatter → reveal.
    // 3 perguntas filosóficas: Renúncia/Aceitação, Velocidade/Profundidade,
    // Manter/Novo. Element match determines score 0..3. Costs charged on
    // execute (irreversible).
    function QuebrarFundacaoModal({ onClose, onResolved }) {
      const [phase, setPhase] = useState("preview"); // preview|q1|q2|q3|cine|done
      const [data, setData] = useState(null);
      const [answers, setAnswers] = useState({}); // {1:str, 2:str, 3:str}
      const [busy, setBusy] = useState(false);
      const [result, setResult] = useState(null);
      const [errInfo, setErrInfo] = useState(null);

      useEffect(() => {
        let cancelled = false;
        (async () => {
          try {
            const res = await api("foundation/break/preview");
            if (!cancelled) setData(res);
          } catch (e) {
            if (!cancelled) setErrInfo({ reason: e.message });
          }
        })();
        return () => { cancelled = true; };
      }, []);

      function pickAnswer(qNum, answer) {
        haptic("select");
        setAnswers(prev => ({ ...prev, [qNum]: answer }));
        if (qNum < 3) {
          setPhase("q" + (qNum + 1));
        } else {
          setPhase("confirm");
        }
      }

      async function execute() {
        if (busy) return;
        setBusy(true);
        haptic("warning");
        try {
          const res = await api("foundation/break/execute", {
            answers: [answers[1], answers[2], answers[3]],
          });
          if (!res.ok) {
            haptic("error");
            setErrInfo(res);
            setBusy(false);
            setPhase("preview");
            return;
          }
          setResult(res);
          setPhase("cine");
          setTimeout(() => {
            haptic("success");
            setPhase("done");
            setBusy(false);
            onResolved && onResolved(res);
          }, 2400);
        } catch (e) {
          haptic("error");
          setErrInfo({ reason: e.message });
          setBusy(false);
        }
      }

      const isCine = phase === "cine";
      const modalOpen = !isCine;

      // Hint chip rendering — server tells us which answers match the player's
      // path. We render a subtle gold sparkle on those (lei §1 transparency).
      const correct = data?.correct_answers || {};

      const footer = phase === "done"
        ? (
            <ActionBtn onClick={onClose} variant="primary" style={{ width:"100%" }}>
              {t("foundation_close")}
            </ActionBtn>
          )
        : phase === "preview" && data && data.eligible
        ? (
            <div style={{ display:"flex", gap:8 }}>
              <ActionBtn onClick={onClose} variant="ghost" style={{ flex:1 }}>
                {t("break_btn_cancel").replace(/[❌]/g, "").trim()}
              </ActionBtn>
              <ActionBtn onClick={() => { haptic("warning"); setPhase("q1"); }} variant="primary" style={{ flex:1.6 }}>
                {t("break_btn_begin").replace(/[🔥]/g, "").trim()}
              </ActionBtn>
            </div>
          )
        : phase === "confirm"
        ? (
            <div style={{ display:"flex", gap:8 }}>
              <ActionBtn onClick={() => setPhase("q3")} variant="ghost" style={{ flex:1 }} disabled={busy}>
                {t("break_btn_back")}
              </ActionBtn>
              <ActionBtn onClick={execute} variant="primary" style={{ flex:1.6 }} disabled={busy}>
                {t("break_btn_confirm")}
              </ActionBtn>
            </div>
          )
        : null;

      function QuestionPanel({ qNum, promptKey, opts }) {
        return (
          <>
            <div style={{
              padding:"10px 12px", marginBottom:10,
              background:"rgba(var(--red-rgb),.08)", border:"1px dashed rgba(var(--red-rgb),.35)",
              borderRadius:10, fontSize:12, color:"var(--text)", lineHeight:1.55,
            }}>
              {t(promptKey).replace(/\*/g, "")}
            </div>
            <div style={{ display:"grid", gap:8 }}>
              {opts.map(o => {
                const matches = correct[qNum] === o.value;
                return (
                  <ActionBtn key={o.value} variant="ghost"
                             onClick={() => pickAnswer(qNum, o.value)}>
                    <span>{t(o.labelKey).replace(/[🔥🌱⚡🌊🛤️🌌]/g, "").trim()}</span>
                    {matches && (
                      <span style={{ marginLeft:6, fontSize:10, color:"var(--gold3)" }}>✦</span>
                    )}
                  </ActionBtn>
                );
              })}
            </div>
            <div style={{ marginTop:8, fontSize:10, color:"var(--muted)", textAlign:"center" }}>
              {qNum} / 3
            </div>
          </>
        );
      }

      return (
        <>
          {modalOpen && (
            <Modal
              onClose={(phase === "preview" || phase === "done") ? onClose : undefined}
              allowBackdropClose={phase === "preview" || phase === "done"}
              title={`🔥 ${t("break_modal_title")}`}
              accent="rgba(var(--red-rgb),.55)"
              maxWidth={380}
              cardStyle={{
                background:"linear-gradient(180deg,rgba(60,30,40,.95),rgba(20,10,15,.99))",
                boxShadow:"0 20px 60px rgba(0,0,0,.7), 0 0 32px rgba(var(--red-rgb),.22)",
              }}
              footer={footer}
            >
              {!data && !errInfo && (
                <div style={{ padding:"22px 0", textAlign:"center", color:"var(--muted)", fontSize:12 }}>
                  <DotSpinner /><div style={{ marginTop:8 }}>{t("foundation_loading")}</div>
                </div>
              )}

              {data && phase === "preview" && (
                <>
                  <div style={{
                    padding:"10px 12px", marginBottom:10,
                    background:"rgba(0,0,0,.3)", border:"1px dashed rgba(var(--red-rgb),.25)",
                    borderRadius:10, fontSize:12, color:"var(--text)", lineHeight:1.55,
                  }}>
                    {t("break_intro_short")}
                  </div>

                  <div style={{ display:"grid", gap:6, marginBottom:10 }}>
                    <KVRow
                      label={`🏯 ${t("foundation_label")}`}
                      value={data.current_foundation
                        ? safeT(`foundation_quality_${data.current_foundation}`, null, data.current_foundation)
                        : "—"}
                    />
                    <KVRow
                      label={`⚡ ${t("break_cost_cb")}`}
                      value={`${fmtNum(data.costs.cb)} (${Math.round(data.costs.cb_percent * 100)}%)`}
                    />
                    <KVRow
                      label={`💰 ${t("break_cost_stones")}`}
                      value={`${fmtNum(data.costs.stones)} (${fmtNum(data.balances.stones)})`}
                    />
                    <KVRow
                      label={`✨ ${t("break_cost_essence")}`}
                      value={`${data.costs.essence} (${data.balances.essence})`}
                    />
                  </div>

                  {!data.realm_ok && (
                    <div style={{
                      marginBottom:10, padding:"6px 10px", borderRadius:8,
                      background:"rgba(var(--red-rgb),.10)", border:"1px solid rgba(var(--red-rgb),.30)",
                      fontSize:11, color:"var(--red)", lineHeight:1.45,
                    }}>
                      {t("break_err_realm", { min_realm: data.min_realm }).replace(/\*/g, "")}
                    </div>
                  )}
                  {data.cooldown_seconds > 0 && (
                    <div style={{
                      marginBottom:10, padding:"6px 10px", borderRadius:8,
                      background:"rgba(var(--warn-rgb),.12)", border:"1px solid rgba(var(--warn-rgb),.35)",
                      fontSize:11, color:"var(--warn)", lineHeight:1.45,
                    }}>
                      {t("break_err_cooldown", {
                        remaining: `${data.cooldown_days}d`,
                      }).replace(/\*/g, "")}
                    </div>
                  )}
                  {!data.affordable && (
                    <div style={{
                      marginBottom:10, padding:"6px 10px", borderRadius:8,
                      background:"rgba(var(--red-rgb),.10)", border:"1px solid rgba(var(--red-rgb),.30)",
                      fontSize:11, color:"var(--red)", lineHeight:1.45,
                    }}>
                      {t("break_err_missing", { which: (data.missing || []).join(", ") }).replace(/\*/g, "")}
                    </div>
                  )}
                  {data.eligible && (
                    <div style={{
                      padding:"6px 10px", borderRadius:8,
                      background:"rgba(var(--red-rgb),.10)", border:"1px solid rgba(var(--red-rgb),.30)",
                      fontSize:11, color:"var(--red)", lineHeight:1.45,
                    }}>
                      {t("break_cost_warning")}
                    </div>
                  )}
                  {errInfo && (
                    <div className="err-banner" style={{ marginTop:10 }}>
                      {errInfo.reason || t("foundation_fail")}
                    </div>
                  )}
                </>
              )}

              {phase === "q1" && (
                <QuestionPanel qNum={1} promptKey="break_q1_prompt" opts={[
                  { value: "renuncia",  labelKey: "break_q1_a_renuncia" },
                  { value: "aceitacao", labelKey: "break_q1_a_aceitacao" },
                ]} />
              )}
              {phase === "q2" && (
                <QuestionPanel qNum={2} promptKey="break_q2_prompt" opts={[
                  { value: "velocidade",   labelKey: "break_q2_a_velocidade" },
                  { value: "profundidade", labelKey: "break_q2_a_profundidade" },
                ]} />
              )}
              {phase === "q3" && (
                <QuestionPanel qNum={3} promptKey="break_q3_prompt" opts={[
                  { value: "manter", labelKey: "break_q3_a_manter" },
                  { value: "novo",   labelKey: "break_q3_a_novo" },
                ]} />
              )}

              {phase === "confirm" && (
                <>
                  <div style={{
                    padding:"10px 12px", marginBottom:10,
                    background:"rgba(var(--red-rgb),.10)", border:"1px solid rgba(var(--red-rgb),.35)",
                    borderRadius:10, fontSize:12, color:"var(--red)", lineHeight:1.5,
                  }}>
                    {t("break_confirm_warning")}
                  </div>
                  <div style={{ display:"grid", gap:6 }}>
                    <KVRow label={`1. ${t("break_q1_short")}`} value={safeT(`break_q1_a_${answers[1]}`, null, answers[1] || "—")} />
                    <KVRow label={`2. ${t("break_q2_short")}`} value={safeT(`break_q2_a_${answers[2]}`, null, answers[2] || "—")} />
                    <KVRow label={`3. ${t("break_q3_short")}`} value={safeT(`break_q3_a_${answers[3]}`, null, answers[3] || "—")} />
                  </div>
                  {errInfo && (
                    <div className="err-banner" style={{ marginTop:10 }}>
                      {errInfo.reason || t("foundation_fail")}
                    </div>
                  )}
                </>
              )}

              {phase === "done" && result && (
                <div>
                  <div style={{ textAlign:"center", marginBottom:14 }}>
                    <div style={{ fontSize:54, marginBottom:6,
                                  filter:`drop-shadow(0 0 18px ${
                                    result.new_foundation === "perfect" ? "var(--realm-10)" :
                                    result.new_foundation === "high"    ? "#22d3ee" :
                                    result.new_foundation === "medium"  ? "var(--realm-2)" : "var(--realm-0)"
                                  })` }}>
                      {result.new_foundation_emoji || "🏯"}
                    </div>
                    <div style={{ fontFamily:"'Cinzel',serif", fontSize:18, fontWeight:700,
                                  color:"var(--gold2)", letterSpacing:1.2 }}>
                      {safeT(result.new_foundation_label_key, null, result.new_foundation)}
                    </div>
                    <div style={{ marginTop:6, fontSize:11, color:"var(--muted)" }}>
                      {t("break_score_label")}: <b style={{ color:"var(--gold3)" }}>{result.score}/3</b>
                    </div>
                  </div>
                  <div style={{
                    padding:"8px 10px", borderRadius:8,
                    background:"rgba(0,0,0,.25)", border:"1px solid rgba(var(--red-rgb),.2)",
                    fontSize:12, color:"var(--text)",
                  }}>
                    <span style={{ color:"var(--muted)" }}>
                      {result.old_foundation_label_key
                        ? safeT(result.old_foundation_label_key, null, result.old_foundation || "—")
                        : "—"}
                    </span>
                    <span style={{ margin:"0 8px", color:"var(--gold2)" }}>→</span>
                    <b style={{
                      color: result.score >= 2 ? "var(--jade)" : "var(--red)",
                    }}>
                      {safeT(result.new_foundation_label_key, null, result.new_foundation)}
                    </b>
                  </div>
                </div>
              )}
            </Modal>
          )}
          {isCine && (
            <div style={{
              position:"fixed", inset:0, zIndex:80,
              display:"grid", placeItems:"center", pointerEvents:"none",
              background:"rgba(20,5,5,.94)",
              animation:"bt-shake-screen .5s linear",
            }}>
              <div style={{
                fontSize:90,
                filter:"drop-shadow(0 0 30px rgba(var(--red-rgb),.7))",
                animation:"bt-charge 1s cubic-bezier(.4,0,.6,1) forwards",
              }}>💔</div>
            </div>
          )}
        </>
      );
    }

    // ─── Apex Reflection Chamber Modal (v14.14d — D-6b) ───────────────────────
    // Mirrors handlers/celestial.py:camara_reflexao_command + _settle_chamber.
    // Toggle session: enter (set entered_at) → exit (roll insights for elapsed
    // full hours, clear entered_at). Player must be Apex (realm 10 sub 9 +
    // 100/100 Heavenly Daos + Mahayana 3/3 trials).
    function ApexChamberModal({ onClose, onResolved }) {
      const [data, setData] = useState(null);
      const [busy, setBusy] = useState(false);
      const [errInfo, setErrInfo] = useState(null);
      const [exitResult, setExitResult] = useState(null);
      const [, setTick] = useState(0);

      useEffect(() => {
        let cancelled = false;
        async function load() {
          try {
            const res = await api("apex/chamber/status");
            if (!cancelled) setData(res);
          } catch (e) {
            if (!cancelled) setErrInfo({ reason: e.message });
          }
        }
        load();
        // Tick for elapsed timer (only when entered).
        const iv = setInterval(() => setTick(x => x + 1), 1000);
        return () => { cancelled = true; clearInterval(iv); };
      }, []);

      async function enter() {
        if (busy) return;
        setBusy(true);
        haptic("warning");
        try {
          const res = await api("apex/chamber/enter");
          if (!res.ok) {
            haptic("error");
            setErrInfo(res);
            setBusy(false);
            return;
          }
          // Refresh state
          const status = await api("apex/chamber/status");
          setData(status);
          setBusy(false);
        } catch (e) {
          haptic("error");
          setErrInfo({ reason: e.message });
          setBusy(false);
        }
      }

      async function exitChamber() {
        if (busy) return;
        setBusy(true);
        haptic("warning");
        try {
          const res = await api("apex/chamber/exit");
          if (!res.ok) {
            haptic("error");
            setErrInfo(res);
            setBusy(false);
            return;
          }
          setExitResult(res);
          haptic(res.insights_gained > 0 ? "success" : "select");
          setBusy(false);
          onResolved && onResolved(res);
        } catch (e) {
          haptic("error");
          setErrInfo({ reason: e.message });
          setBusy(false);
        }
      }

      // Live elapsed timer when entered.
      const liveElapsed = data && data.entered && data.entered_at_ms
        ? Math.max(0, Date.now() - data.entered_at_ms)
        : 0;
      const liveHours = Math.floor(liveElapsed / 3600000);
      const liveMins = Math.floor((liveElapsed % 3600000) / 60000);

      const footer = exitResult
        ? (
            <ActionBtn onClick={onClose} variant="primary" style={{ width:"100%" }}>
              {t("foundation_close")}
            </ActionBtn>
          )
        : data && data.entered
        ? (
            <ActionBtn onClick={exitChamber} variant="primary" style={{ width:"100%" }} disabled={busy}>
              {t("apex_chamber_exit_btn")}
            </ActionBtn>
          )
        : data && data.is_apex && !data.is_meditating
        ? (
            <ActionBtn onClick={enter} variant="primary" style={{ width:"100%" }} disabled={busy}>
              {t("apex_chamber_btn_enter").replace(/[🌌✨]/g, "").trim()}
            </ActionBtn>
          )
        : (
            <ActionBtn onClick={onClose} variant="ghost" style={{ width:"100%" }}>
              {t("foundation_close")}
            </ActionBtn>
          );

      return (
        <Modal
          onClose={onClose}
          allowBackdropClose={!exitResult}
          title={`🌌 ${t("apex_chamber_title").replace(/[🌌*]/g, "").trim() || t("apex_modal_title")}`}
          accent="rgba(253,224,138,.55)"
          maxWidth={380}
          cardStyle={{
            background:"linear-gradient(180deg,rgba(40,30,60,.95),rgba(20,10,40,.99))",
            boxShadow:"0 20px 60px rgba(0,0,0,.7), 0 0 32px rgba(253,224,138,.18)",
          }}
          footer={footer}
        >
          {!data && !errInfo && (
            <div style={{ padding:"22px 0", textAlign:"center", color:"var(--muted)", fontSize:12 }}>
              <DotSpinner /><div style={{ marginTop:8 }}>{t("foundation_loading")}</div>
            </div>
          )}

          {data && !data.is_apex && (
            <div style={{
              padding:"14px 12px", textAlign:"center",
              background:"rgba(var(--warn-rgb),.08)", border:"1px solid rgba(var(--warn-rgb),.25)",
              borderRadius:10, fontSize:12, color:"var(--warn)", lineHeight:1.55,
            }}>
              {t("apex_chamber_locked").replace(/\*/g, "")}
            </div>
          )}

          {data && data.is_apex && data.is_meditating && !data.entered && (
            <div style={{
              padding:"14px 12px", textAlign:"center",
              background:"rgba(var(--warn-rgb),.08)", border:"1px solid rgba(var(--warn-rgb),.25)",
              borderRadius:10, fontSize:12, color:"var(--warn)", lineHeight:1.55,
            }}>
              {t("apex_chamber_already_active").replace(/\*/g, "")}
            </div>
          )}

          {data && data.is_apex && !data.entered && !data.is_meditating && !exitResult && (
            <>
              <div style={{
                padding:"10px 12px", marginBottom:10,
                background:"rgba(0,0,0,.3)", border:"1px dashed rgba(253,224,138,.25)",
                borderRadius:10, fontSize:12, color:"var(--text)", lineHeight:1.55,
              }}>
                {t("apex_chamber_flavor").replace(/\*/g, "")}
              </div>
              <KVRow label={t("apex_chamber_insights_label")} value={data.divine_law_insights} />
              <div style={{
                marginTop:8, padding:"6px 10px", borderRadius:8,
                background:"rgba(253,224,138,.06)", border:"1px solid rgba(253,224,138,.22)",
                fontSize:11, color:"var(--gold3)", lineHeight:1.45, textAlign:"center",
              }}>
                {t("apex_chamber_chance_hint", {
                  pct: (data.insight_chance_per_hour * 100).toFixed(1),
                })}
              </div>
            </>
          )}

          {data && data.entered && !exitResult && (
            <>
              <div style={{
                padding:"14px 12px", textAlign:"center", marginBottom:10,
                background:"rgba(253,224,138,.08)", border:"1px dashed rgba(253,224,138,.4)",
                borderRadius:10,
              }}>
                <div style={{ fontSize:42, marginBottom:6,
                              animation:"pulse-glow 2.4s ease-in-out infinite",
                              filter:"drop-shadow(0 0 16px rgba(253,224,138,.6))" }}>🌌</div>
                <div style={{ fontFamily:"'Cinzel',serif", fontSize:13,
                              color:"var(--gold2)", letterSpacing:1 }}>
                  {t("apex_chamber_in_session")}
                </div>
                <div style={{ fontSize:18, color:"var(--gold3)", marginTop:6, fontWeight:700 }}>
                  {liveHours > 0 ? `${liveHours}h ${liveMins}m` : `${liveMins}m`}
                </div>
              </div>
              <KVRow label={t("apex_chamber_insights_label")} value={data.divine_law_insights} />
              <KVRow
                label={t("apex_chamber_chance_label")}
                value={`${(data.insight_chance_per_hour * 100).toFixed(1)}%/h`}
              />
            </>
          )}

          {exitResult && (
            <div style={{ textAlign:"center" }}>
              <div style={{ fontSize:60, marginBottom:8,
                            filter:"drop-shadow(0 0 18px rgba(253,224,138,.5))" }}>
                {exitResult.insights_gained > 0 ? "✨" : "🌌"}
              </div>
              <div style={{ fontFamily:"'Cinzel',serif", fontSize:18, fontWeight:700,
                            color:"var(--gold2)", letterSpacing:1.2, marginBottom:10 }}>
                {exitResult.insights_gained > 0
                  ? t("apex_chamber_session_won")
                  : t("apex_chamber_session_empty")}
              </div>
              <div style={{ display:"grid", gap:6 }}>
                <KVRow label={t("apex_chamber_elapsed_label")}
                       value={`${exitResult.elapsed_hours}h ${Math.floor((exitResult.elapsed_seconds % 3600) / 60)}m`} />
                <KVRow label={t("apex_chamber_gained_label")}
                       value={`+${exitResult.insights_gained}`} />
                <KVRow label={t("apex_chamber_total_label")} value={exitResult.total_insights} />
              </div>
            </div>
          )}

          {errInfo && (
            <div className="err-banner" style={{ marginTop:10 }}>
              {errInfo.reason || t("foundation_fail")}
            </div>
          )}
        </Modal>
      );
    }

    // ─── Body Tempering Tab (v14.14e) ─────────────────────────────────────────
    // Drill-in tab via Home card 💪. Mirrors handlers/cultivation.py
    // tempering_menu_callback + tempering ascend flow. Engine
    // core/body_tempering_engine.py. Nine Transformations (+Celestial 10-12).
    // Cultivo do Corpo @ R0–R6 (Mortal band) — lives in the Body Tempering tab (the unified
    // body home for all realms). Self-contained: own temper handler + state; reads
    // player.body_cultivation (from api_player) and refreshes via onPlayerRefresh. HARD
    // (realm-capped, body ≤ reino+1) + VISIBLE (HP / Defesa / Poder de Combate before→after).
    // Gated by cultivo_corpo_r0 → returns null on `main` (the 57 never see it).
    function BodyCultivationCard({ player, onPlayerRefresh }) {
      const [bodyBusy, setBodyBusy] = useState(false);
      const [bodyConfirm, setBodyConfirm] = useState(false);
      const bc = player && player.body_cultivation;
      if (!featureEnabled("cultivo_corpo_r0") || !bc || !bc.tier_key) return null;

      async function temperBody() {
        if (bodyBusy) return;
        setBodyBusy(true);
        try {
          const res = await api("world/body_temper", {});
          if (res && res.ok) {
            // VISIBLE increase (research §1/§2): HP + Defesa + Poder de Combate before→after.
            showToast("💪 " + t("body_temper_done", { tier: safeT(res.tier_key, null, "") })
              + (res.hp_gain > 0 ? "\n" + t("body_temper_gain", { hp: fmtNum(res.hp_gain), pow: fmtNum(res.power_gain || 0), def: res.def_pct_after }) : ""), "ok");
            setBodyConfirm(false);
            if (onPlayerRefresh) onPlayerRefresh();
          } else {
            const reason = (res && res.reason) || "body_temper_locked";
            showToast("⚠️ " + safeT(reason, null, t("err_engine") || "engine"), "err");
            setBodyConfirm(false);
          }
        } catch (e) {
          showToast(t("err_engine") || "engine", "err");
        } finally {
          setBodyBusy(false);
        }
      }

      return (
        <Card>
          <CardTitle left={"💪 " + t("body_cult_panel_title")} />
          <div style={{ display:"flex", alignItems:"center", gap:8, flexWrap:"wrap" }}>
            <span style={{ display:"inline-flex", alignItems:"center", gap:5,
                           padding:"4px 11px", borderRadius:999, fontSize:13,
                           background:"rgba(255,255,255,.06)",
                           border:"1px solid var(--border,#2a2a3a)", color:"var(--text)" }}>
              {bc.tier_emoji} {safeT(bc.tier_key, null, "")}
            </span>
            <span style={{ fontSize:11, color:"var(--muted)", fontFamily:"'Cinzel',serif", letterSpacing:.3 }}>
              {bc.is_apex ? (bc.transformation_emoji || "🌟") : (bc.mortal_level + "/" + bc.max_level)}
            </span>
          </div>
          <div style={{ fontSize:12, marginTop:8, lineHeight:1.45,
                        color: bc.risk_band === "danger" ? "#e07a7a"
                          : bc.risk_band === "warn" ? "#e6c46a" : "#9fd6a0" }}>
            {t("body_limit_title")}: {safeT("body_limit_" + bc.risk_band, null, "")}
          </div>

          {/* VISIBLE power (research §1/§2: always show the number going up). */}
          {!bc.is_apex && bc.max_hp != null && (
            <div style={{ display:"flex", gap:14, marginTop:8, fontSize:11.5, color:"var(--text)", flexWrap:"wrap" }}>
              <span>❤️ {t("body_max_hp")}: <b style={{ color:"var(--gold2)" }}>{fmtNum(bc.max_hp)}</b></span>
              <span>🛡️ {t("body_defense")}: <b style={{ color:"var(--gold2)" }}>+{bc.def_pct}%</b></span>
              {bc.combat_power != null && (
                <span>⚔️ {t("body_combat_power")}: <b style={{ color:"var(--gold2)" }}>{fmtNum(bc.combat_power)}</b>
                  {bc.next_combat_power != null && bc.next_combat_power > bc.combat_power && (
                    <span style={{ color:"var(--jade)", fontSize:10.5 }}>{" → " + fmtNum(bc.next_combat_power)}</span>
                  )}</span>
              )}
            </div>
          )}

          {bc.is_apex ? (
            <div style={{ fontSize:11, color:"var(--gold3)", marginTop:10, lineHeight:1.45 }}>
              {t("body_apex_note")}
            </div>
          ) : bc.at_realm_cap ? (
            <div style={{ fontSize:11, color:"var(--gold3)", marginTop:10, lineHeight:1.5,
                          padding:"8px 10px", borderRadius:8, background:"rgba(var(--gold2-rgb),.08)",
                          border:"1px solid rgba(var(--gold2-rgb),.3)" }}>
              ⛓️ {t("body_temper_realm_capped")}
            </div>
          ) : bc.next_cost ? (
            <div style={{ marginTop:10 }}>
              <div style={{ fontSize:11, color:"var(--gold3)", marginBottom:6 }}>
                {t("body_next_tier", { tier: safeT(bc.next_tier_key, null, "") })}
                {bc.next_def_pct != null && (
                  <span style={{ color:"var(--jade)" }}>{" · 🛡️ +" + bc.next_def_pct + "%"}</span>
                )}
                {" · "}🪨 {fmtNum(bc.next_cost.stones)}
                {" · "}🌀 {fmtNum(bc.next_cost.qi)}
                {bc.next_cost.via_progress && (
                  <span style={{ color:"var(--jade)" }}>{" · ⚡ " + t("body_via_horta")}</span>
                )}
              </div>
              <ActionBtn variant="primary"
                         disabled={bodyBusy || !bc.can_temper}
                         onClick={() => { if (bodyConfirm) temperBody(); else setBodyConfirm(true); }}
                         style={{ width:"100%" }}>
                {bodyConfirm ? ("✅ " + t("body_temper_confirm")) : ("💪 " + t("body_temper_btn"))}
              </ActionBtn>
              {!bc.can_temper && bc.temper_reason_key && (
                <div style={{ fontSize:10, color:"var(--red)", textAlign:"center", marginTop:5 }}>
                  {safeT(bc.temper_reason_key, null, "")}
                </div>
              )}
            </div>
          ) : (
            <div style={{ fontSize:10.5, fontStyle:"italic", color:"var(--muted)", marginTop:10, lineHeight:1.4 }}>
              🫀 {t("body_temper_maxed")}
            </div>
          )}

          {/* MV-4 — refino ancorado em LUGAR (Lei §1: a tela DIZ onde você
              está e o que isso vale; a key só chega com corpo_profundo ON —
              server-resolved, o custo acima já foi precificado com o mult). */}
          {bc.refine_place && bc.refine_place.line && (
            <div style={{ fontSize:10.5, color: bc.refine_place.place_key === "road" ? "#e6c46a" : "var(--jade)",
                          marginTop:8, lineHeight:1.45, padding:"7px 9px", borderRadius:8,
                          background:"rgba(255,255,255,.04)", border:"1px solid rgba(255,255,255,.09)" }}>
              {bc.refine_place.emoji} {bc.refine_place.line}
            </div>
          )}

          <div style={{ fontSize:10.5, fontStyle:"italic", color:"var(--muted)", marginTop:8, lineHeight:1.4 }}>
            {t("body_cult_future")}
          </div>
        </Card>
      );
    }

    // ─── MV-4 — Corpo Profundo: os 12 MERIDIANOS 经脉 ─────────────────────────
    // O mapa dos 12 canais (fechado/aberto/em ritual) + o ritual multi-etapa:
    // preparar (custo) → circular (idle, N horas, mais rápido no lugar certo)
    // → romper (chance honesta; falha = progresso parcial, Lei §1). Nomes e
    // linha do lugar chegam SERVER-RESOLVED (padrão continentes); o bónus por
    // canal folda na Alma (body_durability_mult) — nada aqui recalcula.
    function MeridiansCard({ onPlayerRefresh }) {
      const [reload, setReload] = useState(0);
      const [busy, setBusy] = useState(false);
      const [confirm, setConfirm] = useState(false);
      const { data, loading } = useApi("world/meridians", null, [reload]);
      if (!featureEnabled("corpo_profundo")) return null;
      if (loading && !data) return null;
      if (!data || !data.ok) return null;

      function fmtHM(sec) {
        const s = Math.max(0, Math.floor(sec || 0));
        const h = Math.floor(s / 3600), m = Math.floor((s % 3600) / 60);
        if (h > 0) return h + "h" + (m ? " " + m + "m" : "");
        return s >= 60 ? m + "m" : s + "s";
      }

      async function startRitual() {
        if (busy) return;
        setBusy(true); haptic("warning");
        try {
          const res = await api("world/meridian_start", {});
          if (res && res.ok) {
            haptic("success");
            showToast("⛩️ " + t("mer_started_toast", { hours: res.circulate_hours }), "ok");
            setConfirm(false); setReload(x => x + 1);
            if (onPlayerRefresh) onPlayerRefresh();
          } else {
            haptic("error");
            showToast("⚠️ " + safeT(res && res.reason, null, t("err_engine") || "engine"), "err");
            setConfirm(false);
          }
        } catch (e) { haptic("error"); showToast(t("err_engine") || "engine", "err"); }
        finally { setBusy(false); }
      }

      async function breakChannel() {
        if (busy) return;
        setBusy(true); haptic("warning");
        try {
          const res = await api("world/meridian_break", {});
          if (res && res.ok && res.opened) {
            haptic("success");
            // Progressão VISÍVEL — o antes→depois do rompimento (HP real via a Alma).
            showToast("🌟 " + t("mer_open_toast", {
              n: res.opened_count, total: res.total,
              hp_before: fmtNum(res.hp_before), hp_after: fmtNum(res.hp_after),
            }), "ok");
            setReload(x => x + 1);
            if (onPlayerRefresh) onPlayerRefresh();
          } else if (res && res.ok) {
            // Falha HONESTA — progresso parcial (a próxima chance sobe).
            haptic("error");
            showToast("💢 " + t("mer_fail_toast", {
              chance: res.chance_pct, next: res.next_chance_pct,
              time: fmtHM((res.recirculate_hours || 0) * 3600),
            }), "err");
            setReload(x => x + 1);
          } else {
            haptic("error");
            showToast("⚠️ " + safeT(res && res.reason, null, t("err_engine") || "engine"), "err");
          }
        } catch (e) { haptic("error"); showToast(t("err_engine") || "engine", "err"); }
        finally { setBusy(false); }
      }

      const ritual = data.ritual;
      const nxt = data.next;
      return (
        <Card>
          <CardTitle left={"⛩️ " + t("mer_section_title")}
                     right={data.opened_count + "/" + data.total} />
          {data.durability_bonus_pct > 0 && (
            <div style={{ fontSize:11, color:"var(--jade)", marginBottom:6 }}>
              🛡️ {t("mer_bonus_line", { pct: data.durability_bonus_pct })}
            </div>
          )}
          {/* O mapa dos 12 canais — aberto brilha, em ritual pulsa, fechado apaga. */}
          <div style={{ display:"grid", gridTemplateColumns:"repeat(4, 1fr)", gap:6, marginBottom:8 }}>
            {(data.channels || []).map(ch => (
              <div key={ch.key} title={ch.name} style={{
                textAlign:"center", padding:"7px 2px", borderRadius:8,
                background: ch.state === "open" ? "rgba(var(--gold2-rgb),.10)" : "rgba(0,0,0,.25)",
                border: "1px solid " + (ch.state === "open" ? "rgba(var(--gold2-rgb),.45)"
                  : ch.state === "ritual" ? "rgba(var(--accent2-rgb),.55)" : "rgba(255,255,255,.08)"),
                opacity: ch.state === "closed" ? .45 : 1,
              }}>
                <div style={{ fontSize:16 }}>{ch.emoji}</div>
                <div style={{ fontSize:7.5, color: ch.state === "open" ? "var(--gold3)" : "var(--muted)",
                              marginTop:2, lineHeight:1.2, overflow:"hidden", textOverflow:"ellipsis",
                              whiteSpace:"nowrap" }}>
                  {ch.name.replace(/^Meridiano (de l[ao]|del|d[ao]) /i, "").replace(/ Meridian$/i, "")}
                </div>
              </div>
            ))}
          </div>

          {data.all_open ? (
            <div style={{ fontSize:11, color:"var(--gold3)", lineHeight:1.5, textAlign:"center", padding:"6px 4px" }}>
              🏮 {t("mer_all_open_mini")}
              <div style={{ fontSize:10, color:"var(--muted)", fontStyle:"italic", marginTop:4 }}>
                {t("mer_teaser_mini")}
              </div>
            </div>
          ) : ritual ? (
            <div>
              <div style={{ fontSize:11.5, color:"var(--gold3)", lineHeight:1.5, marginBottom:8 }}>
                {ritual.ready
                  ? ("⚡ " + t("mer_ready_line", { name: ritual.name, chance: ritual.chance_pct }))
                  : ("⏳ " + t("mer_circulating_line", { name: ritual.name, time: fmtHM(ritual.remaining_seconds) }))}
              </div>
              {/* QoL 05/08 (report do [jogador]) — a cicatriz PERSISTENTE. O toast da
                  falha some antes de dar tempo de ler, e a re-circulação dura
                  HORAS: sem esta linha o jogador esquece que falhou e nunca vê
                  que a chance subiu. Só aparece com attempts > 0 (quem nunca
                  falhou não lê nada). Diz o antes→depois, que é a lei da casa
                  para toda progressão. */}
              {ritual.attempts > 0 && (
                <div style={{ fontSize:10.5, color:"var(--muted)", lineHeight:1.5, marginBottom:8,
                              padding:"6px 8px", borderRadius:8,
                              background:"rgba(255,120,120,.07)",
                              border:"1px solid rgba(255,120,120,.18)" }}>
                  💢 {t("mer_retry_memory", {
                        n: ritual.attempts,
                        was: ritual.base_chance_pct,
                        now: ritual.chance_pct,
                      })}
                </div>
              )}
              {ritual.ready && (
                <ActionBtn variant="primary" disabled={busy} onClick={breakChannel} style={{ width:"100%" }}>
                  ⚡ {t("mer_break_btn")}
                </ActionBtn>
              )}
            </div>
          ) : nxt ? (
            <div>
              <div style={{ fontSize:11, color:"var(--gold3)", marginBottom:6, lineHeight:1.5 }}>
                {nxt.emoji} <b>{nxt.name}</b>
                <div style={{ fontSize:10.5, color:"var(--muted)", marginTop:2 }}>
                  🪨 {fmtNum(nxt.cost.stones)} · 🧵 {nxt.cost.progress} · 🦴 {nxt.cost.essence}
                  {" · ⏳ " + nxt.circulate_hours + "h · 🎲 " + nxt.chance_pct + "%"}
                </div>
              </div>
              {nxt.can_start ? (
                <ActionBtn variant="primary" disabled={busy}
                           onClick={() => { if (confirm) startRitual(); else setConfirm(true); }}
                           style={{ width:"100%" }}>
                  {confirm ? ("✅ " + t("mer_start_confirm")) : ("⛩️ " + t("mer_start_btn"))}
                </ActionBtn>
              ) : (
                <div style={{ fontSize:10.5, color:"#e6c46a", textAlign:"center", lineHeight:1.45 }}>
                  {nxt.reason_key === "mer_cooldown"
                    ? "⏳ " + t("mer_cooldown_mini", { time: fmtHM(nxt.cooldown_remaining) })
                    : "🔒 " + safeT(nxt.reason_key, null, "")}
                </div>
              )}
            </div>
          ) : null}

          {/* Onde você está — o refino ancorado (server-resolved, Lei §1). */}
          {data.place && data.place.line && (
            <div style={{ fontSize:10, color:"var(--muted)", marginTop:8, lineHeight:1.4, fontStyle:"italic" }}>
              {data.place.emoji} {data.place.line}
            </div>
          )}
        </Card>
      );
    }

    // ═══ 星 2.1 — O CORPO QUE ACENDE ═════════════════════════════════════════
    // A primeira prova do idioma que o owner pediu para o jogo INTEIRO
    // (16/09): *"refina o corpo, lá tem o desenho do cultivador, e cada vez que
    // melhoras abre algo ou ilumina, como estrelas"*. O desenho é do Astra
    // (`Olho/Astra/2026-09-16-e-o-corpo-que-acende.md` §2); a gramática visual
    // é a da prévia que o owner aprovou (`newapp/preview/portal-v1.html`).
    //
    // ⚠️ TRÊS CAMADAS, NUNCA SOMADAS. Refino Mortal, Transformações e Meridianos
    // são progressões diferentes, com donos diferentes no servidor
    // (`player.body_cultivation`, `body_tempering/status`, `world/meridians`).
    // Um "31 estrelas do Corpo" ou uma percentagem comum seria um número que o
    // jogo não tem.
    //
    // ⚠️ UMA ESTRELA NUNCA SUBSTITUI O NÚMERO. Cada camada escreve, ao lado da
    // figura, o valor `L / M`, a etapa real, o que falta e o custo — e depois
    // de uma acção confirmada, o antes → depois com unidade.
    //
    // ⚠️ SÓ A CONFIRMAÇÃO ACENDE. Uma tentativa falhada, um ritual iniciado, um
    // erro de rede e uma simples reentrada não acendem nada. Em Meridianos o
    // servidor responde `ok:true` com `opened:false` quando o canal NÃO abre —
    // e isso é uma falha honesta, não um ponto.
    //
    // ⚠️ AS ÂNCORAS SÃO DA PINTURA, POR VARIANTE. As três peças (`male`,
    // `female` e 背影 de costas) são quadradas (1024²) e o corpo não cai no
    // mesmo sítio nas três: o cinto está a ~64% na masculina, ~63% na feminina
    // e ~68% na de costas. Coordenadas em % da própria imagem — a caixa é
    // quadrada, o `contain` não deixa faixas, e bitmap e marcas partilham o
    // MESMO rectângulo. A régua de partida é a do Astra (§2); o 6º ponto subiu
    // de 32 para 35 na masculina porque 32 cai em cima da BOCA, visto a olhar.
    var CORPO_PARES = [[42, 58, 36], [37, 63, 43], [34, 66, 50],
                       [33, 67, 57], [36, 64, 64], [44, 56, 71]];
    var CORPO_ANCORAS = {
      male:   { seam: [[50, 64], [50, 58], [50, 52], [50, 46], [50, 40], [50, 35], [50, 23]],
                pares: CORPO_PARES },
      female: { seam: [[50, 63], [50, 57], [50, 51], [50, 45], [50, 39], [50, 34], [50, 23.5]],
                pares: CORPO_PARES },
      back:   { seam: [[50, 67], [50, 60], [50, 53], [50, 46], [50, 40], [50, 34], [50, 25]],
                pares: CORPO_PARES },
    };

    // ⚠️ O MAPA DOS CANAIS É EXPLÍCITO. O Astra pediu *"registar as chaves
    // medidas num mapa visual explícito"* — medidas em
    // `core/meridian_engine.MERIDIAN_CHANNELS`: os 12 canais em seis pares
    // clássicos yin/yang (肺/大肠 metal · 胃/脾 terra · 心/小肠 fogo · 膀胱/肾
    // água · 心包/三焦 fogo ministro · 胆/肝 madeira). Cada par ocupa um dos
    // seis lugares dos lados do tronco: o 1º do par à esquerda, o 2º à
    // direita. Nunca ordenar pelo nome TRADUZIDO nem pela posição na resposta:
    // mudar de língua deslocaria as conquistas.
    var CORPO_MER_LUGAR = {
      pulmao: [0, 0], intestino_grosso: [0, 1],
      estomago: [1, 0], baco: [1, 1],
      coracao: [2, 0], intestino_delgado: [2, 1],
      bexiga: [3, 0], rim: [3, 1],
      pericardio: [4, 0], triplo_aquecedor: [4, 1],
      vesicula: [5, 0], figado: [5, 1],
    };

    function corpoVariante(gender) {
      return (gender === "male" || gender === "female") ? gender : "back";
    }

    // Os lugares de uma camada, pela ordem dos pontos: o Mortal sobe pela
    // costura; as Transformações dão os níveis 1/2 ao 1º par, 3/4 ao 2º…
    function corpoLugaresDe(camada, variante) {
      var a = CORPO_ANCORAS[variante] || CORPO_ANCORAS.back;
      if (camada === "mortal") {
        return a.seam.map(function (p) { return { x: p[0], y: p[1] }; });
      }
      var out = [];
      a.pares.forEach(function (p) {
        out.push({ x: p[0], y: p[2] });
        out.push({ x: p[1], y: p[2] });
      });
      return out;
    }

    // ── As três LEITURAS. Funções puras: recebem o que o servidor disse e
    //    devolvem `null` quando não há leitura (a carregar, a falhar, ou uma
    //    forma que não se reconhece). `null` NUNCA é zero — um `0 / 12` só
    //    aparece se o servidor o confirmou.
    function corpoLerMortal(bc, confirmado) {
      if (!bc || !bc.tier_key) return null;
      var M = Number(bc.max_level), L = Number(bc.mortal_level);
      if (!isFinite(M) || !isFinite(L) || M < 1 || L < 0) return null;
      // O número muda quando a CONFIRMAÇÃO chega, sem esperar pelo refresh do
      // jogador — e só para cima, e só até ao máximo que o servidor declarou.
      if (confirmado != null && confirmado > L && confirmado <= M) L = confirmado;
      var chaves = (Array.isArray(bc.tier_keys) && bc.tier_keys.length === M) ? bc.tier_keys : null;
      var pontos = [];
      for (var i = 1; i <= M; i++) {
        var est = i <= L ? "got"
                : i === L + 1 ? ((bc.is_apex || bc.at_realm_cap) ? "locked" : "next")
                : "empty";
        pontos.push({ id: i, n: i, estado: est,
                      nome: chaves ? safeT(chaves[i - 1], null, t("corpo_etapa_n", { n: i }))
                                   : t("corpo_etapa_n", { n: i }) });
      }
      return { L: L, M: M, pontos: pontos };
    }

    function _corpoTrancaReino(k) {
      return k === "tempering_need_realm" || k === "tempering_need_celestial_realm";
    }

    function corpoLerTransf(d, confirmado) {
      if (!d || d.ok === false || typeof d.current_level !== "number"
          || typeof d.max_level !== "number" || d.max_level < 1) return null;
      var M = d.max_level, L = d.current_level;
      if (confirmado != null && confirmado > L && confirmado <= M) L = confirmado;
      var niveis = Array.isArray(d.levels) ? d.levels : [];
      var nx = d.next;
      var pontos = [];
      for (var i = 1; i <= M; i++) {
        var lv = niveis[i - 1];
        var nome = (lv && lv.level === i && lv.name_key)
          ? safeT(lv.name_key, null, t("corpo_etapa_n", { n: i }))
          : t("corpo_etapa_n", { n: i });
        var est = i <= L ? "got"
                : i === L + 1 ? ((!d.unlocked || (nx && _corpoTrancaReino(nx.blocked_reason_key)))
                                 ? "locked" : "next")
                : "empty";
        pontos.push({ id: i, n: i, nome: nome, estado: est });
      }
      return { L: L, M: M, pontos: pontos };
    }

    function corpoLerMer(d, confirmado) {
      if (!d || d.ok !== true || !Array.isArray(d.channels) || typeof d.total !== "number") return null;
      var chs = d.channels.filter(function (c) { return c && c.key; });
      var vistas = {};
      var unicas = chs.every(function (c) {
        if (vistas[c.key]) return false;
        vistas[c.key] = true; return true;
      });
      // O mapa só se desenha quando o conjunto recebido é EXACTAMENTE o
      // conhecido. Um payload parcial não redistribui estrelas: a lista
      // textual é a leitura até o mapa voltar a bater.
      var mapaOk = unicas && chs.length === d.total && chs.length === 12
        && chs.every(function (c) {
          return Object.prototype.hasOwnProperty.call(CORPO_MER_LUGAR, c.key);
        });
      var prox = d.ritual ? d.ritual.channel : (d.next ? d.next.channel : null);
      var trancaProx = !d.ritual && d.next && !d.next.can_start
        && (d.next.reason_key === "mer_need_realm" || d.next.reason_key === "mer_realm_capped");
      var pontos = chs.map(function (c) {
        var est = (c.state === "open" || c.key === confirmado) ? "got"
                : c.state === "ritual" ? "ritual"
                : c.key === prox ? (trancaProx ? "locked" : "next")
                : "empty";
        var lugar = mapaOk ? CORPO_MER_LUGAR[c.key] : null;
        return { id: c.key, n: null, nome: ondaNomeLimpo(c.name || c.key), grupo: c.group || "",
                 estado: est, slot: lugar ? (lugar[0] * 2 + lugar[1]) : null };
      });
      // O número vem do CONTADOR do servidor; sem ele, só uma lista COMPLETA o
      // pode dar. Contar os abertos de uma lista parcial seria afirmar um
      // número menor do que o verdadeiro — sem leitura, não há número.
      var L;
      if (typeof d.opened_count === "number") L = d.opened_count;
      else if (chs.length === d.total) L = chs.filter(function (c) { return c.state === "open"; }).length;
      else return null;
      if (confirmado && !chs.some(function (c) { return c.key === confirmado && c.state === "open"; })) {
        L = Math.min(d.total, L + 1);
      }
      return { L: L, M: d.total, pontos: pontos, mapaOk: mapaOk };
    }

    // Os meridianos só se pedem num mundo que os tem. Um hook próprio porque
    // o `useApi` não sabe não pedir, e chamar hooks sob condição parte a ordem
    // deles (lição MA-32b). E um erro NÃO apaga a última leitura válida.
    function useCorpoMeridianos(on, rec) {
      const [st, setSt] = useState({ data: null, loading: !!on, error: null });
      useEffect(() => {
        if (!on) { setSt({ data: null, loading: false, error: null }); return undefined; }
        let cancel = false;
        setSt(s => ({ data: s.data, loading: true, error: null }));
        api("world/meridians", {})
          .then(d => { if (!cancel) setSt({ data: d, loading: false, error: null }); })
          .catch(e => { if (!cancel) setSt(s => ({ data: s.data, loading: false, error: (e && e.message) || "erro" })); });
        return () => { cancel = true; };
      }, [on, rec]);
      return st;
    }

    function corpoHM(seg) {
      var s = Math.max(0, Math.floor(Number(seg) || 0));
      var h = Math.floor(s / 3600), m = Math.floor((s % 3600) / 60);
      if (h > 0) return h + "h" + (m ? " " + m + "m" : "");
      return s >= 60 ? m + "m" : s + "s";
    }

    // A seta do botão da prévia, em vector — a catraca do §15 conta as setas
    // tipográficas como emoji, e o desenho da prévia é um traço, não um glifo.
    function CorpoSeta() {
      return (
        <svg aria-hidden="true" width="22" height="10" viewBox="0 0 22 10"
             style={{ flexShrink: 0, display: "block" }}>
          <path d="M0 5 H20 M15.5 0.8 L20.6 5 L15.5 9.2" fill="none"
                stroke="currentColor" strokeWidth="1.1" />
        </svg>
      );
    }

    // ── A MARCA — a gramática do Astra (§1 de "é o corpo que acende"), UMA vez.
    //    Vazio: anel de papel apagado. Próximo: anel de papel + contorno de
    //    posição. Adquirido: anel de ouro + núcleo de 4 px. O gesto (núcleo em
    //    ~220 ms, halo até 600 ms) só com `acende`, que o chamador só liga
    //    depois de um `ok` do servidor.
    //
    //    🎒 3.2 — nasceu dentro da `CorpoFigura` e SAIU dela quando o anel
    //    espacial precisou da mesma marca. Duas cópias da mesma gramática
    //    divergem sempre (Lei 0 §2); aqui há uma, e o Corpo desenha o MESMO DOM
    //    de antes (os filhos vêm num fragmento, sem nó a mais).
    //
    //    Desenha-se à volta de uma âncora de tamanho zero: quem chama põe a
    //    âncora onde a marca vive (sobre a figura, ou numa linha).
    function MarcaOnda({ estado, sel, acende }) {
      const P = NIV_ONDA;
      const eAcende = !!acende && estado === "got";
      const anel = estado === "got" ? P.gold
                 : (estado === "next" || estado === "ritual") ? P.paper
                 : estado === "unknown" ? "rgba(236,229,216,.28)"
                 : "rgba(236,229,216,.55)";
      return (
        <>
          {/* o respaldo de tinta: separa a marca de uma zona clara da pintura */}
          <span style={{ position: "absolute", left: -9, top: -9, width: 18, height: 18,
                         borderRadius: "50%", background: "rgba(11,10,12,.58)" }} />
          {(estado === "next" || estado === "ritual") && (
            <span style={{ position: "absolute", left: -8, top: -8, width: 16, height: 16,
                           borderRadius: "50%", border: "1px solid rgba(236,229,216,.45)" }} />
          )}
          {sel && (
            <span style={{ position: "absolute", left: -10, top: -10, width: 20, height: 20,
                           borderRadius: "50%", border: "1px solid " + P.paper }} />
          )}
          <span style={{ position: "absolute", left: -5, top: -5, width: 10, height: 10,
                         borderRadius: "50%", boxSizing: "border-box",
                         border: (estado === "next" || estado === "ritual" ? 1.5 : 1.25) + "px "
                                 + (estado === "unknown" ? "dashed " : "solid ") + anel }} />
          {estado === "got" && (
            <span className={eAcende ? "corpo-nucleo-acende" : undefined}
                  style={{ position: "absolute", left: -2, top: -2, width: 4, height: 4,
                           borderRadius: "50%", background: P.gold }} />
          )}
          {eAcende && (
            <span className="corpo-halo-acende"
                  style={{ position: "absolute", left: -5, top: -5, width: 10, height: 10,
                           borderRadius: "50%", border: "1px solid " + P.gold }} />
          )}
        </>
      );
    }

    // ── A FIGURA — o modo de DIAGRAMA que o Astra pediu. A `CultivatorFigure`
    //    só monta a imagem quando `meditating` é verdadeiro (a figura sentada é
    //    a prova de que o jogador medita); aqui ela é uma consulta do próprio
    //    corpo e não pode fingir meditação — nem herdar anéis, partículas ou
    //    respiração. Por baixo da pintura há SEMPRE uma silhueta vectorial com
    //    a mesma caixa: a arte que demora ou falha nunca tira os pontos, os
    //    números nem a acção.
    function CorpoFigura({ gender, camada, pontos, sel, acende, size, legenda, rotulo }) {
      const _S = Number(size) || 300;
      const P = NIV_ONDA;
      const colocados = (pontos || []).filter(p => p && p.x != null && p.y != null);

      // O traçado: a matéria de cada camada tem a sua forma. A costura central
      // no Mortal; os dois flancos nas Transformações; os canais a correr para
      // o eixo nos Meridianos. O troço entre pontos ADQUIRIDOS é de ouro.
      function tracado() {
        if (!colocados.length) return null;
        const base = "rgba(236,229,216,.22)";
        const ouro = "rgba(201,144,58,.85)";
        if (camada === "mortal") {
          const pts = colocados.map(p => p.x + "," + p.y).join(" ");
          const feitos = colocados.filter(p => p.estado === "got");
          return (
            <g>
              <polyline points={pts} fill="none" stroke={base} strokeWidth="1"
                        vectorEffect="non-scaling-stroke" />
              {feitos.length > 1 && (
                <polyline points={feitos.map(p => p.x + "," + p.y).join(" ")} fill="none"
                          stroke={ouro} strokeWidth="1.2" vectorEffect="non-scaling-stroke" />
              )}
            </g>
          );
        }
        if (camada === "transf") {
          const lados = [colocados.filter((p, i) => i % 2 === 0), colocados.filter((p, i) => i % 2 === 1)];
          return (
            <g>
              {lados.map((lado, k) => (
                <g key={k}>
                  <polyline points={lado.map(p => p.x + "," + p.y).join(" ")} fill="none"
                            stroke={base} strokeWidth="1" vectorEffect="non-scaling-stroke" />
                  {lado.filter(p => p.estado === "got").length > 1 && (
                    <polyline points={lado.filter(p => p.estado === "got").map(p => p.x + "," + p.y).join(" ")}
                              fill="none" stroke={ouro} strokeWidth="1.2"
                              vectorEffect="non-scaling-stroke" />
                  )}
                </g>
              ))}
            </g>
          );
        }
        return (
          <g>
            {colocados.map(p => (
              <path key={p.id} d={"M" + p.x + " " + p.y + " Q" + ((p.x + 50) / 2) + " " + (p.y - 3) + " 50 " + (p.y + 1)}
                    fill="none" stroke={p.estado === "got" ? ouro : base}
                    strokeWidth={p.estado === "got" ? 1.2 : 1}
                    strokeDasharray={p.estado === "got" ? undefined : "2 3"}
                    vectorEffect="non-scaling-stroke" />
            ))}
          </g>
        );
      }

      function marca(p) {
        // 🎒 3.2 — a anatomia da marca é da `MarcaOnda` (a mesma do anel);
        // aqui só se põe a âncora no sítio do corpo.
        return (
          <div key={p.id} aria-hidden="true" data-corpo-ponto={p.estado}
               style={{ position: "absolute", left: p.x + "%", top: p.y + "%",
                        width: 0, height: 0, zIndex: 4 }}>
            <MarcaOnda estado={p.estado} sel={sel != null && sel === p.id}
                       acende={acende != null && acende === p.id} />
          </div>
        );
      }

      const foco = legenda && colocados.find(p => p.id === legenda.id);
      // A PINTURA e a silhueta são do dono único da figura (`CultivatorFigure`,
      // modo `diagrama`); aqui só se desenha o que é do Corpo, no MESMO
      // rectângulo: o traçado, as marcas e a legenda.
      return (
        <CultivatorFigure diagrama gender={gender} size={_S} rotulo={rotulo}>
          <svg aria-hidden="true" viewBox="0 0 100 100" preserveAspectRatio="none"
               style={{ position: "absolute", inset: 0, width: "100%", height: "100%", zIndex: 3,
                        overflow: "visible" }}>
            {tracado()}
          </svg>
          {colocados.map(marca)}
          {foco && (
            <div aria-hidden="true"
                 style={Object.assign({ position: "absolute", top: foco.y + "%", zIndex: 5,
                                        transform: "translateY(-50%)", maxWidth: "46%",
                                        padding: "3px 8px", background: "rgba(11,10,12,.8)",
                                        fontFamily: P.body, fontSize: 12, lineHeight: (16 / 12),
                                        color: P.paper, whiteSpace: "normal" },
                                      foco.x >= 50 ? { left: "calc(" + foco.x + "% + 14px)" }
                                                   : { right: "calc(" + (100 - foco.x) + "% + 14px)" })}>
              {legenda.texto}
            </div>
          )}
        </CultivatorFigure>
      );
    }

    // Uma linha de leitura: rótulo à esquerda, número à direita, fio por baixo.
    // A anatomia é a das linhas de estado da prévia ("ESTADO · Em contemplação").
    function CorpoLinha({ rotulo, valor, tom, nota }) {
      const P = NIV_ONDA;
      return (
        <div style={{ padding: "10px 0", borderTop: "1px solid " + P.line }}>
          <div style={{ display: "flex", flexWrap: "wrap", alignItems: "baseline",
                        columnGap: 12, rowGap: 2 }}>
            <span style={{ flexShrink: 0, fontFamily: P.label, fontSize: 10, lineHeight: 1.6,
                           letterSpacing: ".16em", textTransform: "uppercase", color: P.muted }}>
              {rotulo}
            </span>
            <span style={Object.assign({}, _ONDA_TNUM, {
              marginLeft: "auto", textAlign: "right", fontSize: 16, lineHeight: (22 / 16),
              fontWeight: 500, color: tom === "seal" ? P.seal : tom === "gold" ? P.gold : P.paper,
              overflowWrap: "anywhere" })}>{valor}</span>
          </div>
          {nota ? (
            <div style={{ marginTop: 4, fontFamily: P.body, fontSize: 12, lineHeight: (18 / 12),
                          color: P.muted }}>{nota}</div>
          ) : null}
        </div>
      );
    }

    // Um requisito com o SEU número: tem / precisa, e a palavra que o diz.
    // A marca encontra depressa; a palavra é que decide (§4.2 da chegada).
    function CorpoReq({ rotulo, tem, precisa, ok }) {
      const P = NIV_ONDA;
      return (
        <div style={{ display: "flex", alignItems: "center", gap: 8, padding: "6px 0",
                      fontFamily: P.body, fontSize: 13, lineHeight: (20 / 13) }}>
          <span aria-hidden="true" style={{ color: ok ? P.gold : P.seal, display: "inline-flex" }}>
            <Mark name={ok ? "check" : "cross"} size={14} />
          </span>
          <span style={{ color: P.muted, flex: 1, minWidth: 0 }}>{rotulo}</span>
          <span style={Object.assign({}, _ONDA_TNUM, { fontSize: 13, color: ok ? P.paper : P.seal })}>
            {tem} / {precisa}
          </span>
          <span className="sr-only" style={{ position: "absolute", width: 1, height: 1,
                                             overflow: "hidden", clip: "rect(0 0 0 0)" }}>
            {ok ? t("corpo_req_ok") : t("corpo_req_falta")}
          </span>
        </div>
      );
    }

    function CorpoQueAcende({ player, onPlayerRefresh }) {
      const P = NIV_ONDA;
      const wide = typeof useWideShell === "function" ? useWideShell() : false;
      const merOn = typeof featureEnabled === "function" && featureEnabled("corpo_profundo");
      const [recT, setRecT] = useState(0);
      const [recM, setRecM] = useState(0);
      const tStat = useApi("body_tempering/status", null, [recT]);
      const mStat = useCorpoMeridianos(merOn, recM);
      // a ÚLTIMA leitura válida de cada fonte — o `useApi` apaga os dados num
      // erro, e um erro de rede não pode transformar o corpo em zero.
      const ultT = useRef(null);
      const ultM = useRef(null);
      const [camada, setCamada] = useState(null);
      const [sel, setSel] = useState(null);
      const [lista, setLista] = useState(false);
      const [busy, setBusy] = useState(false);
      const [confirmar, setConfirmar] = useState(false);
      const [recibo, setRecibo] = useState(null);
      const [erro, setErro] = useState(null);
      const [incerto, setIncerto] = useState(false);
      const [acende, setAcende] = useState(null);
      const [confMortal, setConfMortal] = useState(null);
      const [confTransf, setConfTransf] = useState(null);
      const [confMer, setConfMer] = useState(null);
      useEffect(() => {
        if (!acende) return undefined;
        const id = setTimeout(() => setAcende(null), 900);
        return () => clearTimeout(id);
      }, [acende]);
      // ⚠️ A LUZ TEM DE SE VER. Medido a 390x844: o botão ficava ~400px abaixo
      // da figura, e o ponto acendia FORA do ecrã — o jogador lia o recibo e
      // nunca via a figura mudar. Ao confirmar, a figura volta à vista (no
      // PC ela é fixa ao lado e não precisa).
      const figRef = useRef(null);
      useEffect(() => {
        if (!acende || !figRef.current) return;
        try {
          const r = figRef.current.getBoundingClientRect();
          if (r.top >= 0 && r.bottom <= (window.innerHeight || 0)) return;
          const reduz = window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches;
          figRef.current.scrollIntoView({ behavior: reduz ? "auto" : "smooth", block: "start" });
        } catch (e) { /* sem scroll, a leitura continua certa */ }
      }, [acende]);

      const tValido = !!(tStat.data && tStat.data.ok !== false
                         && typeof tStat.data.current_level === "number");
      if (tValido) ultT.current = tStat.data;
      const mValido = !!(mStat.data && mStat.data.ok === true && Array.isArray(mStat.data.channels));
      if (mValido) ultM.current = mStat.data;
      const dT = tValido ? tStat.data : ultT.current;
      const dM = mValido ? mStat.data : ultM.current;

      const bc = player && player.body_cultivation;
      const temMortal = !!(bc && bc.tier_key);
      const camadas = [];
      if (temMortal) camadas.push("mortal");
      camadas.push("transf");
      if (merOn) camadas.push("mer");
      const padrao = (temMortal && !bc.is_apex) ? "mortal" : "transf";
      const cam = camadas.indexOf(camada) >= 0 ? camada : padrao;
      const variante = corpoVariante(player && player.gender);

      const leituras = {
        mortal: corpoLerMortal(bc, confMortal),
        transf: corpoLerTransf(dT, confTransf),
        mer: merOn ? corpoLerMer(dM, confMer) : null,
      };
      const lei = leituras[cam];
      const fonte = cam === "transf" ? tStat : cam === "mer" ? mStat : null;
      const velho = (cam === "transf" && !tValido && !!dT) || (cam === "mer" && !mValido && !!dM);
      const aCarregar = !lei && fonte && fonte.loading;
      const falhou = !lei && fonte && !fonte.loading;

      // Os pontos na figura. Mortal/Transformações: um lugar por nível, e o
      // número de lugares tem de BATER com o máximo do servidor — se não bate,
      // a figura não corta nem inventa pontos; a lista textual é a leitura.
      const lugares = corpoLugaresDe(cam, variante);
      let pontosFig = [];
      let mapaBate = true;
      if (lei) {
        if (cam === "mer") {
          mapaBate = !!lei.mapaOk;
          pontosFig = mapaBate ? lei.pontos.map(p => Object.assign({}, p, lugares[p.slot])) : [];
        } else {
          mapaBate = lei.pontos.length === lugares.length;
          pontosFig = mapaBate ? lei.pontos.map((p, i) => Object.assign({}, p, lugares[i])) : [];
        }
      } else {
        // sem leitura: lugares RESERVADOS, sem estado — nunca "zero conquistado"
        pontosFig = lugares.map((l, i) => ({ id: "r" + i, x: l.x, y: l.y, estado: "unknown" }));
      }

      function trocarCamada(c) {
        if (c === cam) return;
        haptic("select");
        setCamada(c); setSel(null); setConfirmar(false); setErro(null); setRecibo(null);
      }

      const nomeCamada = { mortal: t("corpo_camada_mortal"), transf: t("corpo_camada_transf"),
                           mer: t("corpo_camada_mer") };
      // o vocabulário da casa é o simplificado (`mer_section_title` = 经脉)
      const hanCamada = { mortal: "身", transf: "体", mer: "经脉" };

      // ── a legenda junto da figura: a selecção manda; sem ela, o ponto em
      //    curso. Doze rótulos sobre a roupa seriam ruído.
      const foco = lei ? (lei.pontos.find(p => p.id === sel)
                          || lei.pontos.find(p => p.estado === "ritual")
                          || lei.pontos.find(p => p.estado === "next")
                          || lei.pontos.find(p => p.estado === "locked")) : null;
      const legenda = foco ? { id: foco.id, texto: (foco.n ? foco.n + " · " : "") + foco.nome } : null;

      const valorTxt = !lei ? "" : cam === "mortal"
        ? t("corpo_valor_mortal", { l: lei.L, m: lei.M })
        : cam === "transf" ? t("corpo_valor_transf", { l: lei.L, m: lei.M })
        : t("corpo_valor_mer", { n: lei.L, total: lei.M });
      const rotuloFig = t("corpo_figura_aria", { camada: nomeCamada[cam],
                                                 valor: lei ? valorTxt : t("corpo_carregando") });

      // ── o TÍTULO: o que o corpo É agora, pelo nome real da etapa.
      let titulo = nomeCamada[cam];
      if (cam === "mortal" && bc) titulo = ondaNomeLimpo(safeT(bc.tier_key, null, nomeCamada.mortal));
      if (cam === "transf" && dT && dT.current_info && dT.current_info.name_key) {
        titulo = ondaNomeLimpo(safeT(dT.current_info.name_key, null, nomeCamada.transf));
      }
      if (cam === "mer") titulo = t("corpo_mer_titulo");

      // ── a reconciliação: uma resposta que não chegou NÃO é uma resposta.
      //    Antes de deixar gastar de novo, o estado verdadeiro volta do servidor.
      async function reconciliar(c) {
        setIncerto(true);
        setErro({ camada: c, texto: t("corpo_incerto") });
        try { if (onPlayerRefresh) await onPlayerRefresh(); } catch (e) { /* o estado fica o último válido */ }
        setRecT(x => x + 1); setRecM(x => x + 1);
        setIncerto(false);
        setErro(null);
      }

      async function temperar() {
        if (busy || incerto) return;
        setBusy(true); setErro(null); setRecibo(null); haptic("warning");
        try {
          const res = await api("world/body_temper", {});
          if (res && res.ok === true && typeof res.new_level === "number") {
            haptic("success");
            const linhas = [t("corpo_res_nivel", { a: res.new_level - 1, b: res.new_level })];
            if (typeof res.hp_before === "number" && typeof res.hp_after === "number" && res.hp_gain > 0) {
              linhas.push(t("corpo_res_vida", { a: fmtFull(res.hp_before), b: fmtFull(res.hp_after),
                                                d: fmtFull(res.hp_gain) }));
            }
            if (res.def_pct_before != null && res.def_pct_after != null) {
              linhas.push(t("corpo_res_defesa", { a: res.def_pct_before, b: res.def_pct_after }));
            }
            if (typeof res.power_before === "number" && typeof res.power_after === "number" && res.power_gain > 0) {
              linhas.push(t("corpo_res_poder", { a: fmtFull(res.power_before), b: fmtFull(res.power_after),
                                                 d: fmtFull(res.power_gain) }));
            }
            setConfMortal(res.new_level);
            setAcende({ camada: "mortal", id: res.new_level });
            setRecibo({ camada: "mortal", tom: "ok", linhas: linhas });
            setConfirmar(false);
            if (onPlayerRefresh) onPlayerRefresh();
          } else {
            haptic("error");
            setConfirmar(false);
            setErro({ camada: "mortal",
                      texto: ondaNomeLimpo(safeT(res && res.reason, null, t("corpo_falha"))) });
          }
        } catch (e) {
          haptic("error");
          setConfirmar(false);
          await reconciliar("mortal");
        } finally { setBusy(false); }
      }

      async function ascender() {
        if (busy || incerto) return;
        setBusy(true); setErro(null); setRecibo(null); haptic("warning");
        try {
          const res = await api("body_tempering/ascend");
          if (res && res.ok === true && typeof res.new_level === "number") {
            haptic("success");
            const linhas = [t("corpo_res_nivel", { a: res.new_level - 1, b: res.new_level })];
            const pd = res.power_delta;
            if (pd && pd.max_hp && typeof pd.max_hp.before === "number" && pd.max_hp.after > pd.max_hp.before) {
              linhas.push(t("corpo_res_vida", { a: fmtFull(pd.max_hp.before), b: fmtFull(pd.max_hp.after),
                                                d: fmtFull(pd.max_hp.after - pd.max_hp.before) }));
            }
            const cp = pd && pd.display_combat_power;
            if (cp && typeof cp.before === "number" && cp.after > cp.before) {
              linhas.push(t("corpo_res_poder", { a: fmtFull(cp.before), b: fmtFull(cp.after),
                                                 d: fmtFull(cp.after - cp.before) }));
            }
            if (res.qi_cap_bonus > 0) linhas.push(t("corpo_res_qicap", { n: fmtFull(res.qi_cap_bonus) }));
            setConfTransf(res.new_level);
            setAcende({ camada: "transf", id: res.new_level });
            setRecibo({ camada: "transf", tom: "ok", linhas: linhas });
            setRecT(x => x + 1);
            if (onPlayerRefresh) onPlayerRefresh();
          } else {
            haptic("error");
            const r = res && res.reason;
            setErro({ camada: "transf",
                      texto: ondaNomeLimpo(safeT(r ? "body_blocked_" + r : null, null, t("body_blocked_generic"))) });
          }
        } catch (e) {
          haptic("error");
          await reconciliar("transf");
        } finally { setBusy(false); }
      }

      function nomeDoCanal(key) {
        const p = leituras.mer && leituras.mer.pontos.find(x => x.id === key);
        return p ? p.nome : key;
      }

      async function iniciarRitual() {
        if (busy || incerto) return;
        setBusy(true); setErro(null); setRecibo(null); haptic("warning");
        try {
          const res = await api("world/meridian_start", {});
          if (res && res.ok === true) {
            haptic("success");
            // ⚠️ Iniciar NÃO acende nada. Um ritual é uma espera, não um canal.
            setRecibo({ camada: "mer", tom: "neutro",
                        linhas: [t("corpo_res_ritual", { name: nomeDoCanal(res.channel),
                                                         h: res.circulate_hours })] });
            setConfirmar(false);
            setRecM(x => x + 1);
            if (onPlayerRefresh) onPlayerRefresh();
          } else {
            haptic("error");
            setConfirmar(false);
            setErro({ camada: "mer", texto: ondaNomeLimpo(safeT(res && res.reason, null, t("corpo_falha"))) });
          }
        } catch (e) {
          haptic("error");
          setConfirmar(false);
          await reconciliar("mer");
        } finally { setBusy(false); }
      }

      async function romperCanal() {
        if (busy || incerto) return;
        setBusy(true); setErro(null); setRecibo(null); haptic("warning");
        try {
          const res = await api("world/meridian_break", {});
          if (res && res.ok === true && res.opened === true) {
            haptic("success");
            const linhas = [t("corpo_res_canal", { name: nomeDoCanal(res.channel),
                                                  n: res.opened_count, total: res.total })];
            if (typeof res.hp_before === "number" && typeof res.hp_after === "number" && res.hp_gain > 0) {
              linhas.push(t("corpo_res_vida", { a: fmtFull(res.hp_before), b: fmtFull(res.hp_after),
                                                d: fmtFull(res.hp_gain) }));
            }
            if (res.durability_pct_before != null && res.durability_pct_after != null) {
              linhas.push(t("corpo_res_durab", { a: res.durability_pct_before, b: res.durability_pct_after }));
            }
            setConfMer(res.channel);
            setAcende({ camada: "mer", id: res.channel });
            setRecibo({ camada: "mer", tom: "ok", linhas: linhas });
            setRecM(x => x + 1);
            if (onPlayerRefresh) onPlayerRefresh();
          } else if (res && res.ok === true) {
            // ⚠️ `ok:true` com `opened:false` — a FALHA HONESTA. A chance sobe e
            // a espera recomeça; o canal continua apagado.
            haptic("error");
            setRecibo({ camada: "mer", tom: "falha",
                        linhas: [t("corpo_res_falhou", { a: res.chance_pct, b: res.next_chance_pct,
                                                         time: corpoHM((res.recirculate_hours || 0) * 3600) })] });
            setRecM(x => x + 1);
          } else {
            haptic("error");
            setErro({ camada: "mer", texto: ondaNomeLimpo(safeT(res && res.reason, null, t("corpo_falha"))) });
          }
        } catch (e) {
          haptic("error");
          await reconciliar("mer");
        } finally { setBusy(false); }
      }

      // ── as LINHAS de cada camada, e a sua acção ───────────────────────────
      function blocoMortal() {
        const l = leituras.mortal;
        const linhas = [];
        const detalhes = [];
        linhas.push(<CorpoLinha key="v" rotulo={t("corpo_lin_mortal")} valor={l.L + " / " + l.M} />);
        const falta = l.M - l.L;
        // o limite do REINO morde antes do da faixa: com `realm_cap` abaixo do
        // máximo, a leitura diz até onde se pode ir AGORA.
        // (no próprio limite a frase do servidor já o diz — não repetir)
        const capReino = (!bc.is_apex && !bc.at_realm_cap && typeof bc.realm_cap === "number"
                          && bc.realm_cap < l.M) ? bc.realm_cap : null;
        linhas.push(<CorpoLinha key="lim" rotulo={t("corpo_lin_limite")}
                                valor={falta <= 0 ? t("corpo_concluido")
                                       : t(falta === 1 ? "corpo_niveis_1" : "corpo_niveis_n", { n: falta })}
                                nota={capReino != null && falta > 0 ? t("corpo_limite_reino", { cap: capReino }) : null} />);
        // cada número pelo SEU valor — um campo ausente não esconde os outros
        if (!bc.is_apex && bc.max_hp != null) {
          detalhes.push(<CorpoLinha key="hp" rotulo={ondaNomeLimpo(t("body_max_hp"))} valor={fmtFull(bc.max_hp)} />);
        }
        if (!bc.is_apex && bc.def_pct != null) {
          detalhes.push(<CorpoLinha key="def" rotulo={ondaNomeLimpo(t("body_defense"))} valor={"+" + bc.def_pct + "%"} />);
        }
        if (!bc.is_apex && bc.combat_power != null) {
          detalhes.push(<CorpoLinha key="cp" rotulo={ondaNomeLimpo(t("body_combat_power"))}
                                  valor={fmtFull(bc.combat_power)}
                                  nota={(bc.next_combat_power != null && bc.next_combat_power > bc.combat_power)
                                        ? t("corpo_prox_poder", { n: fmtFull(bc.next_combat_power) }) : null} />);
        }
        if (bc.risk_band) {
          detalhes.push(<CorpoLinha key="risk" rotulo={ondaNomeLimpo(t("body_limit_title"))}
                                  valor={ondaNomeLimpo(safeT("body_limit_" + bc.risk_band, null, ""))}
                                  tom={bc.risk_band === "danger" ? "seal" : bc.risk_band === "warn" ? "gold" : null} />);
        }
        let acao = null, nota = null;
        if (bc.is_apex) {
          nota = t("corpo_mortal_fechado", { l: l.L, m: l.M });
        } else if (l.L >= l.M) {
          nota = ondaNomeLimpo(t("body_temper_maxed"));
        } else if (bc.at_realm_cap) {
          nota = ondaNomeLimpo(t("body_temper_realm_capped"));
        } else if (bc.next_cost) {
          const c = bc.next_cost;
          linhas.push(<CorpoLinha key="prox" rotulo={t("corpo_lin_proximo")}
                                  valor={ondaNomeLimpo(safeT(bc.next_tier_key, null, ""))}
                                  nota={bc.next_def_pct != null ? t("corpo_prox_defesa", { pct: bc.next_def_pct }) : null} />);
          linhas.push(<CorpoLinha key="custo" rotulo={t("corpo_lin_custo")}
                                  valor={t("corpo_custo_pedras", { n: fmtFull(c.stones) }) + " · "
                                         + t("corpo_custo_qi", { n: fmtFull(c.qi) })}
                                  nota={c.via_progress ? t("corpo_custo_horta") : null} />);
          acao = (
            <OndaBtn disabled={busy || incerto || !bc.can_temper}
                     onClick={() => { if (confirmar) temperar(); else { haptic("select"); setConfirmar(true); } }}
                     style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: 24,
                              width: wide ? "auto" : "100%", minWidth: wide ? 260 : undefined }}>
              <span>{busy ? t("corpo_a_confirmar")
                          : ondaNomeLimpo(confirmar ? t("body_temper_confirm") : t("body_temper_btn"))}</span>
              <CorpoSeta />
            </OndaBtn>
          );
          if (!bc.can_temper && bc.temper_reason_key) {
            nota = ondaNomeLimpo(safeT(bc.temper_reason_key, null, ""));
          }
        }
        if (bc.refine_place && bc.refine_place.line) {
          detalhes.push(<CorpoLinha key="lugar" rotulo={t("corpo_lin_lugar")}
                                  valor={ondaNomeLimpo(bc.refine_place.line)} />);
        }
        return { linhas, detalhes, acao, nota };
      }

      function blocoTransf() {
        const l = leituras.transf;
        const d = dT;
        const linhas = [];
        const detalhes = [];
        if (!d.unlocked) {
          return { linhas: [<CorpoLinha key="v" rotulo={t("corpo_lin_transf")} valor={l.L + " / " + l.M} />],
                   acao: null,
                   nota: t("corpo_transf_trancada", { realm: d.min_realm_required, cur: d.realm }),
                   notaTom: "trancado" };
        }
        linhas.push(<CorpoLinha key="v" rotulo={t("corpo_lin_transf")} valor={l.L + " / " + l.M} />);
        const falta = l.M - l.L;
        detalhes.push(<CorpoLinha key="lim" rotulo={t("corpo_lin_limite")}
                                valor={falta <= 0 ? t("corpo_concluido")
                                       : t(falta === 1 ? "corpo_niveis_1" : "corpo_niveis_n", { n: falta })} />);
        if (d.current_info && typeof d.current_info.hp_def_mult === "number") {
          detalhes.push(<CorpoLinha key="mult" rotulo={t("corpo_lin_mult")}
                                  valor={"×" + d.current_info.hp_def_mult.toFixed(2)} />);
        }
        const nx = d.next;
        if (!nx) {
          return { linhas, detalhes, acao: null, nota: ondaNomeLimpo(t("body_maxed_hint")) };
        }
        const req = Math.max(0, Number(nx.progress_required) || 0);
        const tem = Math.max(0, Number(d.body_tempering_progress) || 0);
        const faltaP = Math.max(0, req - tem);
        linhas.push(
          <div key="prog" style={{ padding: "10px 0", borderTop: "1px solid " + P.line }}>
            <div style={{ display: "flex", alignItems: "baseline", columnGap: 12, flexWrap: "wrap" }}>
              <span style={{ fontFamily: P.label, fontSize: 10, lineHeight: 1.6, letterSpacing: ".16em",
                             textTransform: "uppercase", color: P.muted }}>{ondaNomeLimpo(t("body_progress_label"))}</span>
              <span style={Object.assign({}, _ONDA_TNUM, { marginLeft: "auto", fontSize: 16, lineHeight: (22 / 16),
                                                           color: P.paper })}>
                {fmtFull(tem)} / {fmtFull(req)}
              </span>
            </div>
            <div style={{ marginTop: 6 }}>
              <CultFio pct={req > 0 ? (tem / req) * 100 : 100} color={P.gold} over={tem > req} />
            </div>
            <div style={{ marginTop: 4, fontFamily: P.body, fontSize: 12, color: P.muted }}>
              {faltaP > 0 ? t("corpo_faltam", { n: fmtFull(faltaP) }) : t("corpo_prog_completo")}
            </div>
          </div>
        );
        const bp = Number(d.total_battle_power || (player && player.battle_power) || 0);
        linhas.push(
          <div key="reqs" style={{ padding: "8px 0 4px", borderTop: "1px solid " + P.line }}>
            <div style={{ fontFamily: P.label, fontSize: 10, lineHeight: 1.6, letterSpacing: ".16em",
                          textTransform: "uppercase", color: P.muted, marginBottom: 2 }}>
              {t("corpo_lin_requisitos", { name: ondaNomeLimpo(safeT(nx.name_key, null, t("corpo_etapa_n", { n: nx.level }))) })}
            </div>
            <CorpoReq rotulo={ondaNomeLimpo(t("body_req_stones"))} tem={fmtFull(d.spirit_stones)}
                      precisa={fmtFull(nx.cost_stones)} ok={d.spirit_stones >= nx.cost_stones} />
            <CorpoReq rotulo={ondaNomeLimpo(t("body_req_qi"))} tem={fmtFull(Math.floor(d.qi))}
                      precisa={fmtFull(nx.cost_qi)} ok={d.qi >= nx.cost_qi} />
            <CorpoReq rotulo={ondaNomeLimpo(t("body_req_bp"))} tem={fmtFull(bp)}
                      precisa={fmtFull(nx.min_battle_power)} ok={bp >= nx.min_battle_power} />
            {nx.min_realm > d.min_realm_required && (
              <CorpoReq rotulo={ondaNomeLimpo(t("body_req_realm"))} tem={d.realm} precisa={nx.min_realm}
                        ok={d.realm >= nx.min_realm} />
            )}
            {nx.essence_cost > 0 && (
              <CorpoReq rotulo={ondaNomeLimpo(t("body_req_essence"))} tem={fmtFull(d.celestial_essence)}
                        precisa={fmtFull(nx.essence_cost)} ok={d.celestial_essence >= nx.essence_cost} />
            )}
          </div>
        );
        const acao = (
          <OndaBtn disabled={busy || incerto || tStat.loading || !nx.can_ascend} onClick={ascender}
                   style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: 24,
                            width: wide ? "auto" : "100%", minWidth: wide ? 260 : undefined }}>
            <span>{busy ? t("corpo_a_confirmar") : ondaNomeLimpo(t("body_ascend_btn"))}</span>
            <CorpoSeta />
          </OndaBtn>
        );
        const nota = nx.can_ascend ? null
          : ondaNomeLimpo(safeT("body_blocked_" + nx.blocked_reason_key, null, t("body_blocked_generic")));
        return { linhas, detalhes, acao, nota };
      }

      function blocoMer() {
        const l = leituras.mer;
        const d = dM;
        const linhas = [<CorpoLinha key="v" rotulo={t("corpo_lin_mer")} valor={l.L + " / " + l.M} />];
        const detalhes = [];
        detalhes.push(<CorpoLinha key="dur" rotulo={t("corpo_mer_durab")}
                                valor={"+" + (d.durability_bonus_pct || 0) + "%"}
                                nota={d.per_channel_pct != null ? t("corpo_mer_por_canal", { pct: d.per_channel_pct }) : null} />);
        let acao = null, nota = null;
        const r = d.ritual;
        const nx = d.next;
        if (d.all_open) {
          nota = ondaNomeLimpo(t("mer_all_open_mini"));
        } else if (r) {
          linhas.push(<CorpoLinha key="rit" rotulo={t("corpo_mer_ritual")}
                                  valor={ondaNomeLimpo(r.name || r.channel)}
                                  nota={r.ready ? t("corpo_mer_pronto", { chance: r.chance_pct })
                                                : t("corpo_mer_circulando", { time: corpoHM(r.remaining_seconds) })} />);
          if (r.attempts > 0) {
            linhas.push(<CorpoLinha key="mem" rotulo={t("corpo_mer_tentativas")} valor={String(r.attempts)}
                                    nota={t("corpo_mer_chance_subiu", { was: r.base_chance_pct, now: r.chance_pct })} />);
          }
          if (r.ready) {
            acao = (
              <OndaBtn disabled={busy || incerto || mStat.loading} onClick={romperCanal}
                       style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: 24,
                                width: wide ? "auto" : "100%", minWidth: wide ? 260 : undefined }}>
                <span>{busy ? t("corpo_a_confirmar") : ondaNomeLimpo(t("mer_break_btn"))}</span>
                <CorpoSeta />
              </OndaBtn>
            );
          }
        } else if (nx) {
          linhas.push(<CorpoLinha key="prox" rotulo={t("corpo_lin_proximo")} valor={ondaNomeLimpo(nx.name || nx.channel)}
                                  nota={t("corpo_mer_espera", { h: nx.circulate_hours, chance: nx.chance_pct })} />);
          linhas.push(<CorpoLinha key="custo" rotulo={t("corpo_lin_custo")}
                                  valor={t("corpo_mer_custo", { stones: fmtFull((nx.cost || {}).stones),
                                                                progress: fmtFull((nx.cost || {}).progress),
                                                                essence: fmtFull((nx.cost || {}).essence) })} />);
          if (nx.can_start) {
            acao = (
              <OndaBtn disabled={busy || incerto || mStat.loading}
                       onClick={() => { if (confirmar) iniciarRitual(); else { haptic("select"); setConfirmar(true); } }}
                       style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: 24,
                                width: wide ? "auto" : "100%", minWidth: wide ? 260 : undefined }}>
                <span>{busy ? t("corpo_a_confirmar")
                            : ondaNomeLimpo(confirmar ? t("mer_start_confirm") : t("mer_start_btn"))}</span>
                <CorpoSeta />
              </OndaBtn>
            );
          } else {
            nota = nx.reason_key === "mer_cooldown"
              ? ondaNomeLimpo(t("mer_cooldown_mini", { time: corpoHM(nx.cooldown_remaining) }))
              : ondaNomeLimpo(safeT(nx.reason_key, null, ""));
          }
        }
        if (d.place && d.place.line) {
          detalhes.push(<CorpoLinha key="lugar" rotulo={t("corpo_lin_lugar")} valor={ondaNomeLimpo(d.place.line)} />);
        }
        return { linhas, detalhes, acao, nota };
      }

      const bloco = !lei ? null
        : cam === "mortal" ? blocoMortal()
        : cam === "transf" ? (dT ? blocoTransf() : null)
        : (dM ? blocoMer() : null);

      const estadoPalavra = {
        got: t("corpo_est_got"), next: t("corpo_est_next"), empty: t("corpo_est_empty"),
        locked: t("corpo_est_locked"), ritual: t("corpo_est_ritual"),
      };

      // ── as PEÇAS da tela ───────────────────────────────────────────────────
      const cabeca = (
        <div>
          <div style={{ fontFamily: P.label, fontSize: 10, lineHeight: 1.7, letterSpacing: ".28em",
                        textTransform: "uppercase", color: P.gold, margin: "0 0 12px" }}>
            {hanCamada[cam]}{"  "}{nomeCamada[cam]}
          </div>
          <h2 style={{ fontFamily: P.serif, fontWeight: 400, margin: 0, color: P.paper,
                       fontSize: wide ? 56 : 40, lineHeight: wide ? (58 / 56) : (44 / 40),
                       letterSpacing: "-.03em", overflowWrap: "anywhere" }}>{titulo}</h2>
          {/* 減 P7 — a frase da camada explica a figura que está logo abaixo
              (quantos pontos, o que os acende) — os números dela vivem nas
              linhas e na figura. Recolhe pela camada ESCOLHIDA: cada uma é o
              seu sistema, com a sua acção confirmada. */}
          <p style={{ fontFamily: P.body, fontSize: 13, lineHeight: 1.75, color: P.muted,
                      margin: "12px 0 0", maxWidth: 380 }}>
            <Explica sistema={"corpo_" + cam} estados={player && player.explicacoes}
                     onRefresh={onPlayerRefresh}>
              {t("corpo_explica_" + cam)}
            </Explica>
          </p>
        </div>
      );

      const seletor = camadas.length > 1 ? (
        <div role="tablist" aria-label={t("corpo_camadas_aria")}
             style={{ display: "flex", flexWrap: "wrap", columnGap: 22, rowGap: 0,
                      borderBottom: "1px solid " + P.line }}>
          {camadas.map(c => {
            const ativo = c === cam;
            const trancada = (c === "transf" && dT && !dT.unlocked);
            return (
              <button key={c} type="button" role="tab" aria-selected={ativo}
                      onClick={() => trocarCamada(c)}
                      style={{ background: "none", border: "none", cursor: "pointer",
                               minHeight: 44, padding: "10px 0", position: "relative",
                               display: "inline-flex", alignItems: "center", gap: 6,
                               fontFamily: P.body, fontSize: 12, letterSpacing: ".06em",
                               color: ativo ? P.paper : P.muted }}>
                {trancada && <span aria-hidden="true" style={{ display: "inline-flex" }}><Mark name="lock" size={12} /></span>}
                {nomeCamada[c]}
                {ativo && <span aria-hidden="true" style={{ position: "absolute", left: 0, right: 0, bottom: -1,
                                                            height: 1, background: P.gold }} />}
              </button>
            );
          })}
        </div>
      ) : null;

      const figura = (
        <CorpoFigura gender={player && player.gender} camada={cam} pontos={pontosFig}
                     sel={sel} acende={acende && acende.camada === cam ? acende.id : null}
                     size={wide ? 440 : 300} legenda={mapaBate ? legenda : null} rotulo={rotuloFig} />
      );

      const leitura = (
        <div>
          {aCarregar && (
            <div role="status" style={{ padding: "12px 0", fontFamily: P.body, fontSize: 14, color: P.muted }}>
              {t("corpo_carregando")}
            </div>
          )}
          {falhou && (
            <div role="alert" style={{ padding: "12px 0" }}>
              <div style={{ fontFamily: P.body, fontSize: 14, lineHeight: (20 / 14), color: P.seal }}>
                {t("corpo_falha")}
              </div>
              <div style={{ marginTop: 10 }}>
                <OndaBtn kind="ghost" onClick={() => { if (cam === "mer") setRecM(x => x + 1); else setRecT(x => x + 1); }}
                         style={{ width: "auto", minWidth: 200 }}>
                  {t("corpo_tentar")}
                </OndaBtn>
              </div>
            </div>
          )}
          {velho && (
            <div style={{ padding: "8px 0", fontFamily: P.body, fontSize: 12, color: P.muted }}>
              {t("corpo_ultima")}
            </div>
          )}
          {lei && !mapaBate && (
            <div style={{ padding: "8px 0", fontFamily: P.body, fontSize: 12, color: P.muted }}>
              {t("corpo_mapa_nao_bate")}
            </div>
          )}
          {bloco && bloco.linhas}
          {bloco && bloco.nota && (
            <div style={{ display: "flex", gap: 8, alignItems: "flex-start", padding: "12px 0 0",
                          fontFamily: P.body, fontSize: 13, lineHeight: 1.6, color: P.muted }}>
              {bloco.notaTom === "trancado" && (
                <span aria-hidden="true" style={{ display: "inline-flex", color: P.gold, marginTop: 2 }}>
                  <Mark name="lock" size={14} />
                </span>
              )}
              <span>{bloco.nota}</span>
            </div>
          )}
          {erro && erro.camada === cam && (
            <div role="alert" style={{ display: "flex", gap: 8, alignItems: "flex-start", padding: "12px 0 0",
                                       fontFamily: P.body, fontSize: 13, lineHeight: 1.6, color: P.seal }}>
              <span aria-hidden="true" style={{ display: "inline-flex", marginTop: 2 }}><Mark name="warn" size={14} /></span>
              <span>{erro.texto}</span>
            </div>
          )}
          {bloco && bloco.acao && (
            <div style={{ marginTop: 18 }}>{bloco.acao}</div>
          )}
          {recibo && recibo.camada === cam && (
            <div aria-live="polite"
                 style={{ marginTop: 18, paddingLeft: 14,
                          borderLeft: "1px solid " + (recibo.tom === "falha" ? P.seal : P.gold) }}>
              <div style={{ fontFamily: P.label, fontSize: 10, letterSpacing: ".22em", textTransform: "uppercase",
                            color: recibo.tom === "falha" ? P.seal : P.gold, marginBottom: 6 }}>
                {recibo.tom === "falha" ? t("corpo_nao_abriu") : t("corpo_confirmado")}
              </div>
              {recibo.linhas.map((ln, i) => (
                <div key={i} style={Object.assign({}, _ONDA_TNUM, { fontSize: 14, lineHeight: (22 / 14),
                                                                   color: P.paper })}>{ln}</div>
              ))}
            </div>
          )}
          {/* os DETALHES depois da acção: a operação fica imediatamente
              próxima da figura (o Astra: "uma operação imediatamente
              próxima"), e o que é contexto vem a seguir */}
          {bloco && bloco.detalhes && bloco.detalhes.length > 0 && (
            <div style={{ marginTop: 22 }}>{bloco.detalhes}</div>
          )}
        </div>
      );

      const consulta = lei ? (
        <div style={{ marginTop: 22 }}>
          <button type="button" aria-expanded={lista} onClick={() => { haptic("select"); setLista(v => !v); }}
                  style={{ background: "none", border: "none", borderBottom: "1px solid " + P.line,
                           cursor: "pointer", minHeight: 44, padding: "8px 0", width: "100%",
                           display: "flex", alignItems: "center", justifyContent: "space-between",
                           fontFamily: P.serif, fontSize: 18, color: P.paper }}>
            <span>{cam === "mer" ? t("corpo_canais") : t("corpo_etapas")} · {lei.pontos.length}</span>
            <span aria-hidden="true" style={{ fontFamily: P.body, fontSize: 12, color: P.muted }}>
              {lista ? t("corpo_fechar_lista") : t("corpo_abrir_lista")}
            </span>
          </button>
          {lista && (
            <ul style={{ listStyle: "none", margin: 0, padding: 0 }}>
              {lei.pontos.map(p => {
                const eSel = sel === p.id;
                return (
                  <li key={p.id}>
                    <button type="button" aria-pressed={eSel}
                            onClick={() => { haptic("select"); setSel(eSel ? null : p.id); }}
                            style={{ width: "100%", minHeight: 44, cursor: "pointer", textAlign: "left",
                                     background: eSel ? "rgba(201,144,58,.08)" : "none",
                                     border: "none", borderBottom: "1px solid " + P.line,
                                     borderLeft: "1px solid " + (eSel ? P.gold : "transparent"),
                                     padding: "8px 10px", display: "flex", alignItems: "center", gap: 12,
                                     fontFamily: P.body, fontSize: 14, color: P.paper }}>
                      <span aria-hidden="true" style={{ width: 10, height: 10, borderRadius: "50%", flexShrink: 0,
                                                        boxSizing: "border-box",
                                                        border: "1.25px solid " + (p.estado === "got" ? P.gold
                                                          : (p.estado === "next" || p.estado === "ritual") ? P.paper
                                                          : "rgba(236,229,216,.45)"),
                                                        background: p.estado === "got" ? P.gold : "transparent" }} />
                      {p.n ? <span style={Object.assign({}, _ONDA_TNUM, { color: P.muted, fontSize: 12, minWidth: 18 })}>{p.n}</span> : null}
                      <span style={{ flex: 1, minWidth: 0 }}>
                        {p.nome}
                        {p.grupo ? <span style={{ color: P.muted, fontSize: 12 }}>{"  " + p.grupo}</span> : null}
                      </span>
                      <span style={{ fontSize: 12, color: p.estado === "got" ? P.gold : P.muted }}>
                        {estadoPalavra[p.estado] || ""}
                      </span>
                    </button>
                  </li>
                );
              })}
            </ul>
          )}
        </div>
      ) : null;

      if (wide) {
        return (
          <section style={{ maxWidth: 1080, margin: "0 auto", padding: "28px 32px 96px" }}>
            <div style={{ display: "grid", gridTemplateColumns: "minmax(320px, 460px) minmax(0, 1fr)",
                          columnGap: 56, alignItems: "start" }}>
              <div style={{ position: "sticky", top: 16 }}>{figura}</div>
              <div style={{ minWidth: 0 }}>
                {cabeca}
                <div style={{ marginTop: 22 }}>{seletor}</div>
                <div style={{ marginTop: 6 }}>{leitura}</div>
                {consulta}
              </div>
            </div>
          </section>
        );
      }
      return (
        <section style={{ padding: "18px 16px 96px" }}>
          {cabeca}
          <div style={{ marginTop: 16 }}>{seletor}</div>
          <div ref={figRef} style={{ marginTop: 14, scrollMarginTop: 8 }}>{figura}</div>
          <div style={{ marginTop: 10 }}>{leitura}</div>
          {consulta}
        </section>
      );
    }

    // O dono da aba. Com a obra ON o Corpo é a figura que acende; com ela OFF,
    // o ramo de sempre, byte a byte (OFF-identidade). Um despachante SEM hooks:
    // a condição pode mudar quando o manifesto chega, e um `return` antes dos
    // hooks do ramo antigo partiria a ordem deles.
    function BodyTemperingTab({ player, onPlayerRefresh }) {
      if (obraOn()) return <CorpoQueAcende player={player} onPlayerRefresh={onPlayerRefresh} />;
      return <BodyTemperingClassic player={player} onPlayerRefresh={onPlayerRefresh} />;
    }

    function BodyTemperingClassic({ player, onPlayerRefresh }) {
      const [reload, setReload] = useState(0);
      const [busy, setBusy] = useState(false);
      const [reveal, setReveal] = useState(null);
      const [errInfo, setErrInfo] = useState(null);
      const { data, loading, error } = useApi("body_tempering/status", null, [reload]);

      // R0–R6 with the body axis ON → THIS tab IS the Mortal Cultivo do Corpo (kills the
      // dead "locked until R7" screen for early players). R7+ falls through to the Nine
      // Transformations below; `main` (flag OFF) → null here → the legacy R7 flow, 57 intact.
      const bcard = player && player.body_cultivation;
      if (featureEnabled("cultivo_corpo_r0") && bcard && bcard.tier_key && !bcard.is_apex) {
        return (
          <div style={{ padding:"4px 2px 80px" }}>
            <BodyCultivationCard player={player} onPlayerRefresh={onPlayerRefresh} />
            {/* MV-4 — os 12 meridianos. Gate no MOUNT (padrão HortaCard): OFF
                → componente nem monta → ZERO requests novos no main. */}
            {featureEnabled("corpo_profundo") && <MeridiansCard onPlayerRefresh={onPlayerRefresh} />}
          </div>
        );
      }

      async function ascend() {
        if (busy) return;
        setBusy(true);
        haptic("warning");
        try {
          const res = await api("body_tempering/ascend");
          if (!res.ok) {
            haptic("error");
            setErrInfo(res);
            setBusy(false);
            return;
          }
          setReveal(res);
          haptic("success");
          setBusy(false);
          setReload(x => x + 1);
          onPlayerRefresh && onPlayerRefresh();
        } catch (e) {
          haptic("error");
          setErrInfo({ reason: e.message });
          setBusy(false);
        }
      }

      if (loading && !data) return <ListSkeleton rows={4} />;
      if (error && !data) return <ErrBanner msg={error} />;
      if (!data) return null;

      if (!data.unlocked) {
        return (
          <Card>
            <div style={{ textAlign:"center", padding:"28px 14px" }}>
              <div style={{ fontSize:54, opacity:.55, marginBottom:8 }}>💪</div>
              <div style={{ fontFamily:"'Cinzel',serif", fontSize:15,
                            color:"var(--gold2)", letterSpacing:.5 }}>
                {t("body_locked_title")}
              </div>
              <div style={{ fontSize:11.5, color:"var(--muted)", marginTop:10, lineHeight:1.55 }}>
                {t("body_locked_hint", { realm: data.min_realm_required })}
              </div>
            </div>
          </Card>
        );
      }

      const ci = data.current_info;
      const nx = data.next;
      const progressPct = nx && nx.progress_required > 0
        ? Math.min(100, (data.body_tempering_progress / nx.progress_required) * 100)
        : 100;

      return (
        <div>
          <Card>
            <div style={{ textAlign:"center", padding:"6px 0 4px" }}>
              <div style={{ fontSize:54, marginBottom:6,
                            filter:"drop-shadow(0 0 14px rgba(var(--gold2-rgb),.5))" }}>
                {ci.emoji || "🪨"}
              </div>
              <div style={{ fontFamily:"'Cinzel',serif", fontSize:18,
                            color:"var(--gold2)", letterSpacing:1, fontWeight:700 }}>
                {safeT(ci.name_key, null, `${t("body_level_label")} ${data.current_level}`)}
              </div>
              <div style={{ fontSize:11, color:"var(--muted)", marginTop:4 }}>
                {t("body_level_short")} {data.current_level} / {data.max_level}
              </div>
              <div style={{ marginTop:6 }}>
                <Badge variant="gold">×{ci.hp_def_mult.toFixed(2)} HP/DEF</Badge>
              </div>
            </div>
          </Card>

          {nx ? (
            <Card>
              <CardTitle left={t("body_next_title", { level: nx.level })} />
              <div style={{ display:"flex", alignItems:"center", gap:10, marginBottom:10 }}>
                <div style={{ fontSize:36 }}>{nx.emoji || "🔥"}</div>
                <div>
                  <div style={{ fontFamily:"'Cinzel',serif", fontSize:13,
                                color:"var(--gold3)", fontWeight:700 }}>
                    {safeT(nx.name_key, null, `${t("body_level_label")} ${nx.level}`)}
                  </div>
                  <div style={{ fontSize:11, color:"var(--muted)", marginTop:2 }}>
                    {t("body_next_mult", { mult: nx.hp_def_mult.toFixed(2) })}
                  </div>
                </div>
              </div>

              <div style={{ marginBottom:10 }}>
                <div style={{ fontSize:10, color:"var(--muted)", marginBottom:4,
                              display:"flex", justifyContent:"space-between" }}>
                  <span>{t("body_progress_label")}</span>
                  <span>{fmtNum(data.body_tempering_progress)} / {fmtNum(nx.progress_required)}</span>
                </div>
                <ProgressBar pct={progressPct} variant="cult" />
              </div>

              <div style={{ display:"grid", gap:6, marginBottom:10 }}>
                <KVRow
                  label={`💰 ${t("body_req_stones")}`}
                  value={`${fmtNum(data.spirit_stones)} / ${fmtNum(nx.cost_stones)} ${data.spirit_stones >= nx.cost_stones ? "✅" : "❌"}`}
                />
                <KVRow
                  label={`⚡ ${t("body_req_qi")}`}
                  value={`${Math.floor(data.qi)} / ${nx.cost_qi} ${data.qi >= nx.cost_qi ? "✅" : "❌"}`}
                />
                <KVRow
                  label={`🥊 ${t("body_req_bp")}`}
                  value={`${fmtNum(data.total_battle_power || player.battle_power || 0)} / ${fmtNum(nx.min_battle_power)} ${(data.total_battle_power || player.battle_power || 0) >= nx.min_battle_power ? "✅" : "❌"}`}
                />
                {nx.min_realm > data.min_realm_required && (
                  <KVRow
                    label={`🌟 ${t("body_req_realm")}`}
                    value={`${data.realm} / ${nx.min_realm} ${data.realm >= nx.min_realm ? "✅" : "❌"}`}
                  />
                )}
                {nx.essence_cost > 0 && (
                  <KVRow
                    label={`✨ ${t("body_req_essence")}`}
                    value={`${data.celestial_essence} / ${nx.essence_cost} ${data.celestial_essence >= nx.essence_cost ? "✅" : "❌"}`}
                  />
                )}
              </div>

              <ActionBtn
                onClick={ascend}
                variant="primary"
                disabled={!nx.can_ascend || busy}
                style={{ width:"100%" }}
              >
                {nx.can_ascend
                  ? t("body_ascend_btn")
                  : safeT(`body_blocked_${nx.blocked_reason_key}`, null, t("body_blocked_generic"))}
              </ActionBtn>

              {errInfo && (
                <div className="err-banner" style={{ marginTop:10 }}>
                  {safeT(`body_blocked_${errInfo.reason}`, null, errInfo.reason || t("foundation_fail"))}
                </div>
              )}
            </Card>
          ) : (
            <Card>
              <div style={{ textAlign:"center", padding:"16px 12px", fontSize:13,
                            color:"var(--gold2)", fontFamily:"'Cinzel',serif" }}>
                {t("body_maxed_title")}
              </div>
              <div style={{ fontSize:11, color:"var(--muted)", textAlign:"center", lineHeight:1.45 }}>
                {t("body_maxed_hint")}
              </div>
            </Card>
          )}

          <Card>
            <CardTitle left={t("body_pill_hint_title")} />
            <div style={{ fontSize:11, color:"var(--muted)", lineHeight:1.5, padding:"4px 2px" }}>
              {t("body_pill_hint_text")}
            </div>
          </Card>

          {/* MV-4 — os canais persistem além de R7. Gate no MOUNT (padrão
              HortaCard): OFF → nem monta → ZERO requests novos no main. */}
          {featureEnabled("corpo_profundo") && <MeridiansCard onPlayerRefresh={onPlayerRefresh} />}

          {reveal && (
            <Modal
              onClose={() => setReveal(null)}
              allowBackdropClose={true}
              title={`💪 ${t("body_ascended_title")}`}
              accent="rgba(var(--gold2-rgb),.55)"
              maxWidth={360}
              footer={
                <ActionBtn onClick={() => setReveal(null)} variant="primary" style={{ width:"100%" }}>
                  {t("foundation_close")}
                </ActionBtn>
              }
            >
              <div style={{ textAlign:"center" }}>
                <div style={{ fontSize:64, marginBottom:8,
                              filter:"drop-shadow(0 0 22px rgba(var(--gold2-rgb),.7))" }}>
                  {reveal.emoji || "🔥"}
                </div>
                <div style={{ fontFamily:"'Cinzel',serif", fontSize:20, color:"var(--gold2)",
                              letterSpacing:1.2, fontWeight:700, marginBottom:6 }}>
                  {safeT(reveal.name_key, null, `${t("body_level_label")} ${reveal.new_level}`)}
                </div>
                <div style={{ fontSize:12, color:"var(--jade)", marginBottom:10 }}>
                  ×{reveal.mult.toFixed(2)} HP/DEF · +{reveal.qi_cap_bonus} {t("qi")} cap
                </div>
                {reveal.body_transformed && (
                  <Badge variant="gold">{t("body_celestial_transform")}</Badge>
                )}
                {/* Progressão Visível — the honest before→after of the temper. */}
                {reveal.power_delta && (
                  <div style={{ textAlign:"left", marginTop:4 }}>
                    <DeltaPanel deltas={reveal.power_delta} order={["display_combat_power", "max_hp"]} />
                  </div>
                )}
              </div>
            </Modal>
          )}
        </div>
      );
    }

    // ─── v14.14i Partner / Dao Partner system 💞 ────────────────────────────
    // Mirror handlers/partner.py (~640 lines). Drill-in via Home card 💞.
    // Chat keys with markdown asterisks are surfaced via the chat i18n bundle
    // (mini-app-side keys are clean plaintext); we use `stripMd` to render
    // chat strings as visual chrome (Cinzel weight does the heavy lifting).
    function stripMd(s) {
      return typeof s === "string" ? s.replace(/\*/g, "") : s;
    }

    function PartnerProposeModal({ onClose, jadeRingCount, onProposed }) {
      const [name, setName] = useState("");
      const [busy, setBusy] = useState(false);
      const [errMsg, setErrMsg] = useState(null);
      const trimmed = name.trim();
      const valid = trimmed.length >= 2 && jadeRingCount > 0;

      async function submit() {
        if (!valid || busy) return;
        setBusy(true);
        setErrMsg(null);
        haptic("warning");
        try {
          const res = await api("partner/propose", { target_dao_name: trimmed });
          if (!res.ok) {
            haptic("error");
            setErrMsg(stripMd(safeT(res.reason, null, t("partner_err_engine"))));
            setBusy(false);
            return;
          }
          haptic("success");
          showToast(t("partner_proposal_sent_toast", { name: res.target_dao_name || trimmed }));
          setBusy(false);
          onProposed && onProposed(res);
        } catch (e) {
          haptic("error");
          setErrMsg(t("partner_err_engine"));
          setBusy(false);
        }
      }

      return (
        <Modal
          onClose={onClose}
          allowBackdropClose={!busy}
          title={`💌 ${t("partner_propose_title")}`}
          accent="rgba(220,120,180,.55)"
          maxWidth={360}
          footer={
            <div style={{ display:"flex", gap:8, width:"100%" }}>
              <ActionBtn onClick={onClose} variant="ghost" style={{ flex:1 }} disabled={busy}>
                {t("partner_cancel_btn_clean")}
              </ActionBtn>
              <ActionBtn onClick={submit} variant="primary" style={{ flex:1 }}
                         disabled={!valid || busy}>
                {busy ? <DotSpinner /> : `💌 ${t("partner_propose_submit_btn")}`}
              </ActionBtn>
            </div>
          }
        >
          <div>
            <div style={{ fontSize:11.5, color:"var(--muted)", marginBottom:10, lineHeight:1.55 }}>
              {stripMd(t("partner_propose_explainer"))}
            </div>
            <div style={{ marginBottom:10, display:"flex", justifyContent:"space-between",
                          fontSize:11.5, color:"var(--gold2)" }}>
              <span>💍 {t("partner_jade_ring_label")}</span>
              <span style={{ fontWeight:700, color: jadeRingCount > 0 ? "var(--jade)" : "var(--red)" }}>
                {jadeRingCount}
              </span>
            </div>
            <input
              type="text"
              maxLength={32}
              value={name}
              onChange={(e) => setName(e.target.value)}
              placeholder={t("partner_dao_name_placeholder")}
              autoFocus
              style={{
                width:"100%", padding:"10px 12px", borderRadius:8, marginBottom:6,
                background:"rgba(0,0,0,.4)", border:"1px solid rgba(220,120,180,.45)",
                color:"var(--text)", fontSize:13, outline:"none",
              }}
            />
            <div style={{ fontSize:10.5, color:"var(--muted)", lineHeight:1.5, marginTop:6 }}>
              {stripMd(t("partner_propose_hint"))}
            </div>
            {errMsg && <ErrBanner msg={errMsg} />}
            {jadeRingCount === 0 && (
              <div className="err-banner" style={{ marginTop:8 }}>
                {stripMd(t("partner_no_ring_short"))}
              </div>
            )}
          </div>
        </Modal>
      );
    }

    function PartnerCutConfirmModal({ partner, onClose, onConfirmed }) {
      const [busy, setBusy] = useState(false);
      const [errMsg, setErrMsg] = useState(null);
      const [doubleCheck, setDoubleCheck] = useState(false);

      async function execute() {
        if (busy) return;
        setBusy(true);
        setErrMsg(null);
        haptic("warning");
        try {
          const res = await api("partner/cut_bond", { confirm: true });
          if (!res.ok) {
            haptic("error");
            setErrMsg(stripMd(safeT(res.reason, null, t("partner_err_engine"))));
            setBusy(false);
            return;
          }
          haptic("error"); // intentional — heartbreak buff applied
          showToast(t("partner_cut_done_toast"));
          setBusy(false);
          onConfirmed && onConfirmed(res);
        } catch (e) {
          haptic("error");
          setErrMsg(t("partner_err_engine"));
          setBusy(false);
        }
      }

      return (
        <Modal
          onClose={onClose}
          allowBackdropClose={!busy}
          title={`✂️ ${t("partner_cut_modal_title")}`}
          accent="rgba(220,60,80,.55)"
          maxWidth={360}
          footer={
            <div style={{ display:"flex", gap:8, width:"100%" }}>
              <ActionBtn onClick={onClose} variant="ghost" style={{ flex:1 }} disabled={busy}>
                {t("partner_cancel_btn_clean")}
              </ActionBtn>
              <ActionBtn
                onClick={() => doubleCheck ? execute() : setDoubleCheck(true)}
                variant="primary"
                style={{ flex:1, background: doubleCheck ? "rgba(220,60,80,.7)" : undefined }}
                disabled={busy}
              >
                {busy ? <DotSpinner />
                       : doubleCheck ? `⚔️ ${t("partner_cut_double_confirm")}`
                                     : `✂️ ${t("partner_cut_first_confirm")}`}
              </ActionBtn>
            </div>
          }
        >
          <div style={{ textAlign:"center", padding:"4px 0 8px" }}>
            <div style={{ fontSize:48, marginBottom:8,
                          filter:"drop-shadow(0 0 16px rgba(220,60,80,.55))" }}>
              💔
            </div>
            <div style={{ fontFamily:"'Cinzel',serif", fontSize:15, color:"var(--gold2)",
                          letterSpacing:.5, marginBottom:6 }}>
              {partner?.partner_dao_name || "—"}
            </div>
            <div style={{ fontSize:11.5, color:"var(--muted)", lineHeight:1.6 }}>
              {stripMd(t("partner_cut_consequences"))}
            </div>
          </div>
          {doubleCheck && (
            <div className="err-banner" style={{ marginTop:8, textAlign:"center" }}>
              {stripMd(t("partner_cut_double_check_hint"))}
            </div>
          )}
          {errMsg && <ErrBanner msg={errMsg} />}
        </Modal>
      );
    }

    function PartnerTab({ player, onPlayerRefresh }) {
      const [reload, setReload] = useState(0);
      const { data, loading, error } = useApi("partner/info", null, [reload]);
      const [proposeOpen, setProposeOpen] = useState(false);
      const [cutOpen, setCutOpen] = useState(false);
      const [busyProp, setBusyProp] = useState(null); // proposal_id while responding
      const [respondErr, setRespondErr] = useState(null);

      useEffect(() => {
        // Best-effort intimacy heartbeat on tab open. Cheap; engine throttles
        // via the 1h sliding window inside increment_intimacy_if_both_online.
        let cancelled = false;
        if (data?.partner) {
          (async () => {
            try {
              const res = await api("partner/intimacy_ping");
              if (cancelled) return;
              if (res?.intimacy_ticked) {
                setReload(x => x + 1);
              }
            } catch { /* silent */ }
          })();
        }
        return () => { cancelled = true; };
      // eslint-disable-next-line react-hooks/exhaustive-deps
      }, [data?.partner?.partner_id]);

      async function respond(proposalId, accept) {
        if (busyProp) return;
        setBusyProp(proposalId);
        setRespondErr(null);
        haptic(accept ? "success" : "warning");
        try {
          const res = await api("partner/respond", { proposal_id: proposalId, accept });
          if (!res.ok) {
            haptic("error");
            setRespondErr(stripMd(safeT(res.reason, null, t("partner_err_engine"))));
            setBusyProp(null);
            setReload(x => x + 1);
            return;
          }
          if (accept && res.partner_dao_name) {
            haptic("success");
            showToast(t("partner_you_accepted_toast", { name: res.partner_dao_name }));
          } else {
            showToast(t("partner_you_rejected_toast"));
          }
          setBusyProp(null);
          setReload(x => x + 1);
          onPlayerRefresh && onPlayerRefresh();
        } catch (e) {
          haptic("error");
          setRespondErr(t("partner_err_engine"));
          setBusyProp(null);
        }
      }

      if (loading && !data) return <ListSkeleton rows={4} />;
      if (error && !data) return <ErrBanner msg={error} />;
      if (!data) return null;

      const p = data.partner;
      const heartbreak = data.heartbreak_remaining_secs > 0;
      const romanticCd = data.romantic_cooldown_remaining_secs > 0;

      return (
        <div>
          {/* ── Header: partner card OR empty state ─────────────────────── */}
          {p ? (
            <Card>
              <div style={{ textAlign:"center", padding:"4px 0 6px" }}>
                <div style={{ fontSize:46, marginBottom:6,
                              filter:"drop-shadow(0 0 14px rgba(220,120,180,.6))" }}>
                  💞
                </div>
                <div style={{ fontFamily:"'Cinzel',serif", fontSize:19,
                              color:"var(--gold2)", letterSpacing:1, fontWeight:700,
                              marginBottom:2 }}>
                  {p.partner_dao_name}
                </div>
                <div style={{ fontSize:11, color:"var(--muted)", marginBottom:8 }}>
                  {safeT(`realm_${p.partner_realm}`, null, `R${p.partner_realm}`)}
                </div>
                <div style={{ display:"flex", gap:6, justifyContent:"center", flexWrap:"wrap" }}>
                  <Badge variant="gold">💍 {t("partner_ring_lvl")} {p.ring_level}</Badge>
                  <Badge variant="jade">💗 {p.intimacy_level} {t("partner_intimacy_unit")}</Badge>
                  <Badge variant="jade">🗓️ {t("partner_days_unit", { days: p.married_days })}</Badge>
                </div>
              </div>

              <div style={{ marginTop:10, display:"grid", gap:6 }}>
                <KVRow
                  label={`💫 ${t("partner_dual_cult_label")}`}
                  value={p.dual_cult_active
                    ? t("partner_dual_cult_active_value")
                    : t("partner_dual_cult_inactive_value")}
                />
                <KVRow
                  label={`🍀 ${t("partner_luck_share_label")}`}
                  value={`+${fmtNum(p.luck_share)}`}
                />
              </div>

              {heartbreak && (
                <div className="err-banner" style={{ marginTop:10 }}>
                  💔 {t("partner_heartbreak_chip", {
                    time: fmtDuration(data.heartbreak_remaining_secs * 1000),
                  })}
                </div>
              )}
            </Card>
          ) : (
            <Card>
              <div style={{ textAlign:"center", padding:"10px 6px" }}>
                <div style={{ fontSize:54, opacity:.55, marginBottom:8 }}>💞</div>
                <div style={{ fontFamily:"'Cinzel',serif", fontSize:16,
                              color:"var(--gold2)", letterSpacing:.5 }}>
                  {t("partner_empty_title")}
                </div>
                <div style={{ fontSize:11.5, color:"var(--muted)", marginTop:8, lineHeight:1.55 }}>
                  {stripMd(t("partner_empty_explainer"))}
                </div>
                <div style={{ marginTop:10, display:"inline-flex", gap:6, alignItems:"center" }}>
                  <Badge variant={data.has_jade_ring ? "jade" : "muted"}>
                    💍 {t("partner_jade_ring_label")}: {data.jade_ring_count}
                  </Badge>
                </div>
                {romanticCd && (
                  <div className="err-banner" style={{ marginTop:10 }}>
                    ⏳ {t("partner_romantic_cooldown_chip", {
                      time: fmtDuration(data.romantic_cooldown_remaining_secs * 1000),
                    })}
                  </div>
                )}
                {heartbreak && (
                  <div className="err-banner" style={{ marginTop:8 }}>
                    💔 {t("partner_heartbreak_chip", {
                      time: fmtDuration(data.heartbreak_remaining_secs * 1000),
                    })}
                  </div>
                )}
              </div>
            </Card>
          )}

          {/* ── Actions card ─────────────────────────────────────────────── */}
          <Card>
            {p ? (
              <ActionBtn
                variant="primary"
                onClick={() => setCutOpen(true)}
                style={{ width:"100%", background:"rgba(220,60,80,.45)" }}
              >
                ✂️ {t("partner_cut_bond_btn_clean")}
              </ActionBtn>
            ) : (
              <ActionBtn
                variant="primary"
                disabled={!data.has_jade_ring || romanticCd || !!data.sent_proposal}
                onClick={() => setProposeOpen(true)}
                style={{ width:"100%" }}
              >
                💌 {t("partner_propose_btn_clean")}
              </ActionBtn>
            )}
            {data.sent_proposal && (
              <div style={{ marginTop:8, fontSize:11, color:"var(--muted)",
                            textAlign:"center", fontStyle:"italic", lineHeight:1.5 }}>
                {stripMd(t("partner_sent_pending", {
                  name: data.sent_proposal.target_dao_name,
                  time: fmtDuration(data.sent_proposal.expires_in_seconds * 1000),
                }))}
              </div>
            )}
          </Card>

          {/* ── Incoming proposals ──────────────────────────────────────── */}
          {data.incoming_proposals && data.incoming_proposals.length > 0 && (
            <Card>
              <CardTitle
                left={t("partner_incoming_title")}
                right={`${data.incoming_proposals.length}`}
              />
              {respondErr && <ErrBanner msg={respondErr} />}
              {data.incoming_proposals.map((prop) => (
                <div key={prop.id} style={{
                  display:"flex", alignItems:"center", gap:8, padding:"8px 10px",
                  marginBottom:6,
                  background:"rgba(220,120,180,.08)",
                  border:"1px solid rgba(220,120,180,.25)", borderRadius:8,
                }}>
                  <div style={{ fontSize:22 }}>💌</div>
                  <div style={{ flex:1, minWidth:0 }}>
                    <div style={{ fontSize:12.5, color:"var(--gold2)",
                                  fontFamily:"'Cinzel',serif", fontWeight:700 }}>
                      {prop.proposer_dao_name}
                    </div>
                    <div style={{ fontSize:10.5, color:"var(--muted)", marginTop:2 }}>
                      {safeT(`realm_${prop.proposer_realm}`, null, `R${prop.proposer_realm}`)}
                      {" · "}
                      ⏳ {fmtDuration(prop.expires_in_seconds * 1000)}
                    </div>
                  </div>
                  <div style={{ display:"flex", gap:4 }}>
                    <button
                      onClick={() => respond(prop.id, true)}
                      disabled={!!busyProp}
                      style={{
                        background:"rgba(126,191,138,.35)",
                        border:"1px solid rgba(126,191,138,.55)",
                        color:"var(--text)", borderRadius:6, padding:"6px 8px",
                        fontSize:14, cursor:"pointer",
                      }}
                    >{ico("✅","check",{ style:{ display:"inline-block", verticalAlign:"-2px" } })}</button>
                    <button
                      onClick={() => respond(prop.id, false)}
                      disabled={!!busyProp}
                      style={{
                        background:"rgba(220,60,80,.30)",
                        border:"1px solid rgba(220,60,80,.55)",
                        color:"var(--text)", borderRadius:6, padding:"6px 8px",
                        fontSize:14, cursor:"pointer",
                      }}
                    >{ico("❌","cross",{ style:{ display:"inline-block", verticalAlign:"-2px" } })}</button>
                  </div>
                </div>
              ))}
            </Card>
          )}

          {/* ── Wuxia narrative hint (always visible for vibe) ──────────── */}
          <Card>
            <div style={{ fontSize:11, color:"var(--muted)", lineHeight:1.55,
                          padding:"4px 2px", fontStyle:"italic" }}>
              {stripMd(t("partner_lore_hint"))}
            </div>
          </Card>

          {proposeOpen && (
            <PartnerProposeModal
              onClose={() => setProposeOpen(false)}
              jadeRingCount={data.jade_ring_count}
              onProposed={() => {
                setProposeOpen(false);
                setReload(x => x + 1);
                onPlayerRefresh && onPlayerRefresh();
              }}
            />
          )}
          {cutOpen && p && (
            <PartnerCutConfirmModal
              partner={p}
              onClose={() => setCutOpen(false)}
              onConfirmed={() => {
                setCutOpen(false);
                setReload(x => x + 1);
                onPlayerRefresh && onPlayerRefresh();
              }}
            />
          )}
        </div>
      );
    }

    // ─── Rebirth Modal (MA-44a) ──────────────────────────────────────────────
    // Shown when the player is at PRESTIGE_REQ_REALM (10) sub_layer 9 — the
    // chat handler `/renascer` is the canonical surface; this mirrors it via
    // /rebirth/preview + /rebirth/attempt. Two phases:
    //   preview     → tech picker + retained/lost summary
    //   confirm     → "really?" gate (rebirth is permanent)
    //   cinematic   → reuses bt-flash + reveal text
    // Mirroring `core.prestige_engine.process_prestige`, the engine is the
    // single source of truth — this modal only assembles the warning copy.
    function RebirthModal({ onClose, onResolved }) {
      const [phase, setPhase] = useState("preview"); // preview|confirm|cine|done
      const [data, setData] = useState(null);
      // Default to "none" (explicit no-retain) so Continue is enabled
      // immediately when preview loads. Owner reported the modal felt stuck
      // because the disabled gate wasn't obvious. User can still pick a
      // technique to retain — the default is just the "skip" option.
      const [pickedTech, setPickedTech] = useState("none");
      const [busy, setBusy] = useState(false);
      const [errInfo, setErrInfo] = useState(null);
      const [result, setResult] = useState(null);

      useEffect(() => {
        let cancelled = false;
        (async () => {
          try {
            const res = await api("rebirth/preview");
            if (!cancelled) setData(res);
          } catch (e) {
            if (!cancelled) setErrInfo({ reason: e.message });
          }
        })();
        return () => { cancelled = true; };
      }, []);

      async function attempt() {
        if (busy || !data?.eligible) return;
        setBusy(true); setErrInfo(null);
        haptic("warning");
        try {
          const techId = (pickedTech === null || pickedTech === "none") ? null : pickedTech;
          const res = await api("rebirth/attempt", { retained_technique_id: techId });
          if (!res.ok) {
            haptic("error");
            setErrInfo(res);
            setBusy(false);
            setPhase("preview");
            return;
          }
          setResult(res);
          setPhase("cine");
          setTimeout(() => {
            haptic("success");
            const msg = t("rebirth_success_toast", { level: res.prestige_level });
            showToast(msg, "ok");
            onResolved && onResolved(res);
            onClose();
          }, 2400);
        } catch (e) {
          haptic("error");
          setErrInfo({ reason: e.message });
          setBusy(false);
          setPhase("preview");
        }
      }

      const backdropClick = (phase === "preview" || phase === "confirm") ? onClose : undefined;

      function Cinematic() {
        if (phase !== "cine" || !result) return null;
        return (
          <div style={{
            position:"fixed", inset:0, zIndex:80,
            display:"grid", placeItems:"center",
            pointerEvents:"none",
            background:"radial-gradient(circle at 50% 50%, rgba(255,255,240,.92) 0%, rgba(50,30,100,.85) 60%, rgba(8,4,20,.95) 100%)",
            animation:"bt-shake-screen .6s linear",
          }}>
            <div style={{
              textAlign:"center", animation:"bt-reveal 1.6s cubic-bezier(.2,.8,.2,1) forwards",
            }}>
              <div style={{ fontSize:88, marginBottom:8, filter:"drop-shadow(0 0 28px var(--gold2))" }}>🌌</div>
              <div style={{
                fontFamily:"'Cinzel',serif", fontSize:30, fontWeight:700,
                color:"var(--gold3)", letterSpacing:1.8,
                textShadow:"0 0 26px var(--gold2), 0 0 48px rgba(255,255,255,.3)",
              }}>
                {t("rebirth_cine_title", { level: result.prestige_level })}
              </div>
              <div style={{ fontFamily:"'Cinzel',serif", fontSize:14, color:"var(--gold)", marginTop:10, letterSpacing:1 }}>
                {result.title}
              </div>
            </div>
          </div>
        );
      }

      // MA-MODAL — split footer per phase. preview shows Cancel + Continue;
      // confirm shows Back + Confirm. Cinematic stays as a separate full-
      // screen overlay (not an in-modal phase) per non-objectives.
      const previewFooter = data && phase === "preview" ? (
        <div style={{ display:"flex", gap:8 }}>
          <ActionBtn onClick={onClose} variant="ghost" style={{ flex:1 }} disabled={busy}>
            {t("btn_cancel")}
          </ActionBtn>
          <ActionBtn onClick={() => setPhase("confirm")} variant="primary"
                     style={{ flex:1.4 }} disabled={!data.eligible || busy}>
            {t("rebirth_continue")}
          </ActionBtn>
        </div>
      ) : null;
      const confirmFooter = data && phase === "confirm" ? (
        <div style={{ display:"flex", gap:8 }}>
          <ActionBtn onClick={() => setPhase("preview")} variant="ghost" style={{ flex:1 }} disabled={busy}>
            {t("rebirth_back")}
          </ActionBtn>
          <ActionBtn onClick={attempt} variant="danger"
                     style={{ flex:1.4 }} disabled={busy}>
            {busy ? <DotSpinner /> : t("rebirth_confirm_btn")}
          </ActionBtn>
        </div>
      ) : null;

      // During cinematic, hide the modal so only the overlay shows.
      const modalOpen = (phase === "preview" || phase === "confirm");

      return (
        <>
          {modalOpen && (
            <Modal
              onClose={backdropClick}
              allowBackdropClose={!!backdropClick}
              title={`🌌 ${t("rebirth_modal_title")}`}
              accent="rgba(var(--gold2-rgb),.55)"
              maxWidth={400}
              cardStyle={{
                background:"linear-gradient(180deg,rgba(35,18,68,.96),rgba(13,6,28,.99))",
                boxShadow:"0 20px 60px rgba(0,0,0,.7), 0 0 32px rgba(var(--gold2-rgb),.35)",
              }}
              footer={previewFooter || confirmFooter}
            >
              {!data && !errInfo && (
                <div style={{ padding:"22px 0", textAlign:"center", color:"var(--muted)", fontSize:12 }}>
                  <DotSpinner /><div style={{ marginTop:8 }}>{t("rebirth_loading")}</div>
                </div>
              )}

              {data && phase === "preview" && (
                <>
                  <div style={{
                    marginTop:12, padding:"10px 12px",
                    background:"rgba(0,0,0,.3)", border:"1px dashed rgba(var(--gold2-rgb),.3)",
                    borderRadius:10, textAlign:"center",
                  }}>
                    <div style={{ fontSize:10, color:"var(--muted)", letterSpacing:1, textTransform:"uppercase" }}>
                      {t("rebirth_prestige_level_label")}
                    </div>
                    <div style={{ marginTop:6, fontSize:14, fontFamily:"'Cinzel',serif", color:"var(--gold3)" }}>
                      {t("rebirth_level_arrow", { from: data.current_prestige_level, to: data.next_prestige_level })}
                    </div>
                    <div style={{ marginTop:4, fontSize:11, color:"var(--gold3)" }}>
                      {data.next_title}
                    </div>
                  </div>

                  <div style={{ marginTop:12, display:"grid", gap:6 }}>
                    <KVRow label={t("rebirth_cb_mult")}
                           value={`+${data.current_multiplier_pct}% → +${data.next_multiplier_pct}%`} />
                    <KVRow label={t("rebirth_pp_label")}
                           value={`${fmtNum(data.current_prestige_points)} → ${fmtNum(data.prestige_points_after)}`} />
                    <KVRow label={t("rebirth_dao_completed")}
                           value={fmtNum(data.completed_dao_count)} />
                  </div>

                  {/* Retained vs lost — quick scannable summary. */}
                  <div style={{ marginTop:12, padding:"8px 10px", borderRadius:8,
                                background:"rgba(var(--jade-rgb),.08)", border:"1px solid rgba(var(--jade-rgb),.25)" }}>
                    <div style={{ fontSize:10, color:"var(--jade)", letterSpacing:.5, fontWeight:700, marginBottom:4 }}>
                      {t("rebirth_retained_title")}
                    </div>
                    <div style={{ fontSize:11, color:"var(--text)", lineHeight:1.5 }}>
                      {t("rebirth_retained_body")}
                    </div>
                  </div>
                  <div style={{ marginTop:8, padding:"8px 10px", borderRadius:8,
                                background:"rgba(var(--warn-rgb),.08)", border:"1px solid rgba(var(--warn-rgb),.3)" }}>
                    <div style={{ fontSize:10, color:"var(--warn)", letterSpacing:.5, fontWeight:700, marginBottom:4 }}>
                      {t("rebirth_lost_title")}
                    </div>
                    <div style={{ fontSize:11, color:"var(--text)", lineHeight:1.5 }}>
                      {t("rebirth_lost_body")}
                    </div>
                  </div>

                  {/* QoL 09/08 Item D (report [jogador]) — a geografia ANTES do tap.
                      Renascer põe realm 0 e NÃO muda o continente: com
                      `dungeons_regionais` ON, quem renasce em Mòyǔ fica até ao
                      reino 5 sem UMA porta. String server-resolved (a mesma do
                      `/renascer`); "" quando não há nada a dizer. */}
                  {data.portal_warning && (
                    <div style={{ marginTop:8, padding:"8px 10px", borderRadius:8,
                                  background:"rgba(239,68,68,.08)", border:"1px solid rgba(239,68,68,.35)" }}>
                      <div style={{ fontSize:11, color:"var(--text)", lineHeight:1.5 }}>
                        {data.portal_warning}
                      </div>
                    </div>
                  )}

                  {/* Technique picker — choose ONE to retain. */}
                  <div style={{ marginTop:12 }}>
                    <div style={{ fontSize:11, color:"var(--muted)", marginBottom:6 }}>
                      {t("rebirth_pick_tech")}
                    </div>
                    <div style={{ display:"flex", flexDirection:"column", gap:6, maxHeight:180, overflowY:"auto" }}>
                      {(data.techniques || []).map(tk => {
                        const active = pickedTech === tk.id;
                        return (
                          <button key={tk.id} onClick={() => { haptic("select"); setPickedTech(tk.id); }}
                            style={{
                              padding:"7px 10px", borderRadius:8,
                              border: active ? "1px solid var(--gold)" : "1px solid rgba(255,255,255,.08)",
                              background: active ? "rgba(var(--gold2-rgb),.12)" : "rgba(0,0,0,.3)",
                              color:"var(--text)", textAlign:"left", cursor:"pointer",
                              display:"flex", alignItems:"center", gap:8,
                            }}>
                            <span style={{ fontSize:18 }}>{tk.emoji}</span>
                            <span style={{ flex:1, fontSize:12, fontWeight:600 }}>{tk.name}</span>
                            <span style={{ fontSize:10, color:"var(--muted)" }}>{t("level_short")} {tk.mastery_level}</span>
                          </button>
                        );
                      })}
                      <button onClick={() => { haptic("select"); setPickedTech("none"); }}
                        style={{
                          padding:"7px 10px", borderRadius:8,
                          border: pickedTech === "none" ? "1px solid var(--gold)" : "1px solid rgba(255,255,255,.08)",
                          background: pickedTech === "none" ? "rgba(var(--gold2-rgb),.12)" : "rgba(0,0,0,.3)",
                          color:"var(--muted)", textAlign:"left", cursor:"pointer", fontSize:12,
                        }}>
                        ⊘ {t("rebirth_no_tech")}
                      </button>
                    </div>
                  </div>

                  {!data.eligible && data.blockers?.length > 0 && (
                    <div className="err-banner" style={{ marginTop:10 }}>
                      {t("rebirth_blocker_realm", {
                        req_realm: data.blockers[0].req_realm,
                        req_sub: data.blockers[0].req_sub_layer,
                      })}
                    </div>
                  )}

                  {errInfo && (
                    <div className="err-banner" style={{ marginTop:10 }}>
                      {errInfo.reason === "not_eligible" ? t("rebirth_blocker_realm",
                        { req_realm: data.req_realm, req_sub: data.req_sub_layer })
                        : (errInfo.reason || t("rebirth_fail"))}
                    </div>
                  )}
                </>
              )}

              {data && phase === "confirm" && (
                <div style={{
                  padding:"12px 14px",
                  background:"rgba(245,68,68,.08)", border:"1px solid rgba(239,68,68,.4)",
                  borderRadius:10, textAlign:"center",
                }}>
                  <div style={{ fontSize:28, marginBottom:6, ...(markOn("warn") ? { display:"grid", placeItems:"center" } : {}) }}>{ico("⚠️","warn",{ size:30 })}</div>
                  <div style={{ fontFamily:"'Cinzel',serif", fontSize:13, color:"#fda4af", letterSpacing:.6 }}>
                    {t("rebirth_confirm_title")}
                  </div>
                  <div style={{ marginTop:8, fontSize:12, color:"var(--text)", lineHeight:1.5 }}>
                    {t("rebirth_confirm_body")}
                  </div>
                  {/* Item D — o gate "really?" é o ÚLTIMO ecrã antes do
                      irreversível; o aviso da geografia repete-se aqui de
                      propósito (quem salta o preview não pode perdê-lo). */}
                  {data.portal_warning && (
                    <div style={{ marginTop:10, fontSize:11.5, color:"#fecaca", lineHeight:1.5 }}>
                      {data.portal_warning}
                    </div>
                  )}
                </div>
              )}

              {errInfo && !data && (
                <div className="err-banner" style={{ marginTop:14 }}>
                  {errInfo.reason || t("rebirth_fail")}
                </div>
              )}
            </Modal>
          )}
          <Cinematic />
        </>
      );
    }

    // ─── Prestige Shop Modal (Sprint v14.14c) ───────────────────────────────
    // Drill-in via CultivationTab card (gate prestige_level ≥ 1). Lists the
    // canonical catalog from `core.prestige_shop_engine.PRESTIGE_SHOP_CATALOG`
    // grouped by category, with per-item state (locked / cap_reached /
    // affordable). Tap → confirm sub-screen → buy. Engine returns the refreshed
    // shop view so we don't re-fetch.
    function PrestigeShopModal({ onClose, onChanged }) {
      const [data, setData] = useState(null);
      const [errMsg, setErrMsg] = useState(null);
      const [picked, setPicked] = useState(null); // item id pending confirm
      const [busy, setBusy] = useState(false);
      const [reloadKey, setReloadKey] = useState(0);

      useEffect(() => {
        let cancelled = false;
        (async () => {
          try {
            setErrMsg(null);
            const res = await api("prestige/shop");
            if (!cancelled) setData(res);
          } catch (e) {
            if (!cancelled) setErrMsg(e.message);
          }
        })();
        return () => { cancelled = true; };
      }, [reloadKey]);

      function reasonText(reason, extra) {
        if (reason === "prestige_locked") return t("prestige_shop_err_locked", { min: extra?.min_prestige ?? 0 });
        if (reason === "cap_reached") return t("prestige_shop_err_cap");
        if (reason === "not_enough_points") return t("prestige_shop_err_short", { cost: extra?.cost ?? 0, have: extra?.have ?? 0 });
        if (reason === "unknown_item") return t("prestige_shop_err_unknown");
        return reason || t("prestige_shop_err_unknown");
      }

      async function buy(itemId) {
        if (busy) return;
        setBusy(true); setErrMsg(null);
        haptic("warning");
        try {
          const res = await api("prestige/buy", { item_id: itemId });
          if (!res.ok) {
            haptic("error");
            setErrMsg(reasonText(res.reason, res));
            setBusy(false);
            return;
          }
          haptic("success");
          const name = t(`prestige_shop_item_${itemId}_name`);
          showToast(t("prestige_shop_bought_toast", { name }), "ok");
          // v15.1.5-hf5 — when the purchase auto-equips a title (player
          // had no active title), surface a second confirmation toast so
          // the player understands the header just changed. Without this
          // they'd buy a title and wonder why nothing visually changed.
          if (res.auto_equipped_title) {
            setTimeout(() => {
              showToast(t("prestige_shop_title_auto_equipped", {
                title: res.auto_equipped_title,
              }), "ok");
            }, 350);
          }
          // Server returned the refreshed view — use it directly.
          if (res.shop) setData(res.shop);
          else setReloadKey(x => x + 1);
          setPicked(null);
          setBusy(false);
          onChanged && onChanged(res);
        } catch (e) {
          haptic("error");
          setErrMsg(e.message);
          setBusy(false);
        }
      }

      // v15.1.5-hf5 — manually equip / unequip a prestige title from the
      // shop modal (mirrors the achievements equip endpoint, which is the
      // canonical one — works for any title in the player's merged unlocked
      // list, prestige + VIP + achievement).
      async function equipPrestigeTitle(title) {
        if (busy) return;
        setBusy(true); setErrMsg(null);
        try {
          const res = await api("achievements/equip_title", { title });
          if (!res.ok) {
            haptic("error");
            showToast(t("prestige_shop_title_equip_failed"), "err");
            setBusy(false);
            return;
          }
          haptic("success");
          showToast(title
            ? t("prestige_shop_title_equipped_toast", { title })
            : t("prestige_shop_title_unequipped_toast"));
          setReloadKey(x => x + 1);
          setBusy(false);
          onChanged && onChanged(res);
        } catch (e) {
          haptic("error");
          setErrMsg(e.message);
          setBusy(false);
        }
      }

      const pickedItem = data && picked
        ? (data.items || []).find(it => it.id === picked)
        : null;

      function renderList() {
        if (!data && !errMsg) {
          return (
            <div style={{ padding:"22px 0", textAlign:"center", color:"var(--muted)", fontSize:12 }}>
              <DotSpinner /><div style={{ marginTop:8 }}>{t("prestige_shop_loading")}</div>
            </div>
          );
        }
        if (errMsg && !data) {
          return <div className="err-banner">{errMsg}</div>;
        }
        const items = data?.items || [];
        if (!items.length) {
          return <div style={{ padding:"18px 0", textAlign:"center", color:"var(--muted)", fontSize:12 }}>{t("prestige_shop_empty")}</div>;
        }
        // v15.1.5-hf5 — Title Manager block. Shows every prestige title
        // the player owns + an Equip / Equipped state. Resolves the owner
        // bug "compraram títulos e não receberam" — players can now see
        // exactly which titles they own and swap freely.
        const titleOpts = data?.prestige_title_options || [];
        const ownedTitles = titleOpts.filter(o => o.owned);
        const activeTitle = data?.active_title || "";

        const cats = ["permanent", "consumable", "title"];
        return (
          <div style={{ display:"grid", gridTemplateColumns:"minmax(0, 1fr)", gap:14 }}>
            {ownedTitles.length > 0 && (
              <div>
                <div style={{
                  fontSize:10.5, color:"var(--gold3)", letterSpacing:1.2,
                  textTransform:"uppercase", fontFamily:"'Cinzel',serif",
                  marginBottom:6,
                }}>
                  {t("prestige_shop_title_manager_header")}
                </div>
                <div style={{ display:"grid", gap:6 }}>
                  {ownedTitles.map(opt => (
                    <div key={opt.item_id} style={{
                      display:"flex", alignItems:"center", gap:8,
                      padding:"8px 10px", borderRadius:8,
                      background: opt.equipped
                        ? "rgba(var(--jade-rgb),.08)"
                        : "rgba(0,0,0,.3)",
                      border: `1px solid ${opt.equipped ? "rgba(var(--jade-rgb),.5)" : "rgba(var(--gold2-rgb),.32)"}`,
                    }}>
                      <span style={{ fontSize:18 }}>{opt.emoji}</span>
                      <span style={{ flex:1, fontSize:12, color:"var(--text)",
                                     fontFamily:"'Cinzel',serif" }}>
                        {opt.title}
                      </span>
                      {opt.equipped ? (
                        <button onClick={() => equipPrestigeTitle(null)} disabled={busy}
                                style={{
                                  padding:"5px 10px", borderRadius:6, cursor:"pointer",
                                  background:"rgba(var(--red-rgb),.15)",
                                  border:"1px solid rgba(var(--red-rgb),.4)",
                                  color:"var(--red2)", fontSize:10.5,
                                  fontFamily:"'Cinzel',serif",
                                }}>
                          {t("prestige_shop_title_btn_unequip")}
                        </button>
                      ) : (
                        <button onClick={() => equipPrestigeTitle(opt.title)} disabled={busy}
                                style={{
                                  padding:"5px 10px", borderRadius:6, cursor:"pointer",
                                  background:"rgba(var(--gold2-rgb),.18)",
                                  border:"1px solid rgba(var(--gold2-rgb),.45)",
                                  color:"var(--gold3)", fontSize:10.5,
                                  fontFamily:"'Cinzel',serif",
                                }}>
                          {t("prestige_shop_title_btn_equip")}
                        </button>
                      )}
                    </div>
                  ))}
                </div>
                {activeTitle && (
                  <div style={{ marginTop:6, fontSize:10.5, color:"var(--muted)",
                                textAlign:"center", fontStyle:"italic" }}>
                    {t("prestige_shop_title_currently_equipped", { title: activeTitle })}
                  </div>
                )}
              </div>
            )}
            {cats.map(cat => {
              const slice = items.filter(it => it.category === cat);
              if (!slice.length) return null;
              return (
                <div key={cat}>
                  <div style={{
                    fontSize:10.5, color:"var(--gold3)", letterSpacing:1.2,
                    textTransform:"uppercase", fontFamily:"'Cinzel',serif",
                    marginBottom:6,
                  }}>
                    {t(`prestige_shop_cat_${cat}`)}
                  </div>
                  <div style={{ display:"grid", gap:8 }}>
                    {slice.map(it => {
                      const name = t(`prestige_shop_item_${it.id}_name`);
                      const desc = t(`prestige_shop_item_${it.id}_desc`);
                      const disabled = it.locked || it.cap_reached || !it.affordable;
                      const badge = it.locked
                        ? t("prestige_shop_locked_label")
                        : it.cap_reached
                          ? t("prestige_shop_owned_label")
                          : `${it.cost} PP`;
                      const accent = it.locked
                        ? "rgba(160,160,160,.45)"
                        : it.cap_reached
                          ? "rgba(var(--jade-rgb),.5)"
                          : it.affordable
                            ? "rgba(var(--gold2-rgb),.55)"
                            : "rgba(239,68,68,.45)";
                      return (
                        <button key={it.id}
                          onClick={() => { if (!disabled) { haptic("select"); setPicked(it.id); } }}
                          disabled={disabled}
                          style={{
                            textAlign:"left", padding:"10px 12px", borderRadius:10,
                            border:`1px solid ${accent}`,
                            background: it.cap_reached
                              ? "rgba(var(--jade-rgb),.06)"
                              : it.locked
                                ? "rgba(0,0,0,.35)"
                                : "rgba(0,0,0,.3)",
                            color: disabled ? "var(--muted)" : "var(--text)",
                            cursor: disabled ? "not-allowed" : "pointer",
                            opacity: disabled && !it.cap_reached ? 0.7 : 1,
                            display:"grid", gap:4,
                          }}>
                          <div style={{ display:"flex", alignItems:"center", gap:8 }}>
                            <span style={{ fontSize:20 }}>{it.emoji}</span>
                            <span style={{ flex:1, minWidth:0,
                                           fontFamily:"'Cinzel',serif", fontSize:13, fontWeight:700,
                                           color: it.cap_reached ? "var(--jade)" :
                                                  it.locked ? "var(--muted)" : "var(--gold2)" }}>
                              {name}
                            </span>
                            <span style={{
                              fontSize:10.5, fontWeight:700,
                              padding:"3px 8px", borderRadius:99,
                              background:"rgba(0,0,0,.4)",
                              border:`1px solid ${accent}`,
                              color: it.cap_reached ? "var(--jade)" :
                                     it.locked ? "var(--muted)" :
                                     it.affordable ? "var(--gold3)" : "var(--red)",
                            }}>
                              {badge}
                            </span>
                          </div>
                          <div style={{ fontSize:11, lineHeight:1.5, color:"var(--muted)" }}>
                            {desc}
                          </div>
                          {(it.max_purchases > 0 || it.purchased_count > 0) && (
                            <div style={{ display:"flex", gap:6, fontSize:10, color:"var(--muted)" }}>
                              {it.max_purchases > 0 && (
                                <span>{t("prestige_shop_max_label", { cap: it.max_purchases })}</span>
                              )}
                              {it.purchased_count > 0 && (
                                <span>· {t("prestige_shop_purchased_count", { count: it.purchased_count })}</span>
                              )}
                            </div>
                          )}
                        </button>
                      );
                    })}
                  </div>
                </div>
              );
            })}
          </div>
        );
      }

      function renderConfirm() {
        if (!pickedItem) return null;
        const name = t(`prestige_shop_item_${pickedItem.id}_name`);
        const desc = t(`prestige_shop_item_${pickedItem.id}_desc`);
        return (
          <div style={{ display:"grid", gap:12 }}>
            <div style={{
              padding:"14px 12px", borderRadius:12,
              background:"linear-gradient(180deg,rgba(35,18,68,.92),rgba(13,6,28,.96))",
              border:"1px solid rgba(var(--gold2-rgb),.4)", textAlign:"center",
            }}>
              <div style={{ fontSize:48, marginBottom:4 }}>{pickedItem.emoji}</div>
              <div style={{ fontFamily:"'Cinzel',serif", fontSize:15, fontWeight:700,
                            color:"var(--gold3)", letterSpacing:.8 }}>
                {name}
              </div>
              <div style={{ marginTop:8, fontSize:11.5, color:"var(--text)", lineHeight:1.55 }}>
                {desc}
              </div>
            </div>
            <KVRow label={t("prestige_shop_modal_title")}
                   value={`${pickedItem.cost} PP`} />
            {pickedItem.max_purchases > 0 && (
              <KVRow label={t("prestige_shop_max_label", { cap: pickedItem.max_purchases })}
                     value={t("prestige_shop_purchased_count", { count: pickedItem.purchased_count })} />
            )}
            {errMsg && <div className="err-banner">{errMsg}</div>}
          </div>
        );
      }

      const subtitle = data
        ? t("prestige_shop_header_subtitle", { pp: data.prestige_points, p_level: data.prestige_level })
        : null;

      const footer = pickedItem ? (
        <div style={{ display:"flex", gap:8 }}>
          <ActionBtn onClick={() => { setPicked(null); setErrMsg(null); }}
                     variant="ghost" style={{ flex:1 }} disabled={busy}>
            {t("btn_back")}
          </ActionBtn>
          <ActionBtn onClick={() => buy(pickedItem.id)} variant="primary"
                     style={{ flex:1.4 }} disabled={busy}>
            {busy ? <DotSpinner /> : `${t("prestige_shop_btn_buy")} — ${pickedItem.cost} PP`}
          </ActionBtn>
        </div>
      ) : (
        <div style={{ display:"flex", gap:8 }}>
          <ActionBtn onClick={onClose} variant="ghost" style={{ flex:1 }}>
            {t("prestige_shop_btn_close")}
          </ActionBtn>
        </div>
      );

      return (
        <Modal
          onClose={onClose}
          allowBackdropClose={!pickedItem && !busy}
          title={`🛍️ ${t("prestige_shop_modal_title")}`}
          subtitle={subtitle}
          accent="rgba(var(--gold2-rgb),.55)"
          maxWidth={460}
          cardStyle={{
            background:"linear-gradient(180deg,rgba(28,14,55,.96),rgba(10,4,22,.99))",
            boxShadow:"0 20px 60px rgba(0,0,0,.7), 0 0 32px rgba(var(--gold2-rgb),.28)",
          }}
          footer={footer}
        >
          {pickedItem ? renderConfirm() : renderList()}
        </Modal>
      );
    }

    // Sprint 4 — Horta 灵田 (Campo Espiritual). Self-contained card: own poll of
    // world/garden, plant/harvest actions, and the Mortal temper-progress bar.
    // Rendered only inside a `cultivo_corpo_r0` world (the parent gates featureEnabled);
    // returns null on main (garden_locked → ok:false) and at R7+ (is_apex).
    function HortaCard({ onPlayerRefresh }) {
      const [tick, setTick] = useState(0);
      const [busy, setBusy] = useState(false);
      const [pickSlot, setPickSlot] = useState(null);  // slot index showing the herb picker
      const g = useApi("world/garden", null, [tick]);
      useVisibleInterval(() => setTick(x => x + 1), 5000);
      const data = g.data;
      if (!data || !data.ok || data.is_apex) return null;

      function fmtSecs(s) {
        s = Math.max(0, Math.floor(s || 0));
        if (s >= 3600) { const m = Math.floor((s % 3600) / 60); return Math.floor(s / 3600) + "h" + (m ? m + "m" : ""); }
        if (s >= 60) return Math.floor(s / 60) + "m";
        return s + "s";
      }

      async function act(endpoint, body, okEmoji, okMsg) {
        if (busy) return null;
        setBusy(true); setPickSlot(null);
        try {
          const res = await api(endpoint, body || {});
          if (res && res.ok) {
            if (okMsg) showToast(okEmoji + " " + okMsg, "ok");
            if (onPlayerRefresh) onPlayerRefresh();
            setTick(x => x + 1);
          } else {
            showToast("⚠️ " + safeT((res && res.reason) || "err_engine", null, t("err_engine") || "engine"), "err");
          }
          return res;
        } catch (e) {
          showToast(t("err_engine") || "engine", "err");
          return null;
        } finally { setBusy(false); }
      }

      const progPct = data.progress_required ? Math.min(100, Math.round((data.temper_progress / data.progress_required) * 100)) : 0;
      const plotBox = { display:"flex", flexDirection:"column", alignItems:"center", gap:4, padding:"10px 6px", borderRadius:10, border:"1px solid var(--border,#2a2a3a)", background:"rgba(255,255,255,.04)", minHeight:78, justifyContent:"center" };

      return (
        <Card>
          <CardTitle left={"🌾 " + t("garden_title")} />
          <div style={{ fontSize:11, color:"var(--muted)", marginBottom:10, lineHeight:1.4 }}>{t("garden_subtitle")}</div>

          {data.progress_required != null && (
            <div style={{ marginBottom:12 }}>
              <div style={{ display:"flex", justifyContent:"space-between", fontSize:10.5, marginBottom:4 }}>
                <span style={{ color:"var(--muted)" }}>{t("garden_progress")}</span>
                <span style={{ color: data.progress_ready ? "var(--jade)" : "var(--muted)", fontFamily:"'Cinzel',serif" }}>
                  {data.temper_progress}/{data.progress_required}{data.progress_ready ? " ⚡" : ""}
                </span>
              </div>
              <div style={{ height:7, borderRadius:5, background:"rgba(255,255,255,.07)", overflow:"hidden" }}>
                <div style={{ height:"100%", width: progPct + "%", borderRadius:5, background:"linear-gradient(90deg, var(--jade), var(--gold3))" }} />
              </div>
              {data.progress_ready && (
                <div style={{ fontSize:10, color:"var(--jade)", marginTop:5 }}>⚡ {t("garden_ready_discount")}</div>
              )}
            </div>
          )}

          <div style={{ display:"grid", gridTemplateColumns:"repeat(2, 1fr)", gap:8 }}>
            {data.plots.map(function (p) {
              if (p.state === "empty") {
                if (pickSlot === p.slot) {
                  return (
                    <div key={p.slot} style={{ ...plotBox, alignItems:"stretch", justifyContent:"flex-start", gridColumn:"1 / -1" }}>
                      {data.catalog.map(function (h) {
                        return (
                          <button key={h.herb_key} disabled={busy || !h.can_afford}
                            onClick={() => act("world/garden_plant", { slot: p.slot, herb_key: h.herb_key }, "🌱", t("garden_planted"))}
                            style={{ display:"flex", justifyContent:"space-between", alignItems:"center", gap:6, padding:"7px 9px", marginBottom:4, borderRadius:8, border:"1px solid var(--border,#2a2a3a)", background: h.can_afford ? "rgba(120,200,140,.08)" : "rgba(255,255,255,.03)", color: h.can_afford ? "var(--text)" : "var(--muted)", fontSize:11, cursor: h.can_afford ? "pointer" : "default", width:"100%" }}>
                            <span>{h.emoji} {safeT("herb_" + h.herb_key, null, h.herb_key)}</span>
                            <span style={{ fontSize:10, color:"var(--muted)" }}>🪨{fmtNum(h.cost_stones)} · +{h.temper_progress} · {fmtSecs(h.grow_seconds)}</span>
                          </button>
                        );
                      })}
                      <button onClick={() => setPickSlot(null)} style={{ fontSize:11, color:"var(--muted)", background:"none", border:"none", cursor:"pointer", marginTop:2 }}>✕ {t("btn_back")}</button>
                    </div>
                  );
                }
                return (
                  <button key={p.slot} disabled={busy} onClick={() => setPickSlot(p.slot)}
                    style={{ ...plotBox, borderStyle:"dashed", cursor:"pointer", color:"var(--muted)", fontSize:13 }}>
                    ➕<span style={{ fontSize:10 }}>{t("garden_plant_btn")}</span>
                  </button>
                );
              }
              return (
                <div key={p.slot} style={plotBox}>
                  <div style={{ fontSize:22 }}>{p.herb_emoji}</div>
                  <div style={{ fontSize:10, color:"var(--muted)" }}>{safeT("herb_" + p.herb_key, null, p.herb_key)}</div>
                  {p.state === "ready" ? (
                    <button disabled={busy} onClick={() => act("world/garden_harvest", { slot: p.slot }, "🌾", t("garden_harvested", { n: p.temper_progress }))}
                      style={{ fontSize:10.5, padding:"4px 10px", borderRadius:8, border:"none", background:"linear-gradient(90deg, var(--jade), var(--gold3))", color:"#102015", fontWeight:600, cursor:"pointer" }}>
                      🌾 {t("garden_harvest_btn")} +{p.temper_progress}
                    </button>
                  ) : (
                    <div style={{ fontSize:10.5, color:"var(--gold3)" }}>⏳ {fmtSecs(p.remaining_seconds)}</div>
                  )}
                </div>
              );
            })}
          </div>

          {/* Sprint 5 — Caça 狩猎 (BC-3): the 2nd input. Beast expeditions drop
              hunt_essence; refine it into the SAME Mortal temper progress. */}
          {data.hunt && !data.hunt.is_apex && (
            <div style={{ marginTop:12, paddingTop:10, borderTop:"1px solid var(--border,#2a2a3a)" }}>
              <div style={{ fontSize:11.5, color:"var(--text)", marginBottom:3 }}>
                🏹 {t("hunt_title")} — <b>{data.hunt.hunt_essence}</b> {t("hunt_essence")}
              </div>
              <div style={{ fontSize:10, color:"var(--muted)", marginBottom:7, lineHeight:1.4 }}>{t("hunt_subtitle")}</div>
              <ActionBtn variant="primary" disabled={busy || !data.hunt.can_refine}
                onClick={() => act("world/hunt_refine", {}, "🏹", t("hunt_refined", { n: data.hunt.refine_yield }))}
                style={{ width:"100%" }}>
                {t("hunt_refine_btn", { cost: data.hunt.refine_cost, yld: data.hunt.refine_yield })}
              </ActionBtn>
            </div>
          )}

          {/* Sprint 6 — Ambiental 环境: the 3rd input. Extreme-environment SITES
              temper the flesh — situational (be in the site's continent) + a global
              cooldown (no stone cost). Same Mortal temper progress (never qi). The
              full site map is always shown (Lei §1 — you always see where to roam). */}
          {data.environment && !data.environment.is_apex && (
            <div style={{ marginTop:12, paddingTop:10, borderTop:"1px solid var(--border,#2a2a3a)" }}>
              <div style={{ fontSize:11.5, color:"var(--text)", marginBottom:3 }}>🌌 {t("env_title")}</div>
              <div style={{ fontSize:10, color:"var(--muted)", marginBottom:7, lineHeight:1.4 }}>{t("env_subtitle")}</div>
              {data.environment.sites.map(s => (
                <div key={s.site_key} style={{ display:"flex", alignItems:"center", gap:8, marginBottom:6 }}>
                  <div style={{ flex:1, fontSize:11, color: s.here ? "var(--text)" : "var(--muted)" }}>
                    {s.emoji} {safeT("env_site_" + s.site_key, null, s.site_key)} <span style={{ color:"var(--muted)" }}>· +{s.progress}</span>
                    {!s.here && (
                      <div style={{ fontSize:9.5, color:"var(--muted)", marginTop:1 }}>
                        {t("env_elsewhere", { continent: safeT("continent_" + s.continent, null, s.continent) })}
                      </div>
                    )}
                  </div>
                  {s.here && (
                    <ActionBtn variant="primary" disabled={busy || !s.can_temper}
                      onClick={() => act("world/env_temper", { site_key: s.site_key }, "🌌", t("env_done", { n: s.progress }))}
                      style={{ whiteSpace:"nowrap" }}>
                      {s.can_temper
                        ? t("env_temper_btn", { pts: s.progress })
                        : t("env_ready_in", { time: fmtSecs(data.environment.cooldown_remaining) })}
                    </ActionBtn>
                  )}
                </div>
              ))}
            </div>
          )}

          {/* Sprint 7 — Combate 顿悟 (4th input, read-only): a worthy WIN tempers the flesh
              (+progress); a near-death worthy win grants a 顿悟 charge the Cerimónia spends.
              No button — it fires on combat. */}
          {data.insight && !data.insight.is_apex && (
            <div style={{ marginTop:12, paddingTop:10, borderTop:"1px solid var(--border,#2a2a3a)" }}>
              <div style={{ fontSize:11.5, color:"var(--text)", marginBottom:3 }}>🥋 {t("insight_title")}</div>
              <div style={{ fontSize:10, color:"var(--muted)", lineHeight:1.4 }}>
                {data.insight.has_charge
                  ? t("insight_has_charge")
                  : (data.insight.cooldown_remaining > 0
                      ? t("insight_cooldown", { time: fmtSecs(data.insight.cooldown_remaining) })
                      : t("insight_ready", { n: data.insight.progress_per_win }))}
              </div>
            </div>
          )}

          <div style={{ fontSize:10.5, fontStyle:"italic", color:"var(--muted)", marginTop:10, lineHeight:1.4 }}>
            {t("garden_future")}
          </div>
        </Card>
      );
    }

    // FTUE espinha — the guided first-hour tracker (server-gated, derived-state, read-only).
    // Renders nothing unless `ftue_espinha` is ON and the spine is incomplete (then the
    // Velho Mendigo points to the next step). Solves "blank menu, no guide" (Lei §1).
    function FtueCard({ setTab }) {
      const [tick, setTick] = useState(0);
      const f = useApi("world/ftue", null, [tick]);
      useVisibleInterval(() => setTick(x => x + 1), 8000);
      const d = f.data;
      if (!d || !d.ftue_on || d.complete || !d.current) return null;
      // MV-1 §0.1 (V-2 [jogador]): cada step LEVA ao lugar (MA-32b — entrada nova,
      // destino existente). Destinos são as tabs que mostram a ação: corpo →
      // BodyCultivationCard (gated cultivo_corpo_r0, mesmo gate dos steps),
      // horta → HortaCard na Caverna. meditar/avanco vivem NESTA tab (sem chip).
      const FTUE_STEP_TAB = { meditar:"cultivation", corpo:"body_tempering", horta:"cavern", avanco:"cultivation" };
      return (
        <Card>
          <CardTitle left={"🗺️ " + t("ftue_title")} />
          <div style={{ fontSize:11.5, color:"var(--text)", lineHeight:1.5, marginBottom:8 }}>
            {t("ftue_mendigo_" + d.current)}
          </div>
          <div style={{ display:"grid", gap:5 }}>
            {d.steps.map(s => {
              const target = setTab && !s.done ? FTUE_STEP_TAB[s.key] : null;
              const showGo = !!target && target !== "cultivation";
              return (
                <div key={s.key}
                     onClick={target ? () => { haptic("select"); setTab(target); } : undefined}
                     style={{ display:"flex", alignItems:"center", gap:8, fontSize:11,
                              cursor: target ? "pointer" : "default",
                              color: s.done ? "var(--muted)" : (s.key === d.current ? "var(--gold2)" : "var(--text)") }}>
                  <span>{s.done ? "✅" : (s.key === d.current ? "▶️" : "⚪")}</span>
                  <span style={{ textDecoration: s.done ? "line-through" : "none" }}>{t("ftue_step_" + s.key)}</span>
                  {showGo && <span style={{ marginLeft:"auto", color:"var(--gold3)", fontSize:12 }}>→</span>}
                </div>
              );
            })}
          </div>
          <div style={{ fontSize:10, color:"var(--muted)", marginTop:8, fontStyle:"italic" }}>
            {t("ftue_progress", { n: d.done_count, total: d.total })}
          </div>
        </Card>
      );
    }

    function CultivationTab({ player, onPlayerRefresh, setTab }) {
      const [tick, setTick] = useState(0);
      const [showBT, setShowBT] = useState(false);
      const [showRB, setShowRB] = useState(false);
      // v14.8 MA-34 — drill-in tribulation modal. Visible from realm 4+
      // (TRIBULATION_START_REALM). Modal handles its own empty state.
      const [showTrib, setShowTrib] = useState(false);
      // v14.10 MA-41 — Spirit Root reroll drill-in (jade-priced + pity bar).
      const [showRoot, setShowRoot] = useState(false);
      // v14.12 MA-42 — Dao Laws drill-in modal (owner override: NOT a tab,
      // drill-in here inside Cultivation). Unlocks at realm 5 (Soul Transf).
      const [showDao, setShowDao] = useState(false);
      // v14.14a — Foundation Trial / Golden Core Formation drill-in. Auto-opens
      // when BreakthroughModal returns foundation_required / core_required (lei
      // §1: jogador NUNCA preso). Manual entry via Trial Pendente card.
      const [showFound, setShowFound] = useState(false);
      const [showCore, setShowCore] = useState(false);
      // v14.14b — Recomeço (D-1a) + Quebrar Fundação (D-1b) drill-ins.
      const [showRec, setShowRec] = useState(false);
      const [showBreak, setShowBreak] = useState(false);
      // v14.14c — Prestige Shop drill-in (gate prestige_level ≥ 1).
      const [showPrShop, setShowPrShop] = useState(false);
      // Recomeço eligibility — fetched lazily so newbies see the card.
      const [recoStatus, setRecoStatus] = useState(null);
      // Cultivo do Corpo (Mortal R0–R6) RELOCADO para a aba "Cultivo do Corpo"
      // (BodyTemperingTab → BodyCultivationCard), o lar único do corpo. Não mais no muro.
      useEffect(() => {
        let cancelled = false;
        (async () => {
          try {
            const res = await api("foundation/recomeco/preview");
            if (!cancelled) setRecoStatus(res);
          } catch (e) { /* silent — eligibility card is best-effort */ }
        })();
        return () => { cancelled = true; };
      }, [tick]);  // refresh when player state changes
      const cultiv = useApi("cultivation", null, [tick]);
      // 坐 ONDA 1 — o eixo largo. ⚠️ Acima dos early-returns de propósito:
      // `useWideShell` é um hook, e um hook depois de um `return` condicional
      // é a Rules of Hooks partida (lição MA-32b). Lido sempre, usado só pelo
      // ramo da onda.
      const _wide = typeof useWideShell === "function" ? useWideShell() : false;
      // 坐 ONDA 1 — o CULTIVADOR JOGÁVEL (desenho do Astra, MESA [011]).
      // Flag PRÓPRIA e ortogonal: quando ela manda, manda sobre a `cena_cultivo`
      // (as duas competem pela mesma composição, e duas composições ao mesmo
      // tempo não é um estado). Com ela OFF nada aqui muda, byte a byte.
      // ⚠️ Lida ACIMA dos early-returns porque o ramo de ERRO também é dela.
      const ondaOn = obraOn();
      useVisibleInterval(() => setTick(x => x + 1), 5000);
      // QoL-Feedback 2 2026-07-30 (report [jogador]): o header lê `player` (poll de
      // 30s do app) e esta aba lê `cultivation` (5s) — num level-up a barra
      // virava na hora e o nível do topo ficava VELHO por até 30s. Quando o
      // payload fresco discorda, puxa o refresh do player para o mesmo
      // instante. O ref trava 1 disparo por estado divergente (nunca loop).
      // ACIMA dos early-returns — Rules of Hooks (lição MA-32b).
      const _lvlSyncRef = useRef("");
      useEffect(() => {
        const d = cultiv.data;
        if (!d || !player) return;
        const mismatch = (d.realm != null && d.realm !== player.realm)
                      || (d.sub_layer != null && d.sub_layer !== player.sub_layer);
        if (!mismatch) { _lvlSyncRef.current = ""; return; }
        const sig = `${d.realm}:${d.sub_layer}`;
        if (_lvlSyncRef.current === sig) return;
        _lvlSyncRef.current = sig;
        onPlayerRefresh && onPlayerRefresh();
      }, [cultiv.data, player, onPlayerRefresh]);
      if (cultiv.loading && !cultiv.data) return <CultivationSkeleton />;
      // 坐 ONDA 1 — o MESMO cartão de recuperação da chegada (S1, variantes 3 e
      // 4). A faixa dizia a palavra crua do servidor e não tinha um botão: quem
      // perdia a sessão a meio lia "unauthorized" e ficava sem saída. Aqui a
      // flag JÁ é alcançável (o manifesto chegou com o `player`), por isso ao
      // contrário da chegada este sítio fica mesmo atrás dela.
      if (cultiv.error && !cultiv.data) {
        return ondaOn
          ? <CultRecovery error={cultiv.error} wide={_wide}
                          onRetry={() => { setTick(x => x + 1); onPlayerRefresh && onPlayerRefresh(); }} />
          : <ErrBanner msg={cultiv.error} />;
      }
      const data = cultiv.data || {};
      const meditating = !!data.is_meditating;
      const cbPct = data.cb_threshold > 0 ? Math.min(100, (data.cultivation_base / data.cb_threshold) * 100) : 0;
      const qiPct = data.qi_capacity > 0 ? Math.min(100, (data.qi / data.qi_capacity) * 100) : 0;
      const remainMs = data.meditation_end_ms ? data.meditation_end_ms - Date.now() : 0;
      // MA-44a — at PRESTIGE_REQ_REALM (10) sub_layer 9 the player has hit
      // True Immortal IX, the canonical max realm. Breakthrough won't progress
      // them further; swap the CTA to "Renascer" so the path forward is
      // discoverable in the mini-app instead of forcing a chat detour.
      const prestigeReady = (data.realm ?? player.realm ?? 0) >= 10
                          && (data.sub_layer ?? player.sub_layer ?? 0) >= 9;
      const breakthroughReady = !prestigeReady && cbPct >= 100 && (data.realm ?? 0) >= 0;

      const medTypes = [
        { key:"light", label_key:"meditation_light", min_realm:0 },
        { key:"deep",  label_key:"meditation_deep", min_realm:0 },
        { key:"void",  label_key:"meditation_void", min_realm:4 },
        { key:"celestial_dao", label_key:"meditation_celestial", min_realm:8 },
      ];

      const meditationLabel = (key) => {
        const map = { light:"meditation_light", deep:"meditation_deep", void:"meditation_void",
                      celestial_dao:"meditation_celestial",
                      dao_basic:"meditation_dao_basic", dao_deep:"meditation_dao_deep",
                      dao_transcend:"meditation_dao_transcend" };
        return map[key] ? t(map[key]) : "🧘 " + key;
      };

      // WEB-E 坐 — a CENA (flag `cena_cultivo`, OFF em todo o mundo). Com a flag
      // OFF esta aba desenha EXACTAMENTE o que desenhava: o orbe solto + os
      // cartões CULTIVO / QI / MEDITAÇÃO, na mesma ordem, com os mesmos estilos.
      const sceneOn = typeof featureEnabled === "function" && featureEnabled("cena_cultivo");

      // 坐 ONDA 1 — o CULTIVADOR JOGÁVEL (desenho do Astra, MESA [011]).
      // Flag PRÓPRIA e ortogonal: quando ela manda, manda sobre a `cena_cultivo`
      // (as duas competem pela mesma composição, e duas composições ao mesmo
      // tempo não é um estado). Com ela OFF nada aqui muda, byte a byte.

      // Os dois CTAs vivem numa constante para as DUAS composições renderizarem
      // literalmente o mesmo JSX — um botão de Avançar que só existisse num dos
      // ramos seria a Lei §1 partida pela flag.
      const advanceCta = (
        <React.Fragment>
          {breakthroughReady && (ondaOn ? (
            /* 坐 ONDA 1 — o MESMO botão, a pele da [013]: papel sobre tinta,
               raio zero, sem gradiente, sem brilho a piscar. Não é um segundo
               CTA — é esta constante a saber em que tela está. */
            <OndaBtn onClick={() => { haptic("warning"); setShowBT(true); }}
                     style={{ marginTop:12 }}>
              {t("btn_breakthrough")}
            </OndaBtn>
          ) : (
            <ActionBtn onClick={() => { haptic("warning"); setShowBT(true); }}
                       variant="primary"
                       style={{
                         width:"100%", marginTop:12,
                         background:"linear-gradient(180deg, rgba(var(--gold2-rgb),.35), rgba(155,110,40,.5))",
                         border:"1px solid var(--gold2)", color:"var(--gold3)",
                         animation:"pulse-glow 2.2s ease-in-out infinite",
                         letterSpacing:1, fontFamily:"'Cinzel',serif",
                       }}>
              {t("btn_breakthrough")}
            </ActionBtn>
          ))}
          {prestigeReady && (ondaOn ? (
            /* ⚠️ E o 🌌 sai com o gradiente: um emoji do sistema operativo é a
               única coisa nesta tela que o aparelho do jogador desenha, e numa
               composição de tinta e papel ele é sempre a peça estrangeira. */
            <OndaBtn onClick={() => { haptic("warning"); setShowRB(true); }}
                     style={{ marginTop:12 }}>
              {t("btn_rebirth")}
            </OndaBtn>
          ) : (
            <ActionBtn onClick={() => { haptic("warning"); setShowRB(true); }}
                       variant="primary"
                       style={{
                         width:"100%", marginTop:12,
                         background:"linear-gradient(180deg, rgba(var(--realm-3-rgb),.35), rgba(80,30,150,.55))",
                         border:"1px solid #c084fc", color:"var(--gold3)",
                         animation:"pulse-glow 2.2s ease-in-out infinite",
                         letterSpacing:1.2, fontFamily:"'Cinzel',serif",
                       }}>
              🌌 {t("btn_rebirth")}
            </ActionBtn>
          ))}
        </React.Fragment>
      );

      async function startMeditation(typeKey) {
        try {
          await api("meditate/start", { type: typeKey });
          haptic("success");
          showToast(t("meditate_started"));
          setTick(x => x + 1);
          onPlayerRefresh && onPlayerRefresh();
        } catch (e) {
          haptic("error");
          if (e.message === "realm_too_low") showToast(t("meditate_min_realm"), "err");
          else if (e.message === "not_enough_qi") showToast(t("meditate_low_qi"), "err");
          else showToast(e.message, "err");
        }
      }
      async function stopMeditation() {
        try {
          await api("meditate/stop");
          haptic("success");
          showToast(t("meditate_stopped"));
          setTick(x => x + 1);
          onPlayerRefresh && onPlayerRefresh();
        } catch (e) {
          haptic("error");
          showToast(e.message, "err");
        }
      }

      // 坐 ONDA 1 — as mesmas duas chamadas, mas que LEVANTAM.
      // ⚠️ Não são um segundo caminho: batem no mesmo endpoint e fazem o mesmo
      // refresh em caso de sucesso. O que muda é quem fala com o jogador — no
      // cartão de S3 a recusa aparece DENTRO do cartão, ao lado da operação e
      // com a escolha preservada, em vez de num toast que desaparece antes de a
      // pessoa acabar de ler. As de cima continuam a servir o ramo OFF.
      async function startMeditationRaw(typeKey) {
        await api("meditate/start", { type: typeKey });
        setTick(x => x + 1);
        onPlayerRefresh && onPlayerRefresh();
      }
      async function stopMeditationRaw() {
        await api("meditate/stop");
        setTick(x => x + 1);
        onPlayerRefresh && onPlayerRefresh();
      }

      // v14.14a — Trial Pendente card. Surface foundation/core trial CTA
      // whenever player.foundation_locked / core_locked. Lei §1: jogador
      // que sobe a realm 2 / 3 NUNCA pode ficar preso sem caminho.
      // WEB-E: extraído para constante — as duas composições (cena ON/OFF)
      // renderizam o MESMO JSX; um bloqueio que só aparecesse num dos ramos
      // seria a Lei §1 partida pela flag. A cena põe-no ANTES do orbe (quem
      // está trancado vê o cadeado primeiro); com a flag OFF a ordem de sempre
      // (orbe → trial) fica intocada.
      const trialCard = (player.foundation_locked || player.core_locked) && (
        ondaOn ? (
            /* 坐 ONDA 1 — o MESMO bloqueio, sem a moldura. Ele vive logo acima
               da cena, e com a caixa de dashboard era a primeira coisa a
               desmentir a pele dois centímetros antes de ela começar.
               ⚠️ O emoji de 30px sai: quem está trancado precisa de LER o que
               falta, e um pictograma a pulsar não diz qual das duas provas é. */
            <div style={{ background: NIV_ONDA.ink, padding:"16px 16px 20px",
                          borderBottom:"1px solid " + NIV_ONDA.line }}>
              <div style={{ fontFamily: NIV_ONDA.label, fontSize:11, lineHeight:(16/11),
                            letterSpacing:".12em", textTransform:"uppercase",
                            color: NIV_ONDA.gold }}>
                {ondaNomeLimpo(t("trial_pending_card_title"))}
              </div>
              <div style={{ marginTop:8, fontFamily: NIV_ONDA.body, fontSize:13,
                            lineHeight:(20/13), color: NIV_ONDA.paper }}>
                {player.foundation_locked
                  ? t("trial_pending_foundation_hint")
                  : t("trial_pending_core_hint")}
              </div>
              <div style={{ marginTop:14 }}>
                <OndaBtn onClick={() => {
                           haptic("warning");
                           if (player.foundation_locked) setShowFound(true);
                           else setShowCore(true);
                         }}>
                  {ondaNomeLimpo(t("trial_pending_open"))}
                </OndaBtn>
              </div>
            </div>
        ) : (
            <Card>
              <CardTitle left={t("trial_pending_card_title")} />
              <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between", gap:10 }}>
                <div style={{ display:"flex", alignItems:"center", gap:10, minWidth:0, flex:1 }}>
                  <div style={{ fontSize:30, lineHeight:1,
                                animation:"pulse-glow 2.2s ease-in-out infinite",
                                filter: player.foundation_locked
                                  ? "drop-shadow(0 0 10px rgba(var(--gold2-rgb),.55))"
                                  : "drop-shadow(0 0 10px rgba(var(--realm-3-rgb),.55))" }}>
                    {player.foundation_locked ? "🏯" : "🔮"}
                  </div>
                  <div style={{ fontSize:11, color:"var(--muted)", lineHeight:1.4 }}>
                    {player.foundation_locked
                      ? t("trial_pending_foundation_hint")
                      : t("trial_pending_core_hint")}
                  </div>
                </div>
                <ActionBtn variant="primary"
                           onClick={() => {
                             haptic("warning");
                             if (player.foundation_locked) setShowFound(true);
                             else setShowCore(true);
                           }}
                           style={{ flexShrink:0 }}>
                  {t("trial_pending_open")}
                </ActionBtn>
              </div>
            </Card>
        )
      );

      // 坐 ONDA 1 — as ÂNCORAS só apontam para secções que EXISTEM nesta página.
      // As três são condicionais (a Prática pede reino 5 ou elegibilidade de
      // Recomeço; os Caminhos pedem reino 4 ou prestígio) e uma âncora fixa
      // levaria um jogador novo a tocar num destino ausente — Lei §1 partida
      // pela decoração. A ordem é a do desenho: Cultivador · Prática · Caminhos,
      // e é a MESMA ordem em que o DOM as desenha com a flag ON (ver `secSelf` /
      // `secPractice` abaixo) — uma âncora que saltasse para trás seria pior do
      // que nenhuma.
      const _hasPractice = (data.realm ?? player.realm ?? 0) >= 5
                        || !!(recoStatus && recoStatus.eligible);
      const _hasPaths = (player.realm ?? 0) >= 4 || (player.prestige_level ?? 0) >= 1;
      // 坐 ONDA 1 — o salto para a operação. Com a identidade a ocupar a
      // largura toda e a paisagem a seguir, S3 cai abaixo da primeira dobra no
      // telemóvel — e a coisa que o jogador veio fazer não pode exigir uma
      // viagem às cegas. A [013] preferiu isto a comprimir a abertura.
      const _jumpMeditar = ondaOn ? (() => {
        haptic("select");
        try {
          const el = document.getElementById("cult-sec-meditar");
          if (el) el.scrollIntoView({ behavior:"smooth", block:"start" });
        } catch (e) {}
      }) : undefined;
      const ondaAnchors = ondaOn ? (
        <CultAnchors wide={_wide} items={[
          { key:"self",     id:"cult-sec-self",     glyph:"己", label:t("cult_sec_self"),     present:true },
          { key:"practice", id:"cult-sec-practice", glyph:"修", label:t("cult_sec_practice"), present:_hasPractice },
          { key:"paths",    id:"cult-sec-paths",    glyph:"途", label:t("cult_sec_paths"),    present:_hasPaths },
        ]} />
      ) : null;

      // 坐 ONDA 1 — as duas secções em constantes, para a ORDEM poder mudar
      // sem o JSX ser escrito duas vezes. O DOM de hoje é 修 (Prática) → 己
      // (Cultivador) → 途 (Caminhos); o desenho decidiu **Cultivador · Prática
      // · Caminhos**, que é a ordem em que os glífos se leem (quem você É, o que
      // você PRATICA, para onde pode IR). Escrever a aba duas vezes para trocar
      // duas posições seria dar dois donos a 240 linhas de JSX — a Lei 0 §2
      // dentro do lote que a está a cumprir. Com a flag OFF a ordem é a de hoje.
      const secPractice = (
        <React.Fragment>
          {((data.realm ?? player.realm ?? 0) >= 5
            || (recoStatus && recoStatus.eligible)) && (
            <SectionRule glyph="修" label={t("cult_sec_practice")} anchorId="cult-sec-practice" />
          )}

          {/* v14.12 MA-42 — Dao Laws drill-in. Owner override 2026-05-06:
              NOT a separate tab — lives inside Cultivation. Realm 5+ gate
              (Soul Transformation). Modal handles Supreme + 3000 Laws +
              Meditation start. */}
          {(data.realm ?? player.realm ?? 0) >= 5 && (
            <Card>
              <CardTitle left={t("dao_card_title")} />
              <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between", gap:10 }}>
                <div style={{ display:"flex", alignItems:"center", gap:10, minWidth:0, flex:1 }}>
                  <div style={{ fontSize:30, lineHeight:1,
                                filter:"drop-shadow(0 0 10px rgba(var(--realm-3-rgb),.5))" }}>🌌</div>
                  <div style={{ fontSize:11, color:"var(--muted)", lineHeight:1.4 }}>
                    {t("dao_card_hint")}
                  </div>
                </div>
                <ActionBtn variant="ghost"
                           onClick={() => { haptic("select"); setShowDao(true); }}
                           style={{ flexShrink:0 }}>
                  {t("dao_card_open")}
                </ActionBtn>
              </div>
            </Card>
          )}

          {/* v14.14b — Recomeço drill-in (D-1a newbie grace). Visible só se
              o server confirmar elegibilidade (realm ≤2 OR ≤7d, e nunca
              usado). Card cyan distinct dos outros. */}
          {recoStatus && recoStatus.eligible && (
            <Card>
              <CardTitle left={t("recomeco_card_title")} />
              <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between", gap:10 }}>
                <div style={{ display:"flex", alignItems:"center", gap:10, minWidth:0, flex:1 }}>
                  <div style={{ fontSize:30, lineHeight:1,
                                filter:"drop-shadow(0 0 10px rgba(34,211,238,.5))" }}>🌱</div>
                  <div style={{ fontSize:11, color:"var(--muted)", lineHeight:1.4 }}>
                    {recoStatus.days_left > 0
                      ? t("recomeco_card_hint_days", { days: recoStatus.days_left })
                      : t("recomeco_card_hint_realm")}
                  </div>
                </div>
                <ActionBtn variant="ghost"
                           onClick={() => { haptic("select"); setShowRec(true); }}
                           style={{ flexShrink:0 }}>
                  🌱 {t("recomeco_card_open")}
                </ActionBtn>
              </div>
            </Card>
          )}

          {/* v14.14b — Quebrar Fundação drill-in (D-1b mid-game ritual). Realm
              5+. Cost: 50% CB + 100k stones + 50 essence. Cooldown 30d. */}
          {(player.realm ?? data.realm ?? 0) >= 5 && (
            <Card>
              <CardTitle left={t("break_card_title")} />
              <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between", gap:10 }}>
                <div style={{ display:"flex", alignItems:"center", gap:10, minWidth:0, flex:1 }}>
                  <div style={{ fontSize:30, lineHeight:1,
                                filter:"drop-shadow(0 0 10px rgba(var(--red-rgb),.5))" }}>🔥</div>
                  <div style={{ fontSize:11, color:"var(--muted)", lineHeight:1.4 }}>
                    {t("break_card_hint")}
                  </div>
                </div>
                <ActionBtn variant="ghost"
                           onClick={() => { haptic("select"); setShowBreak(true); }}
                           style={{ flexShrink:0 }}>
                  🔥 {t("break_card_open")}
                </ActionBtn>
              </div>
            </Card>
          )}
        </React.Fragment>
      );
      const secSelf = (
        <React.Fragment>
          {/* v14.10 MA-41 — Spirit Root drill-in. Always visible (the cur root
              info is already displayed in the player header on chat side). UI
              shows the current root + a CTA to open the reroll modal with
              cost/pity preview. Mirrors handlers/shop._show_root_reroll. */}
          <SectionRule glyph="己" label={t("cult_sec_self")} anchorId="cult-sec-self" />

          <Card>
            <CardTitle left={t("root_reroll_card_title")} />
            <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between", gap:10 }}>
              <div style={{ display:"flex", alignItems:"center", gap:10, minWidth:0, flex:1 }}>
                <div style={{ fontSize:30, lineHeight:1,
                              filter:`drop-shadow(0 0 8px ${cssHex(_ROOT_COLOR[player.spirit_root] || "var(--realm-2)")}99)` }}>
                  {player.spirit_root_emoji || "🌱"}
                </div>
                <div style={{ minWidth:0, flex:1 }}>
                  <div style={{ fontFamily:"'Cinzel',serif", fontWeight:700, fontSize:13,
                                color: _ROOT_COLOR[player.spirit_root] || "var(--text)" }}>
                    {player.spirit_root || "—"}
                  </div>
                  <div style={{ fontSize:11, color:"var(--muted)", lineHeight:1.4 }}>
                    {t("root_reroll_card_hint")}
                  </div>
                </div>
              </div>
              <ActionBtn variant="ghost"
                         onClick={() => { haptic("select"); setShowRoot(true); }}
                         style={{ flexShrink:0 }}>
                🌱 {t("root_reroll_card_btn")}
              </ActionBtn>
            </div>

            {/* Track A item 5 — Raízes: the COMPOSITION axis (orthogonal to the
                quality root above). PURE disclosure — element chips + archetype
                lore + an honest "awakens in the new world" teaser. No %; the
                gating/modifiers are wipe-bound (Lei §1). */}
            {player.root_elements && (player.root_elements.elements || []).length > 0 && (
              <div style={{ marginTop:12, paddingTop:12, borderTop:"1px solid var(--border,#2a2a3a)" }}>
                <div style={{ fontSize:11, color:"var(--muted)", marginBottom:6,
                              fontFamily:"'Cinzel',serif", letterSpacing:.3 }}>
                  {t("root_reson_title")}
                </div>
                <div style={{ display:"flex", flexWrap:"wrap", gap:6 }}>
                  {player.root_elements.elements.map((el) => (
                    <span key={el.key}
                          style={{ display:"inline-flex", alignItems:"center", gap:4,
                                   padding:"3px 9px", borderRadius:999, fontSize:12,
                                   background: el.rare ? "rgba(var(--realm-2-rgb),.12)" : "rgba(255,255,255,.06)",
                                   border:`1px solid ${el.rare ? "var(--realm-2)" : "var(--border,#2a2a3a)"}`,
                                   color: el.rare ? "var(--realm-2)" : "var(--text)" }}>
                      {el.emoji} {safeT("root_el_" + el.key, null, el.key)}
                    </span>
                  ))}
                </div>
                <div style={{ fontSize:12, color:"var(--text)", marginTop:8, lineHeight:1.45 }}>
                  <b>{safeT("root_archetype_" + player.root_elements.archetype, null, "")}</b>
                  {" — "}
                  {safeT("root_archetype_" + player.root_elements.archetype + "_lore", null, "")}
                </div>
                {player.root_elements.has_variant && (
                  <div style={{ fontSize:11, color:"var(--realm-2)", marginTop:6 }}>
                    ✦ {t("root_reson_variant")}
                  </div>
                )}
                <div style={{ fontSize:10.5, fontStyle:"italic", color:"var(--muted)",
                              marginTop:8, lineHeight:1.4 }}>
                  {t("root_reson_future")}
                </div>
              </div>
            )}
          </Card>

          {/* Track A (B4) — Lifespan 寿命 ("Mar de Longevidade 寿海"). PURE
              disclosure: the current realm's longevity ceiling + the next-realm
              CARROT + the immortal flag. NO running clock — the future teaser is
              explicit ("ainda não corre"); nothing ages/dies and no number changes
              (the tick + death are wipe-bound, Lei §1, §5). */}
          {player.lifespan && (
            <Card>
              <CardTitle left={"🌊 " + t("lifespan_title")} />
              {player.lifespan.is_immortal ? (
                <div style={{ fontSize:12.5, color:"var(--gold3)", lineHeight:1.5 }}>
                  {t("lifespan_immortal")}
                </div>
              ) : (
                <div style={{ fontSize:12.5, color:"var(--text)", lineHeight:1.55 }}>
                  <div>
                    {player.realm_emoji || "🪨"}{" "}
                    {/* ⚠️ WEB-E 2026-09-02 (visto, nao testado) — `lifespan.realm_name`
                        vem do servidor em INGLES por decisao declarada
                        (`lifespan_engine._realm_name`: "canonical, language-neutral").
                        Num ecra em portugues isso punha "Core Formation: 500 anos" a
                        300px do cartao CULTIVO que diz "Nucleo" — o MESMO reino com
                        dois nomes na mesma tela. O payload ja traz o INTEIRO
                        (`lifespan.realm`), e o cliente ja sabe traduzi-lo
                        (`realmName` -> chave `realm_N`). Zero string nova, zero
                        mudanca de servidor, zero mudanca de payload. */}
                    {t("lifespan_ceiling", { realm: realmName(player.lifespan.realm), anos: player.lifespan.ceiling })}
                  </div>
                  {/* TEC-5 — o relógio ganhou DENTE: cada uso de arte proibida
                      QUEIMA anos. Quem nunca queimou nada não vê esta linha, e
                      o teaser "ainda não corre" só se diz enquanto for verdade
                      (Lei §1 — nunca uma tela contradizendo a outra). */}
                  {player.lifespan.age_years > 0 && (
                    <div style={{ color:"#e5a0a0", marginTop:5 }}>
                      ☠️ {t("lifespan_burned", { anos: fmtNum(player.lifespan.age_years),
                                                 left: fmtNum(Math.max(0, (player.lifespan.ceiling || 0) - player.lifespan.age_years)) })}
                    </div>
                  )}
                  {player.lifespan.burn_on && player.lifespan.uses_left != null && (
                    <div style={{ fontSize:10.5, color:"var(--muted)", marginTop:4 }}>
                      {t("lifespan_burn_rate", { years: fmtNum(player.lifespan.years_per_use),
                                                 uses: fmtNum(player.lifespan.uses_left) })}
                    </div>
                  )}
                  {player.lifespan.next_realm != null && (
                    <div style={{ color:"var(--gold3)", marginTop:5 }}>
                      ↳ {player.lifespan.next_is_immortal
                          ? t("lifespan_next_immortal", { next: realmName(player.lifespan.next_realm) })
                          : t("lifespan_next", { next: realmName(player.lifespan.next_realm), anos: player.lifespan.next_ceiling })}
                    </div>
                  )}
                  <div style={{ fontSize:10.5, fontStyle:"italic", color:"var(--muted)", marginTop:8, lineHeight:1.4 }}>
                    {player.lifespan.age_years > 0 ? t("lifespan_running") : t("lifespan_future")}
                  </div>
                </div>
              )}
            </Card>
          )}

          {/* Sprint 1 — Raça (KEYSTONE A, disclosure-only). The 3rd birth axis,
              gated by the Surface Manifest feature `racas`: only worlds that opt
              in (s2) render it; `main` (flag OFF) never draws it and the 57 have
              race=NULL (the payload sends race=null there too). PURE disclosure —
              o povo + raridade + continente-casa + 1 linha de lore + teaser
              honesto. ZERO mecânica (Lei §1/§5); a profundidade (técnicas-por-
              origem, acesso-a-continente, reroll) é Track B/wipe. */}
          {featureEnabled("racas") && (
            <Card>
              <CardTitle left={"🧬 " + t("race_panel_title")} />
              {player.race && player.race.key ? (
                <div>
                  <div style={{ display:"flex", alignItems:"center", gap:8, flexWrap:"wrap" }}>
                    <span style={{ display:"inline-flex", alignItems:"center", gap:5,
                                   padding:"4px 11px", borderRadius:999, fontSize:13,
                                   background: player.race.rarity_band === "legendary" ? "rgba(var(--realm-2-rgb),.14)"
                                     : player.race.rarity_band === "rare" ? "rgba(167,139,250,.12)" : "rgba(255,255,255,.06)",
                                   border:`1px solid ${player.race.rarity_band === "legendary" ? "var(--realm-2)"
                                     : player.race.rarity_band === "rare" ? "#a78bfa" : "var(--border,#2a2a3a)"}`,
                                   color: player.race.rarity_band === "legendary" ? "var(--realm-2)"
                                     : player.race.rarity_band === "rare" ? "#c4b5fd" : "var(--text)" }}>
                      {player.race.emoji} {safeT("race_" + player.race.key, null, player.race.key)}
                    </span>
                    <span style={{ fontSize:11, color:"var(--muted)", fontFamily:"'Cinzel',serif", letterSpacing:.3 }}>
                      {safeT("race_rarity_" + player.race.rarity_band, null, "")}
                    </span>
                  </div>
                  {player.race.home_continent && (
                    <div style={{ fontSize:12, color:"var(--muted)", marginTop:8 }}>
                      {player.race.home_continent}
                    </div>
                  )}
                  <div style={{ fontSize:12, color:"var(--text)", marginTop:6, lineHeight:1.45 }}>
                    {safeT("race_" + player.race.key + "_lore", null, "")}
                  </div>
                  <div style={{ fontSize:10.5, fontStyle:"italic", color:"var(--muted)", marginTop:8, lineHeight:1.4 }}>
                    {t("race_future")}
                  </div>
                </div>
              ) : (
                /* Honest empty-state (Lei §1 — never a silent void). Only reachable
                   in an ON world if the projection came back null (corrupt/missing
                   key); `main` keeps the flag OFF so this panel never renders there. */
                <div style={{ fontSize:12, fontStyle:"italic", color:"var(--muted)", lineHeight:1.45 }}>
                  {t("race_none")}
                </div>
              )}
            </Card>
          )}

          {/* Sprint 2+3 — Cultivo do Corpo @ R0 (Mortal band) RELOCADO para a aba dedicada
              "Cultivo do Corpo" (BodyTemperingTab → BodyCultivationCard): o lar único do
              corpo (Mortal R0–R6 + Nove Transformações R7+). Tirado do muro da Cultivação. */}

          {/* Sprint 4 — Horta 灵田: RELOCADA para a aba Caverna (洞府) — o jardim
              espiritual idle (+ Caça/Ambiental/Combate) vive no espaço pessoal, ao
              lado das Formações, não no muro da Cultivação. Ver CavernTab. */}

          {/* Track A (B4) — Mind Sea 识海 ("Mar da Consciência"). REFRAME (no
              column — item-6 precedent): a depth TIER derived from soul_strength +
              perception + realm. PURE disclosure — tier + lore, the note that the
              player's LIVE Sentido Divino (神識) flows from here, and an honest
              "awakens in the new world" teaser. No %; soul-defense / alchemy-focus
              are wipe-bound (Lei §1, §3, §5). ZERO modifier — no number changes. */}
          {player.mind_sea && (
            <Card>
              <CardTitle left={"🪷 " + t("mind_sea_title")} />
              <div style={{ fontSize:12.5, color:"var(--text)", lineHeight:1.55 }}>
                <div>
                  {player.mind_sea.tier_emoji}{" "}
                  <b>{safeT("mind_sea_tier_" + player.mind_sea.tier, null, "")}</b>
                  {" — "}
                  {safeT("mind_sea_tier_" + player.mind_sea.tier + "_lore", null, "")}
                </div>
                <div style={{ color:"var(--gold3)", marginTop:6, fontSize:11.5 }}>
                  ↳ {t("mind_sea_sense")}
                </div>
                <div style={{ fontSize:10.5, fontStyle:"italic", color:"var(--muted)", marginTop:8, lineHeight:1.4 }}>
                  {t("mind_sea_future")}
                </div>
              </div>
            </Card>
          )}

          {/* Track A (B4) — Dao Heart 道心 ("Coração Dao"). REFRAME (no column —
              Mind Sea / item-6 precedent): a firmeza (conviction) TIER + the Will's
              tendency, SYNTHESIZED from path + karma + the existing ±500 divergence
              boundary. PURE disclosure — tier + lore, the Will's inclination, the
              note that the Dao Heart holds the soul against the 心魔 Heart Demon
              (which ALREADY warns on divergence), and an honest future teaser
              (intention-weighted karma / choice verbs / 心魔劫 Judgment — [jogador]'s
              feedback). No %; the deep model is wipe-bound (Lei §1, §3, §5). ZERO
              modifier; complements (never repeats) the KarmaModal. The
              tendency_variant / demon_variant come from the engine so this card and
              the chat /status render the IDENTICAL line for the same row. */}
          {player.dao_heart && (
            <Card>
              <CardTitle left={"❤️‍🔥 " + t("dao_heart_title")} />
              <div style={{ fontSize:12.5, color:"var(--text)", lineHeight:1.55 }}>
                <div>
                  {player.dao_heart.firmeza_emoji}{" "}
                  <b>{safeT("dao_heart_tier_" + player.dao_heart.firmeza, null, "")}</b>
                  {" — "}
                  {safeT("dao_heart_tier_" + player.dao_heart.firmeza + "_lore", null, "")}
                </div>
                <div style={{ marginTop:6 }}>
                  ↳ {t("dao_heart_" + player.dao_heart.tendency_variant, {
                        tendency: safeT("dao_heart_tend_label_" + player.dao_heart.tendency, null, ""),
                     })}
                </div>
                <div style={{ color: player.dao_heart.heart_demon_near ? "#f4a4a4" : "var(--gold3)",
                              marginTop:6, fontSize:11.5 }}>
                  ↳ {t("dao_heart_" + player.dao_heart.demon_variant)}
                </div>
                <div style={{ fontSize:10.5, fontStyle:"italic", color:"var(--muted)", marginTop:8, lineHeight:1.4 }}>
                  {t("dao_heart_future")}
                </div>
              </div>
            </Card>
          )}

        </React.Fragment>
      );
      return (
        <div>
          {ondaOn ? (
            <React.Fragment>
              {ondaAnchors}
              {trialCard}
              {/* 坐 ONDA 1 §B.4 — no PC a cena e a operação ficam LADO A LADO
                  (824 + 32 + 456 na referência de 1440). Antes estavam em
                  sequência, com o `FtueCard` ENTRE elas — num ecrã largo isso
                  deixava metade da tela vazia à direita e empurrava a operação
                  para fora da vista, que é o contrário do que um ecrã largo serve.
                  ⚠️ O empilhar NÃO é decidido em JS: `flexWrap` com os mínimos da
                  [013] (640 de cena, 400 de operação) faz a coluna cair sozinha
                  quando deixa de caber — inclusive numa janela que o jogador
                  redimensiona a meio, onde uma medição feita uma vez mentiria. */}
              <div style={_wide
                ? { display:"flex", flexWrap:"wrap", gap:32, alignItems:"flex-start" }
                : undefined}>
                <div style={_wide ? { flex:"1 1 640px", minWidth:0 } : undefined}>
                  <CultivationSynthesis
                    name={player.dao_name || player.name || "—"}
                    realm={data.realm ?? player.realm ?? 0}
                    subLayer={data.sub_layer ?? player.sub_layer ?? 1}
                    realmLabel={realmName(data.realm ?? player.realm ?? 0)}
                    meditating={meditating}
                    medLabel={meditationLabel(data.meditation_type)}
                    remainMs={remainMs}
                    hpNow={player.current_hp}
                    hpMax={player.max_hp}
                    qiNow={data.qi} qiMax={data.qi_capacity}
                    cbNow={data.cultivation_base} cbMax={data.cb_threshold}
                    combatPower={(typeof featureEnabled === "function"
                                  && featureEnabled("progressao_visivel"))
                                  ? player.display_combat_power : null}
                    gender={player?.gender || null}
                    atCeiling={prestigeReady}
                    cta={advanceCta}
                    onJumpMeditar={_jumpMeditar}
                    wide={_wide} />
                </div>
                <div style={_wide ? { flex:"1 1 400px", maxWidth:456, minWidth:0 } : undefined}>
                  <MeditationCard
                    anchorId="cult-sec-meditar"
                    catalog={data.meditation_catalog}
                    realm={data.realm ?? player.realm ?? 0}
                    qi={data.qi}
                    meditating={meditating}
                    medType={data.meditation_type}
                    medMult={data.meditation_multiplier || 0}
                    remainMs={remainMs}
                    onStart={startMeditationRaw}
                    onStop={stopMeditationRaw}
                    onRefresh={() => { setTick(x => x + 1); onPlayerRefresh && onPlayerRefresh(); }}
                    wide={_wide} />
                </div>
              </div>
            </React.Fragment>
          ) : sceneOn ? (
            <React.Fragment>
              {trialCard}
              <CultivationScene
                realm={data.realm ?? player.realm ?? 0}
                meditating={meditating}
                cbPct={cbPct} qiPct={qiPct}
                cbNow={data.cultivation_base} cbMax={data.cb_threshold}
                qiNow={data.qi} qiMax={data.qi_capacity}
                qiRegenMult={data.qi_regen_mult || 0}
                realmLabel={realmName(data.realm)}
                medLabel={meditationLabel(data.meditation_type)}
                medMult={data.meditation_multiplier || 1}
                remainMs={remainMs}
                medTypes={medTypes}
                atCeiling={prestigeReady}
                onStart={startMeditation}
                onStop={stopMeditation}
                cta={advanceCta}
                gender={player?.gender || null}
              />
            </React.Fragment>
          ) : (
          <React.Fragment>
          <CultivationOrb realm={data.realm ?? player.realm} meditating={meditating}
                          gender={player?.gender || null} />

          {trialCard}

          <Card>
            <CardTitle left={t("cultivation")} right={cbPct.toFixed(1) + "%"} />
            <ProgressBar pct={cbPct} variant="cult" />
            <div style={{ display:"flex", justifyContent:"space-between", marginTop:6, fontSize:11, color:"var(--muted)" }}>
              <span>{fmtNum(data.cultivation_base)} / {fmtNum(data.cb_threshold)}</span>
              <span>{realmName(data.realm)}</span>
            </div>
            {advanceCta}
          </Card>
          </React.Fragment>
          )}

          <FtueCard setTab={setTab} />

          {/* WEB-E: com a cena ON estes dois cartões estão DENTRO dela —
              os mesmos números, o mesmo chip de regeneração, os mesmos
              quatro assentos com os mesmos cadeados. Nada foi removido. */}
          {!sceneOn && !ondaOn && (<React.Fragment>
          <Card>
            <CardTitle left={t("qi")} right={qiPct.toFixed(0) + "%"} />
            <ProgressBar pct={qiPct} variant="qi" />
            <div style={{ display:"flex", justifyContent:"space-between", marginTop:6, fontSize:11, color:"var(--muted)" }}>
              <span>{fmtNum(data.qi)} / {fmtNum(data.qi_capacity)}</span>
              {data.qi_regen_mult > 1 && <Badge variant="jade">×{data.qi_regen_mult.toFixed(1)} qi/s</Badge>}
            </div>
          </Card>

          <Card>
            <CardTitle left={t("meditation")} />
            {meditating ? (
              <div>
                <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center" }}>
                  <span style={{ fontSize:13, fontWeight:600 }}>{meditationLabel(data.meditation_type)}</span>
                  <Badge variant="gold">×{(data.meditation_multiplier || 1).toFixed(1)}</Badge>
                </div>
                <div style={{ display:"flex", justifyContent:"space-between", marginTop:8, fontSize:12, color:"var(--muted)" }}>
                  <span>{t("ends_in")}</span>
                  <b style={{ color:"var(--gold2)" }}>{fmtDuration(remainMs)}</b>
                </div>
                <ActionBtn onClick={stopMeditation} variant="danger" style={{ width:"100%", marginTop:12 }}>
                  {t("meditate_stop")}
                </ActionBtn>
              </div>
            ) : (
              <div>
                <div style={{ fontSize:12, color:"var(--muted)", marginBottom:10, textAlign:"center" }}>
                  {t("meditate_choose")}
                </div>
                <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:8 }}>
                  {medTypes.map(m => {
                    const locked = (data.realm ?? player.realm ?? 0) < m.min_realm;
                    return (
                      <ActionBtn key={m.key} variant="ghost" disabled={locked}
                        onClick={() => startMeditation(m.key)}>
                        {locked ? <>{ico("🔒","lock",{ size:12, style:{ display:"inline-block", verticalAlign:"-2px" } })}{" "}{t(m.label_key)}</> : t(m.label_key)}
                      </ActionBtn>
                    );
                  })}
                </div>
              </div>
            )}
          </Card>
          </React.Fragment>)}

          <Card>
            <CardTitle left={t("attributes")} />
            <StatGrid stats={[
              // Progressão Visível — the aggregated Poder de Combate (offense + body)
              // count-ups on every upgrade when the flag is on; `main` keeps the raw
              // battle_power (byte-identical).
              { label: t("battle_power"),
                value: (typeof featureEnabled === "function" && featureEnabled("progressao_visivel") && player.display_combat_power != null)
                  ? <CountUp value={player.display_combat_power} />
                  : fmtNum(player.battle_power) },
              { label: t("soul"),         value: fmtNum(player.soul_strength) },
              { label: t("perception"),   value: fmtNum(player.perception) },
              { label: t("luck"),         value: fmtNum(player.luck) },
              ...(player.body_tempering_level > 0 ? [{ label: t("body_tempering"), value: `${t("level_short")} ${player.body_tempering_level}` }] : []),
              ...(player.prestige_level > 0 ? [{ label: t("prestige"), value: `${t("level_short")} ${player.prestige_level}` }] : []),
            ]} />
          </Card>

          {/* v14.11 — Active buffs panel. Mostra PlayerBuff activos (cb_boost,
              soul_boost, qi_regen_boost, etc) com countdown. Auto-refresh 30s.
              Empty state colapsa o card (nada mostrado se não há buffs). */}
          <ActiveBuffsCard />

          {ondaOn
            ? <React.Fragment>{secSelf}{secPractice}</React.Fragment>
            : <React.Fragment>{secPractice}{secSelf}</React.Fragment>}
          {((player.realm ?? 0) >= 4 || (player.prestige_level ?? 0) >= 1) && (
            <SectionRule glyph="途" label={t("cult_sec_paths")} anchorId="cult-sec-paths" />
          )}

          {/* v14.8 MA-34 — Tribulação drill-in. Available from realm 4+. The
              card is always visible at the threshold realm so the player has
              a discoverable surface — modal handles empty state honestly when
              no trib is pending. Lightning storm cinematic + thunder phase
              fully playable in-app; HD/Dao surface chat-redirect. */}
          {(player.realm ?? 0) >= 4 && (
            <Card>
              <CardTitle left={t("trib_card_title")} />
              <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between", gap:10 }}>
                <div style={{ display:"flex", alignItems:"center", gap:10, minWidth:0, flex:1 }}>
                  <div style={{ fontSize:30, lineHeight:1,
                                animation:"trib-storm 1.6s ease-in-out infinite",
                                filter:"drop-shadow(0 0 10px rgba(120,180,255,.55))" }}>⚡</div>
                  <div style={{ fontSize:11, color:"var(--muted)", lineHeight:1.4 }}>
                    {t("trib_card_idle")}
                  </div>
                </div>
                <ActionBtn variant="primary"
                           onClick={() => { haptic("warning"); setShowTrib(true); }}
                           style={{ flexShrink:0 }}>
                  {t("trib_card_open")}
                </ActionBtn>
              </div>
            </Card>
          )}

          {/* v14.14c — Prestige Shop drill-in. Gate prestige_level ≥ 1 so
              pre-renascimento players don't see an empty/locked surface.
              The chat side mirrors via /loja_prestige.
              ⚠️ WEB-E (2026-09-01): este cartão vivia ENTRE o Cultivo e o Qi —
              uma loja encaixada entre os dois números que dão nome à tela, com
              a mesma moldura dos dois, portanto com o mesmo peso de leitura.
              Desceu para 途 CAMINHOS. Não foi removido nem escondido: continua
              a mesma porta, no sítio onde uma porta se procura (Lei §1). */}
          {(player.prestige_level ?? 0) >= 1 && (
            <Card>
              <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between", gap:10 }}>
                <div style={{ display:"flex", alignItems:"center", gap:10, minWidth:0, flex:1 }}>
                  <div style={{ fontSize:30, lineHeight:1,
                                filter:"drop-shadow(0 0 12px rgba(var(--gold2-rgb),.55))" }}>🛍️</div>
                  <div style={{ minWidth:0, flex:1 }}>
                    <div style={{ fontFamily:"'Cinzel',serif", fontWeight:700, fontSize:13,
                                  color:"var(--gold3)" }}>
                      {t("prestige_shop_card_title")}
                    </div>
                    <div style={{ fontSize:11, color:"var(--muted)", lineHeight:1.4 }}>
                      {t("prestige_shop_card_hint")}
                    </div>
                  </div>
                </div>
                <ActionBtn variant="ghost"
                           onClick={() => { haptic("select"); setShowPrShop(true); }}
                           style={{ flexShrink:0 }}>
                  💠 {fmtNum(player.prestige_points || 0)} PP
                </ActionBtn>
              </div>
            </Card>
          )}

          {showBT && (
            <BreakthroughModal
              onClose={() => setShowBT(false)}
              onResolved={() => { setTick(x => x + 1); onPlayerRefresh && onPlayerRefresh(); }}
              onGateFoundation={() => { setShowBT(false); setShowFound(true); }}
              onGateCore={() => { setShowBT(false); setShowCore(true); }}
              onGateTrib={() => { setShowBT(false); setShowTrib(true); }}
              onGateCelestial={setTab ? () => { setShowBT(false); setTab("celestial"); } : undefined}
            />
          )}
          {showFound && (
            <FoundationTrialModal
              onClose={() => setShowFound(false)}
              onResolved={() => { setTick(x => x + 1); onPlayerRefresh && onPlayerRefresh(); }}
            />
          )}
          {showCore && (
            <CoreFormationModal
              onClose={() => setShowCore(false)}
              onResolved={() => { setTick(x => x + 1); onPlayerRefresh && onPlayerRefresh(); }}
            />
          )}
          {showRec && (
            <RecomecoModal
              onClose={() => setShowRec(false)}
              onResolved={() => { setTick(x => x + 1); setRecoStatus(null); onPlayerRefresh && onPlayerRefresh(); }}
            />
          )}
          {showBreak && (
            <QuebrarFundacaoModal
              onClose={() => setShowBreak(false)}
              onResolved={() => { setTick(x => x + 1); onPlayerRefresh && onPlayerRefresh(); }}
            />
          )}
          {showRB && (
            <RebirthModal
              onClose={() => setShowRB(false)}
              onResolved={() => { setTick(x => x + 1); onPlayerRefresh && onPlayerRefresh(); }}
            />
          )}
          {showTrib && (
            <TribulationModal
              onClose={() => setShowTrib(false)}
              onResolved={() => { setTick(x => x + 1); onPlayerRefresh && onPlayerRefresh(); }}
            />
          )}
          {showRoot && (
            <SpiritRootRerollModal
              onClose={() => setShowRoot(false)}
              onChanged={() => { setTick(x => x + 1); onPlayerRefresh && onPlayerRefresh(); }}
            />
          )}
          {showDao && (
            <DaoLawsModal
              onClose={() => setShowDao(false)}
              onChanged={() => { setTick(x => x + 1); onPlayerRefresh && onPlayerRefresh(); }}
            />
          )}
          {showPrShop && (
            <PrestigeShopModal
              onClose={() => setShowPrShop(false)}
              onChanged={() => { setTick(x => x + 1); onPlayerRefresh && onPlayerRefresh(); }}
            />
          )}
        </div>
      );
    }

    // ─── Sect Tab ────────────────────────────────────────────────────────────
    // MA-33 (2026-05-07) — full action set. Existing SectTab was read-only; now
    // donate/upgrade/promote/kick/leave/shop/create/join all live in the mini-app.
    // Engine reuse via core.sect_engine functions; ranks gated server-side, UI
    // hides forbidden actions as polish only.
    // ─── Seita de Cultivo Tab (🏯) ───────────────────────────────────────────
    // Taxonomia (2026-06-24): a aba "Seita" = a SEITA DE CULTIVO (as 9 casas NPC
    // onde se aprendem técnicas e se sobe de rank), NÃO a Guilda de jogadores.
    // Landing leve que abre os modais canónicos já existentes:
    //   • WorldSectDirectoryModal — as 9 seitas + estado de recrutamento (s.recruitable)
    //   • SectHallModal — o Hall do membro (Biblioteca/técnicas, rank, quests)
    // A Guilda de jogadores vive agora na aba "Guilda" (SectTab).
    function SeitaCultivoTab({ player, onOpenDirectory, onOpenHall, setTab }) {
      const isMember = !!(player && player.sect_chip_visible);
      return (
        <div>
          <Card>
            <CardTitle left={"🏯 " + safeT("seita_cultivo_title", null, "Seita de Cultivo")} />
            <div style={{ fontSize:12, color:"var(--muted)", lineHeight:1.5, marginBottom:12 }}>
              {safeT("seita_cultivo_intro", null,
                "As 9 grandes Seitas de Cultivo do mundo — onde aprendes técnicas, sobes de rank e ganhas o favor de uma Casa.")}
            </div>
            <div style={{ display:"grid", gap:8 }}>
              {isMember && (
                <ActionBtn variant="primary" onClick={onOpenHall}>
                  ⛩️ {safeT("seita_cultivo_btn_hall", null, "O meu Hall (técnicas · rank · quests)")}
                </ActionBtn>
              )}
              <ActionBtn variant={isMember ? "ghost" : "primary"} onClick={onOpenDirectory}>
                📜 {safeT("seita_cultivo_btn_directory", null, "Ver as 9 Seitas (técnicas · quem recruta)")}
              </ActionBtn>
            </div>
          </Card>
          <Card>
            <div style={{ fontSize:12, color:"var(--muted)", marginBottom:8 }}>
              {safeT("seita_cultivo_guild_hint", null, "Procuras a tua Guilda de jogadores?")}
            </div>
            <div style={{ display:"grid", gap:8 }}>
              <ActionBtn variant="ghost" onClick={() => setTab("guild")}>
                🤝 {safeT("tab_guild", null, "Guilda")}
              </ActionBtn>
            </div>
          </Card>
        </div>
      );
    }

    function SectTab({ player, onPlayerRefresh }) {
      const [reload, setReload] = useState(0);
      const { data, loading, error } = useApi("sect", null, [reload]);
      const [donateOpen, setDonateOpen] = useState(false);
      const [leaveOpen, setLeaveOpen] = useState(false);
      const [shopOpen, setShopOpen] = useState(false);
      // v15.3 — Sect War drill-in modal state
      const [warOpen, setWarOpen] = useState(false);
      // v16.1 — Sect Lineage drill-in + chooser modals
      const [lineageChooserOpen, setLineageChooserOpen] = useState(false);
      const [lineageInfoOpen, setLineageInfoOpen] = useState(false);
      // {action: "promote"|"kick", target: dao_name} for confirm dialog
      const [memberAction, setMemberAction] = useState(null);
      // 幫 4.2 — a planta das seis instalações, só com a chave-mestra. ⚠️ TODOS
      // os estados nascem aqui, antes dos `return` de baixo (React #310).
      const onda = obraOn();
      const [guildaSel, setGuildaSel] = useState(null);       // a instalação lida
      const [guildaOv, setGuildaOv] = useState(null);         // { depois, dados }
      const [guildaAcende, setGuildaAcende] = useState(null); // { key, k }
      const [guildaRecibo, setGuildaRecibo] = useState(null); // { linhas, k }
      const [guildaBusy, setGuildaBusy] = useState(null);     // a instalação em melhoria
      const [guildaErro, setGuildaErro] = useState(null);
      const [guildaRolar, setGuildaRolar] = useState(0);
      const guildaRef = useRef(null);
      useEffect(() => {
        if (!guildaAcende) return undefined;
        const id = setTimeout(() => setGuildaAcende(null), 900);
        return () => clearTimeout(id);
      }, [guildaAcende]);
      // a luz tem de se VER: a planta e o recibo voltam à vista juntos (a lição da
      // 3.3). ⚠️ Olhado a 390: numa ABA (não numa janela, como o Salão) a barra
      // de baixo é `absolute` e tapa os últimos 85 px da área rolável — alinhar
      // o fundo da planta com o fundo da área punha o recibo POR TRÁS da barra.
      // A margem vive na planta (`scrollMarginBottom`) e a conta lê a área real.
      useEffect(() => {
        if (!guildaRolar || !guildaRef.current) return;
        try {
          const el = guildaRef.current;
          const area = el.closest && el.closest(".scroll-area");
          const topo = area ? area.getBoundingClientRect().top : 0;
          const r = el.getBoundingClientRect();
          if (r.top >= topo && r.bottom <= (window.innerHeight || 0) - GUILDA_FOLGA_BAIXO) return;
          const reduz = window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches;
          el.scrollIntoView({ behavior: reduz ? "auto" : "smooth", block: "nearest" });
        } catch (e) { /* sem rolagem, a leitura continua certa */ }
      }, [guildaRolar]);

      const refresh = useCallback(() => {
        setReload(x => x + 1);
        onPlayerRefresh && onPlayerRefresh();
      }, [onPlayerRefresh]);

      // UMA porta para o ganho confirmado: a melhoria. Só o `guilda_ganho` do
      // servidor acende; nunca o toque.
      function aplicarGanhoGuilda(g, dadosVelhos) {
        if (!onda || !g) return;
        setGuildaRecibo({ linhas: reciboDaGuilda(g), k: Date.now() });
        if (g.depois && dadosVelhos) setGuildaOv({ depois: g.depois, dados: dadosVelhos });
        if ((g.acende || []).indexOf("nivel") >= 0) setGuildaAcende({ key: g.depois.key, k: Date.now() });
        setGuildaRolar(x => x + 1);
      }

      // 幫 4.2 — a melhoria da onda: a MESMA rota, e o que ela CONFIRMOU fica na
      // planta (o recibo, a instalação que acende) em vez de um toast que some.
      async function melhorarOnda(key) {
        if (guildaBusy) return;
        setGuildaBusy(key); setGuildaErro(null); haptic("warning");
        const dadosVelhos = data;
        try {
          const res = await api("sect/upgrade", { building: key });
          if (res && res.ok) {
            haptic("success");
            aplicarGanhoGuilda(res.guilda_ganho, dadosVelhos);
            refresh();
          } else {
            haptic("error");
            const m = { insufficient_stones: "sect_err_insufficient_stones", rank_too_low: "sect_err_rank_too_low",
                        not_in_sect: "sect_err_not_in_sect" };
            setGuildaErro(t(m[res && res.reason] || "sect_err_engine"));
          }
        } catch (e) { haptic("error"); setGuildaErro(t("sect_err_engine")); }
        finally { setGuildaBusy(null); }
      }

      // com a onda a planta continua à vista durante a releitura (o "depois"
      // confirmado pousa por cima dos dados até a releitura o apanhar)
      if (loading && !(onda && data && data.sect)) return <ListSkeleton rows={8} />;
      if (error) return <ErrBanner msg={error} />;
      if (!data?.sect) {
        return <SectCreateOrJoin onDone={refresh} />;
      }

      const s = data.sect;
      const myRank = s.your_rank;
      const isMasterOrElder = myRank === "master" || myRank === "elder";
      const isMaster = myRank === "master";
      const BUILDING_ICONS = { training:"⚔️", herb_garden:"🌿", forge:"⚒️", library:"📜", defense:"🛡️", spirit_vein:"💫" };
      const BUILDING_LABELS = { training:t("b_training"), herb_garden:t("b_garden"), forge:t("b_forge"),
                                 library:t("b_library"), defense:t("b_defense"), spirit_vein:t("b_spirit_vein") };
      const RANK_LABEL = { master:t("rank_master"), elder:t("rank_elder"), member:t("rank_member"), disciple:t("rank_disciple") };
      // Cost = 1000 * (lvl+1)^2  (mirror of core.sect_engine.calculate_upgrade_cost)
      const upgradeCost = (lvl) => 1000 * Math.pow(lvl + 1, 2);
      // 幫 4.2 — a planta só se desenha com a onda E com a planta do servidor
      // (o nível, o número do efeito e o custo, tudo do motor). Sem ela, a aba
      // de hoje inteira — nunca uma planta com números inventados no cliente.
      const plantaOk = onda && Array.isArray(s.planta) && s.planta.length > 0;
      const guildaPend = !!(plantaOk && guildaOv && guildaOv.dados === data);
      const tesouroVisto = guildaPend ? guildaOv.depois.treasury : s.spirit_stones;

      return (
        <div>
          <Card>
            <CardTitle left={s.name} right={plantaOk ? undefined : `${s.member_count}/${s.max_members}`} />
            {s.bulletin && (
              <div style={{
                fontSize:12, color:"var(--muted)", fontStyle:"italic",
                padding:"2px 0 10px", borderBottom:"1px dashed rgba(var(--glow-rgb),.2)", marginBottom:10,
              }}>"{s.bulletin}"</div>
            )}
            <StatGrid stats={plantaOk ? [
              /* 幫 4.2 — os números INTEIROS e nomeados; os membros são ocupação
                 ("49 de 50"); e NADA soma as seis instalações num "nível da
                 guilda" que não existe (a linha do Astra) */
              { label: t("treasury"), value: fmtFull(tesouroVisto) },
              { label: t("your_contribution"), value: fmtFull(s.your_contribution) },
              { label: t("your_rank"), value: RANK_LABEL[s.your_rank] || s.your_rank },
              { label: t("guilda_onda_membros"),
                value: t("guilda_onda_membros_de", { n: fmtFull(s.member_count), max: fmtFull(s.max_members) }) },
            ] : [
              { label: t("treasury"), value: `🪨 ${fmtNum(s.spirit_stones)}` },
              { label: t("your_contribution"), value: fmtNum(s.your_contribution) },
              { label: t("your_rank"), value: RANK_LABEL[s.your_rank] || s.your_rank },
              { label: t("buildings"), value: Object.values(s.buildings).reduce((a,b)=>a + (typeof b === "object" ? (b.level||0) : (b||0)), 0) },
            ]} />
            <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:6, marginTop:10 }}>
              <ActionBtn variant="primary" onClick={() => setDonateOpen(true)}>
                💰 {t("sect_btn_donate")}
              </ActionBtn>
              <ActionBtn variant="ghost" onClick={() => setShopOpen(true)}>
                🛒 {t("sect_btn_shop")}
              </ActionBtn>
              {/* v15.3 — War drill-in (was chat inline only) */}
              <ActionBtn variant="ghost" onClick={() => setWarOpen(true)}>
                ⚔️ {safeT("sect_btn_war")}
              </ActionBtn>
              <ActionBtn variant="danger" onClick={() => setLeaveOpen(true)}>
                🚪 {t("sect_btn_leave")}
              </ActionBtn>
            </div>
            {/* v14.13d (2026-05-25) — Owner P2 backlog: backend devolve
                `group_link` mas client nunca usou. Mostra o Telegram group
                link da seita como chip clicável quando present. Tap → abre
                no Telegram via tg.openTelegramLink (mantém within-app). */}
            {s.group_link && (
              <div style={{ marginTop:10 }}>
                <button onClick={() => {
                  haptic("select");
                  try {
                    if (tg?.openTelegramLink) tg.openTelegramLink(s.group_link);
                    else window.open(s.group_link, "_blank");
                  } catch (e) {
                    window.open(s.group_link, "_blank");
                  }
                }} style={{
                  width:"100%", padding:"9px 10px", borderRadius:8,
                  cursor:"pointer", display:"flex", alignItems:"center", gap:8,
                  background:"linear-gradient(180deg,rgba(var(--realm-1-rgb),.12),rgba(30,55,110,.35))",
                  border:"1px solid rgba(var(--realm-1-rgb),.4)",
                  color:"var(--gold3)",
                  fontFamily:"'Cinzel',serif", fontSize:11, letterSpacing:.4,
                }}>
                  <span style={{ fontSize:18 }}>📨</span>
                  <span style={{ flex:1, textAlign:"left",
                                 overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap" }}>
                    {t("sect_open_group_chat")}
                  </span>
                  <span style={{ fontSize:14 }}>›</span>
                </button>
              </div>
            )}
          </Card>

          {/* v16.1 — Sect Lineage block. NULL → pulsing CTA to chooser.
              SET → display card click → LineageInfoModal. Server-authoritative;
              only master/elder rows trigger the chooser (UI guard, server gates). */}
          <Card>
            <CardTitle left={`🏯 ${safeT("sect_lineage_label")}`} />
            {s.lineage_meta_resolved ? (
              <button onClick={() => { haptic("select"); setLineageInfoOpen(true); }}
                style={{
                  width:"100%", textAlign:"left", padding:"10px 12px",
                  borderRadius:10, cursor:"pointer", display:"grid", gap:6,
                  background:"linear-gradient(180deg,rgba(var(--gold2-rgb),.06),rgba(30,40,80,.20))",
                  border:"1px solid rgba(var(--gold2-rgb),.30)",
                  color:"var(--text)",
                }}>
                <div style={{ display:"flex", alignItems:"center", gap:10 }}>
                  <span style={{ fontSize:26, lineHeight:1 }}>
                    {s.lineage_meta_resolved.emoji}
                  </span>
                  <div style={{ flex:1, minWidth:0 }}>
                    <div style={{ fontFamily:"'Cinzel',serif", fontWeight:700,
                                   color:"var(--gold2)", fontSize:13, letterSpacing:.4 }}>
                      {s.lineage_meta_resolved.name}
                    </div>
                    <div style={{ fontSize:10, color:"var(--muted)", marginTop:2,
                                   fontStyle:"italic", lineHeight:1.4,
                                   overflow:"hidden", textOverflow:"ellipsis",
                                   whiteSpace:"nowrap" }}>
                      "{s.lineage_meta_resolved.philosophy}"
                    </div>
                  </div>
                  <span style={{ fontSize:14, color:"var(--muted)" }}>›</span>
                </div>
                {(s.lineage_meta_resolved.bonuses || []).length > 0 && (
                  <div style={{ display:"flex", flexWrap:"wrap", gap:4,
                                 borderTop:"1px dashed var(--border)", paddingTop:6 }}>
                    {s.lineage_meta_resolved.bonuses.slice(0, 4).map((b) => (
                      <span key={b.key} style={{
                        fontSize:10, color:"rgba(var(--text2-rgb),.85)",
                        padding:"1px 6px", borderRadius:7,
                        background:"rgba(var(--jade-rgb),.08)",
                        border:"1px solid rgba(var(--jade-rgb),.28)",
                      }}>
                        {b.label} {b.value}
                      </span>
                    ))}
                  </div>
                )}
              </button>
            ) : (
              <div style={{ display:"grid", gap:7 }}>
                {/* v16.4 (Sect-Guild Split SHIPPED) — the chooser is GONE.
                    The 9 lineages are now LIVING NPC houses (world_sects)
                    that a cultivator JOINS organically via affinity (path +
                    continent + karma + lineage holdover), not by picking from
                    a menu (Lei §2). This note points the player at the new
                    system — the Seita de Cultivo directory via Profile 🏯. The old
                    LineageChooserModal below is inert (no CTA reaches it). */}
                <div style={{
                  padding:"10px 12px", borderRadius:10,
                  background:"rgba(var(--gold2-rgb),.06)",
                  border:"1px dashed rgba(var(--gold2-rgb),.30)",
                  fontSize:11.5, color:"rgba(var(--text2-rgb),.90)", lineHeight:1.5,
                  fontStyle:"italic",
                }}>
                  🏯 {safeT("wsect_lineage_migrated_note")}
                </div>
              </div>
            )}
          </Card>

          {plantaOk ? (
            <GuildaPlanta planta={s.planta} ov={guildaPend ? guildaOv : null} tesouro={tesouroVisto}
                          sel={guildaSel} onSel={setGuildaSel} acende={guildaAcende}
                          recibo={guildaRecibo} plantaRef={guildaRef} busy={guildaBusy}
                          erro={guildaErro} podeMelhorar={isMasterOrElder} onMelhorar={melhorarOnda} />
          ) : (
          <Card>
            <CardTitle left={t("buildings")} />
            <div style={{ display:"grid", gridTemplateColumns:"repeat(3,1fr)", gap:8 }}>
              {Object.entries(s.buildings).map(([k, raw]) => {
                // D (2026-06-16): api_sect now ships {level, effect}; accept the old
                // int payload too (backwards-compat during rollout).
                const lvl = (raw && typeof raw === "object") ? (raw.level || 0) : (raw || 0);
                const effect = (raw && typeof raw === "object") ? raw.effect : null;
                const cost = upgradeCost(lvl);
                const canAfford = s.spirit_stones >= cost;
                return (
                  <div key={k} style={{
                    background:"rgba(0,0,0,.3)", border:"1px solid rgba(var(--glow-rgb),.18)",
                    borderRadius:10, padding:"10px 8px 8px", textAlign:"center",
                    display:"flex", flexDirection:"column", gap:4,
                  }}>
                    <div style={{ fontSize:22 }}>{BUILDING_ICONS[k]}</div>
                    <div style={{ fontSize:9.5, color:"var(--muted)", textTransform:"uppercase", letterSpacing:.5 }}>{BUILDING_LABELS[k]}</div>
                    <div style={{ fontSize:13, fontWeight:600, color: lvl > 0 ? "var(--gold2)" : "var(--muted2)" }}>
                      {lvl > 0 ? `${t("level_short")} ${lvl}` : "—"}
                    </div>
                    {effect && lvl > 0 && (
                      <div style={{ fontSize:9.5, fontWeight:600, color:"var(--jade)", lineHeight:1.2 }}>{effect}</div>
                    )}
                    {isMasterOrElder && (
                      <SectUpgradeBtn
                        building={k} cost={cost} canAfford={canAfford}
                        onDone={refresh}
                      />
                    )}
                  </div>
                );
              })}
            </div>
          </Card>
          )}

          <Card>
            <CardTitle left={t("members")} right={data.members.length} />
            {data.members.map((m, i) => {
              const rankBadge = m.rank === "master" ? <Badge variant="gold">{t("rank_master")}</Badge>
                              : m.rank === "elder"  ? <Badge variant="warn">{t("rank_elder")}</Badge>
                              : null;
              // Action gates mirror server-side rules in core.sect_engine
              // (master kicks anyone except self/master; elder kicks disciples
              // only; promote disciple→elder is master-only).
              const isSelf = m.name === data.sect.your_dao_name; // best-effort; server is authoritative
              const canPromote = isMaster && m.rank === "disciple" && !isSelf;
              const canKick = !isSelf && m.rank !== "master" && (
                isMaster || (myRank === "elder" && m.rank === "disciple")
              );
              return (
                <div key={i} style={{
                  display:"flex", alignItems:"center", gap:8, padding:"6px 0",
                  borderBottom: i < data.members.length - 1 ? "1px solid rgba(var(--glow-rgb),.12)" : "none",
                }}>
                  <div style={{
                    width:22, textAlign:"center", color:"var(--muted)",
                    fontFamily:"'Cinzel',serif", fontSize:11,
                  }}>{i + 1}</div>
                  <div style={{ flex:1, minWidth:0 }}>
                    <div style={{ display:"flex", gap:6, alignItems:"center", flexWrap:"wrap" }}>
                      <span style={{ fontSize:12.5, color:"var(--text)", overflow:"hidden", textOverflow:"ellipsis" }}>{m.name}</span>
                      {rankBadge}
                    </div>
                    <div style={{ fontSize:10, color:"var(--muted)", marginTop:1 }}>
                      {m.realm_emoji} {m.sub_layer} · ☯️ {fmtNum(m.contribution)}
                    </div>
                  </div>
                  {(canPromote || canKick) && (
                    <div style={{ display:"flex", gap:4 }}>
                      {canPromote && (
                        <button onClick={() => { haptic("light"); setMemberAction({ action:"promote", target:m.name, current_rank:m.rank }); }}
                          title={t("sect_btn_promote")} style={{
                            width:28, height:28, borderRadius:7, padding:0, cursor:"pointer",
                            background:"rgba(var(--gold2-rgb),.12)", border:"1px solid rgba(var(--gold2-rgb),.42)",
                            color:"var(--gold2)", fontSize:13,
                          }}>⬆️</button>
                      )}
                      {canKick && (
                        <button onClick={() => { haptic("light"); setMemberAction({ action:"kick", target:m.name, current_rank:m.rank }); }}
                          title={t("sect_btn_kick")} style={{
                            width:28, height:28, borderRadius:7, padding:0, cursor:"pointer",
                            background:"rgba(var(--red-rgb),.1)", border:"1px solid rgba(var(--red-rgb),.42)",
                            color:"var(--red2)", fontSize:13,
                          }}>✕</button>
                      )}
                    </div>
                  )}
                </div>
              );
            })}
          </Card>

          {donateOpen && (
            <SectDonateModal
              currentTreasury={s.spirit_stones}
              currentContribution={s.your_contribution}
              playerStones={player?.spirit_stones || 0}
              onClose={() => setDonateOpen(false)}
              onDone={refresh}
            />
          )}
          {leaveOpen && (
            <SectLeaveConfirm
              isMaster={isMaster}
              memberCount={s.member_count}
              onClose={() => setLeaveOpen(false)}
              onDone={refresh}
            />
          )}
          {shopOpen && (
            <SectShopPanel
              onClose={() => setShopOpen(false)}
              onBuyDone={refresh}
            />
          )}
          {/* v15.3 — Sect War drill-in modal (engine reuse: same register_war_attack) */}
          {warOpen && (
            <SectWarPanel onClose={() => setWarOpen(false)} onDone={refresh} />
          )}
          {memberAction && (
            <SectMemberActionConfirm
              action={memberAction.action}
              target={memberAction.target}
              currentRank={memberAction.current_rank}
              onClose={() => setMemberAction(null)}
              onDone={() => { setMemberAction(null); refresh(); }}
            />
          )}
          {/* v16.1 — Sect Lineage modals */}
          {lineageChooserOpen && (
            <LineageChooserModal
              onClose={() => setLineageChooserOpen(false)}
              onChosen={() => { setLineageChooserOpen(false); refresh(); }}
            />
          )}
          {lineageInfoOpen && (
            <LineageInfoModal
              onClose={() => setLineageInfoOpen(false)}
              lineageMeta={s.lineage_meta_resolved}
            />
          )}
        </div>
      );
    }

    // ─── Sect: building upgrade button ──────────────────────────────────────
    function SectUpgradeBtn({ building, cost, canAfford, onDone }) {
      const [busy, setBusy] = useState(false);
      const [err, setErr] = useState(null);
      async function doUpgrade() {
        if (busy || !canAfford) return;
        setBusy(true); setErr(null); haptic("warning");
        try {
          const res = await api("sect/upgrade", { building });
          if (!res.ok) {
            haptic("error");
            setErr(t(`sect_err_${res.reason || "engine"}`) || res.reason || "Error");
            setBusy(false);
            return;
          }
          haptic("success");
          showToast(t("sect_upgrade_toast", { name: t(`b_${building === "herb_garden" ? "garden" : building}`), level: res.new_level }));
          setBusy(false);
          onDone && onDone();
        } catch (e) { haptic("error"); setErr(t("sect_err_engine")); setBusy(false); }
      }
      return (
        <>
          <button onClick={doUpgrade} disabled={busy || !canAfford} style={{
            marginTop:2, padding:"4px 6px", borderRadius:6, fontSize:10,
            fontFamily:"'Cinzel',serif", letterSpacing:.4, cursor: (busy || !canAfford) ? "default" : "pointer",
            background: canAfford ? "rgba(var(--jade-rgb),.12)" : "rgba(0,0,0,.3)",
            border:`1px solid ${canAfford ? "rgba(var(--jade-rgb),.42)" : "rgba(var(--glow-rgb),.2)"}`,
            color: canAfford ? "var(--jade)" : "var(--muted2)",
            opacity: busy ? .6 : 1,
          }}>
            {busy ? "…" : `⬆️ ${fmtNum(cost)}`}
          </button>
          {err && <div style={{ fontSize:9, color:"var(--red2)", marginTop:2 }}>{err}</div>}
        </>
      );
    }

    // ═══ 幫 4.2 — A GUILDA: a planta das seis instalações ══════════════════════
    //
    // A linha é do Astra («Mundo · Guilda»): *"Planta das seis instalações da
    // guilda (…) cada instalação mostra o seu nível confirmado (…) Melhoria grava
    // um traço na instalação. `your_contribution` e `member_count / max_members`
    // ficam nomeados, sem somar tudo num 'nível da guilda' fictício."*
    //
    // Tudo o que a planta escreve vem do SERVIDOR (`core/guilda.py`): o nível
    // gravado, o NÚMERO do efeito (o do motor) e o custo do próximo nível. Os
    // níveis não têm teto (medido: até 856 no `main`), portanto nenhuma inscrição
    // "N de M" — o nível e o custo do próximo, nunca uma fracção inventada.
    //
    // A marca de cada instalação — UM dono (a catraca do §15: a planta nasce
    // sem emoji). O Treino é cultivo (o efeito é no cultivo); a Defesa é a
    // formação que guarda a casa; a Veia dá pedras.
    var GUILDA_MARCA = {
      training: "seated", herb_garden: "herb", forge: "sword",
      library: "brush", defense: "formation", spirit_vein: "stone",
    };
    // a barra de baixo do telefone tapa 85 px da área rolável (medido a 390×844):
    // a planta volta à vista ACIMA dela, nunca por trás
    var GUILDA_FOLGA_BAIXO = 96;

    function nomeDaInstalacao(key) {
      return t("guilda_inst_" + key);
    }

    function efeitoDaInstalacao(key, n) {
      return t("guilda_efeito_" + key, { n: fmtFull(n) });
    }

    // O recibo — só do `guilda_ganho` (o antes e o depois da MESMA transacção).
    function reciboDaGuilda(g) {
      const L = [];
      const a = g && g.antes, d = g && g.depois;
      if (a && d && Number(d.level) !== Number(a.level)) {
        L.push(t("guilda_onda_recibo_nivel", {
          nome: nomeDaInstalacao(d.key), a: fmtFull(a.level), b: fmtFull(d.level),
        }));
      }
      if (a && d && Number(d.treasury) !== Number(a.treasury)) {
        L.push(t("guilda_onda_recibo_tesouro", {
          a: fmtFull(a.treasury), b: fmtFull(d.treasury),
          d: fmtFull(Number(a.treasury) - Number(d.treasury)),
        }));
      }
      return L;
    }

    function GuildaPlanta({ planta, ov, tesouro, sel, onSel, acende, recibo, plantaRef, busy, erro,
                            podeMelhorar, onMelhorar }) {
      const P = NIV_ONDA;
      // o "depois" confirmado, por cima dos dados que AINDA não o apanharam
      const pendente = !!ov;
      const fresco = !pendente;
      const lida = planta.some(i => i.key === sel) ? sel : planta[0].key;
      // o "depois" é da MESMA transacção da melhoria (o nível, o efeito e o custo
      // do próximo, todos do motor) — a tela não muda de altura à espera da
      // releitura; só o botão espera por ela (reconciliar antes de gastar outra vez)
      function visto(inst) {
        if (pendente && ov.depois && ov.depois.key === inst.key) {
          return Object.assign({}, inst, { level: ov.depois.level, effect_n: ov.depois.effect_n,
                                           next_cost: ov.depois.next_cost });
        }
        return inst;
      }
      const atual = visto(planta.find(i => i.key === lida));
      const nivel = Number(atual.level) || 0;
      const custo = Number(atual.next_cost) || 0;
      const temTesouro = Number(tesouro) || 0;
      const basta = temTesouro >= custo;
      const rotulo = { fontFamily: P.label, fontSize: 10, lineHeight: 1.6, letterSpacing: ".16em",
                       textTransform: "uppercase", color: P.muted };
      const linha = Object.assign({}, _ONDA_TNUM, { fontSize: 12.5, lineHeight: (18 / 12.5), color: P.muted });
      return (
        <Card>
          <CardTitle left={t("guilda_onda_planta")} />
          {/* ⚠️ Olhado a 1440: em grelha de uma coluna a planta esticava até
              1.050 px e o rótulo ficava a um palmo do número. A figura e a
              leitura vão LADO A LADO quando cabem (flex que quebra): no telefone
              empilham, no PC a figura, o número, o requisito e a acção ficam juntos. */}
          <div ref={plantaRef} data-guilda-planta=""
               style={{ display: "flex", flexWrap: "wrap", alignItems: "flex-start", gap: 16,
                        scrollMarginBottom: GUILDA_FOLGA_BAIXO, scrollMarginTop: 8 }}>
            {/* o recinto: o muro, o eixo e o portão — o traço que mostra a casa */}
            <div data-guilda-recinto="" style={{ position: "relative", padding: "12px 12px 26px",
                                                 flex: "1 1 320px", maxWidth: 520, minWidth: 0 }}>
              {/* o muro com o portão a meio do lado de baixo */}
              <svg aria-hidden="true" viewBox="0 0 100 100" preserveAspectRatio="none"
                   style={{ position: "absolute", inset: 0, width: "100%", height: "100%",
                            overflow: "visible", pointerEvents: "none" }}>
                <path d="M44 100 H0 V0 H100 V100 H56" fill="none" stroke={P.edge}
                      strokeWidth="1" vectorEffect="non-scaling-stroke" />
              </svg>
              {/* o caminho que entra pelo portão até às instalações — só na folga de
                  baixo (olhado a 1440: um eixo até meio do recinto cortava o número
                  da instalação do meio, que é transparente) */}
              <span aria-hidden="true" style={{ position: "absolute", left: "50%", bottom: 0, width: 1,
                                                 height: 26, background: P.line, pointerEvents: "none" }} />
              <div style={{ position: "relative", display: "grid",
                            gridTemplateColumns: "repeat(3, minmax(0, 1fr))", gap: 8 }}>
                {planta.map(inst0 => {
                  const inst = visto(inst0);
                  const lv = Number(inst.level) || 0;
                  const eSel = inst.key === lida;
                  const nome = nomeDaInstalacao(inst.key);
                  return (
                    <button key={inst.key} type="button" data-guilda-lote={inst.key}
                            aria-pressed={eSel ? "true" : "false"}
                            aria-label={t("guilda_onda_lote_aria", { nome, n: fmtFull(lv) })}
                            onClick={() => onSel(inst.key)}
                            style={{ position: "relative", minWidth: 0, minHeight: 84, padding: "20px 6px 8px",
                                     display: "grid", justifyItems: "center", alignContent: "start", gap: 4,
                                     background: eSel ? P.wash : "transparent",
                                     border: "1px solid " + (eSel ? P.paper : P.line), borderRadius: 0,
                                     color: P.paper, cursor: "pointer", textAlign: "center",
                                     boxShadow: "none", backgroundImage: "none" }}>
                      <span aria-hidden="true" style={{ position: "absolute", left: 12, top: 12, width: 0, height: 0 }}>
                        <MarcaOnda estado={lv > 0 ? "got" : "empty"}
                                   acende={!!acende && acende.key === inst.key} />
                      </span>
                      <span aria-hidden="true" style={{ display: "inline-flex", color: lv > 0 ? P.gold : P.muted }}>
                        <Mark name={GUILDA_MARCA[inst.key] || "pagoda"} size={20} />
                      </span>
                      <span style={{ fontFamily: P.label, fontSize: 9.5, lineHeight: 1.3, letterSpacing: ".1em",
                                     textTransform: "uppercase", color: P.muted, overflowWrap: "normal",
                                     wordBreak: "normal" }}>{nome}</span>
                      <span style={Object.assign({}, _ONDA_TNUM, { fontSize: 16, lineHeight: (22 / 16),
                                     whiteSpace: "nowrap", color: lv > 0 ? P.paper : P.muted })}>{fmtFull(lv)}</span>
                    </button>
                  );
                })}
              </div>
            </div>

            {/* a leitura da instalação lida: o nome, o nível, o efeito, o próximo */}
            <div data-guilda-leitura={lida} style={{ flex: "1 1 260px", maxWidth: 460, minWidth: 0 }}>
              <div style={{ display: "flex", alignItems: "baseline", columnGap: 12, flexWrap: "wrap" }}>
                <span style={rotulo}>{nomeDaInstalacao(lida)}</span>
                <span style={Object.assign({}, _ONDA_TNUM, { marginLeft: "auto", fontSize: 16,
                                                              lineHeight: (22 / 16), color: P.paper })}>
                  {nivel > 0 ? t("guilda_onda_nivel", { n: fmtFull(nivel) }) : t("guilda_onda_por_construir")}
                </span>
              </div>
              {nivel > 0 && (
                <div style={{ display: "flex", alignItems: "baseline", columnGap: 12, marginTop: 4 }}>
                  <span style={{ fontFamily: P.body, fontSize: 13, lineHeight: (20 / 13), color: P.muted }}>
                    {t("guilda_onda_efeito")}
                  </span>
                  <span style={Object.assign({}, _ONDA_TNUM, { marginLeft: "auto", fontSize: 13,
                                                                lineHeight: (20 / 13), color: P.paper,
                                                                textAlign: "right" })}>
                    {efeitoDaInstalacao(lida, atual.effect_n)}
                  </span>
                </div>
              )}
              {/* o próximo nível: o preço e o tesouro, ANTES do toque */}
              <div style={{ marginTop: 8 }}>
                <div style={Object.assign({}, rotulo, { color: P.gold })}>
                  {t("guilda_onda_para", { n: fmtFull(nivel + 1) })}
                </div>
                <CorpoReq rotulo={t("guilda_onda_req_tesouro")} tem={fmtFull(temTesouro)}
                          precisa={fmtFull(custo)} ok={basta} />
                {!basta && (
                  <div style={linha}>{t("guilda_onda_faltam", { n: fmtFull(Math.max(0, custo - temTesouro)) })}</div>
                )}
              </div>
              {/* o RECIBO, junto da operação — só do `guilda_ganho` */}
              {recibo && recibo.linhas && recibo.linhas.length > 0 && (
                <div role="status" style={{ marginTop: 10, paddingLeft: 12, borderLeft: "1px solid " + P.gold }}>
                  {recibo.linhas.map((l, i) => (
                    <div key={i} style={Object.assign({}, _ONDA_TNUM, { fontSize: 13, lineHeight: (20 / 13),
                                                                        color: i === 0 ? P.paper : P.muted })}>{l}</div>
                  ))}
                </div>
              )}
              {erro && (
                <div style={{ marginTop: 8, fontSize: 12.5, lineHeight: (18 / 12.5), color: P.seal }}>{erro}</div>
              )}
              <div style={{ marginTop: 12 }}>
                {podeMelhorar ? (
                  <OndaBtn disabled={!!busy || !fresco || !basta} onClick={() => onMelhorar(lida)}
                           ariaLabel={t("guilda_onda_melhorar_aria", { nome: nomeDaInstalacao(lida),
                                                                       n: fmtFull(nivel + 1), c: fmtFull(custo) })}>
                    {busy === lida ? t("guilda_onda_a_melhorar") : t("guilda_onda_melhorar", { n: fmtFull(nivel + 1) })}
                  </OndaBtn>
                ) : (
                  <div style={linha}>{t("guilda_onda_so_lideres")}</div>
                )}
              </div>
            </div>
          </div>
        </Card>
      );
    }

    // ─── Sect: donate modal ─────────────────────────────────────────────────
    // Owner request 2026-05-08: must show player's stones balance + quick-fill
    // chips (25%/50%/Max) so players don't have to type. Done view (set via
    // setDone) keeps modal open with confirmation; user closes manually.
    function SectDonateModal({ currentTreasury, currentContribution, playerStones, onClose, onDone }) {
      const [amount, setAmount] = useState("");
      const [busy, setBusy] = useState(false);
      const [err, setErr] = useState(null);
      const [done, setDone] = useState(null);
      const parsed = parseInt(amount, 10);
      const valid = !isNaN(parsed) && parsed > 0 && parsed <= playerStones;
      const cpPreview = valid ? Math.floor(parsed / 100) : 0;
      const tooMuch = !isNaN(parsed) && parsed > playerStones;
      const setPct = (pct) => {
        const v = Math.max(1, Math.floor(playerStones * pct));
        setAmount(String(v));
      };
      async function submit() {
        if (busy || !valid) return;
        setBusy(true); setErr(null); haptic("warning");
        try {
          const res = await api("sect/donate", { amount: parsed });
          if (!res.ok) {
            haptic("error");
            setErr(t(`sect_err_${res.reason || "engine"}`) || res.reason);
            setBusy(false);
            return;
          }
          haptic("success");
          setDone(res);
          setBusy(false);
          onDone && onDone();
        } catch (e) { haptic("error"); setErr(t("sect_err_engine")); setBusy(false); }
      }
      // 2026-06-05 fix — the submit/confirm buttons used to live in the scrollable
      // body; on iPhone the numeric keypad covered them and the body scroll was
      // finicky (player report: "Doação pra Seita está meio bugado a tela").
      // Moving them into the Modal's STICKY footer keeps the action above the
      // keyboard (the card shrinks via 100dvh; footer stays pinned to its bottom).
      const donateFooter = !done ? (
        <ActionBtn variant="primary" disabled={busy || !valid} onClick={submit} style={{ width:"100%" }}>
          {busy ? <DotSpinner /> : `💰 ${t("sect_donate_submit")}`}
        </ActionBtn>
      ) : (
        <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:6 }}>
          <ActionBtn variant="ghost" onClick={() => { setDone(null); setAmount(""); }}>
            💰 {t("sect_donate_again")}
          </ActionBtn>
          <ActionBtn variant="primary" onClick={onClose}>{t("btn_ok")}</ActionBtn>
        </div>
      );
      return (
        <ModalShell onClose={onClose} title={`💰 ${t("sect_btn_donate")}`} accent="rgba(var(--jade-rgb),.42)" footer={donateFooter}>
          {!done ? (
            <>
              {/* Player balance card — owner request 2026-05-08. */}
              <div style={{
                display:"flex", justifyContent:"space-between", alignItems:"center",
                padding:"8px 12px", marginBottom:10, borderRadius:8,
                background:"rgba(var(--jade-rgb),.08)", border:"1px solid rgba(var(--jade-rgb),.3)",
                fontSize:12, color:"var(--jade)",
              }}>
                <span style={{ fontFamily:"'Cinzel',serif", letterSpacing:.4 }}>🪨 {t("your_stones")}</span>
                <b>{fmtNum(playerStones)}</b>
              </div>
              <div style={{ fontSize:11, color:"var(--muted)", marginBottom:8, lineHeight:1.5 }}>
                {t("sect_donate_hint")}
              </div>
              <div style={{ display:"flex", gap:6, alignItems:"center", marginBottom:6 }}>
                <input type="number" inputMode="numeric" enterKeyHint="done" min="1" max={playerStones} placeholder={t("sect_donate_placeholder")} value={amount}
                  onChange={(e) => setAmount(e.target.value.replace(/[^0-9]/g, ""))}
                  style={{
                    flex:1, padding:"10px 12px", borderRadius:8,
                    background:"rgba(0,0,0,.4)",
                    border:`1px solid ${tooMuch ? "rgba(var(--red-rgb),.6)" : "rgba(var(--jade-rgb),.4)"}`,
                    color:"var(--text)", fontSize:14, outline:"none",
                  }} />
                <span style={{ fontSize:18 }}>🪨</span>
              </div>
              {/* Quick-fill chips */}
              <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr 1fr", gap:6, marginBottom:8 }}>
                {[
                  { pct: 0.25, label: "25%" },
                  { pct: 0.50, label: "50%" },
                  { pct: 1.00, label: t("btn_max") },
                ].map(({ pct, label }) => (
                  <button key={label} onClick={() => setPct(pct)} disabled={playerStones <= 0} style={{
                    padding:"6px 8px", borderRadius:6, fontSize:11,
                    fontFamily:"'Cinzel',serif", letterSpacing:.4,
                    background:"rgba(0,0,0,.3)", border:"1px solid rgba(var(--jade-rgb),.3)",
                    color: playerStones > 0 ? "var(--jade)" : "var(--muted2)",
                    cursor: playerStones > 0 ? "pointer" : "default",
                  }}>{label}</button>
                ))}
              </div>
              {valid && (
                <div style={{ fontSize:10.5, color:"var(--gold2)", textAlign:"center", marginBottom:8 }}>
                  → +{fmtNum(cpPreview)} CP
                </div>
              )}
              {tooMuch && (
                <div style={{ fontSize:10.5, color:"var(--red2)", textAlign:"center", marginBottom:8 }}>
                  ⚠️ {t("sect_donate_too_much")}
                </div>
              )}
              {err && <ErrBanner msg={err} />}
            </>
          ) : (
            <div style={{ textAlign:"center", padding:"10px 0 14px" }}>
              <div style={{ fontSize:48, marginBottom:8, animation:"pop .35s ease-out", ...(markOn("check") ? { display:"grid", placeItems:"center" } : {}) }}>{ico("✅","check",{ size:50 })}</div>
              <div style={{ fontFamily:"'Cinzel',serif", fontSize:14, color:"var(--jade)", lineHeight:1.4 }}>
                {t("sect_donate_done", { amount: fmtNum(done.donated), cp: fmtNum(done.cp_gained) })}
              </div>
              <div style={{ fontSize:10.5, color:"var(--muted)", marginTop:10, lineHeight:1.6 }}>
                {t("treasury")}: 🪨 {fmtNum(done.sect_treasury)}
                <br />
                {t("your_contribution")}: ☯️ {fmtNum(done.your_contribution)}
                <br />
                {t("your_stones")}: 🪨 {fmtNum(done.stones_remaining)}
              </div>
            </div>
          )}
        </ModalShell>
      );
    }

    // ─── Sect: leave confirm ────────────────────────────────────────────────
    function SectLeaveConfirm({ isMaster, memberCount, onClose, onDone }) {
      const [busy, setBusy] = useState(false);
      const [err, setErr] = useState(null);
      const blockedAsMaster = isMaster && memberCount > 1;
      async function submit() {
        if (busy || blockedAsMaster) return;
        setBusy(true); setErr(null); haptic("warning");
        try {
          const res = await api("sect/leave", {});
          if (!res.ok) {
            haptic("error");
            setErr(t(`sect_err_${res.reason || "engine"}`) || res.reason);
            setBusy(false);
            return;
          }
          haptic("success");
          showToast(res.deleted_sect ? t("sect_leave_deleted") : t("sect_leave_done"));
          setBusy(false);
          onDone && onDone();
        } catch (e) { haptic("error"); setErr(t("sect_err_engine")); setBusy(false); }
      }
      return (
        <ModalShell onClose={onClose} title={`🚪 ${t("sect_btn_leave")}`} accent="rgba(var(--red-rgb),.42)">
          {blockedAsMaster ? (
            <>
              <div style={{ fontSize:12, color:"var(--red2)", textAlign:"center", padding:"8px 0", lineHeight:1.5 }}>
                ⚠️ {t("sect_err_master_must_promote_first")}
              </div>
              <ActionBtn variant="ghost" onClick={onClose}>{t("btn_close")}</ActionBtn>
            </>
          ) : (
            <>
              <div style={{ fontSize:12, color:"var(--muted)", textAlign:"center", padding:"6px 0 14px", lineHeight:1.5 }}>
                {t("sect_leave_warning")}
                {isMaster && (
                  <div style={{ marginTop:8, color:"var(--red2)" }}>
                    {t("sect_leave_master_lone")}
                  </div>
                )}
              </div>
              {err && <ErrBanner msg={err} />}
              <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:6 }}>
                <ActionBtn variant="ghost" onClick={onClose}>{t("btn_cancel")}</ActionBtn>
                <ActionBtn variant="danger" disabled={busy} onClick={submit}>
                  {busy ? <DotSpinner /> : `🚪 ${t("sect_leave_yes")}`}
                </ActionBtn>
              </div>
            </>
          )}
        </ModalShell>
      );
    }

    // ─── Sect: member action confirm (promote/kick) ─────────────────────────
    function SectMemberActionConfirm({ action, target, currentRank, onClose, onDone }) {
      const [busy, setBusy] = useState(false);
      const [err, setErr] = useState(null);
      const isPromote = action === "promote";
      async function submit() {
        if (busy) return;
        setBusy(true); setErr(null); haptic("warning");
        try {
          const res = await api(isPromote ? "sect/promote" : "sect/kick", { target_dao_name: target });
          if (!res.ok) {
            haptic("error");
            setErr(t(`sect_err_${res.reason || "engine"}`) || res.reason);
            setBusy(false);
            return;
          }
          haptic("success");
          showToast(isPromote
            ? t("sect_promote_done", { name: target })
            : t("sect_kick_done", { name: target }));
          setBusy(false);
          onDone && onDone();
        } catch (e) { haptic("error"); setErr(t("sect_err_engine")); setBusy(false); }
      }
      return (
        <ModalShell onClose={onClose}
          title={isPromote ? `⬆️ ${t("sect_btn_promote")}` : `✕ ${t("sect_btn_kick")}`}
          accent={isPromote ? "rgba(var(--gold2-rgb),.42)" : "rgba(var(--red-rgb),.42)"}>
          <div style={{ fontSize:12, color:"var(--muted)", textAlign:"center", padding:"6px 0 14px", lineHeight:1.5 }}>
            {isPromote
              ? t("sect_promote_confirm", { name: target })
              : t("sect_kick_confirm", { name: target })}
          </div>
          {err && <ErrBanner msg={err} />}
          <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:6 }}>
            <ActionBtn variant="ghost" onClick={onClose}>{t("btn_cancel")}</ActionBtn>
            <ActionBtn variant={isPromote ? "primary" : "danger"} disabled={busy} onClick={submit}>
              {busy ? <DotSpinner /> : (isPromote ? `⬆️ ${t("sect_promote_yes")}` : `✕ ${t("sect_kick_yes")}`)}
            </ActionBtn>
          </div>
        </ModalShell>
      );
    }

    // ─── Sect: shop panel (modal) ───────────────────────────────────────────
    function SectShopPanel({ onClose, onBuyDone }) {
      const [reload, setReload] = useState(0);
      const { data, loading, error } = useApi("sect/shop", null, [reload]);
      const [busyId, setBusyId] = useState(null);
      const [err, setErr] = useState(null);
      const [last, setLast] = useState(null);
      async function buy(item_id, label) {
        if (busyId) return;
        setBusyId(item_id); setErr(null); haptic("warning");
        try {
          const res = await api("sect/buy", { item_id });
          if (!res.ok) {
            haptic("error");
            setErr(t(`sect_err_${res.reason || "engine"}`, res) || res.reason);
            setBusyId(null);
            return;
          }
          haptic("success");
          setLast({ id: item_id, label });
          showToast(t("sect_shop_bought_toast", { name: label }));
          setReload(x => x + 1);
          setBusyId(null);
          onBuyDone && onBuyDone();
        } catch (e) { haptic("error"); setErr(t("sect_err_engine")); setBusyId(null); }
      }
      return (
        <ModalShell onClose={onClose} title={`🛒 ${t("sect_shop_title")}`} accent="rgba(var(--gold2-rgb),.42)" maxWidth={460}>
          {loading ? <ListSkeleton rows={4} />
          : error ? <ErrBanner msg={error} />
          : !data?.in_sect ? <div style={{ fontSize:12, color:"var(--muted)", textAlign:"center", padding:"12px 0" }}>{t("sect_err_not_in_sect")}</div>
          : (
            <>
              <div style={{
                display:"flex", justifyContent:"space-between", alignItems:"center",
                padding:"6px 10px", marginBottom:10, borderRadius:8,
                background:"rgba(var(--gold2-rgb),.08)", border:"1px solid rgba(var(--gold2-rgb),.25)",
                fontSize:11, color:"var(--gold2)",
              }}>
                <span>☯️ {t("your_cp")}</span>
                <b>{fmtNum(data.your_cp)}</b>
              </div>
              {err && <ErrBanner msg={err} />}
              <div style={{ fontSize:10, color:"var(--muted)", letterSpacing:.5, textTransform:"uppercase", marginBottom:6 }}>
                {t("sect_shop_items_header_short")}
              </div>
              {data.items.map((it) => {
                const name = safeT(it.name_key, null, "");
                const can = !it.locked && data.your_cp >= it.cost;
                return (
                  <ShopRow key={it.id} emoji={it.emoji} label={name}
                    cost={it.cost} canBuy={can} busy={busyId === it.id}
                    locked={it.locked}
                    sub={it.locked ? t("sect_shop_req_train", { lvl: it.req_lvl }) : null}
                    onBuy={() => buy(it.id, name)} />
                );
              })}
              <div style={{ fontSize:10, color:"var(--muted)", letterSpacing:.5, textTransform:"uppercase", margin:"12px 0 6px" }}>
                {t("sect_shop_scrolls_header_short")}
              </div>
              {data.scrolls.map((sc) => {
                const name = safeT(sc.name_key, null, "");
                const can = !sc.locked && !sc.already_learned && !sc.already_owned && data.your_cp >= sc.cost;
                let sub = null;
                if (sc.locked) sub = t("sect_shop_req_lib", { lvl: sc.req_library });
                else if (sc.already_learned) sub = t("sect_shop_already_learned");
                else if (sc.already_owned) sub = t("sect_shop_already_owned");
                return (
                  <ShopRow key={sc.id} emoji={sc.emoji} label={name}
                    cost={sc.cost} canBuy={can} busy={busyId === sc.id}
                    locked={sc.locked || sc.already_learned || sc.already_owned}
                    sub={sub} onBuy={() => buy(sc.id, name)} />
                );
              })}
            </>
          )}
        </ModalShell>
      );
    }

    function ShopRow({ emoji, label, cost, canBuy, busy, locked, sub, onBuy }) {
      return (
        <div style={{
          display:"flex", alignItems:"center", gap:8, padding:"8px 10px", marginBottom:5,
          background: canBuy ? "rgba(var(--jade-rgb),.05)" : "rgba(0,0,0,.25)",
          border:`1px solid ${canBuy ? "rgba(var(--jade-rgb),.25)" : "rgba(var(--glow-rgb),.18)"}`,
          borderRadius:8, opacity: locked && !canBuy ? .65 : 1,
        }}>
          <div style={{ fontSize:18 }}>{emoji}</div>
          <div style={{ flex:1, minWidth:0 }}>
            <div style={{ fontSize:12, color:"var(--text)" }}>{label}</div>
            {sub && <div style={{ fontSize:10, color:"var(--muted)" }}>{sub}</div>}
          </div>
          <button onClick={onBuy} disabled={!canBuy || busy} style={{
            padding:"6px 12px", borderRadius:6, cursor: (!canBuy || busy) ? "default" : "pointer",
            background: canBuy ? "rgba(var(--gold2-rgb),.12)" : "rgba(0,0,0,.3)",
            border:`1px solid ${canBuy ? "rgba(var(--gold2-rgb),.42)" : "rgba(var(--glow-rgb),.2)"}`,
            color: canBuy ? "var(--gold2)" : "var(--muted2)",
            fontFamily:"'Cinzel',serif", fontSize:11, fontWeight:600,
            minWidth:60,
          }}>{busy ? "…" : `${fmtNum(cost)} CP`}</button>
        </div>
      );
    }

    // ─── v15.3 — SectWarPanel (mini-app surface for sect_war chat menu) ──────
    // Drives `/api/miniapp/sect/war_info` (polled every 10s) + `/sect/war_attack`.
    // Replaces the chat inline button menu: every territory + attack action is
    // here, and the bell rings when wars start/resolve (notification_engine).
    //
    // Engine reuse: `register_war_attack` is the same call as the chat
    // handler, so contributions / attack-per-player limits / sect membership
    // gates are enforced server-side identically.
    function SectWarPanel({ onClose, onDone }) {
      const [reload, setReload] = useState(0);
      const { data, loading, error } = useApi("sect/war_info", null, [reload]);
      // Re-poll every 10s while open so the contestant BP table feels live.
      useVisibleInterval(() => setReload(x => x + 1), 10000);
      const [busyId, setBusyId] = useState(null);

      function fmtSecondsRemaining(s) {
        if (!s || s <= 0) return safeT("sect_war_window_closed");
        const m = Math.floor(s / 60);
        const ss = s % 60;
        return `${m}m ${String(ss).padStart(2, "0")}s`;
      }

      function fmtNextWarRelative(iso) {
        if (!iso) return "—";
        try {
          const target = new Date(iso);
          const now = new Date();
          const diff = (target - now) / 1000;
          if (diff <= 0) return safeT("sect_war_window_closed");
          const hours = Math.floor(diff / 3600);
          const days = Math.floor(hours / 24);
          if (days >= 1) return safeT("sect_war_next_in_days", { days });
          return safeT("sect_war_next_in_hours", { hours });
        } catch (e) {
          return "—";
        }
      }

      async function attack(territoryId) {
        if (busyId) return;
        setBusyId(territoryId);
        try {
          const res = await api("sect/war_attack", { territory_id: territoryId });
          if (!res.ok) {
            haptic("error");
            const errKey = res.reason || "sect_war_attack_failed";
            // Surface the chat-side error key directly when available; falls
            // back to the generic mini-app key.
            const localized = safeT(errKey, null, safeT("sect_war_attack_failed"));
            showToast(localized, "err");
            return;
          }
          haptic("success");
          showToast(safeT("sect_war_attack_success", {
            terr: res.territory_id, bp: fmtNum(res.bp_contributed),
          }));
          setReload(x => x + 1);
          if (onDone) onDone();
        } catch (e) {
          haptic("error");
          showToast(e.message || safeT("sect_war_attack_failed"), "err");
        } finally {
          setBusyId(null);
        }
      }

      return (
        <Modal onClose={onClose} title={`⚔️ ${safeT("sect_war_modal_title")}`}>
          <div style={{ display:"grid", gap:11, fontSize:12 }}>
            {error && <ErrBanner msg={error} />}
            {loading && !data && <ListSkeleton rows={5} />}

            {data && !data.active && (
              <Card style={{ padding:"11px 13px", display:"grid", gap:6 }}>
                <div style={{ fontFamily:"'Cinzel',serif", fontWeight:700,
                              color:"var(--gold2)", fontSize:13, letterSpacing:.4 }}>
                  🏯 {safeT("sect_war_inactive_header")}
                </div>
                <div style={{ fontSize:11, color:"var(--muted)" }}>
                  📅 {safeT("sect_war_next_label")}: {fmtNextWarRelative(data.next_war_at)}
                </div>
                <div style={{ fontSize:11, color:"var(--muted)" }}>
                  {safeT("sect_war_rules_compact")}
                </div>
              </Card>
            )}

            {data && data.active && (
              <Card style={{ padding:"11px 13px", display:"grid", gap:7 }}>
                <div style={{ display:"flex", alignItems:"center", gap:8 }}>
                  <div style={{ fontSize:22 }}>⚔️</div>
                  <div style={{ flex:1, minWidth:0 }}>
                    <div style={{ fontFamily:"'Cinzel',serif", fontWeight:700,
                                  color:"var(--red)", fontSize:13, letterSpacing:.4 }}>
                      {safeT("sect_war_active_header")}
                    </div>
                    <div style={{ fontSize:10.5, color:"var(--muted)" }}>
                      ⏳ {fmtSecondsRemaining(data.seconds_remaining)}
                      {" · "}
                      {safeT("sect_war_participants", { n: (data.participating_sects || []).length })}
                    </div>
                  </div>
                </div>
                {data.my_sect_in_war ? (
                  <div style={{ fontSize:11, color:"var(--text)" }}>
                    🏯 {safeT("sect_war_your_sect", { name: data.my_sect_name || "—" })}
                    {" · "}
                    <span style={{ color:"var(--jade)" }}>
                      {safeT("sect_war_your_contribution", { bp: fmtNum(data.my_sect_bp_total) })}
                    </span>
                    {data.already_attacked && (
                      <span style={{ marginLeft:6, color:"var(--red2)" }}>
                        · {safeT("sect_war_already_attacked_short")}
                      </span>
                    )}
                  </div>
                ) : (
                  <div style={{ fontSize:11, color:"var(--muted)", fontStyle:"italic" }}>
                    {data.my_sect_id
                      ? safeT("sect_war_sect_not_participating")
                      : safeT("sect_war_not_in_sect")}
                  </div>
                )}
              </Card>
            )}

            {/* Territories list */}
            {data && (data.territories || []).map(terr => {
              const canAttack = data.active
                && data.my_sect_in_war
                && !data.already_attacked;
              const myScore = terr.my_sect_score || 0;
              const leader = terr.leader;
              const winning = leader && leader.is_mine;
              return (
                <Card key={terr.id} style={{ padding:"10px 12px", display:"grid", gap:6 }}>
                  <div style={{ display:"flex", alignItems:"baseline", gap:6 }}>
                    <div style={{ fontFamily:"'Cinzel',serif", fontWeight:700,
                                  fontSize:12.5, color:"var(--gold2)", flex:1, letterSpacing:.4 }}>
                      🏴 {terr.name}
                    </div>
                    {terr.current_owner_name && (
                      <div style={{ fontSize:10, color:"var(--muted)" }}>
                        {safeT("sect_war_owner_label", { owner: terr.current_owner_name })}
                        {terr.expires_in_days != null && terr.expires_in_days > 0 && (
                          <span> · {safeT("sect_war_owner_expires_days", { days: terr.expires_in_days })}</span>
                        )}
                      </div>
                    )}
                  </div>
                  <div style={{ fontSize:10, color:"var(--muted)" }}>
                    💰 {fmtNum(terr.bonus_stones)} {safeT("sect_war_stones_per_tick")}
                    {" · "}
                    ⚡ +{Math.round((terr.bonus_cb || 0) * 100)}% CB
                  </div>

                  {data.active && (terr.contestants || []).length > 0 && (
                    <div style={{ display:"grid", gap:3, fontSize:10.5,
                                   borderTop:"1px dashed var(--border)", paddingTop:5 }}>
                      {terr.contestants.slice(0, 5).map(c => (
                        <div key={c.sect_id} style={{ display:"flex",
                                                       justifyContent:"space-between",
                                                       color: c.is_mine ? "var(--jade)" : "var(--text)" }}>
                          <span>{c.is_mine ? "→ " : "  "}{c.name}</span>
                          <span style={{ fontFamily:"'Cinzel',serif", fontWeight:600 }}>
                            {fmtNum(c.bp)} BP
                          </span>
                        </div>
                      ))}
                    </div>
                  )}

                  {data.active && data.my_sect_in_war && (
                    <div style={{ display:"flex", alignItems:"center", gap:6, marginTop:3 }}>
                      <div style={{ fontSize:10, color:"var(--muted)", flex:1 }}>
                        {winning
                          ? safeT("sect_war_status_winning", { bp: fmtNum(myScore) })
                          : myScore > 0
                            ? safeT("sect_war_status_contributed", { bp: fmtNum(myScore) })
                            : safeT("sect_war_status_no_contribution")}
                      </div>
                      <ActionBtn variant="primary" disabled={!canAttack || busyId === terr.id}
                                 onClick={() => attack(terr.id)}
                                 style={{ padding:"6px 11px", fontSize:11 }}>
                        {busyId === terr.id ? "…" : `⚔️ ${safeT("sect_war_btn_attack")}`}
                      </ActionBtn>
                    </div>
                  )}
                </Card>
              );
            })}

            {data && (data.territories || []).length === 0 && (
              <div style={{ fontSize:11, color:"var(--muted)", textAlign:"center", padding:"12px 0" }}>
                {safeT("sect_war_no_territories_yet")}
              </div>
            )}
          </div>
        </Modal>
      );
    }

    // ─── v16.0 — Continent Modal (World Foundation drill-in) ────────────────
    // Reads /api/miniapp/world/continent_info. Renders the player's
    // current+home continent at the top + the directory of all five
    // continents. Lei §1 (honest disclosure): every continent is visible,
    // but those the player cannot yet reach (Mòyǔ, locked behind Demonic
    // Path) carry an explicit lock badge + i18n explanation. Travel itself
    // ships in v16.0b — we communicate that inline instead of teasing a
    // dead button.
    //
    // Element pictograms are local — no extra i18n round-trip for the few
    // short symbol labels. Future v16.x can swap to i18n if the colour
    // schemes get richer.
    var CONTINENT_ELEMENT_ICONS = {
      universal: "🌐",
      water:     "💧",
      ice:       "❄️",
      earth:     "🪨",
      wind:      "🌬️",
      wood:      "🌿",
      light:     "☀️",
      fire:      "🔥",
      lightning: "⚡",
      chaos:     "🌀",
      shadow:    "🌑",
      death:     "💀",
    };

    function ContinentModal({ onClose }) {
      const { data, loading, error } = useApi("world/continent_info", null, []);

      return (
        <Modal onClose={onClose} title={`🗺️ ${safeT("world_continent_title")}`}>
          {/* QoL 31/07 — sweep do fix do Salão: grid sem template estica com filho nowrap */}
          <div style={{ display:"grid", gridTemplateColumns:"minmax(0, 1fr)", gap:11, fontSize:12 }}>
            {error && <ErrBanner msg={error} />}
            {loading && !data && <ListSkeleton rows={6} />}

            {data && data.ok !== false && (
              <>
                {/* ── Current continent (hero card) ─────────────────── */}
                <Card style={{ padding:"13px 14px", display:"grid", gap:7 }}>
                  <div style={{ display:"flex", alignItems:"center", gap:11 }}>
                    <div style={{ fontSize:34, lineHeight:1 }}>
                      {data.current && data.current.emoji}
                    </div>
                    <div style={{ flex:1, minWidth:0 }}>
                      <div style={{ fontFamily:"'Cinzel',serif", fontWeight:700,
                                     color:"var(--gold2)", fontSize:14, letterSpacing:.5,
                                     whiteSpace:"nowrap", overflow:"hidden", textOverflow:"ellipsis" }}>
                        {data.current && data.current.name}
                      </div>
                      <div style={{ fontSize:10.5, color:"var(--muted)",
                                     fontStyle:"italic", marginTop:2, lineHeight:1.4 }}>
                        {data.current && data.current.subtitle}
                      </div>
                    </div>
                  </div>

                  {data.current && (data.current.elements || []).length > 0 && (
                    <div style={{ display:"flex", flexWrap:"wrap", gap:5, alignItems:"center",
                                   borderTop:"1px dashed var(--border)", paddingTop:7 }}>
                      <span style={{ fontSize:10, color:"var(--muted)", marginRight:4 }}>
                        {safeT("continent_elements_label")}:
                      </span>
                      {(data.current.elements || []).map((el) => (
                        <span key={el} style={{
                          display:"inline-flex", alignItems:"center", gap:3,
                          padding:"2px 7px", borderRadius:10,
                          background:"rgba(160,200,255,.10)",
                          border:"1px solid rgba(160,200,255,.28)",
                          fontSize:10.5, color:"rgba(var(--text2-rgb),.92)",
                        }}>
                          <span>{CONTINENT_ELEMENT_ICONS[el] || "·"}</span>
                          <span style={{ letterSpacing:.3 }}>{safeT(`world_element_${el}`, null, el)}</span>
                        </span>
                      ))}
                    </div>
                  )}

                  {data.is_traveling && data.home && (
                    <div style={{ fontSize:10.5, color:"var(--jade)",
                                   borderTop:"1px dashed var(--border)", paddingTop:6 }}>
                      🏠 {safeT("world_home_continent_label")}: {data.home.emoji} {data.home.name}
                    </div>
                  )}

                  {data.current && data.current.lore && (
                    <div style={{ fontSize:11, color:"rgba(var(--text2-rgb),.85)",
                                   fontStyle:"italic", lineHeight:1.5,
                                   borderTop:"1px dashed var(--border)", paddingTop:7 }}>
                      “{data.current.lore}”
                    </div>
                  )}
                </Card>

                {/* ── Honest disclosure: travel unavailable in v16.0 ── */}
                {data.travel_available === false && (
                  <Card style={{ padding:"10px 13px",
                                  background:"rgba(var(--gold2-rgb),.06)",
                                  borderColor:"rgba(var(--gold2-rgb),.35)" }}>
                    <div style={{ fontSize:11, color:"rgba(245,220,160,.95)", lineHeight:1.45 }}>
                      {safeT("world_travel_unavailable")}
                    </div>
                  </Card>
                )}

                {/* ── Directory of all 5 continents ─────────────────── */}
                <div style={{ display:"grid", gap:7 }}>
                  {(data.all_continents || []).map((c) => {
                    const isCurrent = data.current && c.key === data.current.key;
                    const locked = !!c.locked;
                    return (
                      <Card key={c.key} style={{
                        padding:"10px 12px",
                        opacity: locked ? 0.78 : 1,
                        borderColor: isCurrent ? "rgba(var(--jade-rgb),.55)" : undefined,
                        boxShadow: isCurrent ? "0 0 12px rgba(var(--jade-rgb),.18)" : undefined,
                      }}>
                        <div style={{ display:"flex", alignItems:"center", gap:9 }}>
                          <div style={{ fontSize:22, lineHeight:1,
                                         filter: locked ? "grayscale(.6)" : "none" }}>
                            {c.emoji}
                          </div>
                          <div style={{ flex:1, minWidth:0 }}>
                            <div style={{ fontFamily:"'Cinzel',serif", fontWeight:700,
                                           fontSize:12.5, color: isCurrent ? "var(--jade)" : "var(--gold2)",
                                           letterSpacing:.4, display:"flex", alignItems:"center", gap:6 }}>
                              <span>{c.name}</span>
                              {isCurrent && <span style={{ fontSize:9, color:"var(--jade)",
                                              border:"1px solid rgba(var(--jade-rgb),.45)",
                                              padding:"1px 5px", borderRadius:8 }}>•</span>}
                              {locked && <span style={{ fontSize:11 }}>{ico("🔒","lock",{ size:12, style:{ display:"inline-block", verticalAlign:"-2px" } })}</span>}
                            </div>
                            <div style={{ fontSize:10.5, color:"var(--muted)", marginTop:2,
                                           fontStyle:"italic", lineHeight:1.35 }}>
                              {c.subtitle}
                            </div>
                          </div>
                        </div>
                        {locked && (
                          <div style={{ marginTop:6, fontSize:10, color:"var(--red2)",
                                         borderTop:"1px dashed var(--border)", paddingTop:5 }}>
                            {safeT("world_demonic_locked")}
                          </div>
                        )}
                        {(c.elements || []).length > 0 && !locked && (
                          <div style={{ marginTop:6, display:"flex", flexWrap:"wrap", gap:4 }}>
                            {c.elements.map((el) => (
                              <span key={el} style={{
                                fontSize:10, color:"rgba(var(--text2-rgb),.78)",
                                padding:"1px 5px", borderRadius:7,
                                background:"rgba(160,200,255,.07)",
                                border:"1px solid rgba(160,200,255,.18)",
                              }}>
                                {CONTINENT_ELEMENT_ICONS[el] || "·"} {safeT(`world_element_${el}`, null, el)}
                              </span>
                            ))}
                          </div>
                        )}
                      </Card>
                    );
                  })}
                </div>
              </>
            )}
          </div>
        </Modal>
      );
    }

    // ─── v16.1 — Sect Lineage modals (chooser + info) ────────────────────────
    // Reuse the canonical `Modal` shell. Both modals are local to the SectTab
    // mount tree but exposed at the module scope so the SectTab card can
    // open/close them through state. Demonic gating uses the server-returned
    // `player_is_demonic` flag — server is still authoritative (set_sect_lineage
    // re-checks), client just renders the visual lock.

    function LineageChooserModal({ onClose, onChosen }) {
      const { data, loading, error } = useApi("world/lineage_info", null, []);
      const [pendingKey, setPendingKey] = useState(null);   // confirmation step
      const [busy, setBusy] = useState(false);
      const [submitErr, setSubmitErr] = useState(null);

      const playerIsDemonic = !!(data && data.player_is_demonic);

      async function confirmChoice(key) {
        if (busy) return;
        setBusy(true); setSubmitErr(null); haptic("warning");
        try {
          const res = await api("sect/lineage_choose", { lineage_key: key });
          if (!res || res.ok === false) {
            const reason = (res && res.reason) || "lineage_choose_failed";
            setSubmitErr(safeT(`err_${reason}`, null, reason));
            haptic("error");
            setBusy(false);
            return;
          }
          haptic("success");
          showToast(safeT("lineage_chooser_success"), "ok");
          onChosen && onChosen(res);
          onClose && onClose();
        } catch (e) {
          setSubmitErr(String(e?.message || e || "error"));
          haptic("error");
          setBusy(false);
        }
      }

      return (
        <Modal onClose={onClose} title={`🏯 ${safeT("lineage_chooser_modal_title")}`}>
          <div style={{ display:"grid", gridTemplateColumns:"minmax(0, 1fr)", gap:11, fontSize:12 }}>
            {error && <ErrBanner msg={error} />}
            {loading && !data && <ListSkeleton rows={6} />}
            {data && data.ok !== false && (
              <>
                <Card style={{ padding:"10px 13px",
                                background:"rgba(var(--gold2-rgb),.06)",
                                borderColor:"rgba(var(--gold2-rgb),.35)" }}>
                  <div style={{ fontSize:11.5, color:"rgba(245,220,160,.95)",
                                 lineHeight:1.5 }}>
                    {safeT("lineage_chooser_intro")}
                  </div>
                  <div style={{ marginTop:6, fontSize:10.5, color:"var(--red2)",
                                 fontFamily:"'Cinzel',serif", letterSpacing:.4 }}>
                    {safeT("lineage_chooser_irreversible")}
                  </div>
                </Card>

                {submitErr && <ErrBanner msg={submitErr} />}

                <div style={{ display:"grid", gap:8 }}>
                  {(data.lineages || []).map((ln) => {
                    const locked = ln.is_demonic && !playerIsDemonic;
                    const isPending = pendingKey === ln.key;
                    return (
                      <Card key={ln.key} style={{
                        padding:"11px 12px",
                        opacity: locked ? 0.55 : 1,
                        borderColor: isPending
                          ? "rgba(var(--jade-rgb),.55)"
                          : (ln.is_demonic ? "rgba(var(--red-rgb),.42)" : undefined),
                        boxShadow: isPending ? "0 0 12px rgba(var(--jade-rgb),.18)" : undefined,
                      }}>
                        <div style={{ display:"flex", alignItems:"center", gap:10 }}>
                          <div style={{ fontSize:28, lineHeight:1,
                                         filter: locked ? "grayscale(.7)" : "none" }}>
                            {ln.emoji}
                          </div>
                          <div style={{ flex:1, minWidth:0 }}>
                            <div style={{ display:"flex", alignItems:"center", gap:6,
                                           flexWrap:"wrap" }}>
                              <span style={{ fontFamily:"'Cinzel',serif", fontWeight:700,
                                              color:"var(--gold2)", fontSize:13,
                                              letterSpacing:.4 }}>
                                {ln.name}
                              </span>
                              <span style={{
                                fontSize:9, padding:"1px 6px", borderRadius:8,
                                border: ln.is_demonic
                                  ? "1px solid rgba(var(--red-rgb),.55)"
                                  : "1px solid rgba(var(--realm-1-rgb),.42)",
                                color: ln.is_demonic ? "var(--red2)" : "#93c5fd",
                                letterSpacing:.4, fontFamily:"'Cinzel',serif",
                                textTransform:"uppercase",
                              }}>
                                {ln.is_demonic
                                  ? safeT("sect_lineage_tier_demonic")
                                  : safeT("sect_lineage_tier_righteous")}
                              </span>
                              {locked && <span style={{ fontSize:12 }}>{ico("🔒","lock",{ size:13, style:{ display:"inline-block", verticalAlign:"-2px" } })}</span>}
                            </div>
                            <div style={{ fontSize:10.5, color:"var(--muted)",
                                           fontStyle:"italic", marginTop:2,
                                           lineHeight:1.4 }}>
                              "{ln.philosophy}"
                            </div>
                          </div>
                        </div>

                        {!locked && (ln.bonuses || []).length > 0 && (
                          <div style={{ marginTop:7, display:"flex", flexWrap:"wrap",
                                         gap:4 }}>
                            {(ln.bonuses || []).map((b) => (
                              <span key={b.key} style={{
                                fontSize:10, color:"rgba(var(--text2-rgb),.88)",
                                padding:"1px 6px", borderRadius:7,
                                background:"rgba(var(--jade-rgb),.10)",
                                border:"1px solid rgba(var(--jade-rgb),.30)",
                              }}>
                                {b.label} {b.value}
                              </span>
                            ))}
                          </div>
                        )}

                        {locked && (
                          <div style={{ marginTop:6, fontSize:10, color:"var(--red2)",
                                         borderTop:"1px dashed var(--border)",
                                         paddingTop:5 }}>
                            {safeT("sect_lineage_demonic_locked")}
                          </div>
                        )}

                        {!locked && !isPending && (
                          <div style={{ marginTop:8 }}>
                            <ActionBtn variant="ghost"
                              onClick={() => { haptic("select"); setPendingKey(ln.key); }}>
                              {safeT("lineage_choose_btn")}
                            </ActionBtn>
                          </div>
                        )}

                        {isPending && (
                          <div style={{ marginTop:8, display:"grid",
                                         gridTemplateColumns:"1fr 1fr", gap:6 }}>
                            <ActionBtn variant="primary" busy={busy}
                              onClick={() => confirmChoice(ln.key)}>
                              ✓ {safeT("lineage_chooser_confirm")}
                            </ActionBtn>
                            <ActionBtn variant="ghost" disabled={busy}
                              onClick={() => setPendingKey(null)}>
                              ✕ {t("btn_cancel")}
                            </ActionBtn>
                          </div>
                        )}
                      </Card>
                    );
                  })}
                </div>
              </>
            )}
          </div>
        </Modal>
      );
    }

    function LineageInfoModal({ onClose, lineageMeta }) {
      if (!lineageMeta) return null;
      const ln = lineageMeta;
      return (
        <Modal onClose={onClose} title={`🏯 ${safeT("lineage_modal_title")}`}>
          {/* QoL 31/07 — sweep do fix do Salão: grid sem template estica com filho nowrap */}
          <div style={{ display:"grid", gridTemplateColumns:"minmax(0, 1fr)", gap:11, fontSize:12 }}>
            {/* ── Hero card ──────────────────────────────────────────── */}
            <Card style={{ padding:"13px 14px", display:"grid", gap:7 }}>
              <div style={{ display:"flex", alignItems:"center", gap:11 }}>
                <div style={{ fontSize:34, lineHeight:1 }}>{ln.emoji}</div>
                <div style={{ flex:1, minWidth:0 }}>
                  <div style={{ fontFamily:"'Cinzel',serif", fontWeight:700,
                                 color:"var(--gold2)", fontSize:14, letterSpacing:.5,
                                 whiteSpace:"nowrap", overflow:"hidden",
                                 textOverflow:"ellipsis" }}>
                    {ln.name}
                  </div>
                  <div style={{ marginTop:3, display:"flex", alignItems:"center",
                                 gap:6, flexWrap:"wrap" }}>
                    <span style={{
                      fontSize:9, padding:"1px 6px", borderRadius:8,
                      border: ln.is_demonic
                        ? "1px solid rgba(var(--red-rgb),.55)"
                        : "1px solid rgba(var(--realm-1-rgb),.42)",
                      color: ln.is_demonic ? "var(--red2)" : "#93c5fd",
                      letterSpacing:.4, fontFamily:"'Cinzel',serif",
                      textTransform:"uppercase",
                    }}>
                      {ln.is_demonic
                        ? safeT("sect_lineage_tier_demonic")
                        : safeT("sect_lineage_tier_righteous")}
                    </span>
                  </div>
                </div>
              </div>

              {ln.philosophy && (
                <div style={{ fontSize:11, color:"rgba(var(--text2-rgb),.85)",
                               fontStyle:"italic", lineHeight:1.5,
                               borderTop:"1px dashed var(--border)", paddingTop:7 }}>
                  "{ln.philosophy}"
                </div>
              )}
            </Card>

            {/* ── Bonuses ─────────────────────────────────────────────── */}
            {(ln.bonuses || []).length > 0 && (
              <Card style={{ padding:"11px 13px" }}>
                <div style={{ fontFamily:"'Cinzel',serif", fontSize:10.5,
                               color:"var(--muted)", letterSpacing:.5,
                               textTransform:"uppercase", marginBottom:7 }}>
                  {safeT("lineage_label_bonuses")}
                </div>
                <div style={{ display:"flex", flexWrap:"wrap", gap:5 }}>
                  {(ln.bonuses || []).map((b) => (
                    <span key={b.key} style={{
                      fontSize:11, color:"rgba(var(--text2-rgb),.92)",
                      padding:"3px 8px", borderRadius:8,
                      background:"rgba(var(--jade-rgb),.10)",
                      border:"1px solid rgba(var(--jade-rgb),.30)",
                    }}>
                      {b.label} <strong style={{ color:"var(--jade)" }}>{b.value}</strong>
                    </span>
                  ))}
                </div>
                <div style={{ marginTop:7, fontSize:10, color:"var(--muted2)",
                               fontStyle:"italic" }}>
                  {safeT("lineage_bonus_display_only")}
                </div>
              </Card>
            )}

            {/* ── Continent + Rival ───────────────────────────────────── */}
            <Card style={{ padding:"11px 13px", display:"grid", gap:8 }}>
              {ln.continent && (
                <div style={{ display:"flex", alignItems:"center", gap:8 }}>
                  <span style={{ fontFamily:"'Cinzel',serif", fontSize:10.5,
                                  color:"var(--muted)", letterSpacing:.5,
                                  textTransform:"uppercase", minWidth:100 }}>
                    {safeT("lineage_label_continent")}
                  </span>
                  <span style={{ fontSize:12, color:"var(--gold3)" }}>
                    {safeT(`continent_${ln.continent}`, null, ln.continent)}
                  </span>
                </div>
              )}
              {ln.rival_name && (
                <div style={{ display:"flex", alignItems:"center", gap:8,
                               borderTop:"1px dashed var(--border)", paddingTop:7 }}>
                  <span style={{ fontFamily:"'Cinzel',serif", fontSize:10.5,
                                  color:"var(--muted)", letterSpacing:.5,
                                  textTransform:"uppercase", minWidth:100 }}>
                    {safeT("lineage_label_rival")}
                  </span>
                  <span style={{ fontSize:12, color:"var(--red2)" }}>
                    {ln.rival_emoji || "⚔️"} {ln.rival_name}
                  </span>
                </div>
              )}
              <div style={{ marginTop:3, fontSize:10.5, color:"var(--jade)",
                             borderTop:"1px dashed var(--border)", paddingTop:6 }}>
                ⚔️ {safeT("lineage_rival_bonus_active")}
              </div>
            </Card>
          </div>
        </Modal>
      );
    }

    // ─── v16.2 — Path Trinity modals (read + picker) ─────────────────────────
    // Two modals, branched by App.js based on player.path_raw / can_pick.
    // PathModal: read view for everyone (R0+) so the system is legible
    //   before eligibility. Includes the 3 paths directory + the player's
    //   current path hero card + the Change CTA (gated until v16.3).
    // PathPickModal: the commit modal — only mounted when the player is
    //   R3+ and has never picked (path_raw === null). After a successful
    //   pick, onPicked() refreshes the player so PlayerHeader updates.

    function _PathTierBadge({ tier }) {
      const palette = tier === "demonic"
        ? { border:"rgba(var(--red-rgb),.55)", color:"var(--red2)", key:"path_tier_demonic" }
        : tier === "celestial"
          ? { border:"rgba(var(--gold2-rgb),.55)", color:"#fcd34d", key:"path_tier_celestial" }
          : { border:"rgba(160,170,180,.55)", color:"rgba(210,215,225,.95)", key:"path_tier_neutral" };
      return (
        <span style={{
          fontSize:9, padding:"1px 6px", borderRadius:8,
          border:`1px solid ${palette.border}`,
          color: palette.color, letterSpacing:.4,
          fontFamily:"'Cinzel',serif", textTransform:"uppercase",
        }}>
          {safeT(palette.key)}
        </span>
      );
    }

    function _PathCardBody({ p, isPending, footerSlot, allowedLineageLabel }) {
      return (
        <Card style={{
          padding:"11px 12px",
          borderColor: isPending ? "rgba(var(--jade-rgb),.55)" : undefined,
          boxShadow: isPending ? "0 0 12px rgba(var(--jade-rgb),.18)" : undefined,
        }}>
          <div style={{ display:"flex", alignItems:"center", gap:10 }}>
            <div style={{ fontSize:30, lineHeight:1 }}>{p.emoji}</div>
            <div style={{ flex:1, minWidth:0 }}>
              <div style={{ display:"flex", alignItems:"center", gap:6, flexWrap:"wrap" }}>
                <span style={{ fontFamily:"'Cinzel',serif", fontWeight:700,
                                color:"var(--gold2)", fontSize:13, letterSpacing:.4 }}>
                  {p.name}
                </span>
                <_PathTierBadge tier={p.tier} />
              </div>
              <div style={{ fontSize:10.5, color:"var(--muted)",
                             fontStyle:"italic", marginTop:2, lineHeight:1.4 }}>
                "{p.philosophy}"
              </div>
            </div>
          </div>
          {(p.bonuses || []).length > 0 && (
            <div style={{ marginTop:7, display:"flex", flexWrap:"wrap", gap:4 }}>
              {(p.bonuses || []).map((b) => (
                <span key={b.key} style={{
                  fontSize:10, color:"rgba(var(--text2-rgb),.88)",
                  padding:"1px 6px", borderRadius:7,
                  background:"rgba(var(--jade-rgb),.10)",
                  border:"1px solid rgba(var(--jade-rgb),.30)",
                }}>
                  {b.label} {b.value}
                </span>
              ))}
            </div>
          )}
          {allowedLineageLabel && (
            <div style={{ marginTop:6, fontSize:10, color:"var(--muted2)",
                           borderTop:"1px dashed var(--border)", paddingTop:5 }}>
              {safeT("path_label_allowed_lineages")}: <span style={{ color:"var(--gold3)" }}>{allowedLineageLabel}</span>
            </div>
          )}
          {footerSlot}
        </Card>
      );
    }

    function _allowedLineageLabelFor(p) {
      // p.is_righteous / p.is_demonic / p.is_rogue come from the projection.
      if (p.is_demonic) return safeT("path_lineages_demonic_short");
      if (p.is_righteous) return safeT("path_lineages_righteous_short");
      return safeT("path_lineages_none_short");
    }

    // v16.2.1 (emergent-path pivot) — PathPickModal removido. Path agora
    // emerge das acções do cultivador (karma + quest choices + actions),
    // policiado pelo v16.3 Karma engine. Não há picker manual. PathModal
    // (abaixo) mostra o path emergente em read-only. O endpoint `path/pick`
    // fica dead até v16.3 wire internal calls. Ver Sessions/2026-05-25-v16.2.1.

    function PathModal({ onClose, player }) {
      // v16.2.1 — read-only emergent path view. No "Change Path" buttons.
      // When `path_raw === null` and the player is at R3+, the modal shows
      // a "your path has not crystallized yet" card explaining that path
      // emerges from karma + quest choices + actions. Pre-R3 shows the same
      // didactic message but with the realm gate as primary hint.
      //
      // v16.3 — also fetches `world/karma_info` for the "Crystallization"
      // card that surfaces the karma snapshot at the moment the path was
      // derived. Renders only when the path is committed (raw set).
      const { data, loading, error } = useApi("world/path_info", null, []);
      const yourPath = data && data.your_path;
      const yourMeta = yourPath && yourPath.meta;
      const _hasCrystallized = !!(yourPath && yourPath.raw);
      const _belowGate = !!(yourPath && yourPath.current_realm < yourPath.gate_realm);
      // Only request karma_info when there is a crystallized path — pre-R3
      // players don't need the second round-trip. The empty `[]` triggers a
      // single fetch on modal open; karma value is stable enough that
      // refetches aren't worth the bandwidth.
      const karmaInfoState = useApi(
        "world/karma_info", null, [_hasCrystallized ? "yes" : "no"],
      );
      const _crystKarma = _hasCrystallized && karmaInfoState.data && karmaInfoState.data.ok !== false
        ? (karmaInfoState.data.path && karmaInfoState.data.path.crystallized_at_karma)
        : null;

      return (
        <Modal onClose={onClose} title={`☯️ ${safeT("path_modal_title")}`}>
          {/* QoL 31/07 — sweep do fix do Salão: grid sem template estica com filho nowrap */}
          <div style={{ display:"grid", gridTemplateColumns:"minmax(0, 1fr)", gap:11, fontSize:12 }}>
            {error && <ErrBanner msg={error} />}
            {loading && !data && <ListSkeleton rows={4} />}

            {data && data.ok !== false && (
              <>
                {/* ── Emergent intro: explains how path forms ─────────── */}
                <Card style={{ padding:"11px 13px",
                                background:"rgba(var(--gold2-rgb),.05)",
                                borderColor:"rgba(var(--gold2-rgb),.28)" }}>
                  <div style={{ fontSize:11.5, color:"rgba(245,220,160,.92)",
                                 lineHeight:1.55, fontStyle:"italic" }}>
                    {safeT("path_emergent_intro")}
                  </div>
                </Card>

                {/* ── Hero card: current emergent state ─────────────── */}
                {_hasCrystallized && yourMeta && (
                  <Card style={{ padding:"13px 14px", display:"grid", gap:7 }}>
                    <div style={{ display:"flex", alignItems:"center", gap:11 }}>
                      <div style={{ fontSize:34, lineHeight:1 }}>{yourMeta.emoji}</div>
                      <div style={{ flex:1, minWidth:0 }}>
                        <div style={{ fontFamily:"'Cinzel',serif", fontWeight:700,
                                       color:"var(--gold2)", fontSize:14, letterSpacing:.5,
                                       whiteSpace:"nowrap", overflow:"hidden", textOverflow:"ellipsis" }}>
                          {yourMeta.name}
                        </div>
                        <div style={{ marginTop:3 }}>
                          <_PathTierBadge tier={yourMeta.tier} />
                        </div>
                      </div>
                    </div>
                    {yourMeta.philosophy && (
                      <div style={{ fontSize:11, color:"rgba(var(--text2-rgb),.85)",
                                     fontStyle:"italic", lineHeight:1.5,
                                     borderTop:"1px dashed var(--border)", paddingTop:7 }}>
                        "{yourMeta.philosophy}"
                      </div>
                    )}
                    {(yourMeta.bonuses || []).length > 0 && (
                      <div style={{ display:"flex", flexWrap:"wrap", gap:5,
                                     borderTop:"1px dashed var(--border)", paddingTop:7 }}>
                        {(yourMeta.bonuses || []).map((b) => (
                          <span key={b.key} style={{
                            fontSize:11, color:"rgba(var(--text2-rgb),.92)",
                            padding:"3px 8px", borderRadius:8,
                            background:"rgba(var(--jade-rgb),.10)",
                            border:"1px solid rgba(var(--jade-rgb),.30)",
                          }}>
                            {b.label} <strong style={{ color:"var(--jade)" }}>{b.value}</strong>
                          </span>
                        ))}
                      </div>
                    )}
                    <div style={{ borderTop:"1px dashed var(--border)", paddingTop:7,
                                   fontSize:10.5, color:"var(--gold3)" }}>
                      {safeT("path_label_allowed_lineages")}: {_allowedLineageLabelFor(yourMeta)}
                    </div>
                  </Card>
                )}

                {/* ── Not crystallized yet ──────────────────────────── */}
                {!_hasCrystallized && (
                  <Card style={{ padding:"12px 14px",
                                  background:"rgba(160,200,255,.05)",
                                  borderColor:"rgba(160,200,255,.25)" }}>
                    <div style={{ fontSize:11.5, color:"rgba(var(--text2-rgb),.88)",
                                   lineHeight:1.55 }}>
                      {_belowGate
                        ? safeT("path_not_crystallized_pre_r3")
                        : safeT("path_not_crystallized_post_r3")}
                    </div>
                  </Card>
                )}

                {/* ── v16.3 Crystallization card ─────────────────────── */}
                {_hasCrystallized && _crystKarma !== null && _crystKarma !== undefined && (
                  <Card style={{ padding:"11px 13px",
                                  background:"rgba(var(--gold2-rgb),.05)",
                                  borderColor:"rgba(var(--gold2-rgb),.25)" }}>
                    <div style={{ fontSize:10.5, color:"var(--gold3)",
                                   fontFamily:"'Cinzel',serif", letterSpacing:1.1,
                                   textTransform:"uppercase", marginBottom:6 }}>
                      ⚖️ {safeT("karma_crystallization_card")}
                    </div>
                    <div style={{ fontSize:11.5, color:"rgba(var(--text2-rgb),.88)",
                                   lineHeight:1.55 }}>
                      {safeT("karma_crystallization_at_value", { value: _crystKarma })}
                    </div>
                  </Card>
                )}

                {/* ── Directory of the 3 paths (always shown — didactic) */}
                <div style={{ display:"grid", gap:8 }}>
                  {(data.paths || []).map((p) => {
                    const isCurrent = yourPath && yourPath.raw && yourPath.key === p.key;
                    return (
                      <_PathCardBody key={p.key} p={p} isPending={isCurrent}
                        allowedLineageLabel={_allowedLineageLabelFor(p)} />
                    );
                  })}
                </div>
              </>
            )}
          </div>
        </Modal>
      );
    }

    // ─── KarmaModal (v16.3) — silent spine that defines the Path ────────────
    //
    // Reads /world/karma_info and renders:
    //   • Hero card: karma value + band label + emoji + gauge (-1000…0…+1000)
    //   • Divergence warning card (only when path+karma diverge post-R3)
    //   • Recent events log (last 10 from karma_log)
    //   • "What changes my karma?" expandable list (Lei §1 transparency)
    //
    // Lei §1 (honest disclosure): the canonical events catalog is always
    // accessible — the player never wonders WHY karma shifted.
    // Lei §3 (depth > variety): one stat, surfaced once, with consequences
    // wired through path crystallization + tribulation modifier + divergence
    // DM. The KarmaModal is the cultivator's window into all of it.
    function KarmaModal({ onClose }) {
      const [expandedCatalog, setExpandedCatalog] = useState(false);
      const [heartDemonBusy, setHeartDemonBusy] = useState(false);
      const [karmaReload, setKarmaReload] = useState(0);
      const { data, loading, error } = useApi("world/karma_info", null, [karmaReload]);

      // Color the gauge marker per band — same palette the chip uses.
      const _bandColor = (band) => ({
        saint:   "rgba(245,220,160,.95)",
        pure:    "rgba(190,220,255,.92)",
        neutral: "rgba(200,210,220,.85)",
        tainted: "rgba(240,170,170,.92)",
        demonic: "rgba(255,180,180,.95)",
      }[band] || "rgba(200,210,220,.85)");

      // TEC-5 — o Rito em curso ocupa a tela (arena padrão, igual à Prova da
      // Sucessão do TEC-3); fechar volta ao KarmaModal e refresca.
      const [riteDuel, setRiteDuel] = useState(null);
      const [choiceBusy, setChoiceBusy] = useState(null);
      const [confirmChoice, setConfirmChoice] = useState(null);

      async function startHeartDemon() {
        if (heartDemonBusy) return;
        setHeartDemonBusy(true); haptic("warning");
        try {
          const res = await api("heart_demon/start", {});
          if (res.ok) {
            haptic("success");
            // TEC-5 — com `forbidden_path` ON o endpoint devolve um DUELO (o
            // Reflexo). Sem a flag, segue a v16.3: só re-arma a DM + a janela.
            if (res.duel_id) { setRiteDuel(res.duel_id); return; }
            showToast(safeT("karma_divergence_grace_remaining", { hours: res.grace_hours || 72 }));
          } else {
            haptic("error");
            const m = { not_diverged: "fpd_mini_err_not_diverged",
                        rite_cooldown: "fpd_mini_err_cooldown",
                        choice_pending: "fpd_mini_err_choice",
                        duel_already_active: "fpd_mini_err_busy",
                        hp_depleted: "fpd_mini_err_hp" };
            showToast(safeT(m[res.reason] || `err_${res.reason || "engine"}`, {
              hours: res.cooldown_ms ? Math.max(1, Math.ceil((res.cooldown_ms - Date.now()) / 3600000)) : 0,
            }));
          }
        } catch (e) {
          haptic("error");
          showToast(safeT("err_engine") || "engine");
        } finally {
          setHeartDemonBusy(false);
        }
      }

      async function chooseHeartDemon(choice) {
        if (choiceBusy) return;
        setChoiceBusy(choice); haptic("warning");
        try {
          const res = await api("heart_demon/choose", { choice });
          if (res.ok) {
            haptic("success");
            setConfirmChoice(null);
            showToast(choice === "cross"
              ? safeT("fpd_mini_crossed", { before: safeT("fpd_path_" + (res.path_before || "rogue")),
                                            after: safeT("fpd_path_" + (res.path_after || "rogue")) })
              : safeT("fpd_mini_stood"));
            setKarmaReload(x => x + 1);
          } else {
            haptic("error");
            showToast(safeT("fpd_mini_err_stale"));
          }
        } catch (e) {
          haptic("error");
          showToast(safeT("err_engine") || "engine");
        } finally {
          setChoiceBusy(null);
        }
      }

      // TEC-5 — o Rito em curso ocupa a tela (padrão da Prova da Sucessão do
      // TEC-3): o settle roda no poll do duelo, então ao fechar basta refrescar
      // e o card já mostra a ESCOLHA pendente (ou a mordida da derrota).
      if (riteDuel) {
        return <DuelArenaModal duelId={riteDuel} playerLang={null}
                 onClose={() => { setRiteDuel(null); setKarmaReload(x => x + 1); }} />;
      }

      return (
        <Modal onClose={onClose} title={`⚖️ ${safeT("karma_modal_title")}`}>
          {/* QoL 31/07 — sweep do fix do Salão: grid sem template estica com filho nowrap */}
          <div style={{ display:"grid", gridTemplateColumns:"minmax(0, 1fr)", gap:11, fontSize:12 }}>
            {error && <ErrBanner msg={error} />}
            {loading && !data && <ListSkeleton rows={4} />}

            {data && data.ok !== false && (() => {
              const k = data.karma || {};
              const g = data.gauge || { min: -1000, max: 1000, value: 0, position_pct: 50 };
              const p = data.path || {};
              const div = p.divergence || {};
              const wv = data.world_view || {};      // Track A item 4 — "o que o mundo vê"
              const nx = wv.next || {};
              const bandColor = _bandColor(k.band);
              return (
                <>
                  {/* ── Hero card: karma value + label + gauge ─────── */}
                  <Card style={{ padding:"13px 14px", display:"grid", gap:9 }}>
                    <div style={{ display:"flex", alignItems:"center", gap:11 }}>
                      <div style={{ fontSize:34, lineHeight:1 }}>{k.emoji}</div>
                      <div style={{ flex:1, minWidth:0 }}>
                        <div style={{ fontFamily:"'Cinzel',serif", fontWeight:700,
                                       color: bandColor, fontSize:18, letterSpacing:.5,
                                       lineHeight:1 }}>
                          {k.value > 0 ? `+${k.value}` : k.value}
                        </div>
                        <div style={{ fontSize:11, color:"var(--gold3)", marginTop:3,
                                       letterSpacing:.4, fontFamily:"'Cinzel',serif" }}>
                          {k.label}
                        </div>
                      </div>
                      <div style={{ textAlign:"right", fontSize:10, color:"var(--muted)" }}>
                        <div>{safeT("karma_gauge_negative_extreme")}</div>
                        <div style={{ marginTop:2 }}>{safeT("karma_gauge_positive_extreme")}</div>
                      </div>
                    </div>

                    {/* Gauge: -1000 ─── 0 ─── +1000 with marker */}
                    <div style={{ position:"relative", marginTop:4 }}>
                      <div style={{
                        position:"relative", height:10, borderRadius:5,
                        background:"linear-gradient(90deg, rgba(var(--red-rgb),.55) 0%, rgba(120,100,90,.4) 35%, rgba(150,160,170,.4) 50%, rgba(120,140,170,.4) 65%, rgba(var(--gold2-rgb),.55) 100%)",
                        border:"1px solid rgba(var(--gold2-rgb),.25)",
                        overflow:"hidden",
                      }}>
                        {/* Center tick at karma=0 */}
                        <div style={{
                          position:"absolute", top:0, bottom:0, left:"50%", width:1,
                          background:"rgba(255,255,255,.4)", transform:"translateX(-50%)",
                        }} />
                        {/* Marker for current karma value */}
                        <div style={{
                          position:"absolute", top:-3, bottom:-3,
                          left: `${g.position_pct}%`, width:3,
                          background: bandColor,
                          boxShadow:`0 0 8px ${bandColor}`,
                          transform:"translateX(-50%)",
                          borderRadius:2,
                        }} />
                      </div>
                      <div style={{ display:"flex", justifyContent:"space-between",
                                     marginTop:4, fontSize:9, color:"var(--muted)",
                                     fontFamily:"'Cinzel',serif", letterSpacing:.3 }}>
                        <span>{g.min}</span>
                        <span>0</span>
                        <span>+{g.max}</span>
                      </div>
                    </div>
                  </Card>

                  {/* ── Track A item 4 — "O que o mundo vê" ──────────── */}
                  {wv.band && (
                    <Card style={{ padding:"12px 14px", display:"grid", gap:9 }}>
                      <div style={{ fontSize:10.5, color:"var(--gold3)",
                                     fontFamily:"'Cinzel',serif", letterSpacing:1.1,
                                     textTransform:"uppercase" }}>
                        🌍 {safeT("karma_world_sees_title")}
                      </div>
                      <div style={{ fontSize:11.5, color:"rgba(var(--text2-rgb),.86)", lineHeight:1.5 }}>
                        <span style={{ color: bandColor, fontFamily:"'Cinzel',serif" }}>{k.emoji} {k.label}</span>
                        {" — "}{safeT(`karma_band_blurb_${k.band}`)}
                      </div>
                      {/* Distance to the next karmic threshold (crystallize / diverge). */}
                      <div style={{ fontSize:11, color:"var(--muted)", fontStyle:"italic", lineHeight:1.5 }}>
                        {nx.kind === "crystallize"
                          ? safeT("karma_dist_crystallize", { dir: safeT(`karma_dir_${nx.projected || "rogue"}`) })
                          : nx.kind === "diverge"
                            ? safeT("karma_dist_diverge", { n: nx.distance })
                            : safeT("karma_dist_settled")}
                      </div>
                      {/* What reacts to your karma (Lei §1). */}
                      {(wv.reacts || []).length > 0 && (
                        <div style={{ borderTop:"1px dashed var(--border)", paddingTop:8, display:"grid", gap:4 }}>
                          <div style={{ fontSize:10, color:"var(--gold3)", letterSpacing:.6,
                                         fontFamily:"'Cinzel',serif", textTransform:"uppercase" }}>
                            {safeT("karma_reacts_title")}
                          </div>
                          {(wv.reacts || []).map((r) => (
                            <div key={r.key} style={{ fontSize:11, lineHeight:1.45,
                                   color: r.active === false ? "var(--muted)" : "rgba(var(--text2-rgb),.82)",
                                   opacity: r.active === false ? 0.6 : 1 }}>
                              • {safeT(`karma_reacts_${r.key}`, { mod: (r.mod != null ? Number(r.mod).toFixed(1) : "") })}
                            </div>
                          ))}
                        </div>
                      )}
                    </Card>
                  )}

                  {/* ── Divergence warning (conditional) ────────────── */}
                  {/* TEC-5 — o card deixou de ser um aviso com um botão que
                      repetia o próprio título: com `forbidden_path` ON ele é a
                      PORTA do Rito do Coração-Demônio (encarar o Reflexo →
                      atravessar/reafirmar), e diz o estado honesto quando não
                      dá para entrar (castigo, escolha pendente). Sem a flag,
                      `hd` é undefined e o card rende exatamente como sempre. */}
                  {(() => {
                    const hd = data.heart_demon || null;
                    // TEC-5 — o Reflexo tem DUAS portas: a divergência (o Céu
                    // chama de volta) e a PROFUNDIDADE na própria estrada (sem
                    // isto o Cofre era inalcançável: os dois gates eram inversos).
                    const hdOpen = hd && (hd.diverged || hd.deep || hd.pending_choice_duel_id);
                    if (!div.diverged && !hdOpen) return null;
                    const k = (hd && hd.knobs) || {};
                    return (
                    <Card style={{ padding:"12px 14px",
                                    background:"rgba(var(--red-rgb),.07)",
                                    borderColor:"rgba(var(--red-rgb),.4)" }}>
                      <div style={{ fontSize:11, color:"var(--red)",
                                     fontFamily:"'Cinzel',serif", letterSpacing:.5,
                                     textTransform:"uppercase", marginBottom:5 }}>
                        ⚠️ {safeT("karma_divergence_warning_card")}
                      </div>
                      <div style={{ fontSize:11.5, color:"rgba(255,210,210,.88)",
                                     lineHeight:1.5 }}>
                        {div.diverged
                          ? safeT("karma_divergence_grace_remaining", { hours: div.grace_hours || 72 })
                          : safeT("fpd_mini_deep", { have: (hd && hd.deep_have) || 0, need: (hd && hd.deep_need) || 0 })}
                      </div>

                      {hd && hd.pending_choice_duel_id ? (
                        <div style={{ marginTop:10 }}>
                          <div style={{ fontSize:11.5, color:"rgba(255,225,225,.92)", lineHeight:1.55, marginBottom:8 }}>
                            {hd.target_path
                              ? safeT("fpd_mini_choice_header", { target: safeT("fpd_path_" + hd.target_path) })
                              : safeT("fpd_mini_choice_header_deep")}
                          </div>
                          {hd.sect_cost && hd.sect_cost.leaves && (
                            <div style={{ fontSize:10.5, color:"#e5a0a0", fontStyle:"italic", marginBottom:8 }}>
                              {safeT("fpd_mini_choice_sect", { karma: Math.abs(hd.sect_cost.karma_cost || 75) })}
                            </div>
                          )}
                          {confirmChoice ? (
                            <div style={{ padding:"8px 10px", borderRadius:7, background:"rgba(var(--red-rgb),.09)", border:"1px solid rgba(var(--red-rgb),.35)" }}>
                              <div style={{ fontSize:11, color:"rgba(255,225,225,.92)", lineHeight:1.5, marginBottom:8 }}>
                                {confirmChoice === "cross"
                                  ? safeT("fpd_mini_confirm_cross", { before: safeT("fpd_path_" + (p.current || "rogue")),
                                                                      after: safeT("fpd_path_" + (hd.target_path || "rogue")) })
                                  : safeT("fpd_mini_confirm_stand")}
                              </div>
                              <div style={{ display:"flex", gap:6 }}>
                                <ActionBtn variant="ghost" onClick={() => setConfirmChoice(null)} style={{ flex:1, padding:"6px 8px", fontSize:11 }}>
                                  {safeT("btn_cancel")}
                                </ActionBtn>
                                <ActionBtn variant="danger" disabled={choiceBusy != null}
                                  onClick={() => chooseHeartDemon(confirmChoice)}
                                  style={{ flex:1, padding:"6px 8px", fontSize:11 }}>
                                  {choiceBusy ? <DotSpinner /> : safeT("fpd_mini_btn_confirm")}
                                </ActionBtn>
                              </div>
                            </div>
                          ) : (
                            <div style={{ display:"flex", gap:6 }}>
                              {hd.target_path && (
                                <ActionBtn variant="danger" onClick={() => { haptic("select"); setConfirmChoice("cross"); }}
                                  style={{ flex:1, padding:"7px 8px", fontSize:11 }}>
                                  ⚔️ {safeT("fpd_mini_btn_cross")}
                                </ActionBtn>
                              )}
                              <ActionBtn variant="ghost" onClick={() => { haptic("select"); setConfirmChoice("stand"); }}
                                style={{ flex:1, padding:"7px 8px", fontSize:11 }}>
                                🧘 {safeT("fpd_mini_btn_stand")}
                              </ActionBtn>
                            </div>
                          )}
                        </div>
                      ) : hd && hd.cooldown_ms ? (
                        <div style={{ marginTop:9, fontSize:10.5, color:"var(--muted)", fontStyle:"italic" }}>
                          {safeT("fpd_mini_cooldown", { hours: Math.max(1, Math.ceil((hd.cooldown_ms - Date.now()) / 3600000)) })}
                        </div>
                      ) : (
                        <div style={{ marginTop:9 }}>
                          {hd && (
                            <div style={{ fontSize:10.5, color:"rgba(255,210,210,.75)", lineHeight:1.5, marginBottom:7 }}>
                              {hd.target_path
                                ? safeT("fpd_mini_rite_intro", { target: safeT("fpd_path_" + hd.target_path),
                                                                 soul: Math.round((k.soul_pct || 0.02) * 100) })
                                : safeT("fpd_mini_rite_intro_deep", { soul: Math.round((k.soul_pct || 0.02) * 100) })}
                            </div>
                          )}
                          <ActionBtn variant="danger" disabled={heartDemonBusy} onClick={startHeartDemon}>
                            {heartDemonBusy ? <DotSpinner />
                              : (hd ? `👁️ ${safeT("fpd_mini_btn_face")}` : safeT("karma_divergence_warning_card"))}
                          </ActionBtn>
                        </div>
                      )}
                    </Card>
                    );
                  })()}

                  {/* ── Recent events log ───────────────────────────── */}
                  <Card style={{ padding:"11px 13px" }}>
                    <div style={{ fontSize:10.5, color:"var(--gold3)",
                                   fontFamily:"'Cinzel',serif", letterSpacing:1.1,
                                   textTransform:"uppercase", marginBottom:7 }}>
                      🕓 {safeT("karma_recent_events")}
                    </div>
                    {(data.recent || []).length === 0 ? (
                      <div style={{ fontSize:11, color:"var(--muted)",
                                     fontStyle:"italic", textAlign:"center",
                                     padding:"8px 0" }}>
                        {safeT("karma_event_log_empty")}
                      </div>
                    ) : (
                      <div style={{ display:"grid", gap:5 }}>
                        {(data.recent || []).map((ev) => {
                          const _sign = ev.delta > 0 ? "+" : (ev.delta < 0 ? "" : "");
                          const _color = ev.delta > 0
                            ? "var(--jade)"
                            : (ev.delta < 0 ? "var(--red)" : "var(--muted)");
                          return (
                            <div key={ev.id} style={{
                              display:"flex", justifyContent:"space-between",
                              gap:8, padding:"5px 8px", borderRadius:5,
                              background:"rgba(0,0,0,.25)",
                              border:"1px solid rgba(var(--gold2-rgb),.08)",
                            }}>
                              <span style={{ fontSize:11.5, color:"rgba(var(--text2-rgb),.88)",
                                              overflow:"hidden", textOverflow:"ellipsis",
                                              whiteSpace:"nowrap", flex:1 }}>
                                {ev.label}
                              </span>
                              <strong style={{ color: _color, fontSize:11.5,
                                                fontFamily:"'Cinzel',serif",
                                                letterSpacing:.3, flexShrink:0 }}>
                                {_sign}{ev.delta}
                              </strong>
                            </div>
                          );
                        })}
                      </div>
                    )}
                  </Card>

                  {/* ── "What changes my karma?" expandable list ────── */}
                  <Card style={{ padding:"11px 13px",
                                  background:"rgba(var(--gold2-rgb),.04)",
                                  borderColor:"rgba(var(--gold2-rgb),.18)" }}>
                    <button onClick={() => { haptic("select"); setExpandedCatalog(v => !v); }}
                      style={{
                        width:"100%", textAlign:"left", padding:"3px 0",
                        background:"transparent", border:"none", cursor:"pointer",
                        display:"flex", justifyContent:"space-between", alignItems:"center",
                        color:"var(--gold3)", fontSize:11,
                        fontFamily:"'Cinzel',serif", letterSpacing:1.1,
                        textTransform:"uppercase",
                      }}>
                      <span>📖 {safeT("karma_what_changes_my_karma")}</span>
                      <span>{expandedCatalog ? "−" : "+"}</span>
                    </button>
                    {expandedCatalog && (
                      <div style={{ display:"grid", gap:4, marginTop:9,
                                     borderTop:"1px dashed var(--border)", paddingTop:8 }}>
                        {(data.catalog || []).map((c) => {
                          const _color = c.delta > 0
                            ? "var(--jade)"
                            : (c.delta < 0 ? "var(--red)" : "var(--muted)");
                          return (
                            <div key={c.event_key} style={{
                              display:"flex", justifyContent:"space-between",
                              fontSize:11, gap:8, padding:"3px 0",
                            }}>
                              <span style={{ color:"rgba(var(--text2-rgb),.85)",
                                              overflow:"hidden", textOverflow:"ellipsis",
                                              whiteSpace:"nowrap", flex:1 }}>
                                {c.label}
                              </span>
                              <strong style={{ color: _color,
                                                fontFamily:"'Cinzel',serif",
                                                flexShrink:0 }}>
                                {c.sign}{Math.abs(c.delta)}
                              </strong>
                            </div>
                          );
                        })}
                      </div>
                    )}
                  </Card>
                </>
              );
            })()}
          </div>
        </Modal>
      );
    }

    // ─── ProfileModal (2026-05-26) — consolidated identity surface ──────────
    //
    // The cultivator's profile, accessed by tapping the player name in the
    // header. Replaces the chip-clutter that accumulated through v16.0
    // (continent) + v16.2 (path) + v16.3 (karma) — each sprint added an
    // identity chip to PlayerHeader until 5 chips couldn't breathe.
    //
    // Structure:
    //   • Hero  — large realm-emoji avatar + name + title + realm/sublayer
    //   • Identity grid (2×2) — Continent / Path / Karma / Sect (v16.4 stub)
    //     Each card taps into its existing drill-in modal (no new modals
    //     needed — the modals stay, only the entry-point consolidates).
    //   • Stats compact — Battle Power / Soul Strength / Perception / Luck
    //   • Achievements preview — 3 most recently unlocked + "see all" CTA
    //   • Open Cultivation shortcut
    //
    // See: GameDesign/profile_modal_spec.md for the full design rationale.
    // ─────────────────────────────────────────────────────────────────────
    // v16.4 — World Sects (Seita de Cultivo). The 9 eternal NPC houses. Opened from
    // the ProfileModal 🏯 card. A house CHOOSES the cultivator via affinity —
    // there is no manual picker (Lei §2). The directory shows every house with
    // the caller's live affinity (Lei §1 — full transparency); the join-confirm
    // (WorldSectJoinModal) stacks on top only when a recruiter encounter is
    // live for that house.
    // ─────────────────────────────────────────────────────────────────────
    function WorldSectDirectoryModal({ player, onClose, onSelectJoin }) {
      const [reload, setReload] = useState(0);
      const { data, loading, error } = useApi("world/sect_directory", null, [reload]);
      const pend = useApi("world/recruiter_pending", null, [reload]);

      const pendingBySect = {};
      if (pend.data && pend.data.pending) {
        pend.data.pending.forEach(p => { pendingBySect[p.sect_id] = p; });
      }
      const your = data && data.your_sect;
      const threshold = (data && data.threshold) || 75;

      return (
        <Modal onClose={onClose} title={`🏯 ${safeT("wsect_dir_title")}`}>
          {/* QoL 31/07 — sweep do fix do Salão: grid sem template estica com filho nowrap */}
          <div style={{ display:"grid", gridTemplateColumns:"minmax(0, 1fr)", gap:11, fontSize:12 }}>
            {error && <ErrBanner msg={error} />}
            {loading && !data && <ListSkeleton rows={5} />}
            {data && data.ok !== false && (
              <>
                <Card style={{ padding:"11px 13px", background:"rgba(var(--gold2-rgb),.05)", borderColor:"rgba(var(--gold2-rgb),.2)" }}>
                  <div style={{ fontSize:11.5, color:"rgba(var(--text2-rgb),.85)", lineHeight:1.5 }}>
                    {safeT("wsect_split_banner")}
                  </div>
                </Card>

                {your && your.meta && (
                  <Card style={{ padding:"12px 14px", borderColor:"rgba(var(--gold2-rgb),.5)" }}>
                    <div style={{ display:"flex", alignItems:"center", gap:10 }}>
                      <div style={{ fontSize:30, lineHeight:1 }}>{your.meta.emoji}</div>
                      <div style={{ flex:1, minWidth:0 }}>
                        <div style={{ fontFamily:"'Cinzel',serif", fontWeight:700, color:"var(--gold3)", fontSize:15 }}>{your.meta.name}</div>
                        <div style={{ fontSize:10.5, color:"var(--muted)", marginTop:2 }}>{safeT(your.rank_key)}</div>
                      </div>
                    </div>
                    <div style={{ fontSize:11, color:"rgba(var(--text2-rgb),.78)", fontStyle:"italic", marginTop:8, lineHeight:1.5 }}>{your.meta.philosophy}</div>
                  </Card>
                )}

                <div style={{ fontSize:10.5, color:"var(--gold3)", fontFamily:"'Cinzel',serif", letterSpacing:1.1, textTransform:"uppercase", paddingLeft:3 }}>
                  {safeT("wsect_dir_houses_title")}
                </div>
                <div style={{ display:"grid", gridTemplateColumns:"minmax(0, 1fr)", gap:8 }}>
                  {(data.sects || []).map(s => {
                    const aff = s.affinity || 0;
                    const recruitable = s.recruitable;
                    const locked = s.path_locked;
                    const hasPending = !!pendingBySect[s.key];
                    const isYours = your && your.sect_id === s.key;
                    const barColor = locked ? "rgba(120,120,130,.5)" : (recruitable ? "var(--jade)" : "rgba(var(--gold2-rgb),.6)");
                    return (
                      <Card key={s.key} style={{ padding:"11px 13px", opacity: locked ? 0.62 : 1, borderColor: isYours ? "rgba(var(--gold2-rgb),.5)" : undefined }}>
                        <div style={{ display:"flex", alignItems:"center", gap:9 }}>
                          <div style={{ fontSize:24, lineHeight:1 }}>{s.emoji}</div>
                          <div style={{ flex:1, minWidth:0 }}>
                            <div style={{ display:"flex", justifyContent:"space-between", gap:6, alignItems:"center" }}>
                              <span style={{ fontFamily:"'Cinzel',serif", fontWeight:600, color:"rgba(var(--text2-rgb),.92)", fontSize:13, overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap" }}>{s.name}</span>
                              <span style={{ fontSize:8.5, color:"var(--muted)", flexShrink:0, fontFamily:"'Cinzel',serif", letterSpacing:.3, textTransform:"uppercase" }}>{s.is_demonic ? safeT("wsect_tier_demonic") : safeT("wsect_tier_righteous")}</span>
                            </div>
                            <div style={{ marginTop:5 }}>
                              <div style={{ height:6, borderRadius:3, background:"rgba(0,0,0,.35)", overflow:"hidden" }}>
                                <div style={{ height:"100%", width:`${Math.max(0, Math.min(100, aff))}%`, background:barColor, transition:"width .3s" }} />
                              </div>
                              <div style={{ display:"flex", justifyContent:"space-between", marginTop:3, fontSize:9.5, color:"var(--muted)" }}>
                                <span>{locked ? safeT("wsect_path_locked") : safeT("wsect_affinity_label", { threshold })}</span>
                                <span>{aff}/100</span>
                              </div>
                              {/* Fix 2026-07-28 (pergunta do jogador [jogador]) — "Caminho
                                  incompatível" dizia QUE estava barrado, nunca POR QUÊ
                                  nem COMO. O motivo real, e o aviso de que a escolha de
                                  caminho é de uma vez só (Lei §1). Key condicional. */}
                              {locked && s.path_block && (
                                <div style={{ fontSize:9, color:"var(--gold3)", marginTop:4, lineHeight:1.45 }}>
                                  🔒 {safeT("wsect_block_" + s.path_block)}
                                </div>
                              )}
                              {/* v16.4b — affinity breakdown chips (Lei §1: why this house courts you). */}
                              {!locked && s.breakdown && (
                                <div style={{ display:"flex", flexWrap:"wrap", gap:4, marginTop:5 }}>
                                  {[
                                    ["wsect_bd_path", s.breakdown.path_alignment],
                                    ["wsect_bd_continent", s.breakdown.continent],
                                    ["wsect_bd_karma", s.breakdown.karma_tier],
                                    ["wsect_bd_lineage", s.breakdown.lineage],
                                    ["wsect_bd_actions", s.breakdown.actions],
                                  ].filter(([, v]) => (v || 0) > 0).map(([k, v]) => (
                                    <span key={k} style={{ fontSize:8.5, padding:"1px 5px", borderRadius:4, background:"rgba(var(--jade-rgb),.1)", border:"1px solid rgba(var(--jade-rgb),.22)", color:"rgba(200,230,210,.85)" }}>
                                      {safeT(k)} +{v}
                                    </span>
                                  ))}
                                </div>
                              )}
                            </div>
                          </div>
                        </div>
                        <div style={{ fontSize:10.5, color:"rgba(var(--text2-rgb),.7)", fontStyle:"italic", marginTop:7, lineHeight:1.45 }}>{s.philosophy}</div>
                        {/* World Pulse Fase 1 — the house is alive: strength + last action (Lei §1). */}
                        {s.pulse && (
                          <div style={{ display:"flex", alignItems:"center", flexWrap:"wrap", gap:8, marginTop:6, fontSize:9.5, color:"var(--muted)" }}>
                            <span>💓 {safeT("wsect_strength_label")}: {fmtNum(s.pulse.strength)}</span>
                            {s.pulse.last_action && (
                              <span style={{ opacity:.85 }}>· {s.pulse.last_action_icon} {s.pulse.last_action_label}</span>
                            )}
                          </div>
                        )}
                        {s.bonuses && s.bonuses.length > 0 && (
                          <div style={{ display:"flex", flexWrap:"wrap", gap:5, marginTop:7 }}>
                            {s.bonuses.map(b => (
                              <span key={b.key} style={{ fontSize:9.5, padding:"2px 6px", borderRadius:5, background:"rgba(var(--jade-rgb),.1)", border:"1px solid rgba(var(--jade-rgb),.25)", color:"rgba(200,230,210,.85)" }}>
                                {b.label} {b.value}
                              </span>
                            ))}
                          </div>
                        )}
                        {!your && hasPending && (
                          <div style={{ marginTop:9 }}>
                            <ActionBtn variant="primary" onClick={() => { haptic("select"); onSelectJoin && onSelectJoin(s); }}>
                              {safeT("wsect_recruiter_pending_cta")}
                            </ActionBtn>
                          </div>
                        )}
                        {!your && !hasPending && recruitable && (
                          <div style={{ marginTop:7, fontSize:10, color:"var(--jade)", textAlign:"center", fontStyle:"italic" }}>
                            {safeT("wsect_recruiter_awaiting")}
                          </div>
                        )}
                      </Card>
                    );
                  })}
                </div>
              </>
            )}
          </div>
        </Modal>
      );
    }

    // v16.4b — the REAL trial. Accepting a house's invitation no longer joins
    // instantly: the cultivator must best the house Elder in a turn-based duel
    // (the standard DuelArenaModal). Victory ⇒ join; defeat ⇒ a short cooldown,
    // never a dead-end (Lei §1). The affinity breakdown is shown verbatim so
    // the cultivator sees exactly why this house courts them (Lei §1 disclosure).
    function WorldSectJoinModal({ sect, onClose, onJoined }) {
      const [phase, setPhase] = useState("intro");   // intro | duel | result
      const [busy, setBusy] = useState(false);
      const [duelId, setDuelId] = useState(null);
      const [result, setResult] = useState(null);    // {in_sect, status, cooldown_until_ms}
      if (!sect) return null;

      const bd = sect.breakdown || {};
      const threshold = sect.affinity_threshold || 75;

      async function faceElder() {
        if (busy) return;
        setBusy(true); haptic("warning");
        try {
          const res = await api("world/sect_trial_start", { sect_id: sect.key });
          if (res && res.ok && res.duel_id) {
            setDuelId(res.duel_id);
            setPhase("duel");
          } else {
            haptic("error");
            const reason = (res && res.reason) || "engine";
            if (reason === "trial_cooldown") {
              setResult({ in_sect: false, status: "lost", cooldown_until_ms: res.cooldown_until_ms || 0 });
              setPhase("result");
            } else if (reason === "duel_already_active") {
              showToast(safeT("wsect_trial_busy"));
            } else {
              showToast(safeT(`err_${reason}`) || reason);
            }
          }
        } catch (e) {
          haptic("error");
          showToast(safeT("err_engine") || "engine");
        } finally {
          setBusy(false);
        }
      }

      async function afterDuel() {
        // The duel closed — poll the trial state to learn the outcome
        // (settle ran server-side when the duel terminated).
        setDuelId(null);
        try {
          const st = await api("world/sect_trial_state", { sect_id: sect.key });
          setResult(st || { in_sect: false, status: "none" });
          setPhase("result");
          if (st && st.in_sect) { haptic("success"); showToast(safeT("wsect_join_success", { sect: sect.name })); }
          else haptic("error");
        } catch (e) {
          setPhase("intro");
        }
      }

      // ── Interactive trial duel — reuse the standard combat arena (z:80,
      // overlays the directory z:60). Closing returns to the result screen.
      if (phase === "duel" && duelId) {
        return <DuelArenaModal duelId={duelId} onClose={afterDuel} playerLang={null} />;
      }

      // ── Result — joined, or bested by the Elder.
      if (phase === "result" && result) {
        const joined = !!result.in_sect;
        const cdMs = result.cooldown_until_ms || 0;
        const cdH = cdMs ? Math.max(1, Math.ceil((cdMs - Date.now()) / 3600000)) : 0;
        const closeFn = joined ? onJoined : onClose;
        return (
          <Modal onClose={closeFn} title={`${sect.emoji} ${sect.name}`} zIndex={70}>
            <div style={{ display:"grid", gridTemplateColumns:"minmax(0, 1fr)", gap:14, fontSize:12, textAlign:"center", padding:"6px 2px" }}>
              <div style={{ fontSize:40, lineHeight:1 }}>{joined ? "🏯" : "🌫️"}</div>
              <div style={{ fontFamily:"'Cinzel',serif", fontSize:16, fontWeight:700, color: joined ? "var(--gold3)" : "rgba(var(--text2-rgb),.8)" }}>
                {joined ? safeT("wsect_trial_result_win_title") : safeT("wsect_trial_result_loss_title")}
              </div>
              <div style={{ fontSize:12, color:"rgba(var(--text2-rgb),.82)", lineHeight:1.6 }}>
                {joined
                  ? safeT("wsect_trial_result_win_body", { sect: sect.name })
                  : safeT("wsect_trial_result_loss_body", { sect: sect.name, hours: cdH })}
              </div>
              <ActionBtn variant="primary" onClick={closeFn}>
                {safeT("wsect_trial_result_close_btn")}
              </ActionBtn>
            </div>
          </Modal>
        );
      }

      // ── Intro — philosophy + affinity breakdown (Lei §1) + the challenge.
      const bdRows = [
        ["wsect_bd_path", bd.path_alignment || 0],
        ["wsect_bd_continent", bd.continent || 0],
        ["wsect_bd_karma", bd.karma_tier || 0],
        ["wsect_bd_lineage", bd.lineage || 0],
        ["wsect_bd_actions", bd.actions || 0],
      ];
      const total = bd.total != null ? bd.total : (sect.affinity || 0);
      return (
        <Modal onClose={onClose} title={`${sect.emoji} ${sect.name}`} zIndex={70}>
          <div style={{ display:"grid", gridTemplateColumns:"minmax(0, 1fr)", gap:13, fontSize:12 }}>
            {/* Pedra 2 — O Chamado: the house courts you in its own (soul-derived)
                voice; fall back to the eternal creed if the call is absent. */}
            <Card style={{ padding:"14px" }}>
              {sect.call && sect.call.text
                ? <div style={{ fontSize:12, color:"rgba(var(--text2-rgb),.9)", lineHeight:1.6, whiteSpace:"pre-line" }}>{sect.call.text}</div>
                : <div style={{ fontSize:12, color:"rgba(var(--text2-rgb),.85)", lineHeight:1.6, fontStyle:"italic" }}>{sect.philosophy}</div>}
            </Card>

            {/* Affinity breakdown — why this house courts you (Lei §1). */}
            <Card style={{ padding:"12px 14px" }}>
              <div style={{ fontSize:10, color:"var(--gold3)", fontFamily:"'Cinzel',serif", letterSpacing:1, textTransform:"uppercase", marginBottom:8 }}>
                {safeT("wsect_bd_title")}
              </div>
              <div style={{ display:"grid", gap:5 }}>
                {bdRows.map(([k, v]) => (
                  <div key={k} style={{ display:"flex", justifyContent:"space-between", fontSize:11, color: v > 0 ? "rgba(var(--text2-rgb),.85)" : "var(--muted)" }}>
                    <span>{safeT(k)}</span>
                    <span style={{ color: v > 0 ? "var(--jade)" : "var(--muted)" }}>{v > 0 ? `+${v}` : "—"}</span>
                  </div>
                ))}
                <div style={{ height:1, background:"rgba(var(--gold2-rgb),.15)", margin:"3px 0" }} />
                <div style={{ display:"flex", justifyContent:"space-between", fontSize:12, fontWeight:700 }}>
                  <span style={{ color:"var(--gold3)" }}>{safeT("wsect_bd_total")}</span>
                  <span style={{ color:"var(--gold3)" }}>{total}/{threshold}</span>
                </div>
              </div>
            </Card>

            <Card style={{ padding:"12px 14px", background:"rgba(var(--gold2-rgb),.05)", borderColor:"rgba(var(--gold2-rgb),.2)" }}>
              <div style={{ fontSize:11.5, color:"rgba(var(--text2-rgb),.82)", lineHeight:1.55 }}>{safeT("wsect_trial_intro_miniapp")}</div>
            </Card>

            <ActionBtn variant="primary" disabled={busy} onClick={faceElder}>
              {busy ? <DotSpinner /> : safeT("wsect_trial_face_btn")}
            </ActionBtn>
            <button onClick={onClose} style={{ background:"transparent", border:"none", color:"var(--muted)", fontSize:11, cursor:"pointer", padding:"4px" }}>
              {safeT("wsect_join_decline_btn")}
            </button>
          </div>
        </Modal>
      );
    }

    // v16.4c — Sect Hall. The interior of the house the cultivator already
    // belongs to: rank ladder + contribution progress + disclosed per-rank
    // perks + the Library (rank-gated, additive technique unlocks) + the
    // member-gated Sect Quests (reusing QuestRow + QuestChoiceModal). Opened
    // from the ProfileModal 🏯 card for MEMBERS (non-members get the directory).
    // ─── 宗 4.1 — O SELO DO POSTO NA CASA (a linha «Mundo · Seita» do Astra) ───
    //
    // *"Pavilhão da Seita de Cultivo, com insígnias de posto (…) `rank_key`,
    // `contribution / next_rank.contribution_needed`; novo posto grava a
    // insígnia. (…) Usar contribuição de posto, sem a confundir com mérito
    // gastável."* — o mesmo selo das bestas (3.3), pela mesma gramática:
    //
    //   · a CONQUISTA é o posto: cinco insígnias da escada que o SERVIDOR manda
    //     (`data.escada`, só com a onda) — sem a escada, nenhuma inscrição;
    //   · o TRAÇO é a contribuição da escada até ao próximo posto, com o número
    //     e o portão de reino (a outra metade do requisito);
    //   · o MÉRITO (o saldo que se gasta) vive numa linha à parte e NUNCA acende.
    //
    // ⚠️ O posto é o GRAVADO (o servidor nunca rebaixa): medido a 05/10, 3
    // herdeiros do `main` estão abaixo do portão de reino — renasceram — e
    // continuam herdeiros no selo.
    function reciboDaSeita(g, res, origem) {
      const L = [];
      const a = g && g.antes, d = g && g.depois;
      if (a && d && Number(d.rank_index) > Number(a.rank_index)) {
        L.push(t("seita_onda_recibo_posto", { a: safeT(a.rank_key), b: safeT(d.rank_key) }));
      }
      if (a && d && Number(d.contribution) !== Number(a.contribution)) {
        L.push(t("seita_onda_recibo_contrib", {
          d: fmtFull(Number(d.contribution) - Number(a.contribution)),
          a: fmtFull(a.contribution), b: fmtFull(d.contribution),
        }));
      }
      if (origem === "tributo" && res && res.stones_spent) {
        L.push(t("seita_onda_recibo_pedras", { n: fmtFull(res.stones_spent) }));
      }
      if (origem === "missao" && res && res.rewards && res.rewards.spirit_stones) {
        L.push(t("seita_onda_recibo_pedras_ganhas", { n: fmtFull(res.rewards.spirit_stones) }));
      }
      return L;
    }

    function SeitaSelo({ data, ov, acende, recibo, seloRef, busy, pedras, erro, onTributo }) {
      const P = NIV_ONDA;
      const escada = Array.isArray(data.escada) ? data.escada : [];
      const nPostos = escada.length;
      // o "depois" confirmado, por cima dos dados que AINDA não o apanharam
      const pendente = !!(ov && ov.dados === data);
      const v = pendente ? ov.depois : data;
      const idx = Number(v.rank_index) || 0;
      const contrib = Number(v.contribution) || 0;
      const fresco = !pendente;
      const prox = fresco ? data.next_rank : null;
      const degrau = nPostos && idx < nPostos ? escada[idx] : null;
      const proxDegrau = nPostos && idx + 1 < nPostos ? escada[idx + 1] : null;
      const rotulo = { fontFamily: P.label, fontSize: 10, lineHeight: 1.6, letterSpacing: ".16em",
                       textTransform: "uppercase", color: P.muted };
      const numero = Object.assign({}, _ONDA_TNUM, { marginLeft: "auto", fontSize: 16,
                                                      lineHeight: (22 / 16), color: P.paper });
      const _passo = 40;
      // o traço entre a insígnia que tem e a próxima: o caminho DESTE degrau, com
      // os dois limiares da escada do servidor (nunca uma conta inventada)
      const frac = (degrau && proxDegrau && proxDegrau.threshold > degrau.threshold)
        ? Math.min(1, Math.max(0, (contrib - degrau.threshold) / (proxDegrau.threshold - degrau.threshold)))
        : 0;
      const taxa = Number(data.tribute_rate) || 25;
      const reino = Number(data.realm) || 0;
      return (
        <div ref={seloRef} data-seita-selo="" style={{ padding: "14px 14px 12px",
             border: "1px solid " + P.line, background: "rgba(11,10,12,.35)" }}>
          <div style={{ display: "flex", alignItems: "baseline", columnGap: 12 }}>
            <span style={rotulo}>{t("seita_onda_posto")}</span>
            <span style={numero}>
              {nPostos ? t("seita_onda_posto_de", { posto: safeT(v.rank_key), n: idx + 1, max: nPostos })
                       : safeT(v.rank_key)}
            </span>
          </div>
          {nPostos > 0 && (
            <div aria-hidden="true" data-seita-postos=""
                 style={{ position: "relative", height: 40, marginTop: 10, width: (nPostos - 1) * _passo + 22 }}>
              <span style={{ position: "absolute", left: 11, top: 11, height: 1,
                             width: (nPostos - 1) * _passo, background: "rgba(236,229,216,.22)" }} />
              {idx > 0 && (
                <span style={{ position: "absolute", left: 11, top: 11, height: 1,
                               width: Math.min(idx, nPostos - 1) * _passo, background: "rgba(201,144,58,.85)" }} />
              )}
              {proxDegrau && fresco && frac > 0 && (
                <span data-seita-fio="" style={{ position: "absolute", left: 11 + idx * _passo, top: 10, height: 2,
                               width: Math.round(frac * _passo), background: P.gold }} />
              )}
              {escada.map((e, i) => {
                const estado = i <= idx ? "got" : (i === idx + 1 && proxDegrau && fresco) ? "next" : "empty";
                return (
                  <span key={e.rank} data-seita-posto={estado}
                        style={{ position: "absolute", left: i * _passo, top: 0, width: 22, height: 40 }}>
                    <span style={{ position: "absolute", left: 11, top: 11, width: 0, height: 0 }}>
                      <MarcaOnda estado={estado} acende={!!acende && i === idx} />
                    </span>
                    <span style={Object.assign({}, _ONDA_TNUM, {
                      position: "absolute", left: 0, right: 0, top: 24, textAlign: "center",
                      fontSize: 10, lineHeight: 1.4,
                      color: estado === "empty" ? "rgba(236,229,216,.45)" : P.paper })}>{i + 1}</span>
                  </span>
                );
              })}
            </div>
          )}
          {/* o requisito do próximo posto, com os SEUS números — ou o topo */}
          {fresco && prox ? (
            <div style={{ marginTop: 2 }}>
              <div style={Object.assign({}, rotulo, { color: P.gold })}>
                {t("seita_onda_para", { posto: safeT(prox.rank_key) })}
              </div>
              <CorpoReq rotulo={t("seita_onda_contrib")} tem={fmtFull(prox.contribution_have)}
                        precisa={fmtFull(prox.contribution_needed)} ok={!!prox.contribution_met} />
              <CorpoReq rotulo={t("seita_onda_reino")} tem={fmtFull(reino)}
                        precisa={fmtFull(prox.realm_gate)} ok={!!prox.realm_met} />
              <div style={Object.assign({}, _ONDA_TNUM, { fontSize: 12.5, lineHeight: (18 / 12.5), color: P.muted })}>
                {prox.contribution_met && !prox.realm_met
                  ? t("seita_onda_portao", { n: fmtFull(prox.realm_gate) })
                  : t("seita_onda_faltam", { n: fmtFull(Math.max(0, prox.contribution_needed - prox.contribution_have)) })}
              </div>
            </div>
          ) : fresco && !prox ? (
            <div style={Object.assign({}, _ONDA_TNUM, { fontSize: 12.5, lineHeight: (18 / 12.5), color: P.muted })}>
              {t("seita_onda_max")} · {t("seita_onda_ganha", { n: fmtFull(contrib) })}
            </div>
          ) : null}
          {/* o MÉRITO — o saldo que se gasta. Linha à parte, sem marca, sem luz. */}
          <div style={Object.assign({}, _ONDA_TNUM, { marginTop: 10, paddingTop: 8, borderTop: "1px solid " + P.line,
                                                      fontSize: 12.5, lineHeight: (18 / 12.5), color: P.muted })}>
            {t("seita_onda_merito", { n: fmtFull(data.merit_balance) })}
          </div>
          {/* o RECIBO, junto da operação — só do `seita_ganho` e da resposta */}
          {recibo && recibo.linhas && recibo.linhas.length > 0 && (
            <div role="status" style={{ marginTop: 10, paddingLeft: 12, borderLeft: "1px solid " + P.gold }}>
              {recibo.linhas.map((l, i) => (
                <div key={i} style={Object.assign({}, _ONDA_TNUM, { fontSize: 13, lineHeight: (20 / 13),
                                                                    color: i === 0 ? P.paper : P.muted })}>{l}</div>
              ))}
            </div>
          )}
          {erro && (
            <div style={{ marginTop: 8, fontSize: 12.5, lineHeight: (18 / 12.5), color: P.seal }}>{erro}</div>
          )}
          {/* o TRIBUTO: o preço e o ganho escritos ANTES do toque */}
          <div style={{ marginTop: 12 }}>
            <div style={Object.assign({}, rotulo, { marginBottom: 6 })}>
              {t("seita_onda_tributo")} · {t("seita_onda_tributo_taxa", { n: fmtFull(taxa) })}
            </div>
            {/* três colunas, duas linhas cada — o preço em cima, o ganho em baixo
                (olhado a 390: numa linha só, "1.000 pedras → +40" partia-se) */}
            <div style={{ display: "grid", gridTemplateColumns: "repeat(3, minmax(0, 1fr))", gap: 8 }}>
              {[250, 1000, 5000].filter(a => pedras >= a).map(a => {
                const pts = fmtFull(Math.floor(a / taxa));
                return (
                  <OndaBtn key={a} kind="ghost" disabled={!!busy || !fresco} onClick={() => onTributo(a)}
                           ariaLabel={t("seita_onda_tributo_aria", { pedras: fmtFull(a), pts })}
                           style={{ minHeight: 52, padding: "8px 6px" }}>
                    {busy === a ? t("seita_onda_a_oferecer") : (
                      /* o número, a unidade e o ganho em três linhas IGUAIS nos três
                         botões — "1.000 pedras" numa linha partia-se a 390 e "250
                         pedras" não, e os botões ficavam desencontrados */
                      <span style={Object.assign({}, _ONDA_TNUM, { display: "grid", gap: 1 })}>
                        <span style={{ fontSize: 14, lineHeight: (18 / 14) }}>{fmtFull(a)}</span>
                        <span style={{ fontSize: 11, lineHeight: (14 / 11), color: P.muted }}>
                          {t("seita_onda_tributo_unidade")}
                        </span>
                        <span style={{ color: (busy || !fresco) ? P.muted : P.gold }}>
                          {t("seita_onda_tributo_mais", { n: pts })}
                        </span>
                      </span>
                    )}
                  </OndaBtn>
                );
              })}
            </div>
            {pedras < 250 && (
              <div style={{ fontSize: 12.5, lineHeight: (18 / 12.5), color: P.muted }}>
                {t("seita_onda_tributo_pouco", { n: fmtFull(250) })}
              </div>
            )}
          </div>
        </div>
      );
    }

    function SectHallModal({ player, onClose, onChanged }) {
      const [reload, setReload] = useState(0);
      const { data, loading, error } = useApi("world/sect_hall", null, [reload]);
      const merit = useApi("world/merit_list", null, [reload]);  // wave 3 — Pavilhão de Mérito
      // TEC-1 — as estantes da Biblioteca (padrão merit_list: dispara no mount
      // do Hall; flag OFF → {on:false} SEM query no servidor e o render cai no
      // bloco legado v16.4c — byte-idêntico para quem não tem a flag).
      const lib = useApi("world/sect_library", null, [reload]);
      const [libBusy, setLibBusy] = useState(null);
      const [libConfirm, setLibConfirm] = useState(null); // tech_id armado (2-tap, antes→depois)
      // TEC-3 — a Prova da Sucessão 秘传: o duelo que destranca a Estante Oculta
      // (reusa a arena padrão, como o rito de entrada v16.4b).
      const [riteDuel, setRiteDuel] = useState(null);
      const [meritBusy, setMeritBusy] = useState(null);
      const [busyTech, setBusyTech] = useState(null);
      const [tributeBusy, setTributeBusy] = useState(false);
      const [choiceQuest, setChoiceQuest] = useState(null);
      // B (2026-06-16) — leave/betray the Cultivation Sect. Two-tap confirm (no native
      // dialog): first tap arms `leaveConfirm`, second performs (disclosure inline).
      const [leaveConfirm, setLeaveConfirm] = useState(false);
      const [leaveBusy, setLeaveBusy] = useState(false);
      // 宗 4.1 — o selo do posto, só com a chave-mestra. ⚠️ TODOS os estados nascem
      // aqui, antes dos `return` de baixo (a Prova, a escolha) — React #310.
      const onda = obraOn();
      const [seitaOv, setSeitaOv] = useState(null);         // { depois, dados }
      const [seitaAcende, setSeitaAcende] = useState(null); // { k }
      const [seitaRecibo, setSeitaRecibo] = useState(null); // { linhas, k }
      const [seitaBusy, setSeitaBusy] = useState(null);     // as pedras do tributo em curso
      const [seitaErro, setSeitaErro] = useState(null);
      const [seitaRolar, setSeitaRolar] = useState(0);
      const seitaSeloRef = useRef(null);
      useEffect(() => {
        if (!seitaAcende) return undefined;
        const id = setTimeout(() => setSeitaAcende(null), 900);
        return () => clearTimeout(id);
      }, [seitaAcende]);
      // a luz tem de se VER: o selo e o recibo voltam à vista juntos (a lição da 3.3)
      useEffect(() => {
        if (!seitaRolar || !seitaSeloRef.current) return;
        try {
          const r = seitaSeloRef.current.getBoundingClientRect();
          if (r.top >= 0 && r.bottom <= (window.innerHeight || 0) - 24) return;
          const reduz = window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches;
          seitaSeloRef.current.scrollIntoView({ behavior: reduz ? "auto" : "smooth", block: "nearest" });
        } catch (e) { /* sem rolagem, a leitura continua certa */ }
      }, [seitaRolar]);
      // UMA porta para o ganho confirmado — o tributo, a missão, a escolha e a
      // promoção que o próprio Salão confirma ao abrir. Só o `seita_ganho` do
      // servidor acende; nunca o toque.
      function aplicarGanhoSeita(g, res, origem, dadosVelhos) {
        if (!onda || !g) return;
        setSeitaRecibo({ linhas: reciboDaSeita(g, res, origem), k: Date.now() });
        if (g.depois && dadosVelhos) setSeitaOv({ depois: g.depois, dados: dadosVelhos });
        if ((g.acende || []).indexOf("posto") >= 0) setSeitaAcende({ k: Date.now() });
        setSeitaRolar(x => x + 1);
      }
      // a promoção confirmada AO ABRIR (um portão de reino caiu desde a última
      // contribuição): chega no próprio payload do Salão, uma vez
      useEffect(() => {
        if (onda && data && data.seita_ganho) aplicarGanhoSeita(data.seita_ganho, null, "salao", null);
      }, [data]);

      function refresh() { setReload(r => r + 1); onChanged && onChanged(); }

      async function doLeave() {
        if (leaveBusy) return;
        setLeaveBusy(true); haptic("warning");
        try {
          const res = await api("world/sect_leave", {});
          if (res && res.ok) {
            haptic("success");
            showToast(safeT("sect_hall_left_ok"));
            onChanged && onChanged();   // header/profile reflect the lost membership
            onClose && onClose();       // close the Hall (no longer a member)
          } else {
            // Idempotent (already left) → treat as success-ish: refresh shows non-member.
            haptic("error");
            showToast(safeT(res && res.reason === "not_in_sect" ? "sect_hall_left_ok" : "err_engine"));
            refresh();
          }
        } catch (e) { haptic("error"); showToast(safeT("err_engine")); }
        finally { setLeaveBusy(false); setLeaveConfirm(false); }
      }

      async function learn(techId) {
        if (busyTech != null) return;
        setBusyTech(techId); haptic("select");
        try {
          const res = await api("world/sect_learn_tech", { tech_id: techId });
          if (res && res.ok) { haptic("success"); showToast(safeT("wsect_learn_ok", { name: res.name })); refresh(); }
          else {
            haptic("error");
            const m = { rank_too_low: "wsect_learn_rank_low", already_learned: "wsect_learn_already", realm_too_low: "wsect_learn_realm_low" };
            showToast(safeT(m[res && res.reason] || "wsect_learn_fail", { realm: (res && res.req_realm) || 0 }));
          }
        } catch (e) { haptic("error"); showToast(safeT("err_engine")); }
        finally { setBusyTech(null); }
      }

      // TEC-1 — aprender uma arte NOVA das estantes (2º tap do confirm).
      async function learnShelf(art) {
        if (libBusy != null) return;
        setLibBusy(art.tech_id); haptic("select");
        try {
          const res = await api("world/sect_library_learn", { tech_id: art.tech_id });
          if (res && res.ok) {
            haptic("success");
            showToast(safeT(res.auto_equipped ? "lib_mini_learned_equipped" : "lib_mini_learned", { name: res.name }));
            setLibConfirm(null);
            refresh();
          } else {
            haptic("error");
            /* TEC-5 — as 3 recusas de ESCRITA do Cofre entram no mapa: quem
               perdesse o gate entre a vitrine e o confirm lia o genérico
               "não foi possível aprender" em vez de saber qual porta fechou. */
            const m = { insufficient_merit: "lib_mini_err_cp", quest_required: "lib_mini_err_quest",
                        rank_too_low: "lib_mini_err_rank", already_learned: "wsect_learn_already",
                        realm_too_low: "wsect_learn_realm_low",
                        path_required: "fpd_mini_block_path",
                        fp_karma_too_low: "fpd_mini_block_karma",
                        hd_rite_required: "fpd_mini_block_rite" };
            showToast(safeT(m[res && res.reason] || "wsect_learn_fail",
              { realm: (res && res.req_realm) || 0, cost: (res && res.cost) || 0, balance: (res && res.balance) || 0,
                have: (res && res.karma_have) || 0, need: (res && res.karma_need) || 0 }));
            setLibConfirm(null);
          }
        } catch (e) { haptic("error"); showToast(safeT("err_engine")); }
        finally { setLibBusy(null); }
      }

      // TEC-3 — abrir a Prova da Sucessão pela arte da Estante Oculta. O settle
      // (que TRANSMITE a arte na vitória) roda no poll de combat/duel_state,
      // então ao fechar a arena basta refrescar as estantes.
      async function startRite(art) {
        if (libBusy != null) return;
        setLibBusy(art.tech_id); haptic("warning");
        try {
          const res = await api("world/hidden_rite_start", { tech_id: art.tech_id });
          if (res && res.ok && res.duel_id) {
            setRiteDuel(res.duel_id);
          } else {
            haptic("error");
            const reason = (res && res.reason) || "engine";
            const m = { rite_cooldown: "sel_mini_err_cooldown", karma_too_low: "sel_mini_err_karma",
                        duel_already_active: "sel_mini_err_busy", hp_depleted: "sel_mini_err_hp",
                        rank_too_low: "lib_mini_err_rank", already_learned: "wsect_learn_already",
                        rite_already_passed: "wsect_learn_already", realm_too_low: "wsect_learn_realm_low" };
            showToast(safeT(m[reason] || "wsect_learn_fail", {
              realm: (res && res.req_realm) || 0,
              have: (res && res.karma_have) || 0,
              need: (res && res.karma_need) || 0,
              hours: (res && res.cooldown_ms) ? Math.max(1, Math.ceil(((res.cooldown_ms) - Date.now()) / 3600000)) : 0,
            }));
          }
        } catch (e) { haptic("error"); showToast(safeT("err_engine")); }
        finally { setLibBusy(null); }
      }

      // 宗 4.1 — o tributo da onda: a mesma rota, e o que ela CONFIRMOU fica no
      // selo (o recibo, a insígnia que acende) em vez de um toast que some.
      async function tributoOnda(amt) {
        if (seitaBusy) return;
        setSeitaBusy(amt); setSeitaErro(null); haptic("warning");
        const dadosVelhos = data;
        try {
          const res = await api("world/sect_tribute", { stones: amt });
          if (res && res.ok) {
            haptic("success");
            aplicarGanhoSeita(res.seita_ganho, res, "tributo", dadosVelhos);
            refresh();
          } else {
            haptic("error");
            setSeitaErro(safeT(res && res.reason === "tribute_too_small" ? "wsect_tribute_too_small"
                                                                       : "err_engine"));
          }
        } catch (e) { haptic("error"); setSeitaErro(safeT("err_engine")); }
        finally { setSeitaBusy(null); }
      }

      async function tribute(amt) {
        if (tributeBusy) return;
        setTributeBusy(true); haptic("warning");
        try {
          const res = await api("world/sect_tribute", { stones: amt });
          if (res && res.ok) {
            haptic("success");
            if (res.promotion) showToast(safeT("wsect_tribute_promoted", { rank: safeT("wsect_rank_" + res.promotion.new) }));
            else showToast(safeT("wsect_tribute_ok", { stones: res.stones_spent, points: res.points }));
            refresh();
          } else { haptic("error"); showToast(safeT("wsect_tribute_too_small")); }
        } catch (e) { haptic("error"); showToast(safeT("err_engine")); }
        finally { setTributeBusy(false); }
      }

      // wave 3 — buy a cosmetic title from the Merit Pavilion (spends merit
      // balance; rank progress is never touched). refresh() reloads BOTH the hall
      // + the merit list ([reload]); onChanged→loadPlayer so the new title shows.
      async function buyMerit(rid) {
        if (meritBusy) return;
        setMeritBusy(rid); haptic("select");
        try {
          const res = await api("world/merit_buy", { reward_id: rid });
          if (res && res.ok) { haptic("success"); showToast(safeT("merit_buy_ok", { title: res.title })); refresh(); }
          else {
            haptic("error");
            const m = { already_owned: "merit_already_owned", insufficient_merit: "merit_insufficient", rank_too_low: "merit_rank_too_low" };
            showToast(safeT(m[res && res.reason] || "err_engine", { rank: safeT((res && res.rank_min_key) || "") }));
          }
        } catch (e) { haptic("error"); showToast(safeT("err_engine")); }
        finally { setMeritBusy(null); }
      }

      if (choiceQuest) {
        return <QuestChoiceModal q={choiceQuest} onClose={() => setChoiceQuest(null)}
                 onDone={(res) => {
                   if (res && res.seita_ganho) aplicarGanhoSeita(res.seita_ganho, res, "missao", data);
                   setChoiceQuest(null); refresh();
                 }} />;
      }

      // TEC-3 — a Prova em curso ocupa a tela (arena padrão, z:80). Fechar
      // volta ao Salão e refresca: o settle já rodou no poll do duelo, então a
      // arte transmitida aparece sozinha na Estante Oculta.
      if (riteDuel) {
        return <DuelArenaModal duelId={riteDuel} playerLang={null}
                 onClose={() => { setRiteDuel(null); refresh(); }} />;
      }

      const sect = (data && data.sect) || {};
      const nxt = data && data.next_rank;
      const contrib = (data && data.contribution) || 0;
      const pct = nxt && nxt.contribution_needed > 0 ? Math.min(100, (contrib / nxt.contribution_needed) * 100) : 100;
      const rate = (data && data.tribute_rate) || 25;
      const stones = (player && player.spirit_stones) || 0;

      return (
        <Modal onClose={onClose} title={`${player.sect_emoji || "🏯"} ${safeT("sect_hall_title")}`}>
          {error && <ErrBanner msg={error} />}
          {loading && !data && <ListSkeleton rows={5} />}
          {data && data.in_sect === false && (
            <div style={{ fontSize:12, color:"var(--muted)", padding:"10px 2px" }}>{safeT("sect_hall_not_member")}</div>
          )}
          {data && data.in_sect && (
            /* Fix overflow (report [jogador] + screenshot Saint 31/07): grid sem
               template = coluna auto que um filho nowrap ESTICA além do card
               (min-width:auto de grid item); o body clipa sem ellipsis.
               minmax(0,1fr) torna todo card encolhível — PC e telefone. */
            <div style={{ display:"grid", gridTemplateColumns:"minmax(0, 1fr)", gap:12, fontSize:12 }}>
              {/* ── Rank + philosophy ── */}
              <Card style={{ padding:"13px 14px" }}>
                <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between", gap:8 }}>
                  <div style={{ fontFamily:"'Cinzel',serif", fontSize:16, fontWeight:700, color:"var(--gold3)" }}>
                    {sect.name || ""}
                  </div>
                  {/* 宗 4.1 — com a onda o posto é o SELO, logo abaixo; um badge
                      aqui seria o mesmo facto escrito duas vezes */}
                  {!onda && <Badge variant="jade">{safeT(data.rank_key)}</Badge>}
                </div>
                {sect.philosophy && (
                  <div style={{ fontSize:11.5, color:"rgba(var(--text2-rgb),.8)", lineHeight:1.55, fontStyle:"italic", marginTop:6 }}>{sect.philosophy}</div>
                )}
                {/* Pedra 2 — the named shifu 师徒 (cosmetic identity; the bond's
                    bonus is deferred to the wipe). */}
                {data.master_name && (
                  <div style={{ display:"flex", alignItems:"center", gap:6, fontSize:11.5, color:"var(--gold3)", marginTop:8 }}>
                    <span>🧧</span>
                    <span>{safeT("sect_hall_master_line", { master: data.master_name })}</span>
                  </div>
                )}
              </Card>

              {/* ── Contribution → next rank ── 宗 4.1: com a onda, o SELO (as
                  cinco insígnias da escada do servidor, o requisito com os seus
                  números, o mérito à parte, o recibo e o tributo juntos) */}
              {onda ? (
                <SeitaSelo data={data} ov={seitaOv} acende={seitaAcende} recibo={seitaRecibo}
                           seloRef={seitaSeloRef} busy={seitaBusy} pedras={stones}
                           erro={seitaErro} onTributo={tributoOnda} />
              ) : (
              <Card style={{ padding:"12px 14px" }}>
                <div style={{ display:"flex", justifyContent:"space-between", fontSize:11, marginBottom:6 }}>
                  <span style={{ color:"var(--gold3)" }}>{safeT("sect_hall_contrib_label")}</span>
                  <span style={{ color:"var(--text)", fontWeight:700 }}>{fmtNum(contrib)}</span>
                </div>
                <ProgressBar pct={pct} variant="cult" />
                <div style={{ fontSize:11, color:"var(--muted)", marginTop:6 }}>
                  {nxt
                    ? safeT("sect_hall_next", { rank: safeT(nxt.rank_key), need: fmtNum(nxt.contribution_needed) })
                    : safeT("sect_hall_maxed")}
                  {nxt && !nxt.realm_met && <span style={{ color:"#FF8C8C" }}> · {safeT("sect_hall_realm_gate", { realm: nxt.realm_gate })}</span>}
                </div>
              </Card>
              )}

              {/* ── Perks (disclosed; full favour activates at the awakening) ── */}
              {data.perks && data.perks.length > 0 && (
                <Card style={{ padding:"12px 14px" }}>
                  <div style={{ fontSize:10, color:"var(--gold3)", fontFamily:"'Cinzel',serif", letterSpacing:1, textTransform:"uppercase", marginBottom:8 }}>
                    {safeT("sect_hall_perks_title")}
                  </div>
                  <div style={{ display:"grid", gap:4 }}>
                    {data.perks.map(p => (
                      <div key={p.key} style={{ display:"flex", justifyContent:"space-between", fontSize:11, color:"rgba(var(--text2-rgb),.82)" }}>
                        <span>{p.label}</span>
                        <span style={{ color:"var(--jade)" }}>{p.value}</span>
                      </div>
                    ))}
                  </div>
                  {/* Pedra 2 — the house's LIVE strength (World Pulse). The full
                      blessing will SCALE with it in the new world (§4) — for now
                      pure disclosure (zero balance, Lei §5). */}
                  {data.strength != null && data.strength > 0 && (
                    <div style={{ display:"flex", justifyContent:"space-between", fontSize:11, marginTop:9, paddingTop:8, borderTop:"1px solid rgba(var(--gold2-rgb),.13)" }}>
                      <span style={{ color:"rgba(var(--text2-rgb),.72)" }}>{safeT("sect_hall_strength_label")}</span>
                      <span style={{ color:"var(--gold3)", fontWeight:700 }}>{fmtNum(data.strength)} 💓</span>
                    </div>
                  )}
                  <div style={{ fontSize:10, color:"var(--muted)", marginTop:8, fontStyle:"italic" }}>{safeT("sect_hall_blessing_note")}</div>
                </Card>
              )}

              {/* ── Library ── TEC-1: com `biblioteca_seitas` ON o Hall mostra as
                  ESTANTES (legada grátis-por-posto + arte nova por contribuição,
                  confirm 2-tap com antes→depois); OFF → o bloco legado v16.4c
                  rende EXATAMENTE como sempre (byte-idêntico). */}
              {(lib.data && lib.data.on && lib.data.in_sect) ? (
                <div>
                  <div style={{ fontSize:10.5, color:"var(--gold3)", fontFamily:"'Cinzel',serif", letterSpacing:1.1, textTransform:"uppercase", marginBottom:7, paddingLeft:3 }}>
                    📚 {safeT("sect_hall_library_title")}
                  </div>
                  <Card style={{ padding:"8px 12px" }}>
                    <div style={{ display:"flex", justifyContent:"space-between", fontSize:11, marginBottom:6, paddingBottom:7, borderBottom:"1px solid rgba(var(--gold2-rgb),.13)" }}>
                      <span style={{ color:"var(--gold3)" }}>{safeT("lib_mini_balance_label")}</span>
                      <span style={{ color:"var(--text)", fontWeight:700 }}>{fmtNum(lib.data.merit_balance)} 🏛️</span>
                    </div>
                    {(lib.data.shelves || []).map(shelf => (
                      <div key={shelf.tier} style={{ marginBottom:4 }}>
                        <div style={{ fontSize:10, color: shelf.rank_ok ? "var(--jade)" : "var(--muted)", fontFamily:"'Cinzel',serif", letterSpacing:.6, textTransform:"uppercase", margin:"7px 0 2px" }}>
                          {shelf.rank_ok ? "📖" : "🔒"} {shelf.label} · {safeT(shelf.min_rank_key)}
                        </div>
                        {/* TEC-3 — o caminho QUANTIFICADO (Lei §1): quanto falta para o degrau */}
                        {shelf.rank_gap && (
                          <div style={{ fontSize:10, color:"var(--muted)", fontStyle:"italic", margin:"0 0 3px" }}>
                            {shelf.rank_gap.contribution && shelf.rank_gap.realm
                              ? safeT("sel_mini_gap_both", { cp: fmtNum(shelf.rank_gap.contribution), realm: shelf.rank_gap.realm })
                              : shelf.rank_gap.contribution
                                ? safeT("sel_mini_gap_cp", { cp: fmtNum(shelf.rank_gap.contribution) })
                                : safeT("sel_mini_gap_realm", { realm: shelf.rank_gap.realm })}
                          </div>
                        )}
                        {(shelf.arts || []).map(art => (
                          <div key={art.tech_id} style={{ padding:"7px 0", borderBottom:"1px dashed rgba(var(--glow-rgb),.18)" }}>
                            <div style={{ display:"flex", alignItems:"center", gap:8 }}>
                              <span style={{ fontSize:17 }}>{art.emoji}</span>
                              <div style={{ flex:1, minWidth:0 }}>
                                <div style={{ fontSize:12.5, fontWeight:600, color: art.learned || art.can_learn ? "var(--text)" : "var(--muted)" }}>
                                  {art.name}
                                </div>
                                <div style={{ fontSize:10.5, color:"var(--muted)", overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap" }}>{art.desc}</div>
                              </div>
                              {art.learned
                                ? <Badge variant="jade">✓ {safeT("sect_hall_learned")}</Badge>
                                : art.can_learn
                                  ? (art.legacy
                                      ? <ActionBtn variant="primary" disabled={busyTech === art.tech_id} onClick={() => learn(art.tech_id)} style={{ flexShrink:0, padding:"6px 12px", fontSize:11 }}>
                                          {busyTech === art.tech_id ? <DotSpinner /> : safeT("sect_hall_learn_btn")}
                                        </ActionBtn>
                                      : <ActionBtn variant="primary" disabled={libBusy === art.tech_id}
                                          onClick={() => { haptic("select"); setLibConfirm(libConfirm === art.tech_id ? null : art.tech_id); }}
                                          style={{ flexShrink:0, padding:"6px 12px", fontSize:11 }}>
                                          {art.cost > 0 ? `${safeT("sect_hall_learn_btn")} · ${fmtNum(art.cost)} 🏛️` : safeT("sect_hall_learn_btn")}
                                        </ActionBtn>)
                                  : art.block === "rite"
                                    /* TEC-3 — a Prova é o preço: botão, não cadeado (Lei §1). */
                                    ? <ActionBtn variant="primary" disabled={libBusy === art.tech_id}
                                        onClick={() => startRite(art)}
                                        style={{ flexShrink:0, padding:"6px 12px", fontSize:11 }}>
                                        {libBusy === art.tech_id ? <DotSpinner /> : `⚔️ ${safeT("sel_mini_rite_btn")}`}
                                      </ActionBtn>
                                    : <span style={{ flexShrink:0, fontSize:10, color:"var(--muted)", textAlign:"right" }}>
                                      🔒 {art.block === "cp" ? safeT("lib_mini_block_cp", { cost: fmtNum(art.cost) })
                                         : art.block === "quest" ? safeT("lib_mini_block_quest")
                                         : art.block === "realm" ? safeT("lib_mini_block_realm", { realm: art.req_realm })
                                         : art.block === "karma" ? safeT("sel_mini_block_karma", { have: art.karma_have, need: art.karma_need })
                                         /* TEC-5 — os 3 bloqueios do Cofre Proibido. Sem estas
                                            linhas o fallback dizia "exige posto Herdeiro" quando
                                            o que falta é o CAMINHO (lição QoL-relatos: enum novo entra
                                            em TODO mapa). */
                                         : art.block === "path" ? safeT("fpd_mini_block_path")
                                         : art.block === "fp_karma" ? safeT("fpd_mini_block_karma", { have: art.karma_have, need: art.karma_need })
                                         : art.block === "hd_rite" ? safeT("fpd_mini_block_rite")
                                         : safeT(art.min_rank_key)}
                                    </span>}
                            </div>
                            {/* TEC-5 — o preço do Cofre DITO na vitrine, antes do tap:
                                karma + anos por uso + "só desperta em duelo verdadeiro"
                                (Lei §1 — custo invisível = custo nenhum). Key condicional. */}
                            {art.forbidden && (() => {
                              const fv = (lib.data && lib.data.forbidden_vault) || {};
                              return (
                                <div style={{ marginTop:4, fontSize:10, color:"#e5a0a0", lineHeight:1.5 }}>
                                  <div>
                                    {fv.immortal
                                      ? safeT("fpd_mini_cost_immortal", { karma: fv.karma_cost })
                                      : safeT("fpd_mini_cost", { karma: fv.karma_cost, years: fv.years_per_use, uses: fv.uses_left })}
                                  </div>
                                  <div style={{ fontStyle:"italic", color:"var(--muted)" }}>{safeT("fpd_mini_duel_only")}</div>
                                </div>
                              );
                            })()}
                            {/* confirm 2-tap: custo + loadout antes→depois (Lei §10) */}
                            {libConfirm === art.tech_id && !art.learned && art.can_learn && !art.legacy && (
                              <div style={{ marginTop:6, padding:"7px 9px", borderRadius:7, background:"rgba(var(--gold2-rgb),.07)", border:"1px solid rgba(var(--gold2-rgb),.25)" }}>
                                <div style={{ fontSize:10.5, color:"rgba(var(--text2-rgb),.85)", lineHeight:1.5, marginBottom:6 }}>
                                  {art.cost > 0
                                    ? safeT("lib_mini_confirm_cost", { cost: fmtNum(art.cost), balance: fmtNum(lib.data.merit_balance) })
                                    : safeT("lib_mini_confirm_free")}
                                  <br />
                                  {safeT("lib_mini_confirm_loadout", {
                                    before: ((lib.data.loadout || []).map(x => x.name).join(", ") || "—"),
                                    name: art.name,
                                  })}
                                </div>
                                <div style={{ display:"flex", gap:6 }}>
                                  <ActionBtn variant="ghost" onClick={() => setLibConfirm(null)} style={{ flex:1, padding:"6px 8px", fontSize:11 }}>
                                    {safeT("btn_cancel")}
                                  </ActionBtn>
                                  <ActionBtn variant="primary" disabled={libBusy === art.tech_id} onClick={() => learnShelf(art)} style={{ flex:1, padding:"6px 8px", fontSize:11 }}>
                                    {libBusy === art.tech_id ? <DotSpinner /> : safeT("lib_mini_confirm_btn")}
                                  </ActionBtn>
                                </div>
                              </div>
                            )}
                          </div>
                        ))}
                      </div>
                    ))}
                    {/* estantes seladas — teaser honesto (Lei §1; TEC-2+) */}
                    {(lib.data.sealed || []).map(s => (
                      <div key={s.key} style={{ marginBottom:4 }}>
                        <div style={{ fontSize:10, color:"var(--muted)", fontFamily:"'Cinzel',serif", letterSpacing:.6, textTransform:"uppercase", margin:"7px 0 2px" }}>
                          {s.rank_ok ? "📖" : "🔒"} {s.label} · {safeT(s.min_rank_key)}
                        </div>
                        {s.art && (
                          <div style={{ display:"flex", alignItems:"center", gap:8, padding:"7px 0" }}>
                            <span style={{ fontSize:17 }}>{s.art.emoji}</span>
                            <div style={{ flex:1, minWidth:0 }}>
                              <div style={{ fontSize:12.5, fontWeight:600, color: s.art.learned || s.art.can_learn ? "var(--text)" : "var(--muted)" }}>{s.art.name}</div>
                            </div>
                            {s.art.learned
                              ? <Badge variant="jade">✓ {safeT("sect_hall_learned")}</Badge>
                              : s.art.can_learn
                                ? <ActionBtn variant="primary" disabled={busyTech === s.art.tech_id} onClick={() => learn(s.art.tech_id)} style={{ flexShrink:0, padding:"6px 12px", fontSize:11 }}>
                                    {busyTech === s.art.tech_id ? <DotSpinner /> : safeT("sect_hall_learn_btn")}
                                  </ActionBtn>
                                : <span style={{ flexShrink:0, fontSize:10, color:"var(--muted)" }}>🔒 {safeT(s.min_rank_key)}</span>}
                          </div>
                        )}
                        <div style={{ fontSize:10, color:"var(--muted)", fontStyle:"italic", padding:"2px 0 6px", borderBottom:"1px dashed rgba(var(--glow-rgb),.18)" }}>
                          🔒 {s.teaser}
                        </div>
                      </div>
                    ))}
                    {!lib.data.quest_done && (
                      <div style={{ fontSize:10, color:"var(--muted)", fontStyle:"italic", marginTop:7 }}>
                        {safeT("lib_mini_quest_hint")}
                      </div>
                    )}
                    {/* TEC-3 — a Prova de castigo: DIZER o prazo (nunca botão morto) */}
                    {lib.data.rite && lib.data.rite.cooldown_ms && (
                      <div style={{ fontSize:10, color:"var(--muted)", fontStyle:"italic", marginTop:5 }}>
                        {safeT("sel_mini_rite_cooldown", { hours: Math.max(1, Math.ceil((lib.data.rite.cooldown_ms - Date.now()) / 3600000)) })}
                      </div>
                    )}
                  </Card>
                </div>
              ) : (
              <div>
                <div style={{ fontSize:10.5, color:"var(--gold3)", fontFamily:"'Cinzel',serif", letterSpacing:1.1, textTransform:"uppercase", marginBottom:7, paddingLeft:3 }}>
                  {safeT("sect_hall_library_title")}
                </div>
                <Card style={{ padding:"6px 12px" }}>
                  {(data.library || []).map(tech => (
                    <div key={tech.tech_id} style={{ display:"flex", alignItems:"center", gap:8, padding:"9px 2px", borderBottom:"1px dashed rgba(var(--glow-rgb),.18)" }}>
                      <span style={{ fontSize:17 }}>{tech.emoji}</span>
                      <div style={{ flex:1, minWidth:0 }}>
                        <div style={{ fontSize:12.5, fontWeight:600, color: tech.unlocked ? "var(--text)" : "var(--muted)" }}>
                          {tech.name} <span style={{ fontSize:10, color:"var(--muted)" }}>· T{tech.tier}</span>
                        </div>
                        {/* Mesmo defeito da alquimia — e aqui doi mais: a
                            tecnica e' a carta mais importante do jogo. */}
                        <div style={{ fontSize:10.5, color:"var(--muted)", lineHeight:1.35,
                                      overflowWrap:"anywhere" }}>{tech.description}</div>
                      </div>
                      {tech.learned
                        ? <Badge variant="jade">✓ {safeT("sect_hall_learned")}</Badge>
                        : tech.unlocked
                          ? <ActionBtn variant="primary" disabled={busyTech === tech.tech_id} onClick={() => learn(tech.tech_id)} style={{ padding:"6px 12px", fontSize:11 }}>
                              {busyTech === tech.tech_id ? <DotSpinner /> : safeT("sect_hall_learn_btn")}
                            </ActionBtn>
                          : <span style={{ flexShrink:0, fontSize:10, color:"var(--muted)" }}>🔒 {safeT(tech.rank_key)}</span>}
                    </div>
                  ))}
                </Card>
              </div>
              )}

              {/* ── Tribute ── 宗 4.1: com a onda o tributo vive DENTRO do selo,
                  junto da insígnia que ele pode acender (a consequência junto da
                  operação) — aqui só sem ela */}
              {!onda && (
              <Card style={{ padding:"12px 14px" }}>
                <div style={{ fontSize:10, color:"var(--gold3)", fontFamily:"'Cinzel',serif", letterSpacing:1, textTransform:"uppercase", marginBottom:6 }}>
                  {safeT("sect_hall_tribute_title")}
                </div>
                <div style={{ fontSize:11, color:"rgba(var(--text2-rgb),.8)", marginBottom:8 }}>{safeT("sect_hall_tribute_intro", { rate })}</div>
                <div style={{ display:"flex", gap:6, flexWrap:"wrap" }}>
                  {[250, 1000, 5000].filter(a => stones >= a).map(a => (
                    <ActionBtn key={a} disabled={tributeBusy} onClick={() => tribute(a)} style={{ flex:1, minWidth:90, padding:"7px 8px", fontSize:11 }}>
                      {tributeBusy ? <DotSpinner /> : `${fmtNum(a)} → +${Math.floor(a / rate)}`}
                    </ActionBtn>
                  ))}
                  {stones < 250 && <div style={{ fontSize:11, color:"var(--muted)" }}>{safeT("sect_hall_tribute_too_small")}</div>}
                </div>
              </Card>
              )}

              {/* ── Pavilhão de Mérito (wave 3) — spend merit on house cosmetics ── */}
              {merit.data && merit.data.in_sect && (merit.data.rewards || []).length > 0 && (
                <div>
                  <div style={{ fontSize:10.5, color:"var(--gold3)", fontFamily:"'Cinzel',serif", letterSpacing:1.1, textTransform:"uppercase", marginBottom:7, paddingLeft:3 }}>
                    {safeT("merit_pavilion_title")}
                  </div>
                  <Card style={{ padding:"10px 14px" }}>
                    <div style={{ fontSize:11, color:"rgba(var(--text2-rgb),.8)", marginBottom:8 }}>{safeT("merit_pavilion_intro")}</div>
                    <div style={{ display:"flex", justifyContent:"space-between", fontSize:11, marginBottom:8, paddingBottom:8, borderBottom:"1px solid rgba(var(--gold2-rgb),.13)" }}>
                      <span style={{ color:"var(--gold3)" }}>{safeT("merit_balance_label")}</span>
                      <span style={{ color:"var(--text)", fontWeight:700 }}>{fmtNum(merit.data.merit_balance)} 🏛️</span>
                    </div>
                    {merit.data.rewards.map(r => (
                      <div key={r.id} style={{ display:"flex", alignItems:"center", gap:8, padding:"8px 0", borderBottom:"1px dashed rgba(var(--glow-rgb),.18)" }}>
                        <div style={{ flex:1, minWidth:0 }}>
                          <div style={{ fontSize:12.5, fontWeight:600, color: r.owned ? "var(--jade)" : (r.rank_ok ? "var(--text)" : "var(--muted)") }}>{r.title}</div>
                          <div style={{ fontSize:10.5, color:"var(--muted)", lineHeight:1.45 }}>{r.desc}</div>
                        </div>
                        {r.owned
                          ? <Badge variant="jade">✓ {safeT("merit_owned")}</Badge>
                          : !r.rank_ok
                            ? <span style={{ flexShrink:0, fontSize:10, color:"var(--muted)", textAlign:"right" }}>🔒 {safeT("merit_locked_rank", { rank: safeT(r.rank_min_key) })}</span>
                            : <ActionBtn variant="primary" disabled={meritBusy === r.id || !r.affordable} onClick={() => buyMerit(r.id)} style={{ flexShrink:0, padding:"7px 12px", fontSize:11 }}>
                                {meritBusy === r.id ? <DotSpinner /> : `${safeT("merit_buy_btn")} · ${fmtNum(r.cost)}`}
                              </ActionBtn>}
                      </div>
                    ))}
                  </Card>
                </div>
              )}

              {/* ── Sect Quests ── */}
              <div>
                <div style={{ fontSize:10.5, color:"var(--gold3)", fontFamily:"'Cinzel',serif", letterSpacing:1.1, textTransform:"uppercase", marginBottom:7, paddingLeft:3 }}>
                  {safeT("sect_hall_quests_title")}
                </div>
                <Card style={{ padding:"4px 12px" }}>
                  {(!data.quests || data.quests.length === 0)
                    ? <div style={{ fontSize:11, color:"var(--muted)", padding:"8px 2px" }}>{safeT("sect_hall_quests_empty")}</div>
                    : data.quests.map(q => (
                        <QuestRow key={q.id} q={q}
                                  onClaimed={(res) => {
                                    // 宗 4.1 — a missão da casa é a porta que MAIS
                                    // muda o posto: o ganho dela vai ao selo
                                    if (res && res.seita_ganho) aplicarGanhoSeita(res.seita_ganho, res, "missao", data);
                                    refresh();
                                  }}
                                  onChoose={(qq) => setChoiceQuest(qq)} />
                      ))}
                </Card>
              </div>

              {/* ── Leave / Betray (B 2026-06-16 — simple leave, no technique lockout) ── */}
              <div style={{ marginTop:2, paddingTop:10, borderTop:"1px solid rgba(255,120,120,.14)" }}>
                {!leaveConfirm ? (
                  <ActionBtn variant="ghost" onClick={() => { haptic("warning"); setLeaveConfirm(true); }}
                    style={{ width:"100%", fontSize:11, color:"#FF9C9C" }}>
                    {safeT("sect_hall_leave_btn")}
                  </ActionBtn>
                ) : (
                  <div style={{ display:"grid", gap:6 }}>
                    <div style={{ fontSize:10.5, color:"#FFB0B0", textAlign:"center", lineHeight:1.45 }}>
                      {safeT("sect_hall_leave_confirm")}
                    </div>
                    {/* TEC-1 — disclosure honesta: as artes do Núcleo LOCKAM ao
                        sair (nunca apagadas; voltar à MESMA casa re-destranca).
                        Derivado do payload das estantes — zero endpoint novo. */}
                    {(() => {
                      if (!(lib.data && lib.data.on && lib.data.in_sect)) return null;
                      const lockable = (lib.data.shelves || [])
                        /* TEC-3: >= 3 — Núcleo, Ancião E Oculta trancam ao sair.
                           Sombra do LOCK_TIER_FLOOR do engine; sem o >= o aviso
                           mentiria por omissão sobre as duas artes mais caras. */
                        .filter(s => s.tier >= 3)
                        .flatMap(s => (s.arts || []).filter(a => a.learned && !a.legacy))
                        .map(a => a.name);
                      if (!lockable.length) return null;
                      return (
                        <div style={{ fontSize:10, color:"#FFB0B0", textAlign:"center", lineHeight:1.45, fontStyle:"italic" }}>
                          {safeT("lib_mini_leave_warn", { arts: lockable.join(", ") })}
                        </div>
                      );
                    })()}
                    <div style={{ display:"flex", gap:6 }}>
                      <ActionBtn variant="ghost" onClick={() => setLeaveConfirm(false)} style={{ flex:1, fontSize:11 }}>
                        {safeT("btn_cancel")}
                      </ActionBtn>
                      <ActionBtn variant="primary" disabled={leaveBusy} onClick={doLeave} style={{ flex:1, fontSize:11 }}>
                        {leaveBusy ? <DotSpinner /> : safeT("sect_hall_leave_do")}
                      </ActionBtn>
                    </div>
                  </div>
                )}
              </div>
            </div>
          )}
        </Modal>
      );
    }

    function ProfileModal({ onClose, player, onOpenContinent, onOpenPath, onOpenKarma, onOpenSect, onOpenHall, onOpenProfession, setTab }) {
      if (!player) return null;
      // ⚠️ Aqui viviam OUTROS 11 emoji de reino, e o comentário deles dizia,
      // por escrito, *"Mirrors the `REALM_EMOJIS` from ui.js"* — a Lei F-7
      // confessada na própria linha que a violava. O avatar tem um dono agora
      // (`RealmAvatar`, em ui.js) e a tabela mora lá.
      const realmName = realmShort(player.realm) || t("realm_0");

      // Achievements preview — last 3 unlocked. Fetched lazily.
      const ach = useApi("achievements/list", null, []);
      const recentUnlocked = (() => {
        if (!ach.data || !ach.data.items) return [];
        return ach.data.items
          .filter(it => it.is_unlocked && it.unlocked_at_ms)
          .sort((a, b) => (b.unlocked_at_ms || 0) - (a.unlocked_at_ms || 0))
          .slice(0, 3);
      })();
      const unlockedCount = (ach.data && ach.data.unlocked_count) || 0;
      const totalCount = (ach.data && ach.data.count) || 0;

      // Karma band → color (same palette KarmaModal/chip use).
      const _karmaColor = (band) => ({
        saint:   "rgba(245,220,160,.95)",
        pure:    "rgba(190,220,255,.92)",
        neutral: "rgba(200,210,220,.85)",
        tainted: "rgba(240,170,170,.92)",
        demonic: "rgba(255,180,180,.95)",
      }[band] || "rgba(200,210,220,.85)");

      // Path tier → color (same palette PathModal uses).
      const _pathColor = (tier) => ({
        celestial: "rgba(245,220,160,.95)",
        demonic:   "rgba(255,180,180,.95)",
        neutral:   "rgba(200,210,220,.85)",
      }[tier] || "rgba(200,210,220,.85)");

      const _identityCard = (icon, labelKey, value, onClick, accentColor, disabled) => (
        <button
          onClick={() => {
            if (disabled) return;
            haptic("select");
            onClick && onClick();
          }}
          disabled={disabled}
          style={{
            display:"flex", flexDirection:"column", gap:4,
            padding:"10px 11px", borderRadius:8,
            background:"rgba(0,0,0,.32)",
            border:`1px solid ${accentColor ? `${accentColor.replace(/[.]95\)/, '.35)').replace(/[.]92\)/, '.35)').replace(/[.]85\)/, '.30)')}` : "rgba(var(--gold2-rgb),.22)"}`,
            color:"var(--text)",
            cursor: disabled ? "default" : "pointer",
            opacity: disabled ? 0.55 : 1,
            textAlign:"left",
            fontFamily:"inherit",
            transition:"all .15s",
            minHeight:64,
            // Report [jogador] 18/08 — a Identidade transbordava para a direita no
            // telemovel. `1fr` = `minmax(auto,1fr)`: o minimo automatico de um
            // item de grid e o seu min-content, e com `whiteSpace:nowrap` nos
            // filhos isso e a LINHA INTEIRA. O ellipsis nunca disparava porque
            // a coluna crescia em vez de o texto encolher. minWidth:0 desarma
            // o minimo automatico (3a recorrencia: Salao 31/07, mapa 09/08).
            minWidth:0,
          }}>
          <div style={{ display:"flex", alignItems:"center", gap:7, minWidth:0 }}>
            <span style={{ fontSize:18, lineHeight:1 }}>{icon}</span>
            <span style={{
              fontSize:9.5, color:"var(--gold3)", letterSpacing:.9,
              fontFamily:"'Cinzel',serif", textTransform:"uppercase", fontWeight:600,
              flex:1, minWidth:0,
              overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap",
            }}>
              {safeT(labelKey)}
            </span>
          </div>
          <div style={{
            fontSize:13, fontWeight:600,
            color: accentColor || "rgba(var(--text2-rgb),.92)",
            marginLeft:25,
            overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap",
          }}>
            {value}
          </div>
        </button>
      );

      const stats = [
        // Poder de Combate: mirror the PlayerHeader/Atributos — show the aggregated
        // display_combat_power when progressao_visivel is ON (else raw battle_power),
        // so tapping the profile matches the headline number the header shows.
        { label: t("battle_power"),
          value: fmtNum((typeof featureEnabled === "function" && featureEnabled("progressao_visivel") && player.display_combat_power != null)
                        ? player.display_combat_power : player.battle_power) },
        { label: t("soul_strength"), value: fmtNum(player.soul_strength) },
        { label: t("perception"), value: fmtNum(player.perception) },
        { label: t("luck"), value: fmtNum(player.luck) },
      ];

      const karmaSign = player.karma > 0 ? "+" : "";
      const karmaValueStr = `${karmaSign}${player.karma || 0} · ${player.karma_label || ""}`;

      // v16.4 — NPC sect (Seita de Cultivo) identity value. Shows the joined house
      // (+ rank) or the CTA when unaffiliated. The card is ALWAYS tappable —
      // it opens the 9-house directory + the cultivator's per-house affinity.
      const sectValueStr = player.sect_chip_visible
        ? `${player.sect_name || ""}${player.sect_rank_key ? " · " + safeT(player.sect_rank_key) : ""}`
        : safeT("profile_grid_sect_empty");

      return (
        <Modal onClose={onClose} title={`☯️ ${safeT("profile_modal_title")}`}>
          {/* Fix overflow 31/07 (mesmo do Salão): minmax(0,1fr) — cards
              encolhíveis; sem isto um filho nowrap esticava a coluna auto. */}
          <div style={{ display:"grid", gridTemplateColumns:"minmax(0, 1fr)", gap:11, fontSize:12 }}>
            {/* ── Hero card — realm-emoji avatar + name + title + realm */}
            <Card style={{ padding:"14px 14px 12px" }}>
              <div style={{ display:"flex", alignItems:"center", gap:13 }}>
                {/* 坐 A SEGUNDA VIDA DO ORBE, morta pelo mesmo dono. Esta bola
                    era uma cópia à mão da do `PlayerHeader` — mesmo gradiente,
                    mesmos 11 emoji, seis valores diferentes por acidente. Agora
                    as duas são `RealmAvatar` (ui.js): um conserto, dois sítios.
                    É a Lei 0 passo 2, e é exactamente a recorrência que a Lei
                    F-7 descreve. */}
                <RealmAvatar realm={player.realm} size={60} style={{ flexShrink:0 }} />
                <div style={{ flex:1, minWidth:0 }}>
                  <div style={{
                    fontFamily:"'Cinzel',serif", fontSize:20, fontWeight:700, letterSpacing:.6,
                    background:"linear-gradient(90deg,var(--gold3),var(--gold2),var(--gold))",
                    WebkitBackgroundClip:"text", backgroundClip:"text", WebkitTextFillColor:"transparent",
                    overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap",
                  }}>
                    {player.dao_name}
                  </div>
                  {player.active_title && (
                    <div style={{ fontSize:11, color:"rgba(var(--gold-rgb),.85)", marginTop:2,
                                   letterSpacing:.3, overflow:"hidden", textOverflow:"ellipsis",
                                   whiteSpace:"nowrap" }}>
                      {t("title_prefix")} {player.active_title}
                    </div>
                  )}
                  <div style={{
                    fontSize:11, color:"var(--gold3)", marginTop:5,
                    fontFamily:"'Cinzel',serif", letterSpacing:.4,
                  }}>
                    {realmName} · {safeT("profile_hero_layer", { n: player.sub_layer || 1 })}
                  </div>
                </div>
              </div>
            </Card>

            {/* ── Identity grid 2×2 — Continent / Path / Karma / Sect */}
            <div>
              <div style={{
                fontSize:10.5, color:"var(--gold3)",
                fontFamily:"'Cinzel',serif", letterSpacing:1.1,
                textTransform:"uppercase", marginBottom:7, paddingLeft:3,
              }}>
                {safeT("profile_identity_section_title")}
              </div>
              <div style={{ display:"grid", gridTemplateColumns:"minmax(0,1fr) minmax(0,1fr)", gap:7 }}>
                {_identityCard(
                  player.current_continent_emoji || "🌍",
                  "profile_grid_continent_card_label",
                  player.current_continent_name || "—",
                  onOpenContinent,
                  "rgba(160,200,255,.85)",
                  !player.current_continent_emoji,
                )}
                {_identityCard(
                  player.path_emoji || "☯️",
                  "profile_grid_path_card_label",
                  player.path_raw ? player.path_name : safeT("path_chip_forming"),
                  onOpenPath,
                  _pathColor(player.path_meta_resolved && player.path_meta_resolved.tier),
                  false,
                )}
                {_identityCard(
                  player.karma_emoji || "☯️",
                  "profile_grid_karma_card_label",
                  player.karma_chip_visible ? karmaValueStr : safeT("profile_grid_karma_empty"),
                  onOpenKarma,
                  _karmaColor(player.karma_band),
                  !player.karma_chip_visible,
                )}
                {_identityCard(
                  player.sect_emoji || "🏯",
                  "profile_grid_sect_card_label",
                  sectValueStr,
                  // v16.4c — MEMBERS open the Sect Hall (rank/library/quests);
                  // unaffiliated cultivators open the 9-house directory.
                  (player.sect_chip_visible ? onOpenHall : onOpenSect),
                  "rgba(var(--gold2-rgb),.95)",
                  false,
                )}
              </div>
              {/* Pedra 2 — the Master-Disciple bond 师徒 as an identity line
                  (keeps the 2×2 card showing sect+rank; non-regressive). */}
              {player.sect_chip_visible && player.sect_master_name && (
                <div style={{ fontSize:11, color:"rgba(var(--gold2-rgb),.85)", marginTop:8, paddingLeft:3, fontStyle:"italic" }}>
                  {safeT("profile_sect_master_line", { master: player.sect_master_name, sect: player.sect_name || "" })}
                </div>
              )}
              {/* MV-7 — a linha do OFÍCIO (payload-gated: profession_view=null
                  com a flag OFF → nada; identidade tocável → Guilda dos
                  Ofícios; sem chip novo no header — lição PlayerHeader). */}
              {player.profession_view && (
                <div onClick={onOpenProfession || undefined}
                     style={{ fontSize:11, color:"rgba(var(--gold2-rgb),.85)", marginTop:6,
                              paddingLeft:3, cursor: onOpenProfession ? "pointer" : "default" }}>
                  {player.profession_view.key
                    ? `${player.profession_view.emoji} ${player.profession_view.name} · ${player.profession_view.tier_name}`
                    : `🏮 ${safeT("prf_mini_card_cta")}`}
                  {onOpenProfession ? " ›" : ""}
                </div>
              )}
            </div>

            {/* ── Stats compact */}
            <div>
              <div style={{
                fontSize:10.5, color:"var(--gold3)",
                fontFamily:"'Cinzel',serif", letterSpacing:1.1,
                textTransform:"uppercase", marginBottom:7, paddingLeft:3,
              }}>
                {safeT("profile_stats_section_title")}
              </div>
              <StatGrid stats={stats} />
              {/* QoL-Feedback 03/08 (report [jogador]) — a Fundação é PERMANENTE e
                  multiplica bp/alma/sorte/percepção + a velocidade de cultivo
                  (core/game_logic.py `stat_mult`), mas NENHUMA tela do mini a
                  mostrava: o jogador usava a Pílula da Fundação Eterna e não via
                  estado nenhum mudar. Paridade com o `status_foundation` do chat.
                  O ×mult vem do servidor (Lei §9 — o mini nunca recalcula) e é
                  condicional: sem fundação estabelecida, a linha não existe. */}
              {player.foundation_quality && (
                <div style={{ marginTop:9, display:"flex", justifyContent:"space-between",
                               alignItems:"baseline", paddingLeft:3, paddingRight:3 }}>
                  <span style={{ fontSize:11, color:"var(--gold3)",
                                  fontFamily:"'Cinzel',serif", letterSpacing:.5 }}>
                    🏯 {safeT("profile_foundation_label")}
                  </span>
                  <span style={{ fontSize:11, color:"rgba(var(--text2-rgb),.92)",
                                  fontVariantNumeric:"tabular-nums" }}>
                    {safeT("foundation_quality_" + player.foundation_quality, null,
                           player.foundation_quality)}
                    {player.foundation_mult != null
                      ? ` (×${Number(player.foundation_mult).toFixed(2)})` : ""}
                  </span>
                </div>
              )}
              {/* Onda B (A Alma do Cultivador) — Vitalidade bar. The owner asked to
                  SEE HP in the profile; player.max_hp now comes from the Alma (==
                  the arena when combate_unificado is ON; raw otherwise). Defensive:
                  only render when the payload carries a positive max_hp so old
                  cached clients (no max_hp field) simply skip it — never throws. */}
              {(typeof player.max_hp === "number" && player.max_hp > 0) && (() => {
                const _mx = player.max_hp;
                const _cur = (player.current_hp == null)
                  ? _mx : Math.max(0, Math.min(player.current_hp, _mx));
                const _pct = Math.round(_mx > 0 ? (_cur / _mx) * 100 : 100);
                return (
                  <div style={{ marginTop:9 }}>
                    <div style={{ display:"flex", justifyContent:"space-between",
                                   alignItems:"baseline", marginBottom:4,
                                   paddingLeft:3, paddingRight:3 }}>
                      <span style={{ fontSize:11, color:"var(--gold3)",
                                      fontFamily:"'Cinzel',serif", letterSpacing:.5 }}>
                        ❤️ {safeT("combat_stat_hp")}
                      </span>
                      <span style={{ fontSize:11, color:"rgba(var(--text2-rgb),.92)",
                                      fontVariantNumeric:"tabular-nums" }}>
                        {fmtNum(_cur)} / {fmtNum(_mx)} ({_pct}%)
                      </span>
                    </div>
                    <div style={{ height:7, borderRadius:5, background:"rgba(0,0,0,.4)",
                                   border:"1px solid rgba(var(--gold2-rgb),.18)", overflow:"hidden" }}>
                      <div style={{
                        width:`${Math.max(0, Math.min(100, _pct))}%`, height:"100%",
                        background:"linear-gradient(90deg,#e0574f,#ff8a7a)",
                        borderRadius:5, transition:"width .3s",
                      }} />
                    </div>
                  </div>
                );
              })()}
            </div>

            {/* ── Achievements preview — 3 most recent unlocked */}
            <div>
              <div style={{
                display:"flex", justifyContent:"space-between", alignItems:"center",
                marginBottom:7, paddingLeft:3, paddingRight:3,
              }}>
                <div style={{
                  fontSize:10.5, color:"var(--gold3)",
                  fontFamily:"'Cinzel',serif", letterSpacing:1.1,
                  textTransform:"uppercase",
                }}>
                  {safeT("profile_achievements_section_title")}
                </div>
                <div style={{ fontSize:10, color:"var(--muted)" }}>
                  {unlockedCount}/{totalCount}
                </div>
              </div>
              {ach.loading && !ach.data ? <ListSkeleton rows={2} />
              : recentUnlocked.length === 0 ? (
                <Card style={{ padding:"10px 12px",
                                background:"rgba(0,0,0,.25)",
                                borderColor:"rgba(var(--gold2-rgb),.18)" }}>
                  <div style={{ fontSize:11, color:"var(--muted)",
                                 fontStyle:"italic", textAlign:"center" }}>
                    {safeT("profile_achievements_empty")}
                  </div>
                </Card>
              ) : (
                <div style={{ display:"grid", gap:5 }}>
                  {recentUnlocked.map((it) => (
                    <div key={it.id} style={{
                      display:"flex", alignItems:"center", gap:9,
                      padding:"7px 10px", borderRadius:6,
                      background:"rgba(var(--gold2-rgb),.08)",
                      border:"1px solid rgba(var(--gold2-rgb),.22)",
                    }}>
                      <span style={{ fontSize:17, lineHeight:1, flexShrink:0 }}>{it.emoji}</span>
                      <div style={{ flex:1, minWidth:0 }}>
                        <div style={{ fontSize:11.5, color:"var(--gold2)",
                                       fontFamily:"'Cinzel',serif", letterSpacing:.4,
                                       overflow:"hidden", textOverflow:"ellipsis",
                                       whiteSpace:"nowrap" }}>
                          {it.name}
                        </div>
                        {it.title_granted && (
                          <div style={{ fontSize:9.5, color:"var(--muted)", marginTop:1,
                                         overflow:"hidden", textOverflow:"ellipsis",
                                         whiteSpace:"nowrap" }}>
                            {t("title_prefix")} {it.title_granted}
                          </div>
                        )}
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>

            {/* ── CTA: Open Cultivation shortcut */}
            <ActionBtn variant="primary" onClick={() => {
              if (setTab) setTab("cultivation");
              onClose && onClose();
            }}>
              ☯️ {safeT("profile_open_cultivation_btn")}
            </ActionBtn>
          </div>
        </Modal>
      );
    }

    // ─── Sect: create/join wizard for non-members ───────────────────────────
    function SectCreateOrJoin({ onDone }) {
      const [mode, setMode] = useState("browse"); // "create" | "browse"
      return (
        <div>
          <Card>
            <div style={{ textAlign:"center", padding:"12px 0 6px" }}>
              <div style={{ fontSize:42 }}>🏯</div>
              <div style={{ fontFamily:"'Cinzel',serif", fontSize:14, color:"var(--gold2)", marginTop:8, letterSpacing:.6 }}>
                {t("sect_none_title")}
              </div>
              <div style={{ fontSize:11.5, color:"var(--muted)", marginTop:6, lineHeight:1.5 }}>
                {t("sect_none_hint")}
              </div>
            </div>
            <SegControl value={mode} onChange={setMode} options={[
              { value:"browse", label: t("sect_browse_tab") },
              { value:"create", label: t("sect_create_tab") },
            ]} />
          </Card>
          {mode === "browse" ? <SectBrowsePanel onJoined={onDone} /> : <SectCreatePanel onCreated={onDone} />}
        </div>
      );
    }

    function SectCreatePanel({ onCreated }) {
      const [name, setName] = useState("");
      const [desc, setDesc] = useState("");
      const [busy, setBusy] = useState(false);
      const [err, setErr] = useState(null);
      const trimmed = name.trim();
      const valid = trimmed.length >= 3 && trimmed.length <= 32;
      async function submit() {
        if (busy || !valid) return;
        setBusy(true); setErr(null); haptic("warning");
        try {
          const res = await api("sect/create", { name: trimmed, description: desc.trim() || null });
          if (!res.ok) {
            haptic("error");
            setErr(t(`sect_err_${res.reason || "engine"}`, res) || res.reason);
            setBusy(false);
            return;
          }
          haptic("success");
          showToast(t("sect_create_done", { name: res.name }));
          setBusy(false);
          onCreated && onCreated();
        } catch (e) { haptic("error"); setErr(t("sect_err_engine")); setBusy(false); }
      }
      return (
        <Card>
          <CardTitle left={t("sect_create_title")} right="🪨 10K" />
          <div style={{ fontSize:11, color:"var(--muted)", marginBottom:8, lineHeight:1.5 }}>
            {t("sect_create_hint")}
          </div>
          <input type="text" placeholder={t("sect_create_name_placeholder")} value={name}
            maxLength={32}
            onChange={(e) => setName(e.target.value)}
            style={{
              width:"100%", padding:"10px 12px", borderRadius:8, marginBottom:6,
              background:"rgba(0,0,0,.4)", border:"1px solid rgba(var(--gold2-rgb),.4)",
              color:"var(--text)", fontSize:13, outline:"none",
            }} />
          <textarea placeholder={t("sect_create_desc_placeholder")} value={desc}
            maxLength={200} rows={2}
            onChange={(e) => setDesc(e.target.value)}
            style={{
              width:"100%", padding:"10px 12px", borderRadius:8, marginBottom:8,
              background:"rgba(0,0,0,.4)", border:"1px solid rgba(var(--glow-rgb),.3)",
              color:"var(--text)", fontSize:12, outline:"none", resize:"vertical",
              fontFamily:"inherit",
            }} />
          {err && <ErrBanner msg={err} />}
          <ActionBtn variant="primary" disabled={busy || !valid} onClick={submit}>
            {busy ? <DotSpinner /> : `🏯 ${t("sect_create_submit")}`}
          </ActionBtn>
        </Card>
      );
    }

    function SectBrowsePanel({ onJoined }) {
      const [page, setPage] = useState(0);
      const [reload, setReload] = useState(0);
      const { data, loading, error } = useApi("sect/list", { page }, [page, reload]);
      const [joiningId, setJoiningId] = useState(null);
      const [err, setErr] = useState(null);
      async function join(sect_id, name) {
        if (joiningId) return;
        setJoiningId(sect_id); setErr(null); haptic("warning");
        try {
          const res = await api("sect/join", { sect_id });
          if (!res.ok) {
            haptic("error");
            setErr(t(`sect_err_${res.reason || "engine"}`, res) || res.reason);
            setJoiningId(null);
            setReload(x => x + 1);
            return;
          }
          haptic("success");
          showToast(t("sect_join_done", { name: res.name }));
          setJoiningId(null);
          onJoined && onJoined();
        } catch (e) { haptic("error"); setErr(t("sect_err_engine")); setJoiningId(null); }
      }
      return (
        <Card>
          <CardTitle left={t("sect_browse_title")} right={data ? `${data.total}` : "…"} />
          {loading ? <ListSkeleton rows={6} />
          : error ? <ErrBanner msg={error} />
          : (data?.sects || []).length === 0 ? (
            <div style={{ fontSize:12, color:"var(--muted)", textAlign:"center", padding:"16px 0" }}>
              {t("sect_browse_empty")}
            </div>
          ) : (
            <>
              {err && <ErrBanner msg={err} />}
              {data.sects.map((s) => (
                <div key={s.id} style={{
                  display:"flex", alignItems:"center", gap:8, padding:"8px 10px", marginBottom:5,
                  background:"rgba(0,0,0,.25)", border:"1px solid rgba(var(--glow-rgb),.18)", borderRadius:8,
                }}>
                  <div style={{ fontSize:20 }}>🏯</div>
                  <div style={{ flex:1, minWidth:0 }}>
                    <div style={{ fontSize:12.5, color:"var(--gold2)", fontFamily:"'Cinzel',serif" }}>{s.name}</div>
                    <div style={{ fontSize:10, color:"var(--muted)" }}>
                      {s.member_count}/{s.max_members} {t("lb_members_short")}
                    </div>
                    {/* v14.13d (2026-05-25) — Owner P3: 40char inline truncation
                        "lê estranho". Moved to its own line with 2-line clamp
                        so the meta row stays clean and the description gets
                        enough horizontal real estate to read naturally. */}
                    {s.description && (
                      <div style={{
                        fontSize:10.5, color:"var(--muted)", marginTop:2,
                        lineHeight:1.4, fontStyle:"italic",
                        display:"-webkit-box", WebkitLineClamp:2,
                        WebkitBoxOrient:"vertical", overflow:"hidden",
                      }}>
                        {s.description}
                      </div>
                    )}
                  </div>
                  <button onClick={() => join(s.id, s.name)} disabled={s.is_full || joiningId === s.id} style={{
                    padding:"6px 12px", borderRadius:6, cursor: (s.is_full || joiningId === s.id) ? "default" : "pointer",
                    background: s.is_full ? "rgba(0,0,0,.3)" : "rgba(var(--jade-rgb),.12)",
                    border:`1px solid ${s.is_full ? "rgba(var(--glow-rgb),.2)" : "rgba(var(--jade-rgb),.42)"}`,
                    color: s.is_full ? "var(--muted2)" : "var(--jade)",
                    fontFamily:"'Cinzel',serif", fontSize:11, fontWeight:600,
                  }}>
                    {joiningId === s.id ? "…" : (s.is_full ? t("sect_browse_full") : t("sect_browse_join"))}
                  </button>
                </div>
              ))}
              {(data.has_more || page > 0) && (
                <div style={{ display:"flex", justifyContent:"space-between", marginTop:8 }}>
                  <button onClick={() => setPage(p => Math.max(0, p - 1))} disabled={page === 0}
                    style={{
                      padding:"6px 12px", borderRadius:6, fontSize:11,
                      background:"rgba(0,0,0,.3)", border:"1px solid rgba(var(--glow-rgb),.2)",
                      color: page === 0 ? "var(--muted2)" : "var(--text)",
                      cursor: page === 0 ? "default" : "pointer",
                    }}>← {t("btn_prev")}</button>
                  <span style={{ fontSize:11, color:"var(--muted)", alignSelf:"center" }}>
                    {page + 1}
                  </span>
                  <button onClick={() => setPage(p => p + 1)} disabled={!data.has_more}
                    style={{
                      padding:"6px 12px", borderRadius:6, fontSize:11,
                      background:"rgba(0,0,0,.3)", border:"1px solid rgba(var(--glow-rgb),.2)",
                      color: !data.has_more ? "var(--muted2)" : "var(--text)",
                      cursor: !data.has_more ? "default" : "pointer",
                    }}>{t("btn_next")} →</button>
                </div>
              )}
            </>
          )}
        </Card>
      );
    }

    // ─── Generic modal shell (centered, scrollable, ornate) ─────────────────
    // MA-MODAL (2026-05-10): now a thin wrapper over the canonical <Modal>
    // primitive in ui.js. Preserves the original API so the 4+ sect modals
    // (donate/leave/member action/shop) inherit sticky chrome + scroll lock
    // for free, with zero call-site changes. Old layout was bespoke
    // (alch-pop animation, single-pane card) — kept that animation here as
    // an opt-in via `pop` prop for callers that want the celebratory feel.
    function ModalShell({ onClose, title, accent, maxWidth, children, footer, pop, zIndex }) {
      return (
        <Modal
          onClose={onClose}
          title={title}
          accent={accent}
          maxWidth={maxWidth || 380}
          zIndex={zIndex || 65}
          footer={footer}
          animation={pop ? "alch-pop 320ms cubic-bezier(.2,1.4,.4,1)" : undefined}
        >
          {children}
        </Modal>
      );
    }

    // ─── Leaderboard Tab ─────────────────────────────────────────────────────
    function LeaderboardTab({ onOpenWhispers, onOpenNpc, onProposeTrade }) {
      const [type, setType] = useState("cultivation");
      const { data, loading, error } = useApi("leaderboard", { type }, [type]);
      // MA-32b — clicking a player row opens a profile card. Lookup key is
      // dao_name (already public on this surface). Sect rows are NOT
      // clickable (no profile concept for sects yet).
      const [profileTarget, setProfileTarget] = useState(null);
      // R6 §4.1 — the ladder arrives as one 50-row wall ("at limit" since the
      // redesign audit). Page it client-side: the server payload is untouched
      // (rank/order preserved), only the card renders 15 at a time.
      const PAGE_SIZE = 15;
      const [page, setPage] = useState(0);
      const opts = [
        { value:"cultivation", label: t("lb_cultivation") },
        { value:"power",       label: t("lb_power") },
        { value:"sects",       label: t("lb_sects") },
      ];
      // Some legacy beta players have null dao_name → leaderboard renders
      // them as "Cultivator". The profile lookup is keyed by dao_name so we
      // can't open a profile for those — disable the click on placeholder
      // names rather than 404 every time.
      const openable = (entryName) => entryName && entryName !== "Cultivator";
      const entries = (!loading && !error && data) ? (data.entries || []) : [];
      const totalPages = Math.max(1, Math.ceil(entries.length / PAGE_SIZE));
      const safePage = Math.min(page, totalPages - 1);
      const view = entries.slice(safePage * PAGE_SIZE, safePage * PAGE_SIZE + PAGE_SIZE);
      return (
        <div>
          {/* Onda 3 — Heaven's Whispers entry (the world breathing). */}
          {onOpenWhispers && (
            <div style={{ display:"flex", justifyContent:"flex-end", marginBottom:8 }}>
              <ActionBtn variant="ghost" onClick={() => onOpenWhispers()} style={{ fontSize:11.5, padding:"6px 12px" }}>
                🌌 {t("wsp_feed_title")}
              </ActionBtn>
            </div>
          )}
          <SegControl value={type} onChange={(v) => { setType(v); setPage(0); }} options={opts} />
          {loading ? <ListSkeleton rows={10} /> : error ? <ErrBanner msg={error} /> : (
            <Card>
              {entries.length === 0 ? (
                <div style={{ textAlign:"center", padding:"24px 0", color:"var(--muted)", fontSize:12 }}>—</div>
              ) : type === "sects" ? view.map((e, i) => (
                <LeaderRow key={i} rank={e.rank}
                  name={`🏯 ${e.name}`}
                  meta={`${e.members} ${t("lb_members_short")} · 🪨${fmtNum(e.spirit_stones)}`}
                />
              )) : view.map((e, i) => (
                <LeaderRow key={i} rank={e.rank}
                  name={
                    <span>
                      {e.name}
                      {/* Onda 3 — honest NPC chip (Lei §1): never disguised as a real player. */}
                      {e.is_npc && <span style={{ marginLeft:6 }}><Badge variant="warn">🤖 {t("lb_npc_chip")}</Badge></span>}
                      {e.prestige > 0 && <span style={{ marginLeft:6 }}><Badge variant="jade">P{e.prestige}</Badge></span>}
                    </span>
                  }
                  meta={`${e.realm_emoji}${e.sub_layer || ""} · ${type === "power" ? `⚔️ ${fmtNum(e.battle_power)}` : (e.is_npc ? "☯️ —" : `☯️ ${fmtNum(e.cultivation_base)}`)}`}
                  onClick={
                    e.is_npc
                      ? () => onOpenNpc && onOpenNpc(e)
                      : (openable(e.name) ? () => setProfileTarget(e.name) : undefined)
                  }
                />
              ))}
              {entries.length > PAGE_SIZE && (
                <div style={{ display:"flex", justifyContent:"space-between", marginTop:8 }}>
                  <button onClick={() => { haptic("select"); setPage(Math.max(0, safePage - 1)); }} disabled={safePage === 0}
                    style={{
                      padding:"6px 12px", borderRadius:6, fontSize:11,
                      background:"rgba(0,0,0,.3)", border:"1px solid rgba(var(--glow-rgb),.2)",
                      color: safePage === 0 ? "var(--muted2)" : "var(--text)",
                      cursor: safePage === 0 ? "default" : "pointer",
                    }}>← {t("btn_prev")}</button>
                  <span style={{ fontSize:11, color:"var(--muted)", alignSelf:"center" }}>
                    {safePage + 1}/{totalPages}
                  </span>
                  <button onClick={() => { haptic("select"); setPage(Math.min(totalPages - 1, safePage + 1)); }} disabled={safePage >= totalPages - 1}
                    style={{
                      padding:"6px 12px", borderRadius:6, fontSize:11,
                      background:"rgba(0,0,0,.3)", border:"1px solid rgba(var(--glow-rgb),.2)",
                      color: safePage >= totalPages - 1 ? "var(--muted2)" : "var(--text)",
                      cursor: safePage >= totalPages - 1 ? "default" : "pointer",
                    }}>{t("btn_next")} →</button>
                </div>
              )}
            </Card>
          )}
          {profileTarget && (
            <ProfileCardModal target={profileTarget} onClose={() => setProfileTarget(null)}
                              onProposeTrade={onProposeTrade} />
          )}
        </div>
      );
    }

    // ─── ProfileCardModal (MA-32b) ──────────────────────────────────────────
    // Public profile shown when tapping a player on the Ranking. Looked up
    // server-side by dao_name (already public on the leaderboard surface);
    // the server filters shadow_mode players with a 404 indistinguishable
    // from "not found", so privacy preferences leak nothing.
    function ProfileCardModal({ target, onClose, onProposeTrade }) {
      const { data, loading, error } = useApi("profile", { target_dao_name: target }, [target]);
      const isShadowOrNotFound = error === "not_found";
      // MA-39a — "Propor Troca" CTA. Rendered as a card inside the modal (never
      // a header chip — memory feedback-player-header-cluttered). Only real
      // players reach ProfileCardModal (NPCs route to NpcCultivatorModal), so
      // the target is always tradeable; self-trade is rejected server-side and
      // surfaced inline here.
      const [ctaErr, setCtaErr] = useState(null);
      const [ctaBusy, setCtaBusy] = useState(false);

      // R5: hex literal — o ProfileCardBody concatena alpha no glow do orbe
      // (`${cssHex(rc)}88`); com var() a declaração inteira morria silenciosa.
      const realmRing = (realmIdx) => realmHex(Math.max(realmIdx || 0, 0));

      // MA-MODAL — owner reported (2026-05-10): "se baixar pode ver o fundo
      // etc". The original ProfileCardModal scrolled the whole card; on tall
      // content the LeaderboardTab page underneath was visible behind it.
      // Wrapping in <Modal> pulls in body scroll lock + sticky header
      // (close ✕ stays visible mid-scroll) without changing the rich body.
      const titleNode = data ? (
        <span style={{
          fontFamily:"'Cinzel',serif", fontSize:13.5, fontWeight:700,
          background:"linear-gradient(90deg,var(--gold3),var(--gold2),var(--gold))",
          WebkitBackgroundClip:"text", backgroundClip:"text", WebkitTextFillColor:"transparent",
          letterSpacing:.4,
          overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap",
        }}>{data.dao_name}</span>
      ) : t("profile_loading");

      return (
        <Modal
          onClose={onClose}
          title={titleNode}
          accent="rgba(var(--gold2-rgb),.42)"
          maxWidth={420}
          zIndex={70}
          cardStyle={{
            background:"linear-gradient(165deg,rgba(var(--surface-rgb),.97) 0%,rgba(var(--surface2-rgb),.98) 100%)",
            boxShadow:"0 24px 64px rgba(0,0,0,.55), inset 0 1px 0 rgba(var(--gold2-rgb),.18)",
          }}
          animation="alch-pop .35s cubic-bezier(.34,1.56,.64,1)"
        >
          {loading ? (
            <div style={{ textAlign:"center", padding:"30px 12px", color:"var(--muted)", fontSize:12 }}>
              <div style={{ marginBottom:10 }}><DotSpinner /></div>
              {t("profile_loading")}
            </div>
          ) : isShadowOrNotFound ? (
            <div style={{ textAlign:"center", padding:"30px 18px" }}>
              <div style={{ fontSize:42, marginBottom:10 }}>🌫️</div>
              <div style={{ fontFamily:"'Cinzel',serif", fontSize:14, color:"var(--gold2)", marginBottom:6 }}>
                {t("profile_not_found_title")}
              </div>
              <div style={{ fontSize:11, color:"var(--muted)", lineHeight:1.6 }}>
                {t("profile_shadow_hint")}
              </div>
            </div>
          ) : error ? (
            <ErrBanner msg={error} />
          ) : data ? (
            <>
              <ProfileCardBody data={data} realmRing={realmRing} />
              {onProposeTrade && (
                <div style={{ marginTop:12 }}>
                  {ctaErr && <div className="err-banner" style={{ marginTop:0, marginBottom:8 }}>⚠️ {ctaErr}</div>}
                  <ActionBtn variant="primary" disabled={ctaBusy} style={{ width:"100%" }}
                             onClick={async () => {
                               setCtaErr(null); setCtaBusy(true);
                               try {
                                 const r = await onProposeTrade(data.dao_name);
                                 if (r && r.ok) { onClose(); }
                                 else { setCtaErr(tradeReason(r && r.reason)); }
                               } finally { setCtaBusy(false); }
                             }}>
                    {t("trade_cta_propose")}
                  </ActionBtn>
                </div>
              )}
            </>
          ) : null}
        </Modal>
      );
    }

    function ProfileCardBody({ data, realmRing }) {
      const rc = realmRing(data.realm);
      const equippedBySlot = Object.fromEntries((data.equipped || []).map(a => [a.slot, a]));
      const SLOT_ORDER = ["weapon", "armor", "accessory1", "accessory2"];
      // R6 §4.2 — progressive disclosure: identity + power triad answer the
      // "who is this?" tap; the equipment grid is drill-down, so it starts
      // collapsed behind its own header (count keeps the closed state honest).
      const [showEquip, setShowEquip] = useState(false);
      const equippedCount = (data.equipped || []).length;
      return (
        <div>
          {/* Header — dao_name with realm orb badge */}
          <div style={{ display:"flex", alignItems:"center", gap:14, marginBottom:14, marginTop:6 }}>
            {/* 坐 2026-09-13 — o SEGUNDO orbe escrito à mão, e o mais absurdo
                dos dois: o herói do hub EU era uma esfera de gradiente com um
                emoji do sistema, e tocá-la abria ESTE modal, que mostrava outra
                esfera de gradiente com o MESMO emoji. Dois donos à mão para a
                mesma ideia — a família F-7 inteira numa só interacção.
                `RealmAvatar` é o dono desde 09/09. */}
            <div style={{ flexShrink:0, animation:"orb-breathe 3.6s ease-in-out infinite" }}>
              <RealmAvatar realm={data.realm} size={64}
                           style={{ boxShadow:`0 0 18px ${cssHex(rc)}55` }} />
            </div>
            <div style={{ minWidth:0, flex:1 }}>
              <div style={{
                fontFamily:"'Cinzel',serif", fontSize:20, fontWeight:700, letterSpacing:.5,
                background:"linear-gradient(90deg,var(--gold3),var(--gold2),var(--gold),var(--gold2),var(--gold3))",
                backgroundSize:"200% 100%",
                WebkitBackgroundClip:"text", backgroundClip:"text", WebkitTextFillColor:"transparent",
                animation:"shimmer 3.5s linear infinite",
                whiteSpace:"nowrap", overflow:"hidden", textOverflow:"ellipsis",
              }}>{data.dao_name}</div>
              <div style={{
                fontFamily:"'Cinzel',serif", fontSize:11, color:rc,
                letterSpacing:.4, marginTop:2,
              }}>
                {data.realm_name} · {t("profile_sub_layer", { n: data.sub_layer })}
                {data.prestige_level > 0 && (
                  <span style={{ marginLeft:6, color:"var(--gold3)" }}>· P{data.prestige_level}</span>
                )}
              </div>
            </div>
          </div>

          {/* Chip strip — sect / title */}
          {(data.sect || data.active_title) && (
            <div style={{ display:"flex", flexWrap:"wrap", gap:6, marginBottom:14 }}>
              {data.sect ? (
                <span style={{
                  display:"inline-flex", alignItems:"center", gap:5,
                  padding:"5px 10px", borderRadius:99,
                  background:"rgba(var(--gold2-rgb),.08)",
                  border:"1px solid rgba(var(--gold2-rgb),.32)",
                  fontSize:11, color:"var(--gold2)", fontFamily:"'Cinzel',serif",
                }}>🏯 {data.sect.name}
                  <span style={{ color:"var(--muted)", fontSize:10, marginLeft:2 }}>· {t("profile_role_" + data.sect.role)}</span>
                </span>
              ) : (
                <span style={{
                  padding:"5px 10px", borderRadius:99,
                  background:"rgba(var(--muted-rgb),.06)",
                  border:"1px dashed rgba(var(--muted-rgb),.3)",
                  fontSize:11, color:"var(--muted)", fontFamily:"'Cinzel',serif",
                }}>{t("profile_no_sect")}</span>
              )}
              {data.active_title && (
                <span style={{
                  display:"inline-flex", alignItems:"center", gap:4,
                  padding:"5px 10px", borderRadius:99,
                  background:"rgba(var(--realm-3-rgb),.08)",
                  border:"1px solid rgba(var(--realm-3-rgb),.35)",
                  fontSize:11, color:"#d8b4fe", fontFamily:"'Cinzel',serif",
                }}>👑 {data.active_title}</span>
              )}
            </div>
          )}

          {/* Stat grid — 3 cols */}
          <div style={{ display:"grid", gridTemplateColumns:"repeat(3,1fr)", gap:6, marginBottom:14 }}>
            {/* R5: accents em hex literal — o ProfileStat concatena alpha
                (borda + textShadow); com var() as declarações morriam. */}
            <ProfileStat icon="⚔️" label_key="profile_battle_power" value={fmtNum(data.battle_power)} accent="var(--red)" />
            <ProfileStat icon="☯️" label_key="profile_cultivation" value={fmtNum(Math.round(data.cultivation_base))} accent={rc} />
            <ProfileStat icon="🛡️" label_key="profile_body_temper" value={String(data.body_tempering_level)} accent="var(--gold2)" />
          </div>

          {/* Equipped grid 4 slots — collapsed by default (R6 §4.2) */}
          <div style={{
            background:"rgba(0,0,0,.25)", borderRadius:8, padding:"10px 10px 8px",
            border:"1px solid rgba(var(--gold2-rgb),.18)", marginBottom:12,
          }}>
            <button onClick={() => { haptic("select"); setShowEquip(v => !v); }}
              style={{
                width:"100%", textAlign:"left", padding:0,
                background:"transparent", border:"none", cursor:"pointer",
                display:"flex", justifyContent:"space-between", alignItems:"center",
              }}>
              <span style={{
                fontSize:9, color:"var(--muted)", letterSpacing:.6, textTransform:"uppercase",
                fontFamily:"'Cinzel',serif",
              }}>{t("profile_equipped")} · {equippedCount}/4</span>
              <span style={{ fontSize:12, color:"var(--muted)", lineHeight:1 }}>{showEquip ? "−" : "+"}</span>
            </button>
            {showEquip && (
            <div style={{ display:"grid", gridTemplateColumns:"repeat(4,1fr)", gap:6, marginTop:8 }}>
              {SLOT_ORDER.map(s => {
                const a = equippedBySlot[s];
                if (a) {
                  const v = GRADE_VISUALS[a.grade] || GRADE_VISUALS[0];
                  return (
                    <div key={s} style={{
                      aspectRatio:1, background: v.bg, position:"relative",
                      border:`1px solid ${cssHex(v.color)}66`, borderRadius:8,
                      display:"grid", placeItems:"center",
                      boxShadow: v.shine ? v.shine : `0 0 8px ${v.glow}`,
                    }}>
                      {itemVivoOn()
                        ? <PieceIcon kind="artifact" name={a.name} artKey={a.art_key} emoji={a.emoji}
                                     size={38} accent={v.color} radius={7} />
                        : <span style={{ fontSize:24, filter:`drop-shadow(0 0 3px ${v.color})` }}>{a.emoji}</span>}
                      <span style={{
                        position:"absolute", bottom:2, right:3,
                        fontFamily:"'Cinzel',serif", fontSize:9, fontWeight:700,
                        color: v.color, textShadow:"0 0 4px rgba(0,0,0,.8)",
                      }}>G{a.grade}</span>
                      {a.has_spirit && (
                        <span style={{
                          position:"absolute", top:2, left:3, fontSize:10,
                          filter:"drop-shadow(0 0 4px rgba(var(--gold2-rgb),.8))",
                        }}>✨</span>
                      )}
                    </div>
                  );
                }
                return (
                  <div key={s} style={{
                    aspectRatio:1, background:"rgba(0,0,0,.3)",
                    border:"1px dashed rgba(var(--glow-rgb),.3)", borderRadius:8,
                    display:"grid", placeItems:"center", opacity:.4,
                  }}>
                    <span style={{ fontSize:18, opacity:.5, display:markOn(SLOT_MARKS[s]) ? "grid" : undefined,
                                   placeItems:markOn(SLOT_MARKS[s]) ? "center" : undefined }}>{slotIco(s, null, 20)}</span>
                  </div>
                );
              })}
            </div>
            )}
            {showEquip && equippedCount === 0 && (
              <div style={{ textAlign:"center", marginTop:8, fontSize:10.5, color:"var(--muted2)", fontFamily:"'Cinzel',serif" }}>
                {t("profile_no_equipped")}
              </div>
            )}
          </div>

          {/* Footer — joined / last seen (relative) */}
          <div style={{
            display:"flex", justifyContent:"space-between",
            fontSize:10, color:"var(--muted2)", letterSpacing:.4,
            paddingTop:6, borderTop:"1px solid rgba(var(--gold2-rgb),.12)",
          }}>
            <span>📜 {t("profile_joined", { ago: timeAgo(data.joined_at_ms) })}</span>
            <span>🌙 {t("profile_last_seen", { ago: timeAgo(data.last_online_ms) })}</span>
          </div>
        </div>
      );
    }

    function ProfileStat({ icon, label_key, value, accent }) {
      return (
        <div style={{
          textAlign:"center", padding:"8px 4px",
          background:"rgba(0,0,0,.3)", borderRadius:8,
          border:`1px solid ${cssHex(accent)}33`,
        }}>
          <div style={{ fontSize:9, color:"var(--muted)", letterSpacing:.6, textTransform:"uppercase", fontFamily:"'Cinzel',serif" }}>
            {icon} {t(label_key)}
          </div>
          <div style={{
            fontFamily:"'Cinzel',serif", fontSize:15, fontWeight:700, color: accent,
            marginTop:3, textShadow:`0 0 8px ${cssHex(accent)}66`,
          }}>{value}</div>
        </div>
      );
    }

    // ─── Inventory Tab ───────────────────────────────────────────────────────
    // Per-grade visual identity. The numeric index is the grade column on
    // ArtifactCatalog (0..8). Each grade gets:
    //   - color:   tier accent (border, label, glow tint)
    //   - glow:    rgba shadow used in the modal header for "this is special"
    //   - bg:      subtle gradient for the card backdrop
    // Mortal..Yellow stays muted; Earth..Heaven warms; Spirit..Divine glows
    // gold; Dao..Celestial bursts pink/red so a Celestial drop *reads* as
    // legendary at a glance, even before art exists.
    // 🎒 3.2 — o NOME do grau de um artefacto, na língua do jogador. ⚠️ O
    // servidor manda `grade_name` do `config.ARTIFACT_GRADES`, em INGLÊS, e 4
    // sítios desenhavam-no cru ("G6 · DIVINE" no detalhe, na oficina e no
    // mercado). A carta da grelha já dizia "Céu" — pela `art_grade_<n>`, que
    // existe nas três línguas. Um dono, e o cru só se a chave faltar.
    function nomeDoGrau(g, cru) {
      const k = "art_grade_" + (Number(g) || 0);
      const v = t(k);
      return v && v !== k ? v : (cru || ("G" + (Number(g) || 0)));
    }

    var GRADE_VISUALS = [
      { color:"var(--realm-0)", glow:"rgba(var(--realm-0-rgb),.0)",  bg:"linear-gradient(180deg,rgba(40,50,70,.6),rgba(var(--surface-rgb),.85))",   shine:"" },
      { color:"var(--gold3)", glow:"rgba(var(--gold3-rgb),.18)", bg:"linear-gradient(180deg,rgba(70,60,30,.45),rgba(25,22,15,.85))",  shine:"" },
      { color:"var(--realm-3)", glow:"rgba(var(--realm-3-rgb),.28)",  bg:"linear-gradient(180deg,rgba(60,30,90,.55),rgba(25,15,40,.85))",  shine:"" },
      { color:"#92400e", glow:"rgba(146,64,14,.28)",   bg:"linear-gradient(180deg,rgba(70,40,15,.55),rgba(30,18,8,.85))",   shine:"" },
      { color:"var(--realm-1)", glow:"rgba(var(--realm-1-rgb),.32)",  bg:"linear-gradient(180deg,rgba(30,55,110,.6),rgba(15,25,55,.9))",   shine:"" },
      { color:"#22d3ee", glow:"rgba(34,211,238,.36)",  bg:"linear-gradient(180deg,rgba(15,90,110,.55),rgba(8,30,40,.9))",   shine:"" },
      { color:"var(--gold2)", glow:"rgba(var(--gold2-rgb),.45)", bg:"linear-gradient(180deg,rgba(110,80,30,.6),rgba(30,22,10,.9))",   shine:"inset 0 0 14px rgba(var(--gold2-rgb),.25)" },
      { color:"var(--realm-10)", glow:"rgba(var(--realm-10-rgb),.5)",  bg:"linear-gradient(180deg,rgba(110,40,90,.55),rgba(40,15,40,.9))",  shine:"inset 0 0 16px rgba(var(--realm-10-rgb),.28)" },
      { color:"#fb7185", glow:"rgba(251,113,133,.55)", bg:"linear-gradient(180deg,rgba(120,30,40,.6),rgba(40,12,18,.9))",   shine:"inset 0 0 18px rgba(251,113,133,.32)" },
    ];
    // Canonical icon per slot. The slot identifies what kind of gear is worn
    // here, so the silhouette reads the *type* at a glance. accessory1=ring,
    // accessory2=pendant — distinct so two equipped accessories don't look
    // identical.
    //
    // ⚠️ 2026-09-10 — ESTE COMENTÁRIO MENTIA POR ANTIGUIDADE. Dizia que o
    // jogador lia o tipo e a raridade *"sem art assets"*, e isso era verdade
    // quando foi escrito: havia **ZERO** peças de arte. Há **235** (técnica 128 ·
    // artefacto 51 · pílula 41 · besta 15), e os 51 artefactos têm TODOS
    // ilustração. O ícone do slot deixou de ser o que o jogador vê da peça e
    // passou a ser o **verso honesto** — o que fica enquanto a arte carrega, se
    // ela falhar, ou enquanto aquela família ainda não tiver arte nenhuma
    // (ervas, minérios, formações...). É um fallback, não a apresentação.
    // Um comentário desactualizado é uma decisão velha a continuar a mandar.
    var SLOT_ICONS = { weapon:"🗡️", armor:"🥋", accessory1:"💍", accessory2:"📿", mount:"🐎", cauldron:"⚗️" };
    // 印 As marcas dos slots. `mount` e' a nuvem e nao um cavalo por decisao: a
    // Lei da Adaptacao (§0.2/7 do Atlas) diz que a montaria MORTAL e' so' o
    // primeiro degrau — a escada acaba em ir de nuvem —, e um cavalo de 4 patas
    // a 18px e' uma nodoa. A `sword` e a `cauldron` sao as MESMAS do Combate e
    // da Forja: repetir a marca onde o sentido e' o mesmo e' o que faz um
    // conjunto; inventar uma segunda espada e' que seria incoerencia.
    var SLOT_MARKS = { weapon:"sword", armor:"robe", accessory1:"ring",
                       accessory2:"beads", mount:"cloud", cauldron:"cauldron" };
    // O icone do slot, ja' comutado. `fallback` e' o emoji do CATALOGO da peca
    // (conteudo, nao chrome) e por isso nunca vira marca — so' entra quando o
    // slot nao se consegue inferir.
    function slotIco(slot, fallback, size) {
      if (slot && SLOT_MARKS[slot] && markOn(SLOT_MARKS[slot])) {
        return <Mark name={SLOT_MARKS[slot]} size={size || 20} />;
      }
      return (slot && SLOT_ICONS[slot]) || fallback || "🗡️";
    }
    // Slots actually shown in the "Equipped" grid. mount/cauldron exist in
    // ARTIFACT_SLOTS but aren't equipped via this UI in the bot — mount has
    // its own handler, cauldron belongs to alchemy. Max real gear slots = 4.
    var EQUIPPABLE_SLOTS = new Set(["weapon", "armor", "accessory1", "accessory2"]);
    var EQUIPPED_MAX = 4;
    var QUALITY_COLOR = { normal:"var(--realm-0)", refined:"var(--realm-1)", superior:"var(--realm-3)", masterwork:"var(--gold2)", heavenly:"var(--realm-10)" };
    // TAPETE QoL §5 itens 1/3/4/5 ([jogador] 25.05): artifact CRAFT quality
    // ("refino" no vocabulário dele) — inferred server-side, shipped on
    // /inventory + market payloads as `quality`. Colors per the player's own
    // spec: "Perfeito Roxo, Divino Dourado e Espírito Colorido".
    // "refined" = grade raised above the catalog via refine_artifact (craft
    // quality erased, duplicates burned) — own chip, and ALWAYS above any
    // bulk-dismantle quality cut (review 2026-06-12).
    var ART_QUALITY_COLOR = { normal:"var(--realm-0)", perfect:"var(--realm-3)", divine:"var(--gold2)", spirit:"var(--realm-10)", refined:"var(--realm-1)" };
    var ART_QUALITY_KEY = { normal:"art_quality_normal", perfect:"art_quality_perfect", divine:"art_quality_divine", spirit:"art_quality_spirit", refined:"art_quality_refined" };
    // "Colorido" = animated-feel gradient text for spirit artifacts.
    var ART_SPIRIT_GRADIENT = "linear-gradient(90deg,var(--realm-10),var(--gold2),#22d3ee)";
    function artQualityChipStyle(quality, fallbackColor) {
      if (quality === "spirit") {
        return { background: ART_SPIRIT_GRADIENT, WebkitBackgroundClip:"text",
                 backgroundClip:"text", color:"transparent" };
      }
      const qc = ART_QUALITY_COLOR[quality];
      return { color: (quality && quality !== "normal" && qc) ? qc : fallbackColor };
    }

    // Slot picker for the rare case where the player tries to equip an
    // accessory but both accessory1 and accessory2 are already filled. The
    // backend returns `accessory_picker_required` and we open this modal so
    // the player picks which slot to overwrite. Mirrors the chat handler's
    // auto-pick first-empty rule but lets the player choose when both occupied.
    function EquipSlotPickerModal({ payload, incoming, onClose, onPick, busy }) {
      if (!payload) return null;
      const slots = payload.slots || [];
      // 窗 2026-09-08 — passa pelo `Overlay` (o dono único). Era a segunda das
      // duas janelas escritas à mão: sem portal, portanto sujeita ao mesmo bug
      // do iOS que escondia o topo por trás do PlayerHeader.
      return (
        <Overlay onClose={onClose} zIndex={80} background="rgba(4,6,12,.85)"
                 maxWidth={380}
                 cardStyle={{
                   background:"linear-gradient(180deg, rgba(var(--card-rgb),.98), rgba(6,9,16,1))",
                   border:"1px solid var(--gold)", borderRadius:14, padding:"14px 14px 12px",
                 }}>
          <>
            <div style={{ fontFamily:"'Cinzel',serif", fontSize:14, fontWeight:700, color:"var(--gold2)",
                          marginBottom:8, textAlign:"center" }}>
              📿 {t("inv_pick_accessory_slot")}
            </div>
            <div style={{ fontSize:11, color:"var(--muted)", marginBottom:10, textAlign:"center", lineHeight:1.4 }}>
              {t("inv_pick_accessory_hint", { name: incoming?.name || "" })}
            </div>
            <div style={{ display:"flex", flexDirection:"column", gap:8 }}>
              {slots.map(s => {
                const occ = s.occupied_by;
                const ov = occ ? (GRADE_VISUALS[occ.grade] || GRADE_VISUALS[0]) : null;
                return (
                  <button key={s.slot} disabled={busy}
                          onClick={() => onPick(s.slot)}
                          style={{
                            display:"flex", alignItems:"center", gap:10,
                            padding:"10px 12px", borderRadius:8,
                            cursor: busy ? "default" : "pointer",
                            background:"rgba(0,0,0,.3)",
                            border: ov ? `1px solid ${cssHex(ov.color)}55` : "1px solid rgba(var(--gold2-rgb),.25)",
                          }}>
                    {itemVivoOn() && occ
                      ? <PieceIcon kind="artifact" name={occ.name} artKey={occ.art_key} emoji={occ.emoji}
                                   size={34} accent={ov ? ov.color : "var(--gold)"} radius={6} />
                      : <span style={{ fontSize:22, display:markOn(SLOT_MARKS[s.slot]) ? "grid" : undefined,
                                   placeItems:markOn(SLOT_MARKS[s.slot]) ? "center" : undefined,
                                   color:markOn(SLOT_MARKS[s.slot]) ? "var(--gold2)" : undefined }}>{slotIco(s.slot, null, 22)}</span>}
                    <div style={{ flex:1, textAlign:"left", minWidth:0 }}>
                      <div style={{ fontFamily:"'Cinzel',serif", fontSize:12, color:"var(--gold2)", fontWeight:700 }}>
                        {s.slot === "accessory1" ? t("inv_slot_accessory1") : t("inv_slot_accessory2")}
                      </div>
                      <div style={{ fontSize:10.5, color:"var(--muted)", marginTop:2,
                                    overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap" }}>
                        {occ ? `${occ.emoji} ${occ.name}` : t("inv_slot_empty")}
                      </div>
                    </div>
                    <span style={{ fontSize:14, color:"var(--gold3)" }}>↻</span>
                  </button>
                );
              })}
            </div>
            <div style={{ marginTop:10 }}>
              <ActionBtn variant="ghost" onClick={onClose}>{t("alch_close")}</ActionBtn>
            </div>
          </>
        </Overlay>
      );
    }

    // Confirmation panel for irreversible dismantle.
    function DismantleConfirm({ entry, onConfirm, onCancel, busy }) {
      const v = GRADE_VISUALS[entry.grade] || GRADE_VISUALS[0];
      const ssMap = {0:50,1:150,2:500,3:1500,4:5000,5:15000,6:50000,7:200000,8:750000};
      const reward = ssMap[entry.grade] || 50;
      return (
        <div style={{
          marginTop:10, padding:"10px 12px",
          background:"rgba(var(--red-rgb),.08)", border:"1px solid rgba(var(--red-rgb),.35)",
          borderRadius:8, animation:"fadein 180ms ease",
        }}>
          <div style={{ fontSize:11, color:"var(--red2)", marginBottom:8, textAlign:"center", lineHeight:1.45 }}>
            ⚠️ {t("inv_dismantle_warn", { name: entry.name, ss: fmtNum(reward) })}
          </div>
          <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:8 }}>
            <ActionBtn variant="danger" disabled={busy} onClick={onConfirm}>
              {busy ? <DotSpinner /> : `♻️ ${t("inv_dismantle_confirm")}`}
            </ActionBtn>
            <ActionBtn variant="ghost" disabled={busy} onClick={onCancel}>
              {t("alch_close")}
            </ActionBtn>
          </div>
        </div>
      );
    }

    // Modal — backdrop click dismisses; details adapt to artifact vs item.
    // For artifacts, the footer renders Equip / Lock / Dismantle action buttons
    // wired to the MA-32 endpoints. The modal stays mounted across actions —
    // refresh is signalled via `onActionDone` so the parent re-fetches inventory.
    function DetailModal({ entry, onClose, onActionDone, player }) {
      const [busy, setBusy] = useState(false);
      const [err, setErr] = useState(null);
      const [picker, setPicker] = useState(null);  // {slots, ...} for accessory disambig
      const [confirmDismantle, setConfirmDismantle] = useState(false);
      if (!entry) return null;
      const isArtifact = entry.kind === "artifact";
      const itemOn = typeof featureEnabled === "function" && featureEnabled("item_vivo");
      // 器 o patamar DESTA peca — a mesma conta da carta, para que o modal e a
      // grelha falem uma so' lingua. Uma erva ou um minerio nao tem posto:
      // `nivRank` devolve null e o patamar cai em "comum", que e' a resposta
      // honesta (nao se ornamenta o que nao se sabe medir).
      const _itemOrn = itemOn
        ? NIV_TIER_ORN[nivTier(nivRank(
            entry.kind === "artifact" ? "artifact" : "pill",
            entry.kind === "artifact" ? entry.grade : entry.required_alchemy_tier))]
        : null;
      const v = isArtifact ? (GRADE_VISUALS[entry.grade] || GRADE_VISUALS[0]) : null;
      const headerColor = isArtifact ? v.color : (QUALITY_COLOR[entry.quality] || "var(--gold2)");
      const headerGlow = isArtifact ? v.glow : "rgba(var(--gold2-rgb),.18)";
      // v14.3 (2026-05-14): the catalog `base_stats` reads the SAME values for
      // every artifact sharing a catalog_id, so a forged G4 "Divine Cosmic Blade"
      // and a fragment-exchange G6 "Divine Cosmic Blade" looked identical even
      // though their actual `custom_stats` (base × (1 + grade*0.5)) differ. The
      // PlayerArtifact row stores the real, grade-scaled values in `custom_stats`
      // — prefer those, fall back to the catalog only if missing (older rows).
      const _shownStats = isArtifact
        ? (entry.custom_stats && Object.keys(entry.custom_stats).length ? entry.custom_stats : (entry.base_stats || {}))
        : {};
      // 🔴 A UNIAO, nao so' a peca nova (achado do Astra, 16/09; medido).
      // `Object.entries(_shownStats)` percorria SO' os atributos da peca NOVA:
      // trocar `{defesa:100}` por `{ataque:20}` mostrava o +20 e **nunca dizia**
      // que se perdiam 100 de defesa. Um atributo que DESAPARECE e' exactamente
      // a informacao que decide a troca, e era a unica que nao chegava.
      // ⚠️ A ordem e' a da peca nova primeiro (o que ela TEM), e so' depois o
      // que ela PERDE — assim a leitura de sempre nao muda de sitio.
      const _eqStatsAll = isArtifact && entry.comparedTo
        ? ((entry.comparedTo.custom_stats && Object.keys(entry.comparedTo.custom_stats).length)
            ? entry.comparedTo.custom_stats : (entry.comparedTo.base_stats || {}))
        : {};
      const stats = isArtifact
        ? Object.entries(_shownStats).concat(
            Object.keys(_eqStatsAll)
              .filter(k => !(k in _shownStats))
              .map(k => [k, 0]))
        : [];
      // ═══ 窗 A JANELA QUE NÃO FECHAVA (2026-09-08) ═══════════════════════
      //
      // Relato do owner, do telemóvel dele: *"quando abro o item no telefone
      // não posso fechar a janela. cobre tudo e nao deixa o X."*
      //
      // TRÊS defeitos somados, e nenhum deles era novo:
      //   1. **Sem portal.** Este `position:fixed` vivia dentro da
      //      `.scroll-area`, e no WebView do iOS isso ancora-o ao contentor que
      //      rola em vez de ao ecrã — o topo (com o ✕) fica por baixo do
      //      PlayerHeader. É textualmente o bug que o `Modal` consertou a
      //      2026-05-10; este modal é escrito à mão e nunca recebeu a correcção.
      //   2. **Sem limite de altura e sem rolagem.** O cartão crescia com o
      //      conteúdo. O 器 (08/09) pôs a ilustração no topo e tornou-o mais
      //      alto — MEDIDO: 504px de cartão. Num WebView de 420px de altura
      //      sobram 124px fora do ecrã, e **a página não rolava** (medido:
      //      `scrollHeight === clientHeight`) ⇒ os botões de acção ficavam
      //      inalcançáveis.
      //   3. **`placeItems:"center"`** — centrar uma peça mais alta que o pai
      //      corta as DUAS pontas. É o que tira o ✕ do ecrã sem deixar maneira
      //      de lá chegar.
      //
      // Agora: `Overlay` (portal + `overflowY:auto` + `margin:auto`) com
      // `bounded` — o cartão nunca passa do ecrã, o corpo rola por dentro, e o
      // ✕ vai em `pinned`, FORA do corpo que rola: está sempre lá.
      //
      // ⚠️ Isto vive no ramo PARTILHADO, de propósito. Uma janela que não fecha
      // é a Lei §1 na letra (*"o jogador NUNCA fica preso sem caminho"*) — não
      // é uma melhoria de estilo que se possa esconder atrás de uma flag, senão
      // quem não tem a flag continua preso. O ensaio do DOM vai acusar esta
      // diferença; é intencional e está escrita aqui.
      const _closeBtn = (
        <button onClick={onClose} aria-label="close" style={{
          position:"absolute", top:6, right:6, zIndex:4,
          width:28, height:28, borderRadius:99,
          background:"rgba(0,0,0,.45)", border:`1px solid ${cssHex(headerColor)}55`,
          color:headerColor, cursor:"pointer", padding:0,
          fontFamily:"'Cinzel',serif", fontSize:14, lineHeight:1,
          display:"grid", placeItems:"center",
          transition:"background .15s, box-shadow .15s",
        }}
        onMouseEnter={e => { e.currentTarget.style.background = "rgba(0,0,0,.7)"; e.currentTarget.style.boxShadow = `0 0 10px ${headerGlow}`; }}
        onMouseLeave={e => { e.currentTarget.style.background = "rgba(0,0,0,.45)"; e.currentTarget.style.boxShadow = "none"; }}
        >✕</button>
      );
      return (
        <Overlay onClose={onClose} zIndex={60} background="rgba(4,8,18,.92)"
                 maxWidth={340} bounded pinned={_closeBtn}
                 bodyStyle={{ padding:"18px 18px 16px" }}
                 cardStyle={{
            /* ⚠️ OLHAR, 2026-09-10: com a foto no topo, o gradiente por GRAU
               (magenta no 7, azul no 4, rosa no 8) deixou de ser cromo e passou
               a ser uma moldura colorida a' volta de uma ilustracao — o codigo
               de cores de nove degraus, na tela onde a peca tem a pagina toda
               so' para ela. Com a flag ON o painel e' o CHAO DA CARTA e herda o
               PATAMAR; o grau continua dito pelo chip `G7 · Dao`. */
            background: itemOn
              ? "rgb(var(--card-rgb))"
              : (isArtifact ? v.bg : "linear-gradient(180deg,rgba(20,30,55,.95),rgba(var(--card-rgb),.98))"),
            border: itemOn
              ? `1px solid rgba(${_itemOrn ? _itemOrn.edgeRgb : "var(--gold-rgb)"},${_itemOrn ? _itemOrn.edge : ".22"})`
              : `1px solid ${headerColor}`,
            borderRadius:14,
            boxShadow: itemOn
              ? "0 20px 60px rgba(0,0,0,.7)" + (_itemOrn ? ", " + _itemOrn.shadow : "")
              : `0 20px 60px rgba(0,0,0,.7), 0 0 32px ${headerGlow}, ${isArtifact && v.shine ? v.shine : "inset 0 0 0 0 transparent"}`,
            animation:"modal-in .22s cubic-bezier(.2,.8,.2,1)",
          }}>
            <>
            {/* ═══ 器 A FOTO DO ITEM (2026-09-10) ══════════════════
                Ordem do owner (2026-09-08): *"se eu abrir o item na mochila
                mostrar a foto dele"*.

                ⚠️ A arte de **51/51 artefactos** já existia, já estava no
                `NIV_ART_INDEX` e já era servida NA CÉLULA desde 06/09
                (`pieceArt("artifact", ...)`, mais abaixo neste ficheiro). Era
                **este modal** que não a pedia: desenhava um ícone de 30px numa
                caixa de 54. É LITERALMENTE o defeito que o owner fotografou a
                07/09 no `BeastDetailModal` — *"um emoji gigante no sítio onde a
                ilustração devia estar"*, com a arte da Thunder Ox a aparecer no
                cartão POR TRÁS do próprio modal. Foi corrigido nessa altura
                **só para as bestas**. Uma correcção que cobre 1 de 3 caminhos
                não corrige os outros 2.

                ⚠️ O MESMO `PieceHero` da besta, por props — nunca um segundo
                componente. Bifurcar a chapa duplicaria o verso honesto, o
                `onError` e o `lazy`, e um dos dois ficaria para trás (foi assim
                que este defeito nasceu).

                ⚠️ Uma peça SEM arte continua honesta: ervas, minérios e
                materiais caem no verso (anéis de tinta + o emoji do catálogo),
                que é o mesmo que a célula deles já mostra. O modal é a célula,
                maior — não uma tela com regras próprias. */}
            {itemOn ? (
              <>
                <PieceHero
                  src={isArtifact
                        ? pieceArt("artifact", entry.name, entry.art_key)
                        : (entry.type === "pill" ? pieceArt("pill", entry.name, entry.art_key) : null)}
                  glyph={isArtifact
                          ? slotIco(slotForArtifact(entry), entry.emoji, 64)
                          : (entry.emoji || "📦")}
                  accent={headerColor}
                  title={entry.name}
                  /* 朱砂 — aqui o selo TEM do que distinguir: o modal fala de
                     UMA peça e a pergunta "esta está posta?" é real. (Na grelha
                     da mochila não está: os quatro slots aparecem lado a lado
                     com os vazios e quatro carimbos matavam o acento.) É também
                     o que apaga o ✦ desta tela — o glifo que o owner leu como
                     "muito AI" a 07/09. */
                  seal={isArtifact && !!entry.is_equipped}
                  sealLabel={t("equipped")}
                  /* ⚠️ 18, não 14: este modal é feito à mão e o corpo dele tem
                     `padding:18`. Com o valor por omissão sobrava uma tira de
                     4px do fundo à volta da arte — a moldura que a chapa existe
                     para não ter. E o raio acompanha o painel (14 menos 1 de
                     borda), senão os cantos rectos passavam por fora dele. */
                  bleed={18} radius="13px 13px 0 0" />
                <div style={{ display:"flex", gap:6, alignItems:"center", flexWrap:"wrap", paddingRight:30 }}>
                  {isArtifact ? (
                    <>
                      <span style={{
                        fontFamily:"'Cinzel',serif", fontSize:10, letterSpacing:1, textTransform:"uppercase",
                        padding:"2px 8px", borderRadius:99, color:headerColor,
                        border:`1px solid ${headerColor}`, background:"rgba(0,0,0,.35)",
                      }}>G{entry.grade} · {nomeDoGrau(entry.grade, entry.grade_name)}</span>
                      {entry.quality && entry.quality !== "normal" && ART_QUALITY_KEY[entry.quality] && (
                        <span style={{
                          fontFamily:"'Cinzel',serif", fontSize:10, letterSpacing:1, textTransform:"uppercase",
                          padding:"2px 8px", borderRadius:99,
                          border:`1px solid ${entry.quality === "spirit" ? "var(--realm-10)" : (ART_QUALITY_COLOR[entry.quality] || "var(--realm-0)")}`,
                          background:"rgba(0,0,0,.35)",
                          ...artQualityChipStyle(entry.quality, "var(--muted)"),
                        }}>{t(ART_QUALITY_KEY[entry.quality])}</span>
                      )}
                      <span style={{ fontSize:10, color:"var(--muted)", textTransform:"capitalize" }}>{
                        /* 🎒 3.2 — era `{entry.type}` CRU ("Weapon" em pt e es) */
                        _TIPO_ARTEFACTO_KEY[entry.type] ? t(_TIPO_ARTEFACTO_KEY[entry.type]) : (entry.type || entry.slot)
                      }</span>
                    </>
                  ) : (
                    <>
                      <span style={{
                        fontFamily:"'Cinzel',serif", fontSize:10, letterSpacing:1, textTransform:"uppercase",
                        padding:"2px 8px", borderRadius:99, color:headerColor,
                        border:`1px solid ${headerColor}`, background:"rgba(0,0,0,.35)",
                      }}>{
                        /* 🎒 3.2 — era `{entry.quality}` CRU ("PERFECT", "MYTHIC") */
                        qualidadeDoItem(entry) || entry.quality || "normal"
                      }</span>
                      <span style={{ fontSize:10, color:"var(--muted)" }}>×{entry.quantity}</span>
                    </>
                  )}
                </div>
              </>
            ) : (
            <div style={{ display:"flex", alignItems:"flex-start", gap:12, paddingRight:30 }}>
              <div style={{
                width:54, height:54, borderRadius:12, flexShrink:0,
                background:"rgba(0,0,0,.35)", border:`1px solid ${headerColor}`,
                display:"grid", placeItems:"center", fontSize:30,
                boxShadow:`inset 0 0 14px ${headerGlow}`,
              }}>{
                // Owner request 2026-05-08: artifact icon should match the
                // canonical SLOT_ICONS (sword/robe/ring/pendant) so the *type*
                // reads at a glance — not the catalog emoji which can be
                // anything (⭐ for "Divine Star Earring" etc.). Falls back to
                // catalog emoji only if slot can't be inferred. Items keep
                // their catalog emoji.
                isArtifact
                  ? slotIco(slotForArtifact(entry), entry.emoji, 30)
                  : (entry.emoji || "📦")
              }</div>
              <div style={{ flex:1, minWidth:0 }}>
                <div style={{ fontFamily:"'Cinzel',serif", fontSize:15, fontWeight:700, color:headerColor, lineHeight:1.2 }}>
                  {entry.name}
                </div>
                <div style={{ display:"flex", gap:6, alignItems:"center", marginTop:6, flexWrap:"wrap" }}>
                  {isArtifact ? (
                    <>
                      <span style={{
                        fontFamily:"'Cinzel',serif", fontSize:10, letterSpacing:1, textTransform:"uppercase",
                        padding:"2px 8px", borderRadius:99, color:headerColor,
                        border:`1px solid ${headerColor}`, background:"rgba(0,0,0,.35)",
                      }}>G{entry.grade} · {nomeDoGrau(entry.grade, entry.grade_name)}</span>
                      {/* TAPETE QoL §5: craft-quality chip (Perfeito/Divino/Espírito) */}
                      {entry.quality && entry.quality !== "normal" && ART_QUALITY_KEY[entry.quality] && (
                        <span style={{
                          fontFamily:"'Cinzel',serif", fontSize:10, letterSpacing:1, textTransform:"uppercase",
                          padding:"2px 8px", borderRadius:99,
                          border:`1px solid ${entry.quality === "spirit" ? "var(--realm-10)" : (ART_QUALITY_COLOR[entry.quality] || "var(--realm-0)")}`,
                          background:"rgba(0,0,0,.35)",
                          ...artQualityChipStyle(entry.quality, "var(--muted)"),
                        }}>{t(ART_QUALITY_KEY[entry.quality])}</span>
                      )}
                      <span style={{ fontSize:10, color:"var(--muted)", textTransform:"capitalize" }}>{
                        /* 🎒 3.2 — era `{entry.type}` CRU ("Weapon" em pt e es) */
                        _TIPO_ARTEFACTO_KEY[entry.type] ? t(_TIPO_ARTEFACTO_KEY[entry.type]) : (entry.type || entry.slot)
                      }</span>
                      {entry.is_equipped && <span style={{ fontSize:9, color:"var(--gold2)" }}>✦ {t("equipped")}</span>}
                    </>
                  ) : (
                    <>
                      <span style={{
                        fontFamily:"'Cinzel',serif", fontSize:10, letterSpacing:1, textTransform:"uppercase",
                        padding:"2px 8px", borderRadius:99, color:headerColor,
                        border:`1px solid ${headerColor}`, background:"rgba(0,0,0,.35)",
                      }}>{
                        /* 🎒 3.2 — era `{entry.quality}` CRU ("PERFECT", "MYTHIC") */
                        qualidadeDoItem(entry) || entry.quality || "normal"
                      }</span>
                      <span style={{ fontSize:10, color:"var(--muted)" }}>×{entry.quantity}</span>
                    </>
                  )}
                </div>
              </div>
            </div>
            )}

            {entry.description && (
              <div style={{
                marginTop:14, padding:"10px 12px",
                background:"rgba(0,0,0,.3)", border:"1px dashed rgba(255,255,255,.07)",
                borderRadius:8, fontSize:11.5, lineHeight:1.5, color:"var(--text)", fontStyle:"italic",
              }}>"{entry.description}"</div>
            )}

            {/* MV-9.5 — DE ONDE VEM. A única escassez do jogo é geográfica e
                nunca tinha sido dita em lado nenhum: o jogador via "0/12" e não
                tinha como saber que aquele minério só nasce noutro continente.
                `entry.origin.line` chega JÁ localizada do servidor (nunca t());
                a key é condicional → com a flag OFF nem existe. */}
            {entry.origin && entry.origin.line && (
              <div style={{
                marginTop:10, padding:"8px 12px", borderRadius:8,
                background:"rgba(0,0,0,.28)", border:"1px solid rgba(var(--gold2-rgb),.16)",
              }}>
                <div style={{ fontSize:9.5, letterSpacing:1, textTransform:"uppercase",
                              color:"var(--muted)", fontFamily:"'Cinzel',serif" }}>
                  {t("crv_origin_head")}
                </div>
                <div style={{ fontSize:11.5, marginTop:3, lineHeight:1.45,
                              color: entry.origin.here ? "var(--gold3)" : "var(--muted)" }}>
                  {entry.origin.line}
                </div>
              </div>
            )}

            {isArtifact && stats.length > 0 && (
              <div style={{ marginTop:14 }}>
                <div style={{ display:"flex", justifyContent:"space-between", alignItems:"baseline", marginBottom:6 }}>
                  <div style={{ fontSize:10, letterSpacing:1.5, color:"var(--muted)", textTransform:"uppercase" }}>
                    {t("attributes")}
                  </div>
                  {entry.comparedTo && (
                    <div style={{ fontSize:9, color:"var(--muted2)", letterSpacing:.4 }}>
                      {t("inv_compare_vs_equipped")}
                    </div>
                  )}
                </div>
                <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:6 }}>
                  {stats.map(([k, val]) => {
                    // Owner request 2026-05-08: green/red delta vs equipped of
                    // same slot so player doesn't have to mentally subtract.
                    // Only shown when entry.comparedTo exists (non-equipped
                    // artifact with a same-slot equipped peer). v14.3: also
                    // read custom_stats first on the compared artifact so the
                    // delta reflects the *real* equipped stats (grade-scaled).
                    const eqStats = (entry.comparedTo?.custom_stats && Object.keys(entry.comparedTo.custom_stats).length)
                      ? entry.comparedTo.custom_stats
                      : (entry.comparedTo?.base_stats || {});
                    const eqVal = eqStats?.[k];
                    const numVal = typeof val === "number" ? val : 0;
                    const numEq = typeof eqVal === "number" ? eqVal : 0;
                    const delta = entry.comparedTo ? (numVal - numEq) : null;
                    const deltaColor = delta == null ? null
                                     : delta > 0 ? "var(--jade)"
                                     : delta < 0 ? "var(--red2)"
                                     : "var(--muted2)";
                    return (
                      <div key={k} style={{
                        display:"flex", justifyContent:"space-between", alignItems:"center",
                        padding:"6px 8px", background:"rgba(0,0,0,.25)",
                        border:"1px solid rgba(var(--glow-rgb),.18)", borderRadius:6, fontSize:11,
                      }}>
                        {/* ⚠️ UM NÚMERO PARTIDO É UM NÚMERO QUE MENTE (2026-09-08).
                            Fotografado pelo owner no telemóvel: "Poder de Combate
                            +12000" imprimia-se como `+1200` / `0` em duas linhas,
                            e lê-se como mil e duzentos. A 390px cada célula desta
                            grelha de 2 colunas tem ~160px; o rótulo longo empurra
                            e o valor quebra. `minWidth:0` desarma o mínimo
                            automático do flex (que é o min-content = a palavra
                            inteira) e `whiteSpace:nowrap` + `flexShrink:0` fazem
                            do NÚMERO a coisa que nunca cede — encolhe o rótulo,
                            nunca o valor. */}
                        <span style={{ color:"var(--muted)", minWidth:0,
                                       overflow:"hidden", textOverflow:"ellipsis",
                                       whiteSpace:"nowrap" }}>{humanizeStat(k)}</span>
                        <span style={{ display:"flex", gap:5, alignItems:"baseline",
                                       flexShrink:0, whiteSpace:"nowrap" }}>
                          <b style={{ color:"var(--gold2)" }}>+{typeof val === "number" ? (val % 1 === 0 ? val : val.toFixed(2)) : val}</b>
                          {delta !== null && delta !== 0 && (
                            <span style={{ fontSize:9.5, color: deltaColor, fontWeight:600 }}>
                              ({delta > 0 ? "+" : ""}{Math.abs(delta) % 1 === 0 ? delta : delta.toFixed(1)})
                            </span>
                          )}
                        </span>
                      </div>
                    );
                  })}
                </div>
                {entry.comparedTo && (
                  <div style={{ fontSize:9.5, color:"var(--muted)", textAlign:"center", marginTop:6, lineHeight:1.4 }}>
                    {t("inv_compare_replaces", { name: entry.comparedTo.name })}
                  </div>
                )}
              </div>
            )}

            {isArtifact && entry.has_spirit && (
              <div style={{ marginTop:12, fontSize:11, color:"var(--gold2)", textAlign:"center" }}>
                ✧ {entry.spirit_name || t("market_art_spirit") /* 🎒 3.2 — era "Awakened Spirit" cru */} ✧
              </div>
            )}
            {isArtifact && entry.enchant_rune && (
              <div style={{ marginTop:6, fontSize:10.5, color:"var(--muted)", textAlign:"center" }}>
                ⟁ {entry.enchant_rune}
              </div>
            )}
            {/* 2026-05-23 + 2026-05-24 (owner): show realm status for EVERY
                artifact — including no-requirement items so player isn't left
                guessing. 62 of 92 catalog artifacts seed without min_realm
                (default 0); previously they showed nothing at all in this slot. */}
            {isArtifact && (() => {
              const curRealm = Number(player?.realm ?? 0);
              const minRealm = Number(entry.min_realm || 0);
              if (minRealm === 0) {
                return (
                  <div style={{
                    marginTop:10, fontSize:11, textAlign:"center",
                    color:"var(--jade)", fontWeight:500,
                  }}>
                    ✅ {t("inv_detail_no_realm_req")}
                  </div>
                );
              }
              const canEquip = curRealm >= minRealm;
              return (
                <div style={{
                  marginTop:10, fontSize:11, textAlign:"center",
                  color: canEquip ? "var(--jade)" : "var(--red)",
                  fontWeight: canEquip ? 500 : 600,
                }}>
                  {canEquip
                    ? `✅ ${t("min_realm_label")}: ${realmName(minRealm)}`
                    : t("inv_detail_realm_locked", { required: realmName(minRealm), current: realmName(curRealm) })}
                </div>
              );
            })()}

            {/* QoL-Feedback 03/08 (report [jogador]: "what kind of weapons can be
                refined? … there's no option to refine it"). O detalhe do item é
                ONDE ele olhou a arma, e não dizia nada sobre refino nem apontava
                o Ateliê. Agora diz — e no topo diz que É o topo, com o caminho
                seguinte (Lei §1). Texto, não navegação: o Ateliê vive dentro de
                Forja › ⚒️, e um salto de aba deixaria o jogador no segmento
                errado — pior do que o silêncio que estamos a corrigir. */}
            {isArtifact && (
              <div style={{ marginTop:8, fontSize:10.5, textAlign:"center",
                             color:"var(--muted)", lineHeight:1.5 }}>
                {(entry.grade ?? 0) >= 8
                  ? `👑 ${t("inv_detail_refine_absolute_max")}`
                  : (entry.grade ?? 0) === 7
                    ? `⭐ ${t("inv_detail_refine_at_max")}`
                    : `✨ ${t("inv_detail_refine_hint", { workshop: t("workshop_open_btn") })}`}
              </div>
            )}

            {isArtifact && (
              <DetailModalActions entry={entry} busy={busy} setBusy={setBusy}
                err={err} setErr={setErr}
                picker={picker} setPicker={setPicker}
                confirmDismantle={confirmDismantle}
                setConfirmDismantle={setConfirmDismantle}
                onActionDone={onActionDone} onClose={onClose} />
            )}

            {/* v14.11 — Pill use panel. Owner pediu 2026-05-06: "Nota tambem
                usar as pilulas mostrar os efeitos etc." Mirror chat
                handlers/inventory._do_use_pill via /pill/use endpoint. */}
            {!isArtifact && entry.type === "pill" && (
              <PillUsePanel entry={entry} onClose={onClose}
                            onActionDone={onActionDone} />
            )}
          </>
        </Overlay>
      );
    }

    // Pulled out so it can hook into useState above without re-mounting on every
    // re-render. Owns the Equip / Lock / Dismantle wiring + accessory picker
    // pop-up + dismantle confirm panel.
    function DetailModalActions({
      entry, busy, setBusy, err, setErr, picker, setPicker,
      confirmDismantle, setConfirmDismantle, onActionDone, onClose,
    }) {
      const equipped = !!entry.is_equipped;
      // Owner request 2026-05-07: button label must flip Bloquear↔Desbloquear
      // immediately after callLock succeeds. The modal stays open (line 1101's
      // "Don't close" intent), but `entry.locked` is the parent's STALE prop
      // until inventory refetches. Local state ensures the toggle reads as soon
      // as the server confirms the new state.
      const [lockedState, setLockedState] = useState(!!entry.locked);
      const locked = lockedState;

      async function callEquip(preferSlot) {
        if (busy) return;
        setBusy(true); setErr(null);
        haptic("warning");
        try {
          const body = preferSlot
            ? { artifact_id: entry.id, prefer_slot: preferSlot }
            : { artifact_id: entry.id };
          const res = await api("artifact/equip", body);
          if (!res.ok) {
            if (res.reason === "accessory_picker_required") {
              setPicker(res);
              setBusy(false);
              return;
            }
            haptic("error");
            setErr(forgeReason(res.reason, { required_realm: entry.min_realm || 0 }));
            setBusy(false);
            return;
          }
          haptic("success");
          showToast(t("inv_equipped_toast", { name: entry.name }) + vpPowerLine(res.power_delta));
          setBusy(false);
          setPicker(null);
          onActionDone && onActionDone();
          onClose && onClose();
        } catch (e) {
          haptic("error");
          setErr(t("forge_err_engine"));
          setBusy(false);
        }
      }

      async function callUnequip() {
        if (busy) return;
        setBusy(true); setErr(null);
        haptic("warning");
        try {
          const res = await api("artifact/unequip", { artifact_id: entry.id });
          if (!res.ok) {
            haptic("error");
            setErr(forgeReason(res.reason));
            setBusy(false);
            return;
          }
          haptic("success");
          showToast(t("inv_unequipped_toast", { name: entry.name }) + vpPowerLine(res.power_delta));
          setBusy(false);
          onActionDone && onActionDone();
          onClose && onClose();
        } catch (e) {
          haptic("error");
          setErr(t("forge_err_engine"));
          setBusy(false);
        }
      }

      async function callLock() {
        if (busy) return;
        setBusy(true); setErr(null);
        haptic("light");
        try {
          const res = await api("artifact/lock", { artifact_id: entry.id });
          if (!res.ok) {
            haptic("error");
            setErr(forgeReason(res.reason));
            setBusy(false);
            return;
          }
          haptic("success");
          showToast(res.locked ? t("inv_locked_toast") : t("inv_unlocked_toast"));
          setLockedState(!!res.locked);  // flip local state so button label updates immediately
          setBusy(false);
          onActionDone && onActionDone();
          // Don't close — keep modal open so user sees toggle state changed
        } catch (e) {
          haptic("error");
          setErr(t("forge_err_engine"));
          setBusy(false);
        }
      }

      async function callDismantle() {
        if (busy) return;
        setBusy(true); setErr(null);
        haptic("warning");
        try {
          const res = await api("forge/dismantle", { artifact_id: entry.id });
          if (!res.ok) {
            haptic("error");
            setErr(forgeReason(res.reason));
            setBusy(false);
            return;
          }
          haptic("success");
          showToast(t("inv_dismantled_toast", { name: entry.name, ss: fmtNum(res.stones_gained) }));
          setBusy(false);
          setConfirmDismantle(false);
          onActionDone && onActionDone();
          onClose && onClose();
        } catch (e) {
          haptic("error");
          setErr(t("forge_err_engine"));
          setBusy(false);
        }
      }

      return (
        <>
          {err && <ErrBanner msg={err} />}

          {confirmDismantle ? (
            <DismantleConfirm entry={entry} busy={busy}
              onConfirm={callDismantle} onCancel={() => setConfirmDismantle(false)} />
          ) : (
            <div style={{ marginTop:14, display:"flex", flexDirection:"column", gap:6 }}>
              {/* Primary: Equip / Unequip */}
              {equipped ? (
                <ActionBtn variant="ghost" disabled={busy} onClick={callUnequip}>
                  {busy ? <DotSpinner /> : `🪶 ${t("inv_unequip_btn")}`}
                </ActionBtn>
              ) : (
                <ActionBtn variant="primary" disabled={busy} onClick={() => callEquip(null)}>
                  {busy ? <DotSpinner /> : `⚔️ ${t("inv_equip_btn")}`}
                </ActionBtn>
              )}

              {/* Secondary: Lock + Dismantle */}
              <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:6 }}>
                <button onClick={callLock} disabled={busy}
                        style={{
                          padding:"9px 10px", borderRadius:8,
                          cursor: busy ? "default" : "pointer",
                          background: locked ? "rgba(var(--gold2-rgb),.12)" : "rgba(0,0,0,.3)",
                          border:`1px solid ${locked ? "rgba(var(--gold2-rgb),.45)" : "rgba(var(--glow-rgb),.3)"}`,
                          color: locked ? "var(--gold2)" : "var(--muted)",
                          fontFamily:"'Cinzel',serif", fontSize:11, fontWeight:600, letterSpacing:.5,
                        }}>
                  {locked ? `🔒 ${t("inv_unlock_btn")}` : `🔓 ${t("inv_lock_btn")}`}
                </button>
                <button onClick={() => setConfirmDismantle(true)}
                        disabled={busy || equipped || locked}
                        style={{
                          padding:"9px 10px", borderRadius:8,
                          cursor: (busy || equipped || locked) ? "default" : "pointer",
                          background: (equipped || locked) ? "rgba(0,0,0,.3)" : "rgba(var(--red-rgb),.08)",
                          border:`1px solid ${(equipped || locked) ? "rgba(var(--glow-rgb),.2)" : "rgba(var(--red-rgb),.4)"}`,
                          color: (equipped || locked) ? "var(--muted2)" : "var(--red2)",
                          fontFamily:"'Cinzel',serif", fontSize:11, fontWeight:600, letterSpacing:.5,
                          opacity: (equipped || locked) ? .55 : 1,
                        }}>
                  ♻️ {t("inv_dismantle_btn")}
                </button>
              </div>
              {(equipped || locked) && (
                <div style={{ fontSize:10, color:"var(--muted2)", textAlign:"center", marginTop:2 }}>
                  {equipped ? t("inv_dismantle_blocked_equipped") : t("inv_dismantle_blocked_locked")}
                </div>
              )}
            </div>
          )}

          {picker && (
            <EquipSlotPickerModal payload={picker} incoming={entry}
              busy={busy}
              onClose={() => setPicker(null)}
              onPick={(slot) => callEquip(slot)} />
          )}
        </>
      );
    }

    // Visual cell shared by equipped + stash + items grids.
    // Icon picks: prefer the slot-canonical icon (sword for weapon, robe for
    // armor, ring/pendant for accessories) so the *type* reads at a glance.
    // For stash entries that have a slot inferred from `type` instead of
    // an actual `slot`, fall back to type→slot mapping. Catalog emoji is a
    // last resort.
    function slotForArtifact(a) {
      if (a.slot && SLOT_ICONS[a.slot]) return a.slot;
      if (a.type === "weapon") return "weapon";
      if (a.type === "armor")  return "armor";
      if (a.type === "accessory") return "accessory1";
      return null;
    }
    // 牌 2026-09-08 — a grelha da mochila (as TRÊS: equipado, anel, secções).
    //
    // ⚠️ TEM DE VIVER AQUI, no topo, e não dentro do `InventoryTab`. A 1ª versão
    // era uma seta declarada no corpo do componente — e isso re-cria o TIPO do
    // componente a cada render, o que faz o React desmontar e remontar a grelha
    // inteira. Consequência VISTA (não deduzida): ao mexer em qualquer estado da
    // mochila, todas as cartas remontavam, o `CardArt` voltava a `loaded:false`
    // e a mochila piscava para o verso honesto — a arte apagava-se sozinha.
    // Nenhum teste podia apanhar isto: os dois caminhos rendem, e o DOM final é
    // o mesmo. Só olhar duas vezes seguidas o mostra.
    //
    // ⚠️ Com `cartas` OFF devolve **exactamente** o `<div>` de hoje.
    function InvGrid({ cards, children }) {
      return cards
        ? <CardGrid min={152}>{children}</CardGrid>
        : <div style={{ display:"grid", gridTemplateColumns:"repeat(4,1fr)", gap:6 }}>{children}</div>;
    }

    // 牌 2026-09-08 — A MOCHILA. É o item 1 da conversão, e por duas razões
    // medidas: (1) é a única tela que serve os QUATRO conteúdos com o mesmo
    // renderizador, logo é a prova de que a carta é sistema e não tela; (2) os
    // **51 artefactos ilustrados** (≈$3,40 de arte paga, indexada desde
    // 2026-09-06) não apareciam em sítio nenhum do jogo — a mochila é onde eles
    // vivem.
    //
    // ⚠️ A grelha de 4 colunas de emojis NÃO desaparece com a flag OFF: o
    // `*Classic` abaixo é o markup de hoje, byte a byte.
    function ArtifactCell({ a, equipped, onClick, playerRealm }) {
      const cardsOn = typeof featureEnabled === "function" && featureEnabled("cartas");
      if (!cardsOn) return <ArtifactCellClassic a={a} equipped={equipped}
                                                onClick={onClick} playerRealm={playerRealm} />;
      const sk = slotForArtifact(a);
      const minRealm = Number(a.min_realm || 0);
      const realmLocked = minRealm > 0 && (Number(playerRealm) || 0) < minRealm;
      const v = GRADE_VISUALS[a.grade] || GRADE_VISUALS[0];
      // ⚠️ O lombo conta o `grade` (0..8), NÃO a qualidade de forja. A
      // qualidade continua a ser o chip que a TAPETE QoL §5 desenhou — porque
      // é o que ela é: um adjectivo do exemplar, não um degrau da escada.
      // `refined` fica onde sempre esteve, fora da escala (ver `NIV_RANK_SCALES`).
      const q = a.quality && a.quality !== "normal" ? a.quality : null;
      return (
        <NivraelCard
          kind="artifact" rank={a.grade}
          glyph={(sk && SLOT_ICONS[sk]) || a.emoji || "🗡️"}
          art={pieceArt("artifact", a.name, a.art_key)}
          name={a.name}
          accent={v.color}
          eyebrow={t("inv_card_kind_artifact")}
          state={equipped ? "active" : realmLocked ? "locked" : "owned"}
          stateLabel={equipped ? t("inv_card_equipped")
                     : realmLocked ? t("inv_card_realm_locked", { n: minRealm }) : null}
          /* 朱砂 — sem selo aqui, e a razão é de sentido, não de contagem.
             O selo marca uma ESCOLHA entre muitas: a arte que o cultivador
             levou para o combate (2-4 de 129), o companheiro (1). Um slot de
             equipamento simplesmente CHEIO não é uma escolha — toda a gente tem
             uma arma posta, e os quatro slots aparecem lado a lado com os
             vazios, portanto a composição já diz tudo. Carimbar os quatro punha
             quatro cinábrios na primeira tela da mochila e o acento morria.
             (A arte equipada no Combate MANTÉM o selo: lá há escolha.) */
          seal={false}
          onClick={onClick}
          effect={(() => {
            const cs = a.custom_stats || a.stats || {};
            const bp = cs.battle_power || 0;
            const alt = !bp && (cs.soul_strength || cs.qi_capacity || cs.luck || 0);
            if (!bp && !alt) return null;
            return <span style={{ color:"var(--gold2)", fontWeight:600 }}>
              {bp ? `⚔️ ${fmtNum(bp)}` : `+${fmtNum(alt)}`}
            </span>;
          })()}
          foot={(
            <>
              <span>{q ? (
                <span style={{ ...artQualityChipStyle(a.quality, v.color) }}>
                  {t(ART_QUALITY_KEY[a.quality] || "art_quality_normal")}
                </span>
              ) : null}</span>
              <span>
                {a.has_spirit && <span title="spirit">✧ </span>}
                {a.locked && <span>{ico("🔒","lock",{ size:13, style:{ display:"inline-block", verticalAlign:"-2px" } })}</span>}
              </span>
            </>
          )} />
      );
    }

    function ArtifactCellClassic({ a, equipped, onClick, playerRealm }) {
      const v = GRADE_VISUALS[a.grade] || GRADE_VISUALS[0];
      const sk = slotForArtifact(a);
      const icon = slotIco(sk, a.emoji, 22);
      const iconIsMark = markOn(SLOT_MARKS[sk]);
      // 2026-05-23 owner request: realm-gate visual chip so player sees
      // BEFORE tap that an artifact cannot be equipped (mirrors chat patch).
      const minRealm = Number(a.min_realm || 0);
      const realmLocked = minRealm > 0 && (Number(playerRealm) || 0) < minRealm;
      return (
        <div onClick={onClick} style={{
          aspectRatio:1,
          background: v.bg,
          border:`1px solid ${equipped ? "var(--gold)" : (realmLocked ? "var(--red)" : v.color)}`,
          borderRadius:8, display:"grid", placeItems:"center",
          position:"relative", cursor:"pointer",
          opacity: realmLocked ? .7 : 1,
          boxShadow: equipped
            ? `inset 0 0 8px rgba(var(--gold-rgb),.3), 0 0 10px ${v.glow}`
            : `0 0 8px ${v.glow}${v.shine ? `, ${v.shine}` : ""}`,
        }}>
          <span style={{
            fontSize:22,
            ...(iconIsMark ? { display:"grid", placeItems:"center", color:cssHex(v.color) } : {}),
            filter:`drop-shadow(0 0 6px ${v.glow})`,
            ...(realmLocked ? { filter:"grayscale(.5) drop-shadow(0 0 4px rgba(var(--red-rgb),.4))" } : {}),
          }}>{icon}</span>
          {/* TAPETE QoL §5 item 5 ([jogador]): the G chip is tinted by CRAFT
              quality when the artifact has one (Perfeito roxo · Divino
              dourado · Espírito colorido); normal keeps the grade color. */}
          <span style={{
            position:"absolute", left:4, top:2, fontSize:9, fontWeight:700,
            fontFamily:"'Cinzel',serif", letterSpacing:.3,
            textShadow: a.quality === "spirit" ? "none" : `0 0 6px ${v.glow}`,
            ...artQualityChipStyle(a.quality, v.color),
          }}>G{a.grade}</span>
          {/* 印 ⚠️ Este era, letra a letra, o glifo que o owner leu como "muito AI"
               no centro do orbe (07/09) — e estava aqui a dizer "equipado". Com a
               flag ON sai por um traco de pincel, que e' o que o resto do jogo usa
               para dizer "sim". */}
          {equipped && <span style={{ position:"absolute", right:3, top:1, fontSize:9, color:"var(--gold2)",
                                      display:markOn("check") ? "grid" : undefined,
                                      placeItems:markOn("check") ? "center" : undefined }}>{ico("✦", "check", { size:10 })}</span>}
          {a.has_spirit && <span style={{ position:"absolute", right:3, bottom:2, fontSize:9 }}>✧</span>}
          {/* TAPETE QoL §5 item 3 ([jogador]: "Ex: BP 22800 ... pra não precisar
              abrir outro inventário") — main stat inline on the cell, same
              info the chat inventory list line shows. */}
          {(() => {
            const cs = a.custom_stats || a.stats || {};
            const bp = cs.battle_power || 0;
            const alt = !bp && (cs.soul_strength || cs.qi_capacity || cs.luck || 0);
            if (!bp && !alt) return null;
            return (
              <span style={{
                position:"absolute", left:"50%", bottom:1, transform:"translateX(-50%)",
                fontSize:8.5, fontWeight:700, color:"var(--gold2)",
                textShadow:"0 0 4px rgba(0,0,0,.9)", whiteSpace:"nowrap",
              }}>{bp ? `⚔️${fmtNum(bp)}` : `+${fmtNum(alt)}`}</span>
            );
          })()}
          {/* Owner request 2026-05-07: lock badge so locked items are visually
              distinguishable on the grid. Bottom-left corner — collision-free
              with G{grade} top-left, ✦ top-right, ✧ bottom-right. */}
          {a.locked && (
            <span style={{
              position:"absolute", left:3, bottom:2, fontSize:9,
              color:"var(--gold2)", textShadow:"0 0 4px rgba(0,0,0,.85)",
              opacity:.9,
              ...(markOn("lock") ? { display:"grid", placeItems:"center" } : {}),
            }}>{ico("🔒", "lock", { size:11 })}</span>
          )}
          {/* Realm gate chip — overlays the centre so it's obvious the item
              is unusable at the player's current realm. */}
          {realmLocked && (
            <span style={{
              position:"absolute", right:3, top:1, fontSize:9, fontWeight:700,
              color:"var(--red)", fontFamily:"'Cinzel',serif", letterSpacing:.3,
              textShadow:"0 0 4px rgba(0,0,0,.85)",
            }}>🚫R{minRealm}</span>
          )}
        </div>
      );
    }
    // 牌 — a MESMA carta serve pílula, erva e minério. É aqui que "profundidade
    // > variedade" (Lei §3) se vê: três conteúdos, um componente, e a única
    // diferença entre eles é o que a peça É — a pílula tem grau (lombo), a erva
    // e o minério têm quantidade e origem.
    // ⚠️ Ervas e minérios ainda NÃO têm arte (ARTE_PROVENIENCIA §2.5: faltam 14
    // ervas e 6 minérios). Caem no VERSO honesto, e é para isso que ele existe:
    // uma carta virada para baixo é um estado legítimo; um rectângulo cinzento
    // não é. Nada aqui espera pela arte para funcionar.
    var _ITEM_KIND_KEY = { pill: "inv_card_kind_pill", herb: "inv_card_kind_herb",
                           ore: "inv_card_kind_ore" };

    function ItemCell({ it, onClick }) {
      const cardsOn = typeof featureEnabled === "function" && featureEnabled("cartas");
      if (!cardsOn) return <ItemCellClassic it={it} onClick={onClick} />;
      const qc = QUALITY_COLOR[it.quality] || "var(--gold)";
      const fallbackByType = it.type === "pill" ? "💊"
                           : it.type === "herb" ? "🌿"
                           : it.type === "ore"  ? "🪨" : "📦";
      return (
        <NivraelCard
          /* ⚠️ SÓ a pílula tem posto (`pill` = `required_alchemy_tier`). A erva
             e o minério têm `tier` no catálogo mas ele nunca foi mostrado ao
             jogador como um grau, e inventar-lhe um lombo seria desenhar uma
             escada que o jogo não tem. `kind` indefinido ⇒ `nivRank` devolve
             null ⇒ sem lombo, que é a resposta honesta. */
          kind={it.type === "pill" ? "pill" : null}
          rank={it.type === "pill" ? it.required_alchemy_tier : null}
          glyph={it.emoji || fallbackByType}
          art={it.type === "pill" ? pieceArt("pill", it.name, it.art_key) : null}
          name={it.name}
          accent={it.type === "pill" ? qc : "var(--gold)"}
          eyebrow={t(_ITEM_KIND_KEY[it.type] || "inv_card_kind_item")}
          state="owned"
          onClick={onClick}
          effect={it.description || null}
          foot={(
            <>
              <span style={{ color:"var(--gold2)", fontWeight:600 }}>
                {t("inv_card_qty", { n: fmtNum(it.quantity) })}
              </span>
              <span>
                {it.is_timed && <span>⏱️ </span>}
                {it.type === "pill" && it.quality && it.quality !== "normal" && (
                  <span style={{ color: qc }}>
                    {t("pill_quality_" + it.quality)}
                  </span>
                )}
                {/* 🎒 3.2 — a armadilha tem RARIDADE (a captura usa-a) e a carta
                    nunca a disse: uma mítica e uma básica eram iguais aqui. */}
                {it.type === "beast_trap" && <span>{qualidadeDoItem(it)}</span>}
              </span>
            </>
          )} />
      );
    }

    function ItemCellClassic({ it, onClick }) {
      // v14.13d (2026-05-25) — Owner P3: item icons polish. Pill cells now
      // show a quality-coloured glow + ring border (mirror artifact GRADE
      // visual idiom for consistency). Herbs/ores keep neutral chrome with
      // emoji-driven visual identity. Type-specific fallback emoji when
      // catalog row is missing one (instead of generic 📦).
      // R5: fallback em hex — qc é concatenado com alpha (gradiente/glow da pílula).
      const qc = QUALITY_COLOR[it.quality] || "var(--border)";
      const isPill = it.type === "pill";
      const fallbackByType = it.type === "pill" ? "💊"
                           : it.type === "herb" ? "🌿"
                           : it.type === "ore"  ? "🪨"
                           : "📦";
      return (
        <div onClick={onClick} style={{
          aspectRatio:1,
          background: isPill
            ? `radial-gradient(circle at 50% 35%, ${cssHex(qc)}22, rgba(20,30,55,.9))`
            : "linear-gradient(180deg,rgba(40,55,90,.7),rgba(20,30,55,.9))",
          border:`1px solid ${qc}`, borderRadius:8, display:"grid", placeItems:"center",
          position:"relative", cursor:"pointer",
          boxShadow: isPill ? `0 0 8px ${cssHex(qc)}55` : "none",
        }}>
          <span style={{
            fontSize:22,
            filter: isPill ? `drop-shadow(0 0 6px ${cssHex(qc)}cc)` : "none",
          }}>{it.emoji || fallbackByType}</span>
          <span style={{ position:"absolute", right:4, bottom:2, fontSize:10, fontWeight:700, color:"var(--gold2)" }}>{it.quantity}</span>
          {/* TAPETE QoL §5 item 6 ([jogador]: "reloginho") — timed-buff pill flag. */}
          {isPill && it.is_timed && (
            <span style={{ position:"absolute", right:3, top:1, fontSize:9,
                           filter:"drop-shadow(0 0 3px rgba(0,0,0,.9))" }}>⏱️</span>
          )}
          {isPill && it.quality && it.quality !== "normal" && (
            <span style={{
              position:"absolute", left:3, top:1, fontSize:8.5, fontWeight:700,
              color: qc, letterSpacing:.3, fontFamily:"'Cinzel',serif",
              textShadow:`0 0 5px ${cssHex(qc)}aa`,
            }}>{it.quality.charAt(0).toUpperCase()}</span>
          )}
        </div>
      );
    }

    // ═══ 🎒 3.2 — O INVENTÁRIO: "tabela para gerir, carta para ver" ═══════════
    //
    // A decisão é do Astra (MESA [018] §1, 21/09), textual: *"a coleção
    // apresenta-se como lista tabular; escolher uma linha abre a peça em
    // NivraelCard, com arte, nome completo, atributos e ações existentes. (…)
    // Título da categoria centrado; nomes e descrições à esquerda. O tipo sobe
    // para o cabeçalho, libertando largura em cada linha."* E: *"O anel espacial
    // e os quatro lugares de equipamento continuam a ser o corpo do sistema."*
    //
    // 🔴 O QUE A CONTAGEM DISSE ANTES (30/09, Beta com as 40 flags): cada peça
    // era uma carta de ~270 px, duas por fila — 4.212 px para 26 linhas, e um
    // jogador no p90 guarda 91 artefactos (máx. medido: 732). As ervas e os
    // minérios não têm arte e mostravam o VERSO vazio em cada carta.
    //
    // Só com a chave-mestra (`obraOn()`); desligada, a mochila de hoje.

    // A palavra da QUALIDADE de um item — um dono, para a tabela e para o
    // detalhe. ⚠️ O detalhe escrevia `{entry.quality}` CRU: "PERFECT" e
    // "MYTHIC" a quem joga em pt e es. A pílula tem cinco graus de qualidade; a
    // armadilha tem RARIDADE (a captura ordena normal < common < rare < epic <
    // mythic < legendary e só dá bónus a partir de rara — `core/beast_engine`),
    // e até hoje a carta não a dizia: uma mítica e uma básica eram iguais. O
    // resto (ervas, minérios, núcleos, plantas, bilhetes) é sempre "normal" em
    // produção (medido: 1.301 linhas de erva, todas) — sem palavra, não se
    // inventa uma qualidade que o item não tem.
    function qualidadeDoItem(it) {
      const q = (it && it.quality) || "normal";
      if (it && it.type === "pill") return t("pill_quality_" + q);
      if (it && it.type === "beast_trap") return t("inv_tab_raridade_" + q);
      return null;
    }

    // UMA tabela da colecção. Cada linha é um <button> com a sua própria
    // grelha; as colunas só alinham entre linhas porque as larguras 2 e 3 são
    // FIXAS, e `minmax(0,1fr)` deixa o nome partir linha no telefone sem
    // empurrar os números (Astra: *"o nome pode quebrar linha, mantendo as
    // outras duas colunas alinhadas"*).
    //
    // ⚠️ O cabeçalho das colunas é `aria-hidden`: cada linha diz TUDO no seu
    // `aria-label` (nome, quantidade, qualidade) — um leitor de ecrã não tem de
    // cruzar colunas para saber o que tem na mão.
    function ColecaoTabela({ titulo, n, colunas, linhas, topo, children }) {
      const P = NIV_ONDA;
      const tres = colunas.length === 3;
      const grade = tres ? "minmax(0,1fr) 5.6em 7.2em" : "minmax(0,1fr) 5.6em";
      const cab = { fontFamily: P.label, fontSize: 10, lineHeight: 1.6,
                    letterSpacing: ".16em", textTransform: "uppercase", color: P.muted };
      return (
        // ⚠️ 760 px no PC: a 1440 a coluna tem 1080 e uma linha esticada põe o
        // nome e o número em pontas opostas do ecrã (olhado a 30/09). No
        // telefone não morde. A composição fina das duas larguras é do Astra.
        <section className="colecao-tabela" style={{ marginBottom: 24, maxWidth: 760 }}>
          <div style={{ textAlign: "center", margin: "0 0 12px", fontFamily: P.label,
                        fontSize: 11, lineHeight: 1.6, letterSpacing: ".2em",
                        textTransform: "uppercase", color: P.gold }}>
            {titulo}
            <span style={Object.assign({}, _ONDA_TNUM, { marginLeft: 8, fontSize: 12,
                                                          letterSpacing: 0, color: P.muted })}>
              {fmtFull(n)}
            </span>
          </div>
          {topo || null}
          <div aria-hidden="true" style={{ display: "grid", gridTemplateColumns: grade,
                                           columnGap: 12, padding: "0 2px 6px" }}>
            {colunas.map((c, i) => (
              <span key={i} style={Object.assign({}, cab,
                              { textAlign: c.dir === "right" ? "right" : "left" })}>{c.rotulo}</span>
            ))}
          </div>
          <ul style={{ listStyle: "none", margin: 0, padding: 0,
                       borderBottom: "1px solid " + P.line }}>
            {linhas.map(l => (
              <li key={l.key}>
                <button type="button" onClick={l.onClick} aria-label={l.aria}
                        data-colecao-linha=""
                        style={{ display: "grid", gridTemplateColumns: grade, columnGap: 12,
                                 alignItems: "start", width: "100%", minHeight: 44,
                                 padding: "11px 2px", margin: 0, background: "transparent",
                                 border: 0, borderTop: "1px solid " + P.line, borderRadius: 0,
                                 color: P.paper, textAlign: "left", cursor: "pointer",
                                 fontFamily: P.body, boxShadow: "none" }}>
                  <span style={{ minWidth: 0 }}>
                    <span style={{ display: "block", fontSize: 14, lineHeight: (20 / 14),
                                   overflowWrap: "anywhere" }}>{l.nome}</span>
                    {l.sub ? (
                      <span style={{ display: "block", marginTop: 1, fontSize: 11.5,
                                     lineHeight: (16 / 11.5), color: P.muted }}>{l.sub}</span>
                    ) : null}
                  </span>
                  <span style={Object.assign({}, _ONDA_TNUM, {
                    fontSize: 14, lineHeight: (20 / 14), color: l.tom2 || P.paper,
                    textAlign: colunas[1].dir === "right" ? "right" : "left" })}>{l.c2}</span>
                  {tres && (
                    <span style={Object.assign({ fontSize: 12.5, lineHeight: (20 / 12.5),
                                                 color: P.muted, overflowWrap: "anywhere" },
                                               l.estilo3 || {})}>{l.c3}</span>
                  )}
                </button>
              </li>
            ))}
          </ul>
          {children}
        </section>
      );
    }

    // As LINHAS de cada família — o que vai em cada coluna.
    //   artefacto: nome (+ tipo, poder, reino) · grau · qualidade (o refino)
    //   pílula:    nome (+ grau da pílula, efeito temporário) · qtd · qualidade
    //   erva/minério/outro: nome · qtd (· raridade, só a armadilha a tem)
    // ⚠️ O artefacto não tem QUANTIDADE (cada linha é um exemplar, com o seu
    // cadeado, o seu espírito, o seu grau) — a 2.ª coluna dele é o GRAU.
    var _TIPO_ARTEFACTO_KEY = { weapon: "inv_card_slot_weapon", armor: "inv_card_slot_armor",
                                accessory: "inv_tab_tipo_acessorio" };
    function linhaArtefacto(a, onAbrir, playerRealm) {
      const cs = a.custom_stats || a.stats || {};
      const bp = Number(cs.battle_power) || 0;
      const minRealm = Number(a.min_realm || 0);
      const trancadoReino = minRealm > 0 && (Number(playerRealm) || 0) < minRealm;
      const v = GRADE_VISUALS[a.grade] || GRADE_VISUALS[0];
      const tipo = _TIPO_ARTEFACTO_KEY[a.type] ? t(_TIPO_ARTEFACTO_KEY[a.type]) : null;
      const partes = [tipo, bp ? t("inv_tab_poder", { n: fmtFull(bp) }) : null,
                      trancadoReino ? t("inv_card_realm_locked", { n: minRealm }) : null]
                     .filter(Boolean);
      const q = a.quality || "normal";
      const qTxt = t(ART_QUALITY_KEY[q] || "art_quality_normal");
      return {
        key: "a" + a.id,
        nome: (
          <>
            {a.name}
            {a.locked ? (
              <span style={{ marginLeft: 6, display: "inline-flex", verticalAlign: "-2px",
                             color: NIV_ONDA.muted }}>
                {ico("🔒", "lock", { size: 13, title: t("inv_tab_trancado") })}
              </span>
            ) : null}
          </>
        ),
        sub: partes.join(" · "),
        c2: "G" + (Number(a.grade) || 0), tom2: v.color,
        c3: qTxt, estilo3: q === "normal" ? null : artQualityChipStyle(q, NIV_ONDA.muted),
        aria: [a.name, "G" + (Number(a.grade) || 0), qTxt].concat(partes)
              .concat(a.locked ? [t("inv_tab_trancado")] : []).join(", "),
        onClick: () => onAbrir(a),
      };
    }
    function linhaItem(it, i, onAbrir) {
      const q = qualidadeDoItem(it);
      const qc = it.type === "pill" ? (QUALITY_COLOR[it.quality] || "var(--gold)") : null;
      const partes = it.type === "pill"
        ? [it.required_alchemy_tier ? t("inv_tab_grau_n", { n: it.required_alchemy_tier }) : null,
           it.is_timed ? t("inv_tab_temporaria") : null].filter(Boolean)
        : [];
      const qtd = fmtFull(it.quantity || 0);
      return {
        key: it.type + "_" + it.catalog_id + "_" + (it.quality || "") + "_" + i,
        nome: it.name,
        sub: partes.join(" · "),
        c2: qtd,
        c3: q, estilo3: qc ? { color: qc } : null,
        aria: [it.name, qtd, q].concat(partes).filter(Boolean).join(", "),
        onClick: () => onAbrir(it),
      };
    }

    // 💍 O ANEL — o corpo do sistema. A linha do Astra (Caverna · Inventário):
    // *"`ring.tier` e a melhoria confirmada expandem a inscrição do anel;
    // `can_upgrade/next_cost` governa a próxima expansão; `used_slots /
    // max_slots` é ocupação."* ⇒ o NÍVEL acende (conquista); a ocupação é um
    // fio com número (estado, nunca acende); a expansão diz antes→depois ANTES
    // do toque e o ganho confirmado DEPOIS.
    //
    // ⚠️ O denominador vem do servidor (`max_tier`, só com a onda). Sem ele não
    // se desenha inscrição nenhuma — "nível 3 de ?" não se inventa no cliente.
    // ⚠️ `ganho` é o `anel_ganho` de uma resposta `ok: true` — só o confirmado
    // acende, e reabrir a aba não repete (o estado vive nesta montagem).
    function AnelCorpo({ ring, pedras, busy, ganho, onExpandir }) {
      const P = NIV_ONDA;
      const max = Number(ring.max_tier) || 0;
      const g = ganho && ganho.tier ? ganho : null;
      const tierLido = Number(ring.tier) || 1;
      // O número muda AO RECEBER a confirmação, sem esperar pelo recarregar.
      const tier = g ? Math.max(tierLido, Number(g.tier.depois) || 0) : tierLido;
      const lugares = g ? Math.max(Number(ring.max_slots) || 0, Number(g.max_slots.depois) || 0)
                        : (Number(ring.max_slots) || 0);
      const usados = Number(ring.used_slots) || 0;
      // Enquanto a leitura não apanhou a confirmação, a PRÓXIMA expansão (preço
      // e meta) ainda é a de antes — não se oferece até o anel ser relido.
      const fresco = !g || tierLido >= (Number(g.tier.depois) || 0);
      const custo = ring.can_upgrade ? (Number(ring.next_cost) || 0) : null;
      const falta = custo != null && pedras != null ? Math.max(0, custo - pedras) : 0;
      const acendeTier = !!(g && (g.acende || []).indexOf("tier") >= 0);
      const marcas = [];
      for (let i = 1; i <= max; i++) marcas.push(i);
      const _feitos = Math.min(tier, max);
      const _passo = 34;
      return (
        <div data-anel-corpo="" style={{ margin: "0 0 22px", maxWidth: 760, fontFamily: P.body }}>
          <div style={{ fontFamily: P.label, fontSize: 11, lineHeight: 1.6, letterSpacing: ".2em",
                        textTransform: "uppercase", color: P.gold,
                        display: "flex", alignItems: "center", gap: 7 }}>
            {ico("💍", "ring", { size: 15 })}
            <span>{t("inv_ring_title")}</span>
          </div>
          <div style={Object.assign({}, _ONDA_TNUM, { marginTop: 4, fontSize: 16,
                                                      lineHeight: (22 / 16), color: P.paper })}>
            {max ? t("inv_ring_nivel_de", { tier: tier, max: max })
                 : t("inv_ring_tier", { tier: tier })}
          </div>
          {max > 0 && (
            <div aria-hidden="true" data-anel-inscricao=""
                 style={{ position: "relative", height: 40, marginTop: 10,
                          width: (max - 1) * _passo + 22 }}>
              {/* o TRAÇO: a estrutura inteira apagada, e o troço já conquistado a ouro */}
              <span style={{ position: "absolute", left: 11, top: 11, height: 1,
                             width: (max - 1) * _passo, background: "rgba(236,229,216,.22)" }} />
              {_feitos > 1 && (
                <span style={{ position: "absolute", left: 11, top: 11, height: 1,
                               width: (_feitos - 1) * _passo, background: "rgba(201,144,58,.85)" }} />
              )}
              {marcas.map(i => {
                const estado = i <= tier ? "got"
                             : (i === tier + 1 && ring.can_upgrade && fresco) ? "next" : "empty";
                return (
                  <span key={i} data-anel-nivel={estado}
                        style={{ position: "absolute", left: (i - 1) * _passo, top: 0,
                                 width: 22, height: 40 }}>
                    <span style={{ position: "absolute", left: 11, top: 11, width: 0, height: 0 }}>
                      <MarcaOnda estado={estado} acende={acendeTier && i === Number(g.tier.depois)} />
                    </span>
                    <span style={Object.assign({}, _ONDA_TNUM, {
                      position: "absolute", left: 0, right: 0, top: 24, textAlign: "center",
                      fontSize: 10, lineHeight: 1.4,
                      color: estado === "empty" ? "rgba(236,229,216,.45)" : P.paper })}>{i}</span>
                  </span>
                );
              })}
            </div>
          )}
          {/* a OCUPAÇÃO — estado reversível: um fio com número, sem luz */}
          <div style={{ marginTop: 10, padding: "10px 0 0", borderTop: "1px solid " + P.line }}>
            <div style={{ display: "flex", alignItems: "baseline", columnGap: 12 }}>
              <span style={{ fontFamily: P.label, fontSize: 10, lineHeight: 1.6,
                             letterSpacing: ".16em", textTransform: "uppercase", color: P.muted }}>
                {t("inv_ring_ocupacao")}
              </span>
              <span style={Object.assign({}, _ONDA_TNUM, {
                marginLeft: "auto", fontSize: 14, lineHeight: (20 / 14),
                color: usados >= lugares * 0.9 ? P.seal : P.paper })}>
                {t("inv_ring_lugares_n", { used: fmtFull(usados), max: fmtFull(lugares) })}
              </span>
            </div>
            <div style={{ marginTop: 6, height: 2, background: P.line }}>
              <div style={{ height: "100%",
                            width: Math.min(100, (usados / Math.max(1, lugares)) * 100) + "%",
                            background: usados >= lugares * 0.9 ? P.seal : P.muted }} />
            </div>
          </div>
          {g && (
            <div data-anel-ganho="" style={Object.assign({}, _ONDA_TNUM, {
              marginTop: 12, fontSize: 13, lineHeight: (20 / 13), color: P.gold })}>
              {t("inv_ring_ganho", { t0: g.tier.antes, t1: g.tier.depois,
                                     m0: fmtFull(g.max_slots.antes), m1: fmtFull(g.max_slots.depois) })}
            </div>
          )}
          {!ring.can_upgrade ? (
            <div style={{ marginTop: 12, fontSize: 12.5, lineHeight: (18 / 12.5), color: P.muted }}>
              {t("inv_ring_limite")}
            </div>
          ) : fresco ? (
            <div style={{ marginTop: 14 }}>
              <OndaBtn kind="ghost" disabled={busy || falta > 0} onClick={onExpandir}>
                {ring.next_max_slots
                  ? t("inv_ring_expandir", { antes: fmtFull(lugares), depois: fmtFull(ring.next_max_slots) })
                  : t("inv_ring_expand_btn", { tier: tier + 1, cost: fmtFull(custo || 0) })}
              </OndaBtn>
              <div style={Object.assign({}, _ONDA_TNUM, { marginTop: 6, fontSize: 12,
                                                          lineHeight: (18 / 12), textAlign: "center",
                                                          color: falta > 0 ? P.seal : P.muted })}>
                {falta > 0 ? t("inv_ring_faltam", { n: fmtFull(falta) })
                           : t("inv_ring_custo", { cost: fmtFull(custo || 0) })}
              </div>
            </div>
          ) : null}
        </div>
      );
    }

    // "Mostrar mais" dentro de uma tabela da onda. A mochila pagina a 32 desde
    // 24/05 (o report da [jogador]: 800+ artefactos) — a tabela mantém o passo, e o
    // botão fala a pele da onda (sem a seta de sistema, que a catraca do §15
    // conta como emoji).
    function MaisLinhas({ total, limite, onMais, onTudo }) {
      const resto = (Number(total) || 0) - (Number(limite) || 0);
      if (resto <= 0) return null;
      return (
        <div style={{ marginTop: 12, display: "flex", flexDirection: "column", gap: 4 }}>
          <OndaBtn kind="ghost" onClick={onMais}>
            {t("inv_load_more", { n: Math.min(32, resto) })}
          </OndaBtn>
          {resto > 32 && (
            <button type="button" onClick={onTudo}
                    style={{ alignSelf: "center", background: "transparent", border: 0,
                             padding: "10px 4px", color: NIV_ONDA.muted, boxShadow: "none",
                             fontFamily: NIV_ONDA.body, fontSize: 12, lineHeight: (18 / 12),
                             textDecoration: "underline", textUnderlineOffset: 4,
                             cursor: "pointer" }}>
              {t("inv_load_all", { n: fmtFull(total) })}
            </button>
          )}
        </div>
      );
    }

    function InventoryTab({ player, onPlayerRefresh }) {
      const [reload, setReload] = useState(0);
      const { data, loading, error } = useApi("inventory", null, [reload]);
      const [modal, setModal] = useState(null);
      const [ringBusy, setRingBusy] = useState(false);   // fix 2026-07-14 — upgrade do anel
      // 2026-05-24 ([jogador] report): inventory was hardcoded `.slice(0, 32)` —
      // players with 800+ artifacts after mass-craft had freshly-acquired items
      // (incl. spirit-awakened ones at the tail) invisible. Load-More progressive
      // reveal lets them reach any item without first dismantling the rest.
      const [stashLimit, setStashLimit] = useState(32);
      const [itemListLimit, setItemListLimit] = useState(32);
      // MA-32b — owner request: "o jogador pode separar em categoria por
      // tiers G etc". Filter ring contents by grade. "all" = everything.
      const [gradeFilter, setGradeFilter] = useState("all");
      // v14.12b — owner feedback 2026-05-23: "Pílulas têm que estar
      // separadas na mochila — todos por grades etc". Pills don't have
      // a catalog grade (PillCatalog has no `grade` column) — the grade
      // concept for pills is the per-instance `quality` (Normal/High/
      // Perfect/Divine/Heavenly). Filter is per-quality.
      const [pillQualityFilter, setPillQualityFilter] = useState("all");
      // v14.13d (2026-05-25) — Owner round 2026-05-24: "mochila ficou feia".
      // Structural polish (NOT speculative styling per memory
      // feedback_dont_redesign_blind): SegControl section navigator at top
      // collapses the stacked-cards layout into one focused section at a
      // time. "All" preserves the original full view for backwards-compat.
      const [section, setSection] = useState("all");
      // Per-section sort. "smart" default = grade-desc for artifacts/pills,
      // count-desc for herbs/ores. Owner: "sort buttons smaller↔larger / by tier".
      const [sortBy, setSortBy] = useState("smart");
      // Bulk Dismantle moved here from ForgePanel (owner request 2026-05-06
      // round 4): "esse bunk deveria ser no inventario. a forja e alquimia
      // so pra forjar mesmo".
      const [showBulkDismantle, setShowBulkDismantle] = useState(false);
      // 🎒 3.2 — o ganho CONFIRMADO da última expansão do anel (`anel_ganho`
      // de uma resposta `ok: true`). Vive nesta montagem: reabrir a aba não
      // repete a conquista. ⚠️ Declarado ANTES dos `return` de baixo (#310).
      const [anelGanho, setAnelGanho] = useState(null);
      const tabela = obraOn();
      // Reset limits when filters change so player doesn't carry a fat list
      // from one filter state into another (perf + UX consistency).
      useEffect(() => { setStashLimit(32); }, [section, gradeFilter, sortBy]);
      useEffect(() => { setItemListLimit(32); }, [section, pillQualityFilter, sortBy]);
      const handleActionDone = () => {
        setReload(x => x + 1);
        onPlayerRefresh && onPlayerRefresh();
      };
      // Fix 2026-07-14 (report [jogador] "preso em 50"): o upgrade só existia
      // no chat. 🎒 3.2 — saiu do `onClick` para ser UM só: o botão de hoje e o
      // corpo do anel da onda chamam o mesmo. Com a onda o servidor manda
      // `anel_ganho`, e só uma resposta `ok: true` o guarda.
      const expandirAnel = async () => {
        if (ringBusy) return;
        setRingBusy(true);
        haptic("select");
        try {
          const res = await api("inventory/ring_upgrade", {});
          if (res && res.ok) {
            haptic("success");
            if (res.ok === true && res.anel_ganho) setAnelGanho(res.anel_ganho);
            showToast(t("inv_ring_expand_ok", { max: res.max_slots }));
            setReload(x => x + 1);
            onPlayerRefresh && onPlayerRefresh();
          } else if (res && res.reason === "not_enough_stones") {
            showToast(t("inv_ring_expand_no_stones", { cost: fmtNum(res.cost || 0) }), "err");
          } else if (res && res.reason === "ring_max") {
            showToast(t("inv_ring_expand_max"), "err");
            setReload(x => x + 1);
          } else {
            showToast(t("inv_ring_expand_fail"), "err");
          }
        } finally { setRingBusy(false); }
      };
      // BUGFIX 2026-07-27 ([jogador], s2): only skeleton on the FIRST load. On a
      // background refetch (after unlock/dismantle/any action) useApi keeps the
      // old `data` (ui.js:88 spreads state), so blanking to GridSkeleton here
      // used to UNMOUNT the open DetailModal → it remounted from a STALE snapshot
      // (locked:true) and the optimistic setLockedState(false) was destroyed →
      // "unlock does nothing / dismantle still blocked". Keeping stale data
      // during reload leaves the modal mounted and its state intact (DB was
      // already committed). Pure UX fix (no state/balance change) — all players.
      if (loading && !data) return <GridSkeleton slots={16} />;
      if (error) return <ErrBanner msg={error} />;

      // Only weapon/armor/accessory1/accessory2 fill the visible 4-slot grid.
      // Bot equip flow caps accessories at 2; mount/cauldron live elsewhere.
      const equipped = data.artifacts.filter(a => a.is_equipped && EQUIPPABLE_SLOTS.has(a.slot));
      const stash = data.artifacts.filter(a => !a.is_equipped);
      // Distinct grades present in the stash (for the filter SegControl).
      // Showing "G7" when player has zero G7 items would be a dead button —
      // hide grades that aren't represented.
      const presentGrades = Array.from(new Set(stash.map(a => a.grade))).sort((x, y) => x - y);
      const gradeOptions = [
        { value: "all", label: t("inv_filter_all") },
        ...presentGrades.map(g => {
          const v = GRADE_VISUALS[g] || GRADE_VISUALS[0];
          return { value: String(g), label: t("inv_filter_grade", { n: g }), color: v.color };
        }),
      ];
      const stashFiltered = gradeFilter === "all"
        ? stash
        : stash.filter(a => String(a.grade) === gradeFilter);
      // Order equipped consistently so empty slots show in a predictable order.
      const SLOT_ORDER = ["weapon", "armor", "accessory1", "accessory2"];
      const bySlot = Object.fromEntries(equipped.map(a => [a.slot, a]));
      // Owner request 2026-05-08: when opening a non-equipped artifact, attach
      // the equipped artifact of the SAME slot type so DetailModal can render
      // green/red stat deltas. For accessories we compare against the cheapest
      // (lowest BP) equipped accessory the player would replace — best-case UX
      // is "if I equip this, what do I lose?". Equipped artifacts have no
      // comparedTo (you can't compare a thing to itself).
      const openArtifact = (a) => {
        haptic("light");
        let comparedTo = null;
        if (!a.is_equipped) {
          if (a.type === "weapon" && bySlot.weapon) comparedTo = bySlot.weapon;
          else if (a.type === "armor" && bySlot.armor) comparedTo = bySlot.armor;
          else if (a.type === "accessory") {
            const accs = [bySlot.accessory1, bySlot.accessory2].filter(Boolean);
            // pick the weakest accessory (smallest BP) — that's the one the
            // player would want to swap out if they equip this incoming piece
            if (accs.length > 0) {
              comparedTo = accs.reduce((min, x) =>
                ((x.battle_power_total || 0) < (min.battle_power_total || 0)) ? x : min, accs[0]);
            }
          }
        }
        setModal({ kind:"artifact", ...a, comparedTo });
      };
      const openItem = (it) => { haptic("light"); setModal({ kind:"item", ...it }); };

      // v14.13d sort: produces a sorted copy of items per active sort.
      // Sort key behavior:
      //   smart    — by-grade-desc (artifacts/pills) OR by-count-desc (herbs/ores)
      //   tier_desc — by grade/quality descending
      //   tier_asc  — by grade/quality ascending
      //   count_desc — by quantity descending (only for stackable items)
      //   count_asc  — by quantity ascending
      const _QUALITY_RANK = { normal:0, high:1, perfect:2, divine:3, heavenly:4 };
      const _gradeOf = (a) => a.grade ?? 0;
      const _qualityRankOf = (it) => _QUALITY_RANK[it.quality] ?? 0;
      const sortItems = (arr, kind) => {
        const out = [...arr];
        if (sortBy === "smart") {
          // 2026-05-24: secondary key = newer first (id desc) so freshly
          // crafted/bought items appear at the top of their grade bucket.
          // [jogador] report: with 800+ artifacts, the freshly-Spirit-awakened
          // one was hidden because grade-only sort left it deep in the tail.
          if (kind === "artifacts") out.sort((a,b) => (_gradeOf(b) - _gradeOf(a)) || ((b.id || 0) - (a.id || 0)));
          else if (kind === "pills") out.sort((a,b) => _qualityRankOf(b) - _qualityRankOf(a));
          else out.sort((a,b) => (b.quantity || 0) - (a.quantity || 0));
        } else if (sortBy === "tier_desc") {
          if (kind === "artifacts") out.sort((a,b) => _gradeOf(b) - _gradeOf(a));
          else if (kind === "pills") out.sort((a,b) => _qualityRankOf(b) - _qualityRankOf(a));
          else out.sort((a,b) => (b.tier || 0) - (a.tier || 0));
        } else if (sortBy === "tier_asc") {
          if (kind === "artifacts") out.sort((a,b) => _gradeOf(a) - _gradeOf(b));
          else if (kind === "pills") out.sort((a,b) => _qualityRankOf(a) - _qualityRankOf(b));
          else out.sort((a,b) => (a.tier || 0) - (b.tier || 0));
        } else if (sortBy === "count_desc") {
          out.sort((a,b) => (b.quantity || 0) - (a.quantity || 0));
        } else if (sortBy === "count_asc") {
          out.sort((a,b) => (a.quantity || 0) - (b.quantity || 0));
        } else if (sortBy === "name_asc") {
          // U4 (v16.6): alphabetical — works for all kinds (every item has `name`).
          out.sort((a,b) => (a.name || "").localeCompare(b.name || ""));
        } else if (sortBy === "name_desc") {
          out.sort((a,b) => (b.name || "").localeCompare(a.name || ""));
        }
        return out;
      };
      const sortedStash = sortItems(stashFiltered, "artifacts");

      const invCards = typeof featureEnabled === "function" && featureEnabled("cartas");

      // 印 As quatro seccoes da mochila sao os UNICOS botoes do jogo que nunca
      // tiveram palavra nenhuma — so' um emoji. Com marcas isso deixaria de
      // anunciar seja o que for a um leitor de ecra, portanto cada uma leva
      // `title` (⇒ `role="img"` + `aria-label`) com o nome que a seccao ja' tem
      // na i18n. E' o unico sitio deste lote onde a iconografia MELHORA a
      // acessibilidade em vez de so' a manter (Lei §1).
      const SECTIONS = [
        { value:"all",        label: t("inv_section_all") },
        { value:"equipment",  label: ico("⚔️", "sword",  { size:15, title:t("equipped") }) },
        { value:"pills",      label: ico("💊", "gourd",  { size:15, title:t("inv_section_pills") }) },
        { value:"herbs",      label: ico("🌿", "herb",   { size:15, title:t("inv_section_herbs") }) },
        { value:"ores",       label: ico("🪨", "stone",  { size:15, title:t("inv_section_ores") }) },
      ];
      const sortOptions = [
        { value:"smart",      label: t("inv_sort_smart") },
        { value:"tier_desc",  label: t("inv_sort_tier_desc") },
        { value:"tier_asc",   label: t("inv_sort_tier_asc") },
        { value:"count_desc", label: t("inv_sort_count_desc") },
        { value:"count_asc",  label: t("inv_sort_count_asc") },
        { value:"name_asc",   label: t("inv_sort_name_asc") },   // U4 (v16.6)
        { value:"name_desc",  label: t("inv_sort_name_desc") },
      ];
      const showAll = section === "all";

      return (
        <div>
          {/* v14.13d — Section navigator + sort. "All" preserves the full
              stacked layout (back-compat); other choices focus one section. */}
          <Card style={{ padding:"10px 12px", marginBottom:9 }}>
            <SegControl options={SECTIONS} value={section} onChange={(v) => { haptic("select"); setSection(v); }} />
            <div style={{ marginTop:8 }}>
              <div style={{ fontSize:9, color:"var(--muted)", letterSpacing:.5,
                            textTransform:"uppercase", marginBottom:4,
                            fontFamily:"'Cinzel',serif" }}>
                {t("inv_sort_label")}
              </div>
              <SegControl options={sortOptions} value={sortBy} onChange={(v) => { haptic("light"); setSortBy(v); }} />
            </div>
          </Card>

          {(showAll || section === "equipment") && (
          <CardHost cards={invCards} title={t("equipped")}
                    right={`${equipped.length}/${EQUIPPED_MAX}`}>
            <InvGrid cards={invCards}>
              {SLOT_ORDER.map(s => {
                const a = bySlot[s];
                if (a) return <ArtifactCell key={s} a={a} equipped onClick={() => openArtifact(a)} playerRealm={player?.realm} />;
                // Empty slot — show the canonical silhouette as a hint of
                // what goes here, dimmed so it's clearly unfilled.
                // 牌 2026-09-08 — com `cartas` ON o slot vazio passa a DIZER o
                // que lá vai, por palavras. Até hoje era um quadrado tracejado
                // com 🥋 lá dentro e mais nada: o jogador tinha de adivinhar que
                // aquele emoji significava "armadura", e em três línguas. Lei §1
                // — um estado vazio tem direito a disclosure honesta, não a um
                // pictograma. A carta-fantasma (`unowned`) já existia sem uso.
                if (invCards) {
                  return (
                    <NivraelCard key={s}
                      glyph={SLOT_ICONS[s]}
                      name={t("inv_card_slot_" + s)}
                      eyebrow={t("inv_card_kind_artifact")}
                      state="unowned"
                      stateLabel={t("inv_card_slot_empty")} />
                  );
                }
                return (
                  <div key={s} style={{
                    aspectRatio:1, background:"rgba(0,0,0,.25)",
                    border:"1px dashed rgba(var(--glow-rgb),.3)", borderRadius:8,
                    display:"grid", placeItems:"center", opacity:.4,
                  }}>
                    <span style={{ fontSize:20, opacity:.55, display:markOn(SLOT_MARKS[s]) ? "grid" : undefined,
                                   placeItems:markOn(SLOT_MARKS[s]) ? "center" : undefined }}>{slotIco(s, null, 22)}</span>
                  </div>
                );
              })}
            </InvGrid>
          </CardHost>
          )}

          {/* v14.12b — owner feedback 2026-05-23: "deveria poner o space
              max da mochila". Bag capacity card on top: used / max + tier
              hint. Reads from `data.ring` enriched in api_inventory. */}
          {(showAll || section === "equipment") && data.ring && tabela && (
            <AnelCorpo ring={data.ring} busy={ringBusy} ganho={anelGanho}
                       onExpandir={expandirAnel}
                       pedras={player && typeof player.spirit_stones === "number"
                                 ? player.spirit_stones : null} />
          )}
          {(showAll || section === "equipment") && data.ring && !tabela && (
            <Card style={{ padding:"10px 12px", marginBottom:9 }}>
              <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between" }}>
                <div>
                  <div style={{ fontFamily:"'Cinzel',serif", fontSize:11,
                                letterSpacing:.4, textTransform:"uppercase",
                                color:"var(--gold2)" }}>
                    💍 {t("inv_ring_title")}
                  </div>
                  <div style={{ fontSize:10, color:"var(--muted)", marginTop:2 }}>
                    {t("inv_ring_tier", { tier: data.ring.tier })}
                  </div>
                </div>
                <div style={{ textAlign:"right" }}>
                  <div style={{ fontFamily:"'Cinzel',serif", fontWeight:700,
                                fontSize:15,
                                color: data.ring.used_slots >= data.ring.max_slots * 0.9
                                  ? "var(--warn)" : "var(--gold3)" }}>
                    {data.ring.used_slots}/{data.ring.max_slots}
                  </div>
                  <div style={{ fontSize:10, color:"var(--muted)" }}>
                    {t("inv_ring_slots")}
                  </div>
                </div>
              </div>
              <div style={{ marginTop:7, height:5, borderRadius:3,
                            background:"rgba(0,0,0,.55)", overflow:"hidden" }}>
                <div style={{
                  width: `${Math.min(100, (data.ring.used_slots / Math.max(1, data.ring.max_slots)) * 100)}%`,
                  height:"100%",
                  background: data.ring.used_slots >= data.ring.max_slots * 0.9
                    ? "linear-gradient(90deg,var(--warn),var(--red))"
                    : "linear-gradient(90deg,var(--gold2),var(--gold3))",
                  transition:"width .3s ease",
                }} />
              </div>
              {/* Fix 2026-07-14 (report [jogador] "preso em 50"): o upgrade só
                  existia no chat — o card era display-only. Botão espelha o
                  fluxo do /inventario; server valida custo/tier. */}
              {data.ring.can_upgrade && (
                <button onClick={expandirAnel}
                        disabled={ringBusy}
                        style={{
                          marginTop:8, width:"100%", padding:"8px 10px", borderRadius:8,
                          background:"rgba(var(--gold-rgb),.14)", border:"1px solid rgba(var(--gold2-rgb),.45)",
                          color:"var(--gold2)", fontFamily:"inherit", fontSize:11.5, fontWeight:700,
                          cursor:"pointer", opacity: ringBusy ? .55 : 1,
                        }}>
                  💍 {t("inv_ring_expand_btn", { tier: data.ring.tier + 1, cost: fmtNum(data.ring.next_cost || 0) })}
                </button>
              )}
            </Card>
          )}

          {/* 🎒 3.2 — a pilha do anel, em TABELA (a carta abre ao tocar). */}
          {(showAll || section === "equipment") && tabela && (
            stash.length === 0 ? (
              <div style={{ margin: "0 0 24px", textAlign: "center", fontFamily: NIV_ONDA.body,
                            fontSize: 13, color: NIV_ONDA.muted }}>
                <div style={{ fontFamily: NIV_ONDA.label, fontSize: 11, letterSpacing: ".2em",
                              textTransform: "uppercase", color: NIV_ONDA.gold, marginBottom: 8 }}>
                  {t("inv_tab_titulo_artefatos")}
                </div>
                {t("empty")}
              </div>
            ) : (
              <ColecaoTabela
                titulo={t("inv_tab_titulo_artefatos")} n={stashFiltered.length}
                colunas={[{ rotulo: t("inv_card_kind_artifact") },
                          { rotulo: t("inv_tab_col_grau") },
                          { rotulo: t("inv_tab_col_qualidade") }]}
                linhas={sortedStash.slice(0, stashLimit).map(a => linhaArtefacto(a, openArtifact, player?.realm))}
                topo={presentGrades.length > 1 ? (
                  <div style={{ marginBottom: 10 }}>
                    <SegControl options={gradeOptions} value={gradeFilter} onChange={setGradeFilter} />
                  </div>
                ) : null}>
                {sortedStash.length === 0 && (
                  <div style={{ padding: "14px 0", textAlign: "center", fontSize: 12,
                                color: NIV_ONDA.muted }}>{t("inv_filter_empty")}</div>
                )}
                <MaisLinhas total={sortedStash.length} limite={stashLimit}
                            onMais={() => { haptic("light"); setStashLimit(x => x + 32); }}
                            onTudo={() => { haptic("light"); setStashLimit(sortedStash.length); }} />
                {stash.some(a => !a.locked) && (
                  <div style={{ marginTop: 12 }}>
                    {/* destrutiva: o cinábrio da paleta, como o vermelho de hoje */}
                    <OndaBtn kind="ghost" onClick={() => { haptic("select"); setShowBulkDismantle(true); }}
                             style={{ color: NIV_ONDA.seal, border: "1px solid rgba(200,68,47,.5)" }}>
                      {t("forge_bulk_dismantle_btn")}
                    </OndaBtn>
                  </div>
                )}
              </ColecaoTabela>
            )
          )}
          {(showAll || section === "equipment") && !tabela && (
          <CardHost cards={invCards} title={t("spatial_ring")}
                    right={`${stashFiltered.length}${gradeFilter !== "all" ? ` / ${stash.length}` : ""}`}>
            {stash.length === 0 ? (
              <div style={{ textAlign:"center", padding:"24px 0", color:"var(--muted)", fontSize:12 }}>{t("empty")}</div>
            ) : (
              <>
                {presentGrades.length > 1 && (
                  <div style={{ marginBottom:8 }}>
                    <SegControl options={gradeOptions} value={gradeFilter} onChange={setGradeFilter} />
                  </div>
                )}
                {sortedStash.length === 0 ? (
                  <div style={{ textAlign:"center", padding:"18px 0", color:"var(--muted)", fontSize:12 }}>
                    {t("inv_filter_empty")}
                  </div>
                ) : (
                  <InvGrid cards={invCards}>
                    {sortedStash.slice(0, stashLimit).map(a => <ArtifactCell key={a.id} a={a} onClick={() => openArtifact(a)} playerRealm={player?.realm} />)}
                    {sortedStash.length > stashLimit && (
                      <div style={{ gridColumn:"1/-1", marginTop:8, display:"flex", flexDirection:"column", gap:6, alignItems:"center" }}>
                        <button onClick={() => { haptic("light"); setStashLimit(x => x + 32); }}
                                style={{
                                  padding:"6px 14px", borderRadius:8, cursor:"pointer",
                                  background:"rgba(var(--gold-rgb),.10)", border:"1px solid rgba(var(--gold-rgb),.35)",
                                  color:"var(--gold2)", fontSize:11.5, fontFamily:"'Cinzel',serif",
                                  letterSpacing:.4, fontWeight:600,
                                }}>
                          ⬇ {t("inv_load_more", { n: Math.min(32, sortedStash.length - stashLimit) })} ({sortedStash.length - stashLimit})
                        </button>
                        {sortedStash.length - stashLimit > 32 && (
                          <button onClick={() => { haptic("light"); setStashLimit(sortedStash.length); }}
                                  style={{
                                    padding:"4px 10px", borderRadius:6, cursor:"pointer",
                                    background:"transparent", border:"1px solid rgba(var(--muted-rgb),.4)",
                                    color:"var(--muted)", fontSize:10.5, fontFamily:"'Cinzel',serif",
                                  }}>
                            {t("inv_load_all", { n: sortedStash.length })}
                          </button>
                        )}
                      </div>
                    )}
                  </InvGrid>
                )}
                {/* Bulk Dismantle CTA — only visible when there's something to dismantle */}
                {stash.some(a => !a.locked) && (
                  <button onClick={() => { haptic("select"); setShowBulkDismantle(true); }}
                          style={{
                            marginTop:10, width:"100%", padding:"9px 10px", borderRadius:8, cursor:"pointer",
                            background:"rgba(var(--red-rgb),.08)", border:"1px solid rgba(var(--red-rgb),.3)",
                            color:"var(--red2)", fontSize:11.5, fontFamily:"'Cinzel',serif",
                            letterSpacing:.6, fontWeight:700, textTransform:"uppercase",
                            display:"flex", alignItems:"center", justifyContent:"center", gap:6,
                          }}>
                    ♻️ {t("forge_bulk_dismantle_btn")}
                  </button>
                )}
              </>
            )}
          </CardHost>
          )}

          {/* v14.12b — owner feedback 2026-05-23: split items by category
              with Cinzel section headers + per-category counts. Pill section
              gains its own grade filter (mirror artifact path MA-32b).
              v14.13d — Sections gated by SegControl navigator + sorted via
              sortItems kind dispatch. */}
          {(() => {
            const pillsRaw = (data.items || []).filter(it => it.type === "pill");
            const herbsRaw = (data.items || []).filter(it => it.type === "herb");
            const oresRaw  = (data.items || []).filter(it => it.type === "ore");
            const otherRaw = (data.items || []).filter(it => !["pill","herb","ore"].includes(it.type));
            const pills = sortItems(pillsRaw, "pills");
            const herbs = sortItems(herbsRaw, "items");
            const ores  = sortItems(oresRaw, "items");
            const other = sortItems(otherRaw, "items");
            // Pill "quality" (per-instance) is the user-facing grade for pills.
            // Order: normal → high → perfect → divine → heavenly.
            const _QUALITY_ORDER = ["normal", "high", "perfect", "divine", "heavenly"];
            const _QUALITY_LABEL = {
              normal:   t("pill_quality_normal"),
              high:     t("pill_quality_high"),
              perfect:  t("pill_quality_perfect"),
              divine:   t("pill_quality_divine"),
              heavenly: t("pill_quality_heavenly"),
            };
            const qualitiesPresent = _QUALITY_ORDER.filter(q =>
              pills.some(p => (p.quality || "normal") === q)
            );
            const pillQualityOpts = [
              { value:"all", label: t("inv_filter_all") },
              ...qualitiesPresent.map(q => ({ value: q, label: _QUALITY_LABEL[q] || q })),
            ];
            const pillsFiltered = pillQualityFilter === "all"
              ? pills
              : pills.filter(p => (p.quality || "normal") === pillQualityFilter);

            // 🎒 3.2 — com a onda, cada família é uma TABELA. O TIPO sobe para o
            // cabeçalho (a 1.ª coluna chama-se "Pílula", "Erva"…) e a coluna da
            // qualidade só existe onde a qualidade existe: na pílula sempre, nos
            // "outros" só quando há uma armadilha (a única com raridade).
            const _TAB_TITULO = { inv_section_pills: "inv_tab_titulo_pilulas",
                                  inv_section_herbs: "inv_tab_titulo_ervas",
                                  inv_section_ores:  "inv_tab_titulo_minerios",
                                  inv_section_other: "inv_tab_titulo_outros" };
            const _TAB_TIPO = { inv_section_pills: "inv_card_kind_pill",
                                inv_section_herbs: "inv_card_kind_herb",
                                inv_section_ores:  "inv_card_kind_ore",
                                inv_section_other: "inv_card_kind_item" };
            const renderSection = (titleKey, accent, list, emptyKey, headerExtra) => {
              if (list.length === 0) return null;
              if (tabela) {
                const comQualidade = list.some(it => qualidadeDoItem(it) != null);
                const colunas = [{ rotulo: t(_TAB_TIPO[titleKey] || "inv_card_kind_item") },
                                 { rotulo: t("inv_tab_col_qtd"), dir: "right" }]
                                .concat(comQualidade ? [{ rotulo: t("inv_tab_col_qualidade") }] : []);
                return (
                  <ColecaoTabela
                    titulo={t(_TAB_TITULO[titleKey] || titleKey)} n={list.length}
                    colunas={colunas} topo={headerExtra || null}
                    linhas={list.slice(0, itemListLimit).map((it, i) => linhaItem(it, i, openItem))}>
                    <MaisLinhas total={list.length} limite={itemListLimit}
                                onMais={() => { haptic("light"); setItemListLimit(x => x + 32); }}
                                onTudo={() => { haptic("light"); setItemListLimit(list.length); }} />
                  </ColecaoTabela>
                );
              }
              return (
                <CardHost cards={invCards} title={t(titleKey)} right={list.length}
                          style={invCards ? undefined : { marginBottom:9 }}>
                  {headerExtra}
                  <InvGrid cards={invCards}>
                    {list.slice(0, itemListLimit).map((it, i) => (
                      <ItemCell key={`${it.type}_${it.catalog_id}_${i}`} it={it}
                                onClick={() => openItem(it)} />
                    ))}
                    {list.length > itemListLimit && (
                      <div style={{ gridColumn:"1/-1", marginTop:8, display:"flex", flexDirection:"column", gap:6, alignItems:"center" }}>
                        <button onClick={() => { haptic("light"); setItemListLimit(x => x + 32); }}
                                style={{
                                  padding:"6px 14px", borderRadius:8, cursor:"pointer",
                                  background:"rgba(var(--gold-rgb),.10)", border:"1px solid rgba(var(--gold-rgb),.35)",
                                  color:"var(--gold2)", fontSize:11.5, fontFamily:"'Cinzel',serif",
                                  letterSpacing:.4, fontWeight:600,
                                }}>
                          ⬇ {t("inv_load_more", { n: Math.min(32, list.length - itemListLimit) })} ({list.length - itemListLimit})
                        </button>
                        {list.length - itemListLimit > 32 && (
                          <button onClick={() => { haptic("light"); setItemListLimit(list.length); }}
                                  style={{
                                    padding:"4px 10px", borderRadius:6, cursor:"pointer",
                                    background:"transparent", border:"1px solid rgba(var(--muted-rgb),.4)",
                                    color:"var(--muted)", fontSize:10.5, fontFamily:"'Cinzel',serif",
                                  }}>
                            {t("inv_load_all", { n: list.length })}
                          </button>
                        )}
                      </div>
                    )}
                  </InvGrid>
                </CardHost>
              );
            };

            const pillsHeader = pills.length > 0 && qualitiesPresent.length > 1 ? (
              <div style={{ marginBottom:8 }}>
                <SegControl options={pillQualityOpts}
                            value={pillQualityFilter}
                            onChange={setPillQualityFilter} />
              </div>
            ) : null;

            if ((data.items || []).length === 0) {
              return (
                <Card>
                  <CardTitle left={t("items")} right={0} />
                  <div style={{ textAlign:"center", padding:"24px 0",
                                color:"var(--muted)", fontSize:12 }}>
                    {t("no_items")}
                  </div>
                </Card>
              );
            }
            return (
              <>
                {(showAll || section === "pills") &&
                  renderSection("inv_section_pills", "💊", pillsFiltered, null, pillsHeader)}
                {(showAll || section === "pills") && pills.length > 0
                  && pillsFiltered.length === 0 && pillQualityFilter !== "all" && (
                  <Card>
                    <div style={{ textAlign:"center", padding:"14px 0",
                                  color:"var(--muted)", fontSize:11 }}>
                      {t("inv_filter_empty")}
                    </div>
                  </Card>
                )}
                {(showAll || section === "herbs") &&
                  renderSection("inv_section_herbs", "🌿", herbs)}
                {(showAll || section === "ores") &&
                  renderSection("inv_section_ores", "🪨", ores)}
                {showAll && other.length > 0 && renderSection("inv_section_other", "📦", other)}
                {/* Empty-state when section selected and nothing in it */}
                {!showAll && section === "pills" && pills.length === 0 && (
                  <Card>
                    <div style={{ textAlign:"center", padding:"24px 0", color:"var(--muted)", fontSize:12,
                                  ...(markOn("gourd") ? { display:"flex", alignItems:"center",
                                                        justifyContent:"center", gap:7 } : {}) }}>
                      {ico("💊", "gourd", { size:16 })} {t("no_items")}
                    </div>
                  </Card>
                )}
                {!showAll && section === "herbs" && herbs.length === 0 && (
                  <Card>
                    <div style={{ textAlign:"center", padding:"24px 0", color:"var(--muted)", fontSize:12,
                                  ...(markOn("herb") ? { display:"flex", alignItems:"center",
                                                        justifyContent:"center", gap:7 } : {}) }}>
                      {ico("🌿", "herb", { size:16 })} {t("no_items")}
                    </div>
                  </Card>
                )}
                {!showAll && section === "ores" && ores.length === 0 && (
                  <Card>
                    <div style={{ textAlign:"center", padding:"24px 0", color:"var(--muted)", fontSize:12,
                                  ...(markOn("stone") ? { display:"flex", alignItems:"center",
                                                        justifyContent:"center", gap:7 } : {}) }}>
                      {ico("🪨", "stone", { size:16 })} {t("no_items")}
                    </div>
                  </Card>
                )}
                {!showAll && section === "equipment" && stash.length === 0 && equipped.length === 0 && (
                  <Card>
                    <div style={{ textAlign:"center", padding:"24px 0", color:"var(--muted)", fontSize:12 }}>
                      ⚔️ {t("empty")}
                    </div>
                  </Card>
                )}
              </>
            );
          })()}

          {modal && <DetailModal entry={modal} onClose={() => setModal(null)} onActionDone={handleActionDone} player={player} />}
          {showBulkDismantle && (
            <BulkDismantleModal
              onClose={() => setShowBulkDismantle(false)}
              onDone={() => { /* keep open so player can chain dismantles */ }}
              refreshData={() => { setReload(x => x + 1); onPlayerRefresh && onPlayerRefresh(); }} />
          )}
        </div>
      );
    }

    // ─── World Boss Tab ──────────────────────────────────────────────────────
    // ─── Boss Rankings (v14.7 Item 3) ────────────────────────────────────────
    // Drill-in modal showing damage rankings for ALL bosses across the 3
    // tiers (mortal/spirit/immortal × 3 = 9). Each boss surfaces top-10
    // damage dealers from its most recent spawn, plus active/expired
    // state and the next scheduled spawn (Wed/Sat 18:00 UTC).
    function BossRankingsModal({ onClose }) {
      const { data, loading, error } = useApi("boss/rankings", null, []);
      const [activeTier, setActiveTier] = useState(null);
      const [now, setNow] = useState(Date.now());
      useVisibleInterval(() => setNow(Date.now()), 1000);

      // Default expanded tier = the player's tier when data lands.
      useEffect(() => {
        if (data && activeTier == null) setActiveTier(data.player_tier || "mortal");
      }, [data, activeTier]);

      const tierLabel = {
        mortal:   t("boss_tier_mortal"),
        spirit:   t("boss_tier_spirit"),
        immortal: t("boss_tier_immortal"),
      };

      function tierOptions(tiers) {
        return tiers.map(t_ => ({
          value: t_.tier,
          label: `${t_.tier_emoji || ""} ${tierLabel[t_.tier] || t_.tier}`,
        }));
      }

      const headerExtra = data?.next_spawn_ms ? (
        <div style={{
          fontSize:10, color:"var(--gold3)", fontFamily:"'Cinzel',serif",
          letterSpacing:.3, textAlign:"right", whiteSpace:"nowrap",
        }}>
          {t("boss_next_spawn")}<br />
          ⏳ {fmtDuration(Math.max(0, data.next_spawn_ms - now))}
        </div>
      ) : null;

      return (
        <Modal onClose={onClose} title={`🏆 ${t("boss_rankings_title")}`}
               accent="rgba(var(--red-rgb),.45)" maxWidth={420} zIndex={70}
               headerExtra={headerExtra}>
          {loading && <ListSkeleton rows={5} />}
          {error && <ErrBanner msg={error} />}
          {data && data.tiers && (
            <div>
              <SegControl
                options={tierOptions(data.tiers)}
                value={activeTier || "mortal"}
                onChange={setActiveTier}
              />
              {(data.tiers.find(tt => tt.tier === activeTier) || data.tiers[0]).bosses.map(boss => (
                <Card key={boss.name} style={{ marginBottom:8, padding:"8px 10px" }}>
                  <div style={{ display:"flex", alignItems:"center", gap:8, marginBottom:5 }}>
                    <PieceIcon kind="boss" name={boss.name} artKey={boss.art_key}
                               emoji={boss.emoji} size={34} radius={7}
                               dim={!boss.is_active}
                               style={{ filter:`drop-shadow(0 0 8px ${boss.is_active ? "rgba(var(--red-rgb),.6)" : "rgba(var(--muted-rgb),.3)"})` }} />
                    <div style={{ flex:1, minWidth:0 }}>
                      <div style={{ fontFamily:"'Cinzel',serif", fontSize:13, fontWeight:600,
                                    whiteSpace:"nowrap", overflow:"hidden", textOverflow:"ellipsis" }}>
                        {boss.name}
                      </div>
                      <div style={{ fontSize:9.5, color:"var(--muted2)", letterSpacing:.4 }}>
                        {boss.is_active
                          ? `🔴 ${t("boss_state_active")} · ${boss.phase || "normal"}`
                          : boss.ever_spawned
                            ? `⚪ ${t("boss_state_ended")}`
                            : `❔ ${t("boss_state_never")}`}
                      </div>
                    </div>
                    {boss.ever_spawned && boss.max_hp > 0 && (
                      <div style={{ fontSize:10, color:"var(--muted)", textAlign:"right", whiteSpace:"nowrap" }}>
                        {fmtNum(boss.current_hp)}/{fmtNum(boss.max_hp)}
                      </div>
                    )}
                  </div>
                  {boss.rankings.length === 0 ? (
                    <div style={{ fontSize:10.5, color:"var(--muted2)", padding:"6px 0", textAlign:"center", fontStyle:"italic" }}>
                      {boss.ever_spawned ? t("boss_no_damage_yet") : t("boss_never_spawned")}
                    </div>
                  ) : (
                    <div style={{ display:"grid", gap:2 }}>
                      {boss.rankings.map(rk => (
                        <LeaderRow key={`${boss.name}-${rk.rank}`}
                                   rank={rk.rank}
                                   name={`${rk.realm_emoji} ${rk.name}`}
                                   meta={`⚔️ ${fmtNum(rk.total_damage)} · ${rk.hits}${t("hits_short")}`}
                                   isYou={rk.is_you} />
                      ))}
                    </div>
                  )}
                </Card>
              ))}
            </div>
          )}
        </Modal>
      );
    }

    function WorldBossTab() {
      const [tick, setTick] = useState(0);
      const [showRankings, setShowRankings] = useState(false);
      // v14.13c — Owner P1 2026-05-08: "ranking visivel é interessante do
      // dano por boss e mostrar a lista de boss de todos os grausd com o
      // ranking por cada 1". v14.7 shipped BossRankingsModal as drill-in;
      // owner wanted INLINE visibility. Section below renders all-tier
      // rankings as a Card with SegControl + per-boss collapsable accordion.
      // Modal kept as fallback (smaller "🏆 Tela cheia" button) for users
      // who prefer the full-screen surface.
      const [showAllRankings, setShowAllRankings] = useState(false);
      const [rankingsTier, setRankingsTier] = useState(null);
      const [expandedBoss, setExpandedBoss] = useState(null);
      // Fetch rankings eagerly when (a) inline expanded OR (b) no active boss
      // (dead-screen needs next_spawn_ms + historic rankings as filler).
      // Note: `data` is captured later via useApi — we drive `rk` solely off
      // the local toggles to avoid coupling fetch order.
      const rk = useApi("boss/rankings", null, [tick]);
      // Default expanded tier when data lands.
      useEffect(() => {
        if (rk.data && rankingsTier == null) setRankingsTier(rk.data.player_tier || "mortal");
      }, [rk.data, rankingsTier]);
      const { data, loading, error } = useApi("world_boss", null, [tick]);
      // Optimistic overlay so the player sees the impact before the next poll
      // catches up. We *replace* the canonical state with these values until
      // the next refetch lands; on next response we just trust the server.
      const [optim, setOptim] = useState(null);
      // Persist the cooldown floor across re-renders. We tick a 1s clock
      // independently from the 8s polling so the countdown is smooth.
      const [now, setNow] = useState(Date.now());
      useVisibleInterval(() => setTick(x => x + 1), 8000);
      useVisibleInterval(() => setNow(Date.now()), 1000);
      // Clear optimistic overlay whenever fresh data arrives.
      const lastFetchedAt = useRef(0);
      useEffect(() => {
        if (data) { lastFetchedAt.current = Date.now(); setOptim(null); }
      }, [data]);

      async function attackBoss() {
        try {
          const res = await api("boss/attack");
          if (!res.ok) {
            haptic("warning");
            const reason = res.reason;
            if (reason === "cooldown") {
              showToast(t("boss_on_cooldown"), "err");
            } else if (reason === "no_boss") {
              showToast(t("no_active_boss"), "err");
            } else if (reason === "expired") {
              showToast(t("boss_expired"), "err");
            } else if (reason === "dead") {
              showToast(t("boss_dead"), "err");
            } else {
              showToast(reason, "err");
            }
            return;
          }
          haptic(res.killed ? "success" : "light");
          showToast(t("boss_attack_dealt", { n: fmtNum(res.damage) }) + (res.damage_capped ? " ⚡" : ""));
          // Optimistic mutation — the next poll will replace this with truth.
          setOptim({
            boss_hp: res.boss_hp,
            your_total: res.your_total,
            your_hits: res.your_hits,
            cooldown_remaining_ms: res.cooldown_remaining_ms,
            cooldown_set_at: Date.now(),
            killed: res.killed,
          });
          if (res.killed) {
            showToast(t("boss_killed_by_you"));
          }
          setTick(x => x + 1);
        } catch (e) {
          haptic("error");
          if (e.message === "unauthorized") showToast(t("err_unauthorized"), "err");
          else showToast(e.message, "err");
        }
      }

      if (loading && !data) return <BossSkeleton />;
      if (error) return <ErrBanner msg={error} />;
      if (!data?.boss) {
        // v14.13d (2026-05-25) — Owner P2 backlog: "No active boss dead-screen
        // mostra apenas mascot + 1 linha". Hydrate the empty state with
        // (a) next-spawn countdown from /boss/rankings (Wed/Sat 18:00 UTC,
        // mirror of _BOSS_SPAWN_DOWS server-side); (b) inline "Rankings"
        // section (same as the active path) so the player can still see
        // top damage history of past spawns; (c) hint pointing to dungeons
        // as alternative PvE between cycles. Modal `BossRankingsModal`
        // continues to work via "🪟 tela cheia".
        return (
          <div>
            <Card>
              <div style={{ textAlign:"center", padding:"22px 0 18px" }}>
                <div style={{ fontSize:56, opacity:.55, filter:"drop-shadow(0 0 14px rgba(var(--muted-rgb),.35))",
                              animation:"pulse-glow 3.5s ease-in-out infinite" }}>🐉</div>
                <div style={{ marginTop:10, fontFamily:"'Cinzel',serif", fontSize:14,
                              color:"var(--gold2)", letterSpacing:.6 }}>{t("no_active_boss")}</div>
                <div style={{ marginTop:4, fontSize:11, color:"var(--muted2)", fontStyle:"italic" }}>
                  {t("boss_idle_hint")}
                </div>
                {rk.data?.next_spawn_ms ? (
                  <div style={{ marginTop:14, display:"inline-block",
                                padding:"7px 16px", borderRadius:8,
                                background:"rgba(var(--gold2-rgb),.08)",
                                border:"1px solid rgba(var(--gold2-rgb),.32)",
                                fontFamily:"'Cinzel',serif" }}>
                    <div style={{ fontSize:9.5, color:"var(--muted)",
                                  letterSpacing:.7, textTransform:"uppercase" }}>
                      {t("boss_next_spawn")}
                    </div>
                    <div style={{ fontSize:16, color:"var(--gold3)",
                                  fontWeight:700, letterSpacing:.4, marginTop:2 }}>
                      ⏳ {fmtDuration(Math.max(0, rk.data.next_spawn_ms - now))}
                    </div>
                  </div>
                ) : (
                  <div style={{ marginTop:14, padding:"6px 14px", display:"inline-block",
                                borderRadius:7, background:"rgba(0,0,0,.3)",
                                border:"1px solid rgba(var(--glow-rgb),.2)",
                                fontSize:10, color:"var(--muted)" }}>
                    ⏳ …
                  </div>
                )}
              </div>
              <div style={{
                marginTop:6, padding:"7px 10px", borderRadius:8,
                background:"rgba(0,0,0,.3)",
                border:"1px solid rgba(var(--glow-rgb),.15)",
                fontSize:11, color:"var(--muted)", textAlign:"center", lineHeight:1.5,
              }}>
                {t("boss_idle_fallback")}
              </div>
            </Card>

            {/* Historic rankings ALWAYS visible in idle state — gives players
                a reason to open the tab between spawns + transparent stats. */}
            <Card>
              <div onClick={() => {
                haptic("select");
                setShowAllRankings(s => !s);
              }} style={{
                display:"flex", alignItems:"center", justifyContent:"space-between",
                cursor:"pointer", padding:"2px 0",
              }}>
                <CardTitle left={`🏆 ${t("boss_rankings_title")}`} />
                <span style={{ fontSize:14, color:"var(--gold2)",
                               transform: showAllRankings ? "rotate(180deg)" : "rotate(0)",
                               transition:"transform .2s ease" }}>▾</span>
              </div>
              {showAllRankings && rk.data?.tiers && (
                <div style={{ marginTop:8 }}>
                  <SegControl
                    options={rk.data.tiers.map(tt => ({
                      value: tt.tier,
                      label: `${tt.tier_emoji || ""} ${t(`boss_tier_${tt.tier}`)}`,
                    }))}
                    value={rankingsTier || "mortal"}
                    onChange={(v) => { haptic("select"); setRankingsTier(v); setExpandedBoss(null); }}
                  />
                  {(rk.data.tiers.find(tt => tt.tier === rankingsTier) || rk.data.tiers[0]).bosses.map(boss => {
                    const exp = expandedBoss === boss.name;
                    return (
                      <div key={boss.name} style={{
                        marginTop:6, padding:"7px 9px", borderRadius:8,
                        background:"rgba(0,0,0,.25)",
                        border:`1px solid ${boss.is_active ? "rgba(var(--red-rgb),.35)" : "rgba(var(--muted-rgb),.2)"}`,
                      }}>
                        <div onClick={() => {
                          haptic("light");
                          setExpandedBoss(exp ? null : boss.name);
                        }} style={{
                          display:"flex", alignItems:"center", gap:8, cursor:"pointer",
                        }}>
                          <PieceIcon kind="boss" name={boss.name} artKey={boss.art_key}
                                     emoji={boss.emoji} size={32} radius={7}
                                     dim={!boss.is_active}
                                     style={{ filter:`drop-shadow(0 0 6px ${boss.is_active ? "rgba(var(--red-rgb),.55)" : "rgba(var(--muted-rgb),.25)"})` }} />
                          <div style={{ flex:1, minWidth:0 }}>
                            <div style={{ fontFamily:"'Cinzel',serif", fontSize:12.5, fontWeight:600,
                                          whiteSpace:"nowrap", overflow:"hidden", textOverflow:"ellipsis" }}>
                              {boss.name}
                            </div>
                            <div style={{ fontSize:9.5, color:"var(--muted2)", letterSpacing:.4 }}>
                              {boss.is_active
                                ? `🔴 ${t("boss_state_active")}`
                                : boss.ever_spawned
                                  ? `⚪ ${t("boss_state_ended")}`
                                  : `❔ ${t("boss_state_never")}`}
                            </div>
                          </div>
                          <span style={{
                            fontSize:12, color:"var(--gold2)",
                            transform: exp ? "rotate(180deg)" : "rotate(0)",
                            transition:"transform .2s ease",
                          }}>▾</span>
                        </div>
                        {exp && (
                          <div style={{ marginTop:6, paddingTop:6, borderTop:"1px dashed rgba(var(--glow-rgb),.18)" }}>
                            {boss.rankings.length === 0 ? (
                              <div style={{ fontSize:10.5, color:"var(--muted2)", padding:"6px 0",
                                            textAlign:"center", fontStyle:"italic" }}>
                                {boss.ever_spawned ? t("boss_no_damage_yet") : t("boss_never_spawned")}
                              </div>
                            ) : (
                              <div style={{ display:"grid", gap:2 }}>
                                {boss.rankings.map(r2 => (
                                  <LeaderRow key={`${boss.name}-${r2.rank}`}
                                             rank={r2.rank}
                                             name={`${r2.realm_emoji} ${r2.name}`}
                                             meta={`⚔️ ${fmtNum(r2.total_damage)} · ${r2.hits}${t("hits_short")}`}
                                             isYou={r2.is_you} />
                                ))}
                              </div>
                            )}
                          </div>
                        )}
                      </div>
                    );
                  })}
                  <div style={{ textAlign:"center", marginTop:6 }}>
                    <button
                      onClick={() => { haptic("select"); setShowRankings(true); }}
                      style={{
                        background:"rgba(0,0,0,.35)", color:"var(--muted)",
                        border:"1px solid rgba(var(--gold2-rgb),.2)", borderRadius:5,
                        padding:"3px 9px", fontSize:9.5, letterSpacing:.4,
                        cursor:"pointer", fontFamily:"'Cinzel',serif",
                      }}>
                      🪟 {t("boss_rankings_fullscreen")}
                    </button>
                  </div>
                </div>
              )}
            </Card>

            {showRankings && <BossRankingsModal onClose={() => setShowRankings(false)} />}
          </div>
        );
      }
      const b = data.boss;
      const currentHp = optim ? Math.max(0, optim.boss_hp) : b.current_hp;
      const hpPct = Math.max(0, (currentHp / b.hp) * 100);
      const remainMs = b.expires_at_ms ? b.expires_at_ms - Date.now() : 0;
      const yourDamage = optim ? optim.your_total : data.your_damage;
      const yourHits = optim ? optim.your_hits : (data.your_hits || 0);
      // Cooldown — prefer the optimistic value, otherwise derive from server's
      // last_hit. Decrement against `now` for smooth countdown.
      let cooldownMs = 0;
      if (optim && optim.cooldown_remaining_ms) {
        cooldownMs = Math.max(0, optim.cooldown_remaining_ms - (now - optim.cooldown_set_at));
      } else if (data.cooldown_remaining_ms > 0) {
        // Server sends snapshot at fetch time; estimate elapsed since.
        const sinceFetch = now - lastFetchedAt.current;
        cooldownMs = Math.max(0, data.cooldown_remaining_ms - sinceFetch);
      }
      const onCooldown = cooldownMs > 0;
      const dead = currentHp <= 0;
      const tierMismatch = !!data.tier_mismatch;
      return (
        <div>
          <Card>
            <div style={{ textAlign:"center", padding:"14px 0 8px" }}>
              {/* 凶 2026-09-14 — ORDEM DO OWNER. Ele fotografou esta tela e
                  perguntou se os chefes tinham imagem: eram 0 de 9, e o que se
                  via aqui era `b.emoji` a 56px — o Void Beast, uma coisa vinda
                  da fresta entre os mundos, desenhado como ☯️.
                  ⚠️ A arte pede-se por `art_key` (o nome CANÓNICO) e nunca por
                  `b.name`, que agora vai traduzido: com o nome, um jogador pt
                  pediria `boss-besta-do-vazio` e cairia no emoji outra vez. */}
              <div style={{ display:"grid", placeItems:"center" }}>
                <PieceIcon kind="boss" name={b.name} artKey={b.art_key}
                           emoji={b.emoji} size={128} radius={12}
                           accent="var(--red)"
                           style={{ filter:"drop-shadow(0 0 16px rgba(255,80,80,.45))" }} />
              </div>
              <div style={{ fontFamily:"'Cinzel',serif", fontSize:17, marginTop:8, letterSpacing:.3 }}>{b.name}</div>
              <div style={{ fontSize:10, color:"var(--gold2)", letterSpacing:1, textTransform:"uppercase", marginTop:3 }}>{b.tier} · {b.phase}</div>
              {tierMismatch && (
                <div style={{ marginTop:8, padding:"4px 10px", display:"inline-block",
                              borderRadius:8, border:"1px solid rgba(245,159,11,.45)",
                              background:"rgba(245,159,11,.08)", color:"var(--warn)",
                              fontSize:11 }}>
                  {t("boss_other_tier")}
                </div>
              )}
            </div>
            <div style={{ marginTop:12, height:11, background:"rgba(255,255,255,.05)", borderRadius:8, overflow:"hidden", border:"1px solid rgba(var(--red-rgb),.3)" }}>
              <div style={{ height:"100%", width: hpPct + "%", background:"linear-gradient(90deg,#991b1b,#dc2626,#ef4444)", borderRadius:8, transition:"width .5s ease" }} />
            </div>
            <div style={{ display:"flex", justifyContent:"space-between", marginTop:6, fontSize:12, color:"var(--muted)" }}>
              <span>{fmtNum(currentHp)} / {fmtNum(b.hp)} HP</span>
              <span>⏱️ {fmtDuration(remainMs)}</span>
            </div>
            <div style={{ display:"flex", justifyContent:"space-between", marginTop:12 }}>
              <span style={{ fontSize:12, color:"var(--muted)" }}>{t("your_damage")}</span>
              <b style={{ color:"var(--gold2)" }}>⚔️ {fmtNum(yourDamage)} · {yourHits}{t("hits_short")}</b>
            </div>
            <div style={{ marginTop:14 }}>
              <ActionBtn
                onClick={attackBoss}
                variant={dead || tierMismatch ? "ghost" : "danger"}
                disabled={dead || onCooldown || tierMismatch}
                style={{ width:"100%", padding:"12px 14px", fontSize:13 }}
              >
                {tierMismatch
                  ? `🔒 ${t("boss_other_tier_btn")}`
                  : dead
                    ? `💀 ${t("boss_dead")}`
                    : onCooldown
                      ? `⏳ ${fmtDuration(cooldownMs)}`
                      : `⚔️ ${t("boss_attack_btn")}`}
              </ActionBtn>
            </div>
          </Card>

          <Card>
            <CardTitle left={t("top_cultivators")} />
            {data.ranking.length === 0 ? (
              <div style={{ textAlign:"center", padding:"24px 0", color:"var(--muted)", fontSize:12 }}>{t("first_to_attack")}</div>
            ) : data.ranking.map(r => (
              <LeaderRow key={r.rank} rank={r.rank} name={r.name}
                meta={`⚔️ ${fmtNum(r.total_damage)} · ${r.hits}${t("hits_short")}`}
                isYou={r.is_you} />
            ))}
          </Card>

          {/* v14.13c — Inline "All Bosses Rankings" section. Replaces the
              modal-button affordance with an in-place collapsable accordion.
              Default collapsed; one-tap expand. SegControl per tier; per-boss
              cards each independently expandable to show top-10 damage. */}
          <Card>
            <div onClick={() => {
              haptic("select");
              if (!showAllRankings) setShowAllRankings(true);
              else setShowAllRankings(false);
            }}
                 style={{
                   display:"flex", alignItems:"center", justifyContent:"space-between",
                   cursor:"pointer", padding:"2px 0",
                 }}>
              <CardTitle left={`🏆 ${t("boss_rankings_title")}`} />
              <span style={{ fontSize:14, color:"var(--gold2)",
                             transform: showAllRankings ? "rotate(180deg)" : "rotate(0)",
                             transition:"transform .2s ease" }}>▾</span>
            </div>
            {showAllRankings && (
              <div style={{ marginTop:8 }}>
                {rk.loading && !rk.data && <ListSkeleton rows={3} />}
                {rk.error && <ErrBanner msg={rk.error} />}
                {rk.data && rk.data.tiers && (
                  <>
                    <SegControl
                      options={rk.data.tiers.map(tt => ({
                        value: tt.tier,
                        label: `${tt.tier_emoji || ""} ${t(`boss_tier_${tt.tier}`)}`,
                      }))}
                      value={rankingsTier || "mortal"}
                      onChange={(v) => { haptic("select"); setRankingsTier(v); setExpandedBoss(null); }}
                    />
                    {(rk.data.tiers.find(tt => tt.tier === rankingsTier) || rk.data.tiers[0]).bosses.map(boss => {
                      const exp = expandedBoss === boss.name;
                      return (
                        <div key={boss.name} style={{
                          marginTop:6, padding:"7px 9px", borderRadius:8,
                          background:"rgba(0,0,0,.25)",
                          border:`1px solid ${boss.is_active ? "rgba(var(--red-rgb),.35)" : "rgba(var(--muted-rgb),.2)"}`,
                        }}>
                          <div onClick={() => {
                            haptic("light");
                            setExpandedBoss(exp ? null : boss.name);
                          }} style={{
                            display:"flex", alignItems:"center", gap:8,
                            cursor:"pointer",
                          }}>
                            <PieceIcon kind="boss" name={boss.name} artKey={boss.art_key}
                                       emoji={boss.emoji} size={32} radius={7}
                                       dim={!boss.is_active}
                                       style={{ filter:`drop-shadow(0 0 6px ${boss.is_active ? "rgba(var(--red-rgb),.55)" : "rgba(var(--muted-rgb),.25)"})` }} />
                            <div style={{ flex:1, minWidth:0 }}>
                              <div style={{ fontFamily:"'Cinzel',serif", fontSize:12.5, fontWeight:600,
                                            whiteSpace:"nowrap", overflow:"hidden", textOverflow:"ellipsis" }}>
                                {boss.name}
                              </div>
                              <div style={{ fontSize:9.5, color:"var(--muted2)", letterSpacing:.4 }}>
                                {boss.is_active
                                  ? `🔴 ${t("boss_state_active")}`
                                  : boss.ever_spawned
                                    ? `⚪ ${t("boss_state_ended")}`
                                    : `❔ ${t("boss_state_never")}`}
                              </div>
                            </div>
                            {boss.rankings.length > 0 && !exp && (
                              <span style={{ fontSize:10, color:"var(--muted)" }}>
                                {boss.rankings.length}{t("hits_short")}
                              </span>
                            )}
                            <span style={{
                              fontSize:12, color:"var(--gold2)",
                              transform: exp ? "rotate(180deg)" : "rotate(0)",
                              transition:"transform .2s ease",
                            }}>▾</span>
                          </div>
                          {exp && (
                            <div style={{ marginTop:6, paddingTop:6, borderTop:"1px dashed rgba(var(--glow-rgb),.18)" }}>
                              {boss.rankings.length === 0 ? (
                                <div style={{ fontSize:10.5, color:"var(--muted2)", padding:"6px 0",
                                              textAlign:"center", fontStyle:"italic" }}>
                                  {boss.ever_spawned ? t("boss_no_damage_yet") : t("boss_never_spawned")}
                                </div>
                              ) : (
                                <div style={{ display:"grid", gap:2 }}>
                                  {boss.rankings.map(r2 => (
                                    <LeaderRow key={`${boss.name}-${r2.rank}`}
                                               rank={r2.rank}
                                               name={`${r2.realm_emoji} ${r2.name}`}
                                               meta={`⚔️ ${fmtNum(r2.total_damage)} · ${r2.hits}${t("hits_short")}`}
                                               isYou={r2.is_you} />
                                  ))}
                                </div>
                              )}
                            </div>
                          )}
                        </div>
                      );
                    })}
                    {rk.data.next_spawn_ms && (
                      <div style={{ marginTop:8, fontSize:10, color:"var(--gold3)",
                                    fontFamily:"'Cinzel',serif", textAlign:"center",
                                    letterSpacing:.3 }}>
                        {t("boss_next_spawn")} ⏳ {fmtDuration(Math.max(0, rk.data.next_spawn_ms - now))}
                      </div>
                    )}
                    <div style={{ textAlign:"center", marginTop:6 }}>
                      <button
                        onClick={() => { haptic("select"); setShowRankings(true); }}
                        style={{
                          background:"rgba(0,0,0,.35)", color:"var(--muted)",
                          border:"1px solid rgba(var(--gold2-rgb),.2)", borderRadius:5,
                          padding:"3px 9px", fontSize:9.5, letterSpacing:.4,
                          cursor:"pointer", fontFamily:"'Cinzel',serif",
                        }}>
                        🪟 {t("boss_rankings_fullscreen")}
                      </button>
                    </div>
                  </>
                )}
              </div>
            )}
          </Card>

          {showRankings && <BossRankingsModal onClose={() => setShowRankings(false)} />}
        </div>
      );
    }

    // ─── Quests Tab ──────────────────────────────────────────────────────────
    // v16.3.5 Karmic Crossroads — quests with a `choices` fork open a moral
    // picker before granting (tab-local modal, same pattern as BossRankingsModal).
    function QuestChoiceModal({ q, onClose, onDone }) {
      const [busy, setBusy] = useState(false);
      const [outcome, setOutcome] = useState(null);
      // 宗 4.1 — a resposta INTEIRA vai a quem fecha: a escolha de uma missão da
      // casa pode dar contribuição (e um posto), e o selo do Salão lê o ganho dela
      const respostaRef = useRef(null);
      async function pick(choiceId) {
        if (busy) return;
        setBusy(true);
        try {
          const res = await api("quests/claim", { quest_id: q.id, choice_id: choiceId });
          if (res && res.choice_result) { haptic("success"); respostaRef.current = res; setOutcome(res.choice_result); }
          else { haptic("error"); showToast(t("quest_claim_failed"), "err"); }
        } catch (e) {
          haptic("error");
          showToast(t("quest_claim_failed"), "err");
        } finally { setBusy(false); }
      }
      const karmaColor = (d) => d > 0 ? "#7CFFA0" : d < 0 ? "#FF8C8C" : "var(--muted)";
      const karmaTag = (d) => d > 0 ? `+${d}` : (d < 0 ? `${d}` : "•");

      const outLines = [];
      if (outcome) {
        if (outcome.result_key) outLines.push(t(outcome.result_key));
        const k = outcome.karma || {}; const kd = k.delta || 0;
        if (kd) {
          const sign = kd > 0 ? "+" : "−";
          const band = k.label ? t("karma_label_" + k.label) : "";
          outLines.push(t("qc_outcome_karma", { delta: sign + Math.abs(kd), label: band }));
        }
        const sd = outcome.stones_delta || 0;
        if (sd) outLines.push(t("qc_outcome_stones", { amount: fmtNum(sd) }));
        if (outcome.item_gained) outLines.push(outcome.item_gained_failed ? t("qc_bag_full") : t("qc_outcome_item_gained"));
        if (outcome.item_lost) outLines.push(t("qc_outcome_item_lost"));
      }

      return (
        <Modal
          onClose={onClose}
          title={`${q.emoji} ${q.name}`}
          accent="rgba(var(--gold2-rgb),.5)"
          maxWidth={400}
          /* 2026-06-05 fix — was compact={true}, which sets the card height to
             `auto`; on iOS Telegram WebView the body's flex:1 1 0 then collapses
             (see Modal comment) and clipped the prompt + choice buttons (player
             report: karmic-choice quests rendered blank). Full-height uses the
             proven sticky-header / scroll-body pattern so every choice shows. */
          footer={outcome ? (
            <ActionBtn onClick={() => onDone && onDone(respostaRef.current)} variant="primary" style={{ width:"100%" }}>
              {t("btn_close") || "OK"}
            </ActionBtn>
          ) : undefined}
        >
          {!outcome ? (
            <div style={{ display:"flex", flexDirection:"column", gap:10 }}>
              <div style={{ fontSize:12.5, color:"var(--text)", lineHeight:1.5, whiteSpace:"pre-line" }}>
                {t("qc_prompt").replace(/\*/g, "")}
              </div>
              {(q.choices || []).map(c => (
                <button key={c.id} onClick={() => pick(c.id)} disabled={busy} style={{
                  display:"flex", justifyContent:"space-between", alignItems:"center", gap:8,
                  padding:"11px 13px", borderRadius:11, cursor: busy ? "default" : "pointer",
                  background:"rgba(0,0,0,.3)", border:"1px solid rgba(var(--gold2-rgb),.22)",
                  color:"var(--text)", fontSize:12.5, fontWeight:600, textAlign:"left",
                  opacity: busy ? 0.5 : 1,
                }}>
                  <span style={{ flex:1 }}>{t(c.label_key)}</span>
                  <span style={{ flexShrink:0, fontSize:11, fontWeight:700, color:karmaColor(c.karma_delta) }}>
                    {karmaTag(c.karma_delta)} ⚖️
                  </span>
                </button>
              ))}
            </div>
          ) : (
            <div style={{ display:"flex", flexDirection:"column", gap:8, animation:"fade-up .3s ease" }}>
              <div style={{ fontSize:13, fontWeight:700, color:"var(--gold2)" }}>
                {t("qc_outcome_title").replace(/[*_]/g, "")}
              </div>
              {outLines.map((line, i) => (
                <div key={i} style={{ fontSize:12.5, color:"var(--text)", lineHeight:1.5 }}>
                  {String(line).replace(/[*_]/g, "")}
                </div>
              ))}
            </div>
          )}
        </Modal>
      );
    }

    // MV-1 §0.1 (V-2 [jogador]) — objective_type → tab que MOSTRA a atividade.
    // Tipo sem entrada = sem link (nunca link errado). Excluído de propósito:
    // login (auto-completa). MV-2 §0 pagou a dívida dos faucets órfãos:
    // tribulation_survive e long_expedition agora TÊM tracker (wire no chat +
    // webserver + beast_engine) → ganham link. tribulation_survive →
    // cultivation (a tribulação nasce do breakthrough, que vive lá).
    // sect_contribution → guild (a doação vive na aba do grupo de jogadores,
    // NÃO na SeitaCultivoTab).
    // QoL 07/08 (report [jogador], "A Fornalha Não Pode Esfriar"): `forge_artifact`
    // era o ÚNICO objective_type do jogo INTEIRO fora deste mapa — entrou pelos
    // storylets (MV-5/MV-9) depois de o mapa ter sido escrito para as quests,
    // logo `goTab` caía a null e o chip "→" nunca aparecia. Um jogador ficou
    // sem para onde ir. (Enésima recorrência: enum novo exige grep a TODOS os
    // mapas. O teste desta onda bate STORYLET_SEEDS contra este dict.)
    //
    // Uma entrada pode ser a string da aba (forma antiga, intocada) OU
    // {tab, seg} quando o destino é um SEGMENTO dentro da aba — a Forja vive em
    // CraftingTab › ⚒️, que abre por defeito na alquimia. Saltar só para a aba
    // largaria o jogador no segmento errado, que é o defeito que o QoL de 03/08
    // já tinha decidido por escrito ser "pior do que o silêncio" (linha ~8318).
    const QUEST_OBJECTIVE_TAB = {
      cultivate: "cultivation",
      craft_pill: { tab: "crafting", seg: "alchemy" },
      forge_artifact: { tab: "crafting", seg: "forge" },
      use_pill: "inventory",
      sparring: "combat",
      arena_win: "combat",
      arena_top3: "combat",
      npc_combat: "combat",
      boss_attack: "world_boss",
      boss_damage: "world_boss",
      beast_expedition: "beasts",
      long_expedition: "beasts",
      tribulation_survive: "cultivation",
      sect_contribution: "guild",
      dungeon_floor: "dungeons",
    };

    // O segmento pedido pela navegação, consumido UMA vez pela aba de destino.
    // Top-level `var` (convenção da casa: escapa ao escopo do script-tag).
    var PENDING_TAB_SEG = null;

    function objectiveRoute(objectiveType) {
      const e = QUEST_OBJECTIVE_TAB[objectiveType];
      if (!e) return null;
      return (typeof e === "string") ? { tab: e, seg: null } : e;
    }

    // Consome o segmento pendente se for para ESTA aba (senão devolve null e
    // não toca no estado — duas abas nunca disputam o mesmo pedido).
    // ⚠️ O pedido caduca em 5s: se o salto não acontecer (o caso em que já se
    // está NA aba de destino, e `setTab` é no-op), o pedido não pode ficar
    // pendurado e sequestrar a próxima abertura manual daquela aba.
    var PENDING_TAB_SEG_TTL_MS = 5000;
    function takePendingSeg(tabKey) {
      const p = PENDING_TAB_SEG;
      PENDING_TAB_SEG = null;               // qualquer mount limpa o pedido
      if (!p || p.tab !== tabKey) return null;
      if ((Date.now() - (p.at || 0)) > PENDING_TAB_SEG_TTL_MS) return null;
      return p.seg || null;
    }

    function goToObjective(setTab, objectiveType) {
      const r = objectiveRoute(objectiveType);
      if (!r || !setTab) return false;
      PENDING_TAB_SEG = r.seg ? { tab: r.tab, seg: r.seg, at: Date.now() } : null;
      setTab(r.tab);
      return true;
    }

    function QuestRow({ q, onClaimed, onChoose, setTab }) {
      const pct = q.objective_value > 0 ? Math.min(100, (q.progress / q.objective_value) * 100) : 0;
      const hasChoices = !!(q.choices && q.choices.length);
      // Chip "→" só enquanto a quest está em progresso (completa → CTA = claim).
      const goTab = (setTab && !q.claimed && !q.is_completed)
        ? (objectiveRoute(q.objective_type) ? q.objective_type : null) : null;
      async function claim() {
        // Fork quest → open the moral picker instead of granting directly.
        if (hasChoices) { onChoose && onChoose(q); return; }
        try {
          const res = await api("quests/claim", { quest_id: q.id });
          // Defensive: server may report needs_choice even if the client's cached
          // quest lacked `choices` (stale list) — open the picker with the payload.
          if (res && res.needs_choice) { onChoose && onChoose({ ...q, choices: res.choices }); return; }
          haptic("success");
          showToast(t("quest_claim_success"));
          // 宗 4.1 — a resposta vai a quem pediu: o Salão lê o `seita_ganho` dela
          onClaimed && onClaimed(res);
        } catch (e) {
          haptic("error");
          showToast(t("quest_claim_failed"), "err");
        }
      }
      const chosen = (q.claimed && q.chosen_choice_id && hasChoices)
        ? (q.choices.find(c => c.id === q.chosen_choice_id) || null) : null;
      return (
        <div style={{ display:"flex", flexDirection:"column", gap:5, padding:"10px 4px", borderBottom:"1px dashed rgba(var(--glow-rgb),.18)" }}>
          <div style={{ display:"flex", alignItems:"center", gap:8 }}>
            <span style={{ fontSize:18 }}>{q.emoji}</span>
            <span style={{ flex:1, fontSize:13, fontWeight:600 }}>{q.name}</span>
            {q.claimed
              ? <Badge variant="jade">✓ {t("quest_claimed")}</Badge>
              : q.is_completed
                ? <Badge variant="warn">{t("quest_ready")}</Badge>
                : null}
          </div>
          <div style={{ fontSize:11, color:"var(--muted)" }}>{q.description}</div>
          <ProgressBar pct={pct} variant="cult" />
          <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", marginTop:2 }}>
            <span style={{ fontSize:11, color:"var(--muted)" }}>
              {chosen ? <span>⚖️ {t(chosen.label_key)}</span> : `${fmtNum(q.progress)} / ${fmtNum(q.objective_value)}`}
            </span>
            {q.is_completed && !q.claimed && (
              <ActionBtn onClick={claim} variant="primary" style={{ padding:"6px 14px", fontSize:11 }}>
                {hasChoices ? "⚖️" : "✦"} {t("quest_claim")}
              </ActionBtn>
            )}
            {goTab && (
              <button onClick={() => { haptic("select"); goToObjective(setTab, goTab); }}
                      style={{ background:"rgba(var(--gold2-rgb),.08)", border:"1px solid rgba(var(--gold2-rgb),.25)",
                               borderRadius:8, color:"var(--gold3)", fontSize:12, padding:"3px 10px",
                               cursor:"pointer", lineHeight:1 }}>
                →
              </button>
            )}
          </div>
        </div>
      );
    }
    // ─── MV-5: Quests VIVAS (storylets) ──────────────────────────────────────
    // A seção "📜 Quests aceitas" + a oferta viva. O PAI gate no MOUNT
    // (featureEnabled — lição MV-4 MeridiansCard: um card com useApi só pode
    // montar onde a flag está ON, senão o request dispara no main). As notifs
    // storylet_* apontam target_tab="quests" — esta seção é o destino que
    // MOSTRA o item (lição do dead-end de notif, A Volta #7).
    function StoryletSection({ onOpenStorylet, styReload, onPlayerRefresh, setTab }) {
      const [reload, setReload] = useState(0);
      const [busy, setBusy] = useState(false);
      const { data, loading } = useApi("world/storylets", null, [reload, styReload]);
      if (!featureEnabled("quests_vivas")) return null; // belt-and-suspenders
      if (loading && !data) return null;
      if (!data || !data.ok) return null;
      const offer = data.offer;
      const accepted = data.accepted || [];
      async function claim(a) {
        if (busy) return;
        setBusy(true);
        try {
          const res = await api("world/storylet_claim", { id: a.id });
          if (res && res.ok) {
            haptic("success");
            showToast(t("sty_claimed_toast", { reward: res.reward_line || "" }));
            if (res.bag_full) showToast(t("sty_bag_full"), "err");
            onPlayerRefresh && onPlayerRefresh();
          } else {
            haptic("error");
            showToast(safeT("sty_" + String((res && res.reason) || "nothing_to_claim").replace(/^sty_/, ""), null, t("sty_nothing_to_claim")), "err");
          }
        } catch (e) {
          haptic("error");
          showToast(t("sty_nothing_to_claim"), "err");
        }
        setBusy(false);
        setReload(x => x + 1);
      }
      return (
        <Card>
          <CardTitle
            left={"📜 " + t("sty_section_title")}
            right={accepted.length ? `${accepted.filter(a => a.is_completed).length}/${accepted.length}` : null}
          />
          {offer && (
            <div
              onClick={() => onOpenStorylet && onOpenStorylet(offer)}
              style={{ display:"flex", alignItems:"center", gap:8, padding:"10px 6px", cursor:"pointer",
                       borderRadius:10, border:"1px dashed rgba(212,170,80,.45)", marginBottom:6 }}
            >
              <span style={{ fontSize:20 }}>{offer.emoji}</span>
              <div style={{ flex:1 }}>
                <div style={{ fontSize:12.5, fontWeight:700 }}>{t("sty_offer_chip", { giver: offer.giver })}</div>
                <div style={{ fontSize:11, color:"var(--muted)" }}>{offer.name}</div>
              </div>
              <span style={{ fontSize:11, color:"var(--gold3)", fontWeight:700 }}>{t("sty_view_offer_btn")} →</span>
            </div>
          )}
          {accepted.map(a => (
            <div key={a.id} style={{ display:"flex", flexDirection:"column", gap:5, padding:"10px 4px",
                                     borderBottom:"1px dashed rgba(var(--glow-rgb),.18)" }}>
              <div style={{ display:"flex", alignItems:"center", gap:8 }}>
                <span style={{ fontSize:18 }}>{a.emoji}</span>
                <span style={{ flex:1, fontSize:13, fontWeight:600 }}>{a.name}</span>
                {a.is_completed
                  ? <Badge variant="warn">{t("quest_ready")}</Badge>
                  : (a.expires_in != null
                      ? <span style={{ fontSize:10.5, color:"var(--muted)" }}>⌛ {fmtDuration(a.expires_in * 1000)}</span>
                      : null)}
              </div>
              <div style={{ fontSize:11, color:"var(--muted)" }}>{a.desc}</div>
              {/* QoL 07/08 ([jogador]) — mesma correção do cartão do Encargo: o
                  objetivo DITO, e o chip que leva ao lugar dele. */}
              {a.objective_line && (
                <div style={{ display:"flex", alignItems:"center", gap:8 }}>
                  <span style={{ flex:1, fontSize:11.5, fontWeight:600, color:"var(--gold2)" }}>
                    {a.objective_line}
                  </span>
                  {setTab && !a.is_completed && objectiveRoute(a.objective_type) && (
                    <button onClick={() => { haptic("select"); goToObjective(setTab, a.objective_type); }}
                            style={{ background:"rgba(var(--gold2-rgb),.08)", border:"1px solid rgba(var(--gold2-rgb),.25)",
                                     borderRadius:8, color:"var(--gold3)", fontSize:12, padding:"3px 10px",
                                     cursor:"pointer", lineHeight:1, flexShrink:0 }}>
                      →
                    </button>
                  )}
                </div>
              )}
              <ProgressBar pct={a.objective_count > 0 ? Math.min(100, (a.progress / a.objective_count) * 100) : 0} variant="cult" />
              <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", marginTop:2 }}>
                <span style={{ fontSize:11, color:"var(--muted)" }}>
                  {fmtNum(a.progress)} / {fmtNum(a.objective_count)} · 🎁 {a.reward_line}
                </span>
                {a.is_completed && (
                  <ActionBtn onClick={() => claim(a)} disabled={busy} variant="primary"
                             style={{ padding:"6px 14px", fontSize:11 }}>
                    {t("sty_claim_btn_mini")}
                  </ActionBtn>
                )}
              </div>
            </div>
          ))}
          {!offer && accepted.length === 0 && (
            <div style={{ textAlign:"center", padding:"14px 0" }}>
              <div style={{ fontSize:30 }}>🌍</div>
              <div style={{ marginTop:6, fontSize:12, color:"var(--muted)" }}>{t("sty_empty_state")}</div>
              {data.next_offer_in > 0 && (
                <div style={{ marginTop:3, fontSize:10.5, color:"var(--muted)" }}>
                  {t("sty_next_offer_in", { time: fmtDuration(data.next_offer_in * 1000) })}
                </div>
              )}
            </div>
          )}
        </Card>
      );
    }

    // O ENCONTRO: diálogo do giver + Aceitar/Recusar. Montado no ROOT do App
    // (lição nav-state-loss: modal fora do _anyModalOpen/_handleBack = back
    // nativo fecha o webapp). Recusar é livre — sem punição (Lei §1).
    function StoryletOfferModal({ offer, onClose, onDone }) {
      const [busy, setBusy] = useState(false);
      if (!offer) return null;
      async function respond(accept) {
        if (busy) return;
        setBusy(true);
        try {
          const res = await api("world/storylet_respond", { id: offer.id, accept });
          if (res && res.ok) {
            haptic("success");
            showToast(accept ? t("sty_accepted_toast") : t("sty_declined_toast"));
          } else {
            haptic("error");
            showToast(t("sty_offer_gone"), "err");
          }
        } catch (e) {
          haptic("error");
          showToast(t("sty_offer_gone"), "err");
        }
        setBusy(false);
        onDone && onDone();
      }
      return (
        <Modal open onClose={onClose} title={`${offer.emoji} ${offer.name}`} accent="gold" maxWidth={420}>
          <div style={{ display:"flex", flexDirection:"column", gap:10, padding:"4px 2px" }}>
            <div style={{ fontSize:12, color:"var(--muted)" }}>{t("sty_offer_by", { giver: offer.giver })}</div>
            {(offer.dialogue || []).map((d, i) => (
              <div key={i} style={{ fontSize:13, fontStyle:"italic", lineHeight:1.5,
                                    padding:"8px 12px", borderLeft:"2px solid rgba(212,170,80,.5)" }}>
                “{d}”
              </div>
            ))}
            <div style={{ fontSize:12.5 }}>🎯 {offer.desc}</div>
            {/* QoL 07/08 ([jogador]) — o que a proposta EXIGE, em palavras, antes de
                aceitar. O `desc` é atmosfera; isto é o contrato. */}
            {offer.objective_line && (
              <div style={{ fontSize:12.5, fontWeight:600, color:"var(--gold2)" }}>{offer.objective_line}</div>
            )}
            <div style={{ fontSize:12.5 }}>🎁 {offer.reward_line}</div>
            <div style={{ fontSize:11.5, color:"var(--muted)" }}>⌛ {t("sty_offer_deadline_mini", { hours: offer.deadline_hours })}</div>
            <div style={{ display:"flex", gap:8, marginTop:6 }}>
              <ActionBtn onClick={() => respond(true)} disabled={busy} variant="primary" style={{ flex:1 }}>
                ✅ {t("sty_accept_btn")}
              </ActionBtn>
              <ActionBtn onClick={() => respond(false)} disabled={busy} style={{ flex:1 }}>
                🚶 {t("sty_decline_btn")}
              </ActionBtn>
            </div>
          </div>
        </Modal>
      );
    }

    // ── MV-7 — Profissões Wuxia ─────────────────────────────────────────────
    // Card leve do HubMundo/Perfil: 100% payload-driven (player.profession_view
    // do api_player — SEM useApi → sem problema de mount-gate; a flag OFF emite
    // null e o card nem renderiza). CTA abre a Guilda (modal root).
    function ProfessionCard({ player, onOpen }) {
      if (!featureEnabled("profissoes")) return null;
      const pv = player && player.profession_view;
      if (!pv) return null;
      const hasProf = !!pv.key;
      return (
        <button onClick={onOpen}
                style={{
                  display:"flex", alignItems:"center", gap:8, width:"100%",
                  padding:"10px 12px", borderRadius:10, cursor:"pointer",
                  background:"rgba(0,0,0,.35)", border:"1px solid rgba(var(--gold2-rgb),.25)",
                  color:"var(--text)", fontFamily:"inherit", fontSize:12.5, textAlign:"left",
                }}>
          <span style={{ fontSize:18, lineHeight:1 }}>{hasProf ? pv.emoji : "🏮"}</span>
          {hasProf ? (
            <span style={{ flex:1, minWidth:0 }}>
              <b>{pv.name}</b> · {pv.tier_name}
              <span style={{ color:"var(--muted)" }}>
                {" "}({pv.xp}/{pv.xp_next == null ? "MAX" : pv.xp_next} XP)
              </span>
              {/* MV-9 §P6 — o card RECEBIA `in_native`/`native_name` e jogava
                  fora: o ProfessionModal mostrava, o card da praça não. É
                  literalmente "por que eu iria àquele continente" descartado,
                  com zero backend (mesmo `player.profession_view`) e zero keys
                  novas (as duas já existem × 3 locales). Lição recorrente:
                  payload entregue ≠ payload visto. */}
              {pv.native_name && (
                <span style={{ display:"block", fontSize:10.5, marginTop:2,
                               color: pv.in_native ? "var(--gold3)" : "var(--muted)" }}>
                  {pv.in_native
                    ? t("prf_mini_in_native", { native: pv.native_name, mult: pv.xp_mult })
                    : t("prf_mini_travel", { native: pv.native_name })}
                </span>
              )}
            </span>
          ) : (
            <span style={{ flex:1 }}>{safeT("prf_mini_card_cta")}</span>
          )}
          <span style={{ color:"var(--gold3)" }}>›</span>
        </button>
      );
    }

    // A Guilda dos Ofícios (modal root — lição nav-state-loss): cerimônia de
    // escolha OU status com bônus vivos + troca + (médico) heal de aliado.
    // Só monta com a flag ON (gate no PAI, app.js — lição MV-4).
    function ProfessionModal({ onClose, onPlayerRefresh }) {
      const [reload, setReload] = useState(0);
      const [confirmKey, setConfirmKey] = useState(null);
      const [swapMode, setSwapMode] = useState(false);
      const [busy, setBusy] = useState(false);
      const [healTarget, setHealTarget] = useState("");
      const [healPill, setHealPill] = useState(null);
      const { data, loading } = useApi("world/profession", null, [reload]);
      const view = data && data.ok && data.view;
      const HEAL_ERRS = ["prf_heal_not_found", "prf_heal_self", "prf_heal_realm_gap",
                         "prf_heal_continent", "prf_heal_no_pill", "prf_heal_not_hp",
                         "prf_heal_full", "prf_not_medico"];
      async function choose(key, switching) {
        if (busy) return;
        setBusy(true);
        try {
          const res = await api("world/profession_choose", { key: key, switch: !!switching });
          if (res && res.ok) {
            haptic("success");
            showToast(t("prf_mini_chosen_toast"));
            setConfirmKey(null); setSwapMode(false);
            setReload(x => x + 1);
            onPlayerRefresh && onPlayerRefresh();
          } else if (res && res.reason === "prf_no_stones") {
            haptic("error"); showToast(t("prf_mini_no_stones"), "err");
          } else {
            haptic("error"); showToast(t("prf_mini_fail"), "err");
          }
        } catch (e) { haptic("error"); showToast(t("prf_mini_fail"), "err"); }
        setBusy(false);
      }
      async function heal() {
        if (busy || !healPill || !healTarget.trim()) return;
        setBusy(true);
        try {
          const res = await api("world/profession_heal", { target: healTarget.trim(), inv_id: healPill });
          if (res && res.ok) {
            haptic("success");
            showToast(t("prf_mini_heal_ok", { name: res.target_name, hp: res.restored }));
            setHealTarget(""); setHealPill(null);
            setReload(x => x + 1);
          } else {
            haptic("error");
            const r = res && res.reason;
            showToast(HEAL_ERRS.indexOf(r) !== -1 ? t("err_" + r) : t("prf_mini_fail"), "err");
          }
        } catch (e) { haptic("error"); showToast(t("prf_mini_fail"), "err"); }
        setBusy(false);
      }
      const xpBar = (v) => {
        if (v.xp_next == null) return null;
        const span = Math.max(1, v.xp_next - v.xp_floor);
        const pct = Math.max(0, Math.min(100, Math.round(100 * (v.xp - v.xp_floor) / span)));
        return (
          <div style={{ height:8, borderRadius:99, background:"rgba(255,255,255,.08)", overflow:"hidden" }}>
            <div style={{ width:`${pct}%`, height:"100%", background:"linear-gradient(90deg, var(--gold), var(--gold2))" }} />
          </div>
        );
      };
      return (
        <Modal open onClose={onClose} title={`🏮 ${t("prf_mini_title")}`} accent="gold" maxWidth={440}>
          {loading && <ListSkeleton rows={4} />}
          {!loading && !view && (
            <div style={{ fontSize:12.5, color:"var(--muted)", padding:8 }}>{t("prf_mini_locked")}</div>
          )}
          {/* ── Cerimônia (sem ofício) ── */}
          {!loading && view && !view.has && !confirmKey && (
            <div style={{ display:"flex", flexDirection:"column", gap:10 }}>
              <div style={{ fontSize:12.5, lineHeight:1.5 }}>{t("prf_mini_intro")}</div>
              {(view.choices || []).map(c => (
                <button key={c.key} onClick={() => { haptic("select"); setConfirmKey(c.key); }}
                        style={{
                          display:"flex", flexDirection:"column", gap:4, textAlign:"left",
                          padding:"10px 12px", borderRadius:10, cursor:"pointer",
                          background:"rgba(0,0,0,.35)", border:"1px solid rgba(var(--gold2-rgb),.25)",
                          color:"var(--text)", fontFamily:"inherit",
                        }}>
                  <div style={{ fontSize:13.5 }}><b>{c.emoji} {c.name}</b></div>
                  <div style={{ fontSize:12, color:"var(--muted)", lineHeight:1.45 }}>{c.desc}</div>
                  <div style={{ fontSize:11.5, color:"var(--gold3)" }}>🗺️ {t("prf_mini_native", { native: c.native_name })}</div>
                </button>
              ))}
              <div style={{ fontSize:11.5, color:"var(--muted)", fontStyle:"italic", lineHeight:1.5 }}>
                {view.teaser} {(view.future || []).join(", ")}
              </div>
            </div>
          )}
          {/* ── Confirmação da cerimônia ── */}
          {!loading && view && !view.has && confirmKey && (() => {
            const c = (view.choices || []).find(x => x.key === confirmKey);
            if (!c) return null;
            return (
              <div style={{ display:"flex", flexDirection:"column", gap:10 }}>
                <div style={{ fontSize:14 }}><b>{c.emoji} {c.name}</b></div>
                <div style={{ fontSize:12.5, lineHeight:1.5 }}>{c.desc}</div>
                <div style={{ fontSize:11.5, color:"var(--gold3)" }}>🗺️ {t("prf_mini_native", { native: c.native_name })}</div>
                <div style={{ fontSize:11.5, color:"var(--muted)", lineHeight:1.5 }}>
                  {t("prf_mini_confirm_warn", { cost: view.switch_cost })}
                </div>
                <div style={{ display:"flex", gap:8 }}>
                  <ActionBtn onClick={() => choose(confirmKey, false)} disabled={busy} variant="primary" style={{ flex:1 }}>
                    ✅ {t("prf_mini_confirm_btn")}
                  </ActionBtn>
                  <ActionBtn onClick={() => setConfirmKey(null)} disabled={busy} style={{ flex:1 }}>
                    {t("prf_mini_back_btn")}
                  </ActionBtn>
                </div>
              </div>
            );
          })()}
          {/* ── Status (com ofício) ── */}
          {!loading && view && view.has && !swapMode && (
            <div style={{ display:"flex", flexDirection:"column", gap:10 }}>
              <div style={{ fontSize:15 }}>
                <b>{view.emoji} {view.name}</b>
                <span style={{ color:"var(--gold3)" }}> — {view.tier_name} ({view.tier}/4)</span>
              </div>
              {xpBar(view)}
              <div style={{ fontSize:11.5, color:"var(--muted)" }}>
                {view.xp_next == null
                  ? t("prf_mini_xp_max", { xp: view.xp })
                  : t("prf_mini_xp", { xp: view.xp, next: view.xp_next })}
              </div>
              <div style={{ display:"flex", flexDirection:"column", gap:4 }}>
                {(view.bonuses || []).map((b, i) => (
                  <div key={i} style={{ fontSize:12.5, lineHeight:1.45 }}>• {b}</div>
                ))}
              </div>
              <div style={{ fontSize:12, color: view.in_native ? "var(--gold3)" : "var(--muted)" }}>
                {view.in_native
                  ? t("prf_mini_in_native", { native: view.native_name, mult: view.xp_mult })
                  : t("prf_mini_travel", { native: view.native_name })}
              </div>
              {view.rep_synergy_line && (
                <div style={{ fontSize:11.5, color:"var(--muted)" }}>{view.rep_synergy_line}</div>
              )}
              {/* 🩺 heal de aliado — só o médico recebe hp_pills do server */}
              {view.key === "medico" && (
                <div style={{ borderTop:"1px solid rgba(var(--gold2-rgb),.18)", paddingTop:10,
                              display:"flex", flexDirection:"column", gap:8 }}>
                  <div style={{ fontSize:12.5 }}><b>🩺 {t("prf_mini_heal_title")}</b></div>
                  {(view.hp_pills || []).length === 0 && (
                    <div style={{ fontSize:11.5, color:"var(--muted)" }}>{t("prf_mini_heal_no_pills")}</div>
                  )}
                  {(view.hp_pills || []).length > 0 && (
                    <React.Fragment>
                      {/* 🩺 O SELETOR DE ALVO (sugestão do [jogador], 12/08). Antes
                          era só um campo de texto: o jogador tinha de sair da
                          tela, ler o nome de Dao, voltar, e torcer para não ter
                          errado uma letra — e o servidor só respondia "não
                          encontrado", sem dizer se era o nome, o continente, o
                          reino ou o HP cheio. `heal_targets` vem do servidor
                          com os MESMOS guardas do heal_ally, logo a lista nunca
                          diverge das recusas. O campo de texto fica como saída
                          para quem sabe o nome de alguém fora dos 12 (o
                          servidor continua a ser a autoridade). */}
                      {(view.heal_targets || []).length > 0 && (
                        <div style={{ display:"flex", gap:6, flexWrap:"wrap" }}>
                          {(view.heal_targets || []).map(tg => (
                            <button key={tg.dao_name}
                                    onClick={() => { haptic("select");
                                      setHealTarget(tg.dao_name === healTarget ? "" : tg.dao_name); }}
                                    style={{
                                      padding:"6px 10px", borderRadius:99, cursor:"pointer",
                                      fontSize:11.5, color:"var(--text)", fontFamily:"inherit",
                                      background: tg.dao_name === healTarget ? "rgba(var(--jade-rgb),.30)" : "rgba(0,0,0,.35)",
                                      border: tg.dao_name === healTarget ? "1px solid rgba(var(--jade-rgb),.75)" : "1px solid rgba(var(--jade-rgb),.22)",
                                    }}>
                              🩸 {tg.dao_name} · {tg.hp_pct}%
                            </button>
                          ))}
                        </div>
                      )}
                      {(view.heal_targets || []).length === 0 && (
                        <div style={{ fontSize:11.5, color:"var(--muted)", lineHeight:1.45 }}>
                          {t("prf_mini_heal_nobody")}
                        </div>
                      )}
                      <input type="text" maxLength={32} value={healTarget}
                             onChange={(e) => setHealTarget(e.target.value)}
                             placeholder={t("prf_mini_heal_placeholder")}
                             style={{
                               width:"100%", padding:"10px 12px", borderRadius:8,
                               background:"rgba(0,0,0,.4)", border:"1px solid rgba(var(--gold2-rgb),.4)",
                               color:"var(--text)", fontSize:13, outline:"none",
                             }} />
                      <div style={{ display:"flex", gap:6, flexWrap:"wrap" }}>
                        {(view.hp_pills || []).map(p => (
                          <button key={p.inv_id}
                                  onClick={() => { haptic("select"); setHealPill(p.inv_id === healPill ? null : p.inv_id); }}
                                  style={{
                                    padding:"6px 10px", borderRadius:99, cursor:"pointer",
                                    fontSize:11.5, color:"var(--text)", fontFamily:"inherit",
                                    background: p.inv_id === healPill ? "rgba(var(--gold-rgb),.35)" : "rgba(0,0,0,.35)",
                                    border: p.inv_id === healPill ? "1px solid rgba(var(--gold2-rgb),.7)" : "1px solid rgba(var(--gold2-rgb),.22)",
                                  }}>
                            {p.emoji} {p.name} ×{p.qty}
                          </button>
                        ))}
                      </div>
                      <ActionBtn onClick={heal} disabled={busy || !healPill || !healTarget.trim()} variant="primary">
                        🩺 {t("prf_mini_heal_btn")}
                      </ActionBtn>
                    </React.Fragment>
                  )}
                </div>
              )}
              <ActionBtn onClick={() => { haptic("select"); setSwapMode(true); }} disabled={busy}>
                🔄 {t("prf_mini_swap_btn")}
              </ActionBtn>
            </div>
          )}
          {/* ── Troca de ofício ── */}
          {!loading && view && view.has && swapMode && (
            <div style={{ display:"flex", flexDirection:"column", gap:10 }}>
              <div style={{ fontSize:12.5, lineHeight:1.5 }}>{t("prf_mini_swap_warn", { cost: view.switch_cost })}</div>
              {["alquimista", "ferreiro", "medico"].filter(k => k !== view.key).map(k => (
                <ActionBtn key={k} onClick={() => choose(k, true)} disabled={busy}>
                  {t("prf_mini_swap_to", { name: t("prf_mini_name_" + k) })}
                </ActionBtn>
              ))}
              <ActionBtn onClick={() => setSwapMode(false)} disabled={busy}>
                {t("prf_mini_back_btn")}
              </ActionBtn>
            </div>
          )}
        </Modal>
      );
    }

    // ── MV-9.5 商队 — A Caravana ─────────────────────────────────────────────
    // Card da praça: 100% payload-driven (o bloco `caravan` do world/plaza —
    // SEM useApi, molde ProfessionCard). A key é CONDICIONAL: com a flag OFF o
    // servidor NÃO a emite → `crv` chega undefined → o card nem renderiza. O
    // gate real é o servidor; aqui não se duplica a decisão.
    function CaravanCard({ crv, onOpen }) {
      // Hooks ANTES do early-return (lição R2/R3). A carga que chegou já foi
      // creditada pelo SERVIDOR ao montar a praça (`credit_arrived` dentro do
      // `caravan_view`); aqui só se DIZ ao jogador — uma vez só, porque o slot
      // do toast é único (2400ms): N itens = N toasts = o jogador vê o último.
      const saidRef = useRef("");
      useEffect(() => {
        const got = (crv && crv.delivered) || [];
        if (!got.length) return;
        const sig = got.map(g => `${g.kind}:${g.item_id}:${g.qty}`).join(",");
        if (saidRef.current === sig) return;
        saidRef.current = sig;
        const first = got[0];
        haptic("success");
        showToast(`🐫 ${first.emoji || "📦"} ${first.name} ×${first.qty}`);
      }, [crv]);
      if (!crv) return null;
      // UMA linha de estado, na ordem em que o mundo manda: a estrada primeiro
      // (é o que está a acontecer), depois a recusa da alma, depois a ausência
      // do velho (Mòyǔ), e só então o convite.
      const stateLine = crv.in_transit ? crv.in_transit.line
        : crv.soul_locked ? crv.soul_locked.line
        : (!crv.has_caravan ? (crv.locked_line || "") : t("crv_card_cta"));
      const stateColor = (!crv.in_transit && crv.soul_locked) ? "var(--red)" : "var(--muted)";
      return (
        <button onClick={onOpen}
                style={{
                  display:"flex", alignItems:"center", gap:8, width:"100%",
                  padding:"10px 12px", borderRadius:10, cursor:"pointer",
                  background:"rgba(0,0,0,.35)", border:"1px solid rgba(var(--gold2-rgb),.25)",
                  color:"var(--text)", fontFamily:"inherit", fontSize:12.5, textAlign:"left",
                }}>
          <span style={{ fontSize:18, lineHeight:1 }}>🐫</span>
          <span style={{ flex:1, minWidth:0 }}>
            <b>{t("crv_card_title")}</b>
            {crv.npc_name && <span style={{ color:"var(--muted)" }}> · {crv.npc_name}</span>}
            {stateLine && (
              <span style={{ display:"block", fontSize:10.5, marginTop:2,
                             color: stateColor, lineHeight:1.4 }}>
                {stateLine}
              </span>
            )}
          </span>
          <span style={{ color:"var(--gold3)" }}>›</span>
        </button>
      );
    }

    // A Caravana (modal root — lição nav-state-loss: abre da praça E da ilha
    // do mapa v2). Molde ProfessionModal. Tudo o que se lê aqui vem RESOLVIDO
    // do servidor (npc_name/npc_intro/honest_line/origin_line/reason_line/line)
    // — NUNCA passar por t(); t() só nos rótulos da moldura.
    function CaravanModal({ onClose, onPlayerRefresh }) {
      const [reload, setReload] = useState(0);
      const [busy, setBusy] = useState(false);
      const [payFor, setPayFor] = useState(null);   // "kind:item_id" da rota aberta
      const [live, setLive] = useState(null);       // a view que o próprio send devolveu
      const { data, loading } = useApi("world/caravan", null, [reload]);
      // useApi só rejeita erro de REDE: um {ok:false} com HTTP 200 chega em
      // `data` e tem de ser testado à mão (a flag caída a meio da sessão
      // devolve `crv_locked` — ver o velho parado é honesto, tela vazia não).
      const fetched = (data && data.ok === false) ? null : ((data && data.view) || null);
      const view = live || fetched;
      const routes = (view && view.routes) || [];
      const atlas = (view && view.atlas) || [];
      const rk = (r) => `${r.kind}:${r.item_id}`;
      // QUEM FINALIZA CREDITA — e quem credita TEM de dizer. Este endpoint
      // também entrega a carga chegada (`credit_arrived` dentro do
      // `caravan_view`, com commit): entrando pela porta da ilha, a praça nunca
      // chega a ver o `delivered` e o crédito seria silencioso. Mesmo toast do
      // card, mesma guarda de assinatura (slot único).
      const saidRef = useRef("");
      useEffect(() => {
        const got = (view && view.delivered) || [];
        if (!got.length) return;
        const sig = got.map(g => `${g.kind}:${g.item_id}:${g.qty}`).join(",");
        if (saidRef.current === sig) return;
        saidRef.current = sig;
        const first = got[0];
        showToast(`🐫 ${first.emoji || "📦"} ${first.name} ×${first.qty}`);
      }, [view]);

      async function send(route, pay) {
        if (busy) return;
        setBusy(true);
        try {
          const res = await api("world/caravan_send", {
            kind: route.kind, item_id: route.item_id,
            pay_kind: pay.kind, pay_id: pay.item_id,
          });
          const ok = !!(res && res.ok);
          haptic(ok ? "success" : "error");
          // Toda recusa do motor é NOMEADA e traz `line` — imprimir a linha do
          // servidor, nunca inventar um "falhou" genérico por cima dela.
          showToast((res && res.line) || t("err_engine"), ok ? "ok" : "err");
          setPayFor(null);
          if (ok && res.view) {
            // Re-render na MESMA resposta: sem 2º round-trip (o bucket de 15
            // tokens é partilhado com quem está a meditar).
            setLive(res.view);
          } else {
            setLive(null);
            setReload(x => x + 1);
          }
          if (ok) onPlayerRefresh && onPlayerRefresh();
        } catch (e) {
          haptic("error");
          showToast(t("err_engine"), "err");
        }
        setBusy(false);
      }

      const sectionTitle = (txt) => (
        <div style={{ fontSize:10, color:"var(--gold3)", fontFamily:"'Cinzel',serif",
                      letterSpacing:1.1, textTransform:"uppercase", marginBottom:6 }}>
          {txt}
        </div>
      );

      return (
        <Modal open onClose={onClose} title={`🐫 ${t("crv_modal_title")}`} accent="gold" maxWidth={440}>
          {loading && !view && <ListSkeleton rows={4} />}
          {!loading && !view && (
            <div style={{ fontSize:12.5, color:"var(--muted)", padding:8 }}>{t("crv_empty")}</div>
          )}
          {view && (
            <div style={{ display:"flex", flexDirection:"column", gap:12 }}>
              {/* ── O velho ── */}
              <div>
                <div style={{ fontSize:14, fontWeight:700, color:"var(--gold2)" }}>{view.npc_name}</div>
                {view.npc_intro && (
                  <div style={{ fontSize:12.5, lineHeight:1.5, marginTop:4 }}>{view.npc_intro}</div>
                )}
              </div>
              {/* A linha honesta, SEMPRE visível: o velho diz na cara que ir a
                  pé rende mais. É o desenho da feature (Lei §4 — a conveniência
                  nunca se vende como o melhor caminho), não letra miúda. */}
              {view.honest_line && (
                <div style={{ fontSize:11.5, color:"var(--muted)", fontStyle:"italic", lineHeight:1.55 }}>
                  {view.honest_line}
                </div>
              )}
              {/* Mòyǔ: a ausência é identidade, e aparece DITA (Lei §1). */}
              {!view.has_caravan && view.locked_line && (
                <div style={{ fontSize:12, color:"var(--red)", lineHeight:1.5 }}>{view.locked_line}</div>
              )}
              {/* Recusa por ALMA (karma/caminho) — o motivo em cima, não só as
                  rotas cinzentas em baixo. */}
              {view.soul_locked && view.soul_locked.line && (
                <div style={{ fontSize:12, color:"var(--red)", lineHeight:1.5 }}>{view.soul_locked.line}</div>
              )}
              {/* ── Na estrada ── */}
              {view.in_transit && (
                <div>
                  {sectionTitle(t("crv_transit_title"))}
                  <div style={{ padding:"8px 10px", borderRadius:8,
                                background:"rgba(0,0,0,.3)", border:"1px solid rgba(var(--gold2-rgb),.18)" }}>
                    <div style={{ display:"flex", alignItems:"center", gap:8 }}>
                      <span style={{ fontSize:17, lineHeight:1, flexShrink:0 }}>{view.in_transit.emoji || "📦"}</span>
                      <span style={{ flex:1, minWidth:0, fontSize:12.5 }}>
                        <b>{view.in_transit.name}</b> ×{view.in_transit.units}
                      </span>
                    </div>
                    <div style={{ fontSize:11, color:"var(--gold3)", marginTop:4, lineHeight:1.45 }}>
                      {view.in_transit.line}
                    </div>
                  </div>
                </div>
              )}
              {/* ── O que ele vai buscar ── */}
              {routes.length > 0 && (
                <div>
                  {sectionTitle(t("crv_routes_title"))}
                  {routes.map(r => {
                    const open = payFor === rk(r);
                    const pays = r.pays || [];
                    // `locked` chega do servidor com o motivo ao lado; sem
                    // pagamento possível a rota também não é ofertável — em
                    // ambos os casos ela APARECE, cinzenta e com o porquê.
                    const shut = !!r.locked || pays.length === 0;
                    return (
                      <div key={rk(r)} style={{
                        padding:"8px 10px", borderRadius:8, marginBottom:6,
                        background:"rgba(0,0,0,.3)", border:"1px solid rgba(var(--gold2-rgb),.18)",
                        opacity: shut ? .55 : 1,
                      }}>
                        <div style={{ display:"flex", alignItems:"center", gap:8 }}>
                          <span style={{ fontSize:17, lineHeight:1, flexShrink:0 }}>{r.emoji || "📦"}</span>
                          <span style={{ flex:1, minWidth:0, fontSize:12.5, overflow:"hidden",
                                         textOverflow:"ellipsis", whiteSpace:"nowrap" }}>
                            <b>{r.name}</b> ×{r.units}
                          </span>
                          <span style={{ fontSize:11, color:"var(--gold3)", flexShrink:0, whiteSpace:"nowrap" }}>
                            {t("crv_cost_label")} {r.cost}
                          </span>
                        </div>
                        {r.origin_line && (
                          <div style={{ fontSize:10.5, color:"var(--muted)", marginTop:3, lineHeight:1.45 }}>
                            {r.origin_line}
                          </div>
                        )}
                        {shut ? (
                          <div style={{ fontSize:11, color:"var(--red)", marginTop:4, lineHeight:1.45 }}>
                            {r.reason_line || t("crv_empty")}
                          </div>
                        ) : !open ? (
                          <ActionBtn onClick={() => { haptic("select"); setPayFor(rk(r)); }}
                                     disabled={busy} style={{ width:"100%", marginTop:6 }}>
                            🐫 {t("crv_send_btn")}
                          </ActionBtn>
                        ) : (
                          <div style={{ marginTop:6 }}>
                            <div style={{ fontSize:10.5, color:"var(--gold3)", marginBottom:5 }}>
                              {t("crv_pick_pay")}
                            </div>
                            <div style={{ display:"flex", gap:6, flexWrap:"wrap" }}>
                              {pays.map(p => (
                                <button key={`${p.kind}:${p.item_id}`}
                                        disabled={busy}
                                        onClick={() => send(r, p)}
                                        style={{
                                          padding:"6px 10px", borderRadius:99,
                                          cursor: busy ? "default" : "pointer",
                                          fontSize:11.5, color:"var(--text)", fontFamily:"inherit",
                                          background:"rgba(0,0,0,.35)",
                                          border:"1px solid rgba(var(--gold2-rgb),.22)",
                                          opacity: busy ? .6 : 1,
                                        }}>
                                  {p.emoji} {p.name} ×{r.cost}
                                </button>
                              ))}
                            </div>
                          </div>
                        )}
                      </div>
                    );
                  })}
                </div>
              )}
              {/* Sem rota nenhuma E nada na estrada — dito, não silêncio. Em
                  Mòyǔ a `locked_line` acima já explica a ausência, e repetir
                  "hoje o velho não vai a lugar nenhum" numa cidade que não tem
                  velho seria flavor a contradizer o estado. */}
              {view.has_caravan && routes.length === 0 && !view.in_transit && (
                <div style={{ fontSize:12, color:"var(--muted)", lineHeight:1.5 }}>{t("crv_empty")}</div>
              )}
              {/* ── Onde nascem as coisas ── O atlas serve TODA a gente, de
                  graça, inclusive em Mòyǔ (onde não há caravana): a única
                  escassez do jogo é geográfica e nunca tinha sido dita. */}
              {atlas.length > 0 && (
                <div>
                  {sectionTitle(t("crv_atlas_title"))}
                  {atlas.map(a => (
                    <div key={`${a.kind}:${a.item_id}`} style={{
                      padding:"7px 2px", borderBottom:"1px dashed rgba(var(--gold2-rgb),.12)",
                    }}>
                      <div style={{ display:"flex", alignItems:"center", gap:8 }}>
                        <span style={{ fontSize:15, lineHeight:1, flexShrink:0 }}>{a.emoji || "📦"}</span>
                        <span style={{ flex:1, minWidth:0, fontSize:12, overflow:"hidden",
                                       textOverflow:"ellipsis", whiteSpace:"nowrap" }}>
                          {a.name}
                        </span>
                        {a.here && <Badge variant="gold">{t("crv_here_badge")}</Badge>}
                      </div>
                      {a.origin_line && (
                        <div style={{ fontSize:10.5, color:"var(--muted)", marginTop:3, lineHeight:1.45 }}>
                          {a.origin_line}
                        </div>
                      )}
                    </div>
                  ))}
                </div>
              )}
            </div>
          )}
        </Modal>
      );
    }

    function QuestsTab({ setTab, onOpenStorylet, styReload, onPlayerRefresh }) {
      const [reload, setReload] = useState(0);
      const [choiceQuest, setChoiceQuest] = useState(null);
      const { data, loading, error } = useApi("quests", null, [reload]);
      if (loading) return <ListSkeleton rows={6} />;
      if (error) return <ErrBanner msg={error} />;
      const dailies = data.quests.filter(q => q.type === "daily");
      const weeklies = data.quests.filter(q => q.type === "weekly");
      // Hotfix "A Volta" 2026-07-07 (#7 [jogador]) — o sino/toast de "quest ready"
      // manda para esta aba com target_tab="quests", mas as sect quests só
      // existiam no Sect Hall = recompensa "não reclamável" (dead-end Lei §1).
      // O endpoint /quests JÁ devolve type==='sect' (nome/desc localizados
      // server-side) e /quests/claim JÁ as aceita — só faltava a seção.
      const sects = data.quests.filter(q => q.type === "sect");
      const refresh = () => setReload(x => x + 1);
      return (
        <div>
          {/* MV-5 — gate no MOUNT (a seção tem useApi próprio; OFF → nem monta
              → ZERO requests novos no main — lição MV-4). */}
          {featureEnabled("quests_vivas") && (
            <StoryletSection onOpenStorylet={onOpenStorylet} styReload={styReload} onPlayerRefresh={onPlayerRefresh} setTab={setTab} />
          )}
          {dailies.length > 0 && (
            <Card>
              <CardTitle left={t("dailies")} right={`${dailies.filter(q => q.is_completed).length}/${dailies.length}`} />
              {dailies.map(q => <QuestRow key={q.id} q={q} onClaimed={refresh} onChoose={setChoiceQuest} setTab={setTab} />)}
            </Card>
          )}
          {weeklies.length > 0 && (
            <Card>
              <CardTitle left={t("weeklies")} right={`${weeklies.filter(q => q.is_completed).length}/${weeklies.length}`} />
              {weeklies.map(q => <QuestRow key={q.id} q={q} onClaimed={refresh} onChoose={setChoiceQuest} setTab={setTab} />)}
            </Card>
          )}
          {sects.length > 0 && (
            <Card>
              <CardTitle left={"🏯 " + t("sect_hall_quests_title")} right={`${sects.filter(q => q.is_completed).length}/${sects.length}`} />
              {sects.map(q => <QuestRow key={q.id} q={q} onClaimed={refresh} onChoose={setChoiceQuest} setTab={setTab} />)}
            </Card>
          )}
          {data.quests.length === 0 && (
            <Card>
              <div style={{ textAlign:"center", padding:"24px 0" }}>
                <div style={{ fontSize:42 }}>🎯</div>
                <div style={{ marginTop:8, fontSize:13, color:"var(--muted)" }}>{t("no_quests")}</div>
              </div>
            </Card>
          )}
          {choiceQuest && (
            <QuestChoiceModal
              q={choiceQuest}
              onClose={() => setChoiceQuest(null)}
              onDone={() => { setChoiceQuest(null); refresh(); }}
            />
          )}
        </div>
      );
    }

    // ─── Announcements Tab ───────────────────────────────────────────────────
    function AnnouncementsTab() {
      const { data, loading, error } = useApi("announcements", null, []);
      if (loading) return <FeedSkeleton rows={6} />;
      if (error) return <ErrBanner msg={error} />;
      const items = data.items || [];
      return (
        <div>
          <Card>
            <CardTitle left={t("global_announcements")} right={items.length} />
            {items.length === 0 ? (
              <div style={{ textAlign:"center", padding:"24px 0", color:"var(--muted)", fontSize:12 }}>{t("no_news")}</div>
            ) : items.map(a => (
              <div key={a.id} style={{ display:"flex", gap:10, padding:"10px 2px", borderBottom:"1px dashed rgba(var(--glow-rgb),.18)", animation:"fade-up .3s ease" }}>
                <span style={{ fontSize:20, flexShrink:0 }}>{a.icon}</span>
                <div style={{ flex:1 }}>
                  <div style={{ fontSize:12.5, lineHeight:1.4 }}>{a.rendered}</div>
                  <div style={{ fontSize:10, color:"var(--muted)", marginTop:3 }}>{timeAgo(a.created_at_ms)}</div>
                </div>
              </div>
            ))}
          </Card>
        </div>
      );
    }

    // ─── Shop Tab ────────────────────────────────────────────────────────────
    // Premium shop — Telegram Stars for jade packs + monthly cards, jade for
    // convenience boosts/charms/talismans, celestial fragments for gacha
    // exchange. The bot's chat-side shop (handlers/shop.py) remains the canon
    // grant path; here we only generate Stars invoice links via Bot API
    // createInvoiceLink (opened by `openPaymentLink` — in-app inside Telegram,
    // a new tab on the web) or call jade-priced
    // endpoints that the existing chat handlers cannot reuse without a chat
    // round-trip. Same effects, same daily caps, same locales as /loja.
    // As recusas das Stars num mundo que não cobra: a RAZÃO vem do servidor
    // (`stars_refusal` em handlers/shop.py — o mesmo dono do pre-checkout do chat).
    // `sandbox_world` = há um Servidor Principal que cobra; `purchases_official_only`
    // = nenhum mundo desta instalação cobra (a edição comunitária, F4b 23/10).
    const SHOP_STARS_REFUSAL = {
      sandbox_world: "shop_sandbox_blocked",
      purchases_official_only: "shop_purchases_official_only",
    };

    function ShopJadeSection({ data, onPaid }) {
      async function buyPack(packKey) {
        try {
          const res = await api("shop/buy_jade", { pack: packKey });
          const recusa = res && SHOP_STARS_REFUSAL[res.reason];
          if (recusa) {
            // Multi-Servidor — mundo que não cobra: compra real bloqueada pelo
            // engine (Lei §4). Toast honesto em vez de "falha" genérica.
            haptic("warning");
            showToast(t(recusa), "err");
            return;
          }
          if (!res.ok || !res.invoice_link) {
            haptic("error");
            showToast(t("shop_invoice_failed"), "err");
            return;
          }
          // WEB-B Fase 1 — dentro do Telegram é o `openInvoice` de sempre; na
          // aba do browser o mesmo link `t.me` abre fora. `openPaymentLink`
          // (ui.js) trata das duas superfícies e do caso do pop-up bloqueado.
          openPaymentLink(res.invoice_link, onPaid);
        } catch (e) {
          haptic("error");
          showToast(t("shop_invoice_failed"), "err");
        }
      }
      return (
        <div>
          {data.is_first_jade_purchase && (
            <div style={{
              marginBottom:10, padding:"10px 12px", borderRadius:10,
              border:"1px solid rgba(var(--gold2-rgb),.45)",
              background:"linear-gradient(135deg,rgba(var(--gold2-rgb),.16),rgba(120,80,30,.22))",
              fontFamily:"'Cinzel',serif", fontSize:11.5, color:"var(--gold3)",
              textAlign:"center", letterSpacing:.3,
              boxShadow:"0 0 18px rgba(var(--gold2-rgb),.18)",
              animation:"pulse-glow 3s ease-in-out infinite",
            }}>
              {t("shop_first_purchase_banner")}
            </div>
          )}
          <Card>
            <CardTitle left={t("shop_seg_jade")} right={`💎 ${fmtNum(data.spirit_jade)}`} />
            {(!data.jade_packs || data.jade_packs.length === 0) ? (
              <div style={{ textAlign:"center", padding:"24px 0", color:"var(--muted)", fontSize:12 }}>{t("shop_no_packs")}</div>
            ) : (
              <div style={{ display:"flex", flexDirection:"column", gap:10 }}>
                {data.jade_packs.map(p => (
                  <div key={p.key} style={{
                    background:"linear-gradient(180deg,rgba(40,55,90,.55),rgba(var(--surface-rgb),.85))",
                    border:"1px solid rgba(var(--gold-rgb),.32)", borderRadius:10,
                    padding:"10px 12px", display:"flex", alignItems:"center", gap:10,
                    boxShadow:"inset 0 0 10px rgba(var(--gold2-rgb),.06)",
                  }}>
                    <div style={{
                      width:46, height:46, flexShrink:0, borderRadius:10,
                      display:"grid", placeItems:"center", fontSize:24,
                      background:"radial-gradient(circle at 35% 30%,rgba(255,240,180,.5),transparent 55%),radial-gradient(circle at 50% 50%,var(--realm-4),#0f766e 70%,#042f2e)",
                      border:"1px solid rgba(var(--gold2-rgb),.4)",
                      boxShadow:"0 0 14px rgba(46,212,191,.3)",
                    }}>💎</div>
                    <div style={{ flex:1, minWidth:0 }}>
                      <div style={{ fontFamily:"'Cinzel',serif", fontSize:13, fontWeight:700, color:"var(--gold2)" }}>
                        {t("shop_pack_total", { n: fmtNum(p.total_jade) })}
                      </div>
                      <div style={{ fontSize:10.5, color:"var(--muted)", marginTop:2 }}>
                        💎 {fmtNum(p.jade)} <span style={{ color:"var(--jade)" }}>{t("shop_pack_bonus", { n: fmtNum(p.bonus) })}</span>
                      </div>
                    </div>
                    <ActionBtn variant="primary" onClick={() => buyPack(p.key)}>
                      {t("shop_buy_for_stars", { n: p.stars })}
                    </ActionBtn>
                  </div>
                ))}
              </div>
            )}
          </Card>
        </div>
      );
    }

    function ShopBoostsSection({ data, onChanged }) {
      const CAT_LABELS = { combat: t("shop_cat_combat"), crafting: t("shop_cat_crafting"), utility: t("shop_cat_utility") };
      const CAT_ORDER = ["combat", "crafting", "utility"];
      const grouped = useMemo(() => {
        const g = { combat: [], crafting: [], utility: [] };
        for (const it of (data.items || [])) {
          (g[it.category] || g.utility).push(it);
        }
        return g;
      }, [data.items]);

      async function buy(itemKey) {
        try {
          const res = await api("shop/purchase", { key: itemKey });
          haptic("success");
          showToast(res.message || t("shop_purchase_done"));
          onChanged && onChanged();
        } catch (e) {
          haptic("error");
          showToast(t("shop_purchase_failed"), "err");
        }
      }

      const total = (data.items || []).length;
      if (total === 0) {
        return (
          <Card>
            <div style={{ textAlign:"center", padding:"24px 0", color:"var(--muted)", fontSize:12 }}>{t("shop_no_items")}</div>
          </Card>
        );
      }

      return (
        <div>
          {CAT_ORDER.map(cat => {
            const list = grouped[cat] || [];
            if (list.length === 0) return null;
            return (
              <Card key={cat}>
                <CardTitle left={CAT_LABELS[cat]} right={list.length} />
                <div style={{ display:"flex", flexDirection:"column", gap:8 }}>
                  {list.map(it => {
                    const cantAfford = data.spirit_jade < it.jade;
                    const exhausted = it.exhausted;
                    const disabled = cantAfford || exhausted;
                    return (
                      <div key={it.key} style={{
                        display:"flex", alignItems:"flex-start", gap:10,
                        padding:"9px 10px", borderRadius:9,
                        background:"rgba(0,0,0,.25)",
                        border:"1px solid rgba(var(--glow-rgb),.18)",
                        opacity: exhausted ? .55 : 1,
                      }}>
                        <div style={{ flex:1, minWidth:0 }}>
                          <div style={{ fontSize:12.5, fontWeight:600, color:"var(--text)" }}>{it.name}</div>
                          <div style={{ fontSize:11, color:"var(--muted)", marginTop:3, lineHeight:1.4 }}>{it.description}</div>
                          <div style={{ display:"flex", gap:8, alignItems:"center", marginTop:5, flexWrap:"wrap" }}>
                            <Badge variant={cantAfford ? "red" : "gold"}>{t("shop_buy_for_jade", { n: it.jade })}</Badge>
                            {it.daily_limit != null && (
                              <span style={{ fontSize:10, color: exhausted ? "var(--red)" : "var(--muted)" }}>
                                {t("shop_daily_used", { used: it.used_today, limit: it.daily_limit })}
                              </span>
                            )}
                          </div>
                        </div>
                        <ActionBtn
                          variant={exhausted ? "ghost" : "primary"}
                          disabled={disabled}
                          onClick={() => buy(it.key)}
                          style={{ padding:"7px 11px", fontSize:11, alignSelf:"center" }}
                        >
                          {exhausted ? t("shop_exhausted_today") : t("shop_card_buy")}
                        </ActionBtn>
                      </div>
                    );
                  })}
                </div>
              </Card>
            );
          })}
        </div>
      );
    }

    function ShopCardsSection({ data, onPaid, onClaimed }) {
      async function buy(cardType) {
        try {
          const res = await api("shop/buy_monthly", { card_type: cardType });
          const recusa = res && SHOP_STARS_REFUSAL[res.reason];
          if (recusa) {
            // Multi-Servidor — mesmo toast honesto do buyPack (mundo que não cobra).
            haptic("warning");
            showToast(t(recusa), "err");
            return;
          }
          if (!res.ok || !res.invoice_link) {
            haptic("error");
            showToast(t("shop_invoice_failed"), "err");
            return;
          }
          // WEB-B Fase 1 — ver o comentário em ShopJadeSection.buyPack.
          openPaymentLink(res.invoice_link, onPaid);
        } catch (e) {
          if (e.message === "monthly_already_active") {
            haptic("warning");
            showToast(t("shop_card_already_active"), "err");
          } else {
            haptic("error");
            showToast(t("shop_invoice_failed"), "err");
          }
        }
      }
      async function claim() {
        try {
          await api("shop/monthly_claim");
          haptic("success");
          showToast(t("shop_purchase_done"));
          onClaimed && onClaimed();
        } catch (e) {
          haptic("error");
          showToast(t("shop_purchase_failed"), "err");
        }
      }
      const cards = data.monthly_cards || [];
      const someActive = data.any_card_active;
      const CARD_ICON = { silver:"🥈", golden:"🥇" };
      return (
        <div>
          {cards.map(c => {
            const isOtherActive = someActive && !c.active;
            const showBuy = !someActive;
            const showClaim = c.active && c.can_claim;
            const showClaimed = c.active && !c.can_claim;
            return (
              <Card key={c.key} style={{
                border: c.active ? "1px solid var(--gold)" : undefined,
                boxShadow: c.active ? "0 0 18px rgba(var(--gold2-rgb),.18), inset 0 0 14px rgba(var(--gold2-rgb),.08)" : undefined,
              }}>
                <div style={{ display:"flex", gap:12, alignItems:"center" }}>
                  <div style={{
                    fontSize:36, lineHeight:1, filter:"drop-shadow(0 0 8px rgba(var(--gold2-rgb),.4))",
                  }}>{CARD_ICON[c.key] || "🎫"}</div>
                  <div style={{ flex:1, minWidth:0 }}>
                    <div style={{ fontFamily:"'Cinzel',serif", fontSize:14, fontWeight:700, color:"var(--gold2)" }}>{c.name}</div>
                    {c.active ? (
                      <div style={{ fontSize:11, color:"var(--jade)", marginTop:3 }}>
                        ✦ {t("shop_card_active_label", { n: c.days_left })}
                      </div>
                    ) : (
                      <div style={{ fontSize:10.5, color:"var(--muted)", marginTop:3 }}>
                        💎 {c.instant_jade} {t("shop_card_instant").toLowerCase()} · 💎 {c.daily_jade}/d
                      </div>
                    )}
                  </div>
                </div>
                <div style={{ display:"flex", justifyContent:"flex-end", gap:8, marginTop:10 }}>
                  {showClaim && (
                    <ActionBtn variant="primary" onClick={claim}>{t("shop_card_claim_today")}</ActionBtn>
                  )}
                  {showClaimed && (
                    <Badge variant="jade">{t("shop_card_already_claimed")}</Badge>
                  )}
                  {showBuy && (
                    <ActionBtn variant="primary" onClick={() => buy(c.key)}>
                      {t("shop_buy_for_stars", { n: c.stars })}
                    </ActionBtn>
                  )}
                  {isOtherActive && (
                    <Badge variant="warn">{t("shop_card_already_active")}</Badge>
                  )}
                </div>
              </Card>
            );
          })}
          {!someActive && cards.length === 0 && (
            <Card>
              <div style={{ textAlign:"center", padding:"24px 0", color:"var(--muted)", fontSize:12 }}>{t("shop_no_active_card")}</div>
            </Card>
          )}
        </div>
      );
    }

    function ShopFragmentsSection({ data, onChanged }) {
      const balance = data.celestial_fragments || 0;
      async function exchange(rarity) {
        try {
          const res = await api("shop/fragment_exchange", { rarity });
          haptic("success");
          showToast(t("shop_frag_received", { name: res.name || "" }));
          onChanged && onChanged();
        } catch (e) {
          haptic("error");
          if (e.message === "not_enough_fragments") showToast(t("shop_frag_no_balance"), "err");
          else showToast(t("shop_purchase_failed"), "err");
        }
      }
      const RARITY_VISUAL = {
        rare:      { color:"var(--realm-1)", glow:"rgba(var(--realm-1-rgb),.32)", emoji:"💙" },
        epic:      { color:"var(--realm-3)", glow:"rgba(var(--realm-3-rgb),.32)", emoji:"💜" },
        legendary: { color:"var(--gold2)", glow:"rgba(var(--gold2-rgb),.45)", emoji:"🌟" },
      };
      return (
        <Card>
          <CardTitle left={t("shop_seg_fragments")} right={`✨ ${fmtNum(balance)}`} />
          <div style={{ display:"flex", flexDirection:"column", gap:10 }}>
            {(data.fragments || []).map(f => {
              const v = RARITY_VISUAL[f.key] || { color:"var(--gold)", glow:"rgba(var(--gold2-rgb),.3)", emoji:"✨" };
              const cant = !f.can_afford;
              return (
                <div key={f.key} style={{
                  display:"flex", alignItems:"center", gap:10,
                  padding:"10px 12px", borderRadius:10,
                  background:"rgba(0,0,0,.3)",
                  border:`1px solid ${v.color}`,
                  boxShadow: `0 0 10px ${v.glow}`,
                  opacity: cant ? .55 : 1,
                }}>
                  <div style={{ fontSize:26, filter:`drop-shadow(0 0 6px ${v.glow})` }}>{v.emoji}</div>
                  <div style={{ flex:1, minWidth:0 }}>
                    <div style={{ fontFamily:"'Cinzel',serif", fontSize:13, color: v.color, fontWeight:600 }}>{f.label}</div>
                    <div style={{ fontSize:10.5, color:"var(--muted)", marginTop:2 }}>✨ {f.cost}</div>
                  </div>
                  <ActionBtn
                    variant="primary"
                    disabled={cant}
                    onClick={() => exchange(f.key)}
                    style={{ padding:"7px 11px", fontSize:11 }}
                  >
                    {t("shop_frag_exchange_btn")}
                  </ActionBtn>
                </div>
              );
            })}
          </div>
          {balance === 0 && (
            <div style={{ textAlign:"center", padding:"14px 0 4px", color:"var(--muted)", fontSize:11 }}>{t("shop_frag_no_balance")}</div>
          )}
        </Card>
      );
    }

    // ─── Gacha Section (Sprint v14.14l) ──────────────────────────────────────
    // ShopTab 5º segmento. Lista banners activos + pity bar + 1x/10x pull
    // (jade ou ticket). Reveal de resultados in-modal com cores por rarity.
    // Engine canónica: `core.monetization.perform_gacha_pull`.
    var _GACHA_RARITY_COLORS = {
      legendary: { glow:"var(--gold3)", bg:"rgba(var(--gold2-rgb),.18)", border:"rgba(var(--gold2-rgb),.6)" },
      epic:      { glow:"#c084fc", bg:"rgba(var(--realm-3-rgb),.16)",  border:"rgba(var(--realm-3-rgb),.55)" },
      rare:      { glow:"var(--realm-1)", bg:"rgba(var(--realm-1-rgb),.16)",  border:"rgba(var(--realm-1-rgb),.55)" },
      common:    { glow:"var(--realm-0)", bg:"rgba(var(--realm-0-rgb),.10)", border:"rgba(var(--realm-0-rgb),.4)" },
    };
    var _GACHA_RARITY_EMOJI = { legendary:"🌟", epic:"💜", rare:"💙", common:"🤍" };

    function GachaResultsModal({ result, onClose }) {
      if (!result) return null;
      const items = result.results || [];
      return (
        <Modal open={true} onClose={onClose}
               title={`🎰 ${t("gacha_results_title")}`}
               accent="rgba(var(--gold2-rgb),.55)" maxWidth={420} zIndex={75}
               footer={(
                 <ActionBtn variant="primary" onClick={onClose} style={{ width:"100%" }}>
                   {t("gacha_results_close")}
                 </ActionBtn>
               )}>
          <div style={{ display:"grid", gap:6 }}>
            {items.map((it, i) => {
              const r = it.rarity || "common";
              const c = _GACHA_RARITY_COLORS[r] || _GACHA_RARITY_COLORS.common;
              return (
                <div key={i} style={{
                  display:"flex", alignItems:"center", gap:8,
                  padding:"8px 10px", borderRadius:8,
                  background:c.bg, border:`1px solid ${c.border}`,
                  boxShadow: r === "legendary" ? `0 0 18px ${cssHex(c.glow)}55` : "none",
                }}>
                  <span style={{ fontSize:18 }}>{_GACHA_RARITY_EMOJI[r] || "🤍"}</span>
                  <span style={{ flex:1, fontFamily:"'Cinzel',serif",
                                 fontWeight:r === "legendary" ? 800 : 600, fontSize:12.5,
                                 color: r === "legendary" ? c.glow : "var(--text)" }}>
                    {it.name || "?"}
                  </span>
                  {it.is_pity && (
                    <span style={{ fontSize:9.5, padding:"2px 6px", borderRadius:99,
                                   background:"rgba(245,68,68,.18)", color:"var(--red)",
                                   border:"1px solid rgba(239,68,68,.5)", fontWeight:700 }}>
                      PITY
                    </span>
                  )}
                </div>
              );
            })}
          </div>
          <div style={{ marginTop:12, display:"grid", gap:4, fontSize:11, color:"var(--muted)" }}>
            <div style={{ display:"flex", justifyContent:"space-between" }}>
              <span>{t("gacha_new_pity_label")}</span>
              <b style={{ color:"var(--gold3)" }}>{result.new_pity}</b>
            </div>
            {!result.used_tickets && (
              <div style={{ display:"flex", justifyContent:"space-between" }}>
                <span>{t("gacha_jade_remaining_label")}</span>
                <b style={{ color:"var(--gold2)" }}>💎 {fmtNum(result.remaining_jade)}</b>
              </div>
            )}
          </div>
        </Modal>
      );
    }

    function ShopGachaSection({ data, onChanged }) {
      const [reload, setReload] = useState(0);
      const { data: gacha, loading, error } = useApi("gacha/banners", null, [reload]);
      const [busy, setBusy] = useState(null); // "<banner_id>:<count>"
      const [result, setResult] = useState(null);

      async function pull(banner_id, count, use_tickets) {
        const k = `${banner_id}:${count}:${use_tickets ? 't' : 'j'}`;
        if (busy) return;
        setBusy(k);
        haptic("warning");
        try {
          const res = await api("gacha/pull", { banner_id, count, use_tickets });
          if (!res.ok) {
            haptic("error");
            const key = (res.reason || "").startsWith("err_")
              ? res.reason : `err_${res.reason || "engine_error"}`;
            showToast(t(key) || t("gacha_pull_failed"), "err");
            setBusy(null);
            return;
          }
          // Highest rarity haptic
          const top = (res.results || []).reduce((acc, it) => {
            const order = { legendary:4, epic:3, rare:2, common:1 };
            return order[it.rarity] > order[acc] ? it.rarity : acc;
          }, "common");
          haptic(top === "legendary" ? "success" : top === "common" ? "light" : "warning");
          setResult({ ...res, used_tickets: !!use_tickets });
          setReload(x => x + 1);
          onChanged && onChanged();
        } catch (e) {
          haptic("error");
          showToast(e.message || "error", "err");
        }
        setBusy(null);
      }

      if (loading && !gacha) return <ListSkeleton rows={3} />;
      if (error && !gacha) return <ErrBanner msg={error} />;
      if (!gacha?.ok) return <ErrBanner msg={t(gacha?.reason === "err_gacha_official_only" ? "err_gacha_official_only" : "gacha_no_banner")} />;
      const banners = gacha.banners || [];

      return (
        <>
          <Card style={{ marginBottom:8 }}>
            <div style={{ display:"flex", justifyContent:"space-between",
                          alignItems:"center", flexWrap:"wrap", gap:8 }}>
              <div style={{ fontFamily:"'Cinzel',serif", fontSize:12.5, color:"var(--gold2)",
                            letterSpacing:.4 }}>
                🎰 {t("gacha_section_title")}
              </div>
              <div style={{ display:"flex", gap:10, fontSize:11, color:"var(--muted)" }}>
                <span>💎 {fmtNum(gacha.spirit_jade)}</span>
                {gacha.tickets > 0 && <span>🎟️ {gacha.tickets}</span>}
              </div>
            </div>
            <div style={{ marginTop:6, fontSize:10.5, color:"var(--muted)", lineHeight:1.5 }}>
              {t("gacha_section_hint", { cost: gacha.cost_per_pull, cost10: gacha.cost_per_10 })}
            </div>
          </Card>

          {banners.length === 0 && (
            <Card><div style={{ textAlign:"center", padding:"18px 8px", color:"var(--muted)", fontSize:12 }}>
              {t("gacha_no_banner")}
            </div></Card>
          )}

          {banners.map(b => {
            const pityPct = b.pity_at > 0 ? Math.min(100, (b.pity_current / b.pity_at) * 100) : 0;
            return (
              <Card key={b.id} style={{ marginBottom:10 }}>
                <div style={{ display:"flex", alignItems:"center", gap:10, marginBottom:6 }}>
                  <span style={{ fontSize:28, ...(markOn("gift") ? { display:"grid", placeItems:"center" } : {}) }}>{ico("🎁","gift",{ size:30 })}</span>
                  <div style={{ flex:1, minWidth:0 }}>
                    <div style={{ fontFamily:"'Cinzel',serif", fontWeight:700, fontSize:13,
                                  color:"var(--gold3)" }}>{b.name}</div>
                    <div style={{ fontSize:10.5, color:"var(--muted)", marginTop:2, lineHeight:1.4,
                                  fontStyle:"italic" }}>{b.description}</div>
                  </div>
                </div>
                <div style={{ fontSize:10, color:"var(--muted)", marginBottom:3,
                              display:"flex", justifyContent:"space-between" }}>
                  <span>{t("gacha_pity_label")}</span>
                  <span><b style={{ color:"var(--gold3)" }}>{b.pity_current}</b> / {b.pity_at}</span>
                </div>
                <div style={{ height:5, borderRadius:3, background:"rgba(255,255,255,.05)",
                              overflow:"hidden", marginBottom:10 }}>
                  <div style={{
                    width:`${pityPct}%`, height:"100%",
                    background:"linear-gradient(90deg, rgba(var(--realm-3-rgb),.55), rgba(var(--gold2-rgb),.7))",
                    transition:"width .3s ease",
                  }} />
                </div>
                <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:8 }}>
                  <ActionBtn variant="primary"
                             disabled={!!busy || gacha.spirit_jade < gacha.cost_per_pull}
                             onClick={() => pull(b.id, 1, false)}>
                    {busy === `${b.id}:1:j` ? <DotSpinner />
                      : `💎 ${t("gacha_btn_pull_1", { cost: gacha.cost_per_pull })}`}
                  </ActionBtn>
                  <ActionBtn variant="primary"
                             disabled={!!busy || gacha.spirit_jade < gacha.cost_per_10}
                             onClick={() => pull(b.id, 10, false)}>
                    {busy === `${b.id}:10:j` ? <DotSpinner />
                      : `💎 ${t("gacha_btn_pull_10", { cost: gacha.cost_per_10 })}`}
                  </ActionBtn>
                </div>
                {gacha.tickets >= 1 && (
                  <div style={{ display:"grid", gridTemplateColumns: gacha.tickets >= 10 ? "1fr 1fr" : "1fr",
                                gap:8, marginTop:6 }}>
                    <ActionBtn variant="ghost"
                               disabled={!!busy || gacha.tickets < 1}
                               onClick={() => pull(b.id, 1, true)}>
                      {busy === `${b.id}:1:t` ? <DotSpinner />
                        : `🎟️ ${t("gacha_btn_ticket_1")}`}
                    </ActionBtn>
                    {gacha.tickets >= 10 && (
                      <ActionBtn variant="ghost"
                                 disabled={!!busy || gacha.tickets < 10}
                                 onClick={() => pull(b.id, 10, true)}>
                        {busy === `${b.id}:10:t` ? <DotSpinner />
                          : `🎟️ ${t("gacha_btn_ticket_10")}`}
                      </ActionBtn>
                    )}
                  </div>
                )}
              </Card>
            );
          })}

          {result && <GachaResultsModal result={result} onClose={() => setResult(null)} />}
        </>
      );
    }

    function ShopTab({ onPlayerRefresh }) {
      const [seg, setSeg] = useState("jade");
      const [reload, setReload] = useState(0);
      const { data, loading, error } = useApi("shop_catalog", null, [reload]);
      const refresh = useCallback(() => {
        setReload(x => x + 1);
        onPlayerRefresh && onPlayerRefresh();
      }, [onPlayerRefresh]);

      const opts = [
        { value:"jade",      label: t("shop_seg_jade") },
        { value:"boosts",    label: t("shop_seg_boosts") },
        { value:"gacha",     label: t("shop_seg_gacha") },
        { value:"cards",     label: t("shop_seg_cards") },
        { value:"fragments", label: t("shop_seg_fragments") },
      ];

      if (loading && !data) return <ListSkeleton rows={6} />;
      if (error && !data) return <ErrBanner msg={error} />;
      if (!data) return null;

      return (
        <div>
          <Card style={{ padding:"10px 12px 8px", marginBottom:10 }}>
            <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", gap:10 }}>
              <div style={{ display:"flex", gap:14, alignItems:"center", flexWrap:"wrap" }}>
                <span style={{ fontFamily:"'Cinzel',serif", fontSize:11, color:"var(--muted)", letterSpacing:.5 }}>
                  💎 <b style={{ color:"var(--gold2)", fontWeight:700 }}>{fmtNum(data.spirit_jade)}</b>
                </span>
                <span style={{ fontFamily:"'Cinzel',serif", fontSize:11, color:"var(--muted)", letterSpacing:.5 }}>
                  ✨ <b style={{ color:"var(--gold3)", fontWeight:700 }}>{fmtNum(data.celestial_fragments)}</b>
                </span>
                {data.vip_level > 0 && <Badge variant="gold">{t("shop_vip_label")} {data.vip_level}</Badge>}
              </div>
            </div>
          </Card>

          <SegControl value={seg} onChange={setSeg} options={opts} />

          {seg === "jade"      && <ShopJadeSection data={data} onPaid={refresh} />}
          {seg === "boosts"    && <ShopBoostsSection data={data} onChanged={refresh} />}
          {seg === "gacha"     && <ShopGachaSection data={data} onChanged={refresh} />}
          {seg === "cards"     && <ShopCardsSection data={data} onPaid={refresh} onClaimed={refresh} />}
          {seg === "fragments" && <ShopFragmentsSection data={data} onChanged={refresh} />}
        </div>
      );
    }

    // ─── Shop overlay modal (owner request 2026-05-08) ───────────────────────
    // Tap-jade-on-PlayerHeader → opens ShopTab as a full-screen modal so the
    // shop is discoverable without a tab switch. Reuses ShopTab unchanged;
    // wrapper provides a top close-bar + scroll area. z-index 75 sits above
    // everything except mid-cinematic overlays (rebirth/breakthrough at 80).
    function ShopOverlayModal({ onClose, onPlayerRefresh }) {
      // MA-MODAL — migrated to canonical <Modal fullScreen> primitive.
      // useBodyScrollLock + sticky header now ride along inside Modal so
      // we don't repeat the manual overflow lock + bespoke close-bar chrome.
      const titleNode = (
        <div style={{ display:"flex", alignItems:"center", gap:10, minWidth:0 }}>
          <span style={{ fontSize:20, filter:"drop-shadow(0 0 8px rgba(var(--jade-rgb),.7))" }}>💎</span>
          <div style={{ minWidth:0 }}>
            <div style={{
              fontFamily:"'Cinzel',serif", fontSize:13.5, fontWeight:700,
              color:"var(--gold2)", letterSpacing:.4,
              overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap",
            }}>{t("shop_modal_title")}</div>
            <div style={{ fontSize:10, color:"var(--muted)", letterSpacing:.3,
                          overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap" }}>
              {t("shop_modal_subtitle")}
            </div>
          </div>
        </div>
      );
      return (
        <Modal onClose={onClose}
               title={titleNode}
               accent="rgba(var(--gold2-rgb),.25)"
               fullScreen={true} zIndex={75}
               cardStyle={{
                 background:"rgba(4,6,12,.96)",
               }}
               bodyStyle={{ padding:"12px 14px 24px" }}>
          <ShopTab onPlayerRefresh={onPlayerRefresh} />
        </Modal>
      );
    }

    // ─── Settings (MA-28) ────────────────────────────────────────────────────
    var LANG_LABELS = {
      pt: { name:"Português", flag:"🇧🇷" },
      en: { name:"English",   flag:"🇬🇧" },
      es: { name:"Español",   flag:"🇪🇸" },
    };

    function SettingsLanguageSection({ data, onChanged }) {
      const [busyLang, setBusyLang] = useState(null);
      async function pick(code) {
        if (busyLang || code === data.language) return;
        setBusyLang(code);
        try {
          const res = await api("settings/update", { language: code });
          haptic("success");
          showToast(t("settings_lang_changed"), "ok");
          onChanged && onChanged(res);
        } catch (e) {
          haptic("error");
          showToast(t("settings_save_failed"), "err");
        } finally {
          setBusyLang(null);
        }
      }
      return (
        <Card>
          <CardTitle left={t("settings_section_language")} />
          <div style={{ fontSize:11, color:"var(--muted)", marginBottom:10 }}>{t("settings_lang_choose")}</div>
          <div style={{ display:"flex", flexDirection:"column", gap:8 }}>
            {(data.supported_languages || ["pt","en","es"]).map(code => {
              const meta = LANG_LABELS[code] || { name:code, flag:"" };
              const active = code === data.language;
              const busy = busyLang === code;
              return (
                <button key={code} onClick={() => pick(code)} disabled={busy || active} style={{
                  display:"flex", alignItems:"center", gap:10,
                  padding:"10px 12px", borderRadius:10,
                  background: active ? "rgba(var(--gold-rgb),.18)" : "rgba(0,0,0,.3)",
                  border: `1px solid ${active ? "var(--gold)" : "rgba(var(--gold-rgb),.18)"}`,
                  color: active ? "var(--gold2)" : "var(--text)",
                  cursor: active ? "default" : "pointer",
                  textAlign:"left", fontFamily:"inherit", fontSize:13,
                  opacity: busy ? .55 : 1,
                  boxShadow: active ? "0 0 10px rgba(var(--gold-rgb),.25)" : "none",
                  transition:"all .15s",
                }}>
                  <span style={{ fontSize:20 }}>{meta.flag}</span>
                  <span style={{ flex:1, fontFamily:"'Cinzel',serif", letterSpacing:.4 }}>{meta.name}</span>
                  {active && <span style={{ color:"var(--gold2)", fontSize:14 }}>✓</span>}
                </button>
              );
            })}
          </div>
        </Card>
      );
    }

    function SettingsToggleRow({ label, value, onToggle, busy }) {
      return (
        <button onClick={onToggle} disabled={busy} style={{
          display:"flex", alignItems:"center", gap:10, width:"100%",
          padding:"10px 12px", borderRadius:10,
          background:"rgba(0,0,0,.3)",
          border:`1px solid ${value ? "rgba(var(--jade-rgb),.35)" : "rgba(var(--gold-rgb),.18)"}`,
          color:"var(--text)", cursor:"pointer", textAlign:"left",
          fontFamily:"inherit", fontSize:12.5,
          opacity: busy ? .55 : 1,
          transition:"all .15s",
        }}>
          <span style={{ flex:1 }}>{label}</span>
          <span aria-hidden="true" style={{
            position:"relative", width:34, height:18, borderRadius:9,
            background: value ? "rgba(var(--jade-rgb),.35)" : "rgba(var(--muted-rgb),.25)",
            border: `1px solid ${value ? "var(--jade)" : "rgba(var(--muted-rgb),.4)"}`,
            transition:"background .15s, border-color .15s",
          }}>
            <span style={{
              position:"absolute", top:1, left: value ? 17 : 1,
              width:14, height:14, borderRadius:"50%",
              background: value ? "var(--jade)" : "var(--muted)",
              boxShadow: value ? "0 0 6px rgba(var(--jade-rgb),.6)" : "none",
              transition:"left .15s, background .15s",
            }} />
          </span>
          <span style={{
            fontSize:10.5, fontFamily:"'Cinzel',serif", letterSpacing:.5, minWidth:62, textAlign:"right",
            color: value ? "var(--jade)" : "var(--muted)",
          }}>
            {value ? t("settings_shadow_on") : t("settings_shadow_off")}
          </span>
        </button>
      );
    }

    function SettingsNotifSection({ data, onChanged }) {
      const [busyKey, setBusyKey] = useState(null);
      const [local, setLocal] = useState(data.notification_prefs || {});
      // Sync local when data changes from outside (e.g. parent refetch).
      useEffect(() => { setLocal(data.notification_prefs || {}); }, [data.notification_prefs]);

      async function toggle(key) {
        if (busyKey) return;
        const prev = !!local[key];
        const next = !prev;
        // Optimistic update
        setLocal(s => ({ ...s, [key]: next }));
        setBusyKey(key);
        haptic("select");
        try {
          const res = await api("settings/update", {
            notification_pref: { key, value: next },
          });
          if (res?.notification_prefs) setLocal(res.notification_prefs);
          onChanged && onChanged(res);
        } catch (e) {
          // Rollback
          setLocal(s => ({ ...s, [key]: prev }));
          haptic("error");
          showToast(t("settings_save_failed"), "err");
        } finally {
          setBusyKey(null);
        }
      }

      const keys = data.notification_keys || Object.keys(local);
      return (
        <Card>
          <CardTitle left={t("settings_section_notifications")} />
          <div style={{ fontSize:11, color:"var(--muted)", marginBottom:10 }}>{t("settings_notif_hint")}</div>
          <div style={{ display:"flex", flexDirection:"column", gap:8 }}>
            {keys.map(key => (
              <SettingsToggleRow
                key={key}
                label={t("settings_pref_" + key)}
                value={!!local[key]}
                busy={busyKey === key}
                onToggle={() => toggle(key)}
              />
            ))}
          </div>
        </Card>
      );
    }

    function SettingsPrivacySection({ data, onChanged }) {
      const [busy, setBusy] = useState(false);
      const [shadow, setShadow] = useState(!!data.shadow_mode);
      useEffect(() => { setShadow(!!data.shadow_mode); }, [data.shadow_mode]);

      // VIP3+ gate. Mirrors `core.achievement_engine.toggle_shadow_mode`.
      // Owner request (2026-05-04): the toggle was previously interactive for
      // free players, who could enable it via the mini-app even though the
      // chat blocks them. Server now rejects the call (`vip_required`) but
      // we also gate the UI so it reads as a paid perk, not a broken switch.
      const minVip = data.shadow_mode_min_vip ?? 3;
      const vipLvl = data.vip_level ?? 0;
      const locked = vipLvl < minVip;

      async function toggle() {
        if (busy || locked) return;
        const prev = shadow;
        const next = !prev;
        setShadow(next);
        setBusy(true);
        haptic("select");
        try {
          const res = await api("settings/update", { shadow_mode: next });
          if (res && res.ok === false) {
            // Server-side gate caught it (race: VIP expired between get/update)
            setShadow(prev);
            haptic("warning");
            showToast(t("settings_shadow_vip_required", { n: res.min_vip || minVip }), "err");
          } else {
            onChanged && onChanged(res);
          }
        } catch (e) {
          setShadow(prev);
          haptic("error");
          showToast(t("settings_save_failed"), "err");
        } finally {
          setBusy(false);
        }
      }

      return (
        <Card>
          <CardTitle left={t("settings_section_privacy")} />
          <div style={{ fontSize:11, color:"var(--muted)", marginBottom:10 }}>{t("settings_shadow_hint")}</div>
          <div style={{ position:"relative" }}>
            <SettingsToggleRow
              label={t("settings_shadow_label")}
              value={shadow && !locked}
              busy={busy}
              onToggle={() => {
                if (locked) {
                  haptic("warning");
                  showToast(t("settings_shadow_vip_required", { n: minVip }), "err");
                  return;
                }
                toggle();
              }}
            />
            {locked && (
              <div style={{
                marginTop:8, padding:"7px 10px", borderRadius:7,
                background:"linear-gradient(135deg, rgba(var(--gold2-rgb),.08), rgba(var(--realm-3-rgb),.06))",
                border:"1px solid rgba(var(--gold2-rgb),.3)",
                fontSize:10.5, color:"var(--gold3)", textAlign:"center", lineHeight:1.45,
              }}>
                💎 {t("settings_shadow_vip_required", { n: minVip })}
                {vipLvl > 0 && (
                  <div style={{ fontSize:9.5, color:"var(--muted2)", marginTop:2 }}>
                    {t("settings_vip_current", { n: vipLvl })}
                  </div>
                )}
              </div>
            )}
          </div>
        </Card>
      );
    }

    // ── UMA CONTA, QUALQUER PLATAFORMA ────────────────────────────────────
    // Vive no hub de Definicoes porque a regra da casa e essa: toda a
    // preferencia controlavel pelo jogador entra no /conf, nunca num comando
    // proprio. Aqui GERA-SE o codigo; o resgate acontece no ecra de criacao do
    // outro lado, que e onde ainda nao ha personagem para perder.
    function SettingsAccountsSection() {
      const [st, setSt] = useState(null);
      const [code, setCode] = useState(null);
      const [busy, setBusy] = useState(false);
      useEffect(() => {
        let alive = true;
        api("account/status").then(r => { if (alive && r && r.ok) setSt(r); }).catch(() => {});
        return () => { alive = false; };
      }, []);

      const gen = useCallback(async () => {
        if (busy) return;
        setBusy(true);
        try {
          const r = await api("account/link_code", {});
          if (r && r.ok) { setCode(r.code); haptic("success"); }
          else { showToast(t("world_start_error"), "err"); haptic("error"); }
        } catch (e) { showToast(t("world_start_error"), "err"); haptic("error"); }
        finally { setBusy(false); }
      }, [busy]);

      const idents = (st && st.identities) || [];
      return (
        <Card style={{ padding:"10px 12px", marginBottom:10 }}>
          <div style={{ fontFamily:"'Cinzel',serif", fontSize:11.5, letterSpacing:.4, color:"var(--gold2)" }}>
            🔗 {t("settings_accounts_title")}
          </div>
          <div style={{ fontSize:10.5, color:"var(--muted)", margin:"3px 0 8px" }}>{t("settings_accounts_desc")}</div>

          {idents.length > 0 && (
            <div style={{ marginBottom:8 }}>
              <div style={{ fontSize:9.5, letterSpacing:".14em", textTransform:"uppercase", color:"var(--muted)", marginBottom:4 }}>
                {t("settings_accounts_linked")}
              </div>
              {idents.map((i, n) => (
                <div key={n} style={{ display:"flex", alignItems:"center", gap:8, fontSize:11.5, padding:"3px 0" }}>
                  <span>{i.provider === "telegram" ? "✈️" : (i.sign_in_provider === "apple.com" ? "" : "🔑")}</span>
                  <span style={{ color:"var(--text)" }}>{i.provider === "telegram" ? "Telegram" : (i.label || "—")}</span>
                </div>
              ))}
            </div>
          )}
          {idents.length <= 1 && (
            <div style={{ fontSize:10.5, color:"var(--muted)", marginBottom:8 }}>{t("settings_accounts_none")}</div>
          )}

          {code ? (
            <div>
              {/* O codigo e para ser LIDO e copiado a mao entre aparelhos:
                  monoespacado, grande, e com espaco entre os grupos. */}
              <div
                onClick={() => { try { navigator.clipboard.writeText(code); showToast(t("settings_accounts_copied"), "ok"); haptic("success"); } catch (e) {} }}
                style={{ cursor:"pointer", textAlign:"center", padding:"12px 8px", borderRadius:8,
                         border:"1px dashed var(--gold)", background:"rgba(var(--gold-rgb),.08)",
                         fontFamily:"ui-monospace,SFMono-Regular,Menlo,monospace",
                         fontSize:24, letterSpacing:".22em", color:"var(--gold2)" }}>
                {code}
              </div>
              <div style={{ fontSize:10.5, color:"var(--muted)", lineHeight:1.5, marginTop:7 }}>{t("settings_accounts_code_hint")}</div>
            </div>
          ) : (
            <ActionBtn variant="ghost" disabled={busy} onClick={gen} style={{ width:"100%" }}>
              {t("settings_accounts_gen")}
            </ActionBtn>
          )}
        </Card>
      );
    }

    function SettingsAboutSection() {
      return (
        <Card>
          <CardTitle left={t("settings_section_about")} />
          <div style={{ textAlign:"center", padding:"6px 0 4px" }}>
            <div style={{ fontSize:32 }}>☯️</div>
            <div style={{ fontFamily:"'Cinzel',serif", fontSize:13, color:"var(--gold2)", marginTop:6, letterSpacing:.5 }}>
              {t("settings_about_app")}
            </div>
            <div style={{ fontSize:11, color:"var(--muted)", marginTop:8, lineHeight:1.5 }}>
              {t("settings_about_hint")}
            </div>
          </div>
        </Card>
      );
    }

    function SettingsTab({ onPlayerRefresh, onReplayTutorial, onOpenLobby, onOpenAdmin, isAdmin }) {
      const [reload, setReload] = useState(0);
      const { data, loading, error } = useApi("settings/get", null, [reload]);

      function handleChanged(res) {
        // Server is the source of truth — refetch settings + player so the
        // header and the LANG global update too (language switch).
        // 語 pelo dono unico — ver `definirLang` em `ui.js`.
        if (res?.language) definirLang(res.language);
        setReload(x => x + 1);
        onPlayerRefresh && onPlayerRefresh();
      }

      if (loading && !data) return <ListSkeleton rows={5} />;
      if (error && !data) return <ErrBanner msg={error} />;
      if (!data) return null;

      return (
        <div>
          <Card style={{ padding:"10px 12px 8px", marginBottom:10 }}>
            <div style={{ fontFamily:"'Cinzel',serif", fontSize:12, letterSpacing:.6, color:"var(--gold2)" }}>
              ⚙️ {t("settings_title")}
            </div>
            <div style={{ fontSize:10.5, color:"var(--muted)", marginTop:3 }}>{t("settings_subtitle")}</div>
          </Card>

          {/* Sistema Multi-Servidor (Fase 2) — Servidores (todos os jogadores).
              Entry lives in Settings (não adiciona chip ao PlayerHeader). */}
          <Card style={{ padding:"10px 12px", marginBottom:10 }}>
            <div style={{ fontFamily:"'Cinzel',serif", fontSize:11.5, letterSpacing:.4, color:"var(--gold2)" }}>
              🌐 {t("settings_servers_title")}
            </div>
            <div style={{ fontSize:10.5, color:"var(--muted)", margin:"3px 0 8px" }}>{t("settings_servers_desc")}</div>
            <ActionBtn variant="ghost" onClick={onOpenLobby} style={{ width:"100%" }}>{t("settings_servers_btn")}</ActionBtn>
          </Card>

          <SettingsAccountsSection />

          {/* Admin Panel — só o dono (player.is_admin = telegram_id em ADMIN_USERS).
              Cada endpoint re-valida ADMIN_USERS no servidor; isto é só visual. */}
          {isAdmin && (
            <Card style={{ padding:"10px 12px", marginBottom:10, border:"1px solid rgba(var(--gold2-rgb),.45)" }}>
              <div style={{ fontFamily:"'Cinzel',serif", fontSize:11.5, letterSpacing:.4, color:"var(--gold2)" }}>
                🛡️ {t("settings_admin_title")}
              </div>
              <div style={{ fontSize:10.5, color:"var(--muted)", margin:"3px 0 8px" }}>{t("settings_admin_desc")}</div>
              <ActionBtn variant="primary" onClick={onOpenAdmin} style={{ width:"100%" }}>{t("settings_admin_btn")}</ActionBtn>
            </Card>
          )}

          <SettingsLanguageSection data={data} onChanged={handleChanged} />
          <SettingsNotifSection data={data} onChanged={handleChanged} />
          <SettingsPrivacySection data={data} onChanged={handleChanged} />
          {/* v14.13 MA-47 — replay welcome tutorial. Onclick flips
              tutorial_seen=false on the server, then asks App.js to re-open
              the modal immediately (don't wait for next launch). */}
          <SettingsTutorialReplaySection onReplay={() => {
            setReload(x => x + 1);
            if (onReplayTutorial) onReplayTutorial();
          }} />
          {/* 減 P7 — toda preferencia vive no hub de Configuracoes (regra da
              casa). So' com a onda: sem ela nao ha' frase que recolha, e a
              tela fica a de hoje, byte a byte. */}
          {obraOn() && <SettingsExplicacoesSection onPlayerRefresh={onPlayerRefresh} />}
          <SettingsAboutSection />
        </div>
      );
    }

    // ═══ Sistema Multi-Servidor (Fase 2) — Lobby + Admin Panel ════════════════
    // Root-mounted modals (wired in app.js, wrapped in ModalErrorBoundary + the
    // _handleBack stack). Talk ONLY to /api/miniapp/lobby/* and /api/miniapp/admin/*
    // (control DB; the auth_middleware skips world-binding for those paths).

    function LobbyModal({ player, onClose, onServerChanged }) {
      const [reloadKey, setReloadKey] = useState(0);
      const { data, loading, error } = useApi("lobby/servers", null, [reloadKey]);
      const [code, setCode] = useState("");
      const [busy, setBusy] = useState(false);
      const [confirmKey, setConfirmKey] = useState(null);
      const activeKey = (data && data.active_server) || (player && player.world_key) || "main";
      const servers = (data && data.servers) || [];
      // a nota de um mundo sem compras aponta o Servidor Principal SÓ se ele cobra
      // (o servidor garante sempre a linha do `main`); se nenhum cobra — a edição
      // comunitária — diz só que o mundo é à parte (F4b, 23/10)
      const mainSells = servers.some(s => s.key === "main" && s.monetization_enabled);

      async function redeem() {
        const c = (code || "").trim();
        if (!c || busy) return;
        setBusy(true); haptic("select");
        try {
          const res = await api("lobby/redeem_code", { code: c });
          if (res && res.ok) {
            haptic("success");
            const nm = (res.server && res.server.name) || c;
            showToast(res.already_member ? t("lobby_already_member", { name: nm })
                                         : t("lobby_redeemed_ok", { name: nm }), "ok");
            setCode("");
            setReloadKey(x => x + 1);
          } else {
            haptic("error");
            const map = { code_invalid:"lobby_code_invalid", code_expired:"lobby_code_expired", code_used:"lobby_code_used" };
            showToast(t(map[(res && res.reason)] || "lobby_code_invalid"), "err");
          }
        } catch (e) { haptic("error"); showToast(t("lobby_error"), "err"); }
        finally { setBusy(false); }
      }

      async function doSwitch(key) {
        if (busy) return;
        setBusy(true); haptic("warning");
        try {
          const res = await api("lobby/switch", { server_key: key });
          if (res && res.ok) {
            haptic("success");
            showToast(t("lobby_switch_ok"), "ok");
            setConfirmKey(null);
            onServerChanged && onServerChanged(key);
            return;
          }
          haptic("error");
          showToast(t((res && res.reason === "not_a_member") ? "lobby_not_member" : "lobby_error"), "err");
        } catch (e) { haptic("error"); showToast(t("lobby_error"), "err"); }
        finally { setBusy(false); }
      }

      return (
        <Modal onClose={onClose} title={`🌐 ${t("lobby_title")}`} accent="rgba(var(--accent2-rgb),.5)">
          <div style={{ fontSize:11.5, color:"var(--muted)", lineHeight:1.5, marginBottom:10 }}>{t("lobby_subtitle")}</div>
          {loading && !data ? <ListSkeleton rows={3} />
            : error ? <ErrBanner msg={t("lobby_error")} />
            : servers.length === 0 ? (
                <Card><div style={{ padding:"16px 0", textAlign:"center", color:"var(--muted)", fontSize:11.5 }}>{t("lobby_empty")}</div></Card>
              )
            : servers.map(srv => {
              const isActive = srv.active || srv.key === activeKey;
              const isMain = srv.key === "main";
              const confirming = confirmKey === srv.key;
              return (
                <Card key={srv.key} style={{ marginBottom:10, padding:"12px", border: isActive ? "1px solid rgba(var(--accent2-rgb),.55)" : undefined }}>
                  <div style={{ display:"flex", alignItems:"center", gap:8 }}>
                    <span style={{ fontSize:18, flexShrink:0 }}>{isMain ? "🏯" : "⚔️"}</span>
                    <div style={{ flex:1, minWidth:0 }}>
                      <div style={{ fontFamily:"'Cinzel',serif", fontSize:13.5, color:"var(--gold2)" }}>{srv.name}</div>
                      <div style={{ fontSize:10, color:"var(--muted)", marginTop:2 }}>
                        {isMain ? t("lobby_main_note") : (srv.monetization_enabled ? "" : t(mainSells ? "lobby_sandbox_note" : "lobby_separate_world_note"))}
                      </div>
                    </div>
                    {isActive && <span style={{ fontSize:9.5, color:"#9fd6a0", border:"1px solid rgba(140,210,140,.5)", borderRadius:6, padding:"2px 6px", flexShrink:0 }}>{t("lobby_active_badge")}</span>}
                  </div>
                  {!isActive && (confirming ? (
                    <div style={{ marginTop:10 }}>
                      <div style={{ fontSize:11, color:"var(--gold3)", marginBottom:8 }}>{t("lobby_switch_confirm", { name: srv.name })}</div>
                      <div style={{ display:"flex", gap:8 }}>
                        <ActionBtn variant="primary" onClick={() => doSwitch(srv.key)} disabled={busy} style={{ flex:1 }}>{t("lobby_switch_confirm_yes")}</ActionBtn>
                        <ActionBtn variant="ghost" onClick={() => setConfirmKey(null)} disabled={busy} style={{ flex:1 }}>{t("lobby_switch_cancel")}</ActionBtn>
                      </div>
                    </div>
                  ) : (
                    <ActionBtn variant="primary" onClick={() => { haptic("select"); setConfirmKey(srv.key); }} disabled={busy} style={{ marginTop:10, width:"100%" }}>{t("lobby_switch_btn")}</ActionBtn>
                  ))}
                </Card>
              );
            })}
          <Card style={{ marginTop:4, padding:"12px" }}>
            <div style={{ fontFamily:"'Cinzel',serif", fontSize:11.5, color:"var(--gold2)" }}>🎟️ {t("lobby_redeem_title")}</div>
            <input type="text" value={code} maxLength={32}
              onChange={(e) => setCode(e.target.value)}
              placeholder={t("lobby_redeem_placeholder")}
              style={{ width:"100%", boxSizing:"border-box", marginTop:8, padding:"9px 10px", borderRadius:8,
                       border:"1px solid rgba(var(--gold2-rgb),.3)", background:"rgba(0,0,0,.4)", color:"var(--text)",
                       fontSize:13, letterSpacing:1, textTransform:"uppercase", outline:"none" }} />
            <ActionBtn variant="primary" onClick={redeem} disabled={busy || !code.trim()} style={{ marginTop:8, width:"100%" }}>{t("lobby_redeem_btn")}</ActionBtn>
          </Card>
        </Modal>
      );
    }

    const _ADMIN_BAL_LABEL = {
      cultivation_speed: "admin_cultivation_speed",
      breakthrough_difficulty: "admin_breakthrough_difficulty",
      drop_rate: "admin_drop_rate",
      qi_cost: "admin_qi_cost",
      profession_speed: "admin_profession_speed",
      qi_band_s: "admin_qi_band_s",
      body_throttle_enabled: "admin_body_throttle_enabled",
      body_throttle_base: "admin_body_throttle_base",
      body_throttle_cap: "admin_body_throttle_cap",
    };
    // Each knob explains itself (label → i18n; desc → "what it does + what changes").
    // Mirrors the self-documenting feature toggles (AdminFeaturesView).
    const _ADMIN_BAL_DESC = {
      cultivation_speed: "admin_bal_cultivation_speed_desc",
      breakthrough_difficulty: "admin_bal_breakthrough_difficulty_desc",
      drop_rate: "admin_bal_drop_rate_desc",
      qi_cost: "admin_bal_qi_cost_desc",
      profession_speed: "admin_bal_profession_speed_desc",
      qi_band_s: "admin_bal_qi_band_s_desc",
      body_throttle_enabled: "admin_bal_body_throttle_enabled_desc",
      body_throttle_base: "admin_bal_body_throttle_base_desc",
      body_throttle_cap: "admin_bal_body_throttle_cap_desc",
    };
    // Per-knob input shape, mirroring the server-side _sanitize_balance ranges
    // (the server re-clamps, so this is just so the UI fits each knob). Anything
    // not listed = a 0.01..100 multiplier (the legacy default).
    const _ADMIN_BAL_KIND = {
      body_throttle_enabled: { kind: "toggle" },                 // 0 / 1 → ON/OFF button
      qi_band_s:            { kind: "scalar", min: 0, max: 1000000, step: 50 },
      body_throttle_base:   { kind: "scalar", min: 0, max: 100, step: 0.05 },
      body_throttle_cap:    { kind: "scalar", min: 0, max: 20, step: 1 },
    };

    function AdminProvisionForm({ onDone }) {
      const [open, setOpen] = useState(false);
      const [key, setKey] = useState("");
      const [name, setName] = useState("");
      const [speed, setSpeed] = useState("0.3");
      const [busy, setBusy] = useState(false);
      const inStyle = { width:"100%", boxSizing:"border-box", marginTop:6, padding:"8px 10px", borderRadius:7,
                        background:"rgba(0,0,0,.4)", border:"1px solid rgba(var(--gold2-rgb),.3)", color:"var(--text)", fontSize:12, outline:"none" };

      async function provision() {
        const k = (key || "").trim().toLowerCase();
        if (!k || !name.trim() || busy) return;
        if (!/^[a-z][a-z0-9_]{1,30}$/.test(k)) { haptic("error"); showToast(t("admin_provision_invalid_key"), "err"); return; }
        setBusy(true); haptic("warning");
        try {
          const bc = {};
          const sp = parseFloat(speed);
          if (!isNaN(sp)) bc.cultivation_speed = sp;
          const res = await api("admin/provision", { key: k, name: name.trim(), balance_config: bc });
          if (res && res.ok) {
            haptic("success");
            showToast(t("admin_provision_started", { key: k }), "ok");
            setKey(""); setName(""); setOpen(false);
            setTimeout(() => onDone && onDone(), 1500);
          } else {
            haptic("error");
            showToast(t((res && res.reason === "invalid_key") ? "admin_provision_invalid_key" : "admin_error"), "err");
          }
        } catch (e) { haptic("error"); showToast(t("admin_error"), "err"); }
        finally { setBusy(false); }
      }

      return (
        <Card style={{ marginBottom:12, padding:"12px", border:"1px solid rgba(140,210,140,.35)" }}>
          <div onClick={() => { haptic("light"); setOpen(o => !o); }} style={{ cursor:"pointer", display:"flex", alignItems:"center", justifyContent:"space-between" }}>
            <span style={{ fontFamily:"'Cinzel',serif", fontSize:12, color:"var(--gold2)" }}>➕ {t("admin_provision_title")}</span>
            <span style={{ color:"var(--muted)" }}>{open ? "▾" : "▸"}</span>
          </div>
          {open && (
            <div style={{ marginTop:8 }}>
              <input type="text" value={key} maxLength={31} onChange={(e) => setKey(e.target.value)} placeholder={t("admin_provision_key")} style={inStyle} />
              <input type="text" value={name} maxLength={48} onChange={(e) => setName(e.target.value)} placeholder={t("admin_provision_name")} style={inStyle} />
              <div style={{ fontSize:10, color:"var(--muted)", marginTop:8 }}>{t("admin_cultivation_speed")}</div>
              <input type="number" step="0.05" min="0.01" value={speed} onChange={(e) => setSpeed(e.target.value)} style={inStyle} />
              <div style={{ fontSize:9.5, color:"var(--muted)", marginTop:6, lineHeight:1.45 }}>{t("admin_provision_speed_hint")}</div>
              <div style={{ fontSize:9.5, color:"var(--muted)", marginTop:4, lineHeight:1.45 }}>{t("admin_provision_hint")}</div>
              <ActionBtn variant="primary" disabled={busy || !key.trim() || !name.trim()} onClick={provision} style={{ marginTop:8, width:"100%" }}>{t("admin_provision_btn")}</ActionBtn>
            </div>
          )}
        </Card>
      );
    }

    function AdminServerCard({ srv, defaults, liveKeys, onReload }) {
      const isMain = srv.key === "main";
      const [bal, setBal] = useState({ ...(defaults || {}), ...(srv.balance_config || {}) });
      const [busy, setBusy] = useState(false);
      const [genUses, setGenUses] = useState("1");
      const [genDays, setGenDays] = useState("");
      const [copied, setCopied] = useState(null);
      const [nameVal, setNameVal] = useState(srv.name || "");
      const live = new Set(liveKeys || []);
      const statusLabel = { active:t("admin_status_active"), maintenance:t("admin_status_maintenance"), closed:t("admin_status_closed") }[srv.status] || srv.status;
      const statusColor = srv.status === "active" ? "#9fd6a0" : (srv.status === "maintenance" ? "#e6c46a" : "#d98a8a");

      async function saveBalance() {
        if (busy) return; setBusy(true); haptic("select");
        try {
          const res = await api("admin/set_balance", { server_key: srv.key, balance_config: bal });
          if (res && res.ok) { haptic("success"); showToast(t("admin_balance_saved"), "ok"); onReload && onReload(); }
          else { haptic("error"); showToast(t((res && res.reason === "main_locked") ? "admin_main_locked" : "admin_error"), "err"); }
        } catch (e) { haptic("error"); showToast(t("admin_error"), "err"); } finally { setBusy(false); }
      }
      async function setStatus(st) {
        if (busy) return; setBusy(true); haptic("warning");
        try {
          const res = await api("admin/set_status", { server_key: srv.key, status: st });
          if (res && res.ok) { haptic("success"); showToast(t("admin_status_saved"), "ok"); onReload && onReload(); }
          else { haptic("error"); showToast(t("admin_error"), "err"); }
        } catch (e) { haptic("error"); showToast(t("admin_error"), "err"); } finally { setBusy(false); }
      }
      async function renameGo() {
        if (busy || !nameVal.trim()) return; setBusy(true); haptic("select");
        try {
          const res = await api("admin/set_name", { server_key: srv.key, name: nameVal.trim() });
          if (res && res.ok) { haptic("success"); showToast(t("admin_renamed"), "ok"); onReload && onReload(); }
          else { haptic("error"); showToast(t("admin_error"), "err"); }
        } catch (e) { haptic("error"); showToast(t("admin_error"), "err"); } finally { setBusy(false); }
      }
      async function toggleFlag(field, value) {
        if (busy) return; setBusy(true); haptic("warning");
        try {
          const res = await api("admin/set_flags", { server_key: srv.key, [field]: value });
          if (res && res.ok) { haptic("success"); showToast(t("admin_flags_saved"), "ok"); onReload && onReload(); }
          else { haptic("error"); showToast(t((res && res.reason === "main_locked") ? "admin_main_locked" : "admin_error"), "err"); }
        } catch (e) { haptic("error"); showToast(t("admin_error"), "err"); } finally { setBusy(false); }
      }
      async function genCode() {
        if (busy) return; setBusy(true); haptic("select");
        try {
          const body = { server_key: srv.key };
          const u = parseInt(genUses, 10); if (!isNaN(u)) body.max_uses = u;
          const d = parseInt(genDays, 10); if (!isNaN(d)) body.expires_days = d;
          const res = await api("admin/gen_code", body);
          if (res && res.ok) { haptic("success"); showToast(`${t("admin_code_generated")}: ${res.code}`, "ok"); onReload && onReload(); }
          else { haptic("error"); showToast(t("admin_error"), "err"); }
        } catch (e) { haptic("error"); showToast(t("admin_error"), "err"); } finally { setBusy(false); }
      }
      function copyCode(c) {
        try { navigator.clipboard && navigator.clipboard.writeText(c); } catch (e) {}
        setCopied(c); haptic("light"); showToast(t("admin_copied"), "ok");
        setTimeout(() => setCopied(null), 1500);
      }
      const numStyle = { width:64, boxSizing:"border-box", padding:"6px 8px", borderRadius:7, background:"rgba(0,0,0,.4)", border:"1px solid rgba(var(--gold2-rgb),.3)", color:"var(--text)", fontSize:11, outline:"none" };

      return (
        <Card style={{ marginBottom:12, padding:"12px" }}>
          <div style={{ display:"flex", alignItems:"center", gap:8 }}>
            <div style={{ flex:1, minWidth:0 }}>
              <div style={{ fontFamily:"'Cinzel',serif", fontSize:13, color:"var(--gold2)" }}>{srv.name} <span style={{ fontSize:10, color:"var(--muted)" }}>· {srv.key}</span></div>
              <div style={{ fontSize:10, color:"var(--muted)", marginTop:2 }}>{srv.monetization_enabled ? "💰" : "🧪"} {isMain ? "" : (srv.requires_code ? "🔒" : "🌍")}</div>
            </div>
            <span style={{ fontSize:9.5, color:statusColor, border:`1px solid ${cssHex(statusColor)}66`, borderRadius:6, padding:"2px 6px", flexShrink:0 }}>{statusLabel}</span>
          </div>

          {/* Rename — available for every world incl. main */}
          <div style={{ display:"flex", gap:6, marginTop:8 }}>
            <input value={nameVal} onChange={(e) => setNameVal(e.target.value)} placeholder={t("admin_rename_ph")} style={{ ...numStyle, width:"auto", flex:1 }} />
            <ActionBtn variant="ghost" disabled={busy} onClick={renameGo} style={{ fontSize:10 }}>{t("admin_rename_btn")}</ActionBtn>
          </div>

          {isMain ? (
            <div style={{ marginTop:8, fontSize:10.5, color:"var(--muted)" }}>{t("admin_main_locked")}</div>
          ) : (
            <div>
              <div style={{ marginTop:10, fontSize:11, color:"var(--gold3)", fontWeight:600 }}>{t("admin_balance_title")}</div>
              {Object.keys(defaults || {}).map(kk => {
                const _kind = _ADMIN_BAL_KIND[kk] || {};
                const _isToggle = _kind.kind === "toggle";
                const _isScalar = _kind.kind === "scalar";
                const _on = Number(bal[kk]) > 0;
                const _desc = _ADMIN_BAL_DESC[kk];
                return (
                  <div key={kk} style={{ marginTop:8, paddingTop:8, borderTop:"1px solid rgba(255,255,255,.05)" }}>
                    <div style={{ display:"flex", alignItems:"center", gap:8 }}>
                      <div style={{ flex:1, minWidth:0 }}>
                        <div style={{ fontSize:11, color:"var(--text)" }}>{t(_ADMIN_BAL_LABEL[kk] || kk)}</div>
                        <div style={{ fontSize:9, color: live.has(kk) ? "#9fd6a0" : "var(--muted)" }}>{live.has(kk) ? t("admin_balance_live") : t("admin_balance_stored")}</div>
                      </div>
                      {_isToggle ? (
                        <ActionBtn variant={_on ? "primary" : "ghost"} disabled={busy}
                          onClick={() => setBal(b => ({ ...b, [kk]: _on ? 0 : 1 }))}
                          style={{ fontSize:10, flexShrink:0, minWidth:62 }}>
                          {_on ? t("admin_features_on") : t("admin_features_off")}
                        </ActionBtn>
                      ) : (
                        <input type="number"
                          step={_kind.step != null ? _kind.step : 0.05}
                          min={_kind.min != null ? _kind.min : 0.01}
                          max={_kind.max != null ? _kind.max : 100}
                          value={bal[kk] != null ? bal[kk] : (_isScalar ? 0 : 1)}
                          onChange={(e) => setBal(b => ({ ...b, [kk]: e.target.value }))}
                          style={{ ...numStyle, width:72 }} />
                      )}
                    </div>
                    {_desc && (
                      <div style={{ fontSize:9.5, color:"var(--muted)", marginTop:4, lineHeight:1.4 }}>{t(_desc)}</div>
                    )}
                  </div>
                );
              })}
              <ActionBtn variant="primary" disabled={busy} onClick={saveBalance} style={{ marginTop:8, width:"100%" }}>{t("admin_balance_save")}</ActionBtn>

              <div style={{ marginTop:12, fontSize:11, color:"var(--gold3)", fontWeight:600 }}>{t("admin_set_status")}</div>
              <div style={{ display:"flex", gap:6, marginTop:6 }}>
                {["active", "maintenance", "closed"].map(st => (
                  <ActionBtn key={st} variant={srv.status === st ? "primary" : "ghost"} disabled={busy} onClick={() => setStatus(st)} style={{ flex:1, fontSize:10 }}>
                    {{ active:t("admin_status_active"), maintenance:t("admin_status_maintenance"), closed:t("admin_status_closed") }[st]}
                  </ActionBtn>
                ))}
              </div>

              <div style={{ marginTop:12, fontSize:11, color:"var(--gold3)", fontWeight:600 }}>{t("admin_flags_title")}</div>
              <div style={{ display:"flex", gap:6, marginTop:6 }}>
                <ActionBtn variant={srv.monetization_enabled ? "primary" : "ghost"} disabled={busy} onClick={() => toggleFlag("monetization_enabled", !srv.monetization_enabled)} style={{ flex:1, fontSize:9.5 }}>{srv.monetization_enabled ? `💰 ${t("admin_flag_monetized")}` : `🧪 ${t("admin_flag_sandbox")}`}</ActionBtn>
                <ActionBtn variant={srv.is_public ? "primary" : "ghost"} disabled={busy} onClick={() => toggleFlag("is_public", !srv.is_public)} style={{ flex:1, fontSize:9.5 }}>{srv.is_public ? `🌍 ${t("admin_flag_public")}` : `🚫 ${t("admin_flag_private")}`}</ActionBtn>
                <ActionBtn variant={srv.requires_code ? "primary" : "ghost"} disabled={busy} onClick={() => toggleFlag("requires_code", !srv.requires_code)} style={{ flex:1, fontSize:9.5 }}>{srv.requires_code ? `🔒 ${t("admin_flag_code")}` : `🔓 ${t("admin_flag_nocode")}`}</ActionBtn>
              </div>

              <div style={{ marginTop:12, fontSize:11, color:"var(--gold3)", fontWeight:600 }}>{t("admin_codes_title")}</div>
              {(srv.codes || []).length === 0 ? (
                <div style={{ fontSize:10, color:"var(--muted)", marginTop:4 }}>{t("admin_codes_empty")}</div>
              ) : (srv.codes || []).map(c => (
                <div key={c.code} style={{ display:"flex", alignItems:"center", gap:6, marginTop:6, opacity: c.active ? 1 : 0.5 }}>
                  <code style={{ flex:1, fontSize:12, letterSpacing:1, color:"var(--gold2)", background:"rgba(0,0,0,.35)", padding:"5px 8px", borderRadius:6, whiteSpace:"nowrap", overflow:"hidden", textOverflow:"ellipsis" }}>{c.code}</code>
                  <span style={{ fontSize:8.5, color:"var(--muted)", flexShrink:0 }}>
                    {t("admin_code_uses", { label: (c.max_uses == null ? `${c.uses}/∞` : `${c.uses}/${c.max_uses}`) })}
                    {c.expired ? ` · ${t("admin_code_expired")}` : ((!c.active && !c.expired) ? ` · ${t("admin_code_spent")}` : "")}
                  </span>
                  <ActionBtn variant="ghost" onClick={() => copyCode(c.code)} style={{ fontSize:10, padding:"4px 8px", flexShrink:0 }}>{copied === c.code ? t("admin_copied") : t("admin_copy")}</ActionBtn>
                </div>
              ))}
              <div style={{ display:"flex", gap:6, marginTop:8, alignItems:"center" }}>
                <input type="number" min="1" value={genUses} onChange={(e) => setGenUses(e.target.value)} title={t("admin_gen_code_uses")} placeholder={t("admin_gen_code_uses")} style={numStyle} />
                <input type="number" min="1" value={genDays} onChange={(e) => setGenDays(e.target.value)} title={t("admin_gen_code_days")} placeholder={t("admin_gen_code_days")} style={{ ...numStyle, width:"auto", flex:1 }} />
              </div>
              <ActionBtn variant="ghost" disabled={busy} onClick={genCode} style={{ marginTop:8, width:"100%" }}>🎟️ {t("admin_gen_code")}</ActionBtn>
            </div>
          )}
        </Card>
      );
    }

    const _ADMIN_INPUT = { boxSizing:"border-box", padding:"8px 10px", borderRadius:7, background:"rgba(0,0,0,.4)", border:"1px solid rgba(var(--gold2-rgb),.3)", color:"var(--text)", fontSize:12, outline:"none" };
    const _DOSSIER_SEC = { marginTop:11, marginBottom:3, fontSize:10, color:"var(--gold3)", fontWeight:700, textTransform:"uppercase", letterSpacing:0.5 };

    function AdminPlayerRow({ p, onClick }) {
      return (
        <Card onClick={onClick} style={{ marginBottom:6, padding:"9px 11px", cursor:"pointer" }}>
          <div style={{ display:"flex", alignItems:"center", gap:8 }}>
            <div style={{ flex:1, minWidth:0 }}>
              <div style={{ fontSize:12.5, color:"var(--gold2)", whiteSpace:"nowrap", overflow:"hidden", textOverflow:"ellipsis" }}>{p.dao_name || p.display_name || "—"} <span style={{ fontSize:9, color:"var(--muted)" }}>#{p.telegram_id}</span></div>
              <div style={{ fontSize:9.5, color:"var(--muted)", marginTop:2 }}>R{p.realm}·{p.sub_layer} · 🪨{fmtNum(p.spirit_stones)} · 💠{fmtNum(p.spirit_jade)} · ☯{p.karma}</div>
            </div>
            <span style={{ color:"var(--muted)", fontSize:14 }}>›</span>
          </div>
        </Card>
      );
    }

    function AdminPlayerDetail({ player, world, isMain, onBack, onViewLogs }) {
      const [p, setP] = useState(player);
      const [busy, setBusy] = useState(false);
      const [stones, setStones] = useState("");
      const [jade, setJade] = useState("");
      const [realm, setRealm] = useState(String(player.realm));
      const [sub, setSub] = useState(String(player.sub_layer));
      const [confirm, setConfirm] = useState(null); // {label, run} when main needs a 2nd tap

      async function _call(endpoint, body, onOk, confirmed) {
        if (busy) return; setBusy(true); haptic("warning");
        try {
          // confirm:true is ONLY sent from the confirmed path → the server's
          // confirm-required-on-main gate is real defense-in-depth (a write to
          // main without an explicit confirm is rejected server-side).
          const res = await api(endpoint, { world_key: world, telegram_id: p.telegram_id, confirm: !!confirmed, ...body });
          if (res && res.ok) { haptic("success"); onOk(res); showToast(t("admin_grant_ok"), "ok"); }
          else if (res && res.reason === "confirm_required") { haptic("error"); showToast(t("admin_main_danger"), "err"); }
          else { haptic("error"); showToast(t(res && res.reason === "out_of_range" ? "admin_set_realm_range" : "admin_error"), "err"); }
        } catch (e) { haptic("error"); showToast(t("admin_error"), "err"); }
        finally { setBusy(false); setConfirm(null); }
      }
      function guard(label, run) {
        // run(confirmed): a SECONDARY world runs immediately (server doesn't gate);
        // `main` shows a 2nd-tap card, then runs confirmed — the only path that
        // sends confirm:true, so the server gate is genuinely enforced.
        if (isMain) { setConfirm({ label, run: () => run(true) }); haptic("warning"); }
        else { run(false); }
      }
      function grant(field, amtStr, clear) {
        const amount = parseInt(amtStr, 10);
        if (isNaN(amount) || amount === 0) return;
        guard(t("admin_grant_confirm", { field, amount }), (confirmed) =>
          _call("admin/player_grant", { field, amount }, (res) => { setP(prev => ({ ...prev, [field]: res.new })); clear(); }, confirmed));
      }
      function setRealmGo() {
        const r = parseInt(realm, 10), s = parseInt(sub, 10);
        if (isNaN(r) || isNaN(s)) return;
        guard(t("admin_set_realm_confirm", { realm: r, sub: s }), (confirmed) =>
          _call("admin/player_set_realm", { realm: r, sub_layer: s }, (res) => setP(prev => ({ ...prev, realm: res.realm, sub_layer: res.sub_layer })), confirmed));
      }

      const Field = ({ label, val }) => (
        <div style={{ display:"flex", justifyContent:"space-between", fontSize:11, padding:"2px 0" }}>
          <span style={{ color:"var(--muted)" }}>{label}</span><span style={{ color:"var(--text)" }}>{val}</span>
        </div>
      );
      return (
        <div>
          <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between", marginBottom:8 }}>
            <div onClick={onBack} style={{ cursor:"pointer", fontSize:11, color:"var(--gold3)" }}>‹ {t("admin_ops_back")}</div>
            {onViewLogs && <ActionBtn variant="ghost" onClick={() => onViewLogs(p.telegram_id)} style={{ fontSize:10, padding:"4px 9px" }}>📋 {t("admin_player_logs")}</ActionBtn>}
          </div>
          <Card style={{ padding:"12px", marginBottom:10 }}>
            <div style={{ fontFamily:"'Cinzel',serif", fontSize:14, color:"var(--gold2)" }}>{p.dao_name || p.display_name || "—"}{p.active_title ? <span style={{ fontSize:9, color:"var(--gold3)" }}> · {p.active_title}</span> : null}</div>
            <div style={{ fontSize:9.5, color:"var(--muted)", marginBottom:2 }}>#{p.telegram_id}{p.username ? ` · @${p.username}` : ""} · {world}</div>

            <div style={_DOSSIER_SEC}>{t("admin_dossier_progress")}</div>
            <Field label={t("admin_player_realm")} val={`R${p.realm} · ${p.sub_layer}`} />
            <Field label={t("admin_dossier_cb")} val={fmtNum(Math.round(p.cultivation_base || 0))} />
            <Field label={t("admin_dossier_prestige")} val={`${p.prestige_level || 0} · ${fmtNum(p.prestige_points || 0)} pts`} />
            <Field label={t("admin_dossier_foundation")} val={`${p.foundation_quality || "—"}${p.foundation_locked ? " 🔒" : ""}`} />
            <Field label={t("admin_dossier_core")} val={p.core_quality || "—"} />
            <Field label={t("admin_dossier_body")} val={`T${p.body_tempering_level || 0}`} />

            <div style={_DOSSIER_SEC}>{t("admin_dossier_treasures")}</div>
            <Field label="⚔ Battle Power" val={fmtNum(p.battle_power)} />
            <Field label="👻 Soul" val={fmtNum(p.soul_strength)} />
            <Field label="🔮 Percep." val={fmtNum(p.perception)} />
            <Field label="🍀 Luck" val={fmtNum(p.luck)} />
            <Field label="🌀 Qi" val={`${fmtNum(p.qi)} / ${fmtNum(p.qi_capacity)}`} />

            <div style={_DOSSIER_SEC}>{t("admin_dossier_economy")}</div>
            <Field label="🪨 Stones" val={fmtNum(p.spirit_stones)} />
            <Field label="💠 Jade" val={fmtNum(p.spirit_jade)} />
            <Field label={t("admin_dossier_jade_earned")} val={fmtNum(p.lifetime_jade_earned || 0)} />
            <Field label="☯ Karma" val={`${p.karma} · ${p.path || "—"}`} />

            <div style={_DOSSIER_SEC}>{t("admin_dossier_identity")}</div>
            <Field label={t("admin_dossier_continent")} val={p.current_continent || "—"} />
            <Field label={t("admin_dossier_sect")} val={p.sect_id ? `${p.sect_id}${p.sect_rank ? " · " + p.sect_rank : ""}` : "—"} />
            <Field label={t("admin_dossier_spirit_root")} val={String(p.spirit_root)} />
            <Field label={t("admin_dossier_lang")} val={p.language || "—"} />
            <Field label={t("admin_dossier_created")} val={p.created_at_ms ? new Date(p.created_at_ms).toLocaleDateString() : "—"} />

            <div style={_DOSSIER_SEC}>{t("admin_dossier_monet")}</div>
            <Field label="VIP" val={`${p.vip_level || 0} · ⭐${fmtNum(p.stars_spent || 0)}`} />
            <Field label={t("admin_dossier_purchases")} val={`${p.purchases_count || 0} · 💠${fmtNum(p.jade_bought_total || 0)}`} />
            {p.monthly_card ? <Field label={t("admin_dossier_monthly")} val={p.monthly_card} /> : null}
            {(p.recent_purchases || []).length ? (p.recent_purchases || []).map((rp, i) => (
              <div key={i} style={{ fontSize:9.5, color:"var(--muted)", display:"flex", justifyContent:"space-between", padding:"1px 0" }}>
                <span style={{ overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap" }}>{rp.product}</span>
                <span style={{ flexShrink:0 }}>⭐{Math.round(rp.amount)} · {rp.at_ms ? new Date(rp.at_ms).toLocaleDateString() : ""}</span>
              </div>
            )) : null}

            <div style={_DOSSIER_SEC}>{t("admin_dossier_collection")}</div>
            <Field label={t("admin_dossier_counts")} val={`🗡️${(p.counts||{}).techniques||0} · 🎒${(p.counts||{}).inventory||0} · 🏆${(p.counts||{}).achievements||0} · ⚔️${(p.counts||{}).artifacts||0}`} />
          </Card>

          {isMain && <div style={{ fontSize:10, color:"#e6a36a", border:"1px solid rgba(230,140,90,.4)", borderRadius:7, padding:"7px 9px", marginBottom:10 }}>⚠️ {t("admin_main_danger")}</div>}

          {confirm ? (
            <Card style={{ padding:"12px", marginBottom:10, border:"1px solid rgba(230,140,90,.5)" }}>
              <div style={{ fontSize:11.5, color:"var(--gold3)", marginBottom:8 }}>{confirm.label}</div>
              <div style={{ display:"flex", gap:8 }}>
                <ActionBtn variant="primary" disabled={busy} onClick={confirm.run} style={{ flex:1 }}>{t("admin_confirm_main")}</ActionBtn>
                <ActionBtn variant="ghost" disabled={busy} onClick={() => setConfirm(null)} style={{ flex:1 }}>{t("lobby_switch_cancel")}</ActionBtn>
              </div>
            </Card>
          ) : (
            <div>
              <Card style={{ padding:"12px", marginBottom:10 }}>
                <div style={{ fontSize:11, color:"var(--gold3)", fontWeight:600, marginBottom:6 }}>{t("admin_grant_title")}</div>
                <div style={{ display:"flex", gap:6, alignItems:"center", marginBottom:6 }}>
                  <span style={{ fontSize:11, width:54 }}>🪨 Stones</span>
                  <input type="number" value={stones} onChange={(e) => setStones(e.target.value)} placeholder="±0" style={{ ..._ADMIN_INPUT, flex:1 }} />
                  <ActionBtn variant="ghost" disabled={busy} onClick={() => grant("spirit_stones", stones, () => setStones(""))}>+</ActionBtn>
                </div>
                <div style={{ display:"flex", gap:6, alignItems:"center" }}>
                  <span style={{ fontSize:11, width:54 }}>💠 Jade</span>
                  <input type="number" value={jade} onChange={(e) => setJade(e.target.value)} placeholder="±0" style={{ ..._ADMIN_INPUT, flex:1 }} />
                  <ActionBtn variant="ghost" disabled={busy} onClick={() => grant("spirit_jade", jade, () => setJade(""))}>+</ActionBtn>
                </div>
              </Card>
              <Card style={{ padding:"12px" }}>
                <div style={{ fontSize:11, color:"var(--gold3)", fontWeight:600, marginBottom:6 }}>{t("admin_set_realm")}</div>
                <div style={{ display:"flex", gap:6, alignItems:"center" }}>
                  <input type="number" min="0" value={realm} onChange={(e) => setRealm(e.target.value)} title="realm" style={{ ..._ADMIN_INPUT, width:60 }} />
                  <input type="number" min="1" value={sub} onChange={(e) => setSub(e.target.value)} title="sub_layer" style={{ ..._ADMIN_INPUT, width:60 }} />
                  <ActionBtn variant="ghost" disabled={busy} onClick={setRealmGo} style={{ flex:1 }}>{t("admin_set_realm_btn")}</ActionBtn>
                </div>
              </Card>
            </div>
          )}
        </div>
      );
    }

    function AdminPlayersView({ world, isMain, onViewLogs }) {
      const [q, setQ] = useState("");
      const [results, setResults] = useState(null);
      const [selected, setSelected] = useState(null);
      const reqRef = useRef(0);

      async function doSearch(query) {
        const myReq = ++reqRef.current;
        try {
          const res = await api("admin/player_search", { world_key: world, q: (query === undefined ? q : query).trim() });
          if (myReq !== reqRef.current) return;  // a newer keystroke superseded this
          setResults((res && res.ok) ? (res.players || []) : []);
        } catch (e) { if (myReq === reqRef.current) setResults([]); }
      }
      // Live search WHILE typing (debounced) + a default browse list when the box
      // is empty (on open / world switch) — type anything (name OR id), or nothing.
      useEffect(() => {
        const tm = setTimeout(() => { doSearch(q); }, 280);
        return () => clearTimeout(tm);
      }, [q, world]);
      // A player opened from world A must not bleed into world B.
      useEffect(() => { setSelected(null); }, [world]);

      async function openDetail(pid) {
        try {
          const res = await api("admin/player_detail", { world_key: world, telegram_id: pid });
          if (res && res.ok) setSelected(res); else showToast(t("admin_error"), "err");
        } catch (e) { showToast(t("admin_error"), "err"); }
      }
      if (selected) return <AdminPlayerDetail player={selected} world={world} isMain={isMain} onBack={() => setSelected(null)} onViewLogs={onViewLogs} />;
      return (
        <div>
          <input value={q} onChange={(e) => setQ(e.target.value)} placeholder={t("admin_ops_search_ph")}
            style={{ ..._ADMIN_INPUT, width:"100%", marginBottom:8 }} />
          {results === null ? <ListSkeleton rows={4} />
            : results.length === 0 ? <div style={{ fontSize:11, color:"var(--muted)", textAlign:"center", padding:"12px 0" }}>{t("admin_ops_no_results")}</div>
            : results.map(p => <AdminPlayerRow key={p.telegram_id} p={p} onClick={() => openDetail(p.telegram_id)} />)}
        </div>
      );
    }

    function AdminEconomyView({ world }) {
      const { data, loading, error } = useApi("admin/economy", { world_key: world }, [world]);
      if (loading && !data) return <ListSkeleton rows={3} />;
      if (error) return <ErrBanner msg={t("admin_error")} />;
      if (!data || !data.ok) return <ErrBanner msg={t("admin_error")} />;
      const Row = ({ k, v }) => (
        <div style={{ display:"flex", justifyContent:"space-between", fontSize:11.5, padding:"3px 0" }}>
          <span style={{ color:"var(--muted)" }}>{k}</span><span style={{ color:"var(--text)" }}>{v}</span>
        </div>
      );
      return (
        <div>
          <Card style={{ padding:"12px", marginBottom:10 }}>
            <Row k={t("admin_econ_players")} v={fmtNum(data.player_count)} />
            <Row k={t("admin_econ_total_stones")} v={`🪨 ${fmtNum(data.total_stones)}`} />
            <Row k={t("admin_econ_total_jade")} v={`💠 ${fmtNum(data.total_jade)}`} />
            <Row k={t("admin_econ_avg_stones")} v={`🪨 ${fmtNum(data.avg_stones)}`} />
            <Row k={t("admin_econ_payers")} v={fmtNum(data.payers)} />
          </Card>
          <Card style={{ padding:"12px" }}>
            <div style={{ fontSize:11, color:"var(--gold3)", fontWeight:600, marginBottom:6 }}>{t("admin_econ_top")}</div>
            {(data.top || []).map((row, i) => (
              <div key={i} style={{ display:"flex", justifyContent:"space-between", fontSize:11, padding:"2px 0" }}>
                <span style={{ color:"var(--muted)" }}>{i + 1}. {row.name}</span><span style={{ color:"var(--gold2)" }}>🪨 {fmtNum(row.stones)}</span>
              </div>
            ))}
          </Card>
        </div>
      );
    }

    function AdminLogsView({ seed }) {
      const [reloadKey, setReloadKey] = useState(0);
      const [live, setLive] = useState(true);
      const [level, setLevel] = useState("");
      const [q, setQ] = useState(seed || "");
      // Seeded from a player dossier ("ver logs deste jogador") → filter by his id.
      useEffect(() => { if (seed) { setQ(seed); setLevel(""); } }, [seed]);
      // Live tail (the fix for "logs só mostram o arranque"): the backend ring
      // buffer already captures every record (INFO+), but this view only fetched
      // once. Re-poll every 3s while "live" is on. useVisibleInterval pauses
      // automatically when the Telegram webview is hidden, so it costs nothing
      // when the owner isn't looking.
      useVisibleInterval(() => { if (live) setReloadKey(x => x + 1); }, 3000);
      const { data, loading, error } = useApi("admin/logs", { level, q, limit: 150 }, [reloadKey]);
      const logs = (data && data.logs) || [];
      const lvlColor = { ERROR:"#e08a8a", CRITICAL:"#e08a8a", WARNING:"#e6c46a", INFO:"#9fb6d6", DEBUG:"#888" };
      return (
        <div>
          <div style={{ display:"flex", gap:6, marginBottom:8, alignItems:"center" }}>
            <input value={q} onChange={(e) => setQ(e.target.value)} placeholder={t("admin_logs_filter_ph")}
              onKeyDown={(e) => { if (e.key === "Enter") setReloadKey(x => x + 1); }} style={{ ..._ADMIN_INPUT, flex:1 }} />
            <ActionBtn variant={live ? "primary" : "ghost"}
              onClick={() => { const wasLive = live; setLive(v => !v); if (!wasLive) setReloadKey(x => x + 1); }}>
              {live ? t("admin_logs_live") : t("admin_logs_paused")}
            </ActionBtn>
            <ActionBtn variant="ghost" onClick={() => setReloadKey(x => x + 1)}>↻</ActionBtn>
          </div>
          <SegControl options={[
            { value:"", label:t("admin_logs_all") },
            { value:"INFO", label:"INFO" },
            { value:"WARNING", label:"WARN" },
            { value:"ERROR", label:"ERR" },
          ]} value={level} onChange={(v) => { setLevel(v); setReloadKey(x => x + 1); }} />
          {loading && !data ? <ListSkeleton rows={5} />
            : error ? <ErrBanner msg={t("admin_error")} />
            : logs.length === 0 ? <div style={{ fontSize:11, color:"var(--muted)", textAlign:"center", padding:"12px 0" }}>{t("admin_logs_empty")}</div>
            : (
              <div style={{ background:"rgba(0,0,0,.4)", borderRadius:8, padding:"8px", maxHeight:340, overflowY:"auto" }}>
                {logs.slice().reverse().map((l, i) => (
                  <div key={i} style={{ fontFamily:"monospace", fontSize:9.5, lineHeight:1.5, marginBottom:3, wordBreak:"break-word" }}>
                    <span style={{ color: lvlColor[l.level] || "#aaa" }}>[{l.level}]</span>{" "}
                    <span style={{ color:"#778" }}>{l.logger}</span>{" "}
                    <span style={{ color:"var(--text)" }}>{l.msg}</span>
                  </div>
                ))}
              </div>
            )}
        </div>
      );
    }

    // Per-world feature flags (FF infra). Reads the enriched admin/servers payload
    // (features + feature_defaults), draws a toggle per catalog key, and POSTs a
    // single-flag patch to admin/set_features. `main` is read-only (the backend
    // ignores its features by construction — Lei §1). Self-contained refresh so a
    // toggle re-pulls fresh state, exactly like AdminLogsView.
    function AdminFeaturesView({ world }) {
      const [reloadKey, setReloadKey] = useState(0);
      const [busy, setBusy] = useState(false);
      const { data, loading, error } = useApi("admin/servers", {}, [reloadKey]);
      const isMain = world === "main";
      const srv = ((data && data.servers) || []).find(s => s.key === world) || null;
      const defaults = (data && data.feature_defaults) || {};
      const cur = (srv && srv.features) || {};
      const keys = Object.keys(defaults);

      async function toggle(fkey, value) {
        if (busy || isMain) return; setBusy(true); haptic("warning");
        try {
          const res = await api("admin/set_features", { world_key: world, features: { [fkey]: value } });
          if (res && res.ok) { haptic("success"); showToast(t("admin_features_saved"), "ok"); setReloadKey(x => x + 1); }
          else { haptic("error"); showToast(t((res && res.reason === "main_locked") ? "admin_features_main_locked" : "admin_error"), "err"); }
        } catch (e) { haptic("error"); showToast(t("admin_error"), "err"); } finally { setBusy(false); }
      }

      if (loading && !data) return <ListSkeleton rows={4} />;
      if (error) return <ErrBanner msg={t("admin_error")} />;
      if (isMain) return (
        <Card style={{ padding:"12px" }}>
          <div style={{ fontSize:11.5, color:"var(--gold3)", lineHeight:1.5 }}>🔒 {t("admin_features_main_locked")}</div>
        </Card>
      );
      if (keys.length === 0) return <div style={{ fontSize:11, color:"var(--muted)", textAlign:"center", padding:"12px 0" }}>{t("admin_ops_no_results")}</div>;
      return (
        <div>
          {keys.map(fk => {
            const on = !!cur[fk];
            return (
              <Card key={fk} style={{ marginBottom:8, padding:"11px 12px" }}>
                <div style={{ display:"flex", alignItems:"center", gap:8 }}>
                  <div style={{ flex:1, minWidth:0 }}>
                    <div style={{ fontSize:12, color:"var(--text)" }}>{t("feature_" + fk)}</div>
                    <div style={{ fontSize:9.5, color:"var(--muted)", marginTop:2, lineHeight:1.4 }}>{t("feature_" + fk + "_desc")}</div>
                  </div>
                  <ActionBtn variant={on ? "primary" : "ghost"} disabled={busy} onClick={() => toggle(fk, !on)} style={{ fontSize:10, flexShrink:0, minWidth:62 }}>
                    {on ? t("admin_features_on") : t("admin_features_off")}
                  </ActionBtn>
                </div>
              </Card>
            );
          })}
        </div>
      );
    }

    function AdminOpsSection({ servers }) {
      const list = (servers && servers.length) ? servers : [{ key:"main", name:t("lobby_main_name") }];
      const [world, setWorld] = useState(list[0].key);
      const [sub, setSub] = useState("players");
      const [logSeed, setLogSeed] = useState("");
      const isMain = world === "main";
      // From a player dossier → jump to Logs pre-filtered by his telegram id.
      const viewPlayerLogs = (tid) => { setLogSeed(String(tid)); setSub("logs"); };
      return (
        <div>
          <div style={{ fontSize:10.5, color:"var(--muted)", marginBottom:4 }}>{t("admin_ops_world")}</div>
          <SegControl options={list.map(s => ({ value:s.key, label:s.name }))} value={world} onChange={setWorld} />
          <SegControl options={[
            { value:"players", label:t("admin_ops_tab_players") },
            { value:"economy", label:t("admin_ops_tab_economy") },
            { value:"features", label:t("admin_ops_tab_features") },
            { value:"logs", label:t("admin_ops_tab_logs") },
          ]} value={sub} onChange={setSub} />
          {sub === "players" && <AdminPlayersView world={world} isMain={isMain} onViewLogs={viewPlayerLogs} />}
          {sub === "economy" && <AdminEconomyView world={world} />}
          {sub === "features" && <AdminFeaturesView world={world} />}
          {sub === "logs" && <AdminLogsView seed={logSeed} />}
        </div>
      );
    }

    function AdminPanelModal({ onClose }) {
      const [reloadKey, setReloadKey] = useState(0);
      const { data, loading, error } = useApi("admin/servers", null, [reloadKey]);
      const reload = () => setReloadKey(x => x + 1);
      const [view, setView] = useState("servers");
      const servers = (data && data.servers) || [];
      return (
        <Modal onClose={onClose} title={`🛡️ ${t("admin_title")}`} accent="rgba(var(--gold2-rgb),.5)">
          <SegControl options={[
            { value:"servers", label:t("admin_tab_servers") },
            { value:"ops", label:t("admin_tab_ops") },
          ]} value={view} onChange={setView} />
          {loading && !data ? <ListSkeleton rows={4} />
            : error ? <ErrBanner msg={t("admin_error")} />
            : (data && !data.control_enabled) ? (
                <Card><div style={{ padding:"14px", fontSize:11.5, color:"var(--gold3)", lineHeight:1.5 }}>{t("admin_disabled")}</div></Card>
              )
            : view === "servers" ? (
              <div>
                <AdminProvisionForm onDone={reload} />
                {servers.map(srv => (
                  <AdminServerCard key={srv.key} srv={srv} defaults={data.balance_defaults} liveKeys={data.live_keys} onReload={reload} />
                ))}
              </div>
            ) : (
              <AdminOpsSection servers={servers} />
            )}
        </Modal>
      );
    }

    // ─── Dungeons (MA-30) ────────────────────────────────────────────────────
    var DUNGEON_DIFF_KEYS = ["easy", "normal", "hard", "nightmare"];
    var DUNGEON_DIFF_MULT = { easy:0.5, normal:1.0, hard:2.0, nightmare:3.0 };
    var DUNGEON_DIFF_EMOJI = { easy:"🟢", normal:"🟡", hard:"🔴", nightmare:"💀" };

    function dngDiffLevel(key) { return DUNGEON_DIFF_KEYS.indexOf(key) + 1; }
    function dngDiffName(key) { return t("dungeon_difficulty_" + key); }

    function dngReason(reason, extras) {
      // Map endpoint `reason` codes to user-facing strings.
      switch (reason) {
        case "no_qi":
          if (extras && extras.current_qi != null && extras.qi_cost != null)
            return t("dungeon_no_qi", { current: extras.current_qi, cost: extras.qi_cost });
          return t("dungeon_no_qi_short");
        case "realm_locked":     return t("dungeon_realm_locked", { n: extras?.min_realm ?? 0 });
        case "diff_gate":        return t("dungeon_diff_gate", { diff: dngDiffName(extras?.required || "easy") });
        case "meditation_blocked": return t("dungeon_meditation_blocked");
        case "hp_too_low":       return t("dungeon_hp_too_low");
        case "not_in_dungeon":   return t("dungeon_not_in_dungeon");
        case "not_completed":    return t("dungeon_not_completed");
        case "already_in_run":   return t("dungeon_already_in_run");
        // QoL-relatos — uma masmorra de cada vez. A recusa NOMEIA a run aberta e
        // o andar; a saída (Retirar-se) é o botão que o RunRefusal desenha
        // logo abaixo do erro — um "não" sem saída seria violação da Lei §1.
        case "run_elsewhere":    return t("dungeon_run_elsewhere", {
          emoji: extras?.run?.emoji || "🗺️",
          name: extras?.run?.name || "",
          floor: extras?.run?.current_floor ?? 0,
        });
        case "run_here":         return t("dungeon_run_here", {
          emoji: extras?.run?.emoji || "🗺️",
          name: extras?.run?.name || "",
          floor: extras?.run?.current_floor ?? 0,
        });
        // MV-1 — o portal fica noutro continente (o servidor garante o gate;
        // este texto é a recusa honesta com o CTA implícito de viajar).
        case "wrong_continent":  return t("dungeon_wrong_continent", {
          emoji: extras?.continent_emoji || "🧭",
          name: safeT("continent_" + (extras?.continent || ""), null, extras?.continent || ""),
        });
        // v16.2.2 hotfix — surface the real reason when a stuck duel blocks
        // the boss spawn. Server now auto-cleans expired duels, but if a
        // legitimately live duel exists (mid-PvP or another mid-PvE), tell
        // the player to finish that one first.
        case "duel_already_active": return t("dungeon_duel_already_active");
        case "dungeon_not_found":
        case "bad_request":
        case "engine_error":
        default:
          return t("dungeon_action_failed");
      }
    }

    function fmtBagSummary(bag) {
      if (!bag || bag.empty) return [t("dungeon_bag_empty")];
      const rows = [];
      if (bag.stones)        rows.push(t("dungeon_bag_stones",        { n: fmtNum(bag.stones) }));
      if (bag.qi_pills)      rows.push(t("dungeon_bag_qi_pills",      { n: bag.qi_pills }));
      if (bag.herbs)         rows.push(t("dungeon_bag_herbs",         { n: bag.herbs }));
      if (bag.ores)          rows.push(t("dungeon_bag_ores",          { n: bag.ores }));
      if (bag.healing_pills) rows.push(t("dungeon_bag_healing",       { n: bag.healing_pills }));
      if (bag.scrolls)       rows.push(t("dungeon_bag_scrolls",       { n: bag.scrolls }));
      if (bag.dao_fragments) rows.push(t("dungeon_bag_dao_fragments", { n: bag.dao_fragments }));
      if (bag.recipe)        rows.push(t("dungeon_bag_recipe",        { name: bag.recipe }));
      return rows.length ? rows : [t("dungeon_bag_empty")];
    }

    function HPBar({ cur, max }) {
      const pct = max > 0 ? Math.max(0, Math.min(100, (cur / max) * 100)) : 0;
      const color = pct > 60 ? "var(--jade)" : pct > 30 ? "var(--gold2)" : "var(--red)";
      return (
        <div style={{ width:"100%" }}>
          <div style={{ display:"flex", justifyContent:"space-between", fontSize:11, color:"var(--muted)", marginBottom:3 }}>
            <span>❤️ {t("dungeon_hp_label")}</span>
            <span style={{ color: pct > 30 ? "var(--text)" : "var(--red)" }}>
              {fmtNum(Math.max(0, Math.round(cur)))}/{fmtNum(Math.round(max))}
            </span>
          </div>
          <div style={{ height:6, borderRadius:4, background:"rgba(255,255,255,.05)", overflow:"hidden" }}>
            <div style={{ width:`${pct}%`, height:"100%", background:color, transition:"width .3s ease" }} />
          </div>
        </div>
      );
    }

    function DropsPreview({ drops }) {
      if (!drops) return null;
      // 2026-06-12 ([jogadores]): the server now sends the FULL drop
      // table (Heavenly Jade was being cut by a top-N truncation) — chips are
      // labeled, nightmare-gated entries get 💀, the stones range says /andar.
      const nm = (it) => it.min_difficulty === "nightmare" ? `${it.name} 💀` : it.name;
      const items = [];
      let hasNightmare = false;
      if (drops.stones && (drops.stones.max || drops.stones.min)) {
        items.push({ key:"st", emoji:"💎", name:`${drops.stones.min}–${drops.stones.max} ${t("dungeon_drops_per_floor")}` });
      }
      (drops.herbs || []).forEach(h => { if (h.min_difficulty === "nightmare") hasNightmare = true; items.push({ key:"h"+h.id, emoji:h.emoji, name:nm(h) }); });
      (drops.ores || []).forEach(o => { if (o.min_difficulty === "nightmare") hasNightmare = true; items.push({ key:"o"+o.id, emoji:o.emoji, name:nm(o) }); });
      (drops.pills || []).forEach(p => { if (p.min_difficulty === "nightmare") hasNightmare = true; items.push({ key:"p"+p.id, emoji:p.emoji, name:nm(p) }); });
      if (drops.pill_chance > 0)         items.push({ key:"hp", emoji:"💊", name:`${t("dungeon_drop_heal_pill")} ${Math.round(drops.pill_chance*100)}%` });
      if (drops.qi_pill_chance > 0)      items.push({ key:"qp", emoji:"⚗️", name:`${t("dungeon_drop_qi_pill")} ${Math.round(drops.qi_pill_chance*100)}%` });
      // TEC-2 — `scroll_chance` já vem CORTADO do servidor (display = roll).
      // Sob escassez a taxa fica sub-1%: mostra 1 casa decimal para não virar
      // "0%" (mentira) nem "1%" (arredondamento generoso).
      if (drops.scroll_chance > 0) {
        const pct = drops.scroll_chance * 100;
        const shown = pct < 1 ? pct.toFixed(1) : Math.round(pct);
        items.push({ key:"sc", emoji:"📜", name:`${t("dungeon_drop_scroll")} ${shown}%` });
      }
      if (drops.dao_fragment_chance > 0) items.push({ key:"df", emoji:"💠", name:`${t("dungeon_drop_dao_frag")} ${Math.round(drops.dao_fragment_chance*100)}%` });
      if (!items.length) return null;
      return (
        <div>
          <div style={{ display:"flex", flexWrap:"wrap", gap:6, marginTop:6 }}>
            {items.map(it => (
              <div key={it.key} style={{
                fontSize:11, padding:"2px 7px",
                borderRadius:8, background:"rgba(var(--gold2-rgb),.06)",
                border:"1px solid rgba(var(--gold2-rgb),.18)", color:"var(--gold3)",
                display:"inline-flex", gap:4, alignItems:"center",
              }}>
                <span>{it.emoji}</span><span style={{ color:"var(--muted)" }}>{it.name}</span>
              </div>
            ))}
          </div>
          {hasNightmare && (
            <div style={{ fontSize:9.5, color:"var(--muted)", marginTop:4 }}>
              {t("dungeon_drops_nightmare_note")}
            </div>
          )}
          {/* TEC-2 — por que a taxa está tão baixa: a era ficou avara de artes,
              e a Biblioteca da seita é o caminho (Lei §1: o motivo é DITO).
              Gated pelo Surface Manifest — flag OFF ⇒ a linha nem existe. */}
          {featureEnabled("escassez_scrolls") && drops.scroll_chance > 0 && (
            <div style={{ fontSize:9.5, color:"var(--muted)", marginTop:4,
                          fontStyle:"italic", lineHeight:1.5 }}>
              {t(featureEnabled("biblioteca_seitas")
                 ? "scr_dng_scarcity_hint" : "scr_dng_scarcity_bare")}
            </div>
          )}
        </div>
      );
    }

    function DungeonCard({ dungeon, onClick }) {
      // 層 4.3 — as dificuldades vencidas e o mais fundo, na gramática da onda
      const onda = obraOn();
      const accessible = dungeon.accessible;
      const st = dungeon.state || {};
      const inRun = st.current_floor > 0;
      const cleared = st.completed;
      const borderColor = inRun ? "rgba(var(--jade-rgb),.55)"
        : cleared ? "rgba(var(--gold2-rgb),.45)"
        : !accessible ? "rgba(255,255,255,.08)" : "rgba(var(--gold2-rgb),.18)";
      return (
        <button onClick={() => { haptic("select"); onClick(dungeon); }} style={{
          width:"100%", textAlign:"left",
          background:"linear-gradient(180deg, rgba(var(--card-rgb),.92), rgba(8,12,22,.96))",
          border:`1px solid ${borderColor}`, borderRadius:12, padding:"10px 12px",
          display:"flex", flexDirection:"column", gap:6, cursor:"pointer",
          opacity: accessible ? 1 : 0.55,
        }}>
          <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", gap:8 }}>
            <div style={{ display:"flex", alignItems:"center", gap:8, minWidth:0 }}>
              <span style={{ fontSize:22 }}>{dungeon.emoji}</span>
              <div style={{ minWidth:0 }}>
                <div style={{ fontFamily:"'Cinzel',serif", fontWeight:600, fontSize:13.5, color:"var(--gold2)", overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap" }}>
                  {dungeon.name}
                </div>
                <div style={{ fontSize:10.5, color:"var(--muted)" }}>
                  {t("dungeon_min_realm", { n: dungeon.min_realm })} · {t("dungeon_base_bp")} {fmtNum(dungeon.base_bp)} · {dungeon.qi_cost_effective} {t("dungeon_qi_label")}/f
                  {/* MV-1: chip do continente (só chega no payload com dungeons_regionais ON) */}
                  {dungeon.continent ? ` · ${dungeon.continent_emoji || ""} ${safeT("continent_" + dungeon.continent, null, dungeon.continent)}` : ""}
                </div>
              </div>
            </div>
            <div style={{ display:"flex", flexDirection:"column", gap:3, alignItems:"flex-end" }}>
              {!accessible && <Badge variant="red">{ico("🔒","lock",{ size:11, style:{ display:"inline-block", verticalAlign:"-1px" } })}</Badge>}
              {inRun && <Badge variant="jade">▶</Badge>}
              {onda ? (
                /* 層 4.3 — o recorde SEPARADO da expedição: as dificuldades
                   vencidas (do `best_difficulty`) e o andar mais fundo */
                (Number(st.best_difficulty) > 0 || st.max_floor_reached > 0) && (
                  <span data-masmorra-cartao="" style={{ display:"inline-flex", flexDirection:"column",
                                                          alignItems:"flex-end", gap:3 }}>
                    <span style={{ display:"inline-flex", alignItems:"center", gap:4 }}>
                      <MasmorraDificuldades melhor={st.best_difficulty} compacto />
                      {Number(st.best_difficulty) > 0 && (
                        <span style={{ fontSize:10, color: NIV_ONDA.paper }}>
                          {dngDiffName(DUNGEON_DIFF_KEYS[Number(st.best_difficulty) - 1])}
                        </span>
                      )}
                    </span>
                    {st.max_floor_reached > 0 && (
                      <span style={{ fontSize:10, color: NIV_ONDA.muted }}>
                        {t("masm_onda_card_fundo", { n: fmtFull(st.max_floor_reached) })}
                      </span>
                    )}
                  </span>
                )
              ) : (
                <>
                  {cleared && !inRun && st.best_difficulty_key && (
                    <span style={{ fontSize:10, color:"var(--gold3)" }}>
                      {DUNGEON_DIFF_EMOJI[st.best_difficulty_key]} {dngDiffName(st.best_difficulty_key)}
                    </span>
                  )}
                  {st.max_floor_reached > 0 && (
                    <span style={{ fontSize:10, color:"var(--muted)" }}>
                      {t("dungeon_best_floor", { n: st.max_floor_reached })}
                    </span>
                  )}
                </>
              )}
            </div>
          </div>
          <DropsPreview drops={dungeon.drops_preview} />
        </button>
      );
    }

    function DungeonEntryModal({ dungeon, qi, currentHp, maxHp, onClose, onAction, onResult, onGanho }) {
      // 層 4.3 — as dificuldades vencidas e o melhor alcance na gramática da onda
      // (só com a chave-mestra; sem ela, esta janela é a de hoje).
      const onda = obraOn();
      const [pickedDiff, setPickedDiff] = useState(null);
      const [busy, setBusy] = useState(false);
      const [err, setErr] = useState(null);
      // QoL-relatos — a run que bloqueou (run_elsewhere/run_here). Guardá-la é o
      // que permite oferecer a SAÍDA (Retirar-se) junto do "não": uma recusa
      // sem caminho seria violação da Lei §1.
      const [blockedBy, setBlockedBy] = useState(null);
      // MA-30b — count picker for sweep (owner request: "SWEEP nao me deixa
      // de novo... Tédioso"). Default 1, owner can pick 5/10/Max. Max =
      // floor(qi / qi_per_sweep). Server caps at 50 anyway.
      const [sweepCount, setSweepCount] = useState(1);
      const [pickedSweepDiff, setPickedSweepDiff] = useState(null);
      // v14.11 — drill-in para dungeon quests per-dungeon (story-driven).
      const [showQuests, setShowQuests] = useState(false);
      const st = dungeon.state || {};
      const bestDiff = st.best_difficulty || 0;
      const inRunHere = st.current_floor > 0;

      // Default difficulty: highest unlocked but not yet completed past, falling back to easy.
      useEffect(() => {
        if (pickedDiff) return;
        const unlocked = DUNGEON_DIFF_KEYS.filter((k, i) => i === 0 || bestDiff >= i);
        setPickedDiff(unlocked[Math.min(unlocked.length - 1, bestDiff)] || "easy");
      }, [pickedDiff, bestDiff]);

      async function callEnter() {
        if (busy || !pickedDiff) return;
        haptic("warning");
        setBusy(true); setErr(null);
        try {
          const res = await api("dungeons/enter", { dungeon_id: dungeon.id, difficulty: pickedDiff });
          if (!res.ok) {
            haptic("error");
            setErr(dngReason(res.reason, res));
            setBlockedBy(res.reason === "run_elsewhere" ? (res.run || null) : null);
            setBusy(false);
            // MA-30b — already_in_run: close the modal and refresh so the
            // user sees the active RunCard at the top instead of getting
            // stuck looking at the entry sheet for the same dungeon.
            if (res.reason === "already_in_run") {
              setTimeout(() => { onAction && onAction(); }, 600);
            }
            return;
          }
          // 層 4.3 — com a onda, o andar 1 CONFIRMADO vai para o corte da
          // expedição (a marca acende lá) em vez do modal do andar. A morte no
          // andar 1 não tem ganho — o caminho de hoje.
          if (res.won && res.masmorra_ganho && onGanho && onGanho(res)) {
            haptic("success");
            setBusy(false);
            onAction && onAction();
            return;
          }
          haptic(res.won ? "success" : "warning");
          onResult && onResult({
            kind: res.won ? "won_floor" : "died_floor",
            floor: res.floor || 1,
            floor_count: res.floor_count,
            loot: res.loot_this_floor,
            named_items: res.loot_named_items || [],
            hp: res.current_hp, max_hp: res.max_hp,
            dungeon,
          });
          setBusy(false);
          onAction && onAction();
        } catch (e) {
          haptic("error");
          setErr(t("dungeon_action_failed"));
          setBusy(false);
        }
      }

      async function callSweep(diff, count = 1) {
        if (busy) return;
        haptic("warning");
        setBusy(true); setErr(null);
        try {
          const res = await api("dungeons/sweep", {
            dungeon_id: dungeon.id, difficulty: diff, count: Math.max(1, count|0),
          });
          if (!res.ok) {
            haptic("error");
            setErr(dngReason(res.reason, res));
            // QoL-relatos — varrer a masmorra onde você está: a saída é retirar-se.
            setBlockedBy(res.reason === "run_here" ? (res.run || null) : null);
            setBusy(false);
            return;
          }
          haptic("success");
          onResult && onResult({
            kind: "sweep",
            difficulty: diff,
            sweep_count: res.sweep_count || count || 1,
            floors_swept: res.floors_swept,
            floors_per_sweep: res.floors_per_sweep,
            qi_cost: res.qi_cost,
            qi_per_sweep: res.qi_per_sweep,
            loot: res.loot_summary,
            named_items: res.loot_named_items || [],
            tempering: res.tempering_gained,
            core_essence: res.core_essence_gained,
            loot_mult: res.loot_mult,
            regional_bonus: res.regional_bonus || null,
            dungeon,
          });
          setBusy(false);
          onAction && onAction();
        } catch (e) {
          haptic("error");
          setErr(t("dungeon_action_failed"));
          setBusy(false);
        }
      }

      const fc = dungeon.floor_counts || {};
      const cleared = !!st.completed;
      const sweepDiff = pickedSweepDiff || (cleared && bestDiff > 0
        ? DUNGEON_DIFF_KEYS[bestDiff - 1]
        : null);
      const floorsForSweep = sweepDiff ? (fc[sweepDiff] || dungeon.floor_counts?.normal || 0) : 0;
      const qiPerSweep = (dungeon.qi_cost_effective || 0) * floorsForSweep;
      const maxSweepByQi = qiPerSweep > 0 ? Math.max(1, Math.min(50, Math.floor(qi / qiPerSweep))) : 1;

      // MA-MODAL — owner's witness case. The Enter / Sweep buttons MUST live
      // in the sticky footer or they fall off the bottom on phone-portrait
      // viewports. Two CTAs may coexist (clean run + sweep on cleared
      // dungeons), so the footer renders the relevant one based on state.
      const showEnter = dungeon.accessible && pickedDiff && !inRunHere;
      const showSweep = cleared && bestDiff > 0 && sweepDiff;
      const footer = (showEnter || showSweep) ? (
        <div style={{ display:"flex", flexDirection:"column", gap:8 }}>
          {showEnter && (
            <ActionBtn variant="primary" disabled={busy || !dungeon.accessible} onClick={callEnter} style={{ width:"100%" }}>
              {busy ? <DotSpinner /> : t("dungeon_enter_btn")}
            </ActionBtn>
          )}
          {showSweep && (
            <ActionBtn variant="primary" disabled={busy || qi < qiPerSweep * sweepCount}
              onClick={() => callSweep(sweepDiff, sweepCount)} style={{ width:"100%" }}>
              {busy ? <DotSpinner /> : `${DUNGEON_DIFF_EMOJI[sweepDiff]} ${t("dungeon_sweep_btn", { n: sweepCount })}`}
            </ActionBtn>
          )}
        </div>
      ) : null;

      const titleNode = (
        <div style={{ display:"flex", gap:10, alignItems:"center", minWidth:0 }}>
          <span style={{ fontSize:24 }}>{dungeon.emoji}</span>
          <div style={{ minWidth:0 }}>
            <div style={{ fontFamily:"'Cinzel',serif", fontWeight:700, fontSize:14.5, color:"var(--gold2)", lineHeight:1.2,
                          overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap" }}>{dungeon.name}</div>
            {/* Mesmo defeito da alquimia (ver acima) — corrigido no mesmo
                lote, porque consertar um e deixar dois e' o fix parcial que
                esta casa ja' pagou cinco vezes. */}
            <div style={{ fontSize:10.5, color:"var(--muted)", lineHeight:1.35,
                          overflowWrap:"anywhere" }}>{dungeon.description}</div>
          </div>
        </div>
      );

      return (
        <Modal onClose={onClose} title={titleNode} maxWidth={480} zIndex={60} footer={footer}
               animation="alch-pop 320ms cubic-bezier(.2,1.4,.4,1)">
          <div style={{ display:"flex", flexWrap:"wrap", gap:6, fontSize:11, color:"var(--muted)", marginBottom:10 }}>
            <Badge variant={dungeon.accessible ? "jade" : "red"}>{t("dungeon_min_realm", { n: dungeon.min_realm })}</Badge>
            <Badge>{t("dungeon_base_bp")} {fmtNum(dungeon.base_bp)}</Badge>
            <Badge>{dungeon.qi_cost_effective} {t("dungeon_qi_label")}/f</Badge>
            {st.max_floor_reached > 0 && <Badge>{onda
              ? t("masm_onda_card_fundo", { n: fmtFull(st.max_floor_reached) })
              : t("dungeon_best_floor", { n: st.max_floor_reached })}</Badge>}
          </div>

          <Card style={{ padding:"10px 12px", marginBottom:10 }}>
            <CardTitle left={t("dungeon_drops_preview")} />
            <DropsPreview drops={dungeon.drops_preview} />
          </Card>

          <Card style={{ padding:"10px 12px", marginBottom:10 }}>
            <CardTitle left={t("dungeon_pick_difficulty")} />
            <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:8, marginTop:6 }}>
              {DUNGEON_DIFF_KEYS.map((key, i) => {
                const unlocked = i === 0 || bestDiff >= i;
                const active = pickedDiff === key;
                return (
                  <button key={key} disabled={!unlocked || busy}
                    onClick={() => { haptic("select"); setPickedDiff(key); }}
                    style={{
                      padding:"8px 10px", borderRadius:10,
                      border: active ? "1px solid rgba(var(--gold2-rgb),.7)" : "1px solid rgba(255,255,255,.08)",
                      background: active ? "rgba(var(--gold2-rgb),.1)" : "rgba(255,255,255,.02)",
                      color: unlocked ? "var(--text)" : "var(--muted2)",
                      cursor: unlocked ? "pointer" : "not-allowed",
                      opacity: unlocked ? 1 : 0.55,
                      textAlign:"left", display:"flex", flexDirection:"column", gap:3,
                    }}>
                    <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center" }}>
                      {onda ? (
                        /* 層 4.3 — a marca da dificuldade: vencida (ouro), a próxima
                           a vencer (contorno), o resto. Do `best_difficulty`. */
                        <span data-masmorra-dif={key} style={{ fontWeight:600, fontSize:12, display:"inline-flex",
                                                               alignItems:"center", gap:6 }}>
                          <span aria-hidden="true" style={{ position:"relative", width:18, height:18, flex:"0 0 18px" }}>
                            <span style={{ position:"absolute", left:9, top:9, width:0, height:0 }}>
                              <MarcaOnda estado={i < bestDiff ? "got" : i === bestDiff ? "next" : "empty"} />
                            </span>
                          </span>
                          {dngDiffName(key)}
                        </span>
                      ) : (
                        <span style={{ fontWeight:600, fontSize:12 }}>{DUNGEON_DIFF_EMOJI[key]} {dngDiffName(key)}</span>
                      )}
                      {!unlocked && <span style={{ fontSize:10 }}>{ico("🔒","lock",{ size:11, style:{ display:"inline-block", verticalAlign:"-1px" } })}</span>}
                    </div>
                    <div style={{ fontSize:10, color:"var(--muted)" }}>
                      {fc[key] || "—"} {t("dungeon_floors").toLowerCase()} · {t("dungeon_loot_mult", { n: DUNGEON_DIFF_MULT[key] })}
                      {onda && i < bestDiff ? " · " + t("masm_onda_dif_vencida") : null}
                    </div>
                  </button>
                );
              })}
            </div>
          </Card>

          {err && <ErrBanner msg={err} />}

          {/* QoL-relatos — a SAÍDA junto do "não" (Lei §1): retirar-se da run que
              bloqueou, sem sair desta tela nem caçar o botão noutro lado. O
              recuo entrega 100% do saco, portanto não custa nada ao jogador. */}
          {blockedBy && (
            <div style={{ marginTop:8 }}>
              {/* ActionBtn (ui.js) e NÃO className="btn": essa classe não
                  existe em nenhuma folha que o cliente carrega — o botão
                  sairia com o chrome cru do browser dentro do modal escuro. */}
              <ActionBtn
                variant="danger"
                disabled={busy}
                style={{ width:"100%" }}
                onClick={async () => {
                  if (busy) return;
                  setBusy(true);
                  try {
                    const r = await api("dungeons/retreat", { dungeon_id: blockedBy.dungeon_id });
                    if (r && r.ok) {
                      haptic("success");
                      setErr(null);
                      setBlockedBy(null);
                      onAction && onAction();
                    } else {
                      haptic("error");
                      setErr(dngReason(r && r.reason, r));
                    }
                  } catch (e) {
                    setErr(t("dungeon_action_failed"));
                  } finally {
                    setBusy(false);
                  }
                }}
              >
                {t("dungeon_btn_retreat_from", {
                  emoji: blockedBy.emoji || "🗺️",
                  name: blockedBy.name || "",
                  floor: blockedBy.current_floor ?? 0,
                })}
              </ActionBtn>
            </div>
          )}

          {/* MA-30b — already_in_run warning: if the player is mid-run for
              THIS dungeon, hide the Enter button and surface a hint to
              close the modal and tap the active RunCard at the top. */}
          {inRunHere && (
            <div className="err-banner" style={{ marginTop:10 }}>
              {t("dungeon_already_in_run_hint")}
            </div>
          )}

          {cleared && bestDiff > 0 && (
            <Card style={{ padding:"10px 12px", marginTop:10 }}>
              <CardTitle left={t("dungeon_sweep_section")} />
              {/* Sweep difficulty picker — only difficulties already beaten. */}
              <div style={{ display:"flex", gap:6, flexWrap:"wrap", marginTop:6 }}>
                {DUNGEON_DIFF_KEYS.map((key, i) => {
                  if (bestDiff < i + 1) return null;
                  const active = sweepDiff === key;
                  return (
                    <button key={key} onClick={() => { haptic("select"); setPickedSweepDiff(key); setSweepCount(1); }}
                      disabled={busy}
                      style={{
                        padding:"5px 10px", borderRadius:8,
                        border: active ? "1px solid var(--gold)" : "1px solid rgba(var(--gold2-rgb),.22)",
                        background: active ? "rgba(var(--gold2-rgb),.14)" : "rgba(255,255,255,.02)",
                        color:"var(--text)", cursor:"pointer", fontSize:11.5, fontWeight:600,
                      }}>
                      {DUNGEON_DIFF_EMOJI[key]} {dngDiffName(key)}
                    </button>
                  );
                })}
              </div>
              {sweepDiff && (
                <>
                  {/* Count picker 1/5/10/Max — addresses owner's "tédioso"
                      feedback (every sweep needed a fresh tap). */}
                  <div style={{ display:"flex", gap:6, marginTop:10 }}>
                    {[1, 5, 10].map(n => {
                      const active = sweepCount === n;
                      const can = n <= maxSweepByQi;
                      return (
                        <button key={n} onClick={() => { haptic("select"); setSweepCount(n); }}
                          disabled={busy || !can}
                          style={{
                            flex:1, padding:"7px 0", borderRadius:8,
                            border: active ? "1px solid var(--gold)" : "1px solid rgba(255,255,255,.08)",
                            background: active ? "rgba(var(--gold2-rgb),.14)" : "rgba(0,0,0,.3)",
                            color: can ? "var(--text)" : "var(--muted2)",
                            cursor: can ? "pointer" : "not-allowed", fontSize:12, fontWeight:700,
                            fontFamily:"'Cinzel',serif", letterSpacing:.4,
                          }}>×{n}</button>
                      );
                    })}
                    <button onClick={() => { haptic("select"); setSweepCount(maxSweepByQi); }}
                      disabled={busy || maxSweepByQi <= 0}
                      style={{
                        flex:1, padding:"7px 0", borderRadius:8,
                        border: sweepCount === maxSweepByQi ? "1px solid var(--gold)" : "1px solid rgba(255,255,255,.08)",
                        background: sweepCount === maxSweepByQi ? "rgba(var(--gold2-rgb),.14)" : "rgba(0,0,0,.3)",
                        color:"var(--gold3)", cursor:"pointer", fontSize:11, fontWeight:700,
                        fontFamily:"'Cinzel',serif", letterSpacing:.4,
                      }}>{t("dungeon_sweep_max")} ({maxSweepByQi})</button>
                  </div>
                  <div style={{ marginTop:8, display:"flex", justifyContent:"space-between", fontSize:11, color:"var(--muted)" }}>
                    <span>{floorsForSweep * sweepCount}f · {sweepCount}× sweep</span>
                    <b style={{ color: qi >= qiPerSweep * sweepCount ? "var(--gold3)" : "var(--red)" }}>
                      {fmtNum(qiPerSweep * sweepCount)} Qi
                    </b>
                  </div>
                </>
              )}
            </Card>
          )}

          {/* v14.11 — Dungeon Quests CTA per-dungeon. Owner reportou ausência
              "tipo 1 dungeon pra mazmorra que vai fazer exemplo terminar o
              nightmare etc estah no menu inline". Drill-in modal mostra
              quests do DungeonQuestCatalog + accept/claim inline. Tracking
              já corre via engine durante floor wins / sweep / auto_progress. */}
          {dungeon.accessible && (
            <Card style={{ padding:"10px 12px", marginTop:10 }}>
              <ActionBtn variant="ghost" onClick={() => { haptic("light"); setShowQuests(true); }}
                         style={{ width:"100%" }}>
                📜 {t("dng_quest_modal_open_btn")}
              </ActionBtn>
            </Card>
          )}

          {showQuests && (
            <DungeonQuestsModal dungeon={dungeon}
                                onClose={() => setShowQuests(false)}
                                onChanged={() => onAction && onAction()} />
          )}
        </Modal>
      );
    }

    // ═══ 層 4.3 — AS MASMORRAS: o corte em patamares ═══════════════════════════
    //
    // A linha é do Astra («Mundo · Masmorras», `Olho/Astra/2026-09-16-…` §3),
    // textual: *"Corte da masmorra em patamares. `active_run.current_floor /
    // floor_count` posiciona a expedição; os andares comprovadamente
    // ultrapassados ficam marcados. Estar num andar não significa tê-lo
    // concluído. `max_floor_reached` aparece como melhor alcance, separado do
    // percurso atual e por dificuldade."*
    //
    // Tudo o que estas peças escrevem vem do SERVIDOR (`core/masmorra.py`): o
    // corte da expedição aberta (`run.corte`) e o ganho de cada acção
    // (`masmorra_ganho`). ⚠️ Medido: `current_floor = N` quer dizer "N VENCIDO
    // nesta expedição" (as rotas só o escrevem no ramo da vitória) — por isso a
    // tela diz "vencidos" e "próximo", nunca "está no andar N".
    //
    // Acendem: o ANDAR vencido e a DIFICULDADE concluída — só com o `acende` do
    // ganho, nunca com o toque. Nunca acendem: a Vida, o Qi, o saco, o recuo, a
    // varredura, a morte.
    //
    // ⚠️ "Por dificuldade" é só o que o servidor deixa fazer: as dificuldades ≤
    // `best_difficulty` (o gate da varredura). O andar mais fundo POR dificuldade
    // não existe no servidor — não se inventa (O_MUNDO.md §5).
    var MASM_POR_PATAMAR = 10;
    // a barra de baixo do telefone tapa 85 px da área rolável (a lição da 4.2):
    // o recibo volta à vista ACIMA dela, nunca por trás — a MESMA folga da Guilda
    var MASM_FOLGA_BAIXO = GUILDA_FOLGA_BAIXO;

    // O recibo — só do `masmorra_ganho` (o antes e o depois da MESMA transacção).
    function reciboDaMasmorra(g) {
      const L = [];
      const a = g && g.antes, d = g && g.depois;
      if (!a || !d) return L;
      const acende = g.acende || [];
      if (acende.indexOf("andar") >= 0 && g.andar) {
        L.push(Number(d.current_floor) > 0
          ? t("masm_onda_recibo_andar", { n: fmtFull(g.andar) })
          // ⚠️ `{n} de {total}`, nunca `{n} de {n}`: o `t()` troca só a PRIMEIRA
          // ocorrência de um marcador (olhado a 390: saía "12 de {n} andares")
          : t("masm_onda_recibo_fim", { dif: dngDiffName(a.difficulty || "normal"),
                                        n: fmtFull(g.andar), total: fmtFull(g.andar) }));
      }
      if (Number(d.max_floor_reached) > Number(a.max_floor_reached)) {
        L.push(t("masm_onda_recibo_alcance", { a: fmtFull(a.max_floor_reached), b: fmtFull(d.max_floor_reached) }));
      }
      if (acende.indexOf("dificuldade") >= 0) {
        const ka = DUNGEON_DIFF_KEYS[Number(a.best_difficulty) - 1];
        const kb = DUNGEON_DIFF_KEYS[Number(d.best_difficulty) - 1];
        L.push(t("masm_onda_recibo_dif", {
          a: ka ? dngDiffName(ka) : t("masm_onda_nenhuma"),
          b: kb ? dngDiffName(kb) : t("masm_onda_nenhuma"),
        }));
      }
      return L;
    }

    // O CORTE — a masmorra de lado, da entrada ao Chefe: um patamar por cada 10
    // andares, um poço que desce por eles, uma marca por andar. Vencido (ouro):
    // `andar ≤ vencidos`; o próximo (contorno de papel): `vencidos + 1`; o resto,
    // por conquistar. O último andar é o Chefe.
    function MasmorraCorte({ total, vencidos, acende, rotulo }) {
      const P = NIV_ONDA;
      const N = Math.max(0, Number(total) || 0);
      const v = Math.max(0, Math.min(N, Number(vencidos) || 0));
      if (!N) return null;
      const patamares = [];
      for (let ini = 1; ini <= N; ini += MASM_POR_PATAMAR) {
        const andares = [];
        for (let f = ini; f <= Math.min(N, ini + MASM_POR_PATAMAR - 1); f++) andares.push(f);
        patamares.push({ ini, andares });
      }
      return (
        <div role="img" aria-label={rotulo} data-masmorra-corte={N}
             style={{ position: "relative", paddingLeft: 30, minWidth: 0 }}>
          {/* o poço: a linha que desce pelos patamares */}
          <span aria-hidden="true" style={{ position: "absolute", left: 24, top: 0, bottom: 0, width: 1,
                                             background: P.line }} />
          {patamares.map(p => (
            <div key={p.ini} data-masmorra-patamar={p.ini}
                 style={{ position: "relative", display: "flex", alignItems: "center", flexWrap: "nowrap",
                          height: 26, borderBottom: "1px solid " + P.line }}>
              <span aria-hidden="true" style={Object.assign({}, _ONDA_TNUM, {
                position: "absolute", left: -30, width: 20, textAlign: "right",
                fontSize: 10.5, lineHeight: 1, color: P.muted })}>{p.ini}</span>
              {p.andares.map(f => {
                const estado = f <= v ? "got" : f === v + 1 ? "next" : "empty";
                return (
                  <span key={f} data-masmorra-andar={f} data-estado={estado}
                        style={{ position: "relative", flex: "0 0 22px", width: 22, height: 22 }}>
                    <span style={{ position: "absolute", left: 11, top: 11, width: 0, height: 0 }}>
                      <MarcaOnda estado={estado} acende={acende === f} />
                    </span>
                  </span>
                );
              })}
              {p.andares[p.andares.length - 1] === N && (
                <span data-masmorra-chefe="" style={{ display: "inline-flex", alignItems: "center", gap: 4,
                                                         marginLeft: 6, color: v >= N ? P.gold : P.muted }}>
                  <Mark name="dragon" size={16} />
                  <span style={{ fontFamily: P.label, fontSize: 9.5, lineHeight: 1, letterSpacing: ".12em",
                                 textTransform: "uppercase" }}>{t("masm_onda_chefe")}</span>
                </span>
              )}
            </div>
          ))}
        </div>
      );
    }

    // AS DIFICULDADES — vencidas (ouro), a próxima a vencer (contorno), o resto.
    // `melhor` é o `best_difficulty` do servidor; nada mais se deduz dele.
    function MasmorraDificuldades({ melhor, acende, compacto }) {
      const P = NIV_ONDA;
      const m = Math.max(0, Number(melhor) || 0);
      const vencidas = DUNGEON_DIFF_KEYS.filter((k, i) => i + 1 <= m).map(dngDiffName);
      return (
        <div role="img" data-masmorra-difs={m}
             aria-label={vencidas.length ? t("masm_onda_difs_aria", { lista: vencidas.join(", ") })
                                         : t("masm_onda_difs_nenhuma")}
             style={{ display: "flex", flexWrap: "wrap", alignItems: "center",
                      columnGap: compacto ? 2 : 14, rowGap: 6 }}>
          {DUNGEON_DIFF_KEYS.map((k, i) => {
            const nivel = i + 1;
            const estado = nivel <= m ? "got" : nivel === m + 1 ? "next" : "empty";
            return (
              <span key={k} data-masmorra-dif={k} data-estado={estado}
                    style={{ display: "inline-flex", alignItems: "center", gap: 6 }}>
                <span aria-hidden="true" style={{ position: "relative", width: 18, height: 18, flex: "0 0 18px" }}>
                  <span style={{ position: "absolute", left: 9, top: 9, width: 0, height: 0 }}>
                    <MarcaOnda estado={estado} acende={!!acende && nivel === m} />
                  </span>
                </span>
                {!compacto && (
                  <span aria-hidden="true" style={{ fontFamily: P.body, fontSize: 12.5, lineHeight: (18 / 12.5),
                                                     color: estado === "got" ? P.paper : P.muted }}>
                    {dngDiffName(k)}
                  </span>
                )}
              </span>
            );
          })}
        </div>
      );
    }

    // A EXPEDIÇÃO — o corpo da onda: o corte e a leitura LADO A LADO (no PC; no
    // telefone empilham), o recibo junto da operação. `fim` = a expedição que
    // acabou no Chefe (o corte inteiro, o recibo, e só o Fechar).
    function MasmorraExpedicao({ fim, nome, dif, total, vencidos, fundo, melhor, acendeAndar, acendeDif,
                                 recibo, reciboRef, hp, maxHp, bag, busy, erro, onAvancar, onRecuar,
                                 onFechar }) {
      const P = NIV_ONDA;
      const N = Number(total) || 0;
      const v = Math.max(0, Math.min(N, Number(vencidos) || 0));
      const faltam = Math.max(0, N - 1 - v);   // os andares ANTES do Chefe
      const proximoChefe = !fim && v + 1 === N;
      const rotulo = { fontFamily: P.label, fontSize: 10, lineHeight: 1.6, letterSpacing: ".16em",
                       textTransform: "uppercase", color: P.muted };
      const linha = Object.assign({}, _ONDA_TNUM, { fontSize: 12.5, lineHeight: (18 / 12.5), color: P.muted });
      const numero = Object.assign({}, _ONDA_TNUM, { marginLeft: "auto", fontSize: 16, lineHeight: (22 / 16),
                                                     color: P.paper, whiteSpace: "nowrap" });
      const temRecibo = !!(recibo && ((recibo.linhas || []).length || (recibo.espolio || []).length));
      return (
        <Card style={{ padding: "14px 14px 12px", marginBottom: 10 }}>
          <div data-masmorra-expedicao={fim ? "fim" : "run"}>
            <div style={{ display: "flex", alignItems: "baseline", columnGap: 12, rowGap: 2, flexWrap: "wrap",
                          marginBottom: 10 }}>
              <span style={{ fontFamily: P.serif, fontSize: 20, lineHeight: (26 / 20), color: P.paper,
                             overflowWrap: "anywhere" }}>{nome}</span>
              <span style={rotulo}>{fim ? t("masm_onda_fim") + " · " + dngDiffName(dif) : dngDiffName(dif)}</span>
            </div>
            <div style={{ display: "flex", flexWrap: "wrap", alignItems: "flex-start", gap: 16 }}>
              <div style={{ flex: "0 1 auto", minWidth: 0 }}>
                <MasmorraCorte total={N} vencidos={fim ? N : v} acende={acendeAndar || null}
                               rotulo={t("masm_onda_corte_aria", { nome, dif: dngDiffName(dif),
                                                                   n: fmtFull(fim ? N : v), total: fmtFull(N) })} />
              </div>
              <div data-masmorra-leitura="" style={{ flex: "1 1 240px", maxWidth: 460, minWidth: 0 }}>
                {/* a posição: os vencidos DESTA expedição, sobre os andares do servidor */}
                <div style={{ display: "flex", alignItems: "baseline", columnGap: 12, flexWrap: "wrap" }}>
                  <span style={rotulo}>{t("masm_onda_vencidos")}</span>
                  <span style={numero}>{t("masm_onda_de", { n: fmtFull(fim ? N : v), total: fmtFull(N) })}</span>
                </div>
                {!fim && (
                  <div style={linha}>
                    {proximoChefe ? t("masm_onda_proximo_chefe")
                      : faltam === 1 ? t("masm_onda_falta_1")
                      : t("masm_onda_faltam", { n: fmtFull(faltam) })}
                  </div>
                )}
                {/* o melhor alcance, SEPARADO do percurso — em qualquer dificuldade */}
                <div style={{ display: "flex", alignItems: "baseline", columnGap: 12, flexWrap: "wrap", marginTop: 8 }}>
                  <span style={Object.assign({}, linha, { flex: "1 1 160px" })}>{t("masm_onda_mais_fundo")}</span>
                  <span style={numero}>
                    {Number(fundo) > 0 ? t("masm_onda_andar", { n: fmtFull(fundo) }) : t("masm_onda_nenhum_andar")}
                  </span>
                </div>
                {/* por dificuldade: as vencidas (o que o servidor deixa varrer) */}
                <div style={{ marginTop: 8 }}>
                  <div style={rotulo}>{t("masm_onda_difs")}</div>
                  <div style={{ marginTop: 4 }}>
                    <MasmorraDificuldades melhor={melhor} acende={!!acendeDif} />
                  </div>
                </div>
                {/* ⚠️ A ORDEM É A LIÇÃO DE OLHAR (08/10). A 390: com o recibo ANTES
                    dos botões, o primeiro andar empurrava o "Avançar" 90 px para
                    baixo — para trás da barra e para fora do dedo de quem avança
                    andar a andar. A 1440: fora desta coluna, os botões esticavam a
                    1.050 px, longe dos números. Figura → leitura → ACÇÃO → o recibo
                    logo debaixo dela; as reservas por fim. */}
                {!fim && erro && <div style={{ marginTop: 10 }}><ErrBanner msg={erro} /></div>}
                {!fim && (
                  <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(150px, 1fr))",
                                gap: 8, marginTop: 12 }}>
                    <OndaBtn disabled={!!busy} onClick={onAvancar}>
                      {busy === "avancar" ? t("masm_onda_a_avancar")
                        : proximoChefe ? t("masm_onda_enfrentar", { n: fmtFull(N) })
                        : t("masm_onda_avancar", { n: fmtFull(v + 1) })}
                    </OndaBtn>
                    <OndaBtn kind="ghost" disabled={!!busy} onClick={onRecuar}>{t("masm_onda_recuar")}</OndaBtn>
                  </div>
                )}
                {/* o RECIBO, junto da operação — só do `masmorra_ganho` */}
                {temRecibo && (
                  <div ref={reciboRef} role="status" data-masmorra-recibo=""
                       style={{ marginTop: 12, paddingLeft: 12, borderLeft: "1px solid " + P.gold,
                                scrollMarginBottom: MASM_FOLGA_BAIXO, scrollMarginTop: 8 }}>
                    {(recibo.linhas || []).map((l, i) => (
                      <div key={i} style={Object.assign({}, _ONDA_TNUM, { fontSize: 13, lineHeight: (20 / 13),
                                                                          color: i === 0 ? P.paper : P.muted })}>{l}</div>
                    ))}
                    {(recibo.espolio || []).length > 0 && (
                      <div style={{ marginTop: 4 }}>
                        <div style={rotulo}>{t("masm_onda_espolio")}</div>
                        {recibo.espolio.map((l, i) => <div key={"e" + i} style={linha}>{l}</div>)}
                      </div>
                    )}
                  </div>
                )}
                {fim && (
                  <div style={{ marginTop: 12 }}>
                    <OndaBtn kind="ghost" onClick={onFechar}>{t("btn_close")}</OndaBtn>
                  </div>
                )}
              </div>
            </div>
            {!fim && (
              <>
                {/* a Vida é reserva: o fio de sempre, nunca uma conquista */}
                <div style={{ marginTop: 12 }}><HPBar cur={hp} max={maxHp} /></div>
                <div data-masmorra-saco="" style={{ marginTop: 10, padding: "8px 10px", background: P.wash,
                                                     border: "1px solid " + P.line }}>
                  <div style={rotulo}>{t("dungeon_bag")}</div>
                  {fmtBagSummary(bag).map((row, i) => <div key={i} style={linha}>{row}</div>)}
                </div>
              </>
            )}
          </div>
        </Card>
      );
    }

    function DungeonRunCard({ run, currentHp, maxHp, qi, qiCap, onAction, onResult,
                              onGanho, onFimMasmorra, recibo, acende, reciboRef }) {
      const [busy, setBusy] = useState(false);
      const [err, setErr] = useState(null);
      // v15.1.4 — last floor of every dungeon is a turn-based boss
      // duel. When the server responds with is_boss_floor:true, we
      // open DuelArenaModal inline. Settle path handles bag transfer +
      // dungeon completion automatically on the duel's terminal state.
      const [bossDuelId, setBossDuelId] = useState(null);
      // 層 4.3 — com a onda, o ganho do Chefe chega pelo fim do duelo (`onFim`)
      // e só se mostra quando a janela FECHA: a luz debaixo da janela não se vê.
      const fimRef = useRef(null);
      const onda = obraOn();
      const corteOk = !!(onda && run && run.corte && Number(run.corte.floor_count) > 0);

      async function callAdvance() {
        if (busy) return;
        haptic("warning");
        setBusy("avancar"); setErr(null);
        try {
          const res = await api("dungeons/advance", { dungeon_id: run.dungeon_id });
          if (!res.ok) {
            haptic("error");
            setErr(dngReason(res.reason, res));
            setBusy(false);
            return;
          }
          // v15.1.4 — Boss floor → swap into DuelArenaModal.
          if (res.is_boss_floor && res.boss_duel_id) {
            haptic("warning");
            setBossDuelId(res.boss_duel_id);
            setBusy(false);
            return;
          }
          // 層 4.3 — com a onda, o andar CONFIRMADO fica no corte (a marca acende,
          // o recibo junto da operação) em vez do modal de cada andar. Sem o
          // ganho do servidor (a morte, ou a onda desligada) — o caminho de hoje.
          if (res.masmorra_ganho && onGanho && onGanho(res, run)) {
            haptic("success");
            setBusy(false);
            onAction && onAction();
            return;
          }
          haptic(res.completed || res.won ? "success" : "warning");
          onResult && onResult(res.completed
            /* QoL 04/08 — o servidor manda `regional_bonus` na conclusão e este
               objeto deitava-o fora: o Tributo da Terra NUNCA aparecia ao acabar
               uma masmorra, só na varredura ("payload entregue ≠ payload visto"). */
            ? { kind:"completed", best_difficulty_key: res.best_difficulty_key, floor_count: res.floor_count, loot: res.final_loot, named_items: res.loot_named_items || [], regional_bonus: res.regional_bonus || null, dungeon: { name: run.name, emoji: run.emoji } }
            /* 層 4.3 — a MORTE dizia "derrotado no andar 0": o servidor devolve
               `floor: 0` (a posição DEPOIS de cair) e o título lia-o como o andar
               onde se caiu. Ninguém o via — o título saía cortado ("Você foi
               derrota…"). O andar da morte é o que se estava a lutar. */
            : { kind: res.won ? "won_floor" : "died_floor", floor: res.won ? res.floor : (Number(run.current_floor) || 0) + 1, floor_count: res.floor_count, loot: res.loot_this_floor, named_items: res.loot_named_items || [], hp: res.current_hp, max_hp: res.max_hp, dungeon: { name: run.name, emoji: run.emoji } }
          );
          // Reset busy BEFORE refresh — RunCard persists across reloads while
          // the run is alive, so a stale busy=true would freeze the buttons
          // until the user navigates away. Same pattern as MA-26 cooldown.
          setBusy(false);
          onAction && onAction();
        } catch (e) {
          haptic("error");
          setErr(t("dungeon_action_failed"));
          setBusy(false);
        }
      }

      async function callRetreat() {
        if (busy) return;
        haptic("warning");
        setBusy("recuar"); setErr(null);
        try {
          const res = await api("dungeons/retreat", { dungeon_id: run.dungeon_id });
          if (!res.ok) {
            haptic("error");
            setErr(dngReason(res.reason, res));
            setBusy(false);
            return;
          }
          haptic("success");
          onResult && onResult({ kind:"retreat", floor: res.floor_reached, loot: res.claimed_bag, named_items: res.loot_named_items || [], dungeon: { name: run.name, emoji: run.emoji } });
          setBusy(false);
          onAction && onAction();
        } catch (e) {
          haptic("error");
          setErr(t("dungeon_action_failed"));
          setBusy(false);
        }
      }

      const pct = run.floor_count > 0 ? Math.round((run.current_floor / run.floor_count) * 100) : 0;
      const diffEmoji = DUNGEON_DIFF_EMOJI[run.difficulty || "normal"];
      const diffName = dngDiffName(run.difficulty || "normal");

      // v15.1.4 — Boss duel modal (PvE). Opens when callAdvance
      // detects is_boss_floor:true. On close: refresh the run so
      // completion (won) or floor reset (lost) are reflected.
      // 層 4.3 — com a onda, o `onFim` guarda o `masmorra_ganho` e o fecho
      // entrega-o (a expedição concluída aparece com o corte inteiro e acende).
      const duelo = bossDuelId ? (
        <DuelArenaModal
          duelId={bossDuelId}
          onFim={onda ? (st) => { if (st && st.masmorra_ganho) fimRef.current = st.masmorra_ganho; } : undefined}
          onClose={() => {
            const g = fimRef.current;
            fimRef.current = null;
            setBossDuelId(null);
            if (g && onFimMasmorra) onFimMasmorra(g, run);
            onAction && onAction();
          }}
          playerLang={null} />
      ) : null;

      if (corteOk) {
        const c = run.corte;
        return (
          <>
            <MasmorraExpedicao
              nome={run.name} dif={c.difficulty || run.difficulty || "normal"}
              total={c.floor_count} vencidos={c.current_floor}
              fundo={c.max_floor_reached} melhor={c.best_difficulty}
              acendeAndar={acende && acende.andar} acendeDif={acende && acende.dif}
              recibo={recibo} reciboRef={reciboRef}
              hp={currentHp} maxHp={maxHp} bag={run.bag_summary}
              busy={busy} erro={err} onAvancar={callAdvance} onRecuar={callRetreat} />
            {duelo}
          </>
        );
      }

      return (
        <Card style={{
          padding:"12px 14px", marginBottom:10,
          border:"1px solid rgba(var(--jade-rgb),.45)",
          background:"linear-gradient(180deg, rgba(15,38,28,.7), rgba(8,16,12,.95))",
        }}>
          <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", marginBottom:8 }}>
            <div style={{ display:"flex", gap:8, alignItems:"center", minWidth:0 }}>
              <span style={{ fontSize:24 }}>{run.emoji}</span>
              <div style={{ minWidth:0 }}>
                <div style={{ fontFamily:"'Cinzel',serif", fontSize:14, color:"var(--gold2)", fontWeight:600, overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap" }}>
                  {run.emoji} {run.name}
                </div>
                <div style={{ fontSize:11, color:"var(--jade)" }}>{diffEmoji} {diffName}</div>
              </div>
            </div>
            <div style={{ fontSize:11, color:"var(--gold3)" }}>{t("dungeon_floor_progress", { floor: run.current_floor, total: run.floor_count })}</div>
          </div>

          <div style={{ height:6, borderRadius:4, background:"rgba(255,255,255,.05)", overflow:"hidden", marginBottom:8 }}>
            <div style={{ width:`${pct}%`, height:"100%", background:"linear-gradient(90deg, var(--jade), var(--gold2))", transition:"width .3s ease" }} />
          </div>

          <div style={{ marginBottom:8 }}><HPBar cur={currentHp} max={maxHp} /></div>

          {(() => {
            const rows = fmtBagSummary(run.bag_summary);
            return (
              <div style={{ background:"rgba(0,0,0,.25)", borderRadius:8, padding:"6px 10px", fontSize:11, color:"var(--muted)", marginBottom:10 }}>
                <div style={{ color:"var(--gold3)", fontWeight:600, fontSize:11, marginBottom:3 }}>{t("dungeon_bag")}</div>
                {rows.map((row, i) => <div key={i}>{row}</div>)}
              </div>
            );
          })()}

          {err && <ErrBanner msg={err} />}

          <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:8 }}>
            <ActionBtn variant="danger" disabled={busy} onClick={callAdvance}>
              {busy ? <DotSpinner /> : (run.current_floor + 1 === run.floor_count ? `👑 ${t("dungeon_boss_btn")}` : t("dungeon_advance_btn"))}
            </ActionBtn>
            <ActionBtn variant="ghost" disabled={busy} onClick={callRetreat}>
              {busy ? <DotSpinner /> : t("dungeon_retreat_btn")}
            </ActionBtn>
          </div>

          {/* v15.1.4 — Boss duel modal (PvE). Opens when callAdvance
              detects is_boss_floor:true. On close: refresh the run so
              completion (won) or floor reset (lost) are reflected, and
              fire onResult with a synthesized envelope so the parent
              can show the completion banner. */}
          {duelo}
        </Card>
      );
    }

    // O espólio agregado (pedras, pílulas de qi, pergaminhos, fragmentos — e as
    // ervas/minérios/pílulas só quando não há a lista com nome), como o modal de
    // resultado o escreve desde a MA-30b. 層 4.3 — saiu de dentro do
    // `DungeonResultModal` quando o recibo da onda precisou da MESMA conta: duas
    // cópias divergem sempre (Lei 0 §2).
    function dngEspolioLinhas(loot, named) {
      const nm = named || [];
      const aggBag = loot ? (
        typeof loot === "object" && (loot.empty !== undefined || loot.total_items !== undefined)
          ? loot
          : (() => {
              const b = loot;
              return {
                stones: b.stones || 0,
                qi_pills: b.qi_pills || 0,
                scrolls: b.scrolls || 0,
                dao_fragments: b.dao_fragments || 0,
                // When we have named_items, suppress the aggregate herbs/ores/pills
                // rows (they'd duplicate the named list).
                herbs: nm.length ? 0 : Object.values(b.herbs || {}).reduce((a, x) => a + Number(x || 0), 0),
                ores: nm.length ? 0 : Object.values(b.ores || {}).reduce((a, x) => a + Number(x || 0), 0),
                healing_pills: nm.length ? 0 : Object.values(b.healing_pills || {}).reduce((a, x) => a + Number(x || 0), 0),
                recipe: nm.length ? null : b.recipe_pill_name,
                empty: false,
                total_items: 1,
              };
            })()
      ) : null;
      return aggBag ? fmtBagSummary(aggBag) : [];
    }

    function DungeonResultModal({ result, onClose, onSweepAgain }) {
      if (!result) return null;
      const { kind, dungeon } = result;
      const titleByKind = {
        won_floor:    t("dungeon_won_floor",    { n: result.floor }),
        died_floor:   t("dungeon_lost_floor",   { n: result.floor }),
        completed:    t("dungeon_completed_title"),
        sweep:        t("dungeon_sweep_done"),
        retreat:      t("dungeon_retreat_btn"),
      };
      const isWin = kind === "won_floor" || kind === "completed" || kind === "sweep" || kind === "retreat";
      // R5: hex literal — o cardStyle concatena alpha (`${cssHex(accent)}33`).
      const accent = isWin ? "var(--jade)" : "var(--red)";
      // MA-30b — owner request "o jogador quer saber o nome do item":
      // when the server provided per-item named rows (loot_named_items),
      // render them as the primary loot list with real catalog names +
      // emojis. Aggregate counts (stones/qi_pills/etc) still go through
      // fmtBagSummary as a fallback for fields the server doesn't enrich.
      const named = result.named_items || [];
      // 層 4.3 — a conta saiu para `dngEspolioLinhas`: o recibo da onda lê a MESMA
      const aggRows = dngEspolioLinhas(result.loot, named);
      const showSweepAgain = kind === "sweep" && onSweepAgain;
      const footer = (
        <div style={{ display:"flex", flexDirection:"column", gap:8 }}>
          {showSweepAgain && (
            <ActionBtn variant="primary" onClick={() => onSweepAgain(result)}
                       style={{ width:"100%",
                                background:"linear-gradient(180deg, rgba(var(--jade-rgb),.32), rgba(20,60,40,.5))",
                                border:"1px solid var(--jade)" }}>
              ⚡ {t("dungeon_sweep_again", { n: result.sweep_count || 1 })}
            </ActionBtn>
          )}
          <ActionBtn variant="ghost" onClick={onClose} style={{ width:"100%" }}>{t("btn_close")}</ActionBtn>
        </div>
      );
      // 層 4.3 — olhado a 390: o título da MORTE saía cortado ("Você foi
      // derrota…"). Com a onda a morte continua neste modal, e um título que não
      // se lê inteiro não diz o que aconteceu: quebra a linha. Sem a onda, o de hoje.
      const quebra = obraOn();
      const titleNode = (
        <div style={{ display:"flex", alignItems:"center", gap:8, minWidth:0 }}>
          <span style={{ fontSize:22 }}>{dungeon?.emoji || "🏛️"}</span>
          <span style={quebra
            ? { color: accent, overflowWrap:"anywhere", whiteSpace:"normal" }
            : { color: accent, overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap" }}>
            {titleByKind[kind] || kind}
          </span>
        </div>
      );
      return (
        <Modal onClose={onClose} title={titleNode}
               accent={accent}
               maxWidth={400} zIndex={70}
               cardStyle={{ boxShadow:`0 0 36px ${cssHex(accent)}33` }}
               animation="dng-pop 360ms cubic-bezier(.2,1.4,.4,1)"
               footer={footer}>
            {kind === "completed" && (
              <div style={{ fontSize:12, color:"var(--muted)", marginBottom:8, textAlign:"center" }}>
                {t("dungeon_completed_msg", {
                  emoji: dungeon?.emoji || "🏛️",
                  name: dungeon?.name || "",
                  diff: dngDiffName(result.best_difficulty_key || "normal"),
                })}
              </div>
            )}
            {kind === "died_floor" && (
              <div style={{ fontSize:11, color:"var(--red)", marginBottom:8, textAlign:"center" }}>{t("dungeon_lost_90")}</div>
            )}
            {kind === "sweep" && (
              <div style={{ fontSize:11, color:"var(--muted)", marginBottom:8, textAlign:"center" }}>
                {result.sweep_count > 1
                  ? t("dungeon_sweep_count_summary", { n: result.sweep_count, floors: result.floors_swept, qi: fmtNum(result.qi_cost) })
                  : `${result.floors_swept}f · ${fmtNum(result.qi_cost)} Qi`}
              </div>
            )}
            {(named.length > 0 || aggRows.length > 0) && (
              <div style={{ background:"rgba(0,0,0,.3)", borderRadius:8, padding:"8px 10px", fontSize:11, color:"var(--muted)", marginBottom:10 }}>
                <div style={{ color:"var(--gold3)", fontWeight:600, fontSize:11, marginBottom:5 }}>
                  {kind === "sweep" ? t("dungeon_sweep_loot") : t("dungeon_bag")}
                </div>
                {/* Aggregate top rows (stones/qi_pills/scrolls/dao_fragments) */}
                {aggRows.filter(r => r !== t("dungeon_bag_empty")).map((row, i) => (
                  <div key={"a"+i} style={{ animation:`dng-loot-cascade 420ms ${i*30}ms both ease-out` }}>{row}</div>
                ))}
                {/* Per-id named rows with real catalog names + emojis */}
                {named.map((it, i) => (
                  <div key={it.kind+it.id} style={{
                    display:"flex", justifyContent:"space-between", gap:6,
                    animation:`dng-loot-cascade 420ms ${(aggRows.length + i)*30}ms both ease-out`,
                    color:"var(--text)",
                  }}>
                    <span><span>{it.emoji}</span> {it.name}</span>
                    <b style={{ color:"var(--gold3)" }}>×{fmtNum(it.count)}</b>
                  </div>
                ))}
                {named.length === 0 && aggRows.length === 0 && (
                  <div>{t("dungeon_bag_empty")}</div>
                )}
              </div>
            )}
            {kind === "sweep" && result.tempering > 0 && (
              <div style={{ fontSize:11, color:"var(--gold3)", marginBottom:4 }}>{t("dungeon_sweep_tempering", { n: result.tempering })}</div>
            )}
            {kind === "sweep" && result.core_essence > 0 && (
              <div style={{ fontSize:11, color:"var(--gold3)", marginBottom:4 }}>{t("dungeon_sweep_core_essence", { n: result.core_essence })}</div>
            )}
            {kind === "sweep" && result.loot_mult > 1 && (
              <div style={{ fontSize:11, color:"var(--warn)", marginBottom:4 }}>{t("dungeon_meteor_bonus")}</div>
            )}
            {/* MV-1 §5 + QoL 04/08 (report [jogador]) — o tributo DIZ o item e a
                quantidade. A linha vem server-resolved (`line`), a mesma que o
                chat imprime; o texto antigo fica como recuo para um payload
                velho em cache. */}
            {result.regional_bonus && (
              <div style={{ fontSize:11, color:"var(--jade)", marginBottom:4 }}>
                {result.regional_bonus.line || t("dungeon_regional_bonus", {
                  emoji: result.regional_bonus.continent_emoji || "🧭",
                  name: safeT("continent_" + result.regional_bonus.continent, null, result.regional_bonus.continent),
                })}
              </div>
            )}
        </Modal>
      );
    }

    function DungeonsTab({ onOpenTravel }) {
      const [reload, setReload] = useState(0);
      const [seg, setSeg] = useState(null);
      const [modalDungeon, setModalDungeon] = useState(null);
      const [resultBanner, setResultBanner] = useState(null);
      // MA-30b — track the most recent sweep params so the result modal's
      // "Sweep Again" button can re-fire with the same difficulty + count.
      // We can't infer them from `dungeons/list` because list payload
      // doesn't include the last sweep choices.
      const [busySweepAgain, setBusySweepAgain] = useState(false);
      // 層 4.3 — o corte da expedição, só com a chave-mestra. ⚠️ TODOS os estados
      // nascem aqui, antes dos `return` de baixo (React #310).
      const onda = obraOn();
      const [mOv, setMOv] = useState(null);         // { res, g, dados, base } — o "depois" de um andar
      const [mFim, setMFim] = useState(null);       // { g, base, dados } — a expedição que acabou
      const [mAcende, setMAcende] = useState(null); // { andar, dif, k }
      const [mRecibo, setMRecibo] = useState(null); // { linhas, espolio, k }
      const [mRolar, setMRolar] = useState(0);
      const mReciboRef = useRef(null);
      const { data, loading, error } = useApi("dungeons/list", null, [reload]);
      const refresh = useCallback(() => setReload(x => x + 1), []);
      useEffect(() => {
        if (!mAcende) return undefined;
        const id = setTimeout(() => setMAcende(null), 900);
        return () => clearTimeout(id);
      }, [mAcende]);
      // o recibo tem de se VER (a lição da 4.2): volta à vista ACIMA da barra de
      // baixo — e só se não estiver à vista. O botão de avançar não foge do dedo
      // de quem avança andar a andar (medido: um jogador do Beta faz um Chefe a
      // cada 48 s).
      useEffect(() => {
        if (!mRolar || !mReciboRef.current) return;
        try {
          const el = mReciboRef.current;
          const area = el.closest && el.closest(".scroll-area");
          const topo = area ? area.getBoundingClientRect().top : 0;
          const r = el.getBoundingClientRect();
          if (r.top >= topo && r.bottom <= (window.innerHeight || 0) - MASM_FOLGA_BAIXO) return;
          const reduz = window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches;
          el.scrollIntoView({ behavior: reduz ? "auto" : "smooth", block: "nearest" });
        } catch (e) { /* sem rolagem, a leitura continua certa */ }
      }, [mRolar]);

      async function sweepAgain(prev) {
        if (busySweepAgain || !prev || !prev.dungeon) return;
        const dungeonId = (cat?.dungeons || []).find(d => d.name === prev.dungeon.name)?.id;
        if (!dungeonId) return;
        const diff = prev.difficulty || "easy";
        const count = prev.sweep_count || 1;
        setBusySweepAgain(true);
        haptic("warning");
        try {
          const res = await api("dungeons/sweep", { dungeon_id: dungeonId, difficulty: diff, count });
          if (!res.ok) {
            haptic("error");
            showToast(dngReason(res.reason, res), "err");
            setBusySweepAgain(false);
            return;
          }
          haptic("success");
          setResultBanner({
            kind:"sweep",
            difficulty: diff,
            sweep_count: res.sweep_count || count,
            floors_swept: res.floors_swept,
            floors_per_sweep: res.floors_per_sweep,
            qi_cost: res.qi_cost,
            qi_per_sweep: res.qi_per_sweep,
            loot: res.loot_summary,
            named_items: res.loot_named_items || [],
            tempering: res.tempering_gained,
            core_essence: res.core_essence_gained,
            loot_mult: res.loot_mult,
            regional_bonus: res.regional_bonus || null,
            dungeon: prev.dungeon,
          });
          refresh();
        } catch (e) {
          haptic("error");
          showToast(t("dungeon_action_failed"), "err");
        } finally {
          setBusySweepAgain(false);
        }
      }

      // Default segment = player's realm category. User override sticks.
      useEffect(() => {
        if (seg || !data) return;
        const r = data.realm ?? 0;
        setSeg(r <= 2 ? "mortal" : r <= 5 ? "spirit" : r <= 8 ? "celestial" : "immortal");
      }, [seg, data]);

      if (loading && !data) return <ListSkeleton rows={6} />;
      if (error && !data) return <ErrBanner msg={error} />;
      if (!data) return null;

      // 層 4.3 — UMA porta para o ganho confirmado (um andar, a conclusão, o
      // Chefe). Só o `masmorra_ganho` do servidor acende; nunca o toque. Devolve
      // `true` quando o ganho foi para o corte (quem chama não abre o modal).
      function aplicarGanhoMasmorra(res, base) {
        const g = res && res.masmorra_ganho;
        if (!onda || !g || !g.depois) return false;
        const k = Date.now();
        const nomeados = res.loot_named_items || [];
        // QoL 04/08 (report [jogador]) — o Tributo da Terra da conclusão vinha no modal
        // de hoje; sem o modal, vem no recibo ("payload entregue ≠ payload visto")
        const tributo = res.regional_bonus && res.regional_bonus.line;
        setMRecibo({
          linhas: reciboDaMasmorra(g),
          // o espólio escrito como o modal de hoje o escreve (a MESMA conta)
          espolio: dngEspolioLinhas(res.final_loot || res.loot_this_floor, nomeados)
            .filter(r => r !== t("dungeon_bag_empty"))
            .concat(nomeados.map(it => ((it.emoji ? it.emoji + " " : "") + it.name + " ×" + fmtFull(it.count))))
            .concat(tributo ? [tributo] : []),
          k,
        });
        if (Number(g.depois.current_floor) > 0) {
          setMFim(null);
          setMOv({ res, g, dados: data, base: base || null });
        } else {
          setMOv(null);
          setMFim({ g, base: base || null, dados: data });
        }
        setMAcende({ andar: g.andar || null, dif: (g.acende || []).indexOf("dificuldade") >= 0, k });
        setMRolar(x => x + 1);
        return true;
      }
      // a morte, o recuo, a varredura: o modal de hoje, e o recibo de um andar
      // anterior não fica pendurado numa expedição que já acabou
      function onResultMasmorra(r) {
        if (onda) { setMRecibo(null); setMOv(null); setMFim(null); }
        setResultBanner(r);
      }

      const opts = [
        { value:"mortal",    label:`🪨 0–2` },
        { value:"spirit",    label:`☁️ 3–5` },
        { value:"celestial", label:`🌌 6–8` },
        { value:"immortal",  label:`⚡ 9–10` },
      ];
      const activeSeg = seg || "mortal";
      const cat = data.categories.find(c => c.key === activeSeg);
      // 層 4.3 — o "depois" confirmado de um andar pousa por cima dos dados até a
      // releitura o apanhar: o corte do ganho, o saco e a Vida da MESMA resposta.
      // A tela não salta à espera da lista (e com a entrada, a expedição aparece
      // logo, com o andar 1 aceso).
      const mPend = !!(onda && mOv && mOv.dados === data);
      const run = mPend ? (() => {
        const d = mOv.g.depois;
        const velho = data.active_run && data.active_run.dungeon_id === d.dungeon_id ? data.active_run : {};
        const base = Object.assign({}, mOv.base || {}, velho);
        return Object.assign(base, {
          dungeon_id: d.dungeon_id, current_floor: d.current_floor, floor_count: d.floor_count,
          difficulty: d.difficulty, bag_summary: mOv.res.bag_summary || base.bag_summary, corte: d,
        });
      })() : data.active_run;
      const hpVisto = mPend && mOv.res.current_hp != null ? mOv.res.current_hp : data.current_hp;
      const maxHpVisto = mPend && mOv.res.max_hp != null ? mOv.res.max_hp : data.max_hp;
      // a expedição que acabou fica à vista (o corte inteiro, o recibo) até o
      // jogador a fechar — e passa à frente dos dados velhos que ainda a mostram
      // aberta enquanto a releitura não chega
      const fimVisto = !!(onda && mFim && (!data.active_run || mFim.dados === data));
      // MV-1: bloco regional — só chega no payload com dungeons_regionais ON.
      const regional = data.regional || null;
      const elsewhere = (regional && regional.elsewhere) || [];

      return (
        <div>
          <Card style={{ padding:"10px 12px 8px", marginBottom:10 }}>
            <div style={{ display:"flex", alignItems:"center", gap:10 }}>
              <div style={{ fontSize:28 }}>🏛️</div>
              <div style={{ minWidth:0 }}>
                <div style={{ fontFamily:"'Cinzel',serif", fontWeight:700, fontSize:14, color:"var(--gold2)" }}>{t("dungeons_title")}</div>
                <div style={{ fontSize:11, color:"var(--muted)", lineHeight:1.4 }}>{t("dungeons_subtitle")}</div>
                {regional && (
                  <div style={{ fontSize:10.5, color:"var(--gold3)", marginTop:2 }}>
                    📍 {regional.continent_emoji} {safeT("continent_" + regional.continent, null, regional.continent)}
                  </div>
                )}
              </div>
            </div>
          </Card>

          {fimVisto ? (
            <MasmorraExpedicao fim
              nome={(mFim.base && mFim.base.name) || ""}
              dif={mFim.g.antes.difficulty || "normal"}
              total={mFim.g.andar || mFim.g.antes.floor_count} vencidos={mFim.g.andar || mFim.g.antes.floor_count}
              fundo={mFim.g.depois.max_floor_reached} melhor={mFim.g.depois.best_difficulty}
              acendeAndar={mAcende && mAcende.andar} acendeDif={mAcende && mAcende.dif}
              recibo={mRecibo} reciboRef={mReciboRef}
              onFechar={() => { setMFim(null); setMRecibo(null); }} />
          ) : run && (
            <DungeonRunCard
              run={run}
              currentHp={onda ? hpVisto : data.current_hp} maxHp={onda ? maxHpVisto : data.max_hp}
              qi={data.qi} qiCap={data.qi_capacity}
              onAction={refresh}
              onResult={onResultMasmorra}
              onGanho={aplicarGanhoMasmorra}
              onFimMasmorra={(g, base) => aplicarGanhoMasmorra({ masmorra_ganho: g }, base)}
              recibo={mRecibo} acende={mAcende} reciboRef={mReciboRef}
            />
          )}

          <Card style={{ padding:"8px 10px", marginBottom:10 }}>
            <SegControl options={opts} value={activeSeg} onChange={setSeg} />
          </Card>

          <div style={{ display:"flex", flexDirection:"column", gap:8 }}>
            {(!cat || cat.dungeons.length === 0) && (
              /* QoL 09/08 Item D (report [jogador]) — "nenhuma masmorra descoberta
                 neste reino" MENTIA quando a lista local está vazia só por
                 geografia: elas existem, são deste reino, e estão do outro lado
                 do mar — o bloco abaixo lista-as por nome. */
              <Card><div style={{ textAlign:"center", padding:"18px 8px", color:"var(--muted)", fontSize:12 }}>
                {elsewhere.length > 0 ? t("dungeon_no_here_elsewhere") : t("dungeon_no_in_category")}
              </div></Card>
            )}
            {cat && cat.dungeons.map(d => (
              <DungeonCard key={d.id} dungeon={d} onClick={setModalDungeon} />
            ))}
            {/* MV-1 Lei §1 — disclosure, não void: os portais que existem
                além do horizonte, com o CTA de viagem (TravelModal existente). */}
            {elsewhere.length > 0 && (
              <Card style={{ padding:"10px 12px" }}>
                <div style={{ color:"var(--gold3)", fontWeight:600, fontSize:12, marginBottom:6 }}>
                  {t("dungeon_elsewhere_title")}
                </div>
                {elsewhere.map(e => (
                  <div key={e.continent} style={{ padding:"3px 0" }}>
                    <div style={{ fontSize:11.5, color:"var(--muted)" }}>
                      {t("dungeon_elsewhere_line", {
                        emoji: e.emoji,
                        name: safeT("continent_" + e.continent, null, e.continent),
                        n: e.count,
                      })}
                    </div>
                    {/* MV-9 §P6 — os portais por NOME. A contagem anônima
                        escondia 20 dos 23 portais de quem não está em Línghé:
                        "guarda 8 portais" não deixa ninguém decidir viajar.
                        Agora cada um diz o nome e o reino exigido. */}
                    {(e.portals || []).map(p => (
                      <div key={p.id} style={{ fontSize:10.5, color:"var(--gold3)",
                                               paddingLeft:14, lineHeight:1.5 }}>
                        {p.emoji} {p.name} · {realmShort(p.min_realm)}
                      </div>
                    ))}
                  </div>
                ))}
                {onOpenTravel && (
                  <ActionBtn variant="ghost" style={{ width:"100%", marginTop:8 }}
                             onClick={() => { haptic("select"); onOpenTravel(); }}>
                    ⛵ {t("travel_btn")}
                  </ActionBtn>
                )}
              </Card>
            )}
          </div>

          {modalDungeon && (
            <DungeonEntryModal
              dungeon={modalDungeon}
              qi={data.qi}
              currentHp={data.current_hp}
              maxHp={data.max_hp}
              onClose={() => setModalDungeon(null)}
              onAction={() => { setModalDungeon(null); refresh(); }}
              onResult={onResultMasmorra}
              onGanho={(res) => aplicarGanhoMasmorra(res, {
                dungeon_id: modalDungeon.id, name: modalDungeon.name, emoji: modalDungeon.emoji })}
            />
          )}
          {resultBanner && (
            <DungeonResultModal result={resultBanner}
                                onClose={() => setResultBanner(null)}
                                onSweepAgain={sweepAgain} />
          )}
        </div>
      );
    }

    // ─── MA-31: Crafting (Alchemy + Forge placeholder) ───────────────────────
    var CRAFT_RESULT_VISUALS = {
      heavenly:  { color:"#ef4444", glow:"rgba(239,68,68,.7)",   label_key:"alch_result_heavenly",  icon:"🌟" },
      divine:    { color:"var(--realm-3)", glow:"rgba(var(--realm-3-rgb),.6)",  label_key:"alch_result_divine",    icon:"✨" },
      perfect:   { color:"var(--gold2)", glow:"rgba(var(--gold2-rgb),.6)", label_key:"alch_result_perfect",   icon:"💎" },
      success:   { color:"var(--jade)", glow:"rgba(var(--jade-rgb),.5)",  label_key:"alch_result_success",   icon:"✅" },
      failure:   { color:"var(--realm-0)", glow:"rgba(var(--realm-0-rgb),.4)", label_key:"alch_result_failure",   icon:"❌" },
      explosion: { color:"#fb7185", glow:"rgba(251,113,133,.6)", label_key:"alch_result_explosion", icon:"💥" },
    };

    var TRIBULATION_ACTIONS = [
      { key:"protect",   icon:"🛡️", color:"var(--realm-1)", glow:"rgba(var(--realm-1-rgb),.55)", rate_pct:70, label_key:"pill_trib_protect",   desc_key:"pill_trib_protect_desc" },
      { key:"reinforce", icon:"🔨", color:"var(--realm-2)", glow:"rgba(var(--realm-2-rgb),.55)", rate_pct:50, label_key:"pill_trib_reinforce", desc_key:"pill_trib_reinforce_desc" },
      { key:"sacrifice", icon:"⚡", color:"#ef4444", glow:"rgba(239,68,68,.55)",  rate_pct:90, label_key:"pill_trib_sacrifice", desc_key:"pill_trib_sacrifice_desc" },
    ];

    function alchReason(code, ctx) {
      // TAPETE QoL §5 item 8 ([jogador]: "n consigo fabricar sem subir kkkk"):
      // the per-pill min_realm gate is intentional seed data, but the error
      // here dropped the number — say WHICH realm when the caller knows it.
      if (code === "realm_too_low" && ctx && (ctx.min_realm || ctx.min_realm === 0)) {
        return t("alch_err_realm_too_low_n", { n: ctx.min_realm });
      }
      const map = {
        realm_locked:        t("alch_err_realm_locked"),
        realm_too_low:       t("alch_err_realm_too_low"),
        tier_locked:         t("alch_err_tier_locked"),
        recipe_locked:       t("alch_err_recipe_locked"),
        missing_ingredients: t("alch_err_missing_ingredients"),
        no_cauldron:         t("alch_err_no_cauldron"),
        cauldron_broken:     t("alch_err_cauldron_broken"),
        not_enough_energy:   t("alch_err_not_enough_energy"),
        inventory_full:      t("alch_err_inventory_full"),
        meditation_blocked:  t("alch_err_meditation_blocked"),
        not_owned:           t("alch_err_not_owned"),
        invalid_action:      t("alch_err_invalid_action"),
        no_active_tribulation: t("alch_err_no_active_trib"),
        engine_error:        t("alch_err_engine"),
        pill_not_found:      t("alch_err_pill_not_found"),
        // Round 7: bulk crafting stops here when a heavenly result triggers
        // a tribulation. Owner reported raw "heavenly_tribulation_pending"
        // showing in the ⚠️ stop-reason banner. Friendly text now.
        heavenly_tribulation_pending: t("alch_reason_heavenly_tribulation_pending"),
        // Sprint v14.14g — cauldron repair / upgrade reasons.
        already_full:        t("alch_err_already_full"),
        max_grade:           t("alch_err_max_grade"),
        not_enough_stones:   t("alch_err_not_enough_stones_short"),
        missing_materials:   t("alch_err_missing_materials"),
        failed_roll:         t("alch_err_failed_roll"),
        bad_request:         t("alch_err_engine"),
      };
      return map[code] || code || t("alch_err_engine");
    }

    function AlchemyHeaderCard({ data, onPickCauldron, onChanged }) {
      // QoL-Feedback 2026-07-29 Item D (MA-48, report [jogador]): alimentar a
      // Chama com núcleos de besta — existia SÓ no chat (/alquimia → 🔥).
      const [feeding, setFeeding] = useState(false);
      async function feedCore() {
        if (feeding) return;
        setFeeding(true);
        haptic("warning");
        try {
          const res = await api("alchemy/feed_core", {});
          if (!res.ok) {
            haptic("error");
            showToast(res.reason === "no_cores" ? t("alch_sf_no_cores_toast")
                    : res.reason === "soul_fire_locked" ? t("alch_sf_locked_toast", { n: res.min_realm })
                    : t("alch_sf_feed_failed"), "err");
            return;
          }
          haptic("success");
          let msg = t("alch_sf_fed_toast", {
            xp: res.xp_gained, before: fmtNum(res.xp_before), after: fmtNum(res.xp_after),
          });
          if (res.leveled) msg += " · " + t("alch_sf_levelup_toast", { name: res.soul_fire.name });
          showToast(msg);
          onChanged && onChanged();
        } catch (e) {
          haptic("error");
          showToast(e.message, "err");
        } finally {
          setFeeding(false);
        }
      }
      // Defensive: backend guarantees these keys, but a malformed/partial
      // response (e.g. transient deploy mid-fetch) would crash the entire
      // tab tree. Render a skeleton placeholder instead — the next refresh
      // recovers cleanly, and the player sees a hint instead of a black void.
      const ec = data?.equipped_cauldron;
      const a = data?.alchemy;
      const sf = data?.soul_fire;
      const en = data?.energy;
      if (!a || !en || !sf) {
        return <Card><div style={{ padding:"16px 8px", textAlign:"center", color:"var(--muted)", fontSize:11 }}>{t("alch_loading_state")}</div></Card>;
      }
      const enPct = en.max > 0 ? Math.round((en.current / en.max) * 100) : 0;
      const aPct = a.at_max ? 100 : (a.xp_to_next > 0 ? Math.round((a.xp / a.xp_to_next) * 100) : 0);
      const sfPct = !sf.unlocked || sf.at_max ? 0 : (sf.xp_to_next > 0 ? Math.round((sf.xp / sf.xp_to_next) * 100) : 0);
      const durPct = ec ? (ec.max_durability > 0 ? Math.round((ec.durability / ec.max_durability) * 100) : 0) : 0;
      const durColor = !ec ? "var(--muted)"
        : ec.durability <= 0 ? "var(--red)"
        : durPct < 30 ? "var(--warn)"
        : durPct < 60 ? "var(--gold2)"
        : "var(--jade)";

      return (
        <Card style={{ padding:"12px 14px 10px", marginBottom:10 }}>
          <div style={{ display:"flex", justifyContent:"space-between", alignItems:"flex-start", gap:10, marginBottom:8 }}>
            <div style={{ display:"flex", gap:10, alignItems:"center", minWidth:0 }}>
              <div style={{ fontSize:24 }}>{a.tier_emoji}</div>
              <div style={{ minWidth:0 }}>
                <div style={{ fontFamily:"'Cinzel',serif", fontSize:13, color:"var(--gold2)", fontWeight:700 }}>
                  {a.tier_name} <span style={{ color:"var(--muted)", fontWeight:400 }}>· T{a.tier}</span>
                </div>
                <div style={{ fontSize:10, color:"var(--muted)" }}>
                  {a.at_max ? t("alch_xp_max") : `${fmtNum(a.xp)} / ${fmtNum(a.xp_to_next)} XP`}
                </div>
              </div>
            </div>
            {!a.at_max && (
              <div style={{ minWidth:80, textAlign:"right" }}>
                <div style={{ height:5, borderRadius:3, background:"rgba(0,0,0,.5)", overflow:"hidden" }}>
                  <div style={{ width:`${aPct}%`, height:"100%", background:"linear-gradient(90deg, var(--gold), var(--gold3))", transition:"width .3s ease" }} />
                </div>
              </div>
            )}
          </div>

          {/* Energy bar */}
          <div style={{ marginBottom:8 }}>
            <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", marginBottom:3 }}>
              <span style={{ fontSize:10.5, color:"var(--muted)", letterSpacing:.4 }}>⚡ {t("alch_energy")}</span>
              <span style={{ fontSize:11, color:"var(--text)", fontWeight:600 }}>
                {en.current}<span style={{ color:"var(--muted)", fontWeight:400 }}>/{en.max}</span>
                {/* o ritmo passou a float (3 x mult do posto) — sem arredondar
                    saia "2.0400000000000005" no ecra do jogador. */}
                <span style={{ color:"var(--muted2)", fontSize:9.5, marginLeft:6 }}>{t("alch_energy_regen", { n: Math.round((en.regen_minutes || 0) * 100) / 100 })}</span>
              </span>
            </div>
            <div style={{ height:7, borderRadius:4, background:"rgba(0,0,0,.5)", overflow:"hidden", border:"1px solid rgba(var(--realm-1-rgb),.2)" }}>
              <div style={{ width:`${enPct}%`, height:"100%", background:"linear-gradient(90deg, #1e7a9e, #4cc4ff, #7be3ff)", transition:"width .3s ease" }} />
            </div>
            {/* 火候 Ponto do Fogo — o posto de Alquimia comprou tecto e ritmo.
                Quem ainda nao ganhou nada le o degrau SEGUINTE (Lei §1: sempre
                um caminho dito em palavras), nunca um "+0" celebrado. */}
            {en.flame && (en.flame.max_bonus > 0 ? (
              <div style={{ fontSize:9.5, color:"rgba(var(--gold2-rgb),.85)", marginTop:4, letterSpacing:.2 }}>
                {t("alch_flame_mastery", { max_bonus: en.flame.max_bonus, pct: en.flame.regen_pct })}
              </div>
            ) : en.flame.next ? (
              <div style={{ fontSize:9.5, color:"var(--muted2)", marginTop:4, letterSpacing:.2 }}>
                {t("alch_flame_mastery_next", { next_tier: en.flame.next.tier_name, max_bonus: en.flame.next.max_bonus, pct: en.flame.next.regen_pct })}
              </div>
            ) : null)}
          </div>

          {/* Soul Fire (R3+) */}
          {sf.unlocked && (
            <div style={{ marginBottom:8 }}>
              <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", marginBottom:3 }}>
                <span style={{ fontSize:10.5, color:"var(--muted)", letterSpacing:.4 }}>
                  🔥 <span style={{ color:"var(--gold3)" }}>{sf.name}</span>
                  {sf.bonus_pct > 0 && <span style={{ color:"var(--jade)", marginLeft:6 }}>+{sf.bonus_pct}%</span>}
                </span>
                <span style={{ fontSize:10, color:"var(--muted2)" }}>
                  {sf.at_max ? t("alch_xp_max") : `${fmtNum(sf.xp)} / ${fmtNum(sf.xp_to_next)}`}
                </span>
              </div>
              {!sf.at_max && (
                <div style={{ height:5, borderRadius:3, background:"rgba(0,0,0,.5)", overflow:"hidden" }}>
                  <div style={{ width:`${sfPct}%`, height:"100%", background:"linear-gradient(90deg, var(--warn), var(--realm-2), var(--gold3))", transition:"width .3s ease" }} />
                </div>
              )}
              {/* Feed de núcleo (MA-48) — contagem visível, botão disclosed
                  mesmo com ×0 (desabilitado); payload antigo sem `cores`
                  esconde a linha inteira. */}
              {sf.cores !== undefined && (
                <div style={{ display:"flex", alignItems:"center", gap:8, marginTop:6 }}>
                  <span style={{ fontSize:10, color:"var(--muted)" }}>
                    🐾 {t("alch_sf_cores_label", { n: fmtNum(sf.cores) })}
                  </span>
                  <ActionBtn variant="ghost" size="sm"
                             disabled={feeding || !(sf.cores > 0)}
                             onClick={feedCore} style={{ marginLeft:"auto" }}>
                    {feeding ? <DotSpinner /> : `🔥 ${t("alch_sf_feed_btn")}`}
                  </ActionBtn>
                </div>
              )}
            </div>
          )}

          {/* Equipped cauldron — tap to swap */}
          <button onClick={() => { haptic("select"); onPickCauldron && onPickCauldron(); }}
                  disabled={!ec}
                  style={{
                    width:"100%", textAlign:"left",
                    background: ec ? "rgba(0,0,0,.3)" : "rgba(var(--red-rgb),.08)",
                    border: ec ? "1px solid rgba(var(--gold2-rgb),.18)" : "1px dashed rgba(var(--red-rgb),.4)",
                    borderRadius:8, padding:"7px 10px",
                    cursor: ec ? "pointer" : "default",
                    display:"flex", alignItems:"center", gap:8,
                  }}>
            <span style={{ fontSize:18 }}>{ec ? ec.emoji : "⚠️"}</span>
            <div style={{ flex:1, minWidth:0 }}>
              <div style={{ fontSize:11.5, color:"var(--text)", fontWeight:600 }}>
                {ec ? `${ec.name} · ${t("alch_grade", { n: ec.grade })}` : t("alch_no_cauldron_warn")}
                {ec && <span style={{ color:"var(--jade)", fontSize:10, marginLeft:5 }}>+{Math.round(ec.success_bonus)}%</span>}
              </div>
              {ec && (
                <div style={{ display:"flex", alignItems:"center", gap:6, marginTop:3 }}>
                  <div style={{ flex:1, height:4, borderRadius:2, background:"rgba(0,0,0,.5)", overflow:"hidden" }}>
                    <div style={{ width:`${durPct}%`, height:"100%", background: durColor, transition:"width .3s" }} />
                  </div>
                  <span style={{ fontSize:9.5, color:"var(--muted2)" }}>{ec.durability}/{ec.max_durability}</span>
                </div>
              )}
            </div>
            {ec && data.owned_cauldrons && data.owned_cauldrons.length > 1 && (
              <span style={{ fontSize:14, color:"var(--gold3)" }}>↻</span>
            )}
          </button>
        </Card>
      );
    }

    // 牌 A CARTA — a PÍLULA. Consumível, e a única das três cujo grau é um
    // NÚMERO (`pills_catalog.difficulty` 1..5) em vez de uma palavra: é por
    // isso que ela está na prova. Um lombo que só sabe ler palavras não é um
    // sistema.
    //
    // ⚠️ Sem sobrancelha de propósito. Na aba de Alquimia TUDO é pílula, e
    // escrever "PÍLULA" em 41 cartas seria ruído (Lei de Ferro (b): menos
    // info, mais interação). O `eyebrow` é opcional precisamente para isto —
    // quando esta mesma carta for para o inventário ou para a loja, onde uma
    // pílula está ao lado de um artefacto, o chamador passa a palavra.
    //
    // ⚠️ E a descrição ganha finalmente casa. O report do [jogador] (03/09) foi que
    // ela vivia no TÍTULO do cartão com `nowrap` + ellipsis — uma linha dura,
    // e expandir não revelava (41 pílulas, mediana 56 chars, máx 159). Aqui
    // ela é o EFEITO, no corpo, com `overflowWrap`.
    function RecipeCard({ recipe, onClick, lang }) {
      const cardsOn = typeof featureEnabled === "function" && featureEnabled("cartas");
      if (!cardsOn) return <RecipeCardClassic recipe={recipe} onClick={onClick} lang={lang} />;

      const m = recipe.mastery;
      const stars = "⭐".repeat(Math.max(0, m.level - 1));
      const canCraft = !!recipe.can_craft;
      const known = recipe.unlocked !== false;
      const reasonKey = recipe.blocked_reasons[0];
      const chips = (
        <div style={{ display:"flex", flexWrap:"wrap", gap:5 }}>
          {recipe.ingredients.map(ing => (
            <span key={ing.herb_id} style={{
              fontSize:10, padding:"2px 6px", borderRadius:10,
              background: ing.ok ? "rgba(var(--jade-rgb),.12)" : "rgba(var(--red-rgb),.12)",
              border: `1px solid ${ing.ok ? "rgba(var(--jade-rgb),.3)" : "rgba(var(--red-rgb),.3)"}`,
              color: ing.ok ? "var(--jade)" : "var(--red)",
            }}>
              {ing.emoji} ×{ing.qty}
              <span style={{ color:"var(--muted)", marginLeft:3, fontSize:9 }}>({ing.owned})</span>
            </span>
          ))}
          <span style={{
            fontSize:10, padding:"2px 6px", borderRadius:10,
            background:"rgba(var(--realm-1-rgb),.12)", border:"1px solid rgba(var(--realm-1-rgb),.3)", color:"#7be3ff",
          }}>⚡{recipe.energy_cost}</span>
          {recipe.owned > 0 && (
            <span style={{
              fontSize:10, padding:"2px 6px", borderRadius:10,
              background:"rgba(var(--gold2-rgb),.12)", border:"1px solid rgba(var(--gold2-rgb),.3)", color:"var(--gold2)",
            }}>📦 {t("alch_owned_count", { n: recipe.owned })}</span>
          )}
        </div>
      );
      return (
        <NivraelCard
          kind="pill" rank={recipe.required_alchemy_tier}
          glyph={recipe.emoji}
          art={pieceArt("pill", recipe.name, recipe.art_key)}
          name={recipe.name}
          onClick={() => { haptic("select"); onClick(recipe); }}
          state={!known ? "unowned" : canCraft ? "owned" : "locked"}
          stateLabel={!known ? t("alch_err_recipe_locked")
                     : canCraft ? null
                     : t("alch_min_realm", { n: recipe.min_realm })}
          effect={recipe.description}
          note={!canCraft && reasonKey ? alchReason(reasonKey, recipe) : null}
          body={chips}
          foot={(
            <>
              <span style={{ color: canCraft ? "var(--jade)" : "var(--muted2)", fontWeight:600 }}>
                {recipe.success_chance}%
              </span>
              <span>
                {recipe.duration_minutes > 0 && <span>⏱️{recipe.duration_minutes}m </span>}
                {stars}
              </span>
            </>
          )}
        />
      );
    }

    function RecipeCardClassic({ recipe, onClick, lang }) {
      const m = recipe.mastery;
      const stars = "⭐".repeat(Math.max(0, m.level - 1));
      const canCraft = recipe.can_craft;
      const dim = !canCraft;
      const reasonKey = recipe.blocked_reasons[0];

      return (
        <button onClick={() => { haptic("select"); onClick(recipe); }}
                style={{
                  width:"100%", textAlign:"left", cursor:"pointer",
                  background: canCraft ? "linear-gradient(180deg, rgba(20,30,55,.85), rgba(var(--card-rgb),.95))"
                                       : "linear-gradient(180deg, rgba(var(--surface-rgb),.55), rgba(13,16,28,.7))",
                  border:`1px solid ${canCraft ? "rgba(var(--gold2-rgb),.25)" : "rgba(255,255,255,.06)"}`,
                  borderRadius:10, padding:"10px 12px",
                  opacity: dim ? .72 : 1,
                  display:"flex", flexDirection:"column", gap:6,
                  position:"relative", overflow:"hidden",
                }}>
          <div style={{ display:"flex", alignItems:"center", gap:10, justifyContent:"space-between" }}>
            <div style={{ display:"flex", alignItems:"center", gap:8, minWidth:0 }}>
              <span style={{ fontSize:22 }}>{recipe.emoji}</span>
              <div style={{ minWidth:0 }}>
                <div style={{ fontFamily:"'Cinzel',serif", fontSize:13, color:"var(--gold2)", fontWeight:600, overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap" }}>
                  {recipe.name}
                </div>
                <div style={{ fontSize:10, color:"var(--muted)", marginTop:2 }}>
                  {t("alch_difficulty", { n: recipe.difficulty })} · {t("alch_min_realm", { n: recipe.min_realm })}
                  {/* TAPETE QoL §5 item 6 ([jogador]): ⏱️ = pílula com buff temporizado */}
                  {recipe.duration_minutes > 0 && <span> · ⏱️{recipe.duration_minutes}m</span>}
                </div>
              </div>
            </div>
            <div style={{ textAlign:"right", whiteSpace:"nowrap" }}>
              <div style={{ fontSize:13, fontWeight:700, color: canCraft ? "var(--jade)" : "var(--muted2)" }}>
                {recipe.success_chance}%
              </div>
              {stars && <div style={{ fontSize:9 }}>{stars}</div>}
            </div>
          </div>

          {/* Ingredients chips */}
          <div style={{ display:"flex", flexWrap:"wrap", gap:5 }}>
            {recipe.ingredients.map(ing => (
              <span key={ing.herb_id} style={{
                fontSize:10, padding:"2px 6px", borderRadius:10,
                background: ing.ok ? "rgba(var(--jade-rgb),.12)" : "rgba(var(--red-rgb),.12)",
                border: `1px solid ${ing.ok ? "rgba(var(--jade-rgb),.3)" : "rgba(var(--red-rgb),.3)"}`,
                color: ing.ok ? "var(--jade)" : "var(--red)",
              }}>
                {ing.emoji} ×{ing.qty}
                <span style={{ color:"var(--muted)", marginLeft:3, fontSize:9 }}>({ing.owned})</span>
              </span>
            ))}
            <span style={{
              fontSize:10, padding:"2px 6px", borderRadius:10,
              background:"rgba(var(--realm-1-rgb),.12)", border:"1px solid rgba(var(--realm-1-rgb),.3)", color:"#7be3ff",
            }}>
              ⚡{recipe.energy_cost}
            </span>
            {/* U3 (v16.6): how many of this pill the player already owns */}
            {recipe.owned > 0 && (
              <span style={{
                fontSize:10, padding:"2px 6px", borderRadius:10,
                background:"rgba(var(--gold2-rgb),.12)", border:"1px solid rgba(var(--gold2-rgb),.3)", color:"var(--gold2)",
              }}>
                📦 {t("alch_owned_count", { n: recipe.owned })}
              </span>
            )}
          </div>

          {!canCraft && reasonKey && (
            <div style={{ fontSize:10, color:"var(--warn)", marginTop:2 }}>
              {alchReason(reasonKey, recipe)}
            </div>
          )}
        </button>
      );
    }

    // Alchemy bulk-craft: how many pills can the player afford right now?
    // = min(per-ingredient floor(owned/qty), energy budget / energy_cost).
    // Capped to BULK_MAX_ALCHEMY (server matches at 30) so a runaway client
    // can't request 999 in one go.
    var BULK_MAX_ALCHEMY = 30;
    function alchMaxBulk(recipe, energy) {
      if (!recipe || !recipe.can_craft) return 0;
      const ingFloors = (recipe.ingredients || []).map(i => {
        if (!i.qty) return Infinity;
        return Math.floor((i.owned || 0) / i.qty);
      });
      const enCost = recipe.energy_cost || 1;
      const enFloor = Math.floor((energy?.current ?? 0) / enCost);
      const cap = Math.min(BULK_MAX_ALCHEMY, ...ingFloors, enFloor);
      return Math.max(1, isFinite(cap) ? cap : 1);
    }

    function BulkSlider({ count, max, onChange, labelKey, color }) {
      // Compact slider + "Max" + step buttons. Used by both alchemy and
      // forge detail modals. `max` is dynamic — when the player has 0 of an
      // ingredient max collapses to 1 and the slider sits at the min (no
      // crash). Visual is a plain range input styled inline so it looks the
      // same on iOS and Android web views.
      // R5: cssHex resolve var()→hex — o accent é concatenado com alpha nas
      // bordas/fundo (com var() as declarações morriam silenciosas).
      const accent = cssHex(color || "var(--gold2)");
      const safeMax = Math.max(1, max);
      const safeCount = Math.max(1, Math.min(safeMax, count));
      return (
        <div style={{ display:"flex", alignItems:"center", gap:8, marginTop:6 }}>
          <button onClick={() => { haptic("light"); onChange(Math.max(1, safeCount - 1)); }}
                  disabled={safeCount <= 1}
                  style={{
                    width:30, height:30, borderRadius:6, cursor: safeCount <= 1 ? "default" : "pointer",
                    background:"rgba(0,0,0,.4)", border:`1px solid ${cssHex(accent)}33`,
                    color: safeCount <= 1 ? "var(--muted2)" : accent, fontSize:14, fontWeight:700,
                  }}>−</button>
          <input type="range" min="1" max={safeMax} value={safeCount}
                 onChange={(e) => { haptic("light"); onChange(parseInt(e.target.value, 10) || 1); }}
                 style={{
                   flex:1, accentColor: accent.startsWith("var(") ? "var(--gold2)" : accent,
                   minWidth:0,
                 }} />
          <button onClick={() => { haptic("light"); onChange(Math.min(safeMax, safeCount + 1)); }}
                  disabled={safeCount >= safeMax}
                  style={{
                    width:30, height:30, borderRadius:6, cursor: safeCount >= safeMax ? "default" : "pointer",
                    background:"rgba(0,0,0,.4)", border:`1px solid ${cssHex(accent)}33`,
                    color: safeCount >= safeMax ? "var(--muted2)" : accent, fontSize:14, fontWeight:700,
                  }}>+</button>
          <button onClick={() => { haptic("select"); onChange(safeMax); }}
                  disabled={safeCount >= safeMax}
                  style={{
                    height:30, padding:"0 10px", borderRadius:6,
                    cursor: safeCount >= safeMax ? "default" : "pointer",
                    background: safeCount >= safeMax ? "rgba(0,0,0,.3)" : `${cssHex(accent)}22`,
                    border:`1px solid ${cssHex(accent)}55`,
                    color: safeCount >= safeMax ? "var(--muted2)" : accent,
                    fontFamily:"'Cinzel',serif", fontSize:11, fontWeight:700, letterSpacing:.5,
                  }}>{t("bulk_max")}</button>
        </div>
      );
    }

    function RecipeDetailModal({ recipe, energy, onClose, onCraft }) {
      const [busy, setBusy] = useState(false);
      const [err, setErr] = useState(null);
      const [count, setCount] = useState(1);
      // Rules of Hooks: ALL hooks must run before any conditional return.
      // The maxBulk recompute lives outside the hook because we need it for
      // render below; the early-return guards `recipe == null` would otherwise
      // skip useEffect and crash React on the next render.
      const maxBulk = recipe ? alchMaxBulk(recipe, energy) : 0;
      useEffect(() => {
        if (!recipe) return;
        if (count > maxBulk) setCount(Math.max(1, maxBulk));
      }, [maxBulk, recipe]);
      if (!recipe) return null;

      async function callCraft() {
        if (busy || !recipe.can_craft) return;
        haptic("warning");
        setBusy(true); setErr(null);
        try {
          const isBulk = count > 1;
          const endpoint = isBulk ? "alchemy/craft_bulk" : "alchemy/craft";
          const body = isBulk
            ? { pill_id: recipe.id, count }
            : { pill_id: recipe.id };
          const res = await api(endpoint, body);
          if (!res.ok) {
            haptic("error");
            setErr(alchReason(res.reason, { min_realm: res.min_realm ?? recipe.min_realm }));
            setBusy(false);
            return;
          }
          // For bulk: pick "best" haptic from results breakdown.
          const isFail = !isBulk && (res.result === "failure" || res.result === "explosion");
          haptic(isFail ? "warning" : "success");
          setBusy(false);
          onCraft && onCraft(res);
        } catch (e) {
          haptic("error");
          setErr(t("alch_err_engine"));
          setBusy(false);
        }
      }

      const m = recipe.mastery;
      const masteryProgress = m.at_max ? 100 : (m.next_crafts > 0 ? Math.round((m.crafts_count / m.next_crafts) * 100) : 0);
      const res = recipe.resistance;

      const titleNode = (
        <div style={{ display:"flex", gap:10, alignItems:"center", minWidth:0 }}>
          {itemVivoOn()
            ? <PieceIcon kind="pill" name={recipe.name} artKey={recipe.art_key} emoji={recipe.emoji}
                         size={38} accent="var(--gold2)" radius={7} />
            : <span style={{ fontSize:24 }}>{recipe.emoji}</span>}
          <div style={{ minWidth:0 }}>
            <div style={{ fontFamily:"'Cinzel',serif", fontWeight:700, fontSize:14.5, color:"var(--gold2)", lineHeight:1.2,
                          overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap" }}>{recipe.name}</div>
            {/* ⚠️ SEM nowrap (report [jogador], 2026-09-03). Isto vivia no titleNode
                do cartao com `whiteSpace:"nowrap"` + ellipsis: UMA linha dura, e
                como a descricao esta' no TITULO e nao no corpo, expandir o
                cartao tambem nao a revelava — nao havia caminho nenhum para o
                texto. Medido no catalogo: 41 pilulas, mediana 56 chars, MAX 159,
                14 acima de 60; cabem ~30-35 no telemovel. Deixar quebrar custa
                2-3 linhas no pior caso e devolve o conteudo. */}
            <div style={{ fontSize:10.5, color:"var(--muted)", lineHeight:1.35,
                          overflowWrap:"anywhere" }}>{recipe.description}</div>
          </div>
        </div>
      );
      const footer = (
        <div>
          <ActionBtn variant="primary" disabled={busy || !recipe.can_craft} onClick={callCraft} style={{ width:"100%" }}>
            {busy ? <DotSpinner /> : (count > 1
              ? `⚗️ ${t("alch_craft_btn_bulk", { n: count })}`
              : `⚗️ ${t("alch_craft_btn")}`)}
          </ActionBtn>
          {!recipe.can_craft && recipe.blocked_reasons.length > 0 && (
            <div style={{ fontSize:10.5, color:"var(--warn)", marginTop:6, textAlign:"center" }}>
              {recipe.blocked_reasons.map(r => alchReason(r, recipe)).join(" · ")}
            </div>
          )}
        </div>
      );

      return (
        <Modal onClose={onClose} title={titleNode}
               accent="rgba(var(--gold2-rgb),.4)"
               maxWidth={480} zIndex={60}
               footer={footer}>
            <div style={{ display:"flex", flexWrap:"wrap", gap:6, marginBottom:10 }}>
              <Badge>{t("alch_difficulty", { n: recipe.difficulty })}</Badge>
              <Badge>{t("alch_min_realm", { n: recipe.min_realm })}</Badge>
              <Badge>T{recipe.required_alchemy_tier}</Badge>
              {recipe.duration_minutes > 0 && <Badge>{recipe.duration_minutes}m</Badge>}
              {recipe.owned > 0 && <Badge>📦 {t("alch_owned_count", { n: recipe.owned })}</Badge>}
            </div>

            <Card style={{ padding:"10px 12px", marginBottom:10 }}>
              <CardTitle left={t("alch_success_chance")} right={`${recipe.success_chance}%`} />
              <div style={{ height:8, borderRadius:4, background:"rgba(0,0,0,.5)", overflow:"hidden", border:"1px solid rgba(var(--jade-rgb),.18)" }}>
                <div style={{ width:`${recipe.success_chance}%`, height:"100%", background:"linear-gradient(90deg, #15803d, var(--jade), #86efac)" }} />
              </div>
            </Card>

            <Card style={{ padding:"10px 12px", marginBottom:10 }}>
              <CardTitle left={t("alch_ingredients")} />
              <div style={{ display:"flex", flexDirection:"column", gap:5 }}>
                {recipe.ingredients.map(ing => (
                  <div key={ing.herb_id} style={{
                    display:"flex", alignItems:"center", gap:8,
                    padding:"6px 8px", borderRadius:6,
                    background: ing.ok ? "rgba(var(--jade-rgb),.06)" : "rgba(var(--red-rgb),.06)",
                    border:`1px solid ${ing.ok ? "rgba(var(--jade-rgb),.18)" : "rgba(var(--red-rgb),.18)"}`,
                  }}>
                    <span style={{ fontSize:18 }}>{ing.emoji}</span>
                    <span style={{ flex:1, minWidth:0, fontSize:12, color:"var(--text)" }}>
                      {ing.name}
                      {/* MV-9.5 — a receita cinzenta passa a DIZER onde nasce o
                          que falta (linha já localizada no servidor; key
                          condicional → OFF nem existe). */}
                      {ing.origin && ing.origin.line && (
                        <span style={{ display:"block", fontSize:10.5, marginTop:2, lineHeight:1.4,
                                       color: ing.origin.here ? "var(--gold3)" : "var(--muted)" }}>
                          {ing.origin.line}
                        </span>
                      )}
                    </span>
                    <span style={{ fontSize:11, color:"var(--muted)" }}>
                      <b style={{ color: ing.ok ? "var(--jade)" : "var(--red)" }}>{ing.owned}</b>
                      <span> / {ing.qty}</span>
                    </span>
                    <span style={{ fontSize:14 }}>{ing.ok ? "✅" : "❌"}</span>
                  </div>
                ))}
              </div>
            </Card>

            <Card style={{ padding:"10px 12px", marginBottom:10 }}>
              <CardTitle left={`📖 ${m.name}`} right={m.at_max ? t("alch_mastery_max") : t("alch_mastery_progress_short", { n: m.crafts_count, total: m.next_crafts })} />
              {!m.at_max && (
                <div style={{ height:5, borderRadius:3, background:"rgba(0,0,0,.5)", overflow:"hidden" }}>
                  <div style={{ width:`${masteryProgress}%`, height:"100%", background:"linear-gradient(90deg, #6b21a8, var(--realm-3), #d8b4fe)", transition:"width .3s" }} />
                </div>
              )}
              {m.bonus > 0 && (
                <div style={{ fontSize:10, color:"var(--jade)", marginTop:5 }}>+{m.bonus}% {t("alch_mastery_bonus")}</div>
              )}
            </Card>

            {res && res.uses > 0 && (
              <Card style={{ padding:"10px 12px", marginBottom:10, borderColor:"rgba(var(--warn-rgb),.3)" }}>
                <div style={{ fontSize:11, color:"var(--warn)" }}>
                  🧪 {t("alch_resistance_eff", { pct: res.pct, uses: res.uses })}
                </div>
                {res.next_threshold && (
                  <div style={{ fontSize:10, color:"var(--muted)", marginTop:3 }}>
                    {t("alch_resistance_next", { n: res.next_threshold, pct: res.next_pct })}
                  </div>
                )}
              </Card>
            )}

            <div style={{ display:"flex", gap:8, alignItems:"center", padding:"6px 10px", marginBottom:10,
                          background:"rgba(var(--realm-1-rgb),.08)", borderRadius:8, border:"1px solid rgba(var(--realm-1-rgb),.2)" }}>
              <span style={{ fontSize:14 }}>⚡</span>
              <span style={{ fontSize:11, color:"var(--text)" }}>
                {count > 1
                  ? t("alch_will_consume_bulk", { each: recipe.energy_cost, total: recipe.energy_cost * count, n: count })
                  : t("alch_will_consume", { n: recipe.energy_cost })}
              </span>
            </div>

            {/* Bulk count picker — owner request: "FAZER MUITAS PILLS SEM PARAR".
                Slider 1→max(ingredients/energy). Persists between crafts so player
                can mash the button. Server caps at BULK_MAX_ALCHEMY (30). */}
            {recipe.can_craft && maxBulk > 1 && (
              <Card style={{ padding:"10px 12px", marginBottom:10, borderColor:"rgba(var(--gold2-rgb),.3)" }}>
                <CardTitle
                  left={`🔄 ${t("alch_bulk_label")}`}
                  right={<span style={{ color: count >= maxBulk ? "var(--gold3)" : "var(--gold2)", fontWeight:700 }}>
                    {count}<span style={{ color:"var(--muted)", fontWeight:400 }}> / {maxBulk}</span>
                  </span>}
                />
                <BulkSlider count={count} max={maxBulk} onChange={setCount} color="var(--gold2)" />
                <div style={{ fontSize:10, color:"var(--muted)", marginTop:6, lineHeight:1.4 }}>
                  {t("alch_bulk_hint")}
                </div>
              </Card>
            )}

            {err && <ErrBanner msg={err} />}
        </Modal>
      );
    }

    // Pick a "headline visual" for a bulk result — the highest-quality
    // outcome wins (heavenly > divine > perfect > success > failure), so the
    // modal still feels celebratory when the player got something rare.
    // Round 7 (2026-05-20): owner reported red ❌ icon on a 1-craft bulk
    // that triggered heavenly tribulation. The heavenly result doesn't
    // populate any results bucket (it's staged for tribulation, not added
    // to inventory yet), so without `earlyStopReason` the visual fell
    // through to `failure`. Now we promote the heavenly visual when bulk
    // stopped specifically because of `heavenly_tribulation_pending`.
    function bulkHeadlineVisual(results, earlyStopReason) {
      if (earlyStopReason === "heavenly_tribulation_pending") return CRAFT_RESULT_VISUALS.heavenly;
      if (!results) return CRAFT_RESULT_VISUALS.failure;
      if (results.divine > 0)  return CRAFT_RESULT_VISUALS.divine;
      if (results.perfect > 0) return CRAFT_RESULT_VISUALS.perfect;
      if (results.success > 0) return CRAFT_RESULT_VISUALS.success;
      return CRAFT_RESULT_VISUALS.failure;
    }

    function CraftResultBulkModal({ result, onClose, onCraftAgain }) {
      const visual = bulkHeadlineVisual(result.results, result.early_stop_reason);
      const r = result.results || {};
      const totalGood = (r.success || 0) + (r.perfect || 0) + (r.divine || 0);
      const totalBad  = (r.failure || 0) + (r.explosion || 0);
      const stoppedHeavenly = result.early_stop_reason === "heavenly_tribulation_pending";
      const footer = (
        <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:8 }}>
          <ActionBtn variant="primary" onClick={() => { onCraftAgain && onCraftAgain(); }}>
            🔄 {t("alch_craft_again")}
          </ActionBtn>
          <ActionBtn variant="ghost" onClick={onClose}>
            {t("alch_close")}
          </ActionBtn>
        </div>
      );
      return (
        <Modal onClose={onClose} title={`⚗️ ${t("alch_bulk_crafted", { n: result.crafts_done })}`}
               accent={visual.color}
               maxWidth={400} zIndex={70}
               cardStyle={{ boxShadow:`0 0 50px ${visual.glow}, inset 0 0 30px ${visual.glow.replace(',.5)', ',.12)').replace(',.6)', ',.15)').replace(',.7)', ',.18)')}` }}
               animation="alch-pop 420ms cubic-bezier(.2,1.4,.4,1)"
               footer={footer}>
            <div style={{ textAlign:"center", marginBottom:12 }}>
              <div style={{
                fontSize:48, marginBottom:6,
                animation: totalGood > 0 ? "alch-icon-spin 600ms ease-out" : "alch-icon-shake 500ms",
                filter:`drop-shadow(0 0 16px ${visual.glow})`,
              }}>{visual.icon}</div>
              <div style={{
                fontFamily:"'Cinzel',serif", fontSize:15, fontWeight:700,
                color: visual.color, letterSpacing:1,
                textShadow:`0 0 12px ${visual.glow}`,
              }}>
                {result.crafts_done < result.crafts_requested && (
                  <span style={{ color:"var(--muted)", fontSize:11, fontWeight:400 }}>
                    {result.crafts_done} / {result.crafts_requested}
                  </span>
                )}
              </div>
              {result.early_stop_reason && (
                <div style={{ fontSize:10.5, color:"var(--warn)", marginTop:5 }}>
                  ⚠️ {alchReason(result.early_stop_reason)}
                </div>
              )}
            </div>

            {/* Per-result-quality breakdown */}
            <div style={{ display:"grid", gridTemplateColumns:"repeat(auto-fit, minmax(64px, 1fr))",
                          gap:6, marginBottom:10 }}>
              {["divine", "perfect", "success", "failure", "explosion"].map(k => {
                const n = r[k] || 0;
                if (n === 0) return null;
                const v = CRAFT_RESULT_VISUALS[k];
                return (
                  <div key={k} style={{
                    background:`linear-gradient(180deg, ${cssHex(v.color)}22, rgba(0,0,0,.4))`,
                    border:`1px solid ${cssHex(v.color)}55`, borderRadius:8,
                    padding:"8px 4px", textAlign:"center",
                  }}>
                    <div style={{ fontSize:18 }}>{v.icon}</div>
                    <div style={{ fontFamily:"'Cinzel',serif", fontSize:14, fontWeight:700, color: v.color }}>×{n}</div>
                    <div style={{ fontSize:9, color:"var(--muted)", textTransform:"uppercase", letterSpacing:.5 }}>
                      {t(v.label_key).replace(/[!.…✨💎❌💥]/g, "").trim()}
                    </div>
                  </div>
                );
              })}
            </div>

            {totalGood > 0 && (
              <div style={{ background:"rgba(var(--jade-rgb),.08)", border:"1px solid rgba(var(--jade-rgb),.25)",
                            borderRadius:8, padding:"6px 10px", marginBottom:8,
                            fontSize:11.5, color:"var(--jade)", textAlign:"center" }}>
                ✅ {t("bulk_pills_added", { n: totalGood })}
              </div>
            )}

            <div style={{
              background:"rgba(0,0,0,.3)", borderRadius:8, padding:"8px 10px",
              fontSize:11, color:"var(--muted)", marginBottom:10, display:"grid", gap:3,
            }}>
              {result.energy_spent > 0 && (
                <div>⚡ {t("alch_energy_spent", { n: result.energy_spent })}: <b style={{ color:"var(--text)" }}>{result.energy_after}/{result.energy_max}</b></div>
              )}
              {result.alchemy_xp_gained > 0 && (
                <div>📚 +{result.alchemy_xp_gained} {t("alch_xp")} <span style={{ color:"var(--muted2)" }}>(T{result.alchemy_tier})</span></div>
              )}
              {/* TEC-1 §0.1 (pedido [jogador]) — XP do ofício ganho, VISÍVEL (Lei §10). */}
              {result.prof_xp_gained > 0 && (
                <div style={{ color:"var(--gold3)" }}>🏮 {result.prof_weight_tier
                  ? t("prf_mini_xp_gain_tier", { n: result.prof_xp_gained, tier: result.prof_weight_tier, w: result.prof_weight })
                  : t("prf_mini_xp_gain", { n: result.prof_xp_gained })}</div>
              )}
              {result.alchemy_leveled_up && (
                <div style={{ color:"var(--gold3)" }}>⭐ {t("alch_tier_levelup", { n: result.alchemy_tier })}</div>
              )}
              {result.core_essence_added > 0 && (
                <div style={{ color:"var(--gold3)" }}>💠 +{result.core_essence_added} {t("alch_core_essence")}</div>
              )}
              {(result.ingredients_consumed || []).length > 0 && (
                <div style={{ marginTop:3, color:"var(--muted2)" }}>
                  {t("bulk_ingredients_used")}: {result.ingredients_consumed.map(ic => `${ic.emoji}×${ic.qty}`).join(" ")}
                </div>
              )}
            </div>

            {stoppedHeavenly && (
              <div style={{
                background:"rgba(239,68,68,.1)", border:"1px solid rgba(239,68,68,.3)",
                borderRadius:8, padding:"8px 10px", marginBottom:10,
                fontSize:11, color:"var(--red2)", textAlign:"center",
              }}>
                🌟 {t("alch_heavenly_pending_after_bulk")}
              </div>
            )}
        </Modal>
      );
    }

    function CraftResultModal({ result, onClose, onCraftAgain }) {
      if (!result) return null;
      // Bulk path: aggregate breakdown modal.
      if (result.bulk) {
        return <CraftResultBulkModal result={result} onClose={onClose} onCraftAgain={onCraftAgain} />;
      }
      const visual = CRAFT_RESULT_VISUALS[result.result] || CRAFT_RESULT_VISUALS.failure;
      const isWin = ["success", "perfect", "divine"].includes(result.result);

      const footer = (
        <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:8 }}>
          <ActionBtn variant="primary" onClick={() => { onCraftAgain && onCraftAgain(); }}>
            🔄 {t("alch_craft_again")}
          </ActionBtn>
          <ActionBtn variant="ghost" onClick={onClose}>
            {t("alch_close")}
          </ActionBtn>
        </div>
      );

      return (
        <Modal onClose={onClose} title={`⚗️ ${t(visual.label_key)}`}
               accent={visual.color}
               maxWidth={400} zIndex={70}
               cardStyle={{ boxShadow:`0 0 50px ${visual.glow}, inset 0 0 30px ${visual.glow.replace(',.5)', ',.12)').replace(',.6)', ',.15)').replace(',.7)', ',.18)')}` }}
               animation="alch-pop 420ms cubic-bezier(.2,1.4,.4,1)"
               footer={footer}>
            <div style={{ textAlign:"center", marginBottom:12 }}>
              <div style={{
                fontSize:54, marginBottom:6,
                animation:`alch-icon-${isWin ? "spin" : "shake"} 600ms ease-out`,
                filter:`drop-shadow(0 0 16px ${visual.glow})`,
              }}>{visual.icon}</div>
              <div style={{
                fontFamily:"'Cinzel',serif", fontSize:18, fontWeight:700,
                color: visual.color, letterSpacing:1,
                textShadow:`0 0 12px ${visual.glow}`,
              }}>
                {t(visual.label_key)}
              </div>
              {result.result !== "failure" && result.result !== "explosion" && (
                <div style={{ fontSize:11, color:"var(--muted)", marginTop:6 }}>
                  {t("alch_chance_was", { pct: result.success_chance })}
                </div>
              )}
            </div>

            {isWin && result.quality && (
              <div style={{
                background:"rgba(0,0,0,.35)", borderRadius:8,
                padding:"10px 12px", marginBottom:10, textAlign:"center",
                border:`1px solid ${cssHex(visual.color)}55`,
              }}>
                <div style={{ fontSize:10, color:"var(--muted)", letterSpacing:.6, textTransform:"uppercase" }}>
                  {t("alch_quality")}
                </div>
                <div style={{
                  fontFamily:"'Cinzel',serif", fontSize:14, fontWeight:700,
                  color: visual.color, marginTop:3,
                }}>{result.quality.toUpperCase()}</div>
                {result.potency_mult > 1 && (
                  <div style={{ fontSize:11, color:"var(--gold3)", marginTop:3 }}>×{result.potency_mult.toFixed(1)} {t("alch_potency")}</div>
                )}
              </div>
            )}

            {result.result === "explosion" && result.durability_after !== null && (
              <div style={{ fontSize:11, color:"var(--red)", textAlign:"center", marginBottom:10 }}>
                💥 {t("alch_durability_lost_msg", { n: result.durability_after })}
              </div>
            )}

            <div style={{
              background:"rgba(0,0,0,.3)", borderRadius:8, padding:"8px 10px",
              fontSize:11, color:"var(--muted)", marginBottom:10,
              display:"grid", gap:3,
            }}>
              <div>⚡ {t("alch_energy")}: <b style={{ color:"var(--text)" }}>{result.energy_after}/{result.energy_max}</b></div>
              {result.alchemy_xp_gained > 0 && (
                <div>📚 +{result.alchemy_xp_gained} {t("alch_xp")} <span style={{ color:"var(--muted2)" }}>(T{result.alchemy_tier})</span></div>
              )}
              {result.mastery_leveled_up && (
                <div style={{ color:"var(--gold3)" }}>📖 {t("alch_mastery_levelup", { n: result.mastery_level })}</div>
              )}
              {result.alchemy_leveled_up && (
                <div style={{ color:"var(--gold3)" }}>⭐ {t("alch_tier_levelup", { n: result.alchemy_tier })}</div>
              )}
              {result.soul_fire_leveled_up && (
                <div style={{ color:"var(--warn)" }}>🔥 {t("alch_soul_fire_levelup")}</div>
              )}
              {result.core_essence_added > 0 && (
                <div style={{ color:"var(--gold3)" }}>💠 +{result.core_essence_added} {t("alch_core_essence")}</div>
              )}
              {result.charm_used && (
                <div style={{ color:"var(--warn)" }}>✨ {t("alch_charm_used")}</div>
              )}
              {/* MV-7 — 🧪 a pílula extra do Alquimista é DITA (single OU lote). */}
              {result.extra_pill && (
                <div style={{ color:"var(--gold3)" }}>🧪 {t("prf_mini_extra_pill")}</div>
              )}
              {result.extra_pills > 0 && (
                <div style={{ color:"var(--gold3)" }}>🧪 {t("prf_mini_extra_pills", { n: result.extra_pills })}</div>
              )}
              {/* TEC-1 §0.1 (pedido [jogador]) — XP do ofício ganho, VISÍVEL (Lei §10;
                  review F6: este modal single não mostrava). */}
              {result.prof_xp_gained > 0 && (
                <div style={{ color:"var(--gold3)" }}>🏮 {result.prof_weight_tier
                  ? t("prf_mini_xp_gain_tier", { n: result.prof_xp_gained, tier: result.prof_weight_tier, w: result.prof_weight })
                  : t("prf_mini_xp_gain", { n: result.prof_xp_gained })}</div>
              )}
            </div>
        </Modal>
      );
    }

    function HeavenlyTribulationModal({ tribulation, onClose, onComplete }) {
      const [state, setState] = useState(tribulation);
      const [busy, setBusy] = useState(false);
      const [err, setErr] = useState(null);
      const [animating, setAnimating] = useState(null);  // "protect"|"reinforce"|"sacrifice"|null
      const [lastResult, setLastResult] = useState(null);  // {action, passed, bonus_applied}
      const [finalResult, setFinalResult] = useState(null);  // server's completion payload

      async function chooseAction(action) {
        if (busy || finalResult) return;
        haptic("warning");
        setBusy(true); setErr(null); setAnimating(action); setLastResult(null);
        try {
          const res = await api("alchemy/tribulation/action", { action });
          if (!res.ok) {
            haptic("error");
            setErr(alchReason(res.reason));
            setBusy(false); setAnimating(null);
            return;
          }
          // brief animation hold so the lightning/flash registers
          setTimeout(() => {
            setLastResult(res.round_result);
            haptic(res.round_result.passed ? "success" : "warning");
            if (res.completed) {
              haptic(res.passed ? "success" : "error");
              setFinalResult(res);
            } else {
              setState(s => ({ ...s, ...res.tribulation }));
            }
            setAnimating(null);
            setBusy(false);
          }, 700);
        } catch (e) {
          haptic("error");
          setErr(t("alch_err_engine"));
          setBusy(false); setAnimating(null);
        }
      }

      function close() {
        if (finalResult) onComplete && onComplete(finalResult);
        onClose && onClose();
      }

      const dots = Array.from({ length: state.rounds_total }).map((_, i) => {
        const h = state.history[i];
        if (!h) return { color:"var(--border)", filled:false, passed:null };
        // R5: hex literal — o glow do ponto concatena alpha (`${cssHex(d.color)}66`).
        return { color: h.passed ? "var(--jade)" : "var(--red)", filled:true, passed:h.passed };
      });

      // Footer adapts: while playing we show no footer (action picker is in
      // the body); on completion the close-CTA goes in the sticky footer.
      const footer = finalResult ? (
        <ActionBtn variant="primary" onClick={close} style={{ width:"100%" }}>{t("alch_close")}</ActionBtn>
      ) : null;

      return (
        <Modal
          onClose={close}
          allowBackdropClose={!!finalResult}
          showCloseBtn={!!finalResult}
          title={`🌟 ${t("pill_trib_title")}`}
          accent="rgba(var(--realm-3-rgb),.55)"
          maxWidth={420}
          zIndex={80}
          cardStyle={{
            background:"linear-gradient(180deg, rgba(20,8,40,.98), rgba(8,4,20,1))",
            boxShadow:"0 0 60px rgba(var(--realm-3-rgb),.4), inset 0 0 30px rgba(var(--realm-3-rgb),.12)",
          }}
          footer={footer}
        >
            {/* Storm background */}
            <div style={{
              position:"absolute", inset:0,
              background:"radial-gradient(circle at 50% 30%, rgba(var(--realm-3-rgb),.18), transparent 60%)",
              animation:"trib-storm 4s ease-in-out infinite", pointerEvents:"none",
            }} />

            <div style={{ position:"relative", zIndex:2 }}>
              <div style={{ textAlign:"center", marginBottom:12 }}>
                <div style={{ fontSize:11, color:"rgba(var(--realm-3-rgb),.85)", letterSpacing:1.5, fontFamily:"'Cinzel',serif", textTransform:"uppercase" }}>
                  {t("pill_trib_title")}
                </div>
                {itemVivoOn() ? (
                  <div style={{ display:"grid", placeItems:"center", marginTop:6,
                                animation: animating ? "trib-pill-shake .7s ease-in-out" : "alch-pop 420ms cubic-bezier(.2,1.4,.4,1)" }}>
                    <PieceIcon kind="pill" name={state.pill_name} artKey={state.pill_art_key} emoji={state.pill_emoji}
                               size={76} accent="var(--realm-3)" radius={10} />
                  </div>
                ) : (
                <div style={{ fontSize:36, marginTop:6, animation: animating ? "trib-pill-shake .7s ease-in-out" : "alch-pop 420ms cubic-bezier(.2,1.4,.4,1)" }}>
                  {state.pill_emoji}
                </div>
                )}
                <div style={{ fontFamily:"'Cinzel',serif", fontSize:14, fontWeight:700, color:"var(--gold2)", marginTop:4 }}>
                  {state.pill_name}
                </div>
              </div>

              {/* Round indicator */}
              <div style={{ display:"flex", justifyContent:"center", gap:8, marginBottom:12 }}>
                {dots.map((d, i) => (
                  <div key={i} style={{
                    width:14, height:14, borderRadius:"50%",
                    background: d.filled ? d.color : "rgba(40,30,80,.6)",
                    border: d.filled ? `1px solid ${d.color}` : "1px solid rgba(var(--realm-3-rgb),.3)",
                    boxShadow: d.filled ? `0 0 8px ${cssHex(d.color)}66` : "none",
                    transition:"all .3s",
                  }} />
                ))}
              </div>

              <div style={{ textAlign:"center", marginBottom:14, fontSize:11, color:"var(--muted)" }}>
                {finalResult ? t("pill_trib_complete") : t("pill_trib_round_progress", {
                  round: Math.min(state.round, state.rounds_total),
                  total: state.rounds_total,
                  successes: state.successes,
                  needed: state.pass_threshold,
                })}
              </div>

              {/* Last round flash */}
              {lastResult && !animating && (
                <div style={{
                  textAlign:"center", marginBottom:12, padding:"8px",
                  background: lastResult.passed ? "rgba(var(--jade-rgb),.1)" : "rgba(var(--red-rgb),.1)",
                  border:`1px solid ${lastResult.passed ? "rgba(var(--jade-rgb),.4)" : "rgba(var(--red-rgb),.4)"}`,
                  borderRadius:8,
                  animation:"alch-pop 320ms",
                }}>
                  <div style={{ fontSize:13, fontWeight:700, color: lastResult.passed ? "var(--jade)" : "var(--red)" }}>
                    {lastResult.passed ? "✅" : "❌"} {t(`pill_trib_${lastResult.action}`)}
                    {lastResult.bonus_applied > 0 && <span style={{ color:"var(--gold3)", marginLeft:6 }}>+{lastResult.bonus_applied} {t("pill_trib_bonus")}</span>}
                  </div>
                </div>
              )}

              {finalResult ? (
                <div>
                  {finalResult.passed ? (
                    <Card style={{
                      background:"linear-gradient(180deg, rgba(var(--gold2-rgb),.18), rgba(120,80,30,.25))",
                      border:"1px solid rgba(var(--gold2-rgb),.6)", padding:"14px 14px 12px",
                      boxShadow:"0 0 30px rgba(var(--gold2-rgb),.4)",
                      textAlign:"center",
                    }} ornate={false}>
                      <div style={{ fontSize:50, animation:"alch-icon-spin 1s ease-out", filter:"drop-shadow(0 0 18px rgba(var(--gold2-rgb),.8))" }}>🌟</div>
                      <div style={{ fontFamily:"'Cinzel',serif", fontSize:16, fontWeight:700, color:"var(--gold3)", marginTop:6 }}>
                        {t("pill_trib_success_title")}
                      </div>
                      <div style={{ fontSize:11, color:"var(--gold2)", marginTop:6 }}>
                        {t("pill_trib_success_body", { pill_name: state.pill_name })}
                      </div>
                      <div style={{ fontSize:10, color:"var(--gold3)", marginTop:6, fontFamily:"'Cinzel',serif", letterSpacing:.6 }}>
                        ×5.0 {t("alch_potency")}
                      </div>
                      {/* QoL-relatos — o XP de ofício da tribulação, VISÍVEL
                          (Lei §10). O endpoint passou a emitir estas keys e o
                          chat já as mostra; sem isto a superfície canônica
                          engolia o MAIOR ganho de ofício do jogo. Keys
                          condicionais → undefined > 0 é false com flag OFF. */}
                      {finalResult.prof_xp_gained > 0 && (
                        <div style={{ fontSize:10, color:"var(--gold3)", marginTop:6 }}>🏮 {finalResult.prof_weight_tier
                          ? t("prf_mini_xp_gain_tier", { n: finalResult.prof_xp_gained, tier: finalResult.prof_weight_tier, w: finalResult.prof_weight })
                          : t("prf_mini_xp_gain", { n: finalResult.prof_xp_gained })}</div>
                      )}
                    </Card>
                  ) : (
                    <Card style={{
                      background:"linear-gradient(180deg, rgba(var(--red-rgb),.15), rgba(60,15,15,.3))",
                      border:"1px solid rgba(var(--red-rgb),.5)", padding:"14px 14px 12px",
                      textAlign:"center",
                    }} ornate={false}>
                      <div style={{ fontSize:48, animation:"alch-icon-shake 700ms" }}>💔</div>
                      <div style={{ fontFamily:"'Cinzel',serif", fontSize:14, fontWeight:700, color:"var(--red)", marginTop:6 }}>
                        {t("pill_trib_fail_title")}
                      </div>
                      <div style={{ fontSize:11, color:"var(--muted)", marginTop:6 }}>
                        {t("pill_trib_fail_body", { pill_name: state.pill_name })}
                      </div>
                      {finalResult.penalty && (
                        <div style={{ fontSize:10.5, color:"var(--warn)", marginTop:8 }}>
                          🔧 -{finalResult.penalty.durability_lost} {t("alch_durability")} · ⚡ -{finalResult.penalty.qi_lost} Qi
                        </div>
                      )}
                    </Card>
                  )}
                </div>
              ) : (
                <div>
                  <div style={{ fontSize:11, color:"var(--muted)", textAlign:"center", marginBottom:8 }}>
                    {t("pill_trib_choose")}
                  </div>
                  <div style={{ display:"flex", flexDirection:"column", gap:8 }}>
                    {TRIBULATION_ACTIONS.map(a => {
                      const isActive = animating === a.key;
                      return (
                        <button key={a.key}
                                disabled={busy || !!finalResult}
                                onClick={() => chooseAction(a.key)}
                                style={{
                                  cursor: busy ? "default" : "pointer",
                                  background: isActive
                                    ? `linear-gradient(180deg, ${cssHex(a.color)}33, ${cssHex(a.color)}11)`
                                    : "linear-gradient(180deg, rgba(40,20,80,.5), rgba(20,8,40,.7))",
                                  border:`1px solid ${cssHex(a.color)}55`,
                                  borderRadius:10, padding:"10px 12px",
                                  textAlign:"left", color:"var(--text)",
                                  opacity: busy && !isActive ? .5 : 1,
                                  boxShadow: isActive ? `0 0 24px ${a.glow}, inset 0 0 12px ${cssHex(a.color)}22` : "none",
                                  transition:"all .2s",
                                  animation: isActive ? "trib-action-flash .7s ease-out" : "none",
                                  display:"flex", alignItems:"center", gap:10,
                                }}>
                          <span style={{
                            fontSize:24,
                            filter: isActive ? `drop-shadow(0 0 12px ${a.glow})` : "none",
                            animation: isActive ? "alch-icon-spin .7s" : "none",
                          }}>{a.icon}</span>
                          <div style={{ flex:1, minWidth:0 }}>
                            <div style={{ fontFamily:"'Cinzel',serif", fontSize:12.5, fontWeight:700, color: a.color }}>
                              {t(a.label_key)} <span style={{ color:"var(--muted)", fontWeight:400 }}>· {a.rate_pct}%</span>
                            </div>
                            <div style={{ fontSize:10, color:"var(--muted)", marginTop:2 }}>{t(a.desc_key)}</div>
                          </div>
                        </button>
                      );
                    })}
                  </div>
                  {err && <div style={{ marginTop:8 }}><ErrBanner msg={err} /></div>}
                </div>
              )}
            </div>
        </Modal>
      );
    }

    function CauldronPickerModal({ data, onClose, onEquipped }) {
      const [busy, setBusy] = useState(0);
      const [err, setErr] = useState(null);
      // Sprint v14.14g — repair/upgrade drill-ins (mini-app port of chat
      // alch_repair_info / alch_upgrade_info flows).
      const [repairOpen, setRepairOpen] = useState(false);
      const [upgradeOpen, setUpgradeOpen] = useState(false);
      const owned = data.owned_cauldrons || [];

      async function callEquip(cauldron_id) {
        if (busy) return;
        haptic("select");
        setBusy(cauldron_id); setErr(null);
        try {
          const res = await api("alchemy/equip_cauldron", { cauldron_id });
          if (!res.ok) {
            haptic("error");
            setErr(alchReason(res.reason));
            setBusy(0);
            return;
          }
          haptic("success");
          showToast(t("alch_cauldron_equipped"));
          onEquipped && onEquipped();
          onClose && onClose();
        } catch (e) {
          haptic("error");
          setErr(t("alch_err_engine"));
          setBusy(0);
        }
      }

      return (
        <Modal onClose={onClose}
               title={`⚗️ ${t("alch_cauldron_picker_title")}`}
               accent="rgba(var(--gold2-rgb),.4)"
               maxWidth={480} zIndex={60}>
            {err && <ErrBanner msg={err} />}

            {owned.length === 0 ? (
              <Card><div style={{ textAlign:"center", padding:"18px 8px", color:"var(--muted)", fontSize:12 }}>{t("alch_no_cauldrons")}</div></Card>
            ) : (
              <div style={{ display:"flex", flexDirection:"column", gap:8 }}>
                {owned.map(c => {
                  const durPct = c.max_durability > 0 ? Math.round((c.durability / c.max_durability) * 100) : 0;
                  const durColor = c.durability <= 0 ? "var(--red)"
                                  : durPct < 30 ? "var(--warn)"
                                  : durPct < 60 ? "var(--gold2)"
                                  : "var(--jade)";
                  return (
                    <div key={c.id} style={{
                      padding:"10px 12px", borderRadius:10,
                      border: c.is_equipped ? "1px solid var(--jade)" : "1px solid rgba(var(--gold2-rgb),.2)",
                      background: c.is_equipped ? "linear-gradient(180deg, rgba(var(--jade-rgb),.08), rgba(20,40,30,.3))"
                                                : "rgba(0,0,0,.25)",
                    }}>
                      <div style={{ display:"flex", alignItems:"center", gap:10, marginBottom:6 }}>
                        <span style={{ fontSize:24 }}>{c.emoji}</span>
                        <div style={{ flex:1, minWidth:0 }}>
                          <div style={{ fontFamily:"'Cinzel',serif", fontWeight:700, fontSize:13, color:"var(--gold2)" }}>
                            {c.name} {c.is_equipped && <span style={{ color:"var(--jade)", fontSize:10, fontWeight:400 }}>· {t("alch_equipped")}</span>}
                          </div>
                          <div style={{ fontSize:10, color:"var(--muted)", marginTop:2 }}>
                            {t("alch_grade", { n: c.grade })} · +{Math.round(c.success_bonus)}% · {c.slots} {t("alch_slots")}
                          </div>
                        </div>
                      </div>
                      <div style={{ display:"flex", alignItems:"center", gap:6, marginBottom: 8 }}>
                        <span style={{ fontSize:10, color:"var(--muted)" }}>🔧</span>
                        <div style={{ flex:1, height:5, borderRadius:3, background:"rgba(0,0,0,.5)", overflow:"hidden" }}>
                          <div style={{ width:`${durPct}%`, height:"100%", background: durColor }} />
                        </div>
                        <span style={{ fontSize:10, color:"var(--muted2)" }}>{c.durability}/{c.max_durability}</span>
                      </div>
                      {!c.is_equipped ? (
                        <ActionBtn variant="primary" disabled={!!busy} onClick={() => callEquip(c.id)}>
                          {busy === c.id ? <DotSpinner /> : t("alch_equip_btn")}
                        </ActionBtn>
                      ) : (
                        <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:6 }}>
                          <ActionBtn variant="ghost" disabled={c.durability >= c.max_durability}
                                     onClick={() => { haptic("select"); setRepairOpen(true); }}>
                            🔧 {t("cauldron_repair_btn_short")}
                          </ActionBtn>
                          <ActionBtn variant="ghost" disabled={c.grade >= 7}
                                     onClick={() => { haptic("select"); setUpgradeOpen(true); }}>
                            ⬆️ {t("cauldron_upgrade_btn_short")}
                          </ActionBtn>
                        </div>
                      )}
                    </div>
                  );
                })}
              </div>
            )}

            <div style={{ marginTop:14, padding:"10px 12px", background:"rgba(var(--gold2-rgb),.05)",
                          borderRadius:8, border:"1px solid rgba(var(--gold2-rgb),.18)",
                          fontSize:10.5, color:"var(--muted)", lineHeight:1.5 }}>
              💡 {t("alch_cauldron_hint")}
            </div>

            {repairOpen && (
              <CauldronRepairModal data={data} onClose={() => setRepairOpen(false)}
                onDone={() => { onEquipped && onEquipped(); }} />
            )}
            {upgradeOpen && (
              <CauldronUpgradeModal data={data} onClose={() => setUpgradeOpen(false)}
                onDone={() => { onEquipped && onEquipped(); }} />
            )}
        </Modal>
      );
    }

    // ─── Sprint v14.14g — Cauldron repair + upgrade modals ──────────────────
    // Both modals fetch a fresh dry-run preview from the server on open and
    // whenever the amount changes (repair). The chat flow is "alch_repair_info
    // → alch_repair_50 / alch_repair_full" — we replicate that as preview-then-
    // confirm without forcing the player to round-trip through Telegram.
    function CauldronRepairModal({ data, onClose, onDone }) {
      const ec = data.equipped_cauldron;
      const [amount, setAmount] = useState("full");
      const [preview, setPreview] = useState(null);
      const [busy, setBusy] = useState(false);
      const [err, setErr] = useState(null);
      const [reload, setReload] = useState(0);

      useEffect(() => {
        let cancelled = false;
        setErr(null);
        (async () => {
          try {
            const res = await api("alchemy/cauldron/repair", { amount, dry_run: true });
            if (cancelled) return;
            if (!res.ok) { setErr(alchReason(res.reason)); setPreview(null); return; }
            setPreview(res);
          } catch (e) {
            if (!cancelled) setErr(t("alch_err_engine"));
          }
        })();
        return () => { cancelled = true; };
      }, [amount, reload]);

      async function confirm() {
        if (busy || !preview || !preview.can_afford) return;
        haptic("warning"); setBusy(true); setErr(null);
        try {
          const res = await api("alchemy/cauldron/repair", { amount });
          if (!res.ok) {
            haptic("error"); setErr(alchReason(res.reason)); setBusy(false);
            // Refresh preview so the player sees post-failure state (rare —
            // typically just not_enough_stones drift between preview/confirm).
            setReload(x => x + 1);
            return;
          }
          haptic("success");
          showToast(t("cauldron_repair_done", { n: res.repaired, cost: fmtNum(res.cost) }));
          onDone && onDone(res);
          onClose && onClose();
        } catch (e) {
          haptic("error"); setErr(t("alch_err_engine")); setBusy(false);
        }
      }

      const footer = preview && (
        <ActionBtn variant="primary" disabled={busy || !preview.can_afford}
                   onClick={confirm} style={{ width:"100%" }}>
          {busy ? <DotSpinner /> :
            preview.can_afford
              ? `🔧 ${t("cauldron_repair_confirm_btn", { cost: fmtNum(preview.cost) })}`
              : `🔧 ${t("cauldron_repair_not_enough_stones")}`}
        </ActionBtn>
      );

      return (
        <Modal onClose={onClose} title={`🔧 ${t("cauldron_repair_title")}`}
               accent="rgba(var(--gold2-rgb),.45)" maxWidth={440} zIndex={70}
               footer={footer}>
          {err && <ErrBanner msg={err} />}

          {ec && (
            <Card style={{ padding:"10px 12px", marginBottom:10 }}>
              <div style={{ display:"flex", alignItems:"center", gap:10 }}>
                <span style={{ fontSize:24 }}>{ec.emoji}</span>
                <div style={{ flex:1, minWidth:0 }}>
                  <div style={{ fontFamily:"'Cinzel',serif", fontWeight:700, fontSize:13, color:"var(--gold2)" }}>
                    {ec.name}
                  </div>
                  <div style={{ fontSize:10.5, color:"var(--muted)" }}>
                    🔧 {ec.durability}/{ec.max_durability} · {t("alch_grade", { n: ec.grade })}
                  </div>
                </div>
              </div>
            </Card>
          )}

          <div style={{ fontSize:11.5, color:"var(--muted)", lineHeight:1.5, marginBottom:10 }}>
            {t("cauldron_repair_explainer")}
          </div>

          <Card style={{ padding:"10px 12px", marginBottom:10 }}>
            <CardTitle left={t("cauldron_repair_amount_label")} />
            <SegControl
              options={[
                { value:"50",   label:`+50 ${t("cauldron_repair_amount_unit")}` },
                { value:"full", label:t("cauldron_repair_amount_full") },
              ]}
              value={amount === 50 || amount === "50" ? "50" : "full"}
              onChange={v => setAmount(v === "50" ? 50 : "full")} />
          </Card>

          {preview ? (
            <Card style={{ padding:"10px 12px" }}>
              <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", marginBottom:6 }}>
                <span style={{ fontSize:11, color:"var(--muted)" }}>
                  {t("cauldron_repair_preview_label")}
                </span>
                <b style={{ color:"var(--gold2)" }}>
                  +{preview.amount_actual} {t("cauldron_repair_amount_unit")}
                </b>
              </div>
              <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", marginBottom:6 }}>
                <span style={{ fontSize:11, color:"var(--muted)" }}>
                  {t("cauldron_repair_new_dur")}
                </span>
                <b style={{ color:"var(--jade)" }}>
                  {preview.new_durability_preview}/{preview.max_durability}
                </b>
              </div>
              <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center" }}>
                <span style={{ fontSize:11, color:"var(--muted)" }}>
                  💰 {t("cauldron_repair_cost")}
                </span>
                <b style={{ color: preview.can_afford ? "var(--gold2)" : "var(--red)" }}>
                  {fmtNum(preview.cost)} 🪙
                </b>
              </div>
              <div style={{ fontSize:10, color:"var(--muted2)", marginTop:6 }}>
                {t("cauldron_repair_your_stones", { stones: fmtNum(preview.your_stones) })}
              </div>
            </Card>
          ) : (
            <div style={{ textAlign:"center", padding:"14px 8px" }}>
              <DotSpinner />
            </div>
          )}
        </Modal>
      );
    }

    function CauldronUpgradeModal({ data, onClose, onDone }) {
      const ec = data.equipped_cauldron;
      const [preview, setPreview] = useState(null);
      const [busy, setBusy] = useState(false);
      const [err, setErr] = useState(null);
      const [result, setResult] = useState(null);
      const [reload, setReload] = useState(0);

      useEffect(() => {
        let cancelled = false;
        setErr(null);
        (async () => {
          try {
            const res = await api("alchemy/cauldron/upgrade", { dry_run: true });
            if (cancelled) return;
            if (!res.ok) { setErr(alchReason(res.reason)); setPreview(null); return; }
            setPreview(res);
          } catch (e) {
            if (!cancelled) setErr(t("alch_err_engine"));
          }
        })();
        return () => { cancelled = true; };
      }, [reload]);

      async function confirm() {
        if (busy || !preview || !preview.can_attempt) return;
        haptic("warning"); setBusy(true); setErr(null);
        try {
          const res = await api("alchemy/cauldron/upgrade", {});
          if (res.ok) {
            haptic("success");
            setResult({ kind:"success", payload: res });
            onDone && onDone(res);
            return;
          }
          // failed_roll is a "soft fail" — engine consumed ores + 50% stones
          // + 20 durability. Show the loss screen instead of dismissing.
          if (res.reason === "failed_roll") {
            haptic("error");
            setResult({ kind:"failed_roll", payload: res });
            onDone && onDone(res);
            return;
          }
          haptic("error");
          setErr(alchReason(res.reason));
          setBusy(false);
          setReload(x => x + 1);
        } catch (e) {
          haptic("error"); setErr(t("alch_err_engine")); setBusy(false);
        }
      }

      if (result) {
        const isOk = result.kind === "success";
        return (
          <Modal onClose={onClose}
                 title={isOk ? `⬆️ ${t("cauldron_upgrade_success_title")}`
                             : `💥 ${t("cauldron_upgrade_failed_title")}`}
                 accent={isOk ? "rgba(var(--jade-rgb),.5)" : "rgba(var(--red-rgb),.45)"}
                 maxWidth={420} zIndex={71}
                 footer={
                   <ActionBtn variant="primary" onClick={onClose} style={{ width:"100%" }}>
                     {t("alch_close")}
                   </ActionBtn>
                 }>
            {isOk ? (
              <Card style={{ padding:"14px 14px 12px", textAlign:"center" }}>
                <div style={{ fontSize:42, marginBottom:6 }}>{result.payload.new_cauldron?.emoji || "⚗️"}</div>
                <div style={{ fontFamily:"'Cinzel',serif", fontSize:15, color:"var(--jade)", fontWeight:700 }}>
                  {result.payload.new_cauldron?.name}
                </div>
                <div style={{ fontSize:11, color:"var(--muted)", marginTop:4 }}>
                  {t("alch_grade", { n: result.payload.new_cauldron?.grade ?? 0 })} ·
                  +{Math.round(result.payload.new_cauldron?.success_bonus ?? 0)}% ·
                  {result.payload.new_cauldron?.slots} {t("alch_slots")}
                </div>
                <div style={{ fontSize:10.5, color:"var(--muted2)", marginTop:10 }}>
                  💰 {t("cauldron_upgrade_stones_spent", { stones: fmtNum(result.payload.stones_spent) })}
                </div>
              </Card>
            ) : (
              <Card style={{ padding:"14px 14px 12px" }}>
                <div style={{ fontSize:11, color:"var(--muted)", lineHeight:1.5, marginBottom:8 }}>
                  {t("cauldron_upgrade_failed_msg")}
                </div>
                <div style={{ display:"flex", justifyContent:"space-between", marginBottom:5 }}>
                  <span style={{ fontSize:11, color:"var(--muted)" }}>💰 {t("cauldron_upgrade_stones_lost")}</span>
                  <b style={{ color:"var(--red)" }}>−{fmtNum(result.payload.stones_lost)}</b>
                </div>
                <div style={{ display:"flex", justifyContent:"space-between" }}>
                  <span style={{ fontSize:11, color:"var(--muted)" }}>🔧 {t("cauldron_upgrade_dur_lost")}</span>
                  <b style={{ color:"var(--red)" }}>−{result.payload.durability_lost}</b>
                </div>
              </Card>
            )}
          </Modal>
        );
      }

      const footer = preview && preview.next && (
        <ActionBtn variant="primary"
                   disabled={busy || !preview.can_attempt}
                   onClick={confirm} style={{ width:"100%" }}>
          {busy ? <DotSpinner /> : `⬆️ ${t("cauldron_upgrade_confirm_btn", {
            pct: Math.round((preview.success_rate || 0) * 100),
          })}`}
        </ActionBtn>
      );

      return (
        <Modal onClose={onClose} title={`⬆️ ${t("cauldron_upgrade_title")}`}
               accent="rgba(var(--gold2-rgb),.5)" maxWidth={460} zIndex={70}
               footer={footer}>
          {err && <ErrBanner msg={err} />}
          {!preview ? (
            <div style={{ textAlign:"center", padding:"24px 8px" }}><DotSpinner /></div>
          ) : !preview.next ? (
            <Card><div style={{ textAlign:"center", padding:"20px 8px", color:"var(--muted)", fontSize:12 }}>
              ⭐ {t("alch_max_tier")}
            </div></Card>
          ) : (
            <>
              {ec && (
                <Card style={{ padding:"10px 12px", marginBottom:10 }}>
                  <CardTitle left={t("cauldron_upgrade_transition")} />
                  <div style={{ display:"flex", alignItems:"center", gap:8, justifyContent:"center" }}>
                    <div style={{ textAlign:"center", flex:1 }}>
                      <div style={{ fontSize:28 }}>{ec.emoji}</div>
                      <div style={{ fontSize:10.5, color:"var(--muted)" }}>{ec.name}</div>
                      <div style={{ fontSize:10, color:"var(--muted2)" }}>
                        +{Math.round(ec.success_bonus)}% · {ec.slots} {t("alch_slots")}
                      </div>
                    </div>
                    <div style={{ fontSize:18, color:"var(--gold2)" }}>→</div>
                    <div style={{ textAlign:"center", flex:1 }}>
                      <div style={{ fontSize:28, filter:"drop-shadow(0 0 6px rgba(var(--gold2-rgb),.6))" }}>
                        {preview.next.emoji}
                      </div>
                      <div style={{ fontSize:10.5, color:"var(--jade)" }}>{preview.next.name}</div>
                      <div style={{ fontSize:10, color:"var(--muted2)" }}>
                        +{Math.round(preview.next.success_bonus)}% · {preview.next.slots} {t("alch_slots")}
                      </div>
                    </div>
                  </div>
                </Card>
              )}

              <Card style={{ padding:"10px 12px", marginBottom:10 }}>
                <CardTitle left={t("cauldron_upgrade_materials")} />
                <div style={{ display:"flex", flexDirection:"column", gap:5 }}>
                  {(preview.ores || []).map(o => (
                    <div key={o.ore_id} style={{
                      display:"flex", alignItems:"center", gap:8,
                      padding:"6px 8px", borderRadius:6,
                      background: o.ok ? "rgba(var(--jade-rgb),.06)" : "rgba(var(--red-rgb),.06)",
                      border:`1px solid ${o.ok ? "rgba(var(--jade-rgb),.18)" : "rgba(var(--red-rgb),.18)"}`,
                    }}>
                      <span style={{ fontSize:18 }}>{o.emoji}</span>
                      <span style={{ flex:1, fontSize:12, color:"var(--text)" }}>{o.name}</span>
                      <span style={{ fontSize:11, color:"var(--muted)" }}>
                        <b style={{ color: o.ok ? "var(--jade)" : "var(--red)" }}>{o.owned}</b>
                        <span> / {o.required}</span>
                      </span>
                      <span style={{ fontSize:14 }}>{o.ok ? "✅" : "❌"}</span>
                    </div>
                  ))}
                  <div style={{
                    display:"flex", alignItems:"center", gap:8,
                    padding:"6px 8px", borderRadius:6,
                    background: preview.stones_ok ? "rgba(var(--jade-rgb),.06)" : "rgba(var(--red-rgb),.06)",
                    border:`1px solid ${preview.stones_ok ? "rgba(var(--jade-rgb),.18)" : "rgba(var(--red-rgb),.18)"}`,
                  }}>
                    <span style={{ fontSize:18 }}>🪙</span>
                    <span style={{ flex:1, fontSize:12, color:"var(--text)" }}>{t("cauldron_upgrade_stones")}</span>
                    <span style={{ fontSize:11, color:"var(--muted)" }}>
                      <b style={{ color: preview.stones_ok ? "var(--jade)" : "var(--red)" }}>{fmtNum(preview.your_stones)}</b>
                      <span> / {fmtNum(preview.stones_required)}</span>
                    </span>
                    <span style={{ fontSize:14 }}>{preview.stones_ok ? "✅" : "❌"}</span>
                  </div>
                </div>
              </Card>

              <Card style={{ padding:"10px 12px" }}>
                <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center" }}>
                  <span style={{ fontSize:11, color:"var(--muted)" }}>🎯 {t("cauldron_upgrade_odds")}</span>
                  <b style={{ color: preview.success_rate >= 0.7 ? "var(--jade)"
                                    : preview.success_rate >= 0.4 ? "var(--gold2)" : "var(--warn)" }}>
                    {Math.round(preview.success_rate * 100)}%
                  </b>
                </div>
                {preview.success_rate < 1.0 && (
                  <div style={{ fontSize:10, color:"var(--warn)", marginTop:6, lineHeight:1.4 }}>
                    ⚠️ {t("cauldron_upgrade_fail_warning")}
                  </div>
                )}
              </Card>
            </>
          )}
        </Modal>
      );
    }

    function AlchemyPanel({ onPlayerRefresh }) {
      const [reload, setReload] = useState(0);
      const [activeTier, setActiveTier] = useState(null);
      const [pickedRecipe, setPickedRecipe] = useState(null);
      const [craftResult, setCraftResult] = useState(null);
      const [tribulation, setTribulation] = useState(null);
      const [showCauldronPicker, setShowCauldronPicker] = useState(false);
      const [filterCraftable, setFilterCraftable] = useState(false);
      const { data, loading, error } = useApi("alchemy_recipes", null, [reload]);
      const refresh = useCallback(() => setReload(x => x + 1), []);

      useEffect(() => {
        if (activeTier !== null || !data) return;
        const cur = data.alchemy?.tier || 1;
        setActiveTier(cur);
      }, [activeTier, data]);

      // Keep `pickedRecipe` pointing at the fresh recipe object every time
      // `data` refreshes — otherwise the detail modal would render stale
      // ingredient counts after a craft.
      // CRITICAL: this MUST stay above the early returns below, otherwise
      // React renders fewer hooks on the loading/realm_locked paths than on
      // the main path → "Rendered fewer hooks than expected" (#310). The
      // effect's body itself already short-circuits when data/pickedRecipe
      // are absent, so calling it unconditionally is safe.
      useEffect(() => {
        if (!data || !pickedRecipe) return;
        const fresh = (data.tiers || [])
          .flatMap(tg => tg.recipes || [])
          .find(r => r.id === pickedRecipe.id);
        if (fresh && fresh !== pickedRecipe) setPickedRecipe(fresh);
      }, [data]);

      if (loading && !data) return <ListSkeleton rows={6} />;
      if (error && !data) return <ErrBanner msg={error} />;
      if (!data) return null;

      if (data.realm_locked) {
        return (
          <Card>
            <div style={{ textAlign:"center", padding:"30px 12px", color:"var(--muted)" }}>
              <div style={{ fontSize:38, marginBottom:8, ...(markOn("lock") ? { display:"grid", placeItems:"center" } : {}) }}>{ico("🔒","lock",{ size:40 })}</div>
              <div style={{ fontFamily:"'Cinzel',serif", fontSize:13, color:"var(--gold2)" }}>
                {t("alch_locked_title")}
              </div>
              {/* 冶 3.1 — o reino vem do SERVIDOR (`min_realm_required`, o dono é
                  `ALCHEMY_MIN_REALM`) e o nome do `realmName`. Sem o número, a
                  frase genérica — nunca "Mortal" por um `undefined`. */}
              <div style={{ fontSize:11, marginTop:6 }}>
                {Number.isInteger(data.min_realm_required)
                  ? t("alch_locked_msg", { realm: realmName(data.min_realm_required), n: data.min_realm_required })
                  : t("alch_err_realm_locked")}
              </div>
            </div>
          </Card>
        );
      }

      const tiers = data.tiers || [];
      const segOptions = tiers.map(tg => ({
        value: tg.tier,
        label: tg.locked ? `🔒 T${tg.tier}` : `${tg.emoji} T${tg.tier}`,
      }));
      const activeTierData = tiers.find(tg => tg.tier === activeTier) || tiers[0];

      const recipesShown = activeTierData
        ? (filterCraftable ? activeTierData.recipes.filter(r => r.can_craft) : activeTierData.recipes)
        : [];

      function handleCraftResult(res) {
        // Owner UX (2026-05-05): the detail modal MUST stay "fixo" so the
        // player can chain crafts without re-picking the recipe. Result modal
        // opens at z-index 70 over detail's 60. We refresh data so the
        // detail modal re-renders with updated material/energy counts; the
        // useEffect at the top of the function points pickedRecipe at the
        // fresh recipe object.
        const isHeavenly =
          res.result === "heavenly_tribulation_pending" ||
          (res.bulk && res.early_stop_reason === "heavenly_tribulation_pending");
        if (isHeavenly) {
          // Heavenly takes over the screen — close detail so the tribulation
          // mini-game has full focus. The bulk result is summarised inline
          // before the trib modal opens (we keep both: result first, then
          // trib on dismiss).
          if (res.bulk && res.crafts_done > 0) {
            setCraftResult(res);
          }
          setPickedRecipe(null);
          setTribulation(res.tribulation);
        } else {
          setCraftResult(res);
        }
        refresh();
        onPlayerRefresh && onPlayerRefresh();
      }

      function handleTribulationComplete(finalRes) {
        setTribulation(null);
        refresh();
        onPlayerRefresh && onPlayerRefresh();
      }

      return (
        <div>
          <AlchemyHeaderCard data={data} onPickCauldron={() => setShowCauldronPicker(true)}
                             onChanged={refresh} />

          {tiers.length > 1 && (
            <Card style={{ padding:"8px 10px", marginBottom:10 }}>
              <SegControl options={segOptions} value={activeTier ?? tiers[0].tier} onChange={setActiveTier} />
            </Card>
          )}

          <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", marginBottom:8, padding:"0 4px" }}>
            <div style={{ fontSize:11, color:"var(--muted)" }}>
              {activeTierData?.locked ? t("alch_tier_locked_msg", { n: activeTier })
                : t("alch_recipes_count", { n: recipesShown.length, total: activeTierData?.recipes.length || 0 })}
            </div>
            <button onClick={() => { haptic("select"); setFilterCraftable(x => !x); }}
                    style={{
                      background: filterCraftable ? "rgba(var(--jade-rgb),.15)" : "rgba(0,0,0,.3)",
                      border:`1px solid ${filterCraftable ? "rgba(var(--jade-rgb),.4)" : "rgba(var(--gold2-rgb),.18)"}`,
                      borderRadius:6, padding:"4px 8px", cursor:"pointer",
                      fontSize:10.5, color: filterCraftable ? "var(--jade)" : "var(--muted)",
                      fontFamily:"'Cinzel',serif",
                    }}>
              {filterCraftable ? "✅" : "○"} {t("alch_filter_craftable")}
            </button>
          </div>

          {activeTierData?.locked ? (
            /* TAPETE QoL §5 item 7 ([jogador]: "Voce vai colocar algo no futuro
               para conseguir as receitas?"): locked tiers used to render a
               bare lock card — silent void (Lei §1). Now the entries list
               with 🔒, and T4/T5 get the honest "desperta no novo mundo"
               teaser (mirrors chat's alch_recipe_locked_apex). Nothing is
               unlocked — display only. */
            <>
              <Card style={{ marginBottom:8 }}>
                <div style={{ textAlign:"center", padding:"10px 8px", color:"var(--muted)", fontSize:12 }}>
                  🔒 {t("alch_tier_locked_msg", { n: activeTier })}
                </div>
                {activeTier >= 4 && (
                  <div style={{ textAlign:"center", padding:"0 10px 10px", color:"var(--gold2)",
                                fontSize:11, fontStyle:"italic", lineHeight:1.5 }}>
                    {t("alch_locked_tier_teaser")}
                  </div>
                )}
              </Card>
              <div style={{ display:"flex", flexDirection:"column", gap:6 }}>
                {(activeTierData?.recipes || []).map(r => (
                  <div key={r.id} style={{
                    display:"flex", alignItems:"center", gap:8, padding:"8px 12px",
                    borderRadius:10, opacity:.6,
                    background:"linear-gradient(180deg, rgba(var(--surface-rgb),.55), rgba(13,16,28,.7))",
                    border:"1px solid rgba(255,255,255,.06)",
                  }}>
                    {itemVivoOn()
                      ? <PieceIcon kind="pill" name={r.name} artKey={r.art_key} emoji={r.emoji} size={30}
                                   accent="var(--muted)" radius={6} dim />
                      : <span style={{ fontSize:18, filter:"grayscale(.7)" }}>{r.emoji}</span>}
                    <span style={{ flex:1, minWidth:0, fontSize:12, color:"var(--muted)",
                                   fontFamily:"'Cinzel',serif",
                                   overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap" }}>
                      {r.name}
                    </span>
                    <span style={{ fontSize:12, flexShrink:0 }}>{ico("🔒","lock",{ size:13, style:{ display:"inline-block", verticalAlign:"-2px" } })}</span>
                  </div>
                ))}
              </div>
            </>
          ) : recipesShown.length === 0 ? (
            <Card><div style={{ textAlign:"center", padding:"20px 8px", color:"var(--muted)", fontSize:12 }}>
              {filterCraftable ? t("alch_no_craftable") : t("alch_no_recipes_in_tier")}
            </div></Card>
          ) : (
            (typeof featureEnabled === "function" && featureEnabled("cartas")) ? (
              <CardGrid min={168}>
                {recipesShown.map(r => (
                  <RecipeCard key={r.id} recipe={r} onClick={setPickedRecipe} lang={LANG} />
                ))}
              </CardGrid>
            ) : (
            <div style={{ display:"flex", flexDirection:"column", gap:8 }}>
              {recipesShown.map(r => (
                <RecipeCard key={r.id} recipe={r} onClick={setPickedRecipe} lang={LANG} />
              ))}
            </div>
            )
          )}

          {pickedRecipe && (
            <RecipeDetailModal recipe={pickedRecipe} energy={data.energy}
              onClose={() => setPickedRecipe(null)} onCraft={handleCraftResult} />
          )}
          {craftResult && (
            <CraftResultModal result={craftResult} onClose={() => setCraftResult(null)}
              onCraftAgain={() => {
                // Detail modal already stays open underneath (z=60); just
                // dismiss the result overlay (z=70). Player can change the
                // bulk count and craft again immediately.
                setCraftResult(null);
              }} />
          )}
          {tribulation && (
            <HeavenlyTribulationModal tribulation={tribulation}
              onClose={() => setTribulation(null)}
              onComplete={handleTribulationComplete} />
          )}
          {showCauldronPicker && (
            <CauldronPickerModal data={data} onClose={() => setShowCauldronPicker(false)} onEquipped={refresh} />
          )}
        </div>
      );
    }

    // ─── MA-32: Forge / Artifacts ────────────────────────────────────────────
    var FORGE_RESULT_VISUALS = {
      divine:  { color:"var(--realm-3)", glow:"rgba(var(--realm-3-rgb),.65)", label_key:"forge_result_divine",  icon:"💎" },
      perfect: { color:"var(--gold2)", glow:"rgba(var(--gold2-rgb),.6)", label_key:"forge_result_perfect", icon:"⚒️" },
      success: { color:"var(--jade)", glow:"rgba(var(--jade-rgb),.5)",  label_key:"forge_result_success", icon:"⚔️" },
      failure: { color:"var(--realm-0)", glow:"rgba(var(--realm-0-rgb),.4)", label_key:"forge_result_failure", icon:"💔" },
    };
    var FORGE_BULK_MAX = 50;

    // ⚒️ A FORJA EM LOTE (report do [jogador], 10/09 07:29) ─────────────────────────
    //
    //   "new ui is beautiful! But, when forging (i think also alchemy), multi
    //    items (forging 50 is what I tried), the display of results is messy.
    //    Suggest that when multi forge is done, shift the result to list or
    //    old display."
    //
    // MEDIDO a 2026-09-12 a SERVIR E OLHAR (Lei 0 passo 3), 390x844 e 1440x900,
    // com um lote de 50 encenado na forma do servidor:
    //
    //   a celula saia  63 x 312 px   e o nome partia-se a UMA LETRA POR LINHA
    //   ("Celes tial Sund ering Blad e")
    //   a lista inteira  3003 px  dentro de uma janela de  553 px  = 5,4 ecras
    //   e os botoes de reciclar — a UNICA coisa que se faz com esta lista —
    //   ficavam por baixo dos 3003.
    //
    // ⚠️ A AVARIA NAO ERA O NUMERO 50, ERA O NUMERO 5. A grelha pedia
    // `minmax(54px, 1fr)` — uma medida escrita para o QUADRADO de 54px do
    // `ArtifactCellClassic`. Desde o 牌 A CARTA a mesma celula e' uma
    // `NivraelCard` em RETRATO; a partir da 5a peca o `auto-fit` abria a 5a
    // coluna, a carta encolhia para 63px e virava uma torre. Medido: 4 pecas =
    // 80x218 e CABE no ecra sem rolar (a tela dos 4 esta' certa); 8 = 63x304.
    //
    // ⚠️ E a causa de fundo e' de Lei F-7 (UM dono): **toda grelha de cartas do
    // jogo passa pelo `CardGrid`/`InvGrid`, com min 152px — esta era a unica
    // escrita a mao**, e por isso foi a unica que nao soube da carta nova.
    //
    // A RESPOSTA tem tres formas, e quem escolhe e' a pergunta *"a peca ainda e'
    // o assunto?"*:
    //
    //   1-3   linhas ricas (como sempre) ....... cada peca E' o assunto
    //   4-9   grelha pintada, largura que se le'  a arte vale, e cabe em 3 filas
    //   10+   o assunto e' o LOTE ............... lista densa, 1 linha por peca
    //
    // A terceira e' a "list or old display" que o proprio report pediu, e e' a
    // forma da FERRAMENTA: quem forja 50 quer a contagem (ja' esta' no topo),
    // os melhores achados (a ordenacao ja' os poe a' frente) e reciclar o resto.
    //
    // ⚠️ NAO DESFAZ O 器 O ITEM VIVO. A carta pintada continua em todos os
    // sitios onde a peca e' o assunto — a mochila, o modal de detalhe, e a
    // grelha de 4 a 9 aqui. O que muda e' **cinquenta de uma vez**.
    //
    // ⚠️ TUDO ISTO VIVE NO RAMO `cartas` LIGADA — e' onde a avaria nasceu. Com a
    // flag OFF a grelha de quadrados de hoje fica byte a byte (as medidas novas
    // estao TODAS dentro do ternario: a OFF-identidade quebra-se pela ORDEM, nao
    // so' pelo valor).
    var FORGE_RESULT_CARD_MIN = 104;   // 3 colunas a 390px (a 63px nao se le')
    var FORGE_RESULT_LIST_FROM = 10;   // a partir daqui o LOTE e' o assunto
    var FORGE_RESULT_PAGE = 24;        // quantas linhas a lista densa mostra

    function forgeReason(code, extras) {
      const e = extras || {};
      const map = {
        recipe_not_found:       t("forge_err_recipe_not_found"),
        realm_too_low:          t("forge_err_realm_too_low", { n: e.required_realm ?? 0 }),
        forge_tier_too_low:     t("forge_err_forge_tier_too_low"),
        not_enough_materials:   t("forge_err_not_enough_materials"),
        artifact_not_found:     t("forge_err_artifact_not_found"),
        is_equipped:            t("forge_err_is_equipped"),
        is_locked:              t("forge_err_is_locked"),
        already_equipped:       t("forge_err_already_equipped"),
        not_equipped:           t("forge_err_not_equipped"),
        invalid_slot_type:      t("forge_err_invalid_slot"),
        no_targets:             t("forge_err_no_dismantle_targets"),
        accessory_picker_required: t("forge_err_accessory_pick"),
        engine_error:           t("forge_err_engine"),
      };
      return map[code] || code || t("forge_err_engine");
    }

    function forgeMaxBulkRecipe(recipe) {
      if (!recipe) return 0;
      const reasons = recipe.blocked_reasons || [];
      if (reasons.includes("realm_too_low") || reasons.includes("forge_tier_too_low")) return 0;
      const mb = parseInt(recipe.max_bulk, 10) || 0;
      return Math.max(0, Math.min(FORGE_BULK_MAX, mb));
    }

    function ForgeHeaderCard({ data }) {
      // Defensive guard — see AlchemyHeaderCard. Without this, a missing
      // `forge` field (e.g. transient `get_or_create_forge_skill` failure)
      // would crash CraftingTab with no visible error → black screen.
      const f = data?.forge;
      if (!f) {
        return <Card><div style={{ padding:"16px 8px", textAlign:"center", color:"var(--muted)", fontSize:11 }}>{t("forge_loading_state")}</div></Card>;
      }
      const fPct = f.at_max ? 100 : (f.xp_to_next > 0 ? Math.round((f.xp / f.xp_to_next) * 100) : 0);
      const sectBonus = data.sect_bonus || {};
      return (
        <Card style={{ padding:"12px 14px 10px", marginBottom:10 }}>
          <div style={{ display:"flex", justifyContent:"space-between", alignItems:"flex-start", gap:10, marginBottom:8 }}>
            <div style={{ display:"flex", gap:10, alignItems:"center", minWidth:0 }}>
              <div style={{ fontSize:24,
                filter:"drop-shadow(0 0 10px rgba(var(--gold2-rgb),.55))",
              }}>{f.tier_emoji}</div>
              <div style={{ minWidth:0 }}>
                <div style={{ fontFamily:"'Cinzel',serif", fontSize:13, color:"var(--gold2)", fontWeight:700 }}>
                  {f.tier_name} <span style={{ color:"var(--muted)", fontWeight:400 }}>· T{f.tier}/{f.max_tier}</span>
                </div>
                <div style={{ fontSize:10, color:"var(--muted)" }}>
                  {f.at_max ? t("forge_xp_max") : `${fmtNum(f.xp)} / ${fmtNum(f.xp_to_next)} XP`}
                </div>
              </div>
            </div>
            {!f.at_max && (
              <div style={{ minWidth:80, textAlign:"right" }}>
                <div style={{ height:5, borderRadius:3, background:"rgba(0,0,0,.5)", overflow:"hidden" }}>
                  <div style={{ width:`${fPct}%`, height:"100%",
                    background:"linear-gradient(90deg, var(--gold), var(--gold3))",
                    transition:"width .3s ease" }} />
                </div>
              </div>
            )}
          </div>

          {/* Stats strip */}
          <div style={{ display:"grid", gridTemplateColumns:"repeat(3,1fr)", gap:6, marginBottom:8 }}>
            <div style={{ textAlign:"center", padding:"6px 4px", background:"rgba(0,0,0,.25)",
                          borderRadius:6, border:"1px solid rgba(var(--gold2-rgb),.12)" }}>
              <div style={{ fontSize:9, color:"var(--muted)", letterSpacing:.5, textTransform:"uppercase" }}>
                {t("forge_total_forges")}
              </div>
              <div style={{ fontFamily:"'Cinzel',serif", fontSize:14, fontWeight:700, color:"var(--gold2)" }}>
                {fmtNum(f.total_forges)}
              </div>
            </div>
            <div style={{ textAlign:"center", padding:"6px 4px", background:"rgba(var(--realm-3-rgb),.05)",
                          borderRadius:6, border:"1px solid rgba(var(--realm-3-rgb),.18)" }}>
              <div style={{ fontSize:9, color:"var(--muted)", letterSpacing:.5, textTransform:"uppercase" }}>
                {t("forge_divine_forges")}
              </div>
              <div style={{ fontFamily:"'Cinzel',serif", fontSize:14, fontWeight:700, color:"#c084fc" }}>
                {fmtNum(f.divine_forges)}
              </div>
            </div>
            <div style={{ textAlign:"center", padding:"6px 4px", background:"rgba(var(--jade-rgb),.05)",
                          borderRadius:6, border:"1px solid rgba(var(--jade-rgb),.18)" }}>
              <div style={{ fontSize:9, color:"var(--muted)", letterSpacing:.5, textTransform:"uppercase" }}>
                {t("forge_quality_bonus")}
              </div>
              <div style={{ fontFamily:"'Cinzel',serif", fontSize:14, fontWeight:700, color:"var(--jade)" }}>
                +{f.quality_bonus}
              </div>
            </div>
          </div>

          {(sectBonus.forge_lvl > 0 || (data.soul_fire_tier || 0) > 0) && (
            <div style={{ display:"flex", flexWrap:"wrap", gap:6, marginBottom:8 }}>
              {sectBonus.forge_lvl > 0 && (
                <Badge>🏯 {t("forge_sect_bonus", { n: sectBonus.forge_lvl })}</Badge>
              )}
              {(data.soul_fire_tier || 0) > 0 && (
                <Badge>🔥 {t("forge_soul_fire_bonus", { n: data.soul_fire_tier })}</Badge>
              )}
              {f.ore_discount > 0 && (
                <Badge>⛏️ {t("forge_ore_discount", { n: Math.round(f.ore_discount * 100) })}</Badge>
              )}
              {/* MV-7 — ⚒️ o desconto REAL do Ferreiro (já refletido nos
                  custos exibidos; key ausente sem ofício/flag OFF). */}
              {data.prof_ore_discount > 0 && (
                <Badge>⚒️ {t("prf_mini_forge_discount", { n: Math.round(data.prof_ore_discount * 100) })}</Badge>
              )}
            </div>
          )}

          {/* Bulk Dismantle moved to Inventory tab (owner request 2026-05-06):
              "esse bunk deveria ser no inventario. a forja e alquimia so pra
              forjar mesmo". The hint here is purely informational. */}
          <div style={{
            width:"100%", padding:"6px 10px", borderRadius:8,
            background:"rgba(0,0,0,.2)", border:"1px dashed rgba(var(--gold2-rgb),.18)",
            color:"var(--muted2)", fontSize:10, fontFamily:"'Cinzel',serif",
            letterSpacing:.4, textAlign:"center",
          }}>
            ♻️ {t("forge_bulk_dismantle_moved_hint")}
          </div>
        </Card>
      );
    }

    function ForgeOreStrip({ ores }) {
      // Compact ore inventory chip strip — read-only summary so the player
      // sees what's available before opening recipe details.
      if (!ores || ores.length === 0) {
        return (
          <Card style={{ padding:"10px 12px", marginBottom:10 }}>
            <div style={{ fontSize:11, color:"var(--muted)", textAlign:"center" }}>
              {t("forge_no_ores")}
            </div>
          </Card>
        );
      }
      return (
        <Card style={{ padding:"8px 10px", marginBottom:10 }}>
          <div style={{ fontSize:9, color:"var(--muted)", letterSpacing:.6, textTransform:"uppercase",
                        marginBottom:6, fontFamily:"'Cinzel',serif" }}>
            {t("forge_ores_owned")}
          </div>
          <div style={{ display:"flex", flexWrap:"wrap", gap:5 }}>
            {ores.map(o => (
              <span key={o.id} style={{
                fontSize:11, padding:"3px 7px", borderRadius:99,
                background:"rgba(0,0,0,.35)", border:"1px solid rgba(var(--gold2-rgb),.2)",
                display:"inline-flex", alignItems:"center", gap:4,
              }}>
                <span style={{ fontSize:13 }}>{o.emoji}</span>
                <span style={{ color:"var(--text)", fontWeight:600 }}>{o.qty}</span>
                <span style={{ color:"var(--muted2)", fontSize:9 }}>T{o.tier}</span>
              </span>
            ))}
          </div>
        </Card>
      );
    }

    function ForgeRecipeCard({ recipe, onClick }) {
      const m = recipe.mastery || {};
      const stars = "⭐".repeat(Math.max(0, (m.level || 1) - 1));
      const canCraft = recipe.can_craft;
      const reasonKey = (recipe.blocked_reasons || [])[0];
      const v = GRADE_VISUALS[recipe.artifact_grade] || GRADE_VISUALS[0];
      return (
        <button onClick={() => { haptic("select"); onClick(recipe); }}
                style={{
                  width:"100%", textAlign:"left", cursor:"pointer",
                  background: canCraft
                    ? "linear-gradient(180deg, rgba(20,30,55,.85), rgba(var(--card-rgb),.95))"
                    : "linear-gradient(180deg, rgba(var(--surface-rgb),.55), rgba(13,16,28,.7))",
                  border:`1px solid ${canCraft ? v.color + "44" : "rgba(255,255,255,.06)"}`,
                  borderRadius:10, padding:"10px 12px",
                  opacity: canCraft ? 1 : .72,
                  display:"flex", flexDirection:"column", gap:6,
                  position:"relative", overflow:"hidden",
                  boxShadow: canCraft ? `0 0 14px ${v.glow}` : "none",
                }}>
          <div style={{ display:"flex", alignItems:"center", gap:10, justifyContent:"space-between" }}>
            <div style={{ display:"flex", alignItems:"center", gap:8, minWidth:0 }}>
              <span style={{ fontSize:22, filter:`drop-shadow(0 0 6px ${v.glow})` }}>{recipe.artifact_emoji}</span>
              <div style={{ minWidth:0 }}>
                <div style={{ fontFamily:"'Cinzel',serif", fontSize:13, color:"var(--gold2)", fontWeight:600,
                              overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap" }}>
                  {recipe.artifact_name}
                </div>
                <div style={{ fontSize:10, color:"var(--muted)", marginTop:2,
                              display:"flex", alignItems:"center", gap:5 }}>
                  <span style={{
                    fontFamily:"'Cinzel',serif", padding:"1px 5px", borderRadius:99,
                    fontSize:9, color: v.color, border:`1px solid ${cssHex(v.color)}55`,
                    letterSpacing:.5,
                  }}>G{recipe.artifact_grade}</span>
                  <span>{t(`slot_${recipe.artifact_type}`)}</span>
                  <span>· {t("forge_min_realm_short", { n: recipe.required_realm })}</span>
                </div>
              </div>
            </div>
            <div style={{ textAlign:"right", whiteSpace:"nowrap" }}>
              <div style={{ fontSize:13, fontWeight:700, color: canCraft ? "var(--jade)" : "var(--muted2)" }}>
                {recipe.success_chance}%
              </div>
              {stars && <div style={{ fontSize:9 }}>{stars}</div>}
            </div>
          </div>

          {/* Material chips */}
          <div style={{ display:"flex", flexWrap:"wrap", gap:5 }}>
            {(recipe.materials || []).map(mat => (
              <span key={mat.ore_id} style={{
                fontSize:10, padding:"2px 6px", borderRadius:10,
                background: mat.ok ? "rgba(var(--jade-rgb),.12)" : "rgba(var(--red-rgb),.12)",
                border: `1px solid ${mat.ok ? "rgba(var(--jade-rgb),.3)" : "rgba(var(--red-rgb),.3)"}`,
                color: mat.ok ? "var(--jade)" : "var(--red)",
              }}>
                {mat.emoji} ×{mat.required}
                <span style={{ color:"var(--muted)", marginLeft:3, fontSize:9 }}>({mat.owned})</span>
              </span>
            ))}
            {recipe.max_bulk > 1 && recipe.can_craft && (
              <span style={{
                fontSize:10, padding:"2px 6px", borderRadius:10,
                background:"rgba(var(--gold2-rgb),.12)", border:"1px solid rgba(var(--gold2-rgb),.3)",
                color:"var(--gold2)", fontFamily:"'Cinzel',serif",
              }}>
                ⚒️ ×{Math.min(recipe.max_bulk, FORGE_BULK_MAX)}
              </span>
            )}
          </div>

          {!canCraft && reasonKey && (
            <div style={{ fontSize:10, color:"var(--warn)", marginTop:2 }}>
              {forgeReason(reasonKey, { required_realm: recipe.required_realm })}
            </div>
          )}
        </button>
      );
    }

    function ForgeRecipeDetailModal({ recipe, onClose, onCraft }) {
      const [busy, setBusy] = useState(false);
      const [err, setErr] = useState(null);
      const [count, setCount] = useState(1);
      // Rules of Hooks — see RecipeDetailModal.
      const maxBulk = recipe ? forgeMaxBulkRecipe(recipe) : 0;
      useEffect(() => {
        if (!recipe) return;
        if (count > maxBulk) setCount(Math.max(1, maxBulk));
      }, [maxBulk, recipe]);
      if (!recipe) return null;

      const v = GRADE_VISUALS[recipe.artifact_grade] || GRADE_VISUALS[0];
      const m = recipe.mastery || {};
      const masteryProgress = m.at_max ? 100 :
        (m.next_forges > 0 ? Math.round((m.forges_count / m.next_forges) * 100) : 0);

      async function callCraft() {
        if (busy || !recipe.can_craft) return;
        haptic("warning");
        setBusy(true); setErr(null);
        try {
          const body = count > 1
            ? { recipe_id: recipe.id, count }
            : { recipe_id: recipe.id };
          const res = await api("forge/craft", body);
          if (!res.ok) {
            haptic("error");
            setErr(forgeReason(res.reason, { required_realm: recipe.required_realm }));
            setBusy(false);
            return;
          }
          // Best-of headline drives the haptic
          const r = res.results || {};
          const headline = r.divine ? "success" : r.perfect ? "success" : r.success ? "success" : "warning";
          haptic(headline);
          setBusy(false);
          onCraft && onCraft(res);
        } catch (e) {
          haptic("error");
          setErr(t("forge_err_engine"));
          setBusy(false);
        }
      }

      const titleNode = (
        <div style={{ display:"flex", gap:10, alignItems:"center", minWidth:0 }}>
          <span style={{ fontSize:24, filter:`drop-shadow(0 0 8px ${v.glow})` }}>
            {recipe.artifact_emoji}
          </span>
          <div style={{ minWidth:0 }}>
            <div style={{ fontFamily:"'Cinzel',serif", fontWeight:700, fontSize:14.5, color:"var(--gold2)", lineHeight:1.2,
                          overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap" }}>
              {recipe.artifact_name}
            </div>
            <div style={{ fontSize:10.5, color:"var(--muted)", lineHeight:1.3,
                          overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap" }}>
              {recipe.artifact_description}
            </div>
          </div>
        </div>
      );
      const footer = (
        <div>
          <ActionBtn variant="primary" disabled={busy || !recipe.can_craft} onClick={callCraft} style={{ width:"100%" }}>
            {busy ? <DotSpinner /> : (count > 1
              ? `⚒️ ${t("forge_craft_btn_bulk", { n: count })}`
              : `⚒️ ${t("forge_craft_btn")}`)}
          </ActionBtn>
          {!recipe.can_craft && (recipe.blocked_reasons || []).length > 0 && (
            <div style={{ fontSize:10.5, color:"var(--warn)", marginTop:6, textAlign:"center" }}>
              {recipe.blocked_reasons.map(r => forgeReason(r, { required_realm: recipe.required_realm })).join(" · ")}
            </div>
          )}
        </div>
      );

      return (
        <Modal onClose={onClose} title={titleNode}
               accent={`${cssHex(v.color)}66`}
               maxWidth={480} zIndex={60}
               footer={footer}>
            <div style={{ display:"flex", flexWrap:"wrap", gap:6, marginBottom:10 }}>
              <span style={{
                fontFamily:"'Cinzel',serif", padding:"2px 8px", borderRadius:99,
                fontSize:10, color: v.color, border:`1px solid ${cssHex(v.color)}55`, letterSpacing:1,
              }}>G{recipe.artifact_grade} · {t("forge_grade_" + recipe.artifact_grade)}</span>
              <Badge>{t(`slot_${recipe.artifact_type}`)}</Badge>
              <Badge>T{recipe.tier}</Badge>
              <Badge>{t("forge_min_realm_short", { n: recipe.required_realm })}</Badge>
            </div>

            {/* Base stats preview */}
            {recipe.artifact_base_stats && Object.keys(recipe.artifact_base_stats).length > 0 && (
              <Card style={{ padding:"10px 12px", marginBottom:10 }}>
                <CardTitle left={t("forge_base_stats")} />
                <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:5 }}>
                  {Object.entries(recipe.artifact_base_stats).map(([k, val]) => (
                    <div key={k} style={{
                      display:"flex", justifyContent:"space-between",
                      padding:"4px 8px", background:"rgba(0,0,0,.25)",
                      border:"1px solid rgba(var(--glow-rgb),.18)", borderRadius:6, fontSize:11,
                    }}>
                      {/* o MESMO defeito do `DetailModal`, na mesma forma de
                          grelha — contado e corrigido no mesmo lote (Lei F-7). */}
                      <span style={{ color:"var(--muted)", minWidth:0,
                                     overflow:"hidden", textOverflow:"ellipsis",
                                     whiteSpace:"nowrap" }}>{humanizeStat(k)}</span>
                      <b style={{ color:"var(--gold2)", flexShrink:0,
                                  whiteSpace:"nowrap" }}>+{val}</b>
                    </div>
                  ))}
                </div>
                <div style={{ fontSize:10, color:"var(--muted2)", marginTop:6 }}>
                  ✦ {t("forge_perfect_mult")} ×1.5 · ✨ {t("forge_divine_mult")} ×2.0
                </div>
              </Card>
            )}

            {/* Success chance */}
            <Card style={{ padding:"10px 12px", marginBottom:10 }}>
              <CardTitle left={t("forge_success_chance")} right={`${recipe.success_chance}%`} />
              <div style={{ height:8, borderRadius:4, background:"rgba(0,0,0,.5)", overflow:"hidden",
                            border:"1px solid rgba(var(--jade-rgb),.18)" }}>
                <div style={{ width:`${recipe.success_chance}%`, height:"100%",
                  background:"linear-gradient(90deg, #15803d, var(--jade), #86efac)" }} />
              </div>
              <div style={{ fontSize:10, color:"var(--muted)", marginTop:6, lineHeight:1.4 }}>
                {t("forge_chance_split")}
              </div>
            </Card>

            {/* Materials */}
            <Card style={{ padding:"10px 12px", marginBottom:10 }}>
              <CardTitle left={t("forge_materials")} />
              <div style={{ display:"flex", flexDirection:"column", gap:5 }}>
                {(recipe.materials || []).map(mat => (
                  <div key={mat.ore_id} style={{
                    display:"flex", alignItems:"center", gap:8,
                    padding:"6px 8px", borderRadius:6,
                    background: mat.ok ? "rgba(var(--jade-rgb),.06)" : "rgba(var(--red-rgb),.06)",
                    border:`1px solid ${mat.ok ? "rgba(var(--jade-rgb),.18)" : "rgba(var(--red-rgb),.18)"}`,
                  }}>
                    <span style={{ fontSize:18 }}>{mat.emoji}</span>
                    <span style={{ flex:1, minWidth:0, fontSize:12, color:"var(--text)" }}>
                      {mat.name} <span style={{ color:"var(--muted2)", fontSize:9.5 }}>T{mat.tier}</span>
                      {/* MV-9.5 — idem alquimia: o minério em falta diz de que
                          continente vem (linha server-resolved; key condicional). */}
                      {mat.origin && mat.origin.line && (
                        <span style={{ display:"block", fontSize:10.5, marginTop:2, lineHeight:1.4,
                                       color: mat.origin.here ? "var(--gold3)" : "var(--muted)" }}>
                          {mat.origin.line}
                        </span>
                      )}
                    </span>
                    <span style={{ fontSize:11, color:"var(--muted)" }}>
                      <b style={{ color: mat.ok ? "var(--jade)" : "var(--red)" }}>{mat.owned}</b>
                      <span> / {mat.required}</span>
                    </span>
                    <span style={{ fontSize:14 }}>{mat.ok ? "✅" : "❌"}</span>
                  </div>
                ))}
              </div>
            </Card>

            {/* Mastery */}
            <Card style={{ padding:"10px 12px", marginBottom:10 }}>
              <CardTitle left={`📖 ${m.name}`}
                         right={m.at_max ? t("forge_mastery_max")
                                : t("forge_mastery_progress", { n: m.forges_count, total: m.next_forges })} />
              {!m.at_max && (
                <div style={{ height:5, borderRadius:3, background:"rgba(0,0,0,.5)", overflow:"hidden" }}>
                  <div style={{ width:`${masteryProgress}%`, height:"100%",
                    background:"linear-gradient(90deg, #6b21a8, var(--realm-3), #d8b4fe)",
                    transition:"width .3s" }} />
                </div>
              )}
              {m.bonus > 0 && (
                <div style={{ fontSize:10, color:"var(--jade)", marginTop:5 }}>
                  +{m.bonus}% {t("forge_mastery_bonus")}
                </div>
              )}
            </Card>

            {/* Bulk count picker (owner request: "MAXIMO INGREDIENTES COMO UMA ESCOLHA") */}
            {recipe.can_craft && maxBulk > 1 && (
              <Card style={{ padding:"10px 12px", marginBottom:10, borderColor:"rgba(var(--gold2-rgb),.3)" }}>
                <CardTitle
                  left={`🔄 ${t("forge_bulk_label")}`}
                  right={<span style={{ color: count >= maxBulk ? "var(--gold3)" : "var(--gold2)", fontWeight:700 }}>
                    {count}<span style={{ color:"var(--muted)", fontWeight:400 }}> / {maxBulk}</span>
                  </span>}
                />
                <BulkSlider count={count} max={maxBulk} onChange={setCount} color="var(--gold2)" />
                {/* TAPETE QoL §5 item 2 ([jogador]: "caixa de texto para colocar
                    o valor desejado" em vez de só MAX) — clamped [1,maxBulk]. */}
                <div style={{ display:"flex", gap:6, alignItems:"center", marginTop:8 }}>
                  <span style={{ fontSize:10, color:"var(--muted)", flexShrink:0 }}>
                    {t("forge_bulk_custom_label")}
                  </span>
                  <input type="number" inputMode="numeric" min={1} max={maxBulk}
                         value={count}
                         onChange={e => {
                           const raw = (e.target.value || "").replace(/[^0-9]/g, "");
                           setCount(raw === "" ? 1 : Math.max(1, Math.min(maxBulk, parseInt(raw, 10) || 1)));
                         }}
                         style={{ flex:1, minWidth:0, padding:"7px 10px", borderRadius:8,
                                  background:"rgba(0,0,0,.3)", border:"1px solid rgba(var(--gold2-rgb),.22)",
                                  color:"var(--text)", fontSize:12 }} />
                </div>
                <div style={{ fontSize:10, color:"var(--muted)", marginTop:6, lineHeight:1.4 }}>
                  {t("forge_bulk_hint")}
                </div>
              </Card>
            )}

            {recipe.xp_capped && (
              <div style={{ fontSize:10.5, color:"var(--warn)", marginBottom:10, textAlign:"center" }}>
                ⚠️ {t("forge_xp_capped")}
              </div>
            )}

            {err && <ErrBanner msg={err} />}
        </Modal>
      );
    }

    function ForgeResultModal({ result, onClose, onPlayerRefresh }) {
      // Owner request 2026-05-06 (round 3): "depois de forjar muitos items
      // que possa clicar neles para ver as info". Selected artifact opens
      // the same DetailModal used in Inventory — consistent UX, prepares
      // for equip/lock/dismantle actions from inside the result.
      const [pickedArt, setPickedArt] = useState(null);
      // v14.7 Item 2 (owner P1 2026-05-08): "Estaria bem tambem se a
      // galera que forjou varios items decidir reciclar todos ou só
      // selecionados ja direto ai". Per-artifact selection + 2 recycle
      // CTAs (selected / all). State scoped to this modal — when the
      // user closes and crafts again, fresh state per craft.
      const [selected, setSelected] = useState(() => new Set());
      const [recycling, setRecycling] = useState(false);
      const [recycleSummary, setRecycleSummary] = useState(null);
      // Local mutable copy of the artifacts grid so we can shrink it
      // after a recycle without parent rerendering the modal.
      const [arts, setArts] = useState(() => result?.artifacts_created || []);
      // ⚒️ A FORJA EM LOTE — a lista densa pagina como o Anel Espacial pagina
      // (`stashLimit`): a casa ja' tem este idioma, e uma 2a maneira de dizer
      // "mostrar mais" seria variedade onde se pedia profundidade (Lei §3).
      const [listLimit, setListLimit] = useState(FORGE_RESULT_PAGE);
      // Reset the local state whenever a new craft result arrives.
      useEffect(() => {
        setSelected(new Set());
        setRecycleSummary(null);
        setArts(result?.artifacts_created || []);
        setListLimit(FORGE_RESULT_PAGE);
      }, [result]);
      // useState above the early return to satisfy Rules of Hooks. The
      // result-modal flow needs `result` to render but the hook order
      // must be deterministic across renders.
      if (!result) return null;
      const r = result.results || {};
      const totalGood = (r.success || 0) + (r.perfect || 0) + (r.divine || 0);
      // Headline = best quality reached. Bulk single-craft both render via this.
      const headlineKey = r.divine > 0 ? "divine"
        : r.perfect > 0 ? "perfect"
        : r.success > 0 ? "success"
        : "failure";
      const visual = FORGE_RESULT_VISUALS[headlineKey];
      const isWin = headlineKey !== "failure";
      const isBulk = !!result.bulk;

      // ⚒️ o ramo da avaria: a carta em retrato so' existe com `cartas` ON.
      // Com a flag OFF o `ArtifactCell` devolve o quadrado de 54px de sempre, e
      // a grelha de hoje esta' certa para ele — logo nao se toca nela.
      const cardsOn = typeof featureEnabled === "function" && featureEnabled("cartas");

      const recyclable = arts.filter(a => !a.is_equipped && !a.locked);
      const recyclableIds = recyclable.map(a => a.id);
      const selectedIds = recyclable.filter(a => selected.has(a.id)).map(a => a.id);

      function toggleSelect(id) {
        setSelected(prev => {
          const next = new Set(prev);
          if (next.has(id)) next.delete(id); else next.add(id);
          return next;
        });
        haptic("select");
      }

      async function doRecycle(ids) {
        if (recycling || ids.length === 0) return;
        setRecycling(true);
        haptic("warning");
        try {
          const res = await api("forge/dismantle_bulk", { artifact_ids: ids });
          if (!res.ok) {
            haptic("error");
            showToast(forgeReason(res.reason) || res.reason, "err");
            setRecycling(false);
            return;
          }
          haptic("success");
          const recycledSet = new Set(res.artifact_ids || []);
          setArts(prev => prev.filter(a => !recycledSet.has(a.id)));
          setSelected(new Set());
          // U2 (v16.6): recycle now also refunds 25% of crafting materials.
          const mats = res.materials_gained || [];
          setRecycleSummary({
            count: res.count || 0,
            stones: res.stones_gained || 0,
            materials: mats,
          });
          const matStr = mats.map(m => `${m.emoji} ${m.name} ×${m.qty}`).join(", ");
          showToast(matStr
            ? t("forge_recycled_msg_mats", { n: res.count, stones: fmtNum(res.stones_gained), mats: matStr })
            : t("forge_recycled_msg", { n: res.count, stones: fmtNum(res.stones_gained) }));
          onPlayerRefresh && onPlayerRefresh();
        } catch (e) {
          haptic("error");
          showToast(e.message || t("forge_err_engine"), "err");
        } finally {
          setRecycling(false);
        }
      }

      // U1 (v16.6): lock/unlock a forged item right here, so a player can protect
      // a Divine pull before tapping "Recycle All" (locked items drop out of
      // `recyclable`). Reuses the api_artifact_lock endpoint.
      async function toggleLock(a) {
        try {
          const res = await api("artifact/lock", { artifact_id: a.id, locked: !a.locked });
          if (res && res.ok !== false) {
            const nowLocked = (res.locked != null) ? res.locked : !a.locked;
            setArts(prev => prev.map(x => x.id === a.id ? { ...x, locked: nowLocked } : x));
            haptic("select");
            showToast(t(nowLocked ? "inv_locked_toast" : "inv_unlocked_toast"));
          }
        } catch (e) {
          haptic("error");
          showToast(e.message || t("forge_err_engine"), "err");
        }
      }

      // U1 (v16.6): show the best pulls first (Divine → Perfect → Common), so a
      // divine result never hides at the bottom of a 50-item bulk.
      const sortedArts = [...arts].sort((a, b) => ((b.grade ?? 0) - (a.grade ?? 0)) || ((b.id || 0) - (a.id || 0)));

      const titleStr = isBulk ? `⚒️ ${t("bulk_crafted", { n: result.crafts_done })}` : `⚒️ ${t(visual.label_key)}`;
      // TAPETE QoL §5 item 2 ([jogador]: "o botão 'forjar novamente' faz a mesma
      // função do 'voltar'"): the craft-again button only dismissed this
      // overlay — identical to Close, since the recipe modal stays open
      // underneath. Removed; single Close. (Chat keeps its two buttons —
      // there they navigate to DIFFERENT screens.)
      const footer = (
        <ActionBtn variant="ghost" onClick={onClose} style={{ width:"100%" }}>
          {t("alch_close")}
        </ActionBtn>
      );

      return (
        // HF v14.10 (2026-05-21): `compact` REMOVED. Owner reported the bulk
        // forge result modal collapsed body (29 cards rendered as zero
        // visible — only header + recycle buttons + footer showed). Cause:
        // `compact={true}` sets card height:auto. iOS WebKit then computes
        // `flex:1 1 0` on the body relative to intrinsic content size; when
        // total content (29 ArtifactCells × ~58px ≈ 1700px) exceeds the
        // bounded maxHeight, the flex container collapses instead of
        // scrolling. This was already documented in CLAUDE.md ("NÃO usar
        // compact={true} para modais com conteúdo dinâmico — lição round 4")
        // but `compact` was added in v14.7 (P1 owner round 2026-05-08) to
        // shrink the empty-bottom area on single crafts. Trade-off accepted:
        // single crafts now render in the standard premium modal "screen"
        // size (some empty space at the bottom) — better than broken bulk.
        <Modal onClose={onClose} title={titleStr}
               accent={visual.color}
               maxWidth={400} zIndex={70}
               cardStyle={{ boxShadow:`0 0 50px ${visual.glow}` }}
               animation="forge-pop 480ms cubic-bezier(.2,1.4,.4,1)"
               footer={footer}>
            <div style={{ textAlign:"center", marginBottom:8 }}>
              <div style={{
                fontSize: r.divine > 0 ? 44 : 36, marginBottom:2,
                animation: isWin
                  ? "forge-anvil-strike 700ms cubic-bezier(.4,0,.2,1)"
                  : "forge-failure-shake 500ms",
                filter:`drop-shadow(0 0 14px ${visual.glow})`,
              }}>{visual.icon}</div>
              {isBulk && result.crafts_done < result.crafts_requested && (
                <div style={{ fontSize:11, color:"var(--muted)", marginTop:2 }}>
                  {t("forge_bulk_partial", { done: result.crafts_done, asked: result.crafts_requested })}
                </div>
              )}
              {result.early_stop_reason && (
                <div style={{ fontSize:10.5, color:"var(--warn)", marginTop:3 }}>
                  ⚠️ {forgeReason(result.early_stop_reason)}
                </div>
              )}
            </div>

            {/* Per-quality breakdown chips — tighter padding */}
            {(isBulk || totalGood > 0) && (
              <div style={{ display:"grid", gridTemplateColumns:"repeat(auto-fit, minmax(58px, 1fr))",
                            gap:5, marginBottom:8 }}>
                {["divine", "perfect", "success", "failure"].map(k => {
                  const n = r[k] || 0;
                  if (n === 0) return null;
                  const v = FORGE_RESULT_VISUALS[k];
                  return (
                    <div key={k} style={{
                      background:`linear-gradient(180deg, ${cssHex(v.color)}22, rgba(0,0,0,.4))`,
                      border:`1px solid ${cssHex(v.color)}55`, borderRadius:7,
                      padding:"5px 4px", textAlign:"center",
                    }}>
                      <div style={{ fontSize:15 }}>{v.icon}</div>
                      <div style={{ fontFamily:"'Cinzel',serif", fontSize:13, fontWeight:700, color: v.color }}>×{n}</div>
                    </div>
                  );
                })}
              </div>
            )}

            {result.spirit_awakened && (
              <div style={{
                background:"linear-gradient(135deg, rgba(var(--gold2-rgb),.18), rgba(var(--realm-3-rgb),.18))",
                border:"1px solid rgba(var(--gold2-rgb),.45)", borderRadius:8,
                padding:"6px 10px", marginBottom:8, textAlign:"center",
                animation:"forge-spirit-shimmer 1.2s ease-in-out infinite alternate",
              }}>
                <div style={{ fontSize:10, color:"var(--gold2)", letterSpacing:1, textTransform:"uppercase" }}>
                  ✦ {t("forge_spirit_awakened")} ✦
                </div>
                <div style={{ fontSize:11, color:"var(--gold3)", marginTop:2 }}>
                  {t("forge_spirit_msg")}
                </div>
              </div>
            )}

            {arts.length > 0 && (
              <div style={{ marginBottom:8 }}>
                <div style={{
                  display:"flex", alignItems:"center", justifyContent:"space-between",
                  marginBottom:4,
                }}>
                  <div style={{ fontSize:9, color:"var(--muted)", letterSpacing:.5, textTransform:"uppercase" }}>
                    {t("forge_artifacts_added")} ({arts.length})
                  </div>
                  {recyclable.length > 1 && (
                    <button
                      onClick={() => {
                        haptic("select");
                        if (selectedIds.length === recyclable.length) setSelected(new Set());
                        else setSelected(new Set(recyclableIds));
                      }}
                      style={{
                        background:"rgba(0,0,0,.4)", color:"var(--gold2)",
                        border:"1px solid rgba(var(--gold2-rgb),.3)", borderRadius:5,
                        padding:"2px 7px", fontSize:9.5, letterSpacing:.4,
                        cursor:"pointer", fontFamily:"'Cinzel',serif",
                      }}>
                      {selectedIds.length === recyclable.length
                        ? t("forge_select_none") : t("forge_select_all")}
                    </button>
                  )}
                </div>
                {/* v14.13c — Owner P1 2026-05-08: "Olha o tamanho do modal
                    quando forja. Muito feio". v14.7 introduziu `compact` mas
                    foi revertido em HF v14.10 (iOS WebKit collapse com bulk
                    de 29 cards). Solução nova: small-N (1-3) renderiza como
                    rich row cards (icon grande + name + grade label + top-3
                    stats), preenchendo verticalmente o modal naturalmente.
                    Bulk ≥4 mantém o slot grid para legibilidade. Tap qualquer
                    card abre DetailModal igual ao Inventory. */}
                {arts.length <= 3 ? (
                  <div style={{ display:"flex", flexDirection:"column", gap:7 }}>
                    {sortedArts.map(a => {
                      const isSel = selected.has(a.id);
                      const canSel = !a.is_equipped && !a.locked;
                      const v = GRADE_VISUALS[a.grade] || GRADE_VISUALS[0];
                      const sk = slotForArtifact(a);
                      const icon = slotIco(sk, a.emoji, 30);
                      const iconIsMark = markOn(SLOT_MARKS[sk]);
                      const stats = a.stats || {};
                      const topStats = Object.entries(stats).slice(0, 3);
                      return (
                        <div key={a.id}
                             onClick={() => { haptic("light"); setPickedArt(a); }}
                             style={{
                               display:"flex", alignItems:"center", gap:10,
                               padding:"9px 10px", borderRadius:9,
                               background: v.bg,
                               border:`1px solid ${v.color}`,
                               boxShadow:`0 0 10px ${v.glow}${v.shine ? `, ${v.shine}` : ""}`,
                               cursor:"pointer", position:"relative",
                             }}>
                          {itemVivoOn() ? (
                            <PieceIcon kind="artifact" name={a.name} artKey={a.art_key} emoji={a.emoji}
                                       size={54} accent={v.color} radius={8}
                                       style={{ border:`1px solid ${cssHex(v.color)}55` }} />
                          ) : (
                          <div style={{
                            width:54, height:54, flexShrink:0, borderRadius:8,
                            display:"grid", placeItems:"center",
                            background:"rgba(0,0,0,.35)",
                            border:`1px solid ${cssHex(v.color)}55`,
                          }}>
                            <span style={{ fontSize:30, filter:`drop-shadow(0 0 8px ${v.glow})`,
                                           ...(iconIsMark ? { display:"grid", placeItems:"center", color:cssHex(v.color) } : {}) }}>{icon}</span>
                          </div>
                          )}
                          <div style={{ flex:1, minWidth:0 }}>
                            <div style={{ display:"flex", alignItems:"center", gap:6, marginBottom:3 }}>
                              <span style={{
                                fontFamily:"'Cinzel',serif", fontSize:9.5, fontWeight:700,
                                color: v.color, letterSpacing:.4,
                                padding:"1px 5px", borderRadius:3,
                                background:"rgba(0,0,0,.4)",
                                border:`1px solid ${cssHex(v.color)}55`,
                                textShadow:`0 0 6px ${v.glow}`,
                              }}>G{a.grade}{a.grade_name ? ` · ${nomeDoGrau(a.grade, a.grade_name)}` : ""}</span>
                              <div style={{
                                fontFamily:"'Cinzel',serif", fontSize:12.5, fontWeight:700,
                                color:"var(--gold2)", letterSpacing:.3,
                                whiteSpace:"nowrap", overflow:"hidden", textOverflow:"ellipsis",
                                flex:1, minWidth:0,
                              }}>{a.name}</div>
                              {a.has_spirit && (
                                <span style={{ fontSize:12, color:"var(--gold3)",
                                               filter:"drop-shadow(0 0 6px rgba(var(--gold2-rgb),.6))" }}>✧</span>
                              )}
                            </div>
                            {topStats.length > 0 && (
                              <div style={{ display:"flex", flexWrap:"wrap", gap:4 }}>
                                {topStats.map(([k, val]) => (
                                  <span key={k} style={{
                                    fontSize:9.5, color:"var(--muted)",
                                    padding:"1px 6px", borderRadius:4,
                                    background:"rgba(0,0,0,.35)",
                                    border:"1px solid rgba(var(--muted-rgb),.3)",
                                  }}>
                                    <span style={{ color:"var(--jade)" }}>+{fmtNum(val)}</span>
                                    <span style={{ marginLeft:3 }}>{humanizeStat(k)}</span>
                                  </span>
                                ))}
                              </div>
                            )}
                          </div>
                          {/* U1 (v16.6): lock toggle — protect a pull before Recycle All */}
                          {!a.is_equipped && (
                            <button
                              onClick={(e) => { e.stopPropagation(); toggleLock(a); }}
                              aria-label={t(a.locked ? "inv_unlock_btn" : "inv_lock_btn")}
                              style={{
                                flexShrink:0,
                                width:26, height:26, borderRadius:5,
                                background:"rgba(0,0,0,.55)",
                                border:`1px solid ${a.locked ? "var(--gold2)" : "rgba(var(--gold2-rgb),.35)"}`,
                                color: a.locked ? "var(--gold2)" : "var(--muted)", cursor:"pointer",
                                fontSize:12, lineHeight:1, padding:0,
                                display:"grid", placeItems:"center",
                              }}>
                              {a.locked ? "🔒" : "🔓"}
                            </button>
                          )}
                          {canSel && (
                            <button
                              onClick={(e) => { e.stopPropagation(); toggleSelect(a.id); }}
                              aria-label={t("forge_recycle_toggle")}
                              style={{
                                flexShrink:0,
                                width:26, height:26, borderRadius:5,
                                background: isSel ? "var(--red)" : "rgba(0,0,0,.55)",
                                border: isSel ? "1px solid var(--red)" : "1px solid rgba(var(--gold2-rgb),.45)",
                                color:"#fff", cursor:"pointer",
                                fontSize:13, lineHeight:1, padding:0,
                                display:"grid", placeItems:"center",
                                fontWeight:700,
                                boxShadow: isSel ? "0 0 8px rgba(var(--red-rgb),.6)" : "none",
                              }}>
                              {isSel ? "✓" : ""}
                            </button>
                          )}
                        </div>
                      );
                    })}
                  </div>
                ) : cardsOn && sortedArts.length >= FORGE_RESULT_LIST_FROM ? (
                  /* ⚒️ 10+ — O LOTE E' O ASSUNTO. Uma linha por peca: marca,
                     posto, nome inteiro, poder, cadeado e caixa de seleccao.
                     ~34px cada contra os 312px da torre — as mesmas 50 pecas
                     passam de 3003px para ~816px, e continuam TODAS a poder ser
                     tocadas, trancadas e escolhidas (nenhuma funcao se perde:
                     a lista faz tudo o que a grelha fazia). */
                  <>
                    <div style={{ display:"flex", flexDirection:"column", gap:3 }}>
                      {sortedArts.slice(0, listLimit).map(a => {
                        const isSel = selected.has(a.id);
                        const canSel = !a.is_equipped && !a.locked;
                        const v = GRADE_VISUALS[a.grade] || GRADE_VISUALS[0];
                        const sk = slotForArtifact(a);
                        const icon = slotIco(sk, a.emoji, 15);
                        /* ⚠️ uma Mark em `currentColor` herda a cor do pai — e
                           preta sobre preto ja' apagou um lote inteiro. A linha
                           da grelha rica resolve-o assim, e esta faz o mesmo. */
                        const iconIsMark = markOn(SLOT_MARKS[sk]);
                        const bp = (a.stats || {}).battle_power || 0;
                        return (
                          <div key={a.id}
                               onClick={() => { haptic("light"); setPickedArt(a); }}
                               style={{
                                 display:"flex", alignItems:"center", gap:7,
                                 padding:"5px 7px", borderRadius:6,
                                 background: isSel ? "rgba(var(--red-rgb),.14)" : "rgba(0,0,0,.3)",
                                 borderLeft:`2px solid ${cssHex(v.color)}`,
                                 cursor:"pointer",
                               }}>
                            <span style={{ width:18, flexShrink:0, fontSize:15, textAlign:"center",
                                           ...(iconIsMark ? { display:"grid", placeItems:"center", color:cssHex(v.color) } : {}) }}>{icon}</span>
                            <span style={{ fontFamily:"'Cinzel',serif", fontSize:9, fontWeight:700,
                                           color: v.color, flexShrink:0, letterSpacing:.3 }}>G{a.grade}</span>
                            <span style={{ flex:1, minWidth:0, fontSize:11.5, color:"var(--gold2)",
                                           whiteSpace:"nowrap", overflow:"hidden", textOverflow:"ellipsis" }}>
                              {a.name}
                            </span>
                            {/* ⚠️ o espirito desperto dito em PALAVRA, nao num
                                dingbat: o ✧ e' da familia do ✦ que o jogo esta'
                                a apagar, e a catraca do emoji nao sobe por causa
                                de uma lista nova. A peca com espirito e' a que
                                nao se deve reciclar por engano — tem de dizer
                                o que e' (Lei §1). */}
                            {a.has_spirit && (
                              <span style={{ fontSize:9, flexShrink:0, color:"var(--gold3)",
                                             fontFamily:"'Cinzel',serif", letterSpacing:.3 }}>
                                {t(ART_QUALITY_KEY.spirit || "art_quality_spirit")}
                              </span>
                            )}
                            {bp > 0 && (
                              <span style={{ fontSize:10.5, color:"var(--jade)", flexShrink:0 }}>
                                {fmtNum(bp)}
                              </span>
                            )}
                            {!a.is_equipped && (
                              <button
                                onClick={(e) => { e.stopPropagation(); toggleLock(a); }}
                                aria-label={t(a.locked ? "inv_unlock_btn" : "inv_lock_btn")}
                                style={{
                                  flexShrink:0, width:20, height:20, borderRadius:4,
                                  background:"rgba(0,0,0,.55)",
                                  border:`1px solid ${a.locked ? "var(--gold2)" : "rgba(var(--gold2-rgb),.3)"}`,
                                  color: a.locked ? "var(--gold2)" : "var(--muted)", cursor:"pointer",
                                  fontSize:10, lineHeight:1, padding:0,
                                  display:"grid", placeItems:"center",
                                }}>
                                {a.locked ? ico("🔒", "lock", { size:11 })
                                          : ico("🔓", "lock", { size:11 })}
                              </button>
                            )}
                            {canSel && (
                              <button
                                onClick={(e) => { e.stopPropagation(); toggleSelect(a.id); }}
                                aria-label={t("forge_recycle_toggle")}
                                style={{
                                  flexShrink:0, width:20, height:20, borderRadius:4,
                                  background: isSel ? "var(--red)" : "rgba(0,0,0,.55)",
                                  border: isSel ? "1px solid var(--red)" : "1px solid rgba(var(--gold2-rgb),.45)",
                                  color:"#fff", cursor:"pointer",
                                  fontSize:11, lineHeight:1, padding:0,
                                  display:"grid", placeItems:"center", fontWeight:700,
                                }}>
                                {isSel ? ico("✓", "check", { size:11 }) : ""}
                              </button>
                            )}
                          </div>
                        );
                      })}
                    </div>
                    {sortedArts.length > listLimit && (
                      <button onClick={() => { haptic("light"); setListLimit(x => x + FORGE_RESULT_PAGE); }}
                              style={{
                                width:"100%", marginTop:6,
                                padding:"6px 14px", borderRadius:8, cursor:"pointer",
                                background:"rgba(var(--gold-rgb),.10)",
                                border:"1px solid rgba(var(--gold-rgb),.35)",
                                color:"var(--gold2)", fontSize:11.5,
                                fontFamily:"'Cinzel',serif", letterSpacing:.4, fontWeight:600,
                              }}>
                        {t("inv_load_more", { n: Math.min(FORGE_RESULT_PAGE, sortedArts.length - listLimit) })} ({sortedArts.length - listLimit})
                      </button>
                    )}
                  </>
                ) : (
                  <div style={{
                    display:"grid",
                    /* ⚒️ 4-9 — a grelha pintada, com a largura do DONO das
                       grelhas de carta (`CardGrid`/`InvGrid` usam 152px; aqui
                       104px da' 3 colunas a 390px, que e' o minimo em que o nome
                       se le'). ⚠️ O ramo OFF e' a string de hoje, byte a byte. */
                    gridTemplateColumns: cardsOn
                      ? `repeat(auto-fill, minmax(${FORGE_RESULT_CARD_MIN}px, 1fr))`
                      : "repeat(auto-fit, minmax(54px, 1fr))",
                    gap: cardsOn ? 7 : 5,
                  }}>
                    {sortedArts.map(a => {
                      const isSel = selected.has(a.id);
                      const canSel = !a.is_equipped && !a.locked;
                      return (
                        <div key={a.id} style={{ position:"relative" }}>
                          <ArtifactCell a={a}
                                        onClick={() => { haptic("light"); setPickedArt(a); }} />
                          {canSel && (
                            <button
                              onClick={(e) => { e.stopPropagation(); toggleSelect(a.id); }}
                              aria-label={t("forge_recycle_toggle")}
                              style={{
                                position:"absolute", top:2, right:2,
                                width:18, height:18, borderRadius:4,
                                background: isSel ? "var(--red)" : "rgba(0,0,0,.65)",
                                border: isSel ? "1px solid var(--red)" : "1px solid rgba(var(--gold2-rgb),.45)",
                                color:"#fff", cursor:"pointer",
                                fontSize:10, lineHeight:"16px", padding:0,
                                display:"grid", placeItems:"center",
                                fontWeight:700,
                                boxShadow: isSel ? "0 0 6px rgba(var(--red-rgb),.6)" : "none",
                              }}>
                              {isSel ? "✓" : ""}
                            </button>
                          )}
                          {/* U1 (v16.6): lock toggle (top-left) — protect/free a pull before Recycle All */}
                          {!a.is_equipped && (
                            <button
                              onClick={(e) => { e.stopPropagation(); toggleLock(a); }}
                              aria-label={t(a.locked ? "inv_unlock_btn" : "inv_lock_btn")}
                              style={{
                                position:"absolute", top:2, left:2,
                                width:18, height:18, borderRadius:4,
                                background:"rgba(0,0,0,.65)",
                                border:`1px solid ${a.locked ? "var(--gold2)" : "rgba(var(--gold2-rgb),.35)"}`,
                                color: a.locked ? "var(--gold2)" : "var(--muted)", cursor:"pointer",
                                fontSize:9, lineHeight:"16px", padding:0,
                                display:"grid", placeItems:"center",
                              }}>
                              {a.locked ? "🔒" : "🔓"}
                            </button>
                          )}
                        </div>
                      );
                    })}
                  </div>
                )}
                <div style={{ fontSize:9.5, color:"var(--muted2)", textAlign:"center", marginTop:3, fontStyle:"italic" }}>
                  {t("forge_artifact_tap_hint")}
                </div>
                {recyclable.length > 0 && (
                  <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:6, marginTop:7 }}>
                    <ActionBtn
                      variant="danger"
                      disabled={recycling || selectedIds.length === 0}
                      onClick={() => doRecycle(selectedIds)}
                      style={{ padding:"8px 8px", fontSize:11 }}>
                      🔥 {t("forge_recycle_selected", { n: selectedIds.length })}
                    </ActionBtn>
                    <ActionBtn
                      variant="danger"
                      disabled={recycling || recyclable.length === 0}
                      onClick={() => doRecycle(recyclableIds)}
                      style={{ padding:"8px 8px", fontSize:11 }}>
                      🔥 {t("forge_recycle_all", { n: recyclable.length })}
                    </ActionBtn>
                  </div>
                )}
              </div>
            )}

            {recycleSummary && (
              <div style={{
                background:"linear-gradient(135deg, rgba(var(--red-rgb),.14), rgba(0,0,0,.4))",
                border:"1px solid rgba(var(--red-rgb),.4)", borderRadius:8,
                padding:"6px 10px", marginBottom:8, fontSize:11,
                color:"var(--gold3)", textAlign:"center",
              }}>
                🔥 {t("forge_recycled_summary", {
                  n: recycleSummary.count,
                  stones: fmtNum(recycleSummary.stones),
                })}
                {/* U2 (v16.6): materials recovered from the recycle */}
                {recycleSummary.materials && recycleSummary.materials.length > 0 && (
                  <div style={{ marginTop:3, fontSize:10.5, color:"var(--jade)" }}>
                    {recycleSummary.materials.map(m => `${m.emoji} ${m.name} ×${m.qty}`).join(", ")}
                  </div>
                )}
              </div>
            )}

            <div style={{
              background:"rgba(0,0,0,.3)", borderRadius:8, padding:"6px 10px",
              fontSize:11, color:"var(--muted)", display:"grid", gap:3,
            }}>
              {result.xp_gain > 0 && (
                <div>📚 +{result.xp_gain} {t("forge_xp")} <span style={{ color:"var(--muted2)" }}>(T{result.forge_tier})</span></div>
              )}
              {result.leveled_up && (
                <div style={{ color:"var(--gold3)" }}>⭐ {t("forge_tier_levelup", { n: result.forge_tier })}</div>
              )}
              {result.mastery_leveled_up && result.mastery_level && (
                <div style={{ color:"var(--gold3)" }}>📖 {t("forge_mastery_levelup", { n: result.mastery_level })}</div>
              )}
              {result.charm_saved && (
                <div style={{ color:"var(--warn)" }}>🛡️ {t("forge_charm_saved")}</div>
              )}
              {/* TEC-1 §0.1 (pedido [jogador]) — XP do ofício ganho, VISÍVEL (Lei §10).
                  Chave condicional: só existe com flag ON + ofício. */}
              {result.prof_xp_gained > 0 && (
                <div style={{ color:"var(--gold3)" }}>🏮 {result.prof_weight_tier
                  ? t("prf_mini_xp_gain_tier", { n: result.prof_xp_gained, tier: result.prof_weight_tier, w: result.prof_weight })
                  : t("prf_mini_xp_gain", { n: result.prof_xp_gained })}</div>
              )}
            </div>
          {pickedArt && (
            <DetailModal entry={{ kind: "artifact", ...pickedArt }}
                         onClose={() => setPickedArt(null)}
                         onActionDone={() => setPickedArt(null)} />
          )}
        </Modal>
      );
    }

    var ART_QUALITY_RANK = { normal:0, perfect:1, divine:2, spirit:3 };
    // Server default BULK_DISMANTLE_LIMIT — mirrors core/webserver.py. Used to
    // clamp the confirm preview so it never promises more than one call does.
    var BULK_DISMANTLE_LIMIT = 200;
    function BulkDismantleModal({ onClose, onDone, refreshData }) {
      const [busy, setBusy] = useState(false);
      const [err, setErr] = useState(null);
      // TAPETE QoL §5 item 1 ([jogador]: "caixinha de seleção com as qualidades —
      // ex: tudo G8 abaixo de Divino"): quality cutoff + a confirm step with
      // a preview computed from the SAME filtered list the server will use.
      const [qualityCut, setQualityCut] = useState("all"); // all|perfect|divine|spirit
      const [pending, setPending] = useState(null); // {cat_type, grade, exact, n, ss}
      const [stats, setStats] = useState(null);    // last result preview
      // Bug fix 2026-05-06 (round 3): owner reported "items NAO SOME ainda
      // fica la mesmo que ja nao passa dar desmantle". Cause: useApi had
      // empty deps → never refetched after dismantle, so buckets showed
      // ghost rows that 404 on retry. We now bump `invReload` after every
      // successful dismantle to refetch the live inventory.
      const [invReload, setInvReload] = useState(0);
      const { data: inv, loading } = useApi("inventory", null, [invReload]);

      function passQuality(a) {
        if (qualityCut === "all") return true;
        // refined/unknown qualities rank ABOVE every cut (mirror the server's
        // artifact_quality_rank) — a quality filter never selects them.
        const rank = ART_QUALITY_RANK[a.quality || "normal"] ?? 99;
        return rank < ART_QUALITY_RANK[qualityCut];
      }

      const buckets = useMemo(() => {
        // Build {weapon: {0: count, ...}, armor: ..., accessory: ...} from
        // unequipped + unlocked artifacts that pass the quality cutoff.
        // Mirrors the server filter (locked now ships on /inventory) so the
        // preview counts match execution.
        const out = { weapon: {}, armor: {}, accessory: {} };
        if (!inv) return out;
        (inv.artifacts || []).forEach(a => {
          if (a.is_equipped || a.locked) return;
          if (!passQuality(a)) return;
          const ty = a.type || "weapon";
          if (!out[ty]) return;
          const g = a.grade ?? 0;
          out[ty][g] = (out[ty][g] || 0) + 1;
        });
        return out;
      }, [inv, qualityCut]);

      async function doDismantle({ cat_type, grade, exact }) {
        if (busy) return;
        setBusy(true); setErr(null);
        haptic("warning");
        try {
          const res = await api("forge/dismantle", {
            bulk: true, cat_type, grade, exact,
            below_quality: qualityCut === "all" ? undefined : qualityCut,
          });
          if (!res.ok) {
            haptic("error");
            setErr(forgeReason(res.reason));
            setBusy(false);
            return;
          }
          haptic("success");
          setStats(res);
          setPending(null);
          setInvReload(x => x + 1);  // refetch local inventory so buckets shrink immediately
          refreshData && refreshData();
          onDone && onDone(res);
        } catch (e) {
          haptic("error");
          setErr(t("forge_err_engine"));
        } finally {
          setBusy(false);
        }
      }

      if (loading) {
        return (
          <Modal onClose={onClose} title={`♻️ ${t("forge_bulk_dismantle_title")}`}
                 accent="rgba(var(--red-rgb),.4)" maxWidth={460} zIndex={65}>
            <div style={{ display:"grid", placeItems:"center", padding:"40px 0" }}>
              <DotSpinner />
            </div>
          </Modal>
        );
      }

      const TYPES = ["weapon", "armor", "accessory"];

      return (
        <Modal onClose={onClose}
               title={`♻️ ${t("forge_bulk_dismantle_title")}`}
               accent="rgba(var(--red-rgb),.4)"
               maxWidth={460} zIndex={65}
               animation="alch-pop 380ms cubic-bezier(.2,1.4,.4,1)">
            <div style={{ fontSize:11, color:"var(--muted)", marginBottom:10, lineHeight:1.5 }}>
              {t("forge_bulk_dismantle_hint")}
            </div>

            {/* TAPETE QoL §5 item 1 — [jogador]'s "caixinha": quality cutoff.
                "< Divino" = dismantle only normal+perfect, keep divine/spirit. */}
            <Card style={{ padding:"8px 10px", marginBottom:10 }}>
              <div style={{ fontSize:10.5, color:"var(--muted)", marginBottom:6 }}>
                🎛️ {t("forge_bulk_quality_label")}
              </div>
              <SegControl
                options={[
                  { value:"all",     label: t("forge_bulk_quality_all") },
                  { value:"perfect", label: `< ${t("art_quality_perfect")}` },
                  { value:"divine",  label: `< ${t("art_quality_divine")}` },
                  { value:"spirit",  label: `< ${t("art_quality_spirit")}` },
                ]}
                value={qualityCut}
                onChange={(v) => { setQualityCut(v); setPending(null); }}
              />
            </Card>

            {err && <ErrBanner msg={err} />}

            {stats && (
              <div style={{
                background:"rgba(var(--jade-rgb),.08)", border:"1px solid rgba(var(--jade-rgb),.3)",
                borderRadius:8, padding:"8px 10px", marginBottom:10,
                fontSize:11.5, color:"var(--jade)", textAlign:"center",
              }}>
                ✅ {t("forge_bulk_dismantle_done", { n: stats.count, ss: fmtNum(stats.stones_gained) })}
                {stats.truncated && (
                  <div style={{ color:"var(--warn)", fontSize:10, marginTop:3 }}>
                    ⚠️ {t("forge_bulk_dismantle_truncated", { limit: stats.limit })}
                  </div>
                )}
              </div>
            )}

            {/* Preview + explicit confirmation before anything is destroyed
                (Lei §1 — preview == execution: same filters as the server). */}
            {pending && (
              <Card style={{ padding:12, marginBottom:10, borderColor:"rgba(var(--red-rgb),.5)" }}>
                <CardTitle left={`⚠️ ${t("forge_bulk_confirm_title")}`} />
                <div style={{ fontSize:12, color:"var(--text)", lineHeight:1.5 }}>
                  {t("forge_bulk_confirm_body", { n: pending.n, ss: fmtNum(pending.ss) })}
                </div>
                <div style={{ fontSize:10.5, color:"var(--muted)", marginTop:6, lineHeight:1.45 }}>
                  🔒 {t("forge_bulk_confirm_note")}
                  {qualityCut !== "all" && (
                    <span> · {t("forge_bulk_quality_label")}: {"< "}{t(ART_QUALITY_KEY[qualityCut])}</span>
                  )}
                </div>
                {pending.clamped && (
                  <div style={{ fontSize:10, color:"var(--warn)", marginTop:5 }}>
                    ⚠️ {t("forge_bulk_dismantle_truncated", { limit: BULK_DISMANTLE_LIMIT })}
                  </div>
                )}
                <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:8, marginTop:10 }}>
                  <ActionBtn variant="danger" disabled={busy}
                             onClick={() => doDismantle(pending)}>
                    {busy ? <DotSpinner /> : `♻️ ${t("forge_bulk_confirm_btn", { n: pending.n })}`}
                  </ActionBtn>
                  <ActionBtn variant="ghost" disabled={busy} onClick={() => setPending(null)}>
                    {t("forge_bulk_cancel_btn")}
                  </ActionBtn>
                </div>
              </Card>
            )}

            {!pending && TYPES.map(ty => {
              const bucket = buckets[ty] || {};
              const grades = Object.keys(bucket).map(Number).sort((a, b) => a - b);
              if (grades.length === 0) return null;
              return (
                <Card key={ty} style={{ padding:"8px 10px", marginBottom:8 }}>
                  <CardTitle left={t(`slot_${ty}`)} />
                  <div style={{ display:"flex", flexDirection:"column", gap:4 }}>
                    {grades.map(g => {
                      const n = bucket[g];
                      const ssEach = ({0:50,1:150,2:500,3:1500,4:5000,5:15000,6:50000,7:200000,8:750000})[g] || 50;
                      const total = n * ssEach;
                      const v = GRADE_VISUALS[g] || GRADE_VISUALS[0];
                      return (
                        <button key={g} disabled={busy}
                                onClick={() => {
                                  haptic("select");
                                  // Clamp the preview to the server's per-call cap so the
                                  // confirmation never promises more than one call executes.
                                  const nClamped = Math.min(n, BULK_DISMANTLE_LIMIT);
                                  setPending({ cat_type: ty, grade: g, exact: true,
                                               n: nClamped, ss: nClamped * ssEach,
                                               clamped: n > BULK_DISMANTLE_LIMIT });
                                }}
                                style={{
                                  display:"flex", alignItems:"center", justifyContent:"space-between",
                                  padding:"7px 10px", borderRadius:7, cursor: busy ? "default" : "pointer",
                                  background:"rgba(0,0,0,.3)", border:`1px solid ${cssHex(v.color)}33`,
                                  color:"var(--text)", fontSize:11.5,
                                }}>
                          <span style={{ display:"flex", alignItems:"center", gap:6 }}>
                            <span style={{
                              padding:"1px 6px", fontSize:9, color: v.color, letterSpacing:.5,
                              fontFamily:"'Cinzel',serif", border:`1px solid ${cssHex(v.color)}55`, borderRadius:99,
                            }}>G{g}</span>
                            <span style={{ color:"var(--muted)" }}>×{n}</span>
                          </span>
                          <b style={{ color:"var(--jade)" }}>+{fmtNum(total)} SS</b>
                        </button>
                      );
                    })}

                    {/* "≤ grade X" combined option — biggest win for grinders */}
                    {grades.length >= 2 && (() => {
                      const cutoff = grades[grades.length - 2];
                      const nTotal = grades.filter(g => g <= cutoff).reduce((s, g) => s + bucket[g], 0);
                      const ssTotal = grades.filter(g => g <= cutoff).reduce((s, g) =>
                        s + bucket[g] * (({0:50,1:150,2:500,3:1500,4:5000,5:15000,6:50000,7:200000,8:750000})[g] || 50), 0);
                      const cv = GRADE_VISUALS[cutoff] || GRADE_VISUALS[0];
                      return (
                        <button disabled={busy}
                                onClick={() => {
                                  haptic("select");
                                  const nClamped = Math.min(nTotal, BULK_DISMANTLE_LIMIT);
                                  // Mixed grades: scale the SS estimate proportionally when
                                  // clamped (body text already says "~").
                                  const ssClamped = nClamped === nTotal ? ssTotal
                                    : Math.round(ssTotal * nClamped / nTotal);
                                  setPending({ cat_type: ty, grade: cutoff, exact: false,
                                               n: nClamped, ss: ssClamped,
                                               clamped: nTotal > BULK_DISMANTLE_LIMIT });
                                }}
                                style={{
                                  display:"flex", alignItems:"center", justifyContent:"space-between",
                                  padding:"7px 10px", borderRadius:7, cursor: busy ? "default" : "pointer",
                                  background:"rgba(var(--red-rgb),.06)", border:"1px solid rgba(var(--red-rgb),.4)",
                                  color:"var(--red2)", fontSize:11.5,
                                }}>
                          <span>♻️ {t("forge_bulk_dismantle_below", { grade: `G${cutoff}` })} <span style={{ color:"var(--muted)" }}>×{nTotal}</span></span>
                          <b style={{ color:"var(--jade)" }}>+{fmtNum(ssTotal)} SS</b>
                        </button>
                      );
                    })()}
                  </div>
                </Card>
              );
            })}

            {!pending && (buckets.weapon && Object.keys(buckets.weapon).length === 0)
              && (buckets.armor && Object.keys(buckets.armor).length === 0)
              && (buckets.accessory && Object.keys(buckets.accessory).length === 0) && (
              <div style={{ textAlign:"center", padding:"20px 8px", color:"var(--muted)", fontSize:12 }}>
                {t("forge_bulk_dismantle_empty")}
              </div>
            )}
        </Modal>
      );
    }

    // ─── Sprint v14.14g — Artifact Workshop (refine + enchant) ──────────────
    // The chat audit flagged `core.forge_engine.refine_artifact` and
    // `enchant_artifact` as engine-only — they existed since H-7 but never
    // had a chat handler. This modal surfaces both into the mini-app. The
    // entry point lives on ForgeHeaderCard as a secondary CTA.

    const ENCHANT_RUNES = [
      { id:"cb_boost",   emoji:"⚡", label_key:"enchant_rune_cb_boost",   accent:"rgba(124,211,255,.5)" },
      { id:"bp_boost",   emoji:"⚔️", label_key:"enchant_rune_bp_boost",   accent:"rgba(var(--red-rgb),.5)" },
      { id:"luck_boost", emoji:"🍀", label_key:"enchant_rune_luck_boost", accent:"rgba(var(--jade-rgb),.5)" },
      { id:"soul_boost", emoji:"👻", label_key:"enchant_rune_soul_boost", accent:"rgba(180,140,255,.5)" },
    ];

    function workshopReason(code) {
      const map = {
        artifact_not_found:   t("workshop_err_artifact_not_found"),
        max_grade:            t("workshop_err_max_grade"),
        no_duplicate_found:   t("workshop_err_no_duplicate"),
        invalid_rune:         t("workshop_err_invalid_rune"),
        engine_error:         t("forge_err_engine"),
      };
      return map[code] || code || t("forge_err_engine");
    }

    function ArtifactWorkshopModal({ onClose, onPlayerRefresh }) {
      const [reload, setReload] = useState(0);
      const { data, loading, error } = useApi("inventory", null, [reload]);
      const [picked, setPicked] = useState(null);  // {kind:"refine"|"enchant", art}
      const [filter, setFilter] = useState("all"); // all|spirit|enchanted|unenchanted

      function bumpRefresh() {
        setReload(x => x + 1);
        onPlayerRefresh && onPlayerRefresh();
      }

      const artifacts = data?.artifacts || [];
      const filtered = artifacts.filter(a => {
        if (filter === "spirit")      return !!a.has_spirit;
        if (filter === "enchanted")   return !!a.enchant_rune;
        if (filter === "unenchanted") return !a.enchant_rune;
        return true;
      })
      // Show higher-grade first so the player's strongest pieces lead.
      .sort((a, b) => (b.grade || 0) - (a.grade || 0) || (a.name || "").localeCompare(b.name || ""));

      return (
        <Modal onClose={onClose} title={`🛡️ ${t("workshop_title")}`}
               accent="rgba(var(--gold2-rgb),.4)" maxWidth={520} zIndex={60}>
          <div style={{ fontSize:11.5, color:"var(--muted)", lineHeight:1.5, marginBottom:10 }}>
            {t("workshop_subtitle")}
          </div>

          {error && <ErrBanner msg={error} />}

          <Card style={{ padding:"8px 10px", marginBottom:10 }}>
            <SegControl
              options={[
                { value:"all",         label:t("workshop_filter_all") },
                { value:"unenchanted", label:`⚪ ${t("workshop_filter_unenchanted")}` },
                { value:"enchanted",   label:`🔮 ${t("workshop_filter_enchanted")}` },
                { value:"spirit",      label:`✧ ${t("workshop_filter_spirit")}` },
              ]}
              value={filter} onChange={setFilter} />
          </Card>

          {loading && !data ? <ListSkeleton rows={4} /> :
           filtered.length === 0 ? (
            <Card><div style={{ textAlign:"center", padding:"22px 10px", color:"var(--muted)", fontSize:12 }}>
              {t("workshop_empty")}
            </div></Card>
          ) : (
            <div style={{ display:"flex", flexDirection:"column", gap:8 }}>
              {filtered.map(a => {
                const v = GRADE_VISUALS[a.grade] || GRADE_VISUALS[0];
                const runeMeta = a.enchant_rune
                  ? ENCHANT_RUNES.find(r => r.id === a.enchant_rune)
                  : null;
                return (
                  <div key={a.id} style={{
                    padding:"10px 12px", borderRadius:10,
                    border:`1px solid ${cssHex(v.color)}55`,
                    background:`linear-gradient(180deg, ${cssHex(v.color)}11, rgba(20,40,55,.4))`,
                  }}>
                    <div style={{ display:"flex", alignItems:"center", gap:10, marginBottom:8 }}>
                      {itemVivoOn()
                        ? <PieceIcon kind="artifact" name={a.name} artKey={a.art_key} emoji={a.emoji}
                                     size={40} accent={v.color} radius={7} />
                        : <span style={{ fontSize:22, filter:`drop-shadow(0 0 6px ${v.glow})` }}>{a.emoji}</span>}
                      <div style={{ flex:1, minWidth:0 }}>
                        <div style={{ fontFamily:"'Cinzel',serif", fontWeight:700, fontSize:13, color:v.color,
                                       overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap" }}>
                          {a.name}
                          {a.is_equipped && <span style={{ color:"var(--gold2)", fontSize:10, marginLeft:6 }}>✦</span>}
                        </div>
                        <div style={{ fontSize:10, color:"var(--muted)", marginTop:1 }}>
                          {t("forge_grade_" + (a.grade ?? 0))}
                          {a.has_spirit && <span style={{ color:"var(--gold2)", marginLeft:6 }}>✧ {a.spirit_name || t("workshop_spirit_short")}</span>}
                          {runeMeta && (
                            <span style={{ marginLeft:6 }}>· {runeMeta.emoji} {t(runeMeta.label_key)}</span>
                          )}
                          {/* QoL-Feedback 03/08 (report [jogador]: "I have a G7
                              spirit weapon, but there's no option to refine it").
                              O teto G7 Dao é design (forge_engine.py:194) — o
                              defeito era o silêncio. O chip diz o estado NA LINHA,
                              antes mesmo de tocar. (Lição: hard-gate que zera não
                              pode esconder a opção.) */}
                          {/* G8 Celestial EXISTE (receitas tier 6, Mahayana):
                              dizer-lhe "grau máximo é G7 Dao" seria contradizer
                              a própria linha acima, que mostra G8. Dois estados,
                              duas verdades. */}
                          {(a.grade ?? 0) >= 8 ? (
                            <span style={{ color:"var(--gold2)", marginLeft:6 }}>
                              · 👑 {t("refine_at_absolute_max")}
                            </span>
                          ) : (a.grade ?? 0) === 7 ? (
                            <span style={{ color:"var(--gold2)", marginLeft:6 }}>
                              · ⭐ {t("refine_at_max")}
                            </span>
                          ) : null}
                        </div>
                      </div>
                    </div>
                    <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:6 }}>
                      {/* QoL-Feedback 03/08 — o botão ficava `disabled` MUDO em
                          G7: o jogador lia "não existe opção de refinar". As
                          strings que explicavam o teto viviam DENTRO do
                          RefineConfirmModal, que o próprio botão desabilitado
                          impedia de abrir — caminho morto. O modal já trata
                          `at_max_grade` com elegância (banner ⭐ + confirmar
                          bloqueado), então deixa-se ABRIR: a recusa passa a DIZER
                          o porquê e a apontar o caminho seguinte (Lei §1). */}
                      <ActionBtn variant="ghost"
                                 onClick={() => { haptic("select"); setPicked({ kind:"refine", art:a }); }}>
                        ✨ {t("workshop_action_refine")}
                      </ActionBtn>
                      <ActionBtn variant="ghost"
                                 onClick={() => { haptic("select"); setPicked({ kind:"enchant", art:a }); }}>
                        🔮 {t("workshop_action_enchant")}
                      </ActionBtn>
                    </div>
                  </div>
                );
              })}
            </div>
          )}

          {picked && picked.kind === "refine" && (
            <RefineConfirmModal art={picked.art}
              onClose={() => setPicked(null)}
              onDone={() => { setPicked(null); bumpRefresh(); }} />
          )}
          {picked && picked.kind === "enchant" && (
            <EnchantPickerModal art={picked.art}
              onClose={() => setPicked(null)}
              onDone={() => { setPicked(null); bumpRefresh(); }} />
          )}
        </Modal>
      );
    }

    function RefineConfirmModal({ art, onClose, onDone }) {
      const [preview, setPreview] = useState(null);
      const [busy, setBusy] = useState(false);
      const [err, setErr] = useState(null);
      const [result, setResult] = useState(null);

      useEffect(() => {
        let cancelled = false;
        setErr(null);
        (async () => {
          try {
            const res = await api("forge/refine", { artifact_id: art.id, dry_run: true });
            if (cancelled) return;
            if (!res.ok) { setErr(workshopReason(res.reason)); setPreview(null); return; }
            setPreview(res);
          } catch (e) {
            if (!cancelled) setErr(t("forge_err_engine"));
          }
        })();
        return () => { cancelled = true; };
      }, [art.id]);

      async function confirm() {
        if (busy || !preview || preview.duplicates < 1 || preview.at_max_grade) return;
        haptic("warning"); setBusy(true); setErr(null);
        try {
          const res = await api("forge/refine", { artifact_id: art.id });
          if (!res.ok) {
            haptic("error"); setErr(workshopReason(res.reason)); setBusy(false); return;
          }
          // status: refine_success | refine_fail | refine_fail_protected | refine_fail_prof (MV-7)
          if (res.status === "refine_success") {
            haptic("success");
            showToast(t("refine_success_toast", { grade: res.artifact?.grade ?? 0 }));
            if (res.prof_free_refine) showToast(t("prf_mini_refine_free"));
          } else if (res.status === "refine_fail_protected") {
            haptic("warning");
            showToast(t("refine_protected_toast"));
          } else if (res.status === "refine_fail_prof") {
            // MV-7 — ⚒️ o ofício segurou a duplicata (falhou, mas nada se perdeu).
            haptic("warning");
            showToast(t("prf_mini_refine_free"));
          } else {
            haptic("error");
            showToast(t("refine_fail_toast"), "err");
          }
          setResult(res);
          onDone && onDone(res);
        } catch (e) {
          haptic("error"); setErr(t("forge_err_engine")); setBusy(false);
        }
      }

      const v = GRADE_VISUALS[art.grade] || GRADE_VISUALS[0];

      const footer = preview && !result && (
        <ActionBtn variant="primary"
                   disabled={busy || preview.at_max_grade || preview.duplicates < 1}
                   onClick={confirm} style={{ width:"100%" }}>
          {busy ? <DotSpinner /> :
            preview.at_max_grade ? `⭐ ${t("refine_at_max")}`
            : preview.duplicates < 1 ? `🔒 ${t("refine_need_duplicate")}`
            : `✨ ${t("refine_confirm_btn", { pct: Math.round(preview.success_chance || 60) })}`}
        </ActionBtn>
      );

      return (
        <Modal onClose={onClose} title={`✨ ${t("refine_title")}`}
               accent={`${cssHex(v.color)}66`} maxWidth={420} zIndex={70}
               footer={footer}>
          {err && <ErrBanner msg={err} />}

          <Card style={{ padding:"12px 14px 10px", marginBottom:10, textAlign:"center" }}>
            {itemVivoOn()
              ? <div style={{ display:"grid", placeItems:"center", marginBottom:6 }}>
                  <PieceIcon kind="artifact" name={art.name} artKey={art.art_key} emoji={art.emoji}
                             size={92} accent={v.color} radius={10} />
                </div>
              : <div style={{ fontSize:38, marginBottom:4, filter:`drop-shadow(0 0 10px ${v.glow})` }}>{art.emoji}</div>}
            <div style={{ fontFamily:"'Cinzel',serif", fontSize:14, color:v.color, fontWeight:700 }}>{art.name}</div>
            <div style={{ fontSize:11, color:"var(--muted)", marginTop:2 }}>
              {t("forge_grade_" + (art.grade ?? 0))}
              {art.has_spirit && <span style={{ color:"var(--gold2)", marginLeft:6 }}>✧</span>}
            </div>
          </Card>

          <div style={{ fontSize:11.5, color:"var(--muted)", lineHeight:1.5, marginBottom:10 }}>
            {t("refine_explainer")}
          </div>

          {preview ? (
            <>
              {result ? (
                <Card style={{ padding:"14px 14px 12px", textAlign:"center",
                               border: result.status === "refine_success" ? "1px solid var(--jade)"
                                     : (result.status === "refine_fail_protected" || result.status === "refine_fail_prof") ? "1px solid var(--gold2)"
                                     : "1px solid var(--red)" }}>
                  <div style={{ fontSize:32, marginBottom:6 }}>
                    {result.status === "refine_success" ? "✨"
                      : result.status === "refine_fail_protected" ? "🛡️"
                      : result.status === "refine_fail_prof" ? "⚒️" : "💔"}
                  </div>
                  <div style={{ fontFamily:"'Cinzel',serif", fontSize:13, color:
                    result.status === "refine_success" ? "var(--jade)"
                    : (result.status === "refine_fail_protected" || result.status === "refine_fail_prof") ? "var(--gold2)" : "var(--red)" }}>
                    {result.status === "refine_success" ? t("refine_success_msg", { grade: result.artifact?.grade ?? 0 })
                      : result.status === "refine_fail_protected" ? t("refine_protected_msg")
                      : result.status === "refine_fail_prof" ? t("prf_mini_refine_free")
                      : t("refine_fail_msg")}
                  </div>
                  {/* MV-7 — sucesso COM proc: a duplicata sobreviveu. */}
                  {result.status === "refine_success" && result.prof_free_refine && (
                    <div style={{ fontSize:11, color:"var(--gold2)", marginTop:4 }}>
                      ⚒️ {t("prf_mini_refine_free")}
                    </div>
                  )}
                  <ActionBtn variant="primary" onClick={onClose} style={{ marginTop:10, width:"100%" }}>
                    {t("alch_close")}
                  </ActionBtn>
                </Card>
              ) : (
                <>
                  {/* Review adversarial 03/08 — este Card mostra
                      "Duplicados ×0" (o servidor faz short-circuit e NÃO conta
                      em G7+) e "Probabilidade 60%" (uma chance que nunca pode
                      ser rolada). Era inofensivo enquanto o botão estava
                      disabled; agora que o modal abre, seriam os DOIS primeiros
                      números que o jogador do report leria — e ambos falsos.
                      No topo, só o banner ⭐ fala. */}
                  {!preview.at_max_grade && (
                  <Card style={{ padding:"10px 12px", marginBottom:10 }}>
                    <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", marginBottom:5 }}>
                      <span style={{ fontSize:11.5, color:"var(--muted)" }}>{t("refine_duplicates_label")}</span>
                      <b style={{ color: preview.duplicates > 0 ? "var(--jade)" : "var(--red)" }}>
                        ×{preview.duplicates}
                      </b>
                    </div>
                    <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center" }}>
                      <span style={{ fontSize:11.5, color:"var(--muted)" }}>{t("refine_chance_label")}</span>
                      <b style={{ color:"var(--gold2)" }}>{Math.round(preview.success_chance || 60)}%</b>
                    </div>
                    {/* MV-7 — ⚒️ o perk do Ferreiro é DITO no preview (Lei da
                        progressão visível; key ausente sem ofício/flag OFF). */}
                    {preview.prof_free_chance > 0 && (
                      <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", marginTop:5 }}>
                        <span style={{ fontSize:11.5, color:"var(--muted)" }}>⚒️ {t("prf_mini_refine_chance_label")}</span>
                        <b style={{ color:"var(--gold2)" }}>{preview.prof_free_chance}%</b>
                      </div>
                    )}
                  </Card>
                  )}
                  {preview.duplicates < 1 && !preview.at_max_grade && (
                    <div style={{ fontSize:11, color:"var(--warn)", textAlign:"center",
                                   padding:"8px 10px", background:"rgba(229,168,68,.08)",
                                   border:"1px solid rgba(229,168,68,.2)", borderRadius:6 }}>
                      ⚠️ {t("refine_hint_no_duplicate")}
                    </div>
                  )}
                  {preview.at_max_grade && (
                    <div style={{ fontSize:11, color:"var(--gold2)", textAlign:"center",
                                   padding:"8px 10px", background:"rgba(var(--gold2-rgb),.08)",
                                   border:"1px solid rgba(var(--gold2-rgb),.2)", borderRadius:6 }}>
                      <div>⭐ {t("refine_at_max")}</div>
                      {/* QoL-Feedback 03/08 (report [jogador]) — Lei §1: a recusa
                          diz o porquê E o caminho seguinte. Acima de G7 não se
                          refina: forja-se inteiro. */}
                      <div style={{ marginTop:5, color:"var(--muted)", lineHeight:1.5 }}>
                        {t("refine_at_max_next")}
                      </div>
                    </div>
                  )}
                </>
              )}
            </>
          ) : (
            <div style={{ textAlign:"center", padding:"14px 8px" }}><DotSpinner /></div>
          )}
        </Modal>
      );
    }

    function EnchantPickerModal({ art, onClose, onDone }) {
      const [busy, setBusy] = useState(false);
      const [err, setErr] = useState(null);
      const [picked, setPicked] = useState(art.enchant_rune || null);

      async function apply() {
        if (busy || !picked) return;
        haptic("warning"); setBusy(true); setErr(null);
        try {
          const res = await api("forge/enchant", { artifact_id: art.id, rune_type: picked });
          if (!res.ok) {
            haptic("error"); setErr(workshopReason(res.reason)); setBusy(false); return;
          }
          haptic("success");
          showToast(t("enchant_done_toast"));
          onDone && onDone(res);
        } catch (e) {
          haptic("error"); setErr(t("forge_err_engine")); setBusy(false);
        }
      }

      const v = GRADE_VISUALS[art.grade] || GRADE_VISUALS[0];
      const isSameAsCurrent = picked && art.enchant_rune === picked;

      const footer = (
        <ActionBtn variant="primary"
                   disabled={busy || !picked || isSameAsCurrent}
                   onClick={apply} style={{ width:"100%" }}>
          {busy ? <DotSpinner /> :
            !picked ? `🔮 ${t("enchant_pick_first")}`
            : isSameAsCurrent ? `✓ ${t("enchant_already_applied")}`
            : `🔮 ${t("enchant_apply_btn")}`}
        </ActionBtn>
      );

      return (
        <Modal onClose={onClose} title={`🔮 ${t("enchant_title")}`}
               accent={`${cssHex(v.color)}66`} maxWidth={440} zIndex={70}
               footer={footer}>
          {err && <ErrBanner msg={err} />}

          <Card style={{ padding:"12px 14px 10px", marginBottom:10, textAlign:"center" }}>
            {itemVivoOn()
              ? <div style={{ display:"grid", placeItems:"center", marginBottom:6 }}>
                  <PieceIcon kind="artifact" name={art.name} artKey={art.art_key} emoji={art.emoji}
                             size={84} accent={v.color} radius={10} />
                </div>
              : <div style={{ fontSize:34, marginBottom:4, filter:`drop-shadow(0 0 8px ${v.glow})` }}>{art.emoji}</div>}
            <div style={{ fontFamily:"'Cinzel',serif", fontSize:13, color:v.color, fontWeight:700 }}>{art.name}</div>
            {art.enchant_rune && (
              <div style={{ fontSize:10.5, color:"var(--muted)", marginTop:4 }}>
                {t("enchant_current_label")}: {(() => {
                  const cur = ENCHANT_RUNES.find(r => r.id === art.enchant_rune);
                  return cur ? `${cur.emoji} ${t(cur.label_key)}` : art.enchant_rune;
                })()}
              </div>
            )}
          </Card>

          <div style={{ fontSize:11.5, color:"var(--muted)", lineHeight:1.5, marginBottom:10 }}>
            {t("enchant_explainer")}
            {art.enchant_rune && (
              <div style={{ color:"var(--warn)", marginTop:4 }}>
                ⚠️ {t("enchant_overwrite_warning")}
              </div>
            )}
          </div>

          <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:8 }}>
            {ENCHANT_RUNES.map(r => {
              const active = picked === r.id;
              const isCurrent = art.enchant_rune === r.id;
              return (
                <button key={r.id} onClick={() => { haptic("select"); setPicked(r.id); }}
                        style={{
                          padding:"12px 10px",
                          background: active
                            ? `linear-gradient(180deg, ${r.accent}, rgba(20,30,55,.4))`
                            : "rgba(0,0,0,.3)",
                          border:`1px solid ${active ? r.accent : "rgba(var(--gold2-rgb),.18)"}`,
                          borderRadius:10, cursor:"pointer",
                          textAlign:"center",
                          color: active ? "var(--text)" : "var(--muted)",
                        }}>
                  <div style={{ fontSize:24, marginBottom:4 }}>{r.emoji}</div>
                  <div style={{ fontFamily:"'Cinzel',serif", fontWeight:700, fontSize:11.5 }}>
                    {t(r.label_key)}
                  </div>
                  {isCurrent && (
                    <div style={{ fontSize:9, color:"var(--gold2)", marginTop:2 }}>✓ {t("enchant_current_badge")}</div>
                  )}
                </button>
              );
            })}
          </div>
        </Modal>
      );
    }

    function ForgePanel({ onPlayerRefresh }) {
      const [reload, setReload] = useState(0);
      const [activeTier, setActiveTier] = useState(null);
      const [pickedRecipe, setPickedRecipe] = useState(null);
      const [craftResult, setCraftResult] = useState(null);
      const [filterCraftable, setFilterCraftable] = useState(false);
      // Sprint v14.14g — Artifact Workshop drill-in (refine + enchant)
      const [workshopOpen, setWorkshopOpen] = useState(false);
      const { data, loading, error } = useApi("forge_recipes", null, [reload]);
      const refresh = useCallback(() => setReload(x => x + 1), []);

      useEffect(() => {
        if (activeTier !== null || !data) return;
        // Default to highest tier player can craft (forge_tier + 1) so the
        // player lands on something useful instead of T1 trash.
        const tiers = data.tiers || [];
        const currentTier = (data.forge?.tier || 1) + 1;
        const fit = tiers.find(tg => tg.tier === currentTier && !tg.locked)
                    || tiers.find(tg => !tg.locked)
                    || tiers[0];
        if (fit) setActiveTier(fit.tier);
      }, [activeTier, data]);

      // Mirror AlchemyPanel: re-point pickedRecipe at fresh data every refresh.
      // CRITICAL: this MUST stay above the early returns below to satisfy
      // Rules of Hooks. Loading path renders fewer hooks than main path
      // otherwise → React error #310.
      useEffect(() => {
        if (!data || !pickedRecipe) return;
        const fresh = (data.tiers || [])
          .flatMap(tg => tg.recipes || [])
          .find(r => r.id === pickedRecipe.id);
        if (fresh && fresh !== pickedRecipe) setPickedRecipe(fresh);
      }, [data]);

      function handleCraftResult(res) {
        // Modal stays "fixo" — same UX as alchemy.
        setCraftResult(res);
        refresh();
        onPlayerRefresh && onPlayerRefresh();
      }

      if (loading && !data) return <ListSkeleton rows={6} />;
      if (error && !data) return <ErrBanner msg={error} />;
      if (!data) return null;

      const tiers = data.tiers || [];
      const segOptions = tiers.map(tg => ({
        value: tg.tier,
        label: tg.locked ? `🔒 T${tg.tier}` : `${tg.emoji} T${tg.tier}`,
      }));
      const activeTierData = tiers.find(tg => tg.tier === activeTier) || tiers[0];

      const recipesShown = activeTierData
        ? (filterCraftable
            ? activeTierData.recipes.filter(r => r.can_craft)
            : activeTierData.recipes)
        : [];

      return (
        <div>
          <ForgeHeaderCard data={data} />
          <ForgeOreStrip ores={data.ores} />

          {/* Sprint v14.14g — Workshop CTA: refine duplicates + enchant runes
              for already-owned artifacts. Lives ABOVE the recipe browser so
              the player notices it without scrolling past T1 recipes. */}
          <Card style={{ padding:"10px 12px", marginBottom:10 }}>
            <ActionBtn variant="ghost" onClick={() => { haptic("select"); setWorkshopOpen(true); }}
                       style={{ width:"100%" }}>
              🛡️ {t("workshop_open_btn")}
            </ActionBtn>
            <div style={{ fontSize:10, color:"var(--muted2)", marginTop:5, textAlign:"center", lineHeight:1.4 }}>
              {t("workshop_open_hint")}
            </div>
          </Card>

          {tiers.length > 1 && (
            <Card style={{ padding:"8px 10px", marginBottom:10 }}>
              <SegControl options={segOptions} value={activeTier ?? tiers[0].tier} onChange={setActiveTier} />
            </Card>
          )}

          <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center",
                        marginBottom:8, padding:"0 4px" }}>
            <div style={{ fontSize:11, color:"var(--muted)" }}>
              {activeTierData?.locked ? t("forge_tier_locked_msg", { n: activeTier })
                : t("forge_recipes_count", { n: recipesShown.length, total: activeTierData?.recipes.length || 0 })}
            </div>
            <button onClick={() => { haptic("select"); setFilterCraftable(x => !x); }}
                    style={{
                      background: filterCraftable ? "rgba(var(--jade-rgb),.15)" : "rgba(0,0,0,.3)",
                      border:`1px solid ${filterCraftable ? "rgba(var(--jade-rgb),.4)" : "rgba(var(--gold2-rgb),.18)"}`,
                      borderRadius:6, padding:"4px 8px", cursor:"pointer",
                      fontSize:10.5, color: filterCraftable ? "var(--jade)" : "var(--muted)",
                      fontFamily:"'Cinzel',serif",
                    }}>
              {filterCraftable ? "✅" : "○"} {t("forge_filter_craftable")}
            </button>
          </div>

          {activeTierData?.locked ? (
            <Card><div style={{ textAlign:"center", padding:"20px 8px", color:"var(--muted)", fontSize:12 }}>
              🔒 {t("forge_tier_locked_msg", { n: activeTier })}
            </div></Card>
          ) : recipesShown.length === 0 ? (
            <Card><div style={{ textAlign:"center", padding:"20px 8px", color:"var(--muted)", fontSize:12 }}>
              {filterCraftable ? t("forge_no_craftable") : t("forge_no_recipes_in_tier")}
            </div></Card>
          ) : (
            <div style={{ display:"flex", flexDirection:"column", gap:8 }}>
              {recipesShown.map(r => (
                <ForgeRecipeCard key={r.id} recipe={r} onClick={setPickedRecipe} />
              ))}
            </div>
          )}

          {pickedRecipe && (
            <ForgeRecipeDetailModal recipe={pickedRecipe}
              onClose={() => setPickedRecipe(null)} onCraft={handleCraftResult} />
          )}
          {craftResult && (
            <ForgeResultModal result={craftResult}
              onClose={() => setCraftResult(null)}
              onPlayerRefresh={onPlayerRefresh} />
          )}
          {workshopOpen && (
            <ArtifactWorkshopModal onClose={() => setWorkshopOpen(false)}
              onPlayerRefresh={onPlayerRefresh} />
          )}
        </div>
      );
    }

    function CraftingTab({ onPlayerRefresh }) {
      // QoL 07/08 ([jogador]) — o objetivo `forge_artifact` deep-linka para AQUI, e o
      // Ateliê vive no segmento ⚒️. Sem consumir o pedido, o salto largava o
      // jogador na alquimia — o erro que o QoL de 03/08 já tinha recusado por
      // escrito. `takePendingSeg` só devolve algo se o pedido era para esta aba,
      // e consome-o (um salto = um segmento; voltar depois abre no normal).
      const [seg, setSeg] = useState(() => takePendingSeg("crafting") || "alchemy");
      const opts = [
        { value:"alchemy", label:`⚗️ ${t("alch_segment_alchemy")}` },
        { value:"forge",   label:`⚒️ ${t("alch_segment_forge")}` },
      ];
      return (
        <div>
          <Card style={{ padding:"10px 12px 8px", marginBottom:10 }}>
            <div style={{ display:"flex", alignItems:"center", gap:10, marginBottom:8 }}>
              <div style={{ fontSize:28 }}>🛠️</div>
              <div style={{ minWidth:0 }}>
                <div style={{ fontFamily:"'Cinzel',serif", fontWeight:700, fontSize:14, color:"var(--gold2)" }}>{t("crafting_title")}</div>
                <div style={{ fontSize:11, color:"var(--muted)", lineHeight:1.4 }}>{t("crafting_subtitle")}</div>
              </div>
            </div>
            <SegControl options={opts} value={seg} onChange={setSeg} />
          </Card>
          {seg === "alchemy" ? <AlchemyPanel onPlayerRefresh={onPlayerRefresh} /> : <ForgePanel onPlayerRefresh={onPlayerRefresh} />}
        </div>
      );
    }

    // ─── v15.2 — Intent System (Sword/Fist/Body/Dao/Killing) ─────────────────
    // The 5 canonical Wuxia "yì" paths. UI lives as a drill-in via CombatTab:
    // a "5 Paths" button opens IntentModal. Each round of a DuelSession renders
    // an intent-matchup chip in the action log (when both sides used a tech
    // with intent_affinity). Each tech in the loadout displays its intent.
    var INTENT_META = {
      sword:   { emoji: "🗡️", color: "#9fd8ff" },
      fist:    { emoji: "👊", color: "#ffb169" },
      body:    { emoji: "🛡️", color: "#b6d680" },
      dao:     { emoji: "🌀", color: "#c997ff" },
      killing: { emoji: "🥷", color: "#ff7a8a" },
    };

    function IntentChip({ intent, size }) {
      if (!intent) return null;
      const meta = INTENT_META[intent] || { emoji: "✦", color: "var(--muted)" };
      const small = size === "sm";
      const label = safeT(`intent_name_${intent}`);
      return (
        <span style={{
          display:"inline-flex", alignItems:"center", gap:3,
          padding: small ? "1px 5px" : "2px 7px",
          borderRadius: small ? 6 : 8,
          background: "rgba(0,0,0,.35)",
          border: `1px solid ${cssHex(meta.color)}55`,
          color: meta.color, fontSize: small ? 9.5 : 10.5, lineHeight:1.1,
          fontFamily:"'Cinzel',serif", letterSpacing:.3,
        }}>
          <span>{meta.emoji}</span><span>{label}</span>
        </span>
      );
    }

    // v15.2b — Format the passive bonus block as a list of "+X% damage"-style
    // chips. Used in the IntentModal tree detail panel + TechDetailModal.
    // `bonus` is a {damage_mult, damage_reduce, armor_ignore, evasion} dict.
    function intentBonusLines(bonus) {
      if (!bonus) return [];
      const out = [];
      if (bonus.damage_mult)    out.push({ k:"damage_mult",    pct: bonus.damage_mult * 100,    label: safeT("intent_passive_damage") });
      if (bonus.damage_reduce)  out.push({ k:"damage_reduce",  pct: bonus.damage_reduce * 100,  label: safeT("intent_passive_damage_reduce") });
      if (bonus.armor_ignore)   out.push({ k:"armor_ignore",   pct: bonus.armor_ignore * 100,   label: safeT("intent_passive_armor_ignore") });
      if (bonus.evasion)        out.push({ k:"evasion",        pct: bonus.evasion * 100,        label: safeT("intent_passive_evasion") });
      return out;
    }

    function IntentTreeBar({ row, intent }) {
      // 10 nodes (R0..R9). Filled up to effective_rank, outlined for ranks
      // above effective but ≤ true_rank (capped by realm), empty for future
      // ranks. Active node = effective_rank.
      const meta = INTENT_META[intent] || {};
      const trueR = row.true_rank ?? row.rank ?? 0;
      const effR = row.effective_rank ?? trueR;
      const nodes = [];
      for (let r = 0; r <= 9; r++) {
        let fill = "transparent";
        let border = "var(--border)";
        let label = "";
        if (r <= effR) {
          fill = meta.color || "var(--gold2)";
          border = meta.color || "var(--gold2)";
        } else if (r <= trueR) {
          // Locked by realm — show outline only ("soul knows, body can't")
          fill = "transparent";
          border = meta.color || "var(--gold2)";
        } else {
          fill = "rgba(0,0,0,.4)";
          border = "var(--border)";
        }
        if (r === effR) label = "▲";
        nodes.push({ r, fill, border, label });
      }
      return (
        <div style={{ display:"grid", gap:4 }}>
          <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between",
                        gap:2, marginTop:2 }}>
            {nodes.map((n, i) => (
              <div key={i} style={{ display:"flex", alignItems:"center",
                                     flex: i === 9 ? "0 0 auto" : "1 1 auto" }}>
                <div style={{
                  width:10, height:10, borderRadius:"50%",
                  background: n.fill, border: `1.5px solid ${n.border}`,
                  flexShrink:0,
                  boxShadow: n.r === effR ? `0 0 6px ${meta.color}` : "none",
                }} />
                {i < 9 && (
                  <div style={{
                    flex:1, height:1.5, marginLeft:2, marginRight:2,
                    background: (n.r + 1) <= effR
                      ? (meta.color || "var(--gold2)")
                      : (n.r + 1) <= trueR
                        ? `${cssHex(meta.color || "var(--gold2)")}66`
                        : "var(--border)",
                  }} />
                )}
              </div>
            ))}
          </div>
          <div style={{ display:"flex", justifyContent:"space-between",
                        fontSize:8.5, color:"var(--muted)" }}>
            <span>R0</span><span>R9</span>
          </div>
        </div>
      );
    }

    function IntentMatchupChip({ info, opp }) {
      if (!info || !info.attacker_intent || !info.defender_intent) return null;
      const pct = Math.round(((info.modifier || 1) - 1) * 100);
      const sign = pct >= 0 ? "+" : "";
      const color = pct > 0 ? "var(--jade)" : pct < 0 ? "var(--red2)" : "var(--muted)";
      const am = INTENT_META[info.attacker_intent] || {};
      const dm = INTENT_META[info.defender_intent] || {};
      return (
        <div style={{
          fontSize:9.5, color:"var(--muted)", marginLeft: opp ? 14 : 14,
          lineHeight:1.1,
        }}>
          <span style={{ color: am.color || "var(--text)" }}>
            {am.emoji} {safeT(`intent_name_${info.attacker_intent}`)}
          </span>
          <span style={{ margin:"0 4px" }}>×</span>
          <span style={{ color: dm.color || "var(--text)" }}>
            {dm.emoji} {safeT(`intent_name_${info.defender_intent}`)}
          </span>
          <span style={{ color, marginLeft:6, fontWeight:600 }}>
            {pct === 0 ? safeT("intent_matchup_neutral") : `${sign}${pct}%`}
          </span>
        </div>
      );
    }

    function IntentModal({ open, onClose }) {
      const [tab, setTab] = useState("paths"); // paths | history
      const { data, loading, error } = useApi(open ? "intent/status" : null, null, [open]);
      const histReq = useApi(open && tab === "history" ? "intent/history" : null, { limit: 10 }, [open, tab]);
      const [focused, setFocused] = useState("sword");

      if (!open) return null;
      const intents = (data && data.intents) || [];
      const focusedRow = intents.find(r => r.intent === focused) || intents[0];

      const segOpts = [
        { value:"paths",   label:`⚔️ ${safeT("intent_seg_paths")}` },
        { value:"history", label:`📜 ${safeT("intent_seg_history")}` },
      ];

      return (
        <Modal open={open} onClose={onClose} title={safeT("intent_modal_title")}>
          <div style={{ display:"grid", gridTemplateColumns:"minmax(0, 1fr)", gap:11 }}>
            <SegControl options={segOpts} value={tab} onChange={setTab} />

            {error && <ErrBanner msg={error} />}
            {loading && !data && <ListSkeleton rows={5} />}

            {tab === "paths" && data && (
              <>
                {/* Lore note — Intent persists across reborn (alma > corpo) */}
                <div style={{
                  fontSize:10, color:"var(--muted)", textAlign:"center", fontStyle:"italic",
                  padding:"4px 8px", borderTop:"1px dashed var(--border)",
                  borderBottom:"1px dashed var(--border)",
                }}>
                  ✦ {safeT("intent_lore_soul_note")} ✦
                </div>

                {/* Path tiles — 5 buttons, show true_rank + effective_rank diff if capped */}
                <div style={{
                  display:"grid", gridTemplateColumns:"repeat(5, 1fr)", gap:5,
                }}>
                  {intents.map(row => {
                    const meta = INTENT_META[row.intent] || {};
                    const active = focused === row.intent;
                    const trueR = row.true_rank ?? row.rank ?? 0;
                    const effR = row.effective_rank ?? trueR;
                    const capped = trueR > effR;
                    return (
                      <button key={row.intent}
                        onClick={() => setFocused(row.intent)}
                        style={{
                          padding:"7px 4px", borderRadius:9, cursor:"pointer",
                          background: active ? `${cssHex(meta.color)}22` : "rgba(0,0,0,.25)",
                          border: active ? `1px solid ${meta.color}` : "1px solid var(--border)",
                          color: meta.color, display:"grid", gap:3,
                          textAlign:"center", lineHeight:1.1,
                        }}>
                        <div style={{ fontSize:18 }}>{meta.emoji}</div>
                        <div style={{ fontSize:9, fontFamily:"'Cinzel',serif",
                                       letterSpacing:.4, textTransform:"uppercase" }}>
                          {safeT(`intent_name_${row.intent}`)}
                        </div>
                        <div style={{ fontSize:10, color:"var(--text)", fontWeight:700 }}>
                          {capped ? `R${effR}/${trueR}` : `R${trueR}`}
                        </div>
                      </button>
                    );
                  })}
                </div>

                {/* Focused intent — tree visualization + detail card */}
                {focusedRow && (() => {
                  const trueR = focusedRow.true_rank ?? focusedRow.rank ?? 0;
                  const effR = focusedRow.effective_rank ?? trueR;
                  const capped = focusedRow.capped || (trueR > effR);
                  const meta = INTENT_META[focusedRow.intent] || {};
                  const rankName = focusedRow.rank_name
                    ? focusedRow.rank_name
                    : safeT("intent_rank_untrained");
                  const nextRankName = focusedRow.next_rank_name;
                  const bonusLines = intentBonusLines(focusedRow.passive_bonus);
                  const nextBonusLines = intentBonusLines(focusedRow.next_passive_bonus);
                  return (
                    <Card style={{ padding:"12px 13px", display:"grid", gap:9 }}>
                      <div style={{ display:"flex", alignItems:"center", gap:9 }}>
                        <div style={{ fontSize:28, lineHeight:1 }}>{meta.emoji}</div>
                        <div style={{ minWidth:0, flex:1 }}>
                          <div style={{ fontFamily:"'Cinzel',serif", fontWeight:700, fontSize:13,
                                         color:"var(--gold2)", letterSpacing:.4 }}>
                            {safeT(`intent_name_${focusedRow.intent}`)} — {rankName}
                          </div>
                          <div style={{ fontSize:10.5, color:"var(--muted)" }}>
                            {capped
                              ? safeT("intent_rank_capped", { eff: effR, tru: trueR })
                              : safeT("intent_rank_label", { rank: trueR, max: 9 })}
                          </div>
                        </div>
                      </div>

                      {/* TREE BAR (R0..R9) */}
                      <IntentTreeBar row={focusedRow} intent={focusedRow.intent} />

                      {capped && (
                        <div style={{ fontSize:10, color:"#ffc680",
                                       background:"rgba(255,198,128,.08)",
                                       border:"1px solid rgba(255,198,128,.25)",
                                       padding:"5px 8px", borderRadius:7 }}>
                          🔒 {safeT("intent_realm_cap_hint", { realm: data.realm, eff: effR, tru: trueR })}
                        </div>
                      )}

                      {/* XP bar */}
                      <div>
                        <div style={{ display:"flex", justifyContent:"space-between",
                                       fontSize:10, color:"var(--muted)", marginBottom:3 }}>
                          <span>XP</span>
                          <span>
                            {focusedRow.xp_curve > 0
                              ? `${focusedRow.xp} / ${focusedRow.xp_curve}`
                              : safeT("intent_max_rank")}
                          </span>
                        </div>
                        <div style={{ height:7, background:"rgba(0,0,0,.4)", borderRadius:4,
                                       overflow:"hidden", border:"1px solid var(--border)" }}>
                          <div style={{
                            height:"100%",
                            width: focusedRow.xp_curve > 0
                              ? `${Math.min(100, Math.round(focusedRow.xp / focusedRow.xp_curve * 100))}%`
                              : "100%",
                            background: meta.color || "var(--gold2)",
                          }}/>
                        </div>
                      </div>

                      {/* Current passive bonus */}
                      {bonusLines.length > 0 && (
                        <div style={{ display:"grid", gap:3 }}>
                          <div style={{ fontSize:10, color:"var(--gold3)", letterSpacing:.6,
                                         textTransform:"uppercase", fontFamily:"'Cinzel',serif" }}>
                            {safeT("intent_current_bonus")}
                          </div>
                          {bonusLines.map(b => (
                            <div key={b.k} style={{ fontSize:11, color:"var(--jade)" }}>
                              +{b.pct.toFixed(1)}% {b.label}
                            </div>
                          ))}
                        </div>
                      )}

                      {/* Next rank preview */}
                      {nextRankName && nextBonusLines.length > 0 && (
                        <div style={{ display:"grid", gap:3,
                                       borderTop:"1px dashed var(--border)", paddingTop:6 }}>
                          <div style={{ fontSize:10, color:"var(--muted)", letterSpacing:.6,
                                         textTransform:"uppercase", fontFamily:"'Cinzel',serif" }}>
                            {safeT("intent_next_rank", { name: nextRankName })}
                          </div>
                          {nextBonusLines.map(b => (
                            <div key={b.k} style={{ fontSize:10.5, color:"var(--muted)" }}>
                              → +{b.pct.toFixed(1)}% {b.label}
                            </div>
                          ))}
                        </div>
                      )}

                      {/* Matchup hints */}
                      <div style={{ display:"grid", gap:4, fontSize:10.5 }}>
                        <div style={{ color:"var(--jade)" }}>
                          ⬆ {safeT("intent_vs_strong")}: {(focusedRow.vs_strong || []).map(s =>
                            <IntentChip key={s} intent={s} size="sm" />)}
                        </div>
                        <div style={{ color:"var(--red2)" }}>
                          ⬇ {safeT("intent_vs_weak")}: {(focusedRow.vs_weak || []).map(s =>
                            <IntentChip key={s} intent={s} size="sm" />)}
                        </div>
                      </div>

                      <div style={{ fontSize:10.5, color:"var(--muted)", fontStyle:"italic",
                                     borderTop:"1px solid var(--border)", paddingTop:6 }}>
                        {safeT(`intent_lore_${focusedRow.intent}`)}
                      </div>
                    </Card>
                  );
                })()}
              </>
            )}

            {tab === "history" && (
              <div style={{ display:"grid", gap:6 }}>
                {histReq.loading && !histReq.data && <ListSkeleton rows={5} />}
                {histReq.data && (histReq.data.history || []).length === 0 && (
                  <div style={{ fontSize:11, color:"var(--muted)", textAlign:"center", padding:"12px 0" }}>
                    {safeT("intent_history_empty")}
                  </div>
                )}
                {histReq.data && (histReq.data.history || []).map((h, i) => {
                  const my = INTENT_META[h.my_intent] || {};
                  const opp = INTENT_META[h.opp_intent] || {};
                  const sign = (h.modifier_pct || 0) >= 0 ? "+" : "";
                  const color = h.modifier_pct > 0 ? "var(--jade)" : h.modifier_pct < 0 ? "var(--red2)" : "var(--muted)";
                  return (
                    <div key={i} style={{
                      padding:"7px 9px", borderRadius:8,
                      background:"rgba(0,0,0,.3)", border:"1px solid var(--border)",
                      display:"flex", alignItems:"center", gap:7, fontSize:10.5,
                    }}>
                      <span style={{ color: h.won ? "var(--jade)" : "var(--red2)", fontWeight:700, width:36 }}>
                        {h.won ? "WIN" : "LOSS"}
                      </span>
                      <span style={{ color: my.color || "var(--text)" }}>
                        {my.emoji || "—"} {h.my_intent ? safeT(`intent_name_${h.my_intent}`) : "—"}
                      </span>
                      <span style={{ color:"var(--muted)" }}>×</span>
                      <span style={{ color: opp.color || "var(--text)" }}>
                        {opp.emoji || "—"} {h.opp_intent ? safeT(`intent_name_${h.opp_intent}`) : "—"}
                      </span>
                      <span style={{ flex:1, textAlign:"right", color, fontWeight:600 }}>
                        {sign}{h.modifier_pct || 0}%
                      </span>
                    </div>
                  );
                })}
              </div>
            )}
          </div>
        </Modal>
      );
    }

    // ─── Combat / Arena Tab (Sprint v14.9 MA-35) ─────────────────────────────
    // 3 sub-views: Loadout (techniques) · NPC Hunt (PvE duel with stance+focus)
    // · Arena (ELO leaderboard + PvP chat hint). PvP challenge/queue stays in
    // chat (interactive accept/decline) — same decision pattern as MA-34
    // (HD/Dao redirect). Reuses `simulate_combat` + `generate_npc_fighter`
    // from core/combat_engine.py via /api/miniapp/combat/duel_npc.
    // v15.2b — Inline chip showing the player's dominant Intent + XP progress
    // + active passive bonus. Always visible on the CombatTab card so the
    // player gets continuous feedback of growth (vs. having to open the modal).
    function IntentInlineChip({ onOpen }) {
      const { data, loading } = useApi("intent/status", null, []);
      if (loading || !data) return null;
      const intents = data.intents || [];
      const dominantKey = data.dominant;
      // Fallback: show Sword R0 (or first 5-path entry) if nothing trained yet.
      const row = (dominantKey && intents.find(r => r.intent === dominantKey)) || intents[0];
      if (!row) return null;
      const meta = INTENT_META[row.intent] || {};
      const trueR = row.true_rank ?? row.rank ?? 0;
      const effR = row.effective_rank ?? trueR;
      const capped = trueR > effR;
      const rankName = row.rank_name ? row.rank_name : safeT("intent_rank_untrained");
      const xpPct = row.xp_curve > 0
        ? Math.min(100, Math.round((row.xp || 0) / row.xp_curve * 100))
        : 100;
      const bonusLines = intentBonusLines(row.passive_bonus);
      const bonusSummary = bonusLines.length
        ? bonusLines.map(b => `+${b.pct.toFixed(1)}% ${b.label}`).join(" · ")
        : safeT("intent_inline_no_bonus");
      return (
        <button onClick={onOpen} style={{
          marginTop:6, padding:"6px 9px", borderRadius:8, cursor:"pointer",
          background:`linear-gradient(180deg, ${cssHex(meta.color)}11, rgba(0,0,0,.25))`,
          border:`1px solid ${cssHex(meta.color)}44`, width:"100%", display:"grid", gap:4,
          textAlign:"left", color:"var(--text)",
        }}>
          <div style={{ display:"flex", alignItems:"center", gap:6, fontSize:11 }}>
            <span style={{ fontSize:14 }}>{meta.emoji}</span>
            <span style={{ color: meta.color, fontFamily:"'Cinzel',serif",
                            fontWeight:700, letterSpacing:.3 }}>
              {safeT(`intent_name_${row.intent}`)} — {rankName}
            </span>
            <span style={{ marginLeft:"auto", fontSize:10, color:"var(--muted)" }}>
              {capped ? `R${effR}/${trueR}` : `R${trueR}`}
            </span>
          </div>
          <div style={{ height:4, background:"rgba(0,0,0,.4)", borderRadius:3,
                         overflow:"hidden" }}>
            <div style={{ height:"100%", width:`${xpPct}%`, background: meta.color }}/>
          </div>
          <div style={{ fontSize:9.5, color:"var(--muted)",
                         whiteSpace:"nowrap", overflow:"hidden", textOverflow:"ellipsis" }}>
            {bonusSummary}
            {row.xp_curve > 0 && (
              <span style={{ float:"right" }}>
                {row.xp || 0}/{row.xp_curve} XP
              </span>
            )}
          </div>
        </button>
      );
    }

    // v15.2b — Intent block on the technique detail modal. Shows the player
    // which Yì path this technique feeds, the current rank+bonus contribution,
    // and a "use this tech to grow X intent" hook. Designed to make the
    // Intent system legible at the point of decision (picking a tech).
    function TechIntentBlock({ tech }) {
      const intent = tech.intent_affinity;
      const { data, loading } = useApi(intent ? "intent/status" : null, null, [intent]);
      if (!intent) return null;
      const meta = INTENT_META[intent] || {};
      const row = (data && (data.intents || []).find(r => r.intent === intent)) || null;
      const trueR = row ? (row.true_rank ?? row.rank ?? 0) : 0;
      const effR = row ? (row.effective_rank ?? trueR) : 0;
      const capped = row ? (row.capped || (trueR > effR)) : false;
      const rankName = row && row.rank_name ? row.rank_name : safeT("intent_rank_untrained");
      const bonusLines = row ? intentBonusLines(row.passive_bonus) : [];

      return (
        <div style={{
          padding:"9px 11px", borderRadius:7,
          background:`linear-gradient(180deg, ${cssHex(meta.color)}0F, rgba(0,0,0,.30))`,
          border:`1px solid ${cssHex(meta.color)}44`,
          display:"grid", gap:6, fontSize:11,
        }}>
          <div style={{ display:"flex", alignItems:"center", gap:8 }}>
            <span style={{ fontSize:18 }}>{meta.emoji}</span>
            <div style={{ flex:1, minWidth:0 }}>
              <div style={{ fontFamily:"'Cinzel',serif", fontWeight:700, fontSize:11.5,
                             color: meta.color, letterSpacing:.4 }}>
                {safeT("intent_tech_path_title", { path: safeT(`intent_name_${intent}`) })}
              </div>
              <div style={{ fontSize:10, color:"var(--muted)" }}>
                {row ? `${rankName} · ${capped ? `R${effR}/${trueR}` : `R${trueR}`}` : safeT("intent_rank_untrained")}
              </div>
            </div>
          </div>
          {bonusLines.length > 0 ? (
            <div style={{ display:"grid", gap:2, fontSize:10.5, color:"var(--jade)" }}>
              {bonusLines.map(b => (
                <div key={b.k}>
                  ⚡ +{b.pct.toFixed(1)}% {b.label} {safeT("intent_tech_bonus_on_this")}
                </div>
              ))}
            </div>
          ) : (
            <div style={{ fontSize:10.5, color:"var(--muted)", fontStyle:"italic" }}>
              {safeT("intent_tech_no_bonus_yet")}
            </div>
          )}
          <div style={{ fontSize:10, color:"var(--muted)", fontStyle:"italic",
                         borderTop:"1px dashed var(--border)", paddingTop:5 }}>
            🌱 {safeT("intent_tech_feeds_path", { path: safeT(`intent_name_${intent}`) })}
          </div>
        </div>
      );
    }

    function CombatTab({ player, onPlayerRefresh }) {
      const [seg, setSeg] = useState("loadout"); // loadout|npc|arena|duel
      const [reload, setReload] = useState(0);
      // v15.2 — drill-in modal for the 5 Intent paths (Sword/Fist/Body/Dao/Killing)
      const [intentOpen, setIntentOpen] = useState(false);
      const { data, loading, error } = useApi("combat/loadout", null, [reload]);
      const refreshAll = () => {
        setReload(x => x + 1);
        if (onPlayerRefresh) onPlayerRefresh();
      };

      const opts = [
        { value:"loadout", label:`📜 ${t("combat_seg_loadout")}` },
        { value:"npc",     label:`⚔️ ${t("combat_seg_npc")}` },
        { value:"arena",   label:`🏆 ${t("combat_seg_arena")}` },
        // v15.1 — turn-based PvP duel with qi consumption + simultaneous rounds
        { value:"duel",    label:`🏟️ ${t("combat_seg_duel")}` },
      ];

      // 武 2.2 — A ENTRADA ILUSTRADA. *"A aba Combate também tem que convidar a
      // jogar"* — e hoje ela abre com um ⚔️ de 30px e duas linhas de texto.
      //
      // 🔴 A ARTE É DA TÉCNICA REALMENTE EQUIPADA, e por isso ela depende da
      // peça que abre este lote: até 2026-09-23 `learned[]` mandava o nome
      // TRADUZIDO e nenhum `art_key`, e esta chapa cairia no verso em `pt` e em
      // `es` — 129 artes por língua, sem erro, sem log, com a guarda verde.
      //
      // ⚠️ A ordem é a do desempenho: a de maior Compreensão é a que o jogador
      // reconhece como "a sua". Zero equipadas ⇒ emblema neutro + *Preparar
      // artes* (o segmento `loadout`), nunca uma imagem qualquer a fingir que
      // há uma arte pronta.
      const _cenaOn = obraOn() && typeof CenaEntradaCombate === "function";
      const _cenaWide = typeof useWideShell === "function" ? useWideShell() : false;
      const _equipadas = ((data && data.techniques && data.techniques.learned) || [])
        .filter(tt => tt && tt.tech_type === "combat" && tt.is_active);
      const _aArte = _equipadas.slice().sort(
        (x, y) => (Number(y.mastery_level) || 0) - (Number(x.mastery_level) || 0))[0] || null;

      return (
        <div>
          {_cenaOn ? (
            <CenaEntradaCombate
              tecnica={_aArte}
              usados={(data && data.stats && data.stats.active_combat_count) || 0}
              max={data && data.stats ? data.stats.max_combat_slots : null}
              onEscolher={() => { haptic("select"); setSeg("npc"); }}
              onPreparar={() => { haptic("select"); setSeg("loadout"); }}
              wide={_cenaWide}
              /* 減 P7 — o estado de "equipar" vem do `/player`; o equip
                 confirmado ja' refresca-o (`refreshAll`). */
              explicacoes={player && player.explicacoes}
              onRefresh={onPlayerRefresh}
            />
          ) : null}
          {/* Header card with title + live stats. Falls back gracefully when
              the endpoint is loading; never blocks the SegControl. */}
          <Card style={{ padding:"11px 13px 9px", marginBottom:11 }}>
            {/* ⚠️ COM A CENA o cabeçalho de emoji RECOLHE — o título e o estado
                passaram para a entrada acima, e deixá-los aqui punha o mesmo
                nome duas vezes no mesmo ecrã. Os NÚMEROS ficam: Poder, Elo,
                lugares, cartel e Vida são evidência, e recolher evidência é o
                que a Lei §1 proíbe (P7 é quem recolhe explicação, nunca prova). */}
            {!_cenaOn ? (
            <div style={{ display:"flex", alignItems:"center", gap:11, marginBottom:8 }}>
              <div style={{ fontSize:30, lineHeight:1, filter:"drop-shadow(0 0 8px rgba(var(--red-rgb),.45))" }}>⚔️</div>
              <div style={{ minWidth:0, flex:1 }}>
                <div style={{ fontFamily:"'Cinzel',serif", fontWeight:700, fontSize:14,
                              color:"var(--gold2)", letterSpacing:.4 }}>
                  {t("combat_tab_title")}
                </div>
                <div style={{ fontSize:11, color:"var(--muted)", lineHeight:1.4 }}>
                  {t("combat_tab_subtitle")}
                </div>
              </div>
            </div>
            ) : null}
            <CombatHeaderStats data={data} loading={loading && !data} />
            <div style={{ marginTop:9 }}>
              <SegControl options={opts} value={seg} onChange={setSeg} />
            </div>
            {/* v15.2 — Intent drill-in (5 Wuxia paths). Full-width subtle CTA. */}
            <div style={{ marginTop:7 }}>
              <button onClick={() => setIntentOpen(true)} style={{
                width:"100%", padding:"7px 11px", borderRadius:9, cursor:"pointer",
                background:"linear-gradient(180deg, rgba(159,216,255,.10), rgba(201,151,255,.10))",
                border:"1px solid rgba(201,151,255,.35)",
                color:"var(--gold2)", fontFamily:"'Cinzel',serif", fontSize:11.5,
                letterSpacing:.5, textTransform:"uppercase", display:"flex",
                alignItems:"center", justifyContent:"center", gap:6,
              }}>
                <span>🗡️ 👊 🛡️ 🌀 🥷</span>
                <span>{safeT("intent_open_btn")}</span>
              </button>
              {/* v15.2b — always-visible inline progress chip for the dominant intent. */}
              <IntentInlineChip onOpen={() => setIntentOpen(true)} />
            </div>
          </Card>

          {error && <ErrBanner msg={error} />}
          {loading && !data && <ListSkeleton rows={5} />}
          {data && seg === "loadout" && (
            <CombatLoadoutPanel data={data} onChanged={refreshAll} reloadKey={reload} />
          )}
          {data && seg === "npc" && (
            <CombatNPCPanel data={data} onChanged={refreshAll} player={player} />
          )}
          {data && seg === "arena" && (
            <CombatArenaPanel data={data} onChanged={refreshAll} />
          )}
          {/* v15.1 — Turn-based PvP duel (qi consumption, simultaneous rounds) */}
          {data && seg === "duel" && (
            <DuelArenaPanel data={data} player={player} onChanged={refreshAll} />
          )}

          {/* v15.2 — Intent System drill-in modal. */}
          <IntentModal open={intentOpen} onClose={() => setIntentOpen(false)} />
        </div>
      );
    }

    function CombatHeaderStats({ data, loading }) {
      if (loading) {
        return (
          <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:6 }}>
            <Skel h={28} br={6} /><Skel h={28} br={6} />
            <Skel h={28} br={6} /><Skel h={28} br={6} />
          </div>
        );
      }
      if (!data) return null;
      const stats = data.stats || {};
      const arena = data.arena || {};
      // 🔴 NULL e' CHEIO, e a linha tem de dizer UMA coisa (achado do Astra,
      // 16/09; medido). Estava `hp_pct ?? 100` ao lado de `current_hp || 0`:
      // com o HP nulo a MESMA linha escrevia **zero de vida e 100%**. E' a
      // familia do `COALESCE(current_hp, 0)` que ja' inventou uma vez '69% dos
      // activos sem poder lutar' — aqui contradizia-se dentro de 40 pixels.
      const hpPct = stats.hp_pct ?? 100;
      const _maxHp = Number(stats.max_hp) || 0;
      const _curHp = (stats.current_hp === null || stats.current_hp === undefined)
        ? _maxHp : (Number(stats.current_hp) || 0);
      return (
        <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:6, fontSize:11 }}>
          <StatChip label={t("combat_stat_bp")} value={fmtNum(stats.battle_power || 0)} accent="var(--red)" />
          <StatChip label={t("combat_stat_elo")} value={`${arena.elo || 1000}`} accent="var(--gold2)" />
          <StatChip label={t("combat_stat_slots")}
                    value={`${stats.active_combat_count || 0}/${stats.max_combat_slots || 0}`}
                    accent="var(--realm-3)" />
          <StatChip label={t("combat_stat_record")
                            .replace("{wins}", arena.wins || 0)
                            .replace("{losses}", arena.losses || 0)}
                    value={`#${arena.rank || "—"}`} accent="var(--jade)" />
          <div style={{ gridColumn:"1 / -1" }}>
            <div style={{ display:"flex", justifyContent:"space-between", marginBottom:3 }}>
              <span style={{ fontSize:10, color:"var(--red2)",
                             fontFamily:"'Cinzel',serif", letterSpacing:.4, textTransform:"uppercase" }}>
                ❤️ {t("combat_stat_hp")}
              </span>
              <span style={{ fontSize:10, color:"var(--text)", fontWeight:600 }}>
                {fmtFull(_curHp)} / {fmtFull(_maxHp)} ({hpPct}%)
              </span>
            </div>
            <div style={{ height:5, borderRadius:3, background:"rgba(0,0,0,.55)", overflow:"hidden" }}>
              <div style={{ width:`${hpPct}%`, height:"100%",
                            background:"linear-gradient(90deg,#7f1d1d,#ef4444,var(--warn))",
                            transition:"width .4s ease" }} />
            </div>
          </div>
        </div>
      );
    }

    function StatChip({ label, value, accent }) {
      return (
        <div style={{
          padding:"5px 8px", borderRadius:6,
          background:"linear-gradient(180deg,rgba(var(--surface-rgb),.7),rgba(var(--surface3-rgb),.85))",
          border:`1px solid ${accent || "var(--border)"}`,
          display:"flex", justifyContent:"space-between", alignItems:"center", gap:6,
        }}>
          <span style={{ fontSize:9.5, color:"var(--muted)", fontFamily:"'Cinzel',serif",
                         letterSpacing:.4, textTransform:"uppercase",
                         whiteSpace:"nowrap", overflow:"hidden", textOverflow:"ellipsis" }}>{label}</span>
          <span style={{ fontSize:11, color: accent || "var(--text)", fontWeight:600,
                         fontFamily:"'Cinzel',serif", flexShrink:0 }}>{value}</span>
        </div>
      );
    }

    // ── Loadout Panel ──────────────────────────────────────────────────────
    function CombatLoadoutPanel({ data, onChanged, reloadKey }) {
      const [detailTech, setDetailTech] = useState(null);
      const [busyId, setBusyId] = useState(null);
      const techs = data.techniques || {};
      const learned = techs.learned || [];
      const learnable = techs.learnable || [];

      async function toggleEquip(tech) {
        if (busyId) return;
        setBusyId(tech.id);
        try {
          const res = await api("combat/equip_technique", {
            tech_id: tech.id, equip: !tech.is_active,
          });
          if (!res.ok) {
            haptic("error");
            const reasonKey = res.reason === "slots_full" ? "combat_equip_slots_full"
                            : res.reason === "realm_too_low" ? "combat_learn_realm_too_low"
                            : res.reason === "spirit_root_required" ? "combat_learn_spirit_root"
                            : res.reason === "lib_locked" ? "lib_mini_locked_toast"
                            : "combat_equip_failed";
            showToast(t(reasonKey, { max: res.max_slots, realm: res.req_realm }), "err");
            return;
          }
          haptic("success");
          showToast(tech.is_active
            ? t("combat_unequip_success", { emoji: tech.emoji, name: tech.name })
            : t("combat_equip_success", { emoji: tech.emoji, name: tech.name }));
          onChanged();
        } catch (e) {
          haptic("error");
          showToast(e.message, "err");
        } finally {
          setBusyId(null);
        }
      }

      async function learn(tech) {
        if (busyId) return;
        setBusyId(tech.id);
        try {
          const res = await api("combat/learn_technique", { tech_id: tech.id });
          if (!res.ok) {
            haptic("error");
            const map = {
              realm_too_low: t("combat_learn_realm_too_low", { realm: res.req_realm }),
              no_scroll:     t("combat_learn_no_scroll"),
              already_learned: t("combat_learn_already_known"),
              dao_required:  t("combat_learn_dao_required",
                { dao: res.dao_law_name, cur: res.current, req: res.required }),
              spirit_root_required: t("combat_learn_spirit_root"),
            };
            showToast(map[res.reason] || t("combat_learn_failed"), "err");
            return;
          }
          haptic("success");
          showToast(t("combat_learn_success", { emoji: res.emoji, name: res.name }));
          onChanged();
        } catch (e) {
          haptic("error");
          showToast(e.message, "err");
        } finally {
          setBusyId(null);
        }
      }

      const stats = data.stats || {};
      // Reorg (owner request 2026-05-20 round 2): Equipped section pinned at
      // the top — combat-typed only (the actual loadout used in fights). The
      // remaining combat techs + meditation + interior live below as
      // "Available" so the player can equip them or open detail to absorb /
      // upgrade. Reduces scroll fatigue when the player wants to swap out
      // a slot quickly.
      const equipped_combat = learned.filter(tt => tt.tech_type === "combat" && tt.is_active);
      const unequipped_combat = learned.filter(tt => tt.tech_type === "combat" && !tt.is_active);
      const meditation_techs = learned.filter(tt => tt.tech_type === "meditation");
      const interior_techs = learned.filter(tt => tt.tech_type === "interior");

      return (
        <div>
          {/* ── Equipped section (top, pinned) ───────────────────────────── */}
          {/* §2.1 2026-09-08 — com `cartas` ON esta secção deixa de ser uma
              caixa. Era o pior caso do jogo inteiro: um `<Card>` com gradiente
              de jade E borda de jade a envolver cartas que já têm contorno
              próprio — três molduras aninhadas na mesma tela (secção, carta,
              chapa de arte). Fica o cabeçalho, que é o que carrega o sentido
              ("⚔️ Equipadas 2/4" + a regra do tecto). */}
          <CardShell cards={typeof featureEnabled === "function" && featureEnabled("cartas")}
                     style={{ padding:"10px 12px 9px", marginBottom:10,
                         background:"linear-gradient(180deg,rgba(var(--jade-rgb),.06),rgba(var(--card-rgb),.95))",
                         border:"1px solid rgba(var(--jade-rgb),.32)" }}>
            <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center",
                          marginBottom:8 }}>
              <span style={{ fontFamily:"'Cinzel',serif", fontSize:12.5, color:"var(--jade)",
                             fontWeight:700, letterSpacing:.4 }}>
                ⚔️ {t("combat_equipped_section")}
              </span>
              <span style={{ fontSize:10.5, color:"var(--gold2)",
                             fontFamily:"'Cinzel',serif", letterSpacing:.5 }}>
                {t("combat_equipped_count",
                  { n: stats.active_combat_count || 0, max: stats.max_combat_slots || 0 })}
              </span>
            </div>
            {/* Track A item 6 — disclose the already-enforced loadout cap honestly. */}
            <div style={{ fontSize:10, color:"var(--muted)", fontStyle:"italic",
                          marginTop:-3, marginBottom:7 }}>
              {t("tech_loadout_cap_hint", { max: stats.max_combat_slots || 0 })}
            </div>
            {equipped_combat.length === 0 ? (
              <div style={{ textAlign:"center", padding:"14px 6px",
                            color:"var(--muted)", fontSize:11, fontStyle:"italic" }}>
                {t("combat_equipped_empty")}
              </div>
            ) : (
              (typeof featureEnabled === "function" && featureEnabled("cartas")) ? (
                <CardGrid>
                  {equipped_combat.map(tech => (
                    <EquippedRow key={tech.id} tech={tech}
                                 onUnequip={() => toggleEquip(tech)}
                                 onInfo={() => setDetailTech(tech)}
                                 busy={busyId === tech.id} />
                  ))}
                </CardGrid>
              ) : (
              <div style={{ display:"flex", flexDirection:"column", gap:6 }}>
                {equipped_combat.map(tech => (
                  <EquippedRow key={tech.id} tech={tech}
                               onUnequip={() => toggleEquip(tech)}
                               onInfo={() => setDetailTech(tech)}
                               busy={busyId === tech.id} />
                ))}
              </div>
              )
            )}
            {/* ⚔️ O GOLPE PADRÃO (report do [jogador], 10/09 09:59) — vive AQUI, e não
                na Arena, porque não é uma regra da arena: é o que as SUAS artes
                fazem quando o relógio dispara por você, em qualquer luta. O
                bloco só existe quando o servidor o manda (flag `golpe_padrao`);
                sem ele, esta secção é a de hoje, byte a byte. */}
            {data.default_strike && (
              <DefaultStrikePicker ds={data.default_strike} onChanged={onChanged} />
            )}
          </CardShell>

          {/* ── Learnable (has scroll) ───────────────────────────────────── */}
          {learnable.length > 0 && (
            <Card style={{ padding:"11px 12px 10px", marginBottom:10 }}>
              <div style={{ fontFamily:"'Cinzel',serif", fontSize:12.5, color:"var(--gold2)",
                            fontWeight:700, marginBottom:7, letterSpacing:.4 }}>
                📜 {t("combat_learnable_title")}
              </div>
              <div style={{ display:"flex", flexDirection:"column", gap:7 }}>
                {learnable.map(tech => (
                  <LearnableRow key={tech.id} tech={tech}
                                onLearn={learn} onInfo={setDetailTech} busy={busyId === tech.id} />
                ))}
              </div>
              {data.dao_locked && (
                <div style={{
                  marginTop:9, padding:"7px 9px", borderRadius:7,
                  background:"rgba(var(--realm-3-rgb),.08)",
                  border:"1px solid rgba(var(--realm-3-rgb),.32)",
                  fontSize:10.5, color:"var(--muted)", lineHeight:1.5,
                }}>
                  {t("combat_dao_lock_hint")}
                </div>
              )}
            </Card>
          )}

          {/* ── Available (other learned, not equipped) ─────────────────── */}
          {(unequipped_combat.length + meditation_techs.length + interior_techs.length > 0) && (
            <Card style={{ padding:"11px 12px 10px", marginBottom:10 }}>
              <div style={{ fontFamily:"'Cinzel',serif", fontSize:12.5, color:"var(--gold2)",
                            fontWeight:700, marginBottom:7, letterSpacing:.4 }}>
                📚 {t("combat_section_other")}
              </div>
              {unequipped_combat.length > 0 && (
                <TechSection title={t("combat_section_combat")} techs={unequipped_combat}
                             onToggle={toggleEquip} onInfo={setDetailTech} busyId={busyId} />
              )}
              {meditation_techs.length > 0 && (
                <TechSection title={t("combat_section_meditation")} techs={meditation_techs}
                             onToggle={toggleEquip} onInfo={setDetailTech} busyId={busyId} />
              )}
              {interior_techs.length > 0 && (
                <TechSection title={t("combat_section_interior")} techs={interior_techs}
                             onToggle={toggleEquip} onInfo={setDetailTech} busyId={busyId} />
              )}
            </Card>
          )}

          {/* Empty state when player has zero techs at all */}
          {learned.length === 0 && learnable.length === 0 && (
            <Card style={{ padding:"22px 14px" }}>
              <div style={{ textAlign:"center", color:"var(--muted)", fontSize:11.5, lineHeight:1.5 }}>
                {t("combat_loadout_empty")}
              </div>
            </Card>
          )}

          {/* ── TEC-2 — Destino do Pergaminho (mount-gated) ─────────────── */}
          <ScrollEconomyCard onChanged={onChanged} reloadKey={reloadKey} />

          {detailTech && (
            <TechDetailModal tech={detailTech}
                             onClose={() => setDetailTech(null)}
                             onChanged={onChanged}
                             playerStones={data.stats?.spirit_stones} />
          )}
        </div>
      );
    }

    // ── TEC-2 — Economia do Pergaminho ────────────────────────────────────
    // A arca inteira de pergaminhos com os DOIS destinos novos: doar à
    // Biblioteca da casa (contribuição — SALDO, nunca posto) e o Ritual de
    // Compreensão (XP de Intenção no caminho da própria arte). Cobre também
    // o pergaminho que NÃO se pode aprender — que até hoje não tinha ação
    // nenhuma em superfície alguma e entupia o anel para sempre (Lei §1).
    //
    // Mount-gated (padrão SectHallModal → world/sect_library): dispara o fetch
    // no mount e some inteiro quando `on` é falso — com a flag OFF a aba de
    // combate rende exatamente como hoje (OFF-identity).
    function ScrollEconomyCard({ onChanged, reloadKey }) {
      const [view, setView] = useState(null);
      const [busy, setBusy] = useState(null);
      const [open, setOpen] = useState(null);

      async function load() {
        try {
          const res = await api("combat/scrolls", {});
          setView(res && res.on ? res : { on: false });
        } catch (e) {
          setView({ on: false });
        }
      }
      // OFF-identity (review TEC-2): sem o gate do Surface Manifest o card
      // disparava um POST novo em TODO mount da aba de Combate em `main` — um
      // pedido que não existia antes desta sprint. Com a flag OFF nem o fetch
      // acontece; o servidor continua a ser a autoridade (devolve on:false).
      // QoL-Feedback 2026-07-29 Item B (report [jogador]): deps [] deixavam a lista
      // STALE após o grade-up consumir pergaminhos fora do card — queimar o
      // fantasma dava erro. `reloadKey` é o `reload` da CombatTab: todo
      // onChanged (equip/learn/grade-up) bumpa e o card refetcha junto.
      useEffect(() => {
        if (!featureEnabled("escassez_scrolls")) { setView({ on: false }); return; }
        load();
      }, [reloadKey]);

      if (!view || !view.on || !(view.scrolls || []).length) return null;

      async function act(kind, s, qty) {
        if (busy) return;
        setBusy(`${kind}:${s.tech_id}`);
        try {
          const res = await api(
            kind === "donate" ? "combat/scroll_donate" : "combat/scroll_burn",
            { tech_id: s.tech_id, qty }
          );
          if (!res || !res.ok) {
            haptic("error");
            const reason = (res && res.reason) || "";
            showToast(
              reason === "not_in_sect" ? t("scr_donate_block_sect")
              : reason === "daily_cap" ? t("scr_donate_block_cap", { cap: view.cap || 0 })
              : t("scr_stale"), "err");
            return;
          }
          haptic("success");
          if (kind === "donate") {
            // Progressão visível: o delta do saldo, sempre antes→depois (Lei §10).
            showToast(t("scr_donated_delta", {
              before: res.balance_before, after: res.balance_after, cp: res.cp_gained }));
          } else {
            showToast(res.leveled_up
              ? t("scr_burned_rankup", { intent: t(`intent_name_${res.intent}`), rank: res.rank_after })
              : t("scr_burned_delta", {
                  intent: t(`intent_name_${res.intent}`), xp: res.xp_gained,
                  before: res.rank_before, after: res.rank_after }));
          }
          setOpen(null);
          await load();
          onChanged && onChanged();
        } catch (e) {
          haptic("error");
          showToast(e.message, "err");
        } finally {
          setBusy(null);
        }
      }

      return (
        <Card style={{ padding:"11px 12px 10px", marginBottom:10 }}>
          <div style={{ fontFamily:"'Cinzel',serif", fontSize:12.5, color:"var(--gold2)",
                        fontWeight:700, marginBottom:4, letterSpacing:.4 }}>
            📜 {t("scr_title")}
          </div>
          <div style={{ fontSize:10.5, color:"var(--muted)", lineHeight:1.5, marginBottom:8 }}>
            {t("scr_intro")}
          </div>
          <div style={{ display:"flex", flexDirection:"column", gap:6 }}>
            {(view.scrolls || []).map(s => {
              const isOpen = open === s.tech_id;
              const fits = Math.max(1, Math.floor((view.headroom || 0) / Math.max(1, s.donate_cp)));
              const cap = view.max_batch || 20;
              const bulkD = Math.min(s.qty, fits, cap);
              const bulkB = Math.min(s.qty, cap);
              return (
                <div key={s.tech_id} style={{
                  padding:"8px 9px", borderRadius:8,
                  background:"rgba(var(--card-rgb),.6)",
                  border:"1px solid rgba(var(--gold2-rgb),.22)",
                }}>
                  <div onClick={() => setOpen(isOpen ? null : s.tech_id)}
                       style={{ display:"flex", alignItems:"center", gap:8, cursor:"pointer" }}>
                    <div style={{ fontSize:19, lineHeight:1, flexShrink:0 }}>{s.emoji}</div>
                    <div style={{ flex:1, minWidth:0 }}>
                      <div style={{ fontSize:12, fontWeight:600, color:"var(--text)",
                                    whiteSpace:"nowrap", overflow:"hidden", textOverflow:"ellipsis" }}>
                        {s.name}{s.learned ? " ✅" : ""}
                      </div>
                      <div style={{ fontSize:10, color:"var(--muted)" }}>
                        ×{s.qty} · {t(`scr_tier_${s.tier}`)}
                      </div>
                    </div>
                    <div style={{ fontSize:12, color:"var(--gold2)", flexShrink:0 }}>
                      {isOpen ? "▾" : "▸"}
                    </div>
                  </div>
                  {isOpen && (
                    <div style={{ marginTop:8, display:"flex", flexDirection:"column", gap:6 }}>
                      <div style={{ fontSize:10.5, color:"var(--muted)", lineHeight:1.5 }}>
                        {t("scr_donate_head", { cp: s.donate_cp })}
                      </div>
                      {s.can_donate ? (
                        <div style={{ display:"flex", gap:6 }}>
                          <ActionBtn variant="primary" disabled={!!busy}
                                     onClick={() => act("donate", s, 1)}
                                     style={{ flex:1, padding:"8px 10px", fontSize:11.5 }}>
                            {t("scr_btn_donate_one", { cp: s.donate_cp })}
                          </ActionBtn>
                          {bulkD > 1 && (
                            <ActionBtn variant="primary" disabled={!!busy}
                                       onClick={() => act("donate", s, bulkD)}
                                       style={{ flex:1, padding:"8px 10px", fontSize:11.5 }}>
                              {t("scr_btn_donate_all", { n: bulkD, cp: s.donate_cp * bulkD })}
                            </ActionBtn>
                          )}
                        </div>
                      ) : (
                        <div style={{ fontSize:10.5, color:"var(--muted)", fontStyle:"italic" }}>
                          {s.donate_block === "no_sect"
                            ? t("scr_donate_block_sect")
                            : t("scr_donate_block_cap", { cap: view.cap || 0 })}
                        </div>
                      )}
                      <div style={{ fontSize:10.5, color:"var(--muted)", lineHeight:1.5, marginTop:2 }}>
                        {t("scr_burn_head", { xp: s.burn_xp,
                                              intent: t(`intent_name_${s.burn_intent}`) })}
                        {s.burn_dao ? " " + t("scr_burn_dao", { n: s.burn_dao }) : ""}
                      </div>
                      <div style={{ display:"flex", gap:6 }}>
                        <ActionBtn disabled={!!busy}
                                   onClick={() => act("burn", s, 1)}
                                   style={{ flex:1, padding:"8px 10px", fontSize:11.5 }}>
                          {t("scr_btn_burn_one", { xp: s.burn_xp })}
                        </ActionBtn>
                        {bulkB > 1 && (
                          <ActionBtn disabled={!!busy}
                                     onClick={() => act("burn", s, bulkB)}
                                     style={{ flex:1, padding:"8px 10px", fontSize:11.5 }}>
                            {t("scr_btn_burn_all", { n: bulkB, xp: s.burn_xp * bulkB })}
                          </ActionBtn>
                        )}
                      </div>
                    </div>
                  )}
                </div>
              );
            })}
          </div>
          <div style={{ marginTop:8, fontSize:10, color:"var(--muted)", fontStyle:"italic",
                        lineHeight:1.5 }}>
            {view.in_sect
              ? t("scr_balance_line", { balance: view.balance || 0, headroom: view.headroom || 0 })
              : t("scr_no_sect_hint")}
          </div>
        </Card>
      );
    }

    // Compact equipped chip — emphasises Tirar (unequip) action; tap card body
    // for ℹ️ detail (where absorb / grade upgrade live).
    // 牌 — ⚠️ ACHADO DE OLHAR (2026-09-05): o ramo `is_active` do `LearnedRow`
    // era CÓDIGO MORTO. A aba separa as artes em duas listas e as equipadas
    // nunca passam por lá — vêm para aqui. Ou seja: o selo 朱砂, que é a marca
    // do estado activo e uma das três razões de a carta existir, não aparecia
    // em sítio nenhum do jogo. Nenhum teste podia apanhá-lo (ambos os ramos
    // rendem); só a tela o diz.
    function EquippedRow({ tech, onUnequip, onInfo, busy }) {
      const cardsOn = typeof featureEnabled === "function" && featureEnabled("cartas");
      if (cardsOn) {
        return (
          <NivraelCard
            kind="technique" rank={tech.grade}
            glyph={tech.emoji}
            art={pieceArt("technique", tech.name, tech.art_key)}
            name={tech.name}
            eyebrow={t("combat_tech_type_" + (tech.tech_type || "combat"))}
            state="active"
            stateLabel={t("combat_tech_status_equipped")}
            onClick={onInfo}
            effect={(
              <span>
                {tech.mastery_emoji} ×{tech.mastery_mult}
                {tech.grade !== "common" && (
                  <> · <span style={{ color:"var(--gold3)" }}>×{tech.grade_mult}</span></>
                )}
                {tech.owned_scroll_qty > 0 && (
                  <> · <span style={{ color:"var(--gold2)" }}>📜×{tech.owned_scroll_qty}</span></>
                )}
              </span>
            )}
            foot={tech.intent_affinity
              ? <IntentChip intent={tech.intent_affinity} size="sm" />
              : <span />}
            actions={(
              <div style={{ display:"flex", gap:6 }}>
                <ActionBtn variant="ghost"
                           onClick={(e) => { e.stopPropagation(); onInfo(); }}
                           style={{ padding:"6px 10px", fontSize:11 }}>ℹ️</ActionBtn>
                <ActionBtn variant="danger" disabled={busy}
                           onClick={(e) => { e.stopPropagation(); onUnequip(); }}
                           style={{ flex:1, padding:"6px 8px", fontSize:11 }}>
                  {t("combat_unequip_quick")}
                </ActionBtn>
              </div>
            )}
          />
        );
      }
      return EquippedRowClassic({ tech, onUnequip, onInfo, busy });
    }

    function EquippedRowClassic({ tech, onUnequip, onInfo, busy }) {
      // 武 2.2 — A CONSISTÊNCIA, e ela é o motivo desta linha existir.
      //
      // 🔴 *"A inconsistência é pior do que a ausência"* (Lei 0): com a obra
      // ligada, a ENTRADA da aba mostra a arte da arte equipada e a tira de
      // preparo mostra as quatro — e esta lista, logo abaixo, continuava a
      // mostrar um emoji de 22px da MESMA peça. A arte da carta só chega com
      // `cartas` ON, que é uma decisão separada do owner e ortogonal por
      // desenho; portanto a linha clássica ganha a cara da peça aqui.
      //
      // ⚠️ Pelo `PieceIcon`, que é o dono Único de *"mostra-me esta peça"* desde
      // 2026-09-10 — nunca um segundo caminho. Ele leva o verso honesto, o
      // `onError` e o `lazy` de graça; um caminho próprio deixaria a pilula e o
      // artefacto três dias atrás, como já aconteceu uma vez.
      const _faceOn = obraOn() && typeof PieceIcon === "function";
      return (
        <div style={{
          padding:"7px 9px", borderRadius:8,
          background:"linear-gradient(180deg,rgba(var(--jade-rgb),.10),rgba(20,30,30,.6))",
          border:"1px solid rgba(var(--jade-rgb),.45)",
          display:"flex", alignItems:"center", gap:8,
        }}>
          <div onClick={onInfo} style={{ display:"flex", alignItems:"center", gap:8,
                                          flex:1, minWidth:0, cursor:"pointer" }}>
            {_faceOn ? (
              <PieceIcon kind="technique" name={tech.name} artKey={tech.art_key}
                         emoji={tech.emoji} size={34} radius={4}
                         accent="var(--jade)" />
            ) : (
            <div style={{ fontSize:22, lineHeight:1, flexShrink:0,
                          filter:"drop-shadow(0 0 5px rgba(var(--jade-rgb),.45))" }}>
              {tech.emoji}
            </div>
            )}
            <div style={{ flex:1, minWidth:0 }}>
              <div style={{ fontSize:12, fontWeight:600, color:"var(--text)",
                            whiteSpace:"nowrap", overflow:"hidden", textOverflow:"ellipsis" }}>
                {tech.name}
              </div>
              <div style={{ fontSize:10, color:"var(--muted)", marginTop:1 }}>
                {tech.mastery_emoji} ×{tech.mastery_mult}
                {tech.grade !== "common" && (
                  <> · <span style={{ color:"var(--gold3)" }}>
                    {tech.grade_emoji} ×{tech.grade_mult}
                  </span></>
                )}
                {tech.owned_scroll_qty > 0 && (
                  <> · <span style={{ color:"var(--gold2)" }}>
                    📜×{tech.owned_scroll_qty}
                  </span></>
                )}
              </div>
            </div>
          </div>
          <button onClick={onInfo}
                  style={{
                    background:"rgba(var(--gold2-rgb),.12)",
                    border:"1px solid rgba(var(--gold2-rgb),.32)",
                    color:"var(--gold2)", borderRadius:6,
                    padding:"5px 8px", fontSize:11, cursor:"pointer", flexShrink:0,
                  }}>ℹ️</button>
          <button onClick={onUnequip} disabled={busy}
                  style={{
                    background:"rgba(var(--red-rgb),.14)",
                    border:"1px solid rgba(var(--red-rgb),.4)",
                    color:"var(--red2)", borderRadius:6, padding:"5px 9px",
                    fontSize:10.5, cursor: busy ? "default" : "pointer", flexShrink:0,
                    fontFamily:"'Cinzel',serif", letterSpacing:.3,
                    opacity: busy ? .5 : 1,
                  }}>{t("combat_unequip_quick")}</button>
        </div>
      );
    }

    function TechSection({ title, techs, onToggle, onInfo, busyId }) {
      // 牌 — uma CARTA numa coluna de largura toda vira um poster: a chapa de
      // arte fica 4:3 sobre 366px e cada arte come um ecrã inteiro. Foi o
      // primeiro defeito que servir-e-olhar apanhou (2026-09-05). A grelha é a
      // forma da carta; a coluna era a forma da linha.
      const cardsOn = typeof featureEnabled === "function" && featureEnabled("cartas");
      const rows = techs.map(tech => (
        <LearnedRow key={tech.id} tech={tech}
                    onToggle={onToggle} onInfo={onInfo} busy={busyId === tech.id} />
      ));
      return (
        <div style={{ marginBottom:8 }}>
          <div style={{ fontSize:10.5, color:"var(--muted)", fontFamily:"'Cinzel',serif",
                        letterSpacing:.5, textTransform:"uppercase", margin:"6px 0 6px" }}>
            {title}
          </div>
          {cardsOn ? <CardGrid>{rows}</CardGrid> : (
            <div style={{ display:"flex", flexDirection:"column", gap:6 }}>{rows}</div>
          )}
        </div>
      );
    }

    // 牌 A CARTA — a técnica é "a carta mais importante do jogo" (o owner:
    // *"no final tens 8 técnicas, e cada uma pesa"*). Com a flag `cartas` OFF
    // isto chama `LearnedRowClassic`, que é o markup de hoje BYTE A BYTE.
    //
    // ⚠️ A carta não perde nada da linha antiga — cada peça tem casa:
    //   emoji → o glifo do verso · nome → o nome · tipo → a sobrancelha ·
    //   grau → o LOMBO + a palavra · compreensão ×mult e XP → o efeito ·
    //   intenção → o pé · equipada/trancada → o estado (+ selo) ·
    //   os dois botões → as acções.
    function LearnedRow({ tech, onToggle, onInfo, busy }) {
      const cardsOn = typeof featureEnabled === "function" && featureEnabled("cartas");
      if (!cardsOn) return <LearnedRowClassic tech={tech} onToggle={onToggle} onInfo={onInfo} busy={busy} />;

      const equipped = !!tech.is_active;
      const locked = !!tech.lib_locked && !equipped;
      const xp = tech.next_mastery_xp != null
        ? t("combat_tech_xp_progress", { cur: tech.mastery_xp, nxt: tech.next_mastery_xp })
        : t("combat_tech_xp_maxed");
      return (
        <NivraelCard
          kind="technique" rank={tech.grade}
          glyph={tech.emoji}
          // A arte, quando existe. O slug deriva do nome do catálogo; uma peça
          // ainda sem ilustração devolve `null` e cai no VERSO — que é o estado
          // de 119 das 129 técnicas hoje, e por isso o verso veio primeiro.
          art={pieceArt("technique", tech.name, tech.art_key)}
          name={tech.name}
          eyebrow={t("combat_tech_type_" + (tech.tech_type || "combat"))}
          state={equipped ? "active" : locked ? "locked" : "owned"}
          stateLabel={equipped ? t("combat_tech_status_equipped")
                               : locked ? t("lib_mini_locked_row") : null}
          effect={(
            <span>
              {tech.mastery_emoji} ×{tech.mastery_mult} · {xp}
              {tech.grade !== "common" && (
                <> · <span style={{ color:"var(--gold3)" }}>×{tech.grade_mult}</span></>
              )}
            </span>
          )}
          foot={(
            <>
              {tech.intent_affinity
                ? <IntentChip intent={tech.intent_affinity} size="sm" />
                : <span />}
              <span style={{ color: equipped ? "var(--jade)" : "var(--muted2)" }}>
                {equipped ? t("combat_tech_status_equipped") : t("combat_tech_status_unequipped")}
              </span>
            </>
          )}
          actions={(
            <div style={{ display:"flex", gap:6 }}>
              {locked ? (
                <div style={{ flex:1, padding:"6px 8px", fontSize:10.5, textAlign:"center",
                              color:"var(--muted)", border:"1px dashed rgba(255,156,156,.35)",
                              borderRadius:8 }}>
                  🔒 {t("lib_mini_locked_row")}
                </div>
              ) : (
                <ActionBtn variant={equipped ? "ghost" : "primary"}
                           disabled={busy}
                           onClick={() => onToggle(tech)}
                           style={{ flex:1, padding:"6px 8px", fontSize:11 }}>
                  {equipped ? t("combat_tech_btn_unequip") : t("combat_tech_btn_equip")}
                </ActionBtn>
              )}
              <ActionBtn variant="ghost"
                         onClick={() => { onInfo(tech); }}
                         style={{ padding:"6px 10px", fontSize:11 }}>
                ℹ️
              </ActionBtn>
            </div>
          )}
        />
      );
    }

    function LearnedRowClassic({ tech, onToggle, onInfo, busy }) {
      // 武 2.2 — a mesma cara, pelo mesmo dono. Ver `EquippedRowClassic`.
      const _faceOn = obraOn() && typeof PieceIcon === "function";
      const equipped = !!tech.is_active;
      const xp = tech.next_mastery_xp != null
        ? t("combat_tech_xp_progress", { cur: tech.mastery_xp, nxt: tech.next_mastery_xp })
        : t("combat_tech_xp_maxed");
      return (
        <div style={{
          padding:"7px 9px", borderRadius:8,
          background: equipped
            ? "linear-gradient(180deg,rgba(var(--jade-rgb),.06),rgba(20,30,30,.55))"
            : "linear-gradient(180deg,rgba(var(--surface-rgb),.55),rgba(var(--surface3-rgb),.75))",
          border: `1px solid ${equipped ? "rgba(var(--jade-rgb),.32)" : "rgba(var(--glow-rgb),.22)"}`,
        }}>
          <div style={{ display:"flex", alignItems:"center", gap:8 }}>
            {_faceOn ? (
              <PieceIcon kind="technique" name={tech.name} artKey={tech.art_key}
                         emoji={tech.emoji} size={34} radius={4}
                         accent={equipped ? "var(--jade)" : "var(--gold2)"} />
            ) : (
            <div style={{ fontSize:22, lineHeight:1, flexShrink:0 }}>{tech.emoji}</div>
            )}
            <div style={{ flex:1, minWidth:0 }}>
              <div style={{ display:"flex", justifyContent:"space-between", alignItems:"baseline", gap:4 }}>
                <span style={{ fontSize:12, color:"var(--text)", fontWeight:600,
                               whiteSpace:"nowrap", overflow:"hidden", textOverflow:"ellipsis" }}>
                  {tech.name}
                </span>
                <span style={{ fontSize:9.5, color: equipped ? "var(--jade)" : "var(--muted)",
                               fontFamily:"'Cinzel',serif", letterSpacing:.4, flexShrink:0 }}>
                  {equipped ? t("combat_tech_status_equipped") : t("combat_tech_status_unequipped")}
                </span>
              </div>
              <div style={{ fontSize:10, color:"var(--muted)", marginTop:2,
                             display:"flex", alignItems:"center", gap:5, flexWrap:"wrap" }}>
                <span>
                  {tech.mastery_emoji} ×{tech.mastery_mult} · {xp}
                  {tech.grade !== "common" && (
                    <> · <span style={{ color:"var(--gold3)" }}>
                      {tech.grade_emoji} ×{tech.grade_mult}
                    </span></>
                  )}
                </span>
                {/* v15.2 — intent affinity chip per tech (NULL → none rendered) */}
                {tech.intent_affinity && (
                  <IntentChip intent={tech.intent_affinity} size="sm" />
                )}
              </div>
            </div>
          </div>
          <div style={{ display:"flex", gap:6, marginTop:6 }}>
            {/* TEC-1 — arte do Núcleo de outra casa: LOCKADA (cross-sect §3).
                `lib_locked` só existe com biblioteca_seitas ON (chave
                condicional) → main rende exatamente como antes. */}
            {tech.lib_locked && !equipped ? (
              <div style={{ flex:1, padding:"6px 8px", fontSize:10.5, textAlign:"center",
                            color:"var(--muted)", border:"1px dashed rgba(255,156,156,.35)",
                            borderRadius:8 }}>
                🔒 {t("lib_mini_locked_row")}
              </div>
            ) : (
              <ActionBtn variant={equipped ? "ghost" : "primary"}
                         disabled={busy}
                         onClick={() => onToggle(tech)}
                         style={{ flex:1, padding:"6px 8px", fontSize:11 }}>
                {equipped ? t("combat_tech_btn_unequip") : t("combat_tech_btn_equip")}
              </ActionBtn>
            )}
            <ActionBtn variant="ghost"
                       onClick={() => { onInfo(tech); }}
                       style={{ padding:"6px 10px", fontSize:11 }}>
              ℹ️
            </ActionBtn>
          </div>
        </div>
      );
    }

    function LearnableRow({ tech, onLearn, onInfo, busy }) {
      const canLearn = !!tech.can_learn;
      const reqRealmName = realmName(tech.req_realm || 0);
      return (
        <div style={{
          padding:"7px 9px", borderRadius:8,
          background:"linear-gradient(180deg,rgba(var(--surface-rgb),.55),rgba(var(--surface3-rgb),.75))",
          border:"1px solid rgba(var(--glow-rgb),.22)",
          opacity: canLearn ? 1 : .8,
        }}>
          <div style={{ display:"flex", alignItems:"center", gap:8 }}>
            {itemVivoOn()
              ? <PieceIcon kind="technique" name={tech.name} artKey={tech.art_key} emoji={tech.emoji}
                           size={34} accent="var(--gold2)" radius={6} dim={!canLearn} />
              : <div style={{ fontSize:22, lineHeight:1, flexShrink:0,
                          filter: canLearn ? "none" : "grayscale(.45)" }}>{tech.emoji}</div>}
            <div style={{ flex:1, minWidth:0 }}>
              <div style={{ fontSize:12, color:"var(--text)", fontWeight:600,
                            whiteSpace:"nowrap", overflow:"hidden", textOverflow:"ellipsis" }}>
                {tech.name}
              </div>
              <div style={{ fontSize:10, color:"var(--muted)", marginTop:2 }}>
                {t("combat_learnable_realm_req", { realm: reqRealmName })}
                {" · "}
                <span style={{ color: tech.has_scroll ? "var(--jade)" : "var(--red)" }}>
                  {tech.has_scroll ? t("combat_learnable_has_scroll") : t("combat_learnable_no_scroll")}
                </span>
                {tech.dao && (
                  <> · {tech.dao.met
                    ? t("combat_learnable_dao_met", { emoji: tech.dao.law_emoji, law: tech.dao.law_name })
                    : t("combat_learnable_dao_req", {
                        emoji: tech.dao.law_emoji, law: tech.dao.law_name,
                        cur: tech.dao.current, req: tech.dao.required,
                      })}</>
                )}
              </div>
            </div>
          </div>
          <div style={{ display:"flex", gap:6, marginTop:6 }}>
            <ActionBtn variant={canLearn ? "primary" : "ghost"}
                       disabled={!canLearn || busy}
                       onClick={() => onLearn(tech)}
                       style={{ flex:1, padding:"6px 8px", fontSize:11 }}>
              {t("combat_learnable_btn_learn")}
            </ActionBtn>
            <ActionBtn variant="ghost"
                       onClick={() => onInfo(tech)}
                       style={{ padding:"6px 10px", fontSize:11 }}>
              ℹ️
            </ActionBtn>
          </div>
        </div>
      );
    }

    // Rich detail modal — owner round 2 (2026-05-20): the previous version
    // showed only "Type: Combat" cropped behind the modal frame. Now structured
    // with Description / Mastery progress / Grade chain / Scrolls (absorb 1
    // or all) / Grade upgrade (with reqs preview) / Effect / Requirements.
    // Only learned techs get the absorb/upgrade sections; unlearnable
    // techs (from the Learnable list) skip those blocks.
    function TechDetailModal({ tech, onClose, onChanged, playerStones }) {
      const [busy, setBusy] = useState(null); // null | "absorb1" | "absorbAll" | "upgrade"
      const isLearned = tech.mastery_level != null;
      const typeLabel = t(`combat_tech_type_${tech.tech_type || "combat"}`);
      const reqRealmName = realmName(tech.req_realm || 0);

      // Track A item 6 — the Compreensão ladder (reframe of the live mastery axis).
      const stages = [
        { lvl: 1, name: t("technique_mastery_stage_1") || "Vislumbre", emoji: "🔰" },
        { lvl: 2, name: t("technique_mastery_stage_2") || "Pequeno Sucesso", emoji: "⭐", req: 100 },
        { lvl: 3, name: t("technique_mastery_stage_3") || "Grande Sucesso", emoji: "🌟", req: 500 },
        { lvl: 4, name: t("technique_mastery_stage_4") || "Perfeição", emoji: "💎", req: 2000 },
        { lvl: 5, name: t("technique_mastery_stage_5") || "Consumação", emoji: "🌸", req: 10000 },
      ];

      // Mastery progress bar — % to next stage.
      let masteryPct = 100;
      let masteryLabel = t("combat_detail_mastery_max",
        { emoji: tech.mastery_emoji || "🌸", mult: tech.mastery_mult || 1 });
      if (isLearned && tech.next_mastery_xp != null) {
        const cur = tech.mastery_xp || 0;
        const tgt = tech.next_mastery_xp;
        const prevReq = stages[(tech.mastery_level || 1) - 1]?.req || 0;
        const span = Math.max(1, tgt - prevReq);
        const into = Math.max(0, cur - prevReq);
        masteryPct = Math.min(100, Math.round((into / span) * 100));
        masteryLabel = t("combat_tech_xp_progress", { cur, nxt: tgt });
      }

      // Grade upgrade requirements preview.
      const u = tech.upgrade;
      const grades_pt = {
        common:"Comum", refined:"Refinado", perfected:"Perfeito",
        transcendent:"Transcendente", celestial:"Celestial",
      };
      const nextGradeName = u ? (t(`technique_grade_${u.next_grade}`) || grades_pt[u.next_grade] || u.next_grade) : null;
      const nextGradeEmojis = {
        common:"⬜", refined:"🟩", perfected:"🟦", transcendent:"🟪", celestial:"🟨",
      };
      const nextGradeEmoji = u ? nextGradeEmojis[u.next_grade] : "";
      const nextGradeMults = { common:1.0, refined:1.2, perfected:1.5, transcendent:2.0, celestial:3.0 };
      const nextMult = u ? nextGradeMults[u.next_grade] : 1;
      const stones = (typeof playerStones === "number") ? playerStones : null;
      const ownedScrolls = tech.owned_scroll_qty || 0;
      const upgradeBlocked = u && (
        !u.ready
        || (u.stones > 0 && stones != null && stones < u.stones)
        || (u.scrolls > 0 && ownedScrolls < u.scrolls)
      );

      async function absorb(all) {
        if (busy) return;
        setBusy(all ? "absorbAll" : "absorb1");
        try {
          const res = await api("combat/absorb_scroll", {
            tech_id: tech.id, all,
          });
          if (!res.ok) {
            haptic("error");
            const map = {
              no_scroll: t("combat_absorb_no_scroll"),
              not_learned: t("combat_absorb_failed"),
            };
            showToast(map[res.reason] || t("combat_absorb_failed"), "err");
            return;
          }
          haptic("success");
          let msg = t("combat_absorb_success",
            { emoji: res.emoji || tech.emoji, name: res.name || tech.name, xp: res.xp_gained });
          if ((res.levelups || []).length > 0) {
            const last = res.levelups[res.levelups.length - 1];
            msg += " · " + t("combat_absorb_levelup",
              { lvl: last.new_level, mult: last.new_mult });
          }
          showToast(msg);
          if (onChanged) onChanged();
          onClose();
        } catch (e) {
          haptic("error");
          showToast(e.message, "err");
        } finally {
          setBusy(null);
        }
      }

      async function upgradeGrade() {
        if (busy) return;
        setBusy("upgrade");
        try {
          const res = await api("combat/grade_upgrade", { tech_id: tech.id });
          if (!res.ok) {
            haptic("error");
            const map = {
              max_grade:           t("combat_grade_upgrade_max"),
              mastery_too_low:     t("combat_grade_upgrade_mastery", { n: res.required_mastery }),
              insufficient_stones: t("combat_grade_upgrade_stones",  { n: res.cost }),
              insufficient_scrolls:t("combat_grade_upgrade_scrolls", { n: res.cost }),
              missing_pill:        t("combat_grade_upgrade_pill",    { pill: res.pill }),
              needs_tribulation:   t("combat_grade_upgrade_trib"),
            };
            showToast(map[res.reason] || t("combat_grade_upgrade_failed"), "err");
            return;
          }
          haptic("success");
          // QoL-Feedback 2026-07-29 Item B (Lei §10): antes→depois do grau
          // quando o payload traz old_grade; fallback = mensagem antiga.
          showToast(res.old_grade
            ? t("combat_grade_upgrade_delta",
                { emoji: res.emoji, name: res.name,
                  old_grade_emoji: res.old_grade_emoji,
                  old_grade: t(`technique_grade_${res.old_grade}`) || res.old_grade,
                  old_mult: res.old_grade_mult,
                  grade_emoji: res.new_grade_emoji,
                  grade: t(`technique_grade_${res.new_grade}`) || res.new_grade,
                  mult: res.new_grade_mult })
            : t("combat_grade_upgrade_success",
                { emoji: res.emoji, name: res.name,
                  grade_emoji: res.new_grade_emoji, grade: t(`technique_grade_${res.new_grade}`) || res.new_grade,
                  mult: res.new_grade_mult }));
          if (onChanged) onChanged();
          onClose();
        } catch (e) {
          haptic("error");
          showToast(e.message, "err");
        } finally {
          setBusy(null);
        }
      }

      return (
        <Modal onClose={onClose} title={`${tech.emoji} ${tech.name}`}
               accent="rgba(var(--gold2-rgb),.55)" maxWidth={420} zIndex={70}>
          <div style={{ display:"flex", flexDirection:"column", gap:10, fontSize:12 }}>
            {/* Top chip strip — type + grade + scroll count badges */}
            <div style={{ display:"flex", flexWrap:"wrap", gap:5 }}>
              <span style={{ fontSize:10, padding:"3px 8px", borderRadius:5,
                             background:"rgba(var(--glow-rgb),.18)", border:"1px solid rgba(var(--glow-rgb),.4)",
                             color:"var(--text)", fontFamily:"'Cinzel',serif", letterSpacing:.4 }}>
                {typeLabel}
              </span>
              {isLearned && (
                <span style={{ fontSize:10, padding:"3px 8px", borderRadius:5,
                               background:"rgba(var(--gold2-rgb),.16)", border:"1px solid rgba(var(--gold2-rgb),.4)",
                               color:"var(--gold3)", fontFamily:"'Cinzel',serif", letterSpacing:.4 }}>
                  {tech.grade_emoji || "⬜"} {t(`technique_grade_${tech.grade}`) || tech.grade} ×{tech.grade_mult}
                </span>
              )}
              {ownedScrolls > 0 && (
                <span style={{ fontSize:10, padding:"3px 8px", borderRadius:5,
                               background:"rgba(var(--jade-rgb),.16)", border:"1px solid rgba(var(--jade-rgb),.4)",
                               color:"var(--jade)", fontFamily:"'Cinzel',serif", letterSpacing:.4 }}>
                  📜 ×{ownedScrolls}
                </span>
              )}
            </div>

            {/* Description */}
            <div style={{ padding:"9px 11px", borderRadius:7,
                          background:"rgba(0,0,0,.35)", border:"1px dashed rgba(var(--gold2-rgb),.22)",
                          fontSize:11.5, color:"var(--text)", lineHeight:1.55 }}>
              📖 {tech.description || t("combat_tech_detail_no_desc")}
            </div>

            {/* v15.2b — Intent affinity panel: shows which Yì this tech feeds,
                what passive bonus the player currently gets on THIS tech, and
                the lore hook for the path. Only renders when tech has an affinity. */}
            {tech.intent_affinity && <TechIntentBlock tech={tech} />}

            {/* Mastery progress (only for learned) */}
            {isLearned && (
              <div>
                <div style={{ fontSize:10.5, color:"var(--gold2)",
                              fontFamily:"'Cinzel',serif", letterSpacing:.5,
                              textTransform:"uppercase", marginBottom:4 }}>
                  {t("combat_detail_mastery_progress")}
                </div>
                <div style={{ fontSize:11, color:"var(--text)", marginBottom:5 }}>
                  {tech.mastery_emoji} {t(`technique_mastery_stage_${tech.mastery_level}`) || `Lv ${tech.mastery_level}`}
                  <span style={{ marginLeft:6, color:"var(--gold3)", fontWeight:600 }}>×{tech.mastery_mult}</span>
                  <span style={{ marginLeft:8, color:"var(--muted)", fontSize:10.5 }}>{masteryLabel}</span>
                </div>
                <ProgressBar pct={masteryPct} variant="cult" height={6} />
                {/* 内功 (report do [jogador] 2026-08-11) — DIZER como esta arte ganha
                    Compreensão. Para as internas/de meditação a única fonte era
                    absorver um pergaminho repetido e nenhuma tela o dizia: o
                    jogador concluía, com razão, que não havia como ganhar XP.
                    `gain_hint` é server-resolved (a MESMA frase do chat) —
                    imprimir CRU, nunca por t(). */}
                {tech.gain_hint && (
                  <div style={{ fontSize:10, color:"var(--muted)", marginTop:5, lineHeight:1.45 }}>
                    {tech.gain_hint}
                  </div>
                )}
              </div>
            )}

            {/* Track A item 6 — Art↔Root resonance (flavor only, zero modifier).
                Renders only when the art's element is a Wuxing element the player's
                root carries (server resolves tech.root_resonance). */}
            {tech.root_resonance && (
              <div style={{ marginTop:2, padding:"7px 9px", borderRadius:7,
                            background:"rgba(var(--gold2-rgb),.05)",
                            border:"1px dashed rgba(var(--gold2-rgb),.22)" }}>
                <div style={{ fontSize:11, color:"var(--text)" }}>
                  {tech.root_resonance.emoji}{" "}
                  {t("tech_root_resonance", { element: t(`root_el_${tech.root_resonance.element}`) })}
                </div>
                <div style={{ fontSize:10, color:"var(--muted)", fontStyle:"italic", marginTop:3 }}>
                  {t("tech_root_resonance_future")}
                </div>
              </div>
            )}

            {/* Scrolls section — only if learned + has scrolls */}
            {isLearned && (
              <div>
                <div style={{ fontSize:10.5, color:"var(--gold2)",
                              fontFamily:"'Cinzel',serif", letterSpacing:.5,
                              textTransform:"uppercase", marginBottom:4 }}>
                  {t("combat_detail_scrolls_section")}
                </div>
                {ownedScrolls > 0 ? (
                  <>
                    <div style={{ fontSize:11, color:"var(--muted)", marginBottom:6 }}>
                      {t("combat_detail_scrolls_count",
                        { n: ownedScrolls, xp: tech.absorb_xp_per_scroll || 0 })}
                    </div>
                    <div style={{ display:"flex", gap:6 }}>
                      <ActionBtn variant="primary"
                                 disabled={!!busy}
                                 onClick={() => absorb(false)}
                                 style={{ flex:1, padding:"8px 10px", fontSize:11.5 }}>
                        {t("combat_detail_btn_absorb_one")}
                      </ActionBtn>
                      {ownedScrolls > 1 && (
                        <ActionBtn variant="primary"
                                   disabled={!!busy}
                                   onClick={() => absorb(true)}
                                   style={{ flex:1, padding:"8px 10px", fontSize:11.5 }}>
                          {t("combat_detail_btn_absorb_all", { n: ownedScrolls })}
                        </ActionBtn>
                      )}
                    </div>
                  </>
                ) : (
                  <div style={{ fontSize:10.5, color:"var(--muted)", fontStyle:"italic" }}>
                    {t("combat_detail_no_scrolls")}
                  </div>
                )}
              </div>
            )}

            {/* Grade chain — only for learned */}
            {isLearned && (
              <div>
                <div style={{ fontSize:10.5, color:"var(--gold2)",
                              fontFamily:"'Cinzel',serif", letterSpacing:.5,
                              textTransform:"uppercase", marginBottom:4 }}>
                  {t("combat_detail_grade_chain")}
                </div>
                <div style={{ fontSize:11, color:"var(--text)", marginBottom:6 }}>
                  {t("combat_detail_grade_current",
                    { emoji: tech.grade_emoji || "⬜",
                      name: t(`technique_grade_${tech.grade}`) || tech.grade,
                      mult: tech.grade_mult || 1 })}
                </div>
                {!u && (
                  <div style={{ fontSize:10.5, color:"var(--muted)", fontStyle:"italic" }}>
                    {t("combat_detail_grade_max")}
                  </div>
                )}
                {u && (
                  <>
                    <div style={{ fontSize:11, color:"var(--gold3)", marginBottom:5 }}>
                      → {t("combat_detail_grade_next",
                          { emoji: nextGradeEmoji, name: nextGradeName, mult: nextMult })}
                    </div>
                    <div style={{ display:"flex", flexDirection:"column", gap:3, marginBottom:7,
                                  fontSize:10.5, color:"var(--muted)", paddingLeft:8,
                                  borderLeft:"2px solid rgba(var(--gold2-rgb),.25)" }}>
                      <div style={{ color: u.ready ? "var(--jade)" : "var(--red2)" }}>
                        {u.ready ? "✓" : "✗"} {t("combat_detail_grade_req_mastery", { n: u.min_mastery })}
                      </div>
                      {u.stones > 0 && (
                        <div style={{ color: stones != null
                          ? (stones >= u.stones ? "var(--jade)" : "var(--red2)")
                          : "var(--muted)" }}>
                          {stones != null ? (stones >= u.stones ? "✓" : "✗") : "·"} {t("combat_detail_grade_req_stones", { n: u.stones })}
                        </div>
                      )}
                      {u.scrolls > 0 && (
                        <div style={{ color: ownedScrolls >= u.scrolls ? "var(--jade)" : "var(--red2)" }}>
                          {ownedScrolls >= u.scrolls ? "✓" : "✗"} {t("combat_detail_grade_req_scrolls", { n: u.scrolls })}
                        </div>
                      )}
                      {u.pill && (
                        <div style={{ color:"var(--muted)" }}>
                          · {t("combat_detail_grade_req_pill", { pill: u.pill })}
                        </div>
                      )}
                      {u.requires_tribulation && (
                        <div style={{ color:"var(--muted)" }}>
                          · {t("combat_detail_grade_req_trib")}
                        </div>
                      )}
                    </div>
                    <ActionBtn
                      variant={upgradeBlocked ? "ghost" : "primary"}
                      disabled={!!busy || upgradeBlocked}
                      onClick={upgradeGrade}
                      style={{ width:"100%", padding:"8px 10px", fontSize:11.5 }}>
                      {upgradeBlocked && !u.ready
                        ? t("combat_detail_btn_grade_locked")
                        : t("combat_detail_btn_grade_upgrade")}
                    </ActionBtn>
                  </>
                )}
              </div>
            )}

            {/* Effect (combat-relevant) */}
            {tech.effect_type && (
              <div style={{ paddingTop:6, borderTop:"1px dashed rgba(var(--gold2-rgb),.18)" }}>
                <div style={{ fontSize:10.5, color:"var(--gold2)",
                              fontFamily:"'Cinzel',serif", letterSpacing:.5,
                              textTransform:"uppercase", marginBottom:3 }}>
                  {t("combat_detail_effect_section")}
                </div>
                <div style={{ fontSize:11, color:"var(--text)" }}>
                  {t("combat_tech_detail_effect",
                    { effect: tech.effect_type, value: tech.effect_value || 0 })}
                </div>
              </div>
            )}

            {/* Requirements */}
            <div style={{ paddingTop:6, borderTop:"1px dashed rgba(var(--gold2-rgb),.18)",
                          fontSize:10.5, color:"var(--muted)" }}>
              <div style={{ fontFamily:"'Cinzel',serif", color:"var(--gold2)",
                            letterSpacing:.5, textTransform:"uppercase", fontSize:10.5,
                            marginBottom:3 }}>
                {t("combat_detail_requirements")}
              </div>
              <div>{t("combat_tech_detail_req_realm", { realm: reqRealmName })}</div>
              {tech.dao && tech.dao.law_name && (
                <div>{t("combat_tech_detail_req_dao",
                  { dao: `${tech.dao.law_emoji || "☯️"} ${tech.dao.law_name}`,
                    req: tech.dao.required })}</div>
              )}
            </div>
          </div>
        </Modal>
      );
    }

    // ── NPC Hunt Panel ─────────────────────────────────────────────────────
    function CombatNPCPanel({ data, onChanged, player }) {
      const [diff, setDiff] = useState(null);
      const [focusId, setFocusId] = useState(0);
      const [fightResult, setFightResult] = useState(null);
      const [fightBusy, setFightBusy] = useState(false);
      // v15.1.4 — turn-based PvE duel: when a duel is spawned, open the
      // DuelArenaModal in PvE mode. Setting this triggers the inline
      // modal at the bottom of this panel.
      const [pveDuelId, setPveDuelId] = useState(null);
      const [now, setNow] = useState(Date.now());
      // Capture the moment the cooldown snapshot was received so the
      // countdown decrements smoothly. When `data` reloads (after a fight
      // or from `onChanged`), the ref resets via the dep array on data.npc.
      const fetchedAtRef = useRef(Date.now());
      useEffect(() => { fetchedAtRef.current = Date.now(); }, [data && data.npc && data.npc.cooldown_seconds]);
      // Tick once a second so the cooldown countdown updates live.
      useEffect(() => {
        const i = setInterval(() => setNow(Date.now()), 1000);
        return () => clearInterval(i);
      }, []);

      const cd = (data.npc && data.npc.cooldown_seconds) || 0;
      const elapsedMs = now - fetchedAtRef.current;
      const remainSec = Math.max(0, cd - Math.floor(elapsedMs / 1000));
      const onCd = remainSec > 0;

      const stats = data.stats || {};
      const techs = (data.techniques && data.techniques.learned) || [];
      // 武 2.2 — estas eram CÓDIGO MORTO. Calculadas aqui desde a v15.1.4 (que
      // tirou o selector de foco) e nunca desenhadas: o jogador escolhia uma
      // dificuldade, pagava 10 a 100 de Qi e entrava sem ver com o que ia
      // lutar. Passam a alimentar a tira de preparo.
      const combatTechs = techs.filter(tt => tt.tech_type === "combat" && tt.is_active);
      const _cenaOn = obraOn() && typeof CenaPreparo === "function";
      const _cenaWide = typeof useWideShell === "function" ? useWideShell() : false;

      const DIFFS = [
        { key:"easy",      emoji:"🟢", qi: 10 },
        { key:"normal",    emoji:"🟡", qi: 25 },
        { key:"hard",      emoji:"🔴", qi: 50 },
        { key:"nightmare", emoji:"💀", qi:100 },
      ];

      async function fight() {
        if (fightBusy || !diff) return;
        setFightBusy(true);
        try {
          // v15.1.4 — Combat Phase 2: NPC Hunt is now turn-based PvE.
          // Spawn a DuelSession via `combat/npc_duel_create` and open
          // DuelArenaModal in PvE mode. The legacy `combat/duel_npc`
          // endpoint stays for chat handlers + backwards-compat only.
          // `focus_tech_id` is no longer passed — the player picks their
          // technique each round inside the duel modal.
          const res = await api("combat/npc_duel_create", {
            difficulty: diff,
          });
          if (!res.ok) {
            haptic("error");
            const map = {
              cooldown:           t("combat_npc_cooldown",
                { min: Math.ceil((res.remaining_seconds || 0) / 60) }),
              qi_insufficient:    t("combat_npc_qi_low", { cost: res.qi_cost }),
              hp_depleted:        hpDepletedMsg("combat_npc_hp_depleted"),
              meditation_too_deep: t("combat_npc_meditation_block"),
              duel_already_active: t("combat_npc_duel_already_active"),
            };
            showToast(map[res.reason] || t("combat_equip_failed"), "err");
            return;
          }
          haptic("warning");
          setPveDuelId(res.duel_id);
        } catch (e) {
          haptic("error");
          showToast(e.message, "err");
        } finally {
          setFightBusy(false);
        }
      }

      return (
        <div>
          {_cenaOn ? (
            <CenaPreparo techs={combatTechs} max={stats.max_combat_slots}
                         wide={_cenaWide} />
          ) : null}
          <Card style={{ padding:"11px 13px 10px", marginBottom:10 }}>
            <div style={{ fontFamily:"'Cinzel',serif", fontSize:13, color:"var(--gold2)",
                          fontWeight:700, marginBottom:5, letterSpacing:.4 }}>
              {t("combat_npc_title")}
            </div>
            <div style={{ fontSize:10.5, color:"var(--muted)", lineHeight:1.5, marginBottom:9 }}>
              {t("combat_npc_subtitle")}
            </div>

            {onCd && (
              <div style={{
                padding:"6px 9px", borderRadius:6, marginBottom:9,
                background:"rgba(var(--red-rgb),.1)", border:"1px solid rgba(var(--red-rgb),.32)",
                fontSize:11, color:"var(--red2)",
              }}>
                {t("combat_npc_cooldown", { min: Math.max(1, Math.ceil(remainSec / 60)) })}
              </div>
            )}

            <div style={{ fontSize:10.5, color:"var(--muted)", fontFamily:"'Cinzel',serif",
                          letterSpacing:.5, textTransform:"uppercase", marginBottom:5 }}>
              {t("combat_npc_pick_difficulty")}
            </div>
            <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:6, marginBottom:9 }}>
              {DIFFS.map(d => (
                <button key={d.key}
                        disabled={onCd}
                        onClick={() => { haptic("select"); setDiff(d.key); }}
                        style={{
                          padding:"8px 8px", borderRadius:7, cursor: onCd ? "default" : "pointer",
                          background: diff === d.key
                            ? "linear-gradient(180deg,rgba(var(--red-rgb),.22),rgba(120,30,30,.4))"
                            : "linear-gradient(180deg,rgba(var(--surface-rgb),.7),rgba(var(--surface3-rgb),.85))",
                          border:`1px solid ${diff === d.key ? "rgba(var(--red-rgb),.6)" : "rgba(var(--glow-rgb),.28)"}`,
                          color: diff === d.key ? "var(--red2)" : "var(--text)",
                          fontFamily:"'Cinzel',serif", fontSize:11, fontWeight:600,
                          letterSpacing:.4, opacity: onCd ? .5 : 1,
                        }}>
                  <div>{d.emoji} {t(`combat_npc_difficulty_${d.key}`)}</div>
                  <div style={{ fontSize:9.5, color:"var(--muted)", marginTop:2 }}>
                    {t("combat_npc_qi_cost", { qi: d.qi })}
                  </div>
                </button>
              ))}
            </div>

            {/* v15.1.4 — Focus picker removed: the turn-based PvE duel
                lets the player pick their technique each round inside
                DuelArenaModal, which makes the pre-fight focus toggle
                redundant. The intent banner below explains the change. */}
            <div style={{
              padding:"6px 9px", borderRadius:6, marginBottom:9,
              background:"rgba(120,90,180,.1)",
              border:"1px solid rgba(120,90,180,.32)",
              fontSize:10.5, color:"var(--gold3)", lineHeight:1.45,
            }}>
              {t("combat_npc_pve_intro")}
            </div>

            <ActionBtn variant="primary"
                       disabled={!diff || onCd || fightBusy}
                       onClick={fight}
                       style={{ width:"100%", padding:"10px 14px", fontSize:12.5 }}>
              {t("combat_npc_btn_fight")}
            </ActionBtn>
          </Card>

          {/* v15.1.4 — turn-based PvE duel arena. Renders inline when a
              duel was spawned by `fight()`. Closing the modal refreshes
              the panel + the parent (Cooldown reset, qi delta, etc). */}
          {pveDuelId && (
            <DuelArenaModal
              duelId={pveDuelId}
              onClose={() => { setPveDuelId(null); onChanged(); }}
              playerLang={player && player.lang} />
          )}

          {fightResult && (
            <CombatResultModal
              result={fightResult}
              onClose={() => { setFightResult(null); onChanged(); }}
              onAgain={() => { setFightResult(null); fight(); }} />
          )}
        </div>
      );
    }

    // ── Combat Result Modal (NPC + PvP duel cinematic + outcome) ───────────
    // Replays rounds[] from server-side simulate_combat with a 600ms tick so
    // the player feels each hit. When all rounds are revealed, the outcome
    // banner unveils with loot + mastery levelups.
    //
    // Round 4 fix: opponent name + viewer perspective. The previous version
    // hardcoded "NPC" in renderCombatEvent — owner reported PvP target
    // seeing "NPC atacou 200B" instead of challenger's dao_name. Now uses
    // `result.opponent_dao_name` (NPC name OR PvP opponent) and
    // `result.viewer_is_attacker` (true for NPC duels and PvP-from-challenger;
    // false for PvP-from-target) to label round events correctly. Outcome
    // banner uses `result.you_won` directly when present (PvP) and falls
    // back to `winner === "attacker"` for NPC duels.
    function CombatResultModal({ result, onClose, onAgain }) {
      const totalRounds = (result.rounds || []).length;
      const [revealedRound, setRevealedRound] = useState(0);
      const [showOutcome, setShowOutcome] = useState(false);

      useEffect(() => {
        if (revealedRound < totalRounds) {
          const tm = setTimeout(() => setRevealedRound(x => x + 1), 600);
          return () => clearTimeout(tm);
        }
        const t2 = setTimeout(() => setShowOutcome(true), 350);
        return () => clearTimeout(t2);
      }, [revealedRound, totalRounds]);

      const winner = result.winner;
      const draw = winner === "draw" || winner == null;
      // PvP responses set `you_won` directly; NPC duels rely on attacker=
      // viewer convention.
      const viewerIsAttacker = (typeof result.viewer_is_attacker === "boolean")
        ? result.viewer_is_attacker
        : true;
      const won = (typeof result.you_won === "boolean")
        ? result.you_won
        : (winner === "attacker");

      const opponentName = result.opponent_dao_name || result.npc_name || "NPC";
      const isPvP = !!result.is_pvp;
      const titleText = isPvP
        ? t("combat_pvp_result_title", { opponent: opponentName })
        : `⚔️ ${opponentName}`;

      const visibleRounds = (result.rounds || []).slice(0, revealedRound);
      const skipReveal = () => {
        setRevealedRound(totalRounds);
        setShowOutcome(true);
      };

      return (
        <Modal onClose={onClose} title={titleText}
               accent={(draw ? "rgba(120,140,180,.55)"
                       : won ? "rgba(var(--jade-rgb),.55)"
                       : "rgba(var(--red-rgb),.55)")}
               maxWidth={420} zIndex={70}
               footer={
                 <div style={{ display:"flex", gap:8, justifyContent:"flex-end" }}>
                   <ActionBtn variant="ghost" onClick={onClose}
                              style={{ padding:"7px 14px", fontSize:11 }}>
                     {t("combat_result_close")}
                   </ActionBtn>
                   {showOutcome && onAgain && (
                     <ActionBtn variant="primary" onClick={onAgain}
                                style={{ padding:"7px 14px", fontSize:11 }}>
                       {t("combat_result_again")}
                     </ActionBtn>
                   )}
                 </div>
               }>
          <div style={{ display:"flex", flexDirection:"column", gap:7 }}>
            {visibleRounds.map((rnd, i) => (
              <CombatRoundLine key={i} rnd={rnd}
                               opponentName={opponentName}
                               viewerIsAttacker={viewerIsAttacker}
                               attackerMaxHp={result.attacker_max_hp || 0}
                               defenderMaxHp={result.defender_max_hp || 0} />
            ))}
            {!showOutcome && revealedRound < totalRounds && (
              <div style={{ textAlign:"center", padding:"6px 0" }}>
                <button onClick={skipReveal} style={{
                  background:"transparent", border:"none",
                  color:"var(--muted)", fontSize:10, cursor:"pointer",
                  fontFamily:"'Cinzel',serif", letterSpacing:.4,
                }}>↓ skip</button>
              </div>
            )}
            {showOutcome && (
              <div style={{
                marginTop:9, padding:"11px 12px", borderRadius:9,
                background: draw
                  ? "linear-gradient(180deg,rgba(120,140,180,.18),rgba(40,50,80,.6))"
                  : won
                    ? "linear-gradient(180deg,rgba(var(--jade-rgb),.18),rgba(20,80,50,.6))"
                    : "linear-gradient(180deg,rgba(var(--red-rgb),.18),rgba(110,30,30,.6))",
                border: `1px solid ${draw ? "rgba(120,140,180,.4)" : won ? "rgba(var(--jade-rgb),.5)" : "rgba(var(--red-rgb),.5)"}`,
                animation:"fade-up .3s ease",
                textAlign:"center",
              }}>
                <div style={{ fontFamily:"'Cinzel',serif", fontSize:18, fontWeight:700,
                              color: draw ? "var(--text)" : won ? "var(--jade)" : "var(--red2)" }}>
                  {draw ? t("combat_result_draw")
                        : won ? t("combat_result_victory")
                        : t("combat_result_defeat")}
                </div>
                <div style={{ fontSize:11, color:"var(--muted)", marginTop:4 }}>
                  {(() => {
                    const n = result.total_rounds || totalRounds;
                    return n === 1
                      ? t("combat_result_round_singular")
                      : t("combat_result_rounds_plural", { n });
                  })()}
                </div>
                {result.hp_lost != null && result.hp_lost > 0 && (
                  <div style={{ fontSize:10.5, color:"var(--red2)", marginTop:3 }}>
                    {t("combat_result_hp_lost", { n: fmtNum(result.hp_lost) })}
                  </div>
                )}
              </div>
            )}
            {showOutcome && (result.items_gained || []).length > 0 && (
              <div style={{ marginTop:6, padding:"9px 11px", borderRadius:8,
                            background:"rgba(var(--gold2-rgb),.05)",
                            border:"1px solid rgba(var(--gold2-rgb),.22)" }}>
                <div style={{ fontSize:10.5, color:"var(--gold2)",
                              fontFamily:"'Cinzel',serif", letterSpacing:.5,
                              textTransform:"uppercase", marginBottom:6 }}>
                  💰 {t("combat_result_loot")}
                </div>
                {(result.items_gained || []).map((it, i) => (
                  <div key={i} style={{
                    display:"flex", alignItems:"center", gap:6, fontSize:11.5,
                    padding:"3px 0", color:"var(--text)",
                  }}>
                    <span style={{ fontSize:16 }}>{it.emoji}</span>
                    <span>{it.name}</span>
                    <span style={{ marginLeft:"auto", color:"var(--gold3)" }}>×{it.count}</span>
                  </div>
                ))}
              </div>
            )}
            {showOutcome && (result.mastery_levelups || []).length > 0 && (
              <div style={{ marginTop:6 }}>
                {(result.mastery_levelups || []).map((m, i) => (
                  <div key={i} style={{
                    fontSize:10.5, color:"var(--gold3)", padding:"3px 6px",
                    fontFamily:"'Cinzel',serif",
                  }}>
                    ⭐ {t("combat_result_mastery_up",
                      { emoji: m.emoji, name: m.name, lvl: m.new_level, mult: m.new_mult })}
                  </div>
                ))}
              </div>
            )}
          </div>
        </Modal>
      );
    }

    function CombatRoundLine({ rnd, opponentName, viewerIsAttacker, attackerMaxHp, defenderMaxHp }) {
      // Round 5 (owner round 4 ext): "com o log nao sabemos quem ganhou".
      // Render HP bars at end of round (Tu vs opponent) + show "KO" indicator
      // when one side falls. Clarifies the fight progression even on 1-round
      // killing blows (which previously showed only "Tu atacou X" with no
      // outcome context inside the round itself).
      const events = rnd.events || [];
      const youHp     = (viewerIsAttacker !== false ? rnd.attacker_hp : rnd.defender_hp) ?? null;
      const youMax    = (viewerIsAttacker !== false ? attackerMaxHp : defenderMaxHp) || 1;
      const oppHp     = (viewerIsAttacker !== false ? rnd.defender_hp : rnd.attacker_hp) ?? null;
      const oppMax    = (viewerIsAttacker !== false ? defenderMaxHp : attackerMaxHp) || 1;
      const youPct    = youHp != null ? Math.max(0, Math.min(100, (youHp / Math.max(1, youMax)) * 100)) : null;
      const oppPct    = oppHp != null ? Math.max(0, Math.min(100, (oppHp / Math.max(1, oppMax)) * 100)) : null;
      const youKO     = youHp != null && youHp <= 0;
      const oppKO     = oppHp != null && oppHp <= 0;

      return (
        <div style={{
          padding:"7px 10px", borderRadius:7,
          background:"rgba(0,0,0,.32)",
          border:"1px solid rgba(var(--glow-rgb),.18)",
          animation:"fade-up .25s ease",
        }}>
          <div style={{ fontSize:10.5, color:"var(--gold2)", fontFamily:"'Cinzel',serif",
                        letterSpacing:.5, marginBottom:4 }}>
            {t("combat_round_label", { n: rnd.round })}
          </div>
          {events.map((e, i) => (
            <div key={i} style={{ fontSize:11, color:"var(--text)", lineHeight:1.5, marginBottom:1 }}>
              {renderCombatEvent(e, opponentName || "NPC", viewerIsAttacker !== false)}
            </div>
          ))}
          {(youHp != null || oppHp != null) && (
            <div style={{ marginTop:6, display:"flex", flexDirection:"column", gap:3 }}>
              {youHp != null && (
                <HpRow name={t("combat_actor_you")} hp={youHp} max={youMax}
                       pct={youPct} ko={youKO} mine={true} />
              )}
              {oppHp != null && (
                <HpRow name={opponentName || "NPC"} hp={oppHp} max={oppMax}
                       pct={oppPct} ko={oppKO} mine={false} />
              )}
            </div>
          )}
          {(youKO || oppKO) && (
            <div style={{
              marginTop:5, padding:"3px 7px", borderRadius:5,
              background: oppKO ? "rgba(var(--jade-rgb),.14)" : "rgba(var(--red-rgb),.14)",
              border: `1px solid ${oppKO ? "rgba(var(--jade-rgb),.4)" : "rgba(var(--red-rgb),.4)"}`,
              fontSize:10.5, fontFamily:"'Cinzel',serif", letterSpacing:.4,
              color: oppKO ? "var(--jade)" : "var(--red2)",
              textAlign:"center",
            }}>
              💀 {oppKO ? (opponentName || "NPC") : t("combat_actor_you")} — {t("combat_event_ko")}
            </div>
          )}
        </div>
      );
    }

    function HpRow({ name, hp, max, pct, ko, mine }) {
      const baseColor = ko ? "var(--muted2)" : (mine ? "var(--jade)" : "var(--red2)");
      return (
        <div style={{ display:"flex", alignItems:"center", gap:6 }}>
          <span style={{ fontSize:9.5, fontFamily:"'Cinzel',serif",
                         letterSpacing:.4, color: baseColor,
                         minWidth:62, whiteSpace:"nowrap", overflow:"hidden",
                         textOverflow:"ellipsis", textTransform:"uppercase" }}>
            {ko ? "💀 " : "❤️ "}{name}
          </span>
          <div style={{ flex:1, height:5, borderRadius:3,
                        background:"rgba(0,0,0,.55)", overflow:"hidden" }}>
            <div style={{
              width:`${pct ?? 0}%`, height:"100%",
              background: ko
                ? "linear-gradient(90deg, #4b5563, #6b7280)"
                : (mine
                    ? "linear-gradient(90deg, #15803d, #22c55e, #4ade80)"
                    : "linear-gradient(90deg, #7f1d1d, #ef4444, #f87171)"),
              transition:"width .3s ease",
            }} />
          </div>
          <span style={{ fontSize:9.5, color:"var(--muted)", fontFamily:"'Cinzel',serif",
                         minWidth:34, textAlign:"right", whiteSpace:"nowrap" }}>
            {Math.max(0, Math.round(pct ?? 0))}%
          </span>
        </div>
      );
    }

    function renderCombatEvent(e, opponentName, viewerIsAttacker) {
      // The simulate_combat result rounds always label sides as "attacker" /
      // "defender". Whether viewer = attacker depends on the call site:
      //   - NPC duel: player IS attacker, opponent (NPC) IS defender.
      //   - PvP from challenger view: viewer = attacker.
      //   - PvP from target view: viewer = defender.
      // Round 4 fix: previously hardcoded "NPC" — broke PvP labels.
      const youLabel = t("combat_actor_you");
      const oppLabel = opponentName || "NPC";
      const whoIsViewer = viewerIsAttacker ? "attacker" : "defender";
      const actorIsViewer = (e.who === whoIsViewer);
      const actorName = actorIsViewer ? youLabel : oppLabel;
      const targetName = actorIsViewer ? oppLabel : youLabel;

      if (e.type === "attack") {
        if (e.blocked > 0) {
          return t("combat_event_blocked",
            { actor: actorName, dmg: fmtNum(e.damage), blk: fmtNum(e.blocked) });
        }
        return t("combat_event_attack", { actor: actorName, dmg: fmtNum(e.damage) });
      }
      if (e.type === "evasion")  return t("combat_event_evasion", { target: targetName });
      if (e.type === "dodge")    return t("combat_event_dodge",   { target: targetName });
      if (e.type === "pet_attack") return t("combat_event_pet",
        { actor: actorName, pet: e.pet_name || "Pet", dmg: fmtNum(e.damage) });
      if (e.type === "stalemate_break") return t("combat_event_stalemate",
        { target: actorName, dmg: fmtNum(e.damage) });
      return JSON.stringify(e);
    }

    // ── Arena Queue Widget (v15.1.5) ──────────────────────────────────────
    // Sits inside CombatArenaPanel and drives the ELO matchmaking pool.
    // States: idle / waiting / matched / expired — each rendered inline
    // (modal canónico stays for the duel itself, not for the queue ticker).
    // ⚔️ O GOLPE PADRÃO — a arte que o relógio dispara quando você não está lá.
    //
    // O REPORT ([jogador], 10/09 09:59): *"in Arena, give option to set 'default'
    // technique to use (instead of default regular attack). This can give the
    // option to advance paths without having to wait each time the 3 minutes
    // counter (can do other things without worry)"*.
    //
    // O QUE HAVIA: quando a ronda esgota (15 s), o motor preenchia o lado que
    // faltou com o GOLPE BÁSICO. Quem fechava o mini-app lutava a soco.
    //
    // ⚠️ A ARTE PROIBIDA NÃO APARECE NESTA LISTA — e a tela DIZ que não aparece,
    // e porquê. Escondê-la em silêncio seria o beco que a Lei §1 proíbe: ele
    // procuraria a arte mais forte que tem, não a encontraria, e concluiria que
    // a tela está avariada. O motivo verdadeiro é que ela cobra karma e ANOS DE
    // VIDA por uso, e um automático não pode cobrar um preço que o jogador não
    // escolheu naquele instante.
    function DefaultStrikePicker({ ds, onChanged }) {
      const [busy, setBusy] = useState(0);
      const elig = ds.eligible || [];
      const cur = ds.current || 0;

      async function pick(id) {
        if (busy) return;
        setBusy(id || -1);
        try {
          const res = await api("combat/default_strike", { tech_id: id });
          if (!res.ok) {
            haptic("error");
            showToast(res.reason === "forbidden_never_auto"
              ? t("gp_err_forbidden")
              : res.reason === "technique_not_equipped"
                ? t("gp_err_not_equipped")
                : t("gp_err_generic"), "err");
            return;
          }
          haptic("success");
          showToast(id ? t("gp_saved") : t("gp_saved_basic"));
          onChanged && onChanged();
        } catch (e) {
          haptic("error");
          showToast(e.message, "err");
        } finally {
          setBusy(0);
        }
      }

      // A opção "golpe básico" é uma escolha de verdade e vem primeiro: é o que
      // o jogo faz hoje, e quem estiver bem assim tem de a poder reencontrar.
      const opts = [{ id: 0, name: t("gp_basic"), emoji: "" }].concat(elig);

      return (
        <div style={{ marginTop:9, paddingTop:8,
                      borderTop:"1px solid rgba(var(--gold2-rgb),.18)" }}>
          <div style={{ fontFamily:"'Cinzel',serif", fontSize:11, color:"var(--gold2)",
                        fontWeight:700, letterSpacing:.4, marginBottom:3 }}>
            {t("gp_title")}
          </div>
          <div style={{ fontSize:10, color:"var(--muted)", lineHeight:1.45,
                        marginBottom:7 }}>
            {t("gp_hint")}
          </div>
          <div style={{ display:"flex", flexWrap:"wrap", gap:5 }}>
            {opts.map(o => {
              const on = (o.id || 0) === cur;
              return (
                <button key={o.id}
                        onClick={() => pick(o.id)}
                        disabled={!!busy}
                        aria-pressed={on}
                        style={{
                          padding:"5px 9px", borderRadius:6, cursor:"pointer",
                          fontSize:10.5, fontFamily:"'Cinzel',serif", letterSpacing:.3,
                          background: on ? "rgba(var(--jade-rgb),.18)" : "rgba(0,0,0,.35)",
                          border: on ? "1px solid var(--jade)"
                                     : "1px solid rgba(var(--gold2-rgb),.28)",
                          color: on ? "var(--jade)" : "var(--gold3)",
                          opacity: busy ? .6 : 1,
                        }}>
                  {o.emoji ? o.emoji + " " : ""}{o.name}
                </button>
              );
            })}
          </div>
          {/* ⚠️ a escolha que MORREU: o id gravado já não está equipado, portanto
              o motor dispararia o golpe básico. A tela diz isso em vez de
              mostrar uma escolha que o motor não cumpre. */}
          {!!ds.stored && ds.stored !== cur && (
            <div style={{ fontSize:10, color:"var(--warn)", marginTop:6, lineHeight:1.4 }}>
              {t("gp_stale")}
            </div>
          )}
          {ds.forbidden_hidden > 0 && (
            <div style={{ fontSize:10, color:"var(--muted2)", marginTop:6,
                          lineHeight:1.4, fontStyle:"italic" }}>
              {t("gp_forbidden_hidden", { n: ds.forbidden_hidden })}
            </div>
          )}
        </div>
      );
    }

    function ArenaQueueWidget({ onMatched }) {
      const [busy, setBusy] = useState(false);
      const [tick, setTick] = useState(0);
      // Poll status every 3s while the panel is visible — that's the
      // freshness window for "match found" to redirect into the duel.
      const { data: status, error } = useApi("arena/queue_status", null, [tick]);
      useVisibleInterval(() => setTick(x => x + 1), 3000);

      const state = (status && status.state) || "none";

      // Match found → fire onMatched ONCE so the parent panel mounts the
      // DuelArenaModal. autoFiredRef stops a polling rerun from re-opening
      // the modal after the player closes it intentionally.
      const autoFiredRef = useRef(false);
      useEffect(() => {
        if (state === "matched" && status && status.duel_id && !autoFiredRef.current) {
          autoFiredRef.current = true;
          if (onMatched) onMatched(status.duel_id);
        }
      }, [state, status]);

      async function joinQueue() {
        if (busy) return;
        setBusy(true);
        try {
          const res = await api("arena/queue_join", {});
          if (!res.ok) {
            const map = {
              hp_too_low:     hpDepletedMsg("combat_arena_q_err_hp"),
              in_active_duel: t("combat_arena_q_err_active_duel"),
              pvp_sealed:     t("combat_arena_q_err_sealed"),
            };
            haptic("error");
            showToast(map[res.reason] || t("combat_arena_q_err_generic"), "err");
            return;
          }
          haptic("success");
          setTick(x => x + 1);
        } catch (e) {
          haptic("error");
          showToast(e.message, "err");
        } finally {
          setBusy(false);
        }
      }

      async function leaveQueue() {
        if (busy) return;
        setBusy(true);
        try {
          await api("arena/queue_leave", {});
          haptic("medium");
          setTick(x => x + 1);
        } catch (e) {
          showToast(e.message, "err");
        } finally {
          setBusy(false);
        }
      }

      // Idle / expired / unknown → "Join" button + range hint.
      if (state === "none" || state === "expired") {
        return (
          <div style={{ marginTop:10, padding:"8px 10px", borderRadius:7,
                        background:"rgba(255,255,255,.03)",
                        border:"1px dashed rgba(var(--gold2-rgb),.32)" }}>
            {state === "expired" && (
              <div style={{ fontSize:10.5, color:"var(--red)", marginBottom:6,
                            textAlign:"center", lineHeight:1.4 }}>
                {t("combat_arena_q_expired_banner")}
              </div>
            )}
            <div style={{ fontSize:10.5, color:"var(--muted)", textAlign:"center",
                          marginBottom:6, lineHeight:1.4 }}>
              {t("combat_arena_q_idle_hint")}
            </div>
            <ActionBtn variant="primary" onClick={joinQueue} disabled={busy}
                       style={{ width:"100%", padding:"9px 8px", fontSize:11.5 }}>
              {busy ? t("combat_arena_q_joining") : t("combat_arena_q_join_btn")}
            </ActionBtn>
            {error && <ErrBanner msg={error} />}
          </div>
        );
      }

      if (state === "waiting") {
        const remaining = (status && status.remaining_seconds) || 0;
        const mm = Math.floor(remaining / 60);
        const ss = String(remaining % 60).padStart(2, "0");
        return (
          <div style={{ marginTop:10, padding:"9px 10px", borderRadius:7,
                        background:"rgba(var(--gold2-rgb),.06)",
                        border:"1px solid rgba(var(--gold2-rgb),.32)" }}>
            <div style={{ fontSize:11, color:"var(--gold3)", textAlign:"center",
                          marginBottom:5, letterSpacing:.3 }}>
              {t("combat_arena_q_waiting_title")}
            </div>
            <div style={{ fontSize:10.5, color:"var(--muted)", textAlign:"center",
                          marginBottom:7, lineHeight:1.4 }}>
              {/* ⚔️ O ENCONTRO RAPIDO — a fila tem de dizer POR QUEM se espera.
                  Medido a 12/09: 0 duelos PvP de arena em 30 dias, e 16.516
                  `arena_npc_fallback` all-time. Quem espera nao esta' a ser
                  emparelhado com ninguem — vai receber um NPC no fim, sempre.
                  Dizer "procurando adversario" durante 3 minutos e' um relogio
                  que nao decide nada (Lei §1). `pool_empty` so' chega com a
                  flag ligada; sem ela, a linha de sempre, byte a byte. */}
              {(status && status.pool_empty)
                ? t("combat_arena_q_waiting_solo", { mins: mm, secs: ss })
                : t("combat_arena_q_waiting_meta", {
                    mins: mm, secs: ss,
                    range: (status && status.elo_range) || 200,
                  })}
            </div>
            <ActionBtn variant="ghost" onClick={leaveQueue} disabled={busy}
                       style={{ width:"100%", padding:"8px 8px", fontSize:11 }}>
              {t("combat_arena_q_leave_btn")}
            </ActionBtn>
          </div>
        );
      }

      // state === 'matched' — branch on NPC fallback so the player knows
      // whether they're fighting a real cultivator or an arena NPC.
      const isNpc = !!(status && status.is_npc_fallback);
      return (
        <div style={{ marginTop:10, padding:"9px 10px", borderRadius:7,
                      background: isNpc
                        ? "rgba(120,180,255,.10)"
                        : "rgba(var(--red-rgb),.08)",
                      border: isNpc
                        ? "1px solid rgba(120,180,255,.45)"
                        : "1px solid rgba(var(--red-rgb),.45)" }}>
          <div style={{ fontSize:11,
                        color: isNpc ? "var(--gold2)" : "var(--red)",
                        textAlign:"center",
                        marginBottom:5, letterSpacing:.3, fontWeight:700 }}>
            {isNpc
              ? t("combat_arena_q_matched_npc_title")
              : t("combat_arena_q_matched_title")}
          </div>
          <div style={{ fontSize:10.5, color:"var(--muted)", textAlign:"center",
                        marginBottom:7, lineHeight:1.4 }}>
            {t(isNpc ? "combat_arena_q_matched_npc_meta" : "combat_arena_q_matched_meta", {
              opponent: (status && status.opponent_dao_name) || "?",
            })}
          </div>
        </div>
      );
    }

    // ── Arena Panel ────────────────────────────────────────────────────────
    // Round 3 (2026-05-20): real PvP duel send/inbox/respond integrated.
    // Owner described the desired flow exactly: input dao_name + optional
    // wager → 5min TTL pending challenge → target sees in inbox bell or
    // Arena tab Inbox button → Accept/Decline. Cancel anytime by sender.
    // PvP rounds re-use CombatResultModal cinematic.
    function CombatArenaPanel({ data, onChanged }) {
      const [reload, setReload] = useState(0);
      const [sendOpen, setSendOpen] = useState(false);
      const [inboxOpen, setInboxOpen] = useState(false);
      const [pvpResult, setPvpResult] = useState(null);
      // v15.1.3 — when a challenge accept spawns a turn-based duel, the
      // server returns redirect_to_duel:true + duel_id. We hand off to the
      // DuelArenaModal in-place instead of opening the legacy CombatResult.
      const [liveDuelId, setLiveDuelId] = useState(null);
      const { data: lb, loading, error } = useApi("arena/leaderboard", { limit: 50 }, [reload]);
      const inbox = useApi("combat/challenge_inbox", null, [reload, sendOpen, inboxOpen]);
      const arena = data.arena || {};
      // Refresh inbox every 15s while panel visible — owner wants near-live
      // state for incoming challenges + outcomes.
      useVisibleInterval(() => setReload(x => x + 1), 15000);
      const incomingCount = (inbox.data && inbox.data.incoming_count) || 0;
      const outgoingCount = (inbox.data && inbox.data.outgoing_count) || 0;
      const unseenCount = (inbox.data && inbox.data.unseen_count) || 0;

      // Round 4 fix: auto-open result modal for unseen outcomes (the
      // challenger's side — they never saw the result before). Owner:
      // "quando aceitar sair notificacao e o modal na pantalla dos 2".
      // Track which IDs we already auto-opened so polling doesn't re-pop
      // the modal repeatedly while we wait for the mark-seen to flush.
      const autoOpenedRef = useRef(new Set());
      useEffect(() => {
        if (pvpResult) return; // a modal is already open
        const outcomes = (inbox.data && inbox.data.unseen_outcomes) || [];
        if (outcomes.length === 0) return;
        // Pick the first not-yet-auto-opened outcome.
        const next = outcomes.find(o => !autoOpenedRef.current.has(o.challenge_id));
        if (!next) return;
        autoOpenedRef.current.add(next.challenge_id);
        const opponent = next.opponent_dao_name || "?";
        const totalRounds = next.total_rounds || (next.rounds || []).length;
        setPvpResult({
          is_pvp: true,
          viewer_is_attacker: !!next.viewer_is_attacker,
          opponent_dao_name: opponent,
          opponent_realm: next.opponent_realm || 0,
          npc_name: opponent,
          npc_realm: next.opponent_realm || 0,
          you_won: !!next.you_won,
          winner: next.winner,
          rounds: next.rounds || [],
          total_rounds: totalRounds,
          attacker_max_hp: next.attacker_max_hp || 0,
          defender_max_hp: next.defender_max_hp || 0,
          attacker_hp_final: 0, defender_hp_final: 0,
          spirit_stones_reward: 0,
          items_gained: [],
          mastery_levelups: [],
          stance: "balanced",
          focus_tech_id: 0,
          wager: next.wager || 0,
          hp_lost: 0,
          challenge_id: next.challenge_id,
          delta: null,
        });
      }, [inbox.data, pvpResult]);

      // Mark-seen + close handler for the auto-opened modal.
      async function closePvPResult() {
        const cid = pvpResult && pvpResult.challenge_id;
        setPvpResult(null);
        if (cid) {
          try {
            await api("combat/challenge_mark_seen", { challenge_id: cid });
          } catch (e) {
            // silent — next inbox poll will re-surface if mark failed
          }
        }
        refreshAll();
      }

      function refreshAll() {
        setReload(x => x + 1);
        if (onChanged) onChanged();
      }

      // 武 2.2 — a MESMA tira do segmento NPC, pelo MESMO componente. A arena
      // cobra Qi e Elo; entrar sem ver com o que se luta é o mesmo defeito.
      // Um dono, dois sítios (Lei 0 §2) — nunca duas tiras parecidas.
      const _cenaOn = obraOn() && typeof CenaPreparo === "function";
      const _cenaWide = typeof useWideShell === "function" ? useWideShell() : false;
      const _prepArena = ((data && data.techniques && data.techniques.learned) || [])
        .filter(tt => tt && tt.tech_type === "combat" && tt.is_active);

      return (
        <div>
          {_cenaOn ? (
            <CenaPreparo techs={_prepArena}
                         max={(data && data.stats && data.stats.max_combat_slots)}
                         wide={_cenaWide} />
          ) : null}
          <Card style={{ padding:"11px 13px 10px", marginBottom:10 }}>
            <div style={{ fontFamily:"'Cinzel',serif", fontSize:13, color:"var(--gold2)",
                          fontWeight:700, marginBottom:5, letterSpacing:.4 }}>
              {t("combat_arena_title")}
            </div>
            <div style={{ fontSize:10.5, color:"var(--muted)", marginBottom:8 }}>
              {t("combat_arena_subtitle", { n: arena.season || 1 })}
            </div>
            <div style={{ padding:"7px 10px", borderRadius:7,
                          background:"rgba(var(--gold2-rgb),.08)",
                          border:"1px solid rgba(var(--gold2-rgb),.32)",
                          fontSize:11, color:"var(--gold3)",
                          textAlign:"center", letterSpacing:.3 }}>
              {arena.rank
                ? t("combat_arena_my_summary",
                    { elo: arena.elo, wins: arena.wins, losses: arena.losses, rank: arena.rank })
                : t("combat_arena_my_summary_unranked", { elo: arena.elo || 1000 })}
            </div>

            {/* PvP CTAs (owner round 3) */}
            <div style={{ fontSize:10.5, color:"var(--muted)", marginTop:9,
                          textAlign:"center", lineHeight:1.5 }}>
              {t("combat_arena_pvp_subtitle")}
            </div>
            <div style={{ display:"flex", gap:7, marginTop:7 }}>
              <ActionBtn variant="primary"
                         onClick={() => setSendOpen(true)}
                         style={{ flex:1, padding:"9px 8px", fontSize:11.5 }}>
                {t("combat_arena_pvp_send")}
              </ActionBtn>
              <ActionBtn variant="ghost"
                         onClick={() => setInboxOpen(true)}
                         style={{
                           flex:1, padding:"9px 8px", fontSize:11.5,
                           position:"relative",
                         }}>
                {t("combat_arena_pvp_inbox")}
                {(incomingCount + outgoingCount + unseenCount) > 0 && (
                  <span style={{
                    position:"absolute", top:-5, right:-5,
                    background: unseenCount > 0 ? "var(--gold2)" : "var(--red)",
                    color: unseenCount > 0 ? "#000" : "#fff",
                    borderRadius:"50%", minWidth:18, height:18,
                    fontSize:10, fontWeight:700,
                    display:"grid", placeItems:"center",
                    border:"1.5px solid var(--bg)",
                    fontFamily:"'Cinzel',serif",
                  }}>{incomingCount + outgoingCount + unseenCount}</span>
                )}
              </ActionBtn>
            </div>

            {/* v15.1.5 — ELO matchmaking queue (DB-backed, shared with chat) */}
            <ArenaQueueWidget
              onMatched={(duelId) => setLiveDuelId(duelId)} />
          </Card>

          <Card style={{ padding:"11px 12px 6px" }}>
            <div style={{ fontFamily:"'Cinzel',serif", fontSize:12, color:"var(--gold2)",
                          fontWeight:700, marginBottom:7, letterSpacing:.4 }}>
              {t("combat_arena_leaderboard", { n: (lb && lb.items && lb.items.length) || 0 })}
            </div>
            {loading && !lb && <ListSkeleton rows={6} />}
            {error && <ErrBanner msg={error} />}
            {lb && (lb.items || []).length === 0 && (
              <div style={{ textAlign:"center", padding:"22px 8px", color:"var(--muted)", fontSize:11.5 }}>
                {t("combat_arena_empty")}
              </div>
            )}
            {lb && (lb.items || []).map(row => (
              <LeaderRow key={row.rank}
                         rank={row.rank}
                         name={`${row.realm_emoji} ${row.dao_name}`}
                         meta={t("combat_arena_row_meta",
                           { elo: row.elo, wins: row.wins, losses: row.losses })}
                         isYou={row.is_you} />
            ))}
          </Card>

          {sendOpen && (
            <PvPSendModal onClose={() => setSendOpen(false)}
                          onSent={refreshAll} />
          )}
          {inboxOpen && (
            <PvPInboxModal onClose={() => setInboxOpen(false)}
                           onAction={refreshAll}
                           onAccepted={(res) => {
                             setInboxOpen(false);
                             // v15.1.3 — new turn-based path: accept spawns
                             // a duel, mini-app jumps straight into the
                             // arena modal. Legacy shape (winner/rounds)
                             // still falls through to CombatResultModal so
                             // pre-deploy in-flight challenges play out.
                             if (res && res.redirect_to_duel && res.duel_id) {
                               setLiveDuelId(res.duel_id);
                             } else {
                               setPvpResult(res);
                             }
                           }} />
          )}
          {pvpResult && (
            <CombatResultModal result={pvpResult}
                               onClose={closePvPResult}
                               onAgain={null} />
          )}
          {liveDuelId && (
            <DuelArenaModal
              duelId={liveDuelId}
              onClose={() => { setLiveDuelId(null); refreshAll(); }}
            />
          )}
        </div>
      );
    }

    // ── PvP Send Modal ─────────────────────────────────────────────────────
    function PvPSendModal({ onClose, onSent }) {
      const [target, setTarget] = useState("");
      const [wager, setWager] = useState("0");
      const [busy, setBusy] = useState(false);

      async function send() {
        if (busy) return;
        const trimmed = target.trim();
        if (!trimmed) return;
        const wagerN = Math.max(0, parseInt(wager || "0", 10) || 0);
        setBusy(true);
        try {
          const res = await api("combat/challenge_create", {
            target_dao_name: trimmed,
            wager: wagerN,
          });
          if (!res.ok) {
            haptic("error");
            const map = {
              target_not_found:       t("combat_pvp_send_target_not_found"),
              cannot_self_challenge:  t("combat_pvp_send_self"),
              realm_gap_too_large:    t("combat_pvp_send_realm_gap", { n: res.max_gap }),
              wager_no_funds_self:    t("combat_pvp_send_no_funds"),
              wager_over_self_cap:    t("combat_pvp_send_over_self_cap", { cap: res.cap }),
              wager_no_funds_target:  t("combat_pvp_send_target_no_funds"),
              wager_over_target_cap:  t("combat_pvp_send_target_over_cap"),
              pvp_sealed:             t("combat_arena_q_err_sealed"),
            };
            showToast(map[res.reason] || t("combat_pvp_send_failed"), "err");
            return;
          }
          haptic("success");
          if (res.duplicate) {
            showToast(t("combat_pvp_send_duplicate", { target: trimmed }));
          } else {
            showToast(t("combat_pvp_send_ok", { target: trimmed }));
          }
          onSent();
          onClose();
        } catch (e) {
          haptic("error");
          showToast(e.message, "err");
        } finally {
          setBusy(false);
        }
      }

      return (
        <Modal onClose={onClose} title={`⚔️ ${t("combat_pvp_send_title")}`}
               accent="rgba(var(--red-rgb),.55)" maxWidth={420} zIndex={70}
               footer={
                 <div style={{ display:"flex", gap:8, justifyContent:"flex-end" }}>
                   <ActionBtn variant="ghost" onClick={onClose}
                              style={{ padding:"7px 14px", fontSize:11 }}>
                     {t("combat_result_close")}
                   </ActionBtn>
                   <ActionBtn variant="primary" onClick={send}
                              disabled={busy || !target.trim()}
                              style={{ padding:"7px 14px", fontSize:11 }}>
                     {t("combat_pvp_send_btn")}
                   </ActionBtn>
                 </div>
               }>
          <div style={{ fontSize:11.5, color:"var(--muted)", lineHeight:1.55, marginBottom:13 }}>
            {t("combat_pvp_send_intro")}
          </div>
          <div style={{ marginBottom:11 }}>
            <div style={{ fontSize:10.5, color:"var(--gold2)",
                          fontFamily:"'Cinzel',serif", letterSpacing:.5,
                          textTransform:"uppercase", marginBottom:5 }}>
              {t("combat_pvp_send_target_label")}
            </div>
            <input type="text" value={target}
                   onChange={e => setTarget(e.target.value)}
                   placeholder={t("combat_pvp_send_target_placeholder")}
                   maxLength={32}
                   style={{
                     width:"100%", boxSizing:"border-box",
                     padding:"10px 12px", borderRadius:7,
                     background:"rgba(0,0,0,.45)",
                     border:"1px solid rgba(var(--gold2-rgb),.32)",
                     color:"var(--text)", fontSize:13,
                     fontFamily:"'Cinzel',serif", letterSpacing:.3,
                   }} />
          </div>
          <div>
            <div style={{ fontSize:10.5, color:"var(--gold2)",
                          fontFamily:"'Cinzel',serif", letterSpacing:.5,
                          textTransform:"uppercase", marginBottom:5 }}>
              {t("combat_pvp_send_wager_label")}
            </div>
            <input type="text" inputMode="numeric" value={wager}
                   onChange={e => setWager(e.target.value.replace(/[^0-9]/g, ""))}
                   maxLength={10}
                   style={{
                     width:"100%", boxSizing:"border-box",
                     padding:"10px 12px", borderRadius:7,
                     background:"rgba(0,0,0,.45)",
                     border:"1px solid rgba(var(--gold2-rgb),.32)",
                     color:"var(--text)", fontSize:13,
                     fontFamily:"'Cinzel',serif", letterSpacing:.3,
                   }} />
            <div style={{ fontSize:10.5, color:"var(--muted)", marginTop:5, fontStyle:"italic" }}>
              {t("combat_pvp_send_wager_hint")}
            </div>
          </div>
        </Modal>
      );
    }

    // ── PvP Inbox Modal ────────────────────────────────────────────────────
    // Round 4: 3rd segment "Histórico" with resolved outcomes (24h window).
    // When the player opens the history segment, all unseen entries are
    // marked as seen via mark_seen endpoint (one round-trip per entry,
    // batched with Promise.all). Owner: needs to see who won past duels.
    function PvPInboxModal({ onClose, onAction, onAccepted }) {
      const [seg, setSeg] = useState("incoming");
      const [reload, setReload] = useState(0);
      const [busyId, setBusyId] = useState(null);
      const [historyResult, setHistoryResult] = useState(null);
      const { data, loading, error } = useApi("combat/challenge_inbox", null, [reload]);
      // Tick once a second so "expires in" countdown updates live.
      const [, setNow] = useState(Date.now());
      useEffect(() => {
        const i = setInterval(() => setNow(Date.now()), 1000);
        return () => clearInterval(i);
      }, []);

      // When viewing the history segment, mark all unseen rows as seen
      // (auto-clears the bell badge for these outcomes).
      const markedSeenRef = useRef(new Set());
      useEffect(() => {
        if (seg !== "history" || !data) return;
        const resolved = data.resolved || [];
        const unseen = resolved.filter(r => !r.seen_by_me && !markedSeenRef.current.has(r.id));
        if (unseen.length === 0) return;
        unseen.forEach(r => markedSeenRef.current.add(r.id));
        Promise.all(unseen.map(r =>
          api("combat/challenge_mark_seen", { challenge_id: r.id }).catch(() => {})
        )).then(() => {
          setReload(x => x + 1);
          onAction && onAction();
        });
      }, [seg, data]);

      async function respond(challenge_id, action) {
        if (busyId) return;
        setBusyId(challenge_id);
        try {
          const res = await api("combat/challenge_respond", { challenge_id, action });
          if (!res.ok) {
            haptic("error");
            const map = {
              expired:                  t("combat_pvp_expired"),
              not_pending:              t("combat_pvp_already_resolved"),
              hp_depleted:              hpDepletedMsg("combat_pvp_hp_depleted"),
              challenger_hp_depleted:   t("combat_pvp_challenger_hp_depleted"),
              wager_no_funds_self:      t("combat_pvp_wager_no_funds_self"),
              wager_no_funds_challenger:t("combat_pvp_wager_no_funds_chal"),
            };
            showToast(map[res.reason] || t("combat_pvp_action_failed"), "err");
            setReload(x => x + 1);
            onAction();
            return;
          }
          haptic("success");
          if (action === "accept") {
            // Hand off to the result modal — close inbox and surface fight.
            onAccepted(res);
            return;
          }
          if (action === "decline") showToast(t("combat_pvp_decline_ok"));
          if (action === "cancel")  showToast(t("combat_pvp_cancel_ok"));
          setReload(x => x + 1);
          onAction();
        } catch (e) {
          haptic("error");
          showToast(e.message, "err");
        } finally {
          setBusyId(null);
        }
      }

      // Replay a past fight in the result modal — fetch via inbox already
      // returns rounds_data for resolved completed rows.
      function viewHistory(entry) {
        if (entry.status !== "completed") {
          // Decline/cancel/expired don't have rounds — show toast outcome.
          const labelMap = {
            declined:   t("combat_pvp_history_declined"),
            cancelled:  t("combat_pvp_history_cancelled"),
            expired:    t("combat_pvp_history_expired"),
          };
          showToast(labelMap[entry.status] || entry.status);
          return;
        }
        // Need the full unseen-outcome shape — synthesise from history row.
        const opp = entry.is_outgoing ? entry.target_dao_name : entry.challenger_dao_name;
        const oppRealm = entry.is_outgoing ? entry.target_realm : entry.challenger_realm;
        // We don't have rounds in the history list (only in unseen_outcomes).
        // For seen rows we'd need a fetch — for now the Histórico just shows
        // outcome label; tap will display a toast with details.
        showToast((entry.you_won
          ? t("combat_pvp_history_won")
          : entry.is_draw
            ? t("combat_pvp_history_draw")
            : t("combat_pvp_history_lost")) + " · " + opp);
      }

      const incoming = (data && data.incoming) || [];
      const outgoing = (data && data.outgoing) || [];
      const resolved = (data && data.resolved) || [];
      const opts = [
        { value:"incoming", label: t("combat_pvp_inbox_incoming", { n: incoming.length }) },
        { value:"outgoing", label: t("combat_pvp_inbox_outgoing", { n: outgoing.length }) },
        { value:"history",  label: t("combat_pvp_inbox_history",  { n: resolved.length }) },
      ];

      let listView;
      if (seg === "history") {
        listView = (
          resolved.length === 0 ? (
            <div style={{ textAlign:"center", padding:"24px 8px",
                          color:"var(--muted)", fontSize:12 }}>
              {t("combat_pvp_inbox_history_empty")}
            </div>
          ) : (
            <div style={{ display:"flex", flexDirection:"column", gap:8, marginTop:9 }}>
              {resolved.map(ch => (
                <PvPHistoryRow key={ch.id} ch={ch} onClick={() => viewHistory(ch)} />
              ))}
            </div>
          )
        );
      } else {
        const list = seg === "incoming" ? incoming : outgoing;
        listView = (
          list.length === 0 ? (
            <div style={{ textAlign:"center", padding:"24px 8px",
                          color:"var(--muted)", fontSize:12 }}>
              {seg === "incoming"
                ? t("combat_pvp_inbox_empty_incoming")
                : t("combat_pvp_inbox_empty_outgoing")}
            </div>
          ) : (
            <div style={{ display:"flex", flexDirection:"column", gap:8, marginTop:9 }}>
              {list.map(ch => (
                <PvPInboxRow key={ch.id} ch={ch} seg={seg}
                             busy={busyId === ch.id}
                             onRespond={respond} />
              ))}
            </div>
          )
        );
      }

      return (
        <Modal onClose={onClose} title={`📨 ${t("combat_pvp_inbox_title")}`}
               accent="rgba(var(--gold2-rgb),.55)" maxWidth={420} zIndex={70}>
          <SegControl options={opts} value={seg} onChange={setSeg} />
          {loading && !data && <ListSkeleton rows={3} />}
          {error && <ErrBanner msg={error} />}
          {data && listView}
        </Modal>
      );
    }

    // ── PvP History Row ────────────────────────────────────────────────────
    function PvPHistoryRow({ ch, onClick }) {
      const opponent = ch.is_outgoing ? ch.target_dao_name : ch.challenger_dao_name;
      const oppEmoji = ch.is_outgoing ? ch.target_realm_emoji : ch.challenger_realm_emoji;
      const dirLabel = ch.is_outgoing
        ? t("combat_pvp_history_outgoing_to", { name: opponent })
        : t("combat_pvp_history_incoming_from", { name: opponent });

      let outcomeLabel, outcomeColor;
      if (ch.status === "completed") {
        if (ch.is_draw) {
          outcomeLabel = t("combat_pvp_history_draw");
          outcomeColor = "var(--text)";
        } else if (ch.you_won) {
          outcomeLabel = t("combat_pvp_history_won");
          outcomeColor = "var(--jade)";
        } else {
          outcomeLabel = t("combat_pvp_history_lost");
          outcomeColor = "var(--red2)";
        }
      } else if (ch.status === "declined") {
        outcomeLabel = t("combat_pvp_history_declined");
        outcomeColor = "var(--muted)";
      } else if (ch.status === "cancelled") {
        outcomeLabel = t("combat_pvp_history_cancelled");
        outcomeColor = "var(--muted)";
      } else {
        outcomeLabel = t("combat_pvp_history_expired");
        outcomeColor = "var(--muted)";
      }

      const ageMs = Date.now() - (ch.resolved_at_ms || ch.created_at_ms || Date.now());
      return (
        <div onClick={onClick}
             style={{
               padding:"9px 11px", borderRadius:9,
               background:"linear-gradient(180deg,rgba(var(--surface-rgb),.7),rgba(var(--surface3-rgb),.85))",
               border:"1px solid rgba(var(--glow-rgb),.25)",
               cursor: ch.status === "completed" ? "pointer" : "default",
             }}>
          <div style={{ display:"flex", alignItems:"center", gap:9 }}>
            <div style={{ fontSize:22, lineHeight:1, flexShrink:0 }}>{oppEmoji}</div>
            <div style={{ flex:1, minWidth:0 }}>
              <div style={{ display:"flex", justifyContent:"space-between",
                            alignItems:"baseline", gap:6 }}>
                <span style={{ fontSize:11.5, fontWeight:600, color:"var(--gold2)",
                               fontFamily:"'Cinzel',serif", letterSpacing:.3,
                               whiteSpace:"nowrap", overflow:"hidden", textOverflow:"ellipsis" }}>
                  {dirLabel}
                </span>
                {!ch.seen_by_me && (
                  <span style={{ fontSize:9.5, padding:"1px 6px", borderRadius:4,
                                 background:"rgba(var(--gold2-rgb),.2)", color:"var(--gold3)",
                                 fontFamily:"'Cinzel',serif", letterSpacing:.5,
                                 textTransform:"uppercase", flexShrink:0 }}>
                    {t("combat_pvp_history_unseen_chip")}
                  </span>
                )}
              </div>
              <div style={{ fontSize:11, marginTop:2, color: outcomeColor, fontWeight:600 }}>
                {outcomeLabel}
                {ch.wager > 0 && (
                  <span style={{ marginLeft:6, color:"var(--muted)", fontWeight:400 }}>
                    · {fmtNum(ch.wager)} 🪨
                  </span>
                )}
              </div>
              <div style={{ fontSize:10, color:"var(--muted)", marginTop:2 }}>
                {t("combat_pvp_history_resolved_at", { time: fmtDuration(ageMs) })}
              </div>
            </div>
          </div>
        </div>
      );
    }

    function PvPInboxRow({ ch, seg, busy, onRespond }) {
      const [, setTick] = useState(0);
      useEffect(() => {
        const i = setInterval(() => setTick(x => x + 1), 1000);
        return () => clearInterval(i);
      }, []);
      const remaining = Math.max(0, (ch.expires_at_ms || 0) - Date.now());
      const expiringSoon = remaining < 60000;
      const otherEmoji = seg === "incoming" ? ch.challenger_realm_emoji : ch.target_realm_emoji;
      const otherName = seg === "incoming" ? ch.challenger_dao_name : ch.target_dao_name;

      return (
        <div style={{
          padding:"9px 11px", borderRadius:9,
          background:"linear-gradient(180deg,rgba(var(--surface-rgb),.7),rgba(var(--surface3-rgb),.85))",
          border:`1px solid ${expiringSoon ? "rgba(var(--red-rgb),.4)" : "rgba(var(--glow-rgb),.32)"}`,
        }}>
          <div style={{ display:"flex", alignItems:"center", gap:9, marginBottom:7 }}>
            <div style={{ fontSize:24, lineHeight:1, flexShrink:0 }}>{otherEmoji}</div>
            <div style={{ flex:1, minWidth:0 }}>
              <div style={{ fontSize:12.5, fontWeight:700, color:"var(--gold2)",
                            fontFamily:"'Cinzel',serif", letterSpacing:.3,
                            whiteSpace:"nowrap", overflow:"hidden", textOverflow:"ellipsis" }}>
                {otherName}
              </div>
              <div style={{ fontSize:10.5, color:"var(--muted)", marginTop:2 }}>
                {ch.wager > 0
                  ? t("combat_pvp_inbox_wager_label", { n: fmtNum(ch.wager) })
                  : t("combat_pvp_inbox_no_wager")}
                {" · "}
                <span style={{ color: expiringSoon ? "var(--red2)" : "var(--gold3)" }}>
                  {t("combat_pvp_inbox_expires_in", { time: fmtDuration(remaining) })}
                </span>
              </div>
            </div>
          </div>
          <div style={{ display:"flex", gap:6 }}>
            {seg === "incoming" ? (
              <>
                <ActionBtn variant="primary" disabled={busy}
                           onClick={() => onRespond(ch.id, "accept")}
                           style={{ flex:1, padding:"6px 8px", fontSize:11 }}>
                  {t("combat_pvp_btn_accept")}
                </ActionBtn>
                <ActionBtn variant="danger" disabled={busy}
                           onClick={() => onRespond(ch.id, "decline")}
                           style={{ flex:1, padding:"6px 8px", fontSize:11 }}>
                  {t("combat_pvp_btn_decline")}
                </ActionBtn>
              </>
            ) : (
              <ActionBtn variant="danger" disabled={busy}
                         onClick={() => onRespond(ch.id, "cancel")}
                         style={{ flex:1, padding:"6px 8px", fontSize:11 }}>
                {t("combat_pvp_btn_cancel")}
              </ActionBtn>
            )}
          </div>
        </div>
      );
    }

    // ─── Home Tab (MA-32b — hub with drill-in cards) ─────────────────────────
    // 8 cards in a 2-col grid. Live stats come from /api/miniapp/home_summary
    // (single round-trip). Cards that don't need live stats use scalar values
    // already on `player`. Cards navigate to existing tabs (preserves all
    // MA-26..MA-32 work — destinations weren't deleted, just hidden from nav).
    // R5: accents em HEX LITERAL (espelho da paleta --realm-*/--gold*/... do
    // index.html) — o HomeCard concatena alpha no hover/medalhão/glow do ícone
    // e com var()/rgba() a declaração inteira morria silenciosa desde sempre.
    var HOME_CARDS = [
      { key:"sect",          tab:"sect",          icon:"🏯", mark:"pagoda", title_key:"home_card_sect",          accent:"var(--gold2)" },
      { key:"guild",         tab:"guild",         icon:"🤝", mark:"allies", title_key:"home_card_guild",         accent:"var(--gold2)" },
      // Onda 4a — Continental Plaza (Wànshì): "há outras almas aqui" + Bounty Board.
      { key:"plaza",         tab:"plaza",         icon:"🏙️", mark:"city", title_key:"home_card_plaza",         accent:"var(--realm-4)" },
      // Onda 5 — Reinos Exploráveis: explore the continent by Divine Sense (神識).
      { key:"explore",       tab:"explore",       icon:"🧭", mark:"compass", title_key:"home_card_explore",       accent:"var(--realm-5)" },
      // Onda 5 Fase 2 — Caverna Pessoal 洞府 + Matrizes/Formações 阵法.
      { key:"cavern",        tab:"cavern",        icon:"🏯", mark:"formation", title_key:"home_card_cavern",        accent:"var(--gold3)" },
      { key:"world_boss",    tab:"world_boss",    icon:"🐉", mark:"dragon", title_key:"home_card_boss",          accent:"var(--red)" },
      { key:"dungeons",      tab:"dungeons",      icon:"🏛️", mark:"portal", title_key:"home_card_dungeons",      accent:"var(--realm-3)" },
      { key:"shop",          tab:"shop",          icon:"💎", mark:"jade", title_key:"home_card_shop",          accent:"var(--gold3)" },
      // v14.9 MA-35 — Combat tab drill-in card (real surface, no longer stub).
      { key:"combat",        tab:"combat",        icon:"⚔️", mark:"sword", title_key:"home_card_combat",        accent:"var(--red)" },
      // v14.10 MA-37 / MA-38 — Bestiário + Facção drill-in cards.
      { key:"beasts",        tab:"beasts",        icon:"🐾", mark:"paw", title_key:"home_card_beasts",        accent:"var(--warn)" },
      { key:"faction",       tab:"faction",       icon:"🔱", mark:"banner", title_key:"home_card_faction",       accent:"var(--realm-6)" },
      // v14.13 MA-43 — Celestial / Mahayana drill-in card (gate realm 8+
      // surfaced inside the tab; card always visible for discoverability so
      // pre-Mahayana players see the launch teaser via the empty state).
      { key:"celestial",     tab:"celestial",     icon:"🌠", mark:"heavens", title_key:"home_card_celestial",     accent:"var(--realm-8)" },
      // v14.14e — Body Tempering dedicated drill-in tab (Nine Transformations).
      { key:"body_tempering",tab:"body_tempering",icon:"💪", mark:"stance", title_key:"home_card_body_tempering",accent:"var(--gold2)" },
      // v14.14i — Dao Partner (marriage trope, Wuxia canónico).
      { key:"partner",       tab:"partner",       icon:"💞", mark:"knot", title_key:"home_card_partner",       accent:"#dc78b4" },
      // v14.12 MA-39 — Mercado drill-in card (P2P listings + auctions).
      { key:"market",        tab:"market",        icon:"💰", mark:"coin", title_key:"home_card_market",        accent:"var(--gold2)" },
      // v14.13d MA-40 — Battle Pass / Celestial Pass missions drill-in.
      { key:"battle_pass",   tab:"battle_pass",   icon:"🎫", mark:"tally", title_key:"home_card_battle_pass",   accent:"var(--realm-2)" },
      { key:"quests",        tab:"quests",        icon:"🎯", mark:"notice", title_key:"home_card_quests",        accent:"var(--jade)" },
      { key:"leaderboard",   tab:"leaderboard",   icon:"🏆", mark:"ranks", title_key:"home_card_ranking",       accent:"var(--gold2)" },
      // v14.8 MA-36 — Achievements drill-in (modal, not tab).
      { key:"achievements",  tab:"achievements",  icon:"🏆", mark:"stele", title_key:"home_card_achievements",  accent:"var(--gold3)" },
      { key:"announcements", tab:"announcements", icon:"📜", mark:"bell", title_key:"home_card_announcements", accent:"var(--realm-1)" },
    ];

    // ─── Tribulation Modal (Sprint v14.8 MA-34) ──────────────────────────────
    // Drill-in modal opened from CultivationTab when a tribulation is pending
    // or in-progress. Views:
    //   preview     → header + phases + stats + chances + buffs + fail block
    //   strategy    → 3 buttons (resist/dodge/absorb) for Thunder
    //   running     → Thunder cinematic with per-round messages
    //   reveal      → Thunder outcome banner (success/perfect/fail) + next path
    //   hd_intro    → Heart Demon tutorial + dominant Dao + Begin button [v15.1.3.h2]
    //   hd_question → Heart Demon question with 3 options + perception hint
    //   hd_reveal   → after a HD answer: feedback + score, then next q OR phase result
    //   dao_preview → Dao Trial chance + fragments + penalties + Attack/Retreat
    //   dao_reveal  → Dao Trial outcome banner + realm-up if all phases done
    //   gated       → no active tribulation (empty state)
    //   history     → list of last 10 (overlay swap)
    function TribulationModal({ onClose, onResolved }) {
      const [view, setView] = useState("preview");
      const [data, setData] = useState(null);
      const [errMsg, setErrMsg] = useState(null);
      const [strategy, setStrategy] = useState(null);
      const [runState, setRunState] = useState(null);
      const [reveal, setReveal] = useState(null);
      const [historyData, setHistoryData] = useState(null);
      const [reloadKey, setReloadKey] = useState(0);
      // v15.1.3.h2 — Heart Demon + Dao state.
      const [hdState, setHdState] = useState(null);     // {q_idx, score, question_key, option_keys, dominant_element, perception_hint, ...}
      const [hdLast, setHdLast] = useState(null);       // {is_correct, score, q_idx, phase_done, phase_passed, next_phase, granted, ...}
      const [daoData, setDaoData] = useState(null);     // dao_preview response
      const [daoResult, setDaoResult] = useState(null); // dao_attempt response
      const [phaseBusy, setPhaseBusy] = useState(false);

      useEffect(() => {
        let cancelled = false;
        (async () => {
          setErrMsg(null);
          try {
            const res = await api("tribulation/preview");
            if (!cancelled) setData(res);
          } catch (e) {
            if (!cancelled) setErrMsg(e.message);
          }
        })();
        return () => { cancelled = true; };
      }, [reloadKey]);

      const trib = data?.trib;
      const phaseToTKey = (p) => p === "thunder" ? "trib_phase_thunder" :
                                p === "heart_demon" ? "trib_phase_heart_demon" :
                                p === "dao" ? "trib_phase_dao" : null;
      const strategyLabel = (s) => s === "resist" ? t("trib_strategy_resist") :
                                   s === "dodge" ? t("trib_strategy_dodge") :
                                   s === "absorb" ? t("trib_strategy_absorb") : s || "—";

      async function startThunder() {
        if (!strategy) return;
        haptic("warning");
        setView("running");
        try {
          const res = await api("tribulation/attempt", { strategy });
          if (!res || !res.ok) {
            // phase_requires_chat or other server-side reject
            setErrMsg(res?.reason || "engine_error");
            setView("preview");
            haptic("error");
            return;
          }
          // Replay rounds with delays for the cinematic.
          setRunState({ rounds: [], total: res.rounds_total, current: 0 });
          for (let i = 0; i < res.rounds.length; i++) {
            await new Promise(r => setTimeout(r, 850));
            // eslint-disable-next-line no-loop-func
            setRunState({
              rounds: res.rounds.slice(0, i + 1),
              total: res.rounds_total,
              current: i + 1,
              latest: res.rounds[i],
            });
            haptic(res.rounds[i].success ? "light" : "warning");
          }
          await new Promise(r => setTimeout(r, 700));
          setReveal(res);
          setView("reveal");
          if (res.outcome === "perfect" || res.outcome === "success") {
            haptic("success");
          } else {
            haptic("error");
          }
          // Refresh player resources downstream.
          if (onResolved) onResolved(res);
        } catch (e) {
          setErrMsg(e.message);
          setView("preview");
          haptic("error");
        }
      }

      async function loadHistory() {
        setView("history");
        setHistoryData(null);
        try {
          const res = await api("tribulation/history", { limit: 10 });
          setHistoryData(res);
        } catch (e) {
          setHistoryData({ items: [], error: e.message });
        }
      }

      // ── v15.1.3.h2 Heart Demon flow ───────────────────────────────────────
      async function openHeartDemon() {
        setView("hd_intro");
        setHdLast(null);
        try {
          const res = await api("tribulation/hd_state");
          if (!res || !res.ok) { setErrMsg(res?.reason || "engine_error"); setView("preview"); return; }
          setHdState(res);
        } catch (e) { setErrMsg(e.message); setView("preview"); }
      }
      function beginHeartDemon() {
        // From intro → first question (state already loaded by openHeartDemon).
        haptic("warning");
        setView("hd_question");
      }
      async function answerHd(optIdx) {
        if (phaseBusy) return;
        setPhaseBusy(true);
        haptic("select");
        try {
          const res = await api("tribulation/hd_answer", { option_idx: optIdx });
          if (!res || !res.ok) { setErrMsg(res?.reason || "engine_error"); setPhaseBusy(false); return; }
          setHdLast(res);
          setView("hd_reveal");
          haptic(res.is_correct ? "success" : "warning");
          // If phase still running, after a brief beat fetch next question.
          if (!res.phase_done) {
            setTimeout(async () => {
              try {
                const nxt = await api("tribulation/hd_state");
                if (nxt && nxt.ok) {
                  setHdState(nxt);
                  setView("hd_question");
                  setHdLast(null);
                }
              } catch {}
              setPhaseBusy(false);
            }, 1200);
          } else {
            // Phase resolved — surface bell, refresh downstream resources.
            if (res.phase_passed) haptic("success"); else haptic("error");
            if (onResolved) onResolved(res);
            setPhaseBusy(false);
          }
        } catch (e) { setErrMsg(e.message); setPhaseBusy(false); }
      }

      // ── v15.1.3.h2 Dao Trial flow ─────────────────────────────────────────
      async function openDao() {
        setView("dao_preview");
        setDaoResult(null);
        try {
          const res = await api("tribulation/dao_preview");
          if (!res || !res.ok) { setErrMsg(res?.reason || "engine_error"); setView("preview"); return; }
          setDaoData(res);
        } catch (e) { setErrMsg(e.message); setView("preview"); }
      }
      async function attackDao() {
        if (phaseBusy) return;
        setPhaseBusy(true);
        haptic("warning");
        try {
          const res = await api("tribulation/dao_attempt");
          if (!res || !res.ok) { setErrMsg(res?.reason || "engine_error"); setPhaseBusy(false); return; }
          setDaoResult(res);
          setView("dao_reveal");
          haptic(res.passed ? "success" : "error");
          if (onResolved) onResolved(res);
        } catch (e) { setErrMsg(e.message); }
        finally { setPhaseBusy(false); }
      }

      // ── Sub-renderers ─────────────────────────────────────────────────────
      function renderPhases(phases) {
        if (!phases || !phases.length) return null;
        return (
          <div style={{ display:"flex", flexWrap:"wrap", gap:6 }}>
            {phases.map((p, i) => {
              const tk = phaseToTKey(p.phase);
              const name = tk ? t(tk) : p.phase;
              const status = p.completed ? "✅" : (p.is_next ? "⚡" : "⏳");
              return (
                <span key={i} style={{
                  display:"inline-flex", alignItems:"center", gap:5,
                  padding:"3px 9px", borderRadius:99,
                  background: p.completed ? "rgba(var(--jade-rgb),.15)" : (p.is_next ? "rgba(var(--gold2-rgb),.18)" : "rgba(0,0,0,.4)"),
                  border:`1px solid ${p.completed ? "rgba(var(--jade-rgb),.45)" : (p.is_next ? "rgba(var(--gold2-rgb),.55)" : "rgba(var(--glow-rgb),.25)")}`,
                  fontSize:11, fontFamily:"'Cinzel',serif",
                  color: p.completed ? "var(--jade)" : (p.is_next ? "var(--gold3)" : "var(--muted)"),
                }}>
                  {status} {i + 1}/{phases.length} · {name}
                </span>
              );
            })}
          </div>
        );
      }

      function renderPreview() {
        if (errMsg && !trib) {
          return <ErrBanner msg={errMsg} />;
        }
        if (!data) {
          return (
            <div style={{ padding:"22px 0", textAlign:"center", color:"var(--muted)", fontSize:12 }}>
              <DotSpinner /><div style={{ marginTop:8 }}>{t("trib_loading")}</div>
            </div>
          );
        }
        if (!trib) {
          return (
            <div style={{ textAlign:"center", padding:"24px 8px" }}>
              <div style={{ fontSize:42, marginBottom:8, opacity:.7 }}>⛅</div>
              <div style={{ fontSize:13, color:"var(--gold3)", fontFamily:"'Cinzel',serif", letterSpacing:.4 }}>
                {t("trib_no_active")}
              </div>
              <div style={{ fontSize:11, color:"var(--muted)", marginTop:8, lineHeight:1.5 }}>
                {t("trib_no_active_hint")}
              </div>
            </div>
          );
        }

        return (
          <>
            <div style={{
              padding:"10px 12px",
              background:"rgba(0,0,0,.35)", border:"1px dashed rgba(var(--gold2-rgb),.32)",
              borderRadius:10, textAlign:"center", marginBottom:10,
            }}>
              <div style={{ fontSize:9.5, color:"var(--muted)", letterSpacing:1, textTransform:"uppercase",
                            fontFamily:"'Cinzel',serif" }}>
                {t("trib_target_label")}
              </div>
              <div style={{ marginTop:4, fontSize:14, fontFamily:"'Cinzel',serif", color:"var(--gold2)" }}>
                {trib.target_realm_emoji} {trib.target_realm_name}
              </div>
              {trib.expires_at_ms && (
                <div style={{ fontSize:10.5, color:"var(--muted)", marginTop:4 }}>
                  {t("trib_expires_in", { time: fmtDuration(Math.max(0, trib.expires_at_ms - Date.now())) })}
                </div>
              )}
            </div>

            <Card style={{ padding:"10px 12px 8px", marginBottom:10 }}>
              <CardTitle left={t("trib_phases_header")} />
              {renderPhases(trib.phases)}
              {trib.next_phase && trib.next_phase !== "thunder" && (
                <div style={{
                  marginTop:10, padding:"8px 10px", borderRadius:8,
                  background:"rgba(120,180,255,.10)", border:"1px solid rgba(120,180,255,.35)",
                }}>
                  <div style={{ fontSize:11, color:"var(--gold3)", fontWeight:600,
                                fontFamily:"'Cinzel',serif", letterSpacing:.4 }}>
                    {trib.next_phase === "heart_demon"
                      ? t("trib_phase_heart_demon_ready_title")
                      : t("trib_phase_dao_ready_title")}
                  </div>
                  <div style={{ fontSize:11, color:"var(--text)", marginTop:4, lineHeight:1.5 }}>
                    {trib.next_phase === "heart_demon"
                      ? t("trib_phase_heart_demon_ready_body")
                      : t("trib_phase_dao_ready_body")}
                  </div>
                </div>
              )}
            </Card>

            {trib.stats && (
              <Card style={{ padding:"10px 12px 8px", marginBottom:10 }}>
                <CardTitle left={t("trib_stats_header")} />
                <StatGrid stats={[
                  { label:t("trib_stat_soul"),       value:fmtNum(trib.stats.soul_strength) },
                  { label:t("trib_stat_bp"),         value:fmtNum(trib.stats.battle_power) },
                  { label:t("trib_stat_perception"), value:fmtNum(trib.stats.perception) },
                ]} />
              </Card>
            )}

            {trib.chances && (
              <Card style={{ padding:"10px 12px 8px", marginBottom:10 }}>
                <CardTitle left={t("trib_chances_header")} />
                <KVRow label={t("trib_strategy_resist")} value={`${trib.chances.resist}%`} />
                <KVRow label={t("trib_strategy_dodge")}  value={`${trib.chances.dodge}%`} />
                <KVRow label={t("trib_strategy_absorb")} value={`${trib.chances.absorb}%`} />
              </Card>
            )}

            {/* MV-11 天时 — O TEMPO DO CÉU, colado às chances que ele acabou de
                mover. `line` e `next.line` são server-resolved (o servidor já as
                escreveu no idioma do jogador, com antes→depois) — imprimir CRUAS,
                nunca passar por t(). A key só chega com `tempo_do_ceu` ON; OFF →
                ausente → payload byte-idêntico.
                ⚠️ O precedente `karma_severity` (webserver.py:10350) é a razão de
                este bloco existir: aquela key é emitida pelo servidor desde a v16.3
                e NUNCA foi renderizada em lado nenhum — emitir key ≠ mostrar ao
                jogador. */}
            {trib.tianshi && (
              <Card style={{ padding:"10px 12px 8px", marginBottom:10,
                             border:"1px solid rgba(var(--accent2-rgb),.28)" }}>
                <div style={{ fontSize:12, color:"var(--text)", lineHeight:1.5 }}>
                  {trib.tianshi.line}
                </div>
                {trib.tianshi.next && trib.tianshi.next.line && (
                  <div style={{ fontSize:10.5, color:"var(--muted)", marginTop:5, lineHeight:1.45 }}>
                    {trib.tianshi.next.line}
                  </div>
                )}
              </Card>
            )}

            {trib.dao && (
              <Card style={{ padding:"10px 12px 8px", marginBottom:10 }}>
                <CardTitle left={t("trib_dao_header")} />
                <KVRow label={t("trib_dao_chance", { chance: trib.dao.chance })} value="" />
                <KVRow label={t("trib_dao_fragments", { have: trib.dao.total_fragments, required: trib.dao.required })} value="" />
                {trib.dao.perfect_bonus && (
                  <div style={{ fontSize:11, color:"var(--jade)", marginTop:4 }}>{t("trib_dao_perfect_bonus")}</div>
                )}
                {trib.dao.tribulation_bonus && (
                  <div style={{ fontSize:11, color:"var(--gold2)", marginTop:4 }}>{t("trib_dao_laws_bonus")}</div>
                )}
                {trib.dao.penalties.includes("foundation") && (
                  <div style={{ fontSize:11, color:"var(--red2)", marginTop:4 }}>{t("trib_dao_penalty_foundation")}</div>
                )}
                {trib.dao.penalties.includes("core") && (
                  <div style={{ fontSize:11, color:"var(--red2)", marginTop:4 }}>{t("trib_dao_penalty_core")}</div>
                )}
              </Card>
            )}

            <Card style={{ padding:"10px 12px 8px", marginBottom:10 }}>
              <CardTitle left={t("trib_buffs_header")} />
              {(trib.buffs && trib.buffs.length > 0) ? (
                <div style={{ display:"flex", flexDirection:"column", gap:4 }}>
                  {trib.buffs.map((b, i) => (
                    <div key={i} style={{ fontSize:11, color:"var(--gold3)", lineHeight:1.4 }}>
                      {b.type === "trib_insurance" && t("trib_buff_insurance")}
                      {b.type === "trib_blessing"  && t("trib_buff_blessing")}
                      {b.type === "revive"         && t("trib_buff_revive")}
                    </div>
                  ))}
                </div>
              ) : (
                <div style={{ fontSize:11, color:"var(--muted)", fontStyle:"italic" }}>{t("trib_buffs_none")}</div>
              )}
            </Card>

            <Card style={{ padding:"10px 12px 8px", marginBottom:10 }}>
              <CardTitle left={t("trib_fail_block_header")} />
              <div style={{ fontSize:11, color:"var(--muted)", lineHeight:1.6 }}>
                <div>{t("trib_fail_light")}</div>
                <div>{t("trib_fail_grave")}</div>
                <div>{t("trib_fail_cooldown", { hours: Math.round((trib.fail.cooldown_seconds || 0) / 3600) })}</div>
              </div>
            </Card>

            {errMsg && <ErrBanner msg={errMsg} />}
          </>
        );
      }

      function renderStrategy() {
        const opts = [
          { key:"resist", label:t("trib_strategy_resist"), desc:t("trib_strategy_resist_desc"), chance:trib?.chances?.resist },
          { key:"dodge",  label:t("trib_strategy_dodge"),  desc:t("trib_strategy_dodge_desc"),  chance:trib?.chances?.dodge },
          { key:"absorb", label:t("trib_strategy_absorb"), desc:t("trib_strategy_absorb_desc"), chance:trib?.chances?.absorb },
        ];
        return (
          <>
            <div style={{ fontSize:12, color:"var(--muted)", textAlign:"center", marginBottom:10, lineHeight:1.5 }}>
              {t("trib_attempt_choose")}
            </div>
            {/* MV-11 天时 — a tela DO TAP. Os 3 botões abaixo carregam a chance
                já mordida pelo céu; sem esta linha o número mudava e ninguém
                dizia porquê ("se mudar, tem de o DIZER antes do tap"). Mesmo
                bloco server-resolved da preview — as duas telas nunca divergem
                porque leem a MESMA key do MESMO payload. */}
            {trib && trib.tianshi && (
              <div style={{ fontSize:11, color:"var(--text)", marginBottom:10, lineHeight:1.5,
                            padding:"8px 10px", borderRadius:8,
                            background:"rgba(var(--accent2-rgb),.08)",
                            border:"1px solid rgba(var(--accent2-rgb),.24)" }}>
                {trib.tianshi.line}
                {trib.tianshi.next && trib.tianshi.next.line && (
                  <div style={{ fontSize:10.5, color:"var(--muted)", marginTop:4 }}>
                    {trib.tianshi.next.line}
                  </div>
                )}
              </div>
            )}
            <div style={{ display:"grid", gap:8 }}>
              {opts.map(o => (
                <button key={o.key}
                        onClick={() => { haptic("select"); setStrategy(o.key); }}
                        style={{
                          textAlign:"left", padding:"10px 12px",
                          background: strategy === o.key
                            ? "linear-gradient(180deg,rgba(var(--gold2-rgb),.18),rgba(155,110,40,.28))"
                            : "linear-gradient(180deg,rgba(var(--surface-rgb),.7),rgba(var(--surface3-rgb),.85))",
                          border:`1px solid ${strategy === o.key ? "var(--gold2)" : "rgba(var(--glow-rgb),.3)"}`,
                          borderRadius:10, cursor:"pointer", color:"var(--text)",
                          transition:"all .15s",
                        }}>
                  <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center" }}>
                    <span style={{ fontFamily:"'Cinzel',serif", fontSize:13, fontWeight:700,
                                   color: strategy === o.key ? "var(--gold3)" : "var(--gold2)" }}>
                      {o.label}
                    </span>
                    <span style={{ fontSize:11, color:"var(--text)", fontWeight:600 }}>{o.chance ?? "?"}%</span>
                  </div>
                  <div style={{ fontSize:10.5, color:"var(--muted)", marginTop:4, lineHeight:1.4 }}>
                    {o.desc}
                  </div>
                </button>
              ))}
            </div>
          </>
        );
      }

      function renderRunning() {
        const latest = runState?.latest;
        const flashKey = runState?.current ?? 0;
        return (
          <div style={{ position:"relative", minHeight:240 }}>
            {/* Lightning flash backdrop — keyed by round so it re-fires per round */}
            <div key={`flash-${flashKey}`} style={{
              position:"absolute", inset:-14, pointerEvents:"none",
              animation:"trib-lightning-flash .55s ease-out",
            }} />
            <div style={{ textAlign:"center", padding:"6px 0 16px", position:"relative" }}>
              <div style={{ fontSize:46, lineHeight:1, animation:"trib-storm 1.3s ease-in-out infinite",
                            filter:"drop-shadow(0 0 14px rgba(120,180,255,.7))" }}>⚡</div>
              <div style={{ fontFamily:"'Cinzel',serif", fontSize:14, color:"var(--gold2)",
                            marginTop:8, letterSpacing:1 }}>
                {t("trib_attempt_running")}
              </div>
              <div style={{ fontSize:10.5, color:"var(--muted)", marginTop:4, fontFamily:"'Cinzel',serif" }}>
                {t("trib_strategy_picked", { strategy: strategyLabel(strategy) })}
              </div>
            </div>
            <div style={{ display:"flex", flexDirection:"column", gap:6 }}>
              {(runState?.rounds || []).map((r, i) => (
                <div key={i} style={{
                  display:"flex", justifyContent:"space-between", alignItems:"center",
                  padding:"7px 11px", borderRadius:8,
                  background: r.success ? "rgba(var(--jade-rgb),.08)" : "rgba(var(--red-rgb),.08)",
                  border:`1px solid ${r.success ? "rgba(var(--jade-rgb),.32)" : "rgba(var(--red-rgb),.32)"}`,
                  animation:"fade-up .35s ease",
                }}>
                  <span style={{ fontSize:11, fontFamily:"'Cinzel',serif",
                                 color: r.success ? "var(--jade)" : "var(--red2)", letterSpacing:.4 }}>
                    {t("trib_round_label", { n: r.round, total: runState?.total ?? "?" })}
                  </span>
                  <span style={{ fontSize:11, color: r.success ? "var(--jade)" : "var(--red2)" }}>
                    {r.success
                      ? t("trib_round_survived", { dmg: fmtNum(r.damage) })
                      : t("trib_round_hit", { dmg: fmtNum(r.damage) })}
                  </span>
                </div>
              ))}
            </div>
          </div>
        );
      }

      function renderReveal() {
        if (!reveal) return null;
        const isWin = reveal.outcome === "success" || reveal.outcome === "perfect";
        const granted = reveal.granted;
        const realmCol = granted
          ? `var(--realm-${Math.min(granted.new_realm || 0, 10)})`
          : (isWin ? "var(--gold2)" : "var(--red2)");
        return (
          <div style={{ textAlign:"center", padding:"6px 0" }}>
            <div style={{
              fontSize:62, lineHeight:1, marginBottom:8,
              filter:`drop-shadow(0 0 22px ${realmCol})`,
              animation: isWin ? "bt-reveal 1s cubic-bezier(.2,.8,.2,1)" : "trib-shake-light .25s ease-in-out 3",
            }}>
              {granted ? granted.new_realm_emoji : (isWin ? "⚡" : "💥")}
            </div>
            <div style={{
              fontFamily:"'Cinzel',serif", fontSize:18, fontWeight:700,
              color: realmCol, letterSpacing:1.2,
              textShadow: isWin ? `0 0 20px ${realmCol}` : "none",
            }}>
              {reveal.outcome === "perfect"        && t("trib_outcome_perfect")}
              {reveal.outcome === "success"        && t("trib_outcome_success")}
              {reveal.outcome === "failure_light"  && t("trib_outcome_failure_light")}
              {reveal.outcome === "failure_grave"  && t("trib_outcome_failure_grave")}
            </div>
            {granted && (
              <div style={{ marginTop:14, padding:"10px 12px", borderRadius:10,
                            background:"rgba(var(--gold2-rgb),.1)", border:"1px solid rgba(var(--gold2-rgb),.4)" }}>
                <div style={{ fontSize:10, color:"var(--muted)", letterSpacing:1, textTransform:"uppercase",
                              fontFamily:"'Cinzel',serif" }}>
                  {t("trib_realm_up_title")}
                </div>
                <div style={{ marginTop:4, fontSize:14, color:"var(--gold3)", fontFamily:"'Cinzel',serif" }}>
                  {granted.new_realm_emoji} {granted.new_realm_name}
                </div>
              </div>
            )}
            {!granted && isWin && reveal.next_phase && (
              <div style={{ marginTop:14, padding:"10px 12px", borderRadius:10,
                            background:"rgba(var(--warn-rgb),.12)", border:"1px solid rgba(var(--warn-rgb),.35)" }}>
                <div style={{ fontSize:11, color:"var(--warn)", fontWeight:600,
                              fontFamily:"'Cinzel',serif", letterSpacing:.4 }}>
                  {t("trib_continue_chat_title")}
                </div>
                <div style={{ fontSize:11, color:"var(--text)", marginTop:6, lineHeight:1.5 }}>
                  {t("trib_continue_chat_body", { phase: phaseToTKey(reveal.next_phase) ? t(phaseToTKey(reveal.next_phase)) : reveal.next_phase })}
                </div>
              </div>
            )}
            {!isWin && reveal.triggered_talisman === "revive" && (
              <div style={{ marginTop:14, fontSize:12, color:"var(--jade)", fontStyle:"italic" }}>
                {t("trib_talisman_revive")}
              </div>
            )}
            {!isWin && reveal.triggered_talisman === "insurance" && (
              <div style={{ marginTop:14, fontSize:12, color:"var(--gold2)", fontStyle:"italic" }}>
                {t("trib_talisman_insurance")}
              </div>
            )}
          </div>
        );
      }

      // ── v15.1.3.h2 Heart Demon renderers ──────────────────────────────────
      function renderHdIntro() {
        if (!hdState) {
          return (
            <div style={{ padding:"22px 0", textAlign:"center", color:"var(--muted)", fontSize:12 }}>
              <DotSpinner /><div style={{ marginTop:8 }}>{t("trib_loading")}</div>
            </div>
          );
        }
        const elemLabel = hdState.dominant_element
          ? safeT(`dao_element_${hdState.dominant_element.toLowerCase()}`, null, hdState.dominant_element)
          : null;
        return (
          <div>
            <div style={{
              padding:"12px 14px", marginBottom:12, borderRadius:10,
              background:"rgba(120,180,255,.10)",
              border:"1px solid rgba(120,180,255,.45)",
              textAlign:"center",
            }}>
              <div style={{ fontSize:36, marginBottom:6 }}>👁️</div>
              <div style={{ fontFamily:"'Cinzel',serif", fontSize:14, color:"var(--gold2)", letterSpacing:.6 }}>
                {t("trib_phase_heart_demon")}
              </div>
            </div>
            <div style={{
              fontSize:12, color:"var(--text)", lineHeight:1.65,
              marginBottom:12, padding:"4px 2px",
            }}>
              <MD text={t("trib_heart_demon_tutorial")} />
            </div>
            <div style={{
              padding:"10px 12px", borderRadius:8,
              background:"rgba(0,0,0,.35)",
              border:"1px solid rgba(var(--gold2-rgb),.35)",
              fontSize:12, color:"var(--text)", lineHeight:1.55,
            }}>
              <MD text={
                elemLabel
                  ? t("trib_hd_your_dao", { element: elemLabel })
                  : t("trib_hd_no_dao")
              } />
            </div>
          </div>
        );
      }

      function renderHdQuestion() {
        if (!hdState) {
          return (
            <div style={{ padding:"22px 0", textAlign:"center", color:"var(--muted)", fontSize:12 }}>
              <DotSpinner /><div style={{ marginTop:8 }}>{t("trib_loading")}</div>
            </div>
          );
        }
        const elemLabel = hdState.dominant_element
          ? safeT(`dao_element_${hdState.dominant_element.toLowerCase()}`, null, hdState.dominant_element)
          : null;
        return (
          <div>
            <div style={{ textAlign:"center", marginBottom:10 }}>
              <div style={{ fontSize:10.5, color:"var(--muted)", letterSpacing:1.2,
                            textTransform:"uppercase", fontFamily:"'Cinzel',serif" }}>
                {t("trib_heart_demon_round_label", { q: hdState.q_idx + 1, total: hdState.total_questions })}
              </div>
              <div style={{ marginTop:6, padding:"10px 12px", borderRadius:10,
                            background:"rgba(0,0,0,.45)",
                            border:"1px solid rgba(120,180,255,.35)",
                            fontSize:13, color:"var(--text)", lineHeight:1.6, fontStyle:"italic" }}>
                {t(hdState.question_key)}
              </div>
              {hdState.perception_hint && elemLabel && (
                <div style={{ marginTop:6, fontSize:11, color:"var(--gold3)", fontStyle:"italic" }}>
                  ✨ {elemLabel}
                </div>
              )}
            </div>
            <div style={{ display:"grid", gap:7 }}>
              {hdState.option_keys.map((ok, i) => (
                <button key={i}
                        disabled={phaseBusy}
                        onClick={() => answerHd(i)}
                        style={{
                          textAlign:"left", padding:"10px 12px",
                          background:"linear-gradient(180deg,rgba(var(--surface-rgb),.7),rgba(var(--surface3-rgb),.85))",
                          border:"1px solid rgba(var(--glow-rgb),.35)",
                          borderRadius:10, color:"var(--text)",
                          cursor: phaseBusy ? "default" : "pointer",
                          opacity: phaseBusy ? 0.6 : 1,
                          fontFamily:"inherit", fontSize:12.5, lineHeight:1.4,
                        }}>
                  {t(ok)}
                </button>
              ))}
            </div>
            <div style={{ marginTop:10, fontSize:10.5, color:"var(--muted)", textAlign:"center" }}>
              {t("trib_heart_demon_score", { score: hdState.score, total: hdState.total_questions })}
            </div>
          </div>
        );
      }

      function renderHdReveal() {
        if (!hdLast) return null;
        // Per-answer feedback (q_idx < 3) — short flash with check/cross.
        if (!hdLast.phase_done) {
          return (
            <div style={{ textAlign:"center", padding:"18px 0" }}>
              <div style={{
                fontSize:48, marginBottom:8,
                filter:`drop-shadow(0 0 14px ${hdLast.is_correct ? "var(--jade)" : "var(--red2)"})`,
              }}>
                {hdLast.is_correct ? "✓" : "✗"}
              </div>
              <div style={{ fontFamily:"'Cinzel',serif", fontSize:14, fontWeight:700,
                            color: hdLast.is_correct ? "var(--jade)" : "var(--red2)", letterSpacing:.8 }}>
                {hdLast.is_correct ? t("trib_heart_demon_correct") : t("trib_heart_demon_wrong")}
              </div>
            </div>
          );
        }
        // Phase resolved (3rd answer given).
        const passed = hdLast.phase_passed;
        const granted = hdLast.granted;
        return (
          <div style={{ textAlign:"center", padding:"6px 0" }}>
            <div style={{
              fontSize:62, lineHeight:1, marginBottom:8,
              filter:`drop-shadow(0 0 22px ${passed ? "var(--jade)" : "var(--red2)"})`,
              animation: passed ? "bt-reveal 1s cubic-bezier(.2,.8,.2,1)" : "trib-shake-light .25s ease-in-out 3",
            }}>
              {granted ? granted.new_realm_emoji : (passed ? "👁️" : "💀")}
            </div>
            <div style={{
              fontFamily:"'Cinzel',serif", fontSize:16, fontWeight:700,
              color: passed ? "var(--jade)" : "var(--red2)", letterSpacing:1,
            }}>
              {passed
                ? t("trib_heart_demon_success", { score: hdLast.score })
                : t("trib_heart_demon_fail")}
            </div>
            {granted && (
              <div style={{ marginTop:14, padding:"10px 12px", borderRadius:10,
                            background:"rgba(var(--gold2-rgb),.1)", border:"1px solid rgba(var(--gold2-rgb),.4)" }}>
                <div style={{ fontSize:10, color:"var(--muted)", letterSpacing:1, textTransform:"uppercase",
                              fontFamily:"'Cinzel',serif" }}>
                  {t("trib_realm_up_title")}
                </div>
                <div style={{ marginTop:4, fontSize:14, color:"var(--gold3)", fontFamily:"'Cinzel',serif" }}>
                  {granted.new_realm_emoji} {granted.new_realm_name}
                </div>
              </div>
            )}
            {passed && !granted && hdLast.next_phase && (
              <div style={{ marginTop:14, fontSize:12, color:"var(--text)", lineHeight:1.5 }}>
                {t("trib_phase_next_hint", {
                  phase: phaseToTKey(hdLast.next_phase) ? t(phaseToTKey(hdLast.next_phase)) : hdLast.next_phase,
                })}
              </div>
            )}
            {!passed && hdLast.triggered_talisman === "revive" && (
              <div style={{ marginTop:14, fontSize:12, color:"var(--jade)", fontStyle:"italic" }}>
                {t("trib_talisman_revive")}
              </div>
            )}
            {!passed && hdLast.triggered_talisman === "insurance" && (
              <div style={{ marginTop:14, fontSize:12, color:"var(--gold2)", fontStyle:"italic" }}>
                {t("trib_talisman_insurance")}
              </div>
            )}
          </div>
        );
      }

      // ── v15.1.3.h2 Dao Trial renderers ────────────────────────────────────
      function renderDaoPreview() {
        if (!daoData) {
          return (
            <div style={{ padding:"22px 0", textAlign:"center", color:"var(--muted)", fontSize:12 }}>
              <DotSpinner /><div style={{ marginTop:8 }}>{t("trib_loading")}</div>
            </div>
          );
        }
        const penalties = daoData.penalties || [];
        return (
          <div>
            <div style={{
              padding:"12px 14px", marginBottom:12, borderRadius:10,
              background:"rgba(var(--gold2-rgb),.10)",
              border:"1px solid rgba(var(--gold2-rgb),.45)",
              textAlign:"center",
            }}>
              <div style={{ fontSize:36, marginBottom:6 }}>☯️</div>
              <div style={{ fontFamily:"'Cinzel',serif", fontSize:14, color:"var(--gold2)", letterSpacing:.6 }}>
                {t("trib_phase_dao")}
              </div>
            </div>
            <div style={{ fontSize:12, color:"var(--text)", lineHeight:1.6, marginBottom:10 }}>
              {t("trib_dao_intro")}
            </div>
            <Card style={{ padding:"10px 12px 8px", marginBottom:10 }}>
              <KVRow label={t("trib_strategy_resist")} value={`${daoData.chance}%`} />
              <KVRow label={t("trib_dao_fragments_label")}
                     value={t("trib_dao_fragments_value", {
                       have: daoData.total_fragments, required: daoData.required,
                     })} />
              {daoData.perfect_bonus && (
                <div style={{ fontSize:11, color:"var(--jade)", marginTop:4 }}>{t("trib_dao_perfect_bonus")}</div>
              )}
              {daoData.tribulation_bonus && (
                <div style={{ fontSize:11, color:"var(--gold2)", marginTop:4 }}>{t("trib_dao_laws_bonus")}</div>
              )}
              {penalties.includes("foundation") && (
                <div style={{ fontSize:11, color:"var(--red2)", marginTop:4 }}>{t("trib_dao_penalty_foundation")}</div>
              )}
              {penalties.includes("core") && (
                <div style={{ fontSize:11, color:"var(--red2)", marginTop:4 }}>{t("trib_dao_penalty_core")}</div>
              )}
              {!daoData.can_attempt && (
                <div style={{ fontSize:11, color:"var(--red2)", marginTop:6, fontStyle:"italic" }}>
                  {t("trib_dao_not_enough_fragments", {
                    have: daoData.total_fragments, required: daoData.required,
                  })}
                </div>
              )}
            </Card>
          </div>
        );
      }

      function renderDaoReveal() {
        if (!daoResult) return null;
        const passed = daoResult.passed;
        const granted = daoResult.granted;
        const penalties = daoResult.penalties || [];
        return (
          <div style={{ textAlign:"center", padding:"6px 0" }}>
            <div style={{
              fontSize:62, lineHeight:1, marginBottom:8,
              filter:`drop-shadow(0 0 22px ${passed ? "var(--gold2)" : "var(--red2)"})`,
              animation: passed ? "bt-reveal 1s cubic-bezier(.2,.8,.2,1)" : "trib-shake-light .25s ease-in-out 3",
            }}>
              {granted ? granted.new_realm_emoji : (passed ? "☯️" : "💔")}
            </div>
            <div style={{
              fontFamily:"'Cinzel',serif", fontSize:16, fontWeight:700,
              color: passed ? "var(--gold2)" : "var(--red2)", letterSpacing:1,
            }}>
              {passed ? t("trib_dao_success") : t("trib_dao_fail")}
            </div>
            {granted && (
              <div style={{ marginTop:14, padding:"10px 12px", borderRadius:10,
                            background:"rgba(var(--gold2-rgb),.1)", border:"1px solid rgba(var(--gold2-rgb),.4)" }}>
                <div style={{ fontSize:10, color:"var(--muted)", letterSpacing:1, textTransform:"uppercase",
                              fontFamily:"'Cinzel',serif" }}>
                  {t("trib_realm_up_title")}
                </div>
                <div style={{ marginTop:4, fontSize:14, color:"var(--gold3)", fontFamily:"'Cinzel',serif" }}>
                  {granted.new_realm_emoji} {granted.new_realm_name}
                </div>
              </div>
            )}
            {!passed && penalties.includes("foundation") && (
              <div style={{ marginTop:10, fontSize:11, color:"var(--red2)" }}>{t("trib_dao_penalty_foundation")}</div>
            )}
            {!passed && penalties.includes("core") && (
              <div style={{ marginTop:10, fontSize:11, color:"var(--red2)" }}>{t("trib_dao_penalty_core")}</div>
            )}
            {!passed && daoResult.triggered_talisman === "revive" && (
              <div style={{ marginTop:14, fontSize:12, color:"var(--jade)", fontStyle:"italic" }}>
                {t("trib_talisman_revive")}
              </div>
            )}
            {!passed && daoResult.triggered_talisman === "insurance" && (
              <div style={{ marginTop:14, fontSize:12, color:"var(--gold2)", fontStyle:"italic" }}>
                {t("trib_talisman_insurance")}
              </div>
            )}
          </div>
        );
      }

      function renderHistory() {
        if (!historyData) {
          return (
            <div style={{ padding:"22px 0", textAlign:"center", color:"var(--muted)", fontSize:12 }}>
              <DotSpinner /><div style={{ marginTop:8 }}>{t("trib_loading")}</div>
            </div>
          );
        }
        if ((historyData.items || []).length === 0) {
          return (
            <div style={{ textAlign:"center", padding:"24px 8px", color:"var(--muted)" }}>
              <div style={{ fontSize:36, marginBottom:8, opacity:.6 }}>📜</div>
              <div style={{ fontSize:12 }}>{t("trib_history_empty")}</div>
            </div>
          );
        }
        const outcomeKey = (o) => o ? `trib_history_outcome_${o}` : "trib_history_outcome_unknown";
        return (
          <div style={{ display:"flex", flexDirection:"column", gap:7 }}>
            {historyData.items.map((it, i) => {
              const isWin = it.status === "completed";
              return (
                <div key={i} style={{
                  padding:"9px 12px", borderRadius:9,
                  background: isWin ? "rgba(var(--jade-rgb),.06)" : "rgba(var(--red-rgb),.06)",
                  border: `1px solid ${isWin ? "rgba(var(--jade-rgb),.28)" : "rgba(var(--red-rgb),.28)"}`,
                }}>
                  <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center" }}>
                    <span style={{ fontFamily:"'Cinzel',serif", fontSize:12, color:"var(--gold2)" }}>
                      {it.target_realm_emoji} {it.target_realm_name}
                    </span>
                    <span style={{ fontSize:10.5, color: isWin ? "var(--jade)" : "var(--red2)",
                                   fontFamily:"'Cinzel',serif" }}>
                      {t(outcomeKey(it.outcome))}
                    </span>
                  </div>
                  <div style={{ fontSize:10.5, color:"var(--muted)", marginTop:4 }}>
                    {it.completed_at_ms ? timeAgo(it.completed_at_ms) : ""} · {t("trib_history_rounds", { survived: it.rounds_survived, total: it.rounds_total })}
                    {it.phases_completed.length > 0 && ` · ${t("trib_history_phases", { phases: it.phases_completed.map(p => phaseToTKey(p) ? t(phaseToTKey(p)) : p).join(", ") })}`}
                  </div>
                </div>
              );
            })}
          </div>
        );
      }

      // ── Footer ────────────────────────────────────────────────────────────
      let footer = null;
      if (view === "preview" && trib && trib.next_phase === "thunder") {
        footer = (
          <div style={{ display:"flex", gap:8 }}>
            <ActionBtn variant="ghost" onClick={loadHistory} style={{ flex:1 }}>
              {t("trib_history_btn")}
            </ActionBtn>
            <ActionBtn variant="primary"
                       onClick={() => { setStrategy(null); setView("strategy"); }}
                       style={{ flex:1.4 }}>
              ⚡ {t("trib_attempt_btn")}
            </ActionBtn>
          </div>
        );
      } else if (view === "preview" && trib && trib.next_phase === "heart_demon") {
        footer = (
          <div style={{ display:"flex", gap:8 }}>
            <ActionBtn variant="ghost" onClick={loadHistory} style={{ flex:1 }}>
              {t("trib_history_btn")}
            </ActionBtn>
            <ActionBtn variant="primary" onClick={openHeartDemon} style={{ flex:1.4 }}>
              👁️ {t("trib_heart_demon_begin_btn")}
            </ActionBtn>
          </div>
        );
      } else if (view === "preview" && trib && trib.next_phase === "dao") {
        footer = (
          <div style={{ display:"flex", gap:8 }}>
            <ActionBtn variant="ghost" onClick={loadHistory} style={{ flex:1 }}>
              {t("trib_history_btn")}
            </ActionBtn>
            <ActionBtn variant="primary" onClick={openDao} style={{ flex:1.4 }}>
              ☯️ {t("trib_dao_begin_btn")}
            </ActionBtn>
          </div>
        );
      } else if (view === "preview") {
        footer = (
          <div style={{ display:"flex", gap:8 }}>
            <ActionBtn variant="ghost" onClick={loadHistory} style={{ flex:1 }}>
              {t("trib_history_btn")}
            </ActionBtn>
            <ActionBtn variant="ghost" onClick={onClose} style={{ flex:1 }}>
              {t("btn_close")}
            </ActionBtn>
          </div>
        );
      } else if (view === "strategy") {
        footer = (
          <div style={{ display:"flex", gap:8 }}>
            <ActionBtn variant="ghost" onClick={() => setView("preview")} style={{ flex:1 }}>
              {t("breakthrough_cancel")}
            </ActionBtn>
            <ActionBtn variant="primary" onClick={startThunder}
                       disabled={!strategy} style={{ flex:1.4 }}>
              {t("trib_attempt_btn")}
            </ActionBtn>
          </div>
        );
      } else if (view === "running") {
        footer = null;
      } else if (view === "reveal") {
        footer = (
          <ActionBtn variant="primary" onClick={() => {
            setReveal(null);
            setStrategy(null);
            setReloadKey(x => x + 1);
            setView("preview");
          }} style={{ width:"100%" }}>
            {t("btn_close")}
          </ActionBtn>
        );
      } else if (view === "history") {
        footer = (
          <ActionBtn variant="ghost" onClick={() => { setHistoryData(null); setView("preview"); }} style={{ width:"100%" }}>
            {t("breakthrough_cancel")}
          </ActionBtn>
        );
      } else if (view === "hd_intro") {
        footer = (
          <div style={{ display:"flex", gap:8 }}>
            <ActionBtn variant="ghost" onClick={() => setView("preview")} style={{ flex:1 }}>
              {t("breakthrough_cancel")}
            </ActionBtn>
            <ActionBtn variant="primary" onClick={beginHeartDemon} style={{ flex:1.4 }}>
              ⚡ {t("trib_heart_demon_begin_btn")}
            </ActionBtn>
          </div>
        );
      } else if (view === "hd_question") {
        // Answer buttons are inline; only ghost cancel here.
        footer = null;
      } else if (view === "hd_reveal") {
        // Mid-phase reveal (between questions) auto-advances; phase-resolved
        // reveal needs an explicit close.
        if (hdLast && hdLast.phase_done) {
          footer = (
            <ActionBtn variant="primary"
                       onClick={() => {
                         setHdLast(null);
                         setHdState(null);
                         setReloadKey(x => x + 1);
                         setView("preview");
                       }}
                       style={{ width:"100%" }}>
              {t("btn_close")}
            </ActionBtn>
          );
        } else {
          footer = null;
        }
      } else if (view === "dao_preview") {
        footer = (
          <div style={{ display:"flex", gap:8 }}>
            <ActionBtn variant="ghost" onClick={() => setView("preview")} style={{ flex:1 }}>
              {t("trib_dao_retreat")}
            </ActionBtn>
            <ActionBtn variant="primary"
                       onClick={attackDao}
                       disabled={phaseBusy || !daoData?.can_attempt}
                       style={{ flex:1.4 }}>
              {phaseBusy ? <DotSpinner /> : `☯️ ${t("trib_dao_attempt")}`}
            </ActionBtn>
          </div>
        );
      } else if (view === "dao_reveal") {
        footer = (
          <ActionBtn variant="primary"
                     onClick={() => {
                       setDaoResult(null);
                       setDaoData(null);
                       setReloadKey(x => x + 1);
                       setView("preview");
                     }}
                     style={{ width:"100%" }}>
            {t("btn_close")}
          </ActionBtn>
        );
      }

      const titlePrefix = view.startsWith("hd_") ? "👁️"
                        : view.startsWith("dao_") ? "☯️"
                        : "⚡";
      let titleText = t("trib_modal_title");
      if (view === "history") titleText = t("trib_history_title");
      else if (view === "running") titleText = t("trib_attempt_running");
      else if (view === "reveal") titleText = t("trib_modal_title");
      else if (view === "hd_intro" || view === "hd_question" || view === "hd_reveal") titleText = t("trib_phase_heart_demon");
      else if (view === "dao_preview" || view === "dao_reveal") titleText = t("trib_phase_dao");

      return (
        <Modal
          onClose={onClose}
          allowBackdropClose={view === "preview" || view === "history"}
          title={`${titlePrefix} ${titleText}`}
          accent="rgba(120,180,255,.55)"
          maxWidth={400}
          zIndex={70}
          footer={footer}
        >
          {view === "preview"     && renderPreview()}
          {view === "strategy"    && renderStrategy()}
          {view === "running"     && renderRunning()}
          {view === "reveal"      && renderReveal()}
          {view === "history"     && renderHistory()}
          {view === "hd_intro"    && renderHdIntro()}
          {view === "hd_question" && renderHdQuestion()}
          {view === "hd_reveal"   && renderHdReveal()}
          {view === "dao_preview" && renderDaoPreview()}
          {view === "dao_reveal"  && renderDaoReveal()}
          {errMsg && (view === "hd_intro" || view === "hd_question" || view === "dao_preview")
            && <ErrBanner msg={errMsg} />}
        </Modal>
      );
    }

    // ─── Achievements Modal (Sprint v14.8 MA-36) ─────────────────────────────
    // Drill-in modal opened from the Home "🏆 Conquistas" card. Lists the full
    // catalog with progress + unlock state + filter (all/unlocked/locked).
    // Equips/removes a title via /api/miniapp/achievements/equip_title — the
    // engine "claim" concept doesn't exist (bonuses apply automatically when
    // unlocked), so the only manual action is title equipping.
    function AchievementsModal({ onClose, onPlayerRefresh }) {
      const [reload, setReload] = useState(0);
      const [filter, setFilter] = useState("all"); // all|unlocked|in_progress|locked
      const { data, loading, error } = useApi("achievements/list", null, [reload]);

      async function equip(title) {
        try {
          const res = await api("achievements/equip_title", { title });
          if (!res.ok) {
            haptic("error");
            showToast(t("ach_equip_failed"), "err");
            return;
          }
          haptic("success");
          showToast(title ? t("ach_equip_success", { title }) : t("ach_equip_removed"));
          setReload(x => x + 1);
          if (onPlayerRefresh) onPlayerRefresh();
        } catch (e) {
          haptic("error");
          showToast(e.message, "err");
        }
      }

      const items = (data?.items || []).filter(it => {
        if (filter === "unlocked")    return it.is_unlocked;
        if (filter === "locked")      return !it.is_unlocked && it.progress === 0;
        if (filter === "in_progress") return !it.is_unlocked && it.progress > 0;
        return true;
      });

      const opts = [
        { value:"all",         label: t("ach_filter_all") },
        { value:"unlocked",    label: t("ach_filter_unlocked") },
        { value:"in_progress", label: t("ach_filter_in_progress") },
        { value:"locked",      label: t("ach_filter_locked") },
      ];

      return (
        <Modal onClose={onClose} title={`🏆 ${t("ach_modal_title")}`}
               accent="rgba(var(--gold2-rgb),.55)" maxWidth={420} zIndex={70}>
          {loading && !data && <ListSkeleton rows={4} />}
          {error && <ErrBanner msg={error} />}
          {data && (
            <>
              <div style={{
                padding:"9px 12px", marginBottom:10,
                background:"rgba(0,0,0,.3)", border:"1px dashed rgba(var(--gold2-rgb),.32)",
                borderRadius:9, textAlign:"center",
              }}>
                <div style={{ fontFamily:"'Cinzel',serif", fontSize:11, color:"var(--gold2)",
                              letterSpacing:.5, textTransform:"uppercase" }}>
                  {t("ach_summary", { unlocked: data.unlocked_count, total: data.count })}
                </div>
                <div style={{ marginTop:4, fontSize:11, color:"var(--text)" }}>
                  {t("ach_active_title_label")}: <b style={{ color:"var(--gold3)" }}>
                    {data.active_title ? `[${data.active_title}]` : t("ach_active_title_none")}
                  </b>
                </div>
                {data.active_title && (
                  <button onClick={() => equip(null)} style={{
                    marginTop:6, padding:"4px 10px", borderRadius:6, cursor:"pointer",
                    background:"rgba(var(--red-rgb),.15)", border:"1px solid rgba(var(--red-rgb),.4)",
                    color:"var(--red2)", fontSize:10.5, fontFamily:"'Cinzel',serif",
                  }}>{t("ach_unequip_btn")}</button>
                )}
              </div>

              {/* TAPETE QoL §5 item 10 ([jogador]: "esses 3 titulos não aparecem
                  lá e não mostram o que fazem") — Honors: the JSONB extra
                  titles (monetization/BP/prestige) listed + described +
                  equipable, finally visible in the mini-app. */}
              {(data.extra_titles || []).length > 0 && (
                <Card style={{ marginBottom:10, borderColor:"rgba(var(--gold2-rgb),.3)" }}>
                  <CardTitle left={`🎖️ ${t("ach_honors_section")}`} />
                  {/* QoL 04/08 (report [jogador]) — a resposta honesta a "titles are
                      not indicating their benefits": o benefício é PRESTÍGIO. É
                      decisão de design (Lei §4: jade nunca compra poder, e há
                      títulos que vêm de marcos VIP/Passe) — faltava a tela dizê-lo. */}
                  <div style={{ fontSize:10.5, color:"var(--muted)", fontStyle:"italic",
                                lineHeight:1.45, marginBottom:8 }}>
                    {t("ach_title_honorary_note")}
                  </div>
                  <div style={{ display:"flex", flexDirection:"column", gap:8 }}>
                    {data.extra_titles.map(et => (
                      <div key={et.name} style={{
                        padding:"7px 10px", borderRadius:8,
                        background:"rgba(0,0,0,.25)", border:"1px solid rgba(var(--gold2-rgb),.18)",
                      }}>
                        <div style={{ display:"flex", justifyContent:"space-between", alignItems:"baseline", gap:6 }}>
                          <span style={{ fontFamily:"'Cinzel',serif", fontSize:12, fontWeight:700,
                                         color:"var(--gold3)", minWidth:0,
                                         overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap" }}>
                            [{et.name}]
                          </span>
                          {et.equipped ? (
                            <span style={{ flexShrink:0, padding:"1px 6px", borderRadius:4,
                                           background:"rgba(var(--jade-rgb),.15)", color:"var(--jade)",
                                           fontSize:9, fontFamily:"'Cinzel',serif", letterSpacing:.5 }}>
                              {t("ach_equipped_chip")}
                            </span>
                          ) : (
                            <button onClick={() => equip(et.name)} style={{
                              flexShrink:0, padding:"3px 9px", borderRadius:6, cursor:"pointer",
                              background:"linear-gradient(180deg,rgba(var(--gold2-rgb),.18),rgba(155,110,40,.28))",
                              border:"1px solid rgba(var(--gold2-rgb),.5)",
                              color:"var(--gold3)", fontSize:10, fontFamily:"'Cinzel',serif",
                            }}>{t("ach_equip_btn")}</button>
                          )}
                        </div>
                        {et.description && (
                          <div style={{ fontSize:10.5, color:"var(--muted)", marginTop:3, lineHeight:1.45 }}>
                            {et.description}
                          </div>
                        )}
                      </div>
                    ))}
                  </div>
                </Card>
              )}

              <SegControl options={opts} value={filter} onChange={setFilter} />

              {items.length === 0 ? (
                <div style={{ textAlign:"center", padding:"24px 8px", color:"var(--muted)", fontSize:12 }}>
                  {t("ach_empty")}
                </div>
              ) : (
                <div style={{ display:"flex", flexDirection:"column", gap:8 }}>
                  {items.map(it => {
                    const status = it.is_unlocked ? "unlocked" : (it.progress > 0 ? "in_progress" : "locked");
                    const statusColor = status === "unlocked" ? "var(--jade)"
                                      : status === "in_progress" ? "var(--gold2)"
                                      : "var(--muted)";
                    const canEquipTitle = it.is_unlocked && it.title_granted;
                    return (
                      <div key={it.id} style={{
                        padding:"9px 11px", borderRadius:9,
                        background: it.is_unlocked
                          ? "linear-gradient(180deg,rgba(var(--jade-rgb),.08),rgba(20,30,30,.6))"
                          : "linear-gradient(180deg,rgba(var(--surface-rgb),.7),rgba(var(--surface3-rgb),.85))",
                        border: `1px solid ${it.is_unlocked ? "rgba(var(--jade-rgb),.32)" : "rgba(var(--glow-rgb),.28)"}`,
                      }}>
                        <div style={{ display:"flex", alignItems:"flex-start", gap:9 }}>
                          <div style={{ fontSize:24, lineHeight:1.1, flexShrink:0,
                                        filter: it.is_unlocked ? "drop-shadow(0 0 6px rgba(var(--gold2-rgb),.45))" : "grayscale(.6) opacity(.6)" }}>
                            {it.emoji}
                          </div>
                          <div style={{ flex:1, minWidth:0 }}>
                            <div style={{ display:"flex", justifyContent:"space-between", alignItems:"baseline", gap:6 }}>
                              <span style={{ fontFamily:"'Cinzel',serif", fontSize:12.5, fontWeight:700,
                                             color: it.is_unlocked ? "var(--gold2)" : "var(--text)",
                                             whiteSpace:"nowrap", overflow:"hidden", textOverflow:"ellipsis" }}>
                                {it.name}
                              </span>
                              <span style={{ fontSize:10, color: statusColor, fontFamily:"'Cinzel',serif",
                                             flexShrink:0, letterSpacing:.3 }}>
                                {status === "unlocked"    && t("ach_status_unlocked")}
                                {status === "in_progress" && t("ach_status_in_progress")}
                                {status === "locked"      && t("ach_status_locked")}
                              </span>
                            </div>
                            <div style={{ fontSize:10.5, color:"var(--muted)", marginTop:3, lineHeight:1.45 }}>
                              {it.description}
                            </div>
                            {!it.is_unlocked && it.target_value > 0 && (
                              <div style={{ marginTop:5 }}>
                                <ProgressBar pct={it.pct} variant="cult" height={5} />
                                <div style={{ fontSize:10, color:"var(--muted)", textAlign:"right", marginTop:2 }}>
                                  {t("ach_progress_label", { cur: it.progress, tgt: it.target_value })}
                                </div>
                              </div>
                            )}
                            {/* QoL 04/08 (report [jogador]) — o título é HONORÍFICO e o
                                bônus é da CONQUISTA. As duas coisas viviam na mesma div e
                                ensinavam "vestir o título dá o bônus"; agora o título traz
                                a marca do que é, e o número só aparece se este mundo o
                                aplicar de facto (bonus_view, server-resolved). */}
                            {it.title_granted && (
                              <div style={{ marginTop:5, fontSize:10.5, color:"var(--gold3)" }}>
                                {t("ach_title_granted", { title: it.title_granted })}
                                <span style={{ marginLeft:5, fontSize:9.5, color:"var(--muted)", fontStyle:"italic" }}>
                                  {t("ach_title_honorary_tag")}
                                </span>
                                {it.title_equipped && (
                                  <span style={{ marginLeft:6, padding:"1px 6px", borderRadius:4,
                                                 background:"rgba(var(--jade-rgb),.15)", color:"var(--jade)",
                                                 fontSize:9, fontFamily:"'Cinzel',serif", letterSpacing:.5 }}>
                                    {t("ach_equipped_chip")}
                                  </span>
                                )}
                              </div>
                            )}
                            {(it.bonus_view || []).length > 0 && (
                              <div style={{ marginTop:4, fontSize:10, color:"var(--muted)" }}>
                                {t("ach_stat_bonus_label")} {it.bonus_view.map(b =>
                                  `+${Number(b.pct).toFixed(0)}% ${t(b.label_key)}`).join(", ")}
                              </div>
                            )}
                            {canEquipTitle && !it.title_equipped && (
                              <button onClick={() => equip(it.title_granted)} style={{
                                marginTop:7, padding:"4px 10px", borderRadius:6, cursor:"pointer",
                                background:"linear-gradient(180deg,rgba(var(--gold2-rgb),.18),rgba(155,110,40,.28))",
                                border:"1px solid rgba(var(--gold2-rgb),.5)",
                                color:"var(--gold3)", fontSize:10.5, fontFamily:"'Cinzel',serif",
                                letterSpacing:.4,
                              }}>{t("ach_equip_btn")}</button>
                            )}
                          </div>
                        </div>
                      </div>
                    );
                  })}
                </div>
              )}
            </>
          )}
        </Modal>
      );
    }

    // ─── Notifications inbox (v14.7 Item 4) ──────────────────────────────────
    // Read-only modal listing pending player-state notifications. Each item
    // has a CTA "Ir" that drills into the relevant tab. Endpoint
    // /api/miniapp/notifications/inbox aggregates from existing engine
    // state — no persistent table.
    // v15.1.2 — Hybrid: live-state items + persistent (achievement_unlock,
    // duel_challenge, duel_result, title_unlock, gacha_legendary). Persistent
    // items have `notification_id` and can be dismissed individually or via
    // "Clear all" footer button. Engine: server-side UNION + 4 endpoints.
    function NotificationsModal({ onClose, onNavigate, refreshKey }) {
      const [tick, setTick] = useState(0);
      const { data, loading, error } = useApi("notifications/inbox", null, [refreshKey || 0, tick]);
      const [busy, setBusy] = useState(false);

      function resolveTitle(item) {
        if (item.title_key) {
          const v = t(item.title_key, item.params || {});
          if (v && v !== item.title_key) return v;
        }
        return item.title || item.title_key || "";
      }
      function resolveBody(item) {
        if (item.body_key) {
          const v = t(item.body_key, item.params || {});
          if (v && v !== item.body_key) return v;
        }
        return item.body || item.body_key || "";
      }
      function go(item) {
        haptic("select");
        // Auto-dismiss persistent items when the user follows the CTA — they
        // won't need to see it again after acting on it.
        if (item.persistent && item.notification_id) {
          api("notifications/dismiss", { notification_id: item.notification_id })
            .catch(() => { /* silent — next poll cleans up */ });
        }
        if (item.target_tab && onNavigate) onNavigate(item.target_tab);
        onClose && onClose();
      }
      async function dismissOne(item) {
        if (busy || !item.persistent || !item.notification_id) return;
        setBusy(true);
        haptic("warning");
        try {
          await api("notifications/dismiss", { notification_id: item.notification_id });
          setTick(x => x + 1);
        } catch (e) { /* silent */ }
        setBusy(false);
      }
      async function clearAll() {
        if (busy) return;
        setBusy(true);
        haptic("warning");
        try {
          await api("notifications/dismiss_all", {});
          setTick(x => x + 1);
        } catch (e) { /* silent */ }
        setBusy(false);
      }

      const items = (data && data.items) || [];
      const hasPersistent = items.some(it => it.persistent);
      const footer = hasPersistent ? (
        <div style={{ display:"flex", gap:8 }}>
          <ActionBtn onClick={clearAll} variant="ghost" style={{ flex:1 }} disabled={busy}>
            {busy ? <DotSpinner /> : `🧹 ${t("notif_inbox_clear_all")}`}
          </ActionBtn>
        </div>
      ) : null;

      return (
        <Modal onClose={onClose} title={`🔔 ${t("notif_inbox_title")}`}
               accent="rgba(var(--gold2-rgb),.45)" maxWidth={400} zIndex={70} footer={footer}>
          {loading && !data && <ListSkeleton rows={4} />}
          {error && <ErrBanner msg={error} />}
          {data && items.length === 0 && (
            <div style={{ textAlign:"center", padding:"32px 8px", color:"var(--muted)" }}>
              <div style={{ fontSize:36, marginBottom:8 }}>🌌</div>
              <div style={{ fontSize:12, color:"var(--muted)" }}>{t("notif_inbox_empty")}</div>
              <div style={{ fontSize:10.5, color:"var(--muted2)", marginTop:6, fontStyle:"italic" }}>
                {t("notif_inbox_empty_hint")}
              </div>
            </div>
          )}
          {data && items.map((item, i) => (
            <div key={`${item.type}-${item.notification_id || item.ref_id || i}`}
                 style={{
                   display:"flex", alignItems:"flex-start", gap:10,
                   padding:"10px 6px", borderBottom:"1px dashed rgba(var(--glow-rgb),.18)",
                   opacity: (item.persistent && item.seen) ? 0.7 : 1,
                 }}>
              <div style={{ fontSize:22, lineHeight:1.1, flexShrink:0,
                            filter:"drop-shadow(0 0 6px rgba(var(--gold2-rgb),.35))" }}>
                {item.icon}
              </div>
              <div style={{ flex:1, minWidth:0 }}>
                <div style={{ fontSize:12.5, fontWeight:600, color:"var(--gold2)",
                              fontFamily:"'Cinzel',serif", letterSpacing:.3 }}>
                  {resolveTitle(item)}
                </div>
                <div style={{ fontSize:11, color:"var(--muted)", marginTop:2, lineHeight:1.4 }}>
                  {resolveBody(item)}
                </div>
              </div>
              <div style={{ display:"flex", flexDirection:"column", gap:4, alignSelf:"center" }}>
                {item.target_tab && (
                  <ActionBtn variant="primary"
                             onClick={() => go(item)}
                             style={{ padding:"6px 10px", fontSize:10.5, flexShrink:0 }}>
                    ✦ {t("notif_inbox_go")}
                  </ActionBtn>
                )}
                {item.persistent && item.notification_id && (
                  <button onClick={() => dismissOne(item)} disabled={busy}
                          aria-label={t("notif_inbox_dismiss")}
                          style={{
                            background:"transparent", border:"1px solid rgba(160,160,160,.3)",
                            borderRadius:6, padding:"4px 8px", fontSize:10,
                            color:"var(--muted)", cursor: busy ? "not-allowed" : "pointer",
                          }}>
                    ✕
                  </button>
                )}
              </div>
            </div>
          ))}
        </Modal>
      );
    }

    // ═══ 至 P2 — QUAL E' O BOTAO DA CHEGADA ════════════════════════
    //
    // A chegada tem **UM** botao, escolhido por PRECEDENCIA DE ESTADO
    // CONFIRMADO (direccao do Astra, MESA [016] §1):
    //
    //   1. voltar ao duelo · 2. ver a meditacao · 3. resolver recompensa
    //   4. avancar de reino · 5. meditar
    //
    // 🔴 A REGRA QUE MANDA, e e' dele: **ausencia de um campo NAO e' estado
    // confirmado.** Um ramo que nao sabe **nao decide** — passa ao seguinte.
    // Por isso cada teste abaixo pergunta pela PRESENCA do facto e nunca pela
    // ausencia do contrario: `acao.duelo` a `undefined` quer dizer *"o servidor
    // nao me disse"*, e inventar "nao ha' duelo" a partir disso seria a tela a
    // afirmar o que ninguem mediu. `{duel_id:null}` **e'** uma resposta; `null`
    // e `undefined` nao sao.
    //
    // ⚠️ E a RECUPERACAO e' um MODIFICADOR, nao um ramo. Medido nos dois
    // lados: o gate e' `get_current_hp(player) <= 0`
    // (`exploration_engine.py:737`), e `current_hp` a **NULL significa CHEIO**
    // (`combat_engine.get_current_hp`, e o COALESCE que inventou "69% dos
    // activos sem poder lutar" ja' nos custou um lote). Ele tranca o que e'
    // LUTA; a meditacao nao. Por isso so' o ramo do duelo vira "Recuperar".
    //
    // ⚠️ E quando nenhum ramo confirma, devolve **null** — a chegada escreve
    // o motivo e NAO desenha botao. Um botao que promete executar o que o
    // servidor vai recusar e' pior do que nenhum (Lei §1).
    function vidaDe(p) {
      // NULL = cheio. Nunca zero.
      const max = Number((p && p.max_hp) || 0);
      const cur = (p && p.current_hp);
      return (cur === null || cur === undefined) ? max : Number(cur);
    }

    function acaoDaChegada(sumario, cult, p) {
      const acao = (sumario && sumario.acao) || {};
      const semVida = vidaDe(p) <= 0;

      // 1 — o duelo aberto. `duelo` ausente = nao sei; `duel_id` null = nao ha'.
      if (acao.duelo && acao.duelo.duel_id) {
        if (semVida) {
          return { chave:"recuperar", rotulo:t("chegada_acao_recuperar"),
                   porque:t("chegada_porque_recuperar"), destino:"cultivation" };
        }
        return { chave:"duelo", rotulo:t("chegada_acao_duelo"),
                 porque:t("chegada_porque_duelo"), destino:"combat" };
      }

      // 2 — a meditacao a decorrer (o `/cultivation`, que a chegada ja' pede).
      // 減 P7 — os dois ramos da meditacao levam `explica`: a frase deles
      // REPETE o que a cena ja' diz ("Meditando · termina em…" / "Sem
      // meditacao ativa") e recolhe depois de uma meditacao confirmada. Os
      // outros ramos NAO levam — cada um diz um facto que so' ali aparece (o
      // duelo aberto, o numero de missoes, o limiar, a vida a zero).
      if (cult && cult.is_meditating) {
        return { chave:"meditacao", rotulo:t("chegada_acao_meditacao"),
                 porque:t("chegada_porque_meditacao"), destino:"cultivation",
                 explica:"meditar" };
      }

      // 3 — recompensa por receber. `quests.ready` e' um numero medido.
      const prontas = sumario && sumario.quests && Number(sumario.quests.ready || 0);
      if (prontas > 0) {
        return { chave:"recompensa", rotulo:t("chegada_acao_recompensa"),
                 porque:t("chegada_porque_recompensa", { n: prontas }), destino:"quests" };
      }

      // 4 — o avanco de reino. `eligible` e' o espelho READ-ONLY do mesmo
      // gate que o `check_breakthrough` aplica — nao e' uma adivinha do cliente.
      if (acao.avanco && acao.avanco.eligible === true) {
        return { chave:"avanco", rotulo:t("chegada_acao_avanco"),
                 porque:t("chegada_porque_avanco"), destino:"cultivation" };
      }

      // 5 — meditar. So' quando o cliente SABE que nao esta' a meditar: um
      // `cult` ausente e' "nao sei", e ai nao se promete nada.
      if (cult && cult.is_meditating === false) {
        return { chave:"meditar", rotulo:t("chegada_acao_meditar"),
                 porque:t("chegada_porque_meditar"), destino:"cultivation",
                 explica:"meditar" };
      }

      return null;
    }

    // ═══ 至 A CHEGADA — O DONO UNICO ══════════════════════════════
    //
    // 🔴 Ela renderiza em DOIS sitios, e e' por isso que existe:
    //   · `home` — a porta da barra antiga (`ui_v2` OFF);
    //   · `hub_eu_screen` — o LANDING do hub Eu, que e' o que a `ui_v2` abre,
    //     e e' o que o owner corre. A [016] §1: *"a chegada vive no hub Eu"*.
    //
    // ⚠️ Escrever a mesma composicao nos dois era a Lei 0 §2 a repetir-se
    // DENTRO do lote que a cumpre — foi exactamente assim que a decisao moral
    // acabou com tres copias e uma delas ja' tinha perdido uma linha.
    //
    // ⚠️ Os dois relogios sao os do `HomeTab` de sempre: o sumario a 30s
    // (muda devagar) e o cultivo a 5s (o cronometro da meditacao tem de parecer
    // vivo). Juntar-los num so' obrigava a escolher entre gastar rede a' toa ou
    // um cronometro que salta de cinco em cinco.
    function Chegada({ player, setTab, notifCount, onSino, onLoja, onPerfil, wide,
                       portas, onPortas, onPlayerRefresh }) {
      const [tickSumario, setTickSumario] = useState(0);
      const [tickCultivo, setTickCultivo] = useState(0);
      const { data } = useApi("home_summary", null, [tickSumario]);
      const cult = useApi("cultivation", null, [tickCultivo]);
      useVisibleInterval(() => setTickSumario(x => x + 1), 30000);
      useVisibleInterval(() => setTickCultivo(x => x + 1), 5000);

      // A accao principal: UM botao, escolhido por precedencia de estado
      // CONFIRMADO. Se nenhum ramo confirmar, `acaoDaChegada` devolve `null` e
      // escreve-se o motivo SEM botao (Lei §1).
      const acao = acaoDaChegada(data, cult && cult.data, player);
      const agir = (
        <div>
          <div style={{ fontSize:14, lineHeight:1.45, color:"var(--muted)", marginBottom:10 }}>
            {acao && acao.explica ? (
              <Explica sistema={acao.explica} estados={player && player.explicacoes}
                       onRefresh={onPlayerRefresh}>
                {acao.porque}
              </Explica>
            ) : (acao ? acao.porque : t("chegada_sem_acao"))}
          </div>
          {acao && (
            <OndaBtn onClick={function () { haptic("select"); setTab(acao.destino); }}>
              {acao.rotulo}
            </OndaBtn>
          )}
        </div>
      );

      // 至 P3 — OS DOIS ATALHOS. O servidor manda `atalhos.tecnica` e
      // `atalhos.arma` no mesmo `home_summary` que a chegada ja' pede.
      // ⚠️ `art_key` e' o nome CANONICO e e' o que encontra a arte: o `name`
      // vem TRADUZIDO e o slug dele nao casa com nenhum ficheiro. Foi assim que
      // 229 pecas por lingua ficaram invisiveis a 2026-09-14.
      // ⚠️ E a arte pode faltar: `pieceArt` devolve `null` e a caixa fica com a
      // MESMA altura, com a marca e o nome legiveis. A accao nunca espera pelo
      // bitmap ([016] §4).
      const _at = (data && data.atalhos) || {};
      // ⚠️ TRES estados, nao dois. `undefined` = o servidor nao me disse (a
      // consulta falhou); `null` = ele confirmou que nao ha' nenhum. Escrever
      // "Nenhum equipado" no primeiro caso e' afirmar o que ninguem mediu — e
      // foi exactamente o que o owner apanhou a olhar.
      function _atalho(chave, rotulo, marca, tipo, item, destino, sabido) {
        const arte = item ? pieceArt(tipo, item.name, item.art_key) : null;
        return (
          <button key={chave} type="button"
                  onClick={function () { haptic("select"); setTab(destino); }}
                  style={{ display:"flex", alignItems:"center", gap:9, minHeight:62,
                           padding:8, textAlign:"left", cursor:"pointer", font:"inherit",
                           background:"rgba(236,229,216,.06)",
                           border:"1px solid rgba(236,229,216,.17)", borderRadius:6,
                           color:"var(--text)" }}>
            {/* ⚠️ A peca desenha-se pelo `CardArt` e por mais nada — e' a Lei
                F-7 (B) e ha' uma guarda que conta os renderizadores de imagem
                do cliente inteiro. Ela apanhou-me a escrever uma etiqueta de
                imagem CRUA
                aqui. O `CardArt` ja' traz o VERSO honesto (os aneis de tinta)
                quando a arte falta ou falha, o que e' exactamente o que a
                [016] §4 pede: mesma caixa, nada quebrado, accao a funcionar. */}
            <span style={{ width:46, height:46, flexShrink:0, borderRadius:3,
                           overflow:"hidden", display:"block" }}>
              <CardArt src={arte} glyph={item ? (item.emoji || undefined) : undefined}
                       aspect="1 / 1" glyphSize={20} />
            </span>
            <span style={{ minWidth:0 }}>
              <span style={{ display:"block", fontFamily:"'Cinzel',serif", fontSize:8.5,
                             letterSpacing:1.2, textTransform:"uppercase",
                             color:"var(--muted)", marginBottom:2 }}>{rotulo}</span>
              <span style={{ display:"block", fontSize:12, lineHeight:1.25,
                             color: item ? "var(--text)" : "var(--muted)" }}>
                {item ? item.name
                      : sabido ? t("chegada_atalho_vazio")
                               : t("chegada_atalho_incerto")}
              </span>
            </span>
          </button>
        );
      }
      const atalhos = (<>
        {/* ⚠️ "technique"/"artifact" e nao "tech"/"art": o prefixo do URL sai do
            `ART_KIND_PREFIX`, cujas CHAVES sao as longas. Com a chave errada o
            `pieceArt` devolve `null` em silencio e a arte nunca aparece —
            exactamente o modo de falha que a carta virada ao verso esconde. */}
        {_atalho("tecnica", t("chegada_atalho_tecnica"), "sword", "technique",
                 _at.tecnica, "combat", Object.prototype.hasOwnProperty.call(_at, "tecnica"))}
        {_atalho("arma", t("chegada_atalho_arma"), "stone", "artifact",
                 _at.arma, "inventory", Object.prototype.hasOwnProperty.call(_at, "arma"))}
      </>);

      return (
        <ChegadaCena p={player} cult={cult} onAgir={agir} atalhos={atalhos} wide={wide}
                     portas={portas} onPortas={onPortas}
                     notifCount={notifCount} onSino={onSino}
                     onLoja={onLoja} onPerfil={onPerfil} />
      );
    }

    function HomeTab({ player, setTab, onPlayerRefresh, onOpenChronicle,
                      notifCount, onSino, onLoja, onPerfil, onAbrirSeletor }) {
      // WEB-D §1 — MEDIDO a olhar para o jogo servido a sério (2026-09-01):
      // a grelha abaixo é `1fr 1fr` e o HomeCard é `aspectRatio:"1/1"`. Num
      // telemóvel isso dá cartões de 177x177 (bonito, foi para isso que foi
      // desenhado); na coluna de 1080px do desktop dá cartões de **514x514**,
      // com um medalhão de 44px no topo, o título no fundo e 440px de vazio
      // pelo meio — e a Home inteira passou a ter 5436px de altura, ou seja,
      // o ecrã LARGO ficou com MAIS scroll do que o telemóvel para o mesmo
      // conteúdo. Um ecrã largo serve para mostrar mais de uma vez, nunca
      // para inchar o que já cabia.
      // A correcção é a grelha, não o cartão: `auto-fill` põe mais cartões por
      // linha e devolve-lhes o tamanho de telemóvel (~180px), que é a medida
      // em que o desenho do medalhão foi pensado. No telemóvel a expressão é
      // literalmente a de sempre → DOM byte-idêntico para os 248.
      const wideShell = typeof useWideShell === "function" ? useWideShell() : false;
      // 至 O PORTAO DA CHEGADA. Um so' sitio: a cena entra e o agregado sai
      // pela MESMA condicao, porque sao a mesma decisao. Duas condicoes
      // separadas deixariam nascer o estado em que nenhum dos dois aparece.
      // ⚠️ A chave-mestra le-se pelo DONO UNICO (`ondaCultOn`, ui.js:4385),
      // nunca com um `featureEnabled("a_obra")` novo: a guarda do §19 conta as
      // leituras por ficheiro exactamente para impedir que ela volte a ter
      // dois donos — e apanhou-me a acrescentar o segundo.
      const chegadaOn = obraOn() && typeof ChegadaCena === "function";
      const [reload, setReload] = useState(0);
      const [cultTick, setCultTick] = useState(0);
      // v14.8 MA-36 — drill-in to achievements modal directly from Home card
      // (no full tab — modal feels lighter for a "trophy room" surface).
      const [achOpen, setAchOpen] = useState(false);
      const ach = useApi("achievements/list", null, [reload, achOpen]);
      const { data, loading, error } = useApi("home_summary", null, [reload]);
      // MA-32b round 3 (owner request): "Home deveria ser onde fica o
      // cultivacion e os atalhos embaixo dele". Fetch the cultivation
      // status directly so the Home shows live CB/Qi/meditation state
      // without forcing a tab switch.
      const cult = useApi("cultivation", null, [cultTick]);
      // Refresh every 30s while visible — same cadence as /player.
      useVisibleInterval(() => setReload(x => x + 1), 30000);
      // Cultivation refresh is faster (5s) so meditation timer + bars feel live.
      useVisibleInterval(() => setCultTick(x => x + 1), 5000);

      const stat = (key) => {
        if (loading && !data) return t("home_stat_loading");
        if (error || !data) return t("home_stat_unavailable");
        switch (key) {
          case "sect":
            return data.sect
              ? `${data.sect.name} · ${t("profile_role_" + data.sect.role)}`
              : t("home_stat_no_sect");
          case "world_boss":
            if (!data.boss) return t("home_stat_no_boss");
            if (data.boss.tier_mismatch) return t("home_stat_boss_mismatch");
            return t("home_stat_boss_hp", { pct: data.boss.hp_pct });
          case "dungeons":
            return t("home_stat_dungeon_explore");
          case "plaza":
            // Onda 4a — light hint (presence + bounty count surfaced inside PlazaTab).
            return t("home_stat_plaza_hint");
          case "shop":
            return t("home_stat_jade", { n: fmtNum(data.spirit_jade ?? 0) });
          case "quests":
            return t("home_stat_quests", { ready: data.quests.ready, total: data.quests.total });
          case "leaderboard":
            return data.your_rank
              ? t("home_stat_your_rank", { rank: data.your_rank })
              : t("home_stat_rank_shadow");
          case "announcements":
            return data.announcements.recent_count > 0
              ? t("home_stat_unread", { n: data.announcements.recent_count })
              : t("home_stat_no_news");
          case "combat":
            // v14.9 MA-35 — combat is now a real tab with arena ELO summary.
            // home_summary doesn't (yet) include arena fields, so we render a
            // generic prompt; arena rank shows up inside the CombatTab itself.
            return t("home_stat_combat_no_arena");
          case "market":
            // v14.12 MA-39 — light hint (full count surfaced inside MarketTab
            // header so home_summary doesn't need extra queries).
            return t("home_stat_market_hint");
          case "battle_pass":
            // v14.13d MA-40 — Light hint; BP details surfaced inside the tab.
            return t("home_stat_battle_pass_hint");
          case "achievements":
            if (ach.loading && !ach.data) return t("home_stat_achievements_loading");
            if (ach.error || !ach.data) return t("home_stat_achievements_loading");
            return t("home_stat_achievements", {
              unlocked: ach.data.unlocked_count || 0,
              total: ach.data.count || 0,
            });
          default:
            return "";
        }
      };

      const cd = cult.data || {};
      const cbPct = cd.cb_threshold > 0 ? Math.min(100, (cd.cultivation_base / cd.cb_threshold) * 100) : 0;
      const qiPct = cd.qi_capacity > 0 ? Math.min(100, (cd.qi / cd.qi_capacity) * 100) : 0;
      const meditating = !!cd.is_meditating;
      const remainMs = cd.meditation_end_ms ? Math.max(0, cd.meditation_end_ms - Date.now()) : 0;

      async function quickStartMeditation() {
        try {
          await api("meditate/start", { type: "light" });
          haptic("success");
          showToast(t("meditate_started"));
          setCultTick(x => x + 1);
          onPlayerRefresh && onPlayerRefresh();
        } catch (e) {
          haptic("error");
          showToast(t(e.message === "not_enough_qi" ? "meditate_low_qi" : "alch_err_engine"), "err");
        }
      }
      async function quickStopMeditation() {
        try {
          await api("meditate/stop");
          haptic("success");
          showToast(t("meditate_stopped"));
          setCultTick(x => x + 1);
          onPlayerRefresh && onPlayerRefresh();
        } catch (e) {
          haptic("error");
          showToast(t("alch_err_engine"), "err");
        }
      }

      return (
        <div>
          {/* 🔴 至 A CHEGADA — a cena substitui o cabeçalho e o widget de
              cultivo. Os dois diziam "quem sou" e "como estou" em dois
              cartões empilhados; a cena diz as duas coisas numa composição só,
              com a paisagem do reino por trás. Direcção do Astra, MESA [016] §1.
              ⚠️ Com a flag OFF os dois voltam, byte a byte. */}
          {chegadaOn && (
            <Chegada player={player} setTab={setTab} wide={wideShell}
                     notifCount={notifCount} onSino={onSino}
                     onLoja={onLoja} onPerfil={onPerfil}
                     /* 門 P6 — a MESMA maçaneta do `hub_eu_screen`, do mesmo
                        dono (`EU_PORTAS`): a app arranca AQUI, e este era o
                        sítio onde ela faltava. */
                     portas={onAbrirSeletor ? euPortasVisiveis(player, EU_PORTAS).nomes : undefined}
                     onPortas={onAbrirSeletor}
                     onPlayerRefresh={onPlayerRefresh} />
          )}

          {!chegadaOn && (<>
          {/* Welcome banner — refined: dao_name centred, realm under,
              meditate CTA below. Drops the side-by-side layout that made
              the dao_name compete visually with the button. */}
          <Card style={{ padding:"14px 14px 12px", marginBottom:14, position:"relative", overflow:"hidden", textAlign:"center" }}>
            <div style={{
              position:"absolute", inset:0, opacity:.07, pointerEvents:"none",
              background:`radial-gradient(circle at 50% 0%, var(--realm-${Math.min(player.realm || 0, 10)}), transparent 65%)`,
            }} />
            <div style={{ position:"relative" }}>
              <div style={{
                fontSize:9.5, color:"var(--muted)", letterSpacing:1.2,
                textTransform:"uppercase", fontFamily:"'Cinzel',serif",
              }}>{t("home_welcome_back")}</div>
              <div style={{
                fontFamily:"'Cinzel',serif", fontSize:20, fontWeight:700, letterSpacing:.8,
                background:"linear-gradient(90deg,var(--gold3),var(--gold2),var(--gold),var(--gold2),var(--gold3))",
                backgroundSize:"200% 100%",
                WebkitBackgroundClip:"text", backgroundClip:"text", WebkitTextFillColor:"transparent",
                animation:"shimmer 4s linear infinite",
                marginTop:4,
                whiteSpace:"nowrap", overflow:"hidden", textOverflow:"ellipsis",
              }}>{player.dao_name}</div>
              {/* Gold thread divider with center dot — ornate scroll feel */}
              <div style={{ display:"flex", alignItems:"center", gap:6, justifyContent:"center", margin:"6px auto 6px", maxWidth:200 }}>
                <div style={{ flex:1, height:1, background:"linear-gradient(90deg,transparent,rgba(var(--gold2-rgb),.55))" }} />
                <div style={{ width:3, height:3, borderRadius:"50%", background:"var(--gold2)", boxShadow:"0 0 4px rgba(var(--gold2-rgb),.7)" }} />
                <div style={{ flex:1, height:1, background:"linear-gradient(90deg,rgba(var(--gold2-rgb),.55),transparent)" }} />
              </div>
              <div style={{ fontSize:11, color:"var(--gold3)", fontFamily:"'Cinzel',serif", letterSpacing:.4 }}>
                {player.realm_name} · {t("profile_sub_layer", { n: player.sub_layer })}
              </div>
              <button onClick={() => { haptic("select"); setTab("cultivation"); }}
                      style={{
                        marginTop:11,
                        background:"linear-gradient(180deg,rgba(var(--gold2-rgb),.18),rgba(var(--gold-rgb),.28))",
                        border:"1px solid rgba(var(--gold2-rgb),.45)",
                        borderRadius:8, padding:"8px 18px", cursor:"pointer",
                        color:"var(--gold3)", fontFamily:"'Cinzel',serif",
                        fontSize:11, fontWeight:700, letterSpacing:1,
                        textTransform:"uppercase",
                        boxShadow:"0 0 14px rgba(var(--gold2-rgb),.18), inset 0 1px 0 rgba(var(--gold3-rgb),.25)",
                      }}>
                {t("home_open_cultivation")}
              </button>
            </div>
          </Card>

          {/* Compact cultivation widget — owner request 2026-05-06 round 3:
              "Home deveria ser onde fica o cultivacion". Live orb + CB/Qi
              bars + quick meditate toggle. Tap the card body to drill into
              the full Cultivation tab for breakthrough/technique controls. */}
          <HomeCultivationCard
            cd={cd}
            cbPct={cbPct}
            qiPct={qiPct}
            meditating={meditating}
            remainMs={remainMs}
            onOpen={() => { haptic("select"); setTab("cultivation"); }}
            onStart={quickStartMeditation}
            onStop={quickStopMeditation}
            loading={cult.loading && !cult.data}
          />
          </>)}

          {/* 8 drill-in cards — square aspect, altar/medallion style.
              Telemóvel: 2 colunas (como sempre). Desktop: quantas couberem a
              ~180px, que é o tamanho para que o medalhão foi desenhado. */}
          {/* 🔴 至 P4 — AS 21 PORTAS DEIXAM DE SER DESENHADAS.
              Ordem do owner, com a tela dele a' frente: *"muito grande essa
              tela (...) a pessoa nao tem que buscar"*. Medido no jogo servido
              a 390x844: a chegada tinha **2.397 px = 2,8 ecras de rolagem** e
              **21 portas com exactamente o mesmo peso**.
              Direccao do Astra (MESA [016] §1): *"o bloco agregador deixa de
              ser renderizado na chegada. **Nao vira carrossel, acordeao 'Tudo'
              ou 21 miniaturas.** Cada destino continua no hub ao qual ja'
              pertence."*
              ⚠️ Com a flag OFF fica byte-identico ao de hoje — a grelha
              inteira, incluindo o `gridTemplateColumns` do desktop. */}
          {!chegadaOn && (
          <div style={{ display:"grid",
                        gridTemplateColumns: wideShell
                          ? "repeat(auto-fill, minmax(168px, 1fr))"
                          : "1fr 1fr",
                        gap:9 }}>
            {HOME_CARDS.map(card => {
              // Achievements doesn't have a tab — opens as a drill-in modal.
              const onClickHandler = card.stub
                ? undefined
                : card.key === "achievements"
                  ? () => { haptic("select"); setAchOpen(true); }
                  : () => { haptic("select"); setTab(card.tab); };
              return (
                <HomeCard key={card.key}
                          icon={card.icon}
                          mark={card.mark}
                          title={t(card.title_key)}
                          stat={stat(card.key)}
                          accent={card.accent}
                          stub={card.stub}
                          onClick={onClickHandler} />
              );
            })}
          </div>
          )}

          {/* World Pulse Fase 1 — Os Registos Celestiais: the world breathes even
              without you. A read-only feed of the 9 sects acting on their own. */}
          {/* 至 *"Margem adaptável: respiro da paisagem. **Não preencher com
              novas portas, notícias ou promoções**"* — [016] §1. Medido: com a
              Crónica ca' em baixo a chegada voltava a rolar (940px num ecrã de
              844). Ela continua no hub Pergaminho, onde a [017] a poe. */}
          {!chegadaOn && onOpenChronicle && (
            <Card onClick={() => onOpenChronicle()} style={{
              marginTop:12, padding:"12px 14px", cursor:"pointer",
              display:"flex", alignItems:"center", gap:12,
              background:"linear-gradient(180deg, rgba(var(--gold2-rgb),.08), rgba(var(--card-rgb),.96))",
              border:"1px solid rgba(var(--gold2-rgb),.26)",
            }}>
              <div style={{ fontSize:26 }}>📜</div>
              <div style={{ flex:1, minWidth:0 }}>
                <div style={{ fontFamily:"'Cinzel',serif", fontSize:13, color:"var(--gold3)" }}>
                  {t("cronica_home_title")}
                </div>
                <div style={{ fontSize:10.5, color:"var(--muted)", marginTop:2 }}>
                  {t("cronica_home_sub")}
                </div>
              </div>
              <div style={{ fontSize:16, color:"var(--muted)" }}>›</div>
            </Card>
          )}

          {achOpen && (
            <AchievementsModal
              onClose={() => { setAchOpen(false); setReload(x => x + 1); }}
              onPlayerRefresh={onPlayerRefresh}
            />
          )}
        </div>
      );
    }

    function HomeCultivationCard({ cd, cbPct, qiPct, meditating, remainMs, onOpen, onStart, onStop, loading }) {
      const realm = cd?.realm ?? 0;
      // R5: hex literal — o mini-orbe concatena alpha no glow (`${cssHex(rc)}66`);
      // com var() a declaração inteira morria silenciosa desde sempre.
      const rc = realmHex(realm);
      return (
        <div style={{
          position:"relative", overflow:"hidden",
          background:"linear-gradient(170deg,rgba(var(--surface-rgb),.94) 0%,rgba(var(--surface2-rgb),.98) 100%)",
          border:"1px solid rgba(var(--gold2-rgb),.32)",
          borderRadius:12, padding:"12px 12px 11px", marginBottom:14,
          animation:"fade-up .35s ease",
        }}>
          {/* Top gold thread */}
          <div style={{
            position:"absolute", top:0, left:14, right:14, height:1,
            background:"linear-gradient(90deg,transparent,rgba(var(--gold2-rgb),.7),transparent)",
          }} />
          <div onClick={onOpen} style={{ display:"flex", alignItems:"center", gap:11, cursor:"pointer" }}>
            {/* Mini orb — static gradient (no animation, save battery on Home) */}
            <div style={{
              width:54, height:54, borderRadius:"50%", flexShrink:0,
              background:`radial-gradient(circle at 30% 30%, ${rc}, transparent 70%), radial-gradient(circle, rgba(0,0,0,.5), rgba(0,0,0,.85))`,
              border:`1.5px solid ${rc}`, boxShadow:`0 0 14px ${cssHex(rc)}66, inset 0 0 12px rgba(0,0,0,.6)`,
              display:"grid", placeItems:"center",
            }}>
              {/* 印 ⚠️ ACHADO A OLHAR (2026-09-08): o ✦ nao morreu a 07/09 — morreu
                   NUM sitio. Ele continuava aqui, no cartao do Cultivo da Home, que
                   e' a primeira tela depois do login e a que se abre mais vezes; e
                   e' o MESMO glifo que o owner leu como "muito AI" no centro do
                   orbe. A figura sentada e' a resposta certa (e ja' e' a marca da
                   propria aba), portanto o mini-orbe a meditar mostra QUEM esta'
                   sentado, e nao um sparkle. Fora da meditacao continua o emoji do
                   reino, que e' CONTEUDO do catalogo e nao se toca.
                   ⚠️ Medido no mesmo varrimento: o ✦ sobrevive noutros 26 sitios do
                   cliente (rotulos, marcadores de "equipado", vinhetas). Esses vao
                   num lote proprio — estao dentro de strings, nao em JSX. */}
              <span style={{ fontSize:24, filter:`drop-shadow(0 0 4px ${rc})`,
                             ...(meditating && markOn("seated") ? { display:"grid", placeItems:"center", color:cssHex(rc) } : {}) }}>
                {meditating ? ico("✦", "seated", { size:26 })
                            : (REALM_EMOJIS[Math.min(realm, 10)] || "🪨")}
              </span>
            </div>
            {/* Bars stack */}
            <div style={{ flex:1, minWidth:0, display:"flex", flexDirection:"column", gap:5 }}>
              <div>
                <div style={{ display:"flex", justifyContent:"space-between", marginBottom:2 }}>
                  <span style={{ fontSize:9.5, color:"var(--gold2)", letterSpacing:.5, fontFamily:"'Cinzel',serif", textTransform:"uppercase" }}>
                    {t("home_cb_label")}
                  </span>
                  <span style={{ fontSize:9.5, color:"var(--text)", fontWeight:600 }}>
                    {Math.round(cbPct)}%
                  </span>
                </div>
                <div style={{ height:5, borderRadius:3, background:"rgba(0,0,0,.55)", overflow:"hidden" }}>
                  <div style={{ width:`${cbPct}%`, height:"100%",
                    background:`linear-gradient(90deg, ${rc}, var(--gold3))`,
                    transition:"width .4s ease",
                    boxShadow: cbPct >= 100 ? `0 0 8px ${rc}` : "none" }} />
                </div>
              </div>
              <div>
                <div style={{ display:"flex", justifyContent:"space-between", marginBottom:2 }}>
                  <span style={{ fontSize:9.5, color:"#7be3ff", letterSpacing:.5, fontFamily:"'Cinzel',serif", textTransform:"uppercase" }}>
                    {t("home_qi_label")}
                  </span>
                  <span style={{ fontSize:9.5, color:"var(--text)", fontWeight:600 }}>
                    {fmtNum(Math.round(cd?.qi || 0))}/{fmtNum(Math.round(cd?.qi_capacity || 0))}
                  </span>
                </div>
                <div style={{ height:5, borderRadius:3, background:"rgba(0,0,0,.55)", overflow:"hidden" }}>
                  <div style={{ width:`${qiPct}%`, height:"100%",
                    background:"linear-gradient(90deg, #1e7a9e, #4cc4ff, #7be3ff)",
                    transition:"width .4s ease" }} />
                </div>
              </div>
            </div>
          </div>
          {/* Status / quick action footer */}
          <div style={{
            marginTop:9, paddingTop:8,
            borderTop:"1px solid rgba(var(--gold2-rgb),.12)",
            display:"flex", alignItems:"center", justifyContent:"space-between", gap:8,
          }}>
            <div style={{ fontSize:10.5, color:"var(--muted)", letterSpacing:.3, minWidth:0,
                          whiteSpace:"nowrap", overflow:"hidden", textOverflow:"ellipsis" }}>
              {loading
                ? t("home_stat_loading")
                : meditating
                  ? `🧘 ${t("home_meditating")} · ${fmtDuration(remainMs)}`
                  : t("home_idle")}
            </div>
            <button onClick={(e) => { e.stopPropagation(); meditating ? onStop() : onStart(); }}
                    style={{
                      flexShrink:0,
                      background: meditating
                        ? "linear-gradient(180deg,rgba(var(--red-rgb),.18),rgba(170,40,30,.28))"
                        : "linear-gradient(180deg,rgba(var(--jade-rgb),.18),rgba(34,140,80,.28))",
                      border: meditating
                        ? "1px solid rgba(var(--red-rgb),.45)"
                        : "1px solid rgba(var(--jade-rgb),.45)",
                      borderRadius:7, padding:"6px 12px", cursor:"pointer",
                      color: meditating ? "var(--red2)" : "var(--jade)",
                      fontFamily:"'Cinzel',serif", fontSize:10, fontWeight:700,
                      letterSpacing:.7, textTransform:"uppercase",
                    }}>
              {meditating ? t("home_meditate_stop") : t("home_meditate_start")}
            </button>
          </div>
        </div>
      );
    }

    // HomeCard — premium altar style. The icon lives inside a circular
    // medallion (dark inset, per-accent ring + glow) so the emoji reads as a
    // sigil, not a giant kid-sized sticker. Cinzel uppercase title + gold
    // thread divider with a centre dot evokes a scroll/temple plaque.
    function HomeCard({ icon, title, stat, accent, mark, stub, onClick }) {
      const interactive = typeof onClick === "function";
      // R5: alpha pré-cozido — `${ring}88` sobre rgba()/var() era inválido e
      // matava a borda do medalhão nos DOIS ramos.
      const ring = stub ? "rgba(var(--muted-rgb),.35)" : `${cssHex(accent)}88`;
      return (
        <div onClick={interactive ? onClick : undefined}
             role={interactive ? "button" : undefined}
             tabIndex={interactive ? 0 : undefined}
             style={{
          position:"relative", overflow:"hidden",
          background: stub
            ? "linear-gradient(170deg,rgba(15,20,35,.85) 0%,rgba(8,11,20,.95) 100%)"
            : "linear-gradient(170deg,rgba(var(--surface-rgb),.94) 0%,rgba(var(--surface2-rgb),.98) 100%)",
          border:`1px solid ${stub ? "rgba(var(--muted-rgb),.18)" : "rgba(var(--gold2-rgb),.32)"}`,
          borderRadius:10, padding:"14px 10px 12px",
          cursor: interactive ? "pointer" : "default",
          opacity: stub ? 0.65 : 1,
          aspectRatio:"1 / 1",
          display:"flex", flexDirection:"column", alignItems:"center", justifyContent:"space-between",
          transition:"transform .15s ease, border-color .2s ease, box-shadow .2s ease",
          boxShadow: stub ? "none" : `0 1px 0 rgba(var(--gold2-rgb),.06) inset`,
          animation:"fade-up .35s ease",
        }}
             onMouseEnter={(e) => {
               if (!interactive) return;
               e.currentTarget.style.borderColor = `${cssHex(accent)}aa`;
               e.currentTarget.style.boxShadow = `0 0 20px ${cssHex(accent)}2a, inset 0 0 14px ${cssHex(accent)}1a, 0 1px 0 rgba(var(--gold2-rgb),.12) inset`;
               e.currentTarget.style.transform = "translateY(-1px)";
             }}
             onMouseLeave={(e) => {
               if (!interactive) return;
               e.currentTarget.style.borderColor = "rgba(var(--gold2-rgb),.32)";
               e.currentTarget.style.boxShadow = "0 1px 0 rgba(var(--gold2-rgb),.06) inset";
               e.currentTarget.style.transform = "translateY(0)";
             }}>
          {/* Subtle top gold thread */}
          <div style={{
            position:"absolute", top:0, left:14, right:14, height:1,
            background:`linear-gradient(90deg,transparent,${stub ? "rgba(var(--muted-rgb),.5)" : "rgba(var(--gold2-rgb),.7)"},transparent)`,
          }} />
          {/* Chevron drill-in indicator (top-right, very subtle) */}
          {interactive && (
            <span style={{
              position:"absolute", top:6, right:9,
              fontSize:11, color:"rgba(var(--gold2-rgb),.35)",
              fontFamily:"'Cinzel',serif", lineHeight:1,
            }}>›</span>
          )}
          {stub && (
            <span style={{
              position:"absolute", top:7, right:9,
              fontSize:7.5, color:"var(--muted2)",
              fontFamily:"'Cinzel',serif", letterSpacing:.6,
              textTransform:"uppercase",
              border:"1px solid rgba(var(--muted-rgb),.3)",
              borderRadius:3, padding:"1px 5px",
            }}>{t("home_card_soon")}</span>
          )}
          {/* Medallion: circular containment for the icon */}
          <div style={{
            width:44, height:44, borderRadius:"50%",
            display:"grid", placeItems:"center",
            marginTop:6,
            background:`radial-gradient(circle, rgba(0,0,0,.45) 0%, rgba(0,0,0,.85) 80%)`,
            border:`1px solid ${ring}`,
            boxShadow: stub
              ? "inset 0 0 6px rgba(0,0,0,.6)"
              : `0 0 10px ${cssHex(accent)}33, inset 0 0 8px rgba(0,0,0,.65), inset 0 0 0 1px rgba(var(--gold2-rgb),.08)`,
          }}>
            {/* 印 A marca herda o ACENTO do proprio cartao — que ja' existia e que
                 o emoji ignorava (um emoji traz a paleta da Apple, nao a nossa).
                 O cartao tem sempre o titulo por baixo, portanto a marca nao
                 precisa de `title`: seria o leitor de ecra a dizer o nome duas
                 vezes. Com a flag OFF isto e' o mesmo `<span>` de hoje. */}
            <span style={{
              fontSize:22, lineHeight:1,
              color: markOn(mark) ? (stub ? "var(--muted)" : cssHex(accent)) : undefined,
              display: markOn(mark) ? "grid" : undefined,
              placeItems: markOn(mark) ? "center" : undefined,
              filter: stub ? "grayscale(1) brightness(.7)" : `drop-shadow(0 0 4px ${cssHex(accent)}99)`,
            }}>{ico(icon, mark, { size:24 })}</span>
          </div>
          {/* Cinzel uppercase title + ornate divider + stat */}
          <div style={{ width:"100%", textAlign:"center" }}>
            <div style={{
              fontFamily:"'Cinzel',serif", fontSize:11, fontWeight:700,
              color: stub ? "var(--muted)" : "var(--gold2)",
              letterSpacing:1, textTransform:"uppercase",
              whiteSpace:"nowrap", overflow:"hidden", textOverflow:"ellipsis",
            }}>{title}</div>
            <div style={{ display:"flex", alignItems:"center", gap:4, justifyContent:"center", margin:"4px auto 4px", maxWidth:"75%" }}>
              <div style={{ flex:1, height:1, background:`linear-gradient(90deg,transparent,${stub ? "rgba(var(--muted-rgb),.3)" : "rgba(var(--gold2-rgb),.5)"})` }} />
              <div style={{ width:2.5, height:2.5, borderRadius:"50%", background: stub ? "var(--muted2)" : "var(--gold2)" }} />
              <div style={{ flex:1, height:1, background:`linear-gradient(90deg,${stub ? "rgba(var(--muted-rgb),.3)" : "rgba(var(--gold2-rgb),.5)"},transparent)` }} />
            </div>
            <div style={{
              fontSize:10, color: stub ? "var(--muted2)" : "var(--text)",
              opacity:.82, lineHeight:1.3,
              whiteSpace:"nowrap", overflow:"hidden", textOverflow:"ellipsis",
              padding:"0 2px",
            }}>{stat}</div>
          </div>
        </div>
      );
    }

    // ─── Sprint v14.10 — MA-37 Bestiário ─────────────────────────────────────
    // Drill-in tab from Home → 🐾 Bestas. 3 sub-views (Lista / Captura /
    // Companion) — Lista is the default and shows owned beasts with level-up
    // CTAs; Captura shows the catalog with chance preview + 🪤 trap counts;
    // Companion is a slim picker that bumps the equipped beast for combat
    // bonuses (mirrors set_companion / remove_companion in beast_engine).

    var _BEAST_RANK_COLOR = {
      "Common":    "var(--realm-0)",
      "Uncommon":  "#86efac",
      "Rare":      "var(--realm-1)",
      "Epic":      "var(--realm-3)",
      "Legendary": "var(--realm-2)",
      "Mythic":    "var(--realm-10)",
      "Divine":    "var(--gold2)",
    };
    var _TRAP_QUALITY_LABEL = {
      normal: "Comum", common: "Comum", rare: "Raro",
      epic: "Épico", mythic: "Mítico", legendary: "Lendário",
    };

    function BeastsTab({ player, onPlayerRefresh }) {
      const [seg, setSeg] = useState("list"); // list|capture|companion
      const [reload, setReload] = useState(0);
      const { data, loading, error } = useApi("beasts/list", null, [reload]);
      // 獸 3.3 — o ÚNICO leitor da chave-mestra nesta aba. Com ela, a lista é a
      // besta selecionada com o selo de crescimento (`BestasOnda`); sem ela, a
      // `BeastsListPanel` de sempre, intocada.
      const onda = obraOn();
      const refreshAll = () => {
        setReload(x => x + 1);
        if (onPlayerRefresh) onPlayerRefresh();
      };

      const opts = [
        { value:"list",      label:`📜 ${t("beasts_seg_list")}` },
        { value:"capture",   label:`🪤 ${t("beasts_seg_capture")}` },
        { value:"companion", label:`🐾 ${t("beasts_seg_companion")}` },
      ];

      const ownedCount = (data?.owned || []).length;
      const trapTotal = data?.traps?.total || 0;
      const companion = (data?.owned || []).find(b => b.is_companion);

      return (
        <div>
          <Card style={{ padding:"11px 13px 9px", marginBottom:11 }}>
            <div style={{ display:"flex", alignItems:"center", gap:11, marginBottom:8 }}>
              <div style={{ fontSize:30, lineHeight:1, filter:"drop-shadow(0 0 8px rgba(var(--gold2-rgb),.45))" }}>🐾</div>
              <div style={{ minWidth:0, flex:1 }}>
                <div style={{ fontFamily:"'Cinzel',serif", fontWeight:700, fontSize:14,
                              color:"var(--gold2)", letterSpacing:.4 }}>
                  {t("beasts_tab_title")}
                </div>
                <div style={{ fontSize:11, color:"var(--muted)", lineHeight:1.4 }}>
                  {t("beasts_tab_subtitle")}
                </div>
              </div>
            </div>
            {data && (
              <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr 1fr", gap:6, fontSize:11 }}>
                <StatChip label={t("beasts_stat_owned")} value={`${ownedCount}`} accent="var(--gold2)" />
                <StatChip label={t("beasts_stat_traps")} value={`${trapTotal}`} accent="var(--realm-3)" />
                <StatChip label={t("beasts_stat_companion")}
                          value={companion ? companion.name : t("beasts_stat_none")}
                          accent="var(--jade)" />
              </div>
            )}
            <div style={{ marginTop:9 }}>
              <SegControl options={opts} value={seg} onChange={setSeg} />
            </div>
          </Card>

          {error && <ErrBanner msg={error} />}
          {loading && !data && <ListSkeleton rows={5} />}
          {data && seg === "list" && (onda
            ? <BestasOnda data={data} onChanged={refreshAll} falhou={!!error} />
            : <BeastsListPanel data={data} onChanged={refreshAll} />
          )}
          {data && seg === "capture" && (
            <BeastsCapturePanel data={data} onChanged={refreshAll} />
          )}
          {data && seg === "companion" && (
            <BeastsCompanionPanel data={data} onChanged={refreshAll} />
          )}
        </div>
      );
    }

    function BeastsListPanel({ data, onChanged }) {
      const [busyId, setBusyId] = useState(null);
      const [detail, setDetail] = useState(null);
      // v14.11 — drill-in modals for expedition + evolve.
      const [expBeast, setExpBeast] = useState(null);
      const [evoBeast, setEvoBeast] = useState(null);
      const owned = data.owned || [];

      async function callCollect(beast_id, beastName) {
        if (busyId) return;
        setBusyId(`collect-${beast_id}`);
        haptic("warning");
        try {
          const res = await api("beasts/collect_expedition", { beast_id });
          if (!res.ok) {
            haptic("error");
            showToast(_translateBeastReason(res.reason, res.error_params), "err");
            return;
          }
          haptic("success");
          const dropsTxt = (res.drops && res.drops.length)
            ? res.drops.slice(0, 3).join(" · ")
            : t("beasts_collect_empty");
          showToast(t("beasts_collect_done", {
            name: res.beast_name || beastName, drops: dropsTxt,
          }));
          onChanged();
        } catch (e) {
          haptic("error");
          showToast(e.message, "err");
        } finally {
          setBusyId(null);
        }
      }

      // 牌 §2.3 — as MESMAS chamadas que a fila de acções da lista faz, içadas
      // para poderem servir os dois sítios. Com `cartas` OFF ninguém as chama
      // (a `actionRow` continua a ter o corpo inline, byte a byte); com a flag
      // ON são a única forma de treinar/equipar, e vivem no modal.
      async function callTrain(b, count) {
        if (busyId) return;
        setBusyId(`level${count}-${b.id}`);
        try {
          const res = await api("beasts/level_up", { beast_id: b.id, count });
          if (res.ok) {
            haptic("success");
            if (count === 1) {
              showToast(res.levels_gained > 0
                ? t("beasts_train_levelup", { level: res.new_level })
                : t("beasts_train_xp", { xp: res.xp_gained }));
            } else {
              showToast(t("beasts_train_bulk_done", {
                levels: res.levels_gained, cost: res.cost,
              }));
            }
            onChanged();
          } else {
            haptic("error");
            showToast(_translateBeastReason(
              count === 1 ? res.reason : res.last_reason,
              count === 1 ? res.error_params : res.last_error_params), "err");
          }
        } catch (e) {
          haptic("error");
          showToast(e.message, "err");
        } finally {
          setBusyId(null);
        }
      }

      async function callCompanion(b) {
        if (busyId) return;
        setBusyId(`comp-${b.id}`);
        try {
          const res = await api("beasts/equip_companion", { beast_id: b.id });
          if (res.ok) {
            haptic("success");
            showToast(t("beasts_companion_equipped"));
            onChanged();
          } else {
            haptic("error");
            showToast(t("beasts_companion_failed"), "err");
          }
        } catch (e) {
          haptic("error");
          showToast(e.message, "err");
        } finally {
          setBusyId(null);
        }
      }

      if (!owned.length) {
        return (
          <Card>
            <div style={{ textAlign:"center", padding:"24px 12px" }}>
              <div style={{ fontSize:36 }}>🐾</div>
              <div style={{ marginTop:10, fontSize:12, color:"var(--muted)" }}>
                {t("beasts_empty_owned")}
              </div>
            </div>
          </Card>
        );
      }
      const cardsGrid = typeof featureEnabled === "function" && featureEnabled("cartas");
      // ⚠️ `Fragment`, NAO `"div"`. A 1a versao usava `"div"` com a flag OFF e o
      // ensaio contra o HEAD apanhou-a: aparecia **um `<div>` a mais** no DOM
      // dos 248. Nao partia nada — e e' precisamente por isso que so' um diff
      // o via. A promessa e' byte-identico, e um invólucro inerte nao e'
      // byte-identico. (A mesma correccao que o `SurfaceColumn` da WEB-C.)
      const Wrap = cardsGrid ? CardGrid : React.Fragment;
      return (
        <div>
          <Wrap {...(cardsGrid ? { min: 168 } : {})}>
          {/* 牌 A CARTA — a BESTA: o único PERSONAGEM não-humano do jogo, e a
              escala mais longa que existe (7 postos, `config.BEAST_RANKS`).
              É o que prova que o lombo não está calibrado para cinco.

              ⚠️ As três peças (cabeçalho · barra de XP · fila de acções) são
              escritas UMA vez e servem os dois caminhos. Com `cartas` OFF o
              <Card> recebe exactamente os mesmos três filhos, pela mesma
              ordem, que recebia antes — a promessa de não-regressão é por
              construção, não por disciplina (a lição do `SurfaceColumn`).

              ⚠️ E um defeito que a carta obrigou a consertar: `{b.rank}` era
              impresso CRU, ou seja "Legendary" a um jogador pt-BR. Agora é a
              escala que o traduz — mas SÓ no caminho novo, porque mudar o
              caminho velho mudaria a tela dos 248. Sobra escrito no §5. */}
          {owned.map(b => {
            const cardsOn = typeof featureEnabled === "function" && featureEnabled("cartas");
            const xpBar = (
            <div style={{ marginTop:7 }}>
              <div style={{ display:"flex", justifyContent:"space-between", marginBottom:3,
                            fontSize:9, color:"var(--muted)" }}>
                <span style={{ fontFamily:"'Cinzel',serif", letterSpacing:.4, textTransform:"uppercase" }}>
                  XP
                </span>
                <span>{b.exp}/{b.exp_needed}</span>
              </div>
              <div style={{ height:5, borderRadius:3, background:"rgba(0,0,0,.55)", overflow:"hidden" }}>
                <div style={{
                  width:`${b.exp_needed ? Math.min(100, (b.exp / b.exp_needed) * 100) : 0}%`,
                  height:"100%",
                  background:"linear-gradient(90deg,var(--realm-5),var(--realm-1),var(--realm-2))",
                  transition:"width .4s ease"
                }} />
              </div>
            </div>
            );
            const actionRow = (
            <div style={{ display:"flex", gap:6, marginTop:8, flexWrap:"wrap" }}>
              <ActionBtn variant="primary" size="sm"
                         disabled={busyId === b.id || b.is_on_expedition || b.level >= b.max_level
                                   || data.spirit_stones < b.train_cost}
                         busy={busyId === `level1-${b.id}`}
                         onClick={async () => {
                           setBusyId(`level1-${b.id}`);
                           try {
                             const res = await api("beasts/level_up", { beast_id: b.id, count: 1 });
                             if (res.ok) {
                               haptic("success");
                               if (res.levels_gained > 0) {
                                 showToast(t("beasts_train_levelup", { level: res.new_level }));
                               } else {
                                 showToast(t("beasts_train_xp", { xp: res.xp_gained }));
                               }
                               onChanged();
                             } else {
                               haptic("error");
                               showToast(_translateBeastReason(res.reason, res.error_params), "err");
                             }
                           } catch (e) {
                             haptic("error");
                             showToast(e.message, "err");
                           } finally {
                             setBusyId(null);
                           }
                         }}>
                💪 {t("beasts_btn_train", { cost: b.train_cost })}
              </ActionBtn>
              <ActionBtn variant="ghost" size="sm"
                         disabled={busyId !== null || b.is_on_expedition || b.level >= b.max_level
                                   || data.spirit_stones < b.train_cost}
                         busy={busyId === `level10-${b.id}`}
                         onClick={async () => {
                           setBusyId(`level10-${b.id}`);
                           try {
                             const res = await api("beasts/level_up", { beast_id: b.id, count: 10 });
                             if (res.ok) {
                               haptic("success");
                               showToast(t("beasts_train_bulk_done", {
                                 levels: res.levels_gained, cost: res.cost,
                               }));
                               onChanged();
                             } else {
                               haptic("error");
                               showToast(_translateBeastReason(res.last_reason, res.last_error_params), "err");
                             }
                           } finally {
                             setBusyId(null);
                           }
                         }}>
                💪 ×10
              </ActionBtn>
              {!b.is_companion && !b.is_on_expedition && (
                <ActionBtn variant="ghost" size="sm"
                           busy={busyId === `comp-${b.id}`}
                           onClick={async () => {
                             setBusyId(`comp-${b.id}`);
                             try {
                               const res = await api("beasts/equip_companion", { beast_id: b.id });
                               if (res.ok) {
                                 haptic("success");
                                 showToast(t("beasts_companion_equipped"));
                                 onChanged();
                               } else {
                                 haptic("error");
                                 showToast(t("beasts_companion_failed"), "err");
                               }
                             } finally {
                               setBusyId(null);
                             }
                           }}>
                  {t("beasts_btn_set_companion")}
                </ActionBtn>
              )}
              {/* v14.11 — Send Expedition CTA. Disabled if companion (engine
                  refuses) or already on expedition. */}
              {!b.is_on_expedition && !b.is_companion && (
                <ActionBtn variant="ghost" size="sm"
                           onClick={() => { haptic("light"); setExpBeast(b); }}>
                  🗺️ {t("beasts_btn_send_exp")}
                </ActionBtn>
              )}
              {/* v14.11 — Collect Expedition CTA: only when returned. Server
                  enforces err_expedition_not_ready if still in transit. */}
              {b.is_on_expedition && (() => {
                const remaining = b.expedition_returns_at_ms
                                ? b.expedition_returns_at_ms - Date.now()
                                : 0;
                const ready = remaining <= 0;
                return ready ? (
                  <ActionBtn variant="primary" size="sm"
                             disabled={!!busyId}
                             busy={busyId === `collect-${b.id}`}
                             onClick={() => callCollect(b.id, b.name)}
                             style={{
                               background:"linear-gradient(180deg, rgba(46,196,182,.4), rgba(20,80,70,.6))",
                               border:"1px solid var(--jade)",
                             }}>
                    🎁 {t("beasts_btn_collect")}
                  </ActionBtn>
                ) : (
                  <div style={{ fontSize:10, color:"var(--muted)", alignSelf:"center" }}>
                    ⏳ {fmtDuration(remaining)}
                  </div>
                );
              })()}
              {/* v14.11 — Evolve CTA: only when ready (rank cap not hit AND
                  level requirement met). Cores currency checked server-side. */}
              {b.evolution && b.evolution.can_evolve && b.evolution.level_met
               && !b.is_on_expedition && (
                <ActionBtn variant="ghost" size="sm"
                           disabled={data.cores < (b.evolution.cores_needed || 0)}
                           onClick={() => { haptic("warning"); setEvoBeast(b); }}>
                  🌟 {t("beasts_btn_evolve")}
                </ActionBtn>
              )}
            </div>
            );
            if (!cardsOn) {
              return (
                <Card key={b.id} style={{ marginBottom:9, padding:"10px 12px" }}>
                  <div style={{ display:"flex", alignItems:"center", gap:10 }}>
                    <div style={{ fontSize:30, lineHeight:1,
                                  filter:`drop-shadow(0 0 6px ${cssHex(_BEAST_RANK_COLOR[b.rank] || "var(--realm-0)")}99)` }}>
                      {b.emoji}
                    </div>
                    <div style={{ flex:1, minWidth:0 }}>
                      <div style={{ display:"flex", alignItems:"center", gap:6 }}>
                        <span style={{ fontFamily:"'Cinzel',serif", fontWeight:700, fontSize:13,
                                       color:"var(--text)", letterSpacing:.3 }}>{b.name}</span>
                        {b.is_companion && (
                          <span style={{ fontSize:9, color:"var(--jade)",
                                         fontFamily:"'Cinzel',serif", letterSpacing:.5,
                                         border:"1px solid var(--jade)", borderRadius:3,
                                         padding:"1px 4px" }}>
                            {t("beasts_companion_badge")}
                          </span>
                        )}
                      </div>
                      <div style={{ fontSize:10.5, color:"var(--muted)", marginTop:2 }}>
                        <span style={{ color: _BEAST_RANK_COLOR[b.rank] || "var(--muted)" }}>
                          {b.rank}
                        </span>
                        <span> · Lv.{b.level}/{b.max_level}</span>
                        {b.is_on_expedition && (
                          <span style={{ marginLeft:6, color:"var(--warn)" }}>· 🗺️ {t("beasts_status_expedition")}</span>
                        )}
                      </div>
                    </div>
                    <ActionBtn variant="ghost" size="sm"
                               onClick={() => { haptic("light"); setDetail(b); }}>
                      {t("beasts_btn_details")}
                    </ActionBtn>
                  </div>
                  {xpBar}
                  {actionRow}
                </Card>
              );
            }
            // 牌 §2.3 — A CARTA MOSTRA, O MODAL OPERA.
            //
            // ⚠️ É mudança de PRODUTO, não de estilo, e a razão foi MEDIDA a
            // olho: as quatro acções empilham a 164px e davam à carta ~450px de
            // altura — a arte, que é a razão de a carta existir, ficava a um
            // quinto do cartão, e as linhas da grelha ficavam esfarrapadas
            // porque uma besta companheira tem 2 acções e uma livre tem 4.
            //
            // ⚠️ Lei §1 — NADA fica inalcançável: as quatro mudaram-se para o
            // `BeastDetailModal` (bloco `ops`) ANTES de saírem daqui, e a carta
            // inteira passa a ser o botão que o abre. O estado que era urgente
            // (🎁 expedição pronta) sobe ao `stateLabel`, por cima da arte, para
            // não deixar de ser VISÍVEL sem estar aberto.
            const expReady = b.is_on_expedition && b.expedition_returns_at_ms
                             && b.expedition_returns_at_ms - Date.now() <= 0;
            return (
              <NivraelCard key={b.id}
                kind="beast" rank={b.rank}
                glyph={b.emoji}
                art={pieceArt("beast", b.name, b.art_key)}
                name={b.name}
                accent={_BEAST_RANK_COLOR[b.rank] || "var(--realm-0)"}
                state={b.is_companion ? "active" : "owned"}
                onClick={() => { haptic("light"); setDetail(b); }}
                stateLabel={b.is_companion ? t("beasts_companion_badge")
                           : expReady ? `🎁 ${t("beasts_btn_collect")}`
                           : b.is_on_expedition ? `🗺️ ${t("beasts_status_expedition")}` : null}
                effect={`Lv.${b.level}/${b.max_level}`}
                body={xpBar}
                foot={(
                  <>
                    <span>🪨 {b.train_cost}</span>
                    <span style={{ color:"var(--gold2)" }}>
                      {t("beasts_btn_details")} ›
                    </span>
                  </>
                )}
              />
            );
          })}
          </Wrap>
          {detail && <BeastDetailModal beast={owned.find(x => x.id === detail.id) || detail}
                                       onClose={() => setDetail(null)}
                                       onSendExpedition={() => { setDetail(null); setExpBeast(detail); }}
                                       onEvolve={() => { setDetail(null); setEvoBeast(detail); }}
                                       cores={data.cores}
                                       ops={cardsGrid ? {
                                         busyId, stones: data.spirit_stones,
                                         onTrain: callTrain,
                                         onCompanion: callCompanion,
                                         onCollect: (b) => callCollect(b.id, b.name),
                                       } : null} />}
          {expBeast && <BeastExpeditionModal beast={expBeast}
                                             onClose={() => setExpBeast(null)}
                                             onSent={onChanged} />}
          {evoBeast && <BeastEvolveModal beast={evoBeast}
                                         onClose={() => setEvoBeast(null)}
                                         onEvolved={onChanged} />}
        </div>
      );
    }

    // ═══ 獸 3.3 — AS BESTAS: a besta selecionada e o selo de crescimento ═══════
    //
    // A linha é do Astra (`Olho/Astra/2026-09-16-e-o-corpo-que-acende.md`,
    // «Caverna · Bestas»): *"A besta selecionada, com um selo de crescimento
    // junto dela. (...) XP desenvolve o traço; nível/evolução confirmados fixam
    // a marca. `is_companion` e `is_on_expedition` mostram função/atividade. Não
    // somar todas as bestas num animal ou nível fictício."*
    //
    // MEDIDO antes (`tools/db_readonly_bestas_1001.py`): p50 = UMA besta (148 dos
    // 242 do `main` só têm a inicial), p90 = 16, máx. 32; 288 no nível 100. ⇒ o
    // corpo é UMA besta; a lista das outras só aparece quando há outras, e
    // escolher uma NÃO abre modal — muda a besta do corpo.
    //
    // Só com a chave-mestra (`obraOn()`, lido UMA vez no `BeastsTab`); sem ela, a
    // `BeastsListPanel` de sempre, intocada.

    // O NOME do posto, do elemento e de cada bónus — UM dono para as telas das
    // bestas. Com a chave-mestra, a palavra na língua do jogador; sem ela, o
    // valor de hoje, exactamente (a OFF-identidade é por construção: o `main`
    // recebe o mesmo texto que recebia).
    function postoDaBesta(rank) {
      if (!obraOn()) return rank;
      const r = nivRank("beast", rank);
      return (r && r.label) || rank;
    }
    function elementoDaBesta(el) {
      if (!obraOn() || !el) return el;
      const k = "world_element_" + String(el).toLowerCase();
      const v = t(k);
      return v && v !== k ? v : el;
    }
    function bonusDaBesta(key) {
      const k = "beasts_bonus_" + key;
      const v = t(k);
      return v && v !== k ? v : humanizeStat(String(key).replace("_mult", ""));
    }
    // o nível compacto das linhas e das cartas: "Lv.12" / "Lv.12/100" sem a
    // chave-mestra (o texto de hoje), "Nv. 12" / "Nv. 12/100" com ela
    function nvDaBesta(level, max) {
      const base = obraOn() ? t("beasts_onda_nv", { level: level }) : "Lv." + level;
      return max != null ? base + "/" + max : base;
    }
    // o bónus em pontos percentuais inteiros — a mesma conta do detalhe de hoje
    function _pctBesta(v) { return Math.round(((Number(v) || 1) - 1) * 100); }

    // As linhas do RECIBO de uma acção confirmada. Saem do `besta_ganho` do
    // servidor (antes→depois da MESMA transacção) e dos números da resposta —
    // nunca de uma conta feita aqui.
    function reciboDaBesta(acao, res, g) {
      const L = [];
      const a = g && g.antes, d = g && g.depois;
      const subiu = !!(a && d && Number(d.level) > Number(a.level));
      if (acao === "evo") {
        if (a && d) L.push(t("beasts_onda_recibo_posto", { a: postoDaBesta(a.rank), b: postoDaBesta(d.rank) }));
        if (res.cores_used) L.push(t("beasts_onda_recibo_nucleos", { n: fmtFull(res.cores_used) }));
        if (a && d) {
          Object.keys(d.effective_stats || {}).forEach(k => {
            const x = _pctBesta((a.effective_stats || {})[k]), y = _pctBesta(d.effective_stats[k]);
            if (x !== y) L.push(t("beasts_onda_recibo_bonus", { nome: bonusDaBesta(k), a: x, b: y }));
          });
        }
      } else if (acao === "col") {
        (res.drops || []).forEach(x => L.push(String(x)));
        // a expedição devolve XP: o nível que subiu, ou o XP antes→depois (a
        // diferença dos DOIS retratos da mesma transacção — nunca uma conta)
        if (subiu) L.push(t("beasts_onda_recibo_nivel", { a: a.level, b: d.level, n: d.level - a.level }));
        else if (a && d && Number(d.exp) > Number(a.exp)) {
          L.push(t("beasts_onda_recibo_xp", { xp: fmtFull(d.exp - a.exp), a: fmtFull(a.exp),
                                               b: fmtFull(d.exp), need: fmtFull(d.exp_needed) }));
        }
      } else {
        if (subiu) {
          L.push(t("beasts_onda_recibo_nivel", { a: a.level, b: d.level, n: d.level - a.level }));
        } else if (a && d) {
          L.push(t("beasts_onda_recibo_xp", { xp: fmtFull(res.xp_gained || 0), a: fmtFull(a.exp),
                                               b: fmtFull(d.exp), need: fmtFull(d.exp_needed) }));
        }
        if (acao === "t10" && res.iterations) L.push(t("beasts_onda_recibo_treinos", { n: fmtFull(res.iterations) }));
        if (res.cost) L.push(t("beasts_onda_recibo_pedras", { n: fmtFull(res.cost) }));
        // o lote pára quando as pedras acabam — dizer porquê, com o número
        if (acao === "t10" && res.last_reason) {
          const pr = Object.assign({}, res.last_error_params || {});
          if (pr.cost != null) pr.cost = fmtFull(pr.cost);
          L.push(_translateBeastReason(res.last_reason, pr));
        }
      }
      return L;
    }

    // Uma LINHA da colecção — a miniatura mostra a peça e o seu estado, sem
    // pulsar (Astra §1: "Em listas, as miniaturas mostram a peça e o seu estado").
    // Cada linha é um botão que diz TUDO no `aria-label`.
    function BestaLinha({ b, sel, onSel }) {
      const P = NIV_ONDA;
      const pronta = b.is_on_expedition && b.expedition_returns_at_ms
                     && b.expedition_returns_at_ms - Date.now() <= 0;
      const estado = b.is_companion ? t("beasts_onda_companheira")
                   : pronta ? t("beasts_onda_exp_pronta")
                   : b.is_on_expedition ? t("beasts_status_expedition") : null;
      const nv = t("beasts_onda_nv", { level: b.level });
      return (
        <li>
          <button type="button" aria-pressed={sel} onClick={onSel} data-besta-linha={b.id}
                  aria-label={[b.name, postoDaBesta(b.rank), nv, estado].filter(Boolean).join(", ")}
                  style={{ width: "100%", minHeight: 56, cursor: "pointer", textAlign: "left",
                           background: sel ? "rgba(201,144,58,.08)" : "transparent",
                           border: 0, borderTop: "1px solid " + P.line, borderRadius: 0,
                           borderLeft: "1px solid " + (sel ? P.gold : "transparent"),
                           padding: "8px 10px", display: "flex", alignItems: "center", gap: 12,
                           color: P.paper, fontFamily: P.body, boxShadow: "none" }}>
            <PieceIcon kind="beast" name={b.name} artKey={b.art_key} emoji={b.emoji} size={40}
                       accent={P.gold} radius={0} />
            <span style={{ flex: 1, minWidth: 0 }}>
              <span style={{ display: "block", fontSize: 14, lineHeight: (20 / 14),
                             overflowWrap: "anywhere" }}>{b.name}</span>
              <span style={{ display: "block", fontSize: 12, lineHeight: (16 / 12), color: P.muted }}>
                {postoDaBesta(b.rank)}
                {estado ? <span style={{ color: b.is_companion || pronta ? P.gold : P.muted }}>{" · " + estado}</span> : null}
              </span>
            </span>
            <span style={Object.assign({}, _ONDA_TNUM, { fontSize: 13, color: P.paper, flexShrink: 0 })}>
              {nv}
            </span>
          </button>
        </li>
      );
    }

    function BestasOnda({ data, onChanged, falhou }) {
      const P = NIV_ONDA;
      const wide = typeof useWideShell === "function" ? useWideShell() : false;
      const owned = data.owned || [];
      const ranks = Array.isArray(data.ranks) ? data.ranks : [];
      const pedras = data.spirit_stones;
      const nucleos = Number(data.cores) || 0;
      // ⚠️ TODOS os estados nascem aqui, antes de qualquer `return` (React #310 —
      // um hook depois de um return parte a aba).
      const [selId, setSelId] = useState(null);
      const [busy, setBusy] = useState(null);       // "t1" | "t10" | "evo" | "comp" | "col"
      const [erro, setErro] = useState(null);       // { id, texto }
      const [recibo, setRecibo] = useState(null);   // { id, linhas }
      const [acende, setAcende] = useState(null);   // { id, eixos, k }
      const [confEvo, setConfEvo] = useState(false);
      const [expBeast, setExpBeast] = useState(null);
      // o "depois" confirmado, por cima dos dados que AINDA não o apanharam: o
      // número muda ao receber a confirmação, sem esperar pelo recarregar.
      const [ov, setOv] = useState(null);           // { id, depois, dados }
      const corpoRef = useRef(null);
      const seloRef = useRef(null);
      // conta as confirmações com ganho: é o que manda o selo+recibo voltar à vista
      const [rolar, setRolar] = useState(0);
      // os dados já apanharam a última confirmação? (o mesmo teste do `pendente`
      // de baixo, sem depender da besta selecionada — tem de nascer antes dos
      // `return`)
      const dadosFrescos = !(ov && ov.dados === data);
      useEffect(() => {
        if (!acende) return undefined;
        const id = setTimeout(() => setAcende(null), 900);
        return () => clearTimeout(id);
      }, [acende]);
      // ⚠️ A LUZ TEM DE SE VER (a lição do Corpo, 2.1): no telefone o botão fica
      // abaixo do selo; ao confirmar, o selo E o recibo voltam à vista juntos.
      // ⚠️ Olhado a 390 (02/10), DUAS vezes: (1) rolar só o selo para o CENTRO
      // deixava o recibo ("Nível 12 → 22") debaixo da barra de baixo — a luz
      // via-se e o número não; (2) mesmo alinhado pelo fim, a RELEITURA trazia de
      // volta o bloco da evolução (escondido enquanto os dados estão velhos) e
      // empurrava o recibo outra vez para baixo da barra. O alvo é o bloco
      // selo+recibo, pelo FIM, acima da barra — e confere-se de novo quando os
      // dados ficam frescos.
      useEffect(() => {
        if (!rolar || !seloRef.current) return;
        try {
          const r = seloRef.current.getBoundingClientRect();
          if (r.top >= 0 && r.bottom <= (window.innerHeight || 0) - 96) return;
          const reduz = window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches;
          seloRef.current.scrollIntoView({ behavior: reduz ? "auto" : "smooth", block: "end" });
        } catch (e) { /* sem rolagem, a leitura continua certa */ }
      }, [rolar, dadosFrescos]);

      if (!owned.length) {
        return (
          <section style={{ padding: "18px 2px 28px", fontFamily: P.body, fontSize: 14,
                            lineHeight: (20 / 14), color: P.muted }}>
            {t("beasts_empty_owned")}
          </section>
        );
      }

      const b = owned.find(x => x.id === selId) || owned.find(x => x.is_companion) || owned[0];
      // ⚠️ "fresco" = os dados já apanharam a última confirmação. Enquanto não,
      // mostra-se o confirmado e NÃO se oferece a próxima acção: o preço do
      // próximo treino e a próxima evolução ainda são os de antes (Astra:
      // "reconciliar antes de repetir uma ação que consome recursos").
      const pendente = !!(ov && ov.id === b.id && ov.dados === data);
      const v = pendente ? Object.assign({}, b, ov.depois) : b;
      const fresco = !pendente;
      const noTecto = Number(v.level) >= Number(v.max_level);
      const evo = v.evolution || null;
      const temProxPosto = !!(evo && !evo.at_max && evo.next_rank);
      const naExp = !!v.is_on_expedition;
      const voltou = naExp && v.expedition_returns_at_ms && v.expedition_returns_at_ms - Date.now() <= 0;
      const faltaPedras = pedras != null ? Math.max(0, Number(v.train_cost || 0) - Number(pedras)) : 0;
      const podeTreinar = fresco && !busy && !naExp && !noTecto && faltaPedras <= 0;
      const nivelOk = !!(evo && evo.level_met);
      const nucleosOk = !!(evo && nucleos >= Number(evo.cores_needed || 0));
      const podeEvoluir = fresco && !busy && !naExp && temProxPosto && nivelOk && nucleosOk;
      const eixos = (acende && acende.id === b.id) ? acende.eixos : [];
      const meuRecibo = recibo && recibo.id === b.id ? recibo : null;
      const meuErro = erro && erro.id === b.id ? erro : null;

      function escolher(x) {
        if (busy) return;
        haptic("select");
        setSelId(x.id); setConfEvo(false); setErro(null);
        try {
          const el = corpoRef.current;
          if (el) {
            const r = el.getBoundingClientRect();
            if (r.top < 0 || r.top > (window.innerHeight || 0) * 0.5) {
              const reduz = window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches;
              el.scrollIntoView({ behavior: reduz ? "auto" : "smooth", block: "start" });
            }
          }
        } catch (e) { /* idem */ }
      }

      // UMA porta para as quatro acções que mexem na besta. Só um `ok: true`
      // guarda o ganho e acende — nunca o toque.
      async function agir(acao) {
        if (busy) return;
        const alvo = b;
        const rota = acao === "evo" ? "beasts/evolve"
                   : acao === "col" ? "beasts/collect_expedition"
                   : acao === "comp" ? "beasts/equip_companion" : "beasts/level_up";
        const corpo = acao === "t1" ? { beast_id: alvo.id, count: 1 }
                    : acao === "t10" ? { beast_id: alvo.id, count: 10 }
                    : { beast_id: alvo.id };
        setBusy(acao); setErro(null); setConfEvo(false);
        haptic(acao === "evo" ? "warning" : "select");
        try {
          const res = await api(rota, corpo);
          if (res && res.ok === true) {
            haptic("success");
            const g = res.besta_ganho || null;
            if (acao !== "comp") setRecibo({ id: alvo.id, linhas: reciboDaBesta(acao, res, g) });
            if (g && g.depois) setOv({ id: alvo.id, depois: g.depois, dados: data });
            if (g && (g.acende || []).length) setAcende({ id: alvo.id, eixos: g.acende, k: Date.now() });
            if (g) setRolar(x => x + 1);
            onChanged && onChanged();
          } else {
            haptic("error");
            const why = acao === "comp" ? t("beasts_companion_failed")
                      : acao === "t10" ? _translateBeastReason(res && res.last_reason, res && res.last_error_params)
                      : _translateBeastReason(res && res.reason, res && res.error_params);
            setErro({ id: alvo.id, texto: why });
          }
        } catch (e) {
          haptic("error");
          setErro({ id: alvo.id, texto: (e && e.message) || t("beasts_train_failed") });
        } finally {
          setBusy(null);
        }
      }

      // ── as PEÇAS ─────────────────────────────────────────────────────────
      const rotulo = { fontFamily: P.label, fontSize: 10, lineHeight: 1.6, letterSpacing: ".16em",
                       textTransform: "uppercase", color: P.muted };
      const numero = Object.assign({}, _ONDA_TNUM, { marginLeft: "auto", fontSize: 16,
                                                      lineHeight: (22 / 16), color: P.paper });
      const arte = (
        <div style={{ position: "relative" }}>
          <CardArt src={pieceArt("beast", b.name, b.art_key)} glyph={b.emoji} accent={P.gold}
                   aspect={wide ? "4 / 3" : "16 / 10"} glyphSize={72} focus="50% 40%" />
        </div>
      );
      const estadoTxt = v.is_companion ? t("beasts_onda_companheira")
                      : voltou ? t("beasts_onda_exp_pronta")
                      : naExp ? t("beasts_onda_em_exp", { t: fmtDuration((v.expedition_returns_at_ms || 0) - Date.now()) })
                      : null;
      const cabeca = (
        <div>
          <h2 style={{ fontFamily: P.serif, fontWeight: 400, margin: 0, color: P.paper,
                       fontSize: wide ? 40 : 30, lineHeight: wide ? (44 / 40) : (34 / 30),
                       letterSpacing: "-.02em", overflowWrap: "anywhere" }}>{b.name}</h2>
          <div style={{ marginTop: 6, fontFamily: P.body, fontSize: 13, lineHeight: (20 / 13), color: P.muted }}>
            {[postoDaBesta(v.rank), elementoDaBesta(b.element)].filter(Boolean).join(" · ")}
            {estadoTxt ? (
              <span style={{ color: v.is_companion || voltou ? P.gold : P.muted }}>{" · " + estadoTxt}</span>
            ) : null}
          </div>
        </div>
      );

      // O SELO DE CRESCIMENTO: o posto (a escada de 7 que o SERVIDOR manda) e o
      // nível, cada um com o seu número. Sem a escada do servidor, nenhuma
      // inscrição — "posto 2 de ?" não se inventa aqui.
      const _passo = 34;
      const nPostos = ranks.length;
      const idx = Number(v.rank_idx) || 0;
      const posto = nPostos > 0 ? (
        <div style={{ padding: "12px 0 0", borderTop: "1px solid " + P.line }}>
          <div style={{ display: "flex", alignItems: "baseline", columnGap: 12 }}>
            <span style={rotulo}>{t("beasts_onda_posto")}</span>
            <span style={numero}>{t("beasts_onda_posto_de", { posto: postoDaBesta(v.rank), n: idx + 1, max: nPostos })}</span>
          </div>
          <div aria-hidden="true" data-besta-postos=""
               style={{ position: "relative", height: 40, marginTop: 10, width: (nPostos - 1) * _passo + 22 }}>
            <span style={{ position: "absolute", left: 11, top: 11, height: 1,
                           width: (nPostos - 1) * _passo, background: "rgba(236,229,216,.22)" }} />
            {idx > 0 && (
              <span style={{ position: "absolute", left: 11, top: 11, height: 1,
                             width: Math.min(idx, nPostos - 1) * _passo, background: "rgba(201,144,58,.85)" }} />
            )}
            {ranks.map((r, i) => {
              const estado = i <= idx ? "got" : (i === idx + 1 && temProxPosto && fresco) ? "next" : "empty";
              return (
                <span key={r} data-besta-posto={estado}
                      style={{ position: "absolute", left: i * _passo, top: 0, width: 22, height: 40 }}>
                  <span style={{ position: "absolute", left: 11, top: 11, width: 0, height: 0 }}>
                    <MarcaOnda estado={estado} acende={eixos.indexOf("posto") >= 0 && i === idx} />
                  </span>
                  <span style={Object.assign({}, _ONDA_TNUM, {
                    position: "absolute", left: 0, right: 0, top: 24, textAlign: "center",
                    fontSize: 10, lineHeight: 1.4,
                    color: estado === "empty" ? "rgba(236,229,216,.45)" : P.paper })}>{i + 1}</span>
                </span>
              );
            })}
          </div>
          {!temProxPosto && evo && evo.at_max && (
            <div style={{ fontSize: 12.5, lineHeight: (18 / 12.5), color: P.muted }}>{t("beasts_onda_posto_max")}</div>
          )}
          {temProxPosto && fresco && (
            <div style={{ marginTop: 2 }}>
              <div style={Object.assign({}, rotulo, { color: P.gold })}>
                {t("beasts_onda_evoluir_a", { posto: postoDaBesta(evo.next_rank) })}
              </div>
              <CorpoReq rotulo={t("beasts_onda_nivel")} tem={fmtFull(v.level)} precisa={fmtFull(evo.level_needed)} ok={nivelOk} />
              <CorpoReq rotulo={t("beasts_onda_nucleos")} tem={fmtFull(nucleos)} precisa={fmtFull(evo.cores_needed)} ok={nucleosOk} />
              {!confEvo ? (
                <div style={{ marginTop: 8 }}>
                  <OndaBtn kind="ghost" disabled={!podeEvoluir} onClick={() => { haptic("warning"); setConfEvo(true); }}>
                    {t("beasts_onda_evoluir_a", { posto: postoDaBesta(evo.next_rank) })}
                  </OndaBtn>
                </div>
              ) : (
                <div role="group" aria-label={t("beasts_onda_evoluir_a", { posto: postoDaBesta(evo.next_rank) })}
                     style={{ marginTop: 8, paddingLeft: 12, borderLeft: "1px solid " + P.gold }}>
                  <div style={{ fontSize: 13, lineHeight: (20 / 13), color: P.paper }}>
                    {t("beasts_onda_confirmar_evo", { n: fmtFull(evo.cores_needed), posto: postoDaBesta(evo.next_rank) })}
                  </div>
                  <div style={{ display: "flex", gap: 8, marginTop: 10 }}>
                    <OndaBtn disabled={!podeEvoluir || !!busy} onClick={() => agir("evo")}>
                      {busy === "evo" ? t("beasts_onda_a_evoluir") : t("beasts_onda_confirmar")}
                    </OndaBtn>
                    <OndaBtn kind="ghost" disabled={!!busy} onClick={() => setConfEvo(false)}>
                      {t("beasts_onda_cancelar")}
                    </OndaBtn>
                  </div>
                </div>
              )}
            </div>
          )}
        </div>
      ) : null;

      // O NÍVEL: o traço (o XP) entre a marca do nível que a besta TEM e a do
      // próximo. No tecto não há fio — "Limite atual", e o XP que sobra no 100
      // não se mostra como progresso (162 bestas no `main`).
      const xp = Number(v.exp) || 0;
      const precisa = Number(v.exp_needed) || 0;
      const nivel = (
        <div style={{ padding: "12px 0 0", marginTop: 12, borderTop: "1px solid " + P.line }}>
          <div style={{ display: "flex", alignItems: "baseline", columnGap: 12 }}>
            <span style={rotulo}>{t("beasts_onda_nivel")}</span>
            <span style={numero}>{t("beasts_onda_nivel_de", { level: fmtFull(v.level), max: fmtFull(v.max_level) })}</span>
          </div>
          <div aria-hidden="true" data-besta-nivel=""
               style={{ position: "relative", height: 22, marginTop: 8 }}>
            <span style={{ position: "absolute", left: 11, top: 11, width: 0, height: 0 }}>
              <MarcaOnda estado="got" acende={eixos.indexOf("nivel") >= 0} />
            </span>
            {!noTecto && precisa > 0 && (
              <>
                <span style={{ position: "absolute", left: 22, right: 22, top: 10, height: 2, background: P.line }} />
                <span data-besta-fio=""
                      style={{ position: "absolute", left: 22, top: 10, height: 2, background: P.gold,
                               width: "calc((100% - 44px) * " + Math.min(1, Math.max(0, xp / precisa)) + ")" }} />
                <span style={{ position: "absolute", right: 11, top: 11, width: 0, height: 0 }}>
                  <MarcaOnda estado="next" />
                </span>
              </>
            )}
          </div>
          <div style={Object.assign({}, _ONDA_TNUM, { marginTop: 6, fontSize: 12.5, lineHeight: (18 / 12.5),
                                                      color: P.muted })}>
            {noTecto ? t("beasts_onda_limite")
                     : t("beasts_onda_xp", { exp: fmtFull(xp), need: fmtFull(precisa),
                                             n: fmtFull(Math.max(0, precisa - xp)) })}
          </div>
        </div>
      );

      const selo = (
        <div data-besta-selo="" style={{ marginTop: 18 }}>
          {posto}
          {nivel}
        </div>
      );

      // As ACÇÕES — os mesmos portões do motor, escritos ao lado do botão.
      const acoes = (
        <div style={{ marginTop: 18 }}>
          {naExp ? (
            voltou ? (
              <OndaBtn disabled={!fresco || !!busy} onClick={() => agir("col")}>
                {busy === "col" ? t("beasts_onda_a_recolher") : t("beasts_onda_recolher")}
              </OndaBtn>
            ) : (
              <div style={{ fontSize: 13, lineHeight: (20 / 13), color: P.muted }}>{t("beasts_onda_bloq_exp")}</div>
            )
          ) : noTecto ? null : (
            <>
              <OndaBtn disabled={!podeTreinar} onClick={() => agir("t1")}>
                {busy === "t1" ? t("beasts_onda_a_treinar")
                               : t("beasts_onda_treinar", { cost: fmtFull(v.train_cost || 0) })}
              </OndaBtn>
              <div style={{ marginTop: 8 }}>
                <OndaBtn kind="ghost" disabled={!podeTreinar} onClick={() => agir("t10")}>
                  {busy === "t10" ? t("beasts_onda_a_treinar") : t("beasts_onda_treinar10")}
                </OndaBtn>
              </div>
              {faltaPedras > 0 && (
                <div style={Object.assign({}, _ONDA_TNUM, { marginTop: 6, fontSize: 12, lineHeight: (18 / 12),
                                                            textAlign: "center", color: P.seal })}>
                  {t("beasts_onda_faltam_pedras", { n: fmtFull(faltaPedras) })}
                </div>
              )}
            </>
          )}
          {!naExp && (!v.is_companion) && (
            <div style={{ display: "flex", gap: 8, marginTop: 8, flexWrap: "wrap" }}>
              <OndaBtn kind="ghost" disabled={!fresco || !!busy} onClick={() => agir("comp")}
                       style={{ flex: "1 1 160px", width: "auto" }}>
                {busy === "comp" ? t("beasts_onda_a_equipar") : t("beasts_onda_tornar_comp")}
              </OndaBtn>
              <OndaBtn kind="ghost" disabled={!fresco || !!busy} onClick={() => { haptic("light"); setExpBeast(b); }}
                       style={{ flex: "1 1 160px", width: "auto" }}>
                {t("beasts_onda_enviar_exp")}
              </OndaBtn>
            </div>
          )}
          {!fresco && (
            <div role="status" style={{ marginTop: 8, fontSize: 12, lineHeight: (18 / 12), color: P.muted }}>
              {falhou ? (
                <button type="button" onClick={() => onChanged && onChanged()}
                        style={{ background: "transparent", border: 0, padding: "10px 0", color: P.muted,
                                 fontFamily: P.body, fontSize: 12, textDecoration: "underline",
                                 textUnderlineOffset: 4, cursor: "pointer", boxShadow: "none" }}>
                  {t("beasts_onda_reler")}
                </button>
              ) : t("beasts_onda_a_atualizar")}
            </div>
          )}
        </div>
      );

      const avisos = (
        <>
          {meuErro && (
            <div role="alert" style={{ display: "flex", gap: 8, alignItems: "flex-start", padding: "12px 0 0",
                                       fontFamily: P.body, fontSize: 13, lineHeight: 1.6, color: P.seal }}>
              <span aria-hidden="true" style={{ display: "inline-flex", marginTop: 2 }}><Mark name="warn" size={14} /></span>
              <span>{meuErro.texto}</span>
            </div>
          )}
          {meuRecibo && meuRecibo.linhas.length > 0 && (
            <div aria-live="polite" data-besta-recibo=""
                 style={{ marginTop: 18, paddingLeft: 14, borderLeft: "1px solid " + P.gold }}>
              <div style={{ fontFamily: P.label, fontSize: 10, letterSpacing: ".22em", textTransform: "uppercase",
                            color: P.gold, marginBottom: 6 }}>{t("beasts_onda_confirmado")}</div>
              {meuRecibo.linhas.map((ln, i) => (
                <div key={i} style={Object.assign({}, _ONDA_TNUM, { fontSize: 14, lineHeight: (22 / 14),
                                                                   color: P.paper })}>{ln}</div>
              ))}
            </div>
          )}
        </>
      );

      // A FUNÇÃO: o que a besta dá como companheira (os bónus EFECTIVOS — o
      // posto e o nível já contados) e a habilidade da espécie. Nunca acende.
      const bonus = v.effective_stats || {};
      const funcao = (Object.keys(bonus).length > 0 || b.special_ability) ? (
        <div style={{ marginTop: 22, paddingTop: 12, borderTop: "1px solid " + P.line }}>
          <div style={rotulo}>{t("beasts_onda_funcao")}</div>
          {Object.keys(bonus).map(k => (
            <div key={k} style={{ display: "flex", alignItems: "baseline", columnGap: 12, padding: "6px 0",
                                  fontFamily: P.body, fontSize: 13, lineHeight: (20 / 13) }}>
              <span style={{ color: P.muted }}>{bonusDaBesta(k)}</span>
              <span style={Object.assign({}, _ONDA_TNUM, { marginLeft: "auto", color: P.paper })}>
                {"+" + _pctBesta(bonus[k]) + "%"}
              </span>
            </div>
          ))}
          {b.special_ability ? (
            <p style={{ margin: "8px 0 0", fontFamily: P.body, fontSize: 13, lineHeight: 1.6, color: P.muted }}>
              {b.special_ability}
            </p>
          ) : null}
        </div>
      ) : null;

      const lista = owned.length > 1 ? (
        <div style={{ marginTop: 28 }}>
          <div style={Object.assign({}, rotulo, { color: P.gold, display: "flex", alignItems: "baseline" })}>
            <span>{t("beasts_onda_tuas")}</span>
            <span style={Object.assign({}, _ONDA_TNUM, { marginLeft: 8, fontSize: 12, letterSpacing: 0,
                                                        color: P.muted })}>{fmtFull(owned.length)}</span>
          </div>
          <ul style={{ listStyle: "none", margin: "10px 0 0", padding: 0, borderBottom: "1px solid " + P.line }}>
            {owned.map(x => (
              <BestaLinha key={x.id} b={x} sel={x.id === b.id} onSel={() => escolher(x)} />
            ))}
          </ul>
        </div>
      ) : null;

      const leitura = (
        <div style={{ minWidth: 0 }}>
          {cabeca}
          {/* o recibo e o erro ENTRE o selo e as acções: a evolução confirma-se
              no bloco do posto e o treino logo abaixo — os dois ficam junto da
              consequência (Astra §1: "junto da operação"), e é este bloco que
              volta à vista quando acende */}
          <div ref={seloRef} style={{ scrollMarginTop: 8, scrollMarginBottom: 96 }}>
            {selo}
            {avisos}
          </div>
          {acoes}
          {funcao}
          {lista}
        </div>
      );

      const modal = expBeast ? (
        <BeastExpeditionModal beast={expBeast} onClose={() => setExpBeast(null)} onSent={onChanged} />
      ) : null;

      if (wide) {
        return (
          <section data-bestas-onda="" ref={corpoRef}
                   style={{ maxWidth: 1080, margin: "4px auto 0", padding: "0 0 96px", fontFamily: P.body }}>
            {/* ⚠️ a pintura das bestas é 4:3 (1200x896) — um retrato 4:5 cortava a
                cabeça da tartaruga a 1440 (olhado a 01/10) */}
            <div style={{ display: "grid", gridTemplateColumns: "minmax(300px, 440px) minmax(0, 1fr)",
                          columnGap: 48, alignItems: "start" }}>
              <div style={{ position: "sticky", top: 16 }}>{arte}</div>
              {leitura}
            </div>
            {modal}
          </section>
        );
      }
      return (
        <section data-bestas-onda="" ref={corpoRef}
                 style={{ padding: "4px 2px 96px", scrollMarginTop: 8, fontFamily: P.body }}>
          {arte}
          <div style={{ marginTop: 14 }}>{leitura}</div>
          {modal}
        </section>
      );
    }

    function BeastsCapturePanel({ data, onChanged }) {
      const [busyId, setBusyId] = useState(null);
      const [outcome, setOutcome] = useState(null); // {captured, ...}
      const catalog = data.catalog || [];
      const trapTotal = data.traps?.total || 0;
      const lure = data.lure?.active;
      const ranksOrder = data.ranks || ["Common", "Uncommon", "Rare", "Epic", "Legendary", "Mythic", "Divine"];
      const sorted = [...catalog].sort(
        (a, b) => (a.rank_idx ?? 0) - (b.rank_idx ?? 0)
      );
      return (
        <div>
          <Card style={{ marginBottom:10, padding:"10px 12px" }}>
            <div style={{ fontFamily:"'Cinzel',serif", fontSize:11,
                          color:"var(--gold2)", letterSpacing:.4,
                          textTransform:"uppercase" }}>
              {t("beasts_capture_traps_title")}
            </div>
            <div style={{ marginTop:6, fontSize:11, color:"var(--text)" }}>
              {trapTotal > 0
                ? t("beasts_capture_traps_have", { total: trapTotal })
                : <span style={{ color:"var(--warn)" }}>{t("beasts_capture_traps_none")}</span>}
              {lure && (
                <span style={{ marginLeft:8, color:"var(--jade)" }}>
                  · ✨ {t("beasts_capture_lure_active")}
                </span>
              )}
            </div>
            {Object.keys(data.traps?.breakdown || {}).length > 0 && (
              <div style={{ marginTop:6, fontSize:10, color:"var(--muted)" }}>
                {Object.entries(data.traps.breakdown).map(([q, n]) => (
                  <span key={q} style={{ marginRight:8 }}>
                    {(_TRAP_QUALITY_LABEL[q] || q)}: <strong>{n}</strong>
                  </span>
                ))}
              </div>
            )}
          </Card>

          {/* 牌 §2.0(b) — o defeito (b) que o OWNER fotografou.
              Esta é a MONTRA: o catálogo de onde se captura, ou seja a lista do
              que o jogador ainda NÃO tem. A lista de posse já era cartas; a de
              DESEJO era uma lista densa com um emoji por linha — exactamente ao
              contrário de onde a arte vende.
              ⚠️ O estado é `unowned` sempre que a besta ainda não foi capturada
              (dessaturada, sem selo — a carta já sabia desenhá-lo e nunca tinha
              tido conteúdo). Uma capturada aparece como `owned`: catálogo é
              catálogo, e mentir sobre a posse seria pior do que a lista velha. */}
          {(() => {
            const cardsOn = typeof featureEnabled === "function" && featureEnabled("cartas");
            const ownedCatIds = new Set((data.owned || []).map(b => b.catalog_id));
            const attempt = async (c) => {
              setBusyId(c.id);
              try {
                const res = await api("beasts/capture_attempt", { catalog_id: c.id });
                setOutcome({ ...res, target: c });
                if (res.captured) {
                  haptic("success");
                  onChanged();
                } else if (res.reason === "missed") {
                  haptic("warning");
                  onChanged();
                } else if (res.reason) {
                  haptic("error");
                }
              } catch (e) {
                haptic("error");
                showToast(e.message, "err");
              } finally {
                setBusyId(null);
              }
            };
            const captureBtn = (c) => (
              <ActionBtn variant="primary" size="sm"
                         disabled={trapTotal <= 0 || busyId !== null}
                         busy={busyId === c.id}
                         onClick={() => attempt(c)}>
                🪤 {t("beasts_btn_capture")}
              </ActionBtn>
            );
            const rows = sorted.map(c => {
              if (!cardsOn) {
                return (
                  <Card key={c.id} style={{ marginBottom:9, padding:"10px 12px" }}>
                    <div style={{ display:"flex", alignItems:"center", gap:10 }}>
                      <div style={{ fontSize:30, lineHeight:1,
                                    filter:`drop-shadow(0 0 6px ${cssHex(_BEAST_RANK_COLOR[c.rank] || "var(--realm-0)")}99)` }}>
                        {c.emoji}
                      </div>
                      <div style={{ flex:1, minWidth:0 }}>
                        <div style={{ fontFamily:"'Cinzel',serif", fontWeight:700, fontSize:13,
                                      color:"var(--text)" }}>{c.name}</div>
                        <div style={{ fontSize:10.5, color:"var(--muted)", marginTop:2 }}>
                          <span style={{ color: _BEAST_RANK_COLOR[c.rank] || "var(--muted)" }}>{postoDaBesta(c.rank)}</span>
                          <span> · {elementoDaBesta(c.element)}</span>
                          <span> · 🪤 {(c.capture_chance_preview * 100).toFixed(1)}%</span>
                        </div>
                      </div>
                      {captureBtn(c)}
                    </div>
                    <div style={{ marginTop:6, fontSize:10, color:"var(--muted2)",
                                  fontStyle:"italic", lineHeight:1.4 }}>
                      {c.description}
                    </div>
                  </Card>
                );
              }
              const has = ownedCatIds.has(c.id);
              // ⚠️ A ÊNFASE INVERTE-SE AQUI, e só se viu ao olhar para a tela.
              // A 1ª versão pôs `unowned` (dessaturado) em tudo o que ainda não
              // se tem — ou seja, em 90% de uma MONTRA. Ficou uma parede cinzenta
              // onde a arte devia vender, e o cinzento dizia "indisponível" a
              // bestas que se podem tentar capturar AGORA MESMO: uma mentira
              // desenhada, do mesmo tipo que o lombo a mentir sobre o grau.
              // Nesta tela o que já se tem é o que se pode PARAR de olhar. Por
              // isso o apagado é a POSSE, e o realce é a caçada.
              const emphasis = has ? "unowned" : "owned";
              return (
                <NivraelCard key={c.id}
                  kind="beast" rank={c.rank}
                  glyph={c.emoji}
                  art={pieceArt("beast", c.name, c.art_key)}
                  name={c.name}
                  accent={_BEAST_RANK_COLOR[c.rank] || "var(--realm-0)"}
                  state={emphasis}
                  stateLabel={has ? t("beasts_capture_state_owned") : null}
                  effect={c.description}
                  foot={(
                    <>
                      <span>{elementoDaBesta(c.element)}</span>
                      <span style={{ color: trapTotal > 0 ? "var(--gold2)" : "var(--muted2)" }}>
                        🪤 {(c.capture_chance_preview * 100).toFixed(1)}%
                      </span>
                    </>
                  )}
                  /* ⚠️ Lei §1 — o PORQUÊ de o botão estar morto. Sem
                     armadilhas, um botão cinzento sozinho é um beco. */
                  note={trapTotal <= 0 ? t("beasts_capture_traps_none") : null}
                  actions={captureBtn(c)}
                />
              );
            });
            return cardsOn ? <CardGrid min={168}>{rows}</CardGrid> : <>{rows}</>;
          })()}
          {outcome && <BeastCaptureOutcomeModal result={outcome} onClose={() => setOutcome(null)} />}
        </div>
      );
    }

    function BeastsCompanionPanel({ data, onChanged }) {
      const [busy, setBusy] = useState(false);
      const owned = data.owned || [];
      const companion = owned.find(b => b.is_companion);
      if (!owned.length) {
        return (
          <Card>
            <div style={{ textAlign:"center", padding:"24px 12px" }}>
              <div style={{ fontSize:36 }}>🐾</div>
              <div style={{ marginTop:10, fontSize:12, color:"var(--muted)" }}>
                {t("beasts_empty_owned")}
              </div>
            </div>
          </Card>
        );
      }
      return (
        <div>
          <Card style={{ marginBottom:10, padding:"10px 12px" }}>
            <div style={{ fontFamily:"'Cinzel',serif", fontSize:11,
                          color:"var(--gold2)", letterSpacing:.4,
                          textTransform:"uppercase" }}>
              {t("beasts_companion_active_title")}
            </div>
            {companion ? (
              <div style={{ display:"flex", alignItems:"center", gap:10, marginTop:8 }}>
                <div style={{ fontSize:34, lineHeight:1,
                              filter:`drop-shadow(0 0 8px ${cssHex(_BEAST_RANK_COLOR[companion.rank] || "var(--realm-0)")}cc)` }}>
                  {companion.emoji}
                </div>
                <div style={{ flex:1, minWidth:0 }}>
                  <div style={{ fontFamily:"'Cinzel',serif", fontWeight:700, fontSize:13,
                                color:"var(--text)" }}>{companion.name}</div>
                  <div style={{ fontSize:10.5, color:"var(--muted)", marginTop:2 }}>
                    {postoDaBesta(companion.rank)} · {nvDaBesta(companion.level)} · {elementoDaBesta(companion.element)}
                  </div>
                  {companion.special_ability && (
                    <div style={{ fontSize:10, color:"var(--gold3)", marginTop:3,
                                  fontStyle:"italic" }}>
                      ✨ {companion.special_ability}
                    </div>
                  )}
                </div>
                <ActionBtn variant="ghost" size="sm" busy={busy}
                           onClick={async () => {
                             setBusy(true);
                             try {
                               const res = await api("beasts/equip_companion", { beast_id: null });
                               if (res.ok) {
                                 haptic("success");
                                 showToast(t("beasts_companion_cleared"));
                                 onChanged();
                               }
                             } finally {
                               setBusy(false);
                             }
                           }}>
                  {t("beasts_btn_unset_companion")}
                </ActionBtn>
              </div>
            ) : (
              <div style={{ marginTop:8, fontSize:11, color:"var(--muted)" }}>
                {t("beasts_companion_none")}
              </div>
            )}
          </Card>

          {(() => {
            // 牌 §2.0(b) — a segunda metade da mesma foto: o candidato a
            // companheiro era uma linha com um emoji de 28px. Escolher UM
            // companheiro entre todos é uma decisão de identidade — é a tela
            // que mais merece a ilustração e era a que menos a tinha.
            const cardsOn = typeof featureEnabled === "function" && featureEnabled("cartas");
            const pool = owned.filter(b => !b.is_companion && !b.is_on_expedition);
            const pick = async (b) => {
              setBusy(true);
              try {
                const res = await api("beasts/equip_companion", { beast_id: b.id });
                if (res.ok) {
                  haptic("success");
                  showToast(t("beasts_companion_equipped"));
                  onChanged();
                } else {
                  haptic("error");
                  showToast(t("beasts_companion_failed"), "err");
                }
              } finally {
                setBusy(false);
              }
            };
            if (cardsOn) {
              return (
                <CardGrid min={168}>
                  {pool.map(b => (
                    <NivraelCard key={b.id}
                      kind="beast" rank={b.rank}
                      glyph={b.emoji}
                      art={pieceArt("beast", b.name, b.art_key)}
                      name={b.name}
                      accent={_BEAST_RANK_COLOR[b.rank] || "var(--realm-0)"}
                      state="owned"
                      effect={nvDaBesta(b.level, b.max_level)}
                      foot={b.element ? <span>{elementoDaBesta(b.element)}</span> : null}
                      actions={(
                        <ActionBtn variant="primary" size="sm" busy={busy}
                                   style={{ width:"100%" }}
                                   onClick={() => pick(b)}>
                          {t("beasts_btn_set_companion")}
                        </ActionBtn>
                      )} />
                  ))}
                </CardGrid>
              );
            }
            return <>{pool.map(b => (
            <Card key={b.id} style={{ marginBottom:9, padding:"10px 12px" }}>
              <div style={{ display:"flex", alignItems:"center", gap:10 }}>
                {itemVivoOn()
                  ? <PieceIcon kind="beast" name={b.name} artKey={b.art_key} emoji={b.emoji} size={40}
                               accent="var(--gold2)" radius={7} />
                  : <div style={{ fontSize:28 }}>{b.emoji}</div>}
                <div style={{ flex:1, minWidth:0 }}>
                  <div style={{ fontFamily:"'Cinzel',serif", fontWeight:700, fontSize:13,
                                color:"var(--text)" }}>{b.name}</div>
                  <div style={{ fontSize:10.5, color:"var(--muted)" }}>
                    {postoDaBesta(b.rank)} · {nvDaBesta(b.level)}
                  </div>
                </div>
                <ActionBtn variant="primary" size="sm" busy={busy}
                           onClick={() => pick(b)}>
                  {t("beasts_btn_set_companion")}
                </ActionBtn>
              </div>
            </Card>
          ))}</>;
          })()}
        </div>
      );
    }

    function BeastDetailModal({ beast, onClose, onSendExpedition, onEvolve, cores, ops }) {
      if (!beast) return null;
      // Bug fix 2026-05-23: use the EVOLVED + LEVELED stats (server now
      // exposes `effective_stats`). The previous `beast.base_stats` was the
      // raw catalog table — evolved Crane Legendary→Divine showed identical
      // +20% Perception. Fallback to base_stats if server hasn't been
      // deployed yet.
      const stats = beast.effective_stats || beast.base_stats || {};
      const accent = _BEAST_RANK_COLOR[beast.rank] || "var(--gold2)";
      // 牌 2026-09-08 — o defeito que o OWNER fotografou. Este modal mostrava um
      // emoji de 54px onde devia estar a ilustração; a arte da besta existia,
      // estava a ser servida, e via-se no cartão POR TRÁS do próprio modal. O
      // modal é o sítio onde a peça tem a página inteira: a arte é MAIOR aqui.
      // ⚠️ O posto era impresso CRU (`{beast.rank}` = "Legendary" a um jogador
      // pt-BR) — a mesma ferida que a lista tinha e que a escala já traduz.
      const cardsOn = typeof featureEnabled === "function" && featureEnabled("cartas");
      const rk = cardsOn ? nivRank("beast", beast.rank) : null;
      return (
        <Modal open={true} onClose={onClose} title={beast.name} accent={accent}>
          {cardsOn ? (
            /* ⚠️ SEM `title` — a barra do modal (que fica fixa ao rolar, com o
               ✕) já diz o nome. Escrevê-lo outra vez 40px abaixo é a mesma
               redundância que a carta passou 05/09 a apagar. O que fica sobre a
               arte é a linha que não existe em mais lado nenhum. */
            <PieceHero src={pieceArt("beast", beast.name, beast.art_key)} glyph={beast.emoji}
                       accent={accent}
                       seal={!!beast.is_companion}
                       sealLabel={t("beasts_companion_badge")}
                       subtitle={[rk ? rk.label : beast.rank,
                                  `Lv.${beast.level}/${beast.max_level}`,
                                  beast.element].filter(Boolean).join(" · ")} />
          ) : (
          <div style={{ display:"flex", alignItems:"center", gap:12 }}>
            <div style={{ fontSize:54, filter:`drop-shadow(0 0 12px ${cssHex(accent)}cc)` }}>
              {beast.emoji}
            </div>
            <div>
              <div style={{ color: accent, fontFamily:"'Cinzel',serif",
                            fontWeight:700, fontSize:14 }}>{beast.rank}</div>
              <div style={{ color:"var(--muted)", fontSize:11 }}>
                Lv.{beast.level}/{beast.max_level} · {beast.element}
              </div>
            </div>
          </div>
          )}
          {beast.special_ability && (
            <div style={{ marginTop:12, padding:"8px 10px",
                          background:"rgba(0,0,0,.35)", borderRadius:6,
                          border:"1px solid var(--border)" }}>
              <div style={{ fontSize:10, color:"var(--gold2)",
                            fontFamily:"'Cinzel',serif", letterSpacing:.4,
                            textTransform:"uppercase", marginBottom:3 }}>
                {t("beasts_detail_ability")}
              </div>
              <div style={{ fontSize:11.5, color:"var(--text)" }}>
                {beast.special_ability}
              </div>
            </div>
          )}
          {/* ⚠️ Lei §1 — um cabeçalho por cima do VAZIO é pior do que nada. Uma
              besta sem stats (ou um payload de servidor antigo) desenhava
              "ESTATÍSTICAS BASE" e depois nada; visto a olho a 2026-09-08. */}
          {Object.keys(stats).length > 0 && (
          <div style={{ marginTop:12 }}>
            <div style={{ fontSize:10, color:"var(--gold2)",
                          fontFamily:"'Cinzel',serif", letterSpacing:.4,
                          textTransform:"uppercase", marginBottom:6 }}>
              {t("beasts_detail_stats")}
            </div>
            <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:6, fontSize:11 }}>
              {Object.entries(stats).map(([k, v]) => (
                <div key={k} style={{ padding:"4px 8px",
                                      background:"rgba(0,0,0,.35)", borderRadius:4,
                                      border:"1px solid var(--border)",
                                      display:"flex", justifyContent:"space-between" }}>
                  <span style={{ color:"var(--muted)", fontSize:10,
                                 fontFamily:"'Cinzel',serif", letterSpacing:.3,
                                 textTransform:"uppercase" }}>
                    {humanizeStat(k.replace("_mult", ""))}
                  </span>
                  <span style={{ color:"var(--jade)", fontWeight:600 }}>
                    +{Math.round(((v || 1) - 1) * 100)}%
                  </span>
                </div>
              ))}
            </div>
          </div>
          )}
          {beast.evolution && !beast.evolution.at_max && (
            <div style={{ marginTop:12, padding:"8px 10px",
                          background:"rgba(var(--gold2-rgb),.06)", borderRadius:6,
                          border:"1px solid rgba(var(--gold2-rgb),.25)" }}>
              <div style={{ fontSize:10, color:"var(--gold2)",
                            fontFamily:"'Cinzel',serif", letterSpacing:.4,
                            textTransform:"uppercase", marginBottom:3 }}>
                {t("beasts_detail_evolve")}
              </div>
              <div style={{ fontSize:11, color:"var(--text)" }}>
                {t("beasts_detail_evolve_hint", {
                  next: beast.evolution.next_rank,
                  level: beast.evolution.level_needed,
                  cores: beast.evolution.cores_needed,
                })}
              </div>
              {/* v14.11 — Evolve CTA dentro do detail modal. Replaced chat-only
                  hint shipped em MA-37 (v14.10). Cores currency check + level
                  gate; engine valida em evolve_beast. */}
              {onEvolve && beast.evolution.level_met && (
                <ActionBtn variant="primary" size="sm"
                           disabled={(cores || 0) < (beast.evolution.cores_needed || 0)}
                           onClick={onEvolve}
                           style={{ width:"100%", marginTop:8 }}>
                  🌟 {t("beasts_detail_evolve_btn", { next: beast.evolution.next_rank })}
                </ActionBtn>
              )}
              {!beast.evolution.level_met && (
                <div style={{ fontSize:9.5, color:"var(--red2)", marginTop:5 }}>
                  {t("beasts_detail_evolve_need_level", { level: beast.evolution.level_needed })}
                </div>
              )}
              {beast.evolution.level_met && (cores || 0) < (beast.evolution.cores_needed || 0) && (
                <div style={{ fontSize:9.5, color:"var(--red2)", marginTop:4 }}>
                  {t("beasts_detail_evolve_need_cores", { n: (beast.evolution.cores_needed - (cores || 0)) })}
                </div>
              )}
            </div>
          )}

          {/* v14.11 — Send expedition CTA inside detail. Mirrors the BeastsListPanel
              inline CTA but available also when player drilled in via Details. */}
          {onSendExpedition && !beast.is_on_expedition && !beast.is_companion && (
            <ActionBtn variant="ghost" size="sm" onClick={onSendExpedition}
                       style={{ width:"100%", marginTop:10 }}>
              🗺️ {t("beasts_detail_send_exp_btn")}
            </ActionBtn>
          )}

          {/* 牌 §2.3 "cartas navegam, modais operam" — as acções que SAÍRAM da
              lista quando `cartas` liga. ⚠️ Lei §1: elas entram AQUI ANTES de
              sair de lá; sem isto, ligar a flag tornaria treinar, equipar e
              recolher INALCANÇÁVEIS. Com a flag OFF nada disto é passado e o
              modal fica byte-idêntico ao de hoje (os `&&` não rendem nada).
              ⚠️ Os gates são os MESMOS da lista, copiados um a um — um botão
              activo aqui e morto lá seria a tela a mentir sobre o que dá. */}
          {ops && (
            <div style={{ marginTop:12, paddingTop:11,
                          borderTop:"1px solid rgba(var(--gold-rgb),.18)" }}>
              <div style={{ fontSize:10, color:"var(--gold2)",
                            fontFamily:"'Cinzel',serif", letterSpacing:.4,
                            textTransform:"uppercase", marginBottom:7 }}>
                {t("beasts_detail_actions")}
              </div>
              <div style={{ display:"flex", gap:6, flexWrap:"wrap" }}>
                <ActionBtn variant="primary" size="sm"
                           disabled={!!ops.busyId || beast.is_on_expedition
                                     || beast.level >= beast.max_level
                                     || (ops.stones || 0) < beast.train_cost}
                           busy={ops.busyId === `level1-${beast.id}`}
                           onClick={() => ops.onTrain(beast, 1)}>
                  💪 {t("beasts_btn_train", { cost: beast.train_cost })}
                </ActionBtn>
                <ActionBtn variant="ghost" size="sm"
                           disabled={!!ops.busyId || beast.is_on_expedition
                                     || beast.level >= beast.max_level
                                     || (ops.stones || 0) < beast.train_cost}
                           busy={ops.busyId === `level10-${beast.id}`}
                           onClick={() => ops.onTrain(beast, 10)}>
                  💪 ×10
                </ActionBtn>
                {!beast.is_companion && !beast.is_on_expedition && (
                  <ActionBtn variant="ghost" size="sm"
                             busy={ops.busyId === `comp-${beast.id}`}
                             onClick={() => ops.onCompanion(beast)}>
                    {t("beasts_btn_set_companion")}
                  </ActionBtn>
                )}
                {beast.is_on_expedition && (() => {
                  const remaining = beast.expedition_returns_at_ms
                                  ? beast.expedition_returns_at_ms - Date.now() : 0;
                  return remaining <= 0 ? (
                    <ActionBtn variant="primary" size="sm"
                               disabled={!!ops.busyId}
                               busy={ops.busyId === `collect-${beast.id}`}
                               onClick={() => ops.onCollect(beast)}
                               style={{
                                 background:"linear-gradient(180deg, rgba(46,196,182,.4), rgba(20,80,70,.6))",
                                 border:"1px solid var(--jade)",
                               }}>
                      🎁 {t("beasts_btn_collect")}
                    </ActionBtn>
                  ) : (
                    <div style={{ fontSize:10.5, color:"var(--muted)", alignSelf:"center" }}>
                      ⏳ {fmtDuration(remaining)}
                    </div>
                  );
                })()}
              </div>
              {/* Lei §1 — quando TUDO está desligado, dizer PORQUÊ. Um punhado
                  de botões cinzentos sem explicação é um beco. */}
              {!beast.is_on_expedition && beast.level < beast.max_level
               && (ops.stones || 0) < beast.train_cost && (
                <div style={{ fontSize:9.5, color:"var(--red2)", marginTop:6 }}>
                  {t("beasts_detail_need_stones", { n: beast.train_cost - (ops.stones || 0) })}
                </div>
              )}
              {beast.level >= beast.max_level && (
                <div style={{ fontSize:9.5, color:"var(--muted2)", marginTop:6 }}>
                  {t("beasts_err_max_level")}
                </div>
              )}
            </div>
          )}
        </Modal>
      );
    }

    function BeastCaptureOutcomeModal({ result, onClose }) {
      if (!result) return null;
      const captured = !!result.captured;
      // R5: hex literal — o drop-shadow concatena alpha (`${cssHex(accent)}cc`).
      const accent = captured ? "var(--jade)" : "var(--red)";
      const target = result.target || {};
      return (
        <Modal open={true} onClose={onClose} accent={accent}
               title={captured ? t("beasts_capture_outcome_caught")
                                : t("beasts_capture_outcome_escaped")}>
          <div style={{ textAlign:"center", padding:"4px 0" }}>
            <div style={{ fontSize:54,
                          filter: captured
                                  ? `drop-shadow(0 0 14px ${cssHex(accent)}cc)`
                                  : "grayscale(.6) opacity(.7)" }}>
              {result.emoji || target.emoji || "🐾"}
            </div>
            <div style={{ marginTop:8, fontFamily:"'Cinzel',serif",
                          fontWeight:700, fontSize:14, color:"var(--text)" }}>
              {result.beast_name || target.name}
            </div>
            <div style={{ marginTop:4, fontSize:11, color:"var(--muted)" }}>
              {postoDaBesta(result.rank || target.rank)}
            </div>
            <div style={{ marginTop:10, fontSize:11, color:"var(--muted)" }}>
              {captured
                ? t("beasts_capture_outcome_caught_msg", { rank: postoDaBesta(result.rank || target.rank) })
                : t("beasts_capture_outcome_escaped_msg", { chance: ((result.chance || 0) * 100).toFixed(1) })}
            </div>
            {result.trap_quality && result.trap_quality !== "normal" && (
              <div style={{ marginTop:6, fontSize:10, color:"var(--gold3)" }}>
                🪤 {t("beasts_capture_used_trap", { quality: _TRAP_QUALITY_LABEL[result.trap_quality] || result.trap_quality })}
              </div>
            )}
            {result.achievements_unlocked?.length > 0 && (
              <div style={{ marginTop:10, padding:"6px 10px",
                            background:"rgba(var(--gold2-rgb),.08)", borderRadius:6,
                            border:"1px solid var(--gold2)" }}>
                <div style={{ fontSize:10, color:"var(--gold2)",
                              fontFamily:"'Cinzel',serif", letterSpacing:.4,
                              textTransform:"uppercase" }}>
                  🏆 {t("beasts_capture_unlocked")}
                </div>
                {result.achievements_unlocked.map(a => (
                  <div key={a.id} style={{ fontSize:11, color:"var(--text)", marginTop:3 }}>
                    {a.emoji} {a.name}
                  </div>
                ))}
              </div>
            )}
          </div>
        </Modal>
      );
    }

    function _translateBeastReason(reason, params) {
      if (!reason) return t("beasts_train_failed");
      const map = {
        err_beast_not_found: "beasts_err_not_found",
        err_beast_max_level: "beasts_err_max_level",
        err_beast_on_expedition: "beasts_err_on_expedition",
        err_beast_stones_needed: "beasts_err_stones_needed",
        err_beast_max_rank: "beasts_err_max_rank",
        err_beast_level_needed: "beasts_err_level_needed",
        err_beast_cores_needed: "beasts_err_cores_needed",
        err_beast_trap_needed: "beasts_err_trap_needed",
        err_beast_not_in_catalog: "beasts_err_not_in_catalog",
        // 獸 3.3 — a recolha da expedição recusava com "Treino falhou"
        err_expedition_not_ready: "beasts_err_exp_not_ready",
        err_beast_not_on_expedition: "beasts_err_not_on_exp",
      };
      const key = map[reason] || "beasts_train_failed";
      return t(key, params || {});
    }

    // ─── Sprint v14.10 — MA-38 Faction ───────────────────────────────────────
    // Pick wizard if not in a faction (2-card grid: Celestial / Demonic with
    // bonuses + lore). Dashboard otherwise: rank progress, bonuses showcase,
    // active quests with claim CTA, available quests with cooldown chip.

    var _FACTION_RANK_EMOJI = ["🔰", "⭐", "🌟", "💎", "👑"];

    // v16.2.1 (Path Trinity pivot) — Legacy soft-disable banner shown at the
    // top of every FactionTab view. The faction system is being absorbed by
    // Path + Sect Recruitment (v16.4). All existing reputation / ranks /
    // quests / shop progress is preserved; the system stays functional for
    // current players but new pickers are surfaced with this honest
    // disclosure so no new player commits to a system about to migrate.
    function _FactionLegacyBanner() {
      return (
        <Card style={{
          marginBottom:10, padding:"10px 12px",
          background:"rgba(160,170,200,.08)",
          borderColor:"rgba(160,170,200,.32)",
        }}>
          <div style={{ fontSize:10.5, color:"rgba(220,225,240,.92)",
                         lineHeight:1.5, fontStyle:"italic" }}>
            {safeT("faction_legacy_banner")}
          </div>
        </Card>
      );
    }

    function FactionTab({ player, onPlayerRefresh }) {
      const [reload, setReload] = useState(0);
      const { data, loading, error } = useApi("faction/info", null, [reload]);
      const refreshAll = () => {
        setReload(x => x + 1);
        if (onPlayerRefresh) onPlayerRefresh();
      };

      if (loading && !data) return <ListSkeleton rows={5} />;
      if (error) return <ErrBanner msg={error} />;
      if (!data) return null;

      if (data.locked) {
        return (
          <>
            <_FactionLegacyBanner />
            <Card>
              <div style={{ textAlign:"center", padding:"28px 16px" }}>
                <div style={{ fontSize:42 }}>🔱</div>
                <div style={{ marginTop:10, fontFamily:"'Cinzel',serif",
                              fontWeight:700, fontSize:14, color:"var(--gold2)" }}>
                  {t("faction_locked_title")}
                </div>
                <div style={{ marginTop:8, fontSize:11.5, color:"var(--muted)",
                              lineHeight:1.5 }}>
                  {t("faction_locked_msg", { realm: data.min_realm })}
                </div>
              </div>
            </Card>
          </>
        );
      }

      if (!data.membership) {
        return (
          <>
            <_FactionLegacyBanner />
            <FactionPickPanel data={data} onChanged={refreshAll} />
          </>
        );
      }
      return (
        <>
          <_FactionLegacyBanner />
          <FactionDashboardPanel data={data} onChanged={refreshAll} />
        </>
      );
    }

    function FactionPickPanel({ data, onChanged }) {
      const [busy, setBusy] = useState(null);
      const factions = data.factions || [];
      return (
        <div>
          <Card style={{ marginBottom:10, padding:"12px 13px" }}>
            <div style={{ display:"flex", alignItems:"center", gap:10 }}>
              <div style={{ fontSize:30, filter:"drop-shadow(0 0 8px rgba(var(--gold2-rgb),.45))" }}>🔱</div>
              <div style={{ flex:1 }}>
                <div style={{ fontFamily:"'Cinzel',serif", fontWeight:700, fontSize:14,
                              color:"var(--gold2)", letterSpacing:.4 }}>
                  {t("faction_pick_title")}
                </div>
                <div style={{ fontSize:11, color:"var(--muted)", lineHeight:1.4 }}>
                  {t("faction_pick_subtitle")}
                </div>
              </div>
            </div>
            <div style={{ marginTop:10, fontSize:11, color:"var(--warn)",
                          fontStyle:"italic" }}>
              ⚠️ {t("faction_pick_irreversible")}
            </div>
          </Card>

          {factions.map(f => (
            <Card key={f.id} style={{ marginBottom:10, padding:"12px 13px" }}>
              <div style={{ display:"flex", alignItems:"center", gap:10 }}>
                <div style={{ fontSize:34, lineHeight:1,
                              filter:"drop-shadow(0 0 8px rgba(var(--realm-3-rgb),.5))" }}>
                  {f.emoji}
                </div>
                <div style={{ flex:1, minWidth:0 }}>
                  <div style={{ fontFamily:"'Cinzel',serif", fontWeight:700, fontSize:14,
                                color:"var(--gold2)" }}>{f.name}</div>
                  <div style={{ fontSize:11, color:"var(--muted)", lineHeight:1.4,
                                marginTop:2, fontStyle:"italic" }}>{f.description}</div>
                </div>
              </div>
              {Object.keys(f.bonuses || {}).length > 0 && (
                <div style={{ marginTop:10 }}>
                  <div style={{ fontSize:10, color:"var(--gold2)",
                                fontFamily:"'Cinzel',serif", letterSpacing:.4,
                                textTransform:"uppercase", marginBottom:5 }}>
                    {t("faction_bonuses_label")}
                  </div>
                  {Object.entries(f.bonuses).map(([k, v]) => (
                    <div key={k} style={{ fontSize:11, color:"var(--jade)", lineHeight:1.5 }}>
                      +{Math.round((v || 0) * 100)}% {humanizeStat(k)}
                    </div>
                  ))}
                </div>
              )}
              <div style={{ marginTop:10 }}>
                <ActionBtn variant="primary" size="md"
                           busy={busy === f.id}
                           disabled={busy !== null}
                           onClick={async () => {
                             setBusy(f.id);
                             try {
                               const res = await api("faction/pick", { faction_id: f.id });
                               if (res.ok) {
                                 haptic("success");
                                 showToast(t("faction_joined", { name: res.faction_name }));
                                 onChanged();
                               } else if (res.reason === "already_in_faction") {
                                 haptic("warning");
                                 showToast(t("faction_err_already_in"), "err");
                                 onChanged();
                               } else if (res.reason === "realm_too_low") {
                                 haptic("error");
                                 showToast(t("faction_locked_msg", { realm: res.min_realm }), "err");
                               } else {
                                 haptic("error");
                                 showToast(res.reason || "error", "err");
                               }
                             } finally {
                               setBusy(null);
                             }
                           }}>
                  {f.emoji} {t("faction_btn_join", { name: f.name })}
                </ActionBtn>
              </div>
            </Card>
          ))}
        </div>
      );
    }

    // v14.11 MA-38b — Accept CTA for faction quests. Mirror chat
    // /faccao aceitar via /api/miniapp/faction/quest_accept.
    function FactionAvailableQuestCard({ q, onAccepted }) {
      const [busy, setBusy] = useState(false);
      const [err, setErr] = useState(null);

      async function callAccept() {
        if (busy) return;
        setBusy(true); setErr(null);
        haptic("warning");
        try {
          const res = await api("faction/quest_accept", { faction_quest_id: q.id });
          if (!res.ok) {
            haptic("error");
            const reasonKey = res.reason === "already_active_or_cooldown"
              ? "faction_accept_already_active"
              : "faction_accept_failed";
            setErr(t(reasonKey));
            setBusy(false);
            return;
          }
          haptic("success");
          showToast(t("faction_accept_done", { name: q.name }));
          setBusy(false);
          onAccepted && onAccepted();
        } catch (e) {
          haptic("error");
          setErr(e.message || t("faction_accept_failed"));
          setBusy(false);
        }
      }

      return (
        <Card style={{ marginBottom:9, padding:"10px 12px" }}>
          <div style={{ display:"flex", alignItems:"center", gap:8 }}>
            <div style={{ fontSize:22 }}>{q.emoji}</div>
            <div style={{ flex:1, minWidth:0 }}>
              <div style={{ fontFamily:"'Cinzel',serif", fontWeight:700,
                            fontSize:12.5, color:"var(--text)" }}>{q.name}</div>
              <div style={{ fontSize:10.5, color:"var(--muted)", marginTop:2 }}>
                ⭐ +{q.reward_rep} · 🎯 ×{q.target_count} · 🔄 {q.cooldown_hours}h
              </div>
            </div>
          </div>
          <div style={{ marginTop:6, fontSize:10.5, color:"var(--muted2)",
                        fontStyle:"italic", lineHeight:1.4 }}>
            {q.description}
          </div>
          {err && <ErrBanner msg={err} />}
          <ActionBtn variant="primary" size="sm" disabled={busy}
                     onClick={callAccept} style={{ width:"100%", marginTop:6 }}>
            {busy ? <DotSpinner /> : `📜 ${t("faction_accept_btn")}`}
          </ActionBtn>
        </Card>
      );
    }

    function FactionDashboardPanel({ data, onChanged }) {
      const m = data.membership;
      // v14.12b MA-38c — owner pediu "loja da faction nao vi". Tab seg
      // ganha 4ª opção `shop` (já tem active/available/bonuses).
      const [seg, setSeg] = useState("active"); // active|available|bonuses|shop
      const [busy, setBusy] = useState(null);
      const [shopBusyId, setShopBusyId] = useState(null);
      const cur_rep_pct = m.next_rank
        ? Math.min(100, ((m.total_rep_earned - (data.ranks[m.rank_idx]?.threshold || 0))
                          / Math.max(1, (m.next_rank.threshold - (data.ranks[m.rank_idx]?.threshold || 0)))) * 100)
        : 100;

      const opts = [
        { value:"active",    label:`📋 ${t("faction_seg_active")}` + (m.claimable_count > 0 ? ` ✦${m.claimable_count}` : "") },
        { value:"available", label:`🎯 ${t("faction_seg_available")}` },
        { value:"bonuses",   label:`🔮 ${t("faction_seg_bonuses")}` },
        // v14.12b MA-38c — drill-in para shop da faction (rep-priced items)
        { value:"shop",      label:`🛒 ${t("faction_seg_shop")}` },
      ];

      async function claim(pfqId) {
        setBusy(pfqId);
        try {
          const res = await api("faction/quest_claim", { pfq_id: pfqId });
          if (res.ok) {
            haptic("success");
            const parts = [];
            if (res.rewards?.reputation) parts.push(`⭐ +${res.rewards.reputation}`);
            if (res.rewards?.spirit_stones) parts.push(`🪨 +${fmtNum(res.rewards.spirit_stones)}`);
            if (res.rewards?.spirit_jade) parts.push(`💎 +${res.rewards.spirit_jade}`);
            showToast(t("faction_claim_done", { rewards: parts.join(", ") || "—" }));
            onChanged();
          } else {
            haptic("error");
            showToast(t("faction_claim_failed"), "err");
          }
        } finally {
          setBusy(null);
        }
      }

      return (
        <div>
          <Card style={{ padding:"12px 13px", marginBottom:10 }}>
            <div style={{ display:"flex", alignItems:"center", gap:10 }}>
              <div style={{ fontSize:34, filter:"drop-shadow(0 0 8px rgba(var(--realm-3-rgb),.5))" }}>
                {m.faction_emoji}
              </div>
              <div style={{ flex:1, minWidth:0 }}>
                <div style={{ fontFamily:"'Cinzel',serif", fontWeight:700, fontSize:14,
                              color:"var(--gold2)" }}>{m.faction_name}</div>
                <div style={{ fontSize:11, color:"var(--muted)" }}>
                  {_FACTION_RANK_EMOJI[m.rank_idx] || "🔰"} {m.rank}
                </div>
              </div>
            </div>
            {/* Reputation bar */}
            <div style={{ marginTop:10 }}>
              <div style={{ display:"flex", justifyContent:"space-between", marginBottom:3,
                            fontSize:10, color:"var(--muted)" }}>
                <span style={{ fontFamily:"'Cinzel',serif", letterSpacing:.4, textTransform:"uppercase" }}>
                  ⭐ {t("faction_rep_total")}: {fmtNum(m.total_rep_earned)}
                </span>
                {m.next_rank && (
                  <span>
                    {t("faction_to_next", { name: m.next_rank.name, rep: fmtNum(m.next_rank.remaining) })}
                  </span>
                )}
              </div>
              <div style={{ height:6, borderRadius:3, background:"rgba(0,0,0,.55)", overflow:"hidden" }}>
                <div style={{ width:`${cur_rep_pct}%`, height:"100%",
                              background:"linear-gradient(90deg,var(--realm-3),var(--realm-2),var(--gold2))",
                              transition:"width .4s ease" }} />
              </div>
              <div style={{ marginTop:6, fontSize:10, color:"var(--jade)" }}>
                💰 {t("faction_rep_spendable")}: {fmtNum(m.reputation)}
              </div>
            </div>
            <div style={{ marginTop:9 }}>
              <SegControl options={opts} value={seg} onChange={setSeg} />
            </div>
          </Card>

          {seg === "active" && (
            <div>
              {m.active_quests.length === 0 ? (
                <Card>
                  <div style={{ textAlign:"center", padding:"24px 12px",
                                fontSize:12, color:"var(--muted)" }}>
                    {t("faction_no_active_quests")}
                  </div>
                </Card>
              ) : m.active_quests.map(q => (
                <Card key={q.id} style={{ marginBottom:9, padding:"10px 12px" }}>
                  <div style={{ display:"flex", alignItems:"center", gap:8 }}>
                    <div style={{ fontSize:22 }}>{q.emoji}</div>
                    <div style={{ flex:1, minWidth:0 }}>
                      <div style={{ fontFamily:"'Cinzel',serif", fontWeight:700,
                                    fontSize:12.5, color:"var(--text)" }}>{q.name}</div>
                      <div style={{ fontSize:10.5, color:"var(--muted)", marginTop:2 }}>
                        ⭐ +{q.reward_rep}
                        {q.reward_items?.spirit_stones && <span> · 🪨 +{fmtNum(q.reward_items.spirit_stones)}</span>}
                      </div>
                    </div>
                    {q.is_completed && !q.claimed && (
                      <ActionBtn variant="primary" size="sm"
                                 busy={busy === q.id}
                                 onClick={() => claim(q.id)}>
                        ✅ {t("faction_btn_claim")}
                      </ActionBtn>
                    )}
                  </div>
                  <div style={{ marginTop:6 }}>
                    <div style={{ display:"flex", justifyContent:"space-between",
                                  fontSize:10, color:"var(--muted)", marginBottom:3 }}>
                      <span>{q.is_completed ? `✅ ${t("faction_quest_completed")}` : t("faction_quest_progress")}</span>
                      <span>{q.progress}/{q.target_count}</span>
                    </div>
                    <div style={{ height:5, borderRadius:3, background:"rgba(0,0,0,.55)", overflow:"hidden" }}>
                      <div style={{
                        width: `${Math.min(100, (q.progress / q.target_count) * 100)}%`,
                        height:"100%",
                        background: q.is_completed
                                    ? "linear-gradient(90deg,var(--jade),var(--gold2))"
                                    : "linear-gradient(90deg,var(--realm-5),var(--realm-3))",
                        transition:"width .4s ease",
                      }} />
                    </div>
                  </div>
                </Card>
              ))}
            </div>
          )}
          {seg === "available" && (
            <div>
              {m.available_quests.length === 0 ? (
                <Card>
                  <div style={{ textAlign:"center", padding:"24px 12px",
                                fontSize:12, color:"var(--muted)" }}>
                    {t("faction_no_available_quests")}
                  </div>
                </Card>
              ) : m.available_quests.map(q => (
                <FactionAvailableQuestCard key={q.id} q={q} onAccepted={onChanged} />
              ))}
            </div>
          )}
          {seg === "bonuses" && (
            <Card style={{ padding:"12px 13px" }}>
              <div style={{ fontFamily:"'Cinzel',serif", fontSize:11,
                            color:"var(--gold2)", letterSpacing:.4,
                            textTransform:"uppercase", marginBottom:8 }}>
                {t("faction_bonuses_active_title")}
              </div>
              {Object.keys(m.bonuses || {}).length === 0 ? (
                <div style={{ fontSize:11, color:"var(--muted)" }}>
                  {t("faction_no_bonuses")}
                </div>
              ) : Object.entries(m.bonuses).map(([k, v]) => (
                <div key={k} style={{ display:"flex", justifyContent:"space-between",
                                       alignItems:"center", padding:"6px 0",
                                       borderBottom:"1px dashed var(--border)" }}>
                  <span style={{ fontSize:11, color:"var(--text)" }}>
                    {humanizeStat(k)}
                  </span>
                  <span style={{ fontSize:12, color:"var(--jade)", fontWeight:600 }}>
                    +{Math.round((v || 0) * 100)}%
                  </span>
                </div>
              ))}
              <div style={{ marginTop:10, fontSize:10.5, color:"var(--muted2)",
                            lineHeight:1.5, fontStyle:"italic" }}>
                {t("faction_bonuses_apply_hint")}
              </div>
            </Card>
          )}
          {seg === "shop" && (
            <FactionShopPanel
              busyId={shopBusyId}
              setBusyId={setShopBusyId}
              onPurchased={onChanged}
            />
          )}
        </div>
      );
    }

    // ─── MA-38c Faction Shop Panel (Sprint v14.12b, owner feedback 2026-05-23) ─
    // Drill-in segment dentro do FactionDashboardPanel. Mirror visual do
    // /faccao loja chat: categories (Techniques / Weapons / Armor / Accessory)
    // + per-item cost rep + min_rank. Reusa engine `faction/buy_shop_item`.
    // Side-effects (rep deduction, technique/recipe/artifact/pill grant)
    // ficam todas no engine; UI só renderiza + dispara.
    var _FAC_SHOP_CAT_DEFS = [
      { key:"technique", icon:"📜", label_key:"faction_shop_cat_techniques" },
      { key:"weapon",    icon:"⚔️", label_key:"faction_shop_cat_weapons" },
      { key:"armor",     icon:"🛡️", label_key:"faction_shop_cat_armor" },
      { key:"accessory", icon:"💍", label_key:"faction_shop_cat_accessories" },
      { key:"pill",      icon:"💊", label_key:"faction_shop_cat_pills" },
      { key:"recipe",    icon:"📜", label_key:"faction_shop_cat_recipes" },
    ];

    function _fac_shop_categorize(item) {
      if (item.item_type === "technique") return "technique";
      if (item.item_type === "pill") return "pill";
      if (item.item_type === "recipe") return "recipe";
      // artifacts → sub-categorize by description (mirror chat _item_category)
      const desc = (item.description || "").toLowerCase();
      if (/weapon|blade|sword|fang|cleaver/.test(desc)) return "weapon";
      if (/armor|robe|plate|vestment|mail|mantle|exoskeleton/.test(desc)) return "armor";
      if (/accessory|ring|halo|talisman|pendant/.test(desc)) return "accessory";
      return "weapon"; // fallback (chat default)
    }

    function FactionShopPanel({ busyId, setBusyId, onPurchased }) {
      const [reloadKey, setReloadKey] = useState(0);
      const { data, loading, error } = useApi("faction/shop", null, [reloadKey]);
      const [cat, setCat] = useState(null);
      const [confirm, setConfirm] = useState(null); // { item, ... }

      async function buy(itemId) {
        setBusyId(itemId);
        try {
          const res = await api("faction/buy_shop_item", { item_id: itemId });
          if (res.ok) {
            haptic("success");
            showToast(t("faction_shop_bought", {
              emoji: res.item_emoji || "",
              name: res.item_name || "",
            }));
            setConfirm(null);
            setReloadKey(x => x + 1);
            onPurchased && onPurchased();
          } else {
            haptic("error");
            showToast(t("faction_shop_err_" + (res.reason || "engine_error")), "err");
          }
        } catch (e) {
          haptic("error");
          showToast(e.message || "Error", "err");
        }
        setBusyId(null);
      }

      if (loading && !data) return <ListSkeleton rows={4} />;
      if (error || !data || !data.ok) {
        return <ErrBanner msg={(data && data.reason) || error || "error"} />;
      }

      const items = data.items || [];
      const cats = {};
      for (const it of items) {
        const c = _fac_shop_categorize(it);
        (cats[c] = cats[c] || []).push(it);
      }

      // Category overview
      if (!cat) {
        return (
          <Card>
            <CardTitle left={`🛒 ${t("faction_shop_title")}`}
                       right={`⭐ ${fmtNum(data.reputation || 0)}`} />
            <div style={{ fontSize:11, color:"var(--muted)", marginBottom:8 }}>
              {t("faction_shop_pick_category")}
            </div>
            <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:8 }}>
              {_FAC_SHOP_CAT_DEFS.map(c => {
                const count = (cats[c.key] || []).length;
                const disabled = count === 0;
                return (
                  <button key={c.key} disabled={disabled}
                          onClick={() => { setCat(c.key); haptic("select"); }}
                          style={{
                            padding:"12px 8px", borderRadius:10,
                            cursor: disabled ? "default" : "pointer",
                            background: disabled ? "rgba(var(--surface-rgb),.3)" : "rgba(var(--surface-rgb),.7)",
                            border:`1px solid ${disabled ? "var(--border)" : "var(--gold2)"}`,
                            opacity: disabled ? .4 : 1,
                          }}>
                    <div style={{ fontSize:22 }}>{c.icon}</div>
                    <div style={{ fontSize:10.5, marginTop:4, fontFamily:"'Cinzel',serif",
                                  color:"var(--gold3)", textTransform:"uppercase", letterSpacing:.4 }}>
                      {t(c.label_key)}
                    </div>
                    <div style={{ fontSize:10, color:"var(--muted)", marginTop:2 }}>
                      {count > 0 ? `${count} ${t("market_items_count")}` : t("market_no_items")}
                    </div>
                  </button>
                );
              })}
            </div>
          </Card>
        );
      }

      const catDef = _FAC_SHOP_CAT_DEFS.find(c => c.key === cat);
      const catItems = cats[cat] || [];

      return (
        <>
          <Card>
            <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", marginBottom:6 }}>
              <CardTitle left={`${catDef.icon} ${t(catDef.label_key)}`}
                         right={`⭐ ${fmtNum(data.reputation || 0)}`} />
              <ActionBtn variant="ghost" onClick={() => { setCat(null); haptic("light"); }}>
                ◀ {t("btn_back")}
              </ActionBtn>
            </div>
          </Card>
          {catItems.length === 0 ? (
            <Card>
              <div style={{ textAlign:"center", padding:"18px 8px", color:"var(--muted)", fontSize:12 }}>
                {t("market_no_items")}
              </div>
            </Card>
          ) : catItems.map(it => {
            const lockedBy = it.locked_by;
            return (
              <Card key={it.id} style={{ marginBottom:8, padding:"10px 12px" }}>
                <div style={{ display:"flex", alignItems:"flex-start", gap:9 }}>
                  <div style={{ fontSize:22, lineHeight:1, flexShrink:0,
                                opacity: it.can_buy ? 1 : .55 }}>{it.emoji}</div>
                  <div style={{ flex:1, minWidth:0 }}>
                    <div style={{ fontFamily:"'Cinzel',serif", fontWeight:700, fontSize:13 }}>
                      {it.name}
                    </div>
                    <div style={{ fontSize:11, color:"var(--muted)", marginTop:3, lineHeight:1.4 }}>
                      {it.description}
                    </div>
                    <div style={{ display:"flex", justifyContent:"space-between", marginTop:6, fontSize:11 }}>
                      <span style={{ color:"var(--gold3)", fontWeight:700 }}>
                        ⭐ {fmtNum(it.rep_cost)} rep
                      </span>
                      <span style={{ color:"var(--muted2)" }}>
                        🏷️ {it.min_rank}
                      </span>
                    </div>
                  </div>
                </div>
                {lockedBy ? (
                  <div style={{ marginTop:7, fontSize:11, color:"var(--warn)" }}>
                    🔒 {t("faction_shop_locked_" + lockedBy)}
                  </div>
                ) : (
                  <ActionBtn variant="primary" disabled={busyId === it.id}
                             onClick={() => setConfirm(it)}
                             style={{ width:"100%", marginTop:7 }}>
                    {busyId === it.id ? <DotSpinner /> : `🛒 ${t("faction_shop_buy_btn")}`}
                  </ActionBtn>
                )}
              </Card>
            );
          })}
          {confirm && (
            <Modal open={true} onClose={() => setConfirm(null)}
                   title={t("faction_shop_confirm_title")}
                   maxWidth={360} zIndex={75}
                   footer={(
                     <div style={{ display:"flex", gap:8 }}>
                       <ActionBtn variant="ghost" onClick={() => setConfirm(null)}
                                  style={{ flex:1 }}>
                         {t("btn_cancel")}
                       </ActionBtn>
                       <ActionBtn variant="primary"
                                  disabled={busyId === confirm.id}
                                  onClick={() => buy(confirm.id)}
                                  style={{ flex:1 }}>
                         {busyId === confirm.id ? <DotSpinner /> : `🛒 ${t("faction_shop_buy_btn")}`}
                       </ActionBtn>
                     </div>
                   )}>
              <div style={{ textAlign:"center" }}>
                <div style={{ fontSize:42, lineHeight:1 }}>{confirm.emoji}</div>
                <div style={{ marginTop:6, fontFamily:"'Cinzel',serif", fontSize:16, fontWeight:700, color:"var(--gold3)" }}>
                  {confirm.name}
                </div>
                <div style={{ fontSize:11.5, color:"var(--muted)", marginTop:6, lineHeight:1.4 }}>
                  {confirm.description}
                </div>
              </div>
              <Card style={{ marginTop:14 }}>
                <div style={{ display:"flex", justifyContent:"space-between", fontSize:12 }}>
                  <span style={{ color:"var(--muted)" }}>{t("faction_shop_cost")}</span>
                  <b style={{ color:"var(--gold2)" }}>⭐ {fmtNum(confirm.rep_cost)}</b>
                </div>
                <div style={{ display:"flex", justifyContent:"space-between", fontSize:12, marginTop:4 }}>
                  <span style={{ color:"var(--muted)" }}>{t("faction_shop_your_rep")}</span>
                  <b>{fmtNum(data.reputation || 0)}</b>
                </div>
                <div style={{ display:"flex", justifyContent:"space-between", fontSize:12, marginTop:4 }}>
                  <span style={{ color:"var(--muted)" }}>{t("faction_shop_after")}</span>
                  <b style={{ color:"var(--jade)" }}>{fmtNum((data.reputation || 0) - confirm.rep_cost)}</b>
                </div>
              </Card>
            </Modal>
          )}
        </>
      );
    }

    // ─── Sprint v14.10 — MA-41 Spirit Root Reroll ────────────────────────────
    // Drill-in modal opened from CultivationTab footer ("🌱 Trocar Raiz").
    // Two-step UX: preview (cost + pity bar + chances) → confirm → reveal
    // banner with old→new emojis. Uses jade currency; mirrors handlers/shop.py
    // _show_root_reroll + _handle_root_reroll_buy exactly.

    var _ROOT_COLOR = {
      Heavenly: "var(--realm-10)",
      Superior: "var(--realm-3)",
      High:     "var(--realm-1)",
      Mid:      "var(--realm-2)",
      Low:      "var(--realm-0)",
    };

    function SpiritRootRerollModal({ onClose, onChanged }) {
      const [preview, setPreview] = useState(null);
      const [phase, setPhase] = useState("preview"); // preview|confirming|revealing|reveal
      const [protected_, setProtected] = useState(false);
      const [busy, setBusy] = useState(false);
      const [result, setResult] = useState(null);
      const [reloadKey, setReloadKey] = useState(0);

      useEffect(() => {
        let cancelled = false;
        (async () => {
          try {
            const res = await api("spirit_root/reroll", { confirm: false });
            if (!cancelled) setPreview(res);
          } catch (e) {
            if (!cancelled) showToast(e.message, "err");
          }
        })();
        return () => { cancelled = true; };
      }, [reloadKey]);

      async function commit() {
        setBusy(true);
        setPhase("revealing");
        try {
          const res = await api("spirit_root/reroll", {
            confirm: true,
            protected: protected_,
          });
          if (res.ok) {
            // Build cinematic delay so the reveal feels weighty.
            await new Promise(r => setTimeout(r, 1200));
            setResult(res);
            setPhase("reveal");
            haptic(res.outcome === "upgrade" ? "success"
                   : res.outcome === "kept" ? "warning" : "warning");
            if (onChanged) onChanged();
          } else {
            haptic("error");
            showToast(res.message || res.reason || "error", "err");
            setPhase("preview");
          }
        } catch (e) {
          haptic("error");
          showToast(e.message, "err");
          setPhase("preview");
        } finally {
          setBusy(false);
        }
      }

      function rerollAgain() {
        setResult(null);
        setPhase("preview");
        setReloadKey(x => x + 1);
      }

      if (!preview) {
        return (
          <Modal open={true} onClose={onClose} title={t("root_reroll_title")}>
            <ListSkeleton rows={3} />
          </Modal>
        );
      }

      const cost = protected_ ? preview.cost_protected : preview.cost_normal;
      const canAfford = protected_ ? preview.can_afford_protected : preview.can_afford_normal;
      const protectedBlocked = protected_ && preview.protected_blocked_at_best;

      return (
        <Modal open={true} onClose={onClose} title={t("root_reroll_title")}
               accent="var(--gold2)" maxWidth={420}>
          {phase === "preview" && (
            <div>
              {/* Current root */}
              <div style={{ textAlign:"center", padding:"6px 0 10px" }}>
                <div style={{ fontSize:54,
                              filter:`drop-shadow(0 0 14px ${cssHex(_ROOT_COLOR[preview.current.name] || "#fff")}99)` }}>
                  {preview.current.emoji}
                </div>
                <div style={{ marginTop:6, fontSize:11, color:"var(--muted)",
                              fontFamily:"'Cinzel',serif", letterSpacing:.4,
                              textTransform:"uppercase" }}>
                  {t("root_reroll_current")}
                </div>
                <div style={{ fontFamily:"'Cinzel',serif", fontWeight:700, fontSize:15,
                              color: _ROOT_COLOR[preview.current.name] || "var(--text)",
                              marginTop:2 }}>
                  {preview.current.name}
                </div>
              </div>

              {/* Pity bar */}
              <div style={{ padding:"8px 10px",
                            background:"rgba(0,0,0,.35)", borderRadius:6,
                            border:"1px solid var(--border)", marginBottom:10 }}>
                <div style={{ fontSize:10, color:"var(--gold2)",
                              fontFamily:"'Cinzel',serif", letterSpacing:.4,
                              textTransform:"uppercase", marginBottom:6 }}>
                  ⏳ {t("root_reroll_pity_title", { total: preview.pity.total })}
                </div>
                {preview.pity.bars.map(b => (
                  <div key={b.threshold} style={{ marginBottom:5 }}>
                    <div style={{ display:"flex", justifyContent:"space-between",
                                  fontSize:10, color:"var(--muted)", marginBottom:2 }}>
                      <span>{b.reached ? "✅" : "⏳"} {b.guaranteed_name}+</span>
                      <span>{Math.min(b.threshold, preview.pity.total)}/{b.threshold}</span>
                    </div>
                    <div style={{ height:4, borderRadius:2,
                                  background:"rgba(0,0,0,.5)", overflow:"hidden" }}>
                      <div style={{ width:`${b.progress * 100}%`, height:"100%",
                                    background: b.reached
                                                ? "linear-gradient(90deg,var(--jade),var(--gold2))"
                                                : `linear-gradient(90deg,${_ROOT_COLOR[b.guaranteed_name] || "var(--realm-1)"},var(--realm-2))`,
                                    transition:"width .4s ease" }} />
                    </div>
                  </div>
                ))}
                {preview.pity.next && (
                  <div style={{ marginTop:5, fontSize:10, color:"var(--gold3)" }}>
                    {t("root_reroll_pity_next", {
                      remaining: preview.pity.next.remaining,
                      name: preview.pity.next.guaranteed_name,
                    })}
                  </div>
                )}
              </div>

              {/* Probability table */}
              <div style={{ padding:"8px 10px",
                            background:"rgba(0,0,0,.35)", borderRadius:6,
                            border:"1px solid var(--border)", marginBottom:10 }}>
                <div style={{ fontSize:10, color:"var(--gold2)",
                              fontFamily:"'Cinzel',serif", letterSpacing:.4,
                              textTransform:"uppercase", marginBottom:5 }}>
                  🎲 {t("root_reroll_chances")}
                </div>
                {preview.weights.filter(w => w.weight > 0).map(w => (
                  <div key={w.idx} style={{ display:"flex", justifyContent:"space-between",
                                             fontSize:11, padding:"3px 0",
                                             borderBottom:"1px dashed rgba(255,255,255,.05)" }}>
                    <span>{w.emoji} {w.name}</span>
                    <span style={{ color: _ROOT_COLOR[w.name] || "var(--text)", fontWeight:600 }}>
                      {w.natural_pct.toFixed(2)}%
                    </span>
                  </div>
                ))}
              </div>

              {/* Protected toggle */}
              <div style={{ padding:"8px 10px", marginBottom:10,
                            background: protected_ ? "rgba(var(--gold2-rgb),.08)" : "rgba(0,0,0,.35)",
                            borderRadius:6,
                            border: `1px solid ${protected_ ? "var(--gold2)" : "var(--border)"}`,
                            cursor: preview.protected_blocked_at_best ? "not-allowed" : "pointer",
                            opacity: preview.protected_blocked_at_best ? 0.5 : 1 }}
                   onClick={() => {
                     if (!preview.protected_blocked_at_best) {
                       haptic("select");
                       setProtected(p => !p);
                     }
                   }}>
                <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center" }}>
                  <span style={{ fontSize:11.5, color:"var(--text)", fontWeight:600 }}>
                    🛡️ {t("root_reroll_protected_label")}
                  </span>
                  <span style={{ fontSize:11, color: protected_ ? "var(--gold2)" : "var(--muted)" }}>
                    {protected_ ? "ON" : "OFF"}
                  </span>
                </div>
                <div style={{ marginTop:4, fontSize:10, color:"var(--muted)", lineHeight:1.4 }}>
                  {t("root_reroll_protected_hint", {
                    cost_normal: preview.cost_normal,
                    cost_protected: preview.cost_protected,
                  })}
                </div>
              </div>

              {/* Jade balance + commit */}
              <div style={{ display:"flex", justifyContent:"space-between",
                            alignItems:"center", marginBottom:8 }}>
                <span style={{ fontSize:11, color:"var(--muted)" }}>
                  💎 {t("root_reroll_jade_balance")}: <strong style={{ color:"var(--gold2)" }}>{preview.spirit_jade}</strong>
                </span>
                <span style={{ fontSize:11, color:"var(--text)" }}>
                  {t("root_reroll_cost")}: <strong style={{ color:"var(--gold3)" }}>💎 {cost}</strong>
                </span>
              </div>
              <ActionBtn variant="primary"
                         disabled={!canAfford || protectedBlocked || busy}
                         busy={busy}
                         onClick={commit}>
                {protectedBlocked
                  ? t("root_reroll_already_best")
                  : !canAfford
                  ? t("root_reroll_not_enough", { cost })
                  : t("root_reroll_btn_confirm", { cost })}
              </ActionBtn>
              <div style={{ marginTop:8, fontSize:10, color:"var(--muted2)",
                            fontStyle:"italic", lineHeight:1.4 }}>
                ⚠️ {t("root_reroll_warning")}
              </div>
            </div>
          )}

          {phase === "revealing" && (
            <div style={{ textAlign:"center", padding:"50px 20px" }}>
              <div style={{ fontSize:60, animation:"alch-icon-spin 1.2s linear infinite" }}>🌱</div>
              <div style={{ marginTop:16, fontSize:13, color:"var(--gold2)",
                            fontFamily:"'Cinzel',serif", letterSpacing:.4 }}>
                {t("root_reroll_revealing")}
              </div>
            </div>
          )}

          {phase === "reveal" && result && (
            <div style={{ textAlign:"center", padding:"6px 0" }}>
              <div style={{ fontSize:11, color:"var(--gold2)",
                            fontFamily:"'Cinzel',serif", letterSpacing:.5,
                            textTransform:"uppercase" }}>
                {result.outcome === "upgrade"
                  ? `🎉 ${t("root_reroll_outcome_upgrade")}`
                  : result.outcome === "kept"
                  ? `🔁 ${t("root_reroll_outcome_kept")}`
                  : `💀 ${t("root_reroll_outcome_downgrade")}`}
              </div>
              <div style={{ marginTop:14, display:"flex",
                            justifyContent:"center", alignItems:"center", gap:18 }}>
                <div style={{ textAlign:"center" }}>
                  <div style={{ fontSize:42, opacity:.55,
                                filter:"grayscale(.4)" }}>{result.old.emoji}</div>
                  <div style={{ fontSize:10, color:"var(--muted)",
                                fontFamily:"'Cinzel',serif", marginTop:3 }}>
                    {result.old.name}
                  </div>
                </div>
                <div style={{ fontSize:24, color:"var(--gold2)" }}>→</div>
                <div style={{ textAlign:"center" }}>
                  <div style={{ fontSize:54,
                                filter:`drop-shadow(0 0 18px ${cssHex(_ROOT_COLOR[result.new.name] || "#fff")}cc)`,
                                animation:"alch-pop .55s ease-out" }}>
                    {result.new.emoji}
                  </div>
                  <div style={{ fontSize:13, color: _ROOT_COLOR[result.new.name] || "var(--text)",
                                fontFamily:"'Cinzel',serif", fontWeight:700, marginTop:3 }}>
                    {result.new.name}
                  </div>
                </div>
              </div>
              {result.pity_triggered && (
                <div style={{ marginTop:14, padding:"6px 10px",
                              background:"rgba(var(--gold2-rgb),.1)", borderRadius:5,
                              border:"1px solid var(--gold2)",
                              fontSize:10.5, color:"var(--gold2)" }}>
                  ⏳ {t("root_reroll_pity_triggered")}
                </div>
              )}
              <div style={{ marginTop:14, display:"flex", gap:8, justifyContent:"center" }}>
                <ActionBtn variant="ghost" size="sm" onClick={rerollAgain}>
                  🔁 {t("root_reroll_btn_again")}
                </ActionBtn>
                <ActionBtn variant="primary" size="sm" onClick={onClose}>
                  ✓ {t("root_reroll_btn_done")}
                </ActionBtn>
              </div>
            </div>
          )}
        </Modal>
      );
    }

    // ─── Sprint v14.11 ─── paridade real ─────────────────────────────────────
    // Pill use + active buffs panel, beast expedition send/collect/evolve,
    // dungeon quests per-dungeon, faction accept_quest. Engines em
    // core/{alchemy,beast,dungeon_quest,faction}_engine.py — UI faz fetch,
    // engine faz o trabalho, side-effects mirrorados no endpoint.

    // ── PillUsePanel ────────────────────────────────────────────────────────
    // Renderizado dentro do DetailModal quando entry.kind === "item" &&
    // entry.type === "pill". Faz fetch lazy de /pill/info para evitar payload
    // pesado no /inventory listing.

    function _pillEffectLabel(pill, scaled) {
      // Maps effect_type + scaled.kind to a human-readable line.
      const eff = pill.effect_type;
      const dur = scaled.duration || 0;
      const durFrag = dur > 0
        ? ` · ${t("pill_panel_duration", { n: dur })}`
        : "";
      if (scaled.kind === "pct") {
        const sign = scaled.pct >= 0 ? "+" : "";
        return `${t("pill_panel_effect_pct", { eff: t("pill_eff_" + eff) || eff, pct: sign + scaled.pct.toFixed(0) })}${durFrag}`;
      }
      if (scaled.kind === "flat") {
        const line = `${t("pill_panel_effect_flat", { eff: t("pill_eff_" + eff) || eff, val: fmtNum(scaled.value) })}${durFrag}`;
        // QoL-Feedback 2026-07-29 Item A (report [jogador] "Pureza +0"): o valor
        // do purity_boost já vem HONESTO do servidor (purity_gain — a mesma
        // função do apply); `purity_foundation` (condicional) liga a nota.
        if (scaled.purity_foundation) {
          const fqLabel = t("foundation_quality_" + scaled.purity_foundation) || scaled.purity_foundation;
          return `${line} · ${t("pill_panel_purity_note", { fq: fqLabel })}`;
        }
        return line;
      }
      // raw
      return t("pill_panel_effect_raw", { eff: t("pill_eff_" + eff) || eff });
    }

    // QoL-Feedback 03/08 (report [jogador]) — a Pílula da Fundação Eterna não mostrava
    // NADA: nem antes (o mini imprimia só o label estático) nem depois (o painel
    // descartava o old→new que o servidor já devolvia). Este bloco é a metade
    // PRÉ-USO: a fundação atual com o ×mult que vale, a tabela de odds real da
    // qualidade do craft e o risco de PIORAR. Os números vêm todos do servidor
    // (foundation_engine — a mesma fonte do apply); o cliente nunca recalcula.
    function FoundationRerollPreview({ found }) {
      if (!found) return null;
      const fqName = (q) => safeT("foundation_quality_" + q, null, q);
      return (
        <div style={{ marginTop:7, fontSize:11, lineHeight:1.55 }}>
          <div style={{ color:"rgba(var(--text2-rgb),.92)" }}>
            🏯 {found.current
              ? t("pill_found_current", {
                  quality: `${fqName(found.current)} ${found.current_emoji || ""}`.trim(),
                  mult: found.current_mult.toFixed(2),
                })
              : t("pill_found_current_none")}
          </div>
          {found.locked ? (
            <div style={{ marginTop:4, color:"var(--gold2)" }}>
              🌌 {t("pill_found_locked")}
            </div>
          ) : (
            <>
              <div style={{ marginTop:5, color:"var(--muted)" }}>
                🎲 {t("pill_found_odds_title")}
              </div>
              <div style={{ marginTop:2, display:"grid", gap:2 }}>
                {(found.odds || []).map((o) => (
                  <div key={o.quality} style={{
                    display:"flex", justifyContent:"space-between", gap:8,
                    color: o.direction === "down" ? "var(--red2)"
                         : o.direction === "up" ? "var(--jade)" : "rgba(var(--text2-rgb),.85)",
                  }}>
                    <span>
                      {o.direction === "down" ? "▼" : o.direction === "up" ? "▲" : "＝"}{" "}
                      {`${fqName(o.quality)} ${o.emoji || ""}`.trim()} (×{o.mult.toFixed(2)})
                    </span>
                    <b style={{ fontVariantNumeric:"tabular-nums" }}>{o.pct}%</b>
                  </div>
                ))}
              </div>
              <div style={{ marginTop:5, color: found.sacred_path ? "var(--gold2)" : "var(--muted)" }}>
                🌌 {found.sacred_path ? t("pill_found_sacred_now") : t("pill_found_sacred_hint")}
              </div>
              {found.can_downgrade && (
                <div style={{ marginTop:4, color:"#fcd34d" }}>
                  ⚠️ {t("pill_found_risk")}
                </div>
              )}
            </>
          )}
        </div>
      );
    }

    function PillUsePanel({ entry, onClose, onActionDone, onPlayerRefresh }) {
      const [info, setInfo] = useState(null);
      const [loading, setLoading] = useState(true);
      const [err, setErr] = useState(null);
      const [busy, setBusy] = useState(false);
      const [resultLines, setResultLines] = useState(null);
      // Review adversarial 03/08 — o card de resultado era SEMPRE jade; um
      // downgrade permanente da fundação lia-se como vitória.
      const [resultBad, setResultBad] = useState(false);
      // v14.13b BUGFIX ([jogador] 2026-05-12): after using a Divine pill, the
      // panel got stuck on the result view with no way back to the action
      // buttons — owner had to close + reopen the Ring to use any other
      // quality of the same pill. `infoReloadKey` lets us refetch
      // `pill/info` (fresh stock_by_quality) when the player taps "Use
      // another" so the panel can keep accepting taps without forcing a
      // round-trip through the inventory tab.
      const [infoReloadKey, setInfoReloadKey] = useState(0);
      // Quick-wins 2026-06-10 — chosen-quantity consume ([jogadores]; the
      // lack drove them to write an auto-consume script). Free-text amount,
      // clamped server-side to [1,50] and to the player's stock.
      const [customQty, setCustomQty] = useState("");

      useEffect(() => {
        let alive = true;
        (async () => {
          try {
            const res = await api("pill/info", {
              pill_id: entry.catalog_id,
              quality: entry.quality || "normal",
            });
            if (alive) setInfo(res);
          } catch (e) {
            if (alive) setErr(e.message || t("pill_panel_load_failed"));
          } finally {
            if (alive) setLoading(false);
          }
        })();
        return () => { alive = false; };
      }, [entry.catalog_id, entry.quality, infoReloadKey]);

      async function callUse(count) {
        if (busy) return;
        setBusy(true); setErr(null); setResultLines(null);
        haptic("warning");
        try {
          const res = await api("pill/use", {
            pill_id: entry.catalog_id,
            quality: entry.quality || "normal",
            count: count || 1,
          });
          if (!res.ok) {
            haptic("error");
            if (res.reason === "buff_already_active") {
              setErr(t("pill_panel_buff_already_active", {
                n: Math.ceil((res.remaining_seconds || 0) / 60),
              }));
            } else if (res.reason === "bulk_not_supported") {
              setErr(t("pill_panel_bulk_unsupported"));
            } else if (res.reason === "stat_at_cap") {
              // QoL-Feedback 2 (report [jogador]): já no teto — nada foi consumido.
              setErr(t("pill_panel_at_cap_refused", { cap: fmtNum(res.cap) }));
            } else if (res.reason === "refill_at_cap") {
              // QoL 07/08 (report [jogador]): dantian/corpo já cheios — o lote
              // é recusado ANTES do débito e as pílulas ficam no anel (Lei §1).
              setErr(t(res.refill_kind === "hp" ? "pill_panel_hp_full_refused"
                                                : "pill_panel_qi_full_refused"));
              // (o servidor emite `refill_kind` nos DOIS ramos — sucesso e
              //  recusa; ver core/webserver.py:api_pill_use)
            } else if (res.reason === "foundation_sacred_locked"
                       || res.reason === "foundation_not_established") {
              // Review adversarial 03/08 — recusa ANTES do débito: a pílula
              // fica no anel e a razão é dita (Lei §1).
              setErr(t("pill_" + res.reason));
            } else {
              setErr(res.reason || t("pill_panel_use_failed"));
            }
            setBusy(false);
            return;
          }
          // Build result summary lines.
          const lines = [];
          // Review adversarial 03/08 — a reforja que NÃO subiu (ou desceu) não
          // pode vibrar sucesso nem vestir card verde. O haptic passa para
          // DEPOIS de sabermos o resultado.
          let outcomeBad = false;
          const applied = res.applied || 0;
          const capped = res.capped || 0;
          if (applied > 0) {
            lines.push(t("pill_panel_result_applied", {
              n: applied, pill: res.pill_name,
            }));
          }
          if (capped > 0) {
            lines.push(t("pill_panel_result_capped", { n: capped }));
          }
          if (res.cap_stopped) {
            // Teto atingido no meio do lote — o resto ficou no anel.
            lines.push(t("pill_panel_at_cap_kept", { cap: fmtNum(res.cap) }));
          }
          if (res.refill_stopped) {
            // QoL 07/08 — encheu no meio do lote: DIZER quantas sobraram, nunca
            // um lote silencioso que sumiu com 50 pílulas.
            lines.push(t("pill_panel_refill_stopped", { left: fmtNum(res.refill_left || 0) }));
          }
          // Last effect summary (if available + relevant).
          const last = (res.effects || []).slice(-1)[0];
          // QoL-Feedback 03/08 (report [jogador] "no visible changes"): o servidor já
          // devolvia old/new/sacred_awakened e o painel deitava fora — o chat
          // dizia "🌌 Fundação Reforjada! X → Y" e a superfície canónica ficava
          // muda. Espelha o formatter do chat (handlers/inventory.py).
          if (last && (last.type === "eternal_foundation_reroll"
                       || (last.type === "foundation_reroll" && last.rerolled))) {
            const fqName = (q) => q ? safeT("foundation_quality_" + q, null, q) : "—";
            const om = last.old_mult != null ? Number(last.old_mult).toFixed(2) : null;
            const nm = last.new_mult != null ? Number(last.new_mult).toFixed(2) : null;
            // Review adversarial 03/08 — a direção MANDA no texto. `old == new`
            // é o resultado mais provável (70% numa divine sobre Perfeita) e era
            // anunciado como "Fundação Reforjada!" — a queixa original com uma
            // celebração falsa por cima; e o downgrade PERMANENTE vinha igual ao
            // ganho, em card verde com haptic de sucesso.
            if (last.sacred_awakened) {
              lines.push(t("pill_found_result_sacred", { old: fqName(last.old), new: fqName(last.new) }));
              if (nm) lines.push(t("pill_found_result_mult", { mult: nm }));
            } else if (last.direction === "same") {
              lines.push(t("pill_found_result_same", { quality: fqName(last.new), mult: nm || "1.00" }));
              outcomeBad = true;
            } else if (last.direction === "down") {
              lines.push(t("pill_found_result_down", {
                old: fqName(last.old), new: fqName(last.new),
                old_mult: om || "1.00", new_mult: nm || "1.00",
              }));
              outcomeBad = true;
            } else {
              lines.push(t("pill_found_result", { old: fqName(last.old), new: fqName(last.new) }));
              if (om && nm) lines.push(t("pill_found_result_mult_delta", { old_mult: om, new_mult: nm }));
            }
          }
          if (last && last.effectiveness < 1.0) {
            lines.push(t("pill_panel_result_reduced", {
              pct: Math.round((last.effectiveness || 0) * 100),
            }));
          }
          if (res.achievements_unlocked && res.achievements_unlocked.length > 0) {
            for (const a of res.achievements_unlocked) {
              lines.push(`🏆 ${a.emoji} ${a.name}`);
            }
          }
          // Progressão Visível — qi-cap pills raise the aggregated Poder de Combate;
          // show the before→after so the permanent gain is never silent.
          const _pl = vpPowerLine(res.power_delta);
          if (_pl) lines.push(_pl.replace(/^\n/, ""));
          haptic(outcomeBad ? "warning" : "success");
          setResultBad(outcomeBad);
          setResultLines(lines.length ? lines : [t("pill_panel_result_done")]);
          setBusy(false);
          onActionDone && onActionDone();
          onPlayerRefresh && onPlayerRefresh();
        } catch (e) {
          haptic("error");
          setErr(e.message || t("pill_panel_use_failed"));
          setBusy(false);
        }
      }

      if (loading) {
        return (
          <div style={{ marginTop:14, padding:"16px 8px", textAlign:"center" }}>
            <DotSpinner />
          </div>
        );
      }
      if (err && !info) {
        return <ErrBanner msg={err} />;
      }
      if (!info) return null;

      const scaled = info.scaled || { kind: "raw" };
      const conflict = info.active_buff_conflict;
      const stockBy = info.stock_by_quality || {};
      const myStock = stockBy[(entry.quality || "normal").toLowerCase()] || 0;
      const supportsBulk = !!info.supports_bulk;
      const effectiveness = info.effectiveness != null ? info.effectiveness : 1.0;

      // After a successful use, render a result panel instead of action buttons.
      // v14.13b: TWO buttons — "Continuar" (refetches info, returns to action
      // view so player can use another pill of any remaining quality without
      // closing the modal) and "OK" (closes back to inventory). Mirrors what
      // the chat does in /pilulas after `/use`.
      if (resultLines) {
        return (
          <div style={{ marginTop:14, display:"flex", flexDirection:"column", gap:6 }}>
            <div style={{
              padding:"10px 12px", borderRadius:8,
              background: resultBad
                ? "linear-gradient(180deg, rgba(229,168,68,.16), rgba(20,30,55,.6))"
                : "linear-gradient(180deg, rgba(46,196,182,.18), rgba(20,30,55,.6))",
              border: `1px solid ${resultBad ? "var(--warn)" : "var(--jade)"}`,
              fontSize:12, color:"var(--text)", lineHeight:1.55,
            }}>
              {resultLines.map((l, i) => <div key={i}>{l}</div>)}
            </div>
            <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:6 }}>
              <ActionBtn variant="ghost" onClick={() => {
                setResultLines(null);
                setResultBad(false);
                setErr(null);
                setLoading(true);
                setInfoReloadKey(x => x + 1);
              }} style={{ width:"100%" }}>
                {t("pill_panel_continue") || "Continuar"}
              </ActionBtn>
              <ActionBtn variant="primary" onClick={onClose} style={{ width:"100%" }}>
                ✓ {t("btn_ok")}
              </ActionBtn>
            </div>
          </div>
        );
      }

      return (
        <div style={{ marginTop:14, display:"flex", flexDirection:"column", gap:10 }}>
          {/* Effect preview */}
          <div style={{
            padding:"10px 12px", borderRadius:8,
            background:"rgba(0,0,0,.3)", border:"1px solid rgba(var(--gold2-rgb),.22)",
            fontSize:12, color:"var(--text)", lineHeight:1.5,
          }}>
            <div style={{ fontSize:10, color:"var(--gold2)",
                          fontFamily:"'Cinzel',serif", letterSpacing:.4,
                          textTransform:"uppercase", marginBottom:4 }}>
              {t("pill_panel_effect_header")}
            </div>
            <div>{_pillEffectLabel(info.pill, scaled)}</div>
            {/* QoL-Feedback 03/08 — Lei §10 PRÉ-USO (key condicional: só a
                pílula da fundação a traz; qualquer outra → nada renderiza). */}
            <FoundationRerollPreview found={scaled.foundation} />
            {/* A irmã (id 34) não tem tabela de odds — é uma PROVA de atributos.
                Dizer a regra é honesto; inventar percentagens não seria. */}
            {scaled.kind === "foundation_trial" && (
              <div style={{ marginTop:7, fontSize:11, lineHeight:1.55 }}>
                <div style={{ color:"rgba(var(--text2-rgb),.92)" }}>
                  🏯 {scaled.foundation_current
                    ? t("pill_found_current", {
                        quality: safeT("foundation_quality_" + scaled.foundation_current,
                                       null, scaled.foundation_current),
                        mult: Number(scaled.foundation_mult || 1).toFixed(2),
                      })
                    : t("pill_found_current_none")}
                </div>
                {scaled.foundation_current === "sacred" ? (
                  <div style={{ marginTop:4, color:"var(--gold2)" }}>🌌 {t("pill_found_locked")}</div>
                ) : (
                  <>
                    <div style={{ marginTop:5, color:"var(--muted)" }}>🎲 {t("pill_found_trial")}</div>
                    <div style={{ marginTop:4, color:"#fcd34d" }}>⚠️ {t("pill_found_risk")}</div>
                  </>
                )}
              </div>
            )}
            {effectiveness < 1.0 && (
              <div style={{ marginTop:6, fontSize:10.5, color:"#fcd34d" }}>
                ⚠️ {t("pill_panel_effectiveness", { pct: Math.round(effectiveness * 100) })}
              </div>
            )}
          </div>

          {conflict && (
            <div style={{
              padding:"8px 10px", borderRadius:6,
              background:"rgba(var(--red-rgb),.08)", border:"1px solid rgba(var(--red-rgb),.4)",
              fontSize:11, color:"var(--red2)",
            }}>
              ⏳ {t("pill_panel_already_active", {
                n: Math.ceil((conflict.remaining_seconds || 0) / 60),
              })}
            </div>
          )}

          {err && <ErrBanner msg={err} />}

          {/* Action buttons */}
          {!conflict && (
            <>
              {/* Review adversarial 03/08 — o preview dizia "esta pílula não
                  muda nada" e o botão continuava vivo: o jogador queimava a
                  pílula mais cara do jogo. O bloqueio é o MESMO que o servidor
                  aplica (foundation_pill_block_reason) — display == recusa. */}
              <ActionBtn variant="primary"
                         disabled={busy || myStock < 1 || !!(scaled.foundation && scaled.foundation.locked)}
                         onClick={() => callUse(1)}
                         style={{ width:"100%" }}>
                {busy ? <DotSpinner />
                  : (scaled.foundation && scaled.foundation.locked)
                    ? `🌌 ${t("pill_found_locked_btn")}`
                    : `💊 ${t("pill_panel_use_btn")}`}
              </ActionBtn>
              {supportsBulk && myStock >= 5 && (() => {
                const maxN = Math.min(50, myStock);
                const quick = myStock >= 10 ? [5, 10] : [5];
                // Only offer a Máx button when it isn't a dead duplicate of the
                // largest quick button (e.g. at stock 5, Máx would also be ×5).
                const showMax = maxN > quick[quick.length - 1];
                const cols = quick.length + (showMax ? 1 : 0);
                const parsed = parseInt(customQty, 10);
                const customValid = parsed >= 1;
                const customN = customValid ? Math.max(1, Math.min(maxN, parsed)) : 0;
                return (
                  <>
                    <div style={{ display:"grid", gridTemplateColumns:`repeat(${cols},1fr)`, gap:6 }}>
                      {quick.map(n => (
                        <ActionBtn key={n} variant="ghost" disabled={busy} onClick={() => callUse(n)}>
                          💊 ×{n}
                        </ActionBtn>
                      ))}
                      {showMax && (
                        <ActionBtn variant="ghost" disabled={busy} onClick={() => callUse(maxN)}>
                          💊 ×{maxN}
                        </ActionBtn>
                      )}
                    </div>
                    {/* Custom amount — clamped to [1, maxN] before send. */}
                    <div style={{ display:"flex", gap:6 }}>
                      <input type="number" inputMode="numeric" min={1} max={maxN}
                             value={customQty}
                             onChange={e => setCustomQty((e.target.value || "").replace(/[^0-9]/g, ""))}
                             placeholder={t("pill_panel_custom_ph", { max: maxN })}
                             style={{ flex:1, minWidth:0, padding:"9px 11px", borderRadius:8,
                                      background:"rgba(0,0,0,.3)", border:"1px solid rgba(var(--gold2-rgb),.22)",
                                      color:"var(--text)", fontSize:12 }} />
                      <ActionBtn variant="ghost" disabled={busy || !customValid}
                                 onClick={() => { callUse(customN); setCustomQty(""); }}>
                        {customValid ? `💊 ×${customN}` : "💊"}
                      </ActionBtn>
                    </div>
                  </>
                );
              })()}
            </>
          )}
          {conflict && (
            <ActionBtn variant="ghost" onClick={onClose} style={{ width:"100%" }}>
              {t("btn_close")}
            </ActionBtn>
          )}
        </div>
      );
    }

    // ── ActiveBuffsCard ─────────────────────────────────────────────────────
    // Mostra os buffs activos (PlayerBuff) com tipo + magnitude + countdown.
    // Embed em CultivationTab por baixo do card "attributes" — local cognitivo
    // mais consistente (vê os stats e logo a seguir os buffs que os afectam).
    function _buffLabel(buff) {
      const key = "pill_eff_" + buff.buff_type;
      const localized = t(key);
      if (localized && localized !== key) return localized;
      // Fallback: humanize the buff_type itself (Battle Power Boost, etc.)
      return humanizeStat(buff.buff_type);
    }
    function _buffMagnitude(buff) {
      const v = buff.buff_value || 0;
      // explore_protection (Onda 5 Fase 2) is FRACTION semantics: 0.35 = 35%
      // of the exploration death-loss prevented — not a multiplier/flat stat.
      if (buff.buff_type === "explore_protection") return `-${Math.round(v * 100)}%`;
      // Multiplier buffs: render as +N%
      if (v > 1) return `+${Math.round((v - 1) * 100)}%`;
      // Stat boost/qi restore: render as flat
      return `+${fmtNum(v)}`;
    }
    function ActiveBuffsCard() {
      const [tick, setTick] = useState(0);
      const { data, loading } = useApi("buffs/active", null, [tick]);
      useVisibleInterval(() => setTick(x => x + 1), 30000);  // refresh every 30s
      const buffs = (data?.buffs || []);
      if (loading && !data) return null;
      if (!buffs.length) return null;
      return (
        <Card>
          <CardTitle left={t("buffs_card_title")} right={`${buffs.length}`} />
          <div style={{ display:"flex", flexDirection:"column", gap:6 }}>
            {buffs.map(b => (
              <div key={b.id} style={{
                display:"flex", alignItems:"center", gap:8,
                padding:"7px 10px", borderRadius:6,
                background:"rgba(46,196,182,.06)",
                border:"1px solid rgba(46,196,182,.25)",
              }}>
                <span style={{ fontSize:18 }}>✨</span>
                <div style={{ flex:1, minWidth:0 }}>
                  <div style={{ fontSize:12, fontWeight:600, color:"var(--text)" }}>
                    {_buffLabel(b)} <span style={{ color:"var(--jade)" }}>{_buffMagnitude(b)}</span>
                  </div>
                  {b.source && (
                    <div style={{ fontSize:10, color:"var(--muted)" }}>
                      {b.source}
                    </div>
                  )}
                </div>
                <div style={{ fontSize:10.5, color:"var(--gold2)",
                              fontFamily:"'Cinzel',serif", letterSpacing:.4, flexShrink:0 }}>
                  ⏳ {fmtDuration((b.remaining_seconds || 0) * 1000)}
                </div>
              </div>
            ))}
          </div>
        </Card>
      );
    }

    // ── BeastExpeditionModal ────────────────────────────────────────────────
    // Picker de expedição para um beast. Mostra catalog + slots VIP + req rank
    // por expedição. Mirror handlers/beasts.beast_expedition_pick + send.
    function _BEAST_RANK_INDEX(rank) {
      // Mirror config.BEAST_RANK_INDEX — local fast lookup so we don't fetch
      // ranks every time.
      // ⚠️ 獸 3.3 — esta cópia tinha Mítico ANTES de Lendário (o motor diz o
      // contrário: `config.BEAST_RANKS`). Não mudava nenhuma tela de hoje (a
      // expedição mais exigente pede Lendário, e as duas passam), mas era a
      // mentira à espera da 1.ª expedição Mítica. A linha da besta já traz o
      // `rank_idx` do servidor, e é ele que se lê primeiro.
      const list = ["Common", "Uncommon", "Rare", "Epic", "Legendary", "Mythic", "Divine"];
      const i = list.indexOf(rank);
      return i < 0 ? 0 : i;
    }
    function BeastExpeditionModal({ beast, onClose, onSent }) {
      const [reload, setReload] = useState(0);
      const { data, loading, error } = useApi("beasts/expeditions", null, [reload]);
      const [busy, setBusy] = useState(false);
      const [err, setErr] = useState(null);

      async function callSend(expedition_id) {
        if (busy) return;
        setBusy(true); setErr(null);
        haptic("warning");
        try {
          const res = await api("beasts/send_expedition", {
            beast_id: beast.id, expedition_id,
          });
          if (!res.ok) {
            haptic("error");
            setErr(_translateBeastReason(res.reason, res.error_params));
            setBusy(false);
            return;
          }
          haptic("success");
          showToast(t("beasts_exp_sent", {
            name: res.expedition_name, hours: res.duration_hours,
          }));
          setBusy(false);
          onSent && onSent();
          onClose && onClose();
        } catch (e) {
          haptic("error");
          setErr(e.message || t("beasts_exp_send_failed"));
          setBusy(false);
        }
      }

      const beastRankIdx = typeof beast.rank_idx === "number" ? beast.rank_idx : _BEAST_RANK_INDEX(beast.rank);

      return (
        <Modal open={true} onClose={onClose} accent="var(--gold2)" maxWidth={400}
               title={t("beasts_exp_modal_title", { name: beast.name })}>
          {loading && !data && <ListSkeleton rows={4} />}
          {error && <ErrBanner msg={error} />}
          {err && <ErrBanner msg={err} />}
          {data && (
            <div>
              <div style={{ display:"flex", gap:6, marginBottom:10, fontSize:11,
                            color:"var(--muted)" }}>
                <Badge>{t("beasts_exp_slots", { used: data.slots.used, max: data.slots.max })}</Badge>
                {data.slots.vip_level > 0 && (
                  <Badge variant="gold">VIP{data.slots.vip_level}</Badge>
                )}
              </div>
              {data.expeditions.length === 0 ? (
                <div style={{ textAlign:"center", padding:"24px 0", color:"var(--muted)" }}>
                  {t("beasts_exp_empty")}
                </div>
              ) : (
                <div style={{ display:"flex", flexDirection:"column", gap:8 }}>
                  {data.expeditions.map(e => {
                    const meets = beastRankIdx >= e.req_rank_idx;
                    return (
                      <div key={e.id} style={{
                        padding:"10px 12px", borderRadius:8,
                        background: meets ? "rgba(0,0,0,.3)" : "rgba(0,0,0,.15)",
                        border:`1px solid ${meets ? "rgba(var(--gold2-rgb),.32)" : "rgba(var(--glow-rgb),.18)"}`,
                        opacity: meets ? 1 : .55,
                      }}>
                        <div style={{ display:"flex", alignItems:"center", gap:8, marginBottom:4 }}>
                          <span style={{ fontSize:20 }}>{e.emoji}</span>
                          <span style={{ flex:1, fontFamily:"'Cinzel',serif", fontWeight:700,
                                         fontSize:13, color: meets ? "var(--gold2)" : "var(--muted2)" }}>
                            {e.name}
                          </span>
                          <span style={{ fontSize:11, color:"var(--muted)" }}>{e.duration_hours}h</span>
                        </div>
                        <div style={{ fontSize:10.5, color:"var(--muted)", marginBottom:7, lineHeight:1.4 }}>
                          {e.description}
                        </div>
                        <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between" }}>
                          <span style={{ fontSize:10, color: meets ? "var(--jade)" : "var(--red2)" }}>
                            {meets
                              ? `✓ ${t("beasts_exp_req_met")}`
                              : `🔒 ${t("beasts_exp_req_rank", { rank: postoDaBesta(e.req_beast_rank) })}`}
                          </span>
                          {meets && (
                            <ActionBtn variant="primary" size="sm" disabled={busy}
                                       onClick={() => callSend(e.id)}>
                              {busy ? <DotSpinner /> : `🗺️ ${t("beasts_exp_send_btn")}`}
                            </ActionBtn>
                          )}
                        </div>
                      </div>
                    );
                  })}
                </div>
              )}
            </div>
          )}
        </Modal>
      );
    }

    // ── BeastEvolveModal ────────────────────────────────────────────────────
    // Confirmação + execução de evolução. Reusa engine evolve_beast.
    function BeastEvolveModal({ beast, onClose, onEvolved }) {
      const [busy, setBusy] = useState(false);
      const [err, setErr] = useState(null);
      const [result, setResult] = useState(null);
      const evo = beast.evolution || {};

      async function callEvolve() {
        if (busy) return;
        setBusy(true); setErr(null);
        haptic("warning");
        try {
          const res = await api("beasts/evolve", { beast_id: beast.id });
          if (!res.ok) {
            haptic("error");
            setErr(_translateBeastReason(res.reason, res.error_params));
            setBusy(false);
            return;
          }
          haptic("success");
          setResult(res);
          setBusy(false);
          onEvolved && onEvolved();
        } catch (e) {
          haptic("error");
          setErr(e.message || t("beasts_evolve_failed"));
          setBusy(false);
        }
      }

      if (result) {
        return (
          <Modal open={true} onClose={onClose} accent="var(--gold2)" maxWidth={360}
                 title={t("beasts_evolve_modal_done")}>
            <div style={{ textAlign:"center", padding:"12px 0" }}>
              <div style={{ fontSize:50,
                            filter:"drop-shadow(0 0 16px rgba(var(--gold2-rgb),.7))",
                            animation:"pulse-glow 1.8s ease-in-out infinite" }}>
                {beast.emoji}
              </div>
              <div style={{ marginTop:10, fontFamily:"'Cinzel',serif",
                            fontSize:14, color:"var(--gold2)", fontWeight:700 }}>
                {result.old_rank} → {result.new_rank}
              </div>
              <div style={{ marginTop:8, fontSize:11.5, color:"var(--muted)" }}>
                {t("beasts_evolve_modal_cores_used", { n: result.cores_used })}
              </div>
              <div style={{ marginTop:6, fontSize:11, color:"var(--text)", lineHeight:1.5 }}>
                {t("beasts_evolve_modal_flavor")}
              </div>
              <ActionBtn variant="primary" onClick={onClose}
                         style={{ width:"100%", marginTop:14 }}>
                ✓ {t("btn_ok")}
              </ActionBtn>
            </div>
          </Modal>
        );
      }

      return (
        <Modal open={true} onClose={onClose} accent="var(--gold2)" maxWidth={360}
               title={t("beasts_evolve_modal_title", { name: beast.name })}>
          <div style={{ textAlign:"center", padding:"8px 0" }}>
            <div style={{ display:"flex", alignItems:"center", justifyContent:"center", gap:14 }}>
              {itemVivoOn()
                ? <PieceIcon kind="beast" name={beast.name} artKey={beast.art_key} emoji={beast.emoji}
                             size={72} accent="var(--muted)" radius={9} dim />
                : <div style={{ fontSize:38 }}>{beast.emoji}</div>}
              <div style={{ fontSize:24, color:"var(--gold2)" }}>→</div>
              {itemVivoOn()
                ? <PieceIcon kind="beast" name={beast.name} artKey={beast.art_key} emoji={beast.emoji}
                             size={72} accent="var(--gold2)" radius={9}
                             style={{ boxShadow:"0 0 14px -2px rgba(var(--gold2-rgb),.7)" }} />
                : <div style={{ fontSize:38, filter:"drop-shadow(0 0 8px rgba(var(--gold2-rgb),.7))" }}>{beast.emoji}</div>}
            </div>
            <div style={{ marginTop:8, fontFamily:"'Cinzel',serif",
                          fontWeight:700, fontSize:13, color:"var(--text)" }}>
              {evo.current_rank} → {evo.next_rank}
            </div>
          </div>

          <div style={{ marginTop:14, padding:"10px 12px", borderRadius:8,
                        background:"rgba(0,0,0,.3)",
                        border:"1px solid rgba(var(--gold2-rgb),.22)" }}>
            <div style={{ display:"flex", justifyContent:"space-between", marginBottom:6, fontSize:11 }}>
              <span style={{ color:"var(--muted)" }}>{t("beasts_evolve_modal_cost")}</span>
              <span style={{ color:"var(--gold2)", fontWeight:600 }}>
                💎 {evo.cores_needed} {t("beasts_evolve_modal_cores")}
              </span>
            </div>
            <div style={{ display:"flex", justifyContent:"space-between", fontSize:11 }}>
              <span style={{ color:"var(--muted)" }}>{t("beasts_evolve_modal_level_req")}</span>
              <span style={{ color: evo.level_met ? "var(--jade)" : "var(--red2)", fontWeight:600 }}>
                {evo.level_met ? "✓" : "✗"} Lv.{beast.level} / {evo.level_needed}
              </span>
            </div>
          </div>

          {err && <ErrBanner msg={err} />}

          <ActionBtn variant="primary" disabled={busy || !evo.level_met}
                     onClick={callEvolve} style={{ width:"100%", marginTop:14 }}>
            {busy
              ? <DotSpinner />
              : `🌟 ${t("beasts_evolve_modal_btn", { next: evo.next_rank })}`}
          </ActionBtn>
          <div style={{ fontSize:10, color:"var(--muted)", textAlign:"center", marginTop:6, lineHeight:1.4 }}>
            {t("beasts_evolve_modal_disclaimer")}
          </div>
        </Modal>
      );
    }

    // ── DungeonQuestsModal ──────────────────────────────────────────────────
    // Lista quests per-dungeon com accept/claim inline. Mirror
    // handlers/dungeons._dungeon_quest_list. Tracking já corre via engine
    // (dungeon_engine), portanto progresso atualiza-se sozinho a cada
    // floor/sweep.

    function _translateDungeonQuestReason(reason, params) {
      const map = {
        dng_quest_not_found: "dng_quest_not_found",
        dng_quest_already_active: "dng_quest_already_active",
        dng_quest_cooldown: "dng_quest_cooldown",
        dng_quest_not_completed: "dng_quest_not_completed",
        dng_quest_not_active: "dng_quest_not_active",
      };
      const key = map[reason] || "dng_quest_action_failed";
      return t(key, params || {});
    }

    function _dungeonQuestRewards(q, hasFaction) {
      const out = [];
      if (q.reward_stones > 0) out.push(`🪨 +${fmtNum(q.reward_stones)}`);
      if (q.reward_rep > 0) {
        // QoL-Feedback 2026-07-29 Item C (report [jogador]): a rep é de FACÇÃO (🔱,
        // o ícone do sistema) — nomear a moeda (≠ rep de continente do MV-6) e
        // avisar quando o claim vai pular o crédito (Lei §1). `hasFaction`
        // undefined (payload antigo) = sem aviso.
        const label = `🔱 +${q.reward_rep} ${t("dng_quest_rep_faction_short")}`;
        out.push(hasFaction === false ? `${label} ${t("dng_quest_rep_needs_faction")}` : label);
      }
      const items = q.reward_items || {};
      if (items.technique_scroll) out.push(`📜 ×${items.technique_scroll}`);
      if (items.herb_pack) out.push(`🌿 ×${items.herb_pack}`);
      if (items.dao_fragment) out.push(`💠 ×${items.dao_fragment}`);
      if (items.ore && items.ore.qty) out.push(`⛏️ ×${items.ore.qty}`);
      if (items.herb && items.herb.qty) out.push(`🌿 ×${items.herb.qty}`);
      return out.join("  ");
    }

    function DungeonQuestsModal({ dungeon, onClose, onChanged }) {
      const [reload, setReload] = useState(0);
      const { data, loading, error } = useApi("dungeons/quests", { dungeon_id: dungeon.id }, [reload]);
      const [busyId, setBusyId] = useState(null);
      const [err, setErr] = useState(null);

      const refreshAll = () => {
        setReload(x => x + 1);
        onChanged && onChanged();
      };

      async function callAccept(quest_id) {
        if (busyId) return;
        setBusyId(`accept-${quest_id}`); setErr(null);
        haptic("warning");
        try {
          const res = await api("dungeons/quest_accept", { quest_id });
          if (!res.ok) {
            haptic("error");
            const params = res.cooldown_remaining_hours
              ? { hours: res.cooldown_remaining_hours }
              : {};
            setErr(_translateDungeonQuestReason(res.reason, params));
            setBusyId(null);
            return;
          }
          haptic("success");
          showToast(t("dng_quest_accepted_toast", { name: res.quest_name }));
          refreshAll();
        } catch (e) {
          haptic("error");
          setErr(e.message || t("dng_quest_action_failed"));
        } finally {
          setBusyId(null);
        }
      }

      async function callClaim(quest_id) {
        if (busyId) return;
        setBusyId(`claim-${quest_id}`); setErr(null);
        haptic("warning");
        try {
          const res = await api("dungeons/quest_claim", { quest_id });
          if (!res.ok) {
            haptic("error");
            setErr(_translateDungeonQuestReason(res.reason));
            setBusyId(null);
            return;
          }
          haptic("success");
          const r = res.rewards || {};
          const parts = [];
          if (r.spirit_stones > 0) parts.push(`🪨 +${fmtNum(r.spirit_stones)}`);
          // QoL-Feedback 2026-07-29 Item C: moeda nomeada (🔱 facção) + o
          // crédito pulado dito no MESMO toast (Lei §1).
          if (r.reputation > 0) parts.push(`🔱 +${r.reputation} ${t("dng_quest_rep_faction_short")}`);
          if (r.reputation_missed > 0) parts.push(t("dng_quest_rep_missed_toast", { n: r.reputation_missed }));
          showToast(t("dng_quest_claimed_toast", {
            name: res.quest_name,
            rewards: parts.join(" · "),
          }));
          refreshAll();
        } catch (e) {
          haptic("error");
          setErr(e.message || t("dng_quest_action_failed"));
        } finally {
          setBusyId(null);
        }
      }

      return (
        <Modal open={true} onClose={onClose} accent="var(--gold2)" maxWidth={440}
               title={t("dng_quest_modal_title", { name: dungeon.name })}>
          {loading && !data && <ListSkeleton rows={3} />}
          {error && <ErrBanner msg={error} />}
          {err && <ErrBanner msg={err} />}
          {data && data.quests.length === 0 && (
            <div style={{ textAlign:"center", padding:"24px 0", color:"var(--muted)" }}>
              {t("dng_quest_modal_empty")}
            </div>
          )}
          {data && data.quests.map(q => {
            const pct = q.objective_count > 0
              ? Math.min(100, (q.progress / q.objective_count) * 100)
              : 0;
            const isBusyAcc = busyId === `accept-${q.id}`;
            const isBusyClm = busyId === `claim-${q.id}`;
            return (
              <Card key={q.id} style={{ marginBottom:10, padding:"10px 12px" }}>
                <div style={{ display:"flex", alignItems:"center", gap:8, marginBottom:6 }}>
                  <span style={{ fontSize:20 }}>{q.emoji}</span>
                  <span style={{ flex:1, fontFamily:"'Cinzel',serif", fontSize:13,
                                 fontWeight:700, color:"var(--gold2)" }}>{q.name}</span>
                  {q.status === "claimable" && <Badge variant="jade">{t("dng_quest_st_claimable")}</Badge>}
                  {q.status === "active" && <Badge variant="gold">{t("dng_quest_st_active")}</Badge>}
                  {q.status === "cooldown" && <Badge variant="red">⏳ {q.cooldown_remaining_hours}h</Badge>}
                  {q.status === "pending" && <Badge>{t("dng_quest_st_pending")}</Badge>}
                  {q.status === "ready" && <Badge>{t("dng_quest_st_ready")}</Badge>}
                </div>
                <div style={{ fontSize:11, color:"var(--muted)", marginBottom:6, fontStyle:"italic", lineHeight:1.4 }}>
                  {safeT(q.description_key, null, "")}
                </div>
                <div style={{ fontSize:11, color:"var(--text)", marginBottom:6 }}>
                  🎁 {_dungeonQuestRewards(q, data.has_faction)}
                </div>
                <div style={{ fontSize:10.5, color:"var(--muted)", marginBottom:6 }}>
                  🏆 {t("dng_quest_modal_min_diff", { diff: dngDiffName(q.min_difficulty) })}
                  {q.cooldown_hours > 0 && ` · ⏳ ${q.cooldown_hours}h`}
                </div>
                {q.status === "active" && (
                  <>
                    <ProgressBar pct={pct} variant="cult" height={6} />
                    <div style={{ display:"flex", justifyContent:"space-between", marginTop:3, fontSize:10, color:"var(--muted)" }}>
                      <span>{q.progress} / {q.objective_count}</span>
                      <span>{pct.toFixed(0)}%</span>
                    </div>
                  </>
                )}
                {(q.status === "pending" || q.status === "ready") && (
                  <ActionBtn variant="primary" size="sm" disabled={!!busyId}
                             onClick={() => callAccept(q.id)}
                             style={{ width:"100%", marginTop:6 }}>
                    {isBusyAcc ? <DotSpinner /> : `📜 ${t("dng_quest_modal_accept_btn")}`}
                  </ActionBtn>
                )}
                {q.status === "claimable" && (
                  <ActionBtn variant="primary" size="sm" disabled={!!busyId}
                             onClick={() => callClaim(q.id)}
                             style={{ width:"100%", marginTop:6,
                                      background:"linear-gradient(180deg, rgba(46,196,182,.4), rgba(20,80,70,.6))",
                                      border:"1px solid var(--jade)" }}>
                    {isBusyClm ? <DotSpinner /> : `🎁 ${t("dng_quest_modal_claim_btn")}`}
                  </ActionBtn>
                )}
              </Card>
            );
          })}
        </Modal>
      );
    }

    // ─── v15.1 Turn-Based Duel (Qi Consumption + Simultaneous Rounds) ────────
    // PvP duel with 3-layer Qi (reservoir / active / combat pool), per-round
    // technique submission, sudden-death tiebreaker. Empates impossíveis.
    //
    // Engine: core/duel_engine.py (state machine).
    // Endpoints: combat/duel_{create,submit,state,forfeit}.

    function DuelArenaPanel({ data, player, onChanged }) {
      // Single source of truth: poll combat/duel_state without id every 4s.
      // The server returns the player's most recent open duel (pending or live).
      // Sub-views render based on state + you_side.
      const [duelState, setDuelState] = useState(null); // null = no duel
      const [target, setTarget] = useState("");
      const [busy, setBusy] = useState(false);
      const [errMsg, setErrMsg] = useState(null);
      const [tick, setTick] = useState(0);
      // While idle/awaiting, poll every 4s. While the live modal is open
      // (state === waiting_actions) the modal itself polls at 2s.
      useEffect(() => {
        const isLive = duelState && (duelState.state === "waiting_actions"
                                     || duelState.state === "finished"
                                     || duelState.state === "forfeited");
        if (isLive) return; // modal owns its own polling
        const iv = setInterval(() => setTick(x => x + 1), 4000);
        return () => clearInterval(iv);
      }, [duelState && duelState.state]);

      useEffect(() => {
        let cancelled = false;
        (async () => {
          try {
            const res = await api("combat/duel_state", {});
            if (cancelled) return;
            // ok=true with duel_id=null means no open duel — back to create form.
            if (res.ok && !res.duel_id && duelState && !duelState.duel_id) return;
            if (res.ok && !res.duel_id) { setDuelState(null); return; }
            if (res.ok && res.duel_id) setDuelState(res);
          } catch (e) { /* silent — best-effort polling */ }
        })();
        return () => { cancelled = true; };
      }, [tick]);

      function reasonText(reason, extra) {
        const map = {
          target_not_found:     t("duel_err_target_not_found"),
          cannot_self_challenge:t("duel_err_self"),
          realm_gap_too_large:  t("duel_err_realm_gap", { gap: extra?.max_gap || 3 }),
          hp_depleted:          t("duel_err_hp_depleted"),
          target_hp_depleted:   t("duel_err_target_hp"),
          duel_already_active:  t("duel_err_already_active"),
          invalid_dao_name:     t("duel_err_invalid_name"),
          pvp_sealed:           t("combat_arena_q_err_sealed"),
        };
        if (reason === "internal_error" && extra) {
          return `⚠️ ${extra.error_class || "Error"}: ${extra.error_msg || "?"}`;
        }
        return map[reason] || t("duel_err_generic", { reason: reason || "?" });
      }

      async function createDuel() {
        if (busy) return;
        const name = (target || "").trim();
        if (!name) { setErrMsg(t("duel_err_invalid_name")); return; }
        setBusy(true); setErrMsg(null);
        haptic("warning");
        try {
          const res = await api("combat/duel_create", { target_dao_name: name });
          if (!res.ok) {
            haptic("error");
            if (res.reason === "duel_already_active" && res.duel_id) {
              setTick(x => x + 1); // refresh state
              setBusy(false);
              return;
            }
            setErrMsg(reasonText(res.reason, res));
            setBusy(false);
            return;
          }
          haptic("success");
          setTarget("");
          setBusy(false);
          setTick(x => x + 1); // immediate refresh — will surface pending_acceptance
        } catch (e) {
          haptic("error");
          setErrMsg(e.message || "error");
          setBusy(false);
        }
      }

      async function acceptDuel() {
        if (busy || !duelState) return;
        setBusy(true); setErrMsg(null);
        haptic("warning");
        try {
          const res = await api("combat/duel_accept", { duel_id: duelState.duel_id });
          if (!res.ok) {
            haptic("error");
            setErrMsg(reasonText(res.reason, res));
            setBusy(false);
            return;
          }
          haptic("success");
          setBusy(false);
          setTick(x => x + 1); // poll will pick up waiting_actions → opens modal
        } catch (e) {
          haptic("error");
          setErrMsg(e.message || "error");
          setBusy(false);
        }
      }

      async function declineOrCancel() {
        if (busy || !duelState) return;
        setBusy(true);
        try {
          await api("combat/duel_forfeit", { duel_id: duelState.duel_id });
          haptic("warning");
          setDuelState(null);
          setBusy(false);
        } catch (e) {
          setErrMsg(e.message);
          setBusy(false);
        }
      }

      // ── State 1: live duel (waiting_actions / finished / forfeited) → modal
      if (duelState && (duelState.state === "waiting_actions"
                        || duelState.state === "finished"
                        || duelState.state === "forfeited")) {
        return (
          <DuelArenaModal
            duelId={duelState.duel_id}
            onClose={() => { setDuelState(null); setTick(x => x + 1); onChanged && onChanged(); }}
            playerLang={player?.language}
          />
        );
      }

      // ── State 2: pending acceptance — render attacker or defender view
      if (duelState && duelState.state === "pending_acceptance") {
        const isAttacker = duelState.you_side === "a";
        const opp = duelState.opponent || {};
        return (
          <Card style={{ padding:"13px 14px" }}>
            <div style={{ display:"flex", alignItems:"center", gap:11, marginBottom:12 }}>
              <div style={{ fontSize:28, lineHeight:1,
                            filter: isAttacker
                              ? "drop-shadow(0 0 8px rgba(var(--realm-1-rgb),.55))"
                              : "drop-shadow(0 0 8px rgba(var(--gold2-rgb),.6))" }}>
                {isAttacker ? "⏳" : "⚔️"}
              </div>
              <div style={{ minWidth:0, flex:1 }}>
                <div style={{ fontFamily:"'Cinzel',serif", fontWeight:700, fontSize:14,
                              color: isAttacker ? "#93c5fd" : "var(--gold2)", letterSpacing:.4 }}>
                  {isAttacker
                    ? t("duel_awaiting_title", { name: opp.dao_name || "?" })
                    : t("duel_received_title", { name: opp.dao_name || "?" })}
                </div>
                <div style={{ fontSize:11, color:"var(--muted)", lineHeight:1.4 }}>
                  {isAttacker
                    ? t("duel_awaiting_hint")
                    : t("duel_received_hint")}
                </div>
              </div>
            </div>

            <div style={{
              padding:"10px 12px", borderRadius:10,
              background:"rgba(0,0,0,.35)",
              border: isAttacker
                ? "1px solid rgba(var(--realm-1-rgb),.3)"
                : "1px solid rgba(var(--gold2-rgb),.35)",
              display:"grid", gap:6, marginBottom:12, fontSize:11,
            }}>
              <KVRow label={t("duel_opponent_label")}
                     value={`${opp.dao_name || "?"}`} />
              <KVRow label={t("duel_hp")}
                     value={`${fmtNum(opp.hp || 0)} / ${fmtNum(opp.hp_max || 0)}`} />
              <KVRow label={t("duel_combat_qi")}
                     value={`${fmtNum(opp.combat_qi || 0)} / ${fmtNum(opp.combat_qi_max || 0)}`} />
            </div>

            {errMsg && <div className="err-banner" style={{ marginBottom:8 }}>{errMsg}</div>}

            {isAttacker ? (
              <ActionBtn onClick={declineOrCancel} disabled={busy} variant="ghost">
                {busy ? <DotSpinner /> : `❌ ${t("duel_btn_cancel_challenge")}`}
              </ActionBtn>
            ) : (
              <div style={{ display:"flex", gap:8 }}>
                <ActionBtn onClick={declineOrCancel} disabled={busy}
                           variant="ghost" style={{ flex:1 }}>
                  {busy ? <DotSpinner /> : `❌ ${t("duel_btn_decline")}`}
                </ActionBtn>
                <ActionBtn onClick={acceptDuel} disabled={busy}
                           variant="primary" style={{ flex:1.4 }}>
                  {busy ? <DotSpinner /> : `✅ ${t("duel_btn_accept")}`}
                </ActionBtn>
              </div>
            )}
          </Card>
        );
      }

      // ── State 3: no duel → create form (default)
      return (
        <Card style={{ padding:"13px 14px" }}>
          <div style={{ display:"flex", alignItems:"center", gap:11, marginBottom:10 }}>
            <div style={{ fontSize:28, lineHeight:1,
                          filter:"drop-shadow(0 0 8px rgba(var(--gold2-rgb),.5))" }}>🏟️</div>
            <div style={{ minWidth:0, flex:1 }}>
              <div style={{ fontFamily:"'Cinzel',serif", fontWeight:700, fontSize:14,
                            color:"var(--gold2)", letterSpacing:.4 }}>
                {t("duel_panel_title")}
              </div>
              <div style={{ fontSize:11, color:"var(--muted)", lineHeight:1.4 }}>
                {t("duel_panel_subtitle")}
              </div>
            </div>
          </div>

          <div style={{
            padding:"10px 12px", borderRadius:10,
            background:"rgba(0,0,0,.35)",
            border:"1px solid rgba(var(--gold2-rgb),.25)",
            display:"grid", gap:8, marginBottom:10,
          }}>
            <div style={{ fontSize:10.5, color:"var(--gold3)", letterSpacing:1.2,
                          textTransform:"uppercase", fontFamily:"'Cinzel',serif" }}>
              {t("duel_rules_header")}
            </div>
            <div style={{ fontSize:11, color:"var(--text)", lineHeight:1.5 }}>
              {t("duel_rules_body")}
            </div>
          </div>

          <div style={{ display:"grid", gap:8 }}>
            <label style={{ fontSize:11, color:"var(--muted)" }}>
              {t("duel_target_label")}
            </label>
            <input
              type="text"
              value={target}
              onChange={e => setTarget(e.target.value)}
              placeholder={t("duel_target_placeholder")}
              style={{
                padding:"8px 10px", borderRadius:8,
                background:"rgba(0,0,0,.55)",
                border:"1px solid var(--border)",
                color:"var(--text)", fontSize:13,
                fontFamily:"inherit",
              }}
            />
            {errMsg && <div className="err-banner">{errMsg}</div>}
            <ActionBtn onClick={createDuel} disabled={busy} variant="primary">
              {busy ? <DotSpinner /> : `⚔️ ${t("duel_btn_send_challenge")}`}
            </ActionBtn>
          </div>
        </Card>
      );
    }

    function DuelArenaModal({ duelId, onClose, playerLang, onFim }) {
      // 武 2.2 — O PORTÃO E A LARGURA VIVEM AQUI EM CIMA, E ISSO NÃO É ARRUMAÇÃO.
      //
      // 🔴 A 1ª versão pôs o `useWideShell()` junto do rodapé, ~200 linhas
      // abaixo — depois do `if (!state) return (<Modal>…carregando…</Modal>)`.
      // No 1º render (`state` ainda `null`) o hook NÃO corria; no 2º corria, e o
      // React conta hooks: *"Rendered more hooks than during the previous
      // render"* (#310). O jogador via a faixa **⚠️ Erro nesta seção** no lugar
      // do duelo inteiro.
      //
      // ⚠️ E 986 guardas estavam VERDES por cima disto. Um erro de ORDEM DE
      // HOOKS não é visível a ler o ficheiro nem a contar chamadas; só apareceu
      // a SERVIR E OLHAR (Lei 0, passo 3). Todo hook novo entra antes do
      // primeiro `return`.
      const _cenaOn = obraOn() && typeof CenaDuelo === "function";
      const _cenaWide = typeof useWideShell === "function" ? useWideShell() : false;
      const [state, setState] = useState(null);
      const [errMsg, setErrMsg] = useState(null);
      const [pickTech, setPickTech] = useState(0); // 0 = basic strike
      const [busy, setBusy] = useState(false);
      const [tick, setTick] = useState(0);
      // v15.1b — 1s ticker for the round countdown clock. Independent of the
      // server poll (2s) so the timer reads smooth instead of jumpy.
      const [nowMs, setNowMs] = useState(Date.now());
      useEffect(() => {
        const iv = setInterval(() => setNowMs(Date.now()), 1000);
        return () => clearInterval(iv);
      }, []);

      // Poll every 2s while waiting for actions; stop polling once finished.
      useEffect(() => {
        if (state && state.state !== "waiting_actions") return;
        const iv = setInterval(() => setTick(x => x + 1), 2000);
        return () => clearInterval(iv);
      }, [state && state.state]);

      // Fetch state on tick.
      // Owner report 2026-05-25: HTTP 502 banner stayed pinned in the modal
      // after a duel resolved (Victory shown + scary "HTTP 502" alongside).
      // Root cause: cultivation_tick saturating the event loop → Coolify proxy
      // timeouts → a single failed poll set errMsg permanently. Fix: clear
      // errMsg on every successful state fetch so transient proxy 502s recover
      // silently when the next 2s poll succeeds.
      useEffect(() => {
        let cancelled = false;
        (async () => {
          try {
            const res = await api("combat/duel_state", { duel_id: duelId });
            if (cancelled) return;
            if (res.ok === false) { setErrMsg(res.reason || "error"); return; }
            setState(res);
            setErrMsg(null);
          } catch (e) {
            if (!cancelled) setErrMsg(e.message);
          }
        })();
        return () => { cancelled = true; };
      }, [duelId, tick]);

      // Compute remaining seconds in this round (clamped to 0).
      const expiresMs = state && state.expires_at ? Date.parse(state.expires_at) : 0;
      const remainingSec = expiresMs ? Math.max(0, Math.ceil((expiresMs - nowMs) / 1000)) : null;

      // v15.1b — auto-submit when the clock hits 0 if the player hasn't acted.
      // Defensive: server also auto-resolves on next poll, this just keeps the
      // UI in sync immediately so we don't flash "waiting" after the clock dies.
      const youPending = state && state.you && state.you.pending;
      useEffect(() => {
        if (!state || state.state !== "waiting_actions") return;
        if (youPending) return; // already submitted
        if (remainingSec === null || remainingSec > 0) return;
        if (busy) return;
        // Fire auto-submit (basic strike + balanced). Ignore errors — server
        // will also resolve via timeout on its own poll cycle.
        (async () => {
          try {
            await api("combat/duel_submit", {
              duel_id: duelId, technique_id: 0,
            });
            setTick(x => x + 1);
          } catch (e) { /* silent — server timeout will catch up */ }
        })();
      }, [remainingSec, youPending, state && state.state]);

      // 層 4.3 — quem abriu o duelo do CHEFE recebe o fim confirmado (o
      // `masmorra_ganho` vem no `duel_state`, gravado pelo settle). ⚠️ Hook ANTES
      // do 1.º `return` (React #310 — a lição do `useWideShell` aqui mesmo). Uma
      // vez por duelo; sem `onFim` (todos os outros duelos) não faz nada.
      const _fimDado = useRef(false);
      useEffect(() => {
        if (!onFim || !state || _fimDado.current) return;
        if (state.state === "finished" || state.state === "forfeited") {
          _fimDado.current = true;
          try { onFim(state); } catch (e) { /* quem chama nunca parte o duelo */ }
        }
      }, [state, onFim]);

      async function submit() {
        if (busy) return;
        // ⚠️ A MESMA regra, recomputada do `state` no instante do envio. Nao
        // basta ler o `pickEfetivo` do render: entre o desenho e o toque pode
        // ter entrado um poll com qi novo, e o que sai daqui tem de ser sempre
        // pagavel. As duas derivacoes concordam por construcao (mesma conta).
        const _y = (state && state.you) || {};
        const _ts = (_y.techniques || []).filter(tt => !!tt && tt.qi_cost !== undefined);
        const _envio = (pickTech !== 0
                        && !_ts.some(tt => tt.id === pickTech
                                           && (_y.combat_qi || 0) >= (tt.qi_cost || 0)))
          ? 0 : pickTech;
        setBusy(true); setErrMsg(null);
        haptic("warning");
        try {
          const res = await api("combat/duel_submit", {
            duel_id: duelId, technique_id: _envio,
          });
          if (!res.ok) {
            haptic("error");
            setErrMsg(safeT("duel_err_submit_" + (res.reason || "generic"), {}, t("duel_err_generic", { reason: res.reason || "error" })));
            setBusy(false);
            return;
          }
          haptic("success");
          setTick(x => x + 1); // refresh immediately
          setBusy(false);
        } catch (e) {
          haptic("error");
          setErrMsg(e.message);
          setBusy(false);
        }
      }

      async function forfeit() {
        if (busy) return;
        if (!confirm(t("duel_confirm_forfeit"))) return;
        setBusy(true);
        try {
          await api("combat/duel_forfeit", { duel_id: duelId });
          haptic("warning");
          setTick(x => x + 1);
          setBusy(false);
        } catch (e) {
          setErrMsg(e.message);
          setBusy(false);
        }
      }

      if (!state) {
        return (
          <Modal open onClose={onClose} title={`🏟️ ${t("duel_arena_title")}`}
                 accent="rgba(var(--gold2-rgb),.55)" maxWidth={460}>
            <div style={{ padding:"22px 0", textAlign:"center", color:"var(--muted)" }}>
              {errMsg ? <div className="err-banner">{errMsg}</div> : (
                <><DotSpinner /><div style={{ marginTop:8, fontSize:12 }}>{t("duel_loading")}</div></>
              )}
            </div>
          </Modal>
        );
      }

      const you = state.you || {};
      const opp = state.opponent || {};
      const finished = state.state === "finished" || state.state === "forfeited";
      const youWon = finished && state.winner_id === you.telegram_id;
      const youSubmitted = !!you.pending;
      const oppSubmitted = !!opp.submitted;
      const techs = (you.techniques || []).filter(tt => !!tt && tt.qi_cost !== undefined);
      // 🔴 O QUE SE VE E' O QUE SE ENVIA (item 6 da auditoria do Astra).
      // `pickTech` persiste entre rondas; o qi nao. Uma tecnica escolhida na
      // ronda anterior pode ter deixado de ser pagavel nesta — a carta dela fica
      // vermelha e desactivada, e o envio mandava-a na mesma.
      // ⚠️ DERIVADO no render, nunca guardado: assim a carta do golpe basico
      // ja' esta' acesa quando o jogador carrega, e ele envia o que esta' a ver.
      // Um `setPickTech(0)` dentro de um efeito daria um frame com a escolha
      // velha ainda acesa — que e' exactamente o instante em que se carrega.
      const _pickCaiu = pickTech !== 0
        && !techs.some(tt => tt.id === pickTech && (you.combat_qi || 0) >= (tt.qi_cost || 0));
      const pickEfetivo = _pickCaiu ? 0 : pickTech;

      // Footer renders submit/forfeit while live, close when finished.
      // ⚠️ COM A CENA, o *enviar* muda de casa: ele é a faixa de CONFIRMAÇÃO da
      // cena (*"resumo 'arte · custo'; botão de 52px, confirmação explícita"*), e
      // deixar uma segunda cópia no pé punha DOIS botões de enviar no mesmo
      // ecrã — que é a duplicação que a chegada matou a 16/09. O pé fica com a
      // rendção, que é uma saída e não uma jogada, e conserva a confirmação
      // própria dela.
      const footer = finished ? (
        /* ⚠️ O FIM TAMBÉM LEVA A PELE DA CENA. Um botão azul do painel antigo
           debaixo de uma cena de tinta é a inconsistência que a Lei 0 diz ser
           pior do que a ausência — e era o que ficava no pé depois da
           vítória. Mesmo componente, ramo `acabou`. */
        _cenaOn ? (
          <CenaConfirmacao acabou onFechar={onClose} />
        ) : (
        <div style={{ display:"flex", gap:8 }}>
          <ActionBtn onClick={onClose} variant="primary" style={{ flex:1 }}>
            {t("btn_close")}
          </ActionBtn>
        </div>
        )
      ) : _cenaOn ? (
        /* 🔴 A FAIXA DE CONFIRMAÇÃO É O RODAPÉ — corrigido a OLHAR.
           A 1a versão deixou-a no corpo da cena, que ROLA: fixo no pé ficava
           **Render** e o golpe caia abaixo da dobra. Aqui ela está sempre à
           vista, com o resumo "arte · custo" por cima do alvo de 52px, e a
           rendção ao lado — uma saída, nunca uma jogada. */
        <CenaConfirmacao
          resumo={(() => {
            const e = cenaEscolha(state, pickEfetivo);
            return t("cena_confirmar", { tec: e.nome, custo: e.custo });
          })()}
          enviado={youSubmitted} busy={busy}
          onConfirmar={submit} onRender={forfeit} />
      ) : (
        <div style={{ display:"flex", gap:8 }}>
          <ActionBtn onClick={forfeit} variant="ghost" style={{ flex:1 }} disabled={busy}>
            🏳️ {t("duel_btn_forfeit")}
          </ActionBtn>
          <ActionBtn onClick={submit} variant="primary" style={{ flex:1.6 }}
                     disabled={busy || youSubmitted}>
            {busy ? <DotSpinner />
                  : youSubmitted ? `⏳ ${t("duel_waiting_opp")}`
                  : `⚔️ ${t("duel_btn_submit")}`}
          </ActionBtn>
        </div>
      );

      function bar(value, max, color, label) {
        const pct = max > 0 ? Math.max(0, Math.min(100, (value / max) * 100)) : 0;
        return (
          <div>
            <div style={{ display:"flex", justifyContent:"space-between", marginBottom:3 }}>
              <span style={{ fontSize:9.5, color:"var(--muted)",
                             fontFamily:"'Cinzel',serif", letterSpacing:.4, textTransform:"uppercase" }}>
                {label}
              </span>
              <span style={{ fontSize:10, color:"var(--text)", fontWeight:600 }}>
                {fmtNum(value)} / {fmtNum(max)}
              </span>
            </div>
            <div style={{ height:6, borderRadius:3, background:"rgba(0,0,0,.55)", overflow:"hidden" }}>
              <div style={{ width:`${pct}%`, height:"100%",
                            background:color, transition:"width .4s ease" }} />
            </div>
          </div>
        );
      }

      const subtitleParts = [];
      subtitleParts.push(t("duel_round_label", { round: state.round_idx, max: state.max_rounds }));
      if (state.sudden_death) subtitleParts.push(`⚡ ${t("duel_sudden_death")}`);
      // v15.1.4 — PvE mode chip (NPC Hunt or Dungeon Boss). Lets the
      // player see at a glance that this is AI combat, not a real
      // cultivator across the table.
      if (state.pve) {
        const isBoss = state.pve_source === "dungeon_boss";
        subtitleParts.push(
          isBoss
            ? `👑 ${safeT("duel_pve_boss_label", {}, "Boss")}`
            : `🤖 ${safeT("duel_pve_npc_label", {}, "NPC")}`
        );
      }
      // v15.1b — round countdown clock. Hidden when finished/forfeited.
      if (remainingSec !== null && (state.state === "waiting_actions")) {
        const urgent = remainingSec <= 5;
        subtitleParts.push(
          `${urgent ? "⏰" : "⏱️"} ${remainingSec}s`
        );
      }

      // v15.1.4 — title varies by PvE source so the modal looks
      // distinct between PvP, NPC Hunt, and Dungeon Boss.
      const modalTitle = state.pve
        ? (state.pve_source === "dungeon_boss"
            ? `👑 ${safeT("duel_boss_arena_title", {}, t("duel_arena_title"))}`
            : `🤖 ${safeT("duel_pve_arena_title", {}, t("duel_arena_title"))}`)
        : `🏟️ ${t("duel_arena_title")}`;

      // 武 2.2 — O RESULTADO, EXTRAÍDO PARA UMA VARIÁVEL E NÃO REESCRITO.
      //
      // 🔴 ESTE BLOCO É O MAIS CARO DO DUELO e por isso ele sai daqui
      // **intacto**, byte a byte, em vez de ser redesenhado. São as QUATRO
      // consequências condicionais que lotes anteriores pagaram a descobrir:
      // o espólio da gruta (QoL 31/07, era MUDO no mini), o Tributo da Terra do
      // chefe (QoL 04/08, rolava no settle e ninguém o dizia), o Rito do
      // Coração-Demônio e o preço do Caminho Proibido (TEC-5, karma + anos com
      // antes→depois).
      //
      // ⚠️ Cada uma é uma key CONDICIONAL do `duel_state`. Redesenhar a cena a
      // partir do zero é exactamente como se perdem — e a lição está escrita:
      // *"o resultado conserva todas as consequências existentes, inclusive as
      // específicas de gruta, tributo, coração-demônio e custo proibido; não o
      // reduzir a um painel genérico de moedas"*. A cena recebe-o por `prop`.
      const blocoResultado = (
        <>
        {/* Finished result banner */}
        {finished && (
          <div style={{
            padding:"14px 12px", borderRadius:12,
            background: youWon
              ? "linear-gradient(180deg,rgba(34,80,52,.92),rgba(8,30,18,.96))"
              : "linear-gradient(180deg,rgba(80,18,18,.92),rgba(30,4,4,.96))",
            border: youWon
              ? "1px solid rgba(134,239,172,.5)"
              : "1px solid rgba(var(--red2-rgb),.5)",
            textAlign:"center",
          }}>
            <div style={{ fontSize:36, marginBottom:4 }}>{youWon ? "🌟" : "💀"}</div>
            <div style={{ fontFamily:"'Cinzel',serif", fontSize:15, fontWeight:700,
                          color: youWon ? "#86efac" : "var(--red2)",
                          letterSpacing:.8 }}>
              {youWon ? t("duel_outcome_win") : t("duel_outcome_loss")}
            </div>
            <div style={{ marginTop:6, fontSize:11.5, color:"var(--text)", lineHeight:1.55 }}>
              {state.state === "forfeited"
                ? t("duel_outcome_forfeit_note")
                : t("duel_outcome_summary", { rounds: state.round_idx })}
            </div>
            {/* QoL 31/07 (dívida TEC-4) — o espólio da gruta era MUDO no mini.
                legacy_cave_result é key CONDICIONAL do duel_state: só chega
                para pve_source="legacy_cave" com settle carimbado. */}
            {state.legacy_cave_result && (() => {
              const lc = state.legacy_cave_result;
              const lines = [];
              if (lc.cave === "won") {
                if (lc.stones) lines.push(t("lgc_mini_won_stones", { stones: fmtNum(lc.stones) }));
                if (lc.materials && lc.materials.length) lines.push(t("lgc_mini_won_mat"));
                if (lc.bag_full) lines.push(t("lgc_mini_won_bagfull"));
                if (lc.dao_fragments) lines.push(t("lgc_mini_won_frag", { n: lc.dao_fragments }));
                if (lc.art) lines.push(t("lgc_mini_won_art", { emoji: lc.art.emoji || "", name: lc.art.name || "" }));
                else if (lc.already_has_art) lines.push(t("lgc_mini_won_dupe"));
                else if (lc.art_missed) lines.push(t("lgc_mini_won_missed", {
                  clears: lc.art_missed.clears, pity: lc.art_missed.pity_at }));
                // TEC-5 — "A Noite de Sangue viu você": key CONDICIONAL que
                // só chega a quem atravessou o Rito e venceu NA tumba dela.
                if (lc.xueye_notice) lines.push(t("fpd_mini_xueye_seen"));
              } else if (lc.cave === "lost") {
                lines.push(t("lgc_mini_lost_try"));
              }
              if (!lines.length) return null;
              return (
                <div style={{ marginTop:10, padding:"9px 11px", borderRadius:9, textAlign:"left",
                              background:"rgba(var(--gold-rgb),.10)", border:"1px solid rgba(var(--gold2-rgb),.35)" }}>
                  <div style={{ fontSize:10.5, fontFamily:"'Cinzel',serif", color:"var(--gold3)",
                                letterSpacing:1.1, textTransform:"uppercase", marginBottom:5 }}>
                    {t("lgc_mini_loot_title")}
                  </div>
                  {lines.map((ln, i) => (
                    <div key={i} style={{ fontSize:11.5, color:"var(--text)", lineHeight:1.5 }}>{ln}</div>
                  ))}
                </div>
              );
            })()}
            {/* QoL 04/08 (report [jogador]) — o Tributo da Terra do CHEFE: até aqui
                ele rolava no settle e NINGUÉM o dizia. Key condicional. */}
            {state.tribute_line && (
              <div style={{ marginTop:10, padding:"9px 11px", borderRadius:9, textAlign:"left",
                            background:"rgba(var(--jade-rgb),.08)", border:"1px solid rgba(var(--jade-rgb),.3)" }}>
                <div style={{ fontSize:11.5, color:"var(--jade)", lineHeight:1.5 }}>
                  {state.tribute_line}
                </div>
              </div>
            )}
            {/* 道 07/10 (report do [jogador]: "setting default attack for PvE arena,
                does not increase relevant path experience") — SUBIA (+18 por
                duelo de arena: 3 por golpe que acerta + 15 de vitória ao caminho
                dominante), mas nenhum ecrã o dizia. Agora o fim da luta diz o
                que cada caminho ganhou, com antes→depois e o denominador do
                SERVIDOR. Key CONDICIONAL do duel_state (só com a onda, só PvE). */}
            {Array.isArray(state.caminho_ganho) && state.caminho_ganho.length > 0 && (
              <div data-caminho-ganho=""
                   style={{ marginTop:10, padding:"9px 11px", borderRadius:9, textAlign:"left",
                            background:"rgba(var(--gold-rgb),.08)", border:"1px solid rgba(var(--gold2-rgb),.3)" }}>
                <div style={{ fontSize:10.5, fontFamily:"'Cinzel',serif", color:"var(--gold3)",
                              letterSpacing:1.1, textTransform:"uppercase", marginBottom:5 }}>
                  {t("caminho_ganho_titulo")}
                </div>
                {state.caminho_ganho.map(cg => {
                  const nome = safeT("intent_name_" + cg.intent);
                  const d = cg.depois || {}, a = cg.antes || {};
                  return (
                    <div key={cg.intent} style={{ fontSize:11.5, color:"var(--text)", lineHeight:1.5 }}>
                      {cg.subiu
                        ? t("caminho_ganho_subiu", { nome, xp: fmtFull(cg.xp), a: a.rank, b: d.rank })
                        : !(d.curva > 0)
                          ? t("caminho_ganho_max", { nome, xp: fmtFull(cg.xp) })
                          : t("caminho_ganho_linha", { nome, xp: fmtFull(cg.xp), a: fmtFull(a.xp),
                                                       b: fmtFull(d.xp), curva: fmtFull(d.curva) })}
                    </div>
                  );
                })}
              </div>
            )}
            {/* TEC-5 — o Rito do Coração-Demônio: vencer NÃO decide (a escolha
                vive no KarmaModal); perder MORDE a alma, e o número tem de
                aparecer aqui com antes→depois (Lei §10). Key condicional. */}
            {state.heart_demon_result && (() => {
              const hd = state.heart_demon_result;
              if (hd.hd === "won") {
                return (
                  <div style={{ marginTop:10, padding:"9px 11px", borderRadius:9, textAlign:"left",
                                background:"rgba(var(--red-rgb),.10)", border:"1px solid rgba(var(--red-rgb),.35)" }}>
                    <div style={{ fontSize:11.5, color:"var(--text)", lineHeight:1.5 }}>
                      {hd.target_path
                        ? t("fpd_mini_duel_won", { target: t("fpd_path_" + hd.target_path) })
                        : t("fpd_mini_duel_won_deep")}
                    </div>
                  </div>
                );
              }
              if (hd.hd === "lost" && hd.soul_lost) {
                return (
                  <div style={{ marginTop:10, padding:"9px 11px", borderRadius:9, textAlign:"left",
                                background:"rgba(var(--red-rgb),.10)", border:"1px solid rgba(var(--red-rgb),.35)" }}>
                    <div style={{ fontSize:11.5, color:"var(--red2)", lineHeight:1.5 }}>
                      {t("fpd_mini_duel_lost", { soul: fmtNum(hd.soul_lost),
                                                 before: fmtNum(hd.soul_before), after: fmtNum(hd.soul_after) })}
                    </div>
                  </div>
                );
              }
              return null;
            })()}
            {/* TEC-5 — o preço do poder proibido, cobrado no settle e DITO
                aqui (karma + anos, antes→depois). Chega em QUALQUER duelo
                (arena/PvP/PvE) pelo marker `fpd_cost` — key condicional. */}
            {state.forbidden_cost && (() => {
              const fc = state.forbidden_cost;
              return (
                <div style={{ marginTop:10, padding:"9px 11px", borderRadius:9, textAlign:"left",
                              background:"rgba(120,20,20,.18)", border:"1px solid rgba(var(--red-rgb),.45)" }}>
                  <div style={{ fontSize:10.5, fontFamily:"'Cinzel',serif", color:"#e5a0a0",
                                letterSpacing:1.1, textTransform:"uppercase", marginBottom:5 }}>
                    ☠️ {t("fpd_mini_cost_title")}
                  </div>
                  <div style={{ fontSize:11.5, color:"var(--text)", lineHeight:1.5 }}>
                    {t("fpd_mini_cost_karma", { uses: fc.uses, karma: Math.abs(fc.karma_delta || 0),
                                                before: fmtNum(fc.karma_before), after: fmtNum(fc.karma_after) })}
                  </div>
                  {!fc.immortal && fc.years_burned > 0 && (
                    <div style={{ fontSize:11.5, color:"var(--red2)", lineHeight:1.5 }}>
                      {t("fpd_mini_cost_years", { years: fmtNum(fc.years_burned),
                                                  before: fmtNum(fc.age_before), after: fmtNum(fc.age_after),
                                                  ceiling: fmtNum(fc.ceiling) })}
                    </div>
                  )}
                  {fc.exhausted && (
                    <div style={{ fontSize:10.5, color:"var(--red2)", fontStyle:"italic", marginTop:4 }}>
                      {t("fpd_mini_cost_exhausted")}
                    </div>
                  )}
                </div>
              );
            })()}
          </div>
        )}
        </>
      );
      return (
        <Modal
          open
          onClose={onClose}
          allowBackdropClose={finished}
          title={modalTitle}
          subtitle={subtitleParts.join(" · ")}
          accent={state.sudden_death ? "rgba(239,68,68,.7)" : "rgba(var(--gold2-rgb),.55)"}
          maxWidth={500}
          footer={footer}
          cardStyle={{
            background: state.sudden_death
              ? "linear-gradient(180deg,rgba(55,14,14,.96),rgba(20,4,4,.99))"
              : "linear-gradient(180deg,rgba(28,18,55,.96),rgba(10,6,22,.99))",
            boxShadow: state.sudden_death
              ? "0 20px 60px rgba(0,0,0,.7), 0 0 32px rgba(239,68,68,.32)"
              : "0 20px 60px rgba(0,0,0,.7), 0 0 32px rgba(var(--gold2-rgb),.28)",
          }}
        >
          {/* 武 2.2 — A CENA, ou o de hoje. Com o portão OFF o ramo de baixo é
              o markup de sempre, linha a linha — a promessa aos jogadores do
              `main` (regra §4.5 de `A_CHEGADA.md`: OFF ⇒ byte-idêntico).
              ⚠️ Tudo o que a cena mostra entra por `prop`. O relógio, o envio,
              a rendção, o `pickEfetivo` que CAI quando o qi não paga e as quatro
              consequências condicionais do fim continuam a ser deste modal, que
              é o dono do estado — a mesma lei da `ChegadaCena`. */}
          {_cenaOn ? (
            <CenaDuelo
              state={state}
              remaining={(remainingSec !== null && state.state === "waiting_actions")
                         ? remainingSec : null}
              pick={pickEfetivo}
              caiu={_pickCaiu}
              onEscolher={(id) => { haptic("select"); setPickTech(id); }}
              onConfirmar={submit}
              busy={busy}
              enviado={youSubmitted}
              wide={_cenaWide}
              resultado={blocoResultado}
              aviso={errMsg ? <div className="err-banner">{errMsg}</div> : null}
            />
          ) : (
          <div style={{ display:"grid", gridTemplateColumns:"minmax(0, 1fr)", gap:14 }}>
            {/* Opponent header */}
            <div style={{
              padding:"10px 12px", borderRadius:10,
              background:"rgba(40,12,12,.45)",
              border:"1px solid rgba(239,68,68,.35)",
              display:"grid", gap:6,
            }}>
              <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between" }}>
                <span style={{ fontFamily:"'Cinzel',serif", fontWeight:700, fontSize:13,
                               color:"var(--red2)" }}>
                  ⚔️ {opp.dao_name || "?"}
                </span>
                {/* v15.3-hf — Hide stale "choosing/ready" badges when the duel
                    is finished. Owner bug report: post-victory modal kept
                    showing "A escolher…" next to opponent's name, even with
                    the Victory banner below. Confusing the player into
                    thinking the duel was still live. */}
                {!finished && (
                  <span style={{ fontSize:10.5, fontWeight:700, padding:"2px 7px",
                                 borderRadius:99, background:"rgba(0,0,0,.4)",
                                 border:"1px solid rgba(239,68,68,.4)",
                                 color: oppSubmitted ? "#86efac" : "var(--muted)" }}>
                    {oppSubmitted ? t("duel_opp_ready") : t("duel_opp_choosing")}
                  </span>
                )}
              </div>
              {bar(opp.hp, opp.hp_max, "linear-gradient(90deg,#7f1d1d,#ef4444,var(--warn))", `❤️ ${t("duel_hp")}`)}
              {bar(opp.combat_qi, opp.combat_qi_max, "linear-gradient(90deg,#3b0764,#7c3aed,#a78bfa)", `⚡ ${t("duel_combat_qi")}`)}
            </div>

            {/* v15.1b — Round countdown clock (prominent, urgent when ≤ 5s) */}
            {remainingSec !== null && state.state === "waiting_actions" && !finished && (
              <div style={{
                padding:"8px 12px", borderRadius:10,
                background: remainingSec <= 5
                  ? "linear-gradient(90deg,rgba(127,29,29,.6),rgba(239,68,68,.45),rgba(127,29,29,.6))"
                  : "rgba(0,0,0,.4)",
                border: remainingSec <= 5
                  ? "1px solid rgba(239,68,68,.8)"
                  : "1px solid rgba(var(--gold2-rgb),.35)",
                display:"flex", alignItems:"center", justifyContent:"center", gap:8,
                fontFamily:"'Cinzel',serif", fontWeight:700,
                fontSize: remainingSec <= 5 ? 16 : 13,
                color: remainingSec <= 5 ? "#fecaca" : "var(--gold2)",
                letterSpacing:.6,
                transition:"all .25s ease",
              }}>
                <span style={{ fontSize: remainingSec <= 5 ? 20 : 16 }}>
                  {remainingSec <= 5 ? "⏰" : "⏱️"}
                </span>
                <span>{remainingSec}s</span>
                {!youPending && remainingSec <= 5 && (
                  <span style={{ fontSize:10, color:"var(--red2)", fontWeight:400,
                                 marginLeft:6, fontFamily:"inherit" }}>
                    {t("duel_auto_hint")}
                  </span>
                )}
              </div>
            )}

            {/* Your stats */}
            <div style={{
              padding:"10px 12px", borderRadius:10,
              background:"rgba(12,30,48,.5)",
              border:"1px solid rgba(var(--realm-1-rgb),.35)",
              display:"grid", gap:6,
            }}>
              <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between" }}>
                <span style={{ fontFamily:"'Cinzel',serif", fontWeight:700, fontSize:13,
                               color:"#93c5fd" }}>
                  🧘 {you.dao_name || "?"}
                </span>
                {/* v15.3-hf — Same fix as opponent badge — hide when finished. */}
                {!finished && (
                  <span style={{ fontSize:10.5, fontWeight:700, padding:"2px 7px",
                                 borderRadius:99, background:"rgba(0,0,0,.4)",
                                 border:"1px solid rgba(var(--realm-1-rgb),.4)",
                                 color: youSubmitted ? "#86efac" : "var(--muted)" }}>
                    {youSubmitted ? t("duel_you_ready") : t("duel_you_choosing")}
                  </span>
                )}
              </div>
              {bar(you.hp, you.hp_max, "linear-gradient(90deg,#065f46,#10b981,#86efac)", `❤️ ${t("duel_hp")}`)}
              {bar(you.combat_qi, you.combat_qi_max, "linear-gradient(90deg,#3b0764,#7c3aed,#a78bfa)", `⚡ ${t("duel_combat_qi")}`)}
            </div>

            {blocoResultado}
            {/* Action picker — hidden when finished */}
            {!finished && (
              <>
                <div style={{ display:"grid", gap:6 }}>
                  <div style={{ fontSize:10.5, color:"var(--gold3)", letterSpacing:1.2,
                                textTransform:"uppercase", fontFamily:"'Cinzel',serif" }}>
                    {t("duel_pick_technique")}
                  </div>
                  {/* 🔴 A escolha CAIU, e a tela diz porquê. Sem esta linha o
                      jogador vê o golpe básico aceso sem nunca o ter escolhido
                      — e "mudou sozinho" é pior do que "mudou e disse". */}
                  {_pickCaiu && (
                    <div style={{ fontSize:11, lineHeight:1.45, color:"var(--gold3)",
                                  marginBottom:6 }}>
                      {t("duel_tech_dropped")}
                    </div>
                  )}
                  <div style={{ display:"grid", gap:6 }}>
                    {/* Basic strike — always available, 0 qi */}
                    <button
                      onClick={() => { haptic("select"); setPickTech(0); }}
                      style={{
                        textAlign:"left", padding:"8px 11px", borderRadius:8,
                        border: pickEfetivo === 0
                          ? "1px solid rgba(var(--gold2-rgb),.7)"
                          : "1px solid var(--border)",
                        background: pickEfetivo === 0
                          ? "rgba(var(--gold2-rgb),.1)"
                          : "rgba(0,0,0,.3)",
                        color:"var(--text)", cursor:"pointer",
                        display:"flex", justifyContent:"space-between", alignItems:"center", gap:8,
                      }}>
                      <span style={{ fontSize:12 }}>👊 {t("duel_tech_basic")}</span>
                      <span style={{ fontSize:10, color:"var(--muted)" }}>0 ⚡</span>
                    </button>
                    {techs.map(tt => {
                      const affordable = you.combat_qi >= (tt.qi_cost || 0);
                      const selected = pickEfetivo === tt.id;
                      return (
                        <button key={tt.id}
                          disabled={!affordable}
                          onClick={() => { if (affordable) { haptic("select"); setPickTech(tt.id); } }}
                          style={{
                            textAlign:"left", padding:"8px 11px", borderRadius:8,
                            border: selected
                              ? "1px solid rgba(var(--gold2-rgb),.7)"
                              : !affordable
                                ? "1px solid rgba(239,68,68,.35)"
                                : "1px solid var(--border)",
                            background: selected
                              ? "rgba(var(--gold2-rgb),.1)"
                              : "rgba(0,0,0,.3)",
                            color: affordable ? "var(--text)" : "var(--muted)",
                            cursor: affordable ? "pointer" : "not-allowed",
                            opacity: affordable ? 1 : 0.55,
                            display:"flex", justifyContent:"space-between", alignItems:"center", gap:8,
                          }}>
                          <span style={{ fontSize:12 }}>
                            {tt.emoji || "⚔️"} {tt.name}
                          </span>
                          <span style={{ fontSize:10,
                                         color: affordable ? "#a78bfa" : "var(--red)" }}>
                            {tt.qi_cost || 0} ⚡
                          </span>
                        </button>
                      );
                    })}
                  </div>
                </div>
              </>
            )}

            {/* Action log — last 3 entries */}
            {(state.action_log || []).length > 0 && (
              <div style={{
                padding:"10px 12px", borderRadius:10,
                background:"rgba(0,0,0,.35)",
                border:"1px solid var(--border)",
                display:"grid", gap:5, fontSize:10.5,
              }}>
                <div style={{ fontSize:10, color:"var(--gold3)", letterSpacing:1.2,
                              textTransform:"uppercase", fontFamily:"'Cinzel',serif" }}>
                  {t("duel_log_header")}
                </div>
                {(state.action_log || []).slice(-3).map((entry, idx) => {
                  if (entry.type === "sudden_death_start") {
                    return <div key={idx} style={{ color:"var(--red2)" }}>
                      ⚡ {t("duel_log_sudden_death", { round: entry.round })}
                    </div>;
                  }
                  if (entry.type === "tiebreak") {
                    // v16.4 fix — distinguish HP-advantage win from a true luck tie.
                    return <div key={idx} style={{ color:"var(--gold3)" }}>
                      ⚖️ {t(entry.tiebreak === "hp" ? "duel_log_tiebreak_hp" : "duel_log_tiebreak")}
                    </div>;
                  }
                  if (entry.type === "forfeit") {
                    return <div key={idx} style={{ color:"var(--muted)" }}>
                      🏳️ {t("duel_log_forfeit")}
                    </div>;
                  }
                  if (entry.round && entry.a && entry.b) {
                    const youKey = state.you_side === "a" ? "a" : "b";
                    const oppKey = youKey === "a" ? "b" : "a";
                    const youAction = entry[youKey];
                    const oppAction = entry[oppKey];
                    return (
                      <div key={idx} style={{ display:"grid", gap:2 }}>
                        <div style={{ color:"var(--gold3)", fontWeight:600 }}>
                          {t("duel_log_round", { round: entry.round })}
                        </div>
                        <div style={{ color:"var(--text)" }}>
                          🧘 {youAction.tech ? `${youAction.tech.emoji} ${youAction.tech.name}` : t("duel_tech_basic")}
                          {" → "}
                          {youAction.evaded ? t("duel_log_evaded")
                            : youAction.dodged ? t("duel_log_dodged")
                            : `${fmtNum(youAction.damage)} dmg`}
                        </div>
                        {/* v15.2 — Intent matchup chip for the player swing this round */}
                        {youAction.intent && youAction.intent.attacker_intent && youAction.intent.defender_intent && (
                          <IntentMatchupChip info={youAction.intent} />
                        )}
                        <div style={{ color:"var(--red2)" }}>
                          ⚔️ {oppAction.tech ? `${oppAction.tech.emoji} ${oppAction.tech.name}` : t("duel_tech_basic")}
                          {" → "}
                          {oppAction.evaded ? t("duel_log_evaded")
                            : oppAction.dodged ? t("duel_log_dodged")
                            : `${fmtNum(oppAction.damage)} dmg`}
                        </div>
                        {oppAction.intent && oppAction.intent.attacker_intent && oppAction.intent.defender_intent && (
                          <IntentMatchupChip info={oppAction.intent} opp />
                        )}
                      </div>
                    );
                  }
                  return null;
                })}
              </div>
            )}

            {errMsg && <div className="err-banner">{errMsg}</div>}
          </div>
          )}
        </Modal>
      );
    }

    // ─── MA-39 Mercado Tab (Sprint v14.12) ───────────────────────────────────
    // Drill-in via Home card 💰 (not in BottomNav). 3 modes via SegControl:
    //   "browse" — global active listings + filters + buy/bid
    //   "mine"   — your own active listings + cancel
    //   "sell"   — sell wizard (category → instance → price/qty → mode/duration)
    // Engine in core/economy.py is source-of-truth — endpoints just shape JSON.
    //
    // CLAUDE.md rule: never use `compact={true}` on dynamic-content modals.
    // The sub-modals (Buy / Bid / SellWizard) all use the canonical `<Modal>`
    // with default sizing — they have list content that grows with player
    // inventory, so compact would cause iOS WebKit body collapse (HF v14.10).
    var _MKT_TYPE_ICON = { herb:"🌿", pill:"💊", ore:"🪨", artifact:"⚔️", cauldron:"⚗️" };

    // ─── P2P Trade (MA-39a 2026-06-13) ──────────────────────────────────────
    // Canonical mini-app surface for the chat /trocar wizard. TradeModal is
    // lifted to the App root (app.js tradeId state) so the Telegram back button
    // closes it (memory feedback-miniapp-nav-state-loss). Items are escrowed
    // server-side on add (core/economy + webserver api_trade_add_item); any
    // mutation resets BOTH confirmations (anti bait-and-switch). Jade NEVER
    // enters a trade (Lei §4) — only items + spirit stones.

    // Map a server `reason` code → a localized message (graceful generic fallback).
    function tradeReason(reason) {
      const key = "trade_reason_" + (reason || "generic");
      const s = t(key);
      return s === key ? t("trade_reason_generic") : s;
    }

    var _TRADE_CAT_ICON = { herb:"🌿", pill:"💊", ore:"🪨", artifact:"⚔️", cauldron:"⚗️" };

    // Sub-modal: pick one inventory item (+ qty for stackables) to escrow.
    // Reuses market/my_inventory (already excludes equipped + locked artifacts).
    function TradeItemPicker({ onClose, onPick }) {
      const { data, loading, error } = useApi("market/my_inventory", null, []);
      const [cat, setCat] = useState("herb");
      const [selected, setSelected] = useState(null); // stackable pending qty
      const [qty, setQty] = useState(1);
      const [pickErr, setPickErr] = useState(null);
      const items = (data && data.items) || {};
      const catOpts = ["herb","pill","ore","artifact","cauldron"].map(c => ({
        value:c, label:`${_TRADE_CAT_ICON[c]}`,
      }));
      const list = items[cat] || [];

      async function pick(it, n) {
        setPickErr(null);
        const r = await onPick(cat, it.instance_id, n);
        if (r && r.ok) { onClose(); }
        else { setPickErr(tradeReason(r && r.reason)); }
      }

      return (
        <Modal onClose={onClose} title={t("trade_picker_title")}
               accent="rgba(var(--realm-1-rgb),.4)" maxWidth={420} zIndex={88}>
          {loading ? (
            <div style={{ textAlign:"center", padding:"24px 0" }}><DotSpinner /></div>
          ) : error ? <ErrBanner msg={error} /> : (
            <div>
              <SegControl options={catOpts} value={cat}
                          onChange={(v) => { setCat(v); setSelected(null); }} />
              {pickErr && <div className="err-banner" style={{ marginTop:10 }}>⚠️ {pickErr}</div>}
              {selected ? (
                <div style={{ marginTop:12, padding:"12px", background:"rgba(12,30,48,.5)",
                              border:"1px solid rgba(var(--realm-1-rgb),.3)", borderRadius:10 }}>
                  <div style={{ fontSize:13, color:"var(--text)", marginBottom:10 }}>
                    {_TRADE_CAT_ICON[cat]} {selected.name}
                  </div>
                  <div style={{ display:"flex", alignItems:"center", gap:10, marginBottom:12 }}>
                    <button onClick={() => setQty(q => Math.max(1, q - 1))}
                            style={{ width:34, height:34, borderRadius:8, border:"1px solid var(--border)",
                                     background:"var(--panel)", color:"var(--text)", fontSize:18 }}>−</button>
                    <input type="number" value={qty}
                           onChange={(e) => {
                             let v = parseInt(e.target.value, 10);
                             if (isNaN(v)) v = 1;
                             setQty(Math.max(1, Math.min(selected.quantity, v)));
                           }}
                           style={{ flex:1, textAlign:"center", padding:"8px", borderRadius:8,
                                    border:"1px solid var(--border)", background:"var(--card)",
                                    color:"var(--text)", fontSize:15 }} />
                    <button onClick={() => setQty(q => Math.min(selected.quantity, q + 1))}
                            style={{ width:34, height:34, borderRadius:8, border:"1px solid var(--border)",
                                     background:"var(--panel)", color:"var(--text)", fontSize:18 }}>+</button>
                  </div>
                  <div style={{ fontSize:10.5, color:"var(--muted)", marginBottom:10 }}>
                    {t("trade_qty")}: {qty} / {selected.quantity}
                  </div>
                  <div style={{ display:"flex", gap:8 }}>
                    <ActionBtn variant="ghost" style={{ flex:1 }} onClick={() => setSelected(null)}>↩</ActionBtn>
                    <ActionBtn variant="primary" style={{ flex:2 }} onClick={() => pick(selected, qty)}>
                      {t("trade_add_btn")}
                    </ActionBtn>
                  </div>
                </div>
              ) : list.length === 0 ? (
                <div style={{ textAlign:"center", padding:"22px 0", color:"var(--muted)", fontSize:12 }}>
                  {t("trade_picker_empty")}
                </div>
              ) : (
                <div style={{ marginTop:10, display:"flex", flexDirection:"column", gap:6 }}>
                  {list.map((it, i) => {
                    const stackable = (cat === "herb" || cat === "pill" || cat === "ore");
                    return (
                      <button key={i} onClick={() => {
                        haptic("light");
                        if (stackable && it.quantity > 1) { setQty(1); setSelected(it); }
                        else { pick(it, 1); }
                      }} style={{
                        display:"flex", alignItems:"center", justifyContent:"space-between",
                        padding:"10px 12px", borderRadius:8, border:"1px solid var(--border)",
                        background:"var(--panel)", color:"var(--text)", fontSize:12.5, textAlign:"left",
                      }}>
                        <span>{it.grade_emoji || _TRADE_CAT_ICON[cat]} {it.name}</span>
                        {it.quantity > 1 && <Badge variant="gold">×{it.quantity}</Badge>}
                      </button>
                    );
                  })}
                </div>
              )}
            </div>
          )}
        </Modal>
      );
    }

    // The trade negotiation surface. Polls trade/state ~3s while pending.
    function TradeModal({ tradeId, onClose, onPlayerRefresh }) {
      const [state, setState] = useState(null);
      const [errMsg, setErrMsg] = useState(null);
      const [tick, setTick] = useState(0);
      const [picking, setPicking] = useState(false);
      const [stonesOpen, setStonesOpen] = useState(false);
      const [stonesInput, setStonesInput] = useState("");
      const [banner, setBanner] = useState(null);
      const [nowMs, setNowMs] = useState(Date.now());
      const prevRef = useRef(null);
      const refreshedRef = useRef(false);

      const isPending = !state || state.status === "pending";
      const refresh = () => setTick(x => x + 1);

      // Poll timer — runs only while pending (mirror DuelArenaModal).
      useEffect(() => {
        if (state && state.status !== "pending") return;
        const iv = setInterval(() => setTick(x => x + 1), 3000);
        return () => clearInterval(iv);
      }, [state && state.status]);

      // Countdown ticker (1s).
      useEffect(() => {
        const iv = setInterval(() => setNowMs(Date.now()), 1000);
        return () => clearInterval(iv);
      }, []);

      // Fetch state on tick / tradeId change.
      useEffect(() => {
        let cancelled = false;
        (async () => {
          try {
            const res = await api("trade/state", { trade_id: tradeId });
            if (cancelled) return;
            if (res.ok === false) { setErrMsg(tradeReason(res.reason)); return; }
            const prev = prevRef.current;
            if (prev && prev.status === "pending" && res.status === "pending") {
              const sigPrev = JSON.stringify([prev.their_items, prev.their_stones, prev.their_confirmed]);
              const sigNew = JSON.stringify([res.their_items, res.their_stones, res.their_confirmed]);
              if (sigPrev !== sigNew) {
                if (!prev.their_confirmed && res.their_confirmed) {
                  setBanner(t("trade_banner_other_confirmed", { name: res.other_dao_name }));
                } else {
                  setBanner(t("trade_banner_other_changed", { name: res.other_dao_name }));
                }
              }
            }
            prevRef.current = res;
            setState(res);
            setErrMsg(null);
          } catch (e) { if (!cancelled) setErrMsg(e.message); }
        })();
        return () => { cancelled = true; };
      }, [tradeId, tick]);

      // Auto-clear the banner after a few seconds.
      useEffect(() => {
        if (!banner) return;
        const id = setTimeout(() => setBanner(null), 4000);
        return () => clearTimeout(id);
      }, [banner]);

      // Refresh player (stones/inventory changed) once the trade resolves.
      useEffect(() => {
        if (state && state.status !== "pending" && !refreshedRef.current) {
          refreshedRef.current = true;
          onPlayerRefresh && onPlayerRefresh();
        }
      }, [state && state.status]);

      async function doAdd(item_type, instance_id, qty) {
        const r = await api("trade/add_item", { trade_id: tradeId, item_type, instance_id, qty });
        if (r.ok) { refresh(); onPlayerRefresh && onPlayerRefresh(); }
        return r;
      }
      async function doRemove(idx) {
        const r = await api("trade/remove_item", { trade_id: tradeId, item_index: idx });
        if (r.ok) { refresh(); onPlayerRefresh && onPlayerRefresh(); }
        else setErrMsg(tradeReason(r.reason));
      }
      async function doStones() {
        let amount = parseInt(String(stonesInput).replace(/[.,\s]/g, ""), 10);
        if (isNaN(amount) || amount < 0) { setErrMsg(t("trade_reason_invalid_value")); return; }
        const r = await api("trade/set_stones", { trade_id: tradeId, amount });
        if (r.ok) { setStonesOpen(false); setStonesInput(""); refresh(); }
        else setErrMsg(tradeReason(r.reason));
      }
      async function doConfirm() {
        const r = await api("trade/confirm", { trade_id: tradeId });
        if (r.ok) { refresh(); if (r.completed) { onPlayerRefresh && onPlayerRefresh(); } }
        else setErrMsg(tradeReason(r.reason));
      }
      async function doCancel() {
        const r = await api("trade/cancel", { trade_id: tradeId });
        if (r.ok) { refresh(); onPlayerRefresh && onPlayerRefresh(); }
        else setErrMsg(tradeReason(r.reason));
      }

      const remaining = (state && state.expires_at_ms) ? Math.max(0, state.expires_at_ms - nowMs) : 0;

      function itemRow(it, idx, removable) {
        return (
          <div key={idx} style={{
            display:"flex", alignItems:"center", justifyContent:"space-between",
            padding:"6px 8px", borderRadius:6, background:"rgba(0,0,0,.22)", marginBottom:4,
          }}>
            <span style={{ fontSize:11.5, color:"var(--text)", minWidth:0, overflow:"hidden",
                           textOverflow:"ellipsis", whiteSpace:"nowrap" }}>
              {it.emoji} {it.name}{it.qty > 1 ? ` ×${it.qty}` : ""}
            </span>
            {removable && (
              <button onClick={() => doRemove(idx)} style={{
                marginLeft:6, width:22, height:22, borderRadius:5, flexShrink:0,
                border:"1px solid rgba(var(--red-rgb),.35)", background:"rgba(var(--red-rgb),.1)",
                color:"var(--red)", fontSize:13, lineHeight:1,
              }}>✕</button>
            )}
          </div>
        );
      }

      function side(title, items, stones, confirmed, mine) {
        return (
          <div style={{
            flex:1, padding:"10px", borderRadius:10, minWidth:0,
            background: mine ? "rgba(12,30,48,.5)" : "rgba(40,22,52,.45)",
            border: `1px solid ${mine ? "rgba(var(--realm-1-rgb),.32)" : "rgba(var(--realm-3-rgb),.3)"}`,
          }}>
            <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", marginBottom:8 }}>
              <span style={{ fontFamily:"'Cinzel',serif", fontSize:11.5, color:"var(--gold2)",
                             overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap" }}>{title}</span>
              {confirmed
                ? <Badge variant="jade">{ico("✅","check",{ size:11, style:{ display:"inline-block", verticalAlign:"-1px" } })}</Badge>
                : <Badge variant="warn">{ico("⏳","incense",{ size:11, style:{ display:"inline-block", verticalAlign:"-1px" } })}</Badge>}
            </div>
            {(items || []).length === 0 && (stones || 0) === 0 ? (
              <div style={{ fontSize:11, color:"var(--muted2)", padding:"6px 0" }}>{t("trade_empty")}</div>
            ) : (
              <div>
                {(items || []).map((it, i) => itemRow(it, i, mine && isPending))}
                {(stones || 0) > 0 && (
                  <div style={{ marginTop:4, fontSize:12, color:"var(--gold3)", fontWeight:600 }}>
                    🪨 {fmtNum(stones)}
                  </div>
                )}
              </div>
            )}
          </div>
        );
      }

      const otherName = (state && state.other_dao_name) || "…";
      const finished = state && state.status !== "pending";

      return (
        <Modal onClose={onClose}
               title={`🤝 ${t("trade_with", { name: otherName })}`}
               accent="rgba(var(--gold2-rgb),.42)" maxWidth={460} zIndex={76}>
          {!state ? (
            errMsg ? <div className="err-banner">⚠️ {errMsg}</div> : (
              <div style={{ textAlign:"center", padding:"26px 0" }}>
                <DotSpinner /><div style={{ marginTop:8, fontSize:12, color:"var(--muted)" }}>{t("trade_loading")}</div>
              </div>
            )
          ) : finished ? (
            <div style={{ textAlign:"center", padding:"18px 6px" }}>
              <div style={{ fontSize:40, marginBottom:8 }}>
                {state.status === "completed" ? "🤝" : (state.status === "expired" ? "⌛" : "🚫")}
              </div>
              <div style={{ fontFamily:"'Cinzel',serif", fontSize:16, color:"var(--gold2)", marginBottom:6 }}>
                {state.status === "completed" ? t("trade_completed_title")
                  : state.status === "expired" ? t("trade_status_expired") : t("trade_status_cancelled")}
              </div>
              {state.status === "completed" && (
                <div style={{ fontSize:12, color:"var(--muted)", marginBottom:14 }}>{t("trade_completed_msg")}</div>
              )}
              <div style={{ display:"flex", gap:8 }}>
                {side(t("trade_you_label"), state.my_items, state.my_stones, true, true)}
                {side(otherName, state.their_items, state.their_stones, true, false)}
              </div>
              <ActionBtn variant="ghost" style={{ width:"100%", marginTop:14 }} onClick={() => onClose()}>
                {t("btn_ok")}
              </ActionBtn>
            </div>
          ) : (
            <div>
              {banner && (
                <div style={{
                  padding:"7px 10px", borderRadius:8, marginBottom:10, fontSize:11.5,
                  background:"rgba(var(--gold2-rgb),.1)", border:"1px solid rgba(var(--gold2-rgb),.3)",
                  color:"var(--gold2)", textAlign:"center",
                }}>{banner}</div>
              )}
              {errMsg && <div className="err-banner" style={{ marginTop:0, marginBottom:10 }}>⚠️ {errMsg}</div>}

              <div style={{ display:"flex", justifyContent:"center", marginBottom:10 }}>
                <Badge variant={remaining < 60000 ? "red" : "gold"}>⏳ {fmtDuration(remaining)}</Badge>
              </div>

              <div style={{ display:"flex", gap:8, alignItems:"stretch" }}>
                {side(t("trade_you_label"), state.my_items, state.my_stones, state.my_confirmed, true)}
                {side(otherName, state.their_items, state.their_stones, state.their_confirmed, false)}
              </div>

              {stonesOpen ? (
                <div style={{ marginTop:12, padding:"12px", background:"rgba(12,30,48,.5)",
                              border:"1px solid rgba(var(--realm-1-rgb),.3)", borderRadius:10 }}>
                  <div style={{ fontSize:12, color:"var(--text)", marginBottom:6 }}>{t("trade_stones_prompt")}</div>
                  <div style={{ fontSize:10.5, color:"var(--muted)", marginBottom:8 }}>
                    {t("trade_stones_balance", { n: fmtNum(state.my_balance) })}
                  </div>
                  <input type="number" value={stonesInput} placeholder="0"
                         onChange={(e) => setStonesInput(e.target.value)}
                         style={{ width:"100%", padding:"9px", borderRadius:8, border:"1px solid var(--border)",
                                  background:"var(--card)", color:"var(--text)", fontSize:15, marginBottom:10 }} />
                  <div style={{ display:"flex", gap:8 }}>
                    <ActionBtn variant="ghost" style={{ flex:1 }} onClick={() => { setStonesOpen(false); setStonesInput(""); }}>↩</ActionBtn>
                    <ActionBtn variant="primary" style={{ flex:2 }} onClick={doStones}>{t("trade_stones_set_btn")}</ActionBtn>
                  </div>
                </div>
              ) : (
                <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:8, marginTop:12 }}>
                  <ActionBtn variant="ghost" onClick={() => { setErrMsg(null); setPicking(true); }}>{t("trade_add_item")}</ActionBtn>
                  <ActionBtn variant="ghost" onClick={() => { setErrMsg(null); setStonesInput(String(state.my_stones || "")); setStonesOpen(true); }}>{t("trade_set_stones")}</ActionBtn>
                  <ActionBtn variant="primary" disabled={state.my_confirmed} onClick={doConfirm}>
                    {state.my_confirmed ? t("trade_confirmed") : t("trade_confirm")}
                  </ActionBtn>
                  <ActionBtn variant="danger" onClick={doCancel}>{t("trade_cancel")}</ActionBtn>
                </div>
              )}

              {state.my_confirmed && !state.their_confirmed && (
                <div style={{ textAlign:"center", marginTop:10, fontSize:11, color:"var(--muted)" }}>
                  {t("trade_you_confirmed", { name: otherName })}
                </div>
              )}

              <div style={{ textAlign:"center", marginTop:12, fontSize:9.5, color:"var(--muted2)",
                            lineHeight:1.5, fontFamily:"'Cinzel',serif" }}>
                {t("trade_jade_note")}
              </div>
            </div>
          )}

          {picking && (
            <TradeItemPicker onClose={() => setPicking(false)} onPick={doAdd} />
          )}
        </Modal>
      );
    }

    // Market dashboard card — entry 2 for P2P trade (the profile CTA is entry 1).
    // Lists my pending trades (open → App-root TradeModal) + "Nova Troca" by DAO
    // name (reuses trade/initiate; onProposeTrade resolves on the App root).
    function MarketP2PCard({ onOpenTrade, onProposeTrade }) {
      const [reload, setReload] = useState(0);
      const { data } = useApi("trade/pending", null, [reload]);
      useVisibleInterval(() => setReload(x => x + 1), 20000);
      const [findOpen, setFindOpen] = useState(false);
      const [findName, setFindName] = useState("");
      const [findErr, setFindErr] = useState(null);
      const trades = (data && data.trades) || [];

      async function startFind() {
        setFindErr(null);
        const name = findName.trim();
        if (!name) return;
        const r = await onProposeTrade(name);
        if (r && r.ok) { setFindOpen(false); setFindName(""); setReload(x => x + 1); }
        else setFindErr(tradeReason(r && r.reason));
      }

      return (
        <Card>
          <CardTitle left={t("trade_p2p_card_title")} />
          <div style={{ fontSize:11, color:"var(--muted)", marginBottom:10 }}>{t("trade_p2p_card_desc")}</div>
          {findOpen ? (
            <div style={{ marginBottom:12 }}>
              <input value={findName} placeholder={t("trade_find_prompt")}
                     onChange={(e) => setFindName(e.target.value)}
                     style={{ width:"100%", padding:"9px", borderRadius:8, border:"1px solid var(--border)",
                              background:"var(--card)", color:"var(--text)", fontSize:14, marginBottom:8 }} />
              {findErr && <div className="err-banner" style={{ marginTop:0, marginBottom:8 }}>⚠️ {findErr}</div>}
              <div style={{ display:"flex", gap:8 }}>
                <ActionBtn variant="ghost" style={{ flex:1 }} onClick={() => { setFindOpen(false); setFindName(""); setFindErr(null); }}>↩</ActionBtn>
                <ActionBtn variant="primary" style={{ flex:2 }} onClick={startFind}>{t("trade_find_btn")}</ActionBtn>
              </div>
            </div>
          ) : (
            <ActionBtn variant="primary" style={{ width:"100%", marginBottom:12 }}
                       onClick={() => { setFindErr(null); setFindOpen(true); }}>
              ➕ {t("trade_new_btn")}
            </ActionBtn>
          )}
          <div style={{ fontSize:10, color:"var(--muted)", textTransform:"uppercase", letterSpacing:.6,
                        fontFamily:"'Cinzel',serif", marginBottom:6 }}>{t("trade_pending_title")}</div>
          {trades.length === 0 ? (
            <div style={{ fontSize:11, color:"var(--muted2)", padding:"4px 0" }}>{t("trade_no_pending")}</div>
          ) : trades.map((tr, i) => (
            <div key={i} style={{
              display:"flex", alignItems:"center", justifyContent:"space-between",
              padding:"8px 10px", borderRadius:8, background:"var(--panel)",
              border:"1px solid var(--border)", marginBottom:6,
            }}>
              <div style={{ minWidth:0 }}>
                <div style={{ fontSize:12.5, color:"var(--text)", overflow:"hidden",
                              textOverflow:"ellipsis", whiteSpace:"nowrap" }}>
                  {tr.am_initiator ? "↗" : "↘"} {tr.other_dao_name}
                </div>
                <div style={{ fontSize:10, color:"var(--muted)", marginTop:2 }}>
                  🎒 {tr.my_item_count}{tr.my_stones > 0 ? ` +🪨${fmtNum(tr.my_stones)}` : ""}
                  {" ⇄ "}
                  {tr.their_item_count}{tr.their_stones > 0 ? ` +🪨${fmtNum(tr.their_stones)}` : ""}
                  {tr.their_confirmed && <span style={{ marginLeft:6, color:"var(--jade)" }}>{ico("✅","check",{ size:12, style:{ display:"inline-block", verticalAlign:"-2px" } })}</span>}
                </div>
              </div>
              <ActionBtn variant="ghost" style={{ padding:"6px 12px", fontSize:11, flexShrink:0 }}
                         onClick={() => onOpenTrade(tr.trade_id)}>{t("trade_open_btn")}</ActionBtn>
            </div>
          ))}
        </Card>
      );
    }

    function MarketTab({ onOpenTrade, onProposeTrade }) {
      const [mode, setMode] = useState("browse"); // browse | mine | sell
      const [filterType, setFilterType] = useState("all");
      const [sort, setSort] = useState("newest");
      const [onlyAuction, setOnlyAuction] = useState(false);
      const [page, setPage] = useState(0);
      const [reload, setReload] = useState(0);

      // Modal state (single source of truth; one modal at a time).
      const [activeListing, setActiveListing] = useState(null);
      const [bidListing, setBidListing] = useState(null);
      const [sellOpen, setSellOpen] = useState(false);

      // Reset page when filters / mode change.
      useEffect(() => { setPage(0); }, [filterType, sort, onlyAuction, mode]);

      const reqExtra = useMemo(() => ({
        item_type: filterType === "all" ? null : filterType,
        sort,
        only_auction: onlyAuction,
        only_mine: mode === "mine",
        page,
        page_size: 10,
      }), [filterType, sort, onlyAuction, mode, page]);

      // Only request listings in browse/mine. Sell mode uses different endpoint.
      const skip = (mode === "sell");
      const { data, loading, error } = useApi(
        skip ? "player" : "market/listings",
        skip ? null : reqExtra,
        [reload, skip ? 0 : 1],
      );
      useVisibleInterval(() => setReload(x => x + 1), 30000);

      const segOpts = [
        { value:"browse", label: t("market_seg_browse") },
        { value:"mine",   label: t("market_seg_mine") },
        { value:"sell",   label: t("market_seg_sell") },
      ];

      const filterOpts = [
        { value:"all",      label: t("market_filter_all") },
        { value:"herb",     label: "🌿" },
        { value:"pill",     label: "💊" },
        { value:"ore",      label: "🪨" },
        { value:"artifact", label: "⚔️" },
        { value:"cauldron", label: "⚗️" },
      ];

      const sortOpts = [
        { value:"newest",    label: t("market_sort_newest") },
        { value:"cheapest",  label: t("market_sort_cheapest") },
        { value:"expensive", label: t("market_sort_expensive") },
        { value:"expiring",  label: t("market_sort_expiring") },
      ];

      function refreshAll() {
        setReload(x => x + 1);
      }

      return (
        <div>
          <Card>
            <CardTitle left={`💰 ${t("tab_market")}`}
                       right={data && !skip
                              ? `${data.your_listings_count || 0}/${data.max_listings || 10}`
                              : null} />
            <SegControl options={segOpts} value={mode} onChange={setMode} />
            {data && !skip && (
              <div style={{ display:"flex", justifyContent:"space-between",
                            marginTop:8, fontSize:11, color:"var(--muted)" }}>
                <span>{t("market_your_stones", { n: fmtNum(data.your_stones || 0) })}</span>
                <span>{t("market_tax_label", { pct: ((data.tax_rate || 0) * 100).toFixed(0) })}</span>
              </div>
            )}
            {/* MV-3 — a nota do mercado LOCAL (server-resolved, Lei §1 — o
                preço nunca muda mudo; key só chega com `estados_regionais` ON
                e estado ≠ neutro). */}
            {data && !skip && data.region_note && (
              <div style={{ marginTop:6, fontSize:10.5, color:"var(--gold3)", lineHeight:1.45 }}>
                {data.region_note}
              </div>
            )}
            {/* MV-6 — a nota da rep local; o server SÓ a manda quando a rep
                muda o preço de verdade (clamp — notas empilhadas nunca
                prometem mais desconto do que o debitado). */}
            {data && !skip && data.region_rep_note && (
              <div style={{ marginTop:4, fontSize:10.5, color:"var(--muted)", lineHeight:1.45 }}>
                {data.region_rep_note}
              </div>
            )}
          </Card>

          {/* MA-39a — P2P Trade dashboard (entry 2). Only in browse to keep the
              sell/mine flows uncluttered; the profile CTA is entry 1. */}
          {mode === "browse" && onOpenTrade && onProposeTrade && (
            <MarketP2PCard onOpenTrade={onOpenTrade} onProposeTrade={onProposeTrade} />
          )}

          {/* MV-7 — 📜 Relatório do Mercado Imperial (key opcional server-
              resolved; flag OFF / sem snapshot → ausente → nada renderiza). */}
          {mode === "browse" && data && data.market_report && (
            <Card>
              <CardTitle left={data.market_report.title} right={data.market_report.window} />
              <div style={{ fontSize:10.5, color:"var(--muted)", marginBottom:6 }}>
                {data.market_report.continent_name}
              </div>
              {(data.market_report.lines || []).map((ln, i) => (
                <div key={i} style={{ fontSize:12, lineHeight:1.55 }}>{ln}</div>
              ))}
            </Card>
          )}

          {mode !== "sell" && (
            <Card>
              <div style={{ marginBottom:8 }}>
                <div style={{ fontSize:10, color:"var(--muted)", marginBottom:4,
                              fontFamily:"'Cinzel',serif", letterSpacing:.6, textTransform:"uppercase" }}>
                  {t("market_filter_title")}
                </div>
                <SegControl options={filterOpts} value={filterType} onChange={setFilterType} />
              </div>
              <div style={{ marginBottom:8 }}>
                <div style={{ fontSize:10, color:"var(--muted)", marginBottom:4,
                              fontFamily:"'Cinzel',serif", letterSpacing:.6, textTransform:"uppercase" }}>
                  {t("market_sort_title")}
                </div>
                <SegControl options={sortOpts} value={sort} onChange={setSort} />
              </div>
              <button
                onClick={() => { haptic("select"); setOnlyAuction(x => !x); }}
                style={{
                  width:"100%", padding:"7px 12px", borderRadius:8, cursor:"pointer",
                  background: onlyAuction
                    ? "linear-gradient(180deg,rgba(var(--gold2-rgb),.22),rgba(var(--gold-rgb),.32))"
                    : "rgba(var(--surface-rgb),.6)",
                  border:`1px solid ${onlyAuction ? "var(--gold2)" : "var(--border)"}`,
                  color: onlyAuction ? "var(--gold3)" : "var(--text)",
                  fontSize:11, fontFamily:"'Cinzel',serif", letterSpacing:.4,
                }}>
                {onlyAuction ? `🔨 ${t("market_filter_auctions_only_on")}` : `🔨 ${t("market_filter_auctions_only_off")}`}
              </button>
            </Card>
          )}

          {mode === "sell" ? (
            <MarketSellPanel onSold={() => { refreshAll(); setMode("mine"); }} />
          ) : (
            <>
              {loading && !data && <ListSkeleton rows={5} />}
              {error && !data && <ErrBanner msg={error} />}
              {data && (data.listings || []).length === 0 && (
                <Card>
                  <div style={{ textAlign:"center", padding:"24px 8px", color:"var(--muted)", fontSize:12 }}>
                    {mode === "mine" ? t("market_mine_empty") : t("market_empty_listings")}
                    {/* Dívida de Lei §1 já em produção: o botão 💰 "Mercador" da
                        praça leva a uma lista EM BRANCO e o jogador não tem como
                        saber que o mercado é 100% P2P (nada nasce do sistema).
                        Molde do `bounty_board_empty_hint`. Independente de flag —
                        vale para os 239 do `main`. Em "minhas" a lista vazia é
                        sobre AS SUAS ofertas, então a dica não se aplica. */}
                    {mode !== "mine" && (
                      <div style={{ marginTop:6, fontSize:10.5, fontStyle:"italic", opacity:.85 }}>
                        {t("market_empty_hint")}
                      </div>
                    )}
                  </div>
                </Card>
              )}
              {data && (data.listings || []).map(l => (
                <MarketListingCard
                  key={l.id}
                  l={l}
                  isOwn={mode === "mine"}
                  onTap={() => { haptic("select");
                    if (l.is_auction) setBidListing(l);
                    else setActiveListing(l);
                  }}
                  onCancel={async () => {
                    if (!l.is_mine) return;
                    haptic("warning");
                    try {
                      await api("market/cancel_listing", { listing_id: l.id });
                      haptic("success");
                      showToast(t("market_cancel_success"));
                      refreshAll();
                    } catch (e) {
                      haptic("error");
                      showToast(t("market_err_" + (e.message || "engine_error")), "err");
                    }
                  }}
                />
              ))}
              {data && data.total_pages > 1 && (
                <div style={{ display:"flex", justifyContent:"space-between", gap:8, marginTop:10 }}>
                  <ActionBtn variant="ghost" disabled={page <= 0}
                             onClick={() => { setPage(p => Math.max(0, p - 1)); haptic("light"); }}>
                    ◀ {t("page_prev")}
                  </ActionBtn>
                  <div style={{ display:"flex", alignItems:"center", fontSize:12, color:"var(--muted)" }}>
                    {page + 1} / {data.total_pages}
                  </div>
                  <ActionBtn variant="ghost" disabled={page + 1 >= data.total_pages}
                             onClick={() => { setPage(p => p + 1); haptic("light"); }}>
                    {t("page_next")} ▶
                  </ActionBtn>
                </div>
              )}
            </>
          )}

          {activeListing && (
            <MarketBuyModal
              listing={activeListing}
              regionMult={data && data.region_price_mult}
              onClose={() => setActiveListing(null)}
              onBought={() => { setActiveListing(null); refreshAll(); }}
            />
          )}
          {bidListing && (
            <MarketBidModal
              listing={bidListing}
              onClose={() => setBidListing(null)}
              onBidPlaced={() => { setBidListing(null); refreshAll(); }}
            />
          )}
        </div>
      );
    }

    function MarketListingCard({ l, isOwn, onTap, onCancel }) {
      const isAuction = !!l.is_auction;
      const displayPrice = isAuction ? (l.current_bid ?? l.unit_price) : l.unit_price;
      const remainMs = l.expires_at_ms - Date.now();
      const expiresShort = remainMs > 0 ? fmtDuration(remainMs) : t("market_listing_expired");
      const isNPC = !!l.is_npc;
      const mine = !!l.is_mine;
      return (
        <Card style={{ padding:10, marginBottom:9, cursor: mine ? "default" : "pointer" }}
              onClick={mine ? undefined : onTap}>
          <div style={{ display:"flex", alignItems:"center", gap:9 }}>
            <div style={{ fontSize:22, lineHeight:1, opacity:.9, flexShrink:0 }}>
              {l.grade_emoji || _MKT_TYPE_ICON[l.item_type] || "📦"}
            </div>
            <div style={{ flex:1, minWidth:0 }}>
              <div style={{ display:"flex", justifyContent:"space-between", alignItems:"baseline", gap:8 }}>
                <div style={{ display:"flex", alignItems:"baseline", gap:6, minWidth:0 }}>
                  {/* TAPETE QoL §5 item 5 ([jogador]): G chip tinted by craft
                      quality — Perfeito roxo, Divino dourado, Espírito colorido. */}
                  {l.item_type === "artifact" && l.grade != null && (
                    <span style={{
                      flexShrink:0, padding:"1px 6px", fontSize:9, fontWeight:700,
                      letterSpacing:.5, fontFamily:"'Cinzel',serif", borderRadius:99,
                      border:`1px solid ${l.quality === "spirit" ? "var(--realm-10)" : (l.quality && l.quality !== "normal" ? (ART_QUALITY_COLOR[l.quality] || "var(--realm-0)") : ((GRADE_VISUALS[l.grade] || GRADE_VISUALS[0]).color))}55`,
                      ...artQualityChipStyle(l.quality, (GRADE_VISUALS[l.grade] || GRADE_VISUALS[0]).color),
                    }}>G{l.grade}</span>
                  )}
                  <div style={{ fontWeight:600, fontSize:13, color:"var(--text)",
                                whiteSpace:"nowrap", overflow:"hidden", textOverflow:"ellipsis" }}>
                    {l.item_name}
                  </div>
                </div>
                {l.quantity > 1 && (
                  <Badge variant="gold">x{l.quantity}</Badge>
                )}
              </div>
              {/* TAPETE QoL §5 item 4 ([jogador] — disclosure de compra, Lei §1):
                  refino + encantamento + espírito visíveis na listagem. */}
              {l.item_type === "artifact" && (l.quality && l.quality !== "normal" || l.enchant_rune || l.has_spirit) && (
                <div style={{ display:"flex", flexWrap:"wrap", gap:4, marginTop:3 }}>
                  {l.quality && l.quality !== "normal" && (
                    <span style={{
                      fontSize:9, padding:"1px 6px", borderRadius:99, fontFamily:"'Cinzel',serif",
                      letterSpacing:.4, textTransform:"uppercase", background:"rgba(0,0,0,.3)",
                      border:`1px solid ${cssHex(l.quality === "spirit" ? "var(--realm-10)" : (ART_QUALITY_COLOR[l.quality] || "var(--realm-0)"))}55`,
                      ...artQualityChipStyle(l.quality, "var(--muted)"),
                    }}>{t(ART_QUALITY_KEY[l.quality] || "art_quality_normal")}</span>
                  )}
                  {l.enchant_rune && (
                    <span style={{ fontSize:9, padding:"1px 6px", borderRadius:99,
                                   background:"rgba(var(--realm-1-rgb),.12)", border:"1px solid rgba(var(--realm-1-rgb),.35)",
                                   color:"#7be3ff" }}>✨ {humanizeStat(l.enchant_rune)}</span>
                  )}
                  {l.has_spirit && (
                    <span style={{ fontSize:9, padding:"1px 6px", borderRadius:99,
                                   background:"rgba(var(--realm-10-rgb),.12)", border:"1px solid rgba(var(--realm-10-rgb),.35)",
                                   color:"#f9a8d4" }}>✧ {l.spirit_name || t("market_art_spirit")}</span>
                  )}
                </div>
              )}
              {l.stats && Object.keys(l.stats).length > 0 && (
                <div style={{ fontSize:10, color:"var(--muted2)", marginTop:2,
                              whiteSpace:"nowrap", overflow:"hidden", textOverflow:"ellipsis" }}>
                  {Object.entries(l.stats).map(([k, v]) => `${humanizeStat(k)} +${v}`).join(" · ")}
                </div>
              )}
              <div style={{ display:"flex", justifyContent:"space-between", marginTop:4 }}>
                <span style={{ fontSize:11, color:"var(--muted)" }}>
                  {isNPC ? "🏮 " : "👤 "}{l.seller_display || "—"}
                </span>
                <span style={{ fontSize:10, color: remainMs > 3600000 ? "var(--muted)" : "var(--warn)" }}>
                  ⏳ {expiresShort}
                </span>
              </div>
            </div>
            <div style={{ flexShrink:0, textAlign:"right" }}>
              {isAuction && <Badge variant="warn">{t("market_listing_auction_chip")}</Badge>}
              <div style={{ fontWeight:700, fontSize:13, color:"var(--gold3)", fontFamily:"'Cinzel',serif", marginTop:2 }}>
                {fmtNum(displayPrice)}
              </div>
              <div style={{ fontSize:9, color:"var(--muted)" }}>{t("market_currency_short")}</div>
            </div>
          </div>
          {mine && (
            <ActionBtn variant="danger"
                       onClick={(e) => { e.stopPropagation && e.stopPropagation(); onCancel(); }}
                       style={{ width:"100%", marginTop:8 }}>
              {t("market_btn_cancel")}
            </ActionBtn>
          )}
        </Card>
      );
    }

    function MarketBuyModal({ listing, onClose, onBought, regionMult }) {
      // 🔴 UMA unidade, nao o estoque inteiro (achado do Astra, 16/09).
      // Estava `useState(listing.quantity)`: a janela abria com TUDO
      // seleccionado e um toque em confirmar levava a oferta completa. O botao
      // "comprar tudo" existe a 30 pixels daqui — ou seja, "tudo" JA' era para
      // ser uma escolha explicita; era so' tambem o que acontecia a quem nao
      // reparou. ⚠️ Uma oferta de 1 unidade rende o mesmo comportamento de
      // antes; a diferenca so' existe onde ela podia doer.
      const [qty, setQty] = useState(1);
      const [busy, setBusy] = useState(false);
      const [err, setErr] = useState(null);
      const unit = listing.unit_price;
      // MV-3 — o total do confirm reflete o estado regional (o engine debita
      // total×mult onde o comprador está; review: número mudo = Lei §1).
      // regionMult só chega com `estados_regionais` ON e estado ≠ neutro.
      const total = Math.round(unit * qty * (regionMult || 1));

      async function doBuy() {
        if (busy) return;
        setBusy(true);
        setErr(null);
        try {
          const res = await api("market/buy", {
            listing_id: listing.id,
            qty: qty < listing.quantity ? qty : undefined,
          });
          if (!res.ok) {
            setErr(res.reason || "engine_error");
            haptic("error");
            setBusy(false);
            return;
          }
          haptic("success");
          showToast(t("market_buy_success"));
          onBought();
        } catch (e) {
          setErr(e.message || "engine_error");
          haptic("error");
        }
        setBusy(false);
      }

      const footer = (
        <ActionBtn variant="primary" disabled={busy || qty <= 0}
                   onClick={doBuy} style={{ width:"100%" }}>
          {/* 🔴 E O BOTÃO É O SÍTIO QUE MAIS IMPORTA: é o último número que o
              jogador lê antes de as pedras saírem. A minha 1ª correcção trocou
              os dois totais do cartão e ESQUECEU este — a guarda apanhou-o, que
              é exactamente para isso que ela existe. `fmtNum` escrevia
              `184.3K` no botão de gastar 184.312. */}
          {busy ? <DotSpinner /> : `💰 ${t("market_btn_buy")} — ${fmtFull(total)}`}
        </ActionBtn>
      );

      return (
        <Modal open={true} onClose={onClose}
               title={t("market_buy_modal_title")}
               maxWidth={380} zIndex={70}
               footer={footer}>
          <div style={{ textAlign:"center" }}>
            <div style={{ fontSize:42, lineHeight:1 }}>
              {listing.grade_emoji || _MKT_TYPE_ICON[listing.item_type] || "📦"}
            </div>
            <div style={{ marginTop:6, fontFamily:"'Cinzel',serif", fontSize:16, fontWeight:700, color:"var(--gold3)" }}>
              {listing.item_name}
            </div>
            {/* TAPETE QoL §5 item 4 — specs "mais visíveis e separadas":
                grade + refino + encantamento + espírito antes da compra. */}
            {listing.item_type === "artifact" && (
              <div style={{ display:"flex", justifyContent:"center", flexWrap:"wrap", gap:5, marginTop:6 }}>
                {listing.grade != null && (
                  <span style={{
                    fontSize:10, padding:"2px 8px", borderRadius:99, fontFamily:"'Cinzel',serif",
                    letterSpacing:.5, textTransform:"uppercase", background:"rgba(0,0,0,.35)",
                    border:`1px solid ${cssHex((GRADE_VISUALS[listing.grade] || GRADE_VISUALS[0]).color)}55`,
                    color:(GRADE_VISUALS[listing.grade] || GRADE_VISUALS[0]).color,
                  }}>G{listing.grade}{listing.grade_name ? ` · ${nomeDoGrau(listing.grade, listing.grade_name)}` : ""}</span>
                )}
                {listing.quality && listing.quality !== "normal" && (
                  <span style={{
                    fontSize:10, padding:"2px 8px", borderRadius:99, fontFamily:"'Cinzel',serif",
                    letterSpacing:.5, textTransform:"uppercase", background:"rgba(0,0,0,.35)",
                    border:`1px solid ${listing.quality === "spirit" ? "var(--realm-10)" : (ART_QUALITY_COLOR[listing.quality] || "var(--realm-0)")}55`,
                    ...artQualityChipStyle(listing.quality, "var(--muted)"),
                  }}>{t(ART_QUALITY_KEY[listing.quality] || "art_quality_normal")}</span>
                )}
                {listing.enchant_rune && (
                  <span style={{ fontSize:10, padding:"2px 8px", borderRadius:99,
                                 background:"rgba(var(--realm-1-rgb),.12)", border:"1px solid rgba(var(--realm-1-rgb),.35)",
                                 color:"#7be3ff" }}>✨ {humanizeStat(listing.enchant_rune)}</span>
                )}
                {listing.has_spirit && (
                  <span style={{ fontSize:10, padding:"2px 8px", borderRadius:99,
                                 background:"rgba(var(--realm-10-rgb),.12)", border:"1px solid rgba(var(--realm-10-rgb),.35)",
                                 color:"#f9a8d4" }}>✧ {listing.spirit_name || t("market_art_spirit")}</span>
                )}
              </div>
            )}
            {listing.stats && Object.keys(listing.stats).length > 0 && (
              <div style={{ fontSize:11, color:"var(--muted)", marginTop:4 }}>
                {Object.entries(listing.stats).map(([k, v]) => `${humanizeStat(k)} +${v}`).join(" · ")}
              </div>
            )}
          </div>
          <Card style={{ marginTop:14 }}>
            <div style={{ display:"flex", justifyContent:"space-between", fontSize:12 }}>
              <span style={{ color:"var(--muted)" }}>{t("market_unit_price")}</span>
              <b style={{ color:"var(--gold2)" }}>{fmtFull(unit)}</b>
            </div>
            <div style={{ display:"flex", justifyContent:"space-between", fontSize:12, marginTop:4 }}>
              <span style={{ color:"var(--muted)" }}>{t("market_stock")}</span>
              <b>{listing.quantity}</b>
            </div>
            <div style={{ display:"flex", justifyContent:"space-between", fontSize:12, marginTop:4 }}>
              <span style={{ color:"var(--muted)" }}>{t("market_listing_seller")}</span>
              <b>{listing.is_npc ? "🏮 " : "👤 "}{listing.seller_display}</b>
            </div>
          </Card>
          {listing.quantity > 1 && (
            <Card style={{ marginTop:10 }}>
              <div style={{ fontSize:11, color:"var(--muted)", marginBottom:6 }}>
                {t("market_buy_qty_label")}
              </div>
              <div style={{ display:"flex", gap:6, flexWrap:"wrap" }}>
                {[1, 5, 10].filter(n => n <= listing.quantity).map(n => (
                  <button key={n}
                          onClick={() => { setQty(n); haptic("light"); }}
                          style={{
                            flex:1, minWidth:55, padding:"7px 4px", borderRadius:7,
                            cursor:"pointer",
                            background: qty === n ? "var(--gold2)" : "rgba(var(--surface-rgb),.6)",
                            border:"1px solid var(--border)",
                            color: qty === n ? "#000" : "var(--text)",
                            fontWeight:700, fontSize:12,
                          }}>×{n}</button>
                ))}
                <button onClick={() => { setQty(listing.quantity); haptic("light"); }}
                        style={{
                          flex:1, minWidth:55, padding:"7px 4px", borderRadius:7,
                          cursor:"pointer",
                          background: qty === listing.quantity ? "var(--gold2)" : "rgba(var(--surface-rgb),.6)",
                          border:"1px solid var(--border)",
                          color: qty === listing.quantity ? "#000" : "var(--text)",
                          fontWeight:700, fontSize:12,
                        }}>{t("market_buy_all")}</button>
              </div>
              <div style={{ marginTop:8, display:"flex", justifyContent:"space-between", fontSize:12 }}>
                <span style={{ color:"var(--muted)" }}>{t("market_total_price")}</span>
                {/* 🔴 O total NUNCA abreviado: e' o numero que sai da carteira.
                    `fmtNum` mostrava `184.3K` onde saem 184.312 pedras. */}
                <b style={{ color:"var(--gold3)" }}>{fmtFull(total)}</b>
              </div>
            </Card>
          )}
          {err && (
            <div style={{ marginTop:10 }}>
              <ErrBanner msg={t("market_err_" + err)} />
            </div>
          )}
        </Modal>
      );
    }

    function MarketBidModal({ listing, onClose, onBidPlaced }) {
      const currentBid = listing.current_bid ?? listing.unit_price;
      const minIncrement = Math.max(1, Math.floor(currentBid * 0.05));
      const minBid = listing.has_bidder ? currentBid + minIncrement : currentBid;
      const [amount, setAmount] = useState(minBid);
      const [busy, setBusy] = useState(false);
      const [err, setErr] = useState(null);

      async function doBid() {
        if (busy) return;
        setBusy(true);
        setErr(null);
        try {
          const res = await api("market/auction_bid", {
            listing_id: listing.id,
            amount: parseInt(amount) || 0,
          });
          if (!res.ok) {
            setErr(res.reason || "engine_error");
            haptic("error");
            setBusy(false);
            return;
          }
          haptic("success");
          showToast(t("market_bid_success"));
          onBidPlaced();
        } catch (e) {
          setErr(e.message || "engine_error");
          haptic("error");
        }
        setBusy(false);
      }

      const footer = (
        <ActionBtn variant="primary" disabled={busy || amount < minBid}
                   onClick={doBid} style={{ width:"100%" }}>
          {busy ? <DotSpinner /> : `🔨 ${t("market_btn_bid")} — ${fmtNum(amount)}`}
        </ActionBtn>
      );

      return (
        <Modal open={true} onClose={onClose}
               title={t("market_bid_modal_title")}
               maxWidth={380} zIndex={70}
               footer={footer}>
          <div style={{ textAlign:"center" }}>
            <div style={{ fontSize:42, lineHeight:1 }}>
              {listing.grade_emoji || _MKT_TYPE_ICON[listing.item_type] || "📦"}
            </div>
            <div style={{ marginTop:6, fontFamily:"'Cinzel',serif", fontSize:16, fontWeight:700, color:"var(--gold3)" }}>
              {listing.item_name}
            </div>
          </div>
          <Card style={{ marginTop:14 }}>
            <div style={{ display:"flex", justifyContent:"space-between", fontSize:12 }}>
              <span style={{ color:"var(--muted)" }}>{t("market_bid_current")}</span>
              <b style={{ color:"var(--gold2)" }}>{fmtNum(currentBid)}</b>
            </div>
            <div style={{ display:"flex", justifyContent:"space-between", fontSize:12, marginTop:4 }}>
              <span style={{ color:"var(--muted)" }}>{t("market_bid_min")}</span>
              <b style={{ color:"var(--jade)" }}>{fmtNum(minBid)}</b>
            </div>
            {listing.highest_bidder_is_me && (
              <div style={{ marginTop:6 }}>
                <Badge variant="jade">{t("market_bid_you_are_top")}</Badge>
              </div>
            )}
          </Card>
          <Card style={{ marginTop:10 }}>
            <div style={{ fontSize:11, color:"var(--muted)", marginBottom:6 }}>
              {t("market_bid_amount_label")}
            </div>
            <input type="number" inputMode="numeric" value={amount}
                   min={minBid} step={Math.max(1, minIncrement)}
                   onChange={(e) => setAmount(e.target.value)}
                   style={{
                     width:"100%", padding:"9px 10px", borderRadius:8,
                     background:"rgba(var(--surface2-rgb),.85)", border:"1px solid var(--border2)",
                     color:"var(--text)", fontSize:14, fontWeight:700,
                     fontFamily:"'Cinzel',serif",
                   }} />
            <div style={{ display:"flex", gap:6, marginTop:8 }}>
              {[minBid, minBid + minIncrement * 4, minBid + minIncrement * 10].map(v => (
                <button key={v}
                        onClick={() => { setAmount(v); haptic("light"); }}
                        style={{
                          flex:1, padding:"6px 4px", borderRadius:6, cursor:"pointer",
                          background:"rgba(var(--surface-rgb),.6)", border:"1px solid var(--border)",
                          color:"var(--gold3)", fontSize:11,
                        }}>{fmtNum(v)}</button>
              ))}
            </div>
          </Card>
          {err && (
            <div style={{ marginTop:10 }}>
              <ErrBanner msg={t("market_err_" + err)} />
            </div>
          )}
        </Modal>
      );
    }

    function MarketSellPanel({ onSold }) {
      // Step: category → instance → price/qty/mode → confirm
      const [step, setStep] = useState("cat"); // cat | item | form
      const [cat, setCat] = useState(null);
      const [picked, setPicked] = useState(null);
      const [price, setPrice] = useState(1000);
      const [qty, setQty] = useState(1);
      const [isAuction, setIsAuction] = useState(false);
      const [duration, setDuration] = useState(48);
      const [busy, setBusy] = useState(false);
      const [err, setErr] = useState(null);
      const inv = useApi("market/my_inventory", null, []);

      function resetAll() {
        setStep("cat"); setCat(null); setPicked(null);
        setPrice(1000); setQty(1); setIsAuction(false); setDuration(48);
        setErr(null);
      }

      async function doList() {
        if (busy) return;
        setBusy(true);
        setErr(null);
        try {
          const res = await api("market/list_sell", {
            item_type: cat,
            instance_id: picked.instance_id,
            qty,
            price: parseInt(price) || 0,
            is_auction: isAuction,
            duration_hours: duration,
          });
          if (!res.ok) {
            setErr(res.reason || "engine_error");
            haptic("error");
            setBusy(false);
            return;
          }
          haptic("success");
          showToast(t("market_sell_success"));
          resetAll();
          onSold && onSold();
        } catch (e) {
          setErr(e.message || "engine_error");
          haptic("error");
        }
        setBusy(false);
      }

      if (inv.loading && !inv.data) return <ListSkeleton rows={4} />;
      if (inv.error && !inv.data) return <ErrBanner msg={inv.error} />;

      const items = (inv.data && inv.data.items) || {};

      if (step === "cat") {
        return (
          <Card>
            <CardTitle left={t("market_sell_pick_category")} />
            <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:8 }}>
              {["herb", "pill", "ore", "artifact", "cauldron"].map(c => {
                const count = (items[c] || []).length;
                const disabled = count === 0;
                return (
                  <button key={c} disabled={disabled}
                          onClick={() => { setCat(c); setStep("item"); haptic("select"); }}
                          style={{
                            padding:"12px 8px", borderRadius:10,
                            cursor: disabled ? "default" : "pointer",
                            background: disabled ? "rgba(var(--surface-rgb),.3)" : "rgba(var(--surface-rgb),.7)",
                            border:`1px solid ${disabled ? "var(--border)" : "var(--gold2)"}`,
                            opacity: disabled ? .4 : 1,
                          }}>
                    <div style={{ fontSize:24 }}>{_MKT_TYPE_ICON[c]}</div>
                    <div style={{ fontSize:11, marginTop:4, fontFamily:"'Cinzel',serif",
                                  color:"var(--gold3)", textTransform:"uppercase", letterSpacing:.4 }}>
                      {t("market_cat_" + c)}
                    </div>
                    <div style={{ fontSize:10, color:"var(--muted)", marginTop:2 }}>
                      {count > 0 ? `${count} ${t("market_items_count")}` : t("market_no_items")}
                    </div>
                  </button>
                );
              })}
            </div>
          </Card>
        );
      }

      if (step === "item") {
        const list = items[cat] || [];
        return (
          <Card>
            <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between", marginBottom:8 }}>
              <CardTitle left={t("market_sell_pick_item") + " — " + t("market_cat_" + cat)} />
              <ActionBtn variant="ghost" onClick={() => { setStep("cat"); haptic("light"); }}>
                ◀ {t("btn_back")}
              </ActionBtn>
            </div>
            {list.length === 0 ? (
              <div style={{ textAlign:"center", padding:"18px 8px", color:"var(--muted)", fontSize:12 }}>
                {t("market_no_items")}
              </div>
            ) : (
              <div style={{ display:"flex", flexDirection:"column", gap:6 }}>
                {list.map(it => (
                  <button key={it.instance_id}
                          onClick={() => {
                            setPicked(it);
                            setQty(it.quantity > 1 ? Math.min(it.quantity, 1) : 1);
                            setStep("form"); haptic("select");
                          }}
                          style={{
                            display:"flex", alignItems:"center", gap:9, padding:"9px 10px",
                            borderRadius:9, cursor:"pointer",
                            background:"rgba(var(--surface-rgb),.6)", border:"1px solid var(--border)",
                            textAlign:"left",
                          }}>
                    <span style={{ fontSize:22 }}>{it.grade_emoji || _MKT_TYPE_ICON[cat]}</span>
                    <span style={{ flex:1, minWidth:0,
                                   whiteSpace:"nowrap", overflow:"hidden", textOverflow:"ellipsis",
                                   color:"var(--text)", fontSize:13, fontWeight:600 }}>
                      {it.name}
                    </span>
                    {it.quantity > 1 && <Badge variant="gold">x{it.quantity}</Badge>}
                    {it.has_spirit && <span title="Spirit">✨</span>}
                  </button>
                ))}
              </div>
            )}
          </Card>
        );
      }

      // step === "form"
      const stackable = (cat === "herb" || cat === "pill" || cat === "ore");
      return (
        <Card>
          <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between", marginBottom:8 }}>
            <CardTitle left={t("market_sell_pricing")} />
            <ActionBtn variant="ghost" onClick={() => { setStep("item"); setErr(null); haptic("light"); }}>
              ◀ {t("btn_back")}
            </ActionBtn>
          </div>
          <div style={{ display:"flex", alignItems:"center", gap:9, marginBottom:12 }}>
            <span style={{ fontSize:28 }}>{picked.grade_emoji || _MKT_TYPE_ICON[cat]}</span>
            <div style={{ flex:1, minWidth:0 }}>
              <div style={{ fontWeight:700, fontSize:14, fontFamily:"'Cinzel',serif", color:"var(--gold3)" }}>
                {picked.name}
              </div>
              {picked.quantity > 1 && (
                <div style={{ fontSize:11, color:"var(--muted)" }}>{t("market_sell_stack_avail", { n: picked.quantity })}</div>
              )}
            </div>
          </div>

          {stackable && picked.quantity > 1 && (
            <>
              <div style={{ fontSize:11, color:"var(--muted)", marginBottom:5 }}>{t("market_sell_qty_label")}</div>
              <input type="number" inputMode="numeric" value={qty}
                     min={1} max={picked.quantity}
                     onChange={(e) => setQty(Math.max(1, Math.min(picked.quantity, parseInt(e.target.value) || 1)))}
                     style={{
                       width:"100%", padding:"9px 10px", borderRadius:8, marginBottom:10,
                       background:"rgba(var(--surface2-rgb),.85)", border:"1px solid var(--border2)",
                       color:"var(--text)", fontSize:13, fontWeight:700,
                     }} />
            </>
          )}

          <div style={{ fontSize:11, color:"var(--muted)", marginBottom:5 }}>
            {t("market_sell_price_label")} ({stackable ? t("market_sell_price_unit") : t("market_sell_price_total")})
          </div>
          <input type="number" inputMode="numeric" value={price}
                 min={1}
                 onChange={(e) => setPrice(e.target.value)}
                 style={{
                   width:"100%", padding:"9px 10px", borderRadius:8, marginBottom:10,
                   background:"rgba(var(--surface2-rgb),.85)", border:"1px solid var(--border2)",
                   color:"var(--text)", fontSize:13, fontWeight:700,
                 }} />

          <div style={{ fontSize:11, color:"var(--muted)", marginBottom:5 }}>{t("market_sell_mode_label")}</div>
          <SegControl
            options={[
              { value:"direct",  label: `💰 ${t("market_sell_mode_direct")}` },
              { value:"auction", label: `🔨 ${t("market_sell_mode_auction")}` },
            ]}
            value={isAuction ? "auction" : "direct"}
            onChange={(v) => setIsAuction(v === "auction")}
          />

          <div style={{ fontSize:11, color:"var(--muted)", margin:"10px 0 5px" }}>{t("market_sell_duration_label")}</div>
          <SegControl
            options={[
              { value:12, label:"12h" },
              { value:24, label:"24h" },
              { value:48, label:"48h" },
              { value:72, label:"3d" },
            ]}
            value={duration}
            onChange={(v) => setDuration(parseInt(v))}
          />

          {err && (
            <div style={{ marginTop:10 }}>
              <ErrBanner msg={t("market_err_" + err)} />
            </div>
          )}

          <ActionBtn variant="primary" disabled={busy || (parseInt(price) || 0) <= 0 || qty <= 0}
                     onClick={doList}
                     style={{ width:"100%", marginTop:12 }}>
            {busy ? <DotSpinner /> : (isAuction
              ? `🔨 ${t("market_sell_btn_start_auction")} — ${fmtNum(price)}`
              : `💰 ${t("market_sell_btn_create")} — ${fmtNum(price * (stackable ? qty : 1))}`)}
          </ActionBtn>
        </Card>
      );
    }

    // ─── MA-42 Dao Laws Modal (Sprint v14.12) ────────────────────────────────
    // Drill-in from CultivationTab (owner override 2026-05-06: NOT a new tab).
    // 3 sub-views via SegControl:
    //   "supreme"   — fragment-based Supreme Laws (6 laws + insight progress)
    //   "discoveries" — 3000 Laws categories → drill into category → paths
    //   "meditation"  — start/cancel Dao Meditations (passive discovery vector)
    //
    // Engine in core/dao_engine.py + core/dao_laws_engine.py is source-of-truth.
    // Discovery is PASSIVE (no pick mechanic) — happens during meditation tick.
    var _DAO_RARITY_COLOR = {
      common:"var(--realm-0)", uncommon:"#22c55e", rare:"var(--realm-5)",
      epic:"var(--realm-3)", legendary:"var(--warn)",
    };

    function DaoLawsModal({ onClose, onChanged }) {
      const [view, setView] = useState("supreme"); // supreme | discoveries | meditation
      const [reload, setReload] = useState(0);
      const { data, loading, error } = useApi("dao/summary", null, [reload]);
      const [pickedCat, setPickedCat] = useState(null);
      const [pickedPath, setPickedPath] = useState(null);
      const [meditatingNow, setMeditatingNow] = useState(false);

      const segOpts = [
        { value:"supreme",     label: t("dao_seg_supreme") },
        { value:"discoveries", label: t("dao_seg_discoveries") },
        { value:"meditation",  label: t("dao_seg_meditation") },
      ];

      // Locked early — show empty state.
      const locked = data && !data.unlocked;

      async function startMeditation(medKey) {
        if (meditatingNow) return;
        setMeditatingNow(true);
        try {
          const res = await api("dao/meditate_start", { med_key: medKey });
          if (!res.ok) {
            haptic("error");
            showToast(t("dao_med_err_" + (res.reason || "engine_error")), "err");
          } else {
            haptic("success");
            showToast(t("dao_med_started"));
            setReload(x => x + 1);
            onChanged && onChanged();
          }
        } catch (e) {
          haptic("error");
          showToast(e.message || "Error", "err");
        }
        setMeditatingNow(false);
      }

      async function cancelMeditation() {
        if (meditatingNow) return;
        setMeditatingNow(true);
        try {
          const res = await api("dao/meditate_cancel");
          haptic("success");
          showToast(t("dao_med_cancelled"));
          setReload(x => x + 1);
          onChanged && onChanged();
        } catch (e) {
          haptic("error");
          showToast(e.message || "Error", "err");
        }
        setMeditatingNow(false);
      }

      const footer = (
        <ActionBtn variant="ghost" onClick={onClose} style={{ width:"100%" }}>
          {t("btn_close")}
        </ActionBtn>
      );

      return (
        <Modal open={true} onClose={onClose}
               title={`🌌 ${t("dao_modal_title")}`}
               accent="rgba(var(--realm-3-rgb),.5)"
               maxWidth={400} zIndex={70}
               footer={footer}>
          {loading && !data && <ListSkeleton rows={5} />}
          {error && !data && <ErrBanner msg={error} />}
          {locked && (
            <Card>
              <div style={{ textAlign:"center", padding:"24px 8px" }}>
                <div style={{ fontSize:48, opacity:.6, ...(markOn("lock") ? { display:"grid", placeItems:"center" } : {}) }}>{ico("🔒","lock",{ size:50 })}</div>
                <div style={{ marginTop:10, fontSize:13, color:"var(--muted)" }}>
                  {t("dao_sealed_desc", { realm: data.min_realm_name || "Soul Transformation" })}
                </div>
              </div>
            </Card>
          )}
          {data && data.unlocked && (
            <>
              <Card>
                <SegControl options={segOpts} value={view} onChange={setView} />
                <div style={{ display:"flex", justifyContent:"space-between",
                              marginTop:8, fontSize:11, color:"var(--muted)" }}>
                  <span>{t("dao_total_discovered", { n: data.total_discovered, total: data.total_laws_global })}</span>
                  {data.dao_heart_paths > 0 && (
                    <span style={{ color:"var(--gold3)" }}>
                      ★★★★★ × {data.dao_heart_paths}
                    </span>
                  )}
                </div>
              </Card>

              {view === "supreme" && <DaoSupremeView laws={data.supreme_laws} />}
              {view === "discoveries" && (
                <DaoDiscoveriesView
                  categories={data.categories}
                  pickedCat={pickedCat} setPickedCat={setPickedCat}
                  pickedPath={pickedPath} setPickedPath={setPickedPath}
                />
              )}
              {view === "meditation" && (
                <DaoMeditationView
                  medActive={data.meditation.active}
                  medType={data.meditation.type}
                  remainSeconds={data.meditation.remaining_seconds}
                  endsMs={data.meditation.ends_at_ms}
                  types={data.meditation_types}
                  qi={data.qi}
                  trials={data.celestial_trials_passed}
                  busy={meditatingNow}
                  onStart={startMeditation}
                  onCancel={cancelMeditation}
                  comprehension={data.comprehension}
                />
              )}
            </>
          )}
        </Modal>
      );
    }

    function DaoSupremeView({ laws }) {
      if (!laws || laws.length === 0) {
        return (
          <Card>
            <div style={{ textAlign:"center", padding:"18px 8px", color:"var(--muted)", fontSize:12 }}>
              {t("dao_supreme_empty")}
            </div>
          </Card>
        );
      }
      return (
        <>
          {laws.map(law => {
            const pct = law.total > 0 ? Math.min(100, (law.frags / law.total) * 100) : 0;
            const rarityTag = law.rarity === "endgame"
              ? t("dao_rarity_endgame")
              : law.rarity === "rare"
                ? t("dao_rarity_rare")
                : "";
            if (law.locked) {
              return (
                <Card key={law.id} style={{ opacity:.6 }}>
                  <div style={{ display:"flex", justifyContent:"space-between", alignItems:"baseline" }}>
                    <div>
                      <span style={{ fontSize:18 }}>{ico("🔒","lock",{ size:18, style:{ display:"inline-block", verticalAlign:"-3px" } })}</span>{" "}
                      <b style={{ fontFamily:"'Cinzel',serif", color:"var(--muted)" }}>{law.name}</b>
                      {rarityTag && <span style={{ marginLeft:6, fontSize:10, color:"var(--gold2)" }}>{rarityTag}</span>}
                    </div>
                  </div>
                  <div style={{ fontSize:11, color:"var(--muted)", marginTop:4 }}>
                    {t("dao_locked_at_realm", { realm: law.min_realm })}
                  </div>
                </Card>
              );
            }
            return (
              <Card key={law.id}>
                <div style={{ display:"flex", justifyContent:"space-between", alignItems:"baseline" }}>
                  <div style={{ flex:1, minWidth:0 }}>
                    <span style={{ fontSize:18 }}>{law.emoji}</span>{" "}
                    <b style={{ fontFamily:"'Cinzel',serif", color: law.is_eternal ? "var(--gold3)" : "var(--text)" }}>{law.name}</b>
                    {rarityTag && <span style={{ marginLeft:6, fontSize:10, color:"var(--gold2)" }}>{rarityTag}</span>}
                    {law.completed && <Badge variant="jade">✨ {t("dao_completed")}</Badge>}
                  </div>
                  <div style={{ fontSize:11, color:"var(--gold3)", fontWeight:700 }}>
                    {law.frags}/{law.total}
                  </div>
                </div>
                <ProgressBar pct={pct} variant="cult" />
                {law.insight_level > 0 && (
                  <div style={{ fontSize:10, color:"var(--muted)", marginTop:4 }}>
                    {"⭐".repeat(law.insight_level)} · ×{law.insight_mult.toFixed(2)} {t("dao_effect_label")}
                  </div>
                )}
                <div style={{ fontSize:11, color:"var(--gold2)", marginTop:4 }}>
                  {t("dao_effect_" + law.effect_type, { pct: law.effect_pct.toFixed(0) })}
                </div>
              </Card>
            );
          })}
        </>
      );
    }

    function DaoDiscoveriesView({ categories, pickedCat, setPickedCat, pickedPath, setPickedPath }) {
      // 3-level navigation: categories → paths → laws (laws via dao/path endpoint)
      if (pickedPath) {
        return <DaoPathDetail pathId={pickedPath.id} onBack={() => setPickedPath(null)} />;
      }
      if (pickedCat) {
        const cat = categories.find(c => c.id === pickedCat);
        if (!cat) return null;
        return (
          <>
            <Card>
              <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between", marginBottom:6 }}>
                <CardTitle left={`${cat.emoji} ${cat.name}`}
                           right={`${cat.discovered}/${cat.total_laws}`} />
                <ActionBtn variant="ghost" onClick={() => setPickedCat(null)}>
                  ◀ {t("btn_back")}
                </ActionBtn>
              </div>
              <div style={{ fontSize:11, color:"var(--muted)" }}>
                {t("dao_cat_bonus_type", { bonus: t("dao_bonus_" + cat.bonus_type) })}
              </div>
            </Card>
            {(cat.paths || []).map(p => {
              const pct = p.total > 0 ? Math.min(100, (p.discovered / p.total) * 100) : 0;
              if (p.locked) {
                return (
                  <Card key={p.id} style={{ opacity:.55 }}>
                    <div style={{ display:"flex", justifyContent:"space-between" }}>
                      <span><span style={{ fontSize:16 }}>{ico("🔒","lock",{ size:16, style:{ display:"inline-block", verticalAlign:"-3px" } })}</span> <b>{p.name}</b></span>
                      <span style={{ fontSize:11, color:"var(--muted)" }}>
                        {t("dao_locked_at_realm", { realm: p.min_realm })}
                      </span>
                    </div>
                  </Card>
                );
              }
              return (
                <Card key={p.id} style={{ cursor:"pointer" }}
                      onClick={() => { setPickedPath(p); haptic("select"); }}>
                  <div style={{ display:"flex", justifyContent:"space-between", alignItems:"baseline" }}>
                    <span>
                      <span style={{ fontSize:18 }}>{p.emoji}</span>{" "}
                      <b style={{ fontFamily:"'Cinzel',serif" }}>{p.name}</b>
                    </span>
                    <span style={{ fontSize:11, color:"var(--gold3)", fontWeight:700 }}>
                      {p.discovered}/{p.total}
                    </span>
                  </div>
                  <ProgressBar pct={pct} variant="cult" />
                  <div style={{ display:"flex", justifyContent:"space-between", fontSize:10, color:"var(--muted)", marginTop:4 }}>
                    <span>{p.tier_stars || "—"} {p.tier_name}</span>
                    {p.tier_bonus > 0 && <span style={{ color:"var(--jade)" }}>+{(p.tier_bonus * 100).toFixed(0)}%</span>}
                  </div>
                </Card>
              );
            })}
          </>
        );
      }
      // Categories overview
      if (!categories || categories.length === 0) {
        return (
          <Card>
            <div style={{ textAlign:"center", padding:"18px 8px", color:"var(--muted)", fontSize:12 }}>
              {t("dao_3000_empty")}
            </div>
          </Card>
        );
      }
      return (
        <>
          {categories.map(cat => (
            <Card key={cat.id}
                  style={{ cursor: cat.locked ? "default" : "pointer", opacity: cat.locked ? .55 : 1 }}
                  onClick={cat.locked ? undefined : () => { setPickedCat(cat.id); haptic("select"); }}>
              <div style={{ display:"flex", justifyContent:"space-between", alignItems:"baseline" }}>
                <span>
                  <span style={{ fontSize:20 }}>{cat.locked ? "🔒" : cat.emoji}</span>{" "}
                  <b style={{ fontFamily:"'Cinzel',serif" }}>{cat.name}</b>
                </span>
                <span style={{ fontSize:11, color:"var(--gold3)", fontWeight:700 }}>
                  {cat.discovered}/{cat.total_laws}
                </span>
              </div>
              {cat.locked ? (
                <div style={{ fontSize:11, color:"var(--muted)", marginTop:4 }}>
                  {t("dao_locked_at_realm", { realm: cat.min_realm })}
                </div>
              ) : (
                <div style={{ fontSize:11, color:"var(--muted)", marginTop:4 }}>
                  {t("dao_cat_bonus_type", { bonus: t("dao_bonus_" + cat.bonus_type) })}
                </div>
              )}
            </Card>
          ))}
        </>
      );
    }

    function DaoPathDetail({ pathId, onBack }) {
      const [page, setPage] = useState(1);
      const { data, loading, error } = useApi("dao/path", { path_id: pathId, page }, [pathId, page]);
      if (loading && !data) return <ListSkeleton rows={4} />;
      if (error || !data || !data.ok) return <ErrBanner msg={(data && data.reason) || error || "error"} />;
      const p = data.path;
      const pct = p.total > 0 ? Math.min(100, (p.discovered / p.total) * 100) : 0;
      return (
        <>
          <Card>
            <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between", marginBottom:6 }}>
              <CardTitle left={`${p.emoji} ${p.name}`}
                         right={`${p.discovered}/${p.total}`} />
              <ActionBtn variant="ghost" onClick={onBack}>◀ {t("btn_back")}</ActionBtn>
            </div>
            <ProgressBar pct={pct} variant="cult" />
            <div style={{ display:"flex", justifyContent:"space-between", marginTop:6, fontSize:11 }}>
              <span style={{ color:"var(--muted)" }}>
                {p.tier_stars || "—"} {p.tier_name}
              </span>
              {p.tier_bonus > 0 && (
                <span style={{ color:"var(--jade)" }}>
                  +{(p.tier_bonus * 100).toFixed(0)}% {t("dao_bonus_" + p.bonus_type)}
                </span>
              )}
            </div>
            {p.is_heavenly && (
              <div style={{ marginTop:6 }}>
                <Badge variant="gold">🌠 {t("dao_path_heavenly")}</Badge>
              </div>
            )}
          </Card>
          <Card>
            <CardTitle left={t("dao_path_laws_header")} />
            {data.laws.length === 0 ? (
              <div style={{ textAlign:"center", padding:"14px 8px", color:"var(--muted)", fontSize:12 }}>
                {t("dao_path_no_laws")}
              </div>
            ) : (
              <div style={{ display:"flex", flexDirection:"column", gap:5 }}>
                {data.laws.map((law, i) => (
                  <div key={i} style={{
                    display:"flex", justifyContent:"space-between", alignItems:"center",
                    padding:"7px 8px", borderRadius:7, background:"rgba(var(--surface-rgb),.45)",
                  }}>
                    <span style={{ flex:1, minWidth:0,
                                   whiteSpace:"nowrap", overflow:"hidden", textOverflow:"ellipsis" }}>
                      <span style={{ fontSize:14 }}>{law.rarity_emoji}</span>{" "}
                      <span style={{
                        fontSize:12, color: _DAO_RARITY_COLOR[law.rarity] || "var(--text)",
                      }}>{law.name}</span>
                    </span>
                  </div>
                ))}
              </div>
            )}
            {data.total_pages > 1 && (
              <div style={{ display:"flex", justifyContent:"space-between", gap:8, marginTop:8 }}>
                <ActionBtn variant="ghost" disabled={page <= 1}
                           onClick={() => setPage(p => Math.max(1, p - 1))}>
                  ◀ {t("page_prev")}
                </ActionBtn>
                <div style={{ display:"flex", alignItems:"center", fontSize:12, color:"var(--muted)" }}>
                  {page} / {data.total_pages}
                </div>
                <ActionBtn variant="ghost" disabled={page >= data.total_pages}
                           onClick={() => setPage(p => p + 1)}>
                  {t("page_next")} ▶
                </ActionBtn>
              </div>
            )}
          </Card>
        </>
      );
    }

    // TAPETE QoL §5 item 11 ([jogador]) — comprehension-speed disclosure card.
    // Component-by-component (the wsect breakdown pattern): perception drives
    // Supreme fragments linearly (saturates at 100%/tick); 3000-Laws
    // discovery DECAYS with progress and perception only shifts rarity
    // (capped ×2). Numbers come server-side from the canonical helper.
    function DaoComprehensionCard({ comp }) {
      if (!comp) return null;
      const remaining = (comp.laws_accessible || 0) - (comp.laws_discovered || 0);
      return (
        <Card style={{ borderColor:"rgba(var(--realm-3-rgb),.35)" }}>
          <CardTitle left={`📖 ${t("dao_comp_header_mini")}`} />
          <div style={{ display:"flex", flexDirection:"column", gap:5, fontSize:11, lineHeight:1.5 }}>
            <div style={{ display:"flex", justifyContent:"space-between", gap:8 }}>
              <span style={{ color:"var(--muted)" }}>🔮 {t("dao_comp_perception_chip")}</span>
              <b style={{ color:"var(--gold2)" }}>{fmtNum(comp.perception_total)}</b>
            </div>
            <div style={{ display:"flex", justifyContent:"space-between", gap:8 }}>
              <span style={{ color:"var(--muted)" }}>🧩 {t("dao_comp_fragments_chip")}</span>
              <b style={{ color:"var(--jade)" }}>
                {comp.fragment_chance_pct}%{comp.fragment_capped ? " · MAX" : ""}
              </b>
            </div>
            {comp.laws_accessible > 0 && (
              <div style={{ display:"flex", justifyContent:"space-between", gap:8 }}>
                <span style={{ color:"var(--muted)" }}>🧭 {t("dao_comp_discovery_chip", { remaining, total: comp.laws_accessible })}</span>
                <b style={{ color:"var(--gold2)" }}>{comp.discovery_chance_pct}%</b>
              </div>
            )}
            <div style={{ display:"flex", justifyContent:"space-between", gap:8 }}>
              <span style={{ color:"var(--muted)" }}>✨ {t("dao_comp_rarity_chip")}</span>
              <b style={{ color:"var(--gold2)" }}>
                ×{comp.perception_rarity_factor}{comp.perception_rarity_capped ? " · MAX" : ""}
              </b>
            </div>
            <div style={{ fontSize:10, color:"var(--muted2)", marginTop:3, fontStyle:"italic" }}>
              {t("dao_comp_note")}
            </div>
          </div>
        </Card>
      );
    }

    function DaoMeditationView({ medActive, medType, remainSeconds, endsMs, types, qi, trials, busy, onStart, onCancel, comprehension }) {
      const remainMs = medActive && endsMs ? Math.max(0, endsMs - Date.now()) : 0;
      if (medActive) {
        const curType = types.find(t_ => t_.key === medType);
        return (
          <>
            <Card>
              <CardTitle left={`🧘 ${t("dao_med_active_title")}`} />
              <div style={{ fontSize:14, fontWeight:700, color:"var(--gold3)", fontFamily:"'Cinzel',serif" }}>
                {curType ? curType.name : medType}
              </div>
              <div style={{ display:"flex", justifyContent:"space-between", marginTop:8, fontSize:12 }}>
                <span style={{ color:"var(--muted)" }}>{t("ends_in")}</span>
                <b style={{ color:"var(--gold2)" }}>{fmtDuration(remainMs)}</b>
              </div>
              <ActionBtn variant="danger" disabled={busy}
                         onClick={onCancel}
                         style={{ width:"100%", marginTop:10 }}>
                {busy ? <DotSpinner /> : t("dao_med_cancel")}
              </ActionBtn>
            </Card>
            {/* Disclosure visible exactly when the ticks apply (review 2026-06-12). */}
            <DaoComprehensionCard comp={comprehension} />
          </>
        );
      }
      return (
        <>
          <Card>
            <div style={{ fontSize:11, color:"var(--muted)", lineHeight:1.45 }}>
              {t("dao_med_intro")}
            </div>
            <div style={{ display:"flex", justifyContent:"space-between", marginTop:8, fontSize:11 }}>
              <span style={{ color:"var(--muted)" }}>💧 {t("qi")}</span>
              <b>{fmtNum(qi)}</b>
            </div>
            <div style={{ display:"flex", justifyContent:"space-between", marginTop:3, fontSize:11 }}>
              <span style={{ color:"var(--muted)" }}>{t("dao_trials_passed")}</span>
              <b>{trials}</b>
            </div>
          </Card>
          <DaoComprehensionCard comp={comprehension} />
          {(types || []).map(med => {
            const lockReason = med.lock_reason;
            const available = med.available;
            return (
              <Card key={med.key} style={{ opacity: available ? 1 : .55 }}>
                <div style={{ display:"flex", justifyContent:"space-between", alignItems:"baseline" }}>
                  <span style={{ fontFamily:"'Cinzel',serif", fontWeight:700, fontSize:13 }}>
                    {med.name}
                  </span>
                  <span style={{ fontSize:11, color:"var(--gold2)", fontWeight:700 }}>
                    ×{med.fragment_mult.toFixed(0)}
                  </span>
                </div>
                <div style={{ display:"flex", justifyContent:"space-between", fontSize:10, color:"var(--muted)", marginTop:4 }}>
                  <span>⏳ {med.duration_minutes}min</span>
                  <span>💧 {med.qi_cost}</span>
                  <span>{t("dao_med_min_realm", { n: med.min_realm })}</span>
                </div>
                {lockReason && (
                  <div style={{ fontSize:11, color:"var(--warn)", marginTop:5 }}>
                    🔒 {t("dao_med_lock_" + lockReason)}
                  </div>
                )}
                <ActionBtn variant={available ? "primary" : "ghost"}
                           disabled={!available || busy}
                           onClick={() => onStart(med.key)}
                           style={{ width:"100%", marginTop:8 }}>
                  {busy ? <DotSpinner /> : `🧘 ${t("dao_med_start")}`}
                </ActionBtn>
              </Card>
            );
          })}
        </>
      );
    }

    // ─── MA-43 Celestial Tab (Sprint v14.13) ─────────────────────────────────
    // Full Celestial / Mahayana dashboard. Drill-in via Home card 🌠. Realm-
    // gated to 8+ — empty state for realm <8 with launch-teaser flavor.
    //
    // Pillars surfaced (mirrors handlers/celestial._build_dashboard):
    //   1. Trials (1/2/3) — passed badges + preview chance + attempt CTA
    //   2. Heavenly Dao bonus (5+ tier-4 paths → +25% all_mult)
    //   3. Body Transformation (Body Tempering tier 10+)
    //   4. Celestial Resonance (grade-8 equipped artifacts set bonus)
    //   5. Heavenly Laws progress (F-11.5 — 100 laws via celestial_dao med)
    //   6. Apex card (D-6a) when player is approaching realm 10 IX
    //
    // Trial attempt uses a cinematic 3-phase flow: charging → resolving → reveal.
    // Modal NEVER uses compact={true} — content is dynamic (preview, trials list,
    // heavenly progress) and iOS WebKit collapse risk is real (HF v14.10 lesson).
    function CelestialTab({ player, onPlayerRefresh }) {
      const [reload, setReload] = useState(0);
      const { data, loading, error } = useApi("celestial/status", null, [reload]);
      const [view, setView] = useState("dashboard"); // dashboard | heavenly_paths
      const [trialPhase, setTrialPhase] = useState(null); // null | charging | reveal
      const [trialResult, setTrialResult] = useState(null);
      // v14.14d — Apex Reflection Chamber drill-in modal (visible só se Apex).
      const [showApex, setShowApex] = useState(false);

      function refreshAll() {
        setReload(x => x + 1);
        if (onPlayerRefresh) onPlayerRefresh();
      }

      async function attemptTrial() {
        setTrialPhase("charging");
        setTrialResult(null);
        haptic("warning");
        try {
          const res = await api("celestial/trial_attempt");
          if (!res.ok) {
            haptic("error");
            showToast(t("cel_err_" + (res.reason || "engine_error")), "err");
            setTrialPhase(null);
            return;
          }
          // Brief charge animation, then reveal.
          await new Promise(r => setTimeout(r, 1200));
          setTrialResult(res);
          setTrialPhase("reveal");
          haptic(res.success ? "success" : "error");
          // Trial attempt always changes player state — refresh.
          if (onPlayerRefresh) onPlayerRefresh();
        } catch (e) {
          haptic("error");
          showToast(e.message || "Error", "err");
          setTrialPhase(null);
        }
      }

      function closeTrialModal() {
        setTrialPhase(null);
        setTrialResult(null);
        refreshAll();
      }

      if (loading && !data) return <ListSkeleton rows={5} />;
      if (error && !data) return <ErrBanner msg={error} />;
      if (!data) return null;

      // ── Locked state — realm < 8 ─────────────────────────────────────────
      if (!data.unlocked) {
        return (
          <div>
            <Card>
              <div style={{ textAlign:"center", padding:"28px 14px" }}>
                <div style={{ fontSize:54, opacity:.55, marginBottom:8 }}>🌠</div>
                <div style={{ fontFamily:"'Cinzel',serif", fontSize:15,
                              color:"var(--gold2)", letterSpacing:.5 }}>
                  {t("cel_locked_title")}
                </div>
                <div style={{ fontSize:11.5, color:"var(--muted)", marginTop:10, lineHeight:1.55 }}>
                  {t("cel_locked_hint", {
                    realm: data.min_realm_name || "Mahayana",
                    n: data.min_realm_required,
                  })}
                </div>
                <div style={{ marginTop:14, fontSize:10.5, color:"var(--gold3)",
                              fontStyle:"italic", opacity:.8 }}>
                  {t("cel_locked_teaser")}
                </div>
              </div>
            </Card>
          </div>
        );
      }

      if (view === "heavenly_paths") {
        return <CelestialHeavenlyPathsPanel onBack={() => setView("dashboard")} />;
      }

      // ── Unlocked dashboard ───────────────────────────────────────────────
      return (
        <div>
          {/* Header — passed counter + essence/fragments balances */}
          <Card style={{ padding:"12px 14px 10px" }}>
            <div style={{ display:"flex", alignItems:"center",
                          justifyContent:"space-between", gap:10 }}>
              <div>
                <div style={{ fontFamily:"'Cinzel',serif", fontSize:13,
                              letterSpacing:.6, color:"var(--gold2)" }}>
                  🌠 {t("cel_title")}
                </div>
                <div style={{ fontSize:10.5, color:"var(--muted)", marginTop:2 }}>
                  {t("cel_subtitle")}
                </div>
              </div>
              <div style={{ textAlign:"right" }}>
                <div style={{ fontFamily:"'Cinzel',serif", fontSize:18,
                              color:"var(--gold3)", fontWeight:700 }}>
                  {data.trials_passed} / {data.trials_max}
                </div>
                <div style={{ fontSize:10, color:"var(--muted)", letterSpacing:.4 }}>
                  {t("cel_trials_passed")}
                </div>
              </div>
            </div>
            <div style={{ display:"flex", gap:10, marginTop:10 }}>
              <CelChip emoji="✨" label={t("cel_essence")} value={fmtNum(data.celestial_essence)} />
              <CelChip emoji="💠" label={t("cel_fragments")} value={fmtNum(data.celestial_fragments)} />
            </div>
          </Card>

          {/* Trials — 3 cards in a row with status badge */}
          <Card>
            <CardTitle left={t("cel_section_trials")} />
            <div style={{ display:"flex", flexDirection:"column", gap:8 }}>
              {data.trials.map(tr => (
                <CelTrialRow key={tr.trial_num} trial={tr}
                             passed={tr.passed}
                             current={!tr.passed && tr.trial_num === data.trial_next_num} />
              ))}
            </div>

            {/* Preview + attempt CTA */}
            {data.preview && data.trial_can_attempt && (
              <div style={{ marginTop:10, padding:"10px 11px",
                            background:"rgba(var(--realm-8-rgb),.08)",
                            border:"1px solid rgba(var(--realm-8-rgb),.32)",
                            borderRadius:10 }}>
                <div style={{ fontFamily:"'Cinzel',serif", fontSize:11,
                              color:"var(--realm-8)", letterSpacing:.5 }}>
                  {t("cel_preview_header", { trial: data.preview.trial_num })}
                </div>
                <div style={{ display:"flex", justifyContent:"space-between",
                              marginTop:6, fontSize:12 }}>
                  <span style={{ color:"var(--muted)" }}>{t("cel_full_clear")}</span>
                  <b style={{ color:"var(--gold3)" }}>
                    {Math.round(data.preview.full_clear_chance * 100)}%
                  </b>
                </div>
                <div style={{ display:"flex", justifyContent:"space-between",
                              marginTop:3, fontSize:11 }}>
                  <span style={{ color:"var(--muted)" }}>{t("cel_per_round")}</span>
                  <span>{Math.round(data.preview.per_round_chance * 100)}% × {data.preview.rounds}</span>
                </div>
                {(data.preview.heavenly_dao_bonus > 0 ||
                  data.preview.trib_3000_bonus > 0 ||
                  data.preview.trib_blessing_bonus > 0 ||
                  data.preview.insurance_active) && (
                  <div style={{ marginTop:6, fontSize:10.5, color:"var(--jade)",
                                display:"flex", flexDirection:"column", gap:2 }}>
                    {data.preview.heavenly_dao_bonus > 0 && (
                      <span>🌌 {t("cel_bonus_heavenly_dao", { pct: Math.round(data.preview.heavenly_dao_bonus * 100) })}</span>
                    )}
                    {data.preview.trib_3000_bonus > 0 && (
                      <span>道 {t("cel_bonus_trib3000", { pct: Math.round(data.preview.trib_3000_bonus * 100) })}</span>
                    )}
                    {data.preview.trib_blessing_bonus > 0 && (
                      <span>🍵 {t("cel_bonus_blessing", { pct: Math.round(data.preview.trib_blessing_bonus * 100) })}</span>
                    )}
                    {data.preview.insurance_active && <span>🛡️ {t("cel_bonus_insurance")}</span>}
                  </div>
                )}
                <ActionBtn variant="primary" onClick={attemptTrial}
                           disabled={trialPhase !== null}
                           style={{ width:"100%", marginTop:10 }}>
                  ⚡ {t("cel_btn_attempt")}
                </ActionBtn>
              </div>
            )}

            {/* Block reasons — cooldown / sub_layer / all_passed */}
            {!data.trial_can_attempt && data.trial_block_reason_key && (
              <div style={{ marginTop:10, padding:"8px 10px",
                            background:"rgba(var(--warn-rgb),.10)",
                            border:"1px solid rgba(var(--warn-rgb),.30)",
                            borderRadius:8, fontSize:11.5, color:"var(--warn)" }}>
                {data.trial_block_reason_key === "celestial_on_cooldown" &&
                  `⏳ ${t("cel_block_cooldown", { time: fmtDuration(data.trial_cooldown_remaining_s * 1000) })}`}
                {data.trial_block_reason_key === "celestial_need_sublayer" &&
                  `🔒 ${t("cel_block_need_sub", { sub: data.trial_need_sub_layer })}`}
                {data.trial_block_reason_key === "celestial_all_passed" &&
                  `✅ ${t("cel_block_all_passed")}`}
              </div>
            )}
          </Card>

          {/* Heavenly Dao bonus pillar */}
          <Card>
            <CardTitle left={`🌌 ${t("cel_heavenly_dao_header")}`} />
            {data.heavenly_dao.unlocked ? (
              <div>
                <div style={{ display:"flex", justifyContent:"space-between",
                              fontSize:12 }}>
                  <span style={{ color:"var(--muted)" }}>{t("cel_qualifying_paths")}</span>
                  <b>{data.heavenly_dao.qualifying} / {data.heavenly_dao.min_paths}+</b>
                </div>
                <div style={{ display:"flex", justifyContent:"space-between",
                              marginTop:4, fontSize:12 }}>
                  <span style={{ color:"var(--muted)" }}>{t("cel_all_mult_bonus")}</span>
                  <b style={{ color:"var(--jade)" }}>
                    +{Math.round(data.heavenly_dao.all_mult_bonus * 100)}%
                  </b>
                </div>
              </div>
            ) : (
              <div style={{ fontSize:11.5, color:"var(--muted)" }}>
                {t("cel_heavenly_dao_locked", {
                  paths: data.heavenly_dao.qualifying,
                  need: data.heavenly_dao.min_paths,
                })}
              </div>
            )}
          </Card>

          {/* Body Transformation pillar */}
          <Card>
            <CardTitle left={`💪 ${t("cel_body_header")}`} />
            {data.body.transformed ? (
              <div>
                <div style={{ fontSize:13, fontFamily:"'Cinzel',serif",
                              color:"var(--gold3)" }}>
                  {data.body.emoji} {data.body.name_key && safeT(data.body.name_key, null, "")} ·
                  {" "}{t("cel_body_level", { n: data.body.level })}
                </div>
                {data.body.passive_trib_bonus > 0 && (
                  <div style={{ fontSize:10.5, color:"var(--jade)", marginTop:4 }}>
                    +{data.body.passive_trib_bonus}% {t("cel_body_trib_bonus")}
                  </div>
                )}
                {data.body.passive_regen_bonus > 0 && (
                  <div style={{ fontSize:10.5, color:"var(--jade)" }}>
                    +{data.body.passive_regen_bonus}% {t("cel_body_regen_bonus")}
                  </div>
                )}
              </div>
            ) : (
              <div style={{ fontSize:11.5, color:"var(--muted)" }}>
                {t("cel_body_untransformed", { n: data.body.celestial_min })}
              </div>
            )}
          </Card>

          {/* Celestial Resonance pillar */}
          <Card>
            <CardTitle left={`💎 ${t("cel_resonance_header")}`} />
            {data.resonance.pieces > 0 ? (
              <div>
                <div style={{ display:"flex", justifyContent:"space-between",
                              fontSize:12 }}>
                  <span style={{ color:"var(--muted)" }}>{t("cel_pieces_equipped")}</span>
                  <b>{Math.min(data.resonance.pieces, 3)} / 3</b>
                </div>
                <div style={{ display:"flex", justifyContent:"space-between",
                              marginTop:4, fontSize:12 }}>
                  <span style={{ color:"var(--muted)" }}>{t("cel_set_bonus")}</span>
                  <b style={{ color:"var(--gold3)" }}>
                    +{Math.round(data.resonance.bonus * 100)}%
                  </b>
                </div>
              </div>
            ) : (
              <div style={{ fontSize:11.5, color:"var(--muted)" }}>
                {t("cel_resonance_inactive")}
              </div>
            )}
          </Card>

          {/* Heavenly Laws (F-11.5) — 100 laws drill-in */}
          <Card>
            <CardTitle left={`☯️ ${t("cel_heavenly_laws_header")}`} />
            {data.heavenly_laws.locked ? (
              <div style={{ fontSize:11.5, color:"var(--muted)" }}>
                {t("cel_heavenly_laws_locked")}
              </div>
            ) : (
              <>
                <div style={{ display:"flex", justifyContent:"space-between",
                              fontSize:12 }}>
                  <span style={{ color:"var(--muted)" }}>{t("cel_progress")}</span>
                  <b style={{ color:"var(--gold3)" }}>
                    {data.heavenly_laws.discovered} / {data.heavenly_laws.total || 100}
                  </b>
                </div>
                <ProgressBar
                  pct={data.heavenly_laws.total > 0
                    ? Math.min(100, (data.heavenly_laws.discovered / data.heavenly_laws.total) * 100)
                    : 0}
                  variant="cult" />
                <ActionBtn variant="ghost" onClick={() => { setView("heavenly_paths"); haptic("select"); }}
                           style={{ width:"100%", marginTop:8 }}>
                  📜 {t("cel_btn_view_paths")}
                </ActionBtn>
                {data.heavenly_laws.complete ? (
                  /* D2 (v16.6): all 100 mastered — meditation has nothing left to
                     discover. Show the Heavenly Sage state instead of a meditate
                     hint (which would be a wasted 800 qi / 8h trap). */
                  <div style={{ marginTop:6, fontSize:10.5, color:"var(--gold3)",
                                textAlign:"center", lineHeight:1.4 }}>
                    {t("cel_heavenly_laws_complete")}
                  </div>
                ) : data.meditation.is_meditating && data.meditation.current_type === "celestial_dao" ? (
                  <div style={{ marginTop:6, fontSize:10.5, color:"var(--jade)",
                                textAlign:"center" }}>
                    🧘 {t("cel_meditating_now")}
                  </div>
                ) : data.meditation.available && (
                  <div style={{ marginTop:6, fontSize:10.5, color:"var(--muted)",
                                textAlign:"center", lineHeight:1.4 }}>
                    {t("cel_meditate_hint", { qi: data.meditation.qi_cost })}
                  </div>
                )}
              </>
            )}
          </Card>

          {/* Apex unlock card — appears as data.apex.unlocked is achieved or close */}
          {data.apex && (data.apex.unlocked || data.apex.heavenly_laws_disc >= 50 || data.trials_passed >= 3) && (
            <Card style={{
              background:"linear-gradient(180deg, rgba(var(--gold2-rgb),.07), rgba(var(--card-rgb),.95))",
              border:"1px solid rgba(var(--gold2-rgb),.45)",
            }}>
              <CardTitle left={`🌌 ${t("cel_apex_header")}`} />
              {data.apex.unlocked ? (
                <div style={{ fontSize:12 }}>
                  <div style={{ color:"var(--gold3)", fontFamily:"'Cinzel',serif",
                                marginBottom:4 }}>
                    ✨ {t("cel_apex_reached")}
                  </div>
                  <div style={{ color:"var(--muted)", fontSize:11 }}>
                    {t("cel_apex_insights", { n: data.apex.insights })}
                  </div>
                  <div style={{ fontSize:10.5, color:"var(--muted)", marginTop:6,
                                lineHeight:1.5, fontStyle:"italic" }}>
                    {t("cel_apex_chamber_hint")}
                  </div>
                  {/* v14.14d — Apex Chamber drill-in CTA. */}
                  <ActionBtn
                    onClick={() => { haptic("select"); setShowApex(true); }}
                    variant="primary"
                    style={{
                      width:"100%", marginTop:10,
                      background:"linear-gradient(180deg, rgba(253,224,138,.35), rgba(155,110,40,.45))",
                      border:"1px solid var(--gold2)", color:"var(--gold3)",
                      letterSpacing:1, fontFamily:"'Cinzel',serif",
                    }}>
                    🌌 {t("apex_chamber_enter_cta")}
                  </ActionBtn>
                </div>
              ) : (
                <div style={{ fontSize:11.5, color:"var(--muted)" }}>
                  {t("cel_apex_progress", {
                    realm: `${data.apex.current_realm}/${data.apex.realm_req}`,
                    sub: `${data.apex.current_sub_layer}/${data.apex.sub_layer_req}`,
                    trials: `${data.apex.trials_passed}/${data.apex.trials_req}`,
                    laws: `${data.apex.heavenly_laws_disc}/${data.apex.heavenly_laws_req}`,
                  })}
                </div>
              )}
            </Card>
          )}

          {trialPhase !== null && (
            <CelestialTrialOutcomeModal
              phase={trialPhase}
              result={trialResult}
              onClose={closeTrialModal}
            />
          )}
          {showApex && (
            <ApexChamberModal
              onClose={() => setShowApex(false)}
              onResolved={() => refreshAll()}
            />
          )}
        </div>
      );
    }

    function CelChip({ emoji, label, value }) {
      return (
        <div style={{
          flex:1, padding:"7px 10px",
          background:"rgba(var(--surface-rgb),.55)",
          border:"1px solid rgba(var(--gold2-rgb),.18)",
          borderRadius:8, textAlign:"center",
        }}>
          <div style={{ fontSize:9.5, color:"var(--muted)", letterSpacing:.5,
                        textTransform:"uppercase", fontFamily:"'Cinzel',serif" }}>
            {label}
          </div>
          <div style={{ fontSize:14, marginTop:2,
                        fontFamily:"'Cinzel',serif", color:"var(--gold3)", fontWeight:700 }}>
            {emoji} {value}
          </div>
        </div>
      );
    }

    function CelTrialRow({ trial, passed, current }) {
      const status = passed ? "passed" : current ? "next" : "future";
      const borderColor = passed ? "rgba(var(--jade-rgb),.45)"
        : current ? "rgba(var(--realm-8-rgb),.55)"
        : "rgba(var(--glow-rgb),.18)";
      return (
        <div style={{
          padding:"9px 11px", borderRadius:9,
          background:"rgba(var(--surface-rgb),.45)",
          border:`1px solid ${borderColor}`,
          opacity: status === "future" ? 0.65 : 1,
          display:"flex", alignItems:"center", gap:10,
        }}>
          <div style={{ fontSize:24 }}>{trial.emoji}</div>
          <div style={{ flex:1, minWidth:0 }}>
            <div style={{ fontFamily:"'Cinzel',serif", fontSize:12.5,
                          color:"var(--gold2)" }}>
              {t(trial.name_key)}
            </div>
            <div style={{ fontSize:10.5, color:"var(--muted)", marginTop:2 }}>
              {trial.rounds} {t("cel_rounds")} · ✨ +{trial.essence_reward}
            </div>
          </div>
          <div style={{ fontSize:12, fontFamily:"'Cinzel',serif",
                        color: passed ? "var(--jade)" : current ? "var(--realm-8)" : "var(--muted)" }}>
            {passed ? "✅" : current ? "⚡" : "⏳"}
          </div>
        </div>
      );
    }

    // Cinematic outcome modal — charging spinner → reveal banner.
    function CelestialTrialOutcomeModal({ phase, result, onClose }) {
      // Modal is dynamic (charging vs reveal+bonuses) — DO NOT use compact={true}.
      // Lesson HF v14.10 round 1: compact + dynamic = iOS WebKit body collapse.
      const isCharging = phase === "charging" || !result;
      const success = result && result.success;

      return (
        <Modal open={true}
               onClose={isCharging ? undefined : onClose}
               allowBackdropClose={!isCharging}
               showCloseBtn={!isCharging}
               title={isCharging ? `⚡ ${t("cel_modal_charging")}` :
                                    success ? `✨ ${t("cel_modal_success")}`
                                            : `💔 ${t("cel_modal_failure")}`}
               accent={success ? "rgba(var(--jade-rgb),.55)"
                               : isCharging ? "rgba(var(--realm-8-rgb),.55)"
                                            : "rgba(var(--red-rgb),.55)"}
               maxWidth={380} zIndex={70}
               footer={!isCharging ? (
                 <ActionBtn variant="primary" onClick={onClose} style={{ width:"100%" }}>
                   {t("btn_close")}
                 </ActionBtn>
               ) : null}>
          {isCharging && (
            <div style={{ textAlign:"center", padding:"40px 14px" }}>
              <div style={{ fontSize:64, animation:"trib-storm 1.4s ease-in-out infinite" }}>
                ⚡
              </div>
              <div style={{ marginTop:18, color:"var(--gold3)",
                            fontFamily:"'Cinzel',serif", fontSize:13, letterSpacing:.5 }}>
                {t("cel_modal_charging_hint")}
              </div>
            </div>
          )}
          {!isCharging && result && (
            <div style={{ textAlign:"center", padding:"6px 4px" }}>
              <div style={{ fontSize:48, marginBottom:6 }}>
                {success ? "🌟" : "🔥"}
              </div>
              <div style={{ fontFamily:"'Cinzel',serif", fontSize:14,
                            color: success ? "var(--jade)" : "var(--red)",
                            letterSpacing:.5 }}>
                {success
                  ? t("cel_modal_trial_success", { trial: result.trial_num, essence: result.essence_gained })
                  : t("cel_modal_trial_failure", { trial: result.trial_num,
                                                    rounds: result.rounds_survived,
                                                    total: result.rounds_total,
                                                    loss: result.cb_loss_pct,
                                                    cd: result.cooldown_hours })}
              </div>
              {!success && result.insurance_used && (
                <div style={{ marginTop:8, fontSize:11, color:"var(--realm-8)" }}>
                  🛡️ {t("cel_modal_insurance_softened")}
                </div>
              )}
              {success && result.apex_unlocked && (
                <div style={{
                  marginTop:14, padding:"12px 14px",
                  background:"linear-gradient(180deg, rgba(var(--gold2-rgb),.14), rgba(var(--surface-rgb),.72))",
                  border:"1px solid rgba(var(--gold2-rgb),.55)", borderRadius:10,
                }}>
                  <div style={{ fontFamily:"'Cinzel',serif", fontSize:13,
                                color:"var(--gold3)", letterSpacing:.5 }}>
                    🌌 {t("cel_apex_unlock_banner_title")}
                  </div>
                  <div style={{ fontSize:11, color:"var(--gold2)", marginTop:6 }}>
                    {t("cel_apex_unlock_banner_jade", { jade: result.apex_jade_reward })}
                  </div>
                </div>
              )}
            </div>
          )}
        </Modal>
      );
    }

    // Heavenly Paths drill-in — list paths with discovered/total + tier bonus.
    function CelestialHeavenlyPathsPanel({ onBack }) {
      const { data, loading, error } = useApi("celestial/heavenly_paths", null, []);
      if (loading && !data) return <ListSkeleton rows={4} />;
      if (error && !data) return <ErrBanner msg={error} />;
      if (!data) return null;
      if (!data.unlocked) {
        return (
          <div>
            <Card>
              <ActionBtn variant="ghost" onClick={onBack}>◀ {t("btn_back")}</ActionBtn>
              <div style={{ textAlign:"center", padding:"22px 8px",
                            color:"var(--muted)", fontSize:12 }}>
                {data.reason === "needs_first_trial"
                  ? t("cel_heavenly_paths_needs_trial")
                  : t("cel_heavenly_paths_needs_mahayana")}
              </div>
            </Card>
          </div>
        );
      }
      return (
        <div>
          <Card>
            <div style={{ display:"flex", alignItems:"center",
                          justifyContent:"space-between", marginBottom:8 }}>
              <CardTitle left={`☯️ ${t("cel_heavenly_paths_title")}`}
                         right={`${data.discovered} / ${data.total}`} />
              <ActionBtn variant="ghost" onClick={onBack}>◀ {t("btn_back")}</ActionBtn>
            </div>
            <div style={{ fontSize:11, color:"var(--muted)", lineHeight:1.5 }}>
              {t("cel_heavenly_paths_hint")}
            </div>
          </Card>
          {data.paths.length === 0 ? (
            <Card>
              <div style={{ textAlign:"center", padding:"18px 8px",
                            color:"var(--muted)", fontSize:12 }}>
                {t("cel_heavenly_paths_empty")}
              </div>
            </Card>
          ) : data.paths.map(p => {
            const pct = p.total > 0 ? Math.min(100, (p.discovered / p.total) * 100) : 0;
            return (
              <Card key={p.id} style={{ opacity: p.locked ? .55 : 1 }}>
                <div style={{ display:"flex", justifyContent:"space-between",
                              alignItems:"baseline" }}>
                  <span>
                    <span style={{ fontSize:18 }}>{p.locked ? "🔒" : p.emoji}</span>{" "}
                    <b style={{ fontFamily:"'Cinzel',serif" }}>{p.name}</b>
                  </span>
                  <span style={{ fontSize:11, color:"var(--gold3)", fontWeight:700 }}>
                    {p.discovered}/{p.total}
                  </span>
                </div>
                {!p.locked && <ProgressBar pct={pct} variant="cult" />}
                <div style={{ display:"flex", justifyContent:"space-between",
                              marginTop:4, fontSize:10.5, color:"var(--muted)" }}>
                  <span>{p.tier_stars || "—"} {p.tier_name}</span>
                  {p.tier_bonus > 0 && (
                    <span style={{ color:"var(--jade)" }}>
                      +{(p.tier_bonus * 100).toFixed(0)}%
                    </span>
                  )}
                  {p.locked && (
                    <span style={{ color:"var(--warn)" }}>
                      {t("dao_locked_at_realm", { realm: p.min_realm })}
                    </span>
                  )}
                </div>
              </Card>
            );
          })}
        </div>
      );
    }

    // ─── MA-40 Battle Pass / Celestial Pass (Sprint v14.13d) ─────────────────
    // Tier-based season missions with free + premium tracks. Free players see
    // every mission and their progress; only premium tier claims grant the
    // reward. Endpoint `battle_pass` returns all missions + premium status;
    // `battle_pass/claim` reuses `core.bp_engine.claim_bp_mission_reward`.
    // Premium upgrade flow stays in chat (`/loja` invoice) until MA-40b — the
    // UI surfaces the upsell as a banner card instead of forking the flow.
    function BattlePassTab({ onPlayerRefresh }) {
      const [reload, setReload] = useState(0);
      const [busyId, setBusyId] = useState(null);
      const [filter, setFilter] = useState("all"); // all | ready | locked
      const { data, loading, error } = useApi("battle_pass", null, [reload]);

      async function claimDailyJade() {
        if (busyId) return;
        setBusyId("daily_jade");
        haptic("warning");
        try {
          const res = await api("battle_pass/claim_daily", {});
          if (!res.ok) {
            haptic("error");
            // Engine reasons arrive err_-prefixed (err_bp_not_active /
            // err_bp_jade_already_claimed / err_player_not_found) — map them
            // onto the existing bp_err_* keys (review: the naive
            // bp_err_${reason} produced bp_err_err_* raw-key toasts).
            const _r = String(res.reason || "engine_error");
            const reasonKey = _r === "err_bp_not_active" ? "premium_required"
              : _r === "err_bp_jade_already_claimed" ? "already_claimed"
              : _r.replace(/^err_/, "");
            showToast(t(`bp_err_${reasonKey}`), "err");
            return;
          }
          haptic("success");
          showToast(t("bp_daily_jade_success", { n: res.granted || 10 }));
          setReload(x => x + 1);
          onPlayerRefresh && onPlayerRefresh();
        } catch (e) {
          haptic("error");
          showToast(t("bp_err_engine_error"), "err");
        } finally {
          setBusyId(null);
        }
      }

      async function claim(mission_id) {
        if (busyId) return;
        setBusyId(mission_id);
        haptic("warning");
        try {
          const res = await api("battle_pass/claim", { mission_id });
          if (!res.ok) {
            haptic("error");
            const reason = res.reason || "engine_error";
            // Premium gate: distinct toast pointing to /loja for the upgrade.
            if (reason === "premium_required") {
              showToast(t("bp_premium_required_toast"), "err");
            } else {
              showToast(t(`bp_err_${reason}`) || reason, "err");
            }
            setBusyId(null);
            return;
          }
          haptic("success");
          const granted = (res.granted || []).join(" + ") || "—";
          showToast(t("bp_claim_success", { rewards: granted }));
          setReload(x => x + 1);
          onPlayerRefresh && onPlayerRefresh();
        } catch (e) {
          haptic("error");
          showToast(t("bp_err_engine_error"), "err");
        } finally {
          setBusyId(null);
        }
      }

      if (loading && !data) return <ListSkeleton rows={6} />;
      if (error) return <ErrBanner msg={error} />;
      if (!data) return null;

      const missions = data.missions || [];
      const claimable = missions.filter(m => m.is_completed && !m.claimed);
      const filterOpts = [
        { value:"all",    label: t("bp_filter_all") },
        { value:"ready",  label: `${t("bp_filter_ready")} ${claimable.length > 0 ? `(${claimable.length})` : ""}` },
        { value:"locked", label: t("bp_filter_locked") },
      ];
      const filtered = filter === "ready"
        ? missions.filter(m => m.is_completed && !m.claimed)
        : filter === "locked"
          ? missions.filter(m => !m.is_completed)
          : missions;

      // Group by reset_type for visual rhythm: daily → weekly → tier.
      const order = ["daily", "weekly", "none"];
      const grouped = order.map(rt => ({
        kind: rt,
        list: filtered.filter(m => (m.reset_type || "none") === rt),
      })).filter(g => g.list.length > 0);

      const groupLabel = (kind) =>
        kind === "daily"  ? `📅 ${t("bp_group_daily")}` :
        kind === "weekly" ? `📆 ${t("bp_group_weekly")}` :
                            `🏆 ${t("bp_group_seasonal")}`;

      const claimableJade = claimable.reduce((s,m) => s + (m.reward_jade || 0), 0);

      return (
        <div>
          {/* Header card: premium chip + season + jade in claimable buffer */}
          <Card>
            <div style={{ display:"flex", alignItems:"center", gap:10 }}>
              <div style={{ fontSize:34, filter:"drop-shadow(0 0 10px rgba(var(--gold2-rgb),.5))" }}>🎫</div>
              <div style={{ flex:1, minWidth:0 }}>
                <div style={{ fontFamily:"'Cinzel',serif", fontSize:14, fontWeight:700,
                              color:"var(--gold2)", letterSpacing:.4 }}>
                  {t("bp_title")}
                </div>
                <div style={{ fontSize:10.5, color:"var(--muted)", marginTop:2 }}>
                  {t("bp_season_label", { n: data.season })} · {t("bp_tier_label", { n: data.current_tier })}
                </div>
              </div>
              <div style={{
                padding:"4px 10px", borderRadius:6,
                background: data.is_premium
                  ? "linear-gradient(180deg,rgba(var(--gold2-rgb),.18),rgba(var(--gold-rgb),.32))"
                  : "rgba(0,0,0,.35)",
                border:`1px solid ${data.is_premium ? "var(--gold2)" : "rgba(var(--muted-rgb),.3)"}`,
                color: data.is_premium ? "var(--gold3)" : "var(--muted)",
                fontFamily:"'Cinzel',serif", fontSize:10, letterSpacing:.4,
              }}>
                {data.is_premium ? `✨ ${t("bp_premium_active")}` : t("bp_premium_inactive")}
              </div>
            </div>
            {/* Daily +10 jade — paying customers had NO mini-app surface for
                this claim ([jogador] 2026-06-12); button mirrors the chat one. */}
            {data.is_premium && (
              data.daily_jade_can_claim ? (
                <ActionBtn variant="primary" disabled={busyId === "daily_jade"}
                           onClick={claimDailyJade}
                           style={{ width:"100%", marginTop:10 }}>
                  💎 {t("bp_daily_jade_claim", { n: data.daily_jade_amount || 10 })}
                </ActionBtn>
              ) : (
                <div style={{
                  marginTop:10, padding:"7px 10px", borderRadius:7,
                  background:"rgba(0,0,0,.3)",
                  border:"1px solid rgba(var(--muted-rgb),.25)",
                  fontSize:10.5, color:"var(--muted)", textAlign:"center",
                }}>
                  ⏳ {t("bp_daily_jade_claimed")}
                </div>
              )
            )}
            {claimable.length > 0 && (
              <div style={{
                marginTop:10, padding:"7px 10px", borderRadius:7,
                background:"rgba(var(--jade-rgb),.08)",
                border:"1px solid rgba(var(--jade-rgb),.35)",
                fontSize:11, color:"var(--jade)", textAlign:"center",
              }}>
                ✦ {t("bp_claimable_summary", { n: claimable.length, jade: claimableJade })}
              </div>
            )}
            {!data.is_premium && (
              <div style={{
                marginTop:10, padding:"8px 10px", borderRadius:7,
                background:"linear-gradient(135deg,rgba(var(--gold2-rgb),.1),rgba(var(--realm-3-rgb),.1))",
                border:"1px dashed rgba(var(--gold2-rgb),.45)",
                fontSize:10.5, color:"var(--gold3)", textAlign:"center",
                fontStyle:"italic", lineHeight:1.5,
              }}>
                💎 {t("bp_premium_upsell")}
              </div>
            )}
          </Card>

          <Card style={{ padding:"10px 12px" }}>
            <SegControl options={filterOpts} value={filter} onChange={setFilter} />
          </Card>

          {filtered.length === 0 ? (
            <Card>
              <div style={{ textAlign:"center", padding:"24px 0", color:"var(--muted)", fontSize:12 }}>
                {filter === "ready" ? t("bp_empty_ready") :
                 filter === "locked" ? t("bp_empty_locked") :
                 t("bp_empty_all")}
              </div>
            </Card>
          ) : grouped.map(group => (
            <Card key={group.kind}>
              <CardTitle left={groupLabel(group.kind)} right={group.list.length} />
              {group.list.map(m => (
                <BPMissionRow key={m.id} m={m}
                              busy={busyId === m.id}
                              isPremium={data.is_premium}
                              onClaim={() => claim(m.id)} />
              ))}
            </Card>
          ))}
        </div>
      );
    }

    function BPMissionRow({ m, busy, isPremium, onClaim }) {
      const pct = m.objective_value > 0
        ? Math.min(100, (m.progress / m.objective_value) * 100)
        : 0;
      // v14.13e — Robust description resolution via safeT:
      // i18n key → server pre-rendered description → humanized fallback.
      // NEVER show raw snake_case to paying players.
      const desc = safeT(m.description_key, { value: m.objective_value }, m.description);
      const canClaim = m.is_completed && !m.claimed;
      const premiumLocked = m.is_premium_only && !isPremium;
      return (
        <div style={{
          padding:"9px 4px", borderBottom:"1px dashed rgba(var(--glow-rgb),.15)",
        }}>
          <div style={{ display:"flex", alignItems:"center", gap:8 }}>
            <div style={{ flex:1, minWidth:0, fontSize:12, lineHeight:1.4 }}>
              <div style={{ display:"flex", gap:6, alignItems:"center", flexWrap:"wrap" }}>
                {m.is_premium_only && (
                  <Badge variant="gold">✨ {t("bp_premium_badge")}</Badge>
                )}
                {m.reset_type === "none" && (
                  <span style={{
                    fontSize:9, color:"var(--muted)", fontFamily:"'Cinzel',serif",
                    letterSpacing:.5,
                  }}>T{m.tier}</span>
                )}
                <span style={{ fontSize:12 }}>{desc}</span>
              </div>
              {m.times_completed > 0 && m.reset_type !== "none" && (
                <div style={{ fontSize:10, color:"var(--muted2)", marginTop:2 }}>
                  ×{m.times_completed} {t("bp_done_count")}
                </div>
              )}
            </div>
            {m.reward_jade > 0 && (
              <div style={{ fontSize:11, color:"var(--gold3)",
                            fontFamily:"'Cinzel',serif", fontWeight:700, flexShrink:0 }}>
                💎 {m.reward_jade}
              </div>
            )}
          </div>
          <div style={{ marginTop:5, display:"flex", alignItems:"center", gap:8 }}>
            <ProgressBar pct={pct} variant="cult" />
            <span style={{ fontSize:10, color:"var(--muted)", whiteSpace:"nowrap", minWidth:50, textAlign:"right" }}>
              {fmtNum(m.progress)}/{fmtNum(m.objective_value)}
            </span>
          </div>
          {canClaim && (
            <ActionBtn variant={premiumLocked ? "ghost" : "primary"}
                       disabled={busy}
                       onClick={onClaim}
                       style={{ marginTop:6, width:"100%", padding:"6px 10px", fontSize:11 }}>
              {busy ? <DotSpinner /> :
                premiumLocked ? `🔒 ${t("bp_locked_premium_btn")}` :
                                `✦ ${t("bp_claim_btn")}`}
            </ActionBtn>
          )}
        </div>
      );
    }

    // ─── MA-45 Events Modal + Banner (Sprint v14.13) ─────────────────────────
    // CelestialEvent list — passive global multipliers driven by scheduler.
    // No `participate` mechanic (mirrors chat events_command — events apply
    // ambient buffs to combat/loot, no opt-in needed).
    //
    // Surface in two places:
    //   - Floating banner ABOVE the topbar when ≥1 active event (App.js).
    //   - Drill-in modal opened by tapping the banner with full effect list.
    function EventsModal({ onClose }) {
      const { data, loading, error } = useApi("events/active", null, []);
      const footer = (
        <ActionBtn variant="ghost" onClick={onClose} style={{ width:"100%" }}>
          {t("btn_close")}
        </ActionBtn>
      );
      return (
        <Modal open={true} onClose={onClose}
               title={`🌌 ${t("events_modal_title")}`}
               accent="rgba(var(--realm-3-rgb),.5)"
               maxWidth={400} zIndex={75}
               footer={footer}>
          {loading && !data && <ListSkeleton rows={3} />}
          {error && !data && <ErrBanner msg={error} />}
          {data && data.count === 0 && (
            <Card>
              <div style={{ textAlign:"center", padding:"22px 8px" }}>
                <div style={{ fontSize:42, opacity:.6 }}>⛅</div>
                <div style={{ marginTop:10, fontSize:12, color:"var(--muted)" }}>
                  {t("events_calm")}
                </div>
              </div>
            </Card>
          )}
          {data && (data.events || []).map(ev => {
            const remainMs = ev.expires_at_ms ? Math.max(0, ev.expires_at_ms - Date.now()) : 0;
            return (
              <Card key={ev.id} style={{
                background:"linear-gradient(180deg, rgba(var(--realm-3-rgb),.08), rgba(var(--card-rgb),.96))",
                border:"1px solid rgba(var(--realm-3-rgb),.35)",
              }}>
                <div style={{ display:"flex", alignItems:"center", gap:10 }}>
                  <div style={{ fontSize:30 }}>{ev.emoji}</div>
                  <div style={{ flex:1, minWidth:0 }}>
                    <div style={{ fontFamily:"'Cinzel',serif", fontSize:13.5,
                                  color:"var(--gold3)" }}>
                      {ev.name}
                    </div>
                    <div style={{ fontSize:11, color:"var(--muted)", marginTop:3,
                                  lineHeight:1.45 }}>
                      {ev.description}
                    </div>
                  </div>
                </div>
                {ev.effects.length > 0 && (
                  <div style={{ display:"flex", flexWrap:"wrap", gap:6, marginTop:8 }}>
                    {ev.effects.map((e, i) => (
                      <span key={i} style={{
                        fontSize:11, padding:"3px 9px",
                        background:"rgba(var(--jade-rgb),.12)",
                        border:"1px solid rgba(var(--jade-rgb),.32)",
                        borderRadius:99, color:"var(--jade)",
                      }}>
                        {e.key === "cb_mult" && `🌀 ×${e.value} ${t("events_eff_cb")}`}
                        {e.key === "loot_mult" && `🎁 ×${e.value} ${t("events_eff_loot")}`}
                        {e.key === "qi_regen_mult" && `💧 ×${e.value} ${t("events_eff_qi")}`}
                        {e.key === "boss_hp_mult" && `🐉 ×${e.value} ${t("events_eff_boss_hp")}`}
                        {e.key === "boss_loot_mult" && `🐉 ×${e.value} ${t("events_eff_boss_loot")}`}
                        {e.key === "market_npc" && `🏮 ${t("events_eff_market_npc")}`}
                      </span>
                    ))}
                  </div>
                )}
                {remainMs > 0 && (
                  <div style={{ marginTop:8, fontSize:10.5, color:"var(--muted)",
                                textAlign:"right" }}>
                    ⏳ {t("events_expires_in", { time: fmtDuration(remainMs) })}
                  </div>
                )}
              </Card>
            );
          })}
        </Modal>
      );
    }

    // Compact strip rendered ABOVE PlayerHeader when ≥1 event is active.
    // Tap → opens EventsModal. Auto-hides when no events.
    function EventsBanner({ events, onClick }) {
      if (!events || events.length === 0) return null;
      const headline = events.length === 1
        ? `${events[0].emoji} ${events[0].name}`
        : `🌌 ${t("events_banner_multi", { n: events.length })}`;
      return (
        <button onClick={() => { haptic("select"); onClick && onClick(); }}
                style={{
          width:"100%", border:"none", cursor:"pointer",
          padding:"6px 14px",
          background:"linear-gradient(90deg, rgba(var(--realm-3-rgb),.32), rgba(var(--realm-8-rgb),.20), rgba(var(--realm-3-rgb),.32))",
          borderBottom:"1px solid rgba(var(--realm-3-rgb),.45)",
          color:"var(--gold3)", fontFamily:"'Cinzel',serif",
          fontSize:11.5, letterSpacing:.5, textAlign:"center",
          display:"flex", alignItems:"center", justifyContent:"center", gap:6,
        }}>
          <span>{headline}</span>
          <span style={{ fontSize:10, opacity:.75 }}>›</span>
        </button>
      );
    }

    // ─── Onda 3 — Heaven's Whispers feed (atmospheric world-event log) ───────
    // Read-only. Server-renders title/body per the reader's language. Clone of
    // EventsModal styling, blue-celestial accent.
    function WhispersModal({ onClose }) {
      const { data, loading, error } = useApi("world/whispers", null, []);
      const footer = (
        <ActionBtn variant="ghost" onClick={onClose} style={{ width:"100%" }}>
          {t("btn_close")}
        </ActionBtn>
      );
      const whispers = (data && data.whispers) || [];
      return (
        <Modal open={true} onClose={onClose}
               title={`🌌 ${t("wsp_feed_title")}`}
               accent="rgba(var(--accent2-rgb),.5)"
               maxWidth={400} zIndex={75}
               footer={footer}>
          {loading && !data && <ListSkeleton rows={3} />}
          {error && !data && <ErrBanner msg={error} />}
          {data && whispers.length === 0 && (
            <Card>
              <div style={{ textAlign:"center", padding:"22px 8px" }}>
                <div style={{ fontSize:42, opacity:.6 }}>🌌</div>
                <div style={{ marginTop:10, fontSize:12, color:"var(--muted)" }}>
                  {t("wsp_feed_empty")}
                </div>
              </div>
            </Card>
          )}
          {whispers.map(w => (
            <Card key={w.id} style={{
              background:"linear-gradient(180deg, rgba(var(--accent2-rgb),.08), rgba(var(--card-rgb),.96))",
              border:"1px solid rgba(var(--accent2-rgb),.30)",
            }}>
              <div style={{ display:"flex", alignItems:"flex-start", gap:10 }}>
                <div style={{ fontSize:26 }}>{w.icon}</div>
                <div style={{ flex:1, minWidth:0 }}>
                  <div style={{ fontFamily:"'Cinzel',serif", fontSize:12.5, color:"var(--gold3)" }}>
                    {w.title}
                  </div>
                  <div style={{ fontSize:11, color:"var(--muted)", marginTop:3, lineHeight:1.5 }}>
                    {w.body}
                  </div>
                </div>
              </div>
            </Card>
          ))}
        </Modal>
      );
    }

    // ─── World Pulse Fase 1 — Os Registos Celestiais 天记 (the living world log) ─
    // A read-only feed of what the world did on its own: the 9 ancient sects
    // raiding, claiming spirit veins, seeking inheritances, recruiting. Each line
    // is rendered server-side (already localized; the sect/rival/continent names
    // are merged in). Mirrors WhispersModal — reuses Card/feed, no new surface.
    function ChronicleModal({ continent, onClose, onOpenIsle }) {
      // MV-3 — `onOpenIsle(continent_key)`: o chip "ver no mapa" leva a entrada
      // ao LUGAR (fecha o modal, abre a ilha no HubMundoScreen). O App só passa
      // o callback com ui_v2 ON — sem ele o chip NÃO renderiza (no-op honesto:
      // o mapa não existe no v1, Lei §1).
      const { data, loading, error } = useApi("world/chronicle", continent ? { continent } : null, []);
      // Espelho de apresentação dos emojis canónicos (CONTINENT_META) — só chrome.
      const RST_CONT_EMOJI = { linghe:"🏔️", qianhe:"⛰️", yanshan:"🌸", fenghuo:"🌋", moyu:"🌑" };
      const footer = (
        <ActionBtn variant="ghost" onClick={onClose} style={{ width:"100%" }}>
          {t("btn_close")}
        </ActionBtn>
      );
      const entries = (data && data.chronicle) || [];
      return (
        <Modal open={true} onClose={onClose}
               title={`📜 ${t("cronica_feed_title")}`}
               accent="rgba(var(--gold2-rgb),.5)"
               maxWidth={400} zIndex={75}
               footer={footer}>
          {loading && !data && <ListSkeleton rows={3} />}
          {error && !data && <ErrBanner msg={error} />}
          {data && entries.length === 0 && (
            <Card>
              <div style={{ textAlign:"center", padding:"22px 8px" }}>
                <div style={{ fontSize:42, opacity:.6 }}>📜</div>
                <div style={{ marginTop:10, fontSize:12, color:"var(--muted)" }}>
                  {t("cronica_feed_empty")}
                </div>
              </div>
            </Card>
          )}
          {entries.map(e => (
            <Card key={e.id} style={{
              background:"linear-gradient(180deg, rgba(var(--gold2-rgb),.07), rgba(var(--card-rgb),.96))",
              border:"1px solid rgba(var(--gold2-rgb),.26)",
            }}>
              <div style={{ display:"flex", alignItems:"flex-start", gap:10 }}>
                <div style={{ fontSize:24 }}>{e.sect_emoji || e.icon}</div>
                <div style={{ flex:1, minWidth:0 }}>
                  <div style={{ fontSize:11.5, color:"rgba(var(--text2-rgb),.9)", lineHeight:1.5 }}>
                    {e.text}
                  </div>
                  <div style={{ fontSize:9.5, color:"var(--muted)", marginTop:4,
                                display:"flex", alignItems:"center", gap:8, flexWrap:"wrap" }}>
                    <span>{e.icon} {timeAgo(e.ts_ms)}</span>
                    {/* MV-3 — a Chronicle deixa de ser texto morto: tocar → o LUGAR */}
                    {onOpenIsle && e.continent_key && (
                      <span onClick={() => { haptic("select"); onOpenIsle(e.continent_key); }}
                            style={{
                              cursor:"pointer", color:"var(--gold3)", fontWeight:700,
                              border:"1px solid rgba(var(--gold2-rgb),.35)", borderRadius:99,
                              padding:"2px 8px", fontSize:9,
                            }}>
                        {RST_CONT_EMOJI[e.continent_key] || "🗺️"} {t("rst_see_on_map")} ›
                      </span>
                    )}
                  </div>
                </div>
              </div>
            </Card>
          ))}
        </Modal>
      );
    }

    // ─── Onda 4a — Continental Plaza (Wànshì) + Bounty Board ─────────────────
    // "Há outras almas aqui." Continent-scoped + bounded (NOT the global
    // ranking). Presence = recently-online real players of THIS continent +
    // the continent's NPC cultivators (honest 🤖, Lei §1). Service NPCs are an
    // atmospheric facade that deep-links to the existing systems (sect / market
    // / quests). The Bounty Board = cartazes on dark-karma NPCs, hunted via the
    // SAME npc_cultivator duel + spare/execute fork. NPC + bounty challenges
    // lift to the App-root NpcCultivatorModal (back-stack safe) via
    // onOpenNpc / onOpenBounty; a bounty target just carries an extra bounty_id.
    function BountyRow({ b, onChallenge }) {
      const npc = b.npc || {};
      const tierLabel = t("bounty_tier_" + (b.tier || "tainted"));
      return (
        <div style={{
          display:"flex", alignItems:"center", gap:10, padding:"10px 2px",
          borderBottom:"1px dashed rgba(180,60,60,.18)",
        }}>
          <div style={{ flex:1, minWidth:0 }}>
            <div style={{ fontSize:12.5, color:"var(--gold2)", fontFamily:"'Cinzel',serif", display:"flex", alignItems:"center", gap:6, flexWrap:"wrap" }}>
              <span>🤖 {npc.name || t("npc_cult_title")}</span>
              <Badge variant="warn">{tierLabel}</Badge>
            </div>
            <div style={{ fontSize:10.5, color:"var(--muted)", marginTop:3 }}>
              {npc.realm_emoji} {npc.realm_name}{npc.sub_layer ? " " + npc.sub_layer : ""} · ⚔️ {fmtNum(npc.power || 0)}
              {npc.karma && <span> · {npc.karma.emoji} {npc.karma.label}</span>}
            </div>
            <div style={{ fontSize:11.5, color:"var(--gold3)", marginTop:3 }}>
              🪨 {fmtNum(b.reward_stones || 0)}
              {b.source === "player" && b.posted_by_name && (
                <span style={{ color:"var(--muted)", fontSize:10.5 }}> · 🎁 {t("wbounty_posted_by", { name: b.posted_by_name })}</span>
              )}
            </div>
          </div>
          {b.mine ? (
            <span style={{ flexShrink:0, fontSize:10.5, color:"var(--muted)", fontFamily:"'Cinzel',serif", textAlign:"center", maxWidth:96 }}>
              🎁 {t("wbounty_yours")}
              {/* MV-3 §0 fix — your cartaz hangs on ANOTHER continent's board:
                  say where (the hunt CTA stays local; self-claim is blocked). */}
              {b.elsewhere && b.continent_name && (
                <span style={{ display:"block", fontSize:9.5, marginTop:2 }}>
                  {b.continent_emoji} {b.continent_name}
                </span>
              )}
            </span>
          ) : (
            <ActionBtn variant="danger" onClick={onChallenge} style={{ flexShrink:0, fontSize:11.5, padding:"7px 12px" }}>
              🏴 {t("bounty_challenge")}
            </ActionBtn>
          )}
        </div>
      );
    }

    function PlazaTab({ player, setTab, onOpenNpc, onOpenBounty, onOpenTravel, onOpenWorldSect, reloadSignal, onProposeTrade, onOpenChronicle, onOpenStorylet, onOpenProfession, onOpenAmbush, onOpenCaravan }) {
      // MV-9 — `encReload` entra nas deps do useApi (que NÃO expõe reload):
      // assumir o encargo tem de repintar o cartão com o progresso 0/N.
      const [encReload, setEncReload] = useState(0);
      const [encBusy, setEncBusy] = useState(false);
      const [encMsg, setEncMsg] = useState(null);
      const plaza = useApi("world/plaza", null, [reloadSignal, encReload]);
      const board = useApi("world/bounties", null, [reloadSignal]);
      const [profileTarget, setProfileTarget] = useState(null);
      const [bountyTab, setBountyTab] = useState("world");   // Track A item 3 — world | player
      const d = plaza.data || {};
      const chip = d.continent_chip;
      const players = d.players || [];
      const npcs = d.npcs || [];
      const whispers = d.whispers || [];
      const chronicle = d.chronicle || [];
      const bounties = (board.data && board.data.bounties) || [];
      // Track A item 3 — the board splits 🏴 world-issued vs 🎁 player-posted.
      const worldBounties = bounties.filter(b => b.source !== "player");
      const playerBounties = bounties.filter(b => b.source === "player");
      const shownBounties = bountyTab === "player" ? playerBounties : worldBounties;

      // Atmospheric service NPCs — pure facade that deep-links to the existing
      // systems (do NOT duplicate their logic; the plaza only aggregates).
      const services = [
        // 🏯 Recrutador = a Seita de Cultivo (world_sects, vive em modal), NÃO a
        // Guilda (SectTab). Member → SectHallModal; não-membro → directório (via
        // onOpenWorldSect no app.js, espelha o ProfileModal sect_chip_visible).
        { key:"recruiter", icon:"🏯", action:"world_sect", label: t("plaza_service_recruiter") },
        { key:"vendor",    icon:"💰", tab:"market", label: t("plaza_service_vendor") },
        { key:"quests",    icon:"📜", tab:"quests", label: t("plaza_service_questgiver") },
      ];
      // MV-7 — a Guilda dos Ofícios É um serviço da praça (spec §2: entrada
      // pelo HubMundo E pela praça — review do owner 2026-07-23: só o HubMundo
      // não era descobrível). Gated: sem a flag o serviço nem existe.
      if (featureEnabled("profissoes") && onOpenProfession) {
        services.push({ key:"oficio", icon:"🏮", action:"profession", label: t("plaza_service_profession") });
      }

      return (
        <div>
          {/* Header — the city + the player's continent chip. */}
          <Card style={{ padding:"14px 14px 12px", marginBottom:12, textAlign:"center",
                         background:"linear-gradient(180deg, rgba(var(--accent2-rgb),.08), rgba(var(--card-rgb),.96))",
                         border:"1px solid rgba(var(--accent2-rgb),.28)" }}>
            {/* MV-9 — o nome do lugar ONDE VOCÊ ESTÁ. Esta linha dizia "Praça
                de Wànshì" nos CINCO continentes; Wànshì fica em Línghé, e 53%
                dos ativos semanais estão fora dela. `d.city` é server-resolved
                (nome/intro/traço já no idioma do jogador) e só chega com a flag
                `cidades` ON — sem ela, a linha de sempre, byte-idêntica. */}
            <div style={{ fontFamily:"'Cinzel',serif", fontSize:18, fontWeight:700, color:"var(--gold2)" }}>
              {d.city ? `${d.city.emoji} ${d.city.name}` : `🏙️ ${t("city_wanshi")}`}
            </div>
            {d.city && d.city.trait && (
              <div style={{ fontSize:10.5, color:"var(--gold3)", marginTop:4, lineHeight:1.45 }}>
                {d.city.trait}
              </div>
            )}
            {chip && (
              <div style={{ marginTop:6 }}>
                <span style={{ fontSize:11, padding:"3px 10px", borderRadius:99,
                               background:"rgba(255,255,255,.06)", border:"1px solid rgba(255,255,255,.12)", color:"var(--muted)" }}>
                  {chip.emoji} {chip.name}
                </span>
              </div>
            )}
            <div style={{ fontSize:11, color:"var(--muted)", marginTop:8, lineHeight:1.5 }}>
              {t("plaza_subtitle")}
            </div>
            {/* MV-11 天时 — O TEMPO DO CÉU. Vem ANTES do estado regional de
                propósito: é a única linha desta praça que é verdadeira nos
                CINCO continentes (o céu é do mundo, não do chão — e por isso
                alcança Mòyǔ, que nunca teve um evento em toda a sua história).
                Server-resolved: imprimir CRU, nunca por t(). A key só chega
                com `tempo_do_ceu` ON — payload byte-idêntico OFF. */}
            {d.tianshi && (
              <div style={{ fontSize:11, color:"var(--muted)", marginTop:6, lineHeight:1.45 }}>
                {d.tianshi.line}
                {d.tianshi.next && d.tianshi.next.line && (
                  <div style={{ color:"var(--gold3)", marginTop:3 }}>
                    {d.tianshi.next.line}
                  </div>
                )}
              </div>
            )}
            {/* MV-4 §0 (dívida MV-3) — a linha do estado LOCAL do continente
                (server-resolved; a key só chega com estados_regionais ON). */}
            {d.region_state_local && (
              <div style={{ fontSize:11, color:"var(--muted)", marginTop:6, lineHeight:1.45 }}>
                {d.region_state_local.emoji} {d.region_state_local.text}
                {/* MV-8 — quem hasteou a bandeira. Server-resolved; a key só
                    existe quando o continente está 🚩 ocupado. */}
                {d.region_state_local.occupant_line && (
                  <div style={{ color:"var(--gold2)", marginTop:3 }}>
                    {d.region_state_local.occupant_line}
                  </div>
                )}
              </div>
            )}
            {/* MV-6 — a rep LOCAL: chip + reverência/desprezo (server-resolved;
                a key só chega com reputacao_rival ON — payload byte-idêntico OFF). */}
            {d.region_rep_local && d.region_rep_local.chip && (
              <div style={{ fontSize:11, color:"var(--muted)", marginTop:6, lineHeight:1.45 }}>
                {d.region_rep_local.chip.line}
              </div>
            )}
            {d.region_rep_local && d.region_rep_local.line && (
              <div style={{ fontSize:11, color:"var(--gold3)", marginTop:4, lineHeight:1.45 }}>
                {d.region_rep_local.line}
              </div>
            )}
            {/* MV-2 — Tiandao: evento NESTE continente (linha local — cobre o
                jogador v1 sem o mapa v2, Lei §1) + rumor de evento NOUTRO
                continente (campos só chegam com a flag ON; server-resolved). */}
            {[...(d.world_event_local || []), ...(d.world_event_rumors || [])].map((r, i) => (
              <div key={i} style={{ fontSize:11, color:"var(--gold3)", marginTop:6, lineHeight:1.45 }}>
                {r.emoji} {r.text}
              </div>
            ))}
            {/* Onda 4b — Travel: the door out of this continent. */}
            {onOpenTravel && (
              <div style={{ marginTop:10 }}>
                <ActionBtn variant="ghost" onClick={() => { haptic("select"); onOpenTravel(); }} style={{ width:"100%" }}>
                  🧭 {t("travel_title")}
                </ActionBtn>
              </div>
            )}
          </Card>

          {/* MV-9 — O ENCARGO 城务: o pedido PERMANENTE desta cidade. Tudo
              server-resolved; a key `city.encargo` só chega com `cidades` ON.
              `locked` (=`quests_vivas` OFF) NÃO esconde o bloco — mostra a
              recusa com o motivo dito (Lei §1: porta trancada aparece trancada).
              A ENTREGA não vive aqui: quando fica pronto, o encargo é uma quest
              viva como qualquer outra e reclama-se em Missões (uma verdade só
              sobre o pagamento). */}
          {d.city && d.city.encargo && (
            <Card style={{ padding:"12px 14px", marginBottom:12,
                           border:"1px solid rgba(var(--gold2-rgb),.28)" }}>
              <div style={{ fontSize:11, color:"var(--gold3)", fontFamily:"'Cinzel',serif",
                            letterSpacing:1.1, textTransform:"uppercase", marginBottom:6 }}>
                {t("cid_encargo_head")}
              </div>
              {d.city.encargo.locked ? (
                <div style={{ fontSize:11.5, color:"var(--muted)", lineHeight:1.5 }}>
                  {d.city.encargo.line}
                </div>
              ) : (
                <div>
                  <div style={{ fontSize:13, fontWeight:700, color:"var(--gold2)" }}>
                    {d.city.encargo.icon} {d.city.encargo.name}
                  </div>
                  <div style={{ fontSize:11, color:"var(--muted)", marginTop:4, lineHeight:1.5 }}>
                    {d.city.encargo.desc}
                  </div>
                  {/* QoL 07/08 (report [jogador]): o OBJETIVO dito em palavras + o
                      chip "→" para o lugar dele. Antes daqui saía nome →
                      atmosfera → barra → "0 / 3": um contador sem substantivo,
                      e o diálogo mandava fazer outra coisa. A frase vem
                      server-resolved (uma verdade para chat e mini); o chip usa
                      a mesma rota da QuestRow, agora ciente de segmento. */}
                  {d.city.encargo.objective_line && (
                    <div style={{ display:"flex", alignItems:"center", gap:8, marginTop:6 }}>
                      <span style={{ flex:1, fontSize:11.5, fontWeight:600, color:"var(--gold2)" }}>
                        {d.city.encargo.objective_line}
                      </span>
                      {/* ⚠️ O chip só existe com o encargo ACEITO. Sem esse
                          gate ele convidava a forjar antes de aceitar — e
                          `track_storylets` só credita rows `accepted`, logo o
                          jogador fazia o trabalho e voltava para um 0/3. Seria
                          o report do [jogador] reproduzido pelo próprio conserto,
                          agora com trabalho perdido. `ready` também fica de
                          fora: aí o caminho é RECLAMAR, não repetir (mesma
                          regra do `!a.is_completed` do StoryletSection). */}
                      {setTab && ((d.city.encargo.mine || {}).status === "accepted")
                        && objectiveRoute(d.city.encargo.objective_type) && (
                        <button onClick={() => { haptic("select"); goToObjective(setTab, d.city.encargo.objective_type); }}
                                style={{ background:"rgba(var(--gold2-rgb),.08)", border:"1px solid rgba(var(--gold2-rgb),.25)",
                                         borderRadius:8, color:"var(--gold3)", fontSize:12, padding:"3px 10px",
                                         cursor:"pointer", lineHeight:1, flexShrink:0 }}>
                          →
                        </button>
                      )}
                    </div>
                  )}
                  {d.city.encargo.reward_line && (
                    <div style={{ fontSize:11, color:"var(--gold3)", marginTop:5 }}>
                      🎁 {d.city.encargo.reward_line}
                    </div>
                  )}
                  {(() => {
                    const mine = d.city.encargo.mine || {};
                    const total = mine.count || d.city.encargo.objective_count || 1;
                    if (mine.status === "accepted" || mine.status === "ready") {
                      return (
                        <div style={{ marginTop:8 }}>
                          <ProgressBar pct={Math.min(100, ((mine.progress || 0) / total) * 100)} variant="cult" />
                          <div style={{ fontSize:10.5, color:"var(--muted)", marginTop:4 }}>
                            {mine.status === "ready"
                              ? t("cid_encargo_done")
                              : `${t("cid_encargo_open")} · ${fmtNum(mine.progress || 0)} / ${fmtNum(total)}`}
                          </div>
                        </div>
                      );
                    }
                    if (mine.reason_line) {
                      return (
                        <div style={{ fontSize:10.5, color:"var(--red)", marginTop:8, lineHeight:1.45 }}>
                          🔒 {mine.reason_line}
                        </div>
                      );
                    }
                    return (
                      <ActionBtn variant="primary" style={{ marginTop:10, width:"100%" }}
                                 disabled={encBusy}
                                 onClick={async () => {
                                   haptic("select"); setEncBusy(true); setEncMsg(null);
                                   try {
                                     const r = await api("world/city_encargo");
                                     setEncMsg(r && r.line ? r.line : null);
                                     if (r && r.ok) setEncReload(x => x + 1);
                                   } catch (e) {
                                     setEncMsg(String(e.message || e));
                                   } finally { setEncBusy(false); }
                                 }}>
                        📜 {t("cid_encargo_btn")}
                      </ActionBtn>
                    );
                  })()}
                  {encMsg && (
                    <div style={{ fontSize:10.5, color:"var(--gold3)", marginTop:6, lineHeight:1.45 }}>
                      {encMsg}
                    </div>
                  )}
                </div>
              )}
            </Card>
          )}

          {/* MV-5 — o encontro vivo: um NPC da presença local "te chama". O
              campo só chega com quests_vivas ON (payload byte-idêntico OFF). */}
          {d.storylet_offer && onOpenStorylet && (
            <Card
              onClick={() => { haptic("select"); onOpenStorylet(d.storylet_offer); }}
              style={{ cursor:"pointer", border:"1px dashed rgba(212,170,80,.5)", marginBottom:12 }}
            >
              <div style={{ display:"flex", alignItems:"center", gap:10 }}>
                <span style={{ fontSize:24 }}>{d.storylet_offer.emoji}</span>
                <div style={{ flex:1 }}>
                  <div style={{ fontSize:13, fontWeight:700 }}>{t("sty_offer_chip", { giver: d.storylet_offer.giver })}</div>
                  <div style={{ fontSize:11, color:"var(--muted)" }}>{d.storylet_offer.name}</div>
                </div>
                <span style={{ fontSize:11, color:"var(--gold3)", fontWeight:700 }}>{t("sty_view_offer_btn")} →</span>
              </div>
            </Card>
          )}

          {/* MV-8 — a EMBOSCADA: alguém te esperava na praça. Card tocável (o
              encontro NUNCA começa sozinho — Lei §1: nenhum duelo sem o tap).
              A key só chega com `jianghu` ON e um caçador vivo aqui. */}
          {d.jianghu_ambush && onOpenAmbush && (
            <Card
              onClick={() => { haptic("select"); onOpenAmbush(d.jianghu_ambush); }}
              style={{ cursor:"pointer", border:"1px dashed rgba(220,90,90,.55)", marginBottom:12 }}
            >
              <div style={{ display:"flex", alignItems:"center", gap:10 }}>
                <span style={{ fontSize:24 }}>🗡️</span>
                <div style={{ flex:1, minWidth:0 }}>
                  <div style={{ fontSize:13, fontWeight:700 }}>{t("jh_amb_chip")}</div>
                  <div style={{ fontSize:11, color:"var(--muted)" }}>{d.jianghu_ambush.name}</div>
                </div>
                <span style={{ fontSize:11, color:"#e07a7a", fontWeight:700 }}>{t("jh_amb_chip_hint")} →</span>
              </div>
            </Card>
          )}

          {/* MV-6 — O RIVAL na praça: presença 😤 + taunt + CTA de duelo (abre
              o MESMO NpcCultivatorModal via onOpenNpc — zero modal novo, zero
              entrada nova no back-stack). A key só chega com reputacao_rival
              ON e o rival PRESENTE (returned/spared) — payload byte-idêntico OFF. */}
          {d.rival && onOpenNpc && (
            <Card
              onClick={() => { haptic("select"); onOpenNpc({ npc_id: d.rival.npc_id }); }}
              style={{ cursor:"pointer", border:"1px dashed rgba(200,60,60,.55)", marginBottom:12 }}
            >
              <div style={{ display:"flex", alignItems:"center", gap:10 }}>
                <span style={{ fontSize:24 }}>😤</span>
                <div style={{ flex:1 }}>
                  <div style={{ fontSize:13, fontWeight:700 }}>{t("rvl_card_title", { name: d.rival.name })}</div>
                  <div style={{ fontSize:11, color:"var(--muted)", fontStyle:"italic" }}>“{d.rival.taunt}”</div>
                  <div style={{ fontSize:10, color:"var(--muted)", marginTop:3 }}>
                    {t("rvl_defeats_chip", { n: d.rival.defeats })}
                    {d.rival.power_bonus_pct > 0 && <> · {t("rvl_power_chip", { pct: d.rival.power_bonus_pct })}</>}
                  </div>
                </div>
                <span style={{ fontSize:11, color:"#e07a7a", fontWeight:700 }}>{t("rvl_challenge_cta")} →</span>
              </div>
            </Card>
          )}

          {/* Bounty Board — the hunt with meaning. Track A item 3 splits the
              feed into 🏴 world-issued vs 🎁 player-posted (a head put "a prêmio"
              by another cultivator); posting lives on the NPC profile modal. */}
          <Card>
            <CardTitle left={`🏴 ${t("bounty_board_title")}`} right={bounties.length || 0} />
            <div style={{ fontSize:10.5, color:"var(--muted)", marginBottom:8, lineHeight:1.5 }}>
              {t("bounty_subtitle")}
            </div>
            {/* Origin tabs */}
            <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:6, marginBottom:8 }}>
              {[
                { key:"world",  label:t("wbounty_tab_world"),  n:worldBounties.length },
                { key:"player", label:t("wbounty_tab_player"), n:playerBounties.length },
              ].map(tabDef => (
                <button key={tabDef.key} onClick={() => { haptic("select"); setBountyTab(tabDef.key); }} style={{
                  padding:"6px 8px", borderRadius:8, fontSize:11, fontFamily:"'Cinzel',serif", letterSpacing:.3,
                  cursor:"pointer",
                  background: bountyTab === tabDef.key ? "rgba(180,60,60,.16)" : "rgba(0,0,0,.3)",
                  border: `1px solid ${bountyTab === tabDef.key ? "rgba(180,60,60,.5)" : "rgba(255,255,255,.1)"}`,
                  color: bountyTab === tabDef.key ? "var(--gold2)" : "var(--muted)",
                }}>{tabDef.label} · {tabDef.n}</button>
              ))}
            </div>
            {board.loading && !board.data ? <ListSkeleton rows={2} />
              : board.error ? <ErrBanner msg={board.error} />
              : shownBounties.length === 0 ? (
                <div style={{ textAlign:"center", padding:"18px 8px", color:"var(--muted)", fontSize:11.5 }}>
                  <div style={{ fontSize:34, opacity:.6 }}>{bountyTab === "player" ? "🎁" : "🏴"}</div>
                  <div style={{ marginTop:6 }}>{t("bounty_board_empty")}</div>
                  {/* MV-3 §0 fix — the empty board teaches the geography (each
                      continent hangs its own cartazes; travel to hunt others). */}
                  <div style={{ marginTop:6, fontSize:10, fontStyle:"italic", opacity:.8 }}>
                    🧭 {t("bounty_board_empty_hint")}
                  </div>
                </div>
              ) : shownBounties.map(b => (
                <BountyRow key={b.bounty_id} b={b} onChallenge={() => { haptic("warning"); onOpenBounty(b); }} />
              ))}
          </Card>

          {/* Service NPCs — deep-links (facade, no duplicated logic). */}
          {/* MV-7 — card da Guilda dos Ofícios NA PRAÇA (payload-driven via
              player.profession_view; flag OFF → null → nada; CTA quando sem
              ofício, status quando tem — descobrível sem depender do ui_v2). */}
          {onOpenProfession && typeof ProfessionCard === "function" && (
            <div style={{ marginBottom:12 }}>
              <ProfessionCard player={player} onOpen={onOpenProfession} />
            </div>
          )}
          {/* MV-9.5 — 商队 A Caravana NA PRAÇA (payload-driven via `d.caravan`;
              a key só existe com o gate ON no servidor → sem ela o card devolve
              null e nada muda para os 239 do `main`). O toast da carga que
              chegou nasce aqui: a praça é um dos pontos onde o servidor credita. */}
          {onOpenCaravan && typeof CaravanCard === "function" && (
            <div style={{ marginBottom:12 }}>
              <CaravanCard crv={d.caravan} onOpen={onOpenCaravan} />
            </div>
          )}

          <Card>
            <CardTitle left={t("plaza_services")} />
            <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr 1fr", gap:8 }}>
              {services.map(s => (
                <button key={s.key} onClick={() => { haptic("select"); s.action === "world_sect" ? onOpenWorldSect() : s.action === "profession" ? onOpenProfession() : setTab(s.tab); }} style={{
                  background:"rgba(255,255,255,.04)", border:"1px solid rgba(var(--gold2-rgb),.20)",
                  borderRadius:10, padding:"10px 4px", cursor:"pointer", color:"var(--muted)",
                  display:"flex", flexDirection:"column", alignItems:"center", gap:4,
                }}>
                  <span style={{ fontSize:22 }}>{s.icon}</span>
                  <span style={{ fontSize:10.5 }}>{s.label}</span>
                </button>
              ))}
            </div>
          </Card>

          {/* Presence — NPC cultivators of this continent (honest 🤖). */}
          <Card>
            <CardTitle left={t("plaza_npcs_here")} right={npcs.length} />
            {plaza.loading && !plaza.data ? <ListSkeleton rows={3} />
              : npcs.length === 0 ? (
                <div style={{ textAlign:"center", padding:"16px 8px", color:"var(--muted)", fontSize:11.5 }}>
                  {t("plaza_empty_npcs")}
                </div>
              ) : npcs.map(n => (
                <div key={n.npc_id} onClick={() => { haptic("select"); onOpenNpc(n); }} style={{
                  display:"flex", alignItems:"center", gap:10, padding:"9px 2px",
                  borderBottom:"1px dashed rgba(var(--accent2-rgb),.16)", cursor:"pointer",
                }}>
                  <div style={{ flex:1, minWidth:0 }}>
                    <div style={{ fontSize:12.5, display:"flex", alignItems:"center", gap:6, flexWrap:"wrap" }}>
                      <span>{n.name}</span>
                      <Badge variant="warn">🤖 {t("lb_npc_chip")}</Badge>
                    </div>
                    <div style={{ fontSize:10.5, color:"var(--muted)", marginTop:2 }}>
                      {n.realm_emoji} {n.realm_name}{n.sub_layer ? " " + n.sub_layer : ""} · ⚔️ {fmtNum(n.power || 0)}
                      {n.path && <span> · {n.path.emoji} {n.path.name}</span>}
                    </div>
                    {/* MV-8 — a VITRINE: é ESTA linha que separa um NPC com
                        vontade de uma estátua com stats. Server-resolved (o
                        rótulo do goal e a linha da escala vêm prontos); a key
                        só existe com `jianghu` ON e o NPC com feito. */}
                    {n.jianghu && (
                      <div style={{ fontSize:10.5, color:"var(--gold3)", marginTop:2 }}>
                        {n.jianghu.label || ""}
                        {n.jianghu.at_ms ? <> · {t("jh_npc_since", { time: timeAgo(n.jianghu.at_ms) })}</> : null}
                        {n.jianghu.scale_line ? <div style={{ color:"#e07a7a" }}>{n.jianghu.scale_line}</div> : null}
                      </div>
                    )}
                  </div>
                  <span style={{ color:"var(--muted)", fontSize:16, flexShrink:0 }}>›</span>
                </div>
              ))}
          </Card>

          {/* Presence — real players of this continent (shadow already filtered). */}
          <Card>
            <CardTitle left={t("plaza_players_here")} right={players.length} />
            {plaza.loading && !plaza.data ? <ListSkeleton rows={2} />
              : players.length === 0 ? (
                <div style={{ textAlign:"center", padding:"16px 8px", color:"var(--muted)", fontSize:11.5 }}>
                  {t("plaza_empty_presence")}
                </div>
              ) : players.map((p, i) => (
                <div key={i} onClick={p.openable ? () => { haptic("select"); setProfileTarget(p.dao_name); } : undefined} style={{
                  display:"flex", alignItems:"center", gap:10, padding:"9px 2px",
                  borderBottom:"1px dashed rgba(var(--gold2-rgb),.14)", cursor: p.openable ? "pointer" : "default",
                }}>
                  <div style={{ flex:1, minWidth:0 }}>
                    <div style={{ fontSize:12.5, color:"var(--gold2)" }}>{p.dao_name || t("npc_cult_title")}</div>
                    <div style={{ fontSize:10.5, color:"var(--muted)", marginTop:2 }}>
                      {p.realm_emoji} {p.realm_name}{p.sub_layer ? " " + p.sub_layer : ""} · ⚔️ {fmtNum(p.power || 0)}
                    </div>
                  </div>
                  {p.openable && <span style={{ color:"var(--muted)", fontSize:16, flexShrink:0 }}>›</span>}
                </div>
              ))}
          </Card>

          {/* Feed — the continent's Heaven's Whispers (atmospheric, read-only). */}
          <Card>
            <CardTitle left={`🌌 ${t("wsp_feed_title")}`} />
            {whispers.length === 0 ? (
              <div style={{ textAlign:"center", padding:"16px 8px", color:"var(--muted)", fontSize:11.5 }}>
                {t("wsp_feed_empty")}
              </div>
            ) : whispers.map(w => (
              <div key={w.id} style={{ display:"flex", gap:9, padding:"8px 2px", borderBottom:"1px dashed rgba(var(--accent2-rgb),.14)" }}>
                <span style={{ fontSize:18, flexShrink:0 }}>{w.icon}</span>
                <div style={{ fontSize:11, color:"var(--muted)", lineHeight:1.5 }}>{w.body}</div>
              </div>
            ))}
          </Card>

          {/* World Pulse Fase 1 — Os Registos Celestiais: the continent's slice of
              the living world log. Strip + "ver tudo" opens the full ChronicleModal. */}
          <Card>
            <CardTitle left={`📜 ${t("cronica_strip_title")}`}
                       right={onOpenChronicle ? (
                         <span onClick={() => onOpenChronicle(d.continent || null)}
                               style={{ cursor:"pointer", fontSize:10.5, color:"var(--gold3)" }}>
                           {t("cronica_see_all")} ›
                         </span>
                       ) : null} />
            {chronicle.length === 0 ? (
              <div style={{ textAlign:"center", padding:"16px 8px", color:"var(--muted)", fontSize:11.5 }}>
                {t("cronica_feed_empty")}
              </div>
            ) : chronicle.slice(0, 4).map(e => (
              <div key={e.id} style={{ display:"flex", gap:9, padding:"8px 2px", borderBottom:"1px dashed rgba(var(--gold2-rgb),.14)" }}>
                <span style={{ fontSize:18, flexShrink:0 }}>{e.sect_emoji || e.icon}</span>
                <div style={{ flex:1, minWidth:0 }}>
                  <div style={{ fontSize:11, color:"var(--muted)", lineHeight:1.5 }}>{e.text}</div>
                  <div style={{ fontSize:9, color:"var(--muted)", opacity:.7, marginTop:2 }}>{timeAgo(e.ts_ms)}</div>
                </div>
              </div>
            ))}
          </Card>

          {profileTarget && (
            <ProfileCardModal target={profileTarget} onClose={() => setProfileTarget(null)}
                              onProposeTrade={onProposeTrade} />
          )}
        </div>
      );
    }

    // ─── Onda 4b — Travel between continents ─────────────────────────────────
    // Lifts current_continent into a player CHOICE. The map shows each
    // continent's IDENTITY (specialty + native content, Lei §1) + live presence
    // (players/NPCs/bounties) + the spirit-stone cost + per-destination
    // eligibility; confirming a destination POSTs world/travel_go (debits stones
    // on its OWN cooldown — never jade, Lei §4) and the plaza/bounty/encounters/
    // sect-affinity all FOLLOW the new continent (it emerges, no new code).
    // Mounted at the App root (in the back-stack) so the hardware/Telegram back
    // button closes it; on travel, onTraveled() refreshes the player + plaza.
    function fmtTravelDur(ms) {
      const s = Math.max(0, Math.floor((ms || 0) / 1000));
      const h = Math.floor(s / 3600), m = Math.floor((s % 3600) / 60);
      if (h > 0) return `${h}h${m > 0 ? " " + m + "m" : ""}`;
      if (m > 0) return `${m}m`;
      return `${s}s`;
    }

    function TravelModal({ onClose, onTraveled }) {
      const [reloadKey, setReloadKey] = useState(0);
      const trip = useApi("world/travel", null, [reloadKey]);
      const d = trip.data || {};
      const dests = d.destinations || [];
      const [confirmKey, setConfirmKey] = useState(null);
      const [err, setErr] = useState(null);

      const reasonText = (dst) => {
        if (dst.reason === "already_here") return t("travel_here");
        if (dst.reason === "locked_demonic") return t("travel_locked_demonic");
        if (dst.reason === "on_cooldown") return t("travel_on_cooldown", { time: fmtTravelDur(d.cooldown_remaining_ms) });
        if (dst.reason === "not_enough_stones") return t("travel_not_enough_stones", { cost: fmtNum(dst.cost || 0) });
        return null;
      };

      async function go(key) {
        setErr(null);
        try {
          const res = await api("world/travel_go", { continent: key });
          if (res && res.ok) {
            haptic("success");
            onTraveled && onTraveled(res);   // App root: loadPlayer + plaza bump + close
            return;
          }
          haptic("error");
          const r = res && res.reason;
          if (r === "not_enough_stones") setErr(t("travel_not_enough_stones", { cost: fmtNum((res && res.cost) || 0) }));
          else if (r === "on_cooldown") setErr(t("travel_on_cooldown", { time: fmtTravelDur((res && res.cooldown_remaining_ms) || 0) }));
          else if (r === "locked_demonic") setErr(t("travel_locked_demonic"));
          else if (r === "already_here") setErr(t("travel_already_here"));
          else setErr(t("travel_failed"));
          setConfirmKey(null);
          setReloadKey(x => x + 1);
        } catch (e) {
          haptic("error");
          setErr((e && e.message) || t("travel_failed"));
        }
      }

      return (
        <ModalShell onClose={onClose} title={`🧭 ${t("travel_title")}`} accent="rgba(var(--accent2-rgb),.5)" maxWidth={400}>
          <div style={{ fontSize:11.5, color:"var(--muted)", lineHeight:1.55, marginBottom:10 }}>
            {t("travel_intro")}
          </div>

          {/* What changes when you travel + the wipe teaser (Lei §1 disclosure). */}
          <div style={{ fontSize:10.5, color:"var(--gold3)", background:"rgba(var(--accent2-rgb),.07)",
                        border:"1px solid rgba(var(--accent2-rgb),.18)", borderRadius:10, padding:"8px 10px",
                        marginBottom:12, lineHeight:1.55 }}>
            <div>✨ {t("travel_changes_note")}</div>
            <div style={{ marginTop:4 }}>🔒 {t("travel_wipe_teaser")}</div>
          </div>

          {err && <div style={{ marginBottom:10 }}><ErrBanner msg={err} /></div>}

          {trip.loading && !trip.data ? <ListSkeleton rows={5} />
            : trip.error ? <ErrBanner msg={trip.error} />
            : dests.map(dst => {
              const confirming = confirmKey === dst.key;
              return (
                <Card key={dst.key} style={{ marginBottom:10, padding:"12px",
                  border: dst.is_current ? "1px solid rgba(var(--gold2-rgb),.4)" : "1px solid rgba(255,255,255,.08)" }}>
                  <div style={{ display:"flex", alignItems:"center", gap:8 }}>
                    <span style={{ fontSize:24, flexShrink:0 }}>{dst.emoji}</span>
                    <div style={{ flex:1, minWidth:0 }}>
                      <div style={{ fontFamily:"'Cinzel',serif", fontSize:14, color:"var(--gold2)", display:"flex", alignItems:"center", gap:6, flexWrap:"wrap" }}>
                        {dst.name}
                        {dst.is_current && <Badge variant="gold">📍 {t("travel_here")}</Badge>}
                        {dst.demonic_only && <Badge variant="red">{ico("🔒","lock",{ size:11, style:{ display:"inline-block", verticalAlign:"-1px" } })}</Badge>}
                      </div>
                      <div style={{ fontSize:10.5, color:"var(--muted)", marginTop:2, lineHeight:1.45 }}>{dst.specialty}</div>
                      {/* MV-3 — a linha do estado regional (server-resolved;
                          só chega no payload com `estados_regionais` ON). */}
                      {dst.region_state_line && (
                        <div style={{ fontSize:10, color:"var(--gold3)", marginTop:3, lineHeight:1.45 }}>
                          {dst.region_state_line}
                        </div>
                      )}
                      {/* MV-6 — como o lugar te recebe (server-resolved;
                          só chega no payload com `reputacao_rival` ON). */}
                      {dst.region_rep_line && (
                        <div style={{ fontSize:10, color:"var(--muted)", marginTop:3, lineHeight:1.45 }}>
                          {dst.region_rep_line}
                        </div>
                      )}
                      {/* MV-8 — 🚩 quem hasteia bandeira ali (server-resolved;
                          campo ADITIVO, nunca dentro do nome do estado). */}
                      {dst.region_state_occupant && (
                        <div style={{ fontSize:10, color:"var(--gold2)", marginTop:3, lineHeight:1.45 }}>
                          {dst.region_state_occupant}
                        </div>
                      )}
                      {/* MV-8 — o disclosure ANTES (Lei §1): você sabe onde te
                          procuram antes de pagar a viagem. */}
                      {dst.hunted > 0 && (
                        <div style={{ fontSize:10, color:"#e07a7a", marginTop:3, lineHeight:1.45 }}>
                          {t("jh_hunted", { n: dst.hunted })}
                        </div>
                      )}
                      {/* MV-9 — a razão de IR: 🏙️ a cidade (sempre) e 📜 o que
                          ela pede (sujeito à latência — longe, a linha diz de
                          quantas horas atrás é a notícia). Server-resolved;
                          as keys só chegam com `cidades` ON. */}
                      {dst.city_name && (
                        <div style={{ fontSize:10.5, color:"var(--gold2)", marginTop:4, lineHeight:1.45 }}>
                          {dst.city_emoji} {dst.city_name}
                        </div>
                      )}
                      {dst.city_encargo_line && (
                        <div style={{ fontSize:10, color:"var(--muted)", marginTop:2, lineHeight:1.45 }}>
                          {dst.city_encargo_line}
                        </div>
                      )}
                    </div>
                  </div>

                  {/* Native content tags — disclosure of what's "native" here. */}
                  {dst.native_tags && dst.native_tags.length > 0 && (
                    <div style={{ display:"flex", gap:6, flexWrap:"wrap", marginTop:8 }}>
                      {dst.native_tags.map(tg => (
                        <span key={tg.key} style={{ fontSize:9.5, padding:"2px 8px", borderRadius:99,
                          background:"rgba(255,255,255,.05)", border:"1px solid rgba(255,255,255,.1)", color:"var(--muted)" }}>
                          {tg.label}
                        </span>
                      ))}
                    </div>
                  )}

                  {/* Live presence + cost. */}
                  <div style={{ display:"flex", alignItems:"center", gap:10, marginTop:8, fontSize:10.5, color:"var(--muted)", flexWrap:"wrap" }}>
                    <span>👤 {fmtNum(dst.presence || 0)}</span>
                    <span>🤖 {fmtNum(dst.npc_count || 0)}</span>
                    {dst.bounty_count > 0 && <span>🏴 {fmtNum(dst.bounty_count)}</span>}
                    {!dst.is_current && <span style={{ marginLeft:"auto", color:"var(--gold3)" }}>🪨 {fmtNum(dst.cost || 0)}</span>}
                  </div>

                  {/* Action / inline confirm (one back-stack entry — no sub-modal). */}
                  {!dst.is_current && (
                    confirming ? (
                      <div style={{ marginTop:10 }}>
                        <div style={{ fontSize:11, color:"var(--gold3)", marginBottom:8, lineHeight:1.5 }}>
                          {t("travel_confirm_q", { name: dst.name, cost: fmtNum(dst.cost || 0) })}
                          {/* Fix display-lie (report [jogador] 2026-07-24): o valor é o
                              DESCANSO pós-viagem (cooldown p/ re-viajar) — sem o
                              rótulo lia-se como duração de trânsito (a viagem é
                              instantânea por design). Chat já rotulava. */}
                          <span style={{ color:"var(--muted)" }}> · ⏱️ {t("travel_cooldown_label")}: {fmtTravelDur(d.cooldown_full_ms)}</span>
                        </div>
                        <div style={{ display:"flex", gap:8 }}>
                          <ActionBtn variant="primary" onClick={() => go(dst.key)} style={{ flex:1 }}>
                            🧭 {t("travel_confirm")}
                          </ActionBtn>
                          <ActionBtn variant="ghost" onClick={() => setConfirmKey(null)} style={{ flex:1 }}>
                            {t("travel_cancel")}
                          </ActionBtn>
                        </div>
                      </div>
                    ) : dst.eligible ? (
                      <ActionBtn variant="primary" onClick={() => { haptic("select"); setConfirmKey(dst.key); setErr(null); }} style={{ marginTop:10, width:"100%" }}>
                        🧭 {t("travel_btn")}
                      </ActionBtn>
                    ) : (
                      <div style={{ marginTop:10, fontSize:10.5, color:"var(--red)", textAlign:"center", lineHeight:1.45 }}>
                        🔒 {reasonText(dst)}
                      </div>
                    )
                  )}
                </Card>
              );
            })}
        </ModalShell>
      );
    }

    // ═══ 決 A DECISAO MORAL — UM DONO (2026-09-16) ═══════════════════════════
    //
    // 🔴 TRES modais faziam a MESMA coisa a' mao: `NpcCultivatorModal` (o
    // perfil), `JianghuAmbushModal` (a emboscada) e `ExploreDuelModal` (o
    // Monstro Escondido). O comentario do segundo ja' dizia a intencao —
    // *"um so' vocabulario para uma so' decisao moral em todo o jogo"* — e o
    // codigo estava copiado tres vezes na mesma.
    //
    // E copia diverge SEMPRE. Medido ao juntar as tres:
    //   • as TRES tinham o mesmo defeito do item 5 da auditoria do Astra;
    //   • e a do Monstro Escondido ja' tinha perdido a linha do Caminho
    //     cristalizado (`karma.crystallized`) que as outras duas mostram — quem
    //     poupava um Monstro Escondido e cristalizava o Caminho nunca soube.
    //
    // ⚠️ O DEFEITO que isto conserta, medido nos DOIS lados:
    //
    //   O codigo antigo lia `st.state === "finished" && st.winner_id === youId`
    //   e mandava tudo o que nao fosse isso para `won=false` — que a tela
    //   escreve como 🥀 *"foste derrotado"*. So' que o servidor tem tres
    //   caminhos que chegam ali sem ser uma derrota:
    //     • `combat/duel_state` devolve **HTTP 200 com `ok:false`**
    //       (`not_a_participant`, webserver.py:16414) e 200 com `duel_id:null`;
    //     • `combat/npc_cultivator_resolve` devolve **HTTP 200 com
    //       `{ok:false,reason:"internal_error"}` em QUALQUER excepcao do
    //       servidor** (webserver.py:14685);
    //     • o prazo de 30s do transporte, que quer dizer "nao sei".
    //   Em nenhum deles o `catch` do cliente dispara. Uma falha de rede de
    //   200ms AFIRMAVA uma derrota que podia nao ter acontecido, e comia a
    //   escolha moral inteira — o karma nunca chegava a ser oferecido.
    //
    // ⚠️ Por isso o estado deixa de ser um BOOLEANO. Um booleano so' sabe dizer
    // duas coisas e aqui ha' TRES: venci, perdi, **nao sei**.
    //
    // 🔴 E o contrato do servidor JA' SALVAVA o jogador: o
    // `apply_combat_moral_choice` e' idempotente por duelo (o marcador
    // `pve_context['moral_resolved']`) e a recusa `already_resolved` **traz o
    // desfecho dentro dela**. O cliente deitava fora exactamente a informacao
    // que o desprendia. Por isso repetir e' seguro, e por isso a repeticao
    // consegue DIZER o que ficou gravado.
    function useDecisaoMoral({ duelId, setFase, aoResolver, aoVencer }) {
      const [desfecho, setDesfecho] = useState("desconhecido"); // vitoria|derrota|desconhecido
      const [moral, setMoral] = useState(null);
      const [moralErro, setMoralErro] = useState(null);   // {tipo:"recusa"|"silencio", razao}
      const [moralBusy, setMoralBusy] = useState(false);
      const won = desfecho === "vitoria";

      // Uma LEITURA — repeti-la e' de graca e nao muta nada. E' o que permite
      // oferecer "ver o desfecho" sem o risco de cobrar duas vezes de que o
      // Astra avisa no item 8 (*uma resposta perdida pode corresponder a uma
      // accao concluida no servidor*).
      async function lerDesfecho() {
        try {
          const st = await api("combat/duel_state", { duel_id: duelId });
          const youId = st && st.you && st.you.telegram_id;
          // `ok === false` chega com HTTP 200; e sem `youId` nao ha' com quem
          // comparar o vencedor. Os dois sao "nao sei", nunca "perdeste".
          if (!st || st.ok === false || st.state !== "finished" || youId == null) return "desconhecido";
          return st.winner_id === youId ? "vitoria" : "derrota";
        } catch (e) { return "desconhecido"; }
      }

      async function aposDuelo() {
        const d = await lerDesfecho();
        setDesfecho(d);
        if (d === "vitoria") {
          if (aoVencer) { try { await aoVencer(); } catch (e) {} }
          haptic("success"); setFase("moral");
        } else {
          haptic(d === "derrota" ? "error" : "warning"); setFase("result");
        }
        if (aoResolver) aoResolver();
      }

      // A saida do "nao sei". Se a segunda leitura disser VITORIA, a escolha
      // moral volta a ser oferecida: a consequencia nao se perde por causa de
      // uma resposta que nao chegou a' primeira.
      async function reverDesfecho() {
        if (moralBusy) return;
        setMoralBusy(true);
        const d = await lerDesfecho();
        setDesfecho(d);
        if (d === "vitoria" && !moral) {
          if (aoVencer) { try { await aoVencer(); } catch (e) {} }
          haptic("success"); setFase("moral");
        }
        setMoralBusy(false);
      }

      async function escolher(outcome) {
        if (moralBusy) return;
        setMoralBusy(true); setMoralErro(null);
        haptic(outcome === "spare" ? "success" : "warning");
        try {
          const res = await api("combat/npc_cultivator_resolve", { duel_id: duelId, outcome });
          if (res && res.ok) {
            setMoral(res); setFase("result");
          } else if (res && res.reason === "already_resolved" && res.outcome) {
            // A recusa idempotente TRAZ o desfecho: a 2a tentativa depois de
            // uma resposta perdida DIZ o que ficou gravado, em vez de calar.
            setMoral({ outcome: res.outcome }); setFase("result");
          } else {
            // Recusa dita pelo servidor, ou o `internal_error` a 200. Fica-se
            // NA escolha: sair para o resultado apagava a decisao sem a tela
            // alguma vez o admitir.
            setMoralErro({ tipo: "recusa", razao: (res && res.reason) || "" });
          }
        } catch (e) {
          // Prazo ou rede: a decisao PODE ter passado. Repetir e' seguro pela
          // idempotencia acima.
          setMoralErro({ tipo: "silencio", razao: (e && e.message) || "" });
        } finally { setMoralBusy(false); if (aoResolver) aoResolver(); }
      }

      return { desfecho, won, moral, moralErro, moralBusy, aposDuelo, reverDesfecho, escolher };
    }

    // O aviso da escolha que nao passou. Fica JUNTO dos dois botoes, que
    // continuam activos — repetir e' seguro (idempotente por duelo).
    function MoralErroAviso({ erro }) {
      if (!erro) return null;
      return (
        <div style={{ marginBottom:10, padding:"9px 11px", borderRadius:9, lineHeight:1.5,
                      background:"rgba(var(--red-rgb),.10)", border:"1px solid rgba(var(--red-rgb),.35)",
                      fontSize:11.5, color:"var(--red)" }}>
          {erro.tipo === "silencio"
            ? t("npc_cult_moral_silencio")
            : apiErroTexto(erro.razao || "server_error")}
        </div>
      );
    }

    // O que a escolha PRODUZIU: o desfecho, o karma e — a linha que a copia do
    // Monstro Escondido tinha perdido — o Caminho cristalizado.
    function MoralResultado({ moral }) {
      if (!moral || !moral.outcome) return null;
      return (
        <div style={{ fontSize:11.5, color:"var(--muted)", marginTop:8, lineHeight:1.5 }}>
          {moral.outcome === "spare" ? `☯️ ${t("npc_cult_spared")}` : `👹 ${t("npc_cult_executed")}`}
          {moral.karma && moral.karma.new_value != null && (
            <div style={{ marginTop:4 }}>⚖️ {t("npc_cult_karma_now", { value: moral.karma.new_value })}</div>
          )}
          {/* Lei §1 — se esta escolha cristalizou um Caminho permanente, diz-se. */}
          {moral.karma && moral.karma.crystallized && (
            <div style={{ marginTop:6, color:"var(--gold3)", fontFamily:"'Cinzel',serif" }}>
              ☯️ {t("npc_cult_path_crystallized")}
            </div>
          )}
        </div>
      );
    }

    // O rosto do desfecho, com as TRES faces. ⚠️ 疑 e' um CARACTERE e nao um
    // emoji: o `tabs.js` esta' no tecto da catraca do §15 (1300/1300) e um
    // emoji novo sem porta fa-la subir. E ele diz "duvida" melhor do que um
    // ponto de interrogacao.
    function DesfechoRosto({ desfecho, textoVitoria, textoDerrota, onRever, busy }) {
      const won = desfecho === "vitoria";
      const naoSei = desfecho === "desconhecido";
      return (
        <>
          <div style={{ fontSize:44, fontFamily: naoSei ? "'Cormorant Garamond',serif" : undefined,
                        color: naoSei ? "var(--gold3)" : undefined }}>
            {won ? "🏆" : desfecho === "derrota" ? "🥀" : "疑"}
          </div>
          <div style={{ fontFamily:"'Cinzel',serif", fontSize:14, marginTop:8,
                        color: won ? "var(--jade)" : naoSei ? "var(--gold3)" : "var(--muted)" }}>
            {won ? textoVitoria : naoSei ? t("explore_desfecho_incerto") : textoDerrota}
          </div>
          {naoSei && onRever && (
            <ActionBtn variant="primary" onClick={onRever} disabled={busy}
                       style={{ width:"100%", marginTop:14 }}>
              {t("explore_desfecho_rever")}
            </ActionBtn>
          )}
        </>
      );
    }

    // ─── Onda 3 — NPC Cultivator profile + challenge ─────────────────────────
    // Honest (Lei §1): ALWAYS marked 🤖 NPC, framed as a snapshot/echo — never
    // disguised as a real player. Flow: profile → duel (reuses DuelArenaModal)
    // → on a win, a spare/execute moral fork (Karmic-Crossroads pattern) → result.
    function NpcCultivatorModal({ target, onClose, onResolved }) {
      const npcId = target && (target.npc_id != null ? target.npc_id : target.id);
      // Onda 4a — when opened from a Bounty Board cartaz, target carries a
      // bounty_id; a WIN then claims the contract (the SAME duel, a reward on top).
      const bountyId = target && target.bounty_id;
      const { data, loading, error } = useApi("world/npc_profile", { npc_id: npcId }, [npcId]);
      const npc = (data && data.npc) || null;
      const bounty = (data && data.bounty) || null;       // Track A item 3 — post disclosure
      const rival = (data && data.rival) || null;         // MV-6 — a memória (só chega se ESTE NPC é o seu rival)
      const [phase, setPhase] = useState("profile");   // profile | duel | moral | result
      const [busy, setBusy] = useState(false);
      const [duelId, setDuelId] = useState(null);
      const [bountyClaim, setBountyClaim] = useState(null);  // bounty_claim response (Onda 4a)
      // 決 — o dono unico da decisao moral (ver `useDecisaoMoral` acima).
      // O `aoVencer` e' a caca ao premio: so' corre com a vitoria CONFIRMADA.
      const { desfecho, won, moral, moralErro, moralBusy, aposDuelo, reverDesfecho, escolher } =
        useDecisaoMoral({
          duelId, setFase: setPhase, aoResolver: onResolved,
          aoVencer: bountyId ? async function () {
            // Onda 4a — bounty hunt: idempotente, paga uma vez, provado pelo
            // duelo do lado do servidor. Best-effort: a recompensa base do
            // duelo ja' foi aplicada mesmo que a reclamacao falhe.
            try {
              const cr = await api("combat/bounty_claim", { bounty_id: bountyId, duel_id: duelId });
              setBountyClaim(cr || { ok: false });
            } catch (e) { setBountyClaim({ ok: false, reason: "engine" }); }
          } : null,
        });
      // Track A item 3 — "Pôr a Prêmio" post panel (inline, no extra back-stack).
      const [posting, setPosting] = useState(false);
      const [postAmt, setPostAmt] = useState("");
      const [postBusy, setPostBusy] = useState(false);
      const [postErr, setPostErr] = useState(null);
      const [postDone, setPostDone] = useState(null);

      async function submitBounty() {
        const min = (bounty && bounty.min_stones) || 0;
        const amt = parseInt(postAmt, 10);
        if (postBusy) return;
        if (isNaN(amt) || amt < min) { haptic("error"); setPostErr(t("wbounty_post_too_cheap", { min: fmtNum(min) })); return; }
        setPostBusy(true); setPostErr(null); haptic("warning");
        try {
          const res = await api("world/bounty_post", { npc_id: npcId, stones: amt });
          if (res && res.ok) {
            haptic("success"); setPostDone(res); setPosting(false);
            if (onResolved) onResolved();   // App root: reload player (stones) + bump plaza board
          } else {
            haptic("error");
            const r = res && res.reason;
            const map = {
              too_cheap: t("wbounty_post_too_cheap", { min: fmtNum((res && res.min_stones) || min) }),
              not_enough_stones: t("wbounty_post_no_stones"),
              max_active: t("wbounty_post_max", { max: (res && res.max_open) || (bounty && bounty.max_open) || 3 }),
              not_eligible: t("wbounty_post_not_eligible"),
              already_targeted: t("wbounty_post_already"),
            };
            setPostErr(map[r] || t("wbounty_post_err"));
          }
        } catch (e) {
          haptic("error"); setPostErr(t("wbounty_post_err"));
        } finally {
          setPostBusy(false);
        }
      }

      async function challenge() {
        if (busy) return;
        setBusy(true); haptic("warning");
        try {
          const res = await api("combat/npc_cultivator_fight", { npc_id: npcId });
          if (res && res.ok && res.duel_id) {
            setDuelId(res.duel_id); setPhase("duel");
          } else {
            haptic("error");
            const reason = (res && res.reason) || "engine";
            if (reason === "cooldown") {
              showToast(t("npc_cult_cooldown", { min: Math.ceil((res.remaining_seconds || 0) / 60) }));
            } else if (reason === "qi_insufficient") {
              showToast(t("npc_cult_no_qi"));
            } else if (reason === "duel_already_active") {
              showToast(t("npc_cult_busy"));
            } else if (reason === "hp_depleted") {
              showToast(t("npc_cult_no_hp"));
            } else if (reason === "npc_unavailable" || reason === "no_opponent") {
              showToast(t("npc_cult_unavailable"));
            } else {
              showToast(t("err_engine") || reason);
            }
          }
        } catch (e) {
          haptic("error"); showToast(t("err_engine") || "engine");
        } finally {
          setBusy(false);
        }
      }

      // Interactive duel — reuse the standard combat arena (overlays at z:80).
      if (phase === "duel" && duelId) {
        return <DuelArenaModal duelId={duelId} onClose={aposDuelo} playerLang={null} />;
      }

      const chip = (emoji, label) => (
        <span style={{
          fontSize:11, padding:"3px 9px", borderRadius:99, marginRight:6, marginBottom:4,
          display:"inline-block", background:"rgba(255,255,255,.06)",
          border:"1px solid rgba(255,255,255,.12)", color:"var(--muted)",
        }}>{emoji} {label}</span>
      );

      const titleNode = (
        <span style={{ fontFamily:"'Cinzel',serif", fontSize:13.5, fontWeight:700, color:"var(--gold2)" }}>
          🤖 {npc ? npc.name : t("npc_cult_title")}
        </span>
      );

      return (
        <Modal onClose={onClose} title={titleNode} accent="rgba(var(--accent2-rgb),.45)"
               maxWidth={420} zIndex={70}>
          {loading ? (
            <div style={{ textAlign:"center", padding:"30px 12px", color:"var(--muted)", fontSize:12 }}>
              <div style={{ marginBottom:10 }}><DotSpinner /></div>{t("profile_loading")}
            </div>
          ) : (error || !npc) ? (
            <ErrBanner msg={error || "not_found"} />
          ) : phase === "moral" ? (
            <div>
              <div style={{ textAlign:"center", padding:"10px 6px 14px" }}>
                <div style={{ fontSize:40 }}>⚔️</div>
                <div style={{ fontFamily:"'Cinzel',serif", fontSize:14, color:"var(--gold3)", marginTop:8 }}>
                  {t("npc_cult_victory_title")}
                </div>
                <div style={{ fontSize:11.5, color:"var(--muted)", marginTop:6, lineHeight:1.5 }}>
                  {t("npc_cult_moral_prompt", { name: npc.name })}
                </div>
              </div>
              <MoralErroAviso erro={moralErro} />
              <ActionBtn variant="primary" onClick={() => escolher("spare")} disabled={moralBusy}
                         style={{ width:"100%", marginBottom:8 }}>
                ☯️ {t("npc_cult_spare")}
              </ActionBtn>
              <div style={{ fontSize:10.5, color:"var(--muted)", textAlign:"center", marginBottom:12 }}>
                {t("npc_cult_spare_hint")}
              </div>
              <ActionBtn variant="danger" onClick={() => escolher("execute")} disabled={moralBusy}
                         style={{ width:"100%", marginBottom:8 }}>
                👹 {t("npc_cult_execute")}
              </ActionBtn>
              <div style={{ fontSize:10.5, color:"var(--muted)", textAlign:"center" }}>
                {t("npc_cult_execute_hint")}
              </div>
            </div>
          ) : phase === "result" ? (
            <div style={{ textAlign:"center", padding:"18px 10px" }}>
              <DesfechoRosto desfecho={desfecho} textoVitoria={t("npc_cult_won")}
                             textoDerrota={t("npc_cult_lost")}
                             onRever={reverDesfecho} busy={moralBusy} />
              <MoralResultado moral={moral} />
              {/* Onda 4a — bounty contract outcome (won fights only). */}
              {bountyClaim && bountyClaim.ok && (
                <div style={{ marginTop:10, fontSize:12, color:"var(--gold3)", fontFamily:"'Cinzel',serif" }}>
                  🏴 {t("bounty_claim_success", { stones: fmtNum(bountyClaim.reward_stones || 0) })}
                </div>
              )}
              {bountyClaim && !bountyClaim.ok && (bountyClaim.reason === "already_claimed") && (
                <div style={{ marginTop:10, fontSize:11, color:"var(--muted)" }}>
                  🏴 {t("bounty_claimed_by_other")}
                </div>
              )}
              {bountyClaim && !bountyClaim.ok && (bountyClaim.reason === "own_bounty") && (
                <div style={{ marginTop:10, fontSize:11, color:"var(--muted)" }}>
                  🎁 {t("wbounty_post_self_note")}
                </div>
              )}
              <ActionBtn variant="ghost" onClick={onClose} style={{ width:"100%", marginTop:16 }}>
                {t("btn_close")}
              </ActionBtn>
            </div>
          ) : (
            // phase === "profile"
            <div>
              <div style={{
                fontSize:10.5, color:"var(--muted)", textAlign:"center", marginBottom:12,
                padding:"7px 10px", borderRadius:8,
                background:"rgba(var(--accent2-rgb),.08)", border:"1px solid rgba(var(--accent2-rgb),.22)",
              }}>
                🤖 {t("npc_cult_honest_banner")}
              </div>
              <div style={{ display:"flex", flexWrap:"wrap", justifyContent:"center", marginBottom:10 }}>
                {chip(npc.realm_emoji || "🌀", `${npc.realm_name || ""}${npc.sub_layer ? " " + npc.sub_layer : ""}`)}
                {npc.continent && chip(npc.continent.emoji, npc.continent.name)}
                {npc.path && chip(npc.path.emoji, npc.path.name)}
                {npc.sect && chip(npc.sect.emoji, npc.sect.name)}
                {npc.karma && chip(npc.karma.emoji, npc.karma.label)}
                {/* Track A (B4) — Lifespan flavor: a deterministic age line (no
                    real ageing/death this wave; ∞ = an ageless immortal echo). */}
                {npc.age != null ? chip("⏳", t("npc_age", { age: npc.age })) : null}
                {/* Track A (B4) — Mind Sea flavor: a deterministic depth tier from
                    the NPC's realm (no soul/perception on the echo row). */}
                {npc.mind_sea ? chip(npc.mind_sea.tier_emoji || "🪷", safeT("mind_sea_tier_" + npc.mind_sea.tier, null, "")) : null}
              </div>
              {/* MV-6 — O RIVAL: a memória fala antes da espada (taunt
                  determinístico + escala honesta). Só chega no payload quando
                  ESTE NPC é o rival do viewer (flag ON) — OFF byte-idêntico. */}
              {rival && (
                <div style={{
                  fontSize:11.5, color:"rgba(255,210,210,.9)", textAlign:"center",
                  fontStyle:"italic", lineHeight:1.5, marginBottom:12,
                  padding:"8px 11px", borderRadius:8,
                  background:"rgba(200,60,60,.08)", border:"1px dashed rgba(200,60,60,.4)",
                }}>
                  😤 {t("rvl_modal_banner")}
                  <div style={{ marginTop:5 }}>“{rival.taunt}”</div>
                  <div style={{ marginTop:5, fontStyle:"normal", fontSize:10, color:"var(--muted)" }}>
                    {t("rvl_defeats_chip", { n: rival.defeats })}
                    {rival.power_bonus_pct > 0 && <> · {t("rvl_power_chip", { pct: rival.power_bonus_pct })}</>}
                  </div>
                </div>
              )}
              {/* Track A item 4 — how this NPC regards YOU, crossed from
                  (npc_karma × your_karma). Pure narrative, zero mechanics. */}
              {npc.reaction && npc.reaction.line ? (
                <div style={{
                  fontSize:11.5, color:"rgba(var(--text2-rgb),.84)", textAlign:"center",
                  fontStyle:"italic", lineHeight:1.5, marginBottom:12,
                  padding:"8px 11px", borderRadius:8,
                  background:"rgba(var(--accent2-rgb),.06)", border:"1px solid rgba(var(--accent2-rgb),.18)",
                }}>
                  {npc.reaction.emoji} {npc.reaction.line}
                </div>
              ) : null}
              <Card style={{ marginBottom:12 }}>
                <div style={{ display:"flex", justifyContent:"space-between", fontSize:12 }}>
                  <span style={{ color:"var(--muted)" }}>⚔️ {t("lb_power")}</span>
                  <span style={{ color:"var(--gold3)", fontWeight:700 }}>{fmtNum(npc.power || 0)}</span>
                </div>
              </Card>
              <ActionBtn variant="primary" onClick={challenge} disabled={busy}
                         style={{ width:"100%" }}>
                ⚔️ {t("npc_cult_challenge")}
              </ActionBtn>

              {/* Track A item 3 — "Pôr a Prêmio": only dark-karma targets that
                  don't already carry an OPEN contract (Lei §1: rules disclosed
                  BEFORE the player commits the non-refundable stones, Lei §4). */}
              {postDone && postDone.ok ? (
                <div style={{ marginTop:12, fontSize:12, color:"var(--gold3)", textAlign:"center", fontFamily:"'Cinzel',serif", lineHeight:1.5 }}>
                  {t("wbounty_post_ok", { stones: fmtNum(postDone.reward_stones || 0), target: (npc ? npc.name : "") })}
                  {/* MV-3 §0 fix — the receipt SAYS which board the cartaz hangs
                      on (it is stamped with the TARGET's continent, which can
                      differ from where the poster stands — Lei §1). */}
                  {postDone.continent_name && (
                    <div style={{ fontSize:10.5, color:"var(--muted)", marginTop:4, fontFamily:"inherit" }}>
                      📜 {t("wbounty_post_ok_where", { continent: `${postDone.continent_emoji || ""} ${postDone.continent_name}`.trim() })}
                    </div>
                  )}
                </div>
              ) : bounty && bounty.eligible && bounty.already_open && !bountyId ? (
                <div style={{ marginTop:10, fontSize:10.5, color:"var(--muted)", textAlign:"center" }}>
                  🎁 {t("wbounty_post_already")}
                </div>
              ) : bounty && bounty.eligible && !bounty.already_open && !posting ? (
                <ActionBtn variant="ghost" onClick={() => { haptic("select"); setPosting(true); setPostErr(null); }}
                           style={{ width:"100%", marginTop:8 }}>
                  {t("wbounty_post_cta")}
                </ActionBtn>
              ) : null}

              {posting && !postDone && (
                <div style={{ marginTop:10, padding:"10px", borderRadius:10,
                              background:"rgba(180,60,60,.06)", border:"1px solid rgba(180,60,60,.2)" }}>
                  <div style={{ fontSize:10.5, color:"var(--muted)", lineHeight:1.5, marginBottom:6 }}>
                    {/* MV-9 — {city} tem de ser PASSADO: `t()` só substitui o que
                        recebe, e uma chaveta não substituída vai crua para a
                        tela. O nome vem resolvido do servidor (o mini-app não
                        tem keys `city_*`); com a flag OFF vem vazio e cai no
                        nome de sempre. */}
                    {t("wbounty_post_intro", { city: (bounty && bounty.city) || "Wànshì" })}
                  </div>
                  <div style={{ fontSize:10, color:"var(--muted)", fontStyle:"italic", marginBottom:8 }}>
                    {t("wbounty_post_self_note")}
                  </div>
                  <div style={{ display:"flex", justifyContent:"space-between", fontSize:10.5, color:"var(--gold3)", marginBottom:6 }}>
                    <span>{t("wbounty_post_cost", { min: fmtNum(bounty.min_stones || 0) })}</span>
                    <span>{t("wbounty_post_active", { open: bounty.your_open || 0, max: bounty.max_open || 0 })}</span>
                  </div>
                  <div style={{ display:"flex", justifyContent:"space-between", fontSize:11, color:"var(--jade)", marginBottom:8 }}>
                    <span>🪨 {t("your_stones")}</span><b>{fmtNum(bounty.your_stones || 0)}</b>
                  </div>
                  {postErr && <div style={{ marginBottom:8 }}><ErrBanner msg={postErr} /></div>}
                  <div style={{ display:"flex", gap:6, alignItems:"center", marginBottom:8 }}>
                    <input type="number" inputMode="numeric" enterKeyHint="done" min={bounty.min_stones || 1}
                           placeholder={t("wbounty_post_placeholder")} value={postAmt}
                           onChange={e => setPostAmt(e.target.value.replace(/[^0-9]/g, ""))}
                           style={{ flex:1, padding:"10px 12px", borderRadius:8, background:"rgba(0,0,0,.4)",
                                    border:"1px solid rgba(180,60,60,.4)", color:"var(--text)", fontSize:14, outline:"none" }} />
                    <span style={{ fontSize:18 }}>🪨</span>
                  </div>
                  <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:6 }}>
                    <ActionBtn variant="ghost" onClick={() => { setPosting(false); setPostErr(null); setPostAmt(""); }} disabled={postBusy}>
                      {t("travel_cancel")}
                    </ActionBtn>
                    <ActionBtn variant="danger" onClick={submitBounty} disabled={postBusy}>
                      {postBusy ? <DotSpinner /> : t("wbounty_post_btn")}
                    </ActionBtn>
                  </div>
                </div>
              )}
            </div>
          )}
        </Modal>
      );
    }

    // ─── MV-8 江湖 — A EMBOSCADA (encontro com ESCOLHA, nunca duelo forçado) ──
    // Montado no ROOT do App (lição nav-state-loss: modal fora do
    // _anyModalOpen/_handleBack = back nativo fecha o webapp).
    //
    // ⚠️ O FORK MORAL PRECISA VIVER AQUI. A UI do spare/execute NÃO lê
    // `offer_moral_choice` do payload: ela é uma FASE dentro da máquina do
    // NpcCultivatorModal, que salta para "moral" quando o PRÓPRIO modal vê a
    // vitória. Um modal novo que não reimplemente a fase faz o fork nascer
    // INVISÍVEL — mesmo com o servidor 100% correto (o endpoint
    // `npc_cultivator_resolve` já aceita a fonte nova). Por isso as fases
    // abaixo são as MESMAS quatro, e reusam as MESMAS keys npc_cult_*: um só
    // vocabulário para uma só decisão moral em todo o jogo.
    function JianghuAmbushModal({ offer, onClose, onDone }) {
      const [phase, setPhase] = useState("offer");   // offer | duel | moral | result
      const [busy, setBusy] = useState(false);
      const [duelId, setDuelId] = useState(null);
      const [outcome, setOutcome] = useState(null);  // bribe | flee
      // 決 — o MESMO dono da decisao moral do perfil e do Monstro Escondido.
      const { desfecho, won, moral, moralErro, moralBusy, aposDuelo, reverDesfecho, escolher } =
        useDecisaoMoral({ duelId, setFase: setPhase, aoResolver: onDone, aoVencer: null });
      if (!offer) return null;

      const cost = offer.bribe_cost || 0;
      const qiCost = offer.qi_cost || 25;
      const hours = offer.travel_cooldown_hours || 4;

      async function resolve(branch) {
        if (busy) return;
        setBusy(true);
        try {
          const res = await api("world/jianghu_ambush", { npc_id: offer.npc_id, branch });
          if (res && res.ok && branch === "fight" && res.duel_id) {
            setDuelId(res.duel_id); setPhase("duel"); return;
          }
          if (res && res.ok) {
            haptic("success");
            setOutcome(branch);
            setPhase("result");
            return;
          }
          const reason = (res && res.reason) || "err_engine";
          haptic("error");
          // ⚠️ Cada recusa tem a SUA frase. Antes o "sem qi" mostrava a DICA
          // ("Custa 25 de qi. Nenhum duelo começa sem o seu toque.") e o "sem
          // pedras" mostrava só o preço: o jogador tocava outra vez e lia a
          // mesma coisa, sem nunca saber que faltava alguma coisa (Lei §1).
          if (reason === "hunter_gone") { showToast(t("jh_amb_gone"), "err"); onDone && onDone(); onClose && onClose(); return; }
          if (reason === "already_resolved" || reason === "duel_already_active") {
            showToast(t("jh_amb_already"), "err"); onDone && onDone(); onClose && onClose(); return;
          }
          if (reason === "not_enough_stones") showToast(t("jh_amb_no_stones", {
            cost: fmtNum(res.cost || cost),
            have: fmtNum(res.have != null ? res.have : (offer.stones || 0)),
          }), "err");
          else if (reason === "hp_depleted") showToast(t("duel_err_hp_depleted") || t("err_engine"), "err");
          else if (reason === "qi_insufficient") showToast(t("jh_amb_no_qi", { qi: fmtNum(res.qi_cost || qiCost) }), "err");
          else showToast(t("err_engine"), "err");
        } catch (e) {
          haptic("error"); showToast(t("err_engine"), "err");
        } finally {
          setBusy(false);
        }
      }

      // A arena padrão (overlay z:80) — a mesma de todo duelo do jogo.
      if (phase === "duel" && duelId) {
        return <DuelArenaModal duelId={duelId} onClose={aposDuelo} playerLang={null} />;
      }

      const reasonLine = offer.reason_line || "";

      return (
        /* `jh_amb_title` já carrega o próprio 🗡️ — um prefixo aqui rendia
           "🗡️ 🗡️ Emboscada" no cabeçalho de toda emboscada. */
        <Modal open onClose={onClose} title={offer.title || t("jh_amb_chip")}
               accent="rgba(220,90,90,.5)" maxWidth={420} zIndex={70}>
          {phase === "moral" ? (
            <div>
              <div style={{ textAlign:"center", padding:"10px 6px 14px" }}>
                <div style={{ fontSize:40 }}>⚔️</div>
                <div style={{ fontFamily:"'Cinzel',serif", fontSize:14, color:"var(--gold3)", marginTop:8 }}>
                  {t("npc_cult_victory_title")}
                </div>
                <div style={{ fontSize:11.5, color:"var(--muted)", marginTop:6, lineHeight:1.5 }}>
                  {t("npc_cult_moral_prompt", { name: offer.name })}
                </div>
              </div>
              <MoralErroAviso erro={moralErro} />
              <ActionBtn variant="primary" onClick={() => escolher("spare")} disabled={moralBusy}
                         style={{ width:"100%", marginBottom:8 }}>
                ☯️ {t("npc_cult_spare")}
              </ActionBtn>
              <div style={{ fontSize:10.5, color:"var(--muted)", textAlign:"center", marginBottom:12 }}>
                {t("npc_cult_spare_hint")}
              </div>
              <ActionBtn variant="danger" onClick={() => escolher("execute")} disabled={moralBusy}
                         style={{ width:"100%", marginBottom:8 }}>
                👹 {t("npc_cult_execute")}
              </ActionBtn>
              <div style={{ fontSize:10.5, color:"var(--muted)", textAlign:"center" }}>
                {t("npc_cult_execute_hint")}
              </div>
            </div>
          ) : phase === "result" ? (
            <div style={{ textAlign:"center", padding:"18px 10px" }}>
              {/* Subornar e fugir sao desfechos ESCOLHIDOS, sem duelo — nao
                  passam pelo rosto de tres faces, que e' sobre o que o
                  servidor confirmou de uma LUTA. */}
              {outcome === "bribe" || outcome === "flee" ? (
                <>
                  <div style={{ fontSize:44 }}>{outcome === "bribe" ? "💰" : "🏃"}</div>
                  <div style={{ fontSize:12, color:"var(--muted)", marginTop:10, lineHeight:1.55 }}>
                    {outcome === "bribe" ? t("jh_amb_bribe_hint") : t("jh_amb_flee_hint", { hours })}
                  </div>
                </>
              ) : (
                <DesfechoRosto desfecho={desfecho} textoVitoria={t("npc_cult_won")}
                               textoDerrota={t("npc_cult_lost")}
                               onRever={reverDesfecho} busy={moralBusy} />
              )}
              <MoralResultado moral={moral} />
              <ActionBtn variant="ghost" onClick={onClose} style={{ width:"100%", marginTop:16 }}>
                {t("btn_close")}
              </ActionBtn>
            </div>
          ) : (
            <div>
              <div style={{ fontSize:12.5, color:"var(--gold3)", fontFamily:"'Cinzel',serif",
                            textAlign:"center", marginBottom:8 }}>
                {offer.intro || offer.name}
              </div>
              {reasonLine && (
                <div style={{ fontSize:11.5, color:"var(--muted)", textAlign:"center",
                              marginBottom:14, lineHeight:1.5, fontStyle:"italic" }}>
                  {reasonLine}
                </div>
              )}
              <ActionBtn variant="danger" onClick={() => resolve("fight")} disabled={busy}
                         style={{ width:"100%", marginBottom:6 }}>
                {t("jh_amb_fight")}
              </ActionBtn>
              <div style={{ fontSize:10.5, color:"var(--muted)", textAlign:"center", marginBottom:12 }}>
                {t("jh_amb_fight_hint", { qi: fmtNum(qiCost) })}
              </div>
              {/* Lei §1 + a lição do hard-gate do [jogador]: o botão NUNCA some por
                  falta de pedras — ele aparece desabilitado, com o número à vista. */}
              <ActionBtn variant="primary" onClick={() => resolve("bribe")}
                         disabled={busy || !offer.can_bribe}
                         style={{ width:"100%", marginBottom:6 }}>
                {t("jh_amb_bribe")} · {t("jh_amb_bribe_cost", { cost: fmtNum(cost) })}
              </ActionBtn>
              <div style={{ fontSize:10.5, color:"var(--muted)", textAlign:"center", marginBottom:12 }}>
                {offer.can_bribe ? t("jh_amb_bribe_hint")
                  : t("jh_amb_stones", { have: fmtNum(offer.stones || 0) })}
              </div>
              <ActionBtn onClick={() => resolve("flee")} disabled={busy}
                         style={{ width:"100%", marginBottom:6 }}>
                {t("jh_amb_flee")}
              </ActionBtn>
              <div style={{ fontSize:10.5, color:"var(--muted)", textAlign:"center" }}>
                {t("jh_amb_flee_hint", { hours })}
              </div>
            </div>
          )}
        </Modal>
      );
    }

    // ─── Onda 5 — Reinos Exploráveis (the additive exploration loop) ─────────
    // The Explore tab: scan the continent by Divine Sense (神識) → pick a
    // direction (cache ✨ / trash ⚠️ / moral fork 🔀 / Hidden Monster ☠️) →
    // gather MATERIALS → safe return or go deeper. ADDITIVE (coexists with
    // /dungeons). A Hidden Monster lifts the duel to the App root (ExploreDuelModal
    // reuses DuelArenaModal + the spare/execute fork). Loot = materials only,
    // never techniques (Lei §5); cost = qi, never jade (Lei §4).

    // R5: hex literal (espelho do :root) — a borda dos cards de direção faz
    // `risk.color + "44"`; com var() o longhand caía p/ currentColor (borda
    // esbranquiçada, artefato) em vez do tint por risco desenhado.
    var EXPLORE_RISK = {
      safe:    { emoji:"✨", color:"var(--jade)" },
      danger:  { emoji:"⚠️", color:"var(--gold3)" },
      choice:  { emoji:"🔀", color:"var(--realm-4)" },
      ominous: { emoji:"☠️", color:"var(--red)" },
      mythic:  { emoji:"👁️‍🗨️", color:"var(--realm-6)" },
    };

    function _exploreLootLine(bag) {
      if (!bag) return null;
      var parts = [];
      if (bag.stones) parts.push("🪨 " + fmtNum(bag.stones));
      (bag.items || []).slice(0, 8).forEach(function (it) { parts.push(it.name + " ×" + it.qty); });
      return parts.length ? parts.join(" · ") : null;
    }

    function ExploreTab({ player, setTab, reloadSignal, onPlayerRefresh, onOpenDuel, onOpenAmbush }) {
      const [reload, setReload] = useState(0);
      const { data, loading, error } = useApi("world/explore_scan", null, [reload, reloadSignal]);
      const [busy, setBusy] = useState(false);
      const [banner, setBanner] = useState(null);   // {tone:'good'|'bad', text, loot}
      const [fork, setFork] = useState(null);        // needs_choice response + {idx}
      const [showTeasers, setShowTeasers] = useState(false);

      function refresh() { setReload(function (x) { return x + 1; }); }

      function reasonToast(res) {
        const r = res && res.reason;
        if (r === "qi_insufficient") return showToast(t("explore_no_qi", { cost: (res && res.qi_cost) || 0 }));
        if (r === "cooldown") return showToast(t("explore_cooldown"));
        if (r === "hp_depleted") return showToast(t("explore_hp_depleted"));
        if (r === "meditation_too_deep") return showToast(t("explore_meditation"));
        if (r === "stale") { refresh(); return; }
        return showToast(t("err_engine") || (r || "engine"));
      }

      async function go(dir, choice) {
        if (busy) return;
        setBusy(true); haptic((dir.is_hidden || dir.is_mythic) ? "warning" : "select");
        try {
          const body = { direction: dir.idx, expected_depth: (data && data.depth) || 0 };
          if (choice) body.choice = choice;
          const res = await api("world/explore_advance", body);
          if (!res || !res.ok) { haptic("error"); reasonToast(res || {}); setFork(null); refresh(); return; }
          if (res.needs_choice) { setFork(Object.assign({}, res, { idx: dir.idx })); return; }
          if (res.redirect_to_duel && res.duel_id) {
            setFork(null);
            if (onOpenDuel) onOpenDuel({ duelId: res.duel_id, npc: res.npc || null });
            return;
          }
          // Resolved inline (cache / trash / fork).
          setFork(null);
          const died = res.type === "trash" && res.died;
          let text = died ? ("💀 " + t("explore_died"))
            : (res.type === "fork" && res.result_key) ? t(res.result_key)
            : (res.type === "trash" && res.won) ? ("⚔️ " + t("explore_won"))
            : (res.type === "cache") ? ("🌿 " + t("explore_cache"))
            : t("explore_advanced");
          const loot = died ? _exploreLootLine(res.survivors) : _exploreLootLine(res.gained);
          setBanner({ tone: died ? "bad" : "good", text: text, loot: loot });
          if (onPlayerRefresh) onPlayerRefresh();
          // MV-8 — a emboscada é EFÊMERA (não existe row de plano): se ninguém
          // a levantar aqui, o encontro simplesmente não aconteceu. O explore é
          // o cano de MAIOR volume do jogo (814 lutas/30d), então é aqui que
          // ela mais aparece. Sobe para o root (o modal stacka a arena).
          if (res.jianghu_ambush && onOpenAmbush) onOpenAmbush(res.jianghu_ambush);
          refresh();
        } catch (e) { haptic("error"); showToast(t("err_engine") || "engine"); }
        finally { setBusy(false); }
      }

      async function retreat() {
        if (busy) return;
        setBusy(true); haptic("select");
        try {
          const res = await api("world/explore_retreat", {});
          if (res && res.ok) {
            setBanner({ tone: "good", text: "🏃 " + t("explore_retreated"), loot: _exploreLootLine(res.banked) });
            if (onPlayerRefresh) onPlayerRefresh();
          } else if (res && res.reason === "duel_in_progress" && res.duel_id) {
            // A Hidden-Monster duel is unsettled — resume it instead of banking.
            setBusy(false);
            if (onOpenDuel) onOpenDuel({ duelId: res.duel_id, npc: null });
            return;
          }
        } catch (e) { showToast(t("err_engine") || "engine"); }
        finally { setBusy(false); refresh(); }
      }

      const bannerNode = banner ? (
        <div style={{
          padding:"9px 12px", borderRadius:10, marginBottom:12, fontSize:12, lineHeight:1.5,
          background: banner.tone === "bad" ? "rgba(220,80,80,.10)" : "rgba(80,200,140,.10)",
          border: "1px solid " + (banner.tone === "bad" ? "rgba(220,80,80,.28)" : "rgba(80,200,140,.28)"),
          color: "var(--text)",
        }}>
          <div>{banner.text}</div>
          {banner.loot && <div style={{ marginTop:5, color:"var(--gold3)" }}>🎁 {banner.loot}</div>}
        </div>
      ) : null;

      // ── Moral fork (Karmic-Crossroads style) ──
      if (fork) {
        return (
          <div style={{ padding:"4px 2px 80px" }}>
            <CardTitle left={"🔀 " + (fork.node_emoji || "🧭") + " " + (fork.node_name || t("explore_title"))} />
            <Card style={{ marginBottom:12 }}>
              <div style={{ fontSize:12.5, color:"var(--text)", lineHeight:1.55 }}>{t(fork.prompt_key)}</div>
            </Card>
            {(fork.choices || []).map(function (c) {
              const kd = c.karma_delta || 0;
              return (
                <ActionBtn key={c.id} variant="ghost" disabled={busy}
                           onClick={function () { go({ idx: fork.idx, is_hidden:false }, c.id); }}
                           style={{ width:"100%", marginBottom:8, textAlign:"left" }}>
                  <span>{t(c.label_key)}</span>
                  {kd !== 0 && (
                    <span style={{ float:"right", color: kd > 0 ? "var(--jade)" : "var(--red)", fontSize:11 }}>
                      {(kd > 0 ? "+" : "") + kd} ⚖️
                    </span>
                  )}
                </ActionBtn>
              );
            })}
            <ActionBtn variant="ghost" onClick={function () { setFork(null); }} style={{ width:"100%", marginTop:4 }}>
              {t("explore_back")}
            </ActionBtn>
          </div>
        );
      }

      return (
        <div style={{ padding:"4px 2px 80px" }}>
          <div style={{ textAlign:"center", marginBottom:10 }}>
            <div style={{ fontFamily:"'Cinzel',serif", fontSize:16, color:"var(--gold2)" }}>🧭 {t("explore_title")}</div>
            <div style={{ fontSize:11, color:"var(--muted)", marginTop:4, lineHeight:1.5 }}>{t("explore_intro")}</div>
          </div>

          {bannerNode}

          <div style={{ display:"flex", justifyContent:"center", gap:8, flexWrap:"wrap", marginBottom:12 }}>
            <Badge>🪜 {t("explore_depth", { depth: (data && data.depth) || 0 })}</Badge>
            <Badge>🌀 {fmtNum(Math.floor((data && data.qi) || 0))} {t("explore_qi_short")}</Badge>
            {/* Fase 2 — clarity: a perception Formação/pill raises the EFFECTIVE
                perception (✨ marks the boost — Lei §1, the player SEES it). */}
            <Badge>👁️ {fmtNum((data && (data.effective_perception || data.perception)) || 0)}
              {(data && data.effective_perception > data.perception) ? " ✨" : ""}</Badge>
            <Badge>🍀 {fmtNum((data && data.luck) || 0)}</Badge>
            {/* Fase 2 — an active Véu (explore_protection) is DISCLOSED here. */}
            {(data && data.protection > 0) && (
              <Badge>🌫️ {t("explore_protection_chip", { pct: Math.round(data.protection * 100) })}</Badge>
            )}
          </div>

          {/* Quick-wins 2026-06-10 — HP bar ([jogador] 09.06: "pra ter noção do
              quanto podemos explorar"). Reuses the dungeon/combat HPBar so the
              player knows when to take Safe Return before a fight kills them. */}
          {(data && data.hp_max > 0) && (
            <div style={{ maxWidth:300, margin:"0 auto 12px" }}>
              <HPBar cur={data.current_hp != null ? data.current_hp : data.hp_max} max={data.hp_max} />
            </div>
          )}

          {(data && data.has_bag) && (
            <Card style={{ marginBottom:12 }}>
              <div style={{ fontSize:11.5, color:"var(--gold3)" }}>🎒 {_exploreLootLine(data.bag)}</div>
              <ActionBtn variant="primary" onClick={retreat} disabled={busy}
                         style={{ width:"100%", marginTop:8 }}>
                🏃 {t("explore_retreat")}
              </ActionBtn>
              <div style={{ fontSize:10, color:"var(--muted)", textAlign:"center", marginTop:5 }}>
                {t("explore_retreat_hint")}
              </div>
            </Card>
          )}

          {loading ? (
            <ListSkeleton rows={3} />
          ) : error ? (
            <ErrBanner msg={error} />
          ) : (data && data.directions && data.directions.length) ? (
            <div>
              <div style={{ fontSize:11, color:"var(--muted)", margin:"4px 2px 8px" }}>🧿 {t("explore_pick")}</div>
              {data.directions.map(function (d) {
                const risk = EXPLORE_RISK[d.risk] || EXPLORE_RISK.danger;
                return (
                  <Card key={d.idx} style={{ marginBottom:8, cursor:"pointer", borderColor: risk.color + "44" }}
                        onClick={function () { go(d); }}>
                    <div style={{ display:"flex", alignItems:"center", gap:10 }}>
                      <div style={{ fontSize:22 }}>{d.emoji}</div>
                      <div style={{ flex:1, minWidth:0 }}>
                        <div style={{ fontSize:12.5, color:"var(--text)", fontWeight:600 }}>
                          {d.node_emoji} {d.node_name}
                          <span style={{ marginLeft:7, fontSize:10.5, color: risk.color }}>
                            {risk.emoji} {t(d.risk_key)}
                          </span>
                          {d.is_mythic && (
                            <span style={{ marginLeft:6, fontSize:9.5, fontWeight:700, color:"var(--realm-6)",
                                           border:"1px solid var(--realm-6)", borderRadius:6, padding:"1px 5px" }}>
                              {d.mythic_emoji || "👁️‍🗨️"} {t("explore_mythic_chip")}
                            </span>
                          )}
                        </div>
                        <div style={{ fontSize:10.5, color: d.is_mythic ? "var(--realm-6)" : "var(--muted)", marginTop:3, lineHeight:1.45 }}>
                          {t(d.clue_key)}
                        </div>
                      </div>
                      <div style={{ fontSize:11, color:"var(--muted)", whiteSpace:"nowrap" }}>🌀 {d.qi_cost}</div>
                    </div>
                  </Card>
                );
              })}
            </div>
          ) : (
            <div style={{ textAlign:"center", color:"var(--muted)", fontSize:12, padding:"20px 10px" }}>
              {t("explore_empty")}
            </div>
          )}

          {/* Onda 5 Fase 2 — the cavern/formations door: the loot's PURPOSE. */}
          <Card style={{ marginTop:14, cursor:"pointer", borderColor:"rgba(212,175,55,.30)" }}
                onClick={function () { haptic("select"); setTab("cavern"); }}>
            <div style={{ display:"flex", alignItems:"center", gap:10 }}>
              <div style={{ fontSize:22 }}>🏯</div>
              <div style={{ flex:1 }}>
                <div style={{ fontSize:12.5, color:"var(--gold3)", fontWeight:600 }}>{t("cavern_title")}</div>
                <div style={{ fontSize:10.5, color:"var(--muted)", marginTop:3, lineHeight:1.45 }}>{t("cavern_explore_hint")}</div>
              </div>
              <div style={{ color:"var(--muted)" }}>›</div>
            </div>
          </Card>

          {/* DISCLOSURE (Lei §1) — what awakens in the new world. */}
          <div style={{ marginTop:18 }}>
            <ActionBtn variant="ghost" onClick={function () { setShowTeasers(function (v) { return !v; }); }}
                       style={{ width:"100%" }}>
              🔮 {t("explore_newworld_title")} {showTeasers ? "▲" : "▼"}
            </ActionBtn>
            {showTeasers && (
              <div style={{ marginTop:8 }}>
                <div style={{ fontSize:10.5, color:"var(--muted)", textAlign:"center", marginBottom:8, lineHeight:1.5 }}>
                  {t("explore_newworld_intro")}
                </div>
                {((data && data.teasers) || []).map(function (te) {
                  return (
                    <Card key={te.key} style={{ marginBottom:7 }}>
                      <div style={{ fontSize:12, color:"var(--gold3)", fontWeight:600 }}>{te.emoji} {t(te.title_key)}</div>
                      <div style={{ fontSize:10.5, color:"var(--muted)", marginTop:3, lineHeight:1.45 }}>{t(te.body_key)}</div>
                    </Card>
                  );
                })}
                <div style={{ fontSize:10, color:"var(--muted)", textAlign:"center", marginTop:4 }}>
                  🔒 {t("explore_wipe_teaser")}
                </div>
              </div>
            )}
          </div>
        </div>
      );
    }

    // App-root modal — a Hidden-Monster duel (reuses DuelArenaModal + the
    // spare/execute fork). The 5-10× loot + depth advance happen in the settle
    // hook server-side; onResolved refreshes the Explore tab to show the spoils.
    function ExploreDuelModal({ target, onClose, onResolved }) {
      const duelId = target && target.duelId;
      const npc = target && target.npc;
      const [phase, setPhase] = useState("duel");   // duel | moral | result
      // 決 — o MESMO dono da decisao moral do perfil e da emboscada. Antes, as
      // tres copias tinham o mesmo defeito E ja' tinham comecado a divergir:
      // esta era a unica que nao dizia o Caminho cristalizado.
      const { desfecho, won, moral, moralErro, moralBusy, aposDuelo, reverDesfecho, escolher } =
        useDecisaoMoral({ duelId, setFase: setPhase, aoResolver: onResolved, aoVencer: null });

      if (phase === "duel" && duelId) {
        return <DuelArenaModal duelId={duelId} onClose={aposDuelo} playerLang={null} />;
      }

      // ── Onda 5 Fase 3 — Ecos Míticos flavour (reuses the same modal). ──
      const isMythic = !!(npc && npc.is_mythic);
      const isDoppel = !!(npc && npc.is_doppelganger);
      const stance = npc && npc.karma_stance;
      const STANCE_COLOR = { aligned: "var(--jade)", opposed: "var(--red)", neutral: "var(--muted)" };
      const titleNode = (
        <span style={{ fontFamily:"'Cinzel',serif", fontSize:13.5, fontWeight:700,
                       color: isMythic ? "var(--realm-6)" : "var(--gold2)" }}>
          {isMythic
            ? `${(npc && npc.mythic_emoji) || "👁️‍🗨️"} ${npc ? npc.name : t(npc.mythic_name_key)}`
            : `☠️ ${npc ? npc.name : t("explore_hidden_title")}`}
        </span>
      );

      // The Sentido Divino reveal + the karma_stance chip — honest disclosure
      // (Lei §1): the eco is shown for what it is; the doppelgänger reveals "estás TU".
      const mythicHeader = isMythic ? (
        <div style={{ marginBottom:12, padding:"9px 12px", borderRadius:10, lineHeight:1.5,
                      background:"rgba(150,90,220,.10)", border:"1px solid var(--realm-6)" }}>
          <div style={{ fontSize:11.5, color:"var(--realm-6)", fontStyle:"italic" }}>
            {npc && npc.mythic_reveal_key ? t(npc.mythic_reveal_key) : ""}
          </div>
          {stance && (
            <div style={{ marginTop:6, fontSize:10, fontWeight:700, color: STANCE_COLOR[stance] || "var(--muted)" }}>
              {isDoppel ? "🪞" : "☯️"} {t("explore_mythic_stance_" + stance)}
            </div>
          )}
        </div>
      ) : null;

      const titleEarned = (isMythic && won && npc && npc.mythic_title) ? (
        <div style={{ fontSize:11.5, color:"var(--realm-6)", fontWeight:700, marginTop:8 }}>
          🏷️ {t("explore_mythic_title_earned", { title: npc.mythic_title })}
        </div>
      ) : null;

      return (
        <Modal onClose={onClose} title={titleNode}
               accent={isMythic ? "rgba(150,90,220,.55)" : "rgba(220,80,80,.45)"} maxWidth={420} zIndex={70}>
          {phase === "moral" ? (
            <div>
              {mythicHeader}
              <div style={{ textAlign:"center", padding:"10px 6px 14px" }}>
                <div style={{ fontSize:40 }}>{isMythic ? "👁️‍🗨️" : "⚔️"}</div>
                <div style={{ fontFamily:"'Cinzel',serif", fontSize:14, color:"var(--gold3)", marginTop:8 }}>
                  {isMythic ? t("explore_mythic_won") : t("explore_hidden_won")}
                </div>
                {titleEarned}
                <div style={{ fontSize:11, color:"var(--jade)", marginTop:6 }}>🎁 {t("explore_hidden_loot_note")}</div>
                <div style={{ fontSize:11.5, color:"var(--muted)", marginTop:8, lineHeight:1.5 }}>
                  {t("npc_cult_moral_prompt", { name: (npc && npc.name) || "?" })}
                </div>
              </div>
              <MoralErroAviso erro={moralErro} />
              <ActionBtn variant="primary" onClick={function () { escolher("spare"); }} disabled={moralBusy}
                         style={{ width:"100%", marginBottom:8 }}>
                ☯️ {t("npc_cult_spare")}
              </ActionBtn>
              <div style={{ fontSize:10.5, color:"var(--muted)", textAlign:"center", marginBottom:12 }}>{t("npc_cult_spare_hint")}</div>
              <ActionBtn variant="danger" onClick={function () { escolher("execute"); }} disabled={moralBusy}
                         style={{ width:"100%", marginBottom:8 }}>
                👹 {t("npc_cult_execute")}
              </ActionBtn>
              <div style={{ fontSize:10.5, color:"var(--muted)", textAlign:"center" }}>{t("npc_cult_execute_hint")}</div>
            </div>
          ) : (
            <div style={{ textAlign:"center", padding:"18px 10px" }}>
              {mythicHeader}
              <DesfechoRosto desfecho={desfecho}
                             textoVitoria={isMythic ? t("explore_mythic_won") : t("explore_hidden_won")}
                             textoDerrota={t("explore_hidden_lost")}
                             onRever={reverDesfecho} busy={moralBusy} />
              {titleEarned}
              {won && <div style={{ fontSize:11, color:"var(--jade)", marginTop:6 }}>🎁 {t("explore_hidden_loot_note")}</div>}
              {/* 🔴 O `MoralResultado` traz a linha do Caminho CRISTALIZADO que
                  esta copia tinha perdido: os outros dois modais mostravam-na e
                  este nao. E' o que uma copia a' mao faz em silencio. */}
              <MoralResultado moral={moral} />
              <ActionBtn variant="ghost" onClick={onClose} style={{ width:"100%", marginTop:16 }}>
                {t("btn_close")}
              </ActionBtn>
            </div>
          )}
        </Modal>
      );
    }

    // ─── Onda 5 Fase 2 — Caverna Pessoal 洞府 + Matrizes/Formações 阵法 ─────────
    // Drill-in tab (Home card + the 🏯 door inside ExploreTab). The loot of the
    // exploration loop becomes USABLE POWER: craft Formações (timed consumables,
    // materials+stones, NEVER jade — Lei §4), activate on the BODY (PlayerBuff:
    // combat/cultivation/Dao/exploration all read it) or hum it in the CAVERN
    // slot (boosts the capped idle qi / Dao comprehension) — the player's
    // CHOICE, disclosed (Lei §1). The target picker is an early-return view
    // (the ExploreTab fork pattern) — NOT an App-root modal, so no back-stack
    // wiring is needed (back peels the tab to home automatically).

    function _formationFx(f) {
      const label = t(f.effect_key || ("formation_effect_" + f.effect_type));
      if (f.effect_type === "explore_protection") {
        return t("formation_fx_prot", { pct: Math.round((f.effect_value || 0) * 100), label: label });
      }
      return t("formation_fx_mult", { pct: Math.round(((f.effect_value || 1) - 1) * 100), label: label });
    }

    function _fmtDurMin(m) {
      m = m || 0;
      if (m < 60) return m + "min";
      if (m % 60 === 0) return (m / 60) + "h";
      return Math.floor(m / 60) + "h" + (m % 60);
    }

    function _cavernReasonToast(res) {
      const r = (res && res.reason) || "";
      // already_active / slot_occupied carry remaining_ms (+ source) — show
      // WHAT blocks and for HOW LONG (Lei §1), not just "wait".
      function blockedSuffix() {
        const parts = [];
        const ms = (res && res.remaining_ms) || 0;
        if (ms > 0) parts.push("⏳ " + _fmtDurMin(Math.max(1, Math.ceil(ms / 60000))));
        let src = res && res.source;
        if (src) {
          if (String(src).indexOf("formation:") === 0) src = t("formation_name_" + String(src).slice(10));
          parts.push(String(src));
        }
        return parts.length ? " (" + parts.join(" · ") + ")" : "";
      }
      if (r === "already_active") return showToast(t("formation_already_active") + blockedSuffix());
      if (r === "slot_occupied") return showToast(t("cavern_slot_occupied") + blockedSuffix());
      const map = {
        not_enough_stones: t("formation_no_stones", { cost: (res && res.cost_stones) || 0 }),
        not_enough_materials: t("formation_no_materials"),
        realm_too_low: t("formation_realm_low", { realm: (res && res.min_realm) || 0 }),
        not_owned: t("formation_not_owned"),
        formation_not_found: t("formation_not_found"),
        already_established: t("cavern_already"),
        no_cavern: t("cavern_none"),
        nothing_accrued: t("cavern_nothing_accrued"),
        qi_full: t("cavern_qi_full"),
        not_cavern_type: t("cavern_not_cavern_type"),
      };
      showToast(map[r] || t("err_engine") || r || "engine");
    }

    function CavernTab({ player, setTab, onPlayerRefresh }) {
      const [reload, setReload] = useState(0);
      const cavern = useApi("world/cavern", null, [reload]);
      const pouch = useApi("world/formations", null, [reload]);
      const [busy, setBusy] = useState(false);
      const [banner, setBanner] = useState(null);   // {tone, text}
      const [pick, setPick] = useState(null);       // formation → target picker view

      function refresh() { setReload(function (x) { return x + 1; }); }

      async function write(endpoint, body, okText) {
        if (busy) return null;
        setBusy(true); haptic("select");
        try {
          const res = await api(endpoint, body || {});
          if (!res || !res.ok) { haptic("error"); _cavernReasonToast(res || {}); return res; }
          haptic("success");
          if (okText) setBanner({ tone: "good", text: okText });
          if (onPlayerRefresh) onPlayerRefresh();
          return res;
        } catch (e) { haptic("error"); showToast(t("err_engine") || "engine"); return null; }
        finally { setBusy(false); refresh(); }
      }

      async function claim() {
        const res = await write("world/cavern_claim", {}, null);
        if (res && res.ok) {
          let text = "🌀 " + t("cavern_claimed", { qi: Math.floor(res.claimed_qi || 0) });
          if (res.truncated) text += " · ⚠️ " + t("cavern_claim_truncated");
          if (res.dao_fragment && res.dao_fragment.law_name) {
            text += " · ☯️ " + t("cavern_dao_fragment", { law: res.dao_fragment.law_name });
          }
          setBanner({ tone: "good", text: text });
        }
      }

      async function activate(f, target) {
        setPick(null);
        const res = await write("world/formation_activate", { formation_id: f.id, target: target }, null);
        if (res && res.ok) {
          let text = target === "cavern" ? ("🔯 " + t("cavern_formation_set"))
            : ("✨ " + t("formation_activated_body", { duration: _fmtDurMin(res.duration_minutes || f.duration_minutes) }));
          // Slot mutations settle the pending accrual first — disclose it.
          if (res.settled_qi > 0) text += " · 🌀 +" + Math.floor(res.settled_qi);
          // 印记 Marca do Traçado — antes→depois SEMPRE (Lei §10), o degrau novo
          // celebrado, e o título dito. Só chega com `marca_do_tracado` ON.
          const mk = res.marca;
          if (mk) {
            text += "\n🔯 " + t("marca_progress_delta", { before: mk.before, after: mk.after });
            if (mk.tier_up) text += "\n" + t("marca_up_" + mk.tier_up, { name: mk.tier_name || "" });
            if (mk.title_granted) text += "\n🏆 " + t("marca_title_granted", { title: mk.title_granted });
          }
          setBanner({ tone: "good", text: text });
        }
        return res;
      }

      const cv = cavern.data || {};
      const fl = (pouch.data && pouch.data.formations) || [];

      const bannerNode = banner ? (
        <div style={{
          padding:"9px 12px", borderRadius:10, marginBottom:12, fontSize:12, lineHeight:1.5,
          background: banner.tone === "bad" ? "rgba(220,80,80,.10)" : "rgba(80,200,140,.10)",
          border: "1px solid " + (banner.tone === "bad" ? "rgba(220,80,80,.28)" : "rgba(80,200,140,.28)"),
          color: "var(--text)",
        }}>{banner.text}</div>
      ) : null;

      // ── Target picker (body vs cavern) — early-return view, fork pattern ──
      if (pick) {
        const cavernOk = pick.cavern_compatible && cv.has_cavern;
        return (
          <div style={{ padding:"4px 2px 80px" }}>
            <CardTitle left={"🔯 " + (pick.emoji || "") + " " + t(pick.name_key)} />
            <Card style={{ marginBottom:12 }}>
              <div style={{ fontSize:12, color:"var(--text)", lineHeight:1.55 }}>{t(pick.desc_key)}</div>
              <div style={{ fontSize:11, color:"var(--gold3)", marginTop:6 }}>
                {_formationFx(pick)} · ⏱️ {_fmtDurMin(pick.duration_minutes)}
              </div>
              {/* 印记 — o Traço estica a duração NO CORPO. A caverna é a OUTRA
                  escolha e não recebe o bônus: sem dizer isto, o número acima
                  ficaria por cima do botão da caverna a prometer 15% que ela
                  não dá (display-lie no ramo errado). A key só chega quando o
                  Traço esticou mesmo alguma coisa. */}
              {pick.base_duration_minutes > 0 && (
                <div style={{ fontSize:10, color:"var(--muted)", marginTop:4, lineHeight:1.45 }}>
                  🏯 {t("marca_cavern_base", { duration: _fmtDurMin(pick.base_duration_minutes) })}
                </div>
              )}
            </Card>
            <div style={{ fontSize:11, color:"var(--muted)", margin:"4px 2px 8px" }}>{t("formation_pick_target")}</div>
            <ActionBtn variant="primary" disabled={busy}
                       onClick={function () { activate(pick, "body"); }}
                       style={{ width:"100%", marginBottom:6 }}>
              🧘 {t("formation_target_body")}
            </ActionBtn>
            <div style={{ fontSize:10, color:"var(--muted)", textAlign:"center", marginBottom:10 }}>
              {t("formation_target_body_hint")}
            </div>
            {pick.cavern_compatible && (
              <div>
                <ActionBtn variant="ghost" disabled={busy || !cavernOk}
                           onClick={function () { if (cavernOk) activate(pick, "cavern"); }}
                           style={{ width:"100%", marginBottom:6 }}>
                  🏯 {t("formation_target_cavern")}
                </ActionBtn>
                <div style={{ fontSize:10, color:"var(--muted)", textAlign:"center", marginBottom:10 }}>
                  {/* While world/cavern is (re)loading, don't flash "no cavern"
                      at a player who has one (review: transient mislead). */}
                  {cavernOk ? t("formation_target_cavern_hint")
                    : cavern.loading ? "…"
                    : cavern.error ? t("err_engine")
                    : t("cavern_none")}
                </div>
              </div>
            )}
            <ActionBtn variant="ghost" onClick={function () { setPick(null); }} style={{ width:"100%", marginTop:4 }}>
              {t("explore_back")}
            </ActionBtn>
          </div>
        );
      }

      const idlePct = cv.cap_qi > 0 ? Math.min(100, Math.round(((cv.accrued_qi || 0) / cv.cap_qi) * 100)) : 0;

      return (
        <div style={{ padding:"4px 2px 80px" }}>
          <div style={{ textAlign:"center", marginBottom:10 }}>
            <div style={{ fontFamily:"'Cinzel',serif", fontSize:16, color:"var(--gold2)" }}>🏯 {t("cavern_title")}</div>
            <div style={{ fontSize:11, color:"var(--muted)", marginTop:4, lineHeight:1.5 }}>{t("cavern_intro")}</div>
          </div>

          {bannerNode}

          {cavern.loading ? (
            <ListSkeleton rows={2} />
          ) : cavern.error ? (
            <ErrBanner msg={cavern.error} />
          ) : !cv.has_cavern ? (
            /* ── Establish door ── */
            <Card style={{ marginBottom:14 }}>
              <div style={{ fontSize:12.5, color:"var(--text)", fontWeight:600 }}>⛏️ {t("cavern_none_yet")}</div>
              <div style={{ fontSize:11, color:"var(--muted)", marginTop:6, lineHeight:1.5 }}>
                {t("cavern_rate_preview", { rate: Math.floor(cv.rate_per_hour_preview || 0), cap: Math.floor(cv.cap_hours || 0) })}
              </div>
              <div style={{ fontSize:11, color:"var(--gold3)", marginTop:8 }}>
                🪨 {fmtNum(cv.establish_cost_stones || 0)}
              </div>
              {(cv.establish_materials || []).map(function (m) {
                return (
                  <div key={m.kind + m.id} style={{ fontSize:10.5, marginTop:3,
                       color: m.has_enough ? "var(--muted)" : "var(--red)" }}>
                    {m.name} ×{m.qty} <span style={{ opacity:.8 }}>({m.owned})</span>
                  </div>
                );
              })}
              <ActionBtn variant="primary" disabled={busy || !cv.can_establish}
                         onClick={async function () {
                           const res = await write("world/cavern_establish", {}, null);
                           if (res && res.ok) setBanner({ tone:"good", text: "⛏️ " + t("cavern_established", { stones: res.cost_stones || 0 }) });
                         }}
                         style={{ width:"100%", marginTop:10 }}>
                ⛏️ {t("cavern_establish_btn")}
              </ActionBtn>
            </Card>
          ) : (
            /* ── The cavern: idle bar + claim + the Formação slot ── */
            <Card style={{ marginBottom:14 }}>
              <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center" }}>
                <div style={{ fontSize:12.5, color:"var(--text)", fontWeight:600 }}>
                  🏯 {t("cavern_status_line", { continent: cv.cavern_continent_name || cv.cavern_continent || "?", rate: Math.floor(cv.rate_per_hour || 0) })}
                </div>
                <Badge>Σ {fmtNum(cv.total_qi_claimed || 0)}</Badge>
              </div>
              <div style={{ marginTop:10 }}>
                <div style={{ display:"flex", justifyContent:"space-between", fontSize:10.5, color:"var(--muted)", marginBottom:4 }}>
                  <span>🌀 {t("cavern_idle_line", { accrued: Math.floor(cv.accrued_qi || 0), cap: Math.floor(cv.cap_qi || 0) })}</span>
                  <span>{cv.at_cap ? "⏸️ " + t("cavern_at_cap") : (Math.round((cv.accrued_hours || 0) * 10) / 10) + "h"}</span>
                </div>
                <div style={{ height:8, borderRadius:5, background:"rgba(255,255,255,.07)", overflow:"hidden" }}>
                  <div style={{ height:"100%", width: idlePct + "%", borderRadius:5,
                                background:"linear-gradient(90deg, var(--jade), var(--gold3))" }} />
                </div>
              </div>
              <ActionBtn variant="primary" disabled={busy || !(cv.claimable_qi > 0)}
                         onClick={claim} style={{ width:"100%", marginTop:10 }}>
                🌀 {t("cavern_claim_btn", { qi: Math.floor(cv.claimable_qi || 0) })}
              </ActionBtn>
              {cv.qi_full && (
                <div style={{ fontSize:10, color:"var(--gold3)", textAlign:"center", marginTop:5 }}>
                  ⚠️ {t("cavern_qi_full")}
                </div>
              )}

              {/* The Formação slot */}
              <div style={{ marginTop:14, paddingTop:10, borderTop:"1px solid rgba(255,255,255,.08)" }}>
                <div style={{ fontSize:11, color:"var(--muted)", marginBottom:6 }}>🔯 {t("cavern_slot_title")}</div>
                {cv.slot ? (
                  <div>
                    <div style={{ fontSize:12, color:"var(--gold3)", fontWeight:600 }}>
                      {cv.slot.emoji} {t(cv.slot.name_key)}
                      {cv.slot.expired && <span style={{ color:"var(--red)", marginLeft:6, fontSize:10.5 }}>({t("cavern_slot_expired")})</span>}
                    </div>
                    <div style={{ fontSize:10.5, color:"var(--muted)", marginTop:3 }}>
                      {_formationFx(cv.slot)}
                      {!cv.slot.expired && " · ⏳ " + _fmtDurMin(Math.max(1, Math.ceil((cv.slot.remaining_ms || 0) / 60000)))}
                      {cv.slot.dao_chance != null && " · ☯️ " + Math.round(cv.slot.dao_chance * 100) + "%"}
                    </div>
                    <ActionBtn variant="ghost" disabled={busy}
                               onClick={async function () {
                                 const res = await write("world/cavern_clear_formation", {}, null);
                                 if (res && res.ok) {
                                   let text = "🧹 " + t("cavern_cleared");
                                   if (res.settled_qi > 0) text += " · 🌀 +" + Math.floor(res.settled_qi);
                                   setBanner({ tone: "good", text: text });
                                 }
                               }}
                               style={{ width:"100%", marginTop:8 }}>
                      🧹 {t("cavern_clear_btn")}
                    </ActionBtn>
                  </div>
                ) : (
                  <div style={{ fontSize:10.5, color:"var(--muted)" }}>{t("cavern_slot_empty")}</div>
                )}
              </div>
            </Card>
          )}

          {/* ── Matrizes/Formações 阵法 — the pouch + the craft catalog ── */}
          <CardTitle left={"🔯 " + t("formations_title")}
                     right={<Badge>🪨 {fmtNum((pouch.data && pouch.data.stones) || 0)}</Badge>} />
          <div style={{ fontSize:10.5, color:"var(--muted)", margin:"0 2px 10px", lineHeight:1.5 }}>
            {t("formations_intro")}
          </div>
          {pouch.loading ? (
            <ListSkeleton rows={4} />
          ) : pouch.error ? (
            <ErrBanner msg={pouch.error} />
          ) : (
            fl.map(function (f) {
              return (
                <Card key={f.id} style={{ marginBottom:8, opacity: f.realm_ok ? 1 : .55 }}>
                  <div style={{ display:"flex", alignItems:"center", gap:10 }}>
                    <div style={{ fontSize:22 }}>{f.emoji}</div>
                    <div style={{ flex:1, minWidth:0 }}>
                      <div style={{ fontSize:12.5, color:"var(--text)", fontWeight:600 }}>
                        {t(f.name_key)}
                        <span style={{ marginLeft:6, fontSize:10, color:"var(--muted)" }}>T{f.tier}</span>
                        {f.cavern_compatible && <span style={{ marginLeft:5, fontSize:10 }}>🏯</span>}
                        {f.owned > 0 && <span style={{ marginLeft:6, fontSize:10.5, color:"var(--jade)" }}>×{f.owned}</span>}
                        {f.effect_active && <span style={{ marginLeft:6, fontSize:10 }}>✨</span>}
                      </div>
                      <div style={{ fontSize:10.5, color:"var(--gold3)", marginTop:3 }}>
                        {_formationFx(f)} · ⏱️ {_fmtDurMin(f.duration_minutes)}
                      </div>
                      <div style={{ fontSize:10, color:"var(--muted)", marginTop:3, lineHeight:1.45 }}>
                        🪨 {fmtNum(f.cost_stones || 0)}
                        {/* 印记 degrau 2 — o preço cheio riscado ao lado do
                            descontado: o desconto tem de ser VISTO, senão é o
                            mesmo que não existir (Lei §10). */}
                        {f.cost_stones_full > 0 && (
                          <span style={{ marginLeft:4, textDecoration:"line-through", opacity:.55 }}>
                            {fmtNum(f.cost_stones_full)}
                          </span>
                        )}
                        {(f.materials || []).map(function (m) {
                          return (
                            <span key={m.kind + m.id} style={{ marginLeft:6, color: m.has_enough ? "inherit" : "var(--red)" }}>
                              {m.name} ×{m.qty}
                            </span>
                          );
                        })}
                        {!f.realm_ok && <span style={{ marginLeft:6 }}>🔒 {t("formation_realm_chip", { realm: f.min_realm })}</span>}
                      </div>
                      {/* 印记 Marca do Traçado — a maestria DESTA formação, com
                          o contador visível desde a 1ª ativação e a barra do
                          degrau seguinte. Server-resolved; só chega com a flag
                          `marca_do_tracado` ON e depois de 1+ ativação. */}
                      {f.marca && (
                        <div style={{ marginTop:5, padding:"5px 7px", borderRadius:7,
                                      background:"rgba(var(--gold2-rgb),.07)",
                                      border:"1px solid rgba(var(--gold2-rgb),.22)" }}>
                          <div style={{ fontSize:10, color:"var(--gold2)", lineHeight:1.45 }}>
                            🔯 {f.marca.line}
                          </div>
                          {f.marca.next_at > 0 && (
                            <div style={{ height:3, borderRadius:99, background:"rgba(0,0,0,.4)",
                                          overflow:"hidden", marginTop:4 }}>
                              <div style={{ height:"100%", borderRadius:99, background:"var(--gold)",
                                            width: Math.min(100, (f.marca.uses / f.marca.next_at) * 100) + "%" }} />
                            </div>
                          )}
                          {f.marca.tier > 0 && (
                            <div style={{ fontSize:9.5, color:"var(--muted)", marginTop:4, lineHeight:1.45 }}>
                              {f.marca.duration_bonus_pct > 0 && (
                                <span>⏱️ +{f.marca.duration_bonus_pct}%</span>
                              )}
                              {f.marca.stone_discount_pct > 0 && (
                                <span style={{ marginLeft:6 }}>🪨 −{f.marca.stone_discount_pct}% · 🌿 −{f.marca.material_cut}</span>
                              )}
                            </div>
                          )}
                        </div>
                      )}
                    </div>
                  </div>
                  <div style={{ display:"flex", gap:8, marginTop:8 }}>
                    <ActionBtn variant="ghost" disabled={busy || !f.craftable}
                               onClick={async function () {
                                 const r = await write("world/formation_craft", { formation_id: f.id }, "⚒️ " + t("formation_crafted"));
                                 // 印记 — o que o Sulco poupou, dito (Lei §10).
                                 if (r && r.ok && r.marca_saved_stones > 0) {
                                   setBanner({ tone:"good", text: "⚒️ " + t("formation_crafted")
                                     + " · " + t("marca_craft_saved", { stones: fmtNum(r.marca_saved_stones) }) });
                                 }
                               }}
                               style={{ flex:1 }}>
                      ⚒️ {t("formation_craft_btn")}
                    </ActionBtn>
                    <ActionBtn variant="primary" disabled={busy || !(f.owned > 0) || !f.realm_ok}
                               onClick={function () { haptic("select"); setPick(f); }}
                               style={{ flex:1 }}>
                      ✨ {t("formation_activate_btn")}
                    </ActionBtn>
                  </div>
                </Card>
              );
            })
          )}

          {/* Sprint 4 — Horta 灵田 (Campo Espiritual), na Caverna (洞府): o jardim
              espiritual idle vive no espaço pessoal, ao lado das Formações. Inclui as
              4 vias do Corpo (Horta/Caça/Ambiental/Combate). Gated por `cultivo_corpo_r0`
              (main OFF → nem monta); esconde-se em R7+ (is_apex). */}
          {featureEnabled("cultivo_corpo_r0") && <HortaCard onPlayerRefresh={onPlayerRefresh} />}
        </div>
      );
    }

    // ─── MA-47 Tutorial / Onboarding (Sprint v14.13) ─────────────────────────
    // 5-slide welcome modal. Auto-opens on first launch (player.tutorial_seen
    // === false). Persists via settings/update {tutorial_seen:true} on dismiss.
    // Re-trigger via Settings → "Mostrar tutorial novamente" button.
    var TUTORIAL_SLIDES = [
      { emoji:"☯️", title_key:"tut_slide_1_title", body_key:"tut_slide_1_body" },
      { emoji:"🧘", title_key:"tut_slide_2_title", body_key:"tut_slide_2_body" },
      { emoji:"🏯", title_key:"tut_slide_3_title", body_key:"tut_slide_3_body" },
      { emoji:"⚡", title_key:"tut_slide_4_title", body_key:"tut_slide_4_body" },
      { emoji:"🏠", title_key:"tut_slide_5_title", body_key:"tut_slide_5_body" },
    ];

    function TutorialModal({ onDismiss }) {
      const [idx, setIdx] = useState(0);
      const [busy, setBusy] = useState(false);
      const slide = TUTORIAL_SLIDES[idx];
      const isLast = idx === TUTORIAL_SLIDES.length - 1;

      async function persistSeen() {
        if (busy) return;
        setBusy(true);
        try {
          await api("settings/update", { tutorial_seen: true });
        } catch (e) {
          // Best-effort — tutorial UX is not blocking even if persistence
          // fails (next launch would just show it again).
          console.warn("tutorial_seen persist failed", e);
        }
        setBusy(false);
        onDismiss && onDismiss();
      }

      function next() {
        haptic("select");
        if (isLast) {
          persistSeen();
        } else {
          setIdx(idx + 1);
        }
      }

      function skip() {
        haptic("light");
        persistSeen();
      }

      const footer = (
        <div style={{ display:"flex", gap:8, width:"100%" }}>
          <ActionBtn variant="ghost" onClick={skip} disabled={busy}
                     style={{ flex:1 }}>
            {t("tut_btn_skip")}
          </ActionBtn>
          <ActionBtn variant="primary" onClick={next} disabled={busy}
                     style={{ flex:1.4 }}>
            {busy ? <DotSpinner /> : isLast ? t("tut_btn_finish") : t("tut_btn_next")}
          </ActionBtn>
        </div>
      );

      return (
        <Modal open={true}
               onClose={skip}
               title={`🌟 ${t("tut_modal_title")}`}
               accent="rgba(var(--gold2-rgb),.55)"
               maxWidth={400} zIndex={85}
               footer={footer}>
          <div style={{ textAlign:"center", padding:"18px 8px 4px" }}>
            <div style={{ fontSize:64, marginBottom:14,
                          animation:"alch-pop 360ms ease-out" }}>
              {slide.emoji}
            </div>
            <div style={{ fontFamily:"'Cinzel',serif", fontSize:15,
                          color:"var(--gold3)", letterSpacing:.5,
                          marginBottom:10 }}>
              {t(slide.title_key)}
            </div>
            <div style={{ fontSize:12.5, color:"var(--muted)", lineHeight:1.55,
                          padding:"0 6px" }}>
              {t(slide.body_key)}
            </div>
          </div>
          {/* Pagination dots */}
          <div style={{ display:"flex", justifyContent:"center", gap:6,
                        marginTop:18 }}>
            {TUTORIAL_SLIDES.map((_, i) => (
              <span key={i} style={{
                width: i === idx ? 18 : 7, height:7, borderRadius:99,
                background: i === idx ? "var(--gold3)"
                          : i < idx ? "rgba(var(--gold2-rgb),.45)"
                          : "rgba(var(--glow-rgb),.35)",
                transition:"width .2s ease",
              }} />
            ))}
          </div>
          <div style={{ marginTop:8, fontSize:10, color:"var(--muted)",
                        textAlign:"center" }}>
            {idx + 1} / {TUTORIAL_SLIDES.length}
          </div>
        </Modal>
      );
    }

    // SettingsTab augmentation — injects the "show tutorial again" row inside
    // the about section. Defined here (not modifying SettingsAboutSection)
    // because it needs an action callback that pops back into the App's
    // tutorial modal state.
    function SettingsTutorialReplaySection({ onReplay }) {
      const [busy, setBusy] = useState(false);
      async function doReplay() {
        if (busy) return;
        setBusy(true);
        try {
          await api("settings/update", { tutorial_seen: false });
          haptic("success");
          showToast(t("tut_replay_toast"));
          onReplay && onReplay();
        } catch (e) {
          haptic("error");
          showToast(e.message || "Error", "err");
        }
        setBusy(false);
      }
      return (
        <Card>
          <CardTitle left={t("settings_section_tutorial")} />
          <div style={{ fontSize:11, color:"var(--muted)", lineHeight:1.5,
                        marginBottom:8 }}>
            {t("settings_tutorial_hint")}
          </div>
          <ActionBtn variant="ghost" disabled={busy}
                     onClick={doReplay} style={{ width:"100%" }}>
            {busy ? <DotSpinner /> : `🌟 ${t("settings_tutorial_replay_btn")}`}
          </ActionBtn>
        </Card>
      );
    }

    // 減 P7 — «Mostrar as explicações de novo». O que estava recolhido volta a
    // "apto" NO SERVIDOR (`core/explicacoes.repor`): a frase reaparece em toda
    // plataforma e «Já percebi» continua oferecido — agir não se desaprende.
    // ⚠️ O aviso de sucesso só sai com `ok` da resposta; uma recusa diz que nada
    // mudou, em vez de fingir que mudou.
    function SettingsExplicacoesSection({ onPlayerRefresh }) {
      const [busy, setBusy] = useState(false);
      async function repor() {
        if (busy) return;
        setBusy(true);
        try {
          const r = await api("settings/update", { explicacoes_repor: true });
          if (r && r.ok) {
            haptic("success");
            showToast(t("settings_explica_ok"));
            if (onPlayerRefresh) onPlayerRefresh();
          } else {
            haptic("error");
            showToast(t("settings_explica_erro"), "err");
          }
        } catch (e) {
          haptic("error");
          showToast(t("settings_explica_erro"), "err");
        }
        setBusy(false);
      }
      return (
        <Card>
          <CardTitle left={t("settings_explica_titulo")} />
          <div style={{ fontSize:11, color:"var(--muted)", lineHeight:1.5,
                        marginBottom:8 }}>
            {t("settings_explica_hint")}
          </div>
          <ActionBtn variant="ghost" disabled={busy}
                     onClick={repor} style={{ width:"100%" }}>
            {busy ? <DotSpinner /> : t("settings_explica_btn")}
          </ActionBtn>
        </Card>
      );
    }

    // ═══ UI v2 "O Pergaminho Vivo" — Onda R2: HubEuScreen (o Orbe da Alma) ═══
    // Gated ui_v2 (flag per-world; graduada no R6). A primeira tela PRÓPRIA
    // do v2: o Orbe da Alma como protagonista — escala/aura/cor derivam do
    // reino + Poder de Combate DO PAYLOAD (a Alma; nunca recalcula — regra da
    // Fonte Única). Leis de Ferro do owner: MENOS informação (orbe + 1 número +
    // 3 barras finas), MAIS interação (orbe tocável → Perfil; grade de caminhos
    // do domínio EU — nenhum destino perdido, matriz REDESIGN_MASTER §5).
    // ═══ 門 P6 — AS PORTAS DO EU, num dono só ═══════════════════════════════
    // 🔴 MEDIDO a servir e a OLHAR (2026-09-27): a app ARRANCA em `home`, que
    // desenha a MESMA chegada — e a maçaneta de 23/09 só existia na do
    // `hub_eu_screen`. O jogador abria o jogo e o primeiro ecrã não dizia uma
    // palavra sobre o Corpo, a Celestial ou o Parceiro: a maçaneta em 1 de 2
    // sítios, a Lei F-7 dentro do lote que a nomeou. E a lista dos sete vivia
    // DENTRO do `HubEuScreen`, portanto o `home` não tinha como a nomear sem
    // uma segunda cópia. Agora é esta — o selector, a maçaneta do hub e a do
    // `home` leem-na, e a regra do marco (`portasDoHub`) aplica-se uma vez.
    // `tab` é a chave pela qual a porta se encontra no `nav_gates`; as
    // Conquistas são uma janela e não têm gate.
    var EU_PORTAS = [
      { ico:"☯️", key:"tab_cultivation",    tab:"cultivation" },
      { ico:"💪", key:"tab_body_tempering", tab:"body_tempering" },
      { ico:"🌠", key:"tab_celestial",      tab:"celestial" },
      { ico:"💞", key:"tab_partner",        tab:"partner" },
      { ico:"🏆", key:"home_card_achievements" },
      { ico:"💎", key:"tab_shop",           tab:"shop" },
      { ico:"⚙️", key:"tab_settings",       tab:"settings" },
    ];

    // → `{ visiveis, distantes, porta, nomes }`. `nomes` é o que a maçaneta
    // escreve: as portas ABERTAS primeiro e as trancadas no fim — o "mais N"
    // conta-as, mas nenhuma aparece nos três nomes à vista como se abrisse (a
    // opção (c), em texto).
    function euPortasVisiveis(player, lista) {
      const ph = portasDoHub(player, lista.filter(p => p.tab).map(p => p.tab), null);
      const visiveis = lista.filter(p => !p.tab || ph.lista.some(x => x.key === p.tab));
      const porta = (p) => (p.tab ? portaDe(player, p.tab) : { estado: "aberta" });
      const nomes = visiveis.filter(p => porta(p).estado === "aberta")
        .concat(visiveis.filter(p => porta(p).estado !== "aberta"))
        .map(p => t(p.key));
      return { visiveis: visiveis, distantes: ph.distantes, porta: porta, nomes: nomes };
    }

    function HubEuScreen({ player, setTab, onOpenProfile, onOpenAchievements,
                           notifCount, onSino, onLoja, seletorAberto, onAbrirSeletor,
                           onFecharSeletor, onPorta, onPlayerRefresh }) {
      // Onda R4 (decisão da home): Conquistas ganhou entrada v2 PRÓPRIA aqui
      // (o modal só abria do card da HomeTab — órfão real a ≤2 taps se a home
      // fosse rebaixada sem isto). O modal vive no App ROOT (review R4: estado
      // local num LANDING deixava o back nativo fora — fechava o webapp em vez
      // do modal; padrão ProfileModal). O da HomeTab fica local (v1, OFF-intacto).
      // R5 (celebração): quando o Poder SOBE (poll de 30s / refresh pós-avanço),
      // o Orbe pulsa 1× (orb-burst substitui o orb-breathe ~0.9s — mesmas
      // propriedades, combinar conflitaria). Hooks ANTES do early-return.
      // Review R5: contador (não boolean) + reset em effect PRÓPRIO keyed no
      // burst — um timer no effect de [power] era cancelado por QUALQUER
      // mudança (queda/null) sem re-agendar → burst preso p/ sempre (orbe
      // parava de respirar); e 2ª subida <1s não re-disparava (string CSS
      // idêntica). O contador vira `key` do orbe → remount reinicia do frame 0.
      const _wideHub = typeof useWideShell === "function" ? useWideShell() : false;
      // ⚠️ Pelo dono único do portão (`chegadaDona`, ui.js) e não com uma
      // condição nova: a guarda do §19 conta os leitores da chave-mestra.
      const chegadaDonaDoHub = () =>
        typeof chegadaDona === "function" && chegadaDona("hub_eu_screen")
        && typeof Chegada === "function";
      const [burstSeq, setBurstSeq] = useState(0);
      const _prevPower = useRef(null);
      // Poder headline: o agregado (== header) quando progressao_visivel ON; senão raw.
      const power = !player ? null
        : (typeof featureEnabled === "function" && featureEnabled("progressao_visivel")
           && player.display_combat_power != null)
          ? player.display_combat_power : (player.battle_power || 0);
      useEffect(() => {
        if (power == null) return;
        if (_prevPower.current != null && power > _prevPower.current) setBurstSeq(s => s + 1);
        _prevPower.current = power;
      }, [power]);
      useEffect(() => {
        if (!burstSeq) return;
        const tm = setTimeout(() => setBurstSeq(0), 1000);
        return () => clearTimeout(tm);
      }, [burstSeq]);
      if (!player) return null;
      const realm = Math.min(player.realm || 0, 10);
      // R5: hex literal — o glow do Orbe concatena alpha (`${cssHex(rc)}88`/`${cssHex(rc)}33`);
      // com var() a aura NUNCA renderizou (nota do review R3, varrida agora).
      const rc = realmHex(realm);
      // O orbe CRESCE com o reino (padrão YNXY §2.2: poder legível sem ler stats).
      const orbSize = Math.min(150, 82 + realm * 6);
      const _mx = (typeof player.max_hp === "number" && player.max_hp > 0) ? player.max_hp : null;
      const _cur = _mx == null ? null
        : (player.current_hp == null ? _mx : Math.max(0, Math.min(player.current_hp, _mx)));
      // 門 P6 — os sete destinos vêm do dono único `EU_PORTAS` (acima do
      // componente); aqui só se lhes junta o GESTO de cada um.
      const paths = EU_PORTAS.map(p => Object.assign({}, p, {
        go: p.tab ? () => setTab(p.tab) : () => onOpenAchievements && onOpenAchievements(),
      })).concat([
        // "Início" REBAIXADO ao fim da grade (decisão da home, Onda R4): todos
        // os cards do dashboard antigo já têm entrada v2 própria (matriz §5) —
        // a tab fica viva como legado (deep-links/notifs apontam lá; saída
        // avaliada no launch). NUNCA remover a rota (notif router usa target_tab).
        { ico:"🏠", key:"tab_home",           go:() => setTab("home") },
      ]);
      // ═══ 至 A CHEGADA É O LANDING DO HUB EU ═══════════════════════════════
      //
      // 🔴 O defeito que isto conserta: a chegada tinha sido construída em
      // `home`, e com a `ui_v2` ligada — o que o owner corre — o hub Eu abre em
      // `hub_eu_screen`. Ela existia, estava certa, e **a navegação dele nunca
      // lhe passava**. 6ª vez nesta casa que "existe" não foi "chega".
      //
      // A decisão já estava escrita e eu é que não a tinha lido até ao fim:
      //   [016] §1 — *"a chegada vive no hub Eu; não acrescentar uma sexta aba
      //               'Início'"*
      //   [017] §3 — *"Cultivo, Corpo, Celestial, Parceiro e Configurações
      //               vivem (…) no selector do hub Eu no telemóvel. Tocar
      //               novamente em **Eu**, já activo, abre esse selector;
      //               fechá-lo devolve a cena."*
      //
      // ⚠️ E NÃO é a cena POR CIMA das sete portas: isso recriava a pilha
      // "cena + lista de portas" que o owner mandou matar. As portas só
      // existem quando o selector está aberto.
      // 至 SETE destinos, nao oito. Astra, §0: *"Cultivo, Corpo, Celestial,
      // Parceiro, Conquistas, Loja, Configuracoes. **Retirar Inicio dessa
      // lista**; preservar `home` como entrada de compatibilidade para os
      // caminhos existentes."*
      // ⚠️ O `home` NAO desaparece do codigo — continua a ser uma aba valida e
      // a renderizar a mesma chegada. So' deixa de ser uma PORTA aqui: com a
      // chegada a SER este ecra, "Inicio" levaria o jogador a um sitio
      // identico aquele onde ja' esta'.
      const pathsSeletor = paths.filter(p => p.key !== "tab_home"
                                          && p.key !== "home_card_home");
      // 門 P6 — A NAVEGAÇÃO ACOMPANHA A PROGRESSÃO. O selector e a maçaneta
      // mostram o mesmo conjunto (uma lista, um dono): as abertas, e das
      // trancadas SÓ o próximo marco — com o selo e o número. O resto vai para
      // a consulta «Desbloqueios». Com a onda OFF tudo é `aberta`.
      const eu = euPortasVisiveis(player, pathsSeletor);
      const phEu = { distantes: eu.distantes };
      const pathsVisiveis = eu.visiveis;
      const portaDoPath = eu.porta;
      const nomesMacaneta = eu.nomes;
      if (chegadaDonaDoHub()) {
        return (
          <div style={{ display:"grid", gridTemplateColumns:"minmax(0, 1fr)", gap:0, animation:"fade-up .25s ease" }}>
            <Chegada player={player} setTab={setTab} wide={_wideHub}
                     notifCount={notifCount} onSino={onSino}
                     onLoja={onLoja} onPerfil={onOpenProfile}
                     /* 至 A MACANETA DECLARADA (owner, 2026-09-23). Os nomes sao
                        os do MESMO `pathsSeletor` que a sobreposicao abre — uma
                        lista, um dono (Lei 0 §2). Se um destino entrar ou sair,
                        a linha segue-o sozinha. */
                     portas={nomesMacaneta}
                     onPortas={onAbrirSeletor}
                     onPlayerRefresh={onPlayerRefresh} />
            {/* 至 O SELECTOR E' UMA SOBREPOSICAO, e nao uma seccao em fluxo.
                Astra, §0: *"o selector e' uma sobreposicao com titulo, fechar
                explicito e conteudo proprio; **nao aumenta a altura da
                chegada**. A cena permanece montada por baixo, sem receber
                interaccao."*
                ⚠️ A minha 1a versao punha-o em fluxo POR BAIXO da cena — que e'
                exactamente a pilha "cena + lista de portas" que o owner mandou
                matar, so' que escondida atras de um gesto.
                ⚠️ E ao passar pelo `Modal` ele ganha o Escape de graca (o
                `useEscapeFecha` das 74 janelas) e o portal para o `body`. */}
            {seletorAberto && (
              <Modal open onClose={onFecharSeletor} title={t("hub_eu")}
                     maxWidth={360} zIndex={70} compact>
                <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:8 }}>
                  {pathsVisiveis.map(p => {
                    const pp = portaDoPath(p);
                    // 門 P6 — trancada: continua no SEU lugar da grelha (a
                    // posição dos comandos não muda), apagada, com o selo e o
                    // reino; o toque fecha o selector e abre a consulta.
                    if (pp.estado !== "aberta") {
                      return (
                        <button key={p.key} type="button"
                                aria-label={portaAria(t(p.key), pp)}
                                onClick={() => { haptic("select"); onFecharSeletor && onFecharSeletor();
                                                 if (onPorta) onPorta("hub_eu", p.tab); else p.go(); }}
                                style={{ display:"flex", flexDirection:"column", alignItems:"flex-start",
                                         justifyContent:"center", gap:5, minHeight:52,
                                         padding:"6px 12px", textAlign:"left", cursor:"pointer",
                                         background:"transparent",
                                         border: portaTom().trancada, borderRadius:10,
                                         color:"var(--text)", font:"inherit", fontSize:13 }}>
                          <span style={{ display:"flex", alignItems:"center", gap:9, minWidth:0 }}>
                            <span style={{ fontSize:18, flexShrink:0 }}>{p.ico}</span>
                            <span style={{ minWidth:0 }}>{t(p.key)}</span>
                          </span>
                          <PortaSelo porta={pp} />
                        </button>
                      );
                    }
                    return (
                    <button key={p.key} type="button"
                            onClick={() => { haptic("select"); onFecharSeletor && onFecharSeletor(); p.go(); }}
                            style={{ display:"flex", alignItems:"center", gap:9, minHeight:52,
                                     padding:"0 12px", textAlign:"left", cursor:"pointer",
                                     background:"rgba(var(--surface-rgb),.55)",
                                     border:"1px solid var(--border)", borderRadius:10,
                                     color:"var(--text)", font:"inherit", fontSize:13 }}>
                      <span style={{ fontSize:18, flexShrink:0 }}>{p.ico}</span>
                      <span style={{ minWidth:0 }}>{t(p.key)}</span>
                    </button>
                    );
                  })}
                  {phEu.distantes.length > 0 && (
                    <button type="button"
                            onClick={() => { haptic("select"); onFecharSeletor && onFecharSeletor();
                                             if (onPorta) onPorta("hub_eu", null); }}
                            style={{ display:"flex", alignItems:"center", justifyContent:"space-between",
                                     gap:9, minHeight:52, padding:"0 12px", textAlign:"left",
                                     cursor:"pointer", background:"transparent",
                                     border: portaTom().consulta, borderRadius:10,
                                     color:"var(--text)", font:"inherit", fontSize:13 }}>
                      <span style={{ minWidth:0 }}>{t("porta_desbloqueios")}</span>
                      <PortaConta n={phEu.distantes.length} />
                    </button>
                  )}
                </div>
              </Modal>
            )}
          </div>
        );
      }

      return (
        // R5: entrada suave ao trocar de hub (o swap era seco).
        <div style={{ display:"grid", gridTemplateColumns:"minmax(0, 1fr)", gap:14, paddingTop:8, animation:"fade-up .25s ease" }}>
          {/* ── O Orbe da Alma (herói; tap → Perfil) ── 留白 generoso
              (topo 26px: respiro extra p/ a aura viva — nota do review R5,
              o scroll-area clipa box-shadow em linha reta no scrollport) */}
          <div style={{ display:"flex", flexDirection:"column", alignItems:"center", gap:10, padding:"26px 0 4px" }}>
            {/* ═══ 坐 O ORBE MORRE AQUI TAMBÉM (2026-09-13) ══════════════════
                Ordem do owner, 2026-09-07, textual: *"esse orb nao gostei nada,
                muito AI. usamos uma imagem e criamos efeito nela tipo de um
                cultivador."* A 07/09 o orbe do Cultivo ganhou dono único
                (`CultivationOrb` → `CultivatorFigure`); a 09/09 a bolinha do
                cabeçalho ganhou dono único (`RealmAvatar`). **Este ficou.** Uma
                esfera de `radial-gradient` de 150px com um EMOJI DO SISTEMA ao
                centro — exactamente a construção que ele rejeitou pelo nome —
                continuava a ser o herói da tela de identidade do jogo. É a 6ª
                recorrência medida da família F-7: uma capacidade com duas
                ligações à mão diverge sempre.

                ⚠️ E **não** pode ser o `CultivatorFigure`: a lei dele é que a
                figura SÓ existe sentada, e aqui o jogador está de pé a olhar
                para si próprio — pô-la aqui repetiria o defeito de a tela se
                contradizer. O dono certo é o que o cabeçalho já escolheu a
                09/09 pelo mesmo motivo: 坐 (você) com o anel do reino.

                ⚠️ O efeito **muda de suporte, não desaparece** (a frase do
                07/09): a respiração e o `orb-burst` da subida de Poder ficam,
                aplicados à marca em vez de à bola. */}
            <button key={burstSeq}
                    onClick={() => { haptic("select"); onOpenProfile && onOpenProfile(); }}
                    aria-label={safeT("profile_modal_title")}
                    style={{
                      width:orbSize, height:orbSize, borderRadius:"50%", cursor:"pointer",
                      background:"none", border:"none",
                      display:"grid", placeItems:"center", padding:0,
                      color:"var(--gold2)",
                      animation: burstSeq
                        ? "orb-burst .9s cubic-bezier(.2,.8,.3,1.15)"
                        : "orb-breathe 3.6s ease-in-out infinite",
                    }}>
              <RealmAvatar realm={realm} size={orbSize}
                           style={{ boxShadow:`0 0 ${18 + realm * 3}px ${cssHex(rc)}55,`
                                             + ` 0 0 ${44 + realm * 6}px ${cssHex(rc)}22` }} />
            </button>
            <div style={{
              fontFamily:"'Cinzel',serif", fontSize:19, fontWeight:700, letterSpacing:.5,
              background:"linear-gradient(90deg,var(--gold3),var(--gold2),var(--gold),var(--gold2),var(--gold3))",
              backgroundSize:"200% 100%",
              WebkitBackgroundClip:"text", backgroundClip:"text", WebkitTextFillColor:"transparent",
              animation:"shimmer 3.5s linear infinite",
              maxWidth:"88%", whiteSpace:"nowrap", overflow:"hidden", textOverflow:"ellipsis",
            }}>{player.dao_name}</div>
            <div style={{ fontFamily:"'Cinzel',serif", fontSize:11, color:rc, letterSpacing:.6, marginTop:-4 }}>
              {player.realm_name} · {safeT("profile_hero_layer", { n: player.sub_layer || 1 })}
            </div>
            {/* O número que SEMPRE sobe (CountUp) — a Alma visível */}
            <div style={{ display:"flex", alignItems:"baseline", gap:7, marginTop:2 }}>
              <span style={{ fontSize:15 }}>⚔️</span>
              <span style={{ fontFamily:"'Cinzel',serif", fontSize:24, fontWeight:700, color:"var(--gold2)",
                             fontVariantNumeric:"tabular-nums" }}>
                <CountUp value={power} />
              </span>
            </div>
          </div>

          {/* ── 3 barras finas (CB → breakthrough · Qi · Vitalidade) ──
              🩸 2026-09-13 — AS TRÊS BARRAS PASSAM A TER NOME, e isto não é
              enfeite: era o defeito mais caro desta tela.

              Servida e OLHADA a 390x844, esta era a única superfície do
              mini-app onde a Vitalidade aparece — e aparecia como **uma linha
              vermelha sem nome e sem número**. O cartão da Home, a dois taps
              daqui, escreve "CULTIVO 57%" e "QI 4.1K/6.8K" ao lado das mesmas
              duas barras. Duas telas, os mesmos números, uma diz e a outra
              não: *a inconsistência é pior do que a ausência* (Lei 0).

              E a consequência era medível. Quando a Vitalidade chega a zero o
              motor recusa a luta (`hp_too_low`, e a recusa é honesta) — mas o
              jogador nunca tinha visto um número a descer, porque nunca houve
              número. A recusa era a PRIMEIRA vez que a barra falava com ele.
              Nomear a barra é o que torna a recusa a confirmação de uma coisa
              que ele já viu, em vez de uma surpresa. (Lei §1 + o princípio da
              progressão visível: um valor que muda sem número visível é um
              valor que não mudou.)

              ⚠️ O rótulo é **Vitalidade**, que é o que `combat_stat_hp` já
              declara e o que as quatro recusas passaram a dizer neste lote.
              Uma palavra, em todo o lado. */}
          <Card style={{ padding:"12px 14px" }}>
            <div style={{ display:"grid", gap:9 }}>
              <LabeledBar label={safeT("cultivation")} variant="cult"
                          pct={Math.min(100, ((player.cultivation_base || 0) / Math.max(1, player.cb_threshold || 1)) * 100)}
                          right={Math.round(Math.min(100, ((player.cultivation_base || 0) / Math.max(1, player.cb_threshold || 1)) * 100)) + "%"} />
              <LabeledBar label={safeT("qi")} variant="qi"
                          pct={Math.min(100, ((player.qi || 0) / Math.max(1, player.qi_capacity || 1)) * 100)}
                          right={fmtNum(Math.floor(player.qi || 0)) + "/" + fmtNum(Math.floor(player.qi_capacity || 0))} />
              {_mx != null && (
                <LabeledBar label={safeT("hub_eu_bar_vitality")} variant="hp"
                            pct={Math.min(100, (_cur / _mx) * 100)}
                            right={fmtNum(Math.floor(_cur)) + "/" + fmtNum(Math.floor(_mx))} />
              )}
            </div>
          </Card>

          {/* ── Caminhos do EU (grade interativa; destinos intactos) ── */}
          <div>
            <div style={{ fontSize:10.5, color:"var(--gold3)", fontFamily:"'Cinzel',serif",
                          letterSpacing:1.1, textTransform:"uppercase", marginBottom:7, paddingLeft:3 }}>
              {safeT("hub_eu_paths")}
            </div>
            <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:8 }}>
              {paths.map(p => (
                <button key={p.key} onClick={() => { haptic("select"); p.go(); }}
                        style={{
                          display:"flex", alignItems:"center", gap:9,
                          padding:"12px 12px", borderRadius:8, textAlign:"left",
                          background:"rgba(0,0,0,.32)", border:"1px solid rgba(var(--gold2-rgb),.22)",
                          color:"var(--text)", cursor:"pointer", fontFamily:"inherit",
                          transition:"all .15s",
                        }}>
                  <span style={{ fontSize:19, lineHeight:1 }}>{p.ico}</span>
                  <span style={{ fontSize:12.5, fontWeight:600, overflow:"hidden",
                                 textOverflow:"ellipsis", whiteSpace:"nowrap" }}>
                    {safeT(p.key)}
                  </span>
                </button>
              ))}
            </div>
          </div>

        </div>
      );
    }

    // ═══ UI v2 "O Pergaminho Vivo" — Onda R3: HubMundoScreen (o MUNDO como mapa) ═══
    // Gated ui_v2 (flag per-world, graduada no R6; render double-gated no app.js).
    // O mapa dos 5 continentes como TELA do hub Mundo (pesquisa §2.4: o mapa
    // interativo é o centro de gravidade). Leis de Ferro: nº 1 — os 8 destinos do
    // grupo Mundo acessíveis DAQUI (Céu: boss/ranking/facção/guilda · ilha:
    // explorar/praça/seita/portais; + crônica e viagem); nº 2 — progressive
    // disclosure: ilha fechada = SÓ nome+emoji; tap → locais. Ilhas = tinta CSS
    // pura (ink-wash: radial-gradients + contorno orgânico + 留白). Dados DO
    // PAYLOAD (player.current_continent — a Alma; zero endpoint novo); viagem =
    // TravelModal existente (o mapa NÃO reimplementa custo/cooldown). As duas
    // safe-areas do fullscreen são respeitadas no shell (app.js), não aqui.
    function HubMundoScreen({ player, setTab, onOpenTravel, onOpenChronicle, onOpenProfession, onOpenCaravan, initialIsle, isleNonce, onIsleConsumed, onPorta }) {
      // A ilha ATUAL nasce aberta (regra MA-32b: toda ação a ≤2 taps — nav →
      // local); as outras 4 ficam fechadas (Lei nº 2). Hook antes do early-return.
      const [openIsle, setOpenIsle] = useState((player && player.current_continent) || "linghe");
      // MV-3 — deep-link Chronicle→LUGAR: o chip "ver no mapa" abre ESTA ilha.
      // One-shot por nonce (lição ui_v2: contador + effect próprio — um boolean
      // não re-dispara quando a mesma ilha é pedida duas vezes) + CONSUMO (o
      // App zera initialIsle depois do uso — sem isso um remount futuro do
      // mapa reabriria a ilha antiga em vez do continente atual).
      useEffect(() => {
        if (initialIsle) {
          setOpenIsle(initialIsle);
          onIsleConsumed && onIsleConsumed();
        }
      }, [isleNonce]);
      // MV-2 — Tiandao: eventos celestiais no mapa · MV-3 — estados regionais
      // (badge 🌾/⚡/🏚️/🏮 por ilha). Fetch SÓ com uma das flags ON (hooks
      // incondicionais + fetch condicional dentro do effect → zero request
      // novo em mundo OFF/OFF, OFF-identity de rede). name/desc chegam
      // server-resolved (padrão Chronicle); o "world snapshot" é o MESMO
      // endpoint world/events (payload aditivo por flag).
      const [wevData, setWevData] = useState(null);
      const [wevReload, setWevReload] = useState(0);
      const [wevMining, setWevMining] = useState(false);
      // TEC-4 — a Gruta do Legado: duelo em curso + guard de duplo-tap (hooks
      // ANTES do early-return — lição MA-32b).
      const [caveDuel, setCaveDuel] = useState(null);
      const [caveBusy, setCaveBusy] = useState(false);
      // 🔴 州 2026-09-13 — O TAP QUE PARECIA NÃO FAZER NADA, apanhado a OLHAR.
      // Com a cena ligada ela ocupa o ecrã inteiro (`1 / 1.70`, 609px de 844):
      // tocar num continente abre a gaveta ~500px ABAIXO da dobra, e o que o
      // jogador vê é o mapa a não reagir. Um botão cujo efeito é invisível é um
      // beco com mais passos (Lei §1) — e nenhum teste o apanharia, porque a
      // gaveta *renderiza*, só não se vê.
      // Hooks ANTES do early-return (lição R2/R3). O `_isleFirst` existe porque
      // `openIsle` já NASCE no continente atual: sem ele a tela dava um salto
      // sozinha ao abrir, que é o defeito oposto.
      const _isleRef = useRef(null);
      const _isleFirst = useRef(true);
      useEffect(() => {
        if (_isleFirst.current) { _isleFirst.current = false; return; }
        const el = _isleRef.current;
        if (!el || typeof el.scrollIntoView !== "function") return;
        try { el.scrollIntoView({ behavior:"smooth", block:"nearest" }); } catch (e) {}
      }, [openIsle]);
      useEffect(() => {
        if (typeof featureEnabled !== "function"
            // MV-9 — `cidades` TEM de estar neste gate. O endpoint `world/events`
            // passou a mandar `cities`, mas num mundo com SÓ `cidades` ON este
            // guard devolvia cedo, `wevData` nunca era buscado, `isleCity()`
            // devolvia null e o motivo nas portas desabilitadas nascia MORTO —
            // uma feature inteira invisível por causa de um `||` em falta.
            || !(featureEnabled("tiandao_director") || featureEnabled("estados_regionais")
                 || featureEnabled("reputacao_rival") || featureEnabled("legacy_caves")
                 || featureEnabled("cidades"))) return;
        let alive = true;
        api("world/events").then(d => { if (alive && d && d.ok) setWevData(d); }).catch(() => {});
        return () => { alive = false; };
      }, [wevReload]);
      if (!player) return null;
      // TEC-4 — a arena ocupa a tela (padrão da Prova TEC-3); fechar volta ao
      // mapa e refetcha: o settle rodou no poll do duelo, então "tentativa
      // gasta"/arte aparecem sozinhos no card da gruta.
      if (caveDuel) {
        return <DuelArenaModal duelId={caveDuel} playerLang={null}
                 onClose={() => { setCaveDuel(null); setWevReload(x => x + 1); }} />;
      }
      const wevFor = (key) =>
        ((wevData && wevData.events) || []).find(e => e.continent === key) || null;
      // TEC-4 — a gruta ativa desta ilha (payload aditivo `legacy_cave`).
      const lgcFor = (key) =>
        (wevData && wevData.legacy_cave && wevData.legacy_cave.continent === key)
          ? wevData.legacy_cave : null;
      const caveEnter = () => {
        if (caveBusy) return;
        setCaveBusy(true);
        api("world/legacy_cave_start").then(res => {
          setCaveBusy(false);
          if (res && res.ok) { haptic("success"); setCaveDuel(res.duel_id); return; }
          haptic("error");
          const r = (res && res.reason) || "";
          if (r === "wrong_continent") {
            showToast(t("lgc_mini_wrong", { emoji: (res && res.continent_emoji) || "🗺️" }), "err");
          } else if (r === "already_attempted") {
            showToast(t("lgc_mini_attempted"), "err");
          } else if (r === "duel_already_active") {
            showToast(t("lgc_mini_busy"), "err");
          } else if (r === "hp_depleted") {
            showToast(hpDepletedMsg("lgc_mini_hp"), "err");
          } else {
            showToast(t("lgc_mini_gone"), "err");
            setWevReload(x => x + 1);
          }
        }).catch(() => setCaveBusy(false));
      };
      // MV-3 — estado regional da ilha ({state, emoji, name, desc, line} server-resolved).
      const rstFor = (key) =>
        ((wevData && wevData.region_states) || {})[key] || null;
      // MV-6 — chip de rep da ilha ({rep, tier, emoji, name, line} server-resolved).
      const repFor = (key) =>
        ((wevData && wevData.region_rep) || {})[key] || null;
      // MV-9 — o nome da cidade da ilha (server-resolved; só chega com
      // `cidades` ON). Serve para a porta desabilitada DIZER a que lugar é
      // preciso chegar, em vez de sair a opacity .45 e muda.
      const isleCity = (isle) => {
        const c = ((wevData && wevData.cities) || {})[isle && isle.key];
        return c ? c.name : null;
      };
      // ⚠️ 2026-09-15 — UM DONO para as duas afordâncias de viagem, e a razão é
      // a CATRACA DO EMOJI (§15), não o gosto. A 1ª versão da V7 escreveu o ⛵
      // duas vezes (uma para a grelha de hoje, outra para a de portas) e a
      // catraca subiu de 5 para 7 — a regra é explícita: *se subiu, baixe-o;
      // não suba o tecto*. O mesmo pictograma escrito em dois ramos é a "dupla
      // ligação à mão" da Lei F-7 em miniatura, e a catraca apanhou-a.
      const seloViagem = (isle) => {
        const c = isleCity(isle);
        return c ? "⛵ " + c : null;
      };
      const botaoViajar = (faixa) => (
        <button onClick={() => { haptic("select"); onOpenTravel && onOpenTravel(); }}
                style={{
                  display:"flex", alignItems:"center", justifyContent:"center", gap:8,
                  padding:"11px 11px", borderRadius:8,
                  background:"rgba(var(--gold-rgb),.16)", border:"1px solid rgba(var(--gold2-rgb),.55)",
                  color:"var(--gold2)", fontFamily:"inherit", cursor:"pointer",
                  minWidth:0, fontSize:12.5, fontWeight:700,
                  // os dois valores novos DENTRO do ternário (a identidade OFF
                  // quebra-se pela ORDEM, não só pelo valor — lição de 09/09)
                  marginTop: faixa ? 12 : undefined,
                  width: faixa ? "100%" : undefined,
                }}>
          <span style={{ fontSize:17, lineHeight:1, flexShrink:0 }}>⛵</span>
          {safeT("hub_mundo_viajar")}
        </button>
      );
      const wevMine = (ev) => {
        if (wevMining) return;
        setWevMining(true);
        api("world/event_mine", { event_id: ev.id }).then(res => {
          setWevMining(false);
          if (res && res.ok) {
            haptic("success");
            const lootTxt = (res.loot_named_items || [])
              .map(it => `${it.emoji || ""} ${it.count}× ${it.name}`).join(", ")
              || `🪨 ${(res.loot && res.loot.stones) || ""}`;
            showToast(t("wev_mine_reward", { loot: lootTxt }));
            setWevReload(x => x + 1);
          } else if (res && res.reason === "wev_cooldown") {
            const h = Math.max(1, Math.ceil((res.remaining_seconds || 0) / 3600));
            showToast(t("wev_mine_cooldown", { time: h + "h" }), "err");
          } else if (res && res.reason === "wev_no_qi") {
            showToast(t("wev_mine_no_qi", { cost: res.qi_cost || "" }), "err");
          } else if (res && res.reason === "wev_wrong_continent") {
            // Fix do review MV-2: recusa honesta com o LUGAR (Lei §1) — o
            // server devolve continent/emoji de propósito; "dissipou" mentia.
            showToast(t("wev_mine_wrong_continent", {
              emoji: res.continent_emoji || "🗺️",
              name: t("continent_" + (res.continent || "")),
            }), "err");
          } else if (res && (res.reason === "wev_no_event" || res.reason === "wev_locked")) {
            showToast(t("wev_gone"), "err");
            setWevReload(x => x + 1);
          } else {
            showToast(t("wev_mine_fail"), "err");
          }
        }).catch(() => setWevMining(false));
      };
      const current = player.current_continent || "linghe";
      const gold = "var(--gold2)";
      // Espelho de APRESENTAÇÃO de CONTINENT_META (core/continent_engine.py):
      // keys + emojis canônicos; nomes pelas keys continent_* (lição Sprint 6).
      // Tintas = HEX LITERAL da paleta --realm-* (index.html) — NÃO realmColor(),
      // que devolve "var(--realm-N)": concatenar alpha num var() é CSS inválido
      // at-computed-value-time e derruba a declaração INTEIRA (review R3).
      // NENHUMA regra de jogo aqui.
      const isles = [
        // Pass visual 2026-07-07 (owner: "meio feio, fica fora"): ml máx 8% +
        // width 84% = nada sangra da tela; focus2 = 2ª mancha de tinta.
        { key:"linghe",  emoji:"🏔️", tint:"var(--realm-8)", radius:"62% 38% 55% 45% / 45% 58% 42% 55%", focus:"30% 25%", focus2:"78% 80%", ml:"0%" },  // --realm-8
        { key:"qianhe",  emoji:"⛰️", tint:"var(--realm-5)", radius:"40% 60% 48% 52% / 58% 42% 60% 40%", focus:"68% 30%", focus2:"20% 78%", ml:"8%" },  // --realm-5
        { key:"yanshan", emoji:"🌸", tint:"var(--realm-10)", radius:"55% 45% 62% 38% / 50% 55% 45% 50%", focus:"35% 65%", focus2:"80% 22%", ml:"2%" },  // --realm-10
        { key:"fenghuo", emoji:"🌋", tint:"var(--warn)", radius:"45% 55% 40% 60% / 60% 45% 55% 40%", focus:"70% 60%", focus2:"22% 20%", ml:"7%" },  // --realm-7
        { key:"moyu",    emoji:"🌑", tint:"var(--realm-6)", radius:"58% 42% 50% 50% / 42% 60% 40% 58%", focus:"50% 35%", focus2:"18% 82%", ml:"4%" },  // --realm-6
      ];
      // O Céu — o que não pertence a nenhum continente (faixa fina no topo).
      // R4 (decisão da home): +📖 a crônica GLOBAL (continent=null) — só abria
      // do card da HomeTab; o Céu é a casa natural do feed do mundo inteiro
      // (o 📖 das ilhas continua per-continente).
      const heavens = [
        // 門 P6 — `tab` e' a chave pela qual a porta se encontra (`nav_gates`).
        { ico:"⚔️", key:"tab_world_boss",  tab:"world_boss",  go:() => setTab("world_boss") },
        { ico:"🏆", key:"tab_leaderboard", tab:"leaderboard", go:() => setTab("leaderboard") },
        { ico:"🔱", key:"tab_faction",     tab:"faction",     go:() => setTab("faction") },
        { ico:"🤝", key:"tab_guild",       tab:"guild",       go:() => setTab("guild") },
        { ico:"📖", key:"hub_mundo_cronica", go:() => onOpenChronicle && onOpenChronicle(null) },
      ];
      // 門 P6 — o mesmo marco dos outros sítios, pelo mesmo dono.
      const phMundo = portasDoHub(player, heavens.filter(h => h.tab).map(h => h.tab), null);
      const heavensVisiveis = heavens.filter(h => !h.tab || phMundo.lista.some(x => x.key === h.tab));
      // Locais revelados pelo tap na ilha (Lei nº 2). A crônica é per-continente
      // (openChronicle(key) já existe no app.js). Na ilha onde o jogador NÃO
      // está, os locais ficam desabilitados e a viagem é a única ação.
      // ⚠️ 圖 V7 (2026-09-15) — cada local ganhou um `id`, e ele é o DESTINO
      // (`explore`, `plaza`, ...), nunca a chave de i18n. É por ele que a porta
      // pintada se deriva (`ISLE_DOOR_ART[id]`), e é por isso que ele não pode
      // ser a chave traduzida: o nome é para LER, a chave é para ENCONTRAR
      // (lição de 14/09, que custou 229 peças de arte por língua).
      // O `ico` FICA, e não é redundância: sem a flag `o_mapa` a grelha é a de
      // hoje, com os mesmos seis emoji, byte a byte.
      const isleSites = (isle) => [
        { id:"explore",   ico:"🧭", key:"tab_explore",       go:() => setTab("explore") },
        { id:"plaza",     ico:"🏙️", key:"tab_plaza",         go:() => setTab("plaza") },
        { id:"sect",      ico:"🏯", key:"tab_sect",          go:() => setTab("sect") },
        { id:"dungeons",  ico:"🏛️", key:"hub_mundo_portais", go:() => setTab("dungeons") },
        // MV-9.5 — a Caravana é uma PORTA da cidade (o velho está na praça, mas
        // o mapa é onde se pensa em geografia). Gated: sem a flag a porta nem
        // existe na lista — nunca uma porta que não leva a lado nenhum.
        ...((typeof caravanEnabled === "function" ? caravanEnabled() : false) && onOpenCaravan
          ? [{ id:"caravan", ico:"🐫", key:"hub_mundo_caravana", go:() => onOpenCaravan && onOpenCaravan() }]
          : []),
        { id:"chronicle", ico:"📖", key:"hub_mundo_cronica", go:() => onOpenChronicle && onOpenChronicle(isle.key) },
      ];
      // ═══ 州 O MUNDO — as cinco elipses viram cinco TERRITÓRIOS (2026-09-13) ══
      //
      // ⚠️ Tudo o que desenha vive no `HubScene` (`ui.js`) — cena, portas,
      // estados, `aria-label`, cor e recurso. Daqui sai APENAS o estado vivo,
      // como na Caverna (regra da Fonte Única).
      //
      // 🔴 E a porta do Mundo **ABRE** em vez de IR. Um continente não é um
      // destino: é o sítio cujos locais (explorar/praça/seita/portais), estado
      // regional, evento do Céu, gruta e viagem se revelam ao tocá-lo. Uma
      // porta que navegasse apagava tudo isso para ganhar atmosfera — a troca
      // exacta que a chapa de recurso perdeu a 11/09. Por isso o `onSelect`.
      //
      // ⚠️ `lit` = **o continente onde você ESTÁ**, e os outros quatro saem
      // apagados — e continuam tocáveis (Lei §1, a regra da porta apagada da
      // Caverna). O mundo escurece onde você não está: é o que torna a viagem
      // uma coisa que se SENTE, em vez de um botão numa lista.
      //
      // ⚠️ `line` carrega o que os badges do botão diziam, por ordem de
      // urgência — a gruta expira, o evento expira, o "está aqui" não. Sem isto
      // a cena teria comido informação viva, que é o único modo de a cena ser
      // um retrocesso.
      const sceneOn = typeof mapaOn === "function" && mapaOn()
                      && typeof HubScene === "function";
      const mundoDoors = {};
      if (sceneOn) {
        isles.forEach(isle => {
          const lgc = lgcFor(isle.key);
          const wev = wevFor(isle.key);
          const rst = rstFor(isle.key);
          const isCur = isle.key === current;
          // ⚠️ A linha NAO leva pictograma proprio, e a catraca do emoji e' so'
          // metade do motivo. A outra metade e' que o continente esta' PINTADO e
          // ACESO dois centimetros acima: um alfinete ao lado de um lugar que ja'
          // brilha e' a mesma redundancia que apagou os cinco emoji da Caverna a
          // 11/09. As palavras chegam, e o estado ja' se ve'.
          // (`wev.emoji` e `rst.emoji` vem do SERVIDOR e sao dados, nao literais
          // desta tela — a catraca conta literais, e esta linha deixou de ter
          // dois.)
          const line = lgc ? (safeT("lgc_mini_enter") + " · " + lgc.time_left_label)
                     : wev ? (wev.emoji + " " + wev.time_left_label)
                     : isCur ? safeT("hub_mundo_voce_aqui")
                     : (rst ? (rst.emoji + " " + rst.name) : "");
          mundoDoors[isle.key] = {
            lit: isCur,
            line: line,
            onSelect: (k) => setOpenIsle(openIsle === k ? null : k),
          };
        });
      }

      // Traço de pincel entre ilhas (o 留白 é o espaço ao redor).
      const inkStroke = (i) => (
        <svg viewBox="0 0 480 12" preserveAspectRatio="none"
             style={{ width:"64%", height:9, margin:"0 auto", display:"block", opacity:.45 }}>
          <path d={i % 2 === 0
                     ? "M10,6 C90,2 170,10 250,6 C330,2 400,9 470,5"
                     : "M10,5 C100,9 180,2 260,6 C340,10 410,3 470,7"}
                fill="none" stroke="rgba(110,137,191,.5)" strokeWidth="1.3" strokeLinecap="round" />
        </svg>
      );
      return (
        // R5: entrada suave ao trocar de hub (o swap era seco).
        <div style={{ display:"grid", gridTemplateColumns:"minmax(0, 1fr)", gap:12, paddingTop:6, animation:"fade-up .25s ease" }}>
          {/* ── O CÉU — faixa fina: os destinos que pairam sobre os continentes ── */}
          <div style={{ display:"flex", alignItems:"center", gap:6, overflowX:"auto",
                        padding:"4px 2px 10px", borderBottom:"1px solid rgba(var(--gold-rgb),.14)" }}>
            <span style={{ fontSize:10, fontFamily:"'Cinzel',serif", color:"var(--gold3)",
                           letterSpacing:1.1, textTransform:"uppercase", flexShrink:0, paddingRight:4 }}>
              {safeT("hub_mundo_ceu")}
            </span>
            {heavensVisiveis.map(h => {
              const pp = h.tab ? portaDe(player, h.tab) : { estado: "aberta" };
              // 門 P6 — a Facção trancada fica no Céu, apagada, com o selo e o
              // reino; o toque abre a consulta em vez da aba que a recusaria.
              if (pp.estado !== "aberta") {
                return (
                  <button key={h.key} aria-label={portaAria(safeT(h.key), pp)}
                          onClick={() => { haptic("select");
                                           if (onPorta) onPorta("hub_mundo", h.tab); else h.go(); }}
                          style={{
                            display:"inline-flex", alignItems:"center", gap:6, flexShrink:0,
                            padding:"4px 10px", borderRadius:99,
                            background:"transparent", border: portaTom().trancada,
                            color:"var(--text)", cursor:"pointer", fontFamily:"inherit", fontSize:11.5,
                          }}>
                    <span style={{ whiteSpace:"nowrap" }}>{safeT(h.key)}</span>
                    <PortaSelo porta={pp} />
                  </button>
                );
              }
              return (
              <button key={h.key} onClick={() => { haptic("select"); h.go(); }}
                      style={{
                        display:"inline-flex", alignItems:"center", gap:5, flexShrink:0,
                        padding:"4px 10px", borderRadius:99,
                        background:"rgba(0,0,0,.35)", border:"1px solid rgba(var(--gold2-rgb),.22)",
                        color:"var(--text)", cursor:"pointer", fontFamily:"inherit", fontSize:11.5,
                      }}>
                <span style={{ fontSize:13, lineHeight:1 }}>{h.ico}</span>
                <span style={{ whiteSpace:"nowrap" }}>{safeT(h.key)}</span>
              </button>
              );
            })}
            {phMundo.distantes.length > 0 && (
              <button onClick={() => { haptic("select"); if (onPorta) onPorta("hub_mundo", null); }}
                      style={{
                        display:"inline-flex", alignItems:"center", gap:6, flexShrink:0,
                        padding:"4px 10px", borderRadius:99,
                        background:"transparent", border: portaTom().consulta,
                        color:"var(--text)", cursor:"pointer", fontFamily:"inherit", fontSize:11.5,
                      }}>
                <span style={{ whiteSpace:"nowrap" }}>{t("porta_desbloqueios")}</span>
                <PortaConta n={phMundo.distantes.length} />
              </button>
            )}
          </div>

          {/* ── MV-7 — a Guilda dos Ofícios (payload-driven; flag OFF → null) ── */}
          {onOpenProfession && typeof ProfessionCard === "function" && (
            <ProfessionCard player={player} onOpen={onOpenProfession} />
          )}

          {/* ── 州 A CENA — os cinco continentes pintados (flag `o_mapa`) ──
              O fundo é o espaço ENTRE eles (mar de nuvens, zero terra); cada
              território é a sua peça, posicionada por CSS.
              ⚠️ 2026-09-16 — a cena do MUNDO sai de cena quando um continente
              está aberto, e isso é o que faz a coisa ler-se como ENTRAR: o
              mundo afasta-se, o continente ocupa o lugar dele. Ter os dois ao
              mesmo tempo era o que fazia a versão de 15/09 parecer um menu
              colado por baixo de um mapa. */}
          {sceneOn && !openIsle && (
            <HubScene hub="hub_mundo" setTab={setTab} doors={mundoDoors} />
          )}

          {/* ── O MAPA — 5 ilhas de tinta (scroll vertical; tap → locais) ── */}
          {isles.map((isle, i) => {
            const isCurrent = isle.key === current;
            const open = openIsle === isle.key;
            // Com a cena ligada, a ilha FECHADA já está desenhada lá em cima —
            // aqui fica só a gaveta da que está aberta. Sem a flag, `sceneOn` é
            // `false` e esta linha nunca corre: a tela de hoje, byte a byte.
            if (sceneOn && !open) return null;
            const wev = wevFor(isle.key);   // MV-2 — evento celestial desta ilha
            const rst = rstFor(isle.key);   // MV-3 — estado regional desta ilha
            const rep = repFor(isle.key);   // MV-6 — como esta ilha te recebe
            const lgc = lgcFor(isle.key);   // TEC-4 — a Gruta do Legado desta ilha
            return (
              <React.Fragment key={isle.key}>
                {!sceneOn && i > 0 && inkStroke(i)}
                {/* ⚠️ Com a cena ligada esta caixa deixa de FINGIR ser uma ilha
                    (a ilha está pintada lá em cima) e passa a ser o que ela
                    realmente é: a gaveta daquele continente. Os valores novos
                    entram DENTRO dos ternários das propriedades que já
                    existiam — a OFF-identidade quebra-se pela ORDEM, não só
                    pelo valor (lição de 09/09). */}
                <div ref={sceneOn && open ? _isleRef : null} style={{
                  width: sceneOn ? "100%" : "84%",
                  marginLeft: sceneOn ? 0 : isle.ml,
                  // Aberta → retângulo suave (o grid de locais brigava com o
                  // recorte elíptico — fix "meio feio" 2026-07-07); fechada →
                  // contorno orgânico de ilha.
                  borderRadius: sceneOn ? 12 : (open ? 22 : isle.radius), overflow:"hidden",
                  transition:"border-radius .3s ease, box-shadow .3s ease",
                  background: sceneOn
                    ? "linear-gradient(160deg,rgba(var(--surface-rgb),.92) 0%,rgba(var(--surface3-rgb),.95) 100%)"
                    : `radial-gradient(ellipse at ${isle.focus}, ${cssHex(isle.tint)}47, transparent 62%), radial-gradient(ellipse at ${isle.focus2}, ${cssHex(isle.tint)}1f, transparent 68%), radial-gradient(ellipse at 50% 42%, rgba(20,32,58,.97), rgba(10,15,28,.9) 72%, rgba(var(--bg-rgb),.55) 100%)`,
                  border:`1px solid ${isCurrent ? "rgba(var(--gold2-rgb),.55)" : "rgba(var(--muted-rgb),.24)"}`,
                  boxShadow: sceneOn
                    ? "none"
                    : (isCurrent
                      ? `0 0 22px ${cssHex(gold)}38, 0 0 48px ${cssHex(isle.tint)}26, inset 0 0 42px ${cssHex(isle.tint)}14, inset 0 0 26px rgba(0,0,0,.5)`
                      : `0 0 14px ${cssHex(isle.tint)}1c, inset 0 0 42px ${cssHex(isle.tint)}10, inset 0 0 26px rgba(0,0,0,.5)`),
                }}>
                  <button onClick={() => { haptic("select"); setOpenIsle(open ? null : isle.key); }}
                          aria-expanded={open}
                          style={{
                            width:"100%", background:"none", border:"none", cursor:"pointer",
                            color:"var(--text)", fontFamily:"inherit",
                            display:"flex", flexDirection:"column", alignItems:"center", gap:6,
                            padding: open ? "16px 16px 8px" : "18px 16px 16px",
                          }}>
                    {/* ⚠️ Com a cena, o emoji de 30px SAI — e não foi
                        substituído por marca nenhuma: o continente está
                        PINTADO a 140px logo acima, e um pictograma ao lado do
                        nome de uma coisa que já se vê é ruído. É o mesmo
                        argumento que apagou os 5 emoji da Caverna a 11/09. */}
                    {!sceneOn && (
                      <span style={{ fontSize:30, lineHeight:1, filter:`drop-shadow(0 0 10px ${cssHex(isle.tint)}aa)` }}>
                        {isle.emoji}
                      </span>
                    )}
                    <span style={{ fontFamily:"'Cinzel',serif", fontSize:15.5, fontWeight:700,
                                   letterSpacing:.8, color: isCurrent ? "var(--gold2)" : "var(--text)" }}>
                      {safeT("continent_" + isle.key)}
                      {/* MV-3 — o emoji do estado ao lado do nome (🌾/⚡/🏚️/🏮);
                          só chega no payload com `estados_regionais` ON. */}
                      {rst && <span style={{ marginLeft:6, fontSize:13 }}>{rst.emoji}</span>}
                    </span>
                    {/* ⚠️ Os três badges abaixo sobem para a `line` da porta
                        quando há cena — a cena É onde o estado do lugar se lê.
                        Repeti-los aqui seria a mesma verdade dita duas vezes a
                        dois centímetros de distância. */}
                    {!sceneOn && isCurrent && (
                      <span style={{
                        fontSize:9.5, fontWeight:700, letterSpacing:.6, textTransform:"uppercase",
                        fontFamily:"'Cinzel',serif", color:"var(--gold2)",
                        border:"1px solid rgba(var(--gold2-rgb),.5)", borderRadius:99, padding:"3px 10px",
                        background:"rgba(var(--surface2-rgb),.65)",
                        animation:"pulse-glow 2.4s ease-in-out infinite",
                      }}>
                        📍 {safeT("hub_mundo_voce_aqui")}
                      </span>
                    )}
                    {/* MV-2 — badge do evento celestial: emoji + timer curto */}
                    {!sceneOn && wev && (
                      <span style={{
                        fontSize:9.5, fontWeight:700, letterSpacing:.5,
                        fontFamily:"'Cinzel',serif", color:"#f0f4ff",
                        border:"1px solid rgba(var(--accent2-rgb),.55)", borderRadius:99, padding:"3px 10px",
                        background:"rgba(30,45,90,.6)",
                        animation:"pulse-glow 2.4s ease-in-out infinite",
                      }}>
                        {wev.emoji} {wev.time_left_label}
                      </span>
                    )}
                    {/* TEC-4 — badge da Gruta do Legado: 🏮 + timer curto */}
                    {!sceneOn && lgc && (
                      <span style={{
                        fontSize:9.5, fontWeight:700, letterSpacing:.5,
                        fontFamily:"'Cinzel',serif", color:"#ffe9c9",
                        border:"1px solid rgba(var(--gold2-rgb),.6)", borderRadius:99, padding:"3px 10px",
                        background:"rgba(90,60,20,.55)",
                        animation:"pulse-glow 2.4s ease-in-out infinite",
                      }}>
                        🏮 {lgc.time_left_label}
                      </span>
                    )}
                  </button>
                  {open && (
                    <div style={{ padding:"0 16px 16px", animation:"fade-up .22s ease" }}>
                      {/* MV-3 — a linha do estado da ilha (server-resolved:
                          "🏚️ Sitiada — estradas caras, mercados nervosos"). */}
                      {rst && (
                        <div style={{ fontSize:11, color:"var(--gold3)", marginBottom:10, lineHeight:1.45 }}>
                          {rst.emoji} {rst.name} — {rst.desc}
                        </div>
                      )}
                      {/* MV-6 — como esta ilha te recebe (chip server-resolved;
                          só chega no payload com `reputacao_rival` ON). */}
                      {rep && (
                        <div style={{ fontSize:10.5, color:"var(--muted)", marginBottom:10, lineHeight:1.45 }}>
                          {safeT("rep_map_label")}: {rep.line}
                        </div>
                      )}
                      {/* MV-2 — o card do evento: ver, ir lá, agir (Lei §1).
                          Maré → progresso do goal; Meteoro na ilha atual →
                          ação de minerar; noutra ilha o ⛵ Viajar abaixo é o CTA. */}
                      {wev && (
                        <div style={{
                          marginBottom:10, padding:"10px 12px", borderRadius:10,
                          background:"rgba(30,45,90,.35)",
                          border:"1px solid rgba(var(--accent2-rgb),.4)",
                        }}>
                          <div style={{ fontSize:13, fontWeight:700, color:"#f0f4ff" }}>
                            {wev.emoji} {wev.name} · ⏳ {t("wev_time_left", { time: wev.time_left_label })}
                          </div>
                          <div style={{ fontSize:11, color:"var(--muted)", marginTop:4, lineHeight:1.45 }}>
                            {wev.desc}
                          </div>
                          {wev.event_type === "beast_tide" && wev.goal > 0 && (
                            <div style={{ marginTop:8 }}>
                              <div style={{ fontSize:10.5, color:"var(--gold3)", marginBottom:4 }}>
                                ⚔️ {t("wev_progress_label")}: {wev.progress}/{wev.goal}
                              </div>
                              <div style={{ height:6, borderRadius:99, background:"rgba(0,0,0,.4)", overflow:"hidden" }}>
                                <div style={{ height:"100%", borderRadius:99, background:"var(--realm-8)",
                                              width: Math.min(100, (wev.progress / wev.goal) * 100) + "%" }} />
                              </div>
                            </div>
                          )}
                          {wev.event_type === "meteor" && isCurrent && (
                            <button onClick={() => { haptic("select"); wevMine(wev); }}
                                    disabled={wevMining || wev.mine_cooldown_remaining_s > 0}
                                    style={{
                                      marginTop:8, width:"100%", padding:"9px 10px", borderRadius:8,
                                      background:"rgba(var(--accent2-rgb),.16)", border:"1px solid rgba(var(--accent2-rgb),.55)",
                                      color:"#f0f4ff", fontFamily:"inherit", fontSize:12.5, fontWeight:700,
                                      cursor:"pointer",
                                      opacity: (wevMining || wev.mine_cooldown_remaining_s > 0) ? .55 : 1,
                                    }}>
                              {wev.mine_cooldown_remaining_s > 0
                                ? t("wev_mine_cooldown", { time: Math.max(1, Math.ceil(wev.mine_cooldown_remaining_s / 3600)) + "h" })
                                : `⛏️ ${t("wev_action_mine")} · ⚡${wev.qi_cost}`}
                            </button>
                          )}
                          {!isCurrent && (
                            <div style={{ fontSize:10.5, color:"var(--gold3)", marginTop:6 }}>
                              ⛵ {t("wev_travel_hint")}
                            </div>
                          )}
                        </div>
                      )}
                      {/* TEC-4 — o card da Gruta do Legado: a vitrine é honesta
                          ANTES do tap (arte + chance + pity + tentativa única —
                          display = roll, Lei §1/§10). Noutra ilha, o ⛵ Viajar
                          é o CTA (a geografia É o custo). */}
                      {lgc && (
                        <div style={{
                          marginBottom:10, padding:"10px 12px", borderRadius:10,
                          background:"rgba(90,60,20,.28)",
                          border:"1px solid rgba(var(--gold2-rgb),.5)",
                        }}>
                          <div style={{ fontSize:13, fontWeight:700, color:"#ffe9c9" }}>
                            🏮 {lgc.name} · ⏳ {t("wev_time_left", { time: lgc.time_left_label })}
                          </div>
                          <div style={{ fontSize:11, color:"var(--muted)", marginTop:4, lineHeight:1.45 }}>
                            {lgc.desc}
                          </div>
                          {lgc.art && (
                            <div style={{ fontSize:11, color:"var(--gold3)", marginTop:6, lineHeight:1.45 }}>
                              {t("lgc_mini_art_line", {
                                emoji: lgc.art.emoji || "📜", name: lgc.art.name || "",
                                pct: lgc.art_chance_pct, pity: lgc.pity_clears,
                              })}
                            </div>
                          )}
                          <div style={{ fontSize:10.5, color:"var(--muted)", marginTop:4 }}>
                            {t("lgc_mini_one_try")}
                          </div>
                          {lgc.has_art && (
                            <div style={{ fontSize:10.5, color:"var(--gold3)", marginTop:4 }}>
                              {t("lgc_mini_has_art")}
                            </div>
                          )}
                          {isCurrent && lgc.attempted && (
                            <div style={{ fontSize:10.5, color:"var(--gold3)", marginTop:6 }}>
                              {t("lgc_mini_attempted")}
                            </div>
                          )}
                          {isCurrent && !lgc.attempted && (
                            <button onClick={() => { haptic("select"); caveEnter(); }}
                                    disabled={caveBusy}
                                    style={{
                                      marginTop:8, width:"100%", padding:"9px 10px", borderRadius:8,
                                      background:"rgba(var(--gold2-rgb),.14)", border:"1px solid rgba(var(--gold2-rgb),.6)",
                                      color:"#ffe9c9", fontFamily:"inherit", fontSize:12.5, fontWeight:700,
                                      cursor:"pointer", opacity: caveBusy ? .55 : 1,
                                    }}>
                              ⚔️ {t("lgc_mini_enter")}
                            </button>
                          )}
                          {!isCurrent && (
                            <div style={{ fontSize:10.5, color:"var(--gold3)", marginTop:6 }}>
                              ⛵ {t("wev_travel_hint")}
                            </div>
                          )}
                        </div>
                      )}
                      {/* ⚠️ Com a cena, o rótulo "LOCAIS" sai: a cena É os
                          locais, e uma etiqueta por cima de uma coisa que já se
                          vê é o mesmo ruído que apagou os 5 emoji da Caverna a
                          11/09. Sem a flag ele fica, porque aí a lista precisa
                          mesmo de se anunciar. */}
                      {!sceneOn && (
                      <div style={{ fontSize:10, color:"var(--gold3)", fontFamily:"'Cinzel',serif",
                                    letterSpacing:1.1, textTransform:"uppercase", margin:"2px 0 7px" }}>
                        {safeT("hub_mundo_locais")}
                      </div>
                      )}
                      {/* ═══ 州 O CONTINENTE ABRE COMO UM LUGAR (2026-09-16) ══
                          Correcção do owner ao que saiu a 15/09: *"eu abro ele
                          tipo um mapa mundial, e dentro tem a imagem da praça,
                          aventura, as dungeons"*. O chão é a pintura `place`
                          deste continente; os seis sítios são as `door` postas
                          por cima, espalhadas como lugares num mapa — não
                          alinhadas como células.
                          ⚠️ A cena reusa o `HubScene` com `sceneDef`: um
                          continente não é um hub (não tem `group` no
                          `HUB_DEFS`), mas a CAIXA, o véu, o recurso e a porta
                          são os mesmos — escrevê-los outra vez era a Lei F-7 §2
                          com a caixa em vez da porta. */}
                      {sceneOn && typeof HubScene === "function"
                               && typeof ISLE_SCENE_ART === "object"
                               && ISLE_SCENE_ART[isle.key] && (
                        <HubScene
                          setTab={setTab}
                          sceneDef={{
                            art: ISLE_SCENE_ART[isle.key],
                            // ⚠️ véu PRÓPRIO, e mais forte que o dos hubs: os
                            // continentes são chão pintado com luz, não rocha
                            // preta. Com o véu dos hubs, cada porta saía com um
                            // halo — ver a nota no `HubScene`.
                            veil: "radial-gradient(ellipse at 50% 46%,"
                                  + " rgba(var(--bg-rgb),.52),"
                                  + " rgba(var(--bg-rgb),.72) 72%,"
                                  + " rgb(var(--bg-rgb)) 100%)",
                            // o mesmo "distante, não desligado" do Mundo: num
                            // continente onde não se está, os seis sítios saem
                            // esbatidos, nunca mortos (lição V6)
                            dim: "grayscale(.34) brightness(.66)",
                            dim_key: "mapa_porta_longe",
                            doors: isleSites(isle)
                              .filter(s => ISLE_DOOR_LAYOUT[s.id])
                              .map(s => Object.assign({
                                key: s.id,
                                tab: "explore",
                                label_key: s.key,
                                art: ISLE_DOOR_ART[s.id],
                              }, ISLE_DOOR_LAYOUT[s.id])),
                          }}
                          doors={isleSites(isle).reduce((acc, s) => {
                            acc[s.id] = {
                              lit: isCurrent,
                              line: !isCurrent ? seloViagem(isle) : null,
                              // ⚠️ A porta distante CONTINUA tocável e leva à
                              // viagem — um lugar pintado que não faz nada é um
                              // beco com mais passos (Lei §1).
                              onSelect: isCurrent
                                ? () => s.go()
                                : () => onOpenTravel && onOpenTravel(),
                            };
                            return acc;
                          }, {})} />
                      )}
                      {/* QoL 09/08 Item E (report [jogador] "map/travel misaligned,
                          mobile") — `1fr` é `minmax(auto,1fr)`: a faixa NUNCA
                          encolhe abaixo do min-content dos filhos. Com os três
                          `nowrap` da porta (ícone + nome + o ⛵ que o MV-9
                          acrescentou ontem), o min-content passa a largura da
                          célula, o `textOverflow:ellipsis` do nome nunca dispara
                          e a grelha transborda — numa coluna de meio telemóvel
                          é literalmente o desalinhamento reportado. `minmax(0,
                          1fr)` + `minWidth:0` é o fix que a casa já aplicou em
                          16 raízes no QoL de 31/07. */}
                      {/* ⚠️ 2026-09-16 — a LISTA só existe SEM a flag.
                          A 15/09 havia DUAS formas de desenhar o dentro do
                          continente: esta grelha (em azulejos pintados) e, a
                          partir de hoje, a cena. Duas formas para a mesma coisa
                          é a Lei F-7 §2 a nascer outra vez — e a grelha era a
                          errada, dita pelo owner. Com a flag ligada o continente
                          é a CENA acima; sem ela, é esta lista, byte a byte
                          como sempre foi. */}
                      {!sceneOn && (
                      <div style={{
                        display:"grid",
                        gridTemplateColumns:"minmax(0,1fr) minmax(0,1fr)",
                        gap:8,
                      }}>
                        {isleSites(isle).map(s => (
                          <button key={s.key}
                                  onClick={isCurrent ? () => { haptic("select"); s.go(); } : undefined}
                                  disabled={!isCurrent}
                                  style={{
                                    display:"flex", alignItems:"center", gap:8,
                                    padding:"11px 11px", borderRadius:8, textAlign:"left",
                                    background:"rgba(0,0,0,.32)", border:"1px solid rgba(var(--gold2-rgb),.22)",
                                    color:"var(--text)", fontFamily:"inherit",
                                    minWidth:0, overflow:"hidden",
                                    cursor: isCurrent ? "pointer" : "default",
                                    opacity: isCurrent ? 1 : .45,
                                  }}>
                            <span style={{ fontSize:17, lineHeight:1, flexShrink:0 }}>{s.ico}</span>
                            <span style={{ fontSize:12, fontWeight:600, overflow:"hidden",
                                           minWidth:0, textOverflow:"ellipsis", whiteSpace:"nowrap" }}>
                              {safeT(s.key)}
                            </span>
                            {/* MV-9 — a porta desabilitada passa a DIZER porquê.
                                Até aqui as 20 portas das 4 ilhas remotas saíam a
                                opacity .45 e mudas: o jogador via a porta, batia,
                                e nada acontecia sem uma palavra (Lei §1). Agora
                                nomeia o lugar a que é preciso chegar. */}
                            {!isCurrent && seloViagem(isle) && (
                              <span style={{ fontSize:9, color:"var(--gold3)", marginLeft:"auto",
                                             flexShrink:0, whiteSpace:"nowrap" }}>
                                {seloViagem(isle)}
                              </span>
                            )}
                          </button>
                        ))}
                        {!isCurrent && botaoViajar(false)}
                      </div>
                      )}
                      {/* ⚠️ Com a cena, a viagem SAI da grelha e ganha faixa
                          própria: um botão de acção no meio de seis portas
                          pintadas é a moldura a voltar por outro caminho. E é o
                          CTA de um continente onde não se está — merece a
                          largura toda, não um sexto dela. */}
                      {!isCurrent && sceneOn && botaoViajar(true)}
                    </div>
                  )}
                </div>
              </React.Fragment>
            );
          })}
        </div>
      );
    }

    // ═══ UI v2 "O Pergaminho Vivo" — Onda R4a: HubCavernaScreen (o LAR) ═══
    // Gated ui_v2 (double-gated no app.js, padrão hub_mundo_screen). A caverna
    // vista de DENTRO: salas de pedra tocáveis (mesma linguagem das ilhas R3 —
    // contorno orgânico + radial-gradient + HEX LITERAL; paleta terrosa/jade,
    // NÃO os tints dos continentes). Leis de Ferro: nº 1 — os 5 destinos do
    // grupo Caverna acessíveis DAQUI (a Faixa some nos landings-tela); nº 2 —
    // sala fechada = SÓ nome+emoji; tap → 1 linha de resumo + Entrar. Este
    // landing NÃO substitui o CavernTab — é a ANTESSALA (regra MA-32b: mudam
    // os PONTOS DE ENTRADA, nunca os destinos). Única leitura de dados: o
    // payload EXISTENTE world/cavern alimenta a linha do Salão (zero endpoint
    // novo — regra da Fonte Única); as outras salas = 1 linha de sabor.
    function HubCavernaScreen({ player, setTab }) {
      // O Salão nasce ABERTO (lição R3: ≤2 taps — nav → Entrar). Hooks ANTES
      // do early-return (lição R2/R3).
      const [openRoom, setOpenRoom] = useState("salao");
      const cavern = useApi("world/cavern", null, []);
      if (!player) return null;
      const cv = cavern.data || {};
      // Salas — tinta terrosa/jade em hex literal (lição R3: alpha-concat em
      // var() é CSS inválido e derruba a declaração inteira). Aberta → morfa
      // p/ retângulo 22px (lição R3.1: o conteúdo briga com o recorte elíptico).
      // "mercado" usa o tab_market existente como nome (regra §6: só criar key
      // quando o tab_* não cobre).
      const rooms = [
        { key:"salao",    emoji:"🛖", name_key:"hub_caverna_salao",    sub_key:"hub_caverna_salao_sub",    tab:"cavern",
          tint:"var(--jade)", radius:"58% 42% 52% 48% / 46% 56% 44% 54%", focus:"32% 28%", ml:"0%" },
        { key:"forja",    emoji:"⚒️", name_key:"hub_caverna_forja",    sub_key:"hub_caverna_forja_sub",    tab:"crafting",
          tint:"#e0862e", radius:"42% 58% 46% 54% / 56% 44% 58% 42%", focus:"66% 32%", ml:"7%" },
        { key:"anel",     emoji:"💍", name_key:"hub_caverna_anel",     sub_key:"hub_caverna_anel_sub",     tab:"inventory",
          tint:"#d4af5a", radius:"54% 46% 60% 40% / 48% 54% 46% 52%", focus:"36% 62%", ml:"2%" },
        { key:"estabulo", emoji:"🐾", name_key:"hub_caverna_estabulo", sub_key:"hub_caverna_estabulo_sub", tab:"beasts",
          tint:"#a67c52", radius:"46% 54% 42% 58% / 58% 46% 54% 42%", focus:"68% 58%", ml:"6%" },
        { key:"mercado",  emoji:"🏮", name_key:"tab_market",           sub_key:"hub_caverna_mercado_sub",  tab:"market",
          tint:"#d96459", radius:"56% 44% 50% 50% / 44% 58% 42% 56%", focus:"48% 34%", ml:"3%" },
      ];
      // A linha do Salão vem do payload (qi acumulado / teaser de estabelecer);
      // loading = "…", erro = cai na linha estática (a sala NUNCA perde o tap).
      const roomSub = (room) => {
        if (room.key !== "salao") return safeT(room.sub_key);
        if (cavern.loading && !cavern.data) return "…";
        // erro HTTP OU payload degenerado (ok:false chega como data — useApi só
        // rejeita erro de rede) → linha estática; a sala NUNCA perde o tap.
        if (cavern.error || !cavern.data || cv.ok === false) return safeT(room.sub_key);
        if (!cv.has_cavern) return safeT("cavern_none_yet");
        return safeT("hub_caverna_salao_qi", { qi: fmtNum(Math.floor(cv.accrued_qi || 0)) });
      };
      // ═══ 圖 O MAPA — a antessala deixa de ser uma lista e vira um LUGAR ══
      //
      // ⚠️ Tudo o que desenha vive no `HubScene` (`ui.js`) — cena, portas,
      // estados, `aria-label`, cor e recurso. Daqui sai APENAS o estado vivo,
      // porque e' esta tela que ja' tem o payload (regra da Fonte Unica: o
      // componente nunca vai buscar dados nem inventa um pedido novo).
      //
      // ⚠️ **UMA porta tem estado, e as outras quatro NAO — e isso vai escrito,
      // nao e' esquecimento** (V5 §3.4, Lei 0 passo 5). O unico dado vivo que
      // esta tela busca e' o `world/cavern`. O Estabulo PODIA apagar quando nao
      // ha' fera companheira, mas isso exigia um pedido novo ao servidor a
      // partir de uma tela de NAVEGACAO — e a leitura certa e' outra: o curral
      // e' um LUGAR, nao o animal. Esta aceso porque existe, nao porque esta'
      // habitado. O estado que importa (o Salao por estabelecer) e' o caso
      // maioritario de quem comeca, e exercita o ramo apagado todos os dias.
      //
      // ⚠️ `cv.has_cavern === false` e NAO `!cv.has_cavern`: enquanto o payload
      // nao chega, `has_cavern` e' `undefined` e a porta ficaria a PISCAR de
      // apagada para acesa em cada abertura. Enquanto nao se sabe, esta acesa —
      // o `line` ja' diz "…" e conta a verdade sozinho.
      //
      // ⚠️ O gate pede `typeof` alem da flag: e' o padrao fail-safe dos hubs
      // (`app.js`) — um cliente com o `ui.js` em cache sem o componente novo cai
      // na tela de hoje em vez de rebentar.
      if (typeof mapaOn === "function" && mapaOn() && typeof HubScene === "function") {
        const mapaDoors = {
          salao: {
            lit: !(cavern.data && cv.ok !== false && cv.has_cavern === false),
            line: roomSub(rooms[0]),
          },
        };
        return (
          <div style={{ paddingTop:6, animation:"fade-up .25s ease" }}>
            <HubScene hub="hub_caverna" setTab={setTab} doors={mapaDoors} />
          </div>
        );
      }

      // Veios de pedra entre as salas (o irmão terroso do traço-pincel R3).
      const veins = (i) => (
        <svg viewBox="0 0 480 12" preserveAspectRatio="none"
             style={{ width:"58%", height:8, margin:"0 auto", display:"block", opacity:.4 }}>
          <path d={i % 2 === 0
                     ? "M10,7 C80,3 160,10 250,5 C330,2 410,9 470,6"
                     : "M10,4 C100,8 190,3 270,7 C350,10 420,4 470,7"}
                fill="none" stroke="rgba(166,124,82,.55)" strokeWidth="1.2" strokeLinecap="round" />
        </svg>
      );
      return (
        // R5: entrada suave ao trocar de hub (o swap era seco).
        <div style={{ display:"grid", gridTemplateColumns:"minmax(0, 1fr)", gap:12, paddingTop:6, animation:"fade-up .25s ease" }}>
          {rooms.map((room, i) => {
            const open = openRoom === room.key;
            return (
              <React.Fragment key={room.key}>
                {i > 0 && veins(i)}
                <div style={{
                  width:"84%", marginLeft:room.ml,
                  borderRadius: open ? 22 : room.radius, overflow:"hidden",
                  transition:"border-radius .3s ease, box-shadow .3s ease",
                  background:`radial-gradient(ellipse at ${room.focus}, ${cssHex(room.tint)}42, transparent 64%), radial-gradient(ellipse at 50% 46%, rgba(34,28,20,.97), rgba(16,13,10,.92) 74%, rgba(8,7,6,.6) 100%)`,
                  border:`1px solid ${open ? "rgba(var(--gold2-rgb),.5)" : "rgba(166,124,82,.28)"}`,
                  boxShadow: open
                    ? `0 0 20px ${cssHex(room.tint)}30, inset 0 0 40px ${cssHex(room.tint)}12, inset 0 0 24px rgba(0,0,0,.55)`
                    : `0 0 12px ${cssHex(room.tint)}1a, inset 0 0 40px ${cssHex(room.tint)}0e, inset 0 0 24px rgba(0,0,0,.55)`,
                }}>
                  <button onClick={() => { haptic("select"); setOpenRoom(open ? null : room.key); }}
                          aria-expanded={open}
                          style={{
                            width:"100%", background:"none", border:"none", cursor:"pointer",
                            color:"var(--text)", fontFamily:"inherit",
                            display:"flex", flexDirection:"column", alignItems:"center", gap:6,
                            padding: open ? "15px 16px 8px" : "17px 16px 15px",
                          }}>
                    <span style={{ fontSize:28, lineHeight:1, filter:`drop-shadow(0 0 9px ${cssHex(room.tint)}aa)` }}>
                      {room.emoji}
                    </span>
                    <span style={{ fontFamily:"'Cinzel',serif", fontSize:15, fontWeight:700,
                                   letterSpacing:.8, color: open ? "var(--gold2)" : "var(--text)" }}>
                      {safeT(room.name_key)}
                    </span>
                  </button>
                  {open && (
                    <div style={{ padding:"0 16px 14px", animation:"fade-up .22s ease" }}>
                      <div style={{ fontSize:11.5, color:"var(--muted)", lineHeight:1.55,
                                    textAlign:"center", marginBottom:10 }}>
                        {roomSub(room)}
                      </div>
                      <button onClick={() => { haptic("select"); setTab(room.tab); }}
                              style={{
                                width:"100%", display:"flex", alignItems:"center", justifyContent:"center",
                                gap:8, padding:"11px 11px", borderRadius:8,
                                background:"rgba(var(--gold-rgb),.16)", border:"1px solid rgba(var(--gold2-rgb),.55)",
                                color:"var(--gold2)", fontFamily:"inherit", cursor:"pointer",
                                fontSize:12.5, fontWeight:700,
                              }}>
                        {safeT("hub_caverna_entrar")} ›
                      </button>
                    </div>
                  )}
                </div>
              </React.Fragment>
            );
          })}
        </div>
      );
    }

    // ═══ UI v2 "O Pergaminho Vivo" — Onda R4b: HubPergaminhoScreen (o DIA) ═══
    // Gated ui_v2 (double-gated no app.js, padrão hub_mundo_screen). O dia do
    // cultivador como UM pergaminho que desenrola (pesquisa §2.2/§2.6 YNXY:
    // rotina ~20min): topo = HOJE (missões → quests), meio = TEMPORADA (passe
    // → battle_pass), fundo = NOTÍCIAS (announcements), separados por selo de
    // cera + traço-pincel. Navegação, não muro de informação (Lei nº 2): cada
    // seção = resumo de 1-2 linhas + 1 tap. Dados dos 3 payloads EXISTENTES
    // (regra da Fonte Única — zero endpoint novo); loading = "…" e erro = "—",
    // mas a seção NUNCA perde o tap (Lei nº 1).
    function HubPergaminhoScreen({ player, setTab }) {
      // Hooks ANTES do early-return (lição R2/R3).
      const quests = useApi("quests", null, []);
      const bp = useApi("battle_pass", null, []);
      const news = useApi("announcements", null, []);
      // ═══ 卷 A PELE (2026-09-15) — o rolo passa a OCUPAR o ecrã ═══════════
      //
      // MEDIDO a 390×844, servido e OLHADO: a caixa de conteúdo tem **601px**
      // e o rolo ocupava **253** (42%) — ficavam **348px de PÁGINA vazia** por
      // baixo dele, com o fundo do reino a aparecer. A régua do desenho diz
      // *"o vazio é a composição"*, e é verdade — **mas um buraco não é vazio**.
      // A diferença é onde ele está: 348px de PAPEL entre dois bastões são
      // 留白; 348px de PÁGINA debaixo de um objecto são um buraco.
      //
      // É o mesmo defeito e a mesma correcção da Caverna a 11/09 (`1 / 1.02`
      // → `1 / 1.70`): *"a cena lia-se como um CARTÃO a flutuar, não como o
      // sítio onde se está"*. Aqui o objecto é um rolo, e um rolo que acaba a
      // um terço do ecrã lê-se como um cartão pela mesma razão.
      //
      // ⚠️ Das três hipóteses pesadas, a REJEITADA foi a da mesa (pôr uma
      // superfície pintada por baixo): a V6 decidiu que este hub **não é um
      // lugar**, e uma pintura por trás reabre essa decisão para ganhar
      // atmosfera — além de que `ARTE_PROVENIENCIA §2.5` obriga a ficheiro novo
      // ao regerar, e um alinhamento pintado passa a mentir em silêncio.
      //
      // ⚠️ E há um ganho de HONESTIDADE, não só de pele: este hub é *o DIA do
      // cultivador*. Um rolo escrito em cima e em branco em baixo diz **que o
      // resto do dia ainda não foi escrito** — que é verdade, e é dramatizar a
      // espera em vez de a disfarçar (régua #3).
      //
      // ⚠️ Porque é MEDIDO e não `100vh`: o cabeçalho muda de altura com o
      // estado do jogador (raiz, reino, passe), e uma conta assada ficava certa
      // hoje e errada na primeira linha nova. Lê-se a caixa que nos hospeda.
      // Se a medição falhar, `fill` fica 0 e a tela é a de hoje, byte a byte.
      const rolRef = useRef(null);
      const [fill, setFill] = useState(0);
      useEffect(() => {
        const medir = () => {
          const el = rolRef.current;
          if (!el) return;
          const host = el.closest(".scroll-area");
          if (!host) { setFill(0); return; }
          const cs = getComputedStyle(host);
          const dentro = host.clientHeight
                       - (parseFloat(cs.paddingTop) || 0)
                       - (parseFloat(cs.paddingBottom) || 0);
          setFill(dentro > 160 ? Math.round(dentro) : 0);
        };
        medir();
        window.addEventListener("resize", medir);
        return () => window.removeEventListener("resize", medir);
      }, []);
      if (!player) return null;

      // ── HOJE — contagens por grupo do payload /quests (mesma leitura do
      // QuestsTab: is_completed/total; inclui as de Seita do hotfix 2026-07-07).
      const qs = (quests.data && quests.data.quests) || null;
      const questLine = (quests.loading && !quests.data) ? "…"
        : !qs ? "—"
        : (() => {
            const d = qs.filter(q => q.type === "daily");
            const w = qs.filter(q => q.type === "weekly");
            const s = qs.filter(q => q.type === "sect");
            const parts = [];
            if (d.length) parts.push(safeT("dailies") + " " + d.filter(q => q.is_completed).length + "/" + d.length);
            if (w.length) parts.push(safeT("weeklies") + " " + w.filter(q => q.is_completed).length + "/" + w.length);
            if (s.length) parts.push("🏯 " + s.filter(q => q.is_completed).length + "/" + s.length);
            return parts.length ? parts.join(" · ") : safeT("hub_pergaminho_hoje_vazio");
          })();

      // ── TEMPORADA — payload /battle_pass (mesma leitura do BattlePassTab).
      const bpd = bp.data;
      const bpm = (bpd && bpd.missions) || [];
      const bpClaimable = bpm.filter(m => m.is_completed && !m.claimed);
      const bpJade = bpClaimable.reduce((sum, m) => sum + (m.reward_jade || 0), 0);
      // ok:false / payload sem season chega como data (useApi só rejeita erro
      // de rede) → "—" em vez de "Temporada undefined"; o tap fica (Lei nº 1).
      const bpLine = (bp.loading && !bp.data) ? "…"
        : (!bpd || bpd.season == null) ? "—"
        : safeT("bp_season_label", { n: bpd.season }) + " · " + safeT("bp_tier_label", { n: bpd.current_tier });

      // ── NOTÍCIAS — payload /announcements (mesma leitura do AnnouncementsTab).
      const items = (news.data && news.data.items) || null;
      const latest = items && items.length > 0 ? items[0] : null;
      const newsLine = (news.loading && !news.data) ? "…"
        : !items ? "—"
        : !latest ? safeT("no_news")
        : ((latest.icon ? latest.icon + " " : "") + (latest.rendered || ""));

      const sections = [
        { key:"hoje",      emoji:"☀️", title_key:"hub_pergaminho_hoje",      line:questLine,
          extra:null, extraTone:null, go:() => setTab("quests") },
        // Título = tab_battle_pass (review R4: "TEMPORADA/Temporada N" duplicava
        // a palavra em linhas adjacentes ×3 idiomas; o nome da feature é mais
        // claro). Extra gated is_premium (review R4: prometer "💎 disponível" a
        // free player que o engine recusa 100% dos claims = promessa falsa, Lei §4).
        { key:"temporada", emoji:"🎫", title_key:"tab_battle_pass", line:bpLine,
          extra: (bpd && bpd.is_premium && bpClaimable.length > 0)
            ? "✦ " + safeT("bp_claimable_summary", { n: bpClaimable.length, jade: bpJade }) : null,
          extraTone:"var(--jade)", go:() => setTab("battle_pass") },
        { key:"noticias",  emoji:"📜", title_key:"tab_announcements",        line:newsLine,
          extra: latest ? timeAgo(latest.created_at_ms) : null,
          extraTone:"var(--muted)", go:() => setTab("announcements") },
      ];

      // Selo de cera sobre traço-pincel — a costura entre as seções do rolo.
      const waxDivider = (i) => (
        <div style={{ position:"relative", padding:"3px 0" }}>
          <svg viewBox="0 0 480 12" preserveAspectRatio="none"
               style={{ width:"78%", height:9, margin:"0 auto", display:"block", opacity:.5 }}>
            <path d={i % 2 === 0
                       ? "M10,6 C90,2 170,10 250,6 C330,2 400,9 470,5"
                       : "M10,5 C100,9 180,2 260,6 C340,10 410,3 470,7"}
                  fill="none" stroke="rgba(201,144,58,.45)" strokeWidth="1.3" strokeLinecap="round" />
          </svg>
          <div style={{ position:"absolute", left:"50%", top:"50%", transform:"translate(-50%,-50%)",
                        width:16, height:16, borderRadius:"50%",
                        background:"radial-gradient(circle at 35% 30%, #d96459, #8c2f26 70%)",
                        border:"1px solid rgba(140,47,38,.9)",
                        boxShadow:"0 1px 4px rgba(0,0,0,.6), inset 0 0 4px rgba(0,0,0,.45)" }} />
        </div>
      );

      const roller = (
        <div style={{ height:10, borderRadius:99, margin:"0 2px",
                      background:"linear-gradient(90deg,#6b4e1e,var(--gold),var(--gold2),var(--gold),#6b4e1e)",
                      boxShadow:"0 2px 8px rgba(0,0,0,.55), inset 0 1px 0 rgba(var(--gold3-rgb),.4)" }} />
      );

      // 卷 A FIBRA. O papel era uma chapa de gradiente — a única superfície do
      // jogo cuja metáfora É papel, e a que menos parecia material. As camadas
      // novas são todas em TOKENS (`--gold-rgb`, `--gold3-rgb`, `--seal-rgb`)
      // para não desfazer a varredura da WEB-D, e vão POR CIMA do corpo antigo,
      // que fica intacto: a cor base do papel não muda, ganha grão e luz.
      //  · a luz do candeeiro cai onde está a escrita e morre em baixo — é o
      //    que faz o papel em branco ler-se como papel na sombra, e não como
      //    espaço morto;
      //  · seis manchas de tempo, todas fora do eixo e de tamanhos diferentes.
      //
      // 🔴 A 1ª TENTATIVA ESTAVA ERRADA, e só se viu a OLHAR. Ela tinha dois
      // `repeating-linear-gradient` cruzados (90° e 0°) a fazer de fibra. Dois
      // repetidores cruzados não dão fibra: dão **uma grelha** — e o que
      // apareceu no ecrã a 390px foi papel milimétrico, uma rede regular que é
      // literalmente a régua #1 a falhar (*"isto podia ser o dashboard de
      // qualquer SaaS?"*). Nenhum teste apanharia: a propriedade estava lá, o
      // valor era o que eu tinha escrito, e o ecrã é que estava errado.
      //
      // ⚠️ A regra que fica: **papel envelhecido é TONAL, não linear.** O que
      // faz uma superfície ler-se como material é a mancha irregular e a luz a
      // cair, nunca uma trama com período. Sem um único repetidor.
      const papel = {
        position:"relative", margin:"0 10px", padding:"4px 0",
        background:
          "radial-gradient(130% 46% at 50% -4%, rgba(var(--gold-rgb),.11), transparent 74%),"
          + "radial-gradient(52% 26% at 14% 26%, rgba(var(--gold-rgb),.05), transparent 76%),"
          + "radial-gradient(44% 19% at 88% 48%, rgba(var(--seal-rgb),.032), transparent 78%),"
          + "radial-gradient(60% 22% at 33% 63%, rgba(var(--gold3-rgb),.028), transparent 78%),"
          + "radial-gradient(38% 15% at 72% 81%, rgba(var(--gold-rgb),.034), transparent 76%),"
          + "radial-gradient(70% 26% at 20% 96%, rgba(0,0,0,.30), transparent 72%),"
          + "linear-gradient(180deg, rgba(26,22,14,.94), rgba(14,12,9,.97))",
        borderLeft:"1px solid rgba(var(--gold-rgb),.22)",
        borderRight:"1px solid rgba(var(--gold-rgb),.22)",
        boxShadow:"inset 0 0 34px rgba(0,0,0,.5)",
        // ⚠️ O valor novo vive DENTRO do ternário (lição de 09/09: a identidade
        // quebra-se pela ORDEM, não só pelo valor). Sem medida, `flex` nem é
        // declarado e o rolo tem exactamente a altura de hoje.
        flex: fill ? 1 : undefined,
      };
      return (
        // R5: entrada suave ao trocar de hub (o swap era seco).
        <div ref={rolRef} style={{
               paddingTop:6, animation:"fade-up .25s ease",
               minHeight: fill ? (fill - 6) : undefined,
               display: fill ? "flex" : undefined,
               flexDirection: fill ? "column" : undefined,
             }}>
          {roller}
          {/* o papel — desenrola entre os dois bastões e vai até ao fim */}
          <div style={papel}>
            {sections.map((s, i) => (
              <React.Fragment key={s.key}>
                {i > 0 && waxDivider(i)}
                <button onClick={() => { haptic("select"); s.go(); }}
                        style={{
                          width:"100%", background:"none", border:"none", cursor:"pointer",
                          color:"var(--text)", fontFamily:"inherit", textAlign:"left",
                          padding:"14px 16px", display:"flex", alignItems:"center", gap:11,
                        }}>
                  <span style={{ fontSize:22, lineHeight:1, flexShrink:0 }}>{s.emoji}</span>
                  <span style={{ flex:1, minWidth:0 }}>
                    <span style={{ display:"block", fontFamily:"'Cinzel',serif", fontSize:12.5,
                                   fontWeight:700, letterSpacing:.9, textTransform:"uppercase",
                                   color:"var(--gold3)" }}>
                      {safeT(s.title_key)}
                    </span>
                    <span style={{ display:"block", fontSize:11.5, color:"var(--muted)", marginTop:3,
                                   whiteSpace:"nowrap", overflow:"hidden", textOverflow:"ellipsis" }}>
                      {s.line}
                    </span>
                    {s.extra && (
                      <span style={{ display:"block", fontSize:10.5, color:s.extraTone, marginTop:3,
                                     whiteSpace:"nowrap", overflow:"hidden", textOverflow:"ellipsis" }}>
                        {s.extra}
                      </span>
                    )}
                  </span>
                  <span style={{ fontSize:16, color:"var(--muted)", flexShrink:0 }}>›</span>
                </button>
              </React.Fragment>
            ))}
          </div>
          {roller}
        </div>
      );
    }


